INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-08393','泾溪东亭寄郑少府谔','李白','quantangshi','','卷9','我游东亭不见君，沙上行将白鹭羣。
白鹭行时散飞去，又如雪点青山云。
欲往泾溪不辞远，龙门蹙波虎眼转。
杜鹃花开春已阑，归向陵阳钓鱼晚。','',''),('quantangshi-08394','宣州九日闻崔四侍御与宇文太守游敬亭余时登响山不同此赏醉后寄崔侍御二首 一','李白','quantangshi','','卷9','九日茱萸熟，插鬓伤早白。
登高望山海，满目悲古昔。
远访投沙人，因为逃名客。
故交竟谁在，独有崔亭伯。
重阳不相知，载酒任所适。
手持一枝菊，调笑二千石。
日暮岸帻归，传呼隘阡陌。
彤襜双白鹿，宾从何辉赫。
夫子在其间，遂成云霄隔。
良辰与美景，两地方虚掷。
晚从南峰归，萝月下水壁。
却登郡楼望，松色寒转碧。
咫尺不可亲，弃我如遗舃。','',''),('quantangshi-08395','宣州九日闻崔四侍御与宇文太守游敬亭余时登响山不同此赏醉后寄崔侍御二首 二','李白','quantangshi','','卷9','九卿天上落，五马道傍来。
列戟朱门晓，褰帏碧嶂开。
登高望远海，召客得英才。
紫绶懽情洽，黄花逸兴催。
山从图上见，溪即镜中回。
遥羡重阳作，应过戏马台。','',''),('quantangshi-08396','寄崔侍御','李白','quantangshi','','卷9','宛溪霜夜听猿愁，去国长为不系舟。
独怜一雁飞南海，却羡双溪解北流。
高人屡解陈蕃榻，过客难登谢朓楼。
此处别离同落叶，朝朝分散敬亭秋。','',''),('quantangshi-08397','泾溪南蓝山下有落星潭可以卜筑余泊舟石上寄何判官昌浩','李白','quantangshi','','卷9','蓝岑竦天壁，突兀如鲸额。
奔蹙横澄潭，势吞落星石。
沙带秋月明，水摇寒山碧。
佳镜宜缓棹，清辉能留客。
恨君阻欢游，使我自惊惕。
所期俱卜筑，结茅炼金液。','',''),('quantangshi-08398','早过漆林渡寄万巨','李白','quantangshi','','卷9','西经大蓝山，南来漆林渡。
水色倒空青，林烟横积素。
漏流昔吞翕，沓浪竞奔注。
潭落天上星，龙开水中雾。
峣岩注公栅，突兀陈焦墓。
岭峭纷上干，川明屡回顾。
因思万夫子，解渴同琼树。
何日覩清光，相欢咏佳句。','',''),('quantangshi-08399','游敬亭寄崔侍御','李白','quantangshi','','卷9','我家敬亭下，輙继谢公作。
相去数百年，风期宛如昨。
登高素秋月，下望青山郭。
俯视鸳鸯羣，饮啄自鸣跃。
夫子虽蹭蹬，瑶台雪中鹤。
独立窥浮云，其心在寥廓。
时来顾我笑，一饭葵与藿。
世路如秋风，相逢尽萧索。
腰间玉具劒，意许无遗诺。
壮士不可轻，相期在云阁。','',''),('quantangshi-08400','三山望金陵寄殷淑','李白','quantangshi','','卷9','三山怀谢朓，水澹望长安。
芜没河阳县，秋江正北看。
卢龙霜气冷，鳷鹊月光寒。
耿耿忆琼树，天涯寄一懽。','',''),('quantangshi-08401','自金陵溯流过白璧山翫月达天门寄句容王主簿','李白','quantangshi','','卷9','沧江溯流归，白璧见秋月。
秋月照白璧，皓如山阴雪。
幽人停宵征，贾客忘早发。
进帆天门山，回首牛渚没。
川长信风来，日出宿雾歇。
故人在咫尺，新赏成胡越。
寄君青兰花，惠好庶不绝。','',''),('quantangshi-08402','寄上吴王三首 一','李白','quantangshi','','卷9','淮王爱八公，携手绿云中。
小子忝枝叶，亦攀丹桂丛。
谬以词赋重，而将枚马同。
何日背淮水，东之观土风。','',''),('quantangshi-08403','寄上吴王三首 二','李白','quantangshi','','卷9','坐啸庐江静，闲闻进玉觞。
去时无一物，东壁挂胡牀。','',''),('quantangshi-08404','寄上吴王三首 三','李白','quantangshi','','卷9','英明庐江守，声誉广平籍。
洒扫黄金台，招邀青云客。
客曾与天通，出入清禁中。
襄王怜宋玉，愿入兰台宫。','',''),('quantangshi-08405','秋日鲁郡尧祠亭上宴别杜补阙范侍御','李白','quantangshi','','卷9','我觉秋兴逸，谁云秋兴悲。
山将落日去，水与晴空宜。
鲁酒白玉壶，送行驻金羁。
歇鞍憩古木，解带挂横枝。
歌鼓川上亭，曲度神飙吹。
云归碧海夕，雁没青天时。
相失各万里，茫然空尔思。','',''),('quantangshi-08406','别鲁颂','李白','quantangshi','','卷9','谁道泰山高，下却鲁连节。
谁云秦军众，摧却鲁连舌。
独立天地间，清风洒兰雪。
夫子还倜傥，攻文继前烈。
错落石上松，无为秋霜折。
赠言镂宝刀，千岁庶不灭。','',''),('quantangshi-08407','别中都明府兄','李白','quantangshi','','卷9','吾兄诗酒继陶君，试宰中都天下闻。
东楼喜奉连枝会，南陌愁为落叶分。
城隅渌水明秋日，海上青山隔暮云。
取醉不辞留夜月，雁行中断惜离羣。','',''),('quantangshi-08408','梦游天姥吟留别','李白','quantangshi','','卷9','海客谈瀛洲，烟涛微茫信难求。
越人语天姥，云霓明灭或可覩。
天姥连天向天横，势拔五岳掩赤城。
天台四万八千丈，对此欲倒东南倾。
我欲因之梦吴越，一夜飞度镜湖月。
湖月照我影，送我至剡溪。
谢公宿处今尚在，渌水荡漾清猨啼。
脚着谢公屐，身登青云梯。
半壁见海日，空中闻天鸡。
千岩万转路不定，迷花倚石忽已暝。
熊咆龙吟殷岩泉，栗深林兮惊层巅。
云青青兮欲雨，水澹澹兮生烟。
列缺霹雳，丘峦崩摧。
洞天石扇，訇然中开。
青冥浩荡不见底，日月照耀金银台。
霓为衣兮风为马，云之君兮纷纷而来下。
虎鼓瑟兮鸾回车，仙之人兮列如麻。
忽魂悸以魄动，怳惊起而长嗟。
惟觉时之枕席，失向来之烟霞。
世间行乐亦如此，古来万事东流水。
别君去时何时还，且放白鹿青崖间，须行即骑访名山。
安能摧眉折腰事权贵？
使我不得开心颜。','',''),('quantangshi-08409','留别曹南羣官之江南','李白','quantangshi','','卷9','我昔钓白龙，放龙溪水傍。
道成本欲去，挥手凌苍苍。
时来不关人，谈笑游轩皇。
献纳少成事，归休辞建章。
十年罢西笑，览镜如秋霜。
闭劒琉璃匣，炼丹紫翠房。
身佩豁落图，腰垂虎鞶囊。
仙人驾彩凤，志在穷遐荒。
恋子四五人，裴回未翱翔。
东流送白日，骤歌兰蕙芳。
仙宫两无从，人间久摧藏。
范蠡说句践，屈平去怀王。
飘飘紫霞心，流浪忆江乡。
愁为万里别，复此一衔觞。
淮水帝王州，金陵绕丹阳。
楼台照海色，衣马摇川光。
及此北望君，相思泪成行。
朝云落梦渚，瑶草空高堂。
帝子隔洞庭，青枫满潇湘。
怀君路绵邈，览古情凄凉。
登岳眺百川，杳然万恨长。
知恋峨眉去，弄景偶骑羊。','',''),('quantangshi-08410','留别于十一兄逖裴十三游塞垣','李白','quantangshi','','卷9','太公渭川水，李斯上蔡门。
钓周猎秦安黎元，小鱼㕙兔何足言。
天张云卷有时节，吾徒莫叹羝触藩。
于公白首大梁野，使人怅望何可论。
既知朱亥为壮士，且愿束心秋毫里。
秦赵虎争血中原，当去抱关救公子。
裴生览千古，龙鸾炳文章。
悲吟雨雪动林木，放书辍劒思高堂。
劝尔一杯酒，拂尔裘上霜。
尔为我楚舞，吾为尔楚歌。
且探虎穴向沙漠，鸣鞭走马凌黄河。
耻作易水别，临岐泪滂沱。','',''),('quantangshi-08411','留别王司马嵩','李白','quantangshi','','卷9','鲁连卖谈笑，岂是顾千金。
陶朱虽相越，本有五湖心。
余亦南阳子，时为梁甫吟。
苍山容偃蹇，白日惜颓侵。
愿一佐明主，功成还旧林。
西来何所为，孤劒托知音。
鸟爱碧山远，鱼游沧海深。
呼鹰过上蔡，卖畚向嵩岑。
他日闲相访，丘中有素琴。','',''),('quantangshi-08412','夜别张五','李白','quantangshi','','卷9','吾多张公子，别酌酣高堂。
听歌舞银烛，把酒轻罗裳。
横笛弄秋月，琵琶弹陌桑。
龙泉解锦带，为尔倾千觞。','',''),('quantangshi-08413','魏郡别苏明府因北游','李白','quantangshi','','卷9','魏都接燕赵，美女夸芙蓉。
淇水流碧玉，舟车日奔冲。
青楼夹两岸，万室喧歌钟。
天下称豪贵，游此每相逢。
洛阳苏季子，劒戟森词锋。
六印虽未佩，轩车若飞龙。
黄金数百镒，白璧有几双。
散尽空掉臂，高歌赋还邛。
落魄乃如此，何人不相从。
远别隔两河，云山杳千重。
何时更杯酒，再得论心胸。','',''),('quantangshi-08414','留别西河刘少府','李白','quantangshi','','卷9','秋发已种种，所为竟无成。
闲倾鲁壶酒，笑对刘公荣。
谓我是方朔，人间落岁星。
白衣千万乘，何事去天庭。
君亦不得意，高歌羡鸿冥。
世人若醯鸡，安可识梅生。
虽为刀笔吏，缅怀在赤城。
余亦如流萍，随波乐休明。
自有两少妾，双骑骏马行。
东山春酒绿，归隐谢浮名。','',''),('quantangshi-08415','颍阳别元丹丘之淮阳','李白','quantangshi','','卷9','吾将元夫子，异姓为天伦。
本无轩裳契，素以烟霞亲。
尝恨迫世网，铭意俱未伸。
松柏虽寒苦，羞逐桃李春。
悠悠市朝间，玉颜日缁磷。
所失重山岳，所得轻埃尘。
精魄渐芜秽，衰老相凭因。
我有锦囊诀，可以持君身。
当餐黄金药，去为紫阳宾。
万事难并立，百年犹崇晨。
别尔东南去，悠悠多悲辛。
前志庶不易，远途期所遵。
已矣归去来，白云飞天津。','',''),('quantangshi-08416','留别广陵诸公','李白','quantangshi','','卷9','忆昔作少年，结交赵与燕。
金羁络骏马，锦带横龙泉。
寸心无疑事，所向非徒然。
晚节觉此疎，猎精草太玄。
空名束壮士，薄俗弃高贤。
中回圣明顾，挥翰凌云烟。
骑虎不敢下，攀龙忽堕天。
还家守清真，孤洁励秋蝉。
炼丹费火石，采药穷山川。
卧海不关人，租税辽东田。
乘兴忽复起，棹歌溪中船。
临醉谢葛强，山公欲倒鞭。
狂歌自此别，垂钓沧浪前。','',''),('quantangshi-08417','广陵赠别','李白','quantangshi','','卷9','玉瓶沽美酒，数里送君还。
系马垂杨下，衔杯大道间。
天边看渌水，海上见青山。
兴罢各分袂，何须醉别颜。','',''),('quantangshi-08418','感时留别从兄徐王延年从弟延陵','李白','quantangshi','','卷9','天籁何参差，噫然大块吹。
玄元包橐龠，紫气何逶迤。
七叶运皇化，千龄光本支。
仙风生指树，大雅歌螽斯。
诸王若鸾虬，肃穆列藩维。
哲兄锡茅土，圣代罗荣滋。
九卿领徐方，七步继陈思。
伊昔全盛日，雄豪动京师。
冠劒朝凤阙，楼船侍龙池。
鼓钟出朱邸，金翠照丹墀。
君王一顾盼，选色献蛾眉。
列戟十八年，未曾輙迁移。
大臣小喑鸣，谪窜天南垂。
长沙不足舞，贝锦且成诗。
佐郡浙江西，病闲绝驱驰。
阶轩日苔藓，鸟雀噪檐帷。
时乘平肩舆，出入畏人知。
北宅聊偃憩，欢愉恤惸嫠。
羞言梁苑地，烜赫耀旌旗。
兄弟八九人，吴秦各分离。
太贤达机兆，岂独虑安危。
小子谢麟阁，雁行忝肩随。
令弟字延陵，凤毛出天姿。
清英神仙骨，芬馥茝兰蕤。
梦得春草句，将非惠连谁。
深心紫河车，与我特相宜。
金膏犹罔象，玉液尚磷缁。
伏枕寄宾馆，宛同清漳湄。
药物多见馈，珍羞亦兼之。
谁道溟渤深，犹言浅恩慈。
鸣蝉游子意，促织念归期。
骄阳何太赫，海水烁龙龟。
百川尽凋枯，舟檝阁中逵。
策马摇凉月，通宵出郊圻。
泣别目眷眷，伤心步迟迟。
愿言保明德，王室伫清夷。
掺袂何所道，援毫投此辞。','',''),('quantangshi-08419','别储邕之剡中','李白','quantangshi','','卷9','借问剡中道，东南指越乡。
舟从广陵去，水入会稽长。
竹色溪下绿，荷花镜里香。
辞君向天姥，拂石卧秋霜。','',''),('quantangshi-08420','留别金陵诸公','李白','quantangshi','','卷9','海水昔飞动，三龙纷战争。
钟山危波澜，倾侧骇奔鲸。
黄旗一扫荡，割壤开吴京。
六代更霸王，遗迹见都城。
至今秦淮间，礼乐秀羣英。
地扇邹鲁学，诗腾颜谢名。
五月金陵西，祖余白下亭。
欲寻庐峰顶，先遶汉水行。
香炉紫烟灭，瀑布落太清。
若攀星辰去，挥手缅含情。','',''),('quantangshi-08421','口号','李白','quantangshi','','卷9','食出野田美，酒临远水倾。
东流若未尽，应见别离情。','',''),('quantangshi-08422','金陵酒肆留别','李白','quantangshi','','卷9','风吹柳花满店香，吴姬压酒唤客尝。
金陵子弟来相送，欲行不行各尽觞。
请君试问东流水，别意与之谁短长。','',''),('quantangshi-08423','金陵白下亭留别','李白','quantangshi','','卷9','驿亭三杨树，正当白下门。
吴烟暝长条，汉水啮古根。
向来送行处，回首阻笑言。
别后若见之，为余一攀翻。','',''),('quantangshi-08424','别东林寺僧','李白','quantangshi','','卷9','东林送客处，月出白猨啼。
笑别庐山远，何烦过虎溪。','',''),('quantangshi-08425','窜夜郎于乌江留别宗十六璟','李白','quantangshi','','卷9','君家全盛日，台鼎何陆离。
斩鳌翼娲皇，炼石补天维。
一回日月顾，三入凤皇池。
失势青门傍，种瓜复几时。
犹会众宾客，三千光路岐。
皇恩雪愤懑，松柏含荣滋。
我非东牀人，令姊忝齐眉。
浪迹未出世，空名动京师。
适遭云罗解，翻谪夜郎悲。
拙妻莫邪劒，及此二龙随。
慙君湍波苦，千里远从之。
白帝晓猨断，黄牛过客迟。
遥瞻明月峡，西去益相思。','',''),('quantangshi-08426','留别龚处士','李白','quantangshi','','卷9','龚子栖闲地，都无人世喧。
柳深陶令宅，竹暗辟疆园。
我去黄牛峡，遥愁白帝猨。
赠君卷葹草，心断竟何言。','',''),('quantangshi-08427','赠别郑判官','李白','quantangshi','','卷9','窜逐勿复哀，惭君问寒灰。
浮云本无意，吹落章华台。
远别泪空尽，长愁心已摧。
二年吟泽畔，顦顇几时回。','',''),('quantangshi-08428','黄鹤楼送孟浩然之广陵','李白','quantangshi','','卷9','故人西辞黄鹤楼，烟花三月下扬州。
孤帆远影碧山尽，唯见长江天际流。','',''),('quantangshi-08429','将游衡岳过汉阳双松亭留别族弟浮屠谈皓','李白','quantangshi','','卷9','秦欺赵氏璧，却入邯郸宫。
本是楚家玉，还来荆山中。
丹彩泻沧溟，精辉凌白虹。
青蝇一相点，流落此时同。
卓绝道门秀，谈玄乃支公。
延萝结幽居，剪竹绕芳丛。
凉花拂户牖，天籁鸣虚空。
忆我初来时，蒲萄开景风。
今兹大火落，秋叶黄梧桐。
水色梦沅湘，长沙去何穷。
寄书访衡峤，但与南飞鸿。','',''),('quantangshi-08430','留别贾舍人至二首 一','李白','quantangshi','','卷9','大梁白云起，飘颻来南洲。
裴回苍梧野，十见罗浮秋。
鳌拚山海倾，四溟扬洪流。
意欲托孤凤，从之摩天游。
凤苦道路难，翱翔还昆丘。
不肯衔我去，哀鸣慙不周。
远客谢主人，明珠难暗投。
拂拭倚天劒，西登岳阳楼。
长啸万里风，扫清胷中忧。
谁念刘越石，化为绕指柔。','',''),('quantangshi-08431','留别贾舍人至二首 二','李白','quantangshi','','卷9','秋风吹胡霜，凋此檐下芳。
折芳怨岁晚，离别凄以伤。
谬攀青琐贤，延我于北堂。
君为长沙客，我独之夜郎。
劝此一杯酒，岂惟道路长。
割珠两分赠，寸心贵不忘。
何必儿女仁，相看泪成行。','',''),('quantangshi-08432','渡荆门送别','李白','quantangshi','','卷9','渡远荆门外，来从楚国游。
山随平野尽，江入大荒流。
月下飞天镜，云生结海楼。
仍连故乡水，万里送行舟。','',''),('quantangshi-08433','闻李太尉大举秦兵百万出征东南懦夫请缨冀申一割之用半道病还留别金陵崔侍御十九韵','李白','quantangshi','','卷9','秦出天下兵，蹴踏燕赵倾。
黄河饮马竭，赤羽连天明。
太尉杖旄钺，云旗绕彭城。
三军受号令，千里肃雷霆。
函谷绝飞鸟，武关拥连营。
意在斩巨鳌，何论鲙长鲸。
恨无左军略，多愧鲁连生。
拂劒照严霜，雕戈鬘胡缨。
愿雪会稽耻，将期报恩荣。
半道谢病还，无因东南征。
亚夫未见顾，剧孟阻先行。
天夺壮士心，长吁别吴京。
金陵遇太守，倒屣相逢迎。
羣公咸祖饯，四座罗朝英。
初发临沧观，醉栖征虏亭。
旧国见秋月，长江流寒声。
帝车信回转，河汉复纵横。
孤凤向西海，飞鸿辞北溟。
因之出寥廓，挥手谢公卿。','',''),('quantangshi-08434','别韦少府','李白','quantangshi','','卷9','西出苍龙门，南登白鹿原。
欲寻商山皓，犹恋汉皇恩。
水国远行迈，仙经深讨论。
洗心向溪月，清耳敬亭猨。
筑室在人境，闭门无世喧。
多君枉高驾，赠我以微言。
交乃意气合，道因风雅存。
别离有相思，瑶瑟与金樽。','',''),('quantangshi-08435','南陵别儿童入京','李白','quantangshi','','卷9','白酒新熟山中归，黄鸡啄黍秋正肥。
呼童烹鸡酌白酒，儿女嬉笑牵人衣。
高歌取醉欲自慰，起舞落日争光辉。
游说万乘苦不早，着鞭跨马涉远道。
会稽愚妇轻买臣，余亦辞家西入秦。
仰天大笑出门去，我辈岂是蓬蒿人。','',''),('quantangshi-08436','别山僧','李白','quantangshi','','卷9','何处名僧到水西，乘舟弄月宿泾溪。
平明别我上山去，手携金策踏云梯。
腾身转觉三天近，举足回看万岭低。
谑浪肯居支遁下，风流还与远公齐。
此度别离何日见，相思一夜暝猨啼。','',''),('quantangshi-08437','赠别王山人归布山','李白','quantangshi','','卷9','王子析道论，微言破秋毫。
还归布山隐，兴入天云高。
尔去安可迟，瑶草恐衰歇。
我心亦怀归，屡梦松上月。
傲然遂独往，长啸开岩扉。
林壑久已芜，石道生蔷薇。
愿言弄笙鹤，岁晚来相依。','',''),('quantangshi-08438','江夏别宋之悌','李白','quantangshi','','卷9','楚水清若空，遥将碧海通。
人分千里外，兴在一杯中。
谷鸟吟晴日，江猨啸晚风。
平生不下泪，于此泣无穷。','',''),('quantangshi-08439','南阳送客','李白','quantangshi','','卷9','斗酒勿为薄，寸心贵不忘。
坐惜故人去，偏令游子伤。
离颜怨芳草，春思结垂杨。
挥手再三别，临岐空断肠。','',''),('quantangshi-08440','送张舍人之江东','李白','quantangshi','','卷9','张翰江东去，正值秋风时。
天清一雁远，海阔孤帆迟。
白日行欲暮，沧波杳难期。
吴洲如见月，千里幸相思。','',''),('quantangshi-08441','送王屋山人魏万还王屋','李白','quantangshi','','卷9','仙人东方生，浩荡弄云海。
沛然乘天游，独往失所在。
魏侯继大名，本家聊摄城。
卷舒入元化，迹与古贤并。
十三弄文史，挥笔如振绮。
辩折田巴生，心齐鲁连子。
西涉清洛源，颇惊人世喧。
采秀卧王屋，因窥洞天门。
朅来游嵩峰，羽客何双双。
朝携月光子，暮宿玉女牕。
鬼谷上窈窕，龙潭下奔潨。
东浮汴河水，访我三千里。
逸兴满吴云，飘颻淛江汜。
挥手杭越间，樟亭望潮还。
涛卷海门石，云横天际山。
白马走素车，雷奔骇心颜。
遥闻会稽美，且度耶溪水。
万壑与千岩，峥嵘镜湖里。
秀色不可名，清辉满江城。
人游月边去，舟在空中行。
此中久延伫，入剡寻王许。
笑读曹娥碑，沈吟黄绢语。
天台连四明，日入向国清。
五峰转月色，百里行松声。
灵溪咨沿越，华顶殊超忽。
石梁横青天，侧足履半月。
忽然思永嘉，不惮海路赊。
挂席历海峤，回瞻赤城霞。
赤城渐微没，孤屿前峣兀。
水续万古流，亭空千霜月。
缙云川谷难，石门最可观。
瀑布挂北斗，莫穷此水端。
喷壁洒素雪，空蒙生昼寒。
却思恶溪去，宁惧恶溪恶。
咆哮七十滩，水石相喷薄。
路创李北海，岩开谢康乐。
松风和猨声，搜索连洞壑。
径出梅花桥，双溪纳归潮。
落帆金华岸，赤松若可招。
沈约八咏楼，城西孤岧峣。
岧峣四荒外，旷望羣川会。
云卷天地开，波连浙西大。
乱流新安口，北指严光濑。
钓台碧云中，邈与苍岭对。
稍稍来吴都，裴回上姑苏。
烟绵横九疑，漭荡见五湖。
目极心更远，悲歌但长吁。
回桡楚江滨，挥策扬子津。
身着日本裘，昂藏出风尘。
五月造我语，知非佁儗人。
相逢乐无限，水石日在眼。
徒干五诸侯，不致百金产。
吾友扬子云，弦歌播清芬。
虽为江宁宰，好与山公羣。
乘兴但一行，且知我爱君。
君来几何时，仙台应有期。
东窗绿玉树，定长三五枝。
至今天坛人，当笑尔归迟。
我苦惜远别，茫然使心悲。
黄河若不断，白首长相思。','',''),('quantangshi-08442','送当涂赵少府赴长芦','李白','quantangshi','','卷9','我来扬都市，送客回轻舠。
因夸楚太子，便覩广陵涛。
仙尉赵家玉，英风凌四豪。
维舟至长芦，目送烟云高。
摇扇对酒楼，持袂把蟹螯。
前途傥相思，登岳一长谣。','',''),('quantangshi-08443','送友人寻越中山水','李白','quantangshi','','卷9','闻道稽山去，偏宜谢客才。
千岩泉洒落，万壑树萦回。
东海横秦望，西陵遶越台。
湖清霜镜晓，涛白雪山来。
八月枚乘笔，三吴张翰杯。
此中多逸兴，早晚向天台。','',''),('quantangshi-08444','送族弟凝之滁求婚崔氏','李白','quantangshi','','卷9','与尔情不浅，忘筌已得鱼。
玉台挂宝镜，持此意何如。
坦腹东牀下，由来志气疎。
遥知向前路，掷果定盈车。','',''),('quantangshi-08445','送友人游梅湖','李白','quantangshi','','卷9','送君游梅湖，应见梅花发。
有使寄我来，无令红芳歇。
暂行新林浦，定醉金陵月。
莫惜一雁书，音尘坐胡越。','',''),('quantangshi-08446','送崔十二游天竺寺','李白','quantangshi','','卷9','还闻天竺寺，梦想怀东越。
每年海树霜，桂子落秋月。
送君游此地，已属流芳歇。
待我来岁行，相随浮溟渤。','',''),('quantangshi-08447','送杨山人归天台','李白','quantangshi','','卷9','客有思天台，东行路超忽。
涛落浙江秋，沙明浦阳月。
今游方厌楚，昨梦先归越。
且尽秉烛欢，无辞凌晨发。
我家小阮贤，剖竹赤城边。
诗人多见重，官烛未曾然。
兴引登山屐，情催泛海船。
石桥如可度，携手弄云烟。','',''),('quantangshi-08448','送温处士归黄山白鹅峰旧居','李白','quantangshi','','卷9','黄山四千仞，三十二莲峰。
丹崖夹石柱，菡萏金芙蓉。
伊昔升绝顶，下窥天目松。
仙人炼玉处，羽化留余踪。
亦闻温伯雪，独往今相逢。
采秀辞五岳，攀岩历万重。
归休白鹅岭，渴饮丹砂井。
凤吹我时来，云车尔当整。
去去陵阳东，行行芳桂丛。
回溪十六度，碧嶂尽晴空。
他日还相访，乘桥蹑彩虹。','',''),('quantangshi-08449','送方士赵叟之东平','李白','quantangshi','','卷9','长桑晓洞视，五藏无全牛。
赵叟得祕诀，还从方士游。
西过获麟台，为我吊孔丘。
念别复怀古，潸然空泪流。','',''),('quantangshi-08450','送韩准裴政孔巢父还山','李白','quantangshi','','卷9','猎客张兔罝，不能挂龙虎。
所以青云人，高歌在岩户。
韩生信英彦，裴子含清真。
孔侯复秀出，俱与云霞亲。
峻节凌远松，同衾卧盘石。
斧冰嗽寒泉，三子同二屐。
时时或乘兴，往往云无心。
出山揖牧伯，长啸轻衣簪。
昨宵梦里还，云弄竹溪月。
今晨鲁东门，帐饮与君别。
雪崖滑去马，萝径迷归人。
相思若烟草，历乱无冬春。','',''),('quantangshi-08451','送杨少府赴选','李白','quantangshi','','卷9','大国置衡镜，准平天地心。
羣贤无邪人，朗鉴穷情深。
吾君咏南风，衮冕弹鸣琴。
时泰多美士，京国会缨簪。
山苗落涧底，幽松出高岑。
夫子有盛才，主司得球琳。
流水非郑曲，前行遇知音。
衣工剪绮绣，一悞伤千金。
何惜刀尺余，不裁寒女衾。
我非弹冠者，感别但开襟。
空谷无白驹，贤人岂悲吟。
大道安弃物，时来或招寻。
尔见山吏部，当应无陆沈。','',''),('quantangshi-08452','对雪奉饯任城六父秩满归京','李白','quantangshi','','卷9','龙虎谢鞭策，鵷鸾不司晨。
君看海上鹤，何似笼中鹑。
独用天地心，浮云乃吾身。
虽将簪组狎，若与烟霞亲。
季父有英风，白眉超常伦。
一官即梦寐，脱屐归西秦。
窦公敞华筵，墨客尽来臻。
燕歌落胡雁，郢曲回阳春。
征马百度嘶，游车动行尘。
踌躇未忍去，恋此四座人。
饯离驻高驾，惜别空殷勤。
何时竹林下，更与步兵邻。','',''),('quantangshi-08453','鲁郡尧祠送吴五之琅琊','李白','quantangshi','','卷9','尧没三千岁，青松古庙存。
送行奠桂酒，拜舞清心魂。
日色促归人，连歌倒芳樽。
马嘶俱醉起，分手更何言。','',''),('quantangshi-08454','鲁郡尧祠送窦明府薄华还西京','李白','quantangshi','','卷9','朝策犂眉騧，举鞭力不堪。
强扶愁疾向何处，角巾微服尧祠南。
长杨扫地不见日，石门喷作金沙潭。
笑夸故人指绝境，山光水色青于蓝。
庙中往往来击鼓，尧本无心尔何苦。
门前长跪双石人，有女如花日歌舞。
银鞍绣毂往复回，簸林蹶石鸣风雷。
远烟空翠时明灭，白鸥历乱长飞雪。
红泥亭子赤阑干，碧流环转青锦湍。
深沈百丈洞海底，那知不有蛟龙蟠。
君不见绿珠潭水流东海，绿珠红粉沈光彩。
绿珠楼下花满园，今日曾无一枝在。
昨夜秋声阊阖来，洞庭木落骚人哀。
遂将三五少年辈，登高远望形神开。
生前一笑轻九鼎，魏武何悲铜雀台。
我歌白云倚牕牖，尔闻其声但挥手。
长风吹月度海来，遥劝仙人一杯酒。
酒中乐酣宵向分，举觞酹尧尧可闻。
何不令臯繇拥彗横八极，直上青天挥浮云。
高阳小饮真琐琐，山公酩酊何如我。
竹林七子去道赊，兰亭雄笔安足夸。
尧祠笑杀五湖水，至今顦悴空荷花。
尔向西秦我东越，暂向瀛洲访金阙。
蓝田太白若可期，为余扫洒石上月。','',''),('quantangshi-08455','金乡送韦八之西京','李白','quantangshi','','卷9','客自长安来，还归长安去。
狂风吹我心，西挂咸阳树。
此情不可道，此别何时遇。
望望不见君，连山起烟雾。','',''),('quantangshi-08456','送薛九被谗去鲁','李白','quantangshi','','卷9','宋人不辨玉，鲁贱东家丘。
我笑薛夫子，胡为两地游。
黄金消众口，白璧竟难投。
梧桐生蒺藜，绿竹乏佳实。
凤凰宿谁家，遂与羣鸡匹。
田家养老马，穷士归其门。
蛾眉笑躄者，宾客去平原。
却斩美人首，三千还骏奔。
毛公一挺劒，楚赵两相存。
孟尝习狡兔，三窟赖冯谖。
信陵夺兵符，为用侯生言。
春申一何愚，刎首为李园。
贤哉四公子，抚掌黄泉里。
借问笑何人，笑人不好士。
尔去且勿喧，桃李竟何言。
沙丘无漂母，谁肯饭王孙。','',''),('quantangshi-08457','单父东楼秋夜送族弟沈之秦','李白','quantangshi','','卷9','尔从咸阳来，问我何劳苦。
沐猴而冠不足言，身骑土牛滞东鲁。
沈弟欲行凝弟留，孤飞一雁秦云秋。
坐来黄叶落四五，北斗已挂西城楼。
丝桐感人弦亦绝，满堂送君皆惜别。
卷帘见月清兴来，疑是山阴夜中雪。
明日斗酒别，惆怅清路尘。
遥望长安日，不见长安人。
长安宫阙九天上，此地曾经为近臣。
一朝复一朝，发白心不改。
屈原憔悴滞江潭，亭伯流离放辽海。
折翮翻飞随转蓬，闻弦坠虚下霜空。
圣朝久弃青云士，他日谁怜张长公。','',''),('quantangshi-08458','送族弟凝至晏堌','李白','quantangshi','','卷9','雪满原野白，戎装出盘游。
挥鞭布猎骑，四顾登高丘。
兔起马足间，苍鹰下平畴。
喧呼相驰逐，取乐销人忧。
舍此戒禽荒，微声列齐讴。
鸣鸡发晏堌，别雁惊涞沟。
西行有东音，寄与长河流。','',''),('quantangshi-08459','鲁城北郭曲腰桑下送张子还嵩阳','李白','quantangshi','','卷9','送别枯桑下，凋叶落半空。
我行懵道远，尔独知天风。
谁念张仲蔚，还依蒿与蓬。
何时一杯酒，更与李膺同。','',''),('quantangshi-08460','送鲁郡刘长史迁弘农长史','李白','quantangshi','','卷9','鲁国一杯水，难容横海鳞。
仲尼且不敬，况乃寻常人。
白玉换斗粟，黄金买尺薪。
闭门木叶下，始觉秋非春。
闻君向西迁，地即鼎湖邻。
宝镜匣苍藓，丹经埋素尘。
轩后上天时，攀龙遗小臣。
及此留惠爱，庶几风化淳。
鲁缟如白烟，五缣不成束。
临行赠贫交，一尺重山岳。
相国齐晏子，赠行不及言。
托阴当树李，忘忧当树萱。
他日见张禄，绨袍怀旧恩。','',''),('quantangshi-08461','送族弟单父主簿凝摄宋城主簿至郭南月桥却回栖霞山留饮赠之','李白','quantangshi','','卷9','吾家青萍剑，操割有余闲。
往来纠二邑，此去何时还。
鞍马月桥南，光辉岐路间。
贤豪相追饯，却到栖霞山。
羣花散芳园，斗酒开离颜。
乐酣相顾起，征马无由攀。','',''),('quantangshi-08462','鲁郡东石门送杜二甫','李白','quantangshi','','卷9','醉别复几日，登临徧池台。
何时石门路，重有金樽开。
秋波落泗水，海色明徂徕。
飞蓬各自远，且尽手中杯。','',''),('quantangshi-08463','鲁郡尧祠送张十四游河北','李白','quantangshi','','卷9','猛虎伏尺草，虽藏难蔽身。
有如张公子，肮脏在风尘。
岂无横腰劒，屈彼淮阴人。
击筑向北燕，燕歌易水滨。
归来泰山上，当与尔为邻。','',''),('quantangshi-08464','杭州送裴大泽赴庐州长史','李白','quantangshi','','卷9','西江天柱远，东越海门深。
去割慈亲恋，行忧报国心。
好风吹落日，流水引长吟。
五月披裘者，应知不取金。','',''),('quantangshi-08465','灞陵行送别','李白','quantangshi','','卷9','送君灞陵亭，灞水流浩浩。
上有无花之古树，下有伤心之春草。
我向秦人问路岐，云是王粲南登之古道。
古道连绵走西京，紫阙落日浮云生。
正当今夕断肠处，黄鹂愁绝不忍听。','',''),('quantangshi-08466','送贺监归四明应制','李白','quantangshi','','卷9','久辞荣禄遂初衣，曾向长生说息机。
真诀自从茅氏得，恩波宁阻洞庭归。
瑶台含雾星辰满，仙峤浮空岛屿微。
借问欲栖珠树鹤，何年却向帝城飞。','',''),('quantangshi-08467','送窦司马贬宜春','李白','quantangshi','','卷9','天马白银鞍，亲承明主欢。
鬬鸡金宫里，射雁碧云端。
堂上罗中贵，歌钟清夜阑。
何言谪南国，拂剑坐长叹。
赵璧为谁点，隋珠枉被弹。
圣朝多雨露，莫厌此行难。','',''),('quantangshi-08468','送羽林陶将军','李白','quantangshi','','卷9','将军出使拥楼船，江上旌旗拂紫烟。
万里横戈探虎穴，三杯拔剑舞龙泉。
莫道词人无胆气，临行将赠绕朝鞭。','',''),('quantangshi-08469','送程刘二侍郎兼独孤判官赴安西幕府','李白','quantangshi','','卷9','安西幕府多材雄，喧喧惟道三数公。
绣衣貂裘明积雪，飞书走檄如飘风。
朝辞明主出紫宫，银鞍送别金城空。
天外飞霜下葱海，火旗云马生光彩。
胡塞清尘几日归，汉家草绿遥相待。','',''),('quantangshi-08470','送侄良携二妓赴会稽戏有此赠','李白','quantangshi','','卷9','携妓东山去，春光半道催。
遥看若桃李，双入镜中开。','',''),('quantangshi-08471','送贺宾客归越','李白','quantangshi','','卷9','镜湖流水漾清波，狂客归舟逸兴多。
山阴道士如相见，应写黄庭换白鹅。','',''),('quantangshi-08472','送张遥之寿阳幕府','李白','quantangshi','','卷9','寿阳信天险，天险横荆关。
苻坚百万众，遥阻八公山。
不假筑长城，大贤在其间。
战夫若熊虎，破敌有余闲。
张子勇且英，少轻卫霍孱。
投躯紫髯将，千里望风颜。
勖尔効才略，功成衣锦还。','',''),('quantangshi-08473','送裴十八图南归嵩山二首 一','李白','quantangshi','','卷9','何处可为别，长安青绮门。
胡姬招素手，延客醉金樽。
临当上马时，我独与君言。
风吹芳兰折，日没鸟雀喧。
举手指飞鸿，此情难具论。
同归无早晚，颍水有清源。','',''),('quantangshi-08474','送裴十八图南归嵩山二首 二','李白','quantangshi','','卷9','君思颍水绿，忽复归嵩岑。
归时莫洗耳，为我洗其心。
洗心得真情，洗耳徒买名。
谢公终一起，相与济苍生。','',''),('quantangshi-08475','同王昌龄送族弟襄归桂阳二首 一','李白','quantangshi','','卷9','秦地见碧草，楚谣对清樽。
把酒尔何思，鹧鸪啼南园。
余欲罗浮隐，犹怀明主恩。
踌躇紫宫恋，孤负沧洲言。
终然无心云，海上同飞翻。
相期乃不浅，幽桂有芳根。','',''),('quantangshi-08476','同王昌龄送族弟襄归桂阳二首 二','李白','quantangshi','','卷9','尔家何在潇湘川，青莎白石长沙边。
昨梦江花照江日，几枝正发东牕前。
觉来欲往心悠然，魂随越鸟飞南天。
秦云连山海相接，桂水横烟不可涉。
送君此去令人愁，风帆茫茫隔河洲。
春潭琼草绿可折，西寄长安明月楼。','',''),('quantangshi-08477','送外甥郑灌从军三首 一','李白','quantangshi','','卷9','六博争雄好彩来，金盘一掷万人开。
丈夫赌命报天子，当斩胡头衣锦回。','',''),('quantangshi-08478','送外甥郑灌从军三首 二','李白','quantangshi','','卷9','丈八蛇矛出陇西，弯弧拂箭白猨啼。
破胡必用龙韬策，积甲应将熊耳齐。','',''),('quantangshi-08479','送外甥郑灌从军三首 三','李白','quantangshi','','卷9','月蚀西方破敌时，及瓜归日未应迟。
斩胡血变黄河水，枭首当悬白鹊旗。','',''),('quantangshi-08480','送于十八应四子举落第还嵩山','李白','quantangshi','','卷9','吾祖吹橐龠，天人信森罗。
归根复太素，羣动熙元和。
炎炎四真人，摛辩若涛波。
交流无时寂，杨墨日成科。
夫子闻洛诵，夸才才固多。
为金好踊跃，久客方蹉跎。
道可束卖之，五宝溢山河。
劝君还嵩丘，开酌盼庭柯。
三花如未落，乘兴一来过。','',''),('quantangshi-08481','送别','李白','quantangshi','','卷9','寻阳五溪水，沿洄直入巫山里。
胜境由来人共传，君到南中自称美。
送君别有八月秋，飒飒芦花复益愁。
云帆望远不相见，日暮长江空自流。','',''),('quantangshi-08482','送族弟绾从军安西','李白','quantangshi','','卷9','汉家兵马乘北风，鼓行而西破犬戎。
尔随汉将出门去，剪虏若草收奇功。
君王按剑望边色，旄头已落胡天空。
匈奴系头数应尽，明年应入蒲萄宫。','',''),('quantangshi-08483','送梁公昌从信安北征','李白','quantangshi','','卷9','入幕推英选，捐书事远戎。
高谈百战术，郁作万夫雄。
起舞莲花剑，行歌明月弓。
将飞天地阵，兵出塞垣通。
祖席留丹景，征麾拂彩虹。
旋应献凯入，麟阁伫深功。','',''),('quantangshi-08484','送白利从金吾董将军西征','李白','quantangshi','','卷9','西羌延国讨，白起佐军威。
剑决浮云气，弓弯明月辉。
马行边草绿，旌卷曙霜飞。
抗手凛相顾，寒风生铁衣。','',''),('quantangshi-08485','送张秀才从军','李白','quantangshi','','卷9','六驳食猛虎，耻从驽马羣。
一朝长鸣去，矫若龙行云。
壮士怀远略，志存解世纷。
周粟犹不顾，齐圭安肯分。
抱剑辞高堂，将投崔冠军。
长策扫河洛，宁亲归汝坟。
当令千古后，麟阁着奇勋。','',''),('quantangshi-08486','送崔度还吴','李白','quantangshi','','卷9','幽燕沙雪地，万里尽黄云。
朝吹归秋雁，南飞日几羣。
中有孤凤雏，哀鸣九天闻。
我乃重此鸟，彩章五色分。
胡为杂凡禽，雏鹜轻贱君。
举手捧尔足，疾心若火焚。
拂羽泪满面，送之吴江濆。
去影忽不见，踌躇日将曛。','',''),('quantangshi-08487','送祝八之江东赋得浣纱石','李白','quantangshi','','卷9','西施越溪女，明艳光云海。
未入吴王宫殿时，浣纱古石今犹在。
桃李新开映古查，菖蒲犹短出平沙。
昔时红粉照流水，今日青苔覆落花。
君去西秦适东越，碧山青江几超忽。
若到天涯思故人，浣纱石上窥明月。','',''),('quantangshi-08488','送侯十一','李白','quantangshi','','卷9','朱亥已击晋，侯嬴尚隐身。
时无魏公子，岂贵抱关人。
余亦不火食，游梁同在陈。
空余湛卢剑，赠尔托交亲。','',''),('quantangshi-08489','鲁中送二从弟赴举之西京','李白','quantangshi','','卷9','鲁客向西笑，君门若梦中。
霜凋逐臣发，日忆明光宫。
复羡二龙去，才华冠世雄。
平衢骋高足，逸翰凌长风。
舞袖拂秋月，歌筵闻蚤鸿。
送君日千里，良会何由同。','',''),('quantangshi-08490','奉饯高尊师如贵道士传道箓毕归北海','李白','quantangshi','','卷9','道隐不可见，灵书藏洞天。
吾师四万劫，历世遰相传。
别杖留青竹，行歌蹑紫烟。
离心无远近，长在玉京悬。','',''),('quantangshi-08491','金陵送张十一再游东吴','李白','quantangshi','','卷9','张翰黄花句，风流五百年。
谁人今继作，夫子世称贤。
再动游吴棹，还浮入海船。
春光白门柳，霞色赤城天。
去国难为别，思归各未旋。
空余贾生泪，相顾共凄然。','',''),('quantangshi-08492','送纪秀才游越','李白','quantangshi','','卷9','海水不满眼，观涛难称心。
即知蓬莱石，却是巨鳌簪。
送尔游华顶，令余发舃吟。
仙人居射的，道士住山阴。
禹穴寻溪入，云门隔岭深。
绿萝秋月夜，相忆在鸣琴。','',''),('quantangshi-08493','送长沙陈太守二首 一','李白','quantangshi','','卷9','长沙陈太守，逸气凌青松。
英主赐五马，本是天池龙。
湘水回九曲，衡山望五峰。
荣君按节去，不及远相从。','',''),('quantangshi-08494','送长沙陈太守二首 二','李白','quantangshi','','卷9','七郡长沙国，南连湘水滨。
定王垂舞袖，地窄不回身。
莫小二千石，当安远俗人。
洞庭乡路远，遥羡锦衣春。','',''),('quantangshi-08495','送杨燕之东鲁','李白','quantangshi','','卷9','关西杨伯起，汉日旧称贤。
四代三公族，清风播人天。
夫子华阴居，开门对玉莲。
何事历衡霍，云帆今始还。
君坐稍解颜，为君歌此篇。
我固侯门士，谬登圣主筵。
一辞金华殿，蹭蹬长江边。
二子鲁门东，别来已经年。
因君此中去，不觉泪如泉。','',''),('quantangshi-08496','送蔡山人','李白','quantangshi','','卷9','我本不弃世，世人自弃我。
一乘无倪舟，八极纵远柂。
燕客期跃马，唐生安敢讥。
采珠勿惊龙，大道可暗归。
故山有松月，迟尔翫清晖。','',''),('quantangshi-08497','送萧三十一之鲁中兼问稚子伯禽','李白','quantangshi','','卷9','六月南风吹白沙，吴牛喘月气成霞。
水国郁蒸不可处，时炎道远无行车。
夫子如何涉江路，云帆袅袅金陵去。
高堂倚门望伯鱼，鲁中正是趋庭处。
我家寄在沙丘傍，三年不归空断肠。
君行既识伯禽子，应驾小车骑白羊。','',''),('quantangshi-08498','送杨山人归嵩山','李白','quantangshi','','卷9','我有万古宅，嵩阳玉女峰。
长留一片月，挂在东溪松。
尔去掇仙草，菖蒲花紫茸。
岁晚或相访，青天骑白龙。','',''),('quantangshi-08499','送殷淑三首 一','李白','quantangshi','','卷9','海水不可解，连江夜为潮。
俄然蒲屿阔，岸去酒船遥。
惜别耐取醉，鸣榔且长谣。
天明尔当去，应便有风飘。','',''),('quantangshi-08500','送殷淑三首 二','李白','quantangshi','','卷9','白鹭洲前月，天明送客回。
青龙山后日，早出海云来。
流水无情去，征帆逐吹开。
相看不忍别，更进手中杯。','',''),('quantangshi-08501','送殷淑三首 三','李白','quantangshi','','卷9','痛饮龙筇下，灯青月复寒。
醉歌惊白鹭，半夜起沙滩。','',''),('quantangshi-08502','送岑征君归鸣臯山','李白','quantangshi','','卷9','岑公相门子，雅望归安石。
奕世皆夔龙，中台竟三拆。
至人达机兆，高揖九州伯。
奈何天地间，而作隐沦客。
贵道能全真，潜辉卧幽邻。
探元入窅默，观化游无垠。
光武有天下，严陵为故人。
虽登洛阳殿，不屈巢由身。
余亦谢明主，今称偃蹇臣。
登高览万古，思与广成邻。
蹈海宁受赏，还山非问津。
西来一摇扇，共拂元规尘。','',''),('quantangshi-08503','送范山人归泰山','李白','quantangshi','','卷9','鲁客抱白鹤，别余往泰山。
初行若片云，杳在青崖间。
高高至天门，日观近可攀。
云山望不及，此去何时还。','',''),('quantangshi-08504','送韩侍御之广德','李白','quantangshi','','卷9','昔日绣衣何足荣，今宵贳酒与君倾。
暂就东山赊月色，酣歌一夜送泉明。','',''),('quantangshi-08505','送通禅师还南陵隐静寺','李白','quantangshi','','卷9','我闻隐静寺，山水多奇踪。
岩种朗公橘，门深杯渡松。
道人制猛虎，振锡还孤峰。
他日南陵下，相期谷口逢。','',''),('quantangshi-08506','送友人','李白','quantangshi','','卷9','青山横北郭，白水遶东城。
此地一为别，孤蓬万里征。
浮云游子意，落日故人情。
挥手自兹去，萧萧班马鸣。','',''),('quantangshi-08507','送别','李白','quantangshi','','卷9','斗酒渭城边，垆头醉不眠。
梨花千树雪，杨叶万条烟。
惜别倾壶醑，临分赠马鞭。
看君颍上去，新月到应圆。','',''),('quantangshi-08508','江上送女道士褚三清游南岳','李白','quantangshi','','卷9','吴江女道士，头戴莲花巾。
霓衣不湿雨，特异阳台云。
足下远游履，凌波生素尘。
寻仙向南岳，应见魏夫人。','',''),('quantangshi-08509','送友人入蜀','李白','quantangshi','','卷9','见说蚕丛路，崎岖不易行。
山从人面起，云傍马头生。
芳树笼秦栈，春流遶蜀城。
升沉应已定，不必问君平。','',''),('quantangshi-08510','送李青归南叶阳川','李白','quantangshi','','卷9','伯阳仙家子，容色如青春。
日月祕灵洞，云霞辞世人。
化心养精魄，隐几窅天真。
莫作千年别，归来城郭新。','',''),('quantangshi-08511','送舍弟','李白','quantangshi','','卷9','吾家白额驹，远别临东道。
他日相思一梦君，应得池塘生春草。','',''),('quantangshi-08512','送别得书字','李白','quantangshi','','卷9','水色南天远，舟行若在虚。
迁人发佳兴，吾子访闲居。
日落看归鸟，潭澄羡跃鱼。
圣朝思贾谊，应降紫泥书。','',''),('quantangshi-08513','送麴十少府','李白','quantangshi','','卷9','试发清秋兴，因为吴会吟。
碧云歛海色，流水折江心。
我有延陵剑，君无陆贾金。
艰难此为别，惆怅一何深。','',''),('quantangshi-08514','送张秀才谒高中丞','李白','quantangshi','','卷9','秦帝沦玉镜，留侯降氛氲。
感激黄石老，经过沧海君。
壮士挥金槌，报讐六国闻。
智勇冠终古，萧陈难与羣。
两龙争鬬时，天地动风云。
酒酣舞长剑，仓卒解汉纷。
宇宙初倒悬，鸿沟势将分。
英谋信奇绝，夫子扬清芬。
胡月入紫微，三光乱天文。
高公镇淮海，谈笑却妖氛。
采尔幕中画，戡难光殊勋。
我无燕霜感，玉石俱烧焚。
但洒一行泪，临岐竟何云。','',''),('quantangshi-08515','寻阳送弟昌峒鄱阳司马作','李白','quantangshi','','卷9','桑落洲渚连，沧江无云烟。
浔阳非剡水，忽见子猷船。
飘然欲相近，来迟杳若仙。
人乘海上月，帆落湖中天。
一覩无二诺，朝懽更胜昨。
尔则吾惠连，吾非尔康乐。
朱绂白银章，上官佐鄱阳。
松门拂中道，石镜回清光。
摇扇及于越，水亭风气凉。
与尔期此亭，期在秋月满。
时过或未来，两乡心已断。
吴山对楚岸，彭蠡当中州。
相思定如此，有穷尽年愁。','',''),('quantangshi-08516','饯校书叔云','李白','quantangshi','','卷9','少年费白日，歌笑矜朱颜。
不知忽已老，喜见春风还。
惜别且为欢，裴回桃李间。
看花饮美酒，听鸟临晴山。
向晚竹林寂，无人空闭关。','',''),('quantangshi-08517','送王孝廉觐省','李白','quantangshi','','卷9','彭蠡将天合，姑苏在日边。
宁亲候海色，欲动孝廉船。
窈窕晴江转，参差远岫连。
相思无昼夜，东泣似长川。','',''),('quantangshi-08518','同吴王送杜秀芝赴举入京','李白','quantangshi','','卷9','秀才何翩翩，王许回也贤。
暂别庐江守，将游京兆天。
秋山宜落日，秀水出寒烟。
欲折一枝桂，还来雁沼前。','',''),('quantangshi-08519','洞庭醉后送绛州吕使君果流澧州','李白','quantangshi','','卷9','昔别若梦中，天涯忽相逢。
洞庭破秋月，纵酒开愁容。
赠剑刻玉字，延平两蛟龙。
送君不尽意，书及雁回峯。','',''),('quantangshi-08520','与诸公送陈郎将归衡阳','李白','quantangshi','','卷9','衡山苍苍入紫冥，下看南极老人星。
回飙吹散五峰雪，往往飞花落洞庭。
气清岳秀有如此，郎将一家拖金紫。
门前食客乱浮云，世人皆比孟尝君。
江上送行无白璧，临歧惆怅若为分。','',''),('quantangshi-08521','送赵判官赴黔府中丞叔幕','李白','quantangshi','','卷9','廓落青云心，交结黄金尽。
富贵翻相忘，令人忽自哂。
蹭蹬鬓毛斑，盛时难再还。
巨源咄石生，何事马蹄间。
绿萝长不厌，却欲还东山。
君为鲁曾子，拜揖高堂里。
叔继赵平原，偏承明主恩。
风霜推独坐，旌节镇雄藩。
虎士秉金钺，蛾眉开玉樽。
才高幕下去，义重林中言。
水宿五溪月，霜啼三峡猨。
东风春草绿，江上候归轩。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-08522','送陆判官往琵琶峡','李白','quantangshi','','卷9','水国秋风夜，殊非远别时。
长安如梦里，何日是归期。','',''),('quantangshi-08523','送梁四归东平','李白','quantangshi','','卷9','玉壶挈美酒，送别强为欢。
大火南星月，长郊北路难。
殷王期负鼎，汶水起垂竿。
莫学东山卧，参差老谢安。','',''),('quantangshi-08524','江夏送友人','李白','quantangshi','','卷9','雪点翠云裘，送君黄鹤楼。
黄鹤振玉羽，西飞帝王州。
凤无琅玕实，何以赠远游。
裴回相顾影，泪下汉江流。','',''),('quantangshi-08525','送郄昂谪巴中','李白','quantangshi','','卷9','瑶草寒不死，移植沧江滨。
东风洒雨露，会入天地春。
予若洞庭叶，随波送逐臣。
思归未可得，书此谢情人。','',''),('quantangshi-08526','江夏送张丞','李白','quantangshi','','卷9','欲别心不忍，临行情更亲。
酒倾无限月，客醉几重春。
藉草依流水，攀花赠远人。
送君从此去，回首泣迷津。','',''),('quantangshi-08527','赋得白鹭鸶送宋少府入三峡','李白','quantangshi','','卷9','白鹭拳一足，月明秋水寒。
人惊远飞去，直向使君滩。','',''),('quantangshi-08528','送二季之江东','李白','quantangshi','','卷9','初发强中作，题诗与惠连。
多惭一日长，不及二龙贤。
西塞当中路，南风欲进船。
云峰出远海，帆影挂清川。
禹穴藏书地，匡山种杏田。
此行俱有适，迟尔早归旋。','',''),('quantangshi-08529','江西送友人之罗浮','李白','quantangshi','','卷9','桂水分五岭，衡山朝九疑。
乡关渺安西，流浪将何之。
素色愁明湖，秋渚晦寒姿。
畴昔紫芳意，已过黄发期。
君王纵疎散，云壑借巢夷。
尔去之罗浮，我还憩峨眉。
中阔道万里，霞月遥相思。
如寻楚狂子，琼树有芳枝。','',''),('quantangshi-08530','宣州谢朓楼饯别校书叔云','李白','quantangshi','','卷9','弃我去者昨日之日不可留，乱我心者今日之日多烦忧。
长风万里送秋雁，对此可以酣高楼。
蓬莱文章建安骨，中间小谢又清发。
俱怀逸兴壮思飞，欲上青天览日月。
抽刀断水水更流，举杯销愁愁更愁。
人生在世不称意，明朝散发弄扁舟。','',''),('quantangshi-08531','宣城送刘副使入秦','李白','quantangshi','','卷9','君即刘越石，雄豪冠当时。
凄清横吹曲，慷慨扶风词。
虎啸俟腾跃，鸡鸣遭乱离。
千金市骏马，万里逐王师。
结交楼烦将，侍从羽林儿。
统兵捍吴越，豺虎不敢窥。
大勋竟莫叙，已过秋风吹。
秉钺有季公，凛然负英姿。
寄深且戎幕，望重必台司。
感激一然诺，纵横两无疑。
伏奏归北阙，鸣驺忽西驰。
列将咸出祖，英僚惜分离。
斗酒满四筵，歌啸宛溪湄。
君携东山妓，我咏北门诗。
贵贱交不易，恐伤中园葵。
昔赠紫骝驹，今倾白玉巵。
同欢万斛酒，未足解相思。
此别又千里，秦吴渺天涯。
月明关山苦，水剧陇头悲。
借问几时还，春风入黄池。
无令长相忆，折断绿杨枝。','',''),('quantangshi-08532','泾川送族弟錞','李白','quantangshi','','卷9','泾川三百里，若耶羞见之。
锦石照碧山，两边白鹭鸶。
佳境千万曲，客行无歇时。
上有琴高水，下有陵阳祠。
仙人不见我，明月空相知。
问我何事来，卢敖结幽期。
蓬山振雄笔，绣服挥清词。
江湖发秀色，草木含荣滋。
置酒送惠连，吾家称白眉。
愧无海峤作，敢阙河梁诗。
见尔复几朝，俄然告将离。
中流漾彩鷁，列岸丛金羁。
叹息苍梧凤，分栖琼树枝。
清晨各飞去，飘落天南垂。
望极落日尽，秋深暝猨悲。
寄情与流水，但有长相思。','',''),('quantangshi-08533','五松山送殷淑','李白','quantangshi','','卷9','秀色发江左，风流奈若何。
仲文了不还，独立扬清波。
载酒五松山，颓然白云歌。
中天度落月，万里遥相过。
抚酒惜此月，流光畏蹉跎。
明日别离去，连峰郁嵯峨。','',''),('quantangshi-08534','送崔氏昆季之金陵','李白','quantangshi','','卷9','放歌倚东楼，行子期晓发。
秋风渡江来，吹落山上月。
主人出美酒，灭烛延清光。
二崔向金陵，安得不尽觞。
水客弄归棹，云帆卷轻霜。
扁舟敬亭下，五两先飘扬。
峡石入水花，碧流日更长。
思君无岁月，西笑阻河梁。','',''),('quantangshi-08535','登黄山凌歊台送族弟溧阳尉济充泛舟赴华阴','李白','quantangshi','','卷9','鸾乃凤之族，翱翔紫云霓。
文章辉五色，双在琼树栖。
一朝各飞去，凤与鸾俱啼。
炎赫五月中，朱曦烁河堤。
尔从泛舟役，使我心魂凄。
秦地无碧草，南云喧鼓鼙。
君王减玉膳，早起思鸣鸡。
漕引救关辅，疲人免涂泥。
宰相作霖雨，农夫得耕犂。
静者伏草间，羣才满金闺。
空手无壮士，穷居使人低。
送君登黄山，长啸倚天梯。
小舟若凫雁，大舟若鲸鲵。
开帆散长风，舒卷与云齐。
日入牛渚晦，苍然夕烟迷。
相思定何许，杳在洛阳西。','',''),('quantangshi-08536','送储邕之武昌','李白','quantangshi','','卷9','黄鹤西楼月，长江万里情。
春风三十度，空忆武昌城。
送尔难为别，衔杯惜未倾。
湖连张乐地，山逐泛舟行。
诺为楚人重，诗传谢朓清。
沧浪吾有曲，寄入棹歌声。','',''),('quantangshi-08537','酬谈少府','李白','quantangshi','','卷9','一尉居倏忽，梅生有仙骨。
三事或可羞，匈奴哂千秋。
壮士屈黄绶，浪迹寄沧洲。
昨观荆岘作，如从云汉游。
老夫当暮矣，蹀足惧骅骝。','',''),('quantangshi-08538','酬宇文少府见赠桃竹书筒','李白','quantangshi','','卷9','桃竹书筒绮绣文，良工巧妙称绝羣。
灵心圆映三江月，彩质叠成五色云。
中藏宝诀峨眉去，千里提携长忆君。','',''),('quantangshi-08539','五月东鲁行答汶上君','李白','quantangshi','','卷9','五月梅始黄，蚕凋桑柘空。
鲁人重织作，机杼鸣帘栊。
顾余不及仕，学剑来山东。
举鞭访前途，获笑汶上翁。
下愚忽壮士，未足论穷通。
我以一箭书，能取聊城功。
终然不受赏，羞与时人同。
西归去直道，落日昏阴虹。
此去尔勿言，甘心为转蓬。','',''),('quantangshi-08540','早秋单父南楼酬窦公衡','李白','quantangshi','','卷9','白露见日灭，红颜随霜凋。
别君若俯仰，春芳辞秋条。
泰山嵯峨夏云在，疑是白波涨东海。
散为飞雨川上来，遥帷却卷清浮埃。
知君独坐青轩下，此时结念同所怀。
我闭南楼看道书，幽帘清寂在仙居。
曾无好事来相访，赖尔高文一起予。','',''),('quantangshi-08541','山中问答','李白','quantangshi','','卷9','问余何意栖碧山，笑而不答心自闲。
桃花流水窅然去，别有天地非人间。','',''),('quantangshi-08542','答友人赠乌纱帽','李白','quantangshi','','卷9','领得乌纱帽，全胜白接䍦。
山人不照镜，稚子道相宜。','',''),('quantangshi-08543','酬张司马赠墨','李白','quantangshi','','卷9','上党碧松烟，夷陵丹砂末。
兰麝凝珍墨，精光乃堪掇。
黄头奴子双鸦鬟，锦囊养之怀袖间。
今日赠予兰亭去，兴来洒笔会稽山。','',''),('quantangshi-08544','答湖州迦叶司马问白是何人','李白','quantangshi','','卷9','青莲居士谪仙人，酒肆藏名三十春。
湖州司马何须问，金粟如来是后身。','',''),('quantangshi-08545','答长安崔少府叔封游终南翠微寺太宗皇帝金沙泉见寄','李白','quantangshi','','卷9','河伯见海若，傲然夸秋水。
小物昧远图，宁知通方士。
多君紫霄意，独往苍山里。
地古寒云深，岩高长风起。
初登翠微岭，复憩金沙泉。
践苔朝霜滑，弄波夕月圆。
饮彼石下流，结萝宿溪烟。
鼎湖梦渌水，龙驾空茫然。
早行子午关，却登山路远。
拂琴听霜猨，灭烛乃星饭。
人烟无明异，鸟道绝往返。
攀厓倒青天，下视白日晚。
既过石门隐，还唱石潭歌。
涉雪搴紫芳，濯缨想清波。
此人不可见，此地君自过。
为余谢风泉，其如幽意何。','',''),('quantangshi-08546','酬崔五郎中','李白','quantangshi','','卷9','朔云横高天，万里起秋色。
壮士心飞扬，落日空叹息。
长啸出原野，凛然寒风生。
幸遭圣明时，功业犹未成。
奈何怀良图，郁悒独愁坐。
杖策寻英豪，立谈乃知我。
崔公生民秀，缅邈青云姿。
制作参造化，托讽含神只。
海岳尚可倾，吐诺终不移。
是时霜飙寒，逸兴临华池。
起舞拂长剑，四座皆扬眉。
因得穷懽情，赠我以新诗。
又结汗漫期，九垓远相待。
举身憩蓬壶，濯足弄沧海。
从此凌倒景，一去无时还。
朝游明光宫，暮入阊阖关。
但得长把袂，何必嵩丘山。','',''),('quantangshi-08547','以诗代书答元丹丘','李白','quantangshi','','卷9','青鸟海上来，今朝发何处。
口衔云锦字，与我忽飞去。
鸟去凌紫烟，书留绮窗前。
开缄方一笑，乃是故人传。
故人深相勖，忆我劳心曲。
离居在咸阳，三见秦草绿。
置书双袂间，引领不暂闲。
长望杳难见，浮云横远山。','',''),('quantangshi-08548','金门答苏秀才','李白','quantangshi','','卷9','君还石门日，朱火始改木。
春草如有情，山中尚含绿。
折芳愧遥忆，永路当自勖。
远见故人心，平生以此足。
巨海纳百川，麟阁多才贤。
献书入金阙，酌醴奉琼筵。
屡忝白云唱，恭闻黄竹篇。
恩光照拙薄，云汉希腾迁。
铭鼎倘云逐，扁丹方渺然。
我留在金门，君去卧丹壑。
未果三山期，遥欣一丘乐。
玄珠寄象罔，赤水非寥廓。
愿狎东海鸥，共营西山药。
栖岩君寂灭，处世余龙蠖。
良辰不同赏，永日应闲居。
鸟吟檐间树，花落窗下书。
缘溪见绿筱，隔岫窥红蕖。
采薇行笑歌，眷我情何已。
月出石镜间，松鸣风琴里。
得心自虚妙，外物空颓靡。
身世如两忘，从君老烟水。','',''),('quantangshi-08549','酬坊州王司马与阎正字对雪见赠','李白','quantangshi','','卷9','游子东南来，自宛适京国。
飘然无心云，倏忽复西北。
访戴昔未偶，寻嵇此相得。
愁颜发新懽，终宴叙前识。
阎公汉庭旧，沈郁富才力。
价重铜龙楼，声高重门侧。
宁期此相遇，华馆陪游息。
积雪明远峰，寒城锁春色。
主人苍生望，假我青云翼。
风水如见资，投竿佐皇极。','',''),('quantangshi-08550','酬中都小吏携斗酒双鱼于逆旅见赠','李白','quantangshi','','卷9','鲁酒若琥珀，汶鱼紫锦鳞。
山东豪吏有俊气，手携此物赠远人。
意气相倾两相顾，斗酒双鱼表情素。
双鳃呀呷鳍鬣张，蹳刺银盘欲飞去。
呼儿拂几霜刃挥，红肌花落白雪霏。
为君下筯一餐饱，醉着金鞍上马归。','',''),('quantangshi-08551','酬张卿夜宿南陵见赠','李白','quantangshi','','卷9','月出鲁城东，明如天上雪。
鲁女惊莎鸡，鸣机应秋节。
当君相思夜，火落金风高。
河汉挂户牖，欲济无轻舠。
我昔辞林丘，云龙忽相见。
客星动太微，朝去洛阳殿。
尔来得茂彦，七叶仕汉余。
身为下邳客，家有圯桥书。
傅说未梦时，终当起岩野。
万古骑辰星，光辉照天下。
与君各未遇，长策委蒿莱。
宝刀隐玉匣，锈涩空莓苔。
遂令世上愚，轻我土与灰。
一朝攀龙去，鼃黾安在哉？
故山定有酒，与尔倾金罍。','',''),('quantangshi-08552','酬岑勋见寻就元丹丘对酒相待以诗见招','李白','quantangshi','','卷9','黄鹤东南来，寄书写心曲。
倚松开其缄，忆我肠断续。
不以千里遥，命驾来相招。
中逢元丹丘，登岭宴碧霄。
对酒忽思我，长啸临清飙。
蹇予未相知，茫茫绿云垂。
俄然素书及，解此长渴饥。
策马望山月，途穷造阶墀。
喜兹一会面，若覩琼树枝。
忆君我远来，我懽方速至。
开颜酌美酒，乐极忽成醉。
我情既不浅，君意方亦深。
相知两相得，一顾轻千金。
且向山客笑，与君论素心。','',''),('quantangshi-08553','答从弟幼成过西园见赠','李白','quantangshi','','卷9','一身自潇洒，万物何嚣喧。
拙薄谢明时，栖闲归故园。
二季过旧壑，四邻驰华轩。
衣剑照松宇，宾徒光石门。
山童荐珍果，野老开芳樽。
上陈樵渔事，下叙农圃言。
昨来荷花满，今见兰苕繁。
一笑复一歌，不知夕景昏。
醉罢同所乐，此情难具论。','',''),('quantangshi-08554','酬王补阙惠翼庄庙宋丞泚赠别','李白','quantangshi','','卷9','学道三千春，自言羲和人。
轩盖宛若梦，云松长相亲。
偶将二公合，复与三山邻。
喜结海上契，自为天外宾。
鸾翮我先铩，龙性君莫驯。
朴散不尚古，时讹皆失真。
勿踏荒溪坡，朅来浩然津。
薜带何辞楚，桃源堪避秦。
世迫且离别，心在期隐沦。
酬赠非炯诫，永言铭佩绅。','',''),('quantangshi-08555','酬裴侍御对雨感时见赠','李白','quantangshi','','卷9','雨色秋来寒，风严清江爽。
孤高绣衣人，潇洒青霞赏。
平生多感激，忠义非外奖。
祸连积怨生，事及徂川往。
楚邦有壮士，鄢郢翻扫荡。
申包哭秦庭，泣血将安仰。
鞭尸辱已及，堂上罗宿莽。
颇似今之人，蟊贼陷忠谠。
渺然一水隔，何由税归鞅。
日夕听猨怨，怀贤盈梦想。','',''),('quantangshi-08556','酬崔侍御','李白','quantangshi','','卷9','严陵不从万乘游，归卧空山钓碧流。
自是客星辞帝座，元非太白醉扬州。','',''),('quantangshi-08557','翫月金陵城西孙楚酒楼达曙歌吹日晚乘醉着紫绮裘乌纱巾与酒客数人棹歌秦淮往石头访崔四侍御','李白','quantangshi','','卷9','昨翫西城月，青天垂玉钩。
朝沽金陵酒，歌吹孙楚楼。
忽忆绣衣人，乘船往石头。
草裹乌纱巾，倒被紫绮裘。
两岸拍手笑，疑是王子猷。
酒客十数公，崩腾醉中流。
谑浪棹海客，喧呼傲阳侯。
半道逢吴姬，卷帘出揶揄。
我忆君到此，不知狂与羞。
一月一见君，三杯便回桡。
舍舟共连袂，行上南渡桥。
兴发歌绿水，秦客为之摇。
鸡鸣复相招，清宴逸云霄。
赠我数百字，字字凌风飙。
系之衣裘上，相忆每长谣。','',''),('quantangshi-08558','江上答崔宣城','李白','quantangshi','','卷9','太华三芙蓉，明星玉女峰。
寻仙下西岳，陶令忽相逢。
问我将何事，湍波历几重。
貂裘非季子，鹤氅似王恭。
谬忝燕台召，而陪郭隗踪。
水流知入海，云去或从龙。
树绕芦洲月，山鸣鹊镇钟。
还期如可访，台岭荫长松。','',''),('quantangshi-08559','答族侄僧中孚赠玉泉仙人掌茶','李白','quantangshi','','卷9','常闻玉泉山，山洞多乳窟。
仙鼠如白鸦，倒悬清溪月。
茗生此中石，玉泉流不歇。
根柯洒芳津，采服润肌骨。
丛老卷绿叶，枝枝相接连。
曝成仙人掌，似拍洪崖肩。
举世未见之，其名定谁传。
宗英乃禅伯，投赠有佳篇。
清镜烛无盐，顾惭西子妍。
朝坐有余兴，长吟播诸天。','',''),('quantangshi-08560','酬裴侍御留岫师弹琴见寄','李白','quantangshi','','卷9','君同鲍明远，邀彼休上人。
鼓琴乱白雪，秋变江上春。
瑶草绿未衰，攀翻寄情亲。
相思两不见，流泪空盈巾。','',''),('quantangshi-08561','张相公出镇荆州寻除太子詹事余时流夜郎行至江夏与张公去千里公因太府丞王昔使车寄罗衣二事及五月五日赠余诗余答以此诗','李白','quantangshi','','卷9','张衡殊不乐，应有四愁诗。
慙君锦绣段，赠我慰相思。
鸿鹄复矫翼，凤凰忆故池。
荣乐一如此，商山老紫芝。','',''),('quantangshi-08562','醉后答丁十八以诗讥余捶碎黄鹤楼','李白','quantangshi','','卷9','黄鹤高楼已槌碎，黄鹤仙人无所依。
黄鹤上天诉玉帝，却放黄鹤江南归。
神明太守再雕饰，新图粉壁还芳菲。
一州笑我为狂客，少年往往来相讥。
君平帘下谁家子，云是辽东丁令威。
作诗调我惊逸兴，白云遶笔窗前飞。
待取明朝酒醒罢，与君烂漫寻春晖。','',''),('quantangshi-08563','答裴侍御先行至石头驿以书见招期月满泛洞庭','李白','quantangshi','','卷9','君至石头驿，寄书黄鹤楼。
开缄识远意，速此南行舟。
风水无定准，湍波或滞留。
忆昨新月生，西檐若琼钩。
今来何所似，破镜悬清秋。
恨不三五明，平湖泛澄流。
此欢竟莫遂，狂杀王子猷。
巴陵定遥远，持赠解人忧。','',''),('quantangshi-08564','答高山人兼呈权顾二侯','李白','quantangshi','','卷9','虹霓掩天光，哲后起康济。
应运生夔龙，开元扫氛翳。
太微廓金镜，端拱清遐裔。
轻尘集嵩岳，虚点盛明意。
谬挥紫泥诏，献纳青云际。
谗惑英主心，恩疎佞臣计。
仿徨庭阙下，叹息光阴逝。
未作仲宣诗，先流贾生涕。
挂帆秋江上，不为云罗制。
山海向东倾，百川无尽势。
我于鸱夷子，相去千余岁。
运阔英达稀，同风遥执袂。
登舻望远水，忽见沧浪枻。
高士何处来，虚舟渺安系。
衣貌本淳古，文章多佳丽。
延引故乡人，风义未沦替。
顾侯达语默，权子识通蔽。
曾是无心云，俱为此留滞。
双萍易飘转，独鹤思凌厉。
明晨去潇湘，共谒苍梧帝。','',''),('quantangshi-08565','答杜秀才五松见赠','李白','quantangshi','','卷9','昔献长杨赋，天开云雨欢。
当时待诏承明里，皆道扬雄才可观。
勅赐飞龙二天马，黄金络头白玉鞍。
浮云蔽日去不返，总为秋风摧紫兰。
角巾东出商山道，采秀行歌咏芝草。
路逢园绮笑向人，两君解来一何好。
闻道金陵龙虎盘，还同谢朓望长安。
千峰夹水向秋浦，五松名山当夏寒。
铜井炎炉歊九天，赫如铸鼎荆山前。
陶公瞿铄呵赤电，回禄睢盱扬紫烟。
此中岂是久留处，便欲烧丹从列仙。
爱听松风且高卧，飕飕吹尽炎氛过。
登崖独立望九州，阳春欲奏谁相和。
闻君往年游锦城，章仇尚书倒屣迎。
飞笺洛绎奏明主，天书降问回恩荣。
肮脏不能就圭组，至今空扬高蹈名。
夫子工文绝世奇，五松新作天下推。
吾非谢尚邀彦伯，异代风流各一时。
一时相逢乐在今，袖拂白云开素琴，弹为三峡流泉音。
从兹一别武陵去，去后桃花春水深。','',''),('quantangshi-08566','至陵阳山登天柱石酬韩侍御见招隐黄山','李白','quantangshi','','卷9','韩众骑白鹿，西往华山中。
玉女千余人，相随在云空。
见我传祕诀，精诚与天通。
何意到陵阳，游目送飞鸿。
天子昔避狄，与君亦乘骢。
拥兵五陵下，长策遏胡戎。
时泰解绣衣，脱身若飞蓬。
鸾凤翻羽翼，啄粟坐樊笼。
海鹤一笑之，思归向辽东。
黄山过石柱，巘崿上攒丛。
因巢翠玉树，忽见浮丘公。
又引王子乔，吹笙舞松风。
朗咏紫霞篇，请开蘂珠宫。
步纲绕碧落，倚树招青童。
何日可携手，遗形入无穷。','',''),('quantangshi-08567','酬崔十五见招','李白','quantangshi','','卷9','尔有鸟迹书，相招琴溪饮。
手迹尺素中，如天落云锦。
读罢向空笑，疑君在我前。
长吟字不灭，怀袖且三年。','',''),('quantangshi-08568','答王十二寒夜独酌有怀','李白','quantangshi','','卷9','昨夜吴中雪，子猷佳兴发。
万里浮云卷碧山，青天中道流孤月。
孤月沧浪河汉清，北斗错落长庚明。
怀余对酒夜霜白，玉牀金井水峥嵘。
人生飘忽百年内，且须酣畅万古情。
君不能狸膏金距学鬬鸡，坐令鼻息吹虹霓。
君不能学哥舒横行青海夜带刀，西屠石堡取紫袍。
吟诗作赋北牕里，万言不直一杯水。
世人闻此皆掉头，有如东风射马耳。
鱼目亦笑我，请与明月同。
骅骝拳局不能食，蹇驴得志鸣春风。
折杨皇华合流俗，晋君听琴枉清角。
巴人谁肯和阳春，楚地由来贱奇璞。
黄金散尽交不成，白首为儒身被轻。
一谈一笑失颜色，苍蝇贝锦喧谤声。
曾参岂是杀人者，谗言三及慈母惊。
与君论心握君手，荣辱于余亦何有。
孔圣犹闻伤凤麟，董龙更是何鸡狗。
一生傲岸苦不谐，恩疎媒劳志多乖。
严陵高揖汉天子，何必长剑拄颐事玉阶。
达亦不足贵，穷亦不足悲。
韩信羞将绛灌比，禰衡耻逐屠沽儿。
君不见李北海，英风豪气今何在？
君不见裴尚书，土坟三尺蒿棘居。
少年早欲五湖去，见此弥将钟鼎疎。','',''),('quantangshi-08569','游南阳白水登石激作','李白','quantangshi','','卷9','朝涉白水源，暂与人俗疎。
岛屿佳境色，江天涵清虚。
目送去海云，心闲游川鱼。
长歌尽落日，乘月归田庐。','',''),('quantangshi-08570','游南阳清泠泉','李白','quantangshi','','卷9','惜彼落日暮，爱此寒泉清。
西辉逐流水，荡漾游子情。
空歌望云月，曲尽长松声。','',''),('quantangshi-08571','寻鲁城北范居士失道落苍耳中见范置酒摘苍耳作','李白','quantangshi','','卷9','雁度秋色远，日静无云时。
客心不自得，浩漫将何之。
忽忆范野人，闲园养幽姿。
茫然起逸兴，但恐行来迟。
城壕失往路，马首迷荒陂。
不惜翠云裘，遂为苍耳欺。
入门且一笑，把臂君为谁。
酒客爱秋蔬，山盘荐霜梨。
他筵不下筯，此席忘朝饥。
酸枣垂北郭，寒瓜蔓东篱。
还倾四五酌，自咏猛虎词。
近作十日欢，远为千载期。
风流自簸荡，谑浪偏相宜。
酣来上马去，却笑高阳池。','',''),('quantangshi-08572','东鲁门泛舟二首 一','李白','quantangshi','','卷9','日落沙明天倒开，波摇石动水萦回。
轻舟泛月寻溪转，疑是山隐雪后来。','',''),('quantangshi-08573','东鲁门泛舟二首 二','李白','quantangshi','','卷9','水作青龙盘石堤，桃花夹岸鲁门西。
若教月下乘舟去，何啻风流到剡溪。','',''),('quantangshi-08574','秋猎孟诸夜归置酒单父东楼观妓','李白','quantangshi','','卷9','倾晖速短炬，走海无停川。
冀餐圆丘草，欲以还颓年。
此事不可得，微生若浮烟。
骏发跨名驹，雕弓控鸣弦。
鹰豪鲁草白，狐兔多肥鲜。
邀遮相驰逐，遂出城东田。
一扫四野空，喧呼鞍马前。
归来献所获，炮炙宜霜天。
出舞两美人，飘颻若云仙。
留欢不知疲，清晓方来旋。','',''),('quantangshi-08575','游泰山六首 一','李白','quantangshi','','卷9','四月上泰山，石屏御道开。
六龙过万壑，涧谷随萦回。
马迹遶碧峯，于今满青苔。
飞流洒绝巘，水急松声哀。
北眺崿嶂奇，倾崖向东摧。
洞门闭石扇，地底兴云雷。
登高望蓬瀛，想象金银台。
天门一长啸，万里清风来。
玉女四五人，飘颻下九垓。
含笑引素手，遗我流霞杯。
稽首再拜之，自愧非仙才。
旷然小宇宙，弃世何悠哉。','',''),('quantangshi-08576','游泰山六首 二','李白','quantangshi','','卷9','清晓骑白鹿，直上天门山。
山际逢羽人，方瞳好容颜。
扪萝欲就语，却掩青云关。
遗我鸟迹书，飘然落岩间。
其字乃上古，读之了不闲。
感此三叹息，从师方未还。','',''),('quantangshi-08577','游泰山六首 三','李白','quantangshi','','卷9','平明登日观，举手开云关。
精神四飞扬，如出天地间。
黄河从西来，窈窕入远山。
凭崖揽八极，目尽长空闲。
偶然值青童，绿发双云鬟。
笑我晚学仙，蹉跎凋朱颜。
踌躇忽不见，浩荡难追攀。','',''),('quantangshi-08578','游泰山六首 四','李白','quantangshi','','卷9','清斋三千日，裂素写道经。
吟诵有所得，众神卫我形。
云行信长风，飒若羽翼生。
攀崖上日观，伏槛窥东溟。
海色动远山，天鸡已先鸣。
银台出倒景，白浪翻长鲸。
安得不死药，高飞向蓬瀛。','',''),('quantangshi-08579','游泰山六首 五','李白','quantangshi','','卷9','日观东北倾，两崖夹双石。
海水落眼前，天光遥空碧。
千峯争攒聚，万壑绝凌历。
缅彼鹤上仙，去无云中迹。
长松入云汉，远望不盈尺。
山花异人间，五月雪中白。
终当遇安期，于此炼玉液。','',''),('quantangshi-08580','游泰山六首 六','李白','quantangshi','','卷9','朝饮王母池，暝投天门关。
独抱绿绮琴，夜行青山间。
山明月露白，夜静松风歇。
仙人游碧峯，处处笙歌发。
寂静娱清晖，玉真连翠微。
想象鸾凤舞，飘颻龙虎衣。
扪天摘匏瓜，恍惚不忆归。
举手弄清浅，误攀织女机。
明晨坐相失，但见五云飞。','',''),('quantangshi-08581','秋夜与刘砀山泛宴喜亭池','李白','quantangshi','','卷9','明宰试舟楫，张灯宴华池。
文招梁苑客，歌动郢中儿。
月色望不尽，空天交相宜。
令人欲泛海，只待长风吹。','',''),('quantangshi-08582','携妓登梁王栖霞山孟氏桃园中','李白','quantangshi','','卷9','碧草已满地，柳与梅争春。
谢公自有东山妓，金屏笑坐如花人。
今日非昨日，明日还复来。
白发对绿酒，强歌心已摧。
君不见梁王池上月，昔照梁王樽酒中。
梁王已去明月在，黄鹂愁醉啼春风。
分明感激眼前事，莫惜醉卧桃园东。','',''),('quantangshi-08583','与从侄杭州刺史良游天竺寺','李白','quantangshi','','卷9','挂席凌蓬丘，观涛憩樟楼。
三山动逸兴，五马同遨游。
天竺森在眼，松风飒惊秋。
览云测变化，弄水穷清幽。
叠嶂隔遥海，当轩写归流。
诗成傲云月，佳趣满吴洲。','',''),('quantangshi-08584','同友人舟行游台越作','李白','quantangshi','','卷9','楚臣伤江枫，谢客拾海月。
怀沙去潇湘，挂席泛溟渤。
蹇予访前迹，独往造穷发。
古人不可攀，去若浮云没。
愿言弄倒景，从此炼真骨。
华顶窥绝溟，蓬壶望超忽。
不知青春度，但怪绿芳歇。
空持钓鳌心，从此谢魏阙。','',''),('quantangshi-08585','下终南山过斛斯山人宿置酒','李白','quantangshi','','卷9','暮从碧山下，山月随人归。
却顾所来径，苍苍横翠微。
相携及田家，童稚开荆扉。
绿竹入幽径，青萝拂行衣。
欢言得所憩，美酒聊共挥。
长歌吟松风，曲尽河星稀。
我醉君复乐，陶然共忘机。','',''),('quantangshi-08586','朝下过卢郎中叙旧游','李白','quantangshi','','卷9','君登金华省，我入银台门。
幸遇圣明主，俱承云雨恩。
复此休浣时，闲为畴昔言。
却话山海事，宛然林壑存。
明湖思晓月，叠嶂忆清猿。
何由返初服，田野醉芳樽。','',''),('quantangshi-08587','侍从游宿温泉宫作','李白','quantangshi','','卷9','羽林十二将，罗列应星文。
霜仗悬秋月，霓旌卷夜云。
严更千户肃，清乐九天闻。
日出瞻佳气，葱葱绕圣君。','',''),('quantangshi-08588','邯郸南亭观妓','李白','quantangshi','','卷9','歌鼓燕赵儿，魏姝弄鸣丝。
粉色艳日彩，舞袖拂花枝。
把酒顾美人，请歌邯郸词。
清筝何缭绕，度曲绿云垂。
平原君安在，科斗生古池。
座客三千人，于今知有谁。
我辈不作乐，但为后代悲。','',''),('quantangshi-08589','春日游罗敷潭','李白','quantangshi','','卷9','行歌入谷口，路尽无人跻。
攀崖度绝壑，弄水寻回溪。
云从石上起，客到花间迷。
淹留未尽兴，日落羣峯西。','',''),('quantangshi-08590','春陪商州裴使君游石娥溪','李白','quantangshi','','卷9','裴公有仙标，拔俗数千丈。
澹荡沧洲云，飘颻紫霞想。
剖竹商洛间，政成心已闲。
萧条出世表，冥寂闭玄关。
我来属芳节，解榻时相悦。
褰帷对云峯，扬袂指松雪。
蹔出东城边，遂游西岩前。
横天耸翠壁，喷壑鸣红泉。
寻幽殊未歇，爱此春光发。
溪傍饶名花，石上有好月。
命驾归去来，露华生翠苔。
淹留惜将晚，复听清猨哀。
清猨断人肠，游子思故乡。
明发首东路，此懽焉可忘。','',''),('quantangshi-08591','陪从祖济南太守泛鹊山湖三首 一','李白','quantangshi','','卷9','初谓鹊山近，宁知湖水遥。
此行殊访戴，自可缓归桡。','',''),('quantangshi-08592','陪从祖济南太守泛鹊山湖三首 二','李白','quantangshi','','卷9','湖阔数千里，湖光摇碧山。
湖西正有月，独送李膺还。','',''),('quantangshi-08593','陪从祖济南太守泛鹊山湖三首 三','李白','quantangshi','','卷9','水入北湖去，舟从南浦回。
遥看鹊山转，却似送人来。','',''),('quantangshi-08594','春日陪杨江宁及诸官宴北湖感古作','李白','quantangshi','','卷9','昔闻颜光禄，攀龙宴京湖。
楼船入天镜，帐殿开云衢。
君王歌大风，如乐丰沛都。
延年献佳作，邈与诗人俱。
我来不及此，独立钟山孤。
杨宰穆清风，芳声腾海隅。
英僚满四座，粲若琼林敷。
鷁首弄倒景，蛾眉缀明珠。
新弦采梨园，古舞娇吴歈。
曲度绕云汉，听者皆欢娱。
鸡栖何嘈嘈，沿月沸笙竽。
古之帝宫苑，今乃人樵苏。
感此劝一觞，愿君覆瓢壶。
荣盛当作乐，无令后贤吁。','',''),('quantangshi-08595','宴郑参卿山池','李白','quantangshi','','卷9','尔恐碧草晚，我畏朱颜移。
愁看杨花飞，置酒正相宜。
歌声送落日，舞影回清池。
今夕不尽杯，留欢更邀谁。','',''),('quantangshi-08596','游谢氏山亭','李白','quantangshi','','卷9','沦老卧江海，再欢天地清。
病闲久寂寞，岁物徒芬荣。
借君西池游，聊以散我情。
扫雪松下去，扪萝石道行。
谢公池塘上，春草飒已生。
花枝拂人来，山鸟向我鸣。
田家有美酒，落日与之倾。
醉罢弄归月，遥欣稚子迎。','',''),('quantangshi-08597','把酒问月','李白','quantangshi','','卷9','青天有月来几时，我今停杯一问之。
人攀明月不可得，月行却与人相随。
皎如飞镜临丹阙，绿烟灭尽清辉发。
但见宵从海上来，宁知晓向云间没。
白兔捣药秋复春，嫦娥孤栖与谁邻。
今人不见古时月，今月曾经照古人。
古人今人若流水，共看明月皆如此。
唯愿当歌对酒时，月光长照金樽里。','',''),('quantangshi-08598','同族侄评事黯游昌禅师山池二首 一','李白','quantangshi','','卷9','远公爱康乐，为我开禅关。
萧然松石下，何异清凉山。
花将色不染，水与心俱闲。
一坐度小劫，观空天地间。','',''),('quantangshi-08599','同族侄评事黯游昌禅师山池二首 二','李白','quantangshi','','卷9','客来花雨际，秋水落金池。
片石寒青锦，疎杨挂绿丝。
高僧拂玉柄，童子献霜梨。
惜去爱佳景，烟萝欲暝时。','',''),('quantangshi-08600','金陵凤凰台置酒','李白','quantangshi','','卷9','置酒延落景，金陵凤凰台。
长波写万古，心与云俱开。
借问往昔时，凤凰为谁来。
凤凰去已久，正当今日回。
明君越羲轩，天老坐三台。
豪士无所用，弹弦醉金罍。
东风吹山花，安可不尽杯。
六帝没幽草，深宫冥绿苔。
置酒勿复道，歌钟但相催。','',''),('quantangshi-08601','秋浦清溪雪夜对酒客有唱山鹧鸪者','李白','quantangshi','','卷9','披君貂襜褕，对君白玉壶。
雪花酒上灭，顿觉夜寒无。
客有桂阳至，能吟山鹧鸪。
清风动窗竹，越鸟起相呼。
持此足为乐，何烦笙与竽。','',''),('quantangshi-08602','与周刚清溪玉镜潭宴别','李白','quantangshi','','卷9','康乐上官去，永嘉游石门。
江亭有孤屿，千载迹犹存。
我来游秋浦，三入桃陂源。
千峯照积雪，万壑尽啼猨。
兴与谢公合，文因周子论。
扫厓去落叶，席月开清樽。
溪当大楼南，溪水正南奔。
回作玉镜潭，澄明洗心魂。
此中得佳境，可以绝嚣喧。
清夜方归来，酣歌出平原。
别后经此地，为余谢兰荪。','',''),('quantangshi-08603','游秋浦白笴陂二首 一','李白','quantangshi','','卷9','何处夜行好，月明白笴陂。
山光摇积雪，猨影挂寒枝。
但恐佳景晚，小令归棹移。
人来有清兴，及此有相思。','',''),('quantangshi-08604','游秋浦白笴陂二首 二','李白','quantangshi','','卷9','白笴夜长啸，爽然溪谷寒。
鱼龙动陂水，处处生波澜。
天借一明月，飞来碧云端。
故乡不可见，肠断正西看。','',''),('quantangshi-08605','宴陶家亭子','李白','quantangshi','','卷9','曲巷幽人宅，高门大士家。
池开照胆镜，林吐破颜花。
绿水藏春日，青轩祕晚霞。
若闻弦管妙，金谷不能夸。','',''),('quantangshi-08606','在水军宴韦司马楼船观妓','李白','quantangshi','','卷9','摇曳帆在空，清流顺归风。
诗因鼓吹发，酒为劒歌雄。
对舞青楼妓，双鬟白玉童。
行云且莫去，留醉楚王宫。','',''),('quantangshi-08607','流夜郎至江夏陪长史叔及薛明府宴兴德寺南阁','李白','quantangshi','','卷9','绀殿横江上，青山落镜中。
岸回沙不尽，日暎水成空。
天乐流香阁，莲舟扬晚风。
恭陪竹林宴，留醉与陶公。','',''),('quantangshi-08608','泛沔州城南郎官湖','李白','quantangshi','','卷9','张公多逸兴，共泛沔城隅。
当时秋月好，不减武昌都。
四座醉清光，为欢古来无。
郎官爱此水，因号郎官湖。
风流若未减，名与此山俱。','',''),('quantangshi-08609','陪侍郎叔游洞庭醉后三首 一','李白','quantangshi','','卷9','今日竹林宴，我家贤侍郎。
三杯容小阮，醉后发清狂。','',''),('quantangshi-08610','陪侍郎叔游洞庭醉后三首 二','李白','quantangshi','','卷9','船上齐桡乐，湖心泛月归。
白鸥闲不去，争拂酒筵飞。','',''),('quantangshi-08611','陪侍郎叔游洞庭醉后三首 三','李白','quantangshi','','卷9','刬却君山好，平铺湘水流。
巴陵无限酒，醉杀洞庭秋。','',''),('quantangshi-08612','夜泛洞庭寻裴侍御清酌','李白','quantangshi','','卷9','日晚湘水绿，孤舟无端倪。
明湖涨秋月，独泛巴陵西。
过憩裴逸人，岩居陵丹梯。
抱琴出深竹，为我弹鵾鸡。
曲尽酒亦倾，北窗醉如泥。
人生且行乐，何必组与圭。','',''),('quantangshi-08613','陪族叔刑部侍郎晔及中书贾舍人至游洞庭五首 一','李白','quantangshi','','卷9','洞庭西望楚江分，水尽南天不见云。
日落长沙秋色远，不知何处吊湘君。','',''),('quantangshi-08614','陪族叔刑部侍郎晔及中书贾舍人至游洞庭五首 二','李白','quantangshi','','卷9','南湖秋水夜无烟，耐可乘流直上天。
且就洞庭赊月色，将船买酒白云边。','',''),('quantangshi-08615','陪族叔刑部侍郎晔及中书贾舍人至游洞庭五首 三','李白','quantangshi','','卷9','洛阳才子谪湘川，元礼同舟月下仙。
记得长安还欲笑，不知何处是西天。','',''),('quantangshi-08616','陪族叔刑部侍郎晔及中书贾舍人至游洞庭五首 四','李白','quantangshi','','卷9','洞庭湖西秋月辉，潇湘江北早鸿飞。
醉客满船歌白苎，不知霜露入秋衣。','',''),('quantangshi-08617','陪族叔刑部侍郎晔及中书贾舍人至游洞庭五首 五','李白','quantangshi','','卷9','帝子潇湘去不还，空余秋草洞庭间。
淡扫明湖开玉镜，丹青画出是君山。','',''),('quantangshi-08618','楚江黄龙矶南宴杨执戟治楼','李白','quantangshi','','卷9','五月入五洲，碧山对青楼。
故人杨执戟，春赏楚江流。
一见醉漂月，三杯歌棹讴。
桂枝攀不尽，他日更相求。','',''),('quantangshi-08619','铜官山醉后绝句','李白','quantangshi','','卷9','我爱铜官乐，千年未拟还。
要须回舞袖，拂尽五松山。','',''),('quantangshi-08620','与南陵常赞府游五松山','李白','quantangshi','','卷9','安石泛溟渤，独啸长风还。
逸韵动海上，高情出人间。
灵异可并迹，澹然与世闲。
我来五松下，置酒穷跻攀。
征古绝遗老，因名五松山。
五松何清幽，胜境美沃州。
萧飒鸣洞壑，终年风雨秋。
响入百泉去，听如三峡流。
剪竹扫天花，且从傲吏游。
龙堂若可憩，吾欲归精修。','',''),('quantangshi-08621','宣城青溪','李白','quantangshi','','卷9','青溪胜桐庐，水木有佳色。
山貌日高古，石容天倾侧。
彩鸟昔未名，白猨初相识。
不见同怀人，对之空叹息。','',''),('quantangshi-08622','与谢良辅游泾川陵岩寺','李白','quantangshi','','卷9','乘君素舸泛泾西，宛似云门对若溪。
且从康乐寻山水，何必东游入会稽。','',''),('quantangshi-08623','游水西简郑明府','李白','quantangshi','','卷9','天宫水西寺，云锦照东郭。
清湍鸣回溪，绿水遶飞阁。
凉风日潇洒，幽客时憩泊。
五月思貂裘，谓言秋霜落。
石萝引古蔓，岸笋开新箨。
吟翫空复情，相思尔佳作。
郑公诗人秀，逸韵宏寥廓。
何当一来游，惬我雪山诺。','',''),('quantangshi-08624','九日登山','李白','quantangshi','','卷9','渊明归去来，不与世相逐。
为无杯中物，遂偶本州牧。
因招白衣人，笑酌黄花菊。
我来不得意，虚过重阳时。
题舆何俊发，遂结城南期。
筑土按响山，俯临宛水湄。
胡人呌玉笛，越女弹霜丝。
自作英王胄，斯乐不可窥。
赤鲤涌琴高，白龟道冯夷。
灵仙如彷佛，奠酹遥相知。
古来登高人，今复几人在。
沧洲违宿诺，明日犹可待。
连山似惊波，合沓出溟海。
扬袂挥四座，酩酊安所知。
齐歌送清扬，起舞乱参差。
宾随落叶散，帽逐秋风吹。
别后登此台，愿言长相思。','',''),('quantangshi-08625','九日','李白','quantangshi','','卷9','今日云景好，水绿秋山明。
携壶酌流霞，搴菊泛寒荣。
地远松石古，风扬弦管清。
窥觞照欢颜，独笑还自倾。
落帽醉山月，空歌怀友生。','',''),('quantangshi-08626','九日龙山饮','李白','quantangshi','','卷9','九日龙山饮，黄花笑逐臣。
醉看风落帽，舞爱月留人。','',''),('quantangshi-08627','九月十日即事','李白','quantangshi','','卷9','昨日登高罢，今朝更举觞。
菊花何太苦，遭此两重阳。','',''),('quantangshi-08628','陪族叔当涂宰游化城寺升公清风亭','李白','quantangshi','','卷9','化城若化出，金牓天宫开。
疑是海上云，飞空结楼台。
升公湖上秀，粲然有辩才。
济人不利己，立俗无嫌猜。
了见水中月，青莲出尘埃。
闲居清风亭，左右清风来。
当暑阴广殿，太阳为裴回。
茗酌待幽客，珍盘荐雕梅。
飞文何洒落，万象为之摧。
季父拥鸣琴，德声布云雷。
虽游道林室，亦举陶潜杯。
清乐动诸天，长松自吟哀。
留欢若可尽，劫石乃成灰。','',''),('quantangshi-08629','登锦城散花楼','李白','quantangshi','','卷9','日照锦城头，朝光散花楼。
金窗夹绣户，珠箔悬银钩。
飞梯绿云中，极目散我忧。
暮雨向三峡，春江绕双流。
今来一登望，如上九天游。','',''),('quantangshi-08630','登峨眉山','李白','quantangshi','','卷9','蜀国多仙山，峨眉邈难匹。
周流试登览，绝怪安可息。
青冥倚天开，彩错疑画出。
泠然紫霞赏，果得锦囊术。
云间吟琼箫，石上弄宝瑟。
平生有微尚，欢笑自此毕。
烟容如在颜，尘累忽相失。
傥逢骑羊子，携手凌白日。','',''),('quantangshi-08631','大庭库','李白','quantangshi','','卷9','朝登大庭库，云物何苍然。
莫辨陈郑火，空霾邹鲁烟。
我来寻梓慎，观化入寥天。
古木朔气多，松风如五弦。
帝图终冥没，叹息满山川。','',''),('quantangshi-08632','登单父陶少府半月台','李白','quantangshi','','卷9','陶公有逸兴，不与常人俱。
筑台像半月，回向高城隅。
置酒望白云，商飙起寒梧。
秋山入远海，桑柘罗平芜。
水色渌且明，令人思镜湖。
终当过江去，爱此暂踟蹰。','',''),('quantangshi-08633','天台晓望','李白','quantangshi','','卷9','天台邻四明，华顶高百越。
门标赤城霞，楼栖沧岛月。
凭高登远览，直下见溟渤。
云垂大鹏翻，波动巨鳌没。
风潮争汹涌，神怪何翕忽。
观奇迹无倪，好道心不歇。
攀条摘朱实，服药炼金骨。
安得生羽毛，千春卧蓬阙。','',''),('quantangshi-08634','早望海霞边','李白','quantangshi','','卷9','四明三千里，朝起赤城霞。
日出红光散，分辉照雪厓。
一餐咽琼液，五内发金沙。
举手何所待，青龙白虎车。','',''),('quantangshi-08635','焦山望寥山','李白','quantangshi','','卷9','石壁望松寥，宛然在碧霄。
安得五彩虹，驾天作长桥。
仙人如爱我，举手来相招。','',''),('quantangshi-08636','杜陵绝句','李白','quantangshi','','卷9','南登杜陵上，北望五陵间。
秋水明落日，流光灭远山。','',''),('quantangshi-08637','登太白峰','李白','quantangshi','','卷9','西上太白峯，夕阳穷登攀。
太白与我语，为我开天关。
愿乘泠风去，直出浮云间。
举手可近月，前行若无山。
一别武功去，何时复见还。','',''),('quantangshi-08638','登邯郸洪波台置酒观发兵','李白','quantangshi','','卷9','我把两赤羽，来游燕赵间。
天狼正可射，感激无时闲。
观兵洪波台，倚劒望玉关。
请缨不系越，且向燕然山。
风引龙虎旗，歌钟昔追攀。
击筑落高月，投壶破愁颜。
遥知百战胜，定扫鬼方还。','',''),('quantangshi-08639','登新平楼','李白','quantangshi','','卷9','去国登兹楼，怀归伤暮秋。
天长落日远，水净寒波流。
秦云起岭树，胡雁飞沙洲。
苍苍几万里，目极令人愁。','',''),('quantangshi-08640','谒老君庙','李白','quantangshi','','卷9','先君怀圣德，灵庙肃神心。
草合人踪断，尘浓鸟迹深。
流沙丹竈灭，关路紫烟沈。
独伤千载后，空余松柏林。','',''),('quantangshi-08641','秋日登扬州西灵塔','李白','quantangshi','','卷9','宝塔凌苍苍，登攀览四荒。
顶高元气合，标出海云长。
万象分空界，三天接画梁。
水摇金刹影，日动火珠光。
鸟拂琼帘度，霞连绣栱张。
目随征路断，心逐去帆扬。
露浴梧楸白，霜催橘柚黄。
玉毫如可见，于此照迷方。','',''),('quantangshi-08642','登金陵冶城西北谢安墩','李白','quantangshi','','卷9','晋室昔横溃，永嘉遂南奔。
沙尘何茫茫，龙虎鬬朝昏。
胡马风汉草，天骄蹙中原。
哲匠感颓运，云鹏忽飞翻。
组练照楚国，旌旗连海门。
西秦百万众，戈甲如云屯。
投鞭可填江，一埽不足论。
皇运有返正，丑虏无遗魂。
谈笑遏横流，苍生望斯存。
冶城访古迹，犹有谢安墩。
凭览周地险，高标绝人喧。
想像东山姿，缅怀右军言。
梧桐识嘉树，蕙草留芳根。
白鹭暎春洲，青龙见朝暾。
地古云物在，台倾禾黍繁。
我来酌清波，于此树名园。
功成拂衣去，归入武陵源。','',''),('quantangshi-08643','登瓦官阁','李白','quantangshi','','卷9','晨登瓦官阁，极眺金陵城。
钟山对北户，淮水入南荣。
漫漫雨花落，嘈嘈天乐鸣。
两廊振法鼓，四角吟风筝。
杳出霄汉上，仰攀日月行。
山空霸气灭，地古寒阴生。
寥廓云海晚，苍茫宫观平。
门余阊阖字，楼识凤凰名。
雷作百山动，神扶万栱倾。
灵光何足贵，长此镇吴京。','',''),('quantangshi-08644','登梅冈望金陵赠族侄高座寺僧中孚','李白','quantangshi','','卷9','钟山抱金陵，霸气昔腾发。
天开帝王居，海色照宫阙。
羣峰如逐鹿，奔走相驰突。
江水九道来，云端遥明没。
时迁大运去，龙虎势休歇。
我来属天清，登览穷楚越。
吾宗挺禅伯，特秀鸾凤骨。
众星罗青天，明者独有月。
冥居顺生理，草木不剪伐。
烟窗引蔷薇，石壁老野蕨。
吴风谢安屐，白足傲履韈。
几宿一下山，萧然忘干谒。
谈经演金偈，降鹤舞海雪。
时闻天香来，了与世事绝。
佳游不可得，春风惜远别。
赋诗留岩屏，千载庶不灭。','',''),('quantangshi-08645','登金陵凤凰台','李白','quantangshi','','卷9','凤凰台上凤凰游，凤去台空江自流。
吴宫花草埋幽径，晋代衣冠成古丘。
三山半落青天外，二水中分白鹭洲。
总为浮云能蔽日，长安不见使人愁。','',''),('quantangshi-08646','望庐山瀑布水二首 一','李白','quantangshi','','卷9','西登香炉峰，南见瀑布水。
挂流三百丈，喷壑数十里。
歘如飞电来，隐若白虹起。
初惊河汉落，半洒云天里。
仰观势转雄，壮哉造化功。
海风吹不断，江月照还空。
空中乱潨射，左右洗青壁。
飞珠散轻霞，流沫沸穹石。
而我乐名山，对之心益闲。
无论潄琼液，还得洗尘颜。
且谐宿所好，永愿辞人间。','',''),('quantangshi-08647','望庐山瀑布水二首 二','李白','quantangshi','','卷9','日照香炉生紫烟，遥看瀑布挂前川。
飞流直下三千尺，疑是银河落九天。','',''),('quantangshi-08648','登庐山五老峰','李白','quantangshi','','卷9','庐山东南五老峰，青天削出金芙蓉。
九江秀色可揽结，吾将此地巢云松。','',''),('quantangshi-08649','江上望皖公山','李白','quantangshi','','卷9','奇峰出奇云，秀木含秀气。
清宴皖公山，巉绝称人意。
独游沧江上，终日淡无味。
但爱兹岭高，何由讨灵异。
默然遥相许，欲徃心莫遂。
待吾还丹成，投迹归此地。','',''),('quantangshi-08650','望黄鹤楼','李白','quantangshi','','卷9','东望黄鹤山，雄雄半空出。
四面生白云，中峰倚红日。
岩峦行穹跨，峰嶂亦冥密。
颇闻列仙人，于此学飞术。
一朝向蓬海，千载空石室。
金竈生烟埃，玉潭祕清谧。
地古遗草木，庭寒老芝术。
蹇予羡攀跻，因欲保闲逸。
观奇徧诸岳，兹岭不可匹。
结心寄青松，永悟客情毕。','',''),('quantangshi-08651','鹦鹉洲','李白','quantangshi','','卷9','鹦鹉来过吴江水，江上洲传鹦鹉名。
鹦鹉西飞陇山去，芳洲之树何青青。
烟开兰叶香风暖，岸夹桃花锦浪生。
迁客此时徒极目，长洲孤月向谁明。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-08652','九日登巴陵置酒望洞庭水军','李白','quantangshi','','卷9','九日天气清，登高无秋云。
造化辟川岳，了然楚汉分。
长风鼓横波，合沓蹙龙文。
忆昔传游豫，楼船壮横汾。
今兹讨鲸鲵，旌斾何缤纷。
白羽落酒樽，洞庭罗三军。
黄花不掇手，战鼓遥相闻。
劒舞转颓阳，当时日停曛。
酣歌激壮士，可以摧妖氛。
龌龊东篱下，渊明不足羣。','',''),('quantangshi-08653','秋登巴陵望洞庭','李白','quantangshi','','卷9','清晨登巴陵，周览无不极。
明湖暎天光，彻底见秋色。
秋色何苍然，际海俱澄鲜。
山青灭远树，水绿无寒烟。
来帆出江中，去鸟向日边。
风清长沙浦，山空云梦田。
瞻光惜颓发，阅水悲徂年。
北渚既荡漾，东流自潺湲。
郢人唱白雪，越女歌采莲。
听此更肠断，凭厓泪如泉。','',''),('quantangshi-08654','与夏十二登岳阳楼','李白','quantangshi','','卷9','楼观岳阳尽，川逈洞庭开。
雁引愁心去，山衔好月来。
云间连下榻，天上接行杯。
醉后凉风起，吹人舞袖回。','',''),('quantangshi-08655','登巴陵开元寺西阁赠衡岳僧方外','李白','quantangshi','','卷9','衡岳有阐士，五峯秀真骨。
见君万里心，海水照秋月。
大臣南溟去，问道皆请谒。
洒以甘露言，清凉润肌发。
明湖落天镜，香阁凌银阙。
登眺餐惠风，新花期启发。','',''),('quantangshi-08656','与贾至舍人于龙兴寺剪落梧桐枝望㴩湖','李白','quantangshi','','卷9','剪落青梧枝，㴩湖坐可窥。
雨洗秋山净，林光澹碧滋。
水闲明镜转，云绕画屏移。
千古风流事，名贤共此时。','',''),('quantangshi-08657','挂席江上待月有怀','李白','quantangshi','','卷9','待月月未出，望江江自流。
倏忽城西郭，青天悬玉钩。
素华虽可揽，清景不可游。
耿耿金波里，空瞻鳷鹊楼。','',''),('quantangshi-08658','金陵望汉江','李白','quantangshi','','卷9','汉江回万里，派作九龙盘。
横溃豁中国，崔嵬飞迅湍。
六帝沦亡后，三吴不足观。
我君混区宇，垂拱众流安。
今日任公子，沧浪罢钓竿。','',''),('quantangshi-08659','秋登宣城谢朓北楼','李白','quantangshi','','卷9','江城如画里，山晓望晴空。
两水夹明镜，双桥落彩虹。
人烟寒橘柚，秋色老梧桐。
谁念北楼上，临风怀谢公。','',''),('quantangshi-08660','望天门山','李白','quantangshi','','卷9','天门中断楚江开，碧水东流至北回。
两岸青山相对出，孤帆一片日边来。','',''),('quantangshi-08661','望木瓜山','李白','quantangshi','','卷9','早起见日出，暮见栖鸟还。
客心自酸楚，况对木瓜山。','',''),('quantangshi-08662','登敬亭北二小山余时送客逢崔侍御并登此地','李白','quantangshi','','卷9','送客谢亭北，逢君纵酒还。
屈盘戏白马，大笑上青山。
回鞭指长安，西日落秦关。
帝乡三千里，杳在碧云间。','',''),('quantangshi-08663','过崔八丈水亭','李白','quantangshi','','卷9','高阁横秀气，清幽并在君。
檐飞宛溪水，窗落敬亭云。
猨啸风中断，渔歌月里闻。
闲随白鸥去，沙上自为羣。','',''),('quantangshi-08664','登广武古战场怀古','李白','quantangshi','','卷9','秦鹿奔野草，逐之若飞蓬。
项王气盖世，紫电明双瞳。
呼吸八千人，横行起江东。
赤精斩白帝，叱咤入关中。
两龙不并跃，五纬与天同。
楚灭无英图，汉兴有成功。
按劒清八极，归酣歌大风。
伊昔临广武，连兵决雌雄。
分我一杯羹，太皇乃汝翁。
战争有古迹，壁垒颓层穹。
猛虎啸洞壑，饥鹰鸣秋空。
翔云列晓阵，杀气赫长虹。
拨乱属豪圣，俗儒安可通。
沈湎呼竖子，狂言非至公。
抚掌黄河曲，嗤嗤阮嗣宗。','',''),('quantangshi-08665','安州应城玉女汤作','李白','quantangshi','','卷9','神女殁幽境，汤池流大川。
阴阳结炎炭，造化开灵泉。
地底烁朱火，沙傍歊素烟。
沸珠跃明月，皎镜函空天。
气浮兰芳满，色涨桃花然。
精览万殊入，潜行七泽连。
愈疾功莫尚，变盈道乃全。
濯濯气清泚，曦发弄潺湲。
散下楚王国，分浇宋玉田。
可以奉巡幸，奈何隔穷偏。
独随朝宗水，赴海输微涓。','',''),('quantangshi-08666','之广陵宿常二南郭幽居','李白','quantangshi','','卷9','绿水接柴门，有如桃花源。
忘忧或假草，满院罗丛萱。
[暝]色湖上来，微雨飞南轩。
故人宿茅宇，夕鸟栖杨园。
还惜诗酒别，深为江海言。
明朝广陵道，独忆此倾樽。','',''),('quantangshi-08667','夜下征虏亭','李白','quantangshi','','卷9','船下广陵去，月明征虏亭。
山花如绣颊，江火似流萤。','',''),('quantangshi-08668','下途归石门旧居','李白','quantangshi','','卷9','吴山高，越水清，握手无言伤别情。
将欲辞君挂帆去，离魂不散烟郊树。
此心郁怅谁能论，有愧叨承国士恩。
云物共倾三月酒，岁时同饯五侯门。
羡君素书尝满案，含丹照白霞色烂。
余尝学道穷冥筌，梦中往往游仙山。
何当脱屣谢时去，壶中别有日月天。
俛仰人间易凋朽，钟峰五云在轩牖。
惜别愁窥玉女窗，归来笑把洪厓手。
隐居寺，隐居山，陶公炼液栖其间。
灵神闭气昔登攀，恬然但觉心绪闲。
数人不知几甲子，昨夜犹带冰霜颜。
我离虽则岁物改，如今了然失所在。
别君莫道不尽欢，悬知乐客遥相待。
石门流水徧桃花，我亦曾到秦人家。
不知何处得鸡豕，就中仍见繁桑麻。
翛然远与世事间，装鸾驾鹤又复远。
何必长从七贵游，劳生徒聚万金产。
挹君去，长相思，云游雨散从此辞。
欲知怅别心易苦，向暮春风杨柳丝。','',''),('quantangshi-08669','客中行','李白','quantangshi','','卷9','兰陵美酒郁金香，玉椀盛来琥珀光。
但使主人能醉客，不知何处是他乡。','',''),('quantangshi-08670','太原早秋','李白','quantangshi','','卷9','岁落众芳歇，时当大火流。
霜威出塞早，云色渡河秋。
梦绕边城月，心飞故国楼。
思归若汾水，无日不悠悠。','',''),('quantangshi-08671','奔亡道中五首 一','李白','quantangshi','','卷9','苏武天山上，田横海岛边。
万重关塞断，何日是归年。','',''),('quantangshi-08672','奔亡道中五首 二','李白','quantangshi','','卷9','亭伯去安在，李陵降未归。
愁容变海色，短服改胡衣。','',''),('quantangshi-08673','奔亡道中五首 三','李白','quantangshi','','卷9','谈笑三军却，交游七贵疎。
仍留一只箭，未射鲁连书。','',''),('quantangshi-08674','奔亡道中五首 四','李白','quantangshi','','卷9','函谷如玉关，几时可生还。
洛阳为易水，嵩岳是燕山。
俗变羗胡语，人多沙塞颜。
申包惟恸哭，七日鬓毛斑。','',''),('quantangshi-08675','奔亡道中五首 五','李白','quantangshi','','卷9','淼淼望湖水，青青芦叶齐。
归心落何处，日没大江西。
歇马傍春草，欲行远道迷。
谁忍子规鸟，连声向我啼。','',''),('quantangshi-08676','郢门秋怀','李白','quantangshi','','卷9','郢门一为客，巴月三成弦。
朔风正摇落，行子愁归旋。
杳杳山外日，茫茫江上天。
人迷洞庭水，雁度潇湘烟。
清旷谐宿好，缁磷及此年。
百龄何荡漾，万化相推迁。
空谒苍梧帝，徒寻溟海仙。
已闻蓬海浅，岂见三桃圆。
倚劒增浩叹，扪襟还自怜。
终当游五湖，濯足沧浪泉。','',''),('quantangshi-08677','至鸭栏驿上白马矶赠裴侍御','李白','quantangshi','','卷9','侧叠万古石，横为白马矶。
乱流若电转，举棹扬珠辉。
临驿卷缇幕，升堂接绣衣。
情亲不避马，为我解霜威。','',''),('quantangshi-08678','荆门浮舟望蜀江','李白','quantangshi','','卷9','春水月峡来，浮舟望安极。
正是桃花流，依然锦江色。
江色绿且明，茫茫与天平。
逶迤巴山尽，摇曳楚云行。
雪照聚沙雁，花飞出谷莺。
芳洲却已转，碧树森森迎。
流目浦烟夕，扬帆海月生。
江陵识遥火，应到渚宫城。','',''),('quantangshi-08679','上三峡','李白','quantangshi','','卷9','巫山夹青天，巴水流若兹。
巴水忽可尽，青天无到时。
三朝上黄牛，三暮行太迟。
三朝又三暮，不觉鬓成丝。','',''),('quantangshi-08680','自巴东舟行经瞿唐峡登巫山最高峰晚还题壁','李白','quantangshi','','卷9','江行几千里，海月十五圆。
始经瞿唐峡，遂步巫山巅。
巫山高不穷，巴国尽所历。
日边攀垂萝，霞外倚穹石。
飞步凌绝顶，极目无纤烟。
却顾失舟壑，仰观临青天。
青天若可扪，银汉去安在。
望云知苍梧，记水辨瀛海。
周游孤光晚，历览幽意多。
积雪照空谷，悲风鸣森柯。
归途行欲曛，佳趣尚未歇。
江寒早啼猨，松暝已吐月。
月色何悠悠，清猨响啾啾。
辞山不忍听，挥策还孤舟。','',''),('quantangshi-08681','早发白帝城','李白','quantangshi','','卷9','朝辞白帝彩云间，千里江陵一日还。
两岸猨声啼不尽，轻舟已过万重山。','',''),('quantangshi-08682','秋下荆门','李白','quantangshi','','卷9','霜落荆门江树空，布帆无恙挂秋风。
此行不为鲈鱼鲙，自爱名山入剡中。','',''),('quantangshi-08683','江行寄远','李白','quantangshi','','卷9','刳木出吴楚，危槎百余尺。
疾风吹片帆，日暮千里隔。
别时酒犹在，已为异乡客。
思君不可得，愁见江水碧。','',''),('quantangshi-08684','宿五松山下荀媪家','李白','quantangshi','','卷9','我宿五松下，寂寥无所欢。
田家秋作苦，邻女夜舂寒。
跪进雕胡饭，月光明素盘。
令人惭漂母，三谢不能餐。','',''),('quantangshi-08685','下泾县陵阳溪至澁滩','李白','quantangshi','','卷9','澁滩鸣嘈嘈，两山足猨猱。
白波若卷雪，侧足不容舠。
渔子与舟人，撑折万张篙。','',''),('quantangshi-08686','下陵阳沿高溪三门六剌滩','李白','quantangshi','','卷9','三门横峻滩，六剌走波澜。
石惊虎伏起，水状龙萦盘。
何慙七里濑，使我欲垂竿。','',''),('quantangshi-08687','夜泊黄山闻殷十四吴吟','李白','quantangshi','','卷9','昨夜谁为吴会吟，风生万壑振空林。
龙惊不敢水中卧，猨啸时闻岩下音。
我宿黄山碧溪月，听之却罢松间琴。
朝来果是沧洲逸，酤酒醍盘饭霜栗。
半酣更发江海声，客愁顿向杯中失。','',''),('quantangshi-08688','宿鰕湖','李白','quantangshi','','卷9','鸡鸣发黄山，暝投鰕湖宿。
白雨暎寒山，森森似银竹。
提携采铅客，结荷水边沐。
半夜四天开，星河烂人目。
明晨大楼去，冈陇多屈伏。
当与持斧翁，前溪伐云木。','',''),('quantangshi-08689','西施','李白','quantangshi','','卷9','西施越溪女，出自苎萝山。
秀色掩今古，荷花羞玉颜。
浣纱弄碧水，自与清波闲。
皓齿信难开，沈吟碧云间。
句践征绝艳，扬蛾入吴关。
提携馆娃宫，杳渺讵可攀。
一破夫差国，千秋竟不还。','',''),('quantangshi-08690','王右军','李白','quantangshi','','卷9','右军本清真，潇洒出风尘。
山阴过羽客，爱此好鹅宾。
扫素写道经，笔精妙入神。
书罢笼鹅去，何曾别主人。','',''),('quantangshi-08691','上元夫人','李白','quantangshi','','卷9','上元谁夫人，偏得王母娇。
嵯峨三角髻，余发散垂腰。
裘披青毛锦，身着赤霜袍。
手提嬴女儿，闲与凤吹箫。
眉语两自笑，忽然随风飘。','',''),('quantangshi-08692','苏台览古','李白','quantangshi','','卷9','旧苑荒台杨柳新，菱歌清唱不胜春。
只今惟有西江月，曾照吴王宫里人。','',''),('quantangshi-08693','越中览古','李白','quantangshi','','卷9','越王句践破吴归，义士还乡尽锦衣。
宫女如花满春殿，只今惟有鹧鸪飞。','',''),('quantangshi-08694','商山四皓','李白','quantangshi','','卷9','白发四老人，昂藏南山侧。
偃卧松雪间，冥翳不可识。
云窗拂青霭，石壁横翠色。
龙虎方战争，于焉自休息。
秦人失金镜，汉祖升紫极。
阴虹浊太阳，前星遂沦匿。
一行佐明圣，倏起生羽翼。
功成身不居，舒卷在胸臆。
窅冥合元化，茫昧信难测。
飞声塞天衢，万古仰遗则。','',''),('quantangshi-08695','过四皓墓','李白','quantangshi','','卷9','我行至商洛，幽独访神仙。
园绮复安在，云萝尚宛然。
荒凉千古迹，芜没四坟连。
伊昔炼金鼎，何年闭玉泉。
陇寒惟有月，松古渐无烟。
木魅风号去，山精雨啸旋。
紫芝高咏罢，青史旧名传。
今日并如此，哀哉信可怜。','',''),('quantangshi-08696','岘山怀古','李白','quantangshi','','卷9','访古登岘首，凭高眺襄中。
天清远峰出，水落寒沙空。
弄珠见游女，醉酒怀山公。
感叹发秋兴，长松鸣夜风。','',''),('quantangshi-08697','苏武','李白','quantangshi','','卷9','苏武在匈奴，十年持汉节。
白雁上林飞，空传一书札。
牧羊边地苦，落日归心绝。
渴饮月窟冰，肌餐天上雪。
东还沙塞远，北怆河梁别。
泣把李陵衣，相看泪成血。','',''),('quantangshi-08698','经下邳圯桥怀张子房','李白','quantangshi','','卷9','子房未虎啸，破产不为家。
沧海得壮士，椎秦博浪沙。
报韩虽不成，天地皆振动。
潜匿游下邳，岂曰非智勇。
我来圯桥上，怀古钦英风。
惟见碧流水，曾无黄石公。
叹息此人去，萧条徐泗空。','',''),('quantangshi-08699','金陵三首 一','李白','quantangshi','','卷9','晋家南渡日，此地旧长安。
地即帝王宅，山为龙虎盘。
金陵空壮观，天堑净波澜。
醉客回桡去，吴歌且自欢。','',''),('quantangshi-08700','金陵三首 二','李白','quantangshi','','卷9','地拥金陵势，城回江水流。
当时百万户，夹道起朱楼。
亡国生春草，离宫没古丘。
空余后湖月，波上对江州。','',''),('quantangshi-08701','金陵三首 三','李白','quantangshi','','卷9','六代兴亡国，三杯为尔歌。
苑方秦地少，山似洛阳多。
古殿吴花草，深宫晋绮罗。
并随人事灭，东逝与沧波。','',''),('quantangshi-08702','秋夜板桥浦泛月独酌怀谢朓','李白','quantangshi','','卷9','天上何所有，迢迢白玉绳。
斜低建章阙，耿耿对金陵。
汉水旧如练，霜江夜清澄。
长川泻落月，洲渚晓寒凝。
独酌板桥浦，古人谁可征。
玄晖难再得，洒酒气填膺。','',''),('quantangshi-08703','入彭蠡经松门观石镜缅怀谢康乐题诗书游览之志','李白','quantangshi','','卷9','谢公之彭蠡，因此游松门。
余方窥石镜，兼得穷江源。
将欲继风雅，岂徒清心魂。
前赏逾所见，后来道空存。
况属临泛美，而无洲渚喧。
漾水向东去，漳流直南奔。
空蒙三川夕，回合千里昏。
青桂隐遥月，绿枫鸣愁猨。
水碧或可采，金精祕莫论。
吾将学仙去，冀与琴高言。','',''),('quantangshi-08704','庐江主人妇','李白','quantangshi','','卷9','孔雀东飞何处栖，庐江小吏仲卿妻。
为客裁缝君自见，城乌独宿夜空啼。','',''),('quantangshi-08705','陪宋中丞武昌夜饮怀古','李白','quantangshi','','卷9','清景南楼夜，风流在武昌。
庾公爱秋月，乘兴坐胡牀。
龙笛吟寒水，天河落晓霜。
我心还不浅，怀古醉余觞。','',''),('quantangshi-08706','望鹦鹉洲怀禰衡','李白','quantangshi','','卷9','魏帝营八极，蚁观一禰衡。
黄祖斗筲人，杀之受恶名。
吴江赋鹦鹉，落笔超羣英。
锵锵振金玉，句句欲飞鸣。
鸷鹗啄孤凤，千春伤我情。
五岳起方寸，隐然讵可平。
才高竟何施，寡识冒天刑。
至今芳洲上，兰蕙不忍生。','',''),('quantangshi-08707','宿巫山下','李白','quantangshi','','卷9','昨夜巫山下，猨声梦里长。
桃花飞绿水，三月下瞿塘。
雨色风吹去，南行拂楚王。
高丘怀宋玉，访古一霑裳。','',''),('quantangshi-08708','金陵白杨十字巷','李白','quantangshi','','卷9','白杨十字巷，北夹湖沟道。
不见吴时人，空生唐年草。
天地有反覆，宫城尽倾倒。
六帝余古丘，樵苏泣遗老。','',''),('quantangshi-08709','谢公亭','李白','quantangshi','','卷9','谢公离别处，风景每生愁。
客散青天月，山空碧水流。
池花春暎日，窗竹夜鸣秋。
今古一相接，长歌怀旧游。','',''),('quantangshi-08710','纪南陵题五松山','李白','quantangshi','','卷9','圣达有去就，潜光愚其德。
鱼与龙同池，龙去鱼不测。
当时版筑辈，岂知傅说情。
一朝和殷羹，光气为列星。
伊尹生空桑，捐庖佐皇极。
桐宫放太甲，摄政无愧色。
三年帝道明，委质终辅翼。
旷哉至人心，万古可为则。
时命或大缪，仲尼将奈何。
鸾凤忽覆巢，麒麟不来过。
龟山蔽鲁国，有斧且无柯。
归来归去来，宵济越洪波。','',''),('quantangshi-08711','夜泊牛渚怀古','李白','quantangshi','','卷9','牛渚西江夜，青天无片云。
登舟望秋月，空忆谢将军。
余亦能高咏，斯人不可闻。
明朝挂帆席，枫叶落纷纷。','',''),('quantangshi-08712','姑孰十咏 姑孰溪','李白','quantangshi','','卷9','爱此溪水闲，乘流兴无极。
漾楫怕鸥惊，垂竿待鱼食。
波飜晓霞影，岸叠春山色。
何处浣纱人，红颜未相识。','',''),('quantangshi-08713','姑孰十咏 丹阳湖','李白','quantangshi','','卷9','湖与元气连，风波浩难止。
天外贾客归，云间片帆起。
龟游莲叶上，鸟宿芦花里。
少女棹归舟，歌声逐流水。','',''),('quantangshi-08714','姑孰十咏 谢公宅','李白','quantangshi','','卷9','青山日将暝，寂寞谢公宅。
竹里无人声，池中虚月白。
荒庭衰草徧，废井苍苔积。
惟有清风闲，时时起泉石。','',''),('quantangshi-08715','姑孰十咏 陵歊台','李白','quantangshi','','卷9','旷望登古台，台高极人目。
叠嶂列远空，杂花间平陆。
闲云入窗牖，野翠生松竹。
欲览碑上文，苔侵岂堪读。','',''),('quantangshi-08716','姑孰十咏 桓公井','李白','quantangshi','','卷9','桓公名已古，废井曾未竭。
石甃冷苍苔，寒泉湛孤月。
秋来桐暂落，春至桃还发。
路远人罕窥，谁能见清彻。','',''),('quantangshi-08717','姑孰十咏 慈姥竹','李白','quantangshi','','卷9','野竹攒石生，含烟暎江岛。
翠色落波深，虚声带寒早。
龙吟曾未听，凤曲吹应好。
不学蒲柳凋，贞心尝自保。','',''),('quantangshi-08718','姑孰十咏 望夫山','李白','quantangshi','','卷9','颙望临碧空，怨情感离别。
江草不知愁，岩花但争发。
云山万重隔，音信千里绝。
春去秋复来，相思几时歇。','',''),('quantangshi-08719','姑孰十咏 牛渚矶','李白','quantangshi','','卷9','绝壁临巨川，连峰势相向。
乱石流洑间，回波自成浪。
但惊羣木秀，莫测精灵状。
更听猨夜啼，忧心醉江上。','',''),('quantangshi-08720','姑孰十咏 灵墟山','李白','quantangshi','','卷9','丁令辞世人，拂衣向仙路。
伏炼九丹成，方随五云去。
松萝蔽幽洞，桃杏深隐处。
不知曾化鹤，辽海归几度。','',''),('quantangshi-08721','姑孰十咏 天门山','李白','quantangshi','','卷9','逈出江山上，双峰自相对。
岸暎松色寒，石分浪花碎。
参差远天际，缥缈晴霞外。
落日舟去遥，回首沈青霭。','',''),('quantangshi-08722','与元丹丘方城寺谈玄作','李白','quantangshi','','卷9','茫茫大梦中，惟我独先觉。
腾转风火来，假合作容貌。
灭除昏疑尽，领略入精要。
澄虑观此身，因得通寂照。
朗悟前后际，始知金仙妙。
幸逢禅居人，酌玉坐相召。
彼我俱若丧，云山岂殊调。
清风生虚空，明月见谈笑。
怡然青莲宫，永愿姿游眺。','',''),('quantangshi-08723','寻高凤石门山中元丹丘','李白','quantangshi','','卷9','寻幽无前期，乘兴不觉远。
苍厓渺难涉，白日忽欲晚。
未穷三四山，已历千万转。
寂寂闻猨愁，行行见云收。
高松来好月，空谷宜清秋。
溪深古雪在，石断寒泉流。
峰峦秀中天，登眺不可尽。
丹丘遥相呼，顾我忽而哂。
遂造穷谷间，始知静者闲。
留欢达永夜，清晓方言还。','',''),('quantangshi-08724','安州般若水阁纳凉喜遇薛员外乂','李白','quantangshi','','卷9','翛然金园赏，远近含晴光。
楼台成海气，草木皆天香。
忽逢青云士，共解丹霞裳。
水退池上热，风生松下凉。
吞讨破万象，搴窥临众芳。
而我遗有漏，与君用无方。
心垢都已灭，永言题禅房。','',''),('quantangshi-08725','鲁中都东楼醉起作','李白','quantangshi','','卷9','昨日东楼醉，还应倒接䍦。
阿谁扶上马，不省下楼时。','',''),('quantangshi-08726','对酒醉题屈突明府厅','李白','quantangshi','','卷9','陶令八十日，长歌归去来。
故人建昌宰，借问几时回。
风落吴江雪，纷纷入酒杯。
山翁今已醉，舞袖为君开。','',''),('quantangshi-08727','月下独酌四首 一','李白','quantangshi','','卷9','花间一壶酒，独酌无相亲。
举杯邀明月，对影成三人。
月既不解饮，影徒随我身。
暂伴月将影，行乐须及春。
我歌月裴回，我舞影零乱。
醒时同交欢，醉后各分散。
永结无情游，相期邈云汉。','',''),('quantangshi-08728','月下独酌四首 二','李白','quantangshi','','卷9','天若不爱酒，酒星不在天。
地若不爱酒，地应无酒泉。
天地既爱酒，爱酒不愧天。
已闻清比圣，复道浊如贤。
贤圣既已饮，何必求神仙。
三杯通大道，一斗合自然。
但得酒中趣，勿为醒者传。','',''),('quantangshi-08729','月下独酌四首 三','李白','quantangshi','','卷9','三月咸阳城，千花昼如锦。
谁能春独愁，对此径须饮。
穷通与修短，造化夙所禀。
一樽齐死生，万事固难审。
醉后失天地，兀然就孤枕。
不知有吾身，此乐最为甚。','',''),('quantangshi-08730','月下独酌四首 四','李白','quantangshi','','卷9','穷愁千万端，美酒三百杯。
愁多酒虽少，酒倾愁不来。
所以知酒圣，酒酣心自开。
辞粟卧首阳，屡空饥颜回。
当代不乐饮，虚名安用哉。
蟹螯即金液，糟丘是蓬莱。
且须饮美酒，乘月醉高台。','',''),('quantangshi-08731','春归终南山松龛旧隐','李白','quantangshi','','卷9','我来南山阳，事事不异昔。
却寻溪中水，还望岩下石。
蔷薇缘东窗，女萝遶北壁。
别来能几日，草木长数尺。
且复命酒樽，独酌陶永夕。','',''),('quantangshi-08732','冬夜醉宿龙门觉起言志','李白','quantangshi','','卷9','醉来脱宝劒，旅憩高堂眠。
中夜忽惊觉，起立明灯前。
开轩聊直望，晓雪河冰壮。
哀哀歌苦寒，郁郁独惆怅。
傅说版筑臣，李斯鹰犬人。
歘起匡社稷，宁复长艰辛。
而我胡为者，叹息龙门下。
富贵未可期，殷忧向谁写。
去去泪满襟，举声梁甫吟。
青云当自致，何必求知音。','',''),('quantangshi-08733','寻山僧不遇作','李白','quantangshi','','卷9','石径入丹壑，松门闭青苔。
闲阶有鸟迹，禅室无人开。
窥窗见白拂，挂壁生尘埃。
使我空叹息，欲去仍裴回。
香云徧山起，花雨从天来。
已有空乐好，况闻青猨哀。
了然绝世事，此地方悠哉。','',''),('quantangshi-08734','过汪氏别业二首 一','李白','quantangshi','','卷9','游山谁可游，子明与浮丘。
叠岭碍河汉，连峰横斗牛。
汪生面北阜，池馆清且幽。
我来感意气，捶炮列珍羞。
扫石待归月，开池涨寒流。
酒酣益爽气，为乐不知秋。','',''),('quantangshi-08735','过汪氏别业二首 二','李白','quantangshi','','卷9','畴昔未识君，知君好贤才。
随山起馆宇，凿石营池台。
星火五月中，景风从南来。
数枝石榴发，一丈荷花开。
恨不当此时，相过醉金罍。
我行值木落，月苦清猨哀。
永夜达五更，吴歈送琼杯。
酒酣欲起舞，四座歌相催。
日出远海明，轩车且裴回。
更游龙潭去，枕石拂莓苔。','',''),('quantangshi-08736','待酒不至','李白','quantangshi','','卷9','玉壶系青丝，沽酒来何迟。
山花向我笑，正好衔杯时。
晚酌东窗下，流莺复在兹。
春风与醉客，今日乃相宜。','',''),('quantangshi-08737','独酌','李白','quantangshi','','卷9','春草如有意，罗生玉堂阴。
东风吹愁来，白发坐相侵。
独酌劝孤影，闲歌面芳林。
长松尔何知，萧瑟为谁吟。
手舞石上月，膝横花间琴。
过此一壶外，悠悠非我心。','',''),('quantangshi-08738','友人会宿','李白','quantangshi','','卷9','涤荡千古愁，留连百壶饮。
良宵宜清谈，皓月未能寝。
醉来卧空山，天地即衾枕。','',''),('quantangshi-08739','春日独酌二首 一','李白','quantangshi','','卷9','东风扇淑气，水木荣春晖。
白日照绿草，落花散且飞。
孤云还空山，众鸟各已归。
彼物皆有托，吾生独无依。
对此石上月，长醉歌芳菲。','',''),('quantangshi-08740','春日独酌二首 二','李白','quantangshi','','卷9','我有紫霞想，缅怀沧洲间。
思对一壶酒，澹然万事闲。
横琴倚高松，把酒望远山。
长空去鸟没，落日孤云还。
但恐光景晚，宿昔成秋颜。','',''),('quantangshi-08741','金陵江上遇蓬池隐者','李白','quantangshi','','卷9','心爱名山游，身随名山远。
罗浮麻姑台，此去或未返。
遇君蓬池隐，就我石上饭。
空言不成欢，强笑惜日晚。
绿水向雁门，黄云蔽龙山。
叹息两客鸟，裴回吴越间。
共语一执手，留连夜将久。
解我紫绮裘，且换金陵酒。
酒来笑复歌，兴酣乐事多。
水影弄月色，清光奈愁何。
明晨挂帆席，离恨满沧波。','',''),('quantangshi-08742','月夜听卢子顺弹琴','李白','quantangshi','','卷9','闲坐夜明月，幽人弹素琴。
忽闻悲风调，宛若寒松吟。
白雪乱纤手，绿水清虚心。
钟期久已没，世上无知音。','',''),('quantangshi-08743','清溪半夜闻笛','李白','quantangshi','','卷9','羗笛梅花引，吴溪陇水情。
寒山秋浦月，肠断玉关声。','',''),('quantangshi-08744','日夕山中忽然有怀','李白','quantangshi','','卷9','久卧青山云，遂为青山客。
山深云更好，赏弄终日夕。
月衔楼间峰，泉潄阶下石。
素心自此得，真趣非外惜。
鼯啼桂方秋，风灭籁归寂。
缅思洪厓术，欲往沧海隔。
云车来何迟，抚几空叹息。','',''),('quantangshi-08745','夏日山中','李白','quantangshi','','卷9','嬾摇白羽扇，躶体青林中。
脱巾挂石壁，露顶洒松风。','',''),('quantangshi-08746','山中与幽人对酌','李白','quantangshi','','卷9','两人对酌山花开，一杯一杯复一杯。
我醉欲眠卿且去，明朝有意抱琴来。','',''),('quantangshi-08747','春日醉起言志','李白','quantangshi','','卷9','处世若大梦，胡为劳其生。
所以终日醉，颓然卧前楹。
觉来盼庭前，一鸟花间鸣。
借问此何时，春风语流莺。
感之欲叹息，对酒还自倾。
浩歌待明月，曲尽已忘情。','',''),('quantangshi-08748','庐山东林寺夜怀','李白','quantangshi','','卷9','我寻青莲宇，独往谢城阙。
霜清东林钟，水白虎溪月。
天香生虚空，天乐鸣不歇。
宴坐寂不动，大千入毫发。
湛然冥真心，旷劫断出没。','',''),('quantangshi-08749','寻雍尊师隐居','李白','quantangshi','','卷9','羣峭碧摩天，逍遥不记年。
拨云寻古道，倚石听流泉。
花暖青牛卧，松高白鹤眠。
语来江色暮，独自下寒烟。','',''),('quantangshi-08750','与史郎中钦听黄鹤楼上吹笛','李白','quantangshi','','卷9','一为迁客去长沙，西望长安不见家。
黄鹤楼中吹玉笛，江城五月落梅花。','',''),('quantangshi-08751','对酒','李白','quantangshi','','卷9','劝君莫拒杯，春风笑人来。
桃李如旧识，倾花向我开。
流莺啼碧树，明月窥金罍。
昨日朱颜子，今日白发催。
棘生石虎殿，鹿走姑苏台。
自古帝王宅，城阙闭黄埃。','',''),('quantangshi-08752','醉题王汉阳厅','李白','quantangshi','','卷9','我似鹧鸪鸟，南迁嬾北飞。
时寻汉阳令，取醉月中归。','',''),('quantangshi-08753','嘲王历阳不肯饮酒','李白','quantangshi','','卷9','地白风色寒，雪花大如手。
笑杀陶渊明，不饮杯中酒。
浪抚一张琴，虚栽五株柳。
空负头上巾，吾于尔何有。','',''),('quantangshi-08754','独坐敬亭山','李白','quantangshi','','卷9','众鸟高飞尽，孤云独去闲。
相看两不厌，只有敬亭山。','',''),('quantangshi-08755','自遣','李白','quantangshi','','卷9','对酒不觉暝，落花盈我衣。
醉起步溪月，鸟还人亦稀。','',''),('quantangshi-08756','访戴天山道士不遇','李白','quantangshi','','卷9','犬吠水声中，桃花带雨浓。
树深时见鹿，溪午不闻钟。
野竹分青霭，飞泉挂碧峰。
无人知所去，愁倚两三松。','',''),('quantangshi-08757','秋日与张少府楚城韦公藏书高斋作','李白','quantangshi','','卷9','日下空庭暮，城荒古迹余。
地形连海尽，天影落江虚。
旧赏人虽隔，新知乐未疎。
彩云思作赋，丹壁间藏书。
楂拥随流叶，萍开出水鱼。
夕来秋兴满，回首意何如。','',''),('quantangshi-08758','秋夜独坐怀故山','李白','quantangshi','','卷9','小隐慕安石，远游学屈平。
天书访江海，云卧起咸京。
入侍瑶池宴，出陪玉辇行。
夸胡新赋作，谏猎短书成。
但奉紫霄顾，非邀青史名。
庄周空说劒，墨翟耻论兵。
拙薄遂疎绝，归闲事耦耕。
顾无苍生望，空爱紫芝荣。
寥落暝霞色，微茫旧壑情。
秋山绿萝月，今夕为谁明。','',''),('quantangshi-08759','忆崔郎中宗之游南阳遗吾孔子琴抚之潸然感旧','李白','quantangshi','','卷9','昔在南阳城，唯餐独山蕨。
忆与崔宗之，白水弄素月。
时过菊潭上，纵酒无休歇。
泛此黄金花，颓然清歌发。
一朝摧玉树，生死殊飘忽。
留我孔子琴，琴存人已殁。
谁传广陵散，但哭邙山骨。
泉户何时明，长扫狐兔窟。','',''),('quantangshi-08760','忆东山二首 一','李白','quantangshi','','卷9','不向东山久，蔷薇几度花。
白云还自散，明月落谁家。','',''),('quantangshi-08761','忆东山二首 二','李白','quantangshi','','卷9','我今携谢妓，长啸绝人羣。
欲报东山客，开关扫白云。','',''),('quantangshi-08762','望月有怀','李白','quantangshi','','卷9','清泉暎疎松，不知几千古。
寒月摇清波，流光入窗户。
对此空长吟，思君意何深。
无因见安道，兴尽愁人心。','',''),('quantangshi-08763','对酒忆贺监二首 一','李白','quantangshi','','卷9','四明有狂客，风流贺季真。
长安一相见，呼我谪仙人。
昔好杯中物，翻为松下尘。
金龟换酒处，却忆泪沾巾。','',''),('quantangshi-08764','对酒忆贺监二首 二','李白','quantangshi','','卷9','狂客归四明，山阴道士迎。
敕赐镜湖水，为君台沼荣。
人亡余故宅，空有荷花生。
念此杳如梦，凄然伤我情。','',''),('quantangshi-08765','重忆一首','李白','quantangshi','','卷9','欲向江东去，定将谁举杯。
稽山无贺老，却棹酒船回。','',''),('quantangshi-08766','春滞沅湘有怀山中','李白','quantangshi','','卷9','沅湘春色还，风暖烟草绿。
古之伤心人，于此肠断续。
予非怀沙客，但美采菱曲。
所愿归东山，寸心于此足。','',''),('quantangshi-08767','落日忆山中','李白','quantangshi','','卷9','雨后烟景绿，晴天散余霞。
东风随春归，发我枝上花。
花落时欲暮，见此令人嗟。
愿游名山去，学道飞丹砂。','',''),('quantangshi-08768','忆秋浦桃花旧游时窜夜郎','李白','quantangshi','','卷9','桃花春水生，白石今出没。
摇荡女萝枝，半摇青天月。
不知旧行径，初拳几枝蕨。
三载夜郎还，于兹炼金骨。','',''),('quantangshi-08769','越中秋怀','李白','quantangshi','','卷9','越水遶碧山，周回数千里。
乃是天镜中，分明画相似。
爱此从冥搜，永怀临湍游。
一为沧波客，十见红蕖秋。
观涛壮天险，望海令人愁。
路遐迫西照，岁晚悲东流。
何必探禹穴，逝将归蓬丘。
不然五湖上，亦可乘扁舟。','',''),('quantangshi-08770','效古二首 一','李白','quantangshi','','卷9','朝入天苑中，谒帝蓬莱宫。
青山映辇道，碧树摇苍空。
谬题金闺籍，得与银台通。
待诏奉明主，抽毫颂清风。
归时落日晚，躞蹀浮云骢。
人马本无意，飞驰自豪雄。
入门紫鸳鸯，金井双梧桐。
清歌弦古曲，美酒沽新丰。
快意且为乐，列筵坐羣公。
光景不可留，生世如转蓬。
早达胜晚遇，羞比垂钓翁。','',''),('quantangshi-08771','效古二首 二','李白','quantangshi','','卷9','自古有秀色，西施与东邻。
蛾眉不可妬，况乃效其矉。
所以尹婕妤，羞见邢夫人。
低头不出气，塞默少精神。
寄语无盐子，如君何足珍。','',''),('quantangshi-08772','拟古十二首 一','李白','quantangshi','','卷9','青天何历历，明星如白石。
黄姑与织女，相去不盈尺。
银河无鹊桥，非时将安适。
闺人理纨素，游子悲行役。
瓶冰知冬寒，霜露欺远客。
客似秋叶飞，飘颻不言归。
别后罗带长，愁宽去时衣。
乘月托宵梦，因之寄金徽。','',''),('quantangshi-08773','拟古十二首 二','李白','quantangshi','','卷9','高楼入青天，下有白玉堂。
明月看欲堕，当窗悬清光。
遥夜一美人，罗衣霑秋霜。
含情弄柔瑟，弹作陌上桑。
弦声何激烈，风卷遶飞梁。
行人皆踯躅，栖鸟起回翔。
但写妾意苦，莫辞此曲伤。
愿逢同心者，飞作紫鸳鸯。','',''),('quantangshi-08774','拟古十二首 三','李白','quantangshi','','卷9','长绳难系日，自古共悲辛。
黄金高北斗，不惜买阳春。
石火无留光，还如世中人。
即事已如梦，后来我谁身。
提壶莫辞贫，取酒会四邻。
仙人殊恍惚，未若醉中真。','',''),('quantangshi-08775','拟古十二首 四','李白','quantangshi','','卷9','清都绿玉树，灼烁瑶台春。
攀花弄秀色，远赠天仙人。
香风送紫蘂，直到扶桑津。
取掇世上艳，所贵心之珍。
相思传一笑，聊欲示情亲。','',''),('quantangshi-08776','拟古十二首 五','李白','quantangshi','','卷9','今日风日好，明日恐不如。
春风笑于人，何乃愁自居。
吹箫舞彩凤，酌醴鲙神鱼。
千金买一醉，取乐不求余。
达士遗天地，东门有二疏。
愚夫同瓦石，有才知卷舒。
无事作悲苦，块然涸辙鱼。','',''),('quantangshi-08777','拟古十二首 六','李白','quantangshi','','卷9','运速天地闭，胡风结飞霜。
百草死冬月，六龙颓西荒。
太白出东方，彗星扬精光。
鸳鸯非越鸟，何为眷南翔。
惟昔鹰将犬，今为侯与王。
得水成蛟龙，争池夺凤凰。
北斗不酌酒，南箕空簸扬。','',''),('quantangshi-08778','拟古十二首 七','李白','quantangshi','','卷9','世路今太行，回车竟何托。
万族皆凋枯，遂无少可乐。
旷野多白骨，幽魂共销铄。
荣贵当及时，春华宜照灼。
人非昆山玉，安得长璀错。
身没期不朽，荣名在麟阁。','',''),('quantangshi-08779','拟古十二首 八','李白','quantangshi','','卷9','月色不可扫，客愁不可道。
玉露生秋衣，流萤飞百草。
日月终销毁，天地同枯槁。
蟪蛄啼青松，安见此树老。
金丹宁误俗，昧者难精讨。
尔非千岁翁，多恨去世早。
饮酒入玉壶，藏身以为宝。','',''),('quantangshi-08780','拟古十二首 九','李白','quantangshi','','卷9','生者为过客，死者为归人。
天地一逆旅，同悲万古尘。
月兔空捣药，扶桑已成薪。
白骨寂无言，青松岂知春。
前后更叹息，浮荣安足珍。','',''),('quantangshi-08781','拟古十二首 十','李白','quantangshi','','卷9','仙人骑彩凤，昨下阆风岑。
海水三清浅，桃源一见寻。
遗我绿玉杯，兼之紫琼琴。
杯以倾美酒，琴以闲素心。
二物非世有，何论珠与金。
琴弹松里风，杯劝天上月。
风月长相知，世人何倏忽。','',''),('quantangshi-08782','拟古十二首 十一','李白','quantangshi','','卷9','涉江弄秋水，爱此荷花鲜。
攀荷弄其珠，荡漾不成圆。
佳人彩云里，欲赠隔远天。
相思无由见，怅望凉风前。','',''),('quantangshi-08783','拟古十二首 十二','李白','quantangshi','','卷9','去去复去去，辞君还忆君。
汉水既殊流，楚山亦此分。
人生难称意，岂得长为羣。
越燕喜海日，燕鸿思朔云。
别久容华晚，琅玕不能饭。
日落知天昏，梦长觉道远。
望夫登高山，化石竟不返。','',''),('quantangshi-08784','感兴六首 一','李白','quantangshi','','卷9','瑶姬天帝女，精彩化朝云。
宛转入宵梦，无心向楚君。
锦衾抱秋月，绮席空兰芬。
茫昧竟谁测，虚传宋玉文。','',''),('quantangshi-08785','感兴六首 二','李白','quantangshi','','卷9','洛浦有宓妃，飘颻雪争飞。
轻云拂素月，了可见清辉。
解佩欲西去，含情讵相违。
香尘动罗袜，绿水不霑衣。
陈王徒作赋，神女岂同归。
好色伤大雅，多为世所讥。','',''),('quantangshi-08786','感兴六首 三','李白','quantangshi','','卷9','裂素持作书，将寄万里怀。
眷眷待远信，竟岁无人来。
征鸿务随阳，又不为我栖。
委之在深箧，蠹鱼坏其题。
何如投水中，流落他人开。
不惜他人开，但恐生是非。','',''),('quantangshi-08787','感兴六首 四','李白','quantangshi','','卷9','十五游神仙，仙游未曾歇。
吹笙坐松风，泛瑟窥海月。
西山玉童子，使我炼金骨。
欲逐黄鹤飞，相呼向蓬阙。','',''),('quantangshi-08788','感兴六首 五','李白','quantangshi','','卷9','西国有美女，结楼青云端。
蛾眉艳晓月，一笑倾城欢。
高节不可夺，炯心如凝丹。
常恐彩色晚，不为人所观。
安得配君子，共乘双飞鸾。','',''),('quantangshi-08789','感兴六首 六','李白','quantangshi','','卷9','嘉谷隐丰草，草深苗且稀。
农夫既不异，孤穗将安归。
常恐委畴陇，忽与秋蓬飞。
乌得荐宗庙，为君生光辉。','',''),('quantangshi-08790','寓言三首 一','李白','quantangshi','','卷9','周公负斧扆，成王何夔夔。
武王昔不豫，剪爪投河湄。
贤圣遇谗慝，不免人君疑。
天风拔大木，禾黍咸伤萎。
管蔡扇苍蝇，公赋鸱鸮诗。
金縢若不启，忠信谁明之。','',''),('quantangshi-08791','寓言三首 二','李白','quantangshi','','卷9','摇裔双彩凤，婉娈三青禽。
往还瑶台里，鸣舞玉山岑。
以欢秦娥意，复得王母心。
区区精卫鸟，衔木空哀吟。','',''),('quantangshi-08792','寓言三首 三','李白','quantangshi','','卷9','长安春色归，先入青门道。
绿杨不自持，从风欲倾倒。
海燕还秦宫，双飞入帘栊。
相思不相见，托梦辽城东。','',''),('quantangshi-08793','秋夕旅怀','李白','quantangshi','','卷9','凉风度秋海，吹我乡思飞。
连山去无际，流水何时归。
目极浮云色，心断明月晖。
芳草歇柔艳，白露催寒衣。
梦长银汉落，觉罢天星稀。
含悲想旧国，泣下谁能挥。','',''),('quantangshi-08794','感遇四首 一','李白','quantangshi','','卷9','吾爱王子晋，得道伊洛滨。
金骨既不毁，玉颜长自春。
可怜浮丘公，猗靡与情亲。
举首白日间，分明谢时人。
二仙去已远，梦想空殷勤。','',''),('quantangshi-08795','感遇四首 二','李白','quantangshi','','卷9','可叹东篱菊，茎疎叶且微。
虽言异兰蕙，亦自有芳菲。
未泛盈樽酒，徒霑清露辉。
当荣君不采，飘落欲何依。','',''),('quantangshi-08796','感遇四首 三','李白','quantangshi','','卷9','昔余闻姮娥，窃药驻云发。
不自娇玉颜，方希炼金骨。
飞去身莫返，含笑坐明月。
紫宫夸蛾眉，随手会凋歇。','',''),('quantangshi-08797','感遇四首 四','李白','quantangshi','','卷9','宋玉事楚王，立身本高洁。
巫山赋彩云，郢路歌白雪。
举国莫能和，巴人皆卷舌。
一感登徒言，恩情遂中绝。','',''),('quantangshi-08798','翰林读书言怀呈集贤诸学士','李白','quantangshi','','卷9','晨趋紫禁中，夕待金门诏。
观书散遗帙，探古穷至妙。
片言苟会心，掩卷忽而笑。
青蝇易相点，白雪难同调。
本是疎散人，屡贻褊促诮。
云天属清朗，林壑忆游眺。
或时清风来，闲倚栏下啸。
严光桐庐溪，谢客临海峤。
功成谢人间，从此一投钓。','',''),('quantangshi-08799','寻阳紫极宫感秋作','李白','quantangshi','','卷9','何处闻秋声，翛翛北窗竹。
回薄万古心，揽之不盈掬。
静坐观众妙，浩然媚幽独。
白云南山来，就我檐下宿。
嬾从唐生决，羞访季主卜。
四十九年非，一往不可复。
野情转萧洒，世道有飜覆。
陶令归去来，田家酒应熟。','',''),('quantangshi-08800','江上秋怀','李白','quantangshi','','卷9','餐霞卧旧壑，散发谢远游。
山蝉号枯桑，始复知天秋。
朔雁别海裔，越燕辞江楼。
飒飒风卷沙，茫茫雾萦洲。
黄云结暮色，白水扬寒流。
恻怆心自悲，潺湲泪难收。
蘅兰方萧瑟，长叹令人愁。','',''),('quantangshi-08801','秋夕书怀','李白','quantangshi','','卷9','北风吹海雁，南渡落寒声。
感此潇湘客，凄其流浪情。
海怀结沧洲，霞想游赤城。
始探蓬壶事，旋觉天地轻。
澹然吟高秋，闲卧瞻太清。
萝月掩空幕，松霜结前楹。
灭见息羣动，猎微穷至精。
桃花有源水，可以保吾生。','',''),('quantangshi-08802','避地司空原言怀','李白','quantangshi','','卷9','南风昔不竞，豪圣思经纶。
刘琨与祖逖，起舞鸡鸣晨。
虽有匡济心，终为乐祸人。
我则异于是，潜光皖水滨。
卜筑司空原，北将天柱邻。
雪霁万里月，云开九江春。
俟乎泰阶平，然后托微身。
倾家事金鼎，年貌可长新。
所愿得此道，终然保清真。
弄景奔日驭，攀星戏河津。
一随王乔去，长年玉天宾。','',''),('quantangshi-08803','上崔相百忧章','李白','quantangshi','','卷9','共公赫怒，天维中摧。
鲲鲸喷荡，扬涛起雷。
鱼龙陷人，成此祸胎。
火焚昆山，玉石相磓。
仰希霖雨，洒宝炎煨。
箭发石开，戈挥日回。
邹衍恸哭，燕霜飒来。
微诚不感，犹絷夏台。
苍鹰搏攫，丹棘崔嵬。
豪圣凋枯，王风伤哀。
斯文未丧，东岳岂颓。
穆逃楚难，邹脱吴灾。
见机苦迟，二公所咍。
骥不骤进，麟何来哉。
星离一门，草掷二孩。
万愤结习，忧从中催。
金瑟玉壶，尽为愁媒。
举酒太息，泣血盈杯。
台星再朗，天纲重恢。
屈法申恩，弃瑕取材。
冶长非罪，尼父无猜。
覆盆傥举，应照寒灰。','',''),('quantangshi-08804','万愤词投魏郎中','李白','quantangshi','','卷9','海水渤潏，人罹鲸鲵。
蓊胡沙而四塞，始滔天于燕齐。
何六龙之浩荡，迁白日于秦西。
九土星分，嗷嗷栖栖。
南冠君子，呼天而啼。
恋高堂而掩泣，泪血地而成泥。
狱户春而不草，独幽怨而沈迷。
兄九江兮弟三峡，悲羽化之难齐。
穆陵关北愁爱子，豫章天南隔老妻。
一门骨肉散百草，遇难不复相提携。
树榛拔桂，囚鸾宠鸡。
舜昔授禹，伯成耕犂。
德自此衰，吾将安栖。
好我者恤我，不好我者何忍临危而相挤。
子胥鸱夷，彭越醢醯。
自古豪烈，胡为此繄。
苍苍之天，高乎视低。
如其听卑，脱我牢狴。
傥辨美玉，君收白圭。','',''),('quantangshi-08805','荆州贼平临洞庭言怀作','李白','quantangshi','','卷9','修蛇横洞庭，吞象临江岛。
积骨成巴陵，遗言闻楚老。
水穷三苗国，地窄三湘道。
岁[晏]天峥嵘，时危人枯槁。
思归阻丧乱，去国伤怀抱。
郢路方丘墟，章华亦倾倒。
风悲猨啸苦，木落鸿飞早。
日隐西赤沙，月明东城草。
关河望已绝，氛雾行当扫。
长呌天可闻，吾将问苍昊。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-08806','览镜书怀','李白','quantangshi','','卷9','得道无古今，失道还衰老。
自笑镜中人，白发如霜草。
扪心空叹息，问影何枯槁。
桃李竟何言，终成南山皓。','',''),('quantangshi-08807','田园言怀','李白','quantangshi','','卷9','贾谊三年谪，班超万里侯。
何如牵白犊，饮水对清流。','',''),('quantangshi-08808','江南春怀','李白','quantangshi','','卷9','青春几何时，黄鸟鸣不歇。
天涯失乡路，江外老华发。
心飞秦塞云，影滞楚关月。
身世殊烂漫，田园久芜没。
岁[晏]何所从，长歌谢金阙。','',''),('quantangshi-08809','听蜀僧浚弹琴','李白','quantangshi','','卷9','蜀僧抱绿绮，西下峨眉峰。
为我一挥手，如听万壑松。
客心洗流水，余响入霜钟。
不觉碧山暮，秋云暗几重。','',''),('quantangshi-08810','鲁东门观刈蒲','李白','quantangshi','','卷9','鲁国寒事早，初霜刈渚蒲。
挥镰若转月，拂水生连珠。
此草最可珍，何必贵龙须。
织作玉牀席，欣承清夜娱。
罗衣能再拂，不畏素尘芜。','',''),('quantangshi-08811','咏邻女东窗海石榴','李白','quantangshi','','卷9','鲁女东窗下，海榴世所稀。
珊瑚映绿水，未足比光辉。
清香随风发，落日好鸟归。
愿为东南枝，低举拂罗衣。
无由共攀折，引领望金扉。','',''),('quantangshi-08812','南轩松','李白','quantangshi','','卷9','南轩有孤松，柯叶自绵幂。
清风无闲时，潇洒终日夕。
阴生古苔绿，色染秋烟碧。
何当凌云霄，直上数千尺。','',''),('quantangshi-08813','咏山樽二首 一','李白','quantangshi','','卷9','蟠木不雕饰，且将斤斧疎。
樽成山岳势，材是栋梁余。
外与金罍并，中涵玉醴虚。
慙君垂拂拭，遂忝玳筵居。','',''),('quantangshi-08814','咏山樽二首 二','李白','quantangshi','','卷9','拥肿寒山木，嵌空成酒樽。
愧无江海量，偃蹇在君门。','',''),('quantangshi-08815','初出金门寻王侍御不遇咏壁上鹦鹉','李白','quantangshi','','卷9','落羽辞金殿，孤鸣咤绣衣。
能言终见弃，还向陇西飞。','',''),('quantangshi-08816','紫藤树','李白','quantangshi','','卷9','紫藤挂云木，花蔓宜阳春。
密叶隐歌鸟，香风留美人。','',''),('quantangshi-08817','观放白鹰二首 一','李白','quantangshi','','卷9','八月边风高，胡鹰白锦毛。
孤飞一片雪，百里见秋毫。','',''),('quantangshi-08818','观放白鹰二首 二','李白','quantangshi','','卷9','寒冬十二月，苍鹰八九毛。
寄言燕雀莫相啅，自有云霄万里高。','',''),('quantangshi-08819','观博平王志安少府山水粉图','李白','quantangshi','','卷9','粉壁为空天，丹青状江海。
游云不知归，日见白鸥在。
博平真人王志安，沈吟至此愿挂冠。
松溪石磴带秋色，愁客思归坐晓寒。','',''),('quantangshi-08820','题雍丘崔明府丹竈','李白','quantangshi','','卷9','美人为政本忘机，服药求仙事不违。
叶县已泥丹竈毕，瀛洲当伴赤松归。
先师有诀神将助，大圣无心火自飞。
九转但能生羽翼，双凫忽去定何依。','',''),('quantangshi-08821','观元丹丘坐巫山屏风','李白','quantangshi','','卷9','昔游三峡见巫山，见画巫山宛相似。
疑是天边十二峰，飞入君家彩屏里。
寒松萧瑟如有声，阳台微茫如有情。
锦衾瑶席何寂寂，楚王神女徒盈盈。
高咫尺，如千里，翠屏丹崖灿如绮。
苍苍远树围荆门，历历行舟泛巴水。
水石潺湲万壑分，烟光草色俱氛氲。
溪花笑日何年发，江客听猨几岁闻。
使人对此心缅邈，疑入嵩丘梦彩云。','',''),('quantangshi-08822','求崔山人百丈崖瀑布图','李白','quantangshi','','卷9','百丈素崖裂，四山丹壁开。
龙潭中喷射，昼夜生风雷。
但见瀑泉落，如潨云汉来。
闻君写真图，岛屿备萦回。
石黛刷幽草，曾青泽古苔。
幽缄傥相传，何必向天台。','',''),('quantangshi-08823','见野草中有曰白头翁者','李白','quantangshi','','卷9','醉入田家去，行歌荒野中。
如何青草里，亦有白头翁。
折取对明镜，宛将衰鬓同。
微芳似相诮，留恨向东风。','',''),('quantangshi-08824','流夜郎题葵叶','李白','quantangshi','','卷9','慙君能卫足，叹我远移根。
白日如分照，还归守故园。','',''),('quantangshi-08825','茔禅师房观山海图','李白','quantangshi','','卷9','真僧闭精宇，灭迹含达观。
列嶂图云山，攒峰入霄汉。
丹崖森在目，清昼疑卷幔。
蓬壶来轩窗，瀛海入几案。
烟涛争喷薄，岛屿相凌乱。
征帆飘空中，瀑水洒天半。
峥嵘若可陟，想像徒盈叹。
杳与真心冥，遂谐静者翫。
如登赤城里，揭步沧洲畔。
即事能娱人，从兹得消散。','',''),('quantangshi-08826','白鹭鹚','李白','quantangshi','','卷9','白鹭下秋水，孤飞如坠霜。
心闲且未去，独立沙洲傍。','',''),('quantangshi-08827','咏槿','李白','quantangshi','','卷9','园花笑芳年，池草艳春色。
犹不如槿花，婵娟玉阶侧。
芬荣何夭促，零落在瞬息。
岂若琼树枝，终岁长翕赩。','',''),('quantangshi-08828','咏桂','李白','quantangshi','','卷9','世人种桃李，皆在金张门。
攀折争捷径，及此春风暄。
一朝天霜下，荣耀难久存。
安知南山桂，绿叶垂芳根。
清阴亦可托，何惜树君园。','',''),('quantangshi-08829','白胡桃','李白','quantangshi','','卷9','红罗袖里分明见，白玉盘中看却无。
疑是老僧休念诵，腕前推下水晶珠。','',''),('quantangshi-08830','巫山枕障','李白','quantangshi','','卷9','巫山枕障画高丘，白帝城边树色秋。
朝云夜入无行处，巴水横天更不流。','',''),('quantangshi-08831','南奔书怀','李白','quantangshi','','卷9','遥夜何漫漫，空歌白石烂。
甯戚未匡齐，陈平终佐汉。
搀抢扫河洛，直割鸿沟半。
历数方未迁，云雷屡多难。
天人秉旄钺，虎竹光藩翰。
侍笔黄金台，传觞青玉案。
不因秋风起，自有思归叹。
主将动谗疑，王师忽离叛。
自来白沙上，鼓噪丹阳岸。
宾御如浮云，从风各消散。
舟中指可掬，城上骸争爨。
草草出近关，行行昧前算。
南奔剧星火，北寇无涯畔。
顾乏七宝鞭，留连道傍翫。
太白夜食昴，长虹日中贯。
秦赵兴天兵，茫茫九州乱。
感遇明主恩，颇高祖逖言。
过江誓流水，志在清中原。
拔剑击前柱，悲歌难重论。','',''),('quantangshi-08832','题随州紫阳先生壁','李白','quantangshi','','卷9','神农好长生，风俗久已成。
复闻紫阳客，早署丹台名。
喘息餐妙气，步虚吟真声。
道与古仙合，心将元化并。
楼疑出蓬海，鹤似飞玉京。
松雪窗外晓，池水阶下明。
忽耽笙歌乐，颇失轩冕情。
终愿惠金液，提携凌太清。','',''),('quantangshi-08833','题元丹丘山居','李白','quantangshi','','卷9','故人栖东山，自爱丘壑美。
青春卧空林，白日犹不起。
松风清襟袖，石潭洗心耳。
羡君无纷喧，高枕碧霞里。','',''),('quantangshi-08834','题元丹丘颍阳山居','李白','quantangshi','','卷9','仙游渡颍水，访隐同元君。
忽遗苍生望，独与洪崖羣。
卜地初晦迹，兴言且成文。
却顾北山断，前瞻南岭分。
遥通汝海月，不隔嵩丘云。
之子合逸趣，而我钦清芬。
举迹倚松石，谈笑迷朝曛。
益愿狎青鸟，拂衣栖江濆。','',''),('quantangshi-08835','题瓜州新河饯族叔舍人贲','李白','quantangshi','','卷9','齐公凿新河，万古流不绝。
丰功利生人，天地同朽灭。
两桥对双阁，芳树有行列。
爱此如甘棠，谁云敢攀折。
吴关倚此固，天险自兹设。
海水落斗门，湖平见沙汭。
我行送季父，弭棹徒流悦。
杨花满江来，疑是龙山雪。
惜此林下兴，怆为山阳别。
瞻望清路尘，归来空寂灭。','',''),('quantangshi-08836','洗脚亭','李白','quantangshi','','卷9','白道向姑熟，洪亭临道傍。
前有昔时井，下有五丈牀。
樵女洗素足，行人歇金装。
西望白鹭洲，芦花似朝霜。
送君此时去，回首泪成行。','',''),('quantangshi-08837','劳劳亭','李白','quantangshi','','卷9','天下伤心处，劳劳送客亭。
春风知别苦，不遣柳条青。','',''),('quantangshi-08838','题金陵王处士水亭','李白','quantangshi','','卷9','王子耽玄言，贤豪多在门。
好鹅寻道士，爱竹啸名园。
树色老荒苑，池光荡华轩。
此堂见明月，更忆陆平原。
埽拭青玉簟，为余置金尊。
醉罢欲归去，花枝宿鸟喧。
何时复来此，再得洗嚣烦。','',''),('quantangshi-08839','题嵩山逸人元丹丘山居','李白','quantangshi','','卷9','家本紫云山，道风未沦落。
沈怀丹丘志，冲赏归寂寞。
朅来游闽荒，扪涉穷禹凿。
夤缘泛潮海，偃蹇陟庐霍。
凭雷蹑天窗，弄影憩霞阁。
且欣登眺美，颇惬隐沦诺。
三山旷幽期，四岳聊所托。
故人契嵩颖，高义炳丹雘。
灭迹遗纷嚣，终言本峰壑。
自矜林湍好，不羡朝市乐。
偶与真意并，顿觉世情薄。
尔能折芳桂，吾亦采兰若。
拙妻好乘鸾，娇女爱飞鹤。
提携访神仙，从此炼金药。','',''),('quantangshi-08840','题江夏修静寺','李白','quantangshi','','卷9','我家北海宅，作寺南江滨。
空庭无玉树，高殿坐幽人。
书带留青草，琴堂幂素尘。
平生种桃李，寂灭不成春。','',''),('quantangshi-08841','题宛溪馆','李白','quantangshi','','卷9','吾怜宛溪好，百尺照心明。
何谢新安水，千寻见底清。
白沙留月色，绿竹助秋声。
却笑严湍上，于今独擅名。','',''),('quantangshi-08842','题东溪公幽居','李白','quantangshi','','卷9','杜陵贤人清且廉，东溪卜筑岁将淹。
宅近青山同谢朓，门垂碧柳似陶潜。
好鸟迎春歌后院，飞花送酒舞前檐。
客到但知留一醉，盘中秪有水晶盐。','',''),('quantangshi-08843','嘲鲁儒','李白','quantangshi','','卷9','鲁叟谈五经，白发死章句。
问以经济策，茫如坠烟雾。
足着远游履，首戴方山巾。
缓步从直道，未行先起尘。
秦家丞相府，不重褒衣人。
君非叔孙通，与我本殊伦。
时事且未达，归耕汶水滨。','',''),('quantangshi-08844','惧谗','李白','quantangshi','','卷9','二桃杀三士，讵假劒如霜。
众女妬蛾眉，双花竞春芳。
魏姝信郑褏，掩袂对怀王。
一惑巧言子，朱颜成死伤。
行将泣团扇，戚戚愁人肠。','',''),('quantangshi-08845','观猎','李白','quantangshi','','卷9','太守耀清威，乘闲弄晚晖。
江沙横猎骑，山火遶行围。
箭逐云鸿落，鹰随月兔飞。
不知白日暮，欢赏夜方归。','',''),('quantangshi-08846','观胡人吹笛','李白','quantangshi','','卷9','胡人吹玉笛，一半是秦声。
十月吴山晓，梅花落敬亭。
愁闻出塞曲，泪满逐臣缨。
却望长安道，空怀恋主情。','',''),('quantangshi-08847','军行','李白','quantangshi','','卷9','骝马新跨白玉鞍，战罢沙场月色寒。
城头铁鼓声犹震，匣里金刀血未干。','',''),('quantangshi-08848','从军行','李白','quantangshi','','卷9','百战沙场碎铁衣，城南已合数重围。
突营射杀呼延将，独领残兵千骑归。','',''),('quantangshi-08849','平虏将军妻','李白','quantangshi','','卷9','平虏将军妇，入门二十年。
君心自有悦，妾宠岂能专。
出解牀前帐，行吟道上篇。
古人不唾井，莫忘昔缠绵。','',''),('quantangshi-08850','春夜洛城闻笛','李白','quantangshi','','卷9','谁家玉笛暗飞声，散入春风满洛城。
此夜曲中闻折柳，何人不起故园情。','',''),('quantangshi-08851','嵩山采菖蒲者','李白','quantangshi','','卷9','神仙多古貌，双耳下垂肩。
嵩岳逢汉武，疑是九疑仙。
我来采菖蒲，服食可延年。
言终忽不见，灭影入云烟。
喻帝竟莫悟，终归茂陵田。','',''),('quantangshi-08852','金陵听韩侍御吹笛','李白','quantangshi','','卷9','韩公吹玉笛，倜傥流英音。
风吹绕钟山，万壑皆龙吟。
王子停凤管，师襄掩瑶琴。
余韵度江去，天涯安可寻。','',''),('quantangshi-08853','流夜郎闻酺不预','李白','quantangshi','','卷9','北阙圣人歌太康，南冠君子窜遐荒。
汉酺闻奏钧天乐，愿得风吹到夜郎。','',''),('quantangshi-08854','放后遇恩不霑','李白','quantangshi','','卷9','天作云与雷，霈然德泽开。
东风日本至，白雉越裳来。
独弃长沙国，三年未许回。
何时入宣室，更问洛阳才。','',''),('quantangshi-08855','宣城见杜鹃花','李白','quantangshi','','卷9','蜀国曾闻子规鸟，宣城还见杜鹃花。
一呌一回肠一断，三春三月忆三巴。','',''),('quantangshi-08856','白田马上闻莺','李白','quantangshi','','卷9','黄鹂啄紫椹，五月鸣桑枝。
我行不记日，误作阳春时。
蚕老客未归，白田已缲丝。
驱马又前去，扪心空自悲。','',''),('quantangshi-08857','三五七言','李白','quantangshi','','卷9','秋风清，秋月明。
落叶聚还散，寒鸦栖复惊。
相思相见知何日，此时此夜难为情。','',''),('quantangshi-08858','杂诗','李白','quantangshi','','卷9','白日与明月，昼夜尚不闲。
况尔悠悠人，安得久世间。
传闻海水上，乃有蓬莱山。
玉树生绿叶，灵仙每登攀。
一食驻玄发，再食留红颜。
吾欲从此去，去之无时还。','',''),('quantangshi-08859','寄远十一首 一','李白','quantangshi','','卷9','三鸟别王母，衔书来见过。
肠断若剪弦，其如愁思何。
遥知玉窗里，纤手弄云和。
奏曲有深意，青松交女萝。
写水山井中，同泉岂殊波。
秦心与楚恨，皎皎为谁多。','',''),('quantangshi-08860','寄远十一首 二','李白','quantangshi','','卷9','青楼何所在，乃在碧云中。
宝镜挂秋水，罗衣轻春风。
新妆坐落日，怅望金屏空。
念此送短书，愿因双飞鸿。','',''),('quantangshi-08861','寄远十一首 三','李白','quantangshi','','卷9','本作一行书，殷勤道相忆。
一行复一行，满纸情何极。
瑶台有黄鹤，为报青楼人。
朱颜凋落尽，白发一何新。
自知未应还，离居经三春。
桃李今若为，当窗发光彩。
莫使香风飘，留与红芳待。','',''),('quantangshi-08862','寄远十一首 四','李白','quantangshi','','卷9','玉[筯]落春镜，坐愁湖阳水。
闻与阴丽华，风烟接邻里。
青春已复过，白日忽相催。
但恐荷花晚，令人意已摧。
相思不惜梦，日夜向阳台。','',''),('quantangshi-08863','寄远十一首 五','李白','quantangshi','','卷9','远忆巫山阳，花明渌江暖。
踌躇未得往，泪向南云满。
春风复无情，吹我梦魂断。
不见眼中人，天长音信短。','',''),('quantangshi-08864','寄远十一首 六','李白','quantangshi','','卷9','阳台隔楚水，春草生黄河。
相思无日夜，浩荡若流波。
流波向海去，欲见终无因。
遥将一点泪，远寄如花人。','',''),('quantangshi-08865','寄远十一首 七','李白','quantangshi','','卷9','妾在舂陵东，君居汉江岛。
一日望花光，往来成白道。
一为云雨别，此地生秋草。
秋草秋蛾飞，相思愁落晖。
何由一相见，灭烛解罗衣。','',''),('quantangshi-08866','寄远十一首 八','李白','quantangshi','','卷9','忆昨东园桃李红碧枝，与君此时初别离。
金瓶落井无消息，令人行叹复坐思。
坐思行叹成楚越，春风玉颜畏销歇。
碧窗纷纷下落花，青楼寂寂空明月。
两不见，但相思，空留锦字表心素，至今缄愁不忍窥。','',''),('quantangshi-08867','寄远十一首 九','李白','quantangshi','','卷9','长短春草绿，缘阶如有情。
卷施心独苦，抽却死还生。
覩物知妾意，希君种后庭。
闲时当采掇，念此莫相轻。','',''),('quantangshi-08868','寄远十一首 十','李白','quantangshi','','卷9','鲁缟如玉霜，笔题月氏书。
寄书白鹦鹉，西海慰离居。
行数虽不多，字字有委曲。
天末如见之，开缄泪相续。
泪尽恨转深，千里同此心。
相思千万里，一书值千金。','',''),('quantangshi-08869','寄远十一首 十一','李白','quantangshi','','卷9','爱君芙蓉婵娟之艳色，色可餐兮难再得。
怜君冰玉清逈之明心，情不极兮意已深。
朝共琅玕之绮食，夜同鸳鸯之锦衾。
恩情婉娈忽为别，使人莫错乱愁心。
乱愁心，涕如雪，寒灯厌梦魂欲绝。
觉来相思生白发，盈盈汉水若可越。
可惜凌波步罗韤，美人美人兮归去来，莫作朝云暮雨兮飞阳台。','',''),('quantangshi-08870','长信宫','李白','quantangshi','','卷9','月皎昭阳殿，霜清长信宫。
天行乘玉辇，飞燕与君同。
别有欢娱处，承恩乐未穷。
谁怜团扇妾，独坐怨秋风。','',''),('quantangshi-08871','长门怨二首 一','李白','quantangshi','','卷9','天回北斗挂西楼，金屋无人萤火流。
月光欲到长门殿，别作深宫一段愁。','',''),('quantangshi-08872','长门怨二首 二','李白','quantangshi','','卷9','桂殿长愁不记春，黄金四屋起秋尘。
夜悬明镜青天上，独照长门宫里人。','',''),('quantangshi-08873','春怨','李白','quantangshi','','卷9','白马金羁辽海东，罗帷绣被卧春风。
落月低轩窥烛尽，飞花入户笑牀空。','',''),('quantangshi-08874','代赠远','李白','quantangshi','','卷9','妾本洛阳人，狂夫幽燕客。
渴饮易水波，由来多感激。
胡马西北驰，香鬃摇绿丝。
鸣鞭从此去，逐虏荡边陲。
昔去有好言，不言久离别。
燕支多美女，走马轻风雪。
见此不记人，恩情云雨绝。
啼流玉筯尽，坐恨金闺切。
织锦作短书，肠随回文结。
相思欲有寄，恐君不见察。
焚之扬其灰，手迹自此灭。','',''),('quantangshi-08875','陌上赠美人','李白','quantangshi','','卷9','骏马骄行踏落花，垂鞭直拂五云车。
美人一笑褰珠箔，遥指红楼是妾家。','',''),('quantangshi-08876','闺情','李白','quantangshi','','卷9','流水去绝国，浮云辞故关。
水或恋前浦，云犹归旧山。
恨君流沙去，弃妾渔阳间。
玉筯夜垂流，双双落朱颜。
黄鸟坐相悲，绿杨谁更攀。
织锦心草草，挑灯泪斑斑。
窥镜不自识，况乃狂夫还。','',''),('quantangshi-08877','代别情人','李白','quantangshi','','卷9','清水本不动，桃花发岸傍。
桃花弄水色，波荡摇春光。
我悦子容艳，子倾我文章。
风吹绿琴去，曲度紫鸳鸯。
昔作一水鱼，今成两枝鸟。
哀哀长鸡鸣，夜夜达五晓。
起折相思树，归赠知寸心。
覆水不可收，行云难重寻。
天涯有度鸟，莫绝瑶华音。','',''),('quantangshi-08878','代秋情','李白','quantangshi','','卷9','几日相别离，门前生穭葵。
寒蝉聒梧桐，日夕长鸣悲。
白露湿萤火，清霜凌兔丝。
空掩紫罗袂，长啼无尽时。','',''),('quantangshi-08879','对酒','李白','quantangshi','','卷9','蒲萄酒，金叵罗，吴姬十五细马驮。
青黛画眉红锦靴，道字不正娇唱歌。
玳瑁筵中怀里醉，芙蓉帐底奈君何。','',''),('quantangshi-08880','怨情','李白','quantangshi','','卷9','新人如花虽可宠，故人似玉由来重。
花性飘扬不自持，玉心皎洁终不移。
故人昔新今尚故，还见新人有故时。
请看陈后黄金屋，寂寂珠帘生网丝。','',''),('quantangshi-08881','湖边采莲妇','李白','quantangshi','','卷9','小姑织白紵，未解将人语。
大嫂采芙蓉，溪湖千万重。
长兄行不在，莫使外人逢。
愿学秋胡妇，贞心比古松。','',''),('quantangshi-08882','怨情','李白','quantangshi','','卷9','美人卷珠帘，深坐颦蛾眉。
但见泪痕湿，不知心恨谁。','',''),('quantangshi-08883','代寄情楚词体','李白','quantangshi','','卷9','君不来兮，徒蓄怨积思而孤吟。
云阳一去已远，隔巫山绿水之沈沈。
留余香兮染绣被，夜欲寝兮愁人心。
朝驰余马于青楼，怳若空而夷犹。
浮云深兮不得语，却惆怅而怀忧。
使青鸟兮衔书，恨独宿兮伤离居。
何无情而雨绝，梦虽往而交疎。
横流涕而长嗟，折芳洲之瑶华。
送飞鸟以极目，怨夕阳之西斜。
愿为连根同死之秋草，不作飞空之落花。','',''),('quantangshi-08884','学古思边','李白','quantangshi','','卷9','衔悲上陇首，肠断不见君。
流水若有情，幽哀从此分。
苍茫愁边色，惆怅落日曛。
山外接远天，天际复有云。
白雁从中来，飞鸣苦难闻。
足系一书札，寄言难离羣。
离羣心断绝，十见花成雪。
胡地无春晖，征人行不归。
相思杳如梦，珠泪湿罗衣。','',''),('quantangshi-08885','思边','李白','quantangshi','','卷9','去年何时君别妾，南园绿草飞蝴蝶。
今岁何时妾忆君，西山白雪暗晴云。
玉关去此三千里，欲寄音书那可闻。','',''),('quantangshi-08886','口号吴王美人半醉','李白','quantangshi','','卷9','风动荷花水殿香，姑苏台上宴吴王。
西施醉舞娇无力，笑倚东窗白玉牀。','',''),('quantangshi-08887','代美人愁镜二首 一','李白','quantangshi','','卷9','明明金鹊镜，了了玉台前。
拂拭交冰月，光辉何清圆。
红颜老昨日，白发多去年。
铅粉坐相误，照来空凄然。','',''),('quantangshi-08888','代美人愁镜二首 二','李白','quantangshi','','卷9','美人赠此盘龙之宝镜，烛我金缕之罗衣。
时将红袖拂明月，为惜普照之余晖。
影中金鹊飞不灭，台下青鸾思独绝。
藳砧一别若箭弦，去有日，来无年。
狂风吹却妾心断，玉筯并堕菱花前。','',''),('quantangshi-08889','赠段七娘','李白','quantangshi','','卷9','罗韤凌波生网尘，那能得计访情亲。
千杯绿酒何辞醉，一面红妆恼杀人。','',''),('quantangshi-08890','别内赴征三首 一','李白','quantangshi','','卷9','王命三征去未还，明朝离别出吴关。
白玉高楼看不见，相思须上望夫山。','',''),('quantangshi-08891','别内赴征三首 二','李白','quantangshi','','卷9','出门妻子强牵衣，问我西行几日归。
归时傥佩黄金印，莫学苏秦不下机。','',''),('quantangshi-08892','别内赴征三首 三','李白','quantangshi','','卷9','翡翠为楼金作梯，谁人独宿倚门啼。
夜坐寒灯连晓月，行行泪尽楚关西。','',''),('quantangshi-08893','秋浦寄内','李白','quantangshi','','卷9','我今寻阳去，辞家千里余。
结荷倦水宿，却寄大雷书。
虽不同辛苦，怆离各自居。
我自入秋浦，三年北信疎。
红颜愁落尽，白发不能除。
有客自梁苑，手携五色鱼。
开鱼得锦字，归问我何如。
江山虽道阻，意合不为殊。','',''),('quantangshi-08894','自代内赠','李白','quantangshi','','卷9','宝刀截流水，无有断绝时。
妾意逐君行，缠绵亦如之。
别来门前草，秋巷春转碧。
埽尽更还生，萋萋满行迹。
鸣凤始相得，雄惊雌各飞。
游云落何山，一往不见归。
估客发大楼，知君在秋浦。
梁苑空锦衾，阳台梦行雨。
妾家三作相，失势去西秦。
犹有旧歌管，凄清闻四邻。
曲度入紫云，啼无眼中人。
妾似井底桃，开花向谁笑。
君如天上月，不肯一回照。
窥镜不自识，别多憔悴深。
安得秦吉了，为人道寸心。','',''),('quantangshi-08895','秋浦感主人归燕寄内','李白','quantangshi','','卷9','霜凋楚关木，始知杀气严。
寥寥金天廓，婉婉绿红潜。
胡燕别主人，双双语前檐。
三飞四回顾，欲去复相瞻。
岂不恋华屋，终然谢珠帘。
我不及此鸟，远行岁已淹。
寄书道中叹，泪下不能缄。','',''),('quantangshi-08896','送内寻庐山女道士李腾空二首 一','李白','quantangshi','','卷9','君寻腾空子，应到碧山家。
水舂云母确，风埽石楠花。
若爱幽居好，相邀弄紫霞。','',''),('quantangshi-08897','送内寻庐山女道士李腾空二首 二','李白','quantangshi','','卷9','多君相门女，学道爱神仙。
素手掬青霭，罗衣曳紫烟。
一往屏风叠，乘鸾着玉鞭。','',''),('quantangshi-08898','赠内','李白','quantangshi','','卷9','三百六十日，日日醉如泥。
虽为李白妇，何异太常妻。','',''),('quantangshi-08899','在浔阳非所寄内','李白','quantangshi','','卷9','闻难知恸哭，行啼入府中。
多君同蔡琰，流泪请曹公。
知登吴章岭，昔与死无分。
崎岖行石道，外折入青云。
相见若悲歌，哀声那可闻。','',''),('quantangshi-08900','南流夜郎寄内','李白','quantangshi','','卷9','夜郎天外怨离居，明月楼中音信疎。
北雁春归看欲尽，南来不得豫章书。','',''),('quantangshi-08901','越女词五首 一','李白','quantangshi','','卷9','长干吴儿女，眉目艳新月。
屐上足如霜，不着鸦头袜。','',''),('quantangshi-08902','越女词五首 二','李白','quantangshi','','卷9','吴儿多白皙，好为荡舟剧。
卖眼掷春心，折花调行客。','',''),('quantangshi-08903','越女词五首 三','李白','quantangshi','','卷9','耶溪采莲女，见客棹歌回。
笑入荷花去，佯羞不出来。','',''),('quantangshi-08904','越女词五首 四','李白','quantangshi','','卷9','东阳素足女，会稽素舸郎。
相看月未堕，白地断肝肠。','',''),('quantangshi-08905','越女词五首 五','李白','quantangshi','','卷9','镜湖水如月，耶溪女似雪。
新妆荡新波，光景两奇绝。','',''),('quantangshi-08906','浣纱石上女','李白','quantangshi','','卷9','玉面耶溪女，青娥红粉妆。
一双金齿屐，两足白如霜。','',''),('quantangshi-08907','示金陵子','李白','quantangshi','','卷9','金陵城东谁家子，窃听琴声碧窗里。
落花一片天上来，随人直渡西江水。
楚歌吴语娇不成，似能未能最有情。
谢公正要东山妓，携手林泉处处行。','',''),('quantangshi-08908','出妓金陵子呈卢六四首 一','李白','quantangshi','','卷9','安石东山三十春，傲然携妓出风尘。
楼中见我金陵子，何似阳台云雨人。','',''),('quantangshi-08909','出妓金陵子呈卢六四首 二','李白','quantangshi','','卷9','南国新丰酒，东山小妓歌。
对君君不乐，花月奈愁何。','',''),('quantangshi-08910','出妓金陵子呈卢六四首 三','李白','quantangshi','','卷9','东道烟霞主，西江诗酒筵。
相逢不觉醉，日堕历阳川。','',''),('quantangshi-08911','出妓金陵子呈卢六四首 四','李白','quantangshi','','卷9','小妓金陵歌楚声，家僮丹砂学凤鸣。
我亦为君饮清酒，君心不肯向人倾。','',''),('quantangshi-08912','巴女词','李白','quantangshi','','卷9','巴水急如箭，巴船去若飞。
十月三千里，郎行几岁归。','',''),('quantangshi-08913','哭晁卿衡','李白','quantangshi','','卷9','日本晁卿辞帝都，征帆一片绕蓬壶。
明月不归沈碧海，白云愁色满苍梧。','',''),('quantangshi-08914','自溧水道哭王炎三首 一','李白','quantangshi','','卷9','白杨双行行，白马悲路傍。
晨兴见晓月，更似发云阳。
溧水通吴关，逝川去未央。
故人万化尽，闭骨茅山冈。
天上坠玉棺，泉中掩龙章。
名飞日月上，义与风云翔。
逸气竟莫展，英图俄夭伤。
楚国一老人，来嗟龚胜亡。
有言不可道，雪泣忆兰芳。','',''),('quantangshi-08915','自溧水道哭王炎三首 二','李白','quantangshi','','卷9','王公希代宝，弃世一何早。
吊死不及哀，殡宫已秋草。
悲来欲脱劒，挂向何枝好。
哭向茅山虽未摧，一生泪尽丹阳道。','',''),('quantangshi-08916','自溧水道哭王炎三首 三','李白','quantangshi','','卷9','王家碧瑶树，一树忽先摧。
海内故人泣，天涯吊鹤来。
未成霖雨用，先失济川材。
一罢广陵散，鸣琴更不开。','',''),('quantangshi-08917','哭宣城善酿纪叟','李白','quantangshi','','卷9','纪叟黄泉里，还应酿老春。
夜台无晓日，沽酒与何人。','',''),('quantangshi-08918','宣城哭蒋征君华','李白','quantangshi','','卷9','敬亭埋玉树，知是蒋征君。
安得相如草，空余封禅文。
池台空有月，词赋旧凌云。
独挂延陵劒，千秋在古坟。','',''),('quantangshi-08919','鞠歌行','李白','quantangshi','','卷9','丽莫似汉宫妃，谦莫似黄家女。
黄女持谦齿发高，汉妃恃丽天庭去。
人生容德不自保，圣人安用推天道。
君不见蔡泽嵌枯诡怪之形状，大言直取秦丞相。
又不见田千秋才智不出人，一朝富贵如有神。
二侯行事在方册，泣麟老人终困厄。
夜光抱恨良叹悲，日月逝矣吾何之。','',''),('quantangshi-08920','胡无人','李白','quantangshi','','卷9','十万羽林儿，临洮破郅支。
杀添胡地骨，降足汉营旗。
塞阔牛羊散，兵休帐幕移。
空余陇头水，呜咽向人悲。','',''),('quantangshi-08921','月夜金陵怀古','李白','quantangshi','','卷9','苍苍金陵月，空悬帝王州。
天文列宿在，霸业大江流。
绿水绝驰道，青松摧古丘。
台倾鳷鹊观，宫没凤凰楼。
别殿悲清暑，芳园罢乐游。
一闻歌玉树，萧瑟后庭秋。','',''),('quantangshi-08922','冬日归旧山','李白','quantangshi','','卷9','未洗染尘缨，归来芳草平。
一条藤径绿，万点雪峰晴。
地冷叶先尽，谷寒云不行。
嫩篁侵舍密，古树倒江横。
白犬离村吠，苍苔壁上生。
穿厨孤雉过，临屋旧猨鸣。
木落禽巢在，篱疎兽路成。
拂牀苍鼠走，倒箧素鱼惊。
洗砚修良策，敲松拟素贞。
此时重一去，去合到三清。','',''),('quantangshi-08923','望夫石','李白','quantangshi','','卷9','仿髴古容仪，含愁带曙辉。
露如今日泪，苔似昔年衣。
有恨同湘女，无言类楚妃。
寂然芳霭内，犹若待夫归。','',''),('quantangshi-08924','对雨','李白','quantangshi','','卷9','卷帘聊举目，露湿草绵芊。
古岫藏云毳，空庭织碎烟。
水纹愁不起，风线重难牵。
尽日扶犂叟，往来江树前。','',''),('quantangshi-08925','晓晴','李白','quantangshi','','卷9','野凉疎雨歇，春色徧萋萋。
鱼跃青池满，莺吟绿树低。
野花妆面湿，山草纽斜齐。
零落残雪片，风吹挂竹溪。','',''),('quantangshi-08926','初月','李白','quantangshi','','卷9','玉蟾离海上，白露湿花时。
云畔风生爪，沙头水浸眉。
乐哉弦管客，愁杀战征儿。
因绝西园赏，临风一咏诗。','',''),('quantangshi-08927','雨后望月','李白','quantangshi','','卷9','四郊阴霭散，开户半蟾生。
万里舒霜合，一条江练横。
出时山眼白，高后海心明。
为惜如团扇，长吟到五更。','',''),('quantangshi-08928','赋得鹤送史司马赴崔相公幕','李白','quantangshi','','卷9','峥嵘丞相府，清切凤凰池。
羡尔瑶台鹤，高栖琼树枝。
归飞晴日好，吟弄惠风吹。
正有乘轩乐，初当学舞时。
珍禽在罗网，微命若游丝。
愿托周周羽，相衔汉水湄。','',''),('quantangshi-08929','送客归吴','李白','quantangshi','','卷9','江村秋雨歇，酒尽一帆飞。
路历波涛去，家惟坐卧归。
岛花开灼灼，汀柳细依依。
别后无余事，还应埽钓矶。','',''),('quantangshi-08930','送友生游峡中','李白','quantangshi','','卷9','风静杨柳垂，看花又别离。
几年同在此，今日各驱驰。
峡里闻猨呌，山头见月时。
殷勤一杯酒，珍重岁寒姿。','',''),('quantangshi-08931','送袁明府任长沙','李白','quantangshi','','卷9','别离杨柳青，樽酒表丹诚。
古道携琴去，深山见峡迎。
暖风花绕树，秋雨草沿城。
自此长江内，无因夜犬惊。','',''),('quantangshi-08932','邹衍谷','李白','quantangshi','','卷9','燕谷无暖气，穷岩闭严阴。
邹子一吹律，能回天地心。','',''),('quantangshi-08933','杂言用投丹阳知己兼奉宣慰判官','李白','quantangshi','','卷9','客从昆仑来，遗我双玉璞。
云是古之得道者西王母食之余，食之可以凌太虚。
受之颇谓绝今昔，求识江淮人犹乎比石。
如今虽在卞和手，□□正憔悴。
了了知之亦何益，恭闻士有调相如。
始从镐京还，复欲镐京去。
能上秦王殿，何时回光一相眄。
欲投君，保君年，幸君持取无弃捐。
无弃捐，服之与君俱神仙。','',''),('quantangshi-08934','观鱼潭','李白','quantangshi','','卷9','观鱼碧潭上，木落潭水清。
日暮紫鳞跃，圆波处处生。
凉烟浮竹尽，秋月照沙明。
何必沧浪去，兹焉可濯缨。','',''),('quantangshi-08935','自广平乘醉走马六十里至邯郸登城楼览古书怀','李白','quantangshi','','卷9','醉骑白花马，西走邯郸城。
扬鞭动柳色，写鞚春风生。
入郭登高楼，山川与云平。
深宫翳绿草，万事伤人情。
相如章华巅，猛气折秦嬴。
两虎不可鬬，廉公终负荆。
提携袴中儿，杵臼及程婴。
立孤就白刃，必死耀丹诚。
平原三千客，谈笑尽豪英。
毛君能頴脱，二国且同盟。
皆为黄泉土，使我涕纵横。
磊磊石子冈，萧萧白杨声。
诸贤没此地，碑版有残铭。
太古共今时，由来互哀荣。
伤哉何足道，感激仰空名。
赵俗爱长劒，文儒少逢迎。
闲从博陵游，畅饮雪朝酲。
歌酣易水动，鼓震丛台倾。
日落把烛归，凌晨向燕京。
方陈五饵策，一使胡尘清。','',''),('quantangshi-08936','宣州长史弟昭赠余琴溪中双舞鹤诗以见志','李白','quantangshi','','卷9','令弟佐宣城，赠余琴溪鹤。
谓言天涯雪，忽向窗前落。
白玉为毛衣，黄金不肯博。
背风振六翮，对舞临山阁。
顾我如有情，长鸣似相托。
何当驾此物，与尔腾寥廓。','',''),('quantangshi-08937','题舒州司空山瀑布','李白','quantangshi','','卷9','断崖如削瓜，岚光破崖绿。
天河从中来，白云涨川谷。
玉案赤文字，世眼不可读。
摄身凌青霄，松风拂我足。','',''),('quantangshi-08938','金陵新亭','李白','quantangshi','','卷9','金陵风景好，豪士集新亭。
举目山河异，偏伤周顗情。
四坐楚囚悲，不忧社稷倾。
王公何慷慨，千载仰雄名。','',''),('quantangshi-08939','上清宝鼎诗 一','李白','quantangshi','','卷9','我居清空表，君处红埃中。
仙人持玉尺，废君多少才。
玉尺不可尽，君才无时休。','',''),('quantangshi-08940','上清宝鼎诗 二','李白','quantangshi','','卷9','咽服十二环，奄有仙人房。
暮骑紫麟去，海气侵肌凉。
赠我累累珠，靡靡明月光。','',''),('quantangshi-08941','题许宣平庵壁','李白','quantangshi','','卷9','我吟传舍咏，来访真人居。
烟岭迷高迹，云林隔太虚。
窥庭但萧瑟，倚杖空踌躇。
应化辽天鹤，归当千岁余。','',''),('quantangshi-08942','戏赠杜甫','李白','quantangshi','','卷9','饭颗山头逢杜甫，顶戴笠子日卓午。
借问别来太瘦生，总为从前作诗苦。','',''),('quantangshi-08943','春感诗','李白','quantangshi','','卷9','茫茫南与北，道直事难谐。
榆荚钱生树，杨花玉糁街。
尘萦游子面，蝶弄美人钗。
却忆青山上，云门掩竹斋。','',''),('quantangshi-08944','白微时募县小吏入令卧内尝驱牛经堂下令妻怒将加诘责白亟以诗谢云','李白','quantangshi','','卷9','素面倚栏钩，娇声出外头。
若非是织女，何得问牵牛。','',''),('quantangshi-08945','句','李白','quantangshi','','卷9','焰随红日去，烟逐暮云飞。
绿鬓随波散，红颜逐浪无。
因何逢伍相，应是想秋胡。
举袖露条脱，招我饭胡麻。','',''),('quantangshi-08946','拟古诗十二首 一','韋應物','quantangshi','','卷9','辞君远行迈，饮此长恨端。
已谓道里远，如何中险艰。
流水赴大壑，孤云还暮山。
无情尚有归，行子何独难。
驱车背乡园，朔风卷行迹。
严冬霜断肌，日入不遑息。
忧欢容发变，寒暑人事易。
中心君讵知，冰玉徒贞白。','',''),('quantangshi-08947','拟古诗十二首 二','韋應物','quantangshi','','卷9','黄鸟何关关，幽兰亦靡靡。
此时深闺妇，日照纱窗里。
娟娟双青娥，微微启玉齿。
自惜桃李年，误身游侠子。
无事久离别，不知今生死。','',''),('quantangshi-08948','拟古诗十二首 三','韋應物','quantangshi','','卷9','峨峨高山巅，浼浼青川流。
世人不自悟，驰谢如惊飍。
百金非所重，厚意良难得。
旨酒亲与朋，芳年乐京国。
京城繁华地，轩盖凌晨出。
垂杨十二衢，隐暎金张室。
汉宫南北对，飞观齐白日。
游泳属芳时，平生自云毕。','',''),('quantangshi-08949','拟古诗十二首 四','韋應物','quantangshi','','卷9','绮楼何氛氲，朝日正杲杲。
四壁含清风，丹霞射其牖。
玉颜上哀啭，绝耳非世有。
但感离恨情，不知谁家妇。
孤云忽无色，边马为回首。
曲绝碧天高，余声散秋草。
徘徊帷中意，独夜不堪守。
思逐朔风翔，一去千里道。','',''),('quantangshi-08950','拟古诗十二首 五','韋應物','quantangshi','','卷9','嘉树蔼初绿，靡芜吐幽芳。
君子不在赏，寄之云路长。
路长信难越，惜此芳时歇。
孤鸟去不还，缄情向天末。','',''),('quantangshi-08951','拟古诗十二首 六','韋應物','quantangshi','','卷9','月满秋夜长，惊乌号北林。
天河横未落，斗柄当西南。
寒蛩悲洞房，好鸟无遗音。
商飙一夕至，独宿怀重衾。
旧交日千里，隔我浮与沈。
人生岂草木，寒暑移此心。','',''),('quantangshi-08952','拟古诗十二首 七','韋應物','quantangshi','','卷9','酒星非所酌，月桂不为食。
虚薄空有名，为君长叹息。
兰蕙虽可怀，芳香与时息。
岂如凌霜叶，岁暮蔼颜色。
折柔将有赠，延意千里客。
草木知贱微，所贵寒不易。','',''),('quantangshi-08953','拟古诗十二首 八','韋應物','quantangshi','','卷9','神州高爽地，遐瞰靡不通。
寒月野无绿，寥寥天宇空。
阴阳不停驭，贞脆各有终。
汾沮何鄙俭，考盘何退穷。
反志解牵局，无为尚劳躬。
美人夺南国，一笑开芙蓉。
清镜理容发，褰帘出深重。
艳曲呈皓齿，舞罗不堪风。
慊慊情有待，赠芳为我容。
可嗟青楼月，流影君帷中。','',''),('quantangshi-08954','拟古诗十二首 九','韋應物','quantangshi','','卷9','春至林木变，洞房夕含清。
单居谁能裁，好鸟对我鸣。
良人久燕赵，新爱移平生。
别时双鸳绮，留此千恨情。
碧草生旧迹，绿琴歇芳声。
思将魂梦欢，反侧寐不成。
揽衣迷所次，起望空前庭。
孤影中自恻，不知双涕零。','',''),('quantangshi-08955','拟古诗十二首 十','韋應物','quantangshi','','卷9','秋天无留景，万物藏光辉。
落叶随风起，愁人独何依。
华月屡圆缺，君还浩无期。
如何雨绝天，一去音问违。','',''),('quantangshi-08956','拟古诗十二首 十一','韋應物','quantangshi','','卷9','有客天一方，寄我孤桐琴。
迢迢万里隔，托此传幽音。
冰霜中自结，龙凤相与吟。
弦以明直道，漆以固交深。','',''),('quantangshi-08957','拟古诗十二首 十二','韋應物','quantangshi','','卷9','白日淇上没，空闺生远愁。
寸心不可限，淇水长悠悠。
芳树自妍芳，春禽自相求。
徘徊东西厢，孤妾谁与俦。
年华逐丝泪，一落俱不收。','',''),('quantangshi-08958','杂体五首 一','韋應物','quantangshi','','卷9','沈沈匣中镜，为此尘垢蚀。
辉光何所如，月在云中黑。
南金既雕错，鞶带共辉饰。
空存鉴物名，坐使妍蚩惑。
美人竭肝胆，思照冰玉色。
自非磨莹工，日日空叹息。','',''),('quantangshi-08959','杂体五首 二','韋應物','quantangshi','','卷9','古宅集祆鸟，羣号枯树枝。
黄昏窥人室，鬼物相与期。
居人不安寝，搏击思此时。
岂无鹰与鹯，饱肉不肯飞。
既乖逐鸟节，空养凌云姿。
孤负肉食恩，何异城上鸱。','',''),('quantangshi-08960','杂体五首 三','韋應物','quantangshi','','卷9','春罗双鸳鸯，出自寒夜女。
心精烟雾色，指历千万绪。
长安贵豪家，妖艳不可数。
裁此百日功，唯将一朝舞。
舞罢复裁新，岂思劳者苦。','',''),('quantangshi-08961','杂体五首 四','韋應物','quantangshi','','卷9','同声自相应，体质不必齐。
谁知贾人铎，能使大乐谐。
铿锵发宫征，和乐变其哀。
人神既昭享，凤鸟亦下来。
岂非至贱物，一奏升天阶。
物情苟有合，莫问玉与泥。','',''),('quantangshi-08962','杂体五首 五','韋應物','quantangshi','','卷9','碌碌荆山璞，卞和献君门。
荆璞非有求，和氏非有恩。
所献知国宝，至公不待言。
是非吾欲默，此道今岂存。','',''),('quantangshi-08963','与友生野饮效陶体','韋應物','quantangshi','','卷9','携酒花林下，前有千载坟。
于时不共酌，奈此泉下人。
始自翫芳物，行当念徂春。
聊舒远世踪，坐望还山云。
且遂一欢笑，焉知贱与贫。','',''),('quantangshi-08964','效何水部二首 一','韋應物','quantangshi','','卷9','玉宇含清露，香笼散轻烟。
应当结沈抱，难从兹夕眠。','',''),('quantangshi-08965','效何水部二首 二','韋應物','quantangshi','','卷9','夕漏起遥恨，虫响乱秋阴。
反覆相思字，中有故人心。','',''),('quantangshi-08966','效陶彭泽','韋應物','quantangshi','','卷9','霜露悴百草，时菊独妍华。
物性有如此，寒暑其奈何。
掇英泛浊醪，日入会田家。
尽醉茅檐下，一生岂在多。','',''),('quantangshi-08967','大梁亭会李四栖梧作','韋應物','quantangshi','','卷9','梁王昔爱才，千古化不泯。
至今蓬池上，远集八方宾。
车马平明合，城郭满埃尘。
逢君一相许，岂要平生亲。
入仕三十载，如何独未伸。
英声久籍籍，台阁多故人。
置酒发清弹，相与乐佳辰。
孤亭得长望，白日下广津。
富贵良可取，朅来西入秦。
秋风旦夕起，安得客梁陈。','',''),('quantangshi-08968','燕李录事','韋應物','quantangshi','','卷9','与君十五侍皇闱，晓拂炉烟上赤墀。
花开汉苑经过处，雪下骊山沐浴时。
近臣零落今犹在，仙驾飘颻不可期。
此日相逢思旧日，一杯成喜亦成悲。','',''),('quantangshi-08969','淮上喜会梁川故人','韋應物','quantangshi','','卷9','江汉曾为客，相逢每醉还。
浮云一别后，流水十年间。
欢笑情如旧，萧疎鬓已斑。
何因北归去，淮上对秋山。','',''),('quantangshi-08970','扬州偶会前洛阳卢耿主簿','韋應物','quantangshi','','卷9','楚塞故人稀，相逢本不期。
犹存袖里字，忽怪鬓中丝。
客舍盈樽酒，江行满箧诗。
更能连骑出，还似洛桥时。','',''),('quantangshi-08971','贾常侍林亭燕集','韋應物','quantangshi','','卷9','高贤侍天陛，迹显心独幽。
朱轩骛关右，池馆在东周。
缭绕接都城，氤氲望嵩丘。
羣公尽词客，方驾永日游。
朝旦气候佳，逍遥写烦忧。
绿林蔼已布，华沼澹不流。
没露摘幽草，涉烟翫轻舟。
圆荷既出水，广厦可淹留。
放神遗所拘，觥罚屡见酬。
乐燕良未极，安知有沈浮。
醉罢各云散，何当复相求。','',''),('quantangshi-08972','月下会徐十一草堂','韋應物','quantangshi','','卷9','空斋无一事，岸帻故人期。
暂辍观书夜，还题翫月诗。
远钟高枕后，清露卷帘时。
暗觉新秋近，残河欲曙迟。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-08973','移疾会诗客元生与释子法朗因贻诸祠曹','韋應物','quantangshi','','卷9','对此嘉树林，独有戚戚颜。
抱瘵知旷职，淹旬非乐闲。
释子来问讯，诗人亦扣关。
道同意暂遣，客散疾徐还。
园径自幽静，玄蝉噪其间。
高牕瞰远郊，暮色起秋山。
英曹幸休暇，悢悢心所攀。','',''),('quantangshi-08974','慈恩伽蓝清会','韋應物','quantangshi','','卷9','素友俱薄世，屡招清景赏。
鸣钟悟音闻，宿昔心已往。
重门相洞达，高宇亦遐朗。
岚岭晓城分，清阴夏条长。
氲氛芳台馥，萧散竹池广。
平荷随波泛，廻飙激林响。
蔬食遵道侣，泊怀遗滞想。
何彼尘昏人，区区在天壤。','',''),('quantangshi-08975','夜偶诗客操公作','韋應物','quantangshi','','卷9','尘襟一潇洒，清夜得禅公。
远自鹤林寺，了知人世空。
惊禽翻暗叶，流水注幽丛。
多谢非玄度，聊将诗兴同。','',''),('quantangshi-08976','与韩库部会王祠曹宅作','韋應物','quantangshi','','卷9','闲门荫堤柳，秋渠含夕清。
微风送荷气，坐客散尘缨。
守默共无恡，抱冲俱寡营。
良时颇高会，琴酌共开情。','',''),('quantangshi-08977','晦日处士叔园林燕集','韋應物','quantangshi','','卷9','遽看蓂叶尽，坐阙芳年赏。
赖此林下期，清风涤烦想。
始萌动新煦，佳禽发幽响。
岚岭对高斋，春流灌蔬壤。
罇酒遗形迹，道言屡开奖。
幸蒙终夕懽，聊用税归鞅。','',''),('quantangshi-08978','扈亭西陂燕赏','韋應物','quantangshi','','卷9','杲杲朝阳时，悠悠清陂望。
嘉树始氤氲，春游方浩荡。
况逢文翰侣，爱此孤舟漾。
绿野际遥波，横云分叠嶂。
公堂日为倦，幽襟自兹旷。
有酒今满盈，愿君尽弘量。','',''),('quantangshi-08979','西郊燕集','韋應物','quantangshi','','卷9','济济众君子，高宴及时光。
羣山霭遐瞩，绿野布熙阳。
列坐遵曲岸，披襟袭兰芳。
野庖荐嘉鱼，激涧泛羽觞。
众鸟鸣茂林，绿草延高冈。
盛时易徂谢，浩思坐飘扬。
眷言同心友，兹游安可忘。','',''),('quantangshi-08980','春宵燕万年吉少府中孚南馆','韋應物','quantangshi','','卷9','始见斗柄廻，复兹霜月霁。
河汉上纵横，春城夜迢递。
宾筵接时彦，乐燕凌芳岁。
稍爱清觞满，仰叹高文丽。
欲去返郊扉，端为一欢滞。','',''),('quantangshi-08981','滁州园池燕元氏亲属','韋應物','quantangshi','','卷9','日暮游清池，疎林罗高天。
余绿飘霜露，夕气变风烟。
水门架危阁，竹亭列广筵。
一展私姻礼，屡叹芳樽前。
感往在兹会，伤离属頽年。
明晨复云去，且愿此流连。','',''),('quantangshi-08982','郡楼春燕','韋應物','quantangshi','','卷9','众乐杂军鞞，高楼邀上客。
思逐花光乱，赏余山景夕。
为郡访雕瘵，守程难损益。
聊假一杯欢，暂忘终日迫。','',''),('quantangshi-08983','南塘泛舟会元六昆季','韋應物','quantangshi','','卷9','端居倦时燠，轻舟泛廻塘。
微风飘襟散，横吹绕林长。
云澹水容夕，雨微荷气凉。
一写悁勤意，宁用诉华觞。','',''),('quantangshi-08984','郡斋雨中与诸文士燕集','韋應物','quantangshi','','卷9','兵卫森画戟，宴寝凝清香。
海上风雨至，逍遥池阁凉。
烦疴近消散，嘉宾复满堂。
自慙居处崇，未覩斯民康。
理会是非遣，性达形迹忘。
鲜肥属时禁，蔬果幸见尝。
俯饮一杯酒，仰聆金玉章。
神欢体自轻，意欲凌风翔。
吴中盛文史，羣彦今汪洋。
方知大藩地，岂曰财赋疆。','',''),('quantangshi-08985','军中冬燕','韋應物','quantangshi','','卷9','沧海已云晏，皇恩犹念勤。
式燕徧恒秩，柔远及斯人。
兹邦实大藩，伐鼓军乐陈。
是时冬服成，戎士气益振。
虎竹谬朝寄，英贤降上宾。
旋罄周旋礼，愧无海陆珍。
庭中九剑阑，堂上歌吹新。
光景不知晚，觥酌岂言频。
单醪昔所感，大醵况同忻。
顾谓军中士，仰答何由申。','',''),('quantangshi-08986','司空主簿琴席','韋應物','quantangshi','','卷9','烟华方散薄，蕙气犹含露。
澹景发清琴，幽期默玄悟。
流连白雪意，断续廻风度。
掩抑虽已终，忡忡在幽素。','',''),('quantangshi-08987','与村老对饮','韋應物','quantangshi','','卷9','鬓眉雪色犹嗜酒，言辞淳朴古人风。
乡村年少生离乱，见话先朝如梦中。','',''),('quantangshi-08988','城中卧疾知阎薛二子屡从邑令饮因以赠之','韋應物','quantangshi','','卷9','车马日萧萧，胡不枉我庐。
方来从令饮，卧病独何如。
秋风起汉臯，开户望平芜。
即此恡音素，焉知中密疎。
渴者不思火，寒者不求水。
人生羁寓时，去就当如此。
犹希心异迹，眷眷存终始。','',''),('quantangshi-08989','听嘉陵江水声寄深上人','韋應物','quantangshi','','卷9','凿崖泄奔湍，称古神禹迹。
夜喧山门店，独宿不安席。
水性自云静，石中本无声。
如何两相激，雷转空山惊。
贻之道门旧，了此物我情。','',''),('quantangshi-08990','高陵书情寄三原卢少府','韋應物','quantangshi','','卷9','直方难为进，守此微贱班。
开卷不及顾，沈埋案牍间。
兵凶久相践，徭赋岂得闲。
促戚下可哀，宽政身致患。
日夕思自退，出门望故山。
君心傥如此，携手相与还。','',''),('quantangshi-08991','假中对雨呈县中僚友','韋應物','quantangshi','','卷9','却足甘为笑，闲居梦杜陵。
残莺知夏浅，社雨报年登。
流麦非关忘，收书独不能。
自然忧旷职，缄此谢良朋。','',''),('quantangshi-08992','赠萧河南','韋應物','quantangshi','','卷9','厌剧辞京县，褒贤待诏书。
酇侯方继业，潘令且闲居。
霁后三川冷，秋深万木疎。
对琴无一事，新兴复何如。','',''),('quantangshi-08993','示从子河南尉班','韋應物','quantangshi','','卷9','拙直余恒守，公方尔所存。
同占朱鸟克，俱起小人言。
立政思悬棒，谋身类触藩。
不能林下去，祗恋府廷恩。','',''),('quantangshi-08994','趋府候晓呈两县僚友','韋應物','quantangshi','','卷9','趋府不遑安，中宵出户看。
满天星尚在，近壁烛仍残。
立马频惊曙，垂帘却避寒。
可怜同宦者，应悟下流难。','',''),('quantangshi-08995','赠李儋','韋應物','quantangshi','','卷9','丝桐本异质，音响合自然。
吾观造化意，二物相因缘。
误触龙凤啸，静闻寒夜泉。
心神自安宅，烦虑顿可捐。
何因知久要，丝白漆亦坚。','',''),('quantangshi-08996','赠卢嵩','韋應物','quantangshi','','卷9','百川注东海，东海无虚盈。
泥滓不能浊，澄波非益清。
恬然自安流，日照万里晴。
云物不隐象，三山共分明。
奈何疾风怒，忽若砥柱倾。
海水虽无心，洪涛亦相惊。
怒号在倏忽，谁识变化情。','',''),('quantangshi-08997','寄冯着','韋應物','quantangshi','','卷9','春雷起萌蛰，土壤日已疎。
胡能遭盛明，才俊伏里闾。
偃仰遂真性，所求惟斗储。
披衣出茅屋，盥漱临清渠。
吾道亦自适，退身保玄虚。
幸无职事牵，且览案上书。
亲友各驰骛，谁当访敝庐。
思君在何夕，明月照广除。','',''),('quantangshi-08998','早春对雪寄前殿中元侍御','韋應物','quantangshi','','卷9','扫雪开幽径，端居望故人。
犹残腊月酒，更值早梅春。
几日东城陌，何时曲水滨。
闻闲且共赏，莫待绣衣新。','',''),('quantangshi-08999','赠王侍御','韋應物','quantangshi','','卷9','心同野鹤与尘远，诗似冰壶见底清。
府县同趋昨日事，升沈不改故人情。
上阳秋晚萧萧雨，洛水寒来夜夜声。
自叹犹为折腰吏，可怜骢马路傍行。','',''),('quantangshi-09000','将往江淮寄李十九儋','韋應物','quantangshi','','卷9','燕燕东向来，文鵷亦西飞。
如何不相见，羽翼有高卑。
徘徊到河洛，华屋未及窥。
秋风飘我行，远与淮海期。
廻首隔烟雾，遥遥两相思。
阳春自当返，短翮欲追随。','',''),('quantangshi-09001','自巩洛舟行入黄河即事寄府县僚友','韋應物','quantangshi','','卷9','夹水苍山路向东，东南山豁大河通。
寒树依微远天外，夕阳明灭乱流中。
孤村几岁临伊岸，一雁初晴下朔风。
为报洛桥游宦侣，扁舟不系与心同。','',''),('quantangshi-09002','寄卢庾','韋應物','quantangshi','','卷9','悠悠远离别，分此欢会难。
如何两相近，反使心不安。
乱发思一栉，垢衣思一浣。
岂如望友生，对酒起长叹。
时节异京洛，孟冬天未寒。
广陵多车马，日夕自游盘。
独我何耿耿，非君谁为欢。','',''),('quantangshi-09003','发广陵留上家兄兼寄上长沙','韋應物','quantangshi','','卷9','将违安可怀，宿恋复一方。
家贫无旧业，薄宦各飘扬。
执板身有属，淹时心恐惶。
拜言不得留，声结泪满裳。
漾漾动行舫，亭亭远相望。
离晨苦须臾，独往道路长。
萧条风雨过，得此海气凉。
感秋意已违，况自结中肠。
推道固当遣，及情岂所忘。
何时共还归，举翼鸣春阳。','',''),('quantangshi-09004','初发扬子寄元大校书','韋應物','quantangshi','','卷9','凄凄去亲爱，泛泛入烟雾。
归棹洛阳人，残钟广陵树。
今朝此为别，何处还相遇。
世事波上舟，沿洄安得住。','',''),('quantangshi-09005','淮上即事寄广陵亲故','韋應物','quantangshi','','卷9','前舟已眇眇，欲渡谁相持。
秋山起暮钟，楚雨连沧海。
风波离思满，宿昔容鬓改。
独鸟下东南，广陵何处在。','',''),('quantangshi-09006','寄洪州幕府二十一侍御','韋應物','quantangshi','','卷9','忽报南昌令，乘骢入郡城。
同时趋府客，此日望尘迎。
文苑台中妙，冰壶幕下清。
洛阳相去远，犹使故林荣。','',''),('quantangshi-09007','经少林精舍寄都邑亲友','韋應物','quantangshi','','卷9','息驾依松岭，高阁一攀缘。
前瞻路已穷，既诣喜更延。
出巘听万籁，入林濯幽泉。
鸣钟生道心，暮磬空云烟。
独往虽暂适，多累终见牵。
方思结茅地，归息期暮年。','',''),('quantangshi-09008','同长源归南徐寄子西子烈有道','韋應物','quantangshi','','卷9','东洛何萧条，相思邈遐路。
策驾复谁游，入门无与晤。
还因送归客，达此缄中素。
屡暌心所欢，岂得颜如故。
所欢不可暌，严霜晨凄凄。
如彼万里行，孤妾守空闺。
临觞一长叹，素欲何时谐。','',''),('quantangshi-09009','雪中闻李儋过门不访聊以寄赠','韋應物','quantangshi','','卷10','度门能不访，冒雪屡西东。
已想人如玉，遥怜马似骢。
乍迷金谷路，稍变上阳宫。
还比相思意，纷纷正满空。','',''),('quantangshi-09010','同德精舍养疾寄河南兵曹东厅掾','韋應物','quantangshi','','卷10','逍遥东城隅，双树寒葱蒨。
广庭流华月，高阁凝余霰。
杜门非养素，抱疾阻良宴。
孰谓无他人，思君岁云变。
官曹亮先忝，陈躅慙俊彦。
岂知晨与夜，相代不相见。
缄书问所如，酬藻当芬绚。','',''),('quantangshi-09011','同德寺雨后寄元侍御李博士','韋應物','quantangshi','','卷10','川上风雨来，须臾满城阙。
岧峣青莲界，萧条孤兴发。
前山遽已净，阴霭夜来歇。
乔木生夏凉，流云吐华月。
严城自有限，一水非难越。
相望曙河远，高斋坐超忽。','',''),('quantangshi-09012','同德阁期元侍御李博士不至各投赠二首 一','韋應物','quantangshi','','卷10','庭树忽已暗，故人那不来。
祗因厌烦暑，永日坐霜台。','',''),('quantangshi-09013','同德阁期元侍御李博士不至各投赠二首 二','韋應物','quantangshi','','卷10','官荣多所系，闲居亦愆期。
高阁犹相望，青山欲暮时。','',''),('quantangshi-09014','使云阳寄府曹','韋應物','quantangshi','','卷10','夙驾祗府命，冒炎不遑息。
百里次云阳，闾阎问漂溺。
上天屡愆气，胡不均寸泽。
仰瞻乔树巅，见此洪流迹。
良苗免湮没，蔓草生宿昔。
颓墉满故墟，喜返将安宅。
周旋涉涂潦，侧峭缘沟脉。
仁贤忧斯民，贱子甘所役。
公堂众君子，言笑思与觌。','',''),('quantangshi-09015','过扶风精舍旧居简朝宗巨川兄弟','韋應物','quantangshi','','卷10','佛刹出高树，晨光闾井中。
年深念陈迹，迨此独忡忡。
零落逢故老，寂寥悲草虫。
旧宇多改构，幽篁延本丛。
栖止事如昨，芳时去已空。
佳人亦携手，再往今不同。
新文聊感旧，想子意无穷。','',''),('quantangshi-09016','赠令狐士曹','韋應物','quantangshi','','卷10','秋檐滴滴对牀寝，山路迢迢联骑行。
到家俱及东篱菊，何事先归半日程。','',''),('quantangshi-09017','赠冯着','韋應物','quantangshi','','卷10','契阔仕两京，念子亦飘蓬。
方来属追往，十载事不同。
岁晏乃云至，微褐还未充。
惨凄游子情，风雪自关东。
华觞发懽颜，嘉藻播清风。
始此盈抱恨，旷然一夕中。
善蕴岂轻售，怀才希国工。
谁当念素士，零落岁华空。','',''),('quantangshi-09018','对雨寄韩库部协','韋應物','quantangshi','','卷10','飒至池馆凉，霭然和晓雾。
萧条集新荷，氤氲散高树。
闲居兴方澹，默想心已屡。
暂出仍湿衣，况君东城住。','',''),('quantangshi-09019','寄子西','韋應物','quantangshi','','卷10','夏景已难度，怀贤思方续。
乔树落疎阴，微风散烦燠。
伤离枉芳札，忻遂见心曲。
蓝上舍已成，田家雨新足。
托邻素多欲，残帙犹见束。
日夕上高斋，但望东原绿。','',''),('quantangshi-09020','县内闲居赠温公','韋應物','quantangshi','','卷10','满郭春[风]岚已昏，鸦栖散吏掩重门。
虽居世网常清净，夜对高僧无一言。','',''),('quantangshi-09021','对雪赠徐秀才','韋應物','quantangshi','','卷10','靡靡寒欲收，霭霭阴还结。
晨起望南端，千林散春雪。
妍光属瑶阶，乱绪陵新节。
无为掩扉卧，独守袁生辙。','',''),('quantangshi-09022','西郊游宴寄赠邑僚李巽','韋應物','quantangshi','','卷10','升阳暧春物，置酒临芳席。
高宴阙英僚，众宾寡懽怿。
是时尚多垒，板筑兴颓壁。
羇旅念越疆，领徒方祗役。
如何嘉会日，当子忧勤夕。
西郊郁已茂，春岚重如积。
何当返徂雨，杂英纷可惜。','',''),('quantangshi-09023','对雨赠李主簿高秀才','韋應物','quantangshi','','卷10','逦迤曙云薄，散漫东风来。
青山满春野，微雨洒轻埃。
吏局劳佳士，宾筵得上才。
终朝狎文墨，高兴共徘徊。','',''),('quantangshi-09024','休沐东还胄贵里示端','韋應物','quantangshi','','卷10','宦游三十载，田野久已疎。
休沐遂兹日，一来还故墟。
山明宿雨霁，风暖百卉舒。
泓泓野泉洁，熠熠林光初。
竹木稍摧翳，园场亦荒芜。
俯惊鬓已衰，周览昔所娱。
存没恻私怀，迁变伤里闾。
欲言少留心，中复畏简书。
世道良自退，荣名亦空虚。
与子终携手，岁晏当来居。','',''),('quantangshi-09025','朝请后还邑寄诸友生','韋應物','quantangshi','','卷10','宰邑分甸服，夙驾朝上京。
是时当暮春，休沐集友生。
抗志青云表，俱践高世名。
樽酒且欢乐，文翰亦纵横。
良游昔所希，累宴夜复明。
晨露含瑶琴，夕风殒素英。
一旦遵归路，伏轼出京城。
谁言再念别，忽若千里行。
闲合寡喧讼，端居结幽情。
况兹昼方永，展转何由平。','',''),('quantangshi-09026','沣上西斋寄诸友','韋應物','quantangshi','','卷10','绝岸临西野，旷然尘事遥。
清川下逦迤，茅栋上岧峣。
翫月爱佳夕，望山属清朝。
俯砌视归翼，开襟纳远飙。
等陶辞小秩，效朱方负樵。
闲游忽无累，心迹随景超。
明世重才彦，雨露降丹霄。
羣公正云集，独予忻寂寥。','',''),('quantangshi-09027','独游西斋寄崔主簿','韋應物','quantangshi','','卷10','同心忽已别，昨事方成昔。
幽径还独寻，绿苔见行迹。
秋斋正萧散，烟水易昏夕。
忧来结几重，非君不可释。','',''),('quantangshi-09028','紫阁东林居士叔缄赐松英丸捧对忻喜盖非尘侣之所当服輙献诗代启','韋應物','quantangshi','','卷10','碧涧苍松五粒稀，侵云采去露沾衣。
夜启羣仙合灵药，朝思俗侣寄将归。
道场斋戒今初服，人事荤膻已觉非。
一望岚峰拜还使，腰间铜印与心违。','',''),('quantangshi-09029','秋集罢还途中作谨献寿春公黎公','韋應物','quantangshi','','卷10','束带自衡门，奉命宰王畿。
君侯枉高鉴，举善掩瑕疵。
斯民本已安，工拙两无施。
何以酬明德，岁晏不磷缁。
时节乃来集，欣怀方载驰。
平明大府开，一得拜光辉。
温如春风至，肃若严霜威。
羣属所载瞻，而忘倦与饥。
公堂燕华筵，礼罢复言辞。
将从平门道，憩车沣水湄。
山川降嘉岁，草木蒙润滋。
孰云还本邑，怀恋独迟迟。','',''),('quantangshi-09030','闲居赠友','韋應物','quantangshi','','卷10','补吏多下迁，罢归聊自度。
园庐既芜没，烟景空澹泊。
闲居养疴瘵，守素甘葵藿。
颜鬓日衰耗，冠带亦寥落。
青苔已生路，绿筠始分箨。
夕气下遥阴，微风动疎薄。
草玄良见诮，杜门无请托。
非君好事者，谁来顾寂寞。','',''),('quantangshi-09031','四禅精舍登览悲旧寄朝宗巨川兄弟','韋應物','quantangshi','','卷10','萧散人事忧，迢遰古原行。
春风日已暄，百草亦复生。
跻阁谒金像，攀云造禅扃。
新景林际曙，杂花川上明。
徂岁方缅邈，陈事尚纵横。
温泉有佳气，驰道指京城。
携手思故日，山河留恨情。
存者邈难见，去者已冥冥。
临风一长恸，谁畏行路惊。','',''),('quantangshi-09032','善福阁对雨寄李儋幼遐','韋應物','quantangshi','','卷10','飞阁凌太虚，晨跻郁峥嵘。
惊飙触悬槛，白云冒层甍。
太阴布其地，密雨垂八纮。
仰观固不测，俯视但冥冥。
感此穷秋气，沈郁命友生。
及时未高步，羇旅游帝京。
圣朝无隐才，品物俱昭形。
国士秉绳墨，何以表坚贞。
寸心东北驰，思与一会并。
我车夙已驾，将逐晨风征。
郊涂住成淹，默默阻中情。','',''),('quantangshi-09033','寺居独夜寄崔主簿','韋應物','quantangshi','','卷10','幽人寂不寐，木叶纷纷落。
寒雨暗深更，流萤度高阁。
坐使青灯晓，还伤夏衣薄。
宁知岁方晏，离居更萧索。','',''),('quantangshi-09034','九日沣上作寄崔主簿倬二李端击','韋應物','quantangshi','','卷10','凄凄感时节，望望临沣涘。
翠岭明华秋，高天澄遥滓。
川寒流愈迅，霜交物初委。
林叶索已空，晨禽迎飙起。
时菊乃盈泛，浊醪自为美。
良游虽可娱，殷念在之子。
人生不自省，营欲无终已。
孰能同一酌，陶然冥斯理。','',''),('quantangshi-09035','西郊养疾闻畅校书有新什见赠久伫不至先寄此诗','韋應物','quantangshi','','卷10','养病惬清夏，郊园敷卉木。
牕夕含涧凉，雨余爱筠绿。
披怀始高咏，对琴转幽独。
仰子游羣英，吐词如兰馥。
还闻枉嘉藻，伫望延昏旭。
唯见草青青，闭户沣水曲。','',''),('quantangshi-09036','沣上寄幼遐','韋應物','quantangshi','','卷10','寂寞到城阙，惆怅返柴荆。
端居无所为，念子远徂征。
夏昼人已息，我怀独未宁。
忽从东斋起，兀兀寻涧行。
罥罣丛榛密，披玩孤花明。
旷然西南望，一极山水情。
周览同游处，逾恨阻音形。
壮图非旦夕，君子勤令名。
勿复久留燕，蹉跎在北京。','',''),('quantangshi-09037','善福精舍示诸生','韋應物','quantangshi','','卷10','湛湛嘉树阴，清露夜景沈。
悄然羣物寂，高阁似阴岑。
方以玄默处，岂为名迹侵。
法妙不知归，独此抱冲襟。
斋舍无余物，陶器与单衾。
诸生时列坐，共爱风满林。','',''),('quantangshi-09038','晚出沣上赠崔都水','韋應物','quantangshi','','卷10','临流一舒啸，望山意转延。
隔林分落景，余霞明远川。
首起趣东作，已看耘夏田。
一从民里居，岁月再徂迁。
昧质得全性，世名良自牵。
行忻携手归，聊复饮酒眠。','',''),('quantangshi-09039','寓居沣上精舍于张二舍人','韋應物','quantangshi','','卷10','万木丛云出香阁，西连碧涧竹林园。
高斋犹宿远山曙，微霰下庭寒雀喧。
道心淡泊对流水，生事萧疎空掩门。
时忆故交那得见，晓排阊阖奉明恩。','',''),('quantangshi-09040','开元观怀旧寄李二韩二裴四兼呈崔郎中严家令','韋應物','quantangshi','','卷10','宿昔清都燕，分散各西东。
车马行迹在，霜雪竹林空。
方轸故五念，谁复一樽同。
聊披道书暇，还此听松风。','',''),('quantangshi-09041','春日郊居寄万年吉少府中孚三原少府伟夏侯校书审','韋應物','quantangshi','','卷10','谷鸟时一啭，田园春雨余。
光风动林早，高牕照日初。
独饮涧中水，吟咏老氏书。
城阙应多事，谁忆此闲居。','',''),('quantangshi-09042','沣上醉题寄涤武','韋應物','quantangshi','','卷10','芳园知夕燕，西郊已独还。
谁言不同赏，俱是醉花间。','',''),('quantangshi-09043','西郊期涤武不至书示','韋應物','quantangshi','','卷10','山高鸣过雨，涧树落残花。
非关春不待，当由期自赊。','',''),('quantangshi-09044','沣上对月寄孔谏议','韋應物','quantangshi','','卷10','思怀在云阙，泊素守中林。
出处虽殊迹，明月两知心。','',''),('quantangshi-09045','将往滁城恋新竹简崔都水示端','韋應物','quantangshi','','卷10','停车欲去绕丛竹，偏爱新筠十数竿。
莫遣儿童触琼粉，留待幽人廻日看。','',''),('quantangshi-09046','还阙首途寄精舍亲友','韋應物','quantangshi','','卷10','休沐日云满，冲然将罢观。
严车候门侧，晨起正朝冠。
山泽含余雨，川涧注惊湍。
揽辔遵东路，廻首一长叹。
居人已不见，高阁在林端。','',''),('quantangshi-09047','秋夜南宫寄沣上弟及诸生','韋應物','quantangshi','','卷10','暝色起烟阁，沈抱积离忧。
况兹风雨夜，萧条梧叶秋。
空宇感凉至，颓颜惊岁周。
日夕游阙下，山水忆同游。','',''),('quantangshi-09048','途中书情寄沣上两弟因送二甥却还','韋應物','quantangshi','','卷10','华簪岂足恋，幽林徒自违。
遥知别后意，寂寞掩郊扉。
廻首昆池上，更羡尔同归。','',''),('quantangshi-09049','雪夜下朝呈省中一绝','韋應物','quantangshi','','卷10','南望青山满禁闱，晓陪鸳鹭正差池。
共爱朝来何处雪，蓬莱宫里拂松枝。','',''),('quantangshi-09050','寄柳州韩司户郎中','韋應物','quantangshi','','卷10','达识与昧机，智殊迹同静。
于焉得携手，屡赏清夜景。
潇洒陪高咏，从容羡华省。
一逐风波迁，南登桂阳岭。
旧里门空掩，欢游事皆屏。
怅望城阙遥，幽居时序永。
春风吹百卉，和煦变闾井。
独闷终日眠，篇书不复省。
唯当望雨露，霑子荒遐境。','',''),('quantangshi-09051','寄令狐侍郎','韋應物','quantangshi','','卷10','三山有琼树，霜雪色逾新。
始自风尘交，中结绸缪姻。
西掖方掌诰，南宫复司春。
夕燕华池月，朝奉玉阶尘。
众宝归和氏，吹嘘多俊人。
羣公共然诺，声问迈时伦。
孤鸿既高举，燕雀在荆榛。
翔集且不同，岂不欲殷勤。
一旦迁南郡，江湖渺无垠。
宠辱良未定，君子岂缁磷。
寒暑已推斥，别离生苦辛。
非将会面目，书札何由申。','',''),('quantangshi-09052','闲居寄端及重阳','韋應物','quantangshi','','卷10','山明野寺曙钟微，雪满幽林人迹稀。
闲居寥落生高兴，无事风尘独不归。','',''),('quantangshi-09053','园林晏起寄昭应韩明府卢主簿','韋應物','quantangshi','','卷10','田家已耕作，井屋起晨烟。
园林鸣好鸟，闲居犹独眠。
不觉朝已晏，起来望青天。
四体一舒散，情性亦忻然。
还复茅檐下，对酒思数贤。
束带理官府，简牍盈目前。
当念中林赏，览物遍山川。
上非遇明世，庶以道自全。','',''),('quantangshi-09054','寄大梁诸友','韋應物','quantangshi','','卷10','分竹守南谯，弭节过梁池。
雄都众君子，出饯拥河湄。
燕谑始云洽，方舟已解维。
一为风水便，但见山川驰。
昨日次睢阳，今夕宿符离。
云树怆重叠，烟波念还期。
相敦在勤事，海内方劳师。','',''),('quantangshi-09055','新秋夜寄诸弟','韋應物','quantangshi','','卷10','两地俱秋夕，相望共星河。
高梧一叶下，空斋归思多。
方用忧人瘼，况自抱微疴。
无将别来近，颜鬓已蹉跎。','',''),('quantangshi-09056','郊园闻蝉寄诸弟','韋應物','quantangshi','','卷10','去岁郊园别，闻蝉在兰省。
今岁卧南谯，蝉鸣归路永。
夕响依山谷，余悲散秋景。
缄书报此时，此心方耿耿。','',''),('quantangshi-09057','寄中书刘舍人','韋應物','quantangshi','','卷10','云霄路竟别，中年迹暂同。
比翼趋丹陛，连骑下南宫。
佳咏邀清月，幽赏滞芳藂。
迨予一出守，与子限西东。
晨露方怆怆，离抱更忡忡。
忽睹九天诏，秉纶归国工。
玉座浮香气，秋禁散凉风。
应向横门度，环佩杳玲珑。
光辉恨未瞩，归思坐难通。
苍苍松桂姿，想在掖垣中。','',''),('quantangshi-09058','郡斋感秋寄诸弟','韋應物','quantangshi','','卷10','首夏辞旧国，穷秋卧滁城。
方如昨日别，忽觉徂岁惊。
高阁收烟雾，池水晚澄清。
户牖已凄爽，晨夜感深情。
昔游郎署间，是月天气晴。
授衣还西郊，晓露田中行。
采菊投酒中，昆弟自同倾。
簪组聊挂壁，焉知有世荣。
一旦居远郡，山川间音形。
大道庶无累，及兹念已盈。','',''),('quantangshi-09059','郡中对雨赠元锡兼简杨凌','韋應物','quantangshi','','卷10','宿雨冒空山，空城响秋叶。
沈沈暮色至，凄凄凉气入。
萧条林表散，的砾荷上集。
夜雾着衣重，新苔侵履湿。
遇兹端忧日，赖与嘉宾接。','',''),('quantangshi-09060','冬至夜寄京师诸弟兼怀崔都水','韋應物','quantangshi','','卷10','理郡无异政，所忧在素飡。
徒令去京国，羁旅当岁寒。
子月生一气，阳景极南端。
已怀时节感，更抱别离酸。
私燕席云罢，还斋夜方阑。
邃幕沈空宇，孤灯照牀单。
应同兹夕念，宁忘故岁欢。
川途恍悠邈，涕下一阑干。','',''),('quantangshi-09061','元日寄诸弟兼呈崔都水','韋應物','quantangshi','','卷10','一从守兹郡，两鬓生素发。
新正加我年，故岁去超忽。
淮滨益时候，了似仲秋月。
川谷风景温，城池草木发。
高斋属多暇，惆怅临芳物。
日月昧还期，念君何时歇。','',''),('quantangshi-09062','寄职方刘郎中','韋應物','quantangshi','','卷10','相闻二十载，不得展平生。
一夕南宫遇，聊用写中情。
端服光朝次，羣烈慕英声。
归来坐粉闱，挥笔乃纵横。
始陪文翰游，欢燕难久并。
予因谬忝出，君为沈疾婴。
别离寒暑过，荏苒春草生。
故园兹日隔，新禽池上鸣。
郡中永无事，归思徒自盈。','',''),('quantangshi-09063','社日寄崔都水及诸弟羣属','韋應物','quantangshi','','卷10','山郡多暇日，社时放吏归。
坐阁独成闷，行塘阅清辉。
春风动高柳，芳园掩夕扉。
遥思里中会，心绪怅微微。','',''),('quantangshi-09064','寒食日寄诸弟','韋應物','quantangshi','','卷10','禁火暧佳辰，念离独伤抱。
见此野田花，心思杜陵道。
联骑定何时，予今颜已老。','',''),('quantangshi-09065','三月三日寄诸弟兼怀崔都水','韋應物','quantangshi','','卷10','暮节看已谢，兹晨愈可惜。
风澹意伤春，池寒花敛夕。
对酒始依依，怀人还的的。
谁当曲水行，相思寻旧迹。','',''),('quantangshi-09066','赠李儋侍御','韋應物','quantangshi','','卷10','风光山郡少，来看广陵春。
残花犹待客，莫问意中人。','',''),('quantangshi-09067','寄杨协律','韋應物','quantangshi','','卷10','吏散门阁掩，鸟鸣山郡中。
远念长江别，俯觉座隅空。
舟泊南池雨，簟卷北楼风。
并罢芳樽燕，为怆昨时同。','',''),('quantangshi-09068','郡斋赠王卿','韋應物','quantangshi','','卷10','无术谬称简，素餐空自嗟。
秋斋雨成滞，山药寒始华。
濩落人皆笑，幽独岁逾赊。
唯君出尘意，赏爱似山家。','',''),('quantangshi-09069','简恒璨','韋應物','quantangshi','','卷10','室虚多凉气，天高属秋时。
空庭夜风雨，草木晓离披。
简书日云旷，文墨谁复持。
聊因遇澄静，一与道人期。','',''),('quantangshi-09070','闲居寄诸弟','韋應物','quantangshi','','卷10','秋艹生庭白露时，故园诸弟益相思。
