数家砧杵秋山下，一郡荆榛寒雨中。','',''),('quantangshi-09072','寄畅当','韋應物','quantangshi','','卷10','寇贼起东山，英俊方未闲。
闻君新应募，籍籍动京关。
出身文翰场，高步不可攀。
青袍未及解，白羽插腰间。
昔为琼树枝，今有风霜颜。
秋郊细柳道，走马一夕还。
丈夫当为国，破敌如摧山。
何必事州府，坐使鬓毛斑。','',''),('quantangshi-09073','赠崔员外','韋應物','quantangshi','','卷10','一别十年事，相逢淮海滨。
还思洛阳日，更话府中人。
且对清觞满，宁知白发新。
怱怱何处去，车马冒风尘。','',''),('quantangshi-09074','寄李儋元锡','韋應物','quantangshi','','卷10','去年花里逢君别，今日花开已一年。
世事茫茫难自料，春愁黯黯独成眠。
身多疾病思田里，邑有流亡愧俸钱。
闻道欲来相问讯，西楼望月几廻圆。','',''),('quantangshi-09075','京师叛乱寄诸弟','韋應物','quantangshi','','卷10','弱冠遭世难，二纪犹未平。
羇离官远郡，虎豹满西京。
上怀犬马恋，下有骨肉情。
归去在何时，流泪忽霑缨。
忧来上北楼，左右但军营。
函谷行人绝，淮南春草生。
鸟鸣野田间，思忆故园行。
何当四海晏，甘与齐民耕。','',''),('quantangshi-09076','赠琮公','韋應物','quantangshi','','卷10','山僧一相访，吏案正盈前。
出处似殊致，喧静两皆禅。
暮春华池宴，清夜高斋眠。
此道本无得，宁复有忘筌。','',''),('quantangshi-09077','寄诸弟','韋應物','quantangshi','','卷10','岁暮兵戈乱京国，帛书间道访存亡。
还信忽从天上落，唯知彼此泪千行。','',''),('quantangshi-09078','寄恒璨','韋應物','quantangshi','','卷10','心绝去来缘，迹顺人间事。
独寻秋草径，夜宿寒山寺。
今日郡斋闲，思问楞伽字。','',''),('quantangshi-09079','简郡中诸生','韋應物','quantangshi','','卷10','守郡卧秋阁，四面尽荒山。
此时听夜雨，孤灯照窗间。
药园日芜没，书帷长自闲。
惟当上客至，论诗一解颜。','',''),('quantangshi-09080','寄全椒山中道士','韋應物','quantangshi','','卷10','今朝郡斋冷，忽念山中客。
涧底束荆薪，归来煮白石。
欲持一瓢酒，远慰风雨夕。
落叶满空山，何处寻行迹。','',''),('quantangshi-09081','寄释子良史酒','韋應物','quantangshi','','卷10','秋山僧冷病，聊寄三五杯。
应泻山瓢里，还寄此瓢来。','',''),('quantangshi-09082','重寄','韋應物','quantangshi','','卷10','复寄满瓢去，定见空瓢来。
若不打瓢破，终当费酒材。','',''),('quantangshi-09083','答释子良史送酒瓢','韋應物','quantangshi','','卷10','此瓢今已到，山瓢知已空。
且饮寒塘水，遥将回也同。','',''),('quantangshi-09084','简陟巡建三甥','韋應物','quantangshi','','卷10','忽羡后生连榻话，独依寒烛一斋空。
时流欢笑事从别，把酒吟诗待尔同。','',''),('quantangshi-09085','览襃子卧病一绝聊以题示','韋應物','quantangshi','','卷10','念子抱沈疾，霜露变滁城。
独此高窗下，自然无世情。','',''),('quantangshi-09086','寄璨师','韋應物','quantangshi','','卷10','林院生夜色，西廊上纱灯。
时忆长松下，独坐一山僧。','',''),('quantangshi-09087','寄卢陟','韋應物','quantangshi','','卷10','柳叶遍寒塘，晓霜凝高阁。
累日此流连，别来成寂寞。','',''),('quantangshi-09088','途中寄杨邈裴绪示襃子','韋應物','quantangshi','','卷10','上宰领淮右，下国属星驰。
