时有山僧来，悬灯独自宿。','',''),('quantangshi-09090','雪行寄襃子','韋應物','quantangshi','','卷10','淅沥覆寒骑，飘颻暗川容。
行子郡城晓，披云看杉松。','',''),('quantangshi-09091','寄裴处士','韋應物','quantangshi','','卷10','春风驻游骑，晚景澹山晖。
一问清泠子，独掩荒园扉。
草木雨来长，里闾人到稀。
方从广陵宴，花落未言归。','',''),('quantangshi-09092','偶入西斋院示释子恒璨','韋應物','quantangshi','','卷10','僧斋地虽密，忘子迹要赊。
一来非问讯，自是看山花。','',''),('quantangshi-09093','示全真元常','韋應物','quantangshi','','卷10','余辞郡符去，尔为外事牵。
宁知风雪夜，复此对牀眠。
始话南池饮，更咏西楼篇。
无将一会易，岁月坐推迁。','',''),('quantangshi-09094','寄刘尊师','韋應物','quantangshi','','卷10','世间荏苒萦此身，长望碧山到无因。
白鹤徘徊看不去，遥知下有清都人。','',''),('quantangshi-09095','寄庐山椶衣居士','韋應物','quantangshi','','卷10','兀兀山行无处归，山中猛虎识椶衣。
俗客欲寻应不遇，云溪道士见犹稀。','',''),('quantangshi-09096','因省风俗与从侄成绪游山水中道先归寄示','韋應物','quantangshi','','卷10','累宵同燕酌，十舍携征骑。
始造双林寂，遐搜洞府祕。
羣峰绕盘郁，悬泉仰特异。
阴壑云松埋，阳崖烟花媚。
每虑观省牵，中乖游践志。
我尚山水行，子归栖息地。
一操临流袂，上耸干云辔。
独往倦危途，怀冲寡幽致。
赖尔还都期，方将登楼迟。','',''),('quantangshi-09097','寒食寄京师诸弟','韋應物','quantangshi','','卷10','雨中禁火空斋冷，江上流莺独坐听。
把酒看花想诸弟，杜陵寒食草青青。','',''),('quantangshi-09098','岁日寄京师诸[季]端武等','韋應物','quantangshi','','卷10','献岁抱深恻，侨居念归缘。
常患亲爱离，始觉世务牵。
少事河阳府，晚守淮南壖。
平生几会散，已及蹉跎年。
昨日罢符竹，家贫遂留连。
部曲多已去，车马不复全。
闲将酒为偶，默以道自诠。
听松南岩寺，见月西涧泉。
为政无异术，当责岂望迁。
终理来时装，归凿杜陵田。','',''),('quantangshi-09099','简卢陟','韋應物','quantangshi','','卷10','可怜白雪曲，未遇知音人。
恓惶戎旅下，蹉跎淮海滨。
涧树含朝雨，山鸟哢余春。
我有一瓢酒，可以慰风尘。','',''),('quantangshi-09100','西涧即事示卢陟','韋應物','quantangshi','','卷10','寝扉临碧涧，晨起澹忘情。
空林细雨至，圆文遍水生。
永日无余事，山中伐木声。
知子尘喧久，暂可散烦缨。','',''),('quantangshi-09101','登郡寄京师诸季淮南子弟','韋應物','quantangshi','','卷10','始罢永阳守，复卧浔阳楼。
悬槛飘寒雨，危堞侵江流。
迨兹闻雁夜，重忆别离秋。
徒有盈樽酒，镇此百端忧。','',''),('quantangshi-09102','寄黄尊师','韋應物','quantangshi','','卷10','结茅种杏在云端，扫雪焚香宿石坛。
灵只不许世人到，忽作雷风登岭难。','',''),('quantangshi-09103','寄黄刘二尊师','韋應物','quantangshi','','卷10','庐山两道士，各在一峰居。
矫掌白云表，曦发阳和初。
清夜降真侣，焚香满空虚。
中有无为乐，自然与世疎。
道尊不可屈，符守岂暇余。
高斋遥致敬，愿示一编书。','',''),('quantangshi-09104','秋夜寄丘二十二员外','韋應物','quantangshi','','卷10','怀君属秋夜，散步咏凉天。
山空松子落，幽人应未眠。','',''),('quantangshi-09105','赠丘员外二首 一','韋應物','quantangshi','','卷10','高词弃浮靡，贞行表乡闾。
未真南宫拜，聊偃东山居。
大藩本多事，日与文章疎。
每一覩之子，高咏遂起予。
宵昼方连燕，烦恡亦顿祛。
格言雅诲阙，善谑矜数余。
久局思游旷，穷惨遇阳舒。
虎丘惬登眺，吴门怅踌躇。
方此恋携手，岂云还旧墟。
告诸吴子弟，文学为何如。','',''),('quantangshi-09106','赠丘员外二首 二','韋應物','quantangshi','','卷10','迹与孤云远，心将野鹤俱。
那同石氏子，每到府门趋。','',''),('quantangshi-09107','赠李判官','韋應物','quantangshi','','卷10','良玉定为宝，长材世所稀。
佐幕方巡郡，奏命布恩威。
食蔬程独守，饮冰节靡违。
决狱兴邦颂，高文禀天机。
宾馆在林表，望山启西扉。
下有千亩田，泱漭吴土肥。
始耕已见获，袗絺今授衣。
政拙劳详省，淹留未得归。
虽慙且忻愿，日夕覩光辉。','',''),('quantangshi-09108','寄皎然上人','韋應物','quantangshi','','卷10','吴兴老释子，野雪盖精庐。
诗名徒自振，道心长晏如。
想兹栖禅夜，见月东峰初。
鸣钟惊岩壑，焚香满空虚。
叨慕端成旧，未识岂为疎。
愿以碧云思，方君怨别余。
茂苑文华地，流水古僧居。
何当一游咏，倚阁吟踌躇。','',''),('quantangshi-09109','赠旧识','韋應物','quantangshi','','卷10','少年游太学，负气蔑诸生。
蹉跎三十载，今日海隅行。','',''),('quantangshi-09110','复理西斋寄丘员外','韋應物','quantangshi','','卷10','前岁理西斋，得与君子同。
迨兹已一周，怅望临春风。
始自疎林竹，还复长榛丛。
端正良难久，芜秽易为功。
援斧开众郁，如师启羣蒙。
庭宇还清旷，烦抱亦舒通。
海隅雨雪霁，春序风景融。
时物方如故，怀贤思无穷。','',''),('quantangshi-09111','和张舍人夜直中书寄吏部刘员外','韋應物','quantangshi','','卷10','西垣草诏罢，南宫忆上才。
月临兰殿出，凉自凤池来。
松桂生丹禁，鸳鹭集云台。
托身各有所，相望徒徘徊。','',''),('quantangshi-09112','和李二主簿寄淮上綦毋三','韋應物','quantangshi','','卷10','满城怜傲吏，终日赋新诗。
请报淮阴客，春帆浪作期。','',''),('quantangshi-09113','寄二严','韋應物','quantangshi','','卷10','丝竹久已懒，今日遇君忺。
打破蜘蛛千道网，总为鹡鸰两个严。','',''),('quantangshi-09114','李五席送李主簿归西台','韋應物','quantangshi','','卷10','请告严程尽，西归道路寒。
欲陪鹰隼集，犹恋鹡鸰单。
洛邑人全少，嵩高雪尚残。
满台谁不故，报我在微官。','',''),('quantangshi-09115','送崔押衙相州','韋應物','quantangshi','','卷10','礼乐儒家子，英豪燕赵风。
驱鸡尝理邑，走马却从戎。
白刃千夫辟，黄金四海同。
嫖姚恩顾下，诸将指挥中。
别路怜芳草，归心伴塞鸿。
邺城新骑满，魏帝旧台空。
望阙应怀恋，遭时贵立功。
万方如已静，何处欲输忠。','',''),('quantangshi-09116','送宣城路录事','韋應物','quantangshi','','卷10','江上宣城郡，孤舟远到时。
云林谢家宅，山水敬亭祠。
纲纪多闲日，观游得赋诗。
都门且尽醉，此别数年期。','',''),('quantangshi-09117','送李十四山东游','韋應物','quantangshi','','卷10','圣朝有遗逸，披胆谒至尊。
岂是贸荣宠，誓将救元元。
权豪非所便，书奏寝禁门。
高歌长安酒，忠愤不可吞。
欻来客河洛，日与静者论。
济世飜小事，丹砂驻精魂。
东游无复系，梁楚多大蕃。
高论动侯伯，疎怀脱尘喧。
送君都门野，饮我林中樽。
立马望东道，白云满梁园。
踟蹰欲何赠，空是平生言。','',''),('quantangshi-09118','送李二归楚州','韋應物','quantangshi','','卷10','情人南楚别，复咏在原诗。
忽此嗟歧路，还令泣素丝。
风波朝夕远，音信往来迟。
好去扁舟客，青云何处期。','',''),('quantangshi-09119','送阎寀赴东川辟','韋應物','quantangshi','','卷10','冰炭俱可怀，孰云热与寒。
何如结发友，不得携手懽。
晨登严霜野，送子天一端。
祗承简书命，俯仰豸角冠。
上陟白云峤，下冥玄壑湍。
离羣自有托，历险得所安。
当念反穷巷，登朝成慨叹。','',''),('quantangshi-09120','送令狐岫宰恩阳','韋應物','quantangshi','','卷10','大雪天地闭，羣山夜来晴。
居家犹苦寒，子有千里行。
行行安得辞，荷此蒲璧荣。
贤豪争追攀，饮饯出西京。
樽酒岂不欢，暮春自有程。
离人起视日，仆御促前征。
逶迟岁已穷，当造巴子城。
和风被草木，江水日夜清。
从来知善政，离别慰友生。','',''),('quantangshi-09121','送冯着受李广州署为录事','韋應物','quantangshi','','卷10','郁郁杨柳枝，萧萧征马悲。
送君灞陵岸，纠郡南海湄。
名在翰墨场，羣公正追随。
如何从此去，千里万里期。
大海吞东南，横岭隔地维。
建邦临日域，温燠御四时。
百国共臻奏，珍奇献京师。
富豪虞兴戎，绳墨不易持。
州伯荷天宠，还当翊丹墀。
子为门下生，终始岂见遗。
所愿酌贪泉，心不为磷缁。
上将玩国士，下以报渴饥。','',''),('quantangshi-09122','送元仓曹归广陵','韋應物','quantangshi','','卷10','官闲得去住，告别恋音徽。
旧国应无业，他乡到是归。
楚山明月满，淮甸夜钟微。
何处孤舟泊，遥遥心曲违。','',''),('quantangshi-09123','送唐明府赴溧水','韋應物','quantangshi','','卷10','三为百里宰，已过十余年。
祗叹官如旧，旋闻邑屡迁。
鱼盐滨海利，姜蔗傍湖田。
到此安甿俗，琴堂又晏然。','',''),('quantangshi-09124','喜于广陵拜觐家兄奉送发还池州','韋應物','quantangshi','','卷10','青青连枝树，苒苒久别离。
客游广陵中，俱到若有期。
俯仰叙存殁，哀肠发酸悲。
收情且为欢，累日不知饥。
夙驾多所迫，复当还归池。
长安三千里，岁晏独何为。
南出登阊门，惊飙左右吹。
所别谅非远，要令心不怡。','',''),('quantangshi-09125','送章八元秀才擢第往上都应制','韋應物','quantangshi','','卷10','决胜文场战已酣，行应辟命复才堪。
旅食不辞游阙下，春衣未换报江南。
天边宿鸟生归思，关外晴山满夕岚。
立马欲从何处别，都门杨柳正毵毵。','',''),('quantangshi-09126','送张侍御祕书江左觐省','韋應物','quantangshi','','卷10','莫叹都门路，归无驷马车。
绣衣犹在箧，芸阁已观书。
沃野收红稻，长江钓白鱼。
晨飡亦可荐，名利欲何如。','',''),('quantangshi-09127','赋得鼎门送卢耿赴任','韋應物','quantangshi','','卷10','名因定鼎地，门对凿龙山。
水北楼台近，城南车马还。
稍开芳野静，欲掩暮钟闲。
去此无嗟屈，前贤尚抱关。','',''),('quantangshi-09128','赋得浮云起离色送郑述诚','韋應物','quantangshi','','卷10','游子欲言去，浮云那得知。
偏能见行色，自是独伤离。
晚带城遥暗，秋生峰尚奇。
还因朔吹断，匹马与相随。','',''),('quantangshi-09129','饯雍聿之潞州谒李中丞','韋應物','quantangshi','','卷10','郁郁雨相遇，出门草青青。
酒酣拔劒舞，慷慨送子行。
驱马涉大河，日暮怀洛京。
前登太行路，志士亦未平。
薄游五府都，高步振英声。
主人才且贤，重士百金轻。
丝竹促飞觞，夜宴达晨星。
娱乐易淹暮，谅在执高情。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-09130','上东门会送李幼举南游徐方','韋應物','quantangshi','','卷10','离弦既罢弹，罇酒亦已阑。
听我歌一曲，南徐在云端。
云端虽云邈，行路本非难。
诸侯皆爱才，公子远结欢。
济济都门宴，将去复盘桓。
令姿何昂昂，良马远游冠。
意气且为别，由来非所叹。','',''),('quantangshi-09131','送洛阳韩丞东游','韋應物','quantangshi','','卷10','仙鸟何飘颻，绿衣翠为襟。
顾我差池羽，咬咬怀好音。
徘徊洛阳中，游戏清川浔。
神交不在结，欢爱自中心。
驾言忽徂征，云路邈且深。
朝游尚同啄，夕息当异林。
出饯宿东郊，列筵属城阴。
举酒欲为乐，忧怀方沈沈。','',''),('quantangshi-09132','送郑长源','韋應物','quantangshi','','卷10','少年一相见，飞辔河洛间。
欢游不知罢，中路忽言还。
泠泠鵾弦哀，悄悄冬夜闲。
丈夫虽耿介，远别多苦颜。
君行拜高堂，速驾难久攀。
鸡鸣俦侣发，朔雪满河关。
须臾在今夕，罇酌且循环。','',''),('quantangshi-09133','送李儋','韋應物','quantangshi','','卷10','别离何从生，乃在亲爱中。
反念行路子，拂衣自西东。
日昃不留宴，严车出崇墉。
行游非所乐，端忧道未通。
春野百卉发，清川思无穷。
芳时坐离散，世事谁可同。
归当掩重关，默默想音容。','',''),('quantangshi-09134','赋得暮雨送李胄','韋應物','quantangshi','','卷10','楚江微雨里，建业暮钟时。
漠漠帆来重，冥冥鸟去迟。
海门深不见，浦树远含滋。
相送情无限，沾襟比散丝。','',''),('quantangshi-09135','留别洛京亲友','韋應物','quantangshi','','卷10','握手出都门，驾言适京师。
岂不怀旧庐，惆怅与子辞。
丽日坐高阁，清觞宴华池。
昨游倏已过，后遇良未知。
念结路方永，岁阴野无晖。
单车我当前，暮雪子独归。
临流一相望，零泪忽沾衣。','',''),('quantangshi-09136','赋得沙际路送从叔象','韋應物','quantangshi','','卷10','独树沙边人迹稀，欲行愁远暮钟时。
野泉几处侵应尽，不过山僧知问谁。','',''),('quantangshi-09137','送榆次林明府','韋應物','quantangshi','','卷10','无嗟千里远，亦是宰王畿。
策马雨中去，逢人关外稀。
邑传榆石在，路遶晋山微。
别思方萧索，新秋一叶飞。','',''),('quantangshi-09138','杂言送黎六郎','韋應物','quantangshi','','卷10','冰壶见底未见清，少年如玉有诗名。
闻话嵩峰多野寺，不嫌黄绶向阳城。
朱门严训朝辞去，骑出东郊满飞絮。
河南庭下拜府君，阳城归路山氛氲。
山氛氲，长不见，钓台水渌荷已生，少姨庙寒花始徧。
县闲吏傲与尘隔，移竹疏泉常岸帻。
莫言去作折腰官，岂似长安折腰客。','',''),('quantangshi-09139','天长寺上方别子西有道','韋應物','quantangshi','','卷10','假邑非拙素，况乃别伊人。
聊登释氏居，携手恋兹晨。
高旷出尘表，逍遥涤心神。
青山对芳苑，列树遶通津。
车马无时绝，行子倦风尘。
今当遵往路，伫立欲何申。
唯持贞白志，以慰心所亲。','',''),('quantangshi-09140','送黎六郎赴阳翟少府','韋應物','quantangshi','','卷10','试吏向嵩阳，春山踯躅芳。
腰垂新绶色，衣满旧芸香。
乔树别时绿，客程关外长。
祗应传善政，日夕慰高堂。','',''),('quantangshi-09141','送别覃孝廉','韋應物','quantangshi','','卷10','思亲自当去，不第未蹉跎。
家住青山下，门前芳草多。
秭归通远徼，巫峡注惊波。
州举年年事，还期复几何。','',''),('quantangshi-09142','送开封卢少府','韋應物','quantangshi','','卷10','雄藩车马地，作尉有光辉。
满席宾常侍，阗街烛夜归。
关河征斾远，烟树夕阳微。
到处无留滞，梁园花欲稀。','',''),('quantangshi-09143','送槐广落第归扬州','韋應物','quantangshi','','卷10','下第常称屈，少年心独轻。
拜亲归海畔，似舅得诗名。
晚对青山别，遥寻芳草行。
还期应不远，寒露湿芜城。','',''),('quantangshi-09144','送汾城王主簿','韋應物','quantangshi','','卷10','少年初带印，汾上又经过。
芳草归时徧，情人故郡多。
禁钟春雨细，宫树野烟和。
相望东桥别，微风起夕波。','',''),('quantangshi-09145','送渑池崔主簿','韋應物','quantangshi','','卷10','邑带洛阳道，年年应此行。
当时匹马客，今日县人迎。
暮雨投关郡，春风别帝城。
东西殊不远，朝夕待佳声。','',''),('quantangshi-09146','送颜司议使蜀访图书','韋應物','quantangshi','','卷10','轺驾一封急，蜀门千岭曛。
讵分江转字，但见路缘云。
山馆夜听雨，秋猿独呌羣。
无为久留滞，圣主待遗文。','',''),('quantangshi-09147','奉送从兄宰晋陵','韋應物','quantangshi','','卷10','东郊暮草歇，千里夏云生。
立马愁将夕，看山独送行。
依微吴苑树，迢递晋陵城。
慰此断行别，邑人多颂声。','',''),('quantangshi-09148','赠别河南李功曹','韋應物','quantangshi','','卷10','耿耿抱私戚，寥寥独掩扉。
临觞自不饮，况与故人违。
故人方琢磨，瓌朗代所稀。
宪礼更右职，文翰洒天机。
聿来自东山，羣彦仰余辉。
谈笑取高第，绾绶即言归。
洛都游燕地，千里及芳菲。
今朝章台别，杨柳亦依依。
云霞未改色，山川犹夕晖。
忽复不相见，心思乱霏霏。','',''),('quantangshi-09149','送五经赵随登科授广德尉','韋應物','quantangshi','','卷10','明经有清秩，当在石渠中。
独往宣城郡，高斋谒谢公。
寒原正芜漫，夕鸟自西东。
秋日不堪别，凄凄多朔风。','',''),('quantangshi-09150','宴别幼遐与君贶兄弟','韋應物','quantangshi','','卷10','乖阙意方弭，安知忽来翔。
累日重欢宴，一旦复离伤。
置酒慰兹夕，秉烛坐华堂。
契阔未及展，晨星出东方。
征人惨已辞，车马俨成装。
我怀自无欢，原野满春光。
羣水含时泽，野雉鸣朝阳。
平生有壮志，不觉泪霑裳。
况自守空宇，日夕但旁徨。','',''),('quantangshi-09151','送宣州周录事','韋應物','quantangshi','','卷10','清时重儒士，纠郡属伊人。
薄游长安中，始得一交亲。
英豪若云集，饯别塞城闉。
高驾临长路，日夕起风尘。
方念清宵宴，已度芳林春。
从兹一分手，缅邈吴与秦。
但覩年运驶，安知后会因。
唯当存令德，可以解悁勤。','',''),('quantangshi-09152','谢栎阳令归西郊赠别诸友生','韋應物','quantangshi','','卷10','结发仕州县，蹉跎在文墨。
徒有排云心，何由生羽翼。
幸遭明盛日，万物蒙生植。
独此抱微疴，颓然谢斯职。
世道方荏苒，郊园思偃息。
为欢日已延，君子情未极。
驰觞忽云晏，高论良难测。
游步清都宫，迎风嘉树侧。
晨起西郊道，原野分黍稷。
自乐陶唐人，服勤在微力。
伫君列丹陛，出处两为得。','',''),('quantangshi-09153','送端东行','韋應物','quantangshi','','卷10','世承清白遗，躬服古人言。
从官俱守道，归来共闭门。
驱车何处去，暮雪满平原。','',''),('quantangshi-09154','送姚孙还河中','韋應物','quantangshi','','卷10','上国旅游罢，故园生事微。
风尘满路起，行人何处归。
留思芳树饮，惜别暮春晖。
几日投关郡，河山对掩扉。','',''),('quantangshi-09155','始除尚书郎别善福精舍','韋應物','quantangshi','','卷10','简略非世器，委身同草木。
逍遥精舍居，饮酒自为足。
累日曾一栉，对书常懒读。
社腊会高年，山川恣游瞩。
明世方选士，中朝悬美禄。
除书忽到门，冠带便拘束。
愧忝郎署迹，谬蒙君子录。
俯仰垂华缨，飘颻翔轻毂。
行将亲爱别，恋此西涧曲。
远峰明夕川，夏雨生众绿。
迅风飘野路，廻首不遑宿。
明晨下烟阁，白云在幽谷。','',''),('quantangshi-09156','送常侍御却使西蕃','韋應物','quantangshi','','卷10','归奏圣朝行万里，却衔天诏报蕃臣。
本是诸生守文墨，今将匹马静烟尘。
旅宿关河逢暮雨，春耕亭障识遗民。
此去多应收故地，宁辞沙塞往来频。','',''),('quantangshi-09157','送郗詹事','韋應物','quantangshi','','卷10','圣朝列羣彦，穆穆佐休明。
君子独知止，悬车守国程。
忠良信旧德，文学播英声。
既获天爵美，况将齿位并。
书奏蒙省察，命驾乃东征。
皇恩赐印绶，归为田里荣。
朝野同称叹，园绮郁齐名。
长衢轩葢集，饮饯出西京。
时属春阳节，草木已含英。
洛川当盛宴，斯焉为达生。','',''),('quantangshi-09158','送苏评事','韋應物','quantangshi','','卷10','季弟仕谯都，元兄坐兰省。
言访始忻忻，念离当耿耿。
嵯峨夏云起，迢遰山川永。
登高望去尘，纷思终难整。','',''),('quantangshi-09159','送李侍御益赴幽州幕','韋應物','quantangshi','','卷10','二十挥篇翰，三十穷典坟。
辟书五府至，名为四海闻。
始从车骑幕，今赴嫖姚军。
契阔晚相遇，草戚遽离羣。
悠悠行子远，眇眇川途分。
登高望燕代，日夕生夏云。
司徒拥精甲，誓将除国氛。
儒生幸持斧，可以佐功勋。
无言羽书急，坐阙相思文。','',''),('quantangshi-09160','自尚书郎出为滁州刺史','韋應物','quantangshi','','卷10','少年不远仕，秉笏东西京。
中岁守淮郡，奉命乃征行。
素慙省阁姿，况忝符竹荣。
効愚方此始，顾私岂获并。
徘徊亲交恋，怆悢昆友情。
日暮风雪起，我去子还城。
登涂建隼旟，勒驾望承明。
云台焕中天，龙阙郁上征。
晨兴奉早朝，玉露霑华缨。
一朝从此去，服膺理庶甿。
皇恩傥岁月，归服厕羣英。','',''),('quantangshi-09161','送元锡杨凌','韋應物','quantangshi','','卷10','荒林翳山郭，积水成秋晦。
端居意自违，况别亲与爱。
欢筵慊未足，离灯悄已对。
还当掩郡阁，伫君方此会。','',''),('quantangshi-09162','送杨氏女','韋應物','quantangshi','','卷10','永日方戚戚，出门复悠悠。
女子今有行，大江溯轻舟。
尔辈况无恃，抚念益慈柔。
幼为长所育，两别泣不休。
对此结中肠，义往难复留。
自小阙内训，事姑贻我忧。
赖兹托令门，仁恤庶无尤。
贫俭诚所尚，资从岂待周。
孝恭遵妇道，容止顺其猷。
别离在今晨，见尔当何秋。
居闲始自遣，临感忽难收。
归来视幼女，零泪缘缨流。','',''),('quantangshi-09163','送中弟','韋應物','quantangshi','','卷10','秋风入疎户，离人起晨朝。
山郡多风雨，西楼更萧条。
嗟予淮海老，送子关河遥。
同来不同去，沈忧宁复消。','',''),('quantangshi-09164','寄别李儋','韋應物','quantangshi','','卷10','首戴惠文冠，心有决胜筹。
翩翩四五骑，结束向并州。
名在相公幕，丘山恩未酬。
妻子不及顾，亲友安得留。
宿昔同文翰，交分共绸缪。
忽枉别离札，涕泪一交流。
远郡卧残疾，凉气满西楼。
想子临长路，时当淮海秋。','',''),('quantangshi-09165','送仓部萧员外院长存','韋應物','quantangshi','','卷10','襆被蹉跎老江国，情人邂逅此相逢。
不随鸳鹭朝天去，遥想蓬莱台阁重。','',''),('quantangshi-09166','送王校书','韋應物','quantangshi','','卷10','同宿高斋换时节，共看移石复栽杉。
送君江浦已惆怅，更上西楼看远帆。','',''),('quantangshi-09167','送丘员外还山','韋應物','quantangshi','','卷10','长栖白云表，蹔访高斋宿。
还辞郡邑喧，归泛松江渌。
结茅隐苍岭，伐薪响深谷。
同是山中人，不知往来躅。
灵芝非庭草，辽鹤委池鹜。
终当署里门，一表高阳族。','',''),('quantangshi-09168','重送丘二十二还临平山居','韋應物','quantangshi','','卷10','岁中始再觏，方来又解携。
才留野艇语，已忆故山栖。
幽涧人夜汲，深林鸟长啼。
还持郡斋酒，慰子霜露凄。','',''),('quantangshi-09169','送郑端公弟移院常州','韋應物','quantangshi','','卷10','时瞻宪臣重，礼为内兄全。
公程傥见责，私爱信不愆。
况昔陪朝列，今兹俱海壖。
清觞方对酌，天书忽告迁。
岂徒咫尺地，使我心思绵。
应当自此始，归拜云台前。','',''),('quantangshi-09170','送房杭州','韋應物','quantangshi','','卷10','专城未四十，暂谪岂蹉跎。
风雨吴门夜，恻怆别情多。','',''),('quantangshi-09171','送陆侍御还越','韋應物','quantangshi','','卷10','居藩久不乐，遇子聊一欣。
英声颇籍甚，交辟乃时珍。
绣衣过旧里，骢马辉四邻。
敬恭尊郡守，牋简具州民。
谬忝诚所愧，思怀方见申。
置榻宿清夜，加笾宴良辰。
遵涂还盛府，行舫遶长津。
自有贤方伯，得此文翰宾。','',''),('quantangshi-09172','听江笛送陆侍御','韋應物','quantangshi','','卷10','远听江上笛，临觞一送君。
还愁独宿夜，更向郡斋闻。','',''),('quantangshi-09173','送丘员外归山居','韋應物','quantangshi','','卷10','郡阁始嘉宴，青山忆旧居。
为君量革履，且愿住蓝轝。','',''),('quantangshi-09174','送崔叔清游越','韋應物','quantangshi','','卷10','忘兹适越意，爱我郡斋幽。
野情岂好谒，诗兴一相留。
远水带寒树，阊门望去舟。
方伯怜文士，无为成滞游。','',''),('quantangshi-09175','送云阳邹儒立少府侍奉还京师','韋應物','quantangshi','','卷10','建中即藩守，天宝为侍臣。
历观两都士，多阅诸侯人。
邹生乃后来，英俊亦罕伦。
为文颇瓌丽，禀度自贞醇。
甲科推令名，延阁播芳尘。
再命趋王畿，请告奉慈亲。
一钟信荣禄，可以展欢欣。
昆弟俱时秀，长衢当自伸。
聊从郡阁暇，美此时景新。
方将极娱宴，已复及离晨。
省署慙再入，江海绵十春。
今日阊门路，握手子归秦。','',''),('quantangshi-09176','送豆卢策秀才','韋應物','quantangshi','','卷10','岁交冰未泮，地卑海气昏。
子有京师游，始发吴阊门。
新黄含远林，微绿生陈根。
诗人感时节，行道当忧烦。
古来濩落者，俱不事田园。
文如金石韵，岂乏知音言。
方辞郡斋榻，为酌离亭罇。
无为倦羁旅，一去高飞翻。','',''),('quantangshi-09177','送王卿','韋應物','quantangshi','','卷10','别酌春林啼鸟稀，双旌背日晚风吹。
却忆回来花已尽，东郊立马望城池。','',''),('quantangshi-09178','送刘评事','韋應物','quantangshi','','卷10','声华满京洛，藻翰发阳春。
未遂鵷鸿举，尚为江海宾。
吴中高宴罢，西上一游秦。
已想函关道，游子冒风尘。
笼禽羡归翼，远守怀交亲。
况复岁云暮，凛凛冰霜辰。
旭霁开郡阁，宠饯集文人。
洞庭摘朱实，松江献白鳞。
丈夫岂恨别，一酌且欢忻。','',''),('quantangshi-09179','送雷监赴阙庭','韋應物','quantangshi','','卷10','才大无不备，出入为时须。
雄藩精理行，祕府擢文儒。
诏书忽已至，焉得久踟躅。
方舟趂朝谒，观者盈路衢。
广筵列众宾，送爵无停迂。
攀饯诚怆恨，贺荣且欢娱。
长陪柏梁宴，日向丹墀趋。
时方重右职，蹉跎独海隅。','',''),('quantangshi-09180','送秦系赴润州','韋應物','quantangshi','','卷10','近作新婚镊白髯，长怀旧卷映蓝衫。
更欲携君虎丘寺，不知方伯望征帆。','',''),('quantangshi-09181','送孙征赴云中','韋應物','quantangshi','','卷10','黄骢少年舞双戟，目视傍人皆辟易。
百战会夸陇上儿，一身复作云中客。
寒风动地气苍芒，横吹先悲出塞长。
敲石军中传夜火，斧冰河畔汲朝浆。
前锋直指阴山外，虏骑纷纷翦应碎。
匈奴破尽看君归，金印酬功如斗大。','',''),('quantangshi-09182','期卢嵩枉书称日暮无马不赴以诗答','韋應物','quantangshi','','卷10','佳期不可失，终愿枉衡门。
南陌人犹度，西林日未昏。
庭前空倚杖，花里独留罇。
莫道无来驾，知君有短辕。','',''),('quantangshi-09183','任洛阳丞答前长安田少府问','韋應物','quantangshi','','卷10','相逢且对酒，相问欲何如。
数岁犹卑吏，家人笑着书。
告归应未得，荣宦又知疎。
日日生春草，空令忆旧居。','',''),('quantangshi-09184','假中枉卢二十二书亦称卧疾兼讶李二久不访问以诗答书因亦戏李二','韋應物','quantangshi','','卷10','微官何事劳趋走，服药闲眠养不才。
花里棋盘憎鸟污，枕边书卷讶风开。
故人问讯缘同病，芳月相思阻一杯。
应笑王戎成俗物，遥持麈尾独徘徊。','',''),('quantangshi-09185','酬卢嵩秋夜见寄五韵','韋應物','quantangshi','','卷10','乔木生夜凉，月华满前墀。
去君咫尺地，劳君千里思。
素秉栖遁志，况贻招隐诗。
坐见林木荣，愿赴沧洲期。
何能待岁晏，携手当此时。','',''),('quantangshi-09186','酬郑户曹骊山感怀','韋應物','quantangshi','','卷10','苍山何郁盘，飞阁凌上清。
先帝昔好道，下元朝百灵。
白云已萧条，麋鹿但纵横。
泉水今尚暖，旧林亦青青。
我念绮襦岁，扈从当太平。
小臣职前驱，驰道出灞亭。
翻翻日月旗，殷殷鼙鼓声。
万马自腾骧，八骏按辔行。
日出烟峤绿，氛氲丽层甍。
登临起遐想，沐浴懽圣情。
朝燕咏无事，时丰贺国祯。
日和弦管音，下使万室听。
海内凑朝贡，贤愚共欢荣。
合沓车马喧，西闻长安城。
事往世如寄，感深迹所经。
申章报兰藻，一望双涕零。','',''),('quantangshi-09187','答李澣三首 一','韋應物','quantangshi','','卷10','孤客逢春暮，缄情寄旧游。
海隅人使远，书到洛阳秋。','',''),('quantangshi-09188','答李澣三首 二','韋應物','quantangshi','','卷10','马卿犹有壁，渔父自无家。
想子今何处，扁舟隐荻花。','',''),('quantangshi-09189','答李澣三首 三','韋應物','quantangshi','','卷10','林中观易罢，溪上对鸥闲。
楚俗饶辞客，何人最往还。','',''),('quantangshi-09190','酬柳郎中春日归扬州南郭见别之作','韋應物','quantangshi','','卷10','广陵三月花正开，花里逢君醉一廻。
南北相过殊不远，暮潮从去早潮来。','',''),('quantangshi-09191','酬豆卢仓曹题库壁见示','韋應物','quantangshi','','卷10','掾局劳才子，新诗动洛川。
运筹知决胜，聚米似论边。
宴罢常分骑，晨趋又比肩。
莫嗟年鬓改，郎署定推先。','',''),('quantangshi-09192','酬李儋','韋應物','quantangshi','','卷10','开门临广陌，旭旦车驾喧。
不见同心友，徘徊忧且烦。
都城二十里，居在艮与坤。
人生所各务，乖阔累朝昏。
湛湛罇中酒，青青芳树园。
缄情未及发，先此枉璵璠。
迈世超高躅，寻流得真源。
明当策疲马，与子同笑言。','',''),('quantangshi-09193','酬元伟过洛阳夜燕','韋應物','quantangshi','','卷10','三载寄关东，所懽皆远违。
思怀方耿耿，忽得观容辉。
亲燕在良夜，欢携辟中闱。
问我犹杜门，不能奋高飞。
明灯照四隅，炎炭正可依。
清觞虽云酌，所愧乏珍肥。
晨装复当行，寥落星已稀。
何以慰心曲，伫子西还归。','',''),('quantangshi-09194','酬韩质舟行阻冻','韋應物','quantangshi','','卷10','晨坐枉嘉藻，持此慰寝兴。
中获辛苦奏，长河结阴冰。
皓曜羣玉发，凄清孤景凝。
至柔反成坚，造化安可恒。
方舟未得行，凿饮空兢兢。
寒苦弥时节，待泮岂所能。
何必涉广川，荒衢且升腾。
殷勤宣中意，庶用达吾朋。','',''),('quantangshi-09195','李博士弟以余罢官居同德精舍共有伊陆名山之期久而未去枉诗见问中云宋生昔登览未云那能顾蓬荜直寄鄙怀聊以为答','韋應物','quantangshi','','卷10','初夏息众缘，双林对禅客。
枉兹芳兰藻，促我幽人策。
冥搜企前哲，逸句陈往迹。
仿髴陆浑南，迢递千峰碧。
从来迟高驾，自顾无物役。
山水心所娱，如何更朝夕。
晨兴涉清洛，访子高阳宅。
莫言往来疎，驽马知阡陌。','',''),('quantangshi-09196','寄酬李博士永宁主簿叔厅见待','韋應物','quantangshi','','卷10','解鞍先几日，款曲见新诗。
定向公堂醉，遥怜独去时。
叶霑寒雨落，钟度远山迟。
晨策已云整，当同林下期。','',''),('quantangshi-09197','答令狐士曹独孤兵曹联骑暮归望山见寄','韋應物','quantangshi','','卷10','共爱青山住近南，行牵吏役背双骖。
枉书独宿对流水，遥羡归时满夕岚。','',''),('quantangshi-09198','答李博士','韋應物','quantangshi','','卷10','休沐去人远，高斋出林杪。
晴山多碧峰，颢气疑秋晓。
端居喜良友，枉使千里路。
缄书当夏时，开缄时已度。
檐雏已颻扬，荷露方萧飒。
梦远竹窗幽，行稀兰径合。
旧居共南北，往来只如昨。
问君今为谁，日夕度清洛。','',''),('quantangshi-09199','答刘西曹','韋應物','quantangshi','','卷10','公馆夜云寂，微凉羣树秋。
西曹得时彦，华月共淹留。
长啸举清觞，志气谁与俦。
千龄事虽邈，俯念忽已周。
篇翰如云兴，京洛颇优游。
诠文不独古，理妙即同流。
浅劣见推许，恐为识者尤。
空慙文璧赠，日夕不能酬。','',''),('quantangshi-09200','答贡士黎逢','韋應物','quantangshi','','卷10','茂等方上达，诸生安可希。
栖神澹物表，涣汗布令词。
如彼昆山玉，本自有光辉。
鄙人徒区区，称叹亦何为。
弥月旷不接，公门但驱驰。
兰章忽有赠，持用慰所思。
不见心尚密，况当相见时。','',''),('quantangshi-09201','答韩库部','韋應物','quantangshi','','卷10','良玉表贞度，丽藻颇为工。
名列金闺籍，心与素士同。
日晏下朝来，车马自生风。
清宵有佳兴，皓月直南宫。
矫翮方上征，顾我邈忡忡。
岂不愿攀举，执事府庭中。
智乖时亦蹇，才大命有通。
还当以道推，解组守蒿蓬。','',''),('quantangshi-09202','答崔主簿倬','韋應物','quantangshi','','卷10','朗月分林霭，遥管动离声。
故驩良已阻，空宇澹无情。
窈窕云雁没，苍茫河汉横。
兰草不可答，冲襟徒自盈。','',''),('quantangshi-09203','答徐秀才','韋應物','quantangshi','','卷10','铅钝谢贞器，时秀猥见称。
岂如白玉仙，方与紫霞升。
清诗舞艳雪，孤抱莹玄冰。
一枝非所贵，怀书思武陵。','',''),('quantangshi-09204','答东林道士','韋應物','quantangshi','','卷10','紫阁西边第几峰，茅斋夜雪虎行踪。
遥看黛色知何处，欲出山门寻暮钟。','',''),('quantangshi-09205','答长宁令杨辙','韋應物','quantangshi','','卷10','皓月升林表，公堂满清辉。
嘉宾自远至，觞饮夜何其。
宰邑视京县，归来无寸资。
瓌文溢众宝，雅正得吾师。
广川含澄澜，茂树擢华滋。
短才何足数，枉赠愧妍词。
欢盼良见属，素怀亦已披。
何意云栖翰，不嫌蓬艾卑。
但恐河汉没，回车首路岐。','',''),('quantangshi-09206','答冯鲁秀才','韋應物','quantangshi','','卷10','晨坐枉琼藻，知子返中林。
澹然山景晏，泉谷响幽禽。
仿髴谢尘迹，逍遥舒道心。
顾我腰间绶，端为华发侵。
簿书劳应对，篇翰旷不寻。
薄田失锄耨，生苗安可任。
徒令慙所问，想望东山岑。','',''),('quantangshi-09207','答崔主簿问兼简温上人','韋應物','quantangshi','','卷10','缘情生众累，晚悟依道流。
诸境一已寂，了将身世浮。
闲居澹无味，忽复四时周。
靡靡芳草积，稍稍新篁抽。
即此抱余素，块然诚寡俦。
自适一忻意，愧蒙君子忧。','',''),('quantangshi-09208','清都观答幼遐','韋應物','quantangshi','','卷10','逍遥仙家子，日夕朝玉皇。
兴高清露没，渴饮琼华浆。
解组一来款，披衣拂天香。
粲然顾我笑，绿简发新章。
泠泠如玉音，馥馥若兰芳。
浩意坐盈此，月华殊未央。
却念喧哗日，何由得清凉。
疎松抗高殿，密竹阴长廊。
荣名等粪土，携手随风翔。','',''),('quantangshi-09209','善福精舍答韩司录清都观会宴见忆','韋應物','quantangshi','','卷10','弱志厌众纷，抱素寄精庐。
皦皦仰时彦，闷闷独为愚。
之子亦辞秩，高踪罢驰驱。
忽因西飞禽，赠我以琼琚。
始表仙都集，复言欢乐殊。
人生各有因，契阔不获俱。
一来田野中，日与人事疎。
水木澄秋景，逍遥清赏余。
枉驾怀前诺，引领岂斯须。
无为便高翔，邈矣不可迂。','',''),('quantangshi-09210','答长安丞裴说','韋應物','quantangshi','','卷10','出身忝时士，于世本无机。
爰以林壑趣，遂成顽钝姿。
临流意已凄，采菊露未稀。
举头见秋山，万事都若遗。
独践幽人踪，邈将亲友违。
髦士佐京邑，怀念枉贞词。
久雨积幽抱，清罇宴良知。
从容操剧务，文翰方见推。
安能戢羽翼，顾此林栖时。','',''),('quantangshi-09211','奉酬处士叔见示','韋應物','quantangshi','','卷10','挂缨守贫贱，积雪卧郊园。
叔父亲降趾，壶觞携到门。
高斋乐宴罢，清夜道心存。
即此同疎氏，可以一忘言。','',''),('quantangshi-09212','答库部韩郎中','韋應物','quantangshi','','卷10','高士不羁世，颇将荣辱齐。
适委华冕去，欲还幽林栖。
虽怀承明恋，忻与物累暌。
逍遥观运流，谁复职端倪。
而我岂高致，偃息平门西。
愚者世所遗，沮溺共耕犂。
风雪积深夜，园田掩荒蹊。
幸蒙相思札，款曲期见携。','',''),('quantangshi-09213','答畅校书当','韋應物','quantangshi','','卷10','偶然弃官去，投迹在田中。
日出照茅屋，园林养愚蒙。
虽云无一资，罇酌会不空。
且忻百谷成，仰叹造化功。
出入与民伍，作事靡不同。
时伐南涧竹，夜还沣水东。
贫蹇自成退，岂为高人踪。
览君金玉篇，彩色发我容。
日月欲为报，方春已徂冬。','',''),('quantangshi-09214','答崔都水','韋應物','quantangshi','','卷10','深夜竹亭雪，孤灯案上书。
不遇无为化，谁复得闲居。','',''),('quantangshi-09215','酬令狐司录善福精舍见赠','韋應物','quantangshi','','卷10','野寺望山雪，空斋对竹林。
我以养愚地，生君道者心。','',''),('quantangshi-09216','沣上精舍答赵氏外生伉','韋應物','quantangshi','','卷10','远迹出尘表，寓身双树林。
如何小子伉，亦有超世心。
担书从我游，携手广川阴。
云开夏郊绿，景晏青山沈。
对榻遇清夜，献诗合雅音。
所推苟礼数，于性道岂深。
隐拙在冲默，经世昧古今。
无为率尔言，可以致华簪。','',''),('quantangshi-09217','答赵氏生伉','韋應物','quantangshi','','卷10','暂与云林别，忽陪鸳鹭翔。
看山不得去，知尔独相望。','',''),('quantangshi-09218','答端','韋應物','quantangshi','','卷10','郊园夏雨歇，闲院绿阴生。
职事方无効，幽赏独违情。
物色坐如见，离抱怅多盈。
况感夕凉气，闻此乱蝉鸣。','',''),('quantangshi-09219','答史馆张学士段柳庶子学士集贤院看花见寄兼呈柳学士','韋應物','quantangshi','','卷10','班杨秉文史，对院自为邻。
余香掩阁去，迟日看花频。
似雪飘阊阖，从风点近臣。
南宫有芳树，不竝禁垣春。','',''),('quantangshi-09220','答王郎中','韋應物','quantangshi','','卷10','卧阁枉芳藻，览旨怅秋晨。
守郡犹羁寓，无以慰嘉宾。
野旷归云尽，天清晓露新。
池荷凉已至，牕梧落渐频。
风物殊京国，邑里但荒榛。
赋繁属军兴，政拙愧斯人。
髦士久台阁，中路一漂沦。
归当列盛朝，岂念卧淮滨。','',''),('quantangshi-09221','答崔都水','韋應物','quantangshi','','卷10','亭亭心中人，迢迢居秦关。
常缄素札去，适枉华章还。
忆在沣郊时，携手望秋山。
久嫌官府劳，初喜罢秩闲。
终年不事业，寝食长慵顽。
不知为时来，名籍挂郎间。
摄衣辞田里，华簪耀颓颜。
卜居又依仁，日夕正追攀。
牧人本无术，命至苟复迁。
离念积岁序，归途眇山川。
郡斋有佳月，园林含清泉。
同心不在宴，罇酒徒盈前。
览君陈迹游，词意俱凄妍。
忽忽已终日，将酬不能宣。
甿税况重叠，公门极熬煎。
责逋甘首免，岁晏当归田。
勿厌守穷辙，慎为名所牵。','',''),('quantangshi-09222','答王卿送别','韋應物','quantangshi','','卷10','去马嘶春草，归人立夕阳。
元知数日别，要使两情伤。','',''),('quantangshi-09223','答裴丞说归京所献','韋應物','quantangshi','','卷10','执事颇勤久，行去亦伤乖。
家贫无僮仆，吏卒升寝斋。
衣服藏内箧，药草曝前阶。
谁复知次第，濩落且安排。
还期在岁晏，何以慰吾怀。','',''),('quantangshi-09224','答裴处士','韋應物','quantangshi','','卷10','遗民爱精舍，乘犊入青山。
来署高阳里，不遇白衣还。
礼贤方化俗，闻风自款关。
况子逸羣士，栖息蓬蒿间。','',''),('quantangshi-09225','答杨奉礼','韋應物','quantangshi','','卷10','多病守山郡，自得接嘉宾。
不见三四日，旷若十余旬。
临觞独无味，对榻已生尘。
一咏舟中作，洒雪忽惊新。
烟波见栖旅，景物具昭陈。
秋塘唯落叶，野寺不逢人。
白事廷吏简，闲居文墨亲。
高天池阁静，寒菊霜露频。
应当整孤棹，归来展殷勤。','',''),('quantangshi-09226','答端','韋應物','quantangshi','','卷10','坐忆故园人已老，宁知远郡雁还来。
长瞻西北是归路，独上城楼日几廻。','',''),('quantangshi-09227','答僴奴重阳二甥','韋應物','quantangshi','','卷10','弃职曾守拙，翫幽遂忘喧。
山涧依硗𥕂，竹树荫清源。
贫居烟火湿，岁熟梨枣繁。
风雨飘茅屋，蒿草没瓜园。
羣属相欢悦，不觉过朝昏。
有时看禾黍，落日上秋原。
饮酒任真性，挥笔肆狂言。
一朝忝兰省，三载居远藩。
复与诸弟子，篇翰每相敦。
西园休习射，南池对芳樽。
山药经雨碧，海榴凌霜飜。
念尔不同此，怅然复一论。
重阳守故家，僴子旅湘沅。
俱有缄中藻，恻恻动离魂。
不知何日见，衣上泪空存。','',''),('quantangshi-09228','答重阳','韋應物','quantangshi','','卷10','省札陈往事，怆忆数年中。
一身朝北阙，家累守田农。
望山亦临水，暇日每来同。
性情一疎散，园林多清风。
忽复隔淮海，梦想在沣东。
病来经时节，起见秋塘空。
城郭连榛岭，鸟雀噪沟丛。
坐使惊霜鬓，撩乱已如蓬。','',''),('quantangshi-09229','酬刘侍郎使君','韋應物','quantangshi','','卷10','琼树凌霜雪，葱蒨如芳春。
英贤虽出守，本自玉阶人。
宿昔陪郎署，出入仰清尘。
孰云俱列郡，比德岂为邻。
风雨飘海气，清凉悦心神。
重门深夏昼，赋诗延众宾。
方以岁月旧，每蒙君子亲。
继作郡斋什，远赠荆山珍。
高闲庶务理，游眺景物新。
朋友亦远集，燕酌在佳辰。
始唱已慙拙，将酬益难伸。
濡毫意僶俛，一用写悁勤。','',''),('quantangshi-09230','答令狐侍郎','韋應物','quantangshi','','卷10','一凶廼一吉，一是复一非。
孰能逃斯理，亮在识其微。
三黜故无愠，高贤当庶几。
但以亲交恋，音容邈难希。
况昔别离久，俱忻藩守归。
朝宴方陪厕，山川又乖违。
吴门冒海雾，峡路凌连矶。
同会在京国，相望涕沾衣。
明时重英才，当复列彤闱。
白玉虽尘垢，拂拭还光辉。','',''),('quantangshi-09231','酬张协律','韋應物','quantangshi','','卷10','昔人鬻舂地，今人复一贤。
属余藩守日，方君卧病年。
丽思阻文宴，芳踪阙宾筵。
经时岂不怀，欲往事屡牵。
公府适烦倦，开缄莹新篇。
非将握中宝，何以比其妍。
感兹栖寓词，想复疴瘵缠。
空宇风霜交，幽居情思绵。
当以贫非病，孰云白未玄。
邑中有其人，憔倅即我愆。
由来牧守重，英俊得荐延。
匪人等鸿毛，斯道何由宣。
遭时无早晚，蕴器俟良缘。
观文心未衰，勿药疾当痊。
晨期简牍罢，驰慰子忡然。','',''),('quantangshi-09232','答秦十四校书','韋應物','quantangshi','','卷10','知掩山扉三十秋，鱼须翠碧弃牀头。
莫道谢公方在郡，五言今日为君休。','',''),('quantangshi-09233','答宾','韋應物','quantangshi','','卷10','斜月才鉴帷，凝霜偏冷枕。
持情须耿耿，故作单牀寝。','',''),('quantangshi-09234','答郑骑曹青橘绝句','韋應物','quantangshi','','卷10','怜君卧病思新橘，试摘犹酸亦未黄。
书后欲题三百颗，洞庭须待满林霜。','',''),('quantangshi-09235','奉和圣制重阳日赐宴','韋應物','quantangshi','','卷10','圣心忧万国，端居在穆清。
玄功致海[晏]，锡宴表文明。
恩属重阳节，雨应此时晴。
寒菊生池苑，高树出宫城。
捧藻千官处，垂戒百王程。
复覩开元日，臣愚献颂声。','',''),('quantangshi-09236','和吴舍人早春归沐西亭言志','韋應物','quantangshi','','卷10','晓漏戒中禁，清香肃朝衣。
一门双掌诰，伯侍仲言归。
亭高性情旷，职密交游稀。
赋诗乐无事，解带偃南扉。
阳春美时泽，旭霁望山晖。
幽禽响未转，东原绿犹微。
名虽列仙爵，心已遣尘机。
即事同岩隐，圣渥良难违。','',''),('quantangshi-09237','奉和张大夫戏示青山郎','韋應物','quantangshi','','卷10','天生逸世姿，竹马不曾骑。
览卷冰将释，援毫露欲垂。
金貂传几叶，玉树长新枝。
荣禄何妨早，甘罗亦小儿。','',''),('quantangshi-09238','答河南李士巽题香山寺','韋應物','quantangshi','','卷10','洛都游宦日，少年携手行。
投杯起芳席，总辔振华缨。
关塞有佳气，岩开伊水清。
攀林憩佛寺，登高望都城。
蹉跎二十载，世务各所营。
兹赏长在梦，故人安得并。
前岁守九江，恩诏赴咸京。
因涂再登历，山河属晴明。
寂寞僧侣少，苍茫林木成。
墙宇或崩剥，不见旧题名。
旧游况存殁，独此泪交横。
交横谁与同，书壁贻友生。
今兹守吴郡，绵思方未平。
子复经陈迹，一感我深情。
远蒙恻怆篇，中有金玉声。
反覆终难答，金玉尚为轻。','',''),('quantangshi-09239','答故人见谕','韋應物','quantangshi','','卷10','素寡名利心，自非周圆器。
徒以岁月资，屡蒙藩条寄。
时风重书札，物情敦货遗。
机杼十缣单，慵疎百函愧。
常负交亲责，且为一官累。
况本濩落人，归无置锥地。
省己已知非，枉书见深致。
虽欲效区区，何由枉其志。','',''),('quantangshi-09240','酬阎员外陟','韋應物','quantangshi','','卷10','寒夜阻良觌，丛竹想幽居。
虎符[予]已误，金丹子何如。
宴集观农暇，笙歌听讼余。
虽蒙一言教，自愧道情疎。','',''),('quantangshi-09241','酬秦征君徐少府春日见寄','韋應物','quantangshi','','卷10','终日愧无政，与君聊散襟。
城根山半腹，亭影水中心。
朗咏竹牕静，野情花迳深。
那能有余兴，不作剡溪寻。','',''),('quantangshi-09242','冬夜宿司空曙野居因寄酬赠','韋應物','quantangshi','','卷10','南北与山邻，蓬庵庇一身。
繁霜疑有雪，荒草似无人。
遂性在耕稼，所交唯贱贫。
何掾张椽傲，每重德璋亲。','',''),('quantangshi-09243','长安遇冯着','韋應物','quantangshi','','卷10','客从东方来，衣上灞陵雨。
问客何为来，采山因买斧。
冥冥花正开，扬扬燕新乳。
昨别今已春，鬓丝生几缕。','',''),('quantangshi-09244','将发楚州经宝应县访李二忽于州馆相遇月夜书事因简李宝应','韋應物','quantangshi','','卷10','孤舟欲夜发，祗为访情人。
此地忽相遇，留连意更新。
停杯嗟别久，对月言家贫。
一问临邛令，如何待上宾。','',''),('quantangshi-09245','广陵遇孟九云卿','韋應物','quantangshi','','卷10','雄藩本帝都，游士多俊贤。
夹河树郁郁，华馆千里连。
新知虽满堂，中意颇未宣。
忽逢翰林友，欢乐斗酒前。
高文激颓波，四海靡不传。
西施且一笑，众女安得妍。
明月满淮海，哀鸿逝长天。
所念京国远，我来君欲还。','',''),('quantangshi-09246','淮上遇洛阳李主簿','韋應物','quantangshi','','卷10','结茅临古渡，卧见长淮流。
窗里人将老，门前树已秋。
寒山独过雁，暮雨远来舟。
日夕逢归客，那能忘旧游。','',''),('quantangshi-09247','路逢崔元二侍御避马见招以诗见赠','韋應物','quantangshi','','卷10','一台称二妙，归路望行尘。
俱是攀龙客，空为避马人。
见招翻局蹐，相问良殷勤。
日日吟趋府，弹冠岂有因。','',''),('quantangshi-09248','逢杨开府','韋應物','quantangshi','','卷10','少事武皇帝，无赖恃恩私。
身作里中横，家藏亡命儿。
朝持樗蒲局，暮窃东邻姬。
司隶不敢捕，立在白玉墀。
骊山风雪夜，长杨羽猎时。
一字都不识，饮酒肆顽痴。
武皇升仙去，憔悴被人欺。
读书事已晚，把笔学题诗。
两府始收迹，南宫谬见推。
非才果不容，出守抚惸嫠。
忽逢杨开府，论旧涕俱垂。
坐客何由识，惟有故人知。','',''),('quantangshi-09249','休暇日访王侍御不遇','韋應物','quantangshi','','卷10','九日驱驰一日闲，寻君不遇又空还。
怪来诗思清人骨，门对寒流雪满山。','',''),('quantangshi-09250','因省风俗访道士侄不见题壁','韋應物','quantangshi','','卷10','去年涧水今亦流，去年杏花今又拆。
山人归来问是谁，还是去年行春客。','',''),('quantangshi-09251','有所思','韋應物','quantangshi','','卷10','借问堤上柳，青青为谁春。
空游昨日地，不见昨日人。
缭绕万家井，往来车马尘。
莫道无相识，要非心所亲。','',''),('quantangshi-09252','暮相思','韋應物','quantangshi','','卷10','朝出自不还，暮归花尽发。
岂无终日会，惜此花间月。
空馆忽相思，微钟坐来歇。','',''),('quantangshi-09253','夏夜忆卢嵩','韋應物','quantangshi','','卷10','霭霭高馆暮，开轩涤烦襟。
不知湘雨来，潇洒在幽林。
炎月得凉夜，芳樽谁与斟。
故人南北居，累月间徽音。
人生无闲日，欢会当在今。
反侧候天旦，层城苦沈沈。','',''),('quantangshi-09254','春思','韋應物','quantangshi','','卷10','野花如雪绕江城，坐见年芳忆帝京。
阊阖晓开凝碧树，曾陪鸳鹭听流莺。','',''),('quantangshi-09255','春中忆元二','韋應物','quantangshi','','卷10','雨歇万井春，柔条已含緑。
徘徊洛阳陌，惆怅杜陵曲。
游丝正高下，啼鸟还断续。
有酒今不同，思君莹如玉。','',''),('quantangshi-09256','怀素友子西','韋應物','quantangshi','','卷10','广陌竝游骑，公堂接华襟。
方欢遽见别，永日独沈吟。
阶暝流暗驶，气疎露已侵。
层城湛深夜，片月生幽林。
往款良未遂，来觌旷无音。
恒当清觞宴，思子玉山岑。
耿耿何以写，密言空委心。','',''),('quantangshi-09257','对韩少尹所赠砚有怀','韋應物','quantangshi','','卷10','故人谪遐远，留砚宠斯文。
白水浮香墨，清池满夏云。
念离心已永，感物思徒纷。
未有桂阳使，裁书一报君。','',''),('quantangshi-09258','月晦忆去年与亲友曲水游宴','韋應物','quantangshi','','卷10','晦赏念前岁，京国结良俦。
骑出宣平里，饮对曲池流。
今朝隔天末，空园伤独游。
雨歇林光变，塘緑鸟声幽。
凋甿积逋税，华鬓集新秋。
谁言恋虎符，终当还旧丘。','',''),('quantangshi-09259','清明日忆诸弟','韋應物','quantangshi','','卷10','冷食方多病，开襟一忻然。
终令思故郡，烟火满晴川。
杏粥犹堪食，榆羹已稍煎。
唯恨乖亲燕，坐度此芳年。','',''),('quantangshi-09260','池上怀王卿','韋應物','quantangshi','','卷10','幽居捐世事，佳雨散园芳。
入门霭已緑，水禽鸣春塘。
重云始成夕，忽霁尚残阳。
轻舟因风泛，郡阁望苍苍。
私燕阻外好，临欢一停觞。
兹游无时尽，旭日愿相将。','',''),('quantangshi-09261','立夏日忆京师诸弟','韋應物','quantangshi','','卷10','改序念芳辰，烦襟倦日永。
夏木已成阴，公门昼恒静。
长风始飘阁，叠云才吐岭。
坐想离居人，还当惜徂景。','',''),('quantangshi-09262','晓至园中忆诸弟崔都水','韋應物','quantangshi','','卷10','山郭恒悄悄，林月亦娟娟。
景清神已澄，事简虑绝牵。
秋塘徧衰草，晓露洗红莲。
不见心所爱，兹赏岂为妍。','',''),('quantangshi-09263','怀琅琊深标二释子','韋應物','quantangshi','','卷10','白云埋大壑，阴崖滴夜泉。
应居西石室，月照山苍然。','',''),('quantangshi-09264','雨夜感怀','韋應物','quantangshi','','卷10','微雨洒高林，尘埃自萧散。
耿耿心未平，沈沈夜方半。
独惊长簟冷，遽觉愁鬓换。
谁能当此夕，不有盈襟叹。','',''),('quantangshi-09265','云阳馆怀谷口','韋應物','quantangshi','','卷10','清泚阶下流，云自谷口源。
念昔白衣士，结庐在石门。
道高杳无累，景静得忘言。
山夕绿阴满，世移清赏存。
吏役岂遑暇，幽怀复朝昏。
云泉非所濯，萝月不可援。
长往遂真性，暂游恨卑喧。
出身既事世，高躅难等论。','',''),('quantangshi-09266','忆沣上幽居','韋應物','quantangshi','','卷10','一来当复去，犹此厌樊笼。
况我林栖子，朝服坐南宫。
唯独问啼鸟，还如沣水东。','',''),('quantangshi-09267','重九登滁城楼忆前岁九日归沣上赴崔都水及诸弟宴集凄然怀旧','韋應物','quantangshi','','卷10','今日重九宴，去岁在京师。
聊廻出省步，一赴郊园期。
嘉节始云迈，周辰已及兹。
秋山满清景，当赏属乖离。
凋散民里阔，摧翳众木衰。
楼中一长啸，恻怆起凉飔。','',''),('quantangshi-09268','始夏南园思旧里','韋應物','quantangshi','','卷10','夏首云物变，雨余草木繁。
池荷初帖水，林花已扫园。
萦丛蝶尚乱，依阁鸟犹喧。
对此残芳月，忆在汉陵原。','',''),('quantangshi-09269','登蒲塘驿沿路见泉谷邨墅忽想京师旧居追怀昔年','韋應物','quantangshi','','卷10','青山导骑遶，春风行斾舒。
均徭视属城，问疾躬里闾。
烟水依泉谷，川陆散樵渔。
忽念故园日，复忆骊山居。
荏苒斑鬓及，梦寝婚宦初。
不觉平生事，咄嗟二纪余。
存殁阔已永，悲多欢自疎。
高秩非为美，阑干泪盈裾。','',''),('quantangshi-09270','经函谷关','韋應物','quantangshi','','卷10','洪河绝山根，单轨出其侧。
万古为要枢，往来何时息。
秦皇即恃险，海内被吞食。
及嗣同覆颠，咽喉莫能塞。
炎灵讵西驾，娄子非经国。
徒欲扼诸侯，不知恢至德。
圣朝及天宝，豺虎起东北。
下沈战死魂，上结穷冤色。
古今虽共守，成败良可识。
藩屏无俊贤，金汤独何力。
[驰]车一登眺，感慨中自恻。','',''),('quantangshi-09271','经武功旧宅','韋應物','quantangshi','','卷10','兹邑昔所游，嘉会常在目。
历载俄二九，始往今来复。
戚戚居人少，茫茫野田绿。
风雨经旧墟，毁垣迷往躅。
门临川流驶，树有羇雌宿。
多累恒悲往，长年觉时速。
欲去中复留，徘徊结心曲。','',''),('quantangshi-09272','往云门郊居涂经廻流作','韋應物','quantangshi','','卷10','兹晨乃休暇，适往田家庐。
原谷径涂涩，春阳草木敷。
才遵板桥曲，复此清涧纡。
崩壑方见射，廻流忽已舒。
明灭泛孤景，杳霭含夕虚。
无将为邑志，一酌澄波余。','',''),('quantangshi-09273','乘月过西郊渡','韋應物','quantangshi','','卷10','远山含紫氛，春野霭云暮。
值此归时月，留连西涧渡。
谬当文墨会，得与羣英遇。
赏逐乱流翻，心将清景悟。
行车俨未转，芳草空盈步。
已举候亭火，犹爱村原树。
还当守故扃，怅恨秉幽素。','',''),('quantangshi-09274','晚归沣川','韋應物','quantangshi','','卷10','凌雾朝阊阖，落日返清川。
簪组方暂解，临水一翛然。
昆弟忻来集，童稚满眼前。
适意在无事，携手望秋田。
南岭横爽气，高林绕遥阡。
野庐不锄理，翳翳起荒烟。
名秩斯逾分，廉退愧不全。
已想平门路，晨骑复言旋。','',''),('quantangshi-09275','授衣还田里','韋應物','quantangshi','','卷10','公门悬甲令，澣濯遂其私。
晨起怀怆恨，野田寒露时。
气收天地广，风凄草木衰。
山明始重叠，川浅更逶迤。
烟火生闾里，禾黍积东菑。
终然可乐业，时节一来斯。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-09276','夕次盱眙县','韋應物','quantangshi','','卷10','落帆逗淮镇，停舫临孤驿。
浩浩风起波，冥冥日沈夕。
人归山郭暗，雁下芦洲白。
独夜忆秦关，听钟未眠客。','',''),('quantangshi-09277','春月观省属城始憩东西林精舍','韋應物','quantangshi','','卷10','因时省风俗，布惠迨高年。
建隼出浔阳，整驾游山川。
白云敛晴壑，羣峰列遥天。
嵚㟢石门状，杳霭香炉烟。
榛荒屡罥罣，逼侧殆覆颠。
方臻释氏庐，时物屡华妍。
昙远昔经始，于兹閟幽玄。
东西竹林寺，灌注寒涧泉。
人事即云泯，岁月复已绵。
殿宇余丹绀，磴阁峭欹悬。
佳士亦栖息，善身绝尘缘。
今我蒙朝寄，教化敷里鄽。
道妙苟为得，出处理无偏。
心当同所尚，迹岂辞缠牵。','',''),('quantangshi-09278','自蒲塘驿廻驾经历山水','韋應物','quantangshi','','卷10','馆宿风雨滞，始晴行盖转。
浔阳山水多，草木俱纷衍。
崎岖缘碧涧，苍翠践苔藓。
高树夹潺湲，崩石横阴巘。
野杏依寒拆，余云冒岚浅。
性惬形岂劳，境殊路遗缅。
忆昔终南下，佳游亦屡展。
时禽下流暮，纷思何由遣。','',''),('quantangshi-09279','山行积雨归途始霁','韋應物','quantangshi','','卷10','揽辔穷登降，阴雨遘二旬。
但见白云合，不睹岩中春。
急涧岂易揭，峻涂良难遵。
深林猿声冷，沮洳虎迹新。
始霁升阳景，山水阅清晨。
杂花积如雾，百卉萋已陈。
鸣驺屡骧首，归路自忻忻。','',''),('quantangshi-09280','伤逝','韋應物','quantangshi','','卷10','染白一为黑，焚木尽成灰。
念我室中人，逝去亦不廻。
结发二十载，宾敬如始来。
提携属时屯，契阔忧患灾。
柔素亮为表，礼章夙所该。
仕公不及私，百事委令才。
一旦入闺门，四屋满尘埃。
斯人既已矣，触物但伤摧。
单居移时节，泣涕抚婴孩。
知妄谓当遣，临感要难裁。
梦想忽如睹，惊起复徘徊。
此心良无已，遶屋生蒿莱。','',''),('quantangshi-09281','往富平伤怀','韋應物','quantangshi','','卷10','晨起凌严霜，恸哭临素帷。
驾言百里涂，恻怆复何为。
昨者仕公府，属城常载驰。
出门无所忧，返室亦熙熙。
今者掩筠扉，但闻童稚悲。
丈夫须出入，顾尔内无依。
衔恨已酸骨，何况苦寒时。
单车路萧条，廻首长逶迟。
飘风忽截野，嘹唳雁起飞。
昔时同往路，独往今讵知。','',''),('quantangshi-09282','出还','韋應物','quantangshi','','卷10','昔出喜还家，今还独伤意。
入室掩无光，衔哀写虚位。
凄凄动幽幔，寂寂惊寒吹。
幼女复何知，时来庭下戏。
咨嗟日复老，错莫身如寄。
家人劝我飡，对案空垂泪。','',''),('quantangshi-09283','冬夜','韋應物','quantangshi','','卷10','杳杳日云夕，郁结谁为开。
单衾自不暖，霜霰已皑皑。
晚岁沦夙志，惊鸿感深哀。
深哀当何为，桃李忽凋摧。
帏怅徒自设，冥寞岂复来。
平生虽恩重，迁去托穷埃。
抱此女曹恨，顾非高世才。
振衣中夜起，河汉尚裴回。','',''),('quantangshi-09284','送终','韋應物','quantangshi','','卷10','奄忽逾时节，日月获其良。
萧萧车马悲，祖载发中堂。
生平同此居，一旦异存亡。
斯须亦何益，终复委山冈。
行出国南门，南望郁苍苍。
日入乃云造，恸哭宿风霜。
晨迁俯玄庐，临诀但遑遑。
方当永潜翳，仰视白日光。
俯仰遽终毕，封树已荒凉。
独留不得还，欲去结中肠。
童稚知所失，啼号捉我裳。
既事犹仓卒，岁月始难忘。','',''),('quantangshi-09285','除日','韋應物','quantangshi','','卷10','思怀耿如昨，季月已云暮。
忽惊年复新，独恨人成故。
冰池始泮绿，梅楥还飘素。
淑景方转延，朝朝自难度。','',''),('quantangshi-09286','对芳树','韋應物','quantangshi','','卷10','迢迢芳园树，列映清池曲。
对此伤人心，还如故时绿。
风条洒余霭，露叶承新旭。
佳人不再攀，下有往来躅。','',''),('quantangshi-09287','月夜','韋應物','quantangshi','','卷10','皓月流春城，华露积芳草。
坐念绮窗空，翻伤清景好。
清景终若斯，伤多人自老。','',''),('quantangshi-09288','叹杨花','韋應物','quantangshi','','卷10','空蒙不自定，况值暄风度。
旧赏逐流年，新愁忽盈素。
才萦下苑曲，稍满东城路。
人意有悲欢，时芳独如故。','',''),('quantangshi-09289','过昭国里故第','韋應物','quantangshi','','卷10','不复见故人，一来过故宅。
物变知景暄，心伤觉时寂。
池荒野筠合，庭绿幽草积。
风散花意谢，鸟还山光夕。
宿昔方同赏，讵知今念昔。
缄室在东厢，遗器不忍觌。
柔翰全分意，芳巾尚染泽。
残工委筐箧，余素经刀尺。
收此还我家，将还复愁惕。
永绝携手欢，空存旧行迹。
冥冥独无语，杳杳将何适。
唯思今古同，时缓伤与戚。','',''),('quantangshi-09290','夏日','韋應物','quantangshi','','卷10','已谓心苦伤，如何日方永。
无人不昼寝，独坐山中静。
悟澹将遣虑，学空庶遗境。
积俗易为侵，愁来复难整。','',''),('quantangshi-09291','端居感怀','韋應物','quantangshi','','卷10','沈沈积素抱，婉婉属之子。
永日独无言，忽惊振衣起。
方如在帏室，复悟永终已。
稚子伤恩绝，盛时若流水。
暄凉同寡趣，朗晦俱无理。
寂性常喻人，滞情今在己。
空房欲云暮，巢燕亦来止。
夏木遽成阴，绿苔谁复履。
感至竟何方，幽独长如此。','',''),('quantangshi-09292','悲纨扇','韋應物','quantangshi','','卷10','非关秋节至，讵是恩情改。
掩嚬人已无，委箧凉空在。
何言永不发，暗使销光彩。','',''),('quantangshi-09293','闲斋对雨','韋應物','quantangshi','','卷10','幽独自盈抱，阴淡亦连朝。
空斋对高树，疎雨共萧条。
巢燕翻泥湿，蕙花依砌消。
端居念往事，倏忽苦惊飙。','',''),('quantangshi-09294','林园晚霁','韋應物','quantangshi','','卷10','雨歇见青山，落日照林园。
山多烟鸟乱，林清风景翻。
提携唯子弟，萧散在琴言。
同游不同意，耿耿独伤魂。
寂寞钟已尽，如何还入门。','',''),('quantangshi-09295','秋夜二首 一','韋應物','quantangshi','','卷10','庭树转萧萧，阴虫还戚戚。
独向高斋眠，夜闻寒雨滴。
微风时动牖，残灯尚留壁。
惆怅平生怀，偏来委今夕。','',''),('quantangshi-09296','秋夜二首 二','韋應物','quantangshi','','卷10','霜露已凄凄，星汉复昭回。
朔风中夜起，惊鸿千里来。
萧条凉叶下，寂寞清砧哀。
岁晏仰空宇，心事若寒灰。','',''),('quantangshi-09297','感梦','韋應物','quantangshi','','卷10','岁月转芜漫，形影长寂寥。
仿髴觏微梦，感叹起中宵。
绵思霭流月，惊魂飒廻飙。
谁念兹夕永，坐令颜鬓凋。','',''),('quantangshi-09298','同德精舍旧居伤怀','韋應物','quantangshi','','卷10','洛京十载别，东林访旧扉。
山河不可望，存没意多违。
时迁迹尚在，同去独来归。
还见窗中鸽，日暮遶庭飞。','',''),('quantangshi-09299','悲故交','韋應物','quantangshi','','卷10','白璧众求瑕，素丝易成污。
万里颠沛还，高堂已长暮。
积愤方盈抱，缠哀忽逾度。
念子从此终，黄泉竟谁诉。
一为时事感，岂独平生故。
唯见荒丘原，野草涂朝露。','',''),('quantangshi-09300','张彭州前与缑氏冯少府各惠寄一篇多故未答张已云没因追哀叙事兼远简冯生','韋應物','quantangshi','','卷10','君昔掌文翰，西垣复石渠。
朱衣乘白马，辉光照里闾。
余时忝南省，接宴愧空虚。
一别守兹郡，蹉跎岁再除。
长怀关河表，永日简牍余。
郡中有方塘，凉阁对红蕖。
金玉蒙远贶，篇咏见吹嘘。
未答平生意，已没九原居。
秋风吹寝门，长恸涕涟如。
覆视缄中字，奄为昔人书。
发鬓已云白，交友日雕疎。
冯生远同恨，憔悴在田庐。','',''),('quantangshi-09301','东林精舍见故殿中郑侍御题诗追旧书情涕泗横集因寄呈阎澧州冯少府','韋應物','quantangshi','','卷10','仲月景气佳，东林一登历。
中有故人诗，凄凉在高壁。
精思长悬世，音容已归寂。
墨泽传洒余，磨灭亲翰迹。
平生忽如梦，百事皆成昔。
结骑京华年，挥文箧笥积。
朝廷重英彦，时辈分圭璧。
永谢柏梁陪，独阙金门籍。
方婴存殁感，岂暇林泉适。
雨余山景寒，风散花光夕。
新知虽满堂，故情谁能觌。
唯当同时友，缄寄空凄戚。','',''),('quantangshi-09302','同李二过亡友郑子故第','韋應物','quantangshi','','卷10','客车名未灭，没世恨应长。
斜月知何照，幽林判自芳。
故人惊逝水，寒雀噪空墙。
不是平生旧，遗踪要可伤。','',''),('quantangshi-09303','话旧','韋應物','quantangshi','','卷10','存亡三十载，事过悉成空。
不惜霑衣泪，并话一宵中。','',''),('quantangshi-09304','至开化里寿春公故宅','韋應物','quantangshi','','卷10','宁知府中吏，故宅一徘徊。
历阶存往敬，瞻位泣余哀。
废井没荒草，阴牖生緑笞。
门前车马散，非复昔时来。','',''),('quantangshi-09305','睢阳感怀','韋應物','quantangshi','','卷10','豺虎犯天纲，升平无内备。
长驱阴山卒，略践三河地。
张侯本忠烈，济世有深智。
坚壁梁宋间，远筹吴楚利。
穷年方绝输，邻援皆携贰。
使者哭其庭，救兵终不至。
重围虽可越，藩翰谅难弃。
饥喉待危巢，悬命中路坠。
甘从锋刃毙，莫夺坚贞志。
宿将降贼庭，儒生独全义。
空城唯白骨，同往无贱贵。
哀哉岂独今，千载当歔欷。','',''),('quantangshi-09306','广德中洛阳作','韋應物','quantangshi','','卷10','生长太平日，不知太平欢。
今还洛阳中，感此方苦酸。
饮药本攻病，毒肠翻自残。
王师涉河洛，玉石俱不完。
时节屡迁斥，山河长郁盘。
萧条孤烟绝，日入空城寒。
蹇劣乏高步，缉遗守微官。
西怀咸阳道，踯躅心不安。','',''),('quantangshi-09307','阊门怀古','韋應物','quantangshi','','卷10','独鸟下高树，遥知吴苑园。
凄凉千古事，日暮倚阊门。','',''),('quantangshi-09308','感事','韋應物','quantangshi','','卷10','霜雪皎素丝，何意坠墨池。
青苍犹可濯，黑色不可移。
女工再三叹，委弃当此时。
岁寒虽无褐，机杼谁肯施。','',''),('quantangshi-09309','感镜','韋應物','quantangshi','','卷10','铸镜广陵市，菱花匣中发。
夙昔尝许人，镜成人已没。
如冰结圆器，类璧无丝发。
形影终不临，清光殊不歇。
一感平生言，松枝树秋月。','',''),('quantangshi-09310','叹白发','韋應物','quantangshi','','卷10','还同一叶落，对此孤镜晓。
丝缕乍难分，杨花复相遶。
时役人易衰，吾年白犹少。','',''),('quantangshi-09311','登高望洛城作','韋應物','quantangshi','','卷10','高台造云端，遐瞰周四垠。
雄都定鼎地，势据万国尊。
河岳出云雨，土圭酌干坤。
舟通南越贡，城背北邙原。
帝宅夹清洛，丹霞捧朝暾。
葱茏瑶台榭，𥦖窱双阙门。
十载构屯难，兵戈若云屯。
膏腴满榛芜，比屋空毁垣。
圣主乃东眷，俾贤拯元元。
熙熙居守化，泛泛太府恩。
至损当受益，苦寒必生温。
平明四城开，稍见市井喧。
坐感理乱迹，永怀经济言。
吾生自不达，空鸟何翩翻。
天高水流远，日晏城郭昏。
裴回讫旦夕，聊用写忧烦。','',''),('quantangshi-09312','同德寺阁集眺','韋應物','quantangshi','','卷10','芳节欲云晏，游遨乐相从。
高阁照丹霞，飗飗含远风。
寂寥氛氲廓，超忽神虑空。
旭日霁皇州，岧峣见两宫。
嵩少多秀色，羣山莫与崇。
三川浩东注，瀍涧亦来同。
阴阳降大和，宇宙得其中。
舟车满川陆，四国靡不通。
旧堵今即葺，庶甿亦已丰。
周览思自奋，行当遇时邕。','',''),('quantangshi-09313','登宝意寺上方旧游','韋應物','quantangshi','','卷10','翠岭香台出半天，万家烟树满晴川。
诸僧近住不相识，坐听微钟记往年。','',''),('quantangshi-09314','登乐游庙作','韋應物','quantangshi','','卷10','高原出东城，郁郁见咸阳。
上有千载事，乃自汉宣皇。
颓壖久凌迟，陈迹翳丘荒。
春草虽复绿，惊风但飘扬。
周览京城内，双阙起中央。
微钟何处来，暮色忽苍苍。
歌吹喧万井，车马塞康庄。
昔人岂不尔，百世同一伤。
归当守冲漠，迹寓心自忘。','',''),('quantangshi-09315','登西南冈卜居遇雨寻竹浪至沣壖萦带数里清流茂树云物可赏','韋應物','quantangshi','','卷10','登高创危构，林表见川流。
微雨飒已至，萧条川气秋。
下寻密竹尽，忽旷沙际游。
纡曲水分野，绵延稼盈畴。
寒花明废墟，樵牧笑榛丘。
云水成阴澹，竹树更清幽。
适自恋佳赏，复兹永日留。','',''),('quantangshi-09316','沣上与幼遐月夜登西冈翫花','韋應物','quantangshi','','卷10','置酒临高隅，佳人自城阙。
已翫满川花，还看满川月。
花月方浩然，赏心何由歇。','',''),('quantangshi-09317','台上迟客','韋應物','quantangshi','','卷10','高台一悄望，远树间朝晖。
但见东西骑，坐令心赏违。
始霁郊原绿，暮春啼鸟稀。
徒然对芳物，何能独醉归。','',''),('quantangshi-09318','登楼','韋應物','quantangshi','','卷10','兹楼日登眺，流岁暗蹉跎。
坐厌淮南守，秋山红树多。','',''),('quantangshi-09319','善福寺阁','韋應物','quantangshi','','卷10','残霞照高阁，青山出远林。
晴明一登望，潇洒此幽襟。','',''),('quantangshi-09320','楼中月夜','韋應物','quantangshi','','卷10','端令倚悬槛，长望抱沈忧。
宁知故园月，今夕在兹楼。
衰莲送余馥，华露湛新秋。
坐见苍林变，清辉怆已休。','',''),('quantangshi-09321','寒食后北楼作','韋應物','quantangshi','','卷10','园林过新节，风花乱高阁。
遥闻击鼓声，蹴鞠军中乐。','',''),('quantangshi-09322','西楼','韋應物','quantangshi','','卷10','高阁一长望，故园何日归？烟尘拥函谷，秋雁过来稀。','',''),('quantangshi-09323','夜望','韋應物','quantangshi','','卷10','南楼夜已寂，暗鸟动林间。
不见城郭事，沈沈唯四山。','',''),('quantangshi-09324','晚登郡阁','韋應物','quantangshi','','卷10','怅然高阁望，已掩东城关。
春风偏送柳，夜景欲沈山。','',''),('quantangshi-09325','登重玄寺阁','韋應物','quantangshi','','卷10','时暇陟云构，晨霁澄景光。
始见吴都大，十里郁苍苍。
山川表明丽，湖海吞大荒。
合沓臻水陆，骈阗会四方。
俗繁节又暄，雨顺物亦康。
禽鱼各翔泳，草木遍芬芳。
于兹省甿俗，一用劝农桑。
诚知虎符忝，但恨归路长。','',''),('quantangshi-09326','观早朝','韋應物','quantangshi','','卷10','伐鼓通严城，车马溢广躔。
煌煌列明烛，朝服照华鲜。
金门杳深沈，尚听清漏传。
河汉忽已没，司阍启晨关。
丹殿据龙首，崔嵬对南山。
寒生千门里，日照双阙间。
禁旅下成列，炉香起中天。
辉辉覩明圣，济济行俊贤。
愧无鸳鹭姿，短翮空飞还。
谁当假毛羽，云路相追攀。','',''),('quantangshi-09327','陪元侍御春游','韋應物','quantangshi','','卷10','何处醉春风，长安西复东。
不因俱罢职，岂得此时同。
贳酒宣平里，寻芳下苑中。
往来杨柳陌，犹避昔年骢。','',''),('quantangshi-09328','游龙门香山泉','韋應物','quantangshi','','卷10','山水本自佳，游人已忘虑。
碧泉更幽绝，赏爱未能去。
潺湲写幽磴，缭绕带嘉树。
激转忽殊流，归泓又同注。
羽觞自成翫，永日亦延趣。
灵草有时香，仙源不知处。
还当候圆月，携手重游寓。','',''),('quantangshi-09329','龙门游眺','韋應物','quantangshi','','卷10','凿山导伊流，中断若天辟。
都门遥相望，佳气生朝夕。
素怀出尘意，适有携手客。
精舍遶层阿，千龛邻峭壁。
缘云路犹缅，憩涧钟已寂。
花树发烟华，淙流散石脉。
长啸招远风，临潭漱金碧。
日落望都城，人间何役役。','',''),('quantangshi-09330','洛都游寓','韋應物','quantangshi','','卷10','东风日已和，元化亮无私。
草木同时植，生条有高卑。
罢官守园庐，岂不怀渴饥。
穷通非所干，局促当何为。
佳辰幸可游，亲友亦相追。
朝从华林宴，暮返东城期。
掇英出兰臯，翫月步川坻。
轩冕诚可慕，所忧在絷维。','',''),('quantangshi-09331','再游龙门怀旧侣','韋應物','quantangshi','','卷10','两山郁相对，晨策方上干。
霭霭眺都城，悠悠俯清澜。
邈矣二三子，兹焉屡游盘。
良时忽已周，独往念前欢。
好鸟始云至，众芳亦未阑。
遇物岂殊昔，慨伤自有端。','',''),('quantangshi-09332','庄严精舍游集','韋應物','quantangshi','','卷10','良游因时暇，乃在西南隅。
绿烟凝层城，丰草满通衢。
精舍何崇旷，烦局一弘舒。
架虹施广荫，构云眺八区。
既此尘境远，忽闻幽鸟殊。
新林泛景光，丛绿含露濡。
永日亮难遂，平生少欢娱。
谁能遽还归，幸与高士俱。','',''),('quantangshi-09333','府舍月游','韋應物','quantangshi','','卷10','官舍耿深夜，佳月喜同游。
横河俱半落，泛露忽惊秋。
散彩疎羣树，分规澄素流。
心期与浩景，苍苍殊未收。','',''),('quantangshi-09334','任鄠令渼陂游眺','韋應物','quantangshi','','卷10','野水滟长塘，烟花乱晴日。
氤氲绿树多，苍翠千山出。
游鱼时可见，新荷尚未密。
屡往心独闲，恨无理人术。','',''),('quantangshi-09335','西郊游瞩','韋應物','quantangshi','','卷10','东风散余冱，陂水淡已绿。
烟芳何处寻，杳蔼春山曲。
新禽哢暄节，晴光泛嘉木。
一与诸君游，华觞忻见属。','',''),('quantangshi-09336','再游西郊渡','韋應物','quantangshi','','卷10','水曲一追游，游人重怀恋。
婵娟昨夜月，还向波中见。
惊禽栖不定，流芳寒未徧。
携手更何时，伫看花似霰。','',''),('quantangshi-09337','月溪与幼遐君贶同游','韋應物','quantangshi','','卷10','岸筱覆廻溪，廻溪曲如月。
沈沈水容绿，寂寂流莺歇。
浅石方凌乱，游禽时出没。
半雨夕阳霏，缘源杂花发。
明晨重来此，同心应已阙。','',''),('quantangshi-09338','与幼遐君贶兄弟同游白家竹潭','韋應物','quantangshi','','卷10','清赏非素期，偶游方自得。
前登绝岭险，下视深潭黑。
密竹已成暮，归云殊未极。
春鸟依谷暄，紫兰含幽色。
已将芳景遇，复款平生忆。
终念一欢别，临风还默默。','',''),('quantangshi-09339','秋夕西斋与僧神静游','韋應物','quantangshi','','卷10','晨登西斋望，不觉至夕曛。
正当秋夏交，原野起烟氛。
坐听凉飙举，华月稍披云。
漠漠山犹隐，滟滟川始分。
物幽夜更殊，境静兴弥臻。
息机非傲世，于时乏嘉闻。
究空自为理，况与释子羣。','',''),('quantangshi-09340','观田家','韋應物','quantangshi','','卷10','微雨众卉新，一雷惊蛰始。
田家几日闲，耕种从此起。
丁壮俱在野，场圃亦就理。
归来景常晏，饮犊西涧水。
饥劬不自苦，膏泽且为喜。
仓廪无宿储，徭役犹未已。
方慙不耕者，禄食出闾里。','',''),('quantangshi-09341','园亭览物','韋應物','quantangshi','','卷10','积雨时物变，夏绿满园新。
残花已落实，高笋半成筠。
守此幽栖地，自是忘机人。','',''),('quantangshi-09342','观沣水涨','韋應物','quantangshi','','卷10','夏雨万壑凑，沣涨暮浑浑。
草木盈川谷，澶漫一平吞。
槎梗方弥泛，涛沫亦洪翻。
北来注泾渭，所过无安源。
云岭同昏黑，观望悸心魂。
舟人空敛棹，风波正自奔。','',''),('quantangshi-09343','陪王卿郎中游南池','韋應物','quantangshi','','卷10','鵷鸿俱失侣，同为此地游。
露浥荷花气，风散柳园秋。
烟草凝衰屿，星汉泛归流。
林高初上月，塘深未转舟。
清言屡往复，华樽始献酬。
终忆秦川赏，端坐起离忧。','',''),('quantangshi-09344','南园陪王卿游瞩','韋應物','quantangshi','','卷10','形迹虽拘检，世事澹无心。
郡中多山水，日夕听幽禽。
几阁文墨暇，园林春景深。
杂花芳意散，绿池暮色沈。
君子有高躅，相携在幽寻。
一酌何为贵，可以写冲襟。','',''),('quantangshi-09345','游西山','韋應物','quantangshi','','卷10','时事方扰扰，幽赏独悠悠。
弄泉朝涉涧，采石夜归州。
挥翰题苍峭，下马历嵌丘。
所爱唯山水，到此即淹留。','',''),('quantangshi-09346','春游南亭','韋應物','quantangshi','','卷10','川明气已变，岩寒云尚拥。
南亭草心绿，春塘泉脉动。
景煦听禽响，雨余看柳重。
逍遥池馆华，益愧专城宠。','',''),('quantangshi-09347','再游西山','韋應物','quantangshi','','卷10','南谯古山郡，信是高人居。
自叹乏弘量，终朝亲簿书。
于时忽命驾，秋野正萧疎。
积逋诚待责，寻山亦有余。
测测石泉冷，暧暧烟谷虚。
中有释门子，种果结茅庐。
出身厌名利，遇境即踌躇。
守直虽多忤，视险方晏如。
况将尘埃外，襟抱从此舒。','',''),('quantangshi-09348','游灵岩寺','韋應物','quantangshi','','卷10','始入松路永，独忻山寺幽。
不知临绝槛，乃见西江流。
吴岫分烟景，楚甸散林丘。
方悟关塞眇，重轸故园愁。
闻钟戒归骑，憩涧惜良游。
地疎泉谷狭，春深草木稠。
兹焉赏未极，清景期杪秋。','',''),('quantangshi-09349','与卢陟同游永定寺北池僧斋','韋應物','quantangshi','','卷10','密竹行已远，子归啼更深。
绿池芳草气，闲斋春树阴。
晴蝶飘兰迳，游蜂遶花心。
不遇君携手，谁复此幽寻。','',''),('quantangshi-09350','游溪','韋應物','quantangshi','','卷10','野水烟鹤唳，楚天云雨空。
翫舟清景晚，垂钓绿蒲中。
落花飘旅衣，归流澹清风。
缘源不可极，远树但青葱。','',''),('quantangshi-09351','游开元精舍','韋應物','quantangshi','','卷10','夏衣始轻体，游步爱僧居。
果园新雨后，香台照日初。
绿阴生昼静，孤花表春余。
符竹方为累，形迹一来疎。','',''),('quantangshi-09352','襄武馆游眺','韋應物','quantangshi','','卷10','州民知礼让，讼简得遨游。
高亭凭古地，山川当暮秋。
是时秔稻熟，西望尽田畴。
仰恩慙政拙，念劳喜岁收。
澹泊风景晏，缭绕云树幽。
节往情恻恻，天高思悠悠。
嘉宾幸云集，芳罇始淹留。
还希习池赏，聊以驻鸣驺。','',''),('quantangshi-09353','秋景诣琅瑘精舍','韋應物','quantangshi','','卷10','屡访尘外迹，未穷幽赏情。
高秋天景远，始见山水清。
上陟岩殿憩，暮看云壑平。
苍茫寒色起，迢递晚钟鸣。
意有清夜恋，身为符守婴。
悟言缁衣子，萧洒中林行。','',''),('quantangshi-09354','同韩郎中闲庭南望秋景','韋應物','quantangshi','','卷10','朝下抱余素，地高心本闲。
如何趋府客，罢秩见秋山。
疎树共寒意，游禽同暮还。
因君悟清景，西望一开颜。','',''),('quantangshi-09355','慈恩精舍南池作','韋應物','quantangshi','','卷10','清境岂云远，炎氛忽如遗。
重门布绿阴，菡萏满广池。
石发散清浅，林光动涟漪。
缘崖摘紫房，扣槛集灵龟。
浥浥余露气，馥馥幽襟披。
积喧忻物旷，耽玩觉景驰。
明晨复趋府，幽赏当反思。','',''),('quantangshi-09356','雨夜宿清都观','韋應物','quantangshi','','卷10','灵飙动阊阖，微雨洒瑶林。
复此新秋夜，高阁正沈沈。
旷岁恨殊迹，兹夕一披襟。
洞户含凉气，网轩构层阴。
况自展良友，芳罇遂盈斟。
适悟委前妄，清言怡道心。
岂恋腰间绶，如彼笼中禽。','',''),('quantangshi-09357','善福精舍秋夜迟诸君','韋應物','quantangshi','','卷10','广庭独闲步，夜色方湛然。
丹阁已排云，皓月更高悬。
繁露降秋节，苍林郁芊芊。
仰观天气凉，高咏古人篇。
抚己亮无庸，结交赖羣贤。
属予翘思时，方子中夜眠。
相去隔城阙，佳期屡徂迁。
如何日夕待，见月三四圆。','',''),('quantangshi-09358','东郊','韋應物','quantangshi','','卷10','吏舍局终年，出郊旷清曙。
杨柳散和风，青山澹吾虑。
依丛适自憩，缘涧还复去。
微雨霭芳原，春鸠鸣何处？
乐幽心屡止，遵事迹犹遽。
终罢斯结庐，慕陶真可庶。','',''),('quantangshi-09359','秋郊作','韋應物','quantangshi','','卷10','清露澄境远，旭日照林初。
一望秋山净，萧条形迹疎。
登原忻时稼，采菊行故墟。
方愿沮溺耦，淡泊守田庐。','',''),('quantangshi-09360','行宽禅师院','韋應物','quantangshi','','卷10','北望极长廊，斜扉映藂竹。
亭午一来寻，院幽僧亦独。
唯闻山鸟啼，爱此林下宿。','',''),('quantangshi-09361','神静师院','韋應物','quantangshi','','卷10','青苔幽巷徧，新林露气微。
经声在深竹，高斋独掩扉。
憩树爱岚岭，听禽悦朝晖。
方耽静中趣，自与尘事违。','',''),('quantangshi-09362','精舍纳凉','韋應物','quantangshi','','卷10','山景寂已晦，野寺变苍苍。
夕风吹高殿，露叶散林光。
清钟始戒夜，幽禽尚归翔。
谁复掩扉卧，不咏南轩凉。','',''),('quantangshi-09363','蓝岭精舍','韋應物','quantangshi','','卷10','石壁精舍高，排云聊直上。
佳游惬始愿，忘险得前赏。
崖倾景方晦，谷转川如掌。
绿林含萧条，飞阁起弘敞。
道人上方至，清夜还独往。
日落羣山阴，天秋百泉响。
所嗟累已成，安得长偃仰。','',''),('quantangshi-09364','道晏寺主院','韋應物','quantangshi','','卷10','北邻有幽竹，潜筠穿我庐。
往来地已密，心乐道者居。
残花廻往节，轻条荫夏初。
闻钟北牕起，啸傲永日余。','',''),('quantangshi-09365','义演法师西斋','韋應物','quantangshi','','卷10','结茅临绝岸，隔水闻清磬。
山水旷萧条，登临散情性。
稍指缘原骑，还寻汲涧迳。
长啸倚亭树，怅然川光暝。','',''),('quantangshi-09366','澄秀上座院','韋應物','quantangshi','','卷10','缭绕西南隅，鸟声转幽静。
秀公今不在，独礼高僧影。
林下器未收，何人适煮茗。','',''),('quantangshi-09367','至西峰兰若受田妇馈','韋應物','quantangshi','','卷10','攀崖复缘涧，遂造幽人居。
鸟鸣泉谷暖，土起萌甲舒。
聊登石楼憩，下翫潭中鱼。
田妇有嘉献，泼撒新岁余。
常怪投钱饮，事与贤达疎。
今我何为答，鳏寡欲焉如。','',''),('quantangshi-09368','昙智禅师院','韋應物','quantangshi','','卷10','高年不复出，门径众草生。
时夏方新雨，果药发余荣。
疎澹下林景，流暮幽禽情。
身名两俱遣，独此野寺行。','',''),('quantangshi-09369','起度律师同居东斋院','韋應物','quantangshi','','卷10','释子喜相偶，幽林俱避喧。
安居同僧夏，清夜讽道言。
对阁景恒晏，步庭阴始繁。
逍遥无一事，松风入南轩。','',''),('quantangshi-09370','游琅瑘山寺','韋應物','quantangshi','','卷10','受命恤人隐，兹游久未遑。
鸣驺响幽涧，前旌耀崇冈。
青冥台砌寒，绿褥草木香。
填壑跻花界，叠石构云房。
经制随岩转，缭绕岂定方。
新泉泄阴壁，高萝荫绿塘。
攀林一栖止，饮水得清凉。
物累诚可遣，疲甿终未忘。
还归坐郡阁，但见山苍苍。','',''),('quantangshi-09371','同越琅瑘山','韋應物','quantangshi','','卷10','石门有雪无形迹，松壑凝烟满众香。
余食施庭寒鸟下，破衣挂树老僧亡。','',''),('quantangshi-09372','诣西山深师','韋應物','quantangshi','','卷10','曹溪旧弟子，何缘住此山。
世有征战事，心将流水闲。
埽林驱虎出，宴坐一林间。
藩守宁为重，拥骑造云关。','',''),('quantangshi-09373','寻简寂观瀑布','韋應物','quantangshi','','卷10','蹑石欹危过急涧，攀崖迢递弄悬泉。
犹将虎竹为身累，欲付归人绝世缘。','',''),('quantangshi-09374','简寂观西涧瀑布下作','韋應物','quantangshi','','卷10','淙流绝壁散，虚烟翠涧深。
丛际松风起，飘来洒尘襟。
窥萝翫猿鸟，解组傲云林。
茶果邀真侣，觞酌洽同心。
旷岁怀兹赏，行春始重寻。
聊将横吹笛，一写山水音。','',''),('quantangshi-09375','游南斋','韋應物','quantangshi','','卷10','池上鸣佳禽，僧斋日幽寂。
高林晚露清，红药无人摘。
春水不生烟，荒冈筠翳石。
不应朝夕游，良为蹉跎客。','',''),('quantangshi-09376','南园','韋應物','quantangshi','','卷10','清露夏天晓，荒园野气通。
水禽遥泛雪，池莲迥披红。
幽林讵知暑，环舟似不穷。
顿洒尘喧意，长啸满襟风。','',''),('quantangshi-09377','西亭','韋應物','quantangshi','','卷10','亭宇丽朝景，帘牖散暄风。
小山初构石，珍树正然红。
弱藤已扶树，幽兰欲成丛。
芳心幸如此，佳人时不同。','',''),('quantangshi-09378','夏景园庐','韋應物','quantangshi','','卷10','羣木昼阴静，北牕凉气多。
闲居逾时节，夏云已嵯峨。
搴叶爱繁绿，缘涧弄惊波。
岂为论夙志，对此青山阿。','',''),('quantangshi-09379','夏至避暑北池','韋應物','quantangshi','','卷10','昼晷已云极，宵漏自此长。
未及施政教，所忧变炎凉。
公门日多暇，是月农稍忙。
高居念田里，苦热安可当。
亭午息羣物，独游爱方塘。
门闭阴寂寂，城高树苍苍。
绿筠尚含粉，圆荷始散芳。
于焉洒烦抱，可以对华觞。','',''),('quantangshi-09380','题从侄成绪西林精舍书斋','韋應物','quantangshi','','卷10','栖身齿多暮，息心君独少。
慕谢始精文，依僧欲观妙。
冽泉前堦注，清池北窗照。
果药杂芬敷，松筠疎蒨峭。
屡跻幽人境，每肆芳辰眺。
采栗玄猿窟，撷芝丹林峤。
紵衣岂寒御，蔬食非饥疗。
虽甘巷北单，岂塞青紫耀。
郡有优贤榻，朝编贡士诏。
欲同朱轮载，勿惮移文诮。','',''),('quantangshi-09381','题郑弘宪侍御遗爱草堂','韋應物','quantangshi','','卷10','居士近依僧，青山结茅屋。
疎松映岚晚，春池含苔绿。
繁华冒阳岭，新禽响幽谷。
长啸攀乔林，慕兹高世躅。','',''),('quantangshi-09382','同元锡题琅瑘寺','韋應物','quantangshi','','卷10','适从郡邑喧，又兹三伏热。
山中清景多，石罅寒泉洁。
花香天界事，松竹人间别。
殿分岚岭明，磴临悬壑绝。
昏旭穷陟降，幽显尽披阅。
嵚骇风雨区，寒知龙蛇穴。
情虚澹泊生，境寂尘妄灭。
经世岂非道，无为厌车辙。','',''),('quantangshi-09383','题郑拾遗草堂','韋應物','quantangshi','','卷10','借地结茅栋，横竹挂朝衣。
秋园雨中绿，幽居尘事违。
阴井夕虫乱，高林霜果稀。
子有白云意，构此想岩扉。','',''),('quantangshi-09384','咏玉','韋應物','quantangshi','','卷10','干坤有精物，至宝无文章。
雕琢为世器，真性一朝伤。','',''),('quantangshi-09385','咏露珠','韋應物','quantangshi','','卷10','秋荷一滴露，清夜坠玄天。
将来玉盘上，不定始知圆。','',''),('quantangshi-09386','咏水精','韋應物','quantangshi','','卷10','映物随颜色，含空无表里。
持来向明月，的皪愁成水。','',''),('quantangshi-09387','咏珊瑚','韋應物','quantangshi','','卷10','绛树无花叶，非石亦非琼。
世人何处得，蓬莱石上生。','',''),('quantangshi-09388','咏瑠璃','韋應物','quantangshi','','卷10','有色同寒冰，无物隔纤尘。
象筵看不见，堪将对玉人。','',''),('quantangshi-09389','咏琥珀','韋應物','quantangshi','','卷10','曾为老茯神，本是寒松液。
蚊蚋落其中，千年犹可觌。','',''),('quantangshi-09390','咏晓','韋應物','quantangshi','','卷10','军中始吹角，城上河初落。
深沈犹隐帷，晃朗先分阁。','',''),('quantangshi-09391','咏夜','韋應物','quantangshi','','卷10','明从何处去，暗从何处来。
但觉年年老，半是此中催。','',''),('quantangshi-09392','咏声','韋應物','quantangshi','','卷10','万物自生听，太空恒寂寥。
还从静中起，却向静中消。','',''),('quantangshi-09393','任洛阳丞请告一首','韋應物','quantangshi','','卷10','方凿不受圆，直木不为轮。
揆材各有用，反性生苦辛。
折腰非吾事，饮水非吾贫。
休告卧空馆，养病绝嚣尘。
游鱼自成族，野鸟亦有羣。
家园杜陵下，千岁心氛氲。
天晴嵩山高，雪后河洛春。
乔木犹未芳，百草日已新。
着书复何为，当去东臯耘。','',''),('quantangshi-09394','县斋','韋應物','quantangshi','','卷10','仲春时景好，草木渐舒荣。
公门且无事，微雨园林清。
决决水泉动，忻忻众鸟鸣。
闲斋始延瞩，东作兴庶甿。
既事翫文墨，抱冲披道经。
于焉日淡泊，徒使芳尊盈。','',''),('quantangshi-09395','晚出府舍与独孤兵曹令狐士曹南寻朱雀街归里第','韋應物','quantangshi','','卷10','分曹幸同简，联骑方惬素。
还从广陌归，不觉青山暮。
翻翻鸟未没，杳杳钟犹度。
寻草远无人，望山多枉路。
聊参世士迹，尝得静者顾。
出入虽见牵，忘身缘所晤。','',''),('quantangshi-09396','休暇东斋','韋應物','quantangshi','','卷10','由来束带士，请谒无朝暮。
公暇及私身，何能独闲步。
摘叶爱芳在，扪竹怜粉汚。
岸帻偃东斋，夏天清晓露。
怀仙阅真诰，贻友题幽素。
荣达颇知疎，恬然自成度。
绿苔日已满，幽寂谁来顾。','',''),('quantangshi-09397','夜直省中','韋應物','quantangshi','','卷10','河汉有秋意，南宫生早凉。
玉漏殊杳杳，云阙更苍苍。
华灯发新焰，轻烟浮夕香。
顾迹知为忝，束带愧周行。','',''),('quantangshi-09398','郡内闲居','韋應物','quantangshi','','卷10','栖息绝尘侣，孱钝得自怡。
腰悬竹使符，心与庐山缁。
永日一酣寝，起坐兀无思。
长廊独看雨，众药发幽姿。
今夕已云罢，明晨复如斯。
何事能为累，宠辱岂要辞。','',''),('quantangshi-09399','燕居即事','韋應物','quantangshi','','卷10','萧条竹林院，风雨丛兰折。
幽鸟林上啼，青苔人迹绝。
燕居日已永，夏木纷成结。
几阁积羣书，时来北窗阅。','',''),('quantangshi-09400','幽居','韋應物','quantangshi','','卷10','贵贱虽异等，出门皆有营。
独无外物牵，遂此幽居情。
微雨夜来过，不知春草生。
青山忽已曙，鸟雀绕舍鸣。
时与道人偶，或随樵者行。
自当安蹇劣，谁谓薄世荣。','',''),('quantangshi-09401','野居书情','韋應物','quantangshi','','卷10','世事日可见，身名良蹉跎。
尚瞻白云岭，聊作负薪歌。','',''),('quantangshi-09402','郊居言志','韋應物','quantangshi','','卷10','负暄衡门下，望云归远山。
但要尊中物，余事岂相关。
交无是非责，且得任疎顽。
日夕临清涧，逍遥思虑闲。
出去唯空屋，弊箦委窗间。
何异林栖鸟，恋此复来还。
世荣斯独已，颓志亦何攀。
唯当岁丰熟，闾里一欢颜。','',''),('quantangshi-09403','夏景端居即事','韋應物','quantangshi','','卷10','北斋有凉气，嘉树对层城。
重门永日掩，清池夏云生。
遇此庭讼简，始闻蝉初鸣。
逾怀故园怆，默默以缄情。','',''),('quantangshi-09404','始至郡','韋應物','quantangshi','','卷10','湓城古雄郡，横江千里驰。
高树上迢递，峻堞绕欹危。
井邑烟火晚，郊原草树滋。
洪流荡北址，崇岭郁南圻。
斯民本乐生，逃逝竟何为。
旱岁属荒歉，旧逋积如坻。
到郡方逾月，终朝理乱丝。
宾朋未及宴，简牍已云疲。
昔贤播高风，得守愧无施。
岂待干戈戢，且愿抚惸嫠。','',''),('quantangshi-09405','郡中西斋','韋應物','quantangshi','','卷10','似与尘境绝，萧条斋舍秋。
寒花独经雨，山禽时到州。
清觞养真气，玉书示道流。
岂将符守恋，幸已栖心幽。','',''),('quantangshi-09406','新理西斋','韋應物','quantangshi','','卷10','方将甿讼理，久翳西斋居。
草木无行次，闲暇一芟除。
春阳土脉起，膏泽发生初。
养条刊朽枿，护药锄秽芜。
稍稍觉林耸，历历忻竹疎。
始见庭宇旷，顿令烦抱舒。
兹焉即可爱，何必是吾庐。','',''),('quantangshi-09407','晓坐西斋','韋應物','quantangshi','','卷10','冬冬城鼓动，稍稍林鵶去。
柳意不胜春，岩光已知曙。
寝斋有单祶，灵药为朝茹。
盥漱忻景清，焚香澄神虑。
公门自常事，道心宁易处。','',''),('quantangshi-09408','郡斋卧疾绝句','韋應物','quantangshi','','卷10','香炉宿火灭，兰灯宵影微。
秋斋独卧病，谁与覆寒衣。','',''),('quantangshi-09409','寓居永定精舍','韋應物','quantangshi','','卷10','政拙忻罢守，闲居初理生。
家贫何由往，梦想在京城。
野寺霜露月，农兴羁旅情。
聊租二顷田，方课子弟耕。
眼暗文字废，身闲道心精。
即与人羣远，岂谓是非婴。','',''),('quantangshi-09410','永定寺喜辟强夜至','韋應物','quantangshi','','卷10','子有新岁庆，独此苦寒归。
夜叩竹林寺，山行雪满衣。
深炉正燃火，空斋共掩扉。
还将一尊对，无言百事违。','',''),('quantangshi-09411','野居','韋應物','quantangshi','','卷10','结发屡辞秩，立身本疎慢。
今得罢守归，幸无世欲患。
栖止且偏僻，嬉游无早晏。
逐兔上坡冈，捕鱼缘赤涧。
高歌意气在，贳酒贫居惯。
时启北窗扉，岂将文墨间。','',''),('quantangshi-09412','同襃子秋斋独宿','韋應物','quantangshi','','卷10','山月皎如烛，风霜时动竹。
夜半鸟惊栖，窗间人独宿。','',''),('quantangshi-09413','饵黄精','韋應物','quantangshi','','卷10','灵药出西山，服食采其根。
九蒸换凡骨，经着上世言。
候火起中夜，馨香满南轩。
斋居感众灵，药术启妙门。
自怀物外心，岂与俗士论。
终期脱印绶，永与天壤存。','',''),('quantangshi-09414','昭国里第听元老师弹琴','韋應物','quantangshi','','卷10','竹林高宇霜露清，朱丝玉徽多故情。
暗识啼乌与别鹤，秪缘中有断肠声。','',''),('quantangshi-09415','野次听元昌奏横吹','韋應物','quantangshi','','卷10','立马莲塘吹横笛，微风动柳生水波。
北人听罢泪将落，南朝曲中怨更多。','',''),('quantangshi-09416','楼中阅清管','韋應物','quantangshi','','卷10','山阳遗韵在，林端横吹惊。
响迥凭高阁，曲怨绕秋城。
淅沥危叶振，萧瑟凉气生。
始遇兹管赏，已怀故园情。','',''),('quantangshi-09417','寒食','韋應物','quantangshi','','卷10','晴明寒食好，春园百卉开。
彩绳拂花去，轻球度阁来。
长歌送落日，缓吹逐残杯。
非关无烛罢，良为羁思催。','',''),('quantangshi-09418','七夕','韋應物','quantangshi','','卷10','人世拘形迹，别去间山川。
岂意灵仙偶，相望亦弥年。
夕衣清露湿，晨驾秋风前。
临欢定不住，当为何所牵。','',''),('quantangshi-09419','九日','韋應物','quantangshi','','卷10','今朝把酒复惆怅，忆在杜陵田舍时。
明年九日知何处，世难还家未有期。','',''),('quantangshi-09420','秋夜','韋應物','quantangshi','','卷10','暗窗凉叶动，秋天寝席单。
忧人半夜起，明月在林端。
一与清景遇，每忆平生欢。
如何方恻怆，披衣露更寒。','',''),('quantangshi-09421','秋夜一绝','韋應物','quantangshi','','卷10','高阁渐凝露，凉叶稍飘闱。
忆在南宫直，夜长钟漏稀。','',''),('quantangshi-09422','滁城对雪','韋應物','quantangshi','','卷10','晨起满闱雪，忆朝阊阖时。
玉座分曙早，金炉上烟迟。
飘散云台下，凌乱桂树姿。
厕迹鸳鹭末，蹈舞丰年期。
今朝覆山郡，寂寥复何为。','',''),('quantangshi-09423','雪中','韋應物','quantangshi','','卷10','空堂岁已晏，密室独安眠。
厌筱夜偏积，覆阁晓逾妍。
连山暗古郡，惊风散一川。
此时骑马出，忽省京华年。','',''),('quantangshi-09424','咏春雪','韋應物','quantangshi','','卷10','裴回轻雪意，似惜艳阳时。
不悟风花冷，翻令梅柳迟。','',''),('quantangshi-09425','对春雪','韋應物','quantangshi','','卷10','萧屑杉松声，寂寥寒夜虑。
州贫人吏稀，雪满山城曙。
春塘看幽谷，栖禽愁未去。
开闱正乱流，宁辨花枝处。','',''),('quantangshi-09426','对残灯','韋應物','quantangshi','','卷10','独照碧窗久，欲随寒烬灭。
幽人将遽眠，解带翻成结。','',''),('quantangshi-09427','对芳尊','韋應物','quantangshi','','卷10','对芳尊，醉来百事何足论。
遥见青山始一醒，欲着接[䍦]还复昏。','',''),('quantangshi-09428','夜对流萤作','韋應物','quantangshi','','卷10','月暗竹亭幽，萤光拂席流。
还思故园夜，更度一年秋。
自惬观书兴，何慙秉烛游。
府中徒冉冉，明发好归休。','',''),('quantangshi-09429','对新篁','韋應物','quantangshi','','卷10','新绿苞初解，嫩气笋犹香。
含露渐舒叶，抽丛稍自长。
清晨止亭下，独爱此幽篁。','',''),('quantangshi-09430','夏花明','韋應物','quantangshi','','卷10','夏条绿已密，朱蕚缀明鲜。
炎炎日正午，灼灼火俱燃。
翻风适自乱，照水复成妍。
归视窗间字，荧煌满眼前。','',''),('quantangshi-09431','对萱草','韋應物','quantangshi','','卷10','何人树萱草，对此郡斋幽。
本是忘忧物，今夕重生忧。
丛疎露始滴，芳余蝶尚留。
还思杜陵圃，离披风雨秋。','',''),('quantangshi-09432','见紫荆花','韋應物','quantangshi','','卷10','杂英纷已积，含芳独暮春。
还如故园树，忽忆故园人。','',''),('quantangshi-09433','翫萤火','韋應物','quantangshi','','卷10','时节变衰草，物色近新秋。
度月影才敛，绕竹光复流。','',''),('quantangshi-09434','对杂花','韋應物','quantangshi','','卷10','朝红争景新，夕素含露翻。
妍姿如有意，流芳复满园。
单栖守远郡，永日掩重门。
不与花为偶，终遣与谁言。','',''),('quantangshi-09435','种药','韋應物','quantangshi','','卷10','好读神农书，多识药草名。
持缣购山客，移莳罗众英。
不改幽涧色，宛如此地生。
汲井既蒙泽，插楥亦扶倾。
阴颖夕房敛，阳条夏花明。
悦翫从兹始，日夕绕庭行。
州民自寡讼，养闲非政成。','',''),('quantangshi-09436','西涧种柳','韋應物','quantangshi','','卷10','宰邑乖所愿，僶俛愧昔人。
聊将休暇日，种柳西涧滨。
置锸息微倦，临流睇归云。
封壤自人力，生条在阳春。
成阴岂自取，为茂属佗辰。
延咏留佳赏，山水变夕曛。','',''),('quantangshi-09437','种瓜','韋應物','quantangshi','','卷10','率性方卤莽，理生尤自疎。
今年学种瓜，园圃多荒芜。
众草同雨露，新苗独翳如。
直以春窘迫，过时不得锄。
田家笑枉费，日夕转空虚。
信非吾侪事，且读古人书。','',''),('quantangshi-09438','喜园中茶生','韋應物','quantangshi','','卷10','洁性不可污，为饮涤尘烦。
此物信灵味，本自出山原。
聊因理郡余，率尔植荒园。
喜随众草长，得与幽人言。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-09439','移海榴','韋應物','quantangshi','','卷10','叶有苦寒色，山中霜霰多。
虽此蒙阳景，移根意如何。','',''),('quantangshi-09440','郡斋移杉','韋應物','quantangshi','','卷10','[擢]干方数尺，幽姿已苍然。
结根西山寺，来植郡斋前。
新含野露气，稍静高窗眠。
虽为赏心遇，岂有岩中缘。','',''),('quantangshi-09441','花径','韋應物','quantangshi','','卷10','山花夹径幽，古甃生苔涩。
胡牀理事余，玉琴承露湿。
朝与诗人赏，夜携禅客入。
自是尘外踪，无令吏趋急。','',''),('quantangshi-09442','慈恩寺南池秋荷咏','韋應物','quantangshi','','卷10','对殿含凉气，裁规覆清沼。
衰红受露多，余馥依人少。
萧萧远尘迹，飒飒凌秋晓。
节谢客来稀，回塘方独遶。','',''),('quantangshi-09443','题桐叶','韋應物','quantangshi','','卷10','参差剪绿绮，潇洒覆琼柯。
忆在沣东寺，偏书此叶多。','',''),('quantangshi-09444','题石桥','韋應物','quantangshi','','卷10','远学临海峤，横此莓苔石。
郡斋三四峰，如有灵仙迹。
方愁暮云滑，始照寒池碧。
自与幽人期，逍遥竟朝夕。','',''),('quantangshi-09445','池上','韋應物','quantangshi','','卷10','郡中卧病久，池上一来赊。
榆柳飘枯叶，风雨倒横查。','',''),('quantangshi-09446','滁州西涧','韋應物','quantangshi','','卷10','独怜幽草涧边生，上有黄鹂深树鸣。
春潮带雨晚来急，野渡无人舟自横。','',''),('quantangshi-09447','西塞山','韋應物','quantangshi','','卷10','势从千里奔，直入江中断。
岚横秋塞雄，地束惊流满。','',''),('quantangshi-09448','山耕叟','韋應物','quantangshi','','卷10','萧萧垂白发，默默讵知情。
独放寒林烧，多寻虎迹行。
暮归何处宿？来此空山耕。','',''),('quantangshi-09449','上方僧','韋應物','quantangshi','','卷10','见月出东山，上方高处禅。
空林无宿火，独夜汲寒泉。
不下蓝溪寺，今年三十年。','',''),('quantangshi-09450','烟际钟','韋應物','quantangshi','','卷10','隐隐起何处，迢迢送落晖。
苍茫随思远，萧散逐烟微。
秋野寂云晦，望山僧独归。','',''),('quantangshi-09451','始闻夏蝉','韋應物','quantangshi','','卷10','徂夏暑未晏，蝉鸣景已曛。
一听知何处，高树但侵云。
响悲遇衰齿，节谢属离羣。
还忆郊园日，独向涧中闻。','',''),('quantangshi-09452','射雉','韋應物','quantangshi','','卷10','走马上东冈，朝日照野田。
野田双雉起，翻射斗回鞭。
虽无百发中，聊取一笑妍。
羽分绣臆碎，头弛锦鞘悬。
方将悦羁旅，非关学少年。
弢弓一长啸，忆在灞城阡。','',''),('quantangshi-09453','夜闻独鸟啼','韋應物','quantangshi','','卷10','失侣度山觅，投林舍北啼。
今将独夜意，偏知对影栖。','',''),('quantangshi-09454','述园鹿','韋應物','quantangshi','','卷10','野性本难畜，翫习亦逾年。
麑班始力直，麚角已苍然。
仰首嚼园柳，俯身饮清泉。
见人若闲暇，蹶起忽低骞。
兹兽有高貌，凡类宁比肩。
不得游山泽，局促诚可怜。','',''),('quantangshi-09455','闻雁','韋應物','quantangshi','','卷10','故园眇何处，归思方悠哉。
淮南秋雨夜，高斋闻雁来。','',''),('quantangshi-09456','子规啼','韋應物','quantangshi','','卷10','高林滴露夏夜清，南山子规啼一声。
邻家孀妇抱儿泣，我独展转何时明。','',''),('quantangshi-09457','始建射侯','韋應物','quantangshi','','卷10','男子本悬弧，有志在四方。
虎竹忝明命，熊侯始张皇。
宾登时事毕，诸将备戎装。
星飞的屡破，鼓噪武更扬。
曾习邹鲁学，亦陪鸳鹭翔。
一朝愿投笔，世难激中肠。','',''),('quantangshi-09458','仙人祠','韋應物','quantangshi','','卷10','苍岑古仙子，清庙閟华容。
千载去寥廓，白云遗旧踪。
归来灞陵上，犹见最高峰。','',''),('quantangshi-09459','鹧鸪啼','韋應物','quantangshi','','卷10','可怜鹧鸪飞，飞向树南枝。
南枝日照暖，北枝霜露滋。
露滋不堪栖，使我夜常啼。
愿逢云中鹤，衔我向寥廓。
愿作城上乌，一年生九雏。
何不旧巢住，枝弱不得去。
何意道苦辛，客子常畏人。','',''),('quantangshi-09460','长安道','韋應物','quantangshi','','卷10','汉家宫殿含云烟，两宫十里相连延。
晨霞出没弄丹阙，春雨依微自甘泉。
春雨依微春尚早，长安贵游爱芳草。
宝马横来下建章，香车却转避驰道。
贵游谁最贵，卫霍世难比。
何能蒙主恩，幸遇边尘起。
归来甲第拱皇居，朱门峨峨临九衢。
中有流苏合欢之宝帐，一百二十凤凰罗列含明珠。
下有锦铺翠被之粲烂，博山吐香五云散。
丽人绮阁情飘颻，头上鸳钗双翠翘。
低鬟曳袖回春雪，聚黛一声愁碧霄。
山珍海错弃藩篱，烹犊炮羔如折葵。
既请列侯封部曲，还将金印授庐儿。
欢荣若此何所苦，但苦白日西南驰。','',''),('quantangshi-09461','行路难','韋應物','quantangshi','','卷10','荆山之白玉兮，良工雕琢双环连，月蚀中央镜心穿。
故人赠妾初相结，恩在环中寻不绝。
人情厚薄苦须臾，昔似连环今似玦。
连环可碎不可离，如何物在人自移。
上客勿遽欢，听妾歌路难。
旁人见环环可怜，不知中有长恨端。','',''),('quantangshi-09462','横塘行','韋應物','quantangshi','','卷10','妾家住横塘，夫壻郗家郎。
玉盘的历双白鱼，宝簟玲珑透象牀。
象牀可寝鱼可食，不知郎意何南北。
岸上种莲岂得生，池中种槿岂得成。
丈夫一去花落树，妾独夜长心未平。','',''),('quantangshi-09463','贵游行','韋應物','quantangshi','','卷10','汉帝外家子，恩泽少封侯。
垂杨拂白马，晓日上青楼。
上有颜如玉，高情世无俦。
轻裾含碧烟，窈窕似云浮。
良时无还景，促节为我讴。
忽闻艳阳曲，四坐亦已柔。
宾友仰称叹，一生何所求。
平明击钟食，入夜乐未休。
风雨愆岁候，兵戎横九州。
焉知坐上客，草草心所忧。','',''),('quantangshi-09464','酒肆行','韋應物','quantangshi','','卷10','豪家沽酒长安陌，一旦起楼高百尺。
碧疏玲珑含春风，银题彩帜邀上客。
回瞻丹凤阙，直视乐游苑。
四方称赏名已高，五陵车马无近远。
晴景悠扬三月天，桃花飘俎柳垂筵。
繁丝急管一时合，他垆邻肆何寂然。
主人无厌且专利，百斛须臾一壶费。
初醲后薄为大偷，饮者知名不知味。
深门潜酝客来稀，终岁醇醲味不移。
长安酒徒空扰扰，路傍过去那得知。','',''),('quantangshi-09465','相逢行','韋應物','quantangshi','','卷10','二十登汉朝，英声迈今古。
适从东方来，又欲谒明主。
犹酣新丰酒，尚带灞陵雨。
邂逅两相逢，别来问寒暑。
宁知白日晚，暂向花间语。
忽闻长乐钟，走马东西去。','',''),('quantangshi-09466','乌引雏','韋應物','quantangshi','','卷10','日出照东城，春乌鵶鵶雏和鸣。
雏和鸣，羽犹短，巢在深林春正寒，引飞欲集东城暖。
羣雏䙰褷睥睨高，举翅不及坠蓬蒿。
雄雌来去飞又引，音声上下惧鹰隼。
引雏乌，尔心急将何如，何得比日搜索雀卵噉尔雏。','',''),('quantangshi-09467','鸢夺巢','韋應物','quantangshi','','卷10','野鹊野鹊巢林梢，鸱鸢恃力夺鹊巢。
吞鹊之肝啄鹊脑，窃食偷居还自保。
凤凰五色百鸟尊，知鸢为害何不言？
霜鹯野鹞得残肉，同啄膻腥不肯逐。
可怜百鸟纷纵横，虽有深林何处宿。','',''),('quantangshi-09468','燕衔泥','韋應物','quantangshi','','卷10','衔泥燕，声喽喽。
尾涎涎，秋去何所归。
春来复相见，岂不解决绝高飞碧云里。
何为地上衔泥滓，衔泥虽贱意有营。
杏梁朝日巢欲成，不见百鸟畏人林野宿。
翻遭网罗俎其肉，未若衔泥入华屋。
燕衔泥，百鸟之智莫与齐。','',''),('quantangshi-09469','鼙鼓行','韋應物','quantangshi','','卷10','淮海生云暮惨澹，广陵城头颦鼓暗。
寒声坎坎风动边，忽似孤城万里绝，四望无人烟。
又如虏骑截辽水，胡马不食仰朔天。
座中亦有燕赵士，闻颦不语客心死。
何况鳏孤火绝无晨炊，独妇夜泣官有期。','',''),('quantangshi-09470','古剑行','韋應物','quantangshi','','卷10','千年土中两刃铁，土蚀不入金星灭。
沈沈青脊鳞甲满，蛟龙无足蛇尾断。
忽欲飞动中有灵，豪士得之敌国宝。
仇家举意半夜鸣，小儿女子不可近。
龙蛇变化此中隐，夏云奔走雷阗阗，恐成霹雳飞上天。','',''),('quantangshi-09471','金谷园歌','韋應物','quantangshi','','卷10','石氏灭，金谷园中水流绝。
当时豪右争骄侈，锦为步障四十里。
东风吹花雪满川，紫气凝阁朝景妍。
洛阳陌上人回首，丝竹飘颻入青天。
晋武平吴恣欢燕，余风靡靡朝廷变。
嗣世衰微谁肯忧，二十四友日日空追游。
追游讵可足，共惜年华促。
祸端一发埋恨长，百草无情春自绿。','',''),('quantangshi-09472','温泉行','韋應物','quantangshi','','卷10','出身天宝今年几，顽钝如锤命如纸。
作官不了却来归，还是杜陵一男子。
北风惨惨投温泉，忽忆先皇游幸年。
身骑廐马引天仗，直入华清列御前。
玉林瑶雪满寒山，上升玄阁游绛烟。
平明羽卫朝万国，车马合沓溢四鄽。
蒙恩每浴华池水，扈猎不蹂渭北田。
朝廷无事共欢燕，美人丝管从九天。
一朝铸鼎降龙驭，小臣髯绝不得去。
今来萧瑟万井空，唯见苍山起烟雾。
可怜蹭蹬失风波，仰天大呌无奈何。
弊裘羸马冻欲死，赖遇主人杯酒多。','',''),('quantangshi-09473','学仙二首 一','韋應物','quantangshi','','卷10','昔有道士求神仙，灵真下试心确然。
千[钧]巨石一发悬，卧之石下十三年。
存道忘身一试过，名奏玉皇乃升天。
云气冉冉渐不见，留语弟子但精坚。','',''),('quantangshi-09474','学仙二首 二','韋應物','quantangshi','','卷10','石上凿井欲到水，惰心一起中路止。
岂不见古来三人俱弟兄，结茅深山读仙经。
上有青冥倚天之绝壁，下有飕飗万壑之松声。
仙人变化为白鹿，二弟翫之兄诵读。
读多七过可乞言，为子心精得神仙。
可怜二弟仰天泣，一失毫厘千万年。','',''),('quantangshi-09475','广陵行','韋應物','quantangshi','','卷10','雄藩镇楚郊，地势郁岧峣。
双旌拥万戟，中有霍嫖姚。
海云助兵气，宝货益军饶。
严城动寒角，晚骑踏霜桥。
翕习英豪集，振夺士卒骁。
列郡何足数，趋拜等卑寮。
日宴方云罢，人逸马萧萧。
忽如京洛间，游子风尘飘。
归来视宝剑，功名岂一朝。','',''),('quantangshi-09476','萼绿华歌','韋應物','quantangshi','','卷10','有一人兮升紫霞，书名玉牒兮蕚绿华。
仙容矫矫兮杂瑶佩，轻衣重重兮蒙绛纱。
云雨愁思兮望淮海，鼓吹萧条兮驾龙车。
世淫浊兮不可降，胡不来兮玉斧家。','',''),('quantangshi-09477','王母歌','韋應物','quantangshi','','卷10','众仙翼神母，羽盖随云起。
上游玄极杳冥中，下看东海一杯水。
海畔种桃经几时，千年开花千年子。
玉颜眇眇何处寻，世上茫茫人自死。','',''),('quantangshi-09478','马明生遇神女歌','韋應物','quantangshi','','卷10','学仙贵功亦贵精，神女变化感马生。
石壁千寻启双检，中有玉堂铺玉簟。
立之一隅不与言，玉体安隐三日眠。
马生一立心转坚，知其丹白蒙哀怜。
安期先生来起居，请示金铛玉佩天皇书。
神女呵责不合见，仙子谢过手足战。
大瓜玄枣冷如冰，海上摘来朝霞凝。
赐仙复坐对食讫，颔之使去随烟升。
乃言马生合不死，少姑教勅令付尔。
安期再拜将生出，一授素书天地毕。','',''),('quantangshi-09479','石鼓歌','韋應物','quantangshi','','卷10','周宣大猎兮岐之阳，刻石表功兮炜煌煌。
石如鼓形数止十，风雨缺讹苔藓涩。
今人濡纸脱其文，既击既埽白黑分。
忽开满卷不可识，惊潜动蛰走云云。
喘逶迤，相纠错，乃是宣王之臣史籀作。
一书遗此天地间，精意长存世冥寞。
秦家祖龙还刻石，碣石之罘李斯迹。
世人好古犹共传，持来比此殊悬隔。','',''),('quantangshi-09480','宝观主白鸜鹆歌','韋應物','quantangshi','','卷10','鸜鹆鸜鹆，众皆如漆，尔独如玉。
鸜之鹆之，众皆蓬蒿下。
尔自三山来，三山处子下人间。
绰约不妆冰雪颜，仙鸟随飞来掌上。
来掌上，时拂拭。
人心鸟意自无猜，玉指霜毛本同色。
有时一去凌苍苍，朝游汗漫暮玉堂。
巫峡雨中飞暂湿，杏花林里过来香。
日夕依仁全羽翼，空欲衔环非报德。
岂不及阿母之家青鸟儿，汉宫来往传消息。','',''),('quantangshi-09481','弹棊歌','韋應物','quantangshi','','卷10','圆天方地局，二十四气子。
刘生绝艺难对曹，客为歌其能。
请从中央起，中央转鬬破欲阑。
零落势背谁能弹，此中举一得六七。
旋风忽散霹雳疾，履机乘变安可当。
置之死地翻取强，不见短兵反掌收已尽。
唯有猛士守四方，四方又何难。
横击且缘边，岂如昆明与碣石。
一箭飞中隔远天，神安志惬动十全，满堂惊视谁得然。','',''),('quantangshi-09482','听莺曲','韋應物','quantangshi','','卷10','东方欲曙花冥冥，啼莺相唤亦可听。
乍去乍来时近远，才闻南陌又东城。
忽似上林翻下苑，绵绵蛮蛮如有情。
欲啭不啭意自娇，羌儿弄笛曲未调。
前声后声不相及，秦女学筝指犹涩。
须臾风暖朝日暾，流音变作百鸟喧。
谁家懒妇惊残梦，何处愁人忆故园？
伯劳飞过声局促，戴胜下时桑田绿。
不及流莺日日啼花间，能使万家春意闲。
有时断续听不了，飞去花枝犹袅袅。
还栖碧树锁千门，春漏方残一声晓。','',''),('quantangshi-09483','白沙亭逢吴叟歌','韋應物','quantangshi','','卷10','龙池宫里上皇时，罗衫宝带香风吹。
满朝豪士今已尽，欲话旧游人不知。
白沙亭上逢吴叟，爱客脱衣且沽酒。
问之执戟亦先朝，零落艰难却负樵。
亲观文物蒙雨露，见我昔年侍丹霄。
冬狩春祠无一事，欢游洽宴多颁赐。
尝陪月夕竹宫斋，每返温泉灞陵醉。
星岁再周十二辰，尔来不语今为君。
盛时忽去良可恨，一生坎壈何足云。','',''),('quantangshi-09484','送褚校书归旧山歌','韋應物','quantangshi','','卷10','握珠不返泉，匣玉不归山。
明皇重士亦如此，忽怪褚生何得还。
方称羽猎赋，未拜兰台职。
汉箧亡书已暗传，嵩丘遗简还能识。
朝朝待诏青鏁闱，中有万年之树蓬莱池。
世人仰望栖此地，生独徘徊意何为。
故山可往薇可采，一自人间星岁改。
藏书壁中苔半侵，洗药泉中月还在。
春风饮饯灞陵原，莫厌归来朝市喧。
不见东方朔，避世从容金马门。','',''),('quantangshi-09485','五弦行','韋應物','quantangshi','','卷10','美人为我弹五弦，尘埃忽静心悄然。
古刀幽磬初相触，千珠贯断落寒玉。
中曲又不喧，徘徊夜长月当轩。
如伴风流萦艳雪，更逐落花飘御园。
独凤寥寥有时隐，碧霄来下听还近。
燕姬有恨楚客愁，言之不尽声能尽。
末曲感我情，解幽释结和乐生。
壮士有仇未得报，拔剑欲去愤已平。
夜寒酒多愁遽明。','',''),('quantangshi-09486','骊山行','韋應物','quantangshi','','卷10','君不见开元至化垂衣裳，厌坐明堂朝万方。
访道灵山降圣祖，沐浴华池集百祥。
千乘万骑被原野，云霞草木相辉光。
禁仗围山晓霜切，离宫积翠夜漏长。
玉堦寂历朝无事，碧树萎蕤寒更芳。
三清小鸟传仙语，九华真人奉琼浆。
下元昧爽漏恒秩，登山朝礼玄元室。
翠华稍隐天半云，丹阁光明海中日。
羽旗旄节憩瑶台，清丝妙管从空来。
万井九衢皆仰望，彩云白鹤方徘徊。
凭高览古嗟寰宇，造化茫茫思悠哉。
秦川八水长缭绕，汉氏五陵空崔嵬。
乃言圣祖奉丹经，以年为日亿万龄。
苍生咸寿阴阳泰，高谢前王出尘外。
英豪共理天下晏，戎夷讋伏兵无战。
时丰赋敛未告劳，海阔珍奇亦来献。
干戈一起文武乖，欢娱已极人事变。
圣皇弓剑坠幽泉，古木苍山闭宫殿。
缵承鸿业圣明君，威震六合驱妖氛。
太平游幸今可待，汤泉岚岭还氛氲。','',''),('quantangshi-09487','汉武帝杂歌三首 一','韋應物','quantangshi','','卷10','汉武好神仙，黄金作台与天近。
王母摘桃海上还，感之西过聊问讯。
欲来不来夜未央，殿前青鸟先回翔。
绿鬓萦云裾曳雾，双节飘颻下仙步。
白日分明到世间，碧空何处来时路。
玉盘捧桃将献君，踟蹰未去留彩云。
海水桑田几翻覆，中间此桃四五熟。
可怜穆满瑶池燕，正值花开不得荐。
花开子熟安可期，邂逅能当汉武时。
颜如芳华洁如玉，心念我皇多嗜欲。
虽留桃核桃有灵，人间粪土种不生。
由来在道岂在药，徒劳方士海上行。
掩扇一言相谢去，如烟非烟不知处。','',''),('quantangshi-09488','汉武帝杂歌三首 二','韋應物','quantangshi','','卷10','金茎孤峙兮凌紫烟，汉宫美人望杳然。
通天台上月初出，承露盘中珠正圆。
珠可饮，寿可永，武皇南面曙欲分。
从空下来玉杯冷，世间彩翠亦作囊。
八月一日仙人方，仙方称上药。
静者服之常绰约，柏梁沈饮自伤神，犹闻驻颜七十春。
乃知甘醲皆是腐肠物，独有淡泊之水能益人。
千载金盘竟何处，当时铸金恐不固。
蔓草生来春复秋，碧天何言空坠露。','',''),('quantangshi-09489','汉武帝杂歌三首 三','韋應物','quantangshi','','卷10','汉天子，观风自南国。
浮舟大江屹不前，蛟龙索鬬风波黑。
春秋方壮雄武才，弯弧叱浪连山开。
愕然观者千万众，举麾齐呼一矢中。
死蛟浮出不复灵，舳舻千里江水清。
鼓颦余响数日在，天吴深入鱼鼈惊。
左有佽飞落霜翮，右有孤儿贯犀革。
何为临深亲射蛟，示威以夺诸侯魄。
威可畏，皇可尊，平田校猎书犹陈。
此日从臣何不言，独有威声振千古，君不见后嗣尊为武。','',''),('quantangshi-09490','椶榈蝇拂歌','韋應物','quantangshi','','卷10','椶榈为拂登君席，青蝇掩乱飞四壁。
文如轻罗散如发，马尾氂牛不能絜。
柄出湘江之竹碧玉寒，上有纤罗萦缕寻未绝。
左挥右洒繁暑清，孤松一枝风有声。
丽人纨素可怜色，安能点白还为黑。','',''),('quantangshi-09491','信州录事参军常曾古鼎歌','韋應物','quantangshi','','卷10','三年纠一郡，独饮寒泉井。
江南铸器多铸银，罢官无物唯古鼎。
雕螭刻篆相错盘，地中岁久青苔寒。
左对苍山右流水，云有古来葛仙子。
葛仙埋之何不还，耕者枪然得其间。
持示世人不知宝，劝君炼丹永寿考。','',''),('quantangshi-09492','夏冰歌','韋應物','quantangshi','','卷10','出自玄泉杳杳之深井，汲在朱明赫赫之炎辰。
九天含露未销铄，阊阖初开赐贵人。
碎如坠琼方截璐，粉壁生寒象筵布。
玉壶纨扇亦玲珑，座有丽人色俱素。
咫尺炎凉变四时，出门焦灼君讵知。
肥羊甘醴心闷闷，饮此莹然何所思。
当念阑干凿者苦，腊月深井汗如雨。','',''),('quantangshi-09493','鼋头山神女歌','韋應物','quantangshi','','卷10','鼋头之山，直上洞庭连青天。
苍苍烟树闭古庙，中有蛾眉成水仙。
水府沈沈行路绝，蛟龙出没无时节。
魂同魍魉潜太阴，身与空山长不灭。
东晋永和今几代，云发素颜犹盼睐。
阴深灵气静凝美，的砾龙绡杂琼佩。
山精木魅不敢亲，昏明想像如有人。
蕙兰琼芳积烟露，碧窗松月无冬春。
舟客经过奠椒醑，巫女南音歌激楚。
碧水冥空惟鸟飞，长天何处云随雨。
红渠绿苹芳意多，玉灵荡漾凌清波。
孤峰绝岛俨相向，鬼啸猿啼垂女萝。
皓雪琼枝殊异色，北方绝代徒倾国。
云没烟销不可期，明堂翡翠无人得。
精灵变态状无方，游龙宛转惊鸿翔。
湘妃独立九疑暮，汉女菱歌春日长。
始知仙事无不有，可惜吴宫空白首。','',''),('quantangshi-09494','寇季膺古刀歌','韋應物','quantangshi','','卷10','古刀寒锋青槭槭，少年交结平陵客。
求之时代不可知，千痕万穴如星离。
重叠泥沙更剥落，纵横鳞甲相参差。
古物有灵知所适，貂裘拂之横广席。
阴森白日掩云虹，错落池光动金碧。
知君宝此夸绝代，求之不得心常爱。
厌见今时绕指柔，片锋折刃犹堪佩。
高山成谷苍海填，英豪埋没谁所捐。
吴钩断马不知处，几度烟尘今独全。
夜光投人人不畏，知君独识精灵器。
酬恩结思心自知，死生好恶不相弃。
白虎司秋金气清，高天寥落云峥嵘。
月肃风凄古堂净，精芒切切如有声。
何不跨蓬莱，斩长鲸？
世人所好殊辽阔，千金买铅徒一割。','',''),('quantangshi-09495','凌雾行','韋應物','quantangshi','','卷10','秋城海雾重，职事凌晨出。
浩浩合元天，溶溶迷朗日。
才看含鬓白，稍视霑衣密。
道骑全不分，郊树都如失。
霏微误嘘吸，肤腠生寒栗。
归当饮一杯，庶用蠲斯疾。','',''),('quantangshi-09496','乐燕行','韋應物','quantangshi','','卷10','良辰且燕乐，乐往不再来。
赵瑟正高张，音响清尘埃。
一弹和妙讴，吹去绕瑶台。
艳云凌空散，舞罗起徘徊。
辉辉发众颜，灼灼叹令才。
当喧既无寂，中饮亦停杯。
华灯何遽升，驰景忽西颓。
高节亦云立，安能滞不回。','',''),('quantangshi-09497','采玉行','韋應物','quantangshi','','卷10','官府征白丁，言采蓝溪玉。
绝岭夜无家，深榛雨中宿。
独妇饷粮还，哀哀舍南哭。','',''),('quantangshi-09498','难言','韋應物','quantangshi','','卷10','掬土移山望山尽，投石填海望海满。
持索捕风几时得，将刀斫水几时断。
未若不相知，中心万仞何由款。','',''),('quantangshi-09499','易言','韋應物','quantangshi','','卷10','洪炉炽炭燎一毛，大鼎炊汤沃残雪。
疾影随形不觉至，千钧引缕不知绝。
未若同心言，一言和同解千结。','',''),('quantangshi-09500','三台二首 一','韋應物','quantangshi','','卷10','一年一年老去，明日后日花开。
未报长安平定，万国岂得衔杯。','',''),('quantangshi-09501','三台二首 二','韋應物','quantangshi','','卷10','冰泮寒塘始绿，雨余百草皆生。
朝来门合无事，晚下高斋有情。','',''),('quantangshi-09502','上皇三台','韋應物','quantangshi','','卷10','不寐倦长更，披衣出户行。
月寒秋竹冷，风切夜窗声。','',''),('quantangshi-09503','答畅参军','韋應物','quantangshi','','卷10','秉笔振芳步，少年且吏游。
官闲高兴生，夜直河汉秋。
念与清赏遇，方抱沈疾忧。
嘉言忽见赠，良药同所瘳。
高树起栖鸦，晨钟满皇州。
凄清露华动，旷朗景气浮。
偶宦心非累，处喧道自幽。
空虚为世薄，子独意绸缪。','',''),('quantangshi-09504','南池宴钱子辛赋得科斗','韋應物','quantangshi','','卷10','临池见科斗，美尔乐有余。
不忧网与钩，幸得免为鱼。
且愿充文字，登君尺素书。','',''),('quantangshi-09505','咏徐正字画青蝇','韋應物','quantangshi','','卷10','误点能成物，迷真许一时。
笔端来已久，座上去何迟。
顾白曾无变，听鸡不复疑。
讵劳才子赏，为入国人诗。','',''),('quantangshi-09506','虞获子鹿','韋應物','quantangshi','','卷10','虞获子鹿，畜之城陬。
园有美草，池有清流。
但见蹶蹶，亦闻呦呦。
谁知其思，岩谷云游。','',''),('quantangshi-09507','陪王郎中寻孔征君','韋應物','quantangshi','','卷10','俗吏闲居少，同人会面难。
偶随香署客，来访竹林欢。
暮馆花微落，春城雨暂寒。
瓮间聊共酌，莫使宦情阑。','',''),('quantangshi-09508','送宫人入道','韋應物','quantangshi','','卷10','舍宠求仙畏色衰，辞天素面立天墀。
金丹拟驻千年貌，宝镜休匀八字眉。
公主与收珠翠后，君王看戴角冠时。
从来宫女皆相妒，说着瑶台总泪垂。','',''),('quantangshi-09509','和晋陵陆丞早春游望','韋應物','quantangshi','','卷10','独有宦游人，偏惊物候新。
云霞出海曙，梅柳渡江春。
淑气催黄鸟，晴光照绿苹。
忽闻歌苦调，归思欲霑巾。','',''),('quantangshi-09510','九日','韋應物','quantangshi','','卷10','一为吴郡守，不觉菊花开。
始有故园思，且喜众宾来。','',''),('quantangshi-09511','元次山居武昌之樊山新春大雪以诗问之','孟彥深','quantangshi','','卷10','江山十日雪，雪深江雾浓。
起来望樊山，但见羣玉峰。
林莺却不语，野兽翻有踪。
山中应大寒，短褐何以完。
皓气凝书帐，清着钓鱼竿。
怀君欲进谒，溪滑渡舟难。','',''),('quantangshi-09512','出塞曲','劉灣','quantangshi','','卷10','将军在重围，音信绝不通。
羽书如流星，飞入甘泉宫。
倚是并州儿，少年心胆雄。
一朝随召募，百战争王公。
去年桑干北，今年桑干东。
死是征人死，功是将军功。
汗马牧秋月，疲卒卧霜风。
仍闻左贤王，更将围云中。','',''),('quantangshi-09513','云南曲','劉灣','quantangshi','','卷10','百蛮乱南方，羣盗如猬起。
骚然疲中原，征战从此始。
白门太和城，来往一万里。
去者无全生，十人九人死。
岱马卧阳山，燕兵哭泸水。
妻行求死夫，父行求死子。
苍天满愁云，白骨积空垒。
哀哀云南行，十万同已矣。','',''),('quantangshi-09514','李陵别苏武','劉灣','quantangshi','','卷10','汉武爱边功，李陵提步卒。
转战单于庭，身随汉军没。
李陵不爱死，心存归汉阙。
誓欲还国恩，不为匈奴屈。
身辱家已无，长居虎狼窟。
胡天无春风，虏地多积雪。
穷阴愁杀人，况与苏武别。
发声天地哀，执手肺肠绝。
白日为我愁，阴云为我结。
生为汉宫臣，死为胡地骨。
万里长相思，终身望南月。','',''),('quantangshi-09515','虹县严孝子墓','劉灣','quantangshi','','卷10','至性教不及，因心天所资。
礼闻三年丧，尔独终身期。
下由骨肉恩，上报父母慈。
礼闻哭有卒，汝独哀无时。
前有松柏林，荆蓁结朦胧。
墓门白日闭，泣血黄泉中。
草服蔽枯骨，垢容戴飞蓬。
举声哭苍天，万木皆悲风。','',''),('quantangshi-09516','对雨愁闷寄钱大郎中','劉灣','quantangshi','','卷10','积雨细纷纷，饥寒命不分。
揽衣愁见肘，窥镜觅从文。
九陌成泥海，千山尽湿云。
龙钟驱欵段，到处倍思君。','',''),('quantangshi-09517','即席赋露中菊','劉灣','quantangshi','','卷10','众芳春竞发，寒菊露偏滋。
受气何曾异，开花独自迟。
晚成犹有分，欲采未过时。
勿弃东篱下，看随秋草衰。','',''),('quantangshi-09518','遇旅鹤','孫昌胤','quantangshi','','卷10','灵鹤产绝境，昂昂无与俦。
羣飞沧海曙，一叫云山秋。
野性方自得，人寰何所求。
时因戏祥风，偶尔来中州。
中州帝王宅，园沼深且幽。
希君惠稻粱，欲并离丹丘。
不然奋飞去，将适汗漫游。
肯作池上鹜，年年空沈浮。','',''),('quantangshi-09519','清明','孫昌胤','quantangshi','','卷10','清明暮春里，怅望北山陲。
燧火开新焰，桐花发故枝。
沈冥慙岁物，欢宴阻朋知。
不及林间鸟，迁乔并羽仪。','',''),('quantangshi-09520','和司空曙刘眘虚九日送人','孫昌胤','quantangshi','','卷10','京邑叹离羣，江楼喜遇君。
开筵当九日，泛菊外浮云。
朗咏山川霁，酣歌物色新。
君看酒中意，未肯丧斯文。','',''),('quantangshi-09521','越裳献白翟','孫昌胤','quantangshi','','卷10','圣哲符休运，伊臯列上台。
覃恩丹徼远，入贡素翚来。
北阙欣初见，南枝顾未回。
敛容残雪净，矫翼片云开。
驯扰将无惧，翻飞幸莫猜。
甘从上苑里，饮啄自裴回。','',''),('quantangshi-09522','绵州越王楼即事','喬琳','quantangshi','','卷10','三蜀澄清郡政闲，登楼携酌日跻攀。
顿觉胷怀无俗事，回看掌握是人寰。
滩声曲折涪州水，云影低衔富乐山。
行雁南飞似乡信，忽然西笑向秦关。','',''),('quantangshi-09523','牡丹','柳渾','quantangshi','','卷10','近来无奈牡丹何，数十千钱买一颗。
今朝始得分明见，也共戎葵不校多。','',''),('quantangshi-09524','读后汉逸人传二首 一','張謂','quantangshi','','卷10','子陵没已久，读史思其贤。
谁谓颍阳人，千秋如比肩。
尝闻汉皇帝，曾是旷周旋。
名位苟无心，对君犹可眠。
东过富春渚，乐此佳山川。
夜卧松下月，朝看江上烟。
钓时如有待，钓罢应忘筌。
生事在林壑，悠悠经暮年。
于今七里濑，遗迹尚依然。
高台竟寂寞，流水空潺湲。','',''),('quantangshi-09525','读后汉逸人传二首 二','張謂','quantangshi','','卷10','庞公南郡人，家在襄阳里。
何处偏来往，襄阳东陂是。
誓将业田种，终得保妻子。
何言二千石，乃欲劝吾仕。
鹳鹊巢茂林，鼋鼍穴深水。
万物从所欲，吾心亦如此。
不见鹿门山，朝朝白云起。
采药复采樵，优游终暮齿。','',''),('quantangshi-09526','同孙构免官后登蓟楼','張謂','quantangshi','','卷10','昔在五陵时，年少心亦壮。
尝矜有奇骨，必是封侯相。
东走到营州，投身似边将。
一朝去乡国，十载履亭障。
部曲皆武夫，功成不相让。
犹希虏尘动，更取林胡帐。
去年大将军，忽负乐生谤。
北别伤士卒，南迁死炎瘴。
濩落悲无成，行登蓟丘上。
长安三千里，日夕西南望。
寒沙榆塞没，秋水滦河涨。
策马从此辞，云山保闲放。','',''),('quantangshi-09527','代北州老翁答','張謂','quantangshi','','卷10','负薪老翁往北州，北望乡关生客愁。
自言老翁有三子，两人已向黄沙死。
如今小儿新长成，明年闻道又征兵。
定知此别必零落，不及相随同死生。
尽将田宅借邻伍，且复伶俜去乡士。
在生本求多子孙，及有谁知更辛苦。
近传天子尊武臣，强兵直欲静胡尘。
安边自合有长策，何必流离中国人。','',''),('quantangshi-09528','湖上对酒行','張謂','quantangshi','','卷10','夜坐不厌湖上月，昼行不厌湖上山。
眼前一尊又长满，心中万事如等闲。
主人有黍百余石，浊醪数斗应不惜。
即今相对不尽欢，别后相思复何益。
茱萸湾头归路赊，愿君且宿黄公家。
风光若此人不醉，参差辜负东园花。','',''),('quantangshi-09529','赠乔琳','張謂','quantangshi','','卷10','去年上策不见收，今年寄食仍淹留。
羡君有酒能便醉，羡君无钱能不忧。
如今五侯不爱客，羡君不问五侯宅。
如今七贵方自尊，羡君不过七贵门。
丈夫会应有知己，世上悠悠何足论。','',''),('quantangshi-09530','邵陵作','張謂','quantangshi','','卷10','尝闻虞帝苦忧人，祗为苍生不为身。
已道一朝辞北阙，何须五月更南巡。
昔时文武皆销铄，今日精灵常寂寞。
斑竹年来笋自生，白苹春尽花空落。
遥望零陵见旧丘，苍梧云起至今愁。
惟余帝子千行泪，添作潇湘万里流。','',''),('quantangshi-09531','寄李侍御','張謂','quantangshi','','卷10','柱下闻周史，书中慰越吟。
近看三岁字，遥见百年心。
价以吹嘘长，恩从顾盼深。','',''),('quantangshi-09532','寄崔沣州','張謂','quantangshi','','卷10','共襆台郎被，俱褰郡守帷。
罚金殊往日，鸣玉幸同时。
五马来何晚，双鱼赠已迟。
江头望乡月，无夜不相思。','',''),('quantangshi-09533','送裴侍御归上都','張謂','quantangshi','','卷10','楚地劳行役，秦城罢鼓鼙。
舟移洞庭岸，路出武陵溪。
江月随人影，山花趁马蹄。
离魂将别梦，先已到关西。','',''),('quantangshi-09534','送青龙一公','張謂','quantangshi','','卷10','事佛轻金印，勤王度玉关。
不知从树下，还肯到人间。
楚水青莲净，吴门白日闲。
圣朝须助理，绝莫爱东山。','',''),('quantangshi-09535','送韦侍御赴上都','張謂','quantangshi','','卷10','天朝辟书下，风宪取才难。
更谒麒麟殿，重簪獬豸冠。
月明湘水夜，霜重桂林寒。
别后头堪白，时时镜里看。','',''),('quantangshi-09536','饯田尚书还兖州','張謂','quantangshi','','卷10','忠义三朝许，威名四海闻。
更乘归鲁诏，犹忆破胡勋。
别路逢霜雨，行营对雪云。
明朝郭门外，长揖大将军。','',''),('quantangshi-09537','送杜侍御赴上都','張謂','quantangshi','','卷10','避马台中贵，登车岭外遥。
还因贡赋礼，来谒大明朝。
地入商山路，乡连渭水桥。
承恩返南越，尊酒重相邀。','',''),('quantangshi-09538','道林寺送莫侍御','張謂','quantangshi','','卷10','何处堪留客，香林隔翠微。
薜萝通驿骑，山竹挂朝衣。
霜引台乌集，风惊塔雁飞。
饮茶胜饮酒，聊以送将归。','',''),('quantangshi-09539','别睢阳故人','張謂','quantangshi','','卷10','少小客游梁，依然似故乡。
城池经战阵，人物恨存亡。
夏雨桑条绿，秋风麦穗黄。
有书无寄处，相送一霑裳。','',''),('quantangshi-09540','郡南亭子宴','張謂','quantangshi','','卷10','亭子春城外，朱门向绿林。
柳枝经雨重，松色带烟深。
漉酒迎山客，穿池集水禽。
白云常在眼，聊足慰人心。','',''),('quantangshi-09541','早春陪崔中丞浣花溪宴得暄字','張謂','quantangshi','','卷10','旌节临溪口，寒郊斗觉暄。
红亭移酒席，画鷁逗江村。
云带歌声扬，风飘舞袖翻。
花间催秉烛，川上欲黄昏。','',''),('quantangshi-09542','宴郑伯璵宅','張謂','quantangshi','','卷10','正月风光好，逢君上客稀。
晓风催鸟啭，春雪带花飞。
堂上吹金管，庭前试舞衣。
俸钱供酒债，行子未须归。','',''),('quantangshi-09543','夜同宴用人字','張謂','quantangshi','','卷10','北斗回新岁，东园值早春。
竹风能醒酒，花月解留人。
邑宰陶元亮，山家郑子真。
平生颇同道，相见日相亲。','',''),('quantangshi-09544','过从弟制疑官舍竹斋','張謂','quantangshi','','卷10','羡尔方为吏，衡门独[晏]如。
野猨偷纸笔，山鸟污图书。
竹里藏公事，花间隐使车。
不妨垂钓坐，时脍小江鱼。','',''),('quantangshi-09545','扬州雨中张十七宅观妓','張謂','quantangshi','','卷10','夜色带寒烟，灯花拂更然。
残妆添石黛，艳舞落金钿。
掩笑须欹扇，迎歌乍动弦。
不知巫峡雨，何事海西边。','',''),('quantangshi-09546','登金陵临江驿楼','張謂','quantangshi','','卷10','古戍依重险，高楼见五梁。
山根盘驿道，河水浸城墙。
庭树巢鹦鹉，园花隐麝香。
忽然江浦上，忆作捕鱼郎。','',''),('quantangshi-09547','同王征君湘中有怀','張謂','quantangshi','','卷10','八月洞庭秋，潇湘水北流。
还家万里梦，为客五更愁。
不用开书帙，偏宜上酒楼。
故人京洛满，何日复同游。','',''),('quantangshi-09548','官舍早梅','張謂','quantangshi','','卷10','堦下双梅树，春来画不成。
晚时花未落，阴处叶难生。
摘子防人到，攀枝畏鸟惊。
风光先占得，桃李莫相轻。','',''),('quantangshi-09549','玉清公主挽歌','張謂','quantangshi','','卷10','学凤年犹小，乘龙日尚赊。
初封千户邑，忽驾五云车。
地接金人岸，山通玉女家。
秋风何太早，吹落禁园花。','',''),('quantangshi-09550','别韦郎中','張謂','quantangshi','','卷10','星轺计日赴岷峨，云树连天阻笑歌。
南入洞庭随雁去，西过巫峡听猨多。
峥嵘洲上飞黄蝶，滟滪堆边起白波。
不醉郎中桑落酒，教人无奈别离何。','',''),('quantangshi-09551','送皇甫龄宰交河','張謂','quantangshi','','卷10','将军帐下来从客，小邑弹琴不易逢。
楼上胡笳传别怨，尊中腊酒为谁浓。
行人醉出双门道，少妇愁看七里烽。
今日相如轻武骑，多应朝暮客临卭。','',''),('quantangshi-09552','杜侍御送贡物戏赠','張謂','quantangshi','','卷10','铜柱朱崖道路难，伏波横海旧登坛。
越人自贡珊瑚树，汉使何劳獬豸冠。
疲马山中愁日晚，孤舟江上畏春寒。
由来此货称难得，多恐君王不忍看。','',''),('quantangshi-09553','春园家宴','張謂','quantangshi','','卷10','南园春色正相宜，大妇同行少妇随。
竹里登楼人不见，花间觅路鸟先知。
樱桃解结垂檐子，杨柳能低入户枝。
山简醉来歌一曲，参差笑杀郢中儿。','',''),('quantangshi-09554','西亭子言怀','張謂','quantangshi','','卷10','数丛芳草在堂阴，几处闲花映竹林。
攀树玄猨呼郡吏，傍溪白鸟应家禽。
青山看景知高下，流水闻声觉浅深。
官属不令拘礼数，时时缓步一相寻。','',''),('quantangshi-09555','辰阳即事','張謂','quantangshi','','卷10','青枫落叶正堪悲，黄菊残花欲待谁。
水近偏逢寒气早，山深常见日光迟。
愁中卜命看周易，病里招魂读楚词。
自恨不如湘浦雁，春来即是北归时。','',''),('quantangshi-09556','送僧','張謂','quantangshi','','卷10','童子学修道，诵经求出家。
手持贝多叶，心念优昙花。
得度北州近，随缘东路赊。
一身求清净，百毳纳袈裟。
钟岭更飞锡，炉峰期结跏。
深心大海水，广愿恒河沙。
此去不堪别，彼行安可涯。
殷勤结香火，来世上牛车。','',''),('quantangshi-09557','同诸公游云公禅寺','張謂','quantangshi','','卷10','共许寻鸡足，谁能惜马蹄。
长空净云雨，斜日半虹霓。
檐下千峰转，窗前万木低。
看花寻径远，听鸟入林迷。
地与喧闻隔，人将物我齐。
不知樵客意，何事武陵溪。','',''),('quantangshi-09558','哭护国上人','張謂','quantangshi','','卷10','昔喜三身净，今悲万劫长。
不应归北斗，应是向西方。
舍利众生得，袈裟弟子将。
鼠行残药椀，虫网旧绳牀。
别起千花塔，空留一草堂。
支公何处在，神理竟茫茫。','',''),('quantangshi-09559','送卢举使河源','張謂','quantangshi','','卷10','故人行役向边州，匹马今朝不少留。
长路关山何日尽，满堂丝竹为君愁。','',''),('quantangshi-09560','题长安壁主人','張謂','quantangshi','','卷10','世人结交须黄金，黄金不多交不深。
纵令然诺暂相许，终是悠悠行路心。','',''),('quantangshi-09561','长安失火后戏题莲花寺','張謂','quantangshi','','卷10','金园宝刹半长沙，烧劫旁延一万家。
楼殿纵随烟焰去，火中何处出莲花。','',''),('quantangshi-09562','早梅','張謂','quantangshi','','卷10','一树寒梅白玉条，逈临林村傍溪桥。
不知近水花先发，疑是经春雪未销。','',''),('quantangshi-09563','赠赵使君美人','張謂','quantangshi','','卷10','红粉青蛾映楚云，桃花马上石榴裙。
罗敷独向东方去，漫学他家作使君。','',''),('quantangshi-09564','句','張謂','quantangshi','','卷10','[稽]山贺老麤知名，吴郡张颠曾不易。
奔蛇走虺势入坐，骤雨旋风声满堂。','',''),('quantangshi-09565','北庭西郊候封大夫受降回军献上','岑參','quantangshi','','卷10','胡地苜蓿美，轮台征马肥。
大夫讨匈奴，前月西出师。
甲兵未得战，降虏来如归。
橐駞何连连，穹帐亦累累。
阴山烽火灭，劒水羽书稀。
却笑霍嫖姚，区区徒尔为。
西郊候中军，平沙悬落晖。
驿马从西来，双节夹路驰。
喜鹊捧金印，蛟龙盘画旗。
如公未四十，富贵能及时。
直上排青云，傍看疾若飞。
前年斩楼兰，去岁平月支。
天子日殊宠，朝廷方见推。
何幸一书生，忽蒙国士知。
侧身佐戎幕，敛袵事边陲。
自逐定远侯，亦着短后衣。
近来能走马，不弱并州儿。','',''),('quantangshi-09566','初至西虢官舍南池呈左右省及南宫诸故人','岑參','quantangshi','','卷10','黜官自西掖，待罪临下阳。
空积犬马恋，岂思鵷鹭行。
素多江湖意，偶佐山水乡。
满院池月静，卷帘溪雨凉。
轩窓竹翠湿，案牍荷花香。
白鸟上衣桁，青苔生笔牀。
数公不可见，一别尽相忘。
敢恨青琐客，无情华省郎。
早年迷进退，晚节悟行藏。
他日能相访，嵩南旧草堂。','',''),('quantangshi-09567','过梁州奉赠张尚书大夫公','岑參','quantangshi','','卷10','汉中二良将，今昔各一时。
韩信此登坛，尚书复来斯。
手把铜虎符，身总丈人师。
错落北斗星，照耀黑水湄。
英雄若神授，大材济时危。
顷岁遇雷云，精神感灵只。
勋业振青史，恩德继鸿私。
羌虏昔未平，华阳积僵尸。
人烟绝墟落，鬼火依城池。
巴汉空水流，襃斜惟鸟飞。
自公布德政，此地生光辉。
百堵创里闾，千家恤惸嫠。
层城重鼓角，甲士如熊罴。
坐啸风自调，行春雨仍随。
芃芃麦苗长，蔼蔼桑叶肥。
浮客相与来，羣盗不敢窥。
何幸承嘉惠，小年即相知。
富贵情易疎，相逢心不移。
置酒宴高馆，娇歌杂青丝。
锦席绣拂庐，玉盘金屈巵。
春景透高戟，江云彗长麾。
枥马嘶柳阴，美人映花枝。
门传大夫印，世拥上将旗。
承家令名扬，许国苦节施。
戎幕宁久驻，台阶不应迟。
别有弹冠士，希君无见遗。','',''),('quantangshi-09568','登北庭北楼呈幕中诸公','岑參','quantangshi','','卷10','尝读西域传，汉家得轮台。
古塞千年空，阴山独崔嵬。
二庭近西海，六月秋风来。
日暮上北楼，杀气凝不开。
大荒无鸟飞，但见白龙塠。
旧国眇天末，归心日悠哉。
上将新破胡，西郊绝烟埃。
边城寂无事，抚劒空徘徊。
幸得趋幕中，托身厕羣才。
早知安边计，未尽平生怀。','',''),('quantangshi-09569','初过陇山途中呈宇文判官','岑參','quantangshi','','卷10','一驿过一驿，驿骑如星流。
平明发咸阳，暮及陇山头。
陇水不可听，呜咽令人愁。
沙尘扑马汗，雾露凝貂裘。
西来谁家子，自道新封侯。
前月发安西，路上无停留。
都护犹未到，来时在西州。
十日过沙碛，终朝风不休。
马走碎石中，四蹄皆血流。
万里奉王事，一身无所求。
也知塞垣苦，岂为妻子谋。
山口月欲出，先照关城楼。
溪流与松风，静夜相飕飗。
别家赖归梦，山塞多离忧。
与子且携手，不愁前路修。','',''),('quantangshi-09570','陪狄员外早秋登府西楼因呈院中诸公','岑參','quantangshi','','卷10','常爱张仪楼，西山正相当。
千峰带积雪，百里临城墙。
烟氛扫晴空，草树映朝光。
车马隘百井，里閈盘二江。
亚相自登坛，时危安此方。
威声振蛮貊，惠化钟华阳。
旌节罗广庭，戈铤凛秋霜。
阶下貔虎士，幕中鵷鹭行。
今我忽登临，顾恩不望乡。
知己犹未报，鬓毛飒已苍。
时命难自知，功业岂暂忘。
蝉鸣秋城夕，鸟去江天长。
兵马休战争，风尘尚苍茫。
谁当共携手，赖有冬官郎。','',''),('quantangshi-09571','冬夜宿仙游寺南凉堂呈谦道人','岑參','quantangshi','','卷10','太乙连太白，两山知几重。
路盘石门窄，匹马行才通。
日西倒山寺，林下逢支公。
昨夜山北时，星星闻此钟。
秦女去已久，仙台在中峰。
箫声不可闻，此地留遗踪。
石潭积黛色，每岁投金龙。
乱流争迅湍，喷薄如雷风。
夜来闻清磬，月出苍山空。
空山满清光，水树相玲珑。
回廊映密竹，秋殿隐深松。
灯影落前溪，夜宿水声中。
爱兹林峦好，结宇向溪东。
相识唯山僧，邻家一钓翁。
林晚栗初拆，枝寒梨已红。
物幽兴易惬，事胜趣弥浓。
愿谢区中缘，永依金人宫。
寄报乘辇客，簪裾尔何容。','',''),('quantangshi-09572','潼关镇国军句覆使院早春寄王同州','岑參','quantangshi','','卷10','胡寇尚未尽，大军镇关门。
旌旗遍草木，兵马如云屯。
圣朝正用武，诸将皆承恩。
不见征战功，但闻歌吹喧。
儒生有长策，闭口不敢言。
昨从关东来，思与故人论。
何为廊庙器，至今居外藩。
黄霸宁淹留，苍生望腾骞。
卷帘见西岳，仙掌明朝暾。
昨夜闻春风，戴胜过后园。
各自限官守，何由叙凉温。
离忧不可忘，襟背思树萱。','',''),('quantangshi-09573','青山峡口泊舟怀狄侍御','岑參','quantangshi','','卷10','峡口秋水壮，沙边且停桡。
奔涛振石壁，峰势如动摇。
九月芦花新，弥令客心焦。
谁念在江岛，故人满天朝。
无处豁心胸，忧来醉能销。
往来巴山道，三见秋草雕。
狄生新相知，才调凌云霄。
赋诗析造化，入幕生风飙。
把笔判甲兵，战士不敢骄。
皆云梁公后，遇鼎还能调。
离别倏经时，音尘殊寂寥。
何当见夫子，不叹乡关遥。','',''),('quantangshi-09574','寄青城龙溪奂道人','岑參','quantangshi','','卷10','五岳之丈人，西望青瞢瞢。
云开露崖峤，百里见石棱。
龙溪盘中峰，上有莲华僧。
绝顶小兰若，四时岚气凝。
身同云虚无，心与溪清澄。
诵戒龙每听，赋诗人则称。
杉风吹袈裟，石壁悬孤灯。
久欲谢微禄，誓将归大乘。
愿闻开士说，庶以心相应。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-09575','梁州对雨怀麴二秀才便呈麴大判官时疾赠余新诗','岑參','quantangshi','','卷10','江上云气黑，𡷛山昨夜雷。
水恶平明飞，雨从嶓冢来。
蒙蒙随风过，萧飒鸣庭槐。
隔帘湿衣巾，当暑凉幽斋。
麴生住相近，言语阻且乖。
卧疾不见人，午时门始开。
终日看本草，药苗满前堦。
兄弟早有名，甲科皆秀才。
二人事慈母，不弱古老莱。
昨叹携手迟，未尽平生怀。
爱君有佳句，一日吟几回。','',''),('quantangshi-09576','潼关使院怀王七季友','岑參','quantangshi','','卷10','王生今才子，时辈咸所仰。
何当见颜色，终日劳梦想。
驱车到关下，欲往阻河广。
满日徒春华，思君罢心赏。
开门见太华，朝日映高掌。
忽觉莲花峰，别来更如长。
无心顾微禄，有意在独往。
不负林中期，终当出尘网。','',''),('quantangshi-09577','至大梁却寄匡城主人','岑參','quantangshi','','卷10','一从弃鱼钓，十载干明王。
无由谒天阶，却欲归沧浪。
仲秋至东郡，遂见天雨霜。
昨日梦故山，蕙草色已黄。
平明辞铁丘，薄暮游大梁。
仲秋萧条景，拔刺飞鹅鸧。
四郊阴气闭，万里无晶光。
长风吹白茅，野火烧枯桑。
故人南燕吏，籍籍名更香。
聊以玉壶赠，置之君子堂。','',''),('quantangshi-09578','宿华阴东郭客舍忆阎防','岑參','quantangshi','','卷10','次舍山郭近，解鞍鸣钟时。
主人炊新粒，行子充夜饥。
关月生首阳，照见华阴祠。
苍茫秋山晦，萧瑟寒松悲。
久从园庐别，遂与朋知辞。
旧壑兰杜晚，归轩今已迟。','',''),('quantangshi-09579','宿东溪王屋李隐者','岑參','quantangshi','','卷10','山店不凿井，百家同一泉。
晚来南村黑，雨色和人烟。
霜畦吐寒菜，沙雁噪河田。
隐者不可见，天坛飞鸟边。','',''),('quantangshi-09580','郊行寄杜位','岑參','quantangshi','','卷10','崷崪空城烟，凄清寒山景。
秋风引归梦，昨夜到汝颍。
近寺闻钟声，映陂见树影。
所思何由见，东北徒引领。','',''),('quantangshi-09581','怀叶县关操姚旷韩涉李叔齐','岑參','quantangshi','','卷10','数子皆故人，一时吏宛叶。
经年总不见，书札徒满箧。
斜日半空庭，旋风走梨叶。
去君千里地，言笑何时接。','',''),('quantangshi-09582','西蜀旅舍春叹寄朝中故人呈狄评事','岑參','quantangshi','','卷10','春与人相乖，柳青头转白。
生平未得意，览镜私自惜。
四海犹未安，一身无所适。
自从兵戈动，遂觉天地窄。
功业悲后时，光阴叹虚掷。
却为文章累，幸有开济策。
何负当途人，无心矜窘厄。
回瞻后来者，皆欲肆轥轹。
起草思南宫，寄言忆西掖。
时危任舒卷，身退知损益。
穷巷草转深，闲门日将夕。
桥西暮雨黑，篱外春江碧。
昨者初识君，相看俱是客。
声华同道术，世业通往昔。
早须归天阶，不得安孔席。
吾先税归鞅，旧国如咫尺。','',''),('quantangshi-09583','太白东溪张老舍即事寄舍弟侄等','岑參','quantangshi','','卷10','渭上秋雨过，北风何骚骚。
天晴诸山出，太白峰最高。
主人东溪老，两耳生长毫。
远近知百岁，子孙皆二毛。
中庭井兰上，一架狝猴桃。
石泉饭香粳，酒瓮开新槽。
爱兹田中趣，始悟世上劳。
我行有胜事，书此寄尔曹。','',''),('quantangshi-09584','上嘉州青衣山中峰题惠净上人幽居寄兵部杨郎中','岑參','quantangshi','','卷10','青衣谁开凿，独在水中央。
浮舟一跻攀，侧迳缘穹苍。
绝顶诣老僧，豁然登上方。
诸岭一何小，三江奔茫茫。
兰若向西开，峨眉正相当。
猿鸟乐钟磬，松萝泛天香。
江云入袈裟，山月吐绳牀。
早知清净理，久乃机心忘。
尚以名宦拘，聿来夷獠乡。
吾友不可见，郁为尚书郎。
早岁爱丹经，留心向青囊。
渺渺云智远，幽幽海怀长。
胜赏欲与俱，引领遥相望。
为政愧无术，分忧幸时康。
君子满天朝，老夫忆沧浪。
况值庐山远，抽簪归法王。','',''),('quantangshi-09585','入劒门作寄杜杨二郎中时二公并为杜元帅判官','岑參','quantangshi','','卷10','不知造化初，此山谁开坼。
双崖倚天立，万仞从地劈。
云飞不到顶，鸟去难过壁。
速驾畏岩倾，单行愁路窄。
平明地仍黑，停午日暂赤。
凛凛三伏寒，巉巉五丁迹。
与时忽开闭，作固或顺逆。
磅礴跨岷峨，巍蟠限蛮貊。
星当觜参分，地处西南僻。
陡觉烟景殊，杳将华夏隔。
刘氏昔颠覆，公孙曾败绩。
始知德不修，恃此险何益。
相公总师旅，远近罢金革。
杜母来何迟，蜀人应更惜。
暂回丹青虑，少用开济策。
二友华省郎，俱为幕中客。
良筹佐戎律，精理皆硕画。
高文出诗骚，奥学穷讨赜。
圣朝无外户，寰宇被德泽。
四海今一家，徒然劒门石。','',''),('quantangshi-09586','巩北秋兴寄崔明允','岑參','quantangshi','','卷10','白露披梧桐，玄蝉昼夜号。
秋风万里动，日暮黄云高。
君子佐休明，小人事蓬蒿。
所适在鱼鸟，焉能徇锥刀。
孤舟向广武，一鸟归成臯。
胜概日相与，思君心郁陶。','',''),('quantangshi-09587','春遇南使贻赵知音','岑參','quantangshi','','卷10','端居春心醉，襟背思树萱。
美人在南州，为尔歌北门。
北风吹烟物，戴胜鸣中园。
枯杨长新条，芳草滋旧根。
网丝结宝琴，尘埃被空樽。
适遇江海信，聊与南客论。','',''),('quantangshi-09588','冀州客舍酒酣贻王绮寄题南楼','岑參','quantangshi','','卷10','夫子傲常调，诏书下征求。
知君欲谒帝，秣马趋西周。
逸足何骎骎，美声实风流。
学富赡清词，下笔不能休。
君家一何盛，赫奕难为俦。
伯父四五人，同时为诸侯。
忆昨始相值，值君客贝丘。
相看复乘兴，携手到冀州。
前日在南县，与君上北楼。
野旷不见山，白日落草头。
客舍梨花繁，深花隐鸣鸠。
南邻新酒熟，有女弹箜篌。
醉后或狂歌，酒醒满离忧。
主人不相识，此地难淹留。
吾庐终南下，堪与王孙游。
何当肯相寻，澧上一孤舟。','',''),('quantangshi-09589','终南云际精舍寻法澄上人不遇归高冠东潭石淙望秦岭微雨作贻友人','岑參','quantangshi','','卷10','昨夜云际宿，旦从西峰回。
不见林中僧，微雨潭上来。
诸峰皆青翠，秦岭独不开。
石鼓有时鸣，秦王安在哉。
东南云开处，突兀狝猴台。
崖口悬瀑流，半空白皑皑。
喷壁四时雨，傍村终日雷。
北瞻长安道，日夕生尘埃。
若访张仲蔚，衡门满蒿莱。','',''),('quantangshi-09590','敬酬杜华淇上见赠兼呈熊曜','岑參','quantangshi','','卷10','杜侯实才子，盛名不可及。
祗曾效一官，今已年四十。
是君同时者，已有尚书郎。
怜君独未遇，淹泊在他乡。
我从京师来，到此喜相见。
共论穷途事，不觉泪满面。
忆昨癸未岁，吾兄自江东。
得君江湖诗，骨气凌谢公。
熊生尉淇上，开馆常待客。
喜我二人来，欢笑朝复夕。
县楼压春岸，戴胜鸣花枝。
吾徒在舟中，纵酒兼弹棊。
三月犹未还，寒愁满春草。
赖蒙瑶华赠，讽咏慰怀抱。','',''),('quantangshi-09591','酬成少尹骆谷行见呈','岑參','quantangshi','','卷10','闻君行路难，惆怅临长衢。
岂不惮险艰，王程剩相拘。
忆昨蓬莱宫，新授刺史符。
明主仍赐衣，价直千万余。
何幸承命日，得与夫子俱。
携手出华省，连镳赴长途。
五马当路嘶，按节投蜀都。
千崖信萦折，一径何盘纡。
层冰滑征轮，密竹碍隼旟。
深林迷昏旦，栈道凌空虚。
飞雪缩马毛，烈风擘我肤。
峰攒望天小，亭午见日初。
夜宿月近人，朝行云满车。
泉浇石罅坼，火入松心枯。
亚尹同心者，风流贤大夫。
荣禄上及亲，之官随板舆。
高价振台阁，清词出应徐。
成都春酒香，且用俸钱沽。
浮名何足道，海上堪乘桴。','',''),('quantangshi-09592','虢中酬陕西甄判官见赠','岑參','quantangshi','','卷10','微才弃散地，拙宦慙清时。
白发徒自负，青云难可期。
胡尘暗东洛，亚相方出师。
分陕振鼓鼙，二崤满旌旗。
夫子廊庙器，迥然青冥姿。
阃外佐戎律，幕中吐兵奇。
前者驿使来，忽枉行军诗。
昼吟庭花落，夜讽山月移。
昔君隐苏门，浪迹不可羁。
诏书自征用，令誉天下知。
别来春草长，东望转相思。
寂寞山城暮，空闻画角悲。','',''),('quantangshi-09593','送许子擢第归江宁拜亲因寄王大昌龄','岑參','quantangshi','','卷10','建业控京口，金陵款沧溟。
君家临秦淮，傍对石头城。
十年自勤学，一鼓游上京。
青春登甲科，动地闻香名。
解榻皆五侯，结交尽羣英。
六月槐花飞，忽思莼菜羹。
跨马出国门，丹阳返柴荆。
楚云引归帆，淮水浮客程。
到家拜亲时，入门有光荣。
乡人尽来贺，置酒相邀迎。
闲眺北顾楼，醉眠湖上亭。
月从海门出，照见茅山青。
昔为帝王州，今幸天地平。
五朝变人世，千载空江声。
玄元告灵符，丹洞获其铭。
皇帝受玉册，羣臣罗天庭。
喜气薄太阳，祥光彻窅冥。
奔走朝万国，崩腾集百灵。
王兄尚谪宦，屡见秋云生。
孤城带后湖，心与湖水清。
一县无诤辞，有时开道经。
黄鹤垂两翅，徘徊但悲鸣。
相思不可见，空望牛女星。','',''),('quantangshi-09594','武威送刘单判官赴安西行营便呈高开府','岑參','quantangshi','','卷10','热海亘铁门，火山赫金方。
白草磨天涯，湖沙奔茫茫。
夫子佐戎幕，其锋利如霜。
中岁学兵符，不能守文章。
功业须及时，立身有行藏。
男儿感忠义，万里忘越乡。
孟夏边候迟，胡国草木长。
马疾过飞鸟，天穷超夕阳。
都护新出师，五月发军装。
甲兵二百万，错落黄金光。
扬旗拂昆仑，伐鼓震蒲昌。
太白引官军，天威临大荒。
西望云似蛇，戎夷知丧亡。
浑驱大宛马，系取楼兰王。
曾到交河城，风土断人肠。
寒驿远如点，边烽互相望。
赤亭多飃风，鼓怒不可当。
有时无人行，沙石乱飘扬。
夜静天萧条，鬼哭夹道傍。
地上多髑髅，皆是古战场。
置酒高馆夕，边城月苍苍。
军中宰肥牛，堂上罗羽觞。
红泪金烛盘，娇歌艳新妆。
望君仰青冥，短翮难可翔。
苍然西郊道，握手何慨慷。','',''),('quantangshi-09595','送王大昌龄赴江宁','岑參','quantangshi','','卷10','对酒寂不语，怅然悲送君。
明时未得用，白首徒攻文。
泽国从一官，沧波几千里。
羣公满天阙，独去过淮水。
旧家富春渚，尝忆卧江楼。
自闻君欲行，频望南徐州。
穷巷独闭门，寒灯静深屋。
北风吹微雪，抱被肯同宿。
君行到京口，正是桃花时。
舟中饶孤兴，湖上多新诗。
潜虬且深蟠，黄鹄举未晚。
惜君青云器，努力加餐饭。','',''),('quantangshi-09596','送祈乐归河东','岑參','quantangshi','','卷10','祁乐后来秀，挺身出河东。
往年诣骊山，献赋温泉宫。
天子不召见，挥鞭遂从戎。
前月还长安，囊中金已空。
有时忽乘兴，画出江上峰。
牀头苍梧云，帘下天台松。
忽如高堂上，飒飒生清风。
五月火云屯，气烧天地红。
鸟且不敢飞，子行如转蓬。
少华与首阳，隔河势争雄。
新月河上出，清光满关中。
置酒灞亭别，高歌披心胸。
君到故山时，为谢五老翁。','',''),('quantangshi-09597','北庭贻宗学士道别','岑參','quantangshi','','卷10','万事不可料，叹君在军中。
读书破万卷，何事来从戎。
曾逐李轻车，西征出太蒙。
荷戈月窟外，擐甲昆仑东。
两度皆破胡，朝廷轻战功。
十年祗一命，万里如飘蓬。
容鬓老胡尘，衣裘脆边风。
忽来轮台下，相见披心胸。
饮酒对春草，弹棊闻夜钟。
今且还龟兹，臂上悬角弓。
平沙向旅馆，匹马随飞鸿。
孤城倚大碛，海气迎边空。
四月犹自寒，天山雪蒙蒙。
君有贤主将，何谓泣途穷。
时来整六翮，一举凌苍穹。','',''),('quantangshi-09598','送许拾遗恩归江宁拜亲','岑參','quantangshi','','卷10','诏书下青琐，驷马还吴洲。
束帛仍赐衣，恩波涨沧流。
微禄将及亲，向家非远游。
看君五斗米，不谢万户侯。
适出西掖垣，如到南徐州。
归心望海日，乡梦登江楼。
大江盘金陵，诸山横石头。
枫树隐茅屋，橘林系渔舟。
种药疏故畦，钓鱼垂旧鈎。
对月京口夕，观涛海门秋。
天子怜谏官，论事不可休。
早来丹墀下，高驾无淹留。','',''),('quantangshi-09599','虢州郡斋南池幽兴因与阎二侍御道别','岑參','quantangshi','','卷10','池色净天碧，水凉雨凄凄。
快风从东南，荷叶翻向西。
性本爱鱼鸟，未能返岩溪。
中岁徇微官，遂令心赏睽。
及兹佐山郡，不异寻幽栖。
小吏趋竹径，讼庭侵药畦。
胡尘暗河洛，二陕震鼓鼙。
故人佐戎轩，逸翮凌云霓。
行军在函谷，两度闻莺啼。
相看红旗下，饮酒白日低。
闻君欲朝天，驷马临道嘶。
仰望浮与沈，忽如云与泥。
夜眠驿楼月，晓发关城鸡。
惆怅西郊暮，乡书对君题。','',''),('quantangshi-09600','青龙招提归一上人远游吴楚别诗','岑參','quantangshi','','卷10','久交应真侣，最叹青龙僧。
弃官向二年，削发归一乘。
了然莹心身，洁念乐空寂。
名香泛牕户，幽磬清晓夕。
往年仗一劒，由是佐二庭。
于焉久从戎，兼复解论兵。
世人犹未知，天子愿相见。
朝从青莲宇，暮入白虎殿。
宫女擎锡杖，御筵出香炉。
说法开藏经，论边穷阵图。
忘机厌尘喧，浪迹向江海。
思师石可访，惠远峰犹在。
今旦飞锡去，何时持钵还。
湖烟冷吴门，淮月衔楚山。
一身如浮云，万里过江水。
相思眇天末，南望无穷已。','',''),('quantangshi-09601','送李翥游江外','岑參','quantangshi','','卷10','相识应十载，见君只一官。
家贫禄尚薄，霜降衣仍单。
惆怅秋草死，萧条芳岁阑。
且寻沧洲路，遥指吴云端。
匹马关塞远，孤舟江海宽。
夜眠楚烟湿，晓饭湖山寒。
砧净红鲙落，袖香朱橘团。
帆前见禹庙，枕底闻严滩。
便获赏心趣，岂歌行路难。
青门须醉别，少为解征鞍。','',''),('quantangshi-09602','送王着作赴淮西幕府','岑參','quantangshi','','卷10','燕子与百劳，一西复一东。
天空信寥廓，翔集何时同。
知己怅难遇，良朋非易逢。
怜君心相亲，与我家又通。
言笑日无度，书札凡几封。
湛湛万顷陂，森森千丈松。
不知有机巧，无事干心胸。
满堂皆酒徒，岂复羡王公。
早年抱将略，累岁依幕中。
昨者从淮西，归来奏边功。
承恩长乐殿，醉出明光宫。
逆旅悲寒蝉，客梦惊飞鸿。
发家见春草，却去闻秋风。
月色冷楚城，淮光透霜空。
各自务功业，当须激深衷。
别后能相思，何嗟山水重。','',''),('quantangshi-09603','送张秘书充刘相公通汴河判官便赴江外觐省','岑參','quantangshi','','卷10','前年见君时，见君正泥蟠。
去年见君处，见君已风[抟]。
朝趋赤墀前，高视青云端。
新登麒麟阁，适脱獬豸冠。
刘公领舟楫，汴水扬波澜。
万里江海通，九州天地宽。
昨夜动使星，今旦送征鞍。
老亲在吴郡，令弟双同官。
鲈鲙剩堪忆，莼羹殊可餐。
既参幕中画，复展膝下欢。
因送故人行，试歌行路难。
何处路最难，最难在长安。
长安多权贵，珂佩声珊珊。
儒生直如弦，权贵不须干。
斗酒取一醉，孤琴为君弹。
临岐欲有赠，持以握中兰。','',''),('quantangshi-09604','冬宵家会饯李郎司兵赴同州','岑參','quantangshi','','卷10','急管杂青丝，玉瓶金屈巵。
寒天高堂夜，扑地飞雪时。
贺君关西掾，新绶腰下垂。
白面皇家郎，逸翮青云姿。
明旦之官去，他辰良会稀。
惜别冬夜短，务欢杯行迟。
季女犹自小，老夫未令归。
且看匹马行，不得鸣凤飞。
昔岁到冯翊，人烟接京师。
曾上月楼头，遥见西岳祠。
沙苑逼官舍，莲峰压城池。
多暇或自公，读书复弹棊。
州县信徒劳，云霄亦可期。
应须力为政，聊慰此相思。','',''),('quantangshi-09605','送颜平原','岑參','quantangshi','','卷10','天子念黎庶，诏书换诸侯。
仙郎授剖符，华省辍分忧。
置酒会前殿，赐钱若山丘。
天章降三光，圣泽该九州。
吾兄镇河朔，拜命宣皇猷。
驷马辞国门，一星东北流。
夏云照银印，暑雨随行輈。
赤笔仍在箧，炉香惹衣裘。
此地邻东溟，孤城吊沧洲。
海风掣金戟，道吏呼鸣驺。
郊原北连燕，剽劫风未休。
鱼盐隘里巷，桑柘盈田畴。
为郡岂淹旬，政成应未秋。
易俗去猛虎，化人似驯鸥。
苍生已望君，黄霸宁久留。','',''),('quantangshi-09606','送狄员外巡按西山军','岑參','quantangshi','','卷10','兵马守西山，中国非得计。
不知何代策，空使蜀人弊。
八州崖谷深，千里云雪闭。
泉浇阁道滑，水冻绳桥脆。
战士常苦饥，糗粮不相继。
胡兵犹不归，空山积年岁。
儒生识损益，言事皆审谛。
狄子幕府郎，有谋必康济。
胸中悬明镜，照耀无巨细。
莫辞冒险艰，可以裨节制。
相思江楼夕，愁见月澄霁。','',''),('quantangshi-09607','虢州送郑兴宗弟归扶风别庐','岑參','quantangshi','','卷10','佐郡已三载，岂能长后时。
出关少亲友，赖汝常相随。
今旦忽言别，怆然俱泪垂。
平生沧洲意，独有青山知。
州县不敢说，云霄谁敢期。
因怀东溪老，最忆南峰缁。
为我多种药，还山应未迟。','',''),('quantangshi-09608','澧头送蒋侯','岑參','quantangshi','','卷10','君住澧水北，我家澧水西。
两村辨乔木，五里闻鸣鸡。
饮酒溪雨过，弹棊山月低。
徒闻蒋生径，尔去谁相携。','',''),('quantangshi-09609','送永寿王赞府迳归县','岑參','quantangshi','','卷10','当官接闲暇，暂得归林泉。
百里路不宿，两乡山复连。
夜深露湿簟，月出风惊蝉。
且尽主人酒，为君从醉眠。','',''),('quantangshi-09610','南池宴饯辛子赋得蝌斗子','岑參','quantangshi','','卷10','临池见蝌斗，羡尔乐有余。
不忧网与钓，幸得免为鱼。
且愿充文字，登君尺素书。','',''),('quantangshi-09611','登嘉州凌云寺作','岑參','quantangshi','','卷10','寺出飞鸟外，青峰戴朱楼。
搏壁跻半空，喜得登上头。
始知宇宙阔，下看三江流。
天晴见峨眉，如向波上浮。
迥旷烟景豁，阴森椶枏稠。
愿割区中缘，永从尘外游。
回风吹虎穴，片雨当龙湫。
僧房云蒙蒙，夏月寒飕飕。
回合俯近郭，寥落见远舟。
胜概无端倪，天宫可淹留。
一官讵足道，欲去令人愁。','',''),('quantangshi-09612','与高适薛据慈恩寺浮图','岑參','quantangshi','','卷10','塔势如涌出，孤高耸天宫。
登临出世界，磴道盘虚空。
突兀压神州，峥嵘如鬼工。
四角碍白日，七层摩苍穹。
下窥指高鸟，俯听闻惊风。
连山若波涛，奔凑似朝东。
青槐夹驰道，宫馆何玲珑。
秋色从西来，苍然满关中。
五陵北原上，万古青蒙蒙。
净理了可悟，胜因夙所宗。
誓将挂冠去，觉道资无穷。','',''),('quantangshi-09613','登千福寺楚金禅师法华院多宝塔','岑參','quantangshi','','卷10','多宝灭已久，莲华付吾师。
宝塔凌太空，忽如涌出时。
数年功不成，一志坚自持。
明主亲梦见，世人今始知。
千家献黄金，万匠磨琉璃。
既空泰山木，亦罄天府赀。
焚香如云屯，蟠盖珊珊垂。
悉窣神绕护，众魔不敢窥。
作礼覩灵境，焚香方证疑。
庶割区中缘，脱身恒在兹。','',''),('quantangshi-09614','出关经华岳寺访法华云公','岑參','quantangshi','','卷10','野寺聊解鞍，偶见法华僧。
开门对西岳，石壁青棱层。
竹径厚苍苔，松门盘紫藤。
长廊列古画，高殿悬孤灯。
五月山雨热，三峰火云蒸。
侧闻樵人言，深谷犹积冰。
久愿寻此山，至今嗟未能。
谪官忽东走，王程苦相仍。
欲去恋双树，何由穷一乘。
月轮吐山郭，夜色空清澄。','',''),('quantangshi-09615','春半与羣公同游元处士别业','岑參','quantangshi','','卷10','郭南处士宅，门外罗羣峰。
胜概忽相引，春华今正浓。
山厨竹里爨，野碓藤间舂。
对酒云数片，卷帘花万重。
岩泉嗟到晚，州县欲归慵。
草色带朝雨，滩声兼夜钟。
爱兹清俗虑，何事老尘容。
况有林下约，转怀方外踪。','',''),('quantangshi-09616','陪羣公龙冈寺泛舟','岑參','quantangshi','','卷10','汉水天一色，寺楼波底看。
钟鸣长空夕，月出孤舟寒。
映酒见山火，隔帘闻夜滩。
紫鳞掣芳饵，红烛然金盘。
良友兴正惬，胜游情未阑。
此中堪倒载，须尽主人欢。','',''),('quantangshi-09617','终南山双峰草堂作','岑參','quantangshi','','卷10','敛迹归山田，息心谢时辈。
昼还草堂卧，但与双峰对。
兴来恣佳游，事惬符胜槩。
着书高牕下，日夕见城内。
曩为世人误，遂负平生爱。
久与林壑辞，及来松杉大。
偶兹近精庐，屡得名僧会。
有时逐樵渔，尽日不冠带。
崖口上新月，石门破苍霭。
色向羣木深，光摇一潭碎。
缅怀郑生谷，颇忆严子濑。
胜事犹可追，斯人邈千载。','',''),('quantangshi-09618','左仆射相国冀公东斋幽居','岑參','quantangshi','','卷10','丞相百僚长，两朝居此官。
成功云雷际，翊圣天地安。
不矜南宫贵，祗向东山看。
宅占凤城胜，牕中云岭宽。
午时松轩夕，六月藤斋寒。
玉佩罥女萝，金印耀牡丹。
山蝉上衣桁，野鼠缘药盘。
有时披道书，竟日不着冠。
幸得趋省闱，常欣在门阑。
何当复持衡，短翮期风[抟]。','',''),('quantangshi-09619','过缑山王处士黑石谷隐居','岑參','quantangshi','','卷10','旧居缑山下，偏识缑山云。
处士久不还，见云如见君。
别来逾十秋，兵马日纷纷。
青溪开战场，黑谷屯行军。
遂令巢由辈，远逐麋鹿羣。
独有南涧水，潺湲如昔闻。','',''),('quantangshi-09620','缑山西峰草堂作','岑參','quantangshi','','卷10','结庐对中岳，青翠常在门。
遂耽水木兴，尽作渔樵言。
顷来阙章句，但欲闲心魂。
日色隐空谷，蝉声喧暮村。
曩闻道士语，偶见清净源。
隐几阅吹叶，乘秋眺归根。
独游念求仲，开径招王孙。
片雨下南涧，孤峰出东原。
栖迟虑益澹，脱略道弥敦。
野霭晴拂枕，客帆遥入轩。
尚平今何在，此意谁与论。
伫立云去尽，苍苍月开园。','',''),('quantangshi-09621','观楚国寺璋上人写一切经院南有曲池深竹','岑參','quantangshi','','卷10','璋公不出院，羣木闭深居。
誓写一切经，欲向万卷余。
挥毫散林鹊，研墨警池鱼。
音翻四句偈，字译五天书。
鸣钟竹阴晚，汲水桐花初。
雨气润衣钵，香烟泛庭除。
此地日清净，诸天应未如。
不知将锡杖，早晚蹑空虚。','',''),('quantangshi-09622','寻巩县南李处士别业','岑參','quantangshi','','卷10','先生近南郭，茅屋临东川。
桑叶隐村户，芦花映钓船。
有时着书暇，尽日牕中眠。
且喜闾井近，灌田同一泉。','',''),('quantangshi-09623','闻崔十二侍御灌口夜宿报恩寺','岑參','quantangshi','','卷10','闻君寻野寺，便宿支公房。
溪月冷深殿，江云拥回廊。
然灯松林静，煮茗柴门香。
胜事不可接，相思幽兴长。','',''),('quantangshi-09624','自潘陵尖还少室居止秋夕凭眺','岑參','quantangshi','','卷10','草堂近少室，夜静闻风松。
月出潘陵尖，照见十六峰。
九月山叶赤，溪云淡秋容。
火点伊阳村，烟深嵩角钟。
尚子不可见，蒋生难再逢。
胜惬只自知，佳趣为谁浓。
昨诣山僧期，上到天坛东。
向下望雷雨，云间见回龙。
夕与人羣疎，转爱丘壑中。
心澹水木会，兴幽鱼鸟通。
稀微了自释，出处乃不同。
况本无宦情，誓将依道风。','',''),('quantangshi-09625','南池夜宿思王屋青萝旧斋','岑參','quantangshi','','卷10','池上卧烦暑，不栉复不巾。
有时清风来，自谓羲皇人。
天晴云归尽，雨洗月色新。
公事常不闲，道书日生尘。
早年家王屋，五别青萝春。
安得还旧山，东溪垂钓纶。','',''),('quantangshi-09626','过王判官西津所居','岑參','quantangshi','','卷10','胜迹不在远，爱君池馆幽。
素怀岩中诺，宛得尘外游。
何必到清溪，忽来见沧洲。
潜移岷山石，暗引巴江流。
树密昼先夜，竹深夏已秋。
沙鸟上笔牀，溪花彗帘鈎。
夫子贱簪冕，注心向林丘。
落日出公堂，垂纶乘钓舟。
赋诗忆楚老，载酒随江鸥。
翛然一傲吏，独在西津头。','',''),('quantangshi-09627','因假归白阁西草堂','岑參','quantangshi','','卷10','雷声傍太白，雨在八九峰。
东望白阁云，半入紫阁松。
胜概纷满目，衡门趣弥浓。
幸有数亩田，得延二仲踪。
早闻达士语，偶与心相通。
误徇一微官，还山愧尘容。
钓竿不复把，野碓无人舂。
惆怅飞鸟尽，南溪闻夜钟。','',''),('quantangshi-09628','题华严寺瓌公禅房','岑參','quantangshi','','卷10','寺南几十峰，峰翠晴可掬。
朝从老僧饭，昨日崖口宿。
锡杖倚枯松，绳牀暎深竹。
东溪草堂路，来往行自熟。
生事在云山，谁能复羁束。','',''),('quantangshi-09629','东归留题太常徐卿草堂','岑參','quantangshi','','卷10','不谢古名将，吾知徐太常。
年才三十余，勇冠西南方。
顷曾策匹马，独出持两枪。
虏骑无数来，见君不敢当。
汉将小卫霍，蜀将凌关张。
卿月益清澄，将星转光芒。
复居少城北，遥对岷山阳。
车马日盈门，宾客常满堂。
曲池荫高树，小径穿丛篁。
江鸟飞入帘，山云来到牀。
题诗芭蕉滑，对酒椶花香。
诸将射猎时，君在翰墨场。
圣主赏勋业，边城最辉光。
与我情绸缪，相知久芬芳。
忽作万里别，东归三峡长。','',''),('quantangshi-09630','太一石鳖崖口潭旧庐招王学士','岑參','quantangshi','','卷10','骤雨鸣淅沥，飕飗溪谷寒。
碧潭千余尺，下见蛟龙蟠。
石门吞众流，绝岸呀层峦。
幽趣倏万变，奇观非一端。
偶逐干禄徒，十年皆小官。
抱板寻旧圃，弊庐临迅湍。
君子满清朝，小人思挂冠。
酿酒漉松子，引泉通竹竿。
何必濯沧浪，不能钓严滩。
此地可遗老，劝君来考盘。','',''),('quantangshi-09631','林卧','岑參','quantangshi','','卷10','偶得鱼鸟趣，复兹水木凉。
远峰带雨色，落日摇川光。
臼中西山药，袖里淮南方。
唯爱隐几时，独游无何乡。','',''),('quantangshi-09632','骊姬墓下作','岑參','quantangshi','','卷10','骊姬北原上，闭骨已千秋。
浍水日东注，恶名终不流。
献公恣耽惑，视子如仇雠。
此事成蔓草，我来逢古丘。
蛾眉山月苦，蝉鬓野云愁。
欲吊二公子，横汾无轻舟。','',''),('quantangshi-09633','东归晚次潼关怀古','岑參','quantangshi','','卷10','暮春别乡树，晚景低津楼。
伯夷在首阳，欲往无轻舟。
遂登关城望，下见洪河流。
自从巨灵开，流血千万秋。
行行潘生赋，赫赫曹公谋。
川上多往事，凄凉满空洲。','',''),('quantangshi-09634','楚夕旅泊古兴','岑參','quantangshi','','卷10','独鹤唳江月，孤帆凌楚云。
秋风冷萧瑟，芦荻花纷纷。
忽思湘川老，欲访云中君。
骐驎息悲鸣，愁见豺虎羣。','',''),('quantangshi-09635','先主武侯庙','岑參','quantangshi','','卷10','先主与武侯，相逢云雷际。
感通君臣分，义激鱼水契。
遗庙空萧然，英灵贯千岁。','',''),('quantangshi-09636','文公讲堂','岑參','quantangshi','','卷10','文公不可见，空使蜀人传。
讲席何时散，高台岂复全。
丰碑文字灭，冥漠不知年。','',''),('quantangshi-09637','杨雄草玄台','岑參','quantangshi','','卷10','吾悲子云居，寂寞人已去。
娟娟西江月，犹照草玄处。
精怪喜无人，睢盱藏老树。','',''),('quantangshi-09638','司马相如琴台','岑參','quantangshi','','卷10','相如琴台古，人去台亦空。
台上寒萧条，至今多悲风。
荒台汉时月，色与旧时同。','',''),('quantangshi-09639','严君平卜肆','岑參','quantangshi','','卷10','君平曾卖卜，卜肆芜已久。
至今杖头钱，时时地上有。
不知支机石，还在人间否。','',''),('quantangshi-09640','张仪楼','岑參','quantangshi','','卷10','传是秦时楼，巍巍至今在。
楼南两江水，千古长不改。
曾闻昔时人，岁月不相待。','',''),('quantangshi-09641','升仙桥','岑參','quantangshi','','卷10','长桥题柱去，犹是未达时。
及乘驷马车，却从桥上归。
名共东流水，滔滔无尽期。','',''),('quantangshi-09642','万里桥','岑參','quantangshi','','卷10','成都与维扬，相去万里地。
沧江东流疾，帆去如鸟翅。
楚客过此桥，东看尽垂泪。','',''),('quantangshi-09643','石犀','岑參','quantangshi','','卷10','江水初荡潏，蜀人几为鱼。
向无尔石犀，安得有邑居。
始知李太守，伯禹亦不如。','',''),('quantangshi-09644','龙女祠','岑參','quantangshi','','卷10','龙女何处来，来时乘风雨。
祠堂青林下，宛宛如相语。
蜀人竞祈恩，捧酒仍击鼓。','',''),('quantangshi-09645','使交河郡郡在火山脚其地苦热无雨雪献封大夫','岑參','quantangshi','','卷10','奉使按胡俗，平明发轮台。
暮投交河城，火山赤崔巍。
九月尚流汗，炎风吹沙埃。
何事阴阳工，不遣雨雪来。
吾君方忧边，分阃资大才。
昨者新破胡，安西兵马回。
铁关控天涯，万里何辽哉。
烟尘不敢飞，白草空皑皑。
军中日无事，醉舞倾金罍。
汉代李将军，微功合可咍。','',''),('quantangshi-09646','与鲜于庶子自梓州成都少尹自襃城同行至利州道中作','岑參','quantangshi','','卷10','剖竹向西蜀，岷峨眇天涯。
空深北阙恋，岂惮南路赊。
前日登七盘，旷然见三巴。
汉水出嶓冢，梁山控襃斜。
栈道笼迅湍，行人贯层崖。
岩倾劣通马，石窄难容车。
深林怯魑魅，洞穴防龙蛇。
水种新插秧，山田正烧畲。
夜猿啸山雨，曙鸟鸣江花。
过午方始饭，经时旋及瓜。
数公各游宦，千里皆辞家。
言笑忘羁旅，还如在京华。','',''),('quantangshi-09647','下外江舟怀终南旧居','岑參','quantangshi','','卷10','杉冷晓猿悲，楚客心欲绝。
孤舟巴山雨，万里阴台月。
水宿已淹时，芦花白如雪。
颜容老难赬，把镜悲鬓发。
早年好金丹，方士传口诀。
敝庐终南下，久与真侣别。
道书谁更开，药竈烟遂灭。
顷来压尘网，安得有仙骨。
岩壑归去来，公卿是何物。','',''),('quantangshi-09648','安西馆中思长安','岑參','quantangshi','','卷10','家在日出处，朝来起东风。
风从帝乡来，不异家信通。
绝域地欲尽，孤城天遂穷。
弥年但走马，终日随飘蓬。
寂寞不得意，辛勤方在公。
胡尘净古塞，兵气屯边空。
乡路眇天外，归期如梦中。
遥凭长房术，为缩天山东。','',''),('quantangshi-09649','暮秋山行','岑參','quantangshi','','卷10','疲马卧长坂，夕阳下通津。
山风吹空林，飒飒如有人。
苍旻霁凉雨，石路无飞尘。
千念集暮节，万籁悲萧晨。
鶗鴂昨夜鸣，蕙草色已陈。
况在远行客，自然多苦辛。','',''),('quantangshi-09650','赴犍为经龙阁道','岑參','quantangshi','','卷10','侧径转青壁，危梁透沧波。
汗流出鸟道，胆碎窥龙涡。
骤雨暗溪口，归云网松萝。
屡闻羌儿笛，厌听巴童歌。
江路险复永，梦魂愁更多。
圣朝幸典郡，不敢嫌岷峨。','',''),('quantangshi-09651','江上阻风雨','岑參','quantangshi','','卷10','江上风欲来，泊舟未能发。
气昏雨已过，突兀山复出。
积浪成高丘，盘涡为嵌窟。
云低岸花掩，水涨滩草没。
老树蛇蜕皮，崩崖龙退骨。
平生抱忠信，艰险殊可忽。','',''),('quantangshi-09652','经火山','岑參','quantangshi','','卷10','火山今始见，突兀蒲昌东。
赤焰烧虏云，炎氛蒸塞空。
不知阴阳炭，何独然此中。
我来严冬时，山下多炎风。
人马尽汗流，孰知造化功。','',''),('quantangshi-09653','题铁门关楼','岑參','quantangshi','','卷10','铁关天西涯，极目少行客。
关门一小吏，终日对石壁。
桥跨千仞危，路盘两崖窄。
试登西楼望，一望头欲白。','',''),('quantangshi-09654','早上五盘岭','岑參','quantangshi','','卷10','平旦驱驷马，旷然出五盘。
江回两崖鬬，日隐羣峰攒。
苍翠烟景曙，森沈云树寒。
松疎露孤驿，花密藏回滩。
栈道溪雨滑，畲田原草干。
此行为知己，不觉蜀道难。','',''),('quantangshi-09655','峨眉东脚临江听猿怀二室旧庐','岑參','quantangshi','','卷10','峨眉烟翠新，昨夜秋雨洗。
分明峰头树，倒插秋江底。
久别二室间，图他五斗米。
哀猿不可听，北客欲流涕。','',''),('quantangshi-09656','东归发犍为至泥溪舟中作','岑參','quantangshi','','卷10','前日解侯印，泛舟归山东。
平旦发犍为，逍遥信回风。
七月江水大，沧波涨秋空。
复有峨眉僧，诵经在舟中。
夜泊防虎豹，朝行逼鱼龙。
一道鸣迅湍，两边走连峰。
猿拂岸花落，鸟啼檐树重。
烟霭吴楚连，溯沿湖海通。
忆昨在西掖，复曾入南宫。
日出朝圣人，端笏陪羣公。
不意今弃置，何由豁心胸。
吾当海上去，且学乘桴翁。','',''),('quantangshi-09657','阻戎泸间羣盗','岑參','quantangshi','','卷10','南州林莽深，亡命聚其间。
杀人无昏晓，尸积填江湾。
饿虎衔髑髅，饥乌啄心肝。
腥裛滩草死，血流江水殷。
夜雨风萧萧，鬼哭连楚山。
三江行人绝，万里无征船。
唯有白鸟飞，空见秋月园。
罢官自南蜀，假道来兹川。
瞻望阳台云，惆怅不敢前。
帝乡北近日，泸口南连蛮。
何当遇长房，缩地到京关。
愿得随琴高，骑鱼向云烟。
明主每忧人，节使恒在边。
兵革方御寇，尔恶胡不悛。
吾窃悲尔徒，此生安得全。','',''),('quantangshi-09658','郡斋闲坐','岑參','quantangshi','','卷10','负郭无良田，屈身狥微禄。
平生好疎旷，何事就羁束。
幸曾趋丹墀，数得侍黄屋。
故人尽荣宠，谁念此幽独。
州县非宿心，云山欣满目。
顷来废章句，终日披案牍。
佐郡竟何成，自悲徒碌碌。','',''),('quantangshi-09659','衙郡守还','岑參','quantangshi','','卷10','世事何反覆，一身难可料。
头白翻折腰，还家私自笑。
所嗟无产业，妻子嫌不调。
五斗米留人，东溪忆垂钓。','',''),('quantangshi-09660','行军诗二首 一','岑參','quantangshi','','卷10','吾窃悲此生，四十幸未老。
一朝逢世乱，终日不自保。
胡兵夺长安，宫殿生野草。
伤心五陵树，不见二京道。
我皇在行军，兵马日浩浩。
胡雏尚未灭，诸将恳征讨。
昨闻咸阳败，杀戮净如扫。
积尸若丘山，流血涨丰镐。
干戈碍乡国，豺虎满城堡。
村落皆无人，萧条空桑枣。
儒生有长策，无处豁怀抱。
块然伤时人，举首哭苍昊。','',''),('quantangshi-09661','行军诗二首 二','岑參','quantangshi','','卷10','早知逢世乱，少小谩读书。
悔不学弯弓，向东射狂胡。
偶从谏官列，谬向丹墀趋。
未能匡吾君，虚作一丈夫。
抚劒伤世路，哀歌泣良图。
功业今已迟，览镜悲白须。
平生抱忠义，不敢私微躯。','',''),('quantangshi-09662','秋夕听罗山人弹三峡流泉','岑參','quantangshi','','卷10','皤皤岷山老，抱琴鬓苍然。
衫袖拂玉徽，为弹三峡泉。
此曲弹未半，高堂如空山。
石林何[飕飗]，忽在窗户间。
绕指弄呜咽，青丝激潺湲。
演漾怨楚云，虚徐韵秋烟。
疑兼阳台雨，似杂巫山猿。
幽引鬼神听，净令耳目便。
楚客肠欲断，湘妃泪斑斑。
谁裁青桐枝，絚以朱丝弦。
能含古人曲，递与今人传。
知音难再逢，惜君方年老。
曲终月已落，惆[怅]东斋眠。','',''),('quantangshi-09663','尹相公京兆府中棠树降甘露诗','岑參','quantangshi','','卷10','相国尹京兆，政成人不欺。
甘露降府庭，上天表无私。
非无他人家，岂少羣木枝。
被兹甘棠树，美掩召伯诗。
团团甜如[蜜]，皛皛凝若脂。
千柯玉光碎，万叶珠颗垂。
昆仑何时来，庆云相逐飞。
魏宫铜盘贮，汉帝金掌持。
王泽布人和，精心动灵只。
君臣日同德，祯瑞方潜施。
何术令大臣，感通能及兹。
忽惊政化理，暗与神物期。
却笑赵张辈，徒称今古稀。
为君天下酒，麴糵将用时。','',''),('quantangshi-09664','刘相公中书江山画障','岑參','quantangshi','','卷10','相府征墨妙，挥毫天地穷。
始知丹青笔，能夺造化功。
潇湘在帘间，庐壑横座中。
忽疑凤凰池，暗与江海通。
粉白湖上云，黛青天际峰。
昼日恒见月，孤帆如有风。
岩花不飞落，涧草无春冬。
担锡香炉缁，钓鱼沧浪翁。
如何平津意，尚想尘外踪。
富贵心独轻，山林兴弥浓。
喧幽趣颇异，出处事不同。
请君为苍生，未可追赤松。','',''),('quantangshi-09665','精卫','岑參','quantangshi','','卷10','负劒出北门，乘桴适东溟。
一鸟海上飞，云是帝女灵。
玉颜溺水死，精卫空为名。
怨积徒有志，力微竟不成。
西山木石尽，巨壑何时平。','',''),('quantangshi-09666','石上藤','岑參','quantangshi','','卷10','石上生孤藤，弱蔓依石长。
不逢高枝引，未得凌空上。
何处堪托身，为君长万丈。','',''),('quantangshi-09667','临河客舍呈狄明府兄留题县南楼','岑參','quantangshi','','卷10','黎阳城南雪正飞，黎阳渡头人未归。
河边酒家堪寄宿，主人小女能缝衣。
故人高卧黎阳县，一别三年不相见。
邑中雨雪偏着时，隔河东郡人遥羡。
邺都唯见古时丘，漳水还如旧日流。
城上望乡应不见，朝来好是嬾登楼。','',''),('quantangshi-09668','客舍悲秋有怀两省旧游呈幕中诸公','岑參','quantangshi','','卷10','三度为郎便白头，一从出守五经秋。
莫言圣主长不用，其那苍生应未休。
人间岁月如流水，客舍秋风今又起。
不知心事向谁论，江上蝉鸣空满耳。','',''),('quantangshi-09669','白雪歌送武判官归京','岑參','quantangshi','','卷10','北风卷地白草折，胡天八月即飞雪。
忽然一夜春风来，千树万树梨花开。
散入珠帘湿罗幕，狐裘不暖锦衾薄。
将军角弓不得控，都护铁衣冷难着。
瀚海阑干百丈冰，愁云黪淡万里凝。
中军置酒饮归客，胡琴琵琶与羌笛。
纷纷暮雪下辕门，风掣红旗冻不翻。
轮台东门送君去，去时雪满天山路。
山回路转不见君，雪上空留马行处。','',''),('quantangshi-09670','热海行送崔侍御还京','岑參','quantangshi','','卷10','侧闻阴山胡儿语，西头热海水如煮。
海上众鸟不敢飞，中有鲤鱼长且肥。
岸傍青草常不歇，空中白雪遥旋灭。
蒸沙烁石然虏云，沸浪炎波煎汉月。
阴火潜烧天地炉，何事偏烘西一隅。
势吞月窟侵太白，气连赤坂通单于。
送君一醉天山郭，正见夕阳海边落。
柏台霜威寒逼人，热海炎气为之薄。','',''),('quantangshi-09671','轮台歌奉送封大夫出师西征','岑參','quantangshi','','卷10','轮台城头夜吹角，轮台城北旄头落。
羽书昨夜过渠黎，单于已在金山西。
戍楼西望烟尘黑，汉兵屯在轮台北。
上将拥旄西出征，平明吹笛大军行。
四边伐鼓雪海涌，三军大呼阴山动。
虏塞兵气连云屯，战场白骨缠草根。
劒河风急雪片阔，沙口石冻马蹄脱。
亚相勤王甘苦辛，誓将报主静边尘。
古来青史谁不见，今见功名胜古人。','',''),('quantangshi-09672','敷水歌送窦渐入京','岑參','quantangshi','','卷10','罗敷昔时秦氏女，千载无人空处所。
昔时流水至今流，万事皆逐东流去。
此水东流无尽期，水声还似旧来时。
岸花仍自羞红脸，堤柳犹能学翠眉。
春去秋来不相待，水中月色长不改。
罗敷养蚕空耳闻，使君五马今何在？
九月霜天水正寒，故人西去度征鞍。
水底鲤鱼幸无数，愿君别后垂尺素。','',''),('quantangshi-09673','天山雪歌送萧治归京','岑參','quantangshi','','卷10','天山有雪常不开，千峰万岭雪崔嵬。
北风夜卷赤亭口，一夜天山雪更厚。
能兼汉月照银山，复逐胡风过铁关。
交河城边飞鸟绝，轮台路上马蹄滑。
暗霭寒氛万里凝，阑干阴崖千丈冰。
将军狐裘卧不暖，都护宝刀冻欲断。
正是天山雪下时，送君走马归京师。
雪中何以赠君别，惟有青青松树枝。','',''),('quantangshi-09674','火山云歌送别','岑參','quantangshi','','卷10','火山突兀赤亭口，火山五月火云厚。
火云满山凝未开，飞鸟千里不敢来。
平明乍逐胡风断，薄暮浑随塞雨回。
缭绕斜吞铁关树，氛氲半掩交河戍。
迢迢征路火山东，山上孤云随马去。','',''),('quantangshi-09675','青门歌送东台张判官','岑參','quantangshi','','卷10','青门金锁平旦开，城头日出使车回。
青门柳枝正堪折，路傍一日几人别。
东出青门路不穷，驿楼官树灞陵东。
花扑征衣看似绣，云随去马色疑骢。
胡姬酒垆日未午，丝绳玉缸酒如乳。
灞头落花没马蹄，昨夜微雨花成泥。
黄鹂翅湿飞转低，关东尺书醉嬾题。
须臾望君不可见，扬鞭飞鞚疾如箭。
借问使乎何时来，莫作东飞伯劳西飞燕。','',''),('quantangshi-09676','梁园歌送河南王说判官','岑參','quantangshi','','卷10','君不见梁孝王修竹园，颓墙隐辚势仍存。
娇娥曼脸成草蔓，罗帷珠帘空竹根。
大梁一旦人代改，秋月春风不相待。
池中几度雁新来，洲上千年鹤应在。
梁园二月梨花飞，却似梁王雪下时。
当时置酒延枚叟，肯料平台狐兔走。
万事翻覆如浮云，昔人空在今人口。
单父古来称宓生，祗今为政有吾兄。
輶轩若过梁园道，应傍琴台闻政声。','',''),('quantangshi-09677','走马川行奉送出师西征','岑參','quantangshi','','卷10','君不见走马川行雪海边，平沙莽莽黄入天。
轮台九月风夜吼，一川碎石大如斗，随风满地石乱走。
匈奴草黄马正肥，金山西见烟尘飞。
汉家大将西出师，将军金甲夜不脱。
半夜军行戈相拨，风头如刀面如割。
马毛带雪汗气蒸，五花连钱旋作冰。
幕中草檄砚水凝，虏骑闻之应胆慑。
料知短兵不敢接，车师西门伫献捷。','',''),('quantangshi-09678','函谷关歌送刘评事使关西','岑參','quantangshi','','卷10','君不见函谷关，崩城毁壁至今在。
树根草蔓遮古道，空谷千年长不改。
寂寞无人空旧山，圣朝无外不须关。
白马公孙何处去，青牛老人更不还。
苍苔白骨空满地，月与古时长相似。
野花不省见行人，山鸟何曾识关吏。
故人方乘使者车，吾知郭丹却不如。
请君时忆关外客，行到关西多致书。','',''),('quantangshi-09679','胡笳歌送颜真卿使赴河陇','岑參','quantangshi','','卷10','君不闻胡笳声最悲，紫髯绿眼胡人吹。
吹之一曲犹未了，愁杀楼兰征戍儿。
凉秋八月萧关道，北风吹断天山草。
昆仑山南月欲斜，胡人向月吹胡笳。
胡笳怨兮将送君，秦山遥望陇山云。
边城夜夜多愁梦，向月胡笳谁喜闻。','',''),('quantangshi-09680','秦筝歌送外甥萧正归京','岑參','quantangshi','','卷10','汝不闻秦筝声最苦，五色缠弦十三柱。
怨调慢声如欲语，一曲未终日移午。
红亭水木不知暑，忽弹黄钟和白紵。
清风飒来云不去，闻之酒醒泪如雨。
汝归秦兮弹秦声，秦声悲兮聊送汝。','',''),('quantangshi-09681','与独孤渐道别长句兼呈严八侍御','岑參','quantangshi','','卷10','轮台客舍春草满，颍阳归客肠堪断。
穷荒绝漠鸟不飞，万碛千山梦犹嬾。
怜君白面一书生，读书千卷未成名。
五侯贵门脚不到，数亩山田身自耕。
兴来浪迹无远近，及至辞家忆乡信。
无事垂鞭信马头，西南几欲穷天尽。
[奉]使三年独未归，边头词客旧来稀。
借问君来得几日，到家不觉换春衣。
高斋清昼卷帷幕，纱帽接䍦慵不着。
中酒朝眠日色高，弹棋夜半灯花落。
冰片高堆金错盘，满堂凛凛五月寒。
桂林蒲萄新吐蔓，武城刺蜜未可餐。
军中置酒夜挝鼓，锦筵红烛月未午。
花门将军善胡歌，叶河蕃王能汉语。
知尔园林压渭滨，夫人堂上泣罗帬。
鱼龙川北盘溪雨，鸟鼠山西洮水云。
台中严公于我厚，别后新诗满人口。
自怜弃置天西头，因君为问相思否。','',''),('quantangshi-09682','送费子归武昌','岑參','quantangshi','','卷10','汉阳归客悲秋草，旅舍叶飞愁不扫。
秋来倍忆武昌鱼，梦着只在巴陵道。
曾随上将过祁连，离家十年恒在边。
劒锋可惜虚用尽，马蹄无事今已穿。
知君开馆常爱客，樗蒱百金每一掷。
平生有钱将与人，江上故园空四壁。
吾观费子毛骨奇，广眉大口仍赤髭。
看君失路尚如此，人生贵贱那得知。
高秋八月归南楚，东门一壶聊出祖。
路指凤皇山北云，衣沾鹦鹉洲边雨。
勿叹蹉跎白发新，应须守道勿羞贫。
男儿何必恋妻子，莫向江村老却人。','',''),('quantangshi-09683','送韩巽入都觐省便赴举','岑參','quantangshi','','卷10','槐叶苍苍柳叶黄，秋高八月天欲霜。
青门百壶送韩侯，白云千里连嵩丘。
北堂倚门望君忆，东归扇枕后秋色。
洛阳才子能几人，明年桂枝是君得。','',''),('quantangshi-09684','送李副使赴碛西官车','岑參','quantangshi','','卷10','火山六月应更热，赤亭道口行人绝。
知君惯度祁连城，岂能愁见轮台月。
脱鞍暂入酒家垆，送君万里西击胡。
功名祗向马上取，真是英雄一丈夫。','',''),('quantangshi-09685','凉州馆中与诸判官夜集','岑參','quantangshi','','卷10','弯弯月出挂城头，城头月出照梁州。
凉州七里十万家，胡人半解弹琵琶。
琵琶一曲肠堪断，风萧萧兮夜漫漫。
河西幕中多故人，故人别来三五春。
花门楼前见秋草，岂能贫贱相看老。
一生大笑能几回，斗酒相逢须醉倒。','',''),('quantangshi-09686','酒泉太守席上醉后作','岑參','quantangshi','','卷10','琵琶长笛曲相和，羌儿胡雏齐唱歌。
浑炙犂牛烹野驼，交河美酒归叵罗。
三更醉后军中寝，无奈秦山归梦何。','',''),('quantangshi-09687','偃师东与韩樽同诣景云晖上人即事','岑參','quantangshi','','卷10','山阴老僧解楞伽，颍阳归客远相过。
烟深草湿昨夜雨，雨后秋风渡漕河。
空山终日尘事少，平郊远见行人小。
尚书碛上黄昏钟，别驾渡头一归鸟。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-09688','醉题匡城周少府厅壁','岑參','quantangshi','','卷10','妇姑城南风雨秋，妇姑城中人独愁。
愁云遮却望乡处，数日不上西南楼。
故人薄暮公事闲，玉壶美酒琥珀殷。
颍阳秋草今黄尽，醉卧君家犹未还。','',''),('quantangshi-09689','炖煌太守后庭歌','岑參','quantangshi','','卷10','炖煌太守才且贤，郡中无事高枕眠。
太守到来山出泉，黄砂碛里人种田。
炖煌耆旧鬓皓然，愿留太守更五年。
城头月出星满天，曲房置酒张锦筵。
美人红妆色正鲜，侧垂高髻插金钿。
醉坐藏钩红烛前，不知鈎在若个边。
为君手把珊瑚鞭，射得半段黄金钱，此中乐事亦已偏。','',''),('quantangshi-09690','喜韩樽相过','岑參','quantangshi','','卷10','三月灞陵春已老，故人相逢耐醉倒。
瓮头春酒黄花脂，禄米只充沽酒资。
长安城中足年少，独共韩侯开口笑。
桃花点地红斑斑，有酒留君且莫还。
与君兄弟日携手，世上虚名好是闲。','',''),('quantangshi-09691','银山碛西馆','岑參','quantangshi','','卷10','银山碛口风似箭，铁门关西月如练。
双双愁泪沾马毛，飒飒胡沙迸人面。
丈夫三十未富贵，安能终日守笔砚。','',''),('quantangshi-09692','感遇','岑參','quantangshi','','卷10','五花骢马七香车，云是平阳帝子家。
凤皇城头日欲斜，门前高树鸣春鸦。
汉家鲁元君不闻，今作城西一古坟。
昔来唯有秦王女，独自吹萧乘白云。','',''),('quantangshi-09693','太白胡僧歌','岑參','quantangshi','','卷10','闻有胡僧在太白，兰若去天三百尺。
一持楞伽入中峰，世人难见但闻钟。
牕边锡杖解两虎，牀下钵盂藏一龙。
草衣不针复不线，两耳垂肩眉覆面。
此僧年几那得知，手种青松今十围。
心将流水同清净，身与浮云无是非。
商山老人已曾识，愿一见之何由得。
山中有僧人不知，城里看山空黛色。','',''),('quantangshi-09694','卫节度赤骠马歌','岑參','quantangshi','','卷10','君家赤骠画不得，一团旋风桃花色。
红缨紫鞚珊瑚鞭，玉鞍锦鞯黄金勒。
请君鞲出看君骑，尾长窣地如红丝。
自矜诸马皆不及，却忆百金新买时。
香街紫陌凤城内，满城见者谁不爱。
扬鞭骤急白汗流，弄影行骄碧蹄碎。
紫髯胡雏金剪刀，平明剪出三鬉高。
枥上看时独意气，众中牵出偏雄豪。
骑将猎向南山口，城南孤兔不复有。
草头一点疾如飞，却使苍鹰翻向后。
忆昨看君朝未央，鸣珂拥盖满路香。
始知边将真富贵，可怜人马相辉光。
男儿称意得如此，骏马长鸣北风起。
待君东去埽胡尘，为君一日行千里。','',''),('quantangshi-09695','田使君美人舞如莲花北鋋歌','岑參','quantangshi','','卷10','美人舞如莲花旋，世人有眼应未见。
高堂满地红氍毹，试舞一曲天下无。
此曲胡人传入汉，诸客见之惊且叹。
慢脸娇娥纤复穠，轻罗金缕花葱茏。
回裾转袖若飞雪，左鋋右鋋生旋风。
琵琶横笛和未匝，花门山头黄云合。
忽作出塞入塞声，白草胡沙寒飒飒。
翻身入破如有神，前见后见回回新。
始知诸曲不可比，采莲落梅徒聒耳。
世人学舞祗是舞，恣态岂能得如此。','',''),('quantangshi-09696','裴将军宅芦管歌','岑參','quantangshi','','卷10','辽东九月芦叶断，辽东小儿采芦管。
可怜新管清且悲，一曲风飘海头满。
海树萧索天雨霜，管声寥亮月苍苍。
白狼河北堪愁恨，玄兔城南皆断肠。
辽东将军长安宅，美人芦管会佳客。
弄调啾飕胜洞箫，发声窈窕欺横笛。
夜半高堂客未回，祗将芦管送君杯。
巧能陌上惊杨柳，复向园中误落梅。
诸客爱之听未足，高卷珠帘列红烛。
将军醉舞不肯休，更使美人吹一曲。','',''),('quantangshi-09697','韦员外家花树歌','岑參','quantangshi','','卷10','今年花似去年好，去年人到今年老。
始知人老不如花，可惜落花君莫埽。
君家兄弟不可当，列卿御史尚书郎。
朝回花底恒会客，花扑玉缸春酒香。','',''),('quantangshi-09698','醉后戏与赵歌儿','岑參','quantangshi','','卷10','秦州歌儿歌调苦，偏能立唱濮阳女。
座中醉客不得意，闻之一声泪如雨。
向使逢着汉帝怜，董贤气咽不能语。','',''),('quantangshi-09699','范公丛竹歌','岑參','quantangshi','','卷10','世人见竹不解爱，知君种竹府城内。
此君托根幸得地，种来几时闻已大。
盛暑翛翛丛色寒，闲宵槭槭叶声干。
能清案牍帘下见，宜对琴书窗外看。
为君成阴将蔽日，迸笋穿堦踏还出。
守节偏凌御史霜，虚心愿比郎官笔。
君莫爱南山松树枝，竹色四时也不移。
寒天草木黄落尽，犹自青青君始知。','',''),('quantangshi-09700','玉门关盖将军歌','岑參','quantangshi','','卷10','盖将军，真丈夫，行年三十执金吾，身长七尺颇有须。
玉门关城迥且孤，黄沙万里白草枯。
南邻犬戎北接胡，将军到来备不虞。
五千甲兵胆力麤，军中无事但欢娱。
暖屋绣帘红地炉，织成壁衣花氍毹。
灯前侍婢泻玉壶，金铛乱点野酡酥。
紫绂金章左右趋，问着只是苍头奴。
美人一双闲且都，朱唇翠眉映明矑。
清歌一曲世所无，今日喜闻凤将雏。
可怜绝胜秦罗敷，使君五马谩踟蹰。
野草绣窠紫罗襦，红牙缕马对樗蒱。
玉盘纤手撒作卢，众中夸道不曾输。
枥上昂昂皆骏驹，桃花叱拨价最殊。
骑将猎向城南隅，腊日射杀千年狐。
我来塞外按边储，为君取醉酒剩沽。
醉争酒盏相喧呼，忽忆咸阳旧酒徒。','',''),('quantangshi-09701','赠酒泉韩太守','岑參','quantangshi','','卷10','太守有能政，遥闻如古人。
俸钱尽供客，家计常清贫。
酒泉西望玉关道，千山万碛皆白草。
辞君走马归长安，忆君倏忽令人老。','',''),('quantangshi-09702','赠西岳山人李冈','岑參','quantangshi','','卷10','君隐处，当一星，莲花峰头饭黄精，仙人掌上演丹经。
鸟可到，人莫攀，隐来十年不下山。
袖中短书谁为达，华阴道士卖药还。','',''),('quantangshi-09703','送张献心充副使归河西杂句','岑參','quantangshi','','卷10','将门子弟君独贤，一从受命常在边。
未至三十已高位，腰间金印色赭然。
前日承恩白虎殿，归来见者谁不羡。
箧中赐衣十重余，案上军书十二卷。
看君谋智若有神，爱君词句皆清新。
澄湖万顷深见底，清冰一片光照人。
云中昨夜使星动，西门驿楼出相送。
玉瓶素蚁腊酒香，金鞭白马紫游缰。
花门南，燕支北，张掖城头云正黑，送君一去天外忆。','',''),('quantangshi-09704','送郭乂杂言','岑參','quantangshi','','卷10','地上青草出，经冬今始归。
博陵无近信，犹未换春衣。
怜汝不忍别，送汝上酒楼。
初行莫早发，且宿霸桥头。
功名须及早，岁月莫虚掷。
早年已工诗，近日兼注易。
何时过东洛，早晚度盟津。
朝歌城边柳嚲地，邯郸道上花扑人。
去年四月初，我正在河朔。
曾上君家县北楼，楼上分明见恒岳。
中山明府待君来，须计行程及早回。
到家速觅长安使，待汝书封我自开。','',''),('quantangshi-09705','送魏升卿擢第归东都因怀魏校书陆浑乔潭','岑參','quantangshi','','卷10','井上桐叶雨，灞亭卷秋风。
故人适战胜，匹马归山东。
问君今年三十几，能使香名满人耳。
君不见三峰直上五千仞，见君文章亦如此。
如君兄弟天下稀，雄辞健笔皆若飞。
将军金印嚲紫绶，御史铁冠重绣衣。
乔生作尉别来久，因君为问平安否。
魏侯校理复何如，前日人来不得书。
陆浑山下佳可赏，蓬阁闲时日应往。
自料青云未有期，谁知白发偏能长。
垆头青丝白玉瓶，别时相顾酒如倾。
摇鞭举袂忽不见，千树万树空蝉鸣。','',''),('quantangshi-09706','送魏四落第还乡','岑參','quantangshi','','卷10','东归不称意，客舍戴胜鸣。
腊酒饮未尽，春衫缝已成。
长安柳枝春欲来，洛阳梨花在前开。
魏侯池馆今尚在，犹有太师歌舞台。
君家盛德岂徒然，时人注意在吾贤。
莫令别后无佳句，祗向垆头空醉眠。','',''),('quantangshi-09707','送宇文南金放后归太原寓居因呈太原郝主簿','岑參','quantangshi','','卷10','归去不得意，北京关路赊。
却投晋山老，愁见汾阳花。
翻作灞陵客，怜君丞相家。
夜眠旅舍雨，晓辞春城鸦。
送君系马青门口，胡姬垆头劝君酒。
为问太原贤主人，春来更有新诗否。','',''),('quantangshi-09708','西亭子送李司马','岑參','quantangshi','','卷10','高高亭子郡城西，直上千尺与云齐。
盘崖缘壁试攀跻，羣山向下飞鸟低。
使君五马天半嘶，丝绳玉壶为君提。
坐来一望无端倪，红花绿柳莺乱啼。
千家万井连回溪，酒行未醉闻暮鸡，点笔操纸为君题。
为君题，惜解携，草萋萋，没马蹄。','',''),('quantangshi-09709','渔父','岑參','quantangshi','','卷10','扁舟沧浪叟，心与沧浪清。
不自道乡里，无人知姓名。
朝从滩上饭，暮向芦中宿。
歌竟还复歌，手持一竿竹。
竿头钓丝长丈余，鼓栧乘流无定居。
世人那得识深意，此翁取适非取鱼。','',''),('quantangshi-09710','登古邺城','岑參','quantangshi','','卷10','下马登邺城，城空复何见。
东风吹野火，暮入飞云殿。
城隅南对望陵台，漳水东流不复回。
武帝宫中人去尽，年年春色为谁来。','',''),('quantangshi-09711','邯郸客舍歌','岑參','quantangshi','','卷10','客从长安来，驱马邯郸道。
伤心丛台下，一带生蔓草。
客舍门临漳水边，垂杨下系钓鱼船。
邯郸女儿夜沽酒，对客挑灯夸数钱。
酪酊醉时日正午，一曲狂歌垆上眠。','',''),('quantangshi-09712','宿蒲关东店忆杜陵别业','岑參','quantangshi','','卷10','关门锁归客，一夜梦还家。
月落河上晓，遥闻秦树鸦。
长安二月归正好，杜陵树边纯是花。','',''),('quantangshi-09713','感遇','岑參','quantangshi','','卷10','北山有芳杜，靡靡花正发。
未及得采之，秋风忽吹杀。
君不见拂云百丈青松柯，纵使秋风无奈何。
四时常作青黛色，可怜杜花不相识。','',''),('quantangshi-09714','优钵罗花歌','岑參','quantangshi','','卷10','白山南，赤山北，其间有花人不识。
绿茎碧叶好颜色，叶六瓣，花九房，夜掩朝开多异香，何不生彼中国兮生西方？移根在庭，媚我公堂，耻与众草之为伍，何亭亭而独芳？何不为人之所赏兮？深山穷谷委严霜。
吾窃悲阳关道路长，曾不得献于君王。','',''),('quantangshi-09715','蜀葵花歌','岑參','quantangshi','','卷10','昨日一花开，今日一花开。
今日花正好，昨日花已老。
始知人老不如花，可惜落花君莫埽。
人生不得长少年，莫惜牀头沽酒钱。
请君有钱向酒家，君不见，蜀葵花。','',''),('quantangshi-09716','题李士曹厅壁画度雨云歌','岑參','quantangshi','','卷10','似出栋梁里，如和风雨飞。
掾曹有时不敢归，谓言雨过湿人衣。','',''),('quantangshi-09717','入蒲关先寄秦中故人','岑參','quantangshi','','卷10','秦山数点似青黛，渭上一条如白练。
京师故人不可见，寄将两眼看飞燕。','',''),('quantangshi-09718','长门怨','岑參','quantangshi','','卷10','君王嫌妾妬，闭妾在长门。
舞袖垂新宠，愁眉结旧恩。
绿钱侵履迹，红粉湿啼痕。
羞被夭桃笑，看春独不言。','',''),('quantangshi-09719','寄左省杜拾遗','岑參','quantangshi','','卷10','联步趋丹陛，分曹限紫微。
晓随天仗入，暮惹御香归。
白发悲花落，青云羡鸟飞。
圣朝无阙事，自觉谏书稀。','',''),('quantangshi-09720','岁暮碛外寄元撝','岑參','quantangshi','','卷10','西风传戍鼓，南望见前军。
沙碛人愁月，山城犬吠云。
别家逢逼岁，出塞独离羣。
发到阳关白，书今远报君。','',''),('quantangshi-09721','寄宇文判官','岑參','quantangshi','','卷10','西行殊未已，东望何时还。
终日风与雪，连天沙复山。
二年领公事，两度过阳关。
相忆不可见，别来头已斑。','',''),('quantangshi-09722','宿关西客舍寄东山严许二山人时天宝初七月初三日在内学见有高道举征','岑參','quantangshi','','卷10','云送关西雨，风传渭北秋。
孤灯然客梦，寒杵捣乡愁。
滩上思严子，山中忆许由。
苍生今有望，飞诏下林丘。','',''),('quantangshi-09723','丘中春卧寄王子','岑參','quantangshi','','卷10','田中开白室，林下闭玄关。
卷迹人方处，无心云自闲。
竹深喧暮鸟，花缺露春山。
胜事那能说，王孙去未还。','',''),('quantangshi-09724','江行夜宿龙吼滩临眺思峨眉隐者兼寄幕中诸公','岑參','quantangshi','','卷10','官舍临江口，滩声人惯闻。
水烟晴吐月，山火夜烧云。
且欲寻方士，无心恋使君。
异乡何可住，况复久离羣。','',''),('quantangshi-09725','汉川山行呈成少尹','岑參','quantangshi','','卷10','西蜀方携手，南宫忆比肩。
平生犹不浅，羁旅转相怜。
山店云迎客，江村犬吠船。
秋来取一醉，须待月光眠。','',''),('quantangshi-09726','奉和杜相公初发京城作','岑參','quantangshi','','卷10','按节辞黄阁，登坛恋赤墀。
衔恩期报主，授律远行师。
野鹊迎金印，郊云拂画旗。
叨陪幕中客，敢和出车诗。','',''),('quantangshi-09727','敬酬李判官使院即事见呈','岑參','quantangshi','','卷10','公府日无事，吾徒只是闲。
草根侵柱础，苔色上门关。
饮砚时见鸟，卷帘晴对山。
新诗吟未足，昨夜梦东还。','',''),('quantangshi-09728','虢州酬辛侍御见赠','岑參','quantangshi','','卷10','门柳叶已大，春花今复阑。
鬓毛方二色，愁绪日千端。
夫子屡新命，鄙夫仍旧官。
相思难见面，时展尺书看。','',''),('quantangshi-09729','酬崔十三侍御登玉垒山思故园见寄','岑參','quantangshi','','卷10','玉垒天晴望，诸峰尽觉低。
故园江树北，斜日巅云西。
旷野看人小，长空共鸟齐。
高山徒仰止，不得日攀跻。','',''),('quantangshi-09730','南楼送卫凭','岑參','quantangshi','','卷10','近县多过客，似君诚亦稀。
南楼取凉好，便送故人归。
鸟向望中灭，雨侵晴处飞。
应须乘月去，且为解征衣。','',''),('quantangshi-09731','送王伯伦应制授正字归','岑參','quantangshi','','卷10','当年最称意，数子不如君。
战胜时偏许，名高人共闻。
半天城北雨，斜日灞西云。
科斗皆成字，无令错古文。','',''),('quantangshi-09732','送宇文舍人出宰元城','岑參','quantangshi','','卷10','双凫出未央，千里过河阳。
马带新行色，衣闻旧御香。
县花迎墨绶，关柳拂铜章。
别后能为政，相思淇水长。','',''),('quantangshi-09733','崔驸马山池重送宇文明府','岑參','quantangshi','','卷10','竹里过红桥，花间藉绿苗。
池凉醒别酒，山翠拂行镳。
凤去妆楼闭，凫飞叶县遥。','',''),('quantangshi-09734','送李郎尉武康','岑參','quantangshi','','卷10','潘郎腰绶新，霅上县花春。
山色低官舍，湖光映吏人。
不须嫌邑小，莫即耻家贫。
更作东征赋，知君有老亲。','',''),('quantangshi-09735','碛西头送李判官入京','岑參','quantangshi','','卷10','一身从远使，万里向安西。
汉月垂乡泪，胡沙费马蹄。
寻河愁地尽，过碛觉天低。
送子军中饮，家书醉里题。','',''),('quantangshi-09736','陪使君早春西亭送王赞府赴选','岑參','quantangshi','','卷10','西亭系五马，为送故人归。
客舍草新出，关门花欲飞。
到来逢岁酒，却去换春衣。
吏部应相待，如君才调稀。','',''),('quantangshi-09737','送刘郎将归河东','岑參','quantangshi','','卷10','借问虎贲将，从军凡几年。
杀人宝刀缺，走马貂裘穿。
山雨醒别酒，关云迎渡船。
谢君贤主将，岂忘轮台边。','',''),('quantangshi-09738','浐水东店送唐子归嵩阳','岑參','quantangshi','','卷10','野店临官路，重城压御堤。
山开灞水北，雨过杜陵西。
归梦秋能作，乡书醉嬾题。
桥回忽不见，征马尚闻嘶。','',''),('quantangshi-09739','西亭送蒋侍御还京','岑參','quantangshi','','卷10','忽闻骢马至，喜见故人来。
欲语多时别，先愁计日回。
山河宜晚眺，云雾待君开。
为报乌台客，须怜白发催。','',''),('quantangshi-09740','水亭送刘颙使还归节度','岑參','quantangshi','','卷10','无计留君住，应须绊马蹄。
红亭莫惜醉，白日眼看低。
解带怜高柳，移牀爱小溪。
此来相见少，正事各东西。','',''),('quantangshi-09741','送杨录事充潼关判官','岑參','quantangshi','','卷10','夫子方寸里，秋天澄霁江。
关西望第一，郡内政无双。
狭室下珠箔，连宵倾玉缸。
平明犹未醉，斜月隐书牕。','',''),('quantangshi-09742','送裴判官自贼中再归河阳幕府','岑參','quantangshi','','卷10','东郊未解围，忠义似君稀。
误落胡尘里，能持汉节归。
卷帘山对酒，上马雪沾衣。
却向嫖姚幕，翩翩去若飞。','',''),('quantangshi-09743','送陕县王主簿赴襄阳成亲','岑參','quantangshi','','卷10','六月襄山道，三星汉水边。
求凤应不远，去马剩须鞭。
野店愁中雨，江城梦里蝉。
襄阳多故事，为我访先贤。','',''),('quantangshi-09744','送李卿赋得孤岛石','岑參','quantangshi','','卷10','一片他山石，巉巉映小池。
绿窠攒剥藓，尖硕坐鸬鷀。
水底看常倒，花边势欲欹。
君心能不转，卿月岂相离。','',''),('quantangshi-09745','送王录事却归华阴','岑參','quantangshi','','卷10','相送欲狂歌，其如此别何。
攀辕人共惜，解印日无多。
仙掌云重见，关门路再过。
双鱼莫不寄，县外是黄河。','',''),('quantangshi-09746','送二十二兄北游寻罗中','岑參','quantangshi','','卷10','斗柄欲东指，吾兄方北游。
无媒谒明主，失计干诸侯。
夜雪入穿履，朝霜凝敝裘。
遥知客舍饮，醉里闻春鸠。','',''),('quantangshi-09747','送郑堪归东京泛水别业','岑參','quantangshi','','卷10','客舍见春草，忽闻思旧山。
看君灞陵去，匹马成臯还。
对酒风与雪，向家河复关。
因悲宦游子，终岁无时闲。','',''),('quantangshi-09748','送崔全被放归都觐省','岑參','quantangshi','','卷10','夫子不自炫，世人知者稀。
来倾阮氏酒，去着老莱衣。
渭北草新出，关东花欲飞。
楚王犹自惑，宋玉且将归。','',''),('quantangshi-09749','送孟孺卿落第归济阳','岑參','quantangshi','','卷10','献赋头欲白，还家衣已穿。
羞过灞陵树，归种汶阳田。
客舍少乡信，牀头无酒钱。
圣朝徒侧席，济上独遗贤。','',''),('quantangshi-09750','送裴校书从大夫淄川觐省','岑參','quantangshi','','卷10','尚书未出守，爱子向青州。
一路通关树，孤城近海楼。
怀中江橘熟，倚处戟门秋。
更奉轻轩去，知君无客愁。','',''),('quantangshi-09751','送杨千牛趂岁赴汝南郡觐省便成婚','岑參','quantangshi','','卷10','问吉转征鞍，安仁道姓潘。
归期明主赐，别酒故人欢。
珠箔障炉暖，孤裘耐腊寒。
汝南遥倚望，蚤去及春盘。','',''),('quantangshi-09752','送胡象落第归王屋别业','岑參','quantangshi','','卷10','看君尚少年，不第莫凄然。
可即疲献赋，山村归种田。
野花迎短褐，河柳拂长鞭。
置酒聊相送，青门一醉眠。','',''),('quantangshi-09753','送颜韶','岑參','quantangshi','','卷10','迁客犹未老，圣朝今复归。
一从襄阳住，几度梨花飞。
世事了可见，怜君人亦稀。
相逢贪醉卧，未得作春衣。','',''),('quantangshi-09754','送杜佐下第归陆浑别业','岑參','quantangshi','','卷10','正月今欲半，陆浑花未开。
出关见青草，春色正东来。
夫子且归去，明时方爱才。
还须及秋赋，莫即隐嵩莱。','',''),('quantangshi-09755','送张郎中赴陇右觐省卿公','岑參','quantangshi','','卷10','中郎凤一毛，世上独贤豪。
弱冠已银印，出身唯宝刀。
还家卿月迥，度陇将星高。
幕下多相识，边书醉嬾操。','',''),('quantangshi-09756','送楚丘麴少府赴官','岑參','quantangshi','','卷10','青袍美少年，黄绶一神仙。
微子城东面，梁王苑北边。
桃花色似马，榆荚小于钱。
单父闻相近，家书早为传。','',''),('quantangshi-09757','送蜀郡李掾','岑參','quantangshi','','卷10','饮酒俱未醉，一言聊赠君。
功曹善为政，明主还应闻。
夜宿劒门月，朝行巴水云。
江城菊花发，满道香氛氲。','',''),('quantangshi-09758','送郑少府赴滏阳','岑參','quantangshi','','卷10','子真河朔尉，邑里带清漳。
春草迎袍色，晴花拂绶香。
青山入官舍，黄鸟度宫墙。
若到铜台上，应怜魏寝荒。','',''),('quantangshi-09759','还高冠潭口留别舍弟','岑參','quantangshi','','卷10','昨日山有信，祗今耕种时。
遥传杜陵叟，怪我还山迟。
独向潭上酌，无人林下棊。
东溪忆汝处，闲卧对鸬鷀。','',''),('quantangshi-09760','醴泉东溪送程皓元镜微入蜀','岑參','quantangshi','','卷10','蜀郡路漫漫，梁州过七盘。
二人来信宿，一县醉衣冠。
溪逼春衫冷，林交宴席寒。
西南如喷酒，遥向雨中看。','',''),('quantangshi-09761','夏初醴泉南楼送太康颜少府','岑參','quantangshi','','卷10','何地堪相饯，南楼出万家。
可怜高处送，远见故人车。
野果新成子，庭槐欲作花。
爱君兄弟好，书向颍中夸。','',''),('quantangshi-09762','送严诜擢第归蜀','岑參','quantangshi','','卷10','巴江秋月新，阁道发征轮。
战胜真才子，名高动世人。
工文能似舅，擢第去荣亲。
十月天官待，应须早赴秦。','',''),('quantangshi-09763','送张直公归南郑拜省','岑參','quantangshi','','卷10','夫子思何速，世人皆叹奇。
万言不加点，七步犹嫌迟。
对酒落日后，还家飞雪时。
北堂应久待，乡梦促征期。','',''),('quantangshi-09764','送周子落第游荆南','岑參','quantangshi','','卷10','足下复不第，家贫寻故人。
且倾湘南酒，羞对关西尘。
山店橘花发，江城枫叶新。
若从巫峡过，应见楚王神。','',''),('quantangshi-09765','送薛彦伟擢第东归','岑參','quantangshi','','卷10','时辈似君稀，青春战胜归。
名登郄诜第，身着老莱衣。
称意人皆羡，还家马若飞。
一枝谁不折，棣蕚独相辉。','',''),('quantangshi-09766','送杨瑗尉南海','岑參','quantangshi','','卷10','不择南州尉，高堂有老亲。
楼台重蜃气，邑里杂鲛人。
海暗三山雨，花明五岭春。
此乡多宝玉，慎莫厌清贫。','',''),('quantangshi-09767','凤翔府行军送程使君赴成州','岑參','quantangshi','','卷10','程侯新出守，好日发行军。
拜命时人羡，能官圣主闻。
江楼黑塞雨，山郭冷秋云。
竹马诸童子，朝朝待使君。','',''),('quantangshi-09768','送张升卿宰新滏','岑參','quantangshi','','卷10','官柳叶尚小，长安春未浓。
送君浔阳宰，把酒青门钟。
水驿楚云冷，山城江树重。
遥知南湖上，只对香炉峰。','',''),('quantangshi-09769','送陈子归陆浑别业','岑參','quantangshi','','卷10','虽不旧相识，知君丞相家。
故园伊川上，夜梦方山花。
种药畏春过，出关愁路赊。
青门酒垆别，日暮东城鸦。','',''),('quantangshi-09770','稠桑驿喜逢严河南中丞便别','岑參','quantangshi','','卷10','驷马映花枝，人人夹路窥。
离心且莫问，春草自应知。
不谓青云客，犹思紫禁时。
别君能几日，看取鬓成丝。','',''),('quantangshi-09771','送蒲秀才擢第归蜀','岑參','quantangshi','','卷10','去马疾如飞，看君战胜归。
新登郄诜第，更着老莱衣。
汉水行人少，巴山客舍稀。
向南风候暖，腊月见春辉。','',''),('quantangshi-09772','送郭司马赴伊吾郡请示李明府','岑參','quantangshi','','卷10','安西美少年，脱劒卸弓弦。
不倚将军势，皆称司马贤。
秋山城北面，古治郡东边。
江上舟中月，遥思李郭仙。','',''),('quantangshi-09773','送滕亢擢第归苏州拜亲','岑參','quantangshi','','卷10','送尔姑苏客，沧波秋正凉。
橘怀三个去，桂折一枝将。
湖上山当舍，天边水是乡。
江村人事少，时作捕鱼郎。','',''),('quantangshi-09774','送任郎中出守明州','岑參','quantangshi','','卷10','罢起郎官草，初封刺史符。
城边楼枕海，郭里树侵湖。
郡政傍连楚，朝恩独借吴。
观涛秋正好，莫不上姑苏。','',''),('quantangshi-09775','临洮客舍留别祁四','岑參','quantangshi','','卷10','无事向边外，至今仍不归。
三年绝乡信，六月未春衣。
客舍洮水聒，孤城胡雁飞。
心知别君后，开口笑应稀。','',''),('quantangshi-09776','送弘文李校书往汉南拜亲','岑參','quantangshi','','卷10','未识已先闻，清辞果出羣。
如逢禰处士，似见鲍参军。
梦暗巴山雨，家连汉水云。
慈亲思爱子，几度泣霑帬。','',''),('quantangshi-09777','送李别将摄伊吾令充使赴武威便寄崔员外','岑參','quantangshi','','卷10','词赋满书囊，胡为在战场。
行间脱宝劒，邑里挂铜章。
马疾飞千里，凫飞向五凉。
遥知竹林下，星使对星郎。','',''),('quantangshi-09778','送四镇薛侍御东归','岑參','quantangshi','','卷10','相送泪沾衣，天涯独未归。
将军初得罪，门客复何依。
梦去湖山阔，书停陇雁稀。
园林幸接近，一为到柴扉。','',''),('quantangshi-09779','送张都尉东归','岑參','quantangshi','','卷10','白羽绿弓弦，年年只在边。
还家劒锋尽，出塞马蹄穿。
逐虏西逾海，平胡北到天。
封侯应不远，燕颔岂徒然。','',''),('quantangshi-09780','送樊侍御使丹阳便觐','岑參','quantangshi','','卷10','卧病穷巷晚，忽惊骢马来。
知君京口去，借问几时回。
驿舫江风引，乡书海雁催。
慈亲应倍喜，爱子在霜台。','',''),('quantangshi-09781','送张卿郎君赴硖石尉','岑參','quantangshi','','卷10','卿家送爱子，愁见灞头春。
草羡青袍色，花随黄绶新。
县西函谷路，城北大阳津。
日暮征鞍去，东郊一片尘。','',''),('quantangshi-09782','送颜少府投郑陈州','岑參','quantangshi','','卷10','一尉便垂白，数年唯草玄。
出关策匹马，逆旅闻秋蝉。
爱客多酒债，罢官无俸钱。
知君羁思少，所适主人贤。','',''),('quantangshi-09783','赵少尹南亭送郑侍御归东台','岑參','quantangshi','','卷10','红亭酒瓮香，白面绣衣郎。
砌冷虫喧坐，帘疎雨到牀。
钟催离兴急，弦逐醉歌长。
关树应先落，随君满鬓霜。','',''),('quantangshi-09784','祁四再赴江南别诗','岑參','quantangshi','','卷10','万里来又去，三湘东复西。
别多人换鬓，行远马穿蹄。
山驿秋云冷，江帆暮雨低。
怜君不解说，相忆在书题。','',''),('quantangshi-09785','送许员外江外置常平仓','岑參','quantangshi','','卷10','诏置海陵仓，朝推画省郎。
还家锦服贵，出使绣衣香。
水驿风催舫，江楼月透牀。
仍怀陆氏橘，归献老亲尝。','',''),('quantangshi-09786','送秘省虞校书赴虞乡丞','岑參','quantangshi','','卷10','花绶傍腰新，关东县欲春。
残书厌科斗，旧阁别麒麟。
虞坂临官舍，条山映吏人。
看君有知己，坦腹向平津。','',''),('quantangshi-09787','送江陵泉少府赴任便呈卫荆州','岑參','quantangshi','','卷10','神仙吏姓梅，人吏待君来。
渭北草新出，江南花已开。
城边宋玉宅，峡口楚王台。
不畏无知己，荆州甚爱才。','',''),('quantangshi-09788','奉送李太保兼御史大夫充渭北节度使','岑參','quantangshi','','卷10','诏出未央宫，登坛近总戎。
上公周太保，副相汉司空。
弓抱关西月，旗翻渭北风。
弟兄皆许国，天地荷成功。','',''),('quantangshi-09789','送江陵黎少府','岑參','quantangshi','','卷10','悔系腰间绶，翻为膝下愁。
那堪汉水远，更值楚山秋。
新橘香官舍，征帆拂县楼。
王城不敢住，岂是爱荆州。','',''),('quantangshi-09790','虢州送天平何丞入京市马','岑參','quantangshi','','卷10','关树晚苍苍，长安近夕阳。
回风醒别酒，细雨湿行装。
习战边尘黑，防秋塞草黄。
知君市骏马，不是学燕王。','',''),('quantangshi-09791','送扬州王司马','岑參','quantangshi','','卷10','君家旧淮水，水上到扬州。
海树青官舍，江云黑郡楼。
东南随去鸟，人吏待行舟。
为报吾兄道，如今已白头。','',''),('quantangshi-09792','陕州月城楼送辛判官入奏','岑參','quantangshi','','卷10','送客飞鸟外，城头楼最高。
樽前遇风雨，牕里动波涛。
谒帝向金殿，随身唯宝刀。
相思灞陵月，祗有梦偏劳。','',''),('quantangshi-09793','送王七录事赴虢州','岑參','quantangshi','','卷10','早岁即相知，嗟君最后时。
青云仍未达，白发欲成丝。
小店关门树，长河华岳祠。
弘农人吏待，莫使马行迟。','',''),('quantangshi-09794','阌乡送上官秀才归关西别业','岑參','quantangshi','','卷10','风尘奈汝何，终日独波波。
亲老无官养，家贫在外多。
醉眼轻白发，春梦渡黄河。
相去关城近，何时更肯过。','',''),('quantangshi-09795','送羽林长孙将军赴歙州','岑參','quantangshi','','卷10','剖竹向江濆，能名计日闻。
隼旗新刺史，虎劒旧将军。
驿舫宿湖月，州城浸海云。
青门酒楼上，欲别醉醺醺。','',''),('quantangshi-09796','送崔主簿赴夏阳','岑參','quantangshi','','卷10','常爱夏阳县，往年曾再过。
县中饶白鸟，郭外是黄河。
地近行程少，家贫酒债多。
知君新称意，好得奈春何。','',''),('quantangshi-09797','送梁判官归女几旧庐','岑參','quantangshi','','卷10','女几知君忆，春云相逐归。
草堂开药裹，苔壁取荷衣。
老竹移时少，新花旧处飞。
可怜真傲吏，尘事到山稀。','',''),('quantangshi-09798','送怀州吴别驾','岑參','quantangshi','','卷10','灞上柳枝黄，垆头酒正香。
春流饮去马，暮雨湿行装。
驿路通函谷，州城接太行。
覃怀人总喜，别驾得王祥。','',''),('quantangshi-09799','送人归江宁','岑參','quantangshi','','卷10','楚客忆乡信，向家湖水长。
住愁春草绿，去喜桂枝香。
海月迎归楚，江云引到乡。
吾兄应借问，为报鬓毛霜。','',''),('quantangshi-09800','送襄州任别驾','岑參','quantangshi','','卷10','别乘向襄州，萧条楚地秋。
江声官舍里，山色郡城头。
莫羡黄公盖，须乘彦伯舟。
高阳诸醉客，唯见古时丘。','',''),('quantangshi-09801','送李司谏归京','岑參','quantangshi','','卷10','别酒为谁香，春官驳正郎。
醉经秦树远，梦怯汉川长。
雨过风头黑，云开日脚黄。
知君解起草，早去入文昌。','',''),('quantangshi-09802','送緜州李司马秩满归京因呈李兵部','岑參','quantangshi','','卷10','久客厌江月，罢官思早归。
眼看春光老，羞见梨花飞。
劒北山居小，巴南音信稀。
因君报兵部，愁泪日沾衣。','',''),('quantangshi-09803','送崔员外入秦因访故园','岑參','quantangshi','','卷10','欲谒明光殿，先趋建礼门。
仙郎去得意，亚相正承恩。
竹里巴山道，花间汉水源。
凭将两行泪，为访邵平园。','',''),('quantangshi-09804','送柳录事赴梁州','岑參','quantangshi','','卷10','英掾柳家郎，离亭酒瓮香。
折腰思汉北，随传过巴阳。
江树连官舍，山云到卧牀。
知君归梦积，去去劒川长。','',''),('quantangshi-09805','送韦侍御先归京','岑參','quantangshi','','卷10','闻欲朝龙阙，应须拂豸冠。
风霜随马去，炎暑为君寒。
客泪题书落，乡愁对酒宽。
先凭报亲友，后月到长安。','',''),('quantangshi-09806','送裴侍御赴岁入京','岑參','quantangshi','','卷10','羡他骢马郎，元日谒明光。
立处闻天语，朝回惹御香。
台寒柏树绿，江暖柳条黄。
惜别津亭暮，挥戈忆鲁阳。','',''),('quantangshi-09807','送颜评事入京','岑參','quantangshi','','卷10','颜子人叹屈，宦游今未迟。
伫闻明主用，岂负青云姿。
江柳秋吐叶，山花寒满枝。
知君客愁处，月满巴川时。','',''),('quantangshi-09808','送赵侍御归上都','岑參','quantangshi','','卷10','骢马五花毛，青云归处高。
霜随驱夏暑，风逐振江涛。
执简皆推直，勤王岂告劳。
帝城谁不恋，回望动离骚。','',''),('quantangshi-09809','送杨子','岑參','quantangshi','','卷10','斗酒渭城边，垆头耐醉眠。
梨花千树雪，杨叶万条烟。
惜别添壶酒，临岐赠马鞭。
看君颍上去，新月到家圆。','',''),('quantangshi-09810','送人赴安西','岑參','quantangshi','','卷10','上马带胡鈎，翩翩度陇头。
小来思报国，不是爱封侯。
万里乡为梦，三边月作愁。
早须清黠虏，无事莫经秋。','',''),('quantangshi-09811','发临洮将赴北庭留别','岑參','quantangshi','','卷10','闻说轮台路，连年见雪飞。
春风曾不到，汉使亦应稀。
白草通疎勒，青山过武威。
勤王敢道远，私向梦中归。','',''),('quantangshi-09812','临洮泛舟赵仙舟自北庭罢使还京','岑參','quantangshi','','卷10','白发轮台使，边功竟不成。
云沙万里地，孤负一书生。
池上风回舫，桥西雨过城。
醉眠乡梦罢，东望羡归程。','',''),('quantangshi-09813','春日醴泉杜明府承恩五品宴席上赋诗','岑參','quantangshi','','卷10','凫舃旧称仙，鸿私降自天。
青袍移草色，朱绶夺花然。
邑里雷仍震，台中星欲悬。
吾兄此栖棘，因得贺初筵。','',''),('quantangshi-09814','早春陪崔中丞同泛浣花溪宴','岑參','quantangshi','','卷10','旌节临溪口，塞郊陡觉暄。
红亭移酒席，画舸逗江村。
云带歌声扬，风飘舞袖翻。
花间催秉烛，川上欲黄昏。','',''),('quantangshi-09815','喜华阴王少府使到南池宴集','岑參','quantangshi','','卷10','有客至铃下，自言身姓梅。
仙人掌里使，黄帝鼎边来。
竹影拂棋局，荷香随酒杯。
池前堪醉卧，待月未须回。','',''),('quantangshi-09816','行军雪后月夜宴王卿家','岑參','quantangshi','','卷10','子夜雪华余，卿家月影初。
酒香薰枕席，炉气暖轩除。
晚岁宦情薄，行军欢宴疎。
相逢剩取醉，身外尽空虚。','',''),('quantangshi-09817','梁州陪赵行军龙冈寺北庭泛舟宴王侍御','岑參','quantangshi','','卷10','谁宴霜台使，行军粉署郎。
唱歌江鸟没，吹笛岸花香。
酒影摇新月，滩声聒夕阳。
江钟闻已暮，归棹绿川长。','',''),('quantangshi-09818','奉陪封大夫宴得征字时封公兼鸿胪卿','岑參','quantangshi','','卷10','西边虏尽平，何处更专征。
幕下人无事，军中政已成。
座参殊俗语，乐杂异方声。
醉里东楼月，偏能照列卿。','',''),('quantangshi-09819','陪封大夫宴瀚海亭纳凉','岑參','quantangshi','','卷10','细管杂青丝，千杯倒接䍦。
军中乘兴出，海上纳凉时。
日没鸟飞急，山高云过迟。
吾从大夫后，归路拥旌旗。','',''),('quantangshi-09820','虢州西亭陪端公宴集','岑參','quantangshi','','卷10','红亭出鸟外，骏马系云端。
万岭牕前睥，千家肘底看。
开瓶酒色嫩，踏地叶声干。
为逼霜台使，重裘也觉寒。','',''),('quantangshi-09821','陪使君早春东郊游眺','岑參','quantangshi','','卷10','太守拥朱轮，东郊物候新。
莺声随坐啸，柳色唤行春。
谷口云迎马，溪边水照人。
郡中叨佐理，何幸接芳尘。','',''),('quantangshi-09822','雪后与羣公过慈恩寺','岑參','quantangshi','','卷10','乘兴忽相招，僧房暮与朝。
雪融双树湿，沙暗一灯烧。
竹外山低塔，藤间院隔桥。
归家如欲嬾，俗虑向来销。','',''),('quantangshi-09823','与鄠县羣官泛渼陂','岑參','quantangshi','','卷10','万顷浸天色，千寻穷地根。
舟移城入树，岸阔水浮村。
闲鹭惊箫管，潜蚪傍酒樽。
暝来呼小吏，列火俨归轩。','',''),('quantangshi-09824','与鄠县源少府泛渼陂','岑參','quantangshi','','卷10','载酒入天色，水凉难醉人。
清摇县郭动，碧洗云山新。
吹笛惊白鹭，垂竿跳紫鳞。
怜君公事后，陂上日娱宾。','',''),('quantangshi-09825','终南东溪中作','岑參','quantangshi','','卷10','溪水碧于草，潺潺花底流。
沙平堪濯足，石浅不胜舟。
洗药朝与暮，钓鱼春复秋。
兴来从所适，还欲向沧洲。','',''),('quantangshi-09826','与鲜于庶子泛汉江','岑參','quantangshi','','卷10','急管更须吹，杯行莫遣迟。
酒光红琥珀，江色碧琉璃。
日影浮归棹，芦花罥钓丝。
山公醉不醉，问取葛[彊]知。','',''),('quantangshi-09827','晦日陪侍御泛北池','岑參','quantangshi','','卷10','春池满复宽，晦节耐邀欢。
月带虾蟆冷，霜随獬豸寒。
水云低锦席，岸柳拂金盘。
日暮舟中散，都人夹道看。','',''),('quantangshi-09828','登凉州尹台寺','岑參','quantangshi','','卷10','胡地三月半，梨花今始开。
因从老僧饭，更上夫人台。
清唱云不去，弹弦风飒来。
应须一倒载，还似山公回。','',''),('quantangshi-09829','登总持阁','岑參','quantangshi','','卷10','高阁逼诸天，登临近日边。
晴开万井树，愁看五陵烟。
槛外低秦岭，牕中小渭川。
蚤知清净理，常愿奉金仙。','',''),('quantangshi-09830','奉陪封大夫九日登高','岑參','quantangshi','','卷10','九日黄花酒，登高会昔闻。
霜威逐亚相，杀气傍中军。
横笛惊征雁，娇歌落塞云。
边头幸无事，醉舞荷吾君。','',''),('quantangshi-09831','郡斋平望江山','岑參','quantangshi','','卷10','水路东连楚，人烟北接巴。
山光围一郡，江月照千家。
庭树纯栽橘，园畦半种茶。
梦魂知忆处，无夜不京华。','',''),('quantangshi-09832','宿岐州北郭严给事别业','岑參','quantangshi','','卷10','郭外山色暝，主人林馆秋。
疎钟入卧内，片月到牀头。
遥夜惜已半，清言殊未休。
君虽在青琐，心不忘沧洲。','',''),('quantangshi-09833','暮秋会严京兆后厅竹斋','岑參','quantangshi','','卷10','京兆小斋宽，公庭半药阑。
瓯香茶色嫩，牕冷竹声干。
盛德中朝贵，清风画省寒。
能将吏部镜，照取寸心看。','',''),('quantangshi-09834','省中即事','岑參','quantangshi','','卷10','华省谬为郎，蹉跎鬓已苍。
到来恒襆被，随例且含香。
竹影遮牕暗，花阴拂簟凉。
君王新赐笔，草奏向明光。','',''),('quantangshi-09835','寻阳七郎中宅即事','岑參','quantangshi','','卷10','万事信苍苍，机心久已忘。
无端来出守，不是厌为郎。
雨滴芭蕉赤，霜催橘子黄。
逢君开口笑，何处有他乡。','',''),('quantangshi-09836','携琴酒寻阎防崇济寺所居僧院','岑參','quantangshi','','卷10','相访但寻钟，门寒古殿松。
弹琴醒暮酒，卷幔引诸峰。
事惬林中语，人幽物外踪。
吾庐幸接近，兹地兴偏慵。','',''),('quantangshi-09837','春寻河阳陶处士别业','岑參','quantangshi','','卷10','风暖日暾暾，黄鹂飞近村。
花明潘子县，柳暗陶公门。
药椀摇山影，鱼竿带水痕。
南桥车马客，何事苦喧喧。','',''),('quantangshi-09838','晚过盘石寺礼郑和尚','岑參','quantangshi','','卷10','暂诣高僧话，来寻野寺孤。
岸花藏水碓，溪水映风炉。
顶上巢新鹊，衣中带旧珠。
谈禅未得去，辍棹且踟蹰。','',''),('quantangshi-09839','寻少室张山人闻与偃师周明府同入都','岑參','quantangshi','','卷10','中峰炼金客，昨日游人间。
叶县凫共去，葛陂龙暂还。
春云凑深水，秋雨悬空山。
寂寂清溪上，空余丹竈闲。','',''),('quantangshi-09840','虢州卧疾喜刘判官相过水亭','岑參','quantangshi','','卷10','卧疾尝晏起，朝来头未梳。
见君胜服药，清话病能除。
低柳共系马，小池堪钓鱼。
观棋不觉暝，月出水亭初。','',''),('quantangshi-09841','武威春暮闻宇文判官西使还已到晋昌','岑參','quantangshi','','卷10','岸雨过城头，黄鹂上戍楼。
塞北飘客泪，边柳挂乡愁。
白发悲明镜，青春换敝裘。
君从万里使，闻已到瓜州。','',''),('quantangshi-09842','虢州南池候严中丞不至','岑參','quantangshi','','卷10','池上日相待，知君殊未回。
徒教柳叶长，漫使梨花开。
驷马去不见，双鱼空往来。
思想不解说，孤负舟中杯。','',''),('quantangshi-09843','春兴思南山旧庐招柳建正字','岑參','quantangshi','','卷10','终岁不得意，春风今复来。
自怜蓬鬓改，羞见梨花开。
西掖诚可恋，南山思早回。
园庐幸接近，相与归蒿莱。','',''),('quantangshi-09844','郡斋南池招杨辚','岑參','quantangshi','','卷10','郡僻人事少，云山常眼前。
偶从池上醉，便向舟中眠。
与子居最近，周官情又偏。
闲时耐相访，正有牀头钱。','',''),('quantangshi-09845','高冠谷口招郑鄠','岑參','quantangshi','','卷10','谷口来相访，空斋不见君。
涧花然暮雨，潭树暖春云。
门径稀人迹，檐峰下鹿羣。
衣裳与枕席，山霭碧氛氲。','',''),('quantangshi-09846','题新乡王釜厅壁','岑參','quantangshi','','卷10','怜君守一尉，家计复清贫。
禄米尝不足，俸钱供与人。
城头苏门树，陌上黎阳尘。
不是旧相识，声同心自亲。','',''),('quantangshi-09847','题山寺僧房','岑參','quantangshi','','卷10','牕影摇羣木，墙阴载一峰。
野炉风自爇，山碓水能舂。
勤学翻知误，为官好欲慵。
高僧暝不见，月出但闻钟。','',''),('quantangshi-09848','汉上题韦氏庄','岑參','quantangshi','','卷10','结茅闻楚客，卜筑汉江边。
日落数归鸟，夜深闻扣舷。
水痕侵岸柳，山翠借厨烟。
调笑提筐妇，春来蚕几眠。','',''),('quantangshi-09849','题永乐韦少府厅壁','岑參','quantangshi','','卷10','大河南郭外，终日气昏昏。
白鸟下公府，青山当县门。
故人是邑尉，过客驻征轩。
不惮烟波阔，思君一笑言。','',''),('quantangshi-09850','题金城临河驿楼','岑參','quantangshi','','卷10','古戍依重险，高楼见五凉。
山根盘驿道，河水浸城墙。
庭树巢鹦鹉，园花隐麝香。
忽如江浦上，忆作捕鱼郎。','',''),('quantangshi-09851','初授官题高冠草堂','岑參','quantangshi','','卷10','三十始一命，宦情多欲阑。
自怜无旧业，不敢耻微官。
涧水吞樵路，山花醉药栏。
秪缘五斗米，辜负一渔竿。','',''),('quantangshi-09852','题虢州西楼','岑參','quantangshi','','卷10','错料一生事，蹉跎今白头。
纵横皆失计，妻子也堪羞。
明主虽然弃，丹心亦未休。
愁来无去处，祗上郡西楼。','',''),('quantangshi-09853','夜过盘石隔河望永乐寄闺中效齐梁体','岑參','quantangshi','','卷10','盈盈一水隔，寂寂二更初。
波上思罗袜，鱼边忆素书。
月如眉已画，云似鬓新梳。
春物知人意，桃花笑索居。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-09854','河西春暮忆秦中','岑參','quantangshi','','卷10','渭北春已老，河西人未归。
边城细草出，客馆梨花飞。
别后乡梦数，昨来家信稀。
凉州三月半，犹未脱寒衣。','',''),('quantangshi-09855','过酒泉忆杜陵别业','岑參','quantangshi','','卷10','昨夜宿[祈]连，今朝过酒泉。
黄沙西际海，白草北连天。
愁里难消日，归期尚隔年。
阳关万里梦，知处杜陵田。','',''),('quantangshi-09856','早发焉耆怀终南别业','岑參','quantangshi','','卷10','晓笛别乡泪，秋冰鸣马蹄。
一身虏云外，万里胡天西。
终日见征战，连年闻鼓鼙。
故山在何处，昨日梦清溪。','',''),('quantangshi-09857','宿铁关西馆','岑參','quantangshi','','卷10','马汗踏成泥，朝驰几万蹄。
雪中行地角，火处宿天倪。
塞迥心常怯，乡遥梦亦迷。
那知故园月，也到铁关西。','',''),('quantangshi-09858','首秋轮台','岑參','quantangshi','','卷10','异域阴山外，孤城雪海边。
秋来唯有雁，夏尽不闻蝉。
雨拂氊墙湿，风摇毳幕膻。
轮台万里地，无事历三年。','',''),('quantangshi-09859','北庭作','岑參','quantangshi','','卷10','雁塞通盐泽，龙堆接醋沟。
孤城天北畔，绝域海西头。
秋雪春仍下，朝风夜不休。
可知年四十，犹自未对侯。','',''),('quantangshi-09860','轮台即事','岑參','quantangshi','','卷10','轮台风物异，地是古单于。
三月无青草，千家尽白榆。
蕃书文字别，胡俗语音殊。
愁见流沙北，天西海一隅。','',''),('quantangshi-09861','还东山洛上作','岑參','quantangshi','','卷10','春流急不浅，归栧去何迟。
愁客叶舟里，夕阳花水时。
云晴开螮蝀，棹发起鸬鷀。
莫道东山远，衡门在梦思。','',''),('quantangshi-09862','杨固店','岑參','quantangshi','','卷10','客舍梨叶赤，邻家闻捣衣。
夜来尝有梦，坠泪缘思归。
洛水行欲尽，缑山看渐微。
长安祗千里，何事信音稀。','',''),('quantangshi-09863','巴南舟中思陆浑别业','岑參','quantangshi','','卷10','泸水南州远，巴山北客稀。
岭云撩乱起，溪鹭等闲飞。
镜里愁衰鬓，舟中换旅衣。
梦魂知忆处，无夜不先归。','',''),('quantangshi-09864','晚发五渡','岑參','quantangshi','','卷10','客厌巴南地，乡邻劒北天。
江村片雨外，野寺夕阳边。
芋叶藏山径，芦花杂渚田。
舟行未可住，乘月且须牵。','',''),('quantangshi-09865','巴南舟中夜市','岑參','quantangshi','','卷10','渡口欲黄昏，归人争渡喧。
近钟清野寺，远火点江村。
见雁思乡信，闻猿积泪痕。
孤舟万里外，秋月不堪论。','',''),('quantangshi-09866','江上春叹','岑參','quantangshi','','卷10','腊月江上暖，南桥新柳枝。
春风触处到，忆得故园时。
终日不如意，出门何所之。
从人觅颜色，自笑弱男儿。','',''),('quantangshi-09867','初至犍为作','岑參','quantangshi','','卷10','山色轩槛内，滩声枕席间。
草生公府静，花落讼庭闲。
云雨连三峡，风尘接百蛮。
到来能几日，不觉鬓毛斑。','',''),('quantangshi-09868','使院中新栽柏树子呈李十五栖筠','岑參','quantangshi','','卷10','爱尔青青色，移根此地来。
不曾台上种，留向碛中栽。
脆叶欺门柳，狂花笑院梅。
不须愁岁晚，霜露岂能摧。','',''),('quantangshi-09869','咏郡斋壁画片云','岑參','quantangshi','','卷10','云片何人画，尘侵粉色微。
未曾行雨去，不见逐风归。
只怪偏凝壁，回看欲惹衣。
丹青忽借便，移向帝乡飞。','',''),('quantangshi-09870','临洮龙兴寺玄上人院同咏青木香丛','岑參','quantangshi','','卷10','移根自远方，种得在僧房。
六月花新吐，三春叶已长。
抽茎高锡杖，引影到绳牀。
只为能除疾，倾心向药王。','',''),('quantangshi-09871','成王挽歌','岑參','quantangshi','','卷10','幽山悲旧桂，长坂怆余兰。
地底孤灯冷，泉中一镜寒。
铭旌门客送，骑吹路人看。
漫作琉璃椀，淮王误合丹。','',''),('quantangshi-09872','苗侍中挽歌二首 一','岑參','quantangshi','','卷10','摄政朝章重，持衡国相尊。
笔端通造化，掌内运干坤。
青史遗芳满，黄枢故事存。
空悲渭桥路，谁对汉皇言。','',''),('quantangshi-09873','苗侍中挽歌二首 二','岑參','quantangshi','','卷10','天子悲元老，都人惜上公。
优贤几杖在，会葬市朝空。
丹旐飞斜日，清笳怨暮风。
平生门下客，继美庙堂中。','',''),('quantangshi-09874','故仆射裴公挽歌三首 一','岑參','quantangshi','','卷10','盛德资邦杰，嘉谟作世程。
门瞻驷马贵，时仰八龙名。
罢市秦人送，还乡绛老迎。
莫埋丞相印，留着付玄成。','',''),('quantangshi-09875','故仆射裴公挽歌三首 二','岑參','quantangshi','','卷10','五府瞻高位，三台丧大贤。
礼容还故绛，宠赠冠新田。
气歇汾阴鼎，魂飞京兆阡。
先时劒已没，陇树久苍然。','',''),('quantangshi-09876','故仆射裴公挽歌三首 三','岑參','quantangshi','','卷10','富贵徒言久，乡闾殁后归。
锦衣都未着，丹旐忽先飞。
哀挽辞秦塞，悲笳出帝畿。
遥知九原上，渐觉吊人稀。','',''),('quantangshi-09877','河西太守杜公挽歌四首 一','岑參','quantangshi','','卷10','蒙叟悲藏壑，殷宗惜济川。
长安非旧日，京兆是新阡。
黄霸官犹屈，苍生望已愆。
唯余卿月在，留向杜陵悬。','',''),('quantangshi-09878','河西太守杜公挽歌四首 二','岑參','quantangshi','','卷10','鼓角城中出，坟茔郭外新。
雨随思太守，云从送夫人。
蒿里埋双劒，松门闭万春。
回瞻北堂上，金印已生尘。','',''),('quantangshi-09879','河西太守杜公挽歌四首 三','岑參','quantangshi','','卷10','忆昨明光殿，新承天子恩。
剖符移北地，授钺领西门。
塞草迎军幕，边云拂使轩。
至今闻陇外，戎虏尚亡魂。','',''),('quantangshi-09880','河西太守杜公挽歌四首 四','岑參','quantangshi','','卷10','漫漫澄波阔，沈沈大厦深。
秉心常匪席，行义每挥金。
汲引窥兰室，招携入翰林。
多君有令子，犹注世人心。','',''),('quantangshi-09881','故河南尹岐国公赠工部尚书苏公挽歌二首 一','岑參','quantangshi','','卷10','河尹恩荣旧，尚书宠赠新。
一门传画戟，几世驾朱轮。
夜色何时晓，泉台不复春。
唯余朝服在，金印已生尘。','',''),('quantangshi-09882','故河南尹岐国公赠工部尚书苏公挽歌二首 二','岑參','quantangshi','','卷10','白日扃泉户，青春掩夜台。
旧堂阶草长，空院砌花开。
山晚铭旌去，郊寒骑吹回。
三川难可见，应惜庾公才。','',''),('quantangshi-09883','韩员外夫人清河县君崔氏挽歌二首 一','岑參','quantangshi','','卷10','令德当时重，高门举世推。
从夫荣已绝，封邑宠难追。
陌上人皆惜，花间鸟亦悲。
仙郎看陇月，犹忆画眉时。','',''),('quantangshi-09884','韩员外夫人清河县君崔氏挽歌二首 二','岑參','quantangshi','','卷10','遽闻伤别劒，忽复叹藏舟。
灯冷泉中夜，衣寒地下秋。
青松吊客泪，丹旐路人愁。
徒有清河在，空悲逝水流。','',''),('quantangshi-09885','西河郡太原守张夫人挽歌','岑參','quantangshi','','卷10','鹊印庆仍传，鱼轩宠莫先。
从夫元凯贵，训子孟轲贤。
龙是双归日，鸾非独舞年。
哀容今共尽，凄怆杜陵田。','',''),('quantangshi-09886','南溪别业','岑參','quantangshi','','卷10','结宇依青嶂，开轩对翠畴。
树交花两色，溪合水重流。
竹径春来埽，兰樽夜不收。
逍遥自得意，鼓腹醉中游。','',''),('quantangshi-09887','奉和中书舍人贾至早朝大明宫','岑參','quantangshi','','卷10','鸡鸣紫陌曙光寒，莺啭皇州春色阑。
金阙晓钟开万户，玉阶仙仗拥千官。
花迎劒佩星初落，柳拂旌旗露未干。
独有凤皇池上客，阳春一曲和皆难。','',''),('quantangshi-09888','和祠部王员外雪后早朝即事','岑參','quantangshi','','卷10','长安雪后似春归，积素凝华连曙晖。
色借玉珂迷晓骑，光添银烛晃朝衣。
西山落月临天仗，北阙晴云捧禁闱。
闻道仙郎歌白雪，由来此曲和人稀。','',''),('quantangshi-09889','奉和相公发益昌','岑參','quantangshi','','卷10','相[国]临戎别帝京，拥麾持节远横行。
朝登劒阁云随马，夜渡巴江雨洗兵。
山花万朵迎征盖，川柳千条拂去旌。
暂到蜀城应计日，须知明主待持衡。','',''),('quantangshi-09890','秋夕读书幽兴献兵部李侍郎','岑參','quantangshi','','卷10','年纪蹉跎四十强，自怜头白始为郎。
雨滋苔藓侵堦绿，秋飒梧桐覆井黄。
惊蝉也解求高树，旅雁还应厌后行。
览卷试穿邻舍壁，明灯何惜借余光。','',''),('quantangshi-09891','使君席夜送严河南赴长水','岑參','quantangshi','','卷10','娇歌急管杂青丝，银烛金杯映翠眉。
使君地主能相送，河尹天明坐莫辞。
春城月出人皆醉，野戍花深马去迟。
寄声报尔山翁道，今日河南胜昔时。','',''),('quantangshi-09892','暮春虢州东亭送李司马归扶风别庐','岑參','quantangshi','','卷10','柳嚲莺娇花复殷，红亭绿酒送君还。
到来函谷愁中月，归去磻溪梦里山。
帘前春色应须惜，世上浮名好是闲。
西望乡关肠欲断，对君衫袖泪痕斑。','',''),('quantangshi-09893','九日使君席奉饯卫中丞赴长水','岑參','quantangshi','','卷10','节使横行西出师，鸣弓擐甲羽林儿。
台上霜风凌草木，军中杀气傍旌旗。
预知汉将宣威日，正是胡尘欲灭时。
为报使君多泛菊，更将弦管醉东篱。','',''),('quantangshi-09894','西掖省即事','岑參','quantangshi','','卷10','西掖重云开曙晖，北山疎雨点朝衣。
千门柳色连青琐，三殿花香入紫微。
平明端笏陪鵷列，薄暮垂鞭信马归。
官拙自悲头白尽，不如岩下偃荆扉。','',''),('quantangshi-09895','首春渭西郊行呈蓝田张二主簿','岑參','quantangshi','','卷10','迥风度雨渭城西，细草新花踏作泥。
秦女峰头雪未尽，胡公阪上日初低。
愁窥白发羞微禄，悔别青山忆旧溪。
闻道辋川多胜事，玉壶春酒正堪携。','',''),('quantangshi-09896','赴嘉州过城固县寻永安超禅师房','岑參','quantangshi','','卷10','满寺枇杷冬着花，老僧相见具袈裟。
汉王城北雪初霁，韩信台西日欲斜。
门外不须催五马，林中且听演三车。
岂料巴川多胜事，为君书此报京华。','',''),('quantangshi-09897','酬畅当嵩山寻麻道士见寄','岑參','quantangshi','','卷10','闻逐樵夫闲看棋，忽逢人世是秦时。
开云种玉嫌山浅，渡海传书怪鹤迟。
阴洞石幢微有字，古坛松树半无枝。
烦君远示青囊录，愿得相从一问师。','',''),('quantangshi-09898','和刑部成员外秋夜寓直寄台省知己','岑參','quantangshi','','卷10','列宿光三署，仙郎直五宵。
时衣天子赐，厨膳大官调。
长乐钟应近，明光漏不遥。
黄门持被覆，侍女捧香烧。
笔为题诗点，灯缘起草挑。
竹喧交砌叶，柳嚲拂牕条。
粉署荣新命，霜台忆旧僚。
名香播兰蕙，重价蕴琼瑶。
击水翻沧海，[抟]风透赤霄。
微才喜同舍，何幸忽闻韶。','',''),('quantangshi-09899','送庐郎中除杭州赴任','岑參','quantangshi','','卷10','罢起郎官草，初分刺史符。
海云迎过楚，江月引归吴。
城低涛声震，楼端蜃气孤。
千家窥驿舫，五马饮春湖。
柳色供诗用，莺声送酒须。
知君望乡处，枉道上姑苏。','',''),('quantangshi-09900','奉送李宾客荆南迎亲','岑參','quantangshi','','卷10','迎亲辞旧苑，恩诏下储闱。
昨见双鱼去，今看驷马归。
驿帆湘水阔，客舍楚山稀。
手把黄香扇，身披莱子衣。
鹊随金印喜，乌傍板舆飞。
胜作东征赋，还家满路辉。','',''),('quantangshi-09901','送严维下第还江东','岑參','quantangshi','','卷10','勿叹今不第，似君殊未迟。
且归沧洲去，相送青门时。
望鸟指乡远，问人愁路疑。
敝裘沾暮雪，归棹带流澌。
严子滩复在，谢公文可追。
江臯如有信，莫不寄新诗。','',''),('quantangshi-09902','六月三十日水亭送华阴王少府还县','岑參','quantangshi','','卷10','亭晚人将别，池凉酒未酣。
关门劳夕梦，仙掌引归骖。
荷叶藏鱼艇，藤花罥客簪。
残云收夏暑，新雨带秋岚。
失路情无适，离怀思不堪。
赖兹庭户里，别有小江潭。','',''),('quantangshi-09903','饯王岑判官赴襄阳道','岑參','quantangshi','','卷10','故人汉阳使，走马向南荆。
不厌楚山路，祗怜襄水清。
津头习氏宅，江上夫人城。
夜入橘花宿，朝穿桐叶行。
害羣应自慑，持法固须平。
暂得青门醉，斜光速去程。','',''),('quantangshi-09904','送薛弁归河东','岑參','quantangshi','','卷10','薛侯故乡处，五老峰西头。
归路秦树灭，到乡河水流。
看君马首去，满耳蝉声愁。
献赋今未售，读书凡几秋。
应过伯夷庙，为上关城楼。
楼上能相忆，西南指雍州。','',''),('quantangshi-09905','送薛播擢第归河东','岑參','quantangshi','','卷10','归去新战胜，盛名人共闻。
乡连渭川树，家近条山云。
夫子能好学，圣朝全用文。
弟兄负世誉，词赋超人羣。
雨气醒别酒，城阴低暮曛。
遥知出关后，更有一终军。','',''),('quantangshi-09906','送陶铣弃举荆南觐省','岑參','quantangshi','','卷10','明时不爱璧，浪迹东南游。
何必世人识，知君轻五侯。
采兰度汉水，问绢过荆州。
异国有归兴，去乡无客愁。
天寒楚塞雨，月净襄阳秋。
坐见吾道远，令人看白头。','',''),('quantangshi-09907','送史司马赴崔相公幕','岑參','quantangshi','','卷10','峥嵘丞相府，清切凤皇池。
羡尔瑶台鹤，高栖琼树枝。
归飞晴日好，吟弄惠风吹。
正有乘轩乐，初当学舞时。
珍禽在罗网，微命若游丝。
愿托周南羽，相衔溪水湄。','',''),('quantangshi-09908','送严黄门拜御史大夫再镇蜀川兼觐省','岑參','quantangshi','','卷10','授钺辞金殿，承恩恋玉墀。
登坛汉主用，讲德蜀人思。
副相韩安国，黄门向子期。
刀州重入梦，劒阁再题词。
春草连青绶，晴花间赤旗。
山莺朝送酒，江月夜供诗。
许国分忧日，荣亲色养时。
苍生望已久，来去不应迟。','',''),('quantangshi-09909','送郭仆射节制劒南','岑參','quantangshi','','卷10','铁马擐红缨，幡旗出禁城。
明王亲授钺，丞相欲专征。
玉馔天厨送，金杯御酒倾。
劒门乘嶮过，阁道踏空行。
山鸟惊吹笛，江猿看洗兵。
晓云随去阵，夜月逐行营。
南仲今时往，西戎计日平。
将心感知己，万里寄悬旌。','',''),('quantangshi-09910','早秋与诸子登虢州西亭观眺','岑參','quantangshi','','卷10','亭高出鸟外，客到与云齐。
树点千家小，天围万岭低。
残[虹]挂陕北，急雨过关西。
酒榼缘青壁，瓜田傍绿溪。
微官何足道，爱客且相携。
唯有乡园处，依依望不迷。','',''),('quantangshi-09911','佐郡思旧游','岑參','quantangshi','','卷10','幸得趋紫殿，却忆侍丹墀。
史笔众推直，谏书人莫窥。
平生恒自负，垂老此安卑。
