胡笳一曲断人肠，座上相看泪如雨。','',''),('quantangshi-09951','题观楼','岑參','quantangshi','','卷10','荒楼荒井闭空山，关令乘云去不还。
羽盖霓旌何处在，空留药臼向人间。','',''),('quantangshi-09952','草堂村寻罗生不遇','岑參','quantangshi','','卷10','数株溪柳色依依，深巷斜阳暮鸟飞。
门前雪满无人迹，应是先生出未归。','',''),('quantangshi-09953','山房春事二首 一','岑參','quantangshi','','卷10','风恬日暖荡春光，戏蝶游蜂乱入房。
