几日应晴去，孤舟且欲归。','',''),('quantangshi-09971','邺城引','張鼎','quantangshi','','卷10','君不见汉家失统三灵变，魏武争雄六龙战。
荡海吞江制中国，回天运斗应南面。
隐隐都城紫阳开，迢迢分野黄星见。
流年不驻漳河水，明月俄终邺国宴。
文章犹入管弦新，帷座空销狐兔尘。
可惜望陵歌舞处，松风四面暮愁人。','',''),('quantangshi-09972','僧舍小池','張鼎','quantangshi','','卷10','引出白云根，潺潺涨藓痕。
冷光摇砌锡，疎影露枝猿。
净带凋霜叶，香通洗药源。
贝多文字古，宜向此中翻。','',''),('quantangshi-09973','拟古','薛奇童','quantangshi','','卷10','沙尘朝蔽日，失道还相遇。
寒影波上云，秋声月前树。
