下帘弹箜篌，不忍见秋月。','',''),('quantangshi-09976','塞下曲','薛奇童','quantangshi','','卷10','骄虏初南下，烟尘暗国中。
独召李将军，夜开甘泉宫。
一身许明主，万里总元戎。
霜甲卧不暖，夜半闻边风。
胡天早飞雪，荒徼多转蓬。
寒云覆水重，秋气连海空。
金鞍谁家子，上马鸣角弓。
自是幽并客，非论爱立功。','',''),('quantangshi-09977','云中行','薛奇童','quantangshi','','卷10','云中小儿吹金管，向晚因风一川满。
塞北云高心已悲，城南木落肠堪断。
忆昔魏家都此方，凉风观前朝百王。
千门晓映山川色，双阙遥连日月光。
举杯称寿永相保，日夕歌钟彻清昊。
将军汗马百战塲，天子射兽五原草。
寂寞金舆去不归，陵上黄尘满路飞。
河边不语伤流水，川上含情叹落晖。
此时独立无所见，日暮寒风吹客衣。','',''),('quantangshi-09978','楚宫词二首 一','薛奇童','quantangshi','','卷10','禁苑春风起，流莺绕合欢。
玉窗通日气，珠箔卷轻寒。
