艳舞矜新宠，愁容泣旧恩。
不堪深殿里，帘外欲黄昏。','',''),('quantangshi-09980','长孙十一东山春夜见赠','楊諫','quantangshi','','卷10','故人谢城阙，挥手碧云期。
