时平祥不去，寿远节长来。
连吹千家笛，同朝百郡杯。
愿持金殿镜，处处照遗才。','',''),('quantangshi-09992','长门怨','梁鍠','quantangshi','','卷10','妾命何偏薄，君王去不归。
欲令遥见悔，楼上试春衣。
空殿看人入，深宫羡鸟飞。
翻悲因买赋，索镜照空辉。','',''),('quantangshi-09993','美人春卧','梁鍠','quantangshi','','卷10','妾家巫峡阳，罗幌寝兰堂。
