美人姿态里，春色上罗衣。
自爱频开镜，时羞欲掩扉。
不知行路客，遥惹五香归。','',''),('quantangshi-09996','狷氏子','梁鍠','quantangshi','','卷10','杏梁初照日，碧玉后堂开。
忆事临妆笑，春娇满镜台。
含声歌扉举，顾影舞腰回。
别有佳期处，青楼客夜来。','',''),('quantangshi-09997','戏赠歌者','梁鍠','quantangshi','','卷10','白皙歌童子，哀音绝又连。
楚妃临扇学，卢女隔帘传。
晓燕喧喉里，春莺啭舌边。
若逢汉武帝，还是李延年。','',''),('quantangshi-09998','七夕泛舟','梁鍠','quantangshi','','卷10','云端有灵匹，掩映拂妆台。
夜久应摇佩，天高响不来。
片欢秋始展，残梦晓翻催。
却怨填河鹊，留桥又不回。','',''),('quantangshi-09999','崔驸马宅咏画山水扇','梁鍠','quantangshi','','卷10','画扇出秦楼，谁家赠列侯。
小含吴剡县，轻带楚扬州。
揜作山云暮，摇成陇树秋。
坐来传与客，汉水又回流。','',''),('quantangshi-10000','观王美人海图障子','梁鍠','quantangshi','','卷10','宋玉东家女，常怀物外多。
自从图渤海，谁为觅湘娥。
白鹭栖脂粉，赬鲂跃绮罗。
