敛形藏一叶，分响出千花。
坐爱时褰幌，行藏或驻车。
不须应独感，三载已辞家。','',''),('quantangshi-10002','省试方士进恒春草','梁鍠','quantangshi','','卷10','东吴有灵草，生彼剡溪傍。
既乱莓苔色，仍连菡萏香。
掇之称远士，持以奉明王。
北阙颜弥驻，南山寿更长。
金膏徒骋妙，石髓莫矜良。
倘使霑涓滴，还游不死方。','',''),('quantangshi-10003','代征人妻喜夫还','梁鍠','quantangshi','','卷10','征夫走马发渔阳，少妇含娇开洞房。
千日废台还挂镜，数年尘面再新妆。
春风喜出今朝户，明日虚眠昨夜牀。
莫道幽闺书信隔，还衣总是旧时香。','',''),('quantangshi-10004','赠李中华','梁鍠','quantangshi','','卷10','莫向嵩山去，神仙多误人。
不如朝魏阙，天子重贤臣。','',''),('quantangshi-10005','咏木老人','梁鍠','quantangshi','','卷10','刻木牵丝作老翁，鸡皮鹤发与真同。
须臾弄罢寂无事，还似人生一梦中。','',''),('quantangshi-10006','句','梁鍠','quantangshi','','卷10','堂高凭上望，宅广乘车行。','',''),('quantangshi-10007','客中作','杜儼','quantangshi','','卷10','书劒催人不暂闲，洛阳羁旅复秦关。
容颜岁岁愁边改，乡国时时梦里还。','',''),('quantangshi-10008','三月三日曲江侍宴','趙良器','quantangshi','','卷10','圣祖发神谋，灵符叶帝求。
一人光锡命，万国荷时休。
雷解圜丘毕，云需曲水游。
岸花迎步辇，仙仗拥行舟。
睿藻天中降，恩波海外流。
小臣同品物，陪此乐皇猷。','',''),('quantangshi-10009','郑国夫人挽歌词','趙良器','quantangshi','','卷11','淑德延公胄，宜家接帝姻。
桂宫男掌仆，兰殿女升嫔。
恩泽昭前命，盈虚变此辰。
万年今已矣，彤管列何人。','',''),('quantangshi-10010','郡中客舍','黃麟','quantangshi','','卷11','虫响乱啾啾，更人正数筹。
魂归洞庭夜，霜卧洛阳秋。
微月有时隐，长河到晓流。
起来还嘱雁，乡信在吴洲。','',''),('quantangshi-10011','途中口号','郭向','quantangshi','','卷11','抱玉三朝楚，怀书十上秦。
年年洛阳陌，花鸟弄归人。','',''),('quantangshi-10012','题李将军山亭','郭良','quantangshi','','卷11','凤辖将军位，龙门司隶家。
衣冠为隐逸，山水作繁华。
径出重林草，池摇两岸花。
谁知贵公第，亭院有烟霞。','',''),('quantangshi-10013','早行','郭良','quantangshi','','卷11','早行星尚在，数里未天明。
不辨云林色，空闻风水声。
月从山上落，河入斗间横。
渐至重门外，依稀见洛城。','',''),('quantangshi-10014','过故人旧宅','王喬','quantangshi','','卷11','故人轩骑罢归来，旧宅园林闲不开。
唯余挟瑟楼中妇，哭向平生歌舞台。','',''),('quantangshi-10015','关山月','徐九臯','quantangshi','','卷11','玉塞抵长城，金徽暎高阙。
遥心万余里，直望三边月。
霜静影逾悬，露曦光渐没。
思君不可见，空叹将焉歇。','',''),('quantangshi-10016','战城南','徐九臯','quantangshi','','卷11','塞北狂胡旅，城南敌汉围。
巉岩一鼓气，拔利五兵威。
虏骑瞻山哭，王师拓地飞。
不应须宠战，当遂勒金徽。','',''),('quantangshi-10017','咏史','徐九臯','quantangshi','','卷11','亡国秦韩代，荣身刘项年。
金槌击政后，玉斗碎增前。
圣主称三杰，明离保四贤。
已申黄石祭，方慕赤松仙。','',''),('quantangshi-10018','途中览镜','徐九臯','quantangshi','','卷11','四海游长倦，百年愁半侵。
赖窥明镜里，时见丈夫心。','',''),('quantangshi-10019','送部四镇人往单于别知故','徐九臯','quantangshi','','卷11','天下今无事，云中独未宁。
忝驱更戍卒，方远送边庭。
马饮长城水，军占太白星。
国恩行可报，何必守经营。','',''),('quantangshi-10020','松滋江北阻风','閻寬','quantangshi','','卷11','江风久未歇，山雨复相仍。
巨浪天涯起，余寒川上凝。
忧人劳夕惕，乡事惫晨兴。
远听知音骇，诚哉不可陵。','',''),('quantangshi-10021','晓入宜都渚','閻寬','quantangshi','','卷11','问俗周楚甸，川行眇江浔。
兴随晓光发，道会春言深。
回眺佳气象，远怀得山林。
伫应舟楫用，曷务归闲心。','',''),('quantangshi-10022','古意','閻寬','quantangshi','','卷11','庭树发华滋，瑶草复葳蕤。
好鸟飞相从，愁人深此时。
天中有灵匹，日夕嚬蛾眉。
愿逐飘风花，千里入遥帷。
心逝爱不见，空歌悲莫悲。','',''),('quantangshi-10023','春宵览月','閻寬','quantangshi','','卷11','月生东荒外，天云收夕阴。
爱见澄清景，象吾虚白心。
耳目静无哗，神超道性深。
乘兴得至乐，寓言因永吟。','',''),('quantangshi-10024','秋怀','閻寬','quantangshi','','卷11','下帷长日尽，虚馆早凉生。
芳草犹未荐，如何蜻蛚鸣。
秋风已振衣，客去何时归。
为问当途者，宁知心有违。','',''),('quantangshi-10025','和中书侍郎院壁画云','李收','quantangshi','','卷11','粉壁画云成，如能上太清。
影从霄汉发，光照掖垣明。
暎筱多幽趣，临轩得野情。
独思作霖雨，流润及生灵。','',''),('quantangshi-10026','幽情','李收','quantangshi','','卷11','幽人惜春暮，潭上折芳草。
佳期何时还，欲寄千里道。','',''),('quantangshi-10027','怀鲁','程彌綸','quantangshi','','卷11','曲阜国，尼丘山。
周公邈难问，夫子犹启关。
履风雩兮若见，游夏兴兮鲁颜。
天孙天孙，何为今兮学且难，负星明而东游闲闲。','',''),('quantangshi-10028','燕歌行','屈同仙','quantangshi','','卷11','君不见渔阳八月塞草腓，征人相对并思归。
云和朔气连天黑，蓬杂惊沙散野飞。
是时天地阴埃遍，瀚海龙城皆习战。
两军鼓角暗相闻，四面旌旗看不见。
昭君远嫁已年多，戎狄无厌不复和。
汉兵候月秋防塞，胡骑乘冰夜渡河。
河塞东西万余里，地与京华不相似。
燕支山下少春晖，黄沙碛里无流水。
金戈玉剑十年征，红粉青楼多怨情。
厌向殊乡久离别，秋来愁听捣衣声。','',''),('quantangshi-10029','乌江女','屈同仙','quantangshi','','卷11','越艳谁家女，朝游江岸傍。
青春犹未嫁，红粉旧来娼。
锦袖盛朱橘，银钩摘紫房。
见人羞不语，回艇入溪藏。','',''),('quantangshi-10030','昌年宫之作','豆盧復','quantangshi','','卷11','但有离宫处，君王每不居。
旗门芳草合，辇路小槐疎。
殿闭山烟满，窗凝野霭虚。
丰年多望幸，春色待銮舆。','',''),('quantangshi-10031','落第归乡留别长安主人','豆盧復','quantangshi','','卷11','客里愁多不记春，闻莺始叹柳条新。
年年下第东归去，羞见长安旧主人。','',''),('quantangshi-10032','奉试咏青','荆冬倩','quantangshi','','卷11','路辟天光远，春还月道临。
草浓河畔色，槐结路边阴。
未映君王史，先标胄子襟。
经明如可拾，自有致云心。','',''),('quantangshi-10033','观汉水','梁洽','quantangshi','','卷11','发源自嶓冢，东注经襄阳。
一道入溟渤，别流为沧浪。
求思咏游女，投吊悲昭王。
水滨不可问，日暮空汤汤。','',''),('quantangshi-10034','游越溪','鄭紹','quantangshi','','卷11','溪水碧悠悠，猨声断客愁。
渔潭逢钓楫，月浦值孤舟。
访泊随烟火，迷途视斗牛。
今宵越乡意，还取醉忘忧。','',''),('quantangshi-10035','登楼','朱斌','quantangshi','','卷11','白日依山尽，黄河入海流。
欲穷千里目，更上一层楼。','',''),('quantangshi-10036','感寓二首 一','梁德裕','quantangshi','','卷11','彩云呈瑞质，五色发人寰。
独作龙虎状，孤飞天地间。
隐隐临北极，峨峨象南山。
恨在帝乡外，不逢枝叶攀。','',''),('quantangshi-10037','感寓二首 二','梁德裕','quantangshi','','卷11','幽涧生蕙若，幽渚老江蓠。
荣落人不见，芳香徒尔为。
不及绿萍草，生君红莲池。
左右美人弄，朝夕春风吹。
叶洗玉泉水，珠清湛露滋。
心亦愿如此，托君君不知。','',''),('quantangshi-10038','咏谈容娘','常非月','quantangshi','','卷11','举手整花钿，翻身舞锦筵。
马围行处匝，人压看场圆。
歌要齐声和，情教细语传。
不知心大小，容得许多怜。','',''),('quantangshi-10039','览史','張良璞','quantangshi','','卷11','享年八十已，历数穷苍生。
七虎门源上，咆哮关内鸣。
建都用鹑宿，设险因金城。
舜曲烟火起，汾河珠翠明。
海云引天仗，朔雪留边兵。
作孽人怨久，其亡鬼信盈。
素灵感刘季，白马从子婴。
昏虐不务德，百代无芳声。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-10040','奉试冷井诗','孫欣','quantangshi','','卷11','仙闱井初凿，灵液沁成泉。
色湛青苔里，寒凝紫绠边。
铜瓶向影落，玉甃抱虚圆。
永愿调神鼎，尧时泰万年。','',''),('quantangshi-10041','都中闲居','王羨門','quantangshi','','卷11','君王巡海内，北阙下明台。
云物天中少，烟花岁后来。
河从御苑出，山向国门开。
寂寞东京里，空留贾谊才。','',''),('quantangshi-10042','江南弄','芮挺章','quantangshi','','卷11','春江可怜事，最在美人家。
鹦鹉能言鸟，芙蓉巧笑花。
地衔金作埒，水抱玉为沙。
薄晚青丝骑，长鞭赴狭斜。','',''),('quantangshi-10043','少年行','芮挺章','quantangshi','','卷11','任气称张放，衔恩在少年。
玉阶朝就日，金屋夜升天。
轩骑青云际，笙歌绿水边。
建章明月好，留醉伴风烟。','',''),('quantangshi-10044','伊水门','樓頴','quantangshi','','卷11','朝涉伊水门，伊水入门流。
惬心乃成兴，澹然泛孤舟。
霏微傍青霭，容与随白鸥。
竹阴交前浦，柳花媚中洲。
日落阴云生，弥觉兹路幽。
聊以恣所适，此外知何求。','',''),('quantangshi-10045','东郊纳凉忆左威卫李录事收昆季太原崔参军三首 一','樓頴','quantangshi','','卷11','水竹谁家宅，幽庭向苑门。
今知季伦沼，旧是辟疆园。
饥鹭窥鱼静，鸣鸦带子喧。
兴成秪自适，欲白返忘言。','',''),('quantangshi-10046','东郊纳凉忆左威卫李录事收昆季太原崔参军三首 二','樓頴','quantangshi','','卷11','纳凉每选地，近得青门东。
林与缭垣接，池将沁水通。
枝交帝女树，桥映美人虹。
想是忘机者，悠悠在兴中。','',''),('quantangshi-10047','东郊纳凉忆左威卫李录事收昆季太原崔参军三首 三','樓頴','quantangshi','','卷11','林间求适意，池上得清飙。
稍稍斜回檝，时时一度桥。
水光壁际动，山影浪中摇。
不见李元礼，神仙何处要。','',''),('quantangshi-10048','西施石','樓頴','quantangshi','','卷11','西施昔日浣纱津，石上青苔思杀人。
一去姑苏不复返，岸旁桃李为谁春。','',''),('quantangshi-10049','江南行','李康成','quantangshi','','卷11','杨柳青青莺欲啼，风光摇荡绿苹齐，金阴城头日色低。
日色低，情难极，水中凫鹥双比翼。','',''),('quantangshi-10050','采莲曲','李康成','quantangshi','','卷11','采莲去，月没春江曙。
翠钿红袖水中央，青荷莲子杂衣香，云起风生归路长。
归路长，那得久。
各回船，两摇手。','',''),('quantangshi-10051','玉华仙子歌','李康成','quantangshi','','卷11','紫阳仙子名玉华，珠盘承露饵丹砂。
转态凝情五云里，娇颜千岁芙蓉花。
紫阳彩女矜无数，遥见玉华皆掩嫭。
高堂初日不成妍，洛渚流风徒自怜。
璇阶霓绮阁，碧题霜罗幕。
仙娥桂树长自春，王母桃花未尝落。
上元夫人宾上清，深宫寂历厌层城。
解佩空怜郑交甫，吹箫不逐许飞琼。
溶溶紫庭步，渺渺瀛台路。
兰陵贵士谢相逢，济北风生尚回顾。
沧洲傲吏爱金丹，清心回望云之端。
羽盖霓裳一相识，传情写念长无极。
长无极，永相随。
攀霄历金阙，弄影下瑶池。
夕宿紫府云母帐，朝餐玄圃昆仑芝。
不学兰香中道绝，却教青鸟报相思。','',''),('quantangshi-10052','自君之出矣','李康成','quantangshi','','卷11','自君之出矣，弦吹绝无声。
思君如百草，撩乱逐春生。','',''),('quantangshi-10053','句','李康成','quantangshi','','卷11','因缘苟会合，万里犹同乡。
运命尚不谐，隔壁无津梁。','',''),('quantangshi-10054','时兴','楊賁','quantangshi','','卷11','贵人昔未贵，咸愿顾寒微。
及自登枢要，何曾问布衣。
平明登紫阁，日晏下彤闱。
扰扰路傍子，无劳歌是非。','',''),('quantangshi-10055','咏石季伦','李清','quantangshi','','卷11','金谷繁华石季伦，只能谋富不谋身。
当时纵与绿珠去，犹有无穷歌舞人。','',''),('quantangshi-10056','鹤警露','陳季','quantangshi','','卷11','南国商飙动，东臯野鹤鸣。
溪松寒暂宿，露草滴还惊。
欲有高飞意，空闻召侣情。
风间传藻质，月下引清声。
未假抟扶势，焉知羽翼轻。
吾君开太液，愿得应皇明。','',''),('quantangshi-10057','湘灵鼓瑟','陳季','quantangshi','','卷11','神女泛瑶瑟，古祠严野亭。
楚云来泱漭，湘水助清泠。
妙指微幽契，繁声入杳冥。
一弹新月白，数曲暮山青。
调苦荆人怨，时遥帝子灵。
遗音如可赏，试奏为君听。','',''),('quantangshi-10058','湘灵鼓瑟','王邕','quantangshi','','卷11','宝瑟和琴韵，灵妃应乐章。
依稀闻促柱，仿髴梦新妆。
波外声初发，风前曲正长。
凄清和万籁，断续绕三湘。
转觉云山迥，空怀杜若芳。
诚能传此意，雅奏在宫商。','',''),('quantangshi-10059','嵩山望幸','王邕','quantangshi','','卷11','峻极位何崇，方知造化功。
降灵逢圣主，望幸表维嵩。
隐映连青壁，嵯峨向碧空。
象车因叶瑞，龙驾愿升中。
万岁声长在，千岩气转雄。
东都歌盛事，西笑伫皇风。','',''),('quantangshi-10060','湘灵鼓瑟','莊若訥','quantangshi','','卷11','帝子鸣金瑟，余声自抑扬。
悲风丝上断，流水曲中长。
出没游鱼听，逶迤彩凤翔。
微音时扣征，雅韵乍含商。
神理诚难测，幽情讵可量。
至今闻古调，应恨滞三湘。','',''),('quantangshi-10061','湘灵鼓瑟','魏璀','quantangshi','','卷11','瑶瑟多哀怨，朱弦且莫听。
扁舟三楚客，藂竹二妃灵。
淅沥闻余响，依稀欲辨形。
柱间寒水碧，曲里暮山青。
良马悲衔草，游鱼思绕萍。
知音若相遇，终不滞南溟。','',''),('quantangshi-10062','怀素上人草书歌','王𩔪','quantangshi','','卷11','衡阳双峡插天峻，青壁巉巉万余仞。
此中灵秀众所知，草书独有怀素奇。
怀素身长五尺四，嚼汤诵呪吁可畏。
铜瓶锡杖倚闲庭，斑管秋毫多逸意。
或粉壁，或彩牋，蒲葵绢素何相鲜。
忽作风驰如电掣，更点飞花兼散雪。
寒猨饮水撼枯藤，壮士拔山伸劲铁。
君不见张芝昔日称独贤，君不见近日张旭为老颠。
二公绝艺人所惜，怀素传之得真迹。
峥嵘蹙出海上山，突兀状成湖畔石。
一纵又一横，一欹又一倾。
临江不羡飞帆势，下笔长为骤雨声。
我牧此州喜相识，又见草书多慧力。
怀素怀素不可得，开卷临池转相忆。','',''),('quantangshi-10063','怀素上人草书歌','竇冀','quantangshi','','卷11','狂僧挥翰狂且逸，独任天机摧格律。
龙虎惭因点画生，雷霆却避锋铓疾。
鱼牋娟素岂不贵，只嫌局促儿童戏。
粉壁长廊数十间，兴来小豁胸襟气。
长幼集，贤豪至，枕糟藉麴犹半醉。
忽然绝叫三五声，满壁纵横千万字。
吴兴张老尔莫颠，叶县公孙我何谓。
如熊如罴不足比，如虺如蛇不足拟。
涵物为动鬼神泣，狂风入林花乱起。
殊形怪状不易说，就中惊燥尤枯绝。
边风杀气同惨烈，崩槎卧木争摧折。
塞草遥飞大漠霜，胡天乱下阴山雪。
偏看能事转新奇，郡守王公同赋诗。
枯藤劲铁愧三舍，骤雨寒猨惊一时。
此生绝艺人莫测，假此常为护持力。
连城之璧不可量，五百年知草圣当。','',''),('quantangshi-10064','怀素上人草书歌','魯收','quantangshi','','卷11','吾观文士多利用，笔精墨妙诚堪重。
身上艺能无不通，就中草圣最天纵。
有时兴酣发神机，抽毫点墨纵横挥。
风声吼烈随手起，龙蛇迸落空壁飞。
连拂数行势不绝，藤悬查蹙生奇节。
划然放纵惊云涛，或时顿挫萦豪发。
自言转腕无所拘，大笑羲之用阵图。
狂来纸尽势不尽，投笔抗声连叫呼。
信知鬼神助此道，墨池未尽书已好。
行路谈君口不容，满堂观者空绝倒。
所恨时人多笑声，唯知贱实翻贵名。
观尔向来三五字，颠奇何谢张先生。','',''),('quantangshi-10065','怀素上人草书歌','朱逵','quantangshi','','卷11','几年出家通宿命，一朝却忆临池圣。
转腕摧锋增崛崎，秋毫茧纸常相随。
衡阳客舍来相访，连饮百杯神转王。
忽闻风里度飞泉，纸落纷纷如跕鸢。
形容脱略真如助，心思周游在何处。
笔下惟看激电流，字成只畏盘龙去。
怪状崩腾若转蓬，飞丝历乱如回风。
长松老死倚云壁，蹙浪相翻惊海鸿。
于今年少尚如此，历覩远代无伦比。
妙绝当动鬼神泣，崔蔡幽魂更心死。','',''),('quantangshi-10066','题怀素上人草书','許瑤','quantangshi','','卷11','志在新奇无定则，古瘦漓纚半无墨。
醉来信手两三行，醒后却书书不得。','',''),('quantangshi-10067','祀风师乐章 迎神','包佶','quantangshi','','卷11','太皞御气，句芒肇功。
苍龙青旗，爰候祥风。
律以和应，神以感通。
鼎俎修蠁，时惟礼崇。','',''),('quantangshi-10068','祀风师乐章 奠币登歌','包佶','quantangshi','','卷11','旨酒告洁，青苹应候。
礼陈瑶币，乐献金奏。
弹弦自昔，解冻惟旧。
仰瞻肸蠁，羣祥来凑。','',''),('quantangshi-10069','祀风师乐章 迎俎酌献','包佶','quantangshi','','卷11','德盛昭临，迎拜巽方。
爰候发生，式荐馨香。
酌醴具举，工歌再扬。
神歆入律，恩降百祥。','',''),('quantangshi-10070','祀风师乐章 亚献终献','包佶','quantangshi','','卷11','膋芗备，玉帛陈。
风动物，乐感神。
三献终，百神臻。
草木荣，天下春。','',''),('quantangshi-10071','祀风师乐章 送神','包佶','quantangshi','','卷11','微穆敷华能应节，飘扬发彩宜行庆。
送迎灵驾神心飨，跪拜灵坛礼容盛。
气和草木发萌芽，德畅禽鱼遂翔泳。
永望翠盖逐流云，自兹率土调春令。','',''),('quantangshi-10072','祀雨师乐章 迎神','包佶','quantangshi','','卷11','陟降左右，诚达幽圆。
作解之功，乐惟有年。
云軿戾止，洒雾飘烟。
惟馨展礼，爰列豆笾。','',''),('quantangshi-10073','祀雨师乐章 奠币登歌','包佶','quantangshi','','卷11','岁正朱明，礼布玄制。
惟乐能感，与神合契。
阴雾离披，灵驭摇裔。
膏泽之庆，期于稔岁。','',''),('quantangshi-10074','祀雨师乐章 迎俎酌献','包佶','quantangshi','','卷11','阳开幽蛰，躬奉郁鬯。
礼备节应，震来灵降。
动植求声，飞沈允望。
时康气茂，惟神之贶。','',''),('quantangshi-10075','祀雨师乐章 亚献终献','包佶','quantangshi','','卷11','奠既备，献将终。
神行令，瑞飞空。
迎干德，祈岁功。
乘烟燎，俨从风。','',''),('quantangshi-10076','祀雨师乐章 送神','包佶','quantangshi','','卷11','整驾升车望寥廓，垂阴荐祉荡昏氛。
飨时灵贶僾如在，乐罢余声遥可闻。
饮福陈诚礼容备，撤俎终献曙光分。
跪拜临坛结空想，年年应节候油云。','',''),('quantangshi-10077','答窦援遗卧病见寄','包佶','quantangshi','','卷11','今春扶病移沧海，几度承恩对白花。
送客屡闻帘外鹊，销愁已辨酒中虵。
瓶开枸杞悬泉水，鼎炼芙蓉伏火砂。
误入尘埃牵吏役，羞将簿领到君家。','',''),('quantangshi-10078','对酒赠故人','包佶','quantangshi','','卷11','扶起离披菊，霜轻喜重开。
醉中惊老去，笑里觉愁来。
月送人无尽，风吹浪不回。
感时将有寄，诗思涩难裁。','',''),('quantangshi-10079','同李吏部伏日口号呈元庶子路中丞','包佶','quantangshi','','卷11','火炎逢六月，金伏过三庚。
几度衣裳汗，谁家枕簟清。
颁冰无下位，裁扇有高名。
吏部还开瓮，殷勤二客情。','',''),('quantangshi-10080','岭下卧疾寄刘长卿员外','包佶','quantangshi','','卷11','唯有贫兼病，能令亲爱疎。
岁时供放逐，身世付空虚。
胫弱秋添絮，头风晓废梳。
波澜喧众口，藜藿静吾庐。
丧马思开卦，占鸮嬾发书。
十年江海隔，离恨子知予。','',''),('quantangshi-10081','戏题诸判官厅壁','包佶','quantangshi','','卷11','六十老翁无所取，二三君子不相遗。
愿留今日交欢意，直到隳官谢病时。','',''),('quantangshi-10082','酬兵部李侍郎晚过东厅之作','包佶','quantangshi','','卷11','酒礼慙先祭，刑书已旷官。
诏驰黄纸速，身在绛纱安。
圣位登堂静，生徒跪席寒。
庭槐暂摇落，幸为入春看。','',''),('quantangshi-10083','昭德皇后挽歌词','包佶','quantangshi','','卷11','西汜驰晖过，东园别路长。
岁华唯陇柏，春事罢公桑。
龟兆开泉户，禽巢闭画梁。
更闻哀礼过，明诏制心丧。','',''),('quantangshi-10084','秋日过徐氏园林','包佶','quantangshi','','卷11','回塘分越水，古树积吴烟。
扫竹催铺席，垂萝待系船。
鸟窥新罅栗，龟上半攲莲。
屡入忘归地，长嗟俗事牵。','',''),('quantangshi-10085','双山过信公所居','包佶','quantangshi','','卷11','遥礼前朝塔，微闻后夜钟。
人间第四祖，云里一双峰。
积雨封苔径，多年亚石松。
传心不传法，谁可继高踪。','',''),('quantangshi-10086','尚书宗兄使过诗以奉献','包佶','quantangshi','','卷11','洛下交亲满，归闲意有余。
翻嫌旧坐宅，却驾所悬车。
腹饱山僧供，头轻侍婢梳。
上官唯揖让，半禄代耕鉏。
雨散三秋别，风传一字书。
胜游如可继，还欲并园庐。','',''),('quantangshi-10087','抱疾谢李吏部赠诃黎勒叶','包佶','quantangshi','','卷11','一叶生西徼，赍来上海查。
岁时经水府，根本别天涯。
方士真难见，商胡辄自夸。
此香同异域，看色胜仙家。
茗饮暂调气，梧丸喜伐邪。
幸蒙祛老疾，深愿驻韶华。','',''),('quantangshi-10088','奉和柳相公中书言怀','包佶','quantangshi','','卷11','运筹时所贵，前席礼偏深。
羸驾归贫宅，攲冠出禁林。
凤巢方得地，牛喘最关心。
雅望期三入，东山未可寻。','',''),('quantangshi-10089','客自江南话过亡友朱司议故宅','包佶','quantangshi','','卷11','交臂多相共，风流忆此人。
海翻移里巷，书蠹积埃尘。
奉佛栖禅久，辞官上疏频。
故来分半宅，惟是旧交亲。','',''),('quantangshi-10090','酬于侍郎湖南见寄十四韵','包佶','quantangshi','','卷11','桂岭千崖断，湘流一派通。
长沙今贾傅，东海旧于公。
章甫经殊俗，离骚继雅风。
金闺文作字，玉匣气成虹。
翰墨时招侣，丹青夙在公。
主恩留左掖，人望积南宫。
巧拙循名异，浮沈顾位同。
九迁归上略，三已契愚衷。
责谢庭中吏，悲宽塞上翁。
楚材欣有适，燕石愧无功。
山晓重岚外，林春苦雾中。
雪花翻海鹤，波影倒江枫。
去札频逢信，回帆早挂空。
避贤方有日，非敢爱微躬。','',''),('quantangshi-10091','朝拜元陵','包佶','quantangshi','','卷11','宫前石马对中峰，云里金铺闭几重。
不见露盘迎晓日，唯闻木斧扣寒松。','',''),('quantangshi-10092','发襄阳后却寄公安人','包佶','quantangshi','','卷11','挥泪送回人，将书报所亲。
晚年多疾病，中路有风尘。
王粲频征楚，君恩许入秦。
还同星火去，马上别江春。','',''),('quantangshi-10093','立春后休沐','包佶','quantangshi','','卷11','心与青春背，新年亦掩扉。
渐穷无相学，惟避不材讥。
积病攻难愈，衔恩报转微。
定知书课日，优诏许辞归。','',''),('quantangshi-10094','宿庐山赠白鹤观刘尊师','包佶','quantangshi','','卷11','苍苍五老雾中坛，杳杳三山洞里官。
手护昆仑象牙简，心推霹雳枣枝盘。
春飞雪粉如毫润，晓漱琼膏冰齿寒。
渐恨流年筋力少，惟思露冕事星冠。','',''),('quantangshi-10095','观壁卢九想图','包佶','quantangshi','','卷11','一世荣枯无异同，百年哀乐又归空。
夜阑鸟鹊相争处，林下真僧在定中。','',''),('quantangshi-10096','送日本国聘贺使晁巨卿东归','包佶','quantangshi','','卷11','上才生下国，东海是西邻。
九译蕃君使，千年圣主臣。
野情偏得礼，木性本含真。
锦帆乘风转，金装照地新。
孤城开蜃阁，晓日上朱轮。
早识来朝岁，涂山玉帛均。','',''),('quantangshi-10097','顾着作宅赋诗','包佶','quantangshi','','卷11','几年江海烟霞，乘醉一到京华。
已觉不嫌羊酪，谁能长守兔罝。
脱巾偏招相国，逢竹便认吾家。
各在芸台阁里，烦君日日登车。','',''),('quantangshi-10098','近获风痹之疾题寄所怀','包佶','quantangshi','','卷11','病夫将已矣，无可答君恩。
衾枕同羇客，图书委外孙。
久来从吏道，常欲奉空门。
疾走机先息，攲行力渐烦。
无医能却老，有变是游魂。
鸟宿还依伴，蓬飘莫问根。
寓形齐指马，观境制心猨。
唯借南荣地，清晨暂负喧。','',''),('quantangshi-10099','奉和常阁老晚秋集贤院即事寄赠徐薛二侍郎','包佶','quantangshi','','卷11','祕殿掖垣西，书楼苑树齐。
秋烟凝缥帙，晓色上璇题。
门接承明近，池连太液低。
疎钟文马驻，繁叶彩禽栖。
职美纶江綍，荣深组及圭。
九霄偏眷顾，三事早提携。
对案临青玉，窥书捧紫泥。
始欢新遇重，还惜旧游暌。
左宦登吴岫，分家渡越溪。
赋中频叹鵩，卜处几听鸡。
望阙应多恋，临津不用迷。
柏梁思和曲，朝夕候金闺。','',''),('quantangshi-10100','酬顾况见寄','包佶','quantangshi','','卷11','于越城边枫叶高，楚人书里寄离骚。
寒江鸂鶒思俦侣，岁岁临流刷羽毛。','',''),('quantangshi-10101','岁日作','包佶','quantangshi','','卷11','更劳今日春风至，枯树无枝可寄花。
览镜唯看飘乱发，临风谁为驻浮槎。','',''),('quantangshi-10102','元日观百僚朝会','包佶','quantangshi','','卷11','万国贺唐尧，清晨会百僚。
花冠萧相府，绣服霍嫖姚。
寿色凝丹槛，欢声彻九霄。
御炉分兽炭，仙管弄云韶。
日照金觞动，风吹玉佩摇。
都城献赋者，不得共趋朝。','',''),('quantangshi-10103','再过金陵','包佶','quantangshi','','卷11','玉树歌终王气收，雁行高送石城秋。
江山不管兴亡事，一任斜阳伴客愁。','',''),('quantangshi-10104','寄杨侍御','包佶','quantangshi','','卷11','一官何幸得同时，十载无媒独见遗。
今日不论腰下组，请君看取鬓边丝。','',''),('quantangshi-10105','江上曲','李嘉祐','quantangshi','','卷11','江心澹澹芙蓉花，江口蛾眉独浣纱。
可怜应是阳台女，对坐鹭鸶娇不语。
掩面羞看北地人，回身忽作空山语。
苍梧秋色不堪论，千载依依帝子魂。
君看峰上斑斑竹，尽是湘妃泣泪痕。','',''),('quantangshi-10106','伤吴中','李嘉祐','quantangshi','','卷11','馆娃宫中春已归，阖闾城头莺已飞。
复见花开人又老，横塘寂寂柳依依。
忆昔吴王在宫阙，馆娃满眼看花发。
舞袖朝欺陌上春，歌声夜怨江边月。
古来人事亦犹今，莫厌清觞与绿琴。
独向西山聊一笑，白云芳草自知心。','',''),('quantangshi-10107','夜闻江南人家赛神因题即事','李嘉祐','quantangshi','','卷11','南方淫祀古风俗，楚妪解唱迎神曲。
枪枪铜鼓芦叶深，寂寂琼筵江水绿。
雨过风清洲渚闲，椒浆醉尽迎神还。
帝女凌空下湘岸，番君隔浦向尧山。
月隐回塘犹自舞，一门依倚神之祜。
韩康灵药不复求，扁鹊医方曾莫覩。
逐客临江空自悲，月明流水无已时。
听此迎神送神曲，携觞欲吊屈原祠。','',''),('quantangshi-10108','古兴','李嘉祐','quantangshi','','卷11','十五小家女，双鬟人不如。
蛾眉暂一见，可直千金余。
自从得向蓬莱里，出入金舆乘玉趾。
梧桐树上春鸦鸣，晓伴君王犹未起。
莫道君恩长不休，婕妤团扇苦悲秋。
君看魏帝邺都里，惟有铜台漳水流。','',''),('quantangshi-10109','杂兴','李嘉祐','quantangshi','','卷11','花间昔日黄鹂啭，妾向青楼已生怨。
花落黄鹂不复来，妾老君心亦应变。
君心比妾心，妾意旧来深。
一别十年无尺素，归时莫赠路傍金。','',''),('quantangshi-10110','送韦邕少府归钟山','李嘉祐','quantangshi','','卷11','祈门官罢后，负笈向桃源。
万卷长开帙，千峰不闭门。
绿杨垂野渡，黄鸟傍山村。
念尔能高枕，丹墀会一论。','',''),('quantangshi-10111','送卢员外往饶州','李嘉祐','quantangshi','','卷11','为郎复典郡，锦帐映朱轮。
露冕随龙节，停桡得水人。
早霜芦叶变，寒雨石榴新。
莫怪谙风土，三年作逐臣。','',''),('quantangshi-10112','送裴五归京口','李嘉祐','quantangshi','','卷11','君罢江西日，家贫为一官。
还归五陵去，只向远峰看。
暮色催人别，秋风待雨寒。
遥知到三径，唯有菊花残。','',''),('quantangshi-10113','送严维归越州','李嘉祐','quantangshi','','卷11','艰难只用武，归向淛河东。
松雪千山暮，林泉一水通。
乡心缘绿草，野思看青枫。
春日偏相忆，裁书寄剡中。','',''),('quantangshi-10114','送杜士瞻楚州觐省','李嘉祐','quantangshi','','卷11','风流与才思，俱似晋时人。
淮月归心促，江花入兴新。
云深沧海暮，柳暗白田春。
共道官犹小，怜君孝养亲。','',''),('quantangshi-10115','送裴宣城上元所居','李嘉祐','quantangshi','','卷11','水流过海稀，尔去换春衣。
泪向槟榔尽，身随鸿雁归。
草思晴后发，花怨雨中飞。
想到金陵渚，酣歌对落晖。','',''),('quantangshi-10116','留别毗陵诸公','李嘉祐','quantangshi','','卷11','久作涔阳令，丹墀忽再还。
凄凉辞泽国，离乱到乡山。
北固滩声满，南徐草色闲。
知心从此别，相忆鬓毛斑。','',''),('quantangshi-10117','送独孤拾遗先辈先赴上都','李嘉祐','quantangshi','','卷11','行春日已晓，桂檝逐寒烟。
转曲遥峰出，看涛极浦连。
入京当献赋，封事更闻天。
日日趋黄阁，应忘云海边。','',''),('quantangshi-10118','常州韦郎中泛舟见饯','李嘉祐','quantangshi','','卷11','主人冯轼贵，送客泛舟稀。
逼岸随芳草，回桡背落晖。
映花双节驻，临水伯劳飞。
醉与羣公狎，春塘露冕归。','',''),('quantangshi-10119','送崔侍御入朝','李嘉祐','quantangshi','','卷11','十年犹执宪，万里独归春。
旧国逢芳草，青云见故人。
潘郎今发白，陶令本家贫。
相送临京口，停桡泪满巾。','',''),('quantangshi-10120','送岳州司马弟之任','李嘉祐','quantangshi','','卷11','岳阳天水外，念尔一帆过。
野墅人烟逈，山城雁影多。
有时巫峡色，终日洞庭波。
丞相今为郡，应无劳者歌。','',''),('quantangshi-10121','裴侍御见赠斑竹杖','李嘉祐','quantangshi','','卷11','骚人夸竹杖，赠我意何深。
万点湘妃泪，三年贾谊心。
愿持终白首，谁道贵黄金。
他日归愚谷，偏宜绿绮琴。','',''),('quantangshi-10122','送张观归袁州','李嘉祐','quantangshi','','卷11','羡尔湘东去，烟花尚可亲。
绿芳深映鸟，远岫递迎人。
饥狖啼初日，残莺惜暮春。
遥怜谢客兴，佳句又应新。','',''),('quantangshi-10123','冬夜饶州使堂饯相公五叔赴歙州','李嘉祐','quantangshi','','卷11','丞相过邦牧，清弦送羽觞。
高情同客醉，子夜为人长。
斜汉这过斗，寒云正护霜。
新安江自绿，明主待惟良。','',''),('quantangshi-10124','蒋山开善寺','李嘉祐','quantangshi','','卷11','山殿秋云里，香烟出翠微。
客寻朝磬至，僧背夕阳归。
下界千门在，前朝万事非。
看心兼送目，葭菼自依依。','',''),('quantangshi-10125','晚发江宁道中呈严维','李嘉祐','quantangshi','','卷11','惆怅遥江路，萧条落日过。
蝉鸣独树急，鸦向古城多。
转曲随青嶂，因高见白波。
潘生秋径草，严子意如何。','',''),('quantangshi-10126','句容县东青阳馆作','李嘉祐','quantangshi','','卷11','句曲千峰暮，归人向远烟。
风摇近水叶，云护欲晴天。
夕照留山馆，秋光落草田。
征途傍斜日，一骑独翩翩。','',''),('quantangshi-10127','晚春宴无锡蔡明府西亭','李嘉祐','quantangshi','','卷11','茅檐闲寂寂，无事觉人和。
井近时浇圃，城低下见河。
兴缘芳草积，情向远峰多。
别日归吴地，停桡更一过。','',''),('quantangshi-10128','送王端赴朝','李嘉祐','quantangshi','','卷11','君承明主意，日日上丹墀。
东阁论兵后，南宫草奏期。
人稀傍河处，槐暗入关时。
独遣吴州客，平陵结梦思。','',''),('quantangshi-10129','送王正字山寺读书','李嘉祐','quantangshi','','卷11','欲究先儒教，还过支遁居。
山堦闲听法，竹迳独看书。
向日荷新卷，迎秋柳半疎。
风流有佳句，不似带经锄。','',''),('quantangshi-10130','送房明府罢长宁令湖州客舍','李嘉祐','quantangshi','','卷11','君为万里宰，恩及五湖人。
未满先求退，归闲不厌贫。
远峰晴更近，残柳雨还新。
要自趋丹陛，明年鸡树亲。','',''),('quantangshi-10131','咏萤','李嘉祐','quantangshi','','卷11','映水光难定，凌虚体自轻。
夜风吹不灭，秋露洗还明。
向烛仍分焰，投书更有情。
犹将流乱影，来此傍檐楹。','',''),('quantangshi-10132','送李中丞杨判官','李嘉祐','quantangshi','','卷11','射策名先着，论兵气自雄。
能全季布诺，不道鲁连功。
流水蒹葭外，诸山睥睨中。
别君秋日晚，回首夕阳空。','',''),('quantangshi-10133','至七里滩作','李嘉祐','quantangshi','','卷11','迁客投于越，临江泪满衣。
独随流水远，转觉故人稀。
万木迎秋序，千峰驻晚晖。
行舟犹未已，惆怅暮潮归。','',''),('quantangshi-10134','南浦渡口','李嘉祐','quantangshi','','卷11','寂寞横塘路，新篁覆水低。
东风潮信满，时雨稻秔齐。
寡妇共租税，渔人逐鼓鼙。
慙无卓鲁术，解印谢黔黎。','',''),('quantangshi-10135','暮秋迁客增思寄京华','李嘉祐','quantangshi','','卷11','宋玉怨三秋，张衡复四愁。
思乡雁北至，欲别水东流。
倚树看黄叶，逢人诉白头。
佳期不可失，落日自登楼。','',''),('quantangshi-10136','送苏修往上饶','李嘉祐','quantangshi','','卷11','爱尔无羁束，云山恣意过。
一身随远岫，孤棹任轻波。
世事关心少，渔家寄宿多。
芦花泊舟处，江月奈人何。','',''),('quantangshi-10137','题王十九茆堂','李嘉祐','quantangshi','','卷11','满庭多种药，入里作山家。
终日能留客，凌寒亦对花。
海鸥过竹屿，门柳拂江沙。
知尔卑栖意，题诗美白华。','',''),('quantangshi-10138','送弘志上人归湖州','李嘉祐','quantangshi','','卷11','山林唯幽静，行住不妨禅。
高月穿松迳，残阳过水田。
诗从宿世悟，法为本师传。
能使南人敬，修持香火缘。','',''),('quantangshi-10139','送陆士伦宰义兴','李嘉祐','quantangshi','','卷11','阳羡兰陵近，高城带水闲。
浅流通野寺，绿茗盖春山。
长吏多愁罢，游人讵肯还。
知君日清净，无事掩重关。','',''),('quantangshi-10140','和张舍人中书宿直','李嘉祐','quantangshi','','卷11','汉主留才子，春城直紫微。
对花阊阖静，过竹吏人稀。
裁诏催添烛，将朝欲更衣。
玉堂宜岁久，且莫厌彤闱。','',''),('quantangshi-10141','司勋王郎中宅送韦九郎中往濠州','李嘉祐','quantangshi','','卷11','怜尔因同舍，看书似外家。
出关逢落叶，傍水见寒花。
送远添秋思，将衰恋岁华。
清淮倍相忆，回首莫令赊。','',''),('quantangshi-10142','晚春送吉校书归楚州','李嘉祐','quantangshi','','卷11','诗人饶楚思，淮上及春归。
旧浦菱花发，闲门柳絮飞。
高名乡曲重，少事道流稀。
定向渔家醉，残阳卧钓矶。','',''),('quantangshi-10143','送严二擢第东归','李嘉祐','quantangshi','','卷11','隳官就宾荐，时辈讵争先。
盛业推儒行，高科独少年。
迎秋见衰叶，余照逐鸣蝉。
旧里三峰下，开门古县前。','',''),('quantangshi-10144','送冷朝阳及第东归江宁','李嘉祐','quantangshi','','卷11','高第由佳句，诸生似者稀。
长安带酒别，建业候潮归。
稚子欢迎棹，隣人为扫扉。
含情过旧浦，鸥鸟亦依依。','',''),('quantangshi-10145','送越州辛法曹之任','李嘉祐','quantangshi','','卷11','但能一官适，莫羡五侯尊。
山色垂趋府，潮声自到门。
缘塘剡溪路，映竹五湖村。
王谢登临处，依依今尚存。','',''),('quantangshi-10146','送樊兵曹潭州谒韦大夫','李嘉祐','quantangshi','','卷11','塞鸿归欲尽，北客始辞春。
零桂虽逢竹，湘川少见人。
江花铺浅水，山木暗残春。
修刺辕门里，多怜尔为亲。','',''),('quantangshi-10147','送杜御史还广陵','李嘉祐','quantangshi','','卷11','慙君从弱岁，顾我比诸昆。
同事元戎久，俱承国士恩。
随莺过淮水，看柳向辕门。
草色金陵岸，思心那可论。','',''),('quantangshi-10148','送兖州杜别驾之任','李嘉祐','quantangshi','','卷11','停车邀别乘，促轸奏胡笳。
若见楚山暮，因愁浙水赊。
河堤经浅草，村径历繁花。
更有堪悲处，梁城春日斜。','',''),('quantangshi-10149','题裴十六少卿东亭','李嘉祐','quantangshi','','卷11','平津旧东阁，深巷见南山。
卷箔岚烟润，遮牕竹影闲。
倾茶兼落帽，恋客不开关。
斜照窥帘外，川禽时往还。','',''),('quantangshi-10150','同皇甫侍御题荐福寺一公房','李嘉祐','quantangshi','','卷11','虚室独焚香，林空静磬长。
闲窥数竿竹，老在一绳牀。
啜茗翻真偈，然灯继夕阳。
人归远相送，步履出回廊。','',''),('quantangshi-10151','送从侄端之东都','李嘉祐','quantangshi','','卷11','虏近人行少，怜君独出城。
故关逢落叶，寒日逐徂征。
闻笛添归思，看山惬野情。
皇华今绝少，龙頟也相迎。','',''),('quantangshi-10152','送王谏议充东都留守判官','李嘉祐','quantangshi','','卷11','时称谢康乐，别事汉平津。
衰柳寒关道，高车左掖臣。
背河见北雁，到洛问东人。
忆昔游金谷，相看华发新。','',''),('quantangshi-10153','和都官苗员外秋夜省直对雨简诸知己','李嘉祐','quantangshi','','卷11','多雨南宫夜，仙郎寓直时。
漏长丹凤阙，秋冷白云司。
萤影侵堦乱，鸿声出苑迟。
萧条人吏散，小谢有新诗。','',''),('quantangshi-10154','送从弟归河朔','李嘉祐','quantangshi','','卷11','故乡那可到，令弟独能归。
诸将矜旄节，何人重布衣。
空城流水在，荒泽旧村稀。
秋日平原路，虫鸣桑叶飞。','',''),('quantangshi-10155','送崔夷甫员外和蕃','李嘉祐','quantangshi','','卷11','君过湟中去，寻源未是赊。
经春逢白草，尽日度黄沙。
双节行为伴，孤烽到似家。
和戎非用武，不学李轻车。','',''),('quantangshi-10156','春日长安送从弟尉吴县','李嘉祐','quantangshi','','卷11','春愁能浩荡，送别又如何。
人向吴台远，莺飞汉苑多。
见花羞白发，因尔忆沧波。
好是神仙尉，前贤亦未过。','',''),('quantangshi-10157','元日无衣冠入朝寄皇甫拾遗冉从弟补阙纾','李嘉祐','quantangshi','','卷11','伏奏随廉使，周行外冗员。
白髭空受岁，丹陛不朝天。
秉烛千官去，垂帘一室眠。
羡君青琐里，并冕入炉烟。','',''),('quantangshi-10158','和韩郎中扬子津翫雪寄严维','李嘉祐','quantangshi','','卷11','雪深扬子岸，看柳尽成梅。
山色潜知近，潮声只听来。
夜禽惊晓散，春物受寒催。
粉署生新兴，瑶华寄上才。','',''),('quantangshi-10159','送王牧往吉州谒王使君叔','李嘉祐','quantangshi','','卷11','细草绿汀洲，王孙耐薄游。
年华初冠带，文体旧弓裘。
野渡花争发，春塘水乱流。
使君怜小阮，应念倚门愁。','',''),('quantangshi-10160','广陵送林宰','李嘉祐','quantangshi','','卷11','清政过前哲，香名达至尊。
明通汉家籍，重识府公恩。
春景生云物，风潮歛雪痕。
长吟策羸马，青楚入关门。','',''),('quantangshi-10161','赠卫南长官赴任','李嘉祐','quantangshi','','卷11','吏曹难茂宰，主意念疲人。
更事文犀节，还过白马津。
云间辞北阙，树里出西秦。
为报陶明府，裁书莫厌贫。','',''),('quantangshi-10162','自常州还江阴途中作','李嘉祐','quantangshi','','卷11','处处空篱落，江村不忍看。
无人花色惨，多雨鸟声寒。
黄霸初临郡，陶潜未罢官。
乘春务征伐，谁肯问凋残。','',''),('quantangshi-10163','润州杨别驾宅送蒋九侍御收兵归扬州','李嘉祐','quantangshi','','卷11','沴气清金虎，兵威壮铁冠。
扬旌川色暗，吹角水风寒。
人对辎軿醉，花垂睥睨残。
羡归丞相阁，空望旧门栏。','',''),('quantangshi-10164','仲夏江阴官舍寄裴明府','李嘉祐','quantangshi','','卷11','万室边江次，孤城对海安。
朝霞晴作雨，湿气晚生寒。
苔色侵衣桁，潮痕上井栏。
题诗招茂宰，思尔欲辞官。','',''),('quantangshi-10165','送夏侯审参军游江东','李嘉祐','quantangshi','','卷11','袖中多丽句，未遣世人闻。
醉夜眠江月，闲时逐海云。
荻花寒漫漫，鸥鸟暮羣羣。
若到长沙苑，渔家更待君。','',''),('quantangshi-10166','送袁员外宣慰劝农毕赴洪州使院','李嘉祐','quantangshi','','卷11','圣主临前殿，殷忧遣使臣。
气迎天诏喜，恩发土膏春。
草色催归棹，莺声为送人。
龙沙多道里，流水自相亲。','',''),('quantangshi-10167','送侍御史四叔归朝','李嘉祐','quantangshi','','卷11','淮南频送别，临水惜残春。
攀折隋宫柳，淹留秦地人。
含情归上国，论旧见平津。
更接天津近，余花映绶新。','',''),('quantangshi-10168','登楚州城望驿路十余里山村竹林相次交映','李嘉祐','quantangshi','','卷11','十里山村道，千峰栎树林。
霜浓竹枝亚，岁晚荻花深。
草市多樵客，渔家足水禽。
幽居虽可羡，无那子牟心。','',''),('quantangshi-10169','奉陪韦润州游鹤林寺','李嘉祐','quantangshi','','卷11','野寺江城近，双旌五马过。
禅心超忍辱，梵语问多罗。
松林闲僧老，云烟晚日和。
寒塘归路转，清磬隔微波。','',''),('quantangshi-10170','奉酬路五郎中院长新除工部员外见简','李嘉祐','quantangshi','','卷11','一门同祕省，万里作长城。
问绢莲花府，扬旗细柳营。
词锋偏却敌，草奏直论兵。
何幸新诗赠，真输小谢名。','',''),('quantangshi-10171','送韦司直西行','李嘉祐','quantangshi','','卷11','不耻青袍故，尤宜白发新。
心朝玉皇帝，貌似紫阳人。
湘浦眠销日，桃源醉度春。
能文兼证道，庄叟是前身。','',''),('quantangshi-10172','送上官侍御赴黔中','李嘉祐','quantangshi','','卷11','莫向黔中路，令人到欲迷。
水声巫峡里，山色夜郎西。
树隔朝云合，猨窥晓月啼。
南方饶翠羽，知尔饮清溪。','',''),('quantangshi-10173','送元侍御还荆南幕府','李嘉祐','quantangshi','','卷11','迢递荆州路，山多水又分。
霜林澹寒日，朔雁蔽南云。
八座由持节，三湘亦置军。
自当行直指，应不为功勋。','',''),('quantangshi-10174','登湓城浦望庐山初晴直省赍敕催赴江阴','李嘉祐','quantangshi','','卷11','西望香炉雪，千峰晚色新。
白头悲作吏，黄纸苦催人。
多负登山屐，深藏漉酒巾。
伤心公府内，手板日相亲。','',''),('quantangshi-10175','九日','李嘉祐','quantangshi','','卷11','惆怅重阳日，空山野菊新。
蒹葭百战地，江海十年人。
叹老堪衰柳，伤秋对白苹。
孤楼闻夕磬，塘路向城闉。','',''),('quantangshi-10176','九日送人','李嘉祐','quantangshi','','卷11','晴景应重阳，高台怆远乡。
水澄千室倒，雾卷四山长。
受节人逾老，惊寒菊半黄。
席前愁此别，未别已沾裳。','',''),('quantangshi-10177','春日淇上作','李嘉祐','quantangshi','','卷11','淇上春风涨，鸳鸯逐浪飞。
清明桑叶小，度雨杏花稀。
卫女红妆薄，王孙白马肥。
相将踏青去，不解惜罗衣。','',''),('quantangshi-10178','送从叔阳冰只召赴都','李嘉祐','quantangshi','','卷11','自小从游惯，多由戏笑偏。
常时矜礼数，渐老荷优怜。
见主承休命，为郎贵晚年。
伯喈文与篆，虚作汉家贤。','',''),('quantangshi-10179','送友人入湘','李嘉祐','quantangshi','','卷11','闻说湘川路，年年苦雨多。
猨啼巫峡雨，月照洞庭波。
穷海人还去，孤城雁共过。
青山不可极，来往自蹉跎。','',''),('quantangshi-10180','送裴员外往江南','李嘉祐','quantangshi','','卷11','公务江南远，留驩幕下荣。
枫林缘楚塞，水驿到湓城。
岸草知春晚，沙禽好夜惊。
风帆几度泊，处处暮潮声。','',''),('quantangshi-10181','登秦岭','李嘉祐','quantangshi','','卷11','南登秦岭头，回望始堪愁。
汉阙青门远，高山蓝水流。
三湘迁客去，九陌故人游。
从此辞乡泪，双垂不复收。','',''),('quantangshi-10182','送张惟俭秀才入举','李嘉祐','quantangshi','','卷11','清秀过终童，携书访老翁。
以吾为世旧，怜尔继家风。
淮岸经霜柳，关城带月鸿。
春归定得意，花送到东中。','',''),('quantangshi-10183','送韦侍御湖南幕府','李嘉祐','quantangshi','','卷11','执宪随征虏，逢秋出故关。
雨多愁郢路，叶下识衡山。
地远从军乐，兵强分野闲。
皇家不易将，此去未应还。','',''),('quantangshi-10184','同皇甫冉赴官留别灵一上人','李嘉祐','quantangshi','','卷11','法许庐山远，诗传休上人。
独归双树宿，静与百花亲。
对物虽留兴，观空已悟身。
能令折腰客，遥赏竹房春。','',''),('quantangshi-10185','送客游荆州','李嘉祐','quantangshi','','卷11','草色随骢马，悠悠共出秦。
水传云梦晓，山接洞庭春。
帆影连三峡，猨声在四隣。
青门一分首，难见杜陵人。','',''),('quantangshi-10186','与郑锡游春','李嘉祐','quantangshi','','卷11','东门垂柳长，回首独心伤。
日暖临芳草，天晴忆故乡。
映花莺上下，过水蝶悠扬。
借问同行客，今朝泪几行。','',''),('quantangshi-10187','故燕国相公挽歌二首 一','李嘉祐','quantangshi','','卷11','文若为全德，留侯是重名。
论公长不宰，因病得无生。
大梦依禅定，高坟共化城。
自应怜寂灭，人世但伤情。','',''),('quantangshi-10188','故燕国相公挽歌二首 二','李嘉祐','quantangshi','','卷11','共美持衡日，皆言折槛时。
蜀侯供庙略，汉主缺台司。
车马行仍止，笳箫咽又悲。
今年杜陵陌，殄瘁百花迟。','',''),('quantangshi-10189','故吏部郎中赠给事中韦公挽歌二首 一','李嘉祐','quantangshi','','卷11','神理今何在，斯人竟若斯。
颜渊徒有德，伯道且无儿。
白发今非老，青云数有奇。
谁言夕郎拜，翻向夜台悲。','',''),('quantangshi-10190','故吏部郎中赠给事中韦公挽歌二首 二','李嘉祐','quantangshi','','卷11','社里东城接，松阡北地开。
闻笳春色惨，执绋故人哀。
终日南山对，何时渭水回。
仁兄与恩旧，相望泣泉台。','',''),('quantangshi-10191','和袁郎中破贼后经剡县山水上太尉','李嘉祐','quantangshi','','卷11','受律仙郎贵，长驱下会稽。
鸣笳山月晓，摇斾野云低。
翦寇人皆贺，回军马自嘶。
地闲春草绿，城静夜乌啼。
破竹清闽岭，看花入剡溪。
元戎催献捷，莫道事攀跻。','',''),('quantangshi-10192','送评事十九叔入秦','李嘉祐','quantangshi','','卷11','白露沾蕙草，王孙转忆归。
蔡州新战罢，郢路去人稀。
谒帝不辞远，怀亲空有违。
孤舟看落叶，平楚逐斜晖。
北阙见端冕，南台当绣衣。
唯余播迁客，只伴鹧鸪飞。','',''),('quantangshi-10193','赠王八衢','李嘉祐','quantangshi','','卷11','丹地偏相逐，清江若有期。
腰金才子贵，剖竹老人迟。
桂楫闲迎客，茶瓯对说诗。
渚田分邑里，山桂树罘罳。
心静无华发，人和似古时。
别君远山去，幽独更应悲。','',''),('quantangshi-10194','入睦州分水路忆刘长卿','李嘉祐','quantangshi','','卷11','北阙忤明主，南方随白云。
沿洄滩草色，应接海鸥羣。
建德潮已尽，新安江又分。
回看严子濑，朗咏谢安文。
雨过暮山碧，猨吟秋日曛。
吴洲不可到，刷鬓为思君。','',''),('quantangshi-10195','奉和杜相公长兴新宅即事呈元相公','李嘉祐','quantangshi','','卷11','意有空门乐，居无甲第奢。
经过容法侣，雕饰让侯家。
隐树重檐肃，开园一迳斜。
据梧听好鸟，行药寄名花。
梦蝶留清簟，垂貂坐绛纱。
当山不掩户，映日自倾茶。
雅望归安石，深知在叔牙。
还成吉甫颂，赠答比瑶华。','',''),('quantangshi-10196','江湖秋思','李嘉祐','quantangshi','','卷11','趋陪禁掖雁行随，迁向江潭鹤发垂。
素浪遥疑八溪水，清枫忽似万年枝。
嵩南春徧伤魂梦，壶口云深隔路岐。
共望汉朝多霈泽，苍蝇早晚得先知。','',''),('quantangshi-10197','送朱中舍游江东','李嘉祐','quantangshi','','卷11','孤城郭外送王孙，越水吴洲共尔论。
野寺山边斜有迳，渔家竹里半开门。
青枫独映摇前浦，白鹭闲飞过远村。
若到西陵征战处，不堪秋草自伤魂。','',''),('quantangshi-10198','送窦拾遗赴朝因寄中书十七弟','李嘉祐','quantangshi','','卷11','自叹未霑黄纸诏，那堪远送赤墀人。
老为侨客偏相恋，素是诗家倍益亲。
妻儿共载无羁思，鸳鹭同行不负身。
凭尔将书通令弟，唯论华发愧头巾。','',''),('quantangshi-10199','自苏台至望亭驿人家尽空春物增思怅然有作因寄从弟纾','李嘉祐','quantangshi','','卷11','南浦菰蒋覆白苹，东吴黎庶逐黄巾。
野棠自发空临水，江燕初归不见人。
远岫依依如送客，平田渺渺独伤春。
那堪回首长洲苑，烽火年年报虏尘。','',''),('quantangshi-10200','承恩量移宰江邑临鄱江怅然之作','李嘉祐','quantangshi','','卷11','四年谪宦滞江城，未厌门前鄱水清。
谁言宰邑化黎庶，欲别云山如弟兄。
双鸥为底无心狎，白发从他遶鬓生。
惆怅闲眠临极浦，夕阳秋草不胜情。','',''),('quantangshi-10201','题灵台县东山村主人','李嘉祐','quantangshi','','卷11','处处征胡人渐稀，山村寥落暮烟微。
门临莽苍经年闭，身逐嫖姚几日归。
贫妻白发输残税，余寇黄河未解围。
天子如今能用武，祗应岁晚息兵机。','',''),('quantangshi-10202','同皇甫冉登重玄阁','李嘉祐','quantangshi','','卷11','高阁朱栏不厌游，蒹葭白水遶长洲。
孤云独鸟川光暮，万井千山海色秋。
清梵林中人转静，夕阳城上角偏愁。
谁怜远作秦吴别，离恨归心双泪流。','',''),('quantangshi-10203','宋州东登望题武陵驿','李嘉祐','quantangshi','','卷11','梁宋人稀鸟自啼，登舻一望倍含凄。
白骨半随河水去，黄云犹傍郡城低。
平陂战地花空落，旧苑春田草未齐。
明主频移虎符守，几时行县向黔黎。','',''),('quantangshi-10204','晚登江楼有怀','李嘉祐','quantangshi','','卷11','独坐南楼佳兴新，青山绿水共为隣。
爽气遥分隔浦岫，斜光偏照渡江人。
心闲鸥鸟时相近，事简鱼竿私自亲。
只忆帝京不可到，秋琴一弄欲沾巾。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-10205','游徐城河忽见清淮因寄赵八','李嘉祐','quantangshi','','卷11','自缘迟暮忆沧洲，翻爱南河浊水流。
初过重阳惜残菊，行看旧浦识羣鸥。
朝霞映日同归处，暝柳摇风欲别秋。
长恨相逢即分首，含情掩泪独回头。','',''),('quantangshi-10206','题游仙阁白公庙','李嘉祐','quantangshi','','卷11','仙冠轻举竟何之，薜荔缘堦竹映祠。
甲子不知风驭日，朝昏唯见雨来时。
霓旌翠盖终难遇，流水青山空所思。
逐客自怜双鬓改，梵香多负白云期。','',''),('quantangshi-10207','送郑正则汉阳迎妇','李嘉祐','quantangshi','','卷11','锦字相催鸟急飞，郎君暂脱老莱衣。
遥想双眉待人画，行看五马送潮归。
望夫山上花犹发，新妇江边莺未稀。
令秩和鸣真可羡，此行谁道负春辉。','',''),('quantangshi-10208','送皇甫冉往安宜','李嘉祐','quantangshi','','卷11','江臯尽日唯烟水，君向白田何日归。
楚地蒹葭连海逈，隋朝杨柳映堤稀。
津楼故市无行客，山馆荒城闭落晖。
若问行人与征战，使君双泪定霑衣。','',''),('quantangshi-10209','晚发咸阳寄同院遗补','李嘉祐','quantangshi','','卷11','征战初休草又衰，咸阳晚眺泪堪垂。
去路全无千里客，秋田不见五陵儿。
秦家故事随流水，汉代高坟对石碑。
回首青山独不语，羡君谈笑万年枝。','',''),('quantangshi-10210','早秋京口旅泊章侍御寄书相问因以赠之时七夕','李嘉祐','quantangshi','','卷11','移家避寇逐行舟，厌见南徐江水流。
吴越征徭非旧日，秣陵凋弊不宜秋。
千家闭户无砧杵，七夕何人望斗牛。
祗有同时骢马客，偏宜尺牍问穷愁。','',''),('quantangshi-10211','秋晓招隐寺东峰茶宴送内弟阎伯均归江州','李嘉祐','quantangshi','','卷11','万畦新稻傍山村，数里深松到寺门。
幸有香茶留穉子，不堪秋草送王孙。
烟尘怨别唯愁隔，井邑萧条谁忍论。
莫怪临歧独垂泪，魏舒偏念外家恩。','',''),('quantangshi-10212','送严员外','李嘉祐','quantangshi','','卷11','春风倚棹阖闾城，水国春寒阴复晴。
细雨湿衣看不见，闲花落地听无声。
日斜江上孤帆影，草绿湖南万里情。
君去若逢相识问，青袍今已误儒生。','',''),('quantangshi-10213','赴南中留别褚七少府湖上林亭','李嘉祐','quantangshi','','卷11','种田东郭傍春陂，万事无情把钓丝。
绿竹放侵行迳里，青山常对卷帘时。
纷纷花发门空闭，寂寂莺啼日更迟。
从此别君千万里，白云流水忆佳期。','',''),('quantangshi-10214','与从弟正字从兄兵曹宴集林园','李嘉祐','quantangshi','','卷11','竹窓松户有佳期，美酒香茶慰所思。
辅嗣外生还解易，惠连羣从总能诗。
檐前花落春深后，谷里莺啼日暮时。
去路归程仍待月，垂缰不控马行迟。','',''),('quantangshi-10215','酬皇甫十六侍御曾见寄','李嘉祐','quantangshi','','卷11','自顾衰容累玉除，忽承优诏赴铜鱼。
江头鸟避青旄节，城里人迎露网车。
长沙地近悲才子，古郡山多忆旧庐。
更枉新诗思何苦，离骚愁处亦无如。','',''),('quantangshi-10216','暮春宜阳郡斋愁坐忽枉刘七侍御新诗因以酬答','李嘉祐','quantangshi','','卷11','子规夜夜[啼]槠叶，远道逢春半是愁。
芳草伴人还易老，落花随水亦东流。
山临睥睨恒多雨，地接潇湘畏及秋。
唯羡君为周柱史，手持黄纸到沧洲。','',''),('quantangshi-10217','送舍弟','李嘉祐','quantangshi','','卷11','诸谢偏推永嘉守，三何独许水曹郎。
老兄鄙思难俦匹，令弟清词堪比量。
叠嶂入云藏古寺，高秋背月转南湘。
定知马上多新句，早寄袁溪当八行。','',''),('quantangshi-10218','送从弟永任饶州录事参军','李嘉祐','quantangshi','','卷11','一官万里向千溪，水宿山行鱼浦西。
日晚长烟高岸近，天寒积雪远峰低。
芦花渚里鸿相呌，苦竹丛边猨暗啼。
闻道慈亲倚门待，到时兰叶正萋萋。','',''),('quantangshi-10219','送马将军奏事毕归滑州使幕','李嘉祐','quantangshi','','卷11','吴门别后蹈沧州，帝里相逢俱白头。
自叹马卿常带病，还嗟李广未封侯。
棠梨宫里瞻龙衮，细柳营前着豹裘。
想到滑台桑叶落，黄河东注荻花秋。','',''),('quantangshi-10220','闻逝者自惊','李嘉祐','quantangshi','','卷11','亦知死是人间事，年老闻之心自疑。
黄卷清琴总为累，落花流水共添悲。
愿将从药看真诀，又欲休官就本师。
儿女眼前难喜舍，弥怜双鬓渐如丝。','',''),('quantangshi-10221','伤歙州陈二使君','李嘉祐','quantangshi','','卷11','怜君辞满卧沧洲，一旦云亡万事休。
慈母断肠妻独泣，寒云惨色水空流。
江村故老长怀惠，山路孤猨亦共愁。
寂寞荒坟近渔浦，野松孤月即千秋。','',''),('quantangshi-10222','白田西忆楚州使君弟','李嘉祐','quantangshi','','卷11','山阳郭里无潮，野水自向新桥。
鱼网平铺荷叶，鹭鸶闲步稻苗。
秣陵归人惆怅，楚地连山寂寥。
却忆士龙宾阁，清琴绿竹萧萧。','',''),('quantangshi-10223','送陆澧还吴中','李嘉祐','quantangshi','','卷11','瓜步寒潮送客，杨花暮雨霑衣。
故乡南望何处，春水连天独归。','',''),('quantangshi-10224','春日忆家','李嘉祐','quantangshi','','卷11','自觉劳乡梦，无人见客心。
空余庭草色，日日伴愁襟。','',''),('quantangshi-10225','远寺钟','李嘉祐','quantangshi','','卷11','疎钟何处来，度竹兼拂水。
渐逐微风声，依依犹在耳。','',''),('quantangshi-10226','白鹭','李嘉祐','quantangshi','','卷11','江南渌水多，顾影逗轻波。
落日秦云里，山高奈若何。','',''),('quantangshi-10227','夜宴南陵留别','李嘉祐','quantangshi','','卷11','雪满前庭月色闲，主人留客未能还。
预愁明日相思处，匹马千山与万山。','',''),('quantangshi-10228','题前溪馆','李嘉祐','quantangshi','','卷11','两年谪宦在江西，举目云山要自迷。
今日始知风土异，浔阳南去鹧鸪啼。','',''),('quantangshi-10229','过乌公山寄钱起员外','李嘉祐','quantangshi','','卷11','雨过青山猨呌时，愁人泪点石榴枝。
无端王事还相系，肠断蒹葭君不知。','',''),('quantangshi-10230','寄王舍人竹楼','李嘉祐','quantangshi','','卷11','傲吏身闲笑五侯，西江取竹起高楼。
南风不用蒲葵扇，纱帽闲眠对水鸥。','',''),('quantangshi-10231','韦润州后亭海榴','李嘉祐','quantangshi','','卷11','江上年年小雪迟，年光独报海榴知。
寂寂山城风日暖，谢公含笑向南枝。','',''),('quantangshi-10232','送崔十一弟归北京','李嘉祐','quantangshi','','卷11','潘郎美貌谢公诗，银印花骢年少时。
楚地江臯一为别，晋山沙水独相思。','',''),('quantangshi-10233','访韩司空不遇','李嘉祐','quantangshi','','卷11','图画风流似长康，文词体格效陈王。
蓬莱对去归常晚，丛竹闲飞满夕阳。','',''),('quantangshi-10234','题道虔上人竹房','李嘉祐','quantangshi','','卷11','诗思禅心共竹闲，任他流水向人间。
手持如意高窓里，斜日沿江千万山。','',''),('quantangshi-10235','秋朝木芙蓉','李嘉祐','quantangshi','','卷11','水面芙蓉秋已衰，繁条到是着花时。
平明露滴垂红脸，似有朝愁暮落悲。','',''),('quantangshi-10236','袁江口忆王司勋王吏部二郎中起居十七弟','李嘉祐','quantangshi','','卷11','京华不啻三千里，客泪如今一万双。
若个最为相忆处，青枫黄竹入袁江。','',''),('quantangshi-10237','答泉州薛播使君重阳日赠酒','李嘉祐','quantangshi','','卷11','欲强登高无力去，篱边黄菊为谁开。
共知不是浔阳郡，那得王弘送酒来。','',''),('quantangshi-10238','题张公洞','李嘉祐','quantangshi','','卷11','空山杳杳鸾凤飞，神仙门户开翠微。
主人白发雪霞衣，松间留我谈玄机。','',''),('quantangshi-10239','句','李嘉祐','quantangshi','','卷11','水田飞白鹭，夏木啭黄鹂。
白马撼金珂，纷纷侍从多。
身居骠骑幕，家住滹沱河。
溪北映初星。','',''),('quantangshi-10240','送泉州李使君之任','包何','quantangshi','','卷11','傍海皆荒服，分符重汉臣。
云山百越路，市井十洲人。
执玉来朝远，还珠入贡频。
连年不见雪，到处即行春。','',''),('quantangshi-10241','和孟虔州闲斋即事','包何','quantangshi','','卷11','古郡邻江岭，公庭半薜萝。
府僚闲不入，山鸟静偏过。
睥睨临花柳，栏干枕芰荷。
麦秋今欲至，君听两岐歌。','',''),('quantangshi-10242','同李郎中净律院梡子树','包何','quantangshi','','卷11','本梡稀难识，沙门种则生。
叶殊经写字，子为佛称名。
滤水浇新长，燃灯暖更荣。
亭亭无别意，只是劝修行。','',''),('quantangshi-10243','同阎伯均宿道士观有述','包何','quantangshi','','卷11','南国佳人去不回，洛阳才子更须媒。
绮琴白雪无心弄，罗幌清风到晓开。
冉冉修篁依户牖，迢迢列宿映楼台。
纵令奔月成仙去，且作行云入梦来。','',''),('quantangshi-10244','送乌程王明府贬巴江','包何','quantangshi','','卷11','一片孤帆无四邻，北风吹过五湖滨。
相看尽是江南客，独有君为岭外人。','',''),('quantangshi-10245','同舍弟佶班韦二员外秋苔对之成咏','包何','quantangshi','','卷11','每看苔藓色，如向簿书闲。
幽思缠芳树，高情寄远山。
雨痕连地绿，日色出林斑。
却笑兴公赋，临危滑石间。','',''),('quantangshi-10246','送王汶宰江阴','包何','quantangshi','','卷11','郡北乘流去，花间竟日行。
海鱼朝满市，江鸟夜喧城。
止酒非关病，援琴不在声。
应缘五斗米，数日滞渊明。','',''),('quantangshi-10247','和苗员外寓直中书','包何','quantangshi','','卷11','朝列称多士，君家有二难。
贞为台里柏，芳作省中兰。
夜宿分曹阔，晨趋接武欢。
每怜双阙下，雁序入鸳鸾。','',''),('quantangshi-10248','阙下芙蓉','包何','quantangshi','','卷11','一人理国致升平，万物呈祥助圣明。
天上河从阙下过，江南花向殿前生。
庆云垂荫开难落，湛露为珠满不倾。
更对乐悬张宴处，歌工欲奏采莲声。','',''),('quantangshi-10249','江上田家','包何','quantangshi','','卷11','近海川原薄，人家本自稀。
黍苗期腊酒，霜叶是寒衣。
市井谁相识，渔樵夜始归。
不须骑马问，恐畏狎鸥飞。','',''),('quantangshi-10250','送韦侍御奉使江岭诸道催青苗钱','包何','quantangshi','','卷11','近远从王事，南行处处经。
手持霜简白，心在夏苗青。
回雁书应报，愁猨夜屡听。
因君使绝域，方物尽来庭。','',''),('quantangshi-10251','和程员外春日东郊即事','包何','quantangshi','','卷11','郎官休浣怜迟日，野老欢娱为有年。
几处折花惊蝶梦，数家留叶待蚕眠。
藤垂宛地萦珠履，泉迸侵堦浸绿钱。
直到闭关朝谒去，莺声不散柳含烟。','',''),('quantangshi-10252','裴端公使院赋得隔帘见春雨','包何','quantangshi','','卷11','细雨未成霖，垂帘但觉阴。
唯看上砌湿，不遣入檐深。
度隟霑霜简，因风润绮琴。
须移户外屦，檐溜夜相侵。','',''),('quantangshi-10253','相里使君第七男生日','包何','quantangshi','','卷11','取妻生子复生男，独有君家众所谈。
荀氏八龙唯欠一，桓山四凤已过三。
他时干蛊声名着，今日悬弧宴乐酣。
谁道众贤能继体，须知个个出于蓝。','',''),('quantangshi-10254','同诸公寻李方直不遇','包何','quantangshi','','卷11','闻说到扬州，吹箫忆旧游。
人来多不见，莫是上迷楼。','',''),('quantangshi-10255','婺州留别邓使君','包何','quantangshi','','卷11','西掖驰名久，东阳出守时。
江山婺女分，风月隐侯诗。
别恨双溪急，留欢五马迟。
回舟映沙屿，未远剩相思。','',''),('quantangshi-10256','寄杨侍御','包何','quantangshi','','卷11','一官何幸得同时，十载无媒独见遗。
今日不论腰下组，请君看取鬓边丝。','',''),('quantangshi-10257','赋得秤送孟孺卿','包何','quantangshi','','卷11','愿以金秤锤，因君赠别离。
钩悬新月吐，衡举众星随。
掌握须平执，锱铢必尽知。
由来投分审，莫放弄权移。','',''),('quantangshi-10258','长安晓望寄崔补阙','包何','quantangshi','','卷11','迢递山河拥帝京，参差宫殿接云平。
风吹晓漏经长乐，柳带晴烟出禁城。
天净笙歌临路发，日高车马隔尘行。
自怜久滞诸生列，未得金闺籍姓名。','',''),('quantangshi-10259','送萧颖士赴东府得路字','賈邕','quantangshi','','卷11','子欲适东周，门人盈岐路。
高标信难仰，薄官非始务。
绵邈千里途，裴回四郊暮。
征车日云远，抚己慙深顾。','',''),('quantangshi-10260','送萧颖士赴东府得适字','劉舟','quantangshi','','卷11','大名掩诸古，独断无不适。
德遂天下宗，官为幕中客。
骊山浮云散，灞岸零雨夕。
请业非远期，圆光再生魄。','',''),('quantangshi-10261','送萧颖士赴东府得离字','長孫鑄','quantangshi','','卷11','大德讵可拟，高梧有长离。
素怀经纶具，昭世犹安卑。
落日去关外，悠悠隔山陂。
我心如浮云，千里相追随。','',''),('quantangshi-10262','送萧颖士赴东府得还字','房白','quantangshi','','卷11','夫子高世迹，时人不可攀。
今予亦云幸，谬得承温颜。
良策资入幕，遂行从近关。
青春灞亭别，此去何时还。','',''),('quantangshi-10263','送萧颖士赴东府得引字','晟','quantangshi','','卷11','吾见夫子德，谁云习相近。
数仞不可窥，言味终难尽。
处喧虑常澹，作吏心亦隐。
更有嵩少峰，东南为胜引。','',''),('quantangshi-10264','送萧颖士赴东府得浅字','劉太沖','quantangshi','','卷11','吾师继微言，赞述在坟典。
寸禄聊自资，平生宦情鲜。
逶迟东州路，春草深复浅。
日远夫子门，中心曷由展。','',''),('quantangshi-10265','送萧颖士赴东府得草字','姚發','quantangshi','','卷11','天生良史笔，浪迹擅文藻。
中夏授参谋，东夷愿闻道。
行轩翫春日，饯席藉芳草。
幸得师季良，欣留箧笥宝。','',''),('quantangshi-10266','送萧颖士赴东府得往字','鄭愕','quantangshi','','卷11','斤溪数亩田，素心拟长往。
繄君曲得引，使我缨俗网。
风尘岂不劳，道义成心赏。
春郊桃李月，忍此戒征两。','',''),('quantangshi-10267','送萧颖士赴东府得散字','殷少野','quantangshi','','卷11','官闲幕府下，聊以任纵诞。
文学鲁仲尼，高标嵇中散。
出门时雨润，对酒春风暖。
感激知己恩，别离魂欲断。','',''),('quantangshi-10268','送萧颖士赴东府得君字','鄔載','quantangshi','','卷11','策名十二载，独立先斯文。
迩来及门者，半已升青云。
青云岂无姿，黄鹄素不羣。
一辞芸香吏，几岁沧江濆。
散职既不羁，天听亦昭闻。
虽承急贤诏，未谒陶唐君。
薄俸还自急，此言那足云。
和风媚东郊，时物滋南薰。
蕙草正可摘，豫章犹未分。
宗师忽千里，使我心氛氲。','',''),('quantangshi-10269','奉陪韦中丞使君游鹤林寺','皇甫曾','quantangshi','','卷11','古寺传灯久，层城闭阁闲。
香花同法侣，旌斾入深山。
寒磬虚空里，孤云起灭间。
谢公忆高卧，徒御欲东还。','',''),('quantangshi-10270','奉送杜侍御还京','皇甫曾','quantangshi','','卷11','罢战回龙节，朝天上凤池。
寒生五湖道，春入万年枝。
召化多遗爱，胡清已畏知。
怀恩偏感别，堕泪向旌麾。','',''),('quantangshi-10271','酬郑侍御秋夜见寄','皇甫曾','quantangshi','','卷11','摇落空林夜，河阳兴已生。
未辞公府步，知结远山情。
高柳风难定，寒泉月助明。
袁公方卧雪，尺素及柴荆。','',''),('quantangshi-10272','酬窦拾遗秋日见呈','皇甫曾','quantangshi','','卷11','孤城永巷时相见，衰柳闲门日半斜。
欲送近臣朝魏阙，犹怜残菊在陶家。','',''),('quantangshi-10273','韦使君宅海榴咏','皇甫曾','quantangshi','','卷11','淮阳卧理有清风，腊月榴花带雪红。
闭阁寂寥常对此，江湖心在数枝中。','',''),('quantangshi-10274','送普上人还阳羡','皇甫曾','quantangshi','','卷11','花宫难久别，道者忆千灯。
残雪入林路，暮山归寺僧。
日光依嫩草，泉响滴春冰。
何用求方便，看心是一乘。','',''),('quantangshi-10275','送李中丞归本道','皇甫曾','quantangshi','','卷11','上将还专席，双旌复出秦。
关河三晋路，宾从五原人。
孤戍云连海，平沙雪度春。','',''),('quantangshi-10276','和谢舍人雪夜寓直','皇甫曾','quantangshi','','卷11','禁省夜沈沈，春风雪满林。
沧洲归客梦，青琐近臣心。
挥翰宣鸣玉，承恩在赐金。
建章寒漏起，更助掖垣深。','',''),('quantangshi-10277','寻刘处士','皇甫曾','quantangshi','','卷11','几年人不见，林下掩柴关。
留客当清夜，逢君话旧山。
隔城寒杵急，带月早鸿还。
南陌虽相近，其如隐者闲。','',''),('quantangshi-10278','哭陆处士','皇甫曾','quantangshi','','卷11','从此无期见，柴门对雪开。
二毛逢世难，万恨掩泉台。
返照空堂夕，孤城吊客回。
汉家偏访道，犹畏鹤书来。','',''),('quantangshi-10279','乌程水楼留别','皇甫曾','quantangshi','','卷11','悠悠千里去，惜此一尊同。
客散高楼上，帆飞细雨中。
山程随远水，楚思在青枫。
共说前期易，沧波处处同。','',''),('quantangshi-10280','题赠吴门邕上人','皇甫曾','quantangshi','','卷11','春山唯一室，独坐草萋萋。
身寂心成道，花闲鸟自啼。
细泉松径里，返景竹林西。
晚与门人别，依依出虎溪。','',''),('quantangshi-10281','送陆鸿渐山人采茶回','皇甫曾','quantangshi','','卷11','千峯待逋客，香茗复丛生。
采摘知深处，烟霞羡独行。
幽期山寺远，野饭石泉清。
寂寂燃灯夜，相思一磬声。','',''),('quantangshi-10282','寄刘员外长卿','皇甫曾','quantangshi','','卷11','南忆新安郡，千山带夕阳。
断猨知夜久，秋草助江长。
疎发应成素，青松独耐霜。
爱才称汉主，题柱待回乡。','',''),('quantangshi-10283','寄张仲甫','皇甫曾','quantangshi','','卷11','悲风生旧浦，云岭隔东田。
伏腊同鸡黍，柴门闭雪天。
孤村明夜火，稚子候归船。
静者心相忆，离居畏度年。','',''),('quantangshi-10284','送元侍御充使湖南','皇甫曾','quantangshi','','卷11','云梦南行尽，三湘万里流。
山川重分手，徒御亦悲秋。
白简劳王事，清猨助客愁。
离羣复多病，岁晚忆沧洲。','',''),('quantangshi-10285','晚至华阴','皇甫曾','quantangshi','','卷11','腊尽促归心，行人及华阴。
云霞仙掌出，松柏古祠深。
野渡冰生岸，寒川烧隔林。
温泉看渐近，宫树晚沈沈。','',''),('quantangshi-10286','送孔征士','皇甫曾','quantangshi','','卷11','谷口山多处，君归不可寻。
家贫青史在，身老白云深。
扫雪开松径，疏泉过竹林。
余生负丘壑，相送亦何心。','',''),('quantangshi-10287','秋兴','皇甫曾','quantangshi','','卷11','流萤与落叶，秋晚共纷纷。
返照城中尽，寒砧雨外闻。
离人见衰鬓，独鹤暮何羣。
楚客在千里，相思看碧云。','',''),('quantangshi-10288','送归中丞使新罗','皇甫曾','quantangshi','','卷11','南幰衔恩去，东夷泛海行。
天遥辞上国，水尽到孤城。
已变炎凉气，仍愁浩淼程。
云涛不可极，来往见双旌。','',''),('quantangshi-10289','送少微上人东南游','皇甫曾','quantangshi','','卷11','石梁人不到，独往更迢迢。
乞食山家少，寻钟野寺遥。
松门风自扫，瀑布雪难消。
秋夜闻清梵，余音逐海潮。','',''),('quantangshi-10290','送韦判官赴闽中','皇甫曾','quantangshi','','卷11','孤棹闽中客，双旌海上军。
路人从北少，海水向南分。
野鹤伤秋别，林猨忌夜闻。
汉家崇亚相，知子远邀勋。','',''),('quantangshi-10291','送人还荆州','皇甫曾','quantangshi','','卷11','草色随骢马，悠悠同出秦。
水传云梦晓，山接洞庭春。
帆影连三峡，猨声近四隣。
青门一分手，难见杜陵人。','',''),('quantangshi-10292','寄净虚上人初至云门','皇甫曾','quantangshi','','卷11','寒踪白云里，法侣自提携。
竹径通城下，松门隔水西。
方同沃洲去，不似武陵迷。
彷佛方知处，高峯是会稽。','',''),('quantangshi-10293','春和杜相公移入长兴宅奉呈诸宰执','皇甫曾','quantangshi','','卷11','欲向幽偏适，还从绝地移。
秦官鼎食贵，尧世土阶卑。
戟户槐阴满，书窗竹叶垂。
才分午夜漏，遥隔万年枝。
北阙深恩在，东林远梦知。
日斜门掩暎，山远树参差。
论道齐鸳翼，题诗忆凤池。
从公亦何幸，长与佩声随。','',''),('quantangshi-10294','路中口号','皇甫曾','quantangshi','','卷11','还乡不见家，年老眼多泪。
车马上河桥，城中好天气。','',''),('quantangshi-10295','山下泉','皇甫曾','quantangshi','','卷11','漾漾带山光，澄澄倒林影。
那知石上喧，却忆山中静。','',''),('quantangshi-10296','早朝日寄所知','皇甫曾','quantangshi','','卷11','长安雪夜见归鸿，紫禁朝天拜舞同。
曙色渐分双阙下，漏声遥在百花中。
炉烟乍起开仙仗，玉佩才成引上公。
共荷发生同雨露，不应黄叶久随风。','',''),('quantangshi-10297','秋夕寄怀契上人','皇甫曾','quantangshi','','卷11','已见槿花朝委露，独悲孤鹤在人羣。
真僧出世心无事，静夜名香手自焚。
窗临绝涧闻流水，客至孤峯扫白云。
更想清晨诵经处，独看松上雪纷纷。','',''),('quantangshi-10298','张芬见访郊居作','皇甫曾','quantangshi','','卷11','林中雨散早凉生，已有迎秋促织声。
三径荒芜羞对客，十年衰老愧称兄。
愁心自惜江蓠晚，世事方看木槿荣。
君若罢官携手日，寻山莫算白云程。','',''),('quantangshi-10299','赠鉴上人','皇甫曾','quantangshi','','卷11','律仪传教诱，僧腊老烟霄。
树色依禅诵，泉声入寂寥。
宝龛经末劫，画壁见南朝。
深竹风开合，寒潭月动摇。
息心归静理，爱道坐中宵。
更欲寻真去，乘船过海潮。','',''),('quantangshi-10300','奉寄中书王舍人','皇甫曾','quantangshi','','卷11','腰金载笔谒承明，至道安禅得此生。
西掖几年纶綍贵，东山遥夜薜萝情。
风传刻漏星河曙，月上梧桐雨露清。
圣主好文谁为荐，闭门空赋子虚成。','',''),('quantangshi-10301','送汤中丞和蕃','皇甫曾','quantangshi','','卷11','继好中司出，天心外国知。
已传尧雨露，更说汉威仪。
陇上应回首，河源复载驰。
孤峯问徒御，空碛见旌麾。
春草乡愁起，边城旅梦移。
莫嗟行远地，此去答恩私。','',''),('quantangshi-10302','送和西蕃使','皇甫曾','quantangshi','','卷11','白简初分命，黄金已在腰。
恩华通外国，徒御发中朝。
雨雪从边起，旌旗上陇遥。
暮天沙漠漠，空碛马萧萧。
寒路随河水，关城见柳条。
和戎先罢战，知胜霍嫖姚。','',''),('quantangshi-10303','送王相公赴幽州','皇甫曾','quantangshi','','卷11','台衮兼戎律，勤忧秉化元。
凤池东掖宠，龙节北方尊。
长路山河转，前驱鼓角喧。
人安布时令，地远答君恩。
暮日平沙迥，秋风大斾翻。
渔阳在天末，恋别信陵门。','',''),('quantangshi-10304','送徐大夫赴南海','皇甫曾','quantangshi','','卷11','旧国当分阃，天涯答圣私。
大军传羽檄，老将拜旌旗。
位重登坛后，恩深弄印时。
何年谏猎赋，今日饮泉诗。
海内求民瘼，城隅见岛夷。
由来黄霸去，自有上台期。','',''),('quantangshi-10305','赠沛禅师','皇甫曾','quantangshi','','卷11','南岳满湘沅，吾师经利涉。
身归沃洲老，名与支公接。
净教传荆吴，道缘止渔猎。
观空色不染，对境心自惬。
室中人寂寞，门外山重叠。
天台积幽梦，早晚当负笈。','',''),('quantangshi-10306','萼岭四望','皇甫曾','quantangshi','','卷11','汉家仙仗在咸阳，洛水东流出建章。
野老至今犹望幸，离宫秋树独苍苍。','',''),('quantangshi-10307','过刘员外长卿别墅','皇甫曾','quantangshi','','卷11','谢客开山后，郊扉积水通。
江湖千里别，衰老一尊同。
返照寒川满，平田暮雪空。
沧洲自有趣，不便哭途穷。','',''),('quantangshi-10308','遇风雨作','皇甫曾','quantangshi','','卷11','草草理夜装，涉江又登陆。
望路殊未穷，指期今已促。
传呼戒徒驭，振辔转林麓。
阴云拥岩端，霑雨当山腹。
震雷如在耳，飞电来照目。
兽迹不敢窥，马蹄惟务速。
虔心若斋祷，濡体如沐浴。
万窍相怒号，百泉暗奔瀑。
危梁虑足跌，峻坂忧车覆。
问我何以然，前日爱微禄。
转知人代事，缨组乃徽束。
向若家居时，安枕春梦熟。
遵途稍已近，候吏来相续。
晓霁心始安，林端见初旭。','',''),('quantangshi-10309','送商州杜中丞赴任','皇甫曾','quantangshi','','卷11','安康地理接商于，帝命专城总赋舆。
夕拜忽辞青琐闼，晨装独捧紫泥书。
深山古驿分驺骑，芳草闲云逐隼旟。
绮皓清风千古在，因君一为谢岩居。','',''),('quantangshi-10310','送着公归越','皇甫曾','quantangshi','','卷11','谁能愁此别，到越会相逢。
长忆云门寺，门前千万峯。
石牀埋积雪，山路倒枯松。
莫学白居士，无人知去踪。','',''),('quantangshi-10311','送郑秀才贡举','皇甫曾','quantangshi','','卷11','西去意如何，知随贡士科。
吟诗向月路，驱马出烟萝。
晚色寒芜远，秋声候雁多。
自怜归未得，相送一劳歌。','',''),('quantangshi-10312','锡杖歌送明楚上人归佛川','皇甫曾','quantangshi','','卷11','上人远自西天至，头陀行遍南朝寺。
口翻贝叶古字经，手持金策声泠泠。
护法护身惟振锡，石濑云溪深寂寂。
乍来松径风露寒，遥暎霜天月成魄。
后夜空山禅诵时，寥寥挂在枯树枝。
真法尝传心不住，东西南北随缘路。
佛川此去何时回，应真莫便游天台。','',''),('quantangshi-10313','玉山岭上作','皇甫曾','quantangshi','','卷11','悠悠驱匹马，征路上连冈。
晚翠深云窦，寒台净石梁。
秋花偏似雪，枫叶不禁霜。
愁见前程远，空郊下夕阳。','',''),('quantangshi-10314','国子柳博士兼领太常博士輙申贺赠','皇甫曾','quantangshi','','卷11','博士本秦官，求才帖职难。
临风曲台净，对月碧池寒。
讲学分阴重，斋祠晓漏残。
朝衣辨色处，双绶更宜看。','',''),('quantangshi-10315','送裴秀才贡举','皇甫曾','quantangshi','','卷11','儒衣羞此别，去抵汉公卿。
宾贡年犹少，篇章艺已成。
临流惜暮景，话别起乡情。
离酌不辞醉，西江春草生。','',''),('quantangshi-10316','赠老将','皇甫曾','quantangshi','','卷11','白草黄云塞上秋，曾随骠骑出并州。
辘轳劒折虬髯白，转战功多独不侯。','',''),('quantangshi-10317','铜雀妓','高適','quantangshi','','卷11','日暮铜雀迥，秋深玉座清。
萧森松柏望，委郁绮罗情。
君恩不再得，妾舞为谁轻。','',''),('quantangshi-10318','塞下曲','高適','quantangshi','','卷11','结束浮云骏，翩翩出从戎。
且凭天子怒，复倚将军雄。
万鼓雷殷地，千旗火生风。
日轮驻霜戈，月魄悬雕弓。
青海阵云匝，黑山兵气衡。
战酣太白高，战罢旄头空。
万里不惜死，一朝得成功。
画图骐麟阁，入朝明光宫。
大笑向文士，一经何足穷。
古人昧此道，往往成老翁。','',''),('quantangshi-10319','塞上','高適','quantangshi','','卷11','东出卢龙塞，浩然客思孤。
亭堠列万里，汉兵犹备胡。
边尘涨北溟，虏骑正南驱。
转鬬岂长策，和亲非远图。
惟昔李将军，按节出皇都。
总戎扫大漠，一战擒单于。
常怀感激心，愿效纵横谟。
倚劒欲谁语，关河空郁纡。','',''),('quantangshi-10320','蓟门行五首 一','高適','quantangshi','','卷11','蓟门逢古老，独立思氛氲。
一身既零丁，头鬓白纷纷。
勋庸今已矣，不识霍将军。','',''),('quantangshi-10321','蓟门行五首 二','高適','quantangshi','','卷11','汉家能用武，开拓穷异域。
戍卒厌糠核，降胡饱衣食。
关亭试一望，吾欲泪沾臆。','',''),('quantangshi-10322','蓟门行五首 三','高適','quantangshi','','卷11','边城十一月，雨雪乱霏霏。
元戎号令严，人马亦轻肥。
羌胡无尽日，征战几时归。','',''),('quantangshi-10323','蓟门行五首 四','高適','quantangshi','','卷11','幽州多骑射，结发重横行。
一朝事将军，出入有声名。
纷纷猎秋草，相向角弓鸣。','',''),('quantangshi-10324','蓟门行五首 五','高適','quantangshi','','卷11','黯黯长城外，日没更烟尘。
胡骑虽凭陵，汉兵不顾身。
古树满空塞，黄云愁杀人。','',''),('quantangshi-10325','效古赠崔二','高適','quantangshi','','卷11','十月河洲时，一看有归思。
风飙生惨烈，雨雪暗天地。
我辈今胡为，浩哉迷所至。
缅怀当涂者，济济居声位。
邈然在云霄，宁肯更沦踬。
周旋多燕乐，门馆列车骑。
美人芙蓉姿，狭室兰麝气。
金炉陈兽炭，谈笑正得意。
岂论草泽中，有此枯槁士。
我慙经济策，久欲甘弃置。
君负纵横才，如何尚顦顇。
长歌增郁怏，对酒不能醉。
穷达自有时，夫子莫下泪。','',''),('quantangshi-10326','钜鹿赠李少府','高適','quantangshi','','卷11','李侯虽薄宦，时誉何籍籍。
骏马常借人，黄金每留客。
投壶华馆静，纵酒凉风夕。
即此遇神仙，吾欣知损益。','',''),('quantangshi-10327','东平留赠狄司马','高適','quantangshi','','卷11','古人无宿诺，兹道以为难。
万里赴知己，一言诚可叹。
马蹄经月窟，劒术指楼兰。
地出北庭尽，城临西海寒。
森然瞻武库，则是弄儒翰。
入幕绾银绶，乘轺兼铁冠。
练兵日精锐，杀敌无遗残。
献捷见天子，论功俘可汗。
激昂丹墀下，顾盼青云端。
谁谓纵横策，翻为权势干。
将军既坎壈，使者亦辛酸。
耿介挹三事，羇离从一官。
知君不得意，他日会鹏抟。','',''),('quantangshi-10328','过卢明府有赠','高適','quantangshi','','卷11','良吏不易得，古人今可传。
静然本诸已，以此知其贤。
我行挹高风，羡尔兼少年。
胸怀豁清夜，史汉如流泉。
明日复行春，逶迤出郊坛。
登高见百里，桑野郁芊芊。
时平俯鹊巢，岁熟多人烟。
奸猾唯闭户，逃亡归种田。
廻轩自郭南，老幼满马前。
皆贺蚕农至，而无徭役牵。
君观黎庶心，抚之诚万全。
何幸逢大道，愿言烹小鲜。
能奏明廷主，一试武城弦。','',''),('quantangshi-10329','单父逢邓司仓覆仓库因而有赠','高適','quantangshi','','卷11','邦牧今坐啸，羣贤趋纪纲。
四人忽不扰，耕者遥相望。
粲粲府中妙，授词如履霜。
炎炎伏热时，草木无晶光。
匹马度睢水，清风何激扬。
校缗阅帑藏，发廪欣斯箱。
邂逅得相逢，欢言至夕阳。
开襟自公余，载酒登琴堂。
举杯挹山川，寓目穷毫芒。
白鸟向田尽，青蝉归路长。
醉中不惜别，况乃正游梁。','',''),('quantangshi-10330','蓟门不遇王之[涣]郭密之因以留赠','高適','quantangshi','','卷11','适远登蓟丘，兹晨独搔屑。
贤交不可见，吾愿终难说。
迢递千里游，羇离十年别。
才华仰清兴，功业嗟芳节。
旷荡阻云海，萧条带风雪。
逢时事多谬，失路心弥折。
行矣勿重陈，怀君但愁绝。','',''),('quantangshi-10331','寄孟五少府','高適','quantangshi','','卷11','秋气落穷巷，离忧兼暮蝉。
后时已如此，高兴亦徒然。
知君念淹泊，忆我屡周旋。
征路见来雁，归人悲远天。
平生感千里，相望在贞坚。','',''),('quantangshi-10332','苦雨寄房四昆季','高適','quantangshi','','卷11','独坐见多雨，况兹兼索居。
茫茫十月交，穷阴千里余。
弥望无端倪，北风击林箊。
白日渺难覩，黄云争卷舒。
安得造化功，旷然一扫除。
滴沥檐宇愁，寥寥谈笑疎。
泥涂拥城郭，水潦盘丘墟。
惆怅悯田农，裴回伤里闾。
曾是力井税，曷为无斗储。
万事切中怀，十年思上书。
君门嗟缅邈，身计念居诸。
沈吟顾草茅，郁怏任盈虚。
黄鹄不可羡，鸡鸣时起予。
故人平台侧，高馆临通衢。
兄弟方荀陈，才华冠应徐。
弹棊自多暇，饮酒更何如。
知人想林宗，直道慙史鱼。
携手风流在，开襟鄙吝祛。
宁能访穷巷，相与对园蔬。','',''),('quantangshi-10333','和贺兰判官望北海作','高適','quantangshi','','卷11','圣代务平典，輶轩推上才。
迢遥溟海际，旷望沧波开。
四牡未遑息，三山安在哉。
巨鳌不可钓，高浪何崔嵬。
湛湛朝百谷，茫茫连九垓。
挹流纳广大，观异增迟廻。
日出见鱼目，月圆知蚌胎。
迹非想像到，心以精灵猜。
远色带孤屿，虚声涵殷雷。
风行越裳贡，水遏天吴灾。
揽辔隼将击，忘机鸥复来。
缘情韵骚雅，独立遗尘埃。
吏道竟殊用，翰林仍忝陪。
长鸣谢知己，所愧非龙媒。','',''),('quantangshi-10334','和崔二少府登楚丘城作','高適','quantangshi','','卷11','故人亦不遇，异县久栖托。
辛勤失路意，感叹登楼作。
清晨眺原野，独立穷寥廓。
云散芒砀山，水还睢阳郭。
绕梁即襟带，封卫多漂泊。
事古悲城池，年丰爱墟落。
相逢俱未展，携手空萧索。
何意千里心，仍求百金诺。
公侯皆我辈，动用在谋略。
圣心思贤才，朅来刈葵藿。','',''),('quantangshi-10335','酬司空璲少府','高適','quantangshi','','卷11','飘颻未得意，感激与谁论。
昨日遇夫子，仍欣吾道存。
江山满词赋，札翰起凉温。
吾见风雅作，人知德业尊。
惊飙荡万木，秋气屯高原。
燕赵何苍茫，鸿雁来翩翻。
此时与君别，握手欲无言。','',''),('quantangshi-10336','酬李少府','高適','quantangshi','','卷11','出塞魂屡惊，怀贤意难说。
谁知吾道间，乃在客中别。
日夕捧琼瑶，相思无休歇。
伊人虽薄宦，举代推高节。
述作凌江山，声华满冰雪。
一登蓟丘上，四顾何惨烈。
来雁无尽时，边风正骚屑。
将从崖谷遁，且与沈浮绝。
君若登青云，余当投魏阙。','',''),('quantangshi-10337','酬裴秀才','高適','quantangshi','','卷11','男儿贵得意，何必相知早。
飘荡与物永，踌跎觉年老。
长卿无产业，季子慙妻嫂。
此事难重陈，未于众人道。','',''),('quantangshi-10338','酬陆少府','高適','quantangshi','','卷11','朝临淇水岸，还望卫人邑。
别意在山阿，征途背原隰。
萧萧前村口，唯见转蓬入。
水渚人去迟，霜天雁飞急。
固应不远别，所与路未及。
欲济川上舟，相思空伫立。','',''),('quantangshi-10339','奉酬北海李太守丈人夏日平阴亭','高適','quantangshi','','卷11','天子股肱守，丈人山岳灵。
出身侍丹墀，举翮凌青冥。
当昔皇运否，人神俱未宁。
谏官莫敢议，酷吏方专刑。
谷永独言事，匡衡多引经。
两朝纳深衷，万乘无不听。
盛烈播南史，雄词豁东溟。
谁谓整隼旟，翻然忆柴扃。
寄书汶阳客，廻首平阴亭。
开封见千里，结念存百龄。
隐轸江山丽，氛氲兰茝馨。
自怜遇时休，漂泊随流萍。
春野变木德，夏天临火星。
一生徒羡鱼，四十犹聚萤。
从此日闲放，焉能怀拾青。','',''),('quantangshi-10340','酬马八效古见赠','高適','quantangshi','','卷11','深崖无绿竹，秀色徒氛氲。
时代种桃李，无人顾此君。
奈何冰雪操，尚与蒿莱羣。
愿托灵仙子，一声吹入云。','',''),('quantangshi-10341','酬鸿胪裴主簿雨后睢阳北楼见赠之作','高適','quantangshi','','卷11','暮霞照新晴，归云犹相逐。
有怀晨昏暇，相见登眺目。
问礼侍彤襜，题诗访茅屋。
高楼多古今，陈事满陵谷。
地久微子封，台余孝王筑。
裴回顾霄汉，豁达俯川陆。
远水对秋城，长天向乔木。
公门何清净，列戟森已肃。
不叹携手稀，恒思着鞭速。
终当拂羽翰，轻举随鸿鹄。','',''),('quantangshi-10342','酬裴员外以诗代书','高適','quantangshi','','卷11','少时方浩荡，遇物犹尘埃。
脱略身外事，交游天下才。
单车入燕赵，独立心悠哉。
宁知戎马间，忽展平生怀。
且欣清论高，岂顾夕阳颓。
题诗碣石馆，纵酒燕王台。
北望沙漠垂，漫天雪皑皑。
临边无策略，览古空裴回。
乐毅吾所怜，拔齐翻见猜。
荆卿吾所悲，适秦不复廻。
然诺多死地，公忠成祸胎。
与君从此辞，每恐流年催。
如何俱老大，始复忘形骸。
兄弟真二陆，声名连八裴。
乙未将星变，贼臣候天灾。
胡骑犯龙山，乘舆经马嵬。
千官无倚着，万姓徒悲哀。
诛吕鬼神动，安刘天地开。
奔波走风尘，倏忽值云雷。
拥旄出淮甸，入幕征楚材。
誓当剪鲸鲵，永以竭驽骀。
小人胡不仁，谗我成死灰。
赖得日月明，照耀无不该。
留司洛阳宫，詹府唯蒿莱。
是时扫氛祲，尚未歼渠魁。
背河列长围，师老将亦乖。
归军剧风火，散卒争椎埋。
一夕瀍洛空，生灵悲曝腮。
衣冠投草莽，予欲驰江淮。
登顿宛叶下，栖遑襄邓隈。
城池何萧条，邑屋更崩摧。
纵横荆棘丛，但见瓦砾堆。
行人无血色，战骨多青苔。
遂除彭门守，因得朝玉阶。
激昂仰鵷鹭，献替欣盐梅。
驱传及远蕃，忧思郁难排。
罢人纷争讼，赋税如山崖。
所思在畿甸，曾是鲁宓侪。
自从拜郎官，列宿焕天街。
那能访遐僻，还复寄琼瓌。
金玉本高价，埙箎终易谐。
朗咏临清秋，凉风下庭槐。
何意寇盗间，独称名义偕。
辛酸陈侯诔，叹息季鹰杯。
白日屡分手，青春不再来。
卧看中散论，愁忆太常斋。
酬赠徒为尔，长歌还自咍。','',''),('quantangshi-10343','酬庞十兵曹','高適','quantangshi','','卷11','忆昔游京华，自言生羽翼。
怀书访知己，末路空相识。
许国不成名，还家有慙色。
托身从𤱶亩，浪迹初自得。
雨泽感天时，耕耘忘帝力。
同人洛阳至，问我睢水北。
遂尔款津涯，净然见胸臆。
高谈悬物象，逸韵投翰墨。
别岸迥无垠，海鹤鸣不息。
梁城多古意，携手共凄恻。
怀贤想邹枚，登高思荆棘。
世情恶疵贱，之子怜孤直。
酬赠感并深，离忧岂终极。','',''),('quantangshi-10344','同吕员外酬田着作幕门军西宿盘山秋夜作','高適','quantangshi','','卷11','碛路天早秋，边城夜应永。
遥传戎旅作，已报关山冷。
上将顿盘阪，诸军徧泉井。
绸缪阃外书，慷慨幕中请。
能使勋业高，动令氛雾屏。
远途能自致，短步终难骋。
羽翮时一看，穷愁始三省。
人生感然诺，何啻若形影。
白发知苦心，阳春见佳境。
星河连塞络，刁斗兼山静。
忆君霜露时，使我空引领。','',''),('quantangshi-10345','酬祕书弟兼寄幕下诸公','高適','quantangshi','','卷11','亚相膺时杰，羣才遇良工。
翩翩幕下来，拜赐甘泉宫。
信知命世奇，适会非常功。
侍御执邦宪，清词焕春丛。
末路望绣衣，他时常发蒙。
孰云三军壮，惧我弹射雄。
谁谓万里遥，在我樽俎中。
光禄经济器，精微自深衷。
前席屡荣问，长城兼在躬。
高纵激颓波，逸翮驰苍穹。
将副节制筹，欲令沙漠空。
司业志应徐，雅度思冲融。
相思三十年，忆昨犹儿童。
今来抱青紫，忽若披鵷鸿。
说劒增慷慨，论交持始终。
祕书即吾门，虚白无不通。
多才陆平原，硕学郑司农。
献封到关西，独步归山东。
永意久知处，嘉言能亢宗。
客从梁宋来，行役随转蓬。
酬赠欣元弟，忆贤瞻数公。
游鳞戏沧浪，鸣凤栖梧桐。
并负垂天翼，俱乘破浪风。
眈眈天府间，偃仰谁敢同。
何意构广厦，翻然顾雕虫。
应知阮步兵，惆怅此途穷。','',''),('quantangshi-10346','淇上酬薛三据兼寄郭少府微','高適','quantangshi','','卷11','自从别京华，我心乃萧索。
十年守章句，万事空寥落。
北上登蓟门，茫茫见沙漠。
倚劒对风尘，慨然思卫霍。
拂衣去燕赵，驱马怅不乐。
天长沧洲路，日暮邯郸郭。
酒肆或淹留，渔潭屡栖泊。
独行备艰险，所见穷善恶。
永愿拯刍荛，孰云干鼎镬。
皇情念淳古，时俗何浮薄。
理道资任贤，安人在求瘼。
故交负灵奇，逸气抱謇谔。
隐轸经济具，纵横建安作。
才望忽先鸣，风期无宿诺。
飘颻劳州县，迢递限言谑。
东驰眇贝丘，西顾弥虢略。
淇水徒自流，浮云不堪托。
吾谋适可用，天路岂寥廓。
不然买山田，一身与耕凿。
且欲同鹪鹩，焉能志鸿鹄。','',''),('quantangshi-10347','酬岑二十主簿秋夜见赠之作','高適','quantangshi','','卷11','舍下蛩乱鸣，居然自萧索。
缅怀高秋兴，忽枉清夜作。
感物我心劳，凉风惊二毛。
池枯菡萏死，月出梧桐高。
如何异乡县，复得交才彦。
汨没嗟后时，蹉跎耻相见。
箕山别来久，魏阙谁不恋。
独有江海心，悠悠未尝倦。','',''),('quantangshi-10348','答侯少府','高適','quantangshi','','卷11','常日好读书，晚年学垂纶。
漆园多乔木，睢水清粼粼。
诏书下柴门，天命敢逡巡。
赫赫三伏时，十日到咸秦。
褐衣不得见，黄绶翻在身。
吏道顿羁束，生涯难重陈。
北使经大寒，关山饶苦辛。
边兵若刍狗，战骨成埃尘。
行矣勿复言，归欤伤我神。
如何燕赵陲，忽遇平生亲。
开馆纳征骑，弹弦娱远宾。
飘颻天地间，一别方兹晨。
东道有佳作，南朝无此人。
性灵出万象，风骨超常伦。
吾党谢王粲，羣贤推郄诜。
明时取秀才，落日过蒲津。
节苦名已富，禄微家转贫。
相逢愧薄游，抚己荷陶钧。
心事正堪尽，离居宁太频。
两河归路遥，二月芳草新。
柳接滹沱暗，莺连渤海春。
谁谓行路难，猥当希代珍。
提握每终日，相思犹比邻。
江海有扁舟，丘园有角巾。
君意定何适，我怀知所遵。
浮沈各异宜，老大贵全真。
莫作云霄计，遑遑随缙绅。','',''),('quantangshi-10349','宋中别周梁李三子','高適','quantangshi','','卷11','曾是不得意，适来兼别离。
如何一尊酒，翻作满堂悲。
周子负高价，梁生多逸词。
周旋梁宋间，感激建安时。
白雪正如此，青云无自疑。
李侯怀英雄，肮脏乃天资。
方寸且无间，衣冠当在斯。
俱为千里游，忽念两乡辞。
且见壮心在，莫嗟携手迟。
凉风吹北原，落日满西陂。
露下草初白，天长云屡滋。
我心不可问，君去定何之。
京洛多知己，谁能忆左思。','',''),('quantangshi-10350','宋中别李八','高適','quantangshi','','卷11','岁晏谁不归，君归意可说。
将趋倚门望，还念同人别。
驻马临长亭，飘然事明发。
苍茫眺千里，正值苦寒节。
旧国多转蓬，平台下明月。
世情薄疵贱，夫子怀贤哲。
行矣各勉旃，吾当挹余烈。','',''),('quantangshi-10351','别王彻','高適','quantangshi','','卷11','归客自南楚，怅然思北林。
萧条秋风暮，廻首江淮深。
留君终日欢，或为梁父吟。
时辈想鹏举，他人嗟陆沈。
载酒登平台，赠君千里心。
浮云暗长路，落日有归禽。
离别未足悲，辛勤当自任。
吾知十年后，季子多黄金。','',''),('quantangshi-10352','送萧十八与房侍御廻还','高適','quantangshi','','卷11','常苦古人远，今见斯人古。
澹泊遗声华，周旋必邹鲁。
故交在梁宋，游方出庭户。
匹马鸣朔风，一身济河浒。
辛勤采兰咏，款曲翰林主。
岁月催别离，庭围远风土。
寥寥寒烟静，莽莽夕阴吐。
明发不在兹，青天眇难覩。','',''),('quantangshi-10353','宋中送族侄式颜','高適','quantangshi','','卷11','大夫击东胡，胡尘不敢起。
胡人山下哭，胡马海边死。
部曲尽公侯，舆台亦朱紫。
当时有勋业，末路遭谗毁。
转斾燕赵间，剖符括苍里。
弟兄莫相见，亲族远枌梓。
不改青云心，仍招布衣士。
平生怀感激，本欲候知己。
去矣难重陈，飘然自兹始。
游梁且未遇，适越今何以。
乡山西北愁，竹箭东南美。
峥嵘缙云外，苍莽几千里。
旅雁悲啾啾，朝昏孰云已。
登临多瘴疠，动息在风水。
虽有贤主人，终为客行子。
我携一尊酒，满酌聊劝尔。
劝尔惟一言，家声勿沦滓。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-10354','又送族侄式颜','高適','quantangshi','','卷11','惜君才未遇，爱君才若此。
世上五百年，吾家一千里。
俱游帝城下，忽在梁园里。
我今行山东，离忧不能已。','',''),('quantangshi-10355','赠别王十七管记','高適','quantangshi','','卷11','故交吾未测，薄宦空年岁。
晚节踪曩贤，雄词冠当世。
堂中皆食客，门外多酒债。
产业曾未言，衣裘与人敝。
飘颻戎幕下，出入关山际。
转战轻壮心，立谈有边计。
云沙自廻合，天海空迢递。
星高汉将骄，月盛胡兵锐。
沙深冷陉断，雪暗辽阳闭。
亦谓扫欃枪，旋惊陷蜂虿。
归旌告东捷，鬬骑传西败。
遥飞绝汉书，已筑长安第。
画龙俱在叶，宠鹤先居卫。
勿辞部曲勋，不藉将军势。
相逢季冬月，伥望穷海裔。
折劒留赠人，严装遂云迈。
我行将悠𥾝，及此还羁滞。
曾非济代谋，且有临深诫。
随波混清浊，与物同丑丽。
眇忆青岩栖，宁忘褐衣拜。
自言爱水石，本欲亲兰蕙。
何意薄松筠，翻然重菅蒯。
恒深取与分，孰慢平生契。
欵曲鸡黍期，酸辛别离袂。
逢时愧名节，遇坎悲沦替。
适赵非解纷，游燕往无说。
浩歌方振荡，逸翮思凌励。
倏若异鹏抟，吾当学蝉蜕。','',''),('quantangshi-10356','涟上别王秀才','高適','quantangshi','','卷11','飘颻经远道，客思满穷秋。
浩荡对长涟，君行殊未休。
崎岖山海侧，想像无前俦。
何意照乘珠，忽然欲暗投。
东路方萧条，楚歌复悲愁。
暮帆使人感，去鸟兼离忧。
行矣当自爱，壮年莫悠悠。
余亦从此辞，异乡难久留。
赠言岂终极，慎勿滞沧洲。','',''),('quantangshi-10357','赠别沈四逸人','高適','quantangshi','','卷11','沈侯未可测，其况信浮沈。
十载常独坐，几人知此心。
乘舟蹈沧海，买劒投黄金。
世务不足烦，有田西山岑。
我来遇知己，遂得开清襟。
何意阃阈间，沛然江海深。
疾风扫秋树，濮上多鸣砧。
耿耿尊酒前，联雁飞愁音。
平生重离别，感激对孤琴。','',''),('quantangshi-10358','送韩九','高適','quantangshi','','卷11','惆怅别离日，裴回岐路前。
归人望独树，匹马随秋蝉。
常与天下士，许君兄弟贤。
良时正可用，行矣莫徒然。','',''),('quantangshi-10359','送崔录事赴宣城','高適','quantangshi','','卷11','大国非不理，小官皆用才。
欲行宣城印，住饮洛阳杯。
晚景为人别，长天无鸟廻。
举帆风波渺，倚棹江山来。
羡尔兼乘兴，芜湖千里开。','',''),('quantangshi-10360','别张少府','高適','quantangshi','','卷11','归客留不住，朝云纵复横。
马头向春草，斗柄临高城。
嗟我久离别，羡君看弟兄。
归心更难道，回首一伤情。','',''),('quantangshi-10361','淇上别刘少府子英','高適','quantangshi','','卷11','近来住淇上，萧条惟空林。
又非耕种时，闲散多自任。
伊君独知我，驱马欲招寻。
千里忽携手，十年同苦心。
求仁见交态，于道喜甘临。
逸思乃天纵，微才应陆沈。
飘然归故乡，不复问离襟。
南登黎阳渡，莽苍寒云阴。
桑叶原上起，河淩山下深。
途穷更远别，相对益悲吟。','',''),('quantangshi-10362','别耿都尉','高適','quantangshi','','卷11','四十能学劒，时人无此心。
如何耿夫子，感激投知音。
翩翩白马来，二月青草深。
别易小千里，兴酣倾百金。','',''),('quantangshi-10363','宋中遇林卢杨十七山人因而有别','高適','quantangshi','','卷11','昔余涉漳水，驱车行邺西。
遥见林虑山，苍苍戛天倪。
邂逅逢尔曹，说君彼岩栖。
萝径垂野蔓，石房倚云梯。
秋韭何青青，药苗数百畦。
栗林隘谷口，栝树森廻溪。
耕耘有山田，纺绩有山妻。
人生苟如此，何必组与圭。
谁谓远相访，曩情殊不迷。
檐前举醇醪，竈下烹双鸡。
朔风忽振荡，昨夜寒螿啼。
游子益思归，罢琴伤解携。
出门尽原野，白日黯已低。
始惊道路难，终念言笑暌。
因声谢岑壑，岁暮一攀跻。','',''),('quantangshi-10364','酬别薛三蔡大留简韩十四主簿','高適','quantangshi','','卷11','迢递辞京华，辛勤异乡县。
登高俯沧海，廻首泪如霰。
同人久离别，失路还相见。
薛侯怀直道，德业应时选。
蔡子负清才，当年擢宾荐。
韩公有奇节，词赋凌羣彦。
读书嵩岑间，作吏沧海甸。
伊余寡栖托，感激多愠见。
纵诞非尔情，飘沦任疵贱。
忽枉琼瑶作，乃深平生眷。
始谓吾道存，终嗟客游倦。
归心无昼夜，别事除言宴。
复值凉风时，苍茫夏云变。','',''),('quantangshi-10365','送虞城刘明府谒魏郡苗太守','高適','quantangshi','','卷11','天官苍生望，出入承明庐。
肃肃领旧藩，皇皇降玺书。
茂宰多感激，良将复吹嘘。
永怀一言合，谁谓千里疎。
对酒忽命驾，兹情何起予。
炎天昼如火，极目无行车。
长路出雷泽，浮云归孟诸。
魏郡十万家，歌钟喧里闾。
传道贤君至，闭关常晏如。
君将挹高论，定是问樵渔。
今日逢明圣，吾为陶隐居。','',''),('quantangshi-10366','途中酬李少府赠别之作','高適','quantangshi','','卷11','西上逢节换，东征私自怜。
故人今卧疾，欲别还留连。
举酒临南轩，夕阳满中筵。
宁知江上兴，乃在河梁偏。
行李多光辉，札翰忽相鲜。
谁谓岁月晚，交情尚贞坚。
终嗟州县劳，官谤复迍邅。
虽负忠信美，其如方寸悬。
连帅扇清风，千里犹眼前。
曾是趋藻镜，不应翻弃捐。
日来知自强，风气殊未痊。
可以加药物，胡为輙忧煎。
驱马出大梁，原野一悠然。
柳色感行客，云阴愁远天。
皇明烛幽遐，德泽普照宣。
鵷鸿列霄汉，燕雀何翩翩。
余亦惬所从，渔樵十二年。
种瓜漆园里，凿井卢门边。
去去勿重陈，生涯难勉旃。
或期遇春事，与尔复周旋。
投报空回首，狂歌谢比肩。','',''),('quantangshi-10367','睢阳酬别畅大判官','高適','quantangshi','','卷11','吾友遇知己，策名逢圣朝。
高才擅白雪，逸翰怀青霄。
承诏选嘉宾，慨然即驰轺。
清昼下公馆，尺书忽相邀。
留欢惜别离，毕景驻行镳。
言及沙漠事，益令胡马骄。
丈夫拔东蕃，声冠霍嫖姚。
兜鍪冲矢石，铁甲生风飙。
诸将出冷陉，连营济石桥。
酋豪尽俘馘，子弟输征徭。
边庭绝刁斗，战地成渔樵。
榆关夜不扃，塞口长萧萧。
降胡满蓟门，一一能射雕。
军中多宴乐，马上何轻趫。
戎狄本无厌，羇縻非一朝。
饥附诚足用，饱飞安可招。
李牧制儋蓝，遗风岂寂寥。
君还谢幕府，慎勿轻刍荛。','',''),('quantangshi-10368','宴韦司户山亭院','高適','quantangshi','','卷11','人幽想灵山，意惬怜远水。
习静务为适，所居还复尔。
汲流涨华池，开酌宴君子。
苔迳试窥践，石屏可攀倚。
入门见中峰，携手如万里。
横琴了无事，垂钓应有以。
高馆何沈沈，飒然凉风起。','',''),('quantangshi-10369','同诸公登慈恩寺浮图','高適','quantangshi','','卷11','香界泯羣有，浮图岂诸相。
登临骇孤高，披拂欣大壮。
言是羽翼生，迥出虚空上。
顿疑身世别，乃觉形神王。
宫阙皆户前，山河尽檐向。
秋风昨夜至，秦塞多清旷。
千里何苍苍，五陵郁相望。
盛时慙阮步，末宦知周防。
输效独无因，斯焉可游放。','',''),('quantangshi-10370','同薛司直诸公秋霁曲江俯见南山作','高適','quantangshi','','卷11','南山郁初霁，曲江湛不流。
若临瑶池前，想望昆仑丘。
廻首见黛色，眇然波上秋。
深沈俯峥嵘，清浅延阻修。
连潭万木影，插岸千岩幽。
杳霭信难测，渊沦无暗投。
片云对渔父，独鸟随虚舟。
我心寄青霞，世事慙白鸥。
得意在乘兴，忘怀非外求。
良辰自多暇，欣与数子游。','',''),('quantangshi-10371','登广陵栖灵寺塔','高適','quantangshi','','卷11','淮南富登临，兹塔信奇最。
直上造云族，凭虚纳天籁。
迥然碧海西，独立飞鸟外。
始知高兴尽，适与赏心会。
连山黯吴门，乔木吞楚塞。
城池满窗下，物象归掌内。
远思驻江帆，暮时结春霭。
轩车疑蠢动，造化资大块。
何必了无身，然后知所退。','',''),('quantangshi-10372','登百丈峰二首 一','高適','quantangshi','','卷11','朝登百丈峰，遥望燕支道。
汉垒青冥间，胡天白如扫。
忆昔霍将军，连年此征讨。
匈奴终不灭，寒山徒草草。
唯见鸿雁飞，令人伤怀抱。','',''),('quantangshi-10373','登百丈峰二首 二','高適','quantangshi','','卷11','晋武轻后事，惠皇终已昏。
豺狼塞瀍洛，胡羯争干坤。
四海如鼎沸，五原徒自尊。
而今白庭路，犹对青阳门。
朝市不足问，君臣随草根。','',''),('quantangshi-10374','同羣公秋登琴台','高適','quantangshi','','卷11','古迹使人感，琴台空寂寥。
静然顾遗尘，千载如昨朝。
临眺自兹始，羣贤久相邀。
德与形神高，孰知天地遥。
四时何倏忽，六月鸣秋蜩。
万象归白帝，平川横赤霄。
犹是对夏伏，几时有凉飙。
燕雀满檐楹，鸿鹄抟扶摇。
物性各自得，我心在渔樵。
兀然还复醉，尚握尊中瓢。','',''),('quantangshi-10375','同羣公出猎海上','高適','quantangshi','','卷11','畋猎自古昔，况伊心赏俱。
偶与羣公游，旷然出平芜。
层阴涨溟海，杀气穷幽都。
鹰隼何翩翩，驰骤相传呼。
豺狼窜榛莽，麋鹿罹艰虞。
高鸟下騂弓，困兽鬬匹夫。
尘惊大泽晦，火燎深林枯。
失之有余恨，获者无全躯。
咄彼工拙间，恨非指踪徒。
犹怀老氏训，感叹此欢娱。','',''),('quantangshi-10376','同羣公题郑少府田家','高適','quantangshi','','卷11','郑侯应凄惶，五十头尽白。
昔为南昌尉，今作东郡客。
与语多远情，论心知所益。
秋林既清旷，穷巷空淅沥。
蝶舞园更闲，鸡鸣日云夕。
男儿未称意，其道固无适。
劝君且杜门，勿叹人事隔。','',''),('quantangshi-10377','同羣公题中山寺','高適','quantangshi','','卷11','平原十里外，稍稍云岩深。
遂及清净所，都无人世心。
名僧既礼谒，高阁复登临。
石壁倚松径，山田多栗林。
超遥尽巘崿，逼侧仍岖嵚。
吾欲休世事，于焉聊自任。','',''),('quantangshi-10378','同羣公宿开善寺赠陈十六所居','高適','quantangshi','','卷11','驾车出人境，避暑投僧家。
裴回龙象侧，始见香林花。
读书不及经，饮酒不胜茶。
知君悟此道，所未搜袈裟。
谈空忘外物，持诫破诸邪。
则是无心地，相看唯月华。','',''),('quantangshi-10379','同韩四薛三东亭翫月','高適','quantangshi','','卷11','远游怅不乐，兹赏吾道存。
款曲故人意，辛勤清夜言。
东亭何寥寥，佳境无朝昏。
堦墀近洲渚，户牖当郊原。
矧乃穷周旋，游时怡讨论。
树阴荡瑶瑟，月气延清尊。
明河带飞雁，野火连荒村。
对此更愁予，悠哉怀故园。','',''),('quantangshi-10380','同敬八卢五泛河间清河','高適','quantangshi','','卷11','清川在城下，沿泛多所宜。
同济惬数公，翫物欣良时。
飘颻波上兴，燕婉舟中词。
昔陟乃平原，今来忽涟漪。
东流达沧海，西流延滹池。
云树共晦明，井邑相逶迤。
稍随归月帆，若与沙鸥期。
渔父更留我，前潭水未滋。','',''),('quantangshi-10381','同房侍御山园新亭与邢判官同游','高適','quantangshi','','卷11','隐隐春城外，朦胧陈迹深。
君子顾榛莽，兴言伤古今。
决河导新流，疏迳踪旧林。
开亭俯川陆，时景宜招寻。
肃穆逢使轩，夤缘事登临。
忝游芝兰室，还对桃李阴。
岸远白波来，气喧黄鸟吟。
因睹歌颂作，始知经济心。
灌坛有遗风，单父多鸣琴。
谁为久州县，苍生怀德音。','',''),('quantangshi-10382','同马太守听九思法师讲金刚经','高適','quantangshi','','卷11','吾师晋阳宝，杰出山河最。
途经世谛间，心到空王外。
鸣钟山虎伏，说法天龙会。
了义同建瓴，梵法若吹籁。
深知亿劫苦，善喻恒沙大。
舍施割肌肤，攀缘去亲爱。
招提何清净，良牧驻轻盖。
露冕众香中，临人觉苑内。
心持佛印久，标割魔军退。
愿开初地因，永奉弥天对。','',''),('quantangshi-10383','涟上题樊氏水亭','高適','quantangshi','','卷11','涟上非所趣，偶为世务牵。
经时驻归棹，日夕对平川。
莫论行子愁，且得主人贤。
亭上酒初熟，厨中鱼每鲜。
自说宦游来，因之居住偏。
煮盐沧海曲，种稻长淮边。
四时常晏如，百口无饥年。
菱芋藩篱下，渔樵耳目前。
异县少朋从，我行复迍邅。
向不逢此君，孤舟已言旋。
明日又分首，风涛还眇然。','',''),('quantangshi-10384','同吕判官从哥舒大夫破洪济城廻登积石军多福七级浮图','高適','quantangshi','','卷11','塞口连浊河，辕门对山寺。
宁知鞍马上，独有登临事。
七级凌太清，千崖列苍翠。
飘飘方寓目，想像见深意。
高兴殊未平，凉风飒然至。
拔城阵云合，转斾胡星坠。
大将何英灵，官军动天地。
君怀生羽翼，本欲附骐骥。
款段苦不前，清冥信难致。
一歌阳春后，三叹终自愧。','',''),('quantangshi-10385','三君咏 魏郑公','高適','quantangshi','','卷11','郑公经纶日，隋氏风尘昏。
济代取高位，逢时敢直言。
道光先帝业，义激旧君恩。
寂寞卧龙处，英灵千载魂。','',''),('quantangshi-10386','三君咏 郭代公','高適','quantangshi','','卷11','代公实英迈，津涯浩难识。
拥兵抗矫征，仗节归有德。
纵横负才智，顾盻安社稷。
流落勿重陈，怀哉为凄恻。','',''),('quantangshi-10387','三君咏 狄梁公','高適','quantangshi','','卷11','梁公乃贞固，勋烈垂竹帛。
昌言太后朝，潜运储君策。
待贤开相府，共理登方伯。
至今青云人，犹是门下客。','',''),('quantangshi-10388','宓公琴台诗三首 一','高適','quantangshi','','卷11','宓子昔为政，鸣琴登此台。
琴和人亦闲，千载称其才。
临眺忽凄怆，人琴安在哉？
悠悠此天壤，唯有颂声来。','',''),('quantangshi-10389','宓公琴台诗三首 二','高適','quantangshi','','卷11','邦伯感遗事，慨然建琴堂。
乃知静者心，千载犹相望。
入室想其人，出门何茫茫。
唯见白云合，东临邹鲁乡。','',''),('quantangshi-10390','宓公琴台诗三首 三','高適','quantangshi','','卷11','皤皤邑中老，自夸邑中理。
何必升君堂，然后知君美。
开门无犬吠，早卧常晏起。
昔人不忍欺，今我还复尔。','',''),('quantangshi-10391','李云南征蛮诗','高適','quantangshi','','卷11','圣人赫斯怒，诏伐西南戎。
肃穆庙堂上，深沈节制雄。
遂令感激士，得建非常功。
料死不料敌，顾恩宁顾终。
鼓行天海外，转战蛮夷中。
梯巘近高鸟，穿林经毒虫。
鬼门无归客，北户多南风。
蜂虿隔万里，云雷随九攻。
长驱大浪破，急击羣山空。
饷道忽已远，悬军垂欲穷。
精诚动白日，愤薄连苍穹。
野食掘田鼠，晡餐兼僰僮。
收兵列亭堠，拓地弥西东。
临事耻苟免，履危能饬躬。
将星独照耀，边色何溟蒙。
泸水夜可涉，交州今始通。
归来长安道，召见甘泉宫。
廉蔺若未死，孙吴知暗同。
相逢论意气，慷慨谢深衷。','',''),('quantangshi-10392','题尉迟将军新庙','高適','quantangshi','','卷11','周室既板荡，贼臣立婴儿。
将军独激昂，誓欲酬恩私。
孤城日无援，高节终可悲。
家国共沦亡，精魂空在斯。
沈沈积冤气，寂寂无人知。
良牧怀深仁，与君建明祠。
父子俱血食，轩车每逶迤。
我来荐苹蘩，感叹兴此词。
晨光上阶闼，杀气翻旌旗。
明明幽冥理，至诚信莫欺。
唯夫二千石，多庆方自兹。','',''),('quantangshi-10393','观李九少府翥树宓子贱神祠碑','高適','quantangshi','','卷11','吾友吏兹邑，亦尝怀宓公。
安知梦寐间，忽与精灵通。
一见兴永叹，再来激深衷。
宾从何逶迤，二十四老翁。
于焉建层碑，突兀长林东。
作者无愧色，行人感遗风。
坐令高岸尽，独对秋山空。
片石勿谓轻，斯言固难穷。
龙盘色丝外，鹊顾偃波中。
形胜驻羣目，坚贞指苍穹。
我非王仲宣，去矣徒发蒙。','',''),('quantangshi-10394','同观陈十六史兴碑','高適','quantangshi','','卷11','荆衡气偏秀，江汉流不歇。
此地多精灵，有时生才杰。
伊人今独步，逸思能间发。
永怀掩风骚，千载常矻矻。
新碑亦崔嵬，佳句悬日月。
则是刊石经，终然继檮杌。
我来观雅制，慷慨变毛发。
季主尽荒淫，前王徒贻厥。
东周既削弱，两汉更沦没。
西晋何披猖，五胡相唐突。
作歌乃彰善，比物仍恶讦。
感叹将谓谁，对之空咄咄。','',''),('quantangshi-10395','宋中十首 一','高適','quantangshi','','卷11','梁王昔全盛，宾客复多才。
悠悠一千年，陈迹唯高台。
寂寞向秋草，悲风千里来。','',''),('quantangshi-10396','宋中十首 二','高適','quantangshi','','卷11','朝临孟诸上，忽见芒砀间。
赤帝终已矣，白云长不还。
时清更何有，禾黍徧空山。','',''),('quantangshi-10397','宋中十首 三','高適','quantangshi','','卷11','景公德何广，临变莫能欺。
三请皆不忍，妖星终自移。
君心本如此，天道岂无知。','',''),('quantangshi-10398','宋中十首 四','高適','quantangshi','','卷11','梁苑白日暮，梁山秋草时。
君王不可见，修竹令人悲。
九月桑叶尽，寒风鸣树枝。','',''),('quantangshi-10399','宋中十首 五','高適','quantangshi','','卷11','登高临旧国，怀古对穷秋。
落日鸿雁度，寒城砧杵愁。
昔贤不复有，行矣莫淹留。','',''),('quantangshi-10400','宋中十首 六','高適','quantangshi','','卷11','出门望终古，独立悲且歌。
忆昔鲁仲尼，凄凄此经过。
众人不可向，伐树将如何。','',''),('quantangshi-10401','宋中十首 七','高適','quantangshi','','卷11','逍遥漆园吏，冥没不知年。
世事浮云外，闲居大道边。
古来同一马，今我亦忘筌。','',''),('quantangshi-10402','宋中十首 八','高適','quantangshi','','卷11','五霸递征伐，宋人无战功。
解围幸奇说，易子伤吾衷。
唯见卢门外，萧条多转蓬。','',''),('quantangshi-10403','宋中十首 九','高適','quantangshi','','卷11','常爱宓子贱，鸣琴能自亲。
邑中静无事，岂不由其身。
何意千年后，寂寞无此人。','',''),('quantangshi-10404','宋中十首 十','高適','quantangshi','','卷11','阏伯去已久，高丘临道傍。
人皆有兄弟，尔独为参商。
终古犹如此，而今安可量。','',''),('quantangshi-10405','蓟中作','高適','quantangshi','','卷11','策马自沙漠，长驱登塞垣。
边城何萧条，白日黄云昏。
一到征战处，每愁胡虏翻。
岂无安边书，诸将已承恩。
惆怅孙吴事，归来独闭门。','',''),('quantangshi-10406','自淇涉黄河途中作十三首 一','高適','quantangshi','','卷11','川上常极目，世情今已闲。
去帆带落日，征路随长山。
亲友若云霄，可望不可攀。
于兹任所惬，浩荡风波间。','',''),('quantangshi-10407','自淇涉黄河途中作十三首 二','高適','quantangshi','','卷11','清晨泛中流，羽族满汀渚。
黄鹄何处来，昂藏寡俦侣。
飞鸣无人见，饮啄岂得所。
云汉尔固知，胡为不轻举。','',''),('quantangshi-10408','自淇涉黄河途中作十三首 三','高適','quantangshi','','卷11','野人头尽白，与我忽相访。
手持青竹竿，日暮淇水上。
虽老美容色，虽贫亦闲放。
钓鱼三十年，中心无所向。','',''),('quantangshi-10409','自淇涉黄河途中作十三首 四','高適','quantangshi','','卷11','南登滑台上，却望河淇间。
竹树夹流水，孤城对远山。
念兹川路阔，羡尔沙鸥闲。
长想别离处，犹无音信还。','',''),('quantangshi-10410','自淇涉黄河途中作十三首 五','高適','quantangshi','','卷11','东入黄河水，茫茫泛纡直。
北望太行山，峨峨半天色。
山河相暎带，深浅未可测。
自昔有贤才，相逢不相识。','',''),('quantangshi-10411','自淇涉黄河途中作十三首 六','高適','quantangshi','','卷11','秋日登滑台，台高秋已暮。
独行既未惬，怀土怅无趣。
晋宋何萧条，羌胡散驰骛。
当时无战略，此地即边戍。
兵革徒自勤，山河孰云固。
乘闲喜临眺，感物伤游寓。
惆怅落日前，飘颻远帆处。
北风吹万里，南雁不知数。
归意方浩然，云沙更廻互。','',''),('quantangshi-10412','自淇涉黄河途中作十三首 七','高適','quantangshi','','卷11','乱流自兹远，倚檝时一望。
遥见楚汉城，崔嵬高山上。
天道昔未测，人心无所向。
屠钓称侯王，龙蛇争霸王。
缅怀多杀戮，顾此生惨怆。
圣代休甲兵，吾其得闲放。','',''),('quantangshi-10413','自淇涉黄河途中作十三首 八','高適','quantangshi','','卷11','兹川方悠邈，云沙无前后。
古堰对河壖，长林出淇口。
独行非吾意，东向日已久。
忧来谁得知，且酌尊中酒。','',''),('quantangshi-10414','自淇涉黄河途中作十三首 九','高適','quantangshi','','卷11','朝从北岸来，泊船南河浒。
试共野人言，深觉农夫苦。
去秋虽薄熟，今夏犹未雨。
耕耘日勤劳，租税兼舃卤。
园蔬空寥落，产业不足数。
尚有献芹心，无因见明主。','',''),('quantangshi-10415','自淇涉黄河途中作十三首 十','高適','quantangshi','','卷11','茫茫浊河注，怀古临河滨。
禹功本豁达，汉迹方因循。
坎德昔滂沱，冯夷胡不仁。
激潏陵堤防，东郡多悲辛。
天子忽惊悼，从官皆负薪。
畚筑岂无谋，祈祷如有神。
宣房今安在，高岸空嶙峋。','',''),('quantangshi-10416','自淇涉黄河途中作十三首 十一','高適','quantangshi','','卷11','我行倦风湍，辍棹将问津。
空传歌瓠子，感慨独愁人。
孟夏桑叶肥，穠阴夹长津。
蚕农有时节，田野无闲人。
临水狎渔樵，望山怀隐沦。
谁能去京洛，顦顇对风尘。','',''),('quantangshi-10417','自淇涉黄河途中作十三首 十二','高適','quantangshi','','卷11','朝景入平川，川长复垂柳。
遥看魏公墓，突兀前山后。
忆昔大业时，羣雄角奔走。
伊人何电迈，独立风尘首。
传檄举敖仓，拥兵屯洛口。
连营一百万，六合如可有。
方项终比肩，乱隋将假手。
力争固难恃，骄战曷能久。
若使学萧曹，功名当不朽。','',''),('quantangshi-10418','自淇涉黄河途中作十三首 十三','高適','quantangshi','','卷11','皤皤河滨叟，相遇似有耻。
辍榜聊问之，答言尽终结。
一生虽贫贱，九十年未死。
且喜对儿孙，弥慙远城市。
结庐黄河曲，垂钓长河里。
漫漫望云沙，萧条听风水。
所思强饭食，永愿在乡里。
万事吾不知，其心只如此。','',''),('quantangshi-10419','宋中遇陈二','高適','quantangshi','','卷11','常忝鲍叔义，所期王佐才。
如何守苦节，独此无良媒。
离别十年外，飘颻千里来。
安知罢官后，惟见柴门开。
穷巷隐东郭，高堂咏南陔。
篱根长花草，井上生莓苔。
伊昔望霄汉，于今倦蒿莱。
男儿命未达，且尽手中杯。','',''),('quantangshi-10420','宋中遇刘书记有别','高適','quantangshi','','卷11','何代无秀士，高门生此才。
森然覩毛发，若见河山来。
几载困常调，一朝时运催。
白身谒明主，待诏登云台。
相逢梁宋间，与我醉蒿莱。
寒楚眇千里，雪天昼不开。
末路终离别，不能强悲哀。
男儿争富贵，劝尔莫迟廻。','',''),('quantangshi-10421','鲁郡途中遇徐十八录事','高適','quantangshi','','卷11','谁谓嵩颍客，遂经邹鲁乡。
前临少昊墟，始觉东蒙长。
独行岂吾心，怀古激中肠。
圣人久已矣，游夏遥相望。
裴回野泽间，左右多悲伤。
日出见阙里，川平知汶阳。
弱冠负高节，十年思自强。
终然不得意，去去任行藏。','',''),('quantangshi-10422','遇冲和先生','高適','quantangshi','','卷11','冲和生何代，或谓游东溟。
三命谒金殿，一言拜银青。
自云多方术，往往通神灵。
万乘亲问道，六宫无敢听。
昔去限霄汉，今来覩仪形。
头戴鹖鸟冠，手遥白鹤翎。
终日饮醇酒，不醉复不醒。
常忆鸡鸣山，每诵西升经。
拊背念离别，依然出户庭。
莫见今如此，曾为一客星。','',''),('quantangshi-10423','鲁西至东平','高適','quantangshi','','卷11','沙岸拍不定，石桥水横流。
问津见鲁俗，怀古伤家丘。
寥落千载后，空传褒圣侯。','',''),('quantangshi-10424','东平路作三首 一','高適','quantangshi','','卷11','南图适不就，东走岂吾心。
索索凉风动，行行秋水深。
蝉鸣木叶落，兹夕更愁霖。','',''),('quantangshi-10425','东平路作三首 二','高適','quantangshi','','卷11','明时好画策，动欲干王公。
今日无成事，依依亲老农。
扁舟向何处？吾爱汶阳中。','',''),('quantangshi-10426','东平路作三首 三','高適','quantangshi','','卷11','清旷凉夜月，裴回孤客舟。
渺然风波上，独爱前山秋。
秋至复摇落，空令行者愁。','',''),('quantangshi-10427','东平路中遇大水','高適','quantangshi','','卷11','天灾自古有，昏垫弥今秋。
霖霪溢川原，澒洞涵田畴。
指途适汶阳，挂席经芦洲。
永望齐鲁郊，白云何悠悠。
傍沿钜野泽，大水纵横流。
虫蛇拥独树，麋鹿奔行舟。
稼穑随波澜，西成不可求。
室居相枕藉，蛙黾声啾啾。
仍怜穴蚁漂，益羡云禽游。
农夫无倚着，野老生殷忧。
圣主当深仁，庙堂运良筹。
仓廪终尔给，田租应罢收。
我心胡郁陶，征旅亦悲愁。
纵怀济时策，谁肯论吾谋。','',''),('quantangshi-10428','登壠','高適','quantangshi','','卷11','壠头远行客，壠上分流水。
流水无尽期，行人未云已。
浅才登一命，孤劒通万里。
岂不思故乡，从来感知己。','',''),('quantangshi-10429','苦雪四首 一','高適','quantangshi','','卷11','二月犹北风，天阴雪冥冥。
寥落一室中，怅然慙百龄。
苦愁正如此，门柳复青青。','',''),('quantangshi-10430','苦雪四首 二','高適','quantangshi','','卷11','惠连发清兴，袁安念高卧。
余故非斯人，为性兼懒惰。
赖兹尊中酒，终日聊自过。','',''),('quantangshi-10431','苦雪四首 三','高適','quantangshi','','卷11','蒙蒙洒平陆，淅沥至幽居。
且喜润羣物，焉能悲斗储。
故交久不见，鸟雀投吾庐。','',''),('quantangshi-10432','苦雪四首 四','高適','quantangshi','','卷11','孰云久闲旷，本自保知寡。
穷巷独无成，春条秪盈把。
安能羡鹏举，且欲歌牛下。
乃知古时人，亦有如我者。','',''),('quantangshi-10433','哭单父梁九少府','高適','quantangshi','','卷11','开箧泪沾臆，见君前日书。
夜台今寂寞，独是子云居。
畴昔探云奇，登临赋山水。
同舟南浦下，望月西江里。
契阔多别离，绸缪到生死。
九原即何处，万事皆如此。
晋山徒峨峨，斯人已冥冥。
常时禄且薄，殁后家复贫。
妻子在远道，弟兄无一人。
十上多苦辛，一官恒自哂。
青云将可致，白日忽先尽。
唯有身后名，空留无远近。','',''),('quantangshi-10434','哭裴少府','高適','quantangshi','','卷11','世人谁不死，嗟君非生虑。
扶病适到官，田园在何处？
公才羣吏感，葬事他人助。
余亦未识君，深悲哭君去。','',''),('quantangshi-10435','行路难二首 一','高適','quantangshi','','卷11','长安少年不少钱，能骑骏马鸣金鞭。
五侯相逢大道边，美人弦管争留连。
黄金如斗不敢惜，片言如山莫弃捐。
安知顦顇读书者，暮宿灵台私自怜。','',''),('quantangshi-10436','行路难二首 二','高適','quantangshi','','卷11','君不见富家翁，旧时贫贱谁比数。
一朝金多结豪贵，万事胜人健如虎。
子孙成行满眼前，妻能管弦妾能舞。
自矜一身忽如此，却笑傍人独愁苦。
东邻少年安所如，席门穷巷出无车。
有才不肯学干谒，何用年年空读书。','',''),('quantangshi-10437','秋胡行','高適','quantangshi','','卷11','妾本邯郸未嫁时，容华倚翠人未知。
一朝结发从君子，将妾迢迢东鲁陲。
时逢大道无艰阻，君方游宦从陈汝。
蕙楼独卧频度春，彩阁辞君几徂暑。
三月垂杨蚕未眠，携笼结侣南陌边。
道逢行子不相识，赠妾黄金买少年。
妾家夫壻经离久，寸心誓与长相守。
愿言行路莫多情，道妾贞心在人口。
日暮蚕饥相命归，携笼端饰来庭闱。
劳心苦力终无恨，所冀君恩即可依。
闻说行人已归止，乃是向来赠金子。
相看颜色不复言，相顾怀慙有何已。
从来自隐无疑背，直为君情也相会。
如何咫尺仍有情，况复迢迢千里外。
誓将顾恩不顾身，念君此日赴河津。
莫道向来不得意，故欲留规诫后人。','',''),('quantangshi-10438','古大梁行','高適','quantangshi','','卷11','古城莽苍饶荆榛，驱马荒城愁杀人。
魏王宫观尽禾黍，信陵宾客随灰尘。
忆昨雄都旧朝市，轩车照耀歌钟起。
军容带甲三十万，国步连营一千里。
全盛须臾那可论，高台曲池无复存。
遗墟但见狐狸迹，古地空余草木根。
暮天摇落伤怀抱，倚劒悲歌对秋草。
侠客犹传朱亥名，行人尚识夷门道。
白璧黄金万户侯，宝刀骏马填山丘。
年代凄凉不可问，往来唯有水东流。','',''),('quantangshi-10439','邯郸少年行','高適','quantangshi','','卷11','邯郸城南游侠子，自矜生长邯郸里。
千塲纵博家仍富，几度报讐身不死。
宅中歌笑日纷纷，门外车马常如云。
未知肝胆向谁是，令人却忆平原君。
君不见今人交态薄，黄金用尽还疎索。
以兹感叹辞旧游，更于时事无所求。
且与少年饮美酒，往来射猎西山头。','',''),('quantangshi-10440','燕歌行','高適','quantangshi','','卷11','汉家烟尘在东北，汉将辞家破残贼。
男儿本自重横行，天子非常赐颜色。
摐金伐鼓下榆关，旌斾逶迤碣石间。
校尉羽书飞瀚海，单于猎火照狼山。
山川萧条极边土，胡骑凭陵杂风雨。
战士军前半死生，美人帐下犹歌舞。
大漠穷秋塞草腓，孤城落日鬬兵稀。
身当恩遇恒轻敌，力尽关山未解围。
铁衣远戍辛勤久，玉筯应啼别离后。
少妇城南欲断肠，征人蓟北空回首。
边庭飘颻那可度，绝域苍茫更何有。
杀气三时作阵云，寒声一夜传刁斗。
相看白刃血纷纷，死节从来岂顾勋。
君不见沙场征战苦，至今犹忆李将军。','',''),('quantangshi-10441','古歌行','高適','quantangshi','','卷11','君不见汉家三叶从代至，高皇旧臣多富贵。
天子垂衣方晏如，庙堂拱手无余议。
苍生偃卧休征战，露台百金以为费。
田舍老翁不出门，洛阳少年莫论事。','',''),('quantangshi-10442','人日寄杜二拾遗','高適','quantangshi','','卷11','人日题诗寄草堂，遥怜故人思故乡。
柳条弄色不忍见，梅花满枝空断肠。
身在远藩无所预，心怀百忧复千虑。
今年人日空相忆，明年人日知何处。
一卧东山三十春，岂知书劒老风尘。
龙钟还忝二千石，愧尔东西南北人。','',''),('quantangshi-10443','九日酬颜少府','高適','quantangshi','','卷11','檐前白日应可惜，篱下黄花为谁有。
行子迎霜未授衣，主人得钱始沽酒。
苏秦顦顇人多厌，蔡泽栖迟世看丑。
纵使登高只断肠，不如独坐空搔首。','',''),('quantangshi-10444','留别郑三韦九兼洛下诸公','高適','quantangshi','','卷11','忆昨相逢论久要，顾君哂我轻常调。
羁旅虽同白社游，诗书已作青云料。
蹇质蹉跎竟不成，年过四十尚躬耕。
长歌达者杯中物，大笑前人身后名。
幸逢明盛多招隐，高山大泽征求尽。
此时亦得辞渔樵，青袍裹身荷圣朝。
犂牛钓竿不复见，县人邑吏来相邀。
远路鸣蝉秋兴发，华堂美酒离忧销。
不知何日更携手，应念兹晨去折腰。','',''),('quantangshi-10445','送杨山人归嵩阳','高適','quantangshi','','卷11','不到嵩阳动十年，旧时心事已徒然。
一二故人不复见，三十六峰犹眼前。
夷门二月柳条色，流莺数声泪沾臆。
凿井耕田不我招，知君以此忘帝力。
山人好去嵩阳路，惟余眷眷长相忆。','',''),('quantangshi-10446','送别','高適','quantangshi','','卷11','昨夜离心正郁陶，三更白露西风高。
萤飞木落何淅沥，此时梦见西归客。
曙钟寥亮三四声，东邻嘶马使人惊。
揽衣出户一相送，唯见归云纵复横。','',''),('quantangshi-10447','赠别晋三处士','高適','quantangshi','','卷11','有人家住清河源，渡河问我游梁园。
手持道经注已毕，心知内篇口不言。
卢门十年见秋草，此心惆怅谁能道。
知己从来不易知，慕君为人与君好。
别时九月桑叶疎，出门千里无行车。
爱君且欲君先达，今上求贤早上书。','',''),('quantangshi-10448','送浑将军出塞','高適','quantangshi','','卷11','将军族贵兵且强，汉家已是浑邪王。
子孙相承在朝野，至今部曲燕支下。
控弦尽用阴山儿，登阵常骑大宛马。
银鞍玉勒绣蝥弧，每逐嫖姚破骨都。
李广从来先将士，卫青未肯学孙吴。
传有沙场千万骑，昨日边庭羽书至。
城头画角三四声，匣里宝刀昼夜鸣。
意气能甘万里去，辛勤判作一年行。
黄云白草无前后，朝建旌旄夕刁斗。
塞下应多侠少年，关西不见春杨柳。
从军借问所从谁，击劒酣歌当此时。
远别无轻绕朝策，平戎早寄仲宣诗。','',''),('quantangshi-10449','送蔡山人','高適','quantangshi','','卷11','东山布衣明古今，自言独未逢知音。
识者阅见一生事，到处豁然千里心。
看书学劒长辛苦，近日方思谒明主。
斗酒相留醉复醒，悲歌数年泪如雨。
丈夫遭遇不可知，买臣主父皆如斯。
我今蹭蹬无所似，看尔崩腾何若为。','',''),('quantangshi-10450','封丘作','高適','quantangshi','','卷11','我本渔樵孟诸野，一生自是悠悠者。
乍可狂歌草泽中，宁堪作吏风尘下。
秪言小邑无所为，公门百事皆有期。
拜迎官长心欲碎，鞭挞黎庶令人悲。
归来向家问妻子，举家尽笑今如此。
生事应须南亩田，世情付与东流水。
梦想旧山安在哉，为衔君命且迟廻。
乃知梅福徒为尔，转忆陶潜归去来。','',''),('quantangshi-10451','题李别驾壁','高適','quantangshi','','卷11','去乡不远逢知己，握手相欢得如此。
礼乐遥传鲁伯禽，宾客争过魏公子。
酒筵暮散明月上，枥马长鸣春风起。
一生称意能几人，今日从君问终始。','',''),('quantangshi-10452','寄宿田家','高適','quantangshi','','卷11','田家老翁住东陂，说道平生隐在兹。
鬓白未曾记日月，山青每到识春时。
门前种柳深成巷，野谷流泉添入池。
牛壮日耕十亩地，人闲常扫一茅茨。
客来满酌清尊酒，感兴平吟才子诗。
岩际窟中藏鼹鼠，潭边竹里隐鸬鹚。
村墟日落行人少，醉后无心怯路岐。
今夜只应还寄宿，明朝拂曙与君辞。','',''),('quantangshi-10453','别韦参军','高適','quantangshi','','卷11','二十解书劒，西游长安城。
举头望君门，屈指取公卿。
国风冲融迈三五，朝廷欢乐弥寰宇。
白璧皆言赐近臣，布衣不得干明主。
归来洛阳无负郭，东过梁宋非吾土。
兔苑为农岁不登，雁池垂钓心长苦。
世人遇我同众人，唯君于我最相亲。
且喜百年有交态，未尝一日辞家贫。
弹棊击筑白日晚，纵酒高歌杨柳春。
欢娱未尽分散去，使我惆怅惊心神。
丈夫不作儿女别，临岐涕泪沾衣巾。','',''),('quantangshi-10454','送田少府贬苍梧','高適','quantangshi','','卷11','沈吟对迁客，惆怅西南天。
昔为一官未得意，今向万里令人怜。
念兹斗酒成暌间，停舟叹君日将晏。
远树应怜北地春，行人却羡南归雁。
丈夫穷达未可知，看君不合长数奇。
江山到处堪乘兴，杨柳青青那足悲。','',''),('quantangshi-10455','平台夜遇李景参有别','高適','quantangshi','','卷11','离心忽怅然，策马对秋天。
孟诸薄暮凉风起，归客相逢渡睢水。
昨时携手已十年，今日分途各千里。
岁物萧条满路岐，此行浩荡令人悲。
家贫羡尔有微禄，欲往从之何所之。','',''),('quantangshi-10456','送郭处士往莱芜兼寄苟山人','高適','quantangshi','','卷11','君为东蒙客，往来东蒙畔。
云卧临峄阳，山行穷日观。
少年词赋皆可听，秀眉白面风清泠。
身上未曾染名利，口中犹未知膻腥。
今日还山意无极，岂辞世路多相识。
归见莱芜九十翁，为论别后长相忆。','',''),('quantangshi-10457','赋得还山吟送沈四山人','高適','quantangshi','','卷11','还山吟，天高日暮寒山深。
送君还山识君心，人生老大须恣意。
看君解作一生事，山间偃仰无不至。
石泉淙淙若风雨，桂花松子常满地。
卖药囊中应有钱，还山服药又长年。
白云劝尽杯中物，明月相随何处眠。
眠时忆问醒时事，梦魂可以相周旋。','',''),('quantangshi-10458','崔司录宅燕大理李卿','高適','quantangshi','','卷11','多雨殊未已，秋云更沈沈。
洛阳故人初解印，山东小吏来相寻。
上卿才大名不朽，早朝至尊暮求友。
豁达常推海内贤，殷勤但酌尊中酒。
饮醉欲言归剡溪，门前驷马光照衣。
路傍观者徒唧唧，我公不以为是非。','',''),('quantangshi-10459','同鲜于洛阳于毕员外宅观画马歌','高適','quantangshi','','卷11','知君爱鸣琴，仍好千里马。
永日恒思单父中，有时心到宛城下。
遇客丹青天下才，白生胡雏控龙媒。
主人娱宾画障开，只言骐骥西极来。
半壁䟃𧽼势不住，满堂风飘飒然度。
家僮愕视欲先鞭，枥马惊嘶还屡顾。
始知物妙皆可怜，燕昭市骏岂徒然。
纵令剪拂无所用，犹胜驽骀在眼前。','',''),('quantangshi-10460','同河南李少尹毕员外宅夜饮时洛阳告捷遂作春酒歌','高適','quantangshi','','卷11','故人美酒胜浊醪，故人清词合风骚。
长歌满酌惟吾曹，高谈正可挥麈毛。
半醉忽然持蟹螯，洛阳告捷倾前后。
武侯腰间印如斗，郎官无事时饮酒。
杯中绿蚁吹转来，瓮上飞花拂还有。
前年持节将楚兵，去年留司在东京。
今年复拜二千石，盛夏五月西南行。
彭门劒门蜀山里，昨逢军人刦夺我。
到家但见妻与子，赖得饮君春酒数十杯，不然令我愁欲死。','',''),('quantangshi-10461','同李九士曹观壁画云作','高適','quantangshi','','卷11','始知帝乡客，能画苍梧云。
秋天万里一片色，只疑飞尽犹氛氲。','',''),('quantangshi-10462','见薛大臂鹰作','高適','quantangshi','','卷11','寒楚十二月，苍鹰八九毛。
寄言燕雀莫相啅，自有云霄万里高。','',''),('quantangshi-10463','画马篇','高適','quantangshi','','卷11','君侯枥上骢，貌在丹青中。
马毛连钱蹄铁色，图画光辉骄玉勒。
马行不动势若来，权奇蹴踏无尘埃。
感兹绝代称妙手，遂令谈者不容口。
麒麟独步自可珍，驽骀万匹知何有，终未如他枥上骢。
载华毂，聘飞鸿，荷君剪拂与君用，一日千里如旋风。','',''),('quantangshi-10464','咏马鞭','高適','quantangshi','','卷11','龙竹养根凡几年，工人截之为长鞭。
一节一目皆天然，珠重重，星连连。
绕指柔，纯金坚，绳不直，规不圆。
把向空中捎一声，良马有心日驰千。','',''),('quantangshi-10465','塞下曲','高適','quantangshi','','卷11','君不见芳树枝，春花落尽蜂不窥。
君不见梁上泥，秋风始高燕不栖。
荡子从军事征战，蛾眉婵娟守空闺。
独宿自然堪下泪，况复时闻鸟夜啼。','',''),('quantangshi-10466','渔父歌','高適','quantangshi','','卷11','曲岸深潭一山叟，驻眼看鈎不移手。
世人欲得知姓名，良久问他不开口。
笋皮笠子荷叶衣，心无所营守钓矶。
料得孤舟无定止，日暮持竿何处归。','',''),('quantangshi-10467','部落曲','高適','quantangshi','','卷11','蕃军傍塞游，代马喷风秋。
老将垂金甲，阏支着锦裘。
雕戈蒙豹尾，红斾插狼头。
日暮天山下，鸣笳汉使愁。','',''),('quantangshi-10468','赠杜二拾遗','高適','quantangshi','','卷11','传道招[提]客，诗书自讨论。
佛香时入院，僧饭屡过门。
听法还应难，寻经剩欲翻。
草玄今已毕，此外复何言。','',''),('quantangshi-10469','醉后赠张九旭','高適','quantangshi','','卷11','世上谩相识，此翁殊不然。
兴来书自圣，醉后语尤颠。
白发老闲事，青云在目前。
牀头一壶酒，能更几回眠。','',''),('quantangshi-10470','途中寄徐录事','高適','quantangshi','','卷11','落日风雨至，秋天鸿雁初。
离忧不堪比，旅馆复何如。
君又几时去，我知音信疎。
空多箧中赠，长见右军书。','',''),('quantangshi-10471','酬卫八雪中见寄','高適','quantangshi','','卷11','季冬忆淇上，落日归山樊。
旧宅带流水，平田临古村。
雪中望来信，醉里开衡门。
果得希代宝，缄之那可论。','',''),('quantangshi-10472','送白少府送兵之陇右','高適','quantangshi','','卷11','践更登陇首，远别指临洮。
为问关山事，何如州县劳。
军容随赤羽，树色引青袍。
谁断单于臂，今年太白高。','',''),('quantangshi-10473','河西送李十七','高適','quantangshi','','卷11','边城多远别，此去莫徒然。
问礼知才子，登科及少年。
出门看落日，驱马向秋天。
高价人争重，行当早着鞭。','',''),('quantangshi-10474','送张瑶贬五溪尉','高適','quantangshi','','卷11','他日维桢干，明时悬镆铘。
江山遥去国，妻子独还家。
离别无嫌远，沈浮勿强嗟。
南登有词赋，知尔吊长沙。','',''),('quantangshi-10475','别韦五','高適','quantangshi','','卷11','徒然酌杯酒，不觉散人愁。
相识仍远别，欲归翻旅游。
夏云满郊甸，明月照河洲。
莫恨征途远，东看漳水流。','',''),('quantangshi-10476','别刘大校书','高適','quantangshi','','卷11','昔日京华去，知君才望新。
应犹作赋好，莫叹在官贫。
且复伤远别，不然愁此身。
清风几万里，江上一归人。','',''),('quantangshi-10477','宋中别司功叔各赋一物得商丘','高適','quantangshi','','卷11','商丘试一望，隐隐带秋天。
地与辰星在，城将大路迁。
干戈悲昔事，墟落对穷年。
即此伤离绪，凄凄赋酒筵。','',''),('quantangshi-10478','送蔡十二之海上','高適','quantangshi','','卷11','黯然何所为，相对但悲酸。
季弟念离别，贤兄救急难。
河流冰处尽，海路雪中寒。
尚有南飞雁，知君不忍看。','',''),('quantangshi-10479','别韦兵曹','高適','quantangshi','','卷11','离别长千里，相逢数十年。
此心应不变，他事已徒然。
惆怅春光里，蹉跎柳色前。
逢时当自取，看尔欲先鞭。','',''),('quantangshi-10480','独孤判官部送兵','高適','quantangshi','','卷11','饯君嗟远别，为客念周旋。
征路今如此，前军犹眇然。
出关逢汉壁，登陇望胡天。
亦是封侯地，期君早着鞭。','',''),('quantangshi-10481','别从甥万盈','高適','quantangshi','','卷11','诸生曰万盈，四十乃知名。
宅相予偏重，家丘人莫轻。
美才应自料，苦节岂无成。
莫以山田薄，今春又不耕。','',''),('quantangshi-10482','别崔少府','高適','quantangshi','','卷11','知君少得意，汶上掩柴扉。
寒食仍留火，春风未授衣。
皆言黄绶屈，早向青云飞。
借问他乡事，今年归不归。','',''),('quantangshi-10483','别冯判官','高適','quantangshi','','卷11','碣石辽西地，渔阳蓟北天。
关山唯一道，雨雪尽三边。
才子方为客，将军正渴贤。
遥知幕府下，书记日翩翩。','',''),('quantangshi-10484','淇上送韦司仓往滑台','高適','quantangshi','','卷11','饮酒莫辞醉，醉多适不愁。
孰知非远别，终念对穷秋。
滑台门外见，淇水眼前流。
君去应回首，风波满渡头。','',''),('quantangshi-10485','送崔功曹赴越','高適','quantangshi','','卷11','传有东南别，题诗报客居。
江山知不厌，州县复何如。
莫恨吴歈曲，尝看越绝书。
今朝欲乘兴，随尔食鲈鱼。','',''),('quantangshi-10486','送蹇秀才赴临洮','高適','quantangshi','','卷11','怅望日千里，如何今二毛。
犹思阳谷去，莫厌陇山高。
倚马见雄笔，随身唯宝刀。
料君终自致，勋业在临洮。','',''),('quantangshi-10487','广陵别郑处士','高適','quantangshi','','卷11','落日知分手，春风莫断肠。
兴来无不惬，才在亦何伤。
溪水堪垂钓，江田耐插秧。
人生只为此，亦足傲羲皇。','',''),('quantangshi-10488','别孙欣','高適','quantangshi','','卷11','离人去复留，白马黑貂裘。
屈指论前事，停鞭惜旧游。
帝乡那可忘，旅馆日堪愁。
谁念无知己，年年睢水流。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-10489','送刘评事充朔方判官赋得征马嘶','高適','quantangshi','','卷11','征马向边州，萧萧嘶不休。
思深应带别，声断为兼秋。
岐路风将远，关山月共愁。
赠君从此去，何日大刀头。','',''),('quantangshi-10490','送魏八','高適','quantangshi','','卷11','更沽淇上酒，还泛驿前舟。
为惜故人去，复怜嘶马愁。
云山行处合，风雨兴中秋。
此路无知己，明珠莫暗投。','',''),('quantangshi-10491','赠别褚山人','高適','quantangshi','','卷11','携手赠将行，山人道姓名。
光阴蓟子训，才术褚先生。
墙上梨花白，尊中桂酒清。
洛阳无二价，犹是慕风声。','',''),('quantangshi-10492','别王八','高適','quantangshi','','卷11','征马嘶长路，离人挹佩刀。
客来东道远，归去北风高。
时候何萧索，乡心正郁陶。
传君遇知己，行日有绨袍。','',''),('quantangshi-10493','送董判官','高適','quantangshi','','卷11','逢君说行迈，倚劒别交亲。
幕府为才子，将军作主人。
近关多雨雪，出塞有风尘。
长策须当用，男儿莫顾身。','',''),('quantangshi-10494','送郑侍御谪闽中','高適','quantangshi','','卷11','谪去君无恨，闽中我旧过。
大都秋雁少，只是夜猿多。
东路云山合，南天瘴疠和。
自当逢雨露，行矣慎风波。','',''),('quantangshi-10495','送李侍御赴安西','高適','quantangshi','','卷11','行子对飞蓬，金鞭指铁骢。
功名万里外，心事一杯中。
虏障燕支北，秦城太白东。
离魂莫惆怅，看取宝刀雄。','',''),('quantangshi-10496','送裴别将之安西','高適','quantangshi','','卷11','绝域眇难跻，悠然信马蹄。
风尘经跋涉，摇落怨暌携。
地出流沙外，天长甲子西。
少年无不可，行矣莫凄凄。','',''),('quantangshi-10497','宴郭校书因之有别','高適','quantangshi','','卷11','彩服趋庭训，分交载酒过。
芸香名早着，蓬转事仍多。
苦战知机息，穷愁奈别何。
云霄莫相待，年鬓已蹉跎。','',''),('quantangshi-10498','同李太守北池泛舟宴高平郑太守','高適','quantangshi','','卷11','每揖龚黄事，还陪李郭舟。
云从四岳起，水向百城流。
幽意随登陟，嘉言即献酬。
乃知缝掖贵，今日对诸侯。','',''),('quantangshi-10499','同崔员外綦毋拾遗九日宴京兆府李士曹','高適','quantangshi','','卷11','今日好相见，羣贤仍废曹。
晚晴催翰墨，秋兴引风骚。
绛叶拥虚砌，黄花随浊醪。
闭门无不可，何事更登高。','',''),('quantangshi-10500','同羣公十月朝宴李太守宅','高適','quantangshi','','卷11','良牧征高赏，褰帷问考盘。
岁时当正月，甲子入初寒。
已听甘棠颂，欣陪旨酒欢。
仍怜门下客，不作布衣看。','',''),('quantangshi-10501','武威同诸公过杨七山人得藤字','高適','quantangshi','','卷11','幕府日多暇，田家岁复登。
相知恨不早，乘兴乃无恒。
穷巷在乔木，深斋垂古藤。
边城唯有醉，此外更何能。','',''),('quantangshi-10502','同羣公登濮阳圣佛寺阁','高適','quantangshi','','卷11','落日登临处，悠然意不穷。
佛因初地识，人觉四天空。
来雁清霜后，孤帆远树中。
裴回伤寓目，萧索对寒风。','',''),('quantangshi-10503','同卫八题陆少府书斋','高適','quantangshi','','卷11','知君薄州县，好静无冬春。
散帙至栖鸟，明灯留故人。
深房腊酒熟，高院梅花新。
若是周旋地，当令风义亲。','',''),('quantangshi-10504','淇上别业','高適','quantangshi','','卷11','依依西山下，别业桑林边。
庭鸭喜多雨，邻鸡知暮天。
野人种秋菜，古老开原田。
且向世情远，吾今聊自然。','',''),('quantangshi-10505','入昌松东界山行','高適','quantangshi','','卷11','鸟道几登顿，马蹄无暂闲。
崎岖出长坂，合沓犹前山。
石激水流处，天寒松色间。
王程应未尽，且莫顾刀环。','',''),('quantangshi-10506','使青夷军入居庸三首 一','高適','quantangshi','','卷11','匹马行将久，征途去转难。
不知边地别，秪讶客衣单。
溪冷泉声苦，山空木叶干。
莫言关塞极，云雪尚漫漫。','',''),('quantangshi-10507','使青夷军入居庸三首 二','高適','quantangshi','','卷11','古镇青山口，寒风落日时。
岩峦鸟不过，冰雪马堪迟。
出塞应无策，还家赖有期。
东山足松桂，归去结茅茨。','',''),('quantangshi-10508','使青夷军入居庸三首 三','高適','quantangshi','','卷11','登顿驱征骑，栖迟愧宝刀。
远行今若此，微禄果徒劳。
绝坂水连下，羣峰云共高。
自堪成白首，何事一青袍。','',''),('quantangshi-10509','自蓟北归','高適','quantangshi','','卷11','驱马蓟门北，北风边马哀。
苍茫远山口，豁达胡天开。
五将已深入，前军止半廻。
谁怜不得意，长劒独归来。','',''),('quantangshi-10510','东平别前卫县李寀少府','高適','quantangshi','','卷11','黄鸟翩翩杨柳垂，春风送客使人悲。
怨别自惊千里外，论交却忆十年时。
云开汶水孤帆远，路绕梁山匹马迟。
此地从来可乘兴，留君不住益凄其。','',''),('quantangshi-10511','夜别韦司士得城字','高適','quantangshi','','卷11','高馆张灯酒复清，夜钟残月雁归声。
只言啼鸟堪求侣，无那春风欲送行。
黄河曲里沙为岸，白马津边柳向城。
莫怨他乡暂离别，知君到处有逢迎。','',''),('quantangshi-10512','送李少府贬峡中王少府贬长沙','高適','quantangshi','','卷11','嗟君此别意何如，驻马衔杯问谪居。
巫峡啼猿数行泪，衡阳归雁几封书。
青枫江上秋天远，白帝城边古木疎。
圣代即今多雨露，暂时分手莫踌躇。','',''),('quantangshi-10513','同陈留崔司户早春宴蓬池','高適','quantangshi','','卷11','同官载酒出郊圻，晴日东驰雁北飞。
隔岸春云邀翰墨，傍檐垂柳报芳菲。
池边转觉虚无尽，台上偏宜酩酊归。
州县徒劳那可度，后时连骑莫相违。','',''),('quantangshi-10514','金城北楼','高適','quantangshi','','卷11','北楼西望满晴空，积水连山胜画中。
湍上急流声若箭，城头残月势如弓。
垂竿已羡磻溪老，体道犹思塞上翁。
为问边庭更何事，至今羌笛怨无穷。','',''),('quantangshi-10515','同颜六少府旅宦秋中之作','高適','quantangshi','','卷11','传君昨夜怅然悲，独坐新斋木落时。
逸气旧来凌燕雀，高才何得混妍媸。
迹留黄绶人多叹，心在青云世莫知。
不是鬼神无正直，从来州县有瑕疵。','',''),('quantangshi-10516','重阳','高適','quantangshi','','卷11','节物惊心两鬓华，东篱空绕未开花。
百年将半仕三已，五亩就荒天一涯。
岂有白衣来剥啄，一从乌帽自攲斜。
真成独坐空搔首，门柳萧萧噪暮鸦。','',''),('quantangshi-10517','古乐府飞龙曲留上陈左相','高適','quantangshi','','卷11','德以精灵降，时膺梦寐求。
苍生谢安石，天子富平侯。
尊俎资高论，岩廊挹大猷。
相门连户牖，卿族嗣弓裘。
豁达云开霁，清明月映秋。
能为吉甫颂，善用子房筹。
阶砌思攀陟，门阑尚阻修。
高山不易仰，大匠本难投。
迹与松乔合，心缘启沃留。
公才山吏部，书癖杜荆州。
幸沐千年圣，何辞一尉休。
折腰知宠辱，廻首见沈浮。
天地庄生马，江湖范蠡舟。
逍遥堪自乐，浩荡信无忧。
去此从黄绶，归欤任白头。
风尘与霄汉，瞻望日悠悠。','',''),('quantangshi-10518','留上李右相','高適','quantangshi','','卷11','风俗登淳古，君臣挹大庭。
深沈谋九德，密勿契千龄。
独立调元气，清心豁窅冥。
本枝连帝系，长策冠生灵。
傅说明殷道，萧何律汉刑。
钧衡持国柄，柱石总朝经。
隐轸江山藻，氛氲鼎鼐铭。
兴中皆白雪，身外即丹青。
江海呼穷鸟，诗书问聚萤。
吹嘘成羽翼，提握动芳馨。
倚伏悲还笑，栖迟醉复醒。
恩荣初就列，含育忝宵形。
有窃丘山惠，无时枕席宁。
壮心瞻落景，生事感浮萍。
莫以才难用，终期善易听。
未为门下客，徒谢少微星。','',''),('quantangshi-10519','同李员外贺哥舒大夫破九曲之作','高適','quantangshi','','卷11','遥传副丞相，昨日破西蕃。
作气羣山动，扬军大斾翻。
奇兵邀转战，连孥绝归奔。
泉喷诸戎血，风驱死虏魂。
头飞攒万戟，面缚聚辕门。
鬼哭黄埃暮，天愁白日昏。
石城与岩险，铁骑皆云屯。
长策一言决，高踪百代存。
威棱慑沙漠，忠义感干坤。
老将黯无色，儒生安敢论。
解围凭庙算，止杀报君恩。
唯有关河渺，苍茫空树墩。','',''),('quantangshi-10520','信安王幕府诗','高適','quantangshi','','卷11','云纪轩皇代，星高太白年。
庙堂咨上策，幕府制中权。
盘石藩维固，升坛礼乐先。
国章荣印绶，公服贵貂蝉。
乐善旌深德，输忠格上玄。
剪桐光宠锡，题劒美贞坚。
圣祚雄图广，师贞武德虔。
雷霆七校发，旌斾五营连。
华省征羣乂，霜台举二贤。
岂伊公望远，曾是茂才迁。
并秉韬钤术，兼该翰墨筵。
帝思麟阁像，臣献柏梁篇。
振玉登辽甸，摐金历蓟壖。
度河飞羽檄，横海泛楼船。
北伐声逾迈，东征务以专。
讲戎喧涿野，料敌静居延。
军势持三略，兵戎自九天。
朝瞻授钺去，时听偃戈旋。
大漠风沙里，长城雨雪边。
云端临碣石，波际隐朝鲜。
夜壁冲高斗，寒空驻彩旃。
倚弓玄兔月，饮马白狼川。
庶物随交泰，苍生解倒悬。
四郊增气象，万里绝风烟。
关塞鸿勋着，京华甲第全。
落梅横吹后，春色凯歌前。
直道常兼济，微才独弃捐。
曳裾诚已矣，投笔尚凄然。
作赋同元淑，能诗匪仲宣。
云霄不可望，空欲仰神仙。','',''),('quantangshi-10521','东平旅游奉赠薛太守二十四韵','高適','quantangshi','','卷11','颂美驰千古，钦贤仰大猷。
晋公标逸气，汾水注长流。
神与公忠节，天生将相俦。
青云本自负，赤县独推尤。
御史风逾劲，郎官草屡修。
鵷鸾粉署起，鹰隼柏台秋。
出入交三事，飞鸣揖五侯。
军书陈上策，廷议借前筹。
肃肃趋朝列，雝雝引帝求。
一麾俄出守，千里再分忧。
不改任棠水，仍传晏子裘。
歌谣随举扇，旌斾逐鸣驺。
郡国长河绕，川原大野幽。
地连尧泰岳，山向禹青州。
汶上春帆渡，秦亭晚日愁。
遗墟当少昊，悬象逼奎娄。
即此逢清鉴，终然喜暗投。
叨承解榻礼，更得问缣游。
高兴陪登陟，嘉言忝献酬。
观棊知战胜，探象会冥搜。
眺听情何限，冲融惠勿休。
祗应齐语默，宁肯问沈浮。
然诺长怀季，栖遑輙累丘。
平生感知己，方寸岂悠悠。','',''),('quantangshi-10522','真定即事奉赠韦使君二十八韵','高適','quantangshi','','卷11','飘泊怀书客，迟回此路隅。
问津惊弃置，投刺忽踟蹰。
方伯恩弥重，苍生咏已苏。
郡称廉叔度，朝议管夷吾。
乃继三台侧，仍将四岳俱。
江山澄气象，崖谷倚冰壶。
诏宠金门策，官荣叶县凫。
擢才登粉署，飞步蹑云衢。
起草征调墨，焚香即宴娱。
光华扬盛矣，霄汉在兹乎。
隐轸推公望，逶迤协帝俞。
轩车辞魏阙，旌节副幽都。
始佩仙郎印，俄兼太守符。
尤多蜀郡理，更得颍川谟。
城邑推雄镇，山川列简图。
旧燕当绝漠，全赵对平芜。
旷野何弥漫，长亭复郁纡。
始泉遗俗近，活水战场无。
月换思乡陌，星廻记斗枢。
岁容归万象，和气发鸿罏。
沦落而谁遇，栖遑有是夫。
不才羞拥肿，干禄谢侏儒。
契阔慙行迈，羁离忆友于。
田园同季子，储蓄异陶朱。
方欲呈高义，吹嘘揖大巫。
永怀吐肝胆，犹惮阻荣枯。
解榻情何限，忘言道未殊。
从来贵缝掖，应是念穷途。','',''),('quantangshi-10523','和窦侍御登凉州七级浮图之作','高適','quantangshi','','卷11','化塔屹中起，孤高宜上跻。
铁冠雄赏眺，金界宠招携。
空色在轩户，边声连鼓鼙。
天寒万里北，地豁九州西。
清兴揖才彦，峻风和端倪。
始知阳春后，具物皆筌蹄。','',''),('quantangshi-10524','酬河南节度使贺兰大夫见赠之作','高適','quantangshi','','卷11','高阁凭栏槛，中军倚斾旌。
感时常激切，于己即忘情。
河华屯妖气，伊瀍有战声。
愧无戡难策，多谢出师名。
秉钺知恩重，临戎觉命轻。
股肱瞻列岳，唇齿赖长城。
隐隐摧锋势，光光弄印荣。
鲁连真义士，陆逊岂书生。
直道宁殊智，先鞭忽抗行。
楚云随去马，淮月尚连营。
抚劒堪投分，悲歌益不平。
从来重然诺，况值欲横行。','',''),('quantangshi-10525','奉酬睢阳路太守见赠之作','高適','quantangshi','','卷11','盛才膺命代，高价动良时。
帝简登藩翰，人和发咏思。
神仙去华省，鵷鹭忆丹墀。
清净能无事，优游即赋诗。
江山纷想像，云物共萎蕤。
逸气刘公干，玄言向子期。
多慙汲引速，翻愧激昂迟。
相马知何限，登龙反自疑。
风尘吏道迫，行迈旅心悲。
拙疾徒为尔，穷愁欲问谁。
秋庭一片叶，朝镜数茎丝。
州县甘无取，丘园悔莫追。
琼瑶生箧笥，光景借茅茨。
他日青霄里，犹应访所知。','',''),('quantangshi-10526','奉酬睢阳李太守','高適','quantangshi','','卷11','公族称王佐，朝经允帝求。
本枝疆我李，盘石冠诸刘。
礼乐光辉盛，山河气象幽。
系高周柱史，名重晋阳秋。
华省膺推择，青云宠宴游。
握兰多具美，前席有嘉谋。
赋得黄金赐，言皆白璧酬。
着鞭驱驷马，操刃解全牛。
出镇兼方伯，承家复列侯。
朝瞻孔北海，时用杜荆州。
广固才登陟，毗陵忽阻修。
三台冀入梦，四岳尚分忧。
郡邑连京口，山川望石头。
海门当建节，江路引鸣驺。
俗见中兴理，人逢至道休。
先移白额横，更息赭衣偷。
梁国歌来晚，徐方怨不留。
岂伊齐政术，将以变浇浮。
讼简知能吏，刑宽察要囚。
坐堂风偃草，行县雨随輈。
地是蒙庄宅，城遗阏伯丘。
孝王余井径，微子故田畴。
冬至招摇转，天寒螮蝀收。
猿岩飞雨雪，兔苑落梧楸。
列戟霜侵户，褰帏月在鈎。
好贤常解榻，乘兴每登楼。
逸足横千里，高谈注九流。
诗题青玉案，衣赠黑貂裘。
穷巷轩车静，闲斋耳目愁。
未能方管乐，翻欲慕巢由。
讲德良难敌，观风岂易俦。
寸心仍有适，江海一扁舟。','',''),('quantangshi-10527','送柴司户充刘卿判官之岭外','高適','quantangshi','','卷11','岭外资雄镇，朝端宠节旄。
月卿临幕府，星使出词曹。
海对羊城阔，山连象郡高。
风霜驱瘴疠，忠信涉波涛。
别恨随流水，交情脱宝刀。
有才无不适，行矣莫徒劳。','',''),('quantangshi-10528','送蔡少府赴登州推事','高適','quantangshi','','卷11','胶东连即墨，莱水入沧溟。
国小常多事，人讹屡抵刑。
公才征郡邑，诏使出郊坰。
标格谁当犯，风谣信可听。
峥嵘大岘口，逦迤汶阳亭。
地迥云偏白，天秋山更青。
祖筵方卜昼，王事急侵星。
劝尔将为德，斯言盖有听。','',''),('quantangshi-10529','秦中送李九赴越','高適','quantangshi','','卷11','携手望千里，于今将十年。
如何每离别，心事复迍邅。
适越虽有以，出关终耿然。
愁霖不可向，长路或难前。
吴会独行客，山阴秋夜船。
谢家征故事，禹穴访遗编。
镜水君所忆，莼羹余旧便。
归来莫忘此，兼示济江篇。','',''),('quantangshi-10530','饯宋八充彭中丞判官之岭南','高適','quantangshi','','卷11','覩君济时略，使我气填膺。
长策竟不用，高才徒见称。
一朝知己达，累日诏书征。
羽翮忽然就，风飙谁敢凌。
举鞭趋岭峤，屈指冒炎蒸。
北雁送驰驿，南人思饮冰。
彼邦本倔强，习俗多骄矜。
翠羽干平法，黄金挠直绳。
若将除害马，慎勿信苍蝇。
魑魅宁无患，忠贞适有凭。
猿啼山不断，鸢跕路难登。
海岸出交趾，江城连始兴。
绣衣当节制，幕府盛威棱。
勿惮九嶷险，须令百越澄。
立谈多感激，行李即严凝。
离别胡为者，云霄迟尔升。','',''),('quantangshi-10531','陪窦侍御泛灵云池','高適','quantangshi','','卷11','白露时先降，清川思不穷。
江湖仍塞上，舟楫在军中。
舞换临津树，歌饶向迥风。
夕阳连积水，边色满秋空。
乘兴宜投辖，邀欢莫避骢。
谁怜持弱羽，犹欲伴鵷鸿。','',''),('quantangshi-10532','陪窦侍御灵云南亭宴诗得雷字','高適','quantangshi','','卷11','人幽宜眺听，目极喜亭台。
风景知愁在，关山忆梦回。
秪言殊语默，何意忝游陪。
连唱波澜动，冥搜物象开。
新秋归远树，残雨拥轻雷。
檐外长天尽，尊前独鸟来。
常吟塞下曲，多谢幕中才。','',''),('quantangshi-10533','同熊少府题卢主簿茅斋','高適','quantangshi','','卷11','虚院野情在，茅斋秋兴存。
孝廉趋下位，才子出高门。
乃继幽人静，能令学者尊。
江山归谢客，神鬼下刘根。
阶树时攀折，窗书任讨论。
自堪成独往，何必武陵源。','',''),('quantangshi-10534','同朱五题卢使君义井','高適','quantangshi','','卷11','高义唯良牧，深仁自下车。
宁知凿井处，还是饮冰余。
地即泉源久，人当汲引初。
体清能鉴物，色洞每含虚。
上善滋来往，中和浃里闾。
济时应未竭，怀惠复何如。','',''),('quantangshi-10535','同郭十题杨主簿新厅','高適','quantangshi','','卷11','华馆曙沈沈，惟良正在今。
用材兼柱石，闻物象高深。
更得芝兰地，兼营枳棘林。
向风扃戟户，当署近棠阴。
勿改安卑节，聊闲理剧心。
多君有知己，一和郢中吟。','',''),('quantangshi-10536','秋日作','高適','quantangshi','','卷11','端居值秋节，此日更愁辛。
寂寞无一事，蒿莱通四邻。
闭门生白发，回首忆青春。
岁月不相待，交游随众人。
云霄何处托，愚直有谁亲。
举酒聊自劝，穷通信尔身。','',''),('quantangshi-10537','辟阳城','高適','quantangshi','','卷11','荒城在高岸，凌眺俯清淇。
传道汉天子，而封审食其。
奸淫且不戮，茅土孰云宜。
何得英雄主，返令儿女欺。
母仪良已失，臣节岂如斯。
太息一朝事，乃令人所嗤。','',''),('quantangshi-10538','赴彭州山行之作','高適','quantangshi','','卷11','峭壁连崆峒，攒峰叠翠微。
鸟声堪驻马，林色可忘机。
怪石时侵径，轻萝乍拂衣。
路长愁作客，年老更思归。
且悦岩峦胜，宁嗟意绪违。
山行应未尽，谁与玩芳菲。','',''),('quantangshi-10539','咏史','高適','quantangshi','','卷11','尚有绨袍赠，应怜范叔寒。
不知天下士，犹作布衣看。','',''),('quantangshi-10540','送兵到蓟北','高適','quantangshi','','卷11','积雪与天迥，屯军连塞愁。
谁知此行迈，不为觅封侯。','',''),('quantangshi-10541','同羣公题张处士菜园','高適','quantangshi','','卷11','耕地桑柘间，地肥菜常熟。
为问葵藿资，何如庙堂肉。','',''),('quantangshi-10542','逢谢偃','高適','quantangshi','','卷11','红颜怆为别，白发始相逢。
唯余昔时泪，无复旧时容。','',''),('quantangshi-10543','田家春望','高適','quantangshi','','卷11','出门何所见，春色满平芜。
可叹无知己，高阳一酒徒。','',''),('quantangshi-10544','闲居','高適','quantangshi','','卷11','柳色惊心事，春风厌索居。
方知一杯酒，犹胜百家书。','',''),('quantangshi-10545','封丘作','高適','quantangshi','','卷11','州县才难适，云山道欲穷。
揣摩惭黠吏，栖隐谢愚公。','',''),('quantangshi-10546','九曲词三首 一','高適','quantangshi','','卷11','许国从来彻庙堂，连年不为在疆塲。
将军天上封侯印，御史台中异姓王。','',''),('quantangshi-10547','九曲词三首 二','高適','quantangshi','','卷11','万骑争歌杨柳春，千塲对舞绣骐驎。
到处尽逢欢洽事，相看总是太平人。','',''),('quantangshi-10548','九曲词三首 三','高適','quantangshi','','卷11','铁骑横行铁岭头，西看逻逤取封侯。
青海只今将饮马，黄河不用更防秋。','',''),('quantangshi-10549','营州歌','高適','quantangshi','','卷11','营州少年厌原野，狐裘蒙茸猎城下。
虏酒千钟不醉人，胡儿十岁能骑马。','',''),('quantangshi-10550','玉真公主歌 一','高適','quantangshi','','卷11','常言龙德本天仙，谁谓仙人每学仙。
更道玄元指李白，多于王母种桃年。','',''),('quantangshi-10551','玉真公主歌 二','高適','quantangshi','','卷11','仙宫仙府有真仙，天宝天仙秘莫传。
为问轩皇三百岁，何如大道一千年。','',''),('quantangshi-10552','和王七玉门关听吹笛','高適','quantangshi','','卷11','胡人吹笛戍楼间，楼上萧条海月闲。
借问落梅凡几曲，从风一夜满关山。','',''),('quantangshi-10553','别董大二首 一','高適','quantangshi','','卷11','十里黄云白日曛，北风吹雁雪纷纷。
莫愁前路无知己，天下谁人不识君。','',''),('quantangshi-10554','别董大二首 二','高適','quantangshi','','卷11','六翮飘颻私自怜，一离京洛十余年。
丈夫贫贱应未足，今日相逢无酒钱。','',''),('quantangshi-10555','送桂阳孝廉','高適','quantangshi','','卷11','桂阳年少西入秦，数经甲科犹白身。
即今江海一归客，他日云霄万里人。','',''),('quantangshi-10556','送李少府时在客舍作','高適','quantangshi','','卷11','相逢旅馆意多违，暮雪初晴候雁飞。
主人酒尽君未醉，薄暮途遥归不归。','',''),('quantangshi-10557','听张立本女吟','高適','quantangshi','','卷11','危冠广袖楚宫妆，独步闲庭逐夜凉。
自把玉钗敲砌竹，清歌一曲月如霜。','',''),('quantangshi-10558','初至封丘作','高適','quantangshi','','卷11','可怜薄暮宦游子，独卧虚斋思无已。
去家百里不得归，到官数日秋风起。','',''),('quantangshi-10559','除夜作','高適','quantangshi','','卷11','旅馆寒灯独不眠，客心何事转凄然。
故乡今夜思千里，愁鬓明朝又一年。','',''),('quantangshi-10560','劒池','李峴','quantangshi','','卷11','阖闾葬日劳人力，嬴政穿来役鬼功。
澄碧尚疑神物在，等闲雷雨起潭中。','',''),('quantangshi-10561','张公洞','李栖筠','quantangshi','','卷11','一径深窈窕，上升翠微中。
忽然灵洞前，日月开仙宫。
道士十二人，往还驭清风。
焚香入深洞，巨石如虚空。
夙夜备苹藻，诏书祠张公。
五云何裴回，玄鹤下苍穹。
我本道门子，愿言出尘笼。
扫除方寸间，几与神灵通。
宿昔勤梦想，契之在深衷。
迟回将不还，章绶击我躬。
稽首谢真侣，辞满归崆峒。','',''),('quantangshi-10562','投宋大夫','李栖筠','quantangshi','','卷11','十处投人九处违，家乡万里又空归。
严霜昨夜侵人骨，谁念高堂未授衣。','',''),('quantangshi-10563','宝林寺作','徐浩','quantangshi','','卷11','兹山昔飞来，远自琅琊台。
孤岫龟形在，深泉鳗井开。
越王屡登陟，何相传词才。
塔庙宗其巅，规模称壮哉。
禅堂清溽润，高阁无恢炱。
照耀珠吐月，铿轰钟隐雷。
揆余久缨弁，末路遭邅回。
一弃沧海曲，六年稽岭隈。
逝川惜东驶，驰景怜西颓。
腰带愁疾减，容颜衰悴催。
赖居兹寺中，法士多瓌能。
洗心听经论，礼足蠲凶灾。
永愿依胜侣，清江乘度杯。','',''),('quantangshi-10564','谒禹庙','徐浩','quantangshi','','卷11','亩浍敷四海，川源涤九州。
既膺九命锡，乃建洪范畴。
鼎革固天启，运兴匪人谋。
肇开宅土业，永庇昏垫忧。
山足灵庙在，门前清镜流。
象筵陈玉帛，容卫俨戈矛。
探穴图书朽，卑宫堂殿修。
梅梁今不坏，松祏古仍留。
负责故乡近，朅来申俎羞。
为鱼知造化，叹凤仰徽猷。
不复闻夏乐，唯余奏楚幽。
婆娑非舞羽，镗鞳异鸣球。
盛德吾无间，高功谁与俦。
灾淫破凶慝，祚圣拥神休。
出谷莺初语，空山猨独愁。
春晖生草树，柳色暖汀洲。
恩贷题舆重，荣殊衣锦游。
宦情同械击，生理任桴浮。
地极临沧海，天遥过斗牛。
精诚如可谅，他日寄冥搜。','',''),('quantangshi-10565','自悼','薛令之','quantangshi','','卷11','朝日上团团，照见先生盘。
盘中何所有，苜蓿长阑干。
饭澁匙难绾，羹稀筯易宽。
只可谋朝夕，何由保岁寒。','',''),('quantangshi-10566','灵岩寺','薛令之','quantangshi','','卷11','草堂栖在灵山谷，勤苦诗书向灯烛。
柴门半掩寂无人，惟有白云相伴宿。','',''),('quantangshi-10567','湘夫人','鄒紹先','quantangshi','','卷11','枫叶下秋渚，二妃愁渡湘。
疑山空杳蔼，何处望君王。
日落水云里，悠悠心自伤。','',''),('quantangshi-10568','寄妻父刘长卿','李穆','quantangshi','','卷11','处处云山无尽时，桐庐南望转参差。
舟人莫道新安近，欲上潺湲行自迟。','',''),('quantangshi-10569','短歌行','馮著','quantangshi','','卷11','寂寞草中兰，亭亭山上松。
贞芳日有分，生长耐相容。
结根各得地，幸沾雨露功。
参辰无停泊，且顾一西东。
君但开怀抱，猜恨莫怱怱。','',''),('quantangshi-10570','洛阳道','馮著','quantangshi','','卷11','洛阳宫中花柳春，洛阳道上无行人。
皮裘毡帐不相识，万户千门闭春色。
春色深，春色深，君王一去何时寻。
春雨洒，春雨洒，周南一望堪泪下。
蓬莱殿中寝胡人，鳷鹊楼前放胡马。
闻君欲行西入秦，君行不用过天津。
天津桥上多胡尘，洛阳道上愁杀人。','',''),('quantangshi-10571','行路难','馮著','quantangshi','','卷11','男儿轗轲徒搔首，入市脱衣且沽酒。
行路难，权门慎勿干，平人争路相摧残。
春秋四气更回换，人事何须再三叹。
君不见雀为鸽，鹰为鸠，东海成田谷为岸。
负薪客，归去来，龟反顾，鹤裴回，黄河岸上起尘埃。
相逢未相识，何用强相猜。
行路难，故山应不改，茅舍汉中在。
白酒杯中聊一歌，苍蝇苍蝇奈尔何。','',''),('quantangshi-10572','燕衔泥','馮著','quantangshi','','卷11','双燕碌碌飞入屋，屋中老人喜燕归。
裴回绕我牀头飞，去年为尔逐黄雀。
雨多屋漏泥土落，尔莫厌老翁茅屋低，梁头作窠梁下栖。
尔不见东家黄鷇鸣啧啧，蛇盘瓦沟鼠穿壁。
豪家大屋尔莫居，娇儿少妇采尔雏。
井旁写水泥自足，衔泥上屋随尔欲。','',''),('quantangshi-10573','同孟浩然宴赋','王迥','quantangshi','','卷11','屈宋英声今止已，江山继嗣多才子。
作者于今尽相似，聚宴王家其乐矣。
共赋新诗发宫征，书于屋壁彰厥美。','',''),('quantangshi-10574','尚书都堂瓦松','李曄','quantangshi','','卷11','华省祕仙踪，高堂露瓦松。
叶因春后长，花为雨来浓。
影混鸳鸯色，光含翡翠容。
天然斯所寄，地势太无从。
接栋临双阙，连甍近九重。
宁知深涧底，霜雪岁兼封。','',''),('quantangshi-10575','省试七月流火','敬括','quantangshi','','卷11','前庭一叶下，言念忽悲秋。
变节金初至，分寒火正流。
气含凉夜早，光拂夏云收。
助月微明散，沿河丽景浮。
礼标时令爽，诗兴国风幽。
自此观邦正，深知王业休。','',''),('quantangshi-10576','奉赠韦左丞二十二韵','杜甫','quantangshi','','卷11','纨袴不饿死，儒冠多误身。
丈人试静听，贱子请具陈。
甫昔少年日，早充观国宾。
读书破万卷，下笔如有神。
赋料扬雄敌，诗看子建亲。
李邕求识面，王翰愿卜邻。
自谓颇挺出，立登要路津。
致君尧舜上，再使风俗淳。
此意竟萧条，行歌非隐沦。
骑驴三十载，旅食京华春。
朝扣富儿门，暮随肥马尘。
残杯与冷炙，到处潜悲辛。
主上顷见征，歘然欲求伸。
青冥却垂翅，蹭蹬无纵鳞。
甚愧丈人厚，甚知丈人真。
每于百僚上，猥诵佳句新。
窃效贡公喜，难甘原宪贫。
焉能心怏怏，秪是走踆踆。
今欲东入海，即将西去秦。
尚怜终南山，回首清渭滨。
常拟报一饭，况怀辞大臣。
白鸥没浩荡，万里谁能驯。','',''),('quantangshi-10577','送高三十五书记','杜甫','quantangshi','','卷11','崆峒小麦熟，且愿休王师。
请公问主将，焉用穷荒为。
饥鹰未饱肉，侧翅随人飞。
高生跨鞍马，有似幽并儿。
脱身簿尉中，始与捶楚辞。
借问今何官，触热向武威。
答云一书记，所愧国士知。
人实不易知，更须慎其仪。
十年出幕府，自可持旌麾。
此行既特达，足以慰所思。
男儿功名遂，亦在老大时。
常恨结驩浅，各在天一涯。
又如参与商，惨惨中肠悲。
惊风吹鸿鹄，不得相追随。
黄尘翳沙漠，念子何当归。
边城有余力，早寄从军诗。','',''),('quantangshi-10578','赠李白','杜甫','quantangshi','','卷11','二年客东都，所历厌机巧。
野人对膻腥，蔬食常不饱。
岂无青精饭，使我颜色好。
苦乏大药资，山林迹如扫。
李侯金闺彦，脱身事幽讨。
亦有梁宋游，方期拾瑶草。','',''),('quantangshi-10579','游龙门奉先寺','杜甫','quantangshi','','卷11','已从招提游，更宿招提境。
阴壑生虚籁，月林散清影。
天阙象纬逼，云卧衣裳冷。
欲觉闻晨钟，令人发深省。','',''),('quantangshi-10580','望岳','杜甫','quantangshi','','卷11','岱宗夫如何，齐鲁青未了。
造化钟神秀，阴阳割昏晓。
荡胷生曾云，决眦入归鸟。
会当凌绝顶，一览众山小。','',''),('quantangshi-10581','陪李北海宴历下亭','杜甫','quantangshi','','卷11','东藩驻皂盖，北渚凌青荷。
海内此亭古，济南名士多。
云山已发兴，玉佩仍当歌。
修竹不受暑，交流空涌波。
蕴真惬所遇，落日将如何。
贵贱俱物役，从公难重过。','',''),('quantangshi-10582','同李太守登历下古城员外新亭亭对鹊湖','杜甫','quantangshi','','卷11','新亭结构罢，隐见清湖阴。
迹籍台观旧，气溟海岳深。
圆荷想自昔，遗堞感至今。
芳宴此时具，哀丝千古心。
主称寿尊客，筵秩宴北林。
不阻蓬荜兴，得兼梁甫吟。','',''),('quantangshi-10583','玄都坛歌寄元逸人','杜甫','quantangshi','','卷11','故人昔隐东蒙峰，已佩含景苍精龙。
故人今居子午谷，独在阴崖结茅屋。
屋前太古玄都坛，青石漠漠常风寒。
子规夜啼山竹裂，王母昼下云旗翻。
知君此计成长往，芝草琅玕日应长。
铁鏁高垂不可攀，致身福地何萧爽。','',''),('quantangshi-10584','今夕行','杜甫','quantangshi','','卷11','今夕何夕岁云徂，更长烛明不可孤。
咸阳客舍一事无，相与博塞为欢娱。
冯陵大叫呼五白，袒跣不肯成枭卢。
英雄有时亦如此，邂逅岂即非良图。
君莫笑刘毅从来布衣愿，家无儋石输百万。','',''),('quantangshi-10585','贫交行','杜甫','quantangshi','','卷11','飜手作云覆手雨，纷纷轻薄何须数。
不见管鲍贫时交，此道今人弃如土。','',''),('quantangshi-10586','兵车行','杜甫','quantangshi','','卷11','车辚辚，马萧萧，行人弓箭各在腰。
耶娘妻子走相送，尘埃不见咸阳桥。
牵衣顿足阑道哭，哭声直上干云霄。
道傍过者问行人，行人但云点行频。
或从十五北防河，便至四十西营田。
去时里正与裹头，归来头白还戍边。
边亭流血成海水，武皇开边意未已。
君不闻汉家山东二百州，千村万落生荆杞。
纵有健妇把锄犂，禾生陇亩无东西。
况复秦兵耐苦战，被驱不异犬与鸡。
长者虽有问，役夫敢申恨。
且如今年冬，未休关西卒。
县官急索租，租税从何出？
信知生男恶，反是生女好。
生女犹是嫁比邻，生男埋没随百草。
君不见青海头，古来白骨无人收。
新鬼烦冤旧鬼哭，天阴雨湿声啾啾。','',''),('quantangshi-10587','高都护骢马行','杜甫','quantangshi','','卷11','安西都护胡青骢，声价歘然来向东。
此马临阵久无敌，与人一心成大功。
功成惠养随所致，飘飘远自流沙至。
雄姿未受伏枥恩，猛气犹思战场利。
腕促蹄高如踣铁，交河几蹴曾冰裂。
五花散作云满身，万里方看汗流血。
长安壮儿不敢骑，走过掣电倾城知。
青丝络头为君老，何由却出横门道。','',''),('quantangshi-10588','天育骠骑歌','杜甫','quantangshi','','卷11','吾闻天子之马走千里，今之画图无乃是。
是何意态雄且杰，骏尾萧梢朔风起。
毛为绿缥两耳黄，眼有紫焰双瞳方。
矫矫龙性合变化，卓立天骨森开张。
伊昔太仆张景顺，监牧攻驹阅清峻。
遂令大奴守天育，别养骥子怜神俊。
当时四十万匹马，张公叹其材尽下。
故独写真传世人，见之座右久更新。
年多物化空形影，呜呼健步无由骋。
如今岂无騕褭与骅骝，时无王良伯乐死即休。','',''),('quantangshi-10589','白丝行','杜甫','quantangshi','','卷11','缫丝须长不须白，越罗蜀锦金粟尺。
象牀玉手乱殷红，万草千花动凝碧。
已悲素质随时染，裂下鸣机色相射。
美人细意熨帖平，裁缝灭尽针线迹。
春天衣着为君舞，蛱蜨飞来黄鹂语。
落絮游丝亦有情，随风照日宜轻举。
香汗轻尘污颜色，开新合故置何许。
君不见才士汲引难，恐惧弃捐忍羁旅。','',''),('quantangshi-10590','秋雨叹三首 一','杜甫','quantangshi','','卷11','雨中百草秋烂死，阶下决明颜色鲜。
着叶满枝翠羽盖，开花无树黄金钱。
凉风萧萧吹汝急，恐汝后时难独立。
堂上书生空白头，临风三齅馨香泣。','',''),('quantangshi-10591','秋雨叹三首 二','杜甫','quantangshi','','卷11','阑风长雨（一作“东风细雨”）秋纷纷，四海（一作“万里”）八荒同一云。
去马来牛不复辨，浊泾清渭何当分。
禾（一作“木”）头生耳黍穗黑，农夫田妇（一作“父”）无消息。
城中斗米换（一作“抱”）衾裯，相许宁论两相直。','',''),('quantangshi-10592','秋雨叹三首 三','杜甫','quantangshi','','卷11','长安布衣谁比数，反鏁衡门守环堵。
老夫不出长蓬蒿，穉子无忧走（一作“奏”）风雨。
雨声飕飕催早寒，胡雁翅湿高飞难。
秋来未曾（一作“省”）见白日，埿污后（一作“厚”）土何时干？','',''),('quantangshi-10593','叹庭前甘菊花','杜甫','quantangshi','','卷11','檐前甘菊移时晚，青蘂重阳不堪摘。
明日萧条醉尽醒，残花烂熳开何益。
篱边野外多众芳，采撷细琐升中堂。
念兹空长大枝叶，结根失所缠风霜。','',''),('quantangshi-10594','醉时歌','杜甫','quantangshi','','卷11','诸公衮衮登台省，广文先生官独冷。
甲第纷纷厌粱肉，广文先生饭不足。
先生有道出羲皇，先生有才过屈宋。
德尊一代常轗轲，名垂万古知何用。
杜陵野客人更嗤，被褐短窄鬓如丝。
日籴太仓五升米，时赴郑老同襟期。
得钱即相觅，沽酒不复疑。
忘形到尔汝，痛饮真吾师。
清夜沈沈动春酌，灯前细雨檐花落。
但觉高歌有鬼神，焉知饿死填沟壑。
相如逸才亲涤器，子云识字终投阁。
先生早赋归去来，石田茅屋荒苍苔。
儒术于我何有哉，孔丘盗跖俱尘埃。
不须闻此意惨怆，生前相遇且衔杯。','',''),('quantangshi-10595','醉歌行','杜甫','quantangshi','','卷11','陆机二十作文赋，汝更小年能缀文。
总角草书又神速，世上儿子徒纷纷。
骅骝作驹已汗血，鸷鸟举翮连青云。
词源倒流三峡水，笔阵独埽千人军。
只今年才十六七，射策军门期第一。
旧穿杨叶真自知，暂蹶霜蹄未为失。
偶然擢秀非难取，会是排风有毛质。
汝身已见唾成珠，汝伯何由发如漆。
春光澹沲秦东亭，渚蒲牙白水荇青。
风吹客衣日杲杲，树搅离思花冥冥。
酒尽沙头双玉瓶，众宾皆醉我独醒。
乃知贫贱别更苦，吞声踯躅涕泪零。','',''),('quantangshi-10596','赠卫八处士','杜甫','quantangshi','','卷11','人生不相见，动如参与商。
今夕复何夕，共此灯烛光。
少壮能几时，鬓发各已苍。
访旧半为鬼，惊呼热中肠。
焉知二十载，重上君子堂。
昔别君未婚，儿女忽成行。
怡然敬父执，问我来何方。
问答乃未已，儿女罗酒浆。
夜雨剪春韭，新炊间黄粱。
主称会面难，一举累十觞。
十觞亦不醉，感子故意长。
明日隔山岳，世事两茫茫。','',''),('quantangshi-10597','苦雨奉寄陇西公兼呈王征士','杜甫','quantangshi','','卷11','今秋乃淫雨，仲月来寒风。
羣木水光下，万象云气中。
所思碍行潦，九里信不通。
悄悄素浐路，迢迢天汉东。
愿腾六尺马，背若孤征鸿。
划见公子面，超然欢笑同。
奋飞既胡越，局促伤樊笼。
一饭四五起，凭轩心力穷。
嘉蔬没混浊，时菊碎榛丛。
鹰隼亦屈猛，乌鸢何所蒙。
式瞻北邻居，取适南巷翁。
挂席钓川涨，焉知清兴终。','',''),('quantangshi-10598','同诸公登慈恩寺塔','杜甫','quantangshi','','卷11','高标跨苍天，烈风无时休。
自非旷士怀，登兹翻百忧。
方知象教力，足可追冥搜。
仰穿龙蛇窟，始出枝撑幽。
七星在北户，河汉声西流。
羲和鞭白日，少昊行清秋。
秦山忽破碎，泾渭不可求。
俯视但一气，焉能辨皇州。
回首叫虞舜，苍梧云正愁。
惜哉瑶池饮，日宴昆仑丘。
黄鹄去不息，哀鸣何所投。
君看随阳雁，各有稻粱谋。','',''),('quantangshi-10599','示从孙济','杜甫','quantangshi','','卷11','平明跨驴出，未知适谁门。
权门多噂𠴲，且复寻诸孙。
诸孙贫无事，宅舍如荒村。
堂前自生竹，堂后自生萱。
萱草秋已死，竹枝霜不蕃。
淘米少汲水，汲多井水浑。
刈葵莫放手，放手伤葵根。
阿翁嬾惰久，觉儿行步奔。
所来为宗族，亦不为盘飧。
小人利口实，薄俗难可论。
勿受外嫌猜，同姓古所敦。','',''),('quantangshi-10600','九日寄岑参','杜甫','quantangshi','','卷11','出门复入门，两脚但如旧。
所向泥活活，思君令人瘦。
沈吟坐西轩，饮食错昏昼。
寸步曲江头，难为一相就。
吁嗟呼苍生，稼穑不可救。
安得诛云师，畴能补天漏。
大明韬日月，旷野号禽兽。
君子强逶迤，小人困驰骤。
维南有崇山，恐与川浸溜。
是节东篱菊，纷披为谁秀。
岑生多新诗，性亦嗜醇酎。
采采黄金花，何由满衣袖。','',''),('quantangshi-10601','送孔巢父谢病归游江东兼呈李白','杜甫','quantangshi','','卷11','巢父掉头不肯住，东将入海随烟雾。
诗卷长流天地间，钓竿欲拂珊瑚树。
深山大泽龙蛇远，春寒野阴风景暮。
蓬莱织女回云车，指点虚无是征路。
自是君身有仙骨，世人那得知其故。
惜君只欲苦死留，富贵何如草头露。
蔡侯静者意有余，清夜置酒临前除。
罢琴惆怅月照席，几岁寄我空中书。
南寻禹穴见李白，道甫问信今何如。','',''),('quantangshi-10602','饮中八仙歌','杜甫','quantangshi','','卷11','知章骑马似乘船，眼花落井水底眠。
汝阳三斗始朝天，道逢麴车口流涎。
恨不移封向酒泉，左相日兴费万钱。
饮如长鲸吸百川，衔杯乐圣称世贤。
宗之潇洒美少年，举觞白眼望青天。
皎如玉树临风前，苏晋长斋绣佛前。
醉中往往爱逃禅，李白一斗诗百篇。
长安市上酒家眠，天子呼来不上船。
自称臣是酒中仙，张旭三杯草圣传。
脱帽露顶王公前，挥毫落纸如云烟。
焦遂五斗方卓然，高谈雄辨惊四筵。','',''),('quantangshi-10603','曲江三章章五句 一','杜甫','quantangshi','','卷11','曲江萧条秋气高，菱荷枯折随风涛。
游子空嗟垂二毛，白石素沙亦相荡，哀鸿独叫求其曹。','',''),('quantangshi-10604','曲江三章章五句 二','杜甫','quantangshi','','卷11','即事非今亦非古，长歌激越梢林莽。
比屋豪华固难数，吾人甘作心似灰，弟侄何伤泪如雨。','',''),('quantangshi-10605','曲江三章章五句 三','杜甫','quantangshi','','卷11','自断此生休问天，杜曲幸有桑麻田。
故将移住南山边，短衣匹马随李广，看射猛虎终残年。','',''),('quantangshi-10606','丽人行','杜甫','quantangshi','','卷11','三月三日天气新，长安水边多丽人。
态浓意远淑且真，肌理细腻骨肉匀。
绣罗衣裳照暮春，蹙金孔雀银麒麟。
头上何所有，翠微㔩叶垂鬓唇。
背后何所见，珠压腰衱稳称身。
就中云幕椒房亲，赐名大国虢与秦。
紫驼之峰出翠釜，水精之盘行素鳞。
犀箸厌饫久未下，銮刀缕切空纷纶。
黄门飞鞚不动尘，御厨络绎送八珍。
箫鼓哀吟感鬼神，宾从杂遝实要津。
后来鞍马何逡巡，当轩下马入锦茵。
杨花雪落覆白苹，青鸟飞去衔红巾。
炙手可热势绝伦，慎莫近前丞相嗔。','',''),('quantangshi-10607','乐游园歌','杜甫','quantangshi','','卷11','乐游古园崒森爽，烟緜碧草萋萋长。
公子华筵势最高，秦川对酒平如掌。
长生木瓢示真率，更调鞍马狂欢赏。
青春波浪芙蓉园，白日雷霆夹城仗。
阊阖晴开昳荡荡，曲江翠幕排银牓。
拂水低徊舞袖飜，缘云清切歌声上。
却忆年年人醉时，只今未醉已先悲。
数茎白发那抛得，百罚深杯亦不辞。
圣朝亦知贱士丑，一物自荷皇天慈。
此身饮罢无归处，独立苍茫自咏诗。','',''),('quantangshi-10608','渼陂行','杜甫','quantangshi','','卷11','岑参兄弟皆好奇，携我远来游渼陂。
天地黤惨忽异色，波涛万顷堆琉璃。
琉璃汗漫泛舟入，事殊兴极忧思集。
鼍作鲸吞不复知，恶风白浪何嗟及。
主人锦帆相为开，舟子喜甚无氛埃。
凫鹥散乱棹讴发，丝管啁啾空翠来。
沈竿续蔓深莫测，菱叶荷花静如拭。
宛在中流渤澥清，下归无极终南黑。
半陂已南纯浸山，动影褭窕冲融间。
船舷暝戛云际寺，水面月出蓝田关。
此时骊龙亦吐珠，冯夷击鼓羣龙趋。
湘妃汉女出歌舞，金支翠旗光有无。
咫尺但愁雷雨至，苍茫不晓神灵意。
少壮几时奈老何，向来哀乐何其多。','',''),('quantangshi-10609','渼陂西南台','杜甫','quantangshi','','卷11','高台面苍陂，六月风日冷。
蒹葭离披去，天水相与永。
怀新目似击，接要心已领。
仿像识鲛人，空蒙辨鱼艇。
错磨终南翠，颠倒白阁影。
崷崒增光辉，乘陵惜俄顷。
劳生愧严郑，外物慕张邴。
世复轻骅骝，吾甘杂鼃黾。
知归俗可忽，取适事莫竝。
身退岂待官，老来苦便静。
况资菱芡足，庶结茅茨迥。
从此具扁舟，弥年逐清景。','',''),('quantangshi-10610','戏简郑广文虔兼呈苏司业源明','杜甫','quantangshi','','卷11','广文到官舍，系马堂阶下。
醉则骑马归，颇遭官长駡。
才名四十年，坐客寒无氊。
赖有苏司业，时时与酒钱。','',''),('quantangshi-10611','夏日李公见访','杜甫','quantangshi','','卷11','远林暑气薄，公子过我游。
贫居类村坞，僻近城南楼。
旁舍颇淳朴，所愿亦易求。
隔屋唤西家，借问有酒不。
墙头过浊醪，展席俯长流。
清风左右至，客意已惊秋。
巢多众鸟鬬，叶密鸣蝉稠。
苦道此物聒，孰谓吾庐幽。
水花晚色静，庶足充淹留。
预恐尊中尽，更起为君谋。','',''),('quantangshi-10612','奉同郭给事汤东灵湫作','杜甫','quantangshi','','卷11','东山气鸿蒙，宫殿居上头。
君来必十月，树羽临九州。
阴火煮玉泉，喷薄涨岩幽。
有时浴赤日，光抱空中搂。
阆风入辙迹，旷原延冥搜。
沸天万乘动，观水百丈湫。
幽灵斯可佳，王命宫属休。
初闻龙用壮，擘石摧林丘。
中夜窟宅改，移因风雨秋。
倒悬瑶池影，屈注苍江流。
味如甘露浆，挥弄滑且柔。
翠旗澹偃蹇，云车纷少留。
箫鼓荡四溟，异香泱漭浮。
鲛人献微绡，曾祝沈豪牛。
百祥奔盛明，古先莫能俦。
坡陀金虾蟆，出见盖有由。
至尊顾之笑，王母不肯收。
复归虚无底，化作长黄虬。
飘飘青琐郎，文采珊瑚钩。
浩歌渌水曲，清绝听者愁。','',''),('quantangshi-10613','夜听许十损诵诗爱而有作','杜甫','quantangshi','','卷11','许生五台宾，业白出石壁。
余亦师粲可，身犹缚禅寂。
何阶子方便，谬引为匹敌。
离索晚相逢，包蒙欣有击。
诵诗浑游衍，四座皆辟易。
应手看捶钩，清心听鸣镝。
精微穿溟涬，飞动摧霹雳。
陶谢不枝梧，风骚共推激。
紫燕自超诣，翠驳谁翦剔。
君意人莫知，人间夜寥阒。','',''),('quantangshi-10614','桥陵诗三十韵因呈县内诸官','杜甫','quantangshi','','卷11','先帝昔晏驾，兹山朝百灵。
崇冈拥象设，沃野开天庭。
即事壮重险，论功超五丁。
坡陀因厚地，却略罗峻屏。
云阙虚冉冉，风松肃泠泠。
石门霜露白，玉殿莓苔青。
宫女晚知曙，祠官朝见星。
空梁簇画戟，阴井敲铜瓶。
中使日夜继，惟王心不宁。
岂徒恤备享，尚谓求无形。
孝理敦国政，神凝推道经。
瑞芝产庙柱，好鸟鸣岩扃。
高岳前嵂崒，洪河左滢濙。
金城蓄峻址，沙苑交回汀。
永与奥区固，川原纷眇冥。
居然赤县立，台榭争岧亭。
官属果称是，声华真可听。
王刘美竹润，裴李春兰馨。
郑氏才振古，啖侯笔不停。
遣辞必中律，利物常发硎。
绮绣相展转，琳琅愈青荧。
侧闻鲁恭化，秉德崔瑗铭。
太史侯凫影，王乔随鹤翎。
朝仪限霄汉，客思回林坰。
轗轲辞下杜，飘颻陵浊泾。
诸生旧短褐，旅泛一浮萍。
荒岁儿女瘦，暮途涕泗零。
主人念老马，廨署容秋萤。
流寓理岂惬，穷愁醉未醒。
何当摆俗累，浩荡乘沧溟。','',''),('quantangshi-10615','沙苑行','杜甫','quantangshi','','卷11','君不见左辅白沙如白水，缭以周墙百余里。
龙媒昔是渥洼生，汗血今称献于此。
苑中騋牝三千匹，丰草青青寒不死。
食之豪健西域无，每岁攻驹冠边鄙。
王有虎臣司苑门，入门天厩皆云屯。
驌骦一骨独当御，春秋二时归至尊。
至尊内外马盈亿，伏枥在坰空大存。
逸羣绝足信殊杰，倜傥权奇难具论。
累累塠阜藏奔突，往往坡陀纵超越。
角壮飜同糜鹿游，浮身簸荡鼋鼍窟。
泉出巨鱼长比人，丹砂作尾黄金鳞。
岂知异物同精气，虽未成龙亦有神。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-10616','聪马行','杜甫','quantangshi','','卷11','邓公马癖人共知，初得花骢大宛种。
夙昔传闻思一见，牵来左右神皆竦。
雄姿逸态何崷崪，顾影骄嘶自矜宠。
隅目青荧夹镜悬，肉骏碨礌连钱动。
朝来久试华轩下，未觉千金满高价。
赤汗微生白雪毛，银鞍却覆香罗帕。
卿家旧赐公取之，天厩真龙此其亚。
昼洗须腾泾渭深，朝趋可刷幽并夜。
吾闻良骥老始成，此马数年人更惊。
岂有四蹄疾于鸟，不与八骏俱先鸣。
时俗造次那得致，云雾晦冥方降精。
近闻下诏喧都邑，肯使骐驎地上行。','',''),('quantangshi-10617','去矣行','杜甫','quantangshi','','卷11','君不见韝上鹰，一饱则飞掣。
焉能作堂上燕，衔泥附炎热。
野人旷荡无腼颜，岂可久在王侯间。
未试囊中餐玉法，明朝且入蓝田山。','',''),('quantangshi-10618','自京赴奉先县咏怀五百字','杜甫','quantangshi','','卷11','杜陵有布衣，老大意转拙。
许身一何愚，窃比稷与契。
居然成濩落，白手甘契阔。
盖棺事则已，此志常觊豁。
穷年忧黎元，叹息肠内热。
取笑同学翁，浩歌弥激烈。
非无江海志，萧洒送日月。
生逢尧舜君，不忍便永诀。
当今廊庙具，构厦岂云缺。
葵藿倾太阳，物性固莫夺。
顾惟蝼蚁辈，但自求其穴。
胡为慕大鲸，辄拟偃溟渤。
以兹悟生理，独耻事干谒。
兀兀遂至今，忍为尘埃没。
终愧巢与由，未能易其节。
沈饮聊自适，放歌颇愁绝。
岁暮百草零，疾风高冈裂。
天衢阴峥嵘，客子中夜发。
霜严衣带断，指直不得结。
凌晨过骊山，御榻在嵽嵲。
蚩尤塞寒空，蹴蹋崖谷滑。
瑶池气郁律，羽林相摩戛。
君臣留欢娱，乐动殷樛嶱。
赐浴皆长缨，与宴非短褐。
彤庭所分帛，本自寒女出。
鞭挞其夫家，聚敛贡城阙。
圣人筐篚恩，实欲邦国活。
臣如忽至理，君岂弃此物。
多士盈朝廷，仁者宜战栗。
况闻内金盘，尽在卫霍室。
中堂舞神仙，烟雾散玉质。
暖客貂鼠裘，悲管逐清瑟。
劝客驼蹄羹，霜橙压香橘。
朱门酒肉臭，路有冻死骨。
荣枯咫尺异，惆怅难再述。
北辕就泾渭，官渡又改辙。
羣冰从西下，极目高崪兀。
疑是崆峒来，恐触天柱折。
河梁幸未坼，枝撑声窸窣。
行旅相攀援，川广不可越。
老妻寄异县，十口隔风雪。
谁能久不顾，庶往共饥渴。
入门闻号啕，幼子饥已卒。
吾宁舍一哀，里巷亦呜咽。
所愧为人父，无食致夭折。
岂知秋未登，贫寠有苍卒。
生常免租税，名不隶征伐。
抚迹犹酸辛，平人固骚屑。
默思失业徒，因念远戍卒。
忧端齐终南，澒洞不可掇。','',''),('quantangshi-10619','奉先刘少府新画山水障歌','杜甫','quantangshi','','卷11','堂上不合生枫树，怪底江山起烟雾。
闻君埽却赤县图，乘兴谴画沧洲趣。
画师亦无数，好手不可遇。
对此融心神，知君重毫素。
岂但祁岳与郑虔，笔迹远过杨契丹。
得非悬圃裂，无乃潇湘飜。
悄然坐我天姥下，耳边已似闻清猨。
反思前夜风雨急，乃是蒲城鬼神人。
元气淋漓障犹湿，真宰上诉天应泣。
野亭春还杂花远，渔翁暝蹋孤舟立。
沧浪水深青溟阔，攲岸侧岛秋毫末。
不见湘妃鼓瑟时，至今斑竹临江活。
刘侯天机精，爱画入骨髓。
自有两儿郎，挥洒亦莫比。
大儿聪明到，能添老树巅崖里。
小儿心孔开，貌得山僧及童子。
若耶溪，云门寺。
吾独胡为在泥滓，青鞵布韤从此始。','',''),('quantangshi-10620','白水县崔少府十九翁高斋三十韵','杜甫','quantangshi','','卷11','客从南县来，浩荡无与适。
旅食白日长，况当朱炎赫。
高斋坐林杪，信宿游衍阒。
清晨陪跻攀，傲睨俯峭壁。
崇冈相枕带，旷野怀咫尺。
始知贤主人，赠此遣愁寂。
危阶根青冥，曾冰生淅沥。
上有无心云，下有欲落石。
泉声闻复急，动静随所击。
鸟呼藏其身，有似惧弹射。
吏隐道性情，兹焉其窟宅。
白水见舅氏，诸翁乃仙伯。
杖藜长松阴，作尉穷谷僻。
为我炊雕胡，逍遥展良觌。
坐久风颇愁，晚来山更碧。
相对十丈蛟，歘翻盘涡坼。
何得空里雷，殷殷寻地脉。
烟氛蔼崷崪，魍魉森惨戚。
昆仑崆峒颠，回首如不隔。
前轩颓反照，巉绝华岳赤。
兵气涨林峦，川光杂锋镝。
知是相公军，铁马云雾积。
玉觞淡无味，胡羯岂强敌。
长歌激屋梁，泪下流衽席。
人生半哀乐，天地有顺逆。
慨彼万国夫，休明备征狄。
猛将纷填委，庙谋蓄长策。
东郊何时开，带甲且来释。
欲告清宴罢，难拒幽明迫。
三叹酒食旁，何由似平昔。','',''),('quantangshi-10621','三川观水涨二十韵','杜甫','quantangshi','','卷11','我经华原来，不复见平陆。
北上唯土山，连山走穷谷。
火云无时出，飞电常在目。
自多穷岫雨，行潦相豗蹙。
蓊匌川气黄，羣流会空曲。
清晨望高浪，忽谓阴崖踣。
恐泥窜蛟龙，登危聚麋鹿。
枯查卷拔树，礧磈共充塞。
声吹鬼神下，势阅人代速。
不有万穴归，何以尊四渎。
及观泉源涨，反惧江海覆。
漂沙坼岸去，漱壑松柏秃。
乘陵破山门，回斡裂地轴。
交洛赴洪河，及关岂信宿。
应沈数州没，如听万室哭。
秽浊殊未清，风涛怒犹蓄。
何时通舟车，阴气不黪黩。
浮生有荡汨，吾道正羁束。
人寰难容身，石壁滑侧足。
云雷此不已，艰险路更局。
普天无川梁，欲济愿水缩。
因悲中林士，未脱众鱼腹。
举头向苍天，安得骑鸿鹄。','',''),('quantangshi-10622','悲陈陶','杜甫','quantangshi','','卷11','孟冬十郡良家子，血作陈陶泽中水。
野旷天清无战声，四万义军同日死。
羣胡归来血洗箭，仍唱胡歌饮都市。
都人回面北向啼，日夜更望官军至。','',''),('quantangshi-10623','悲青坂','杜甫','quantangshi','','卷11','我军青坂在东门，天寒饮马太白窟。
黄头奚儿日向西，数骑弯弓敢驰突。
山雪河冰野萧飋，青是烽烟白人骨。','',''),('quantangshi-10624','哀江头','杜甫','quantangshi','','卷11','少陵野老吞声哭，春日潜行曲江曲。
江头宫殿锁千门，细柳新蒲为谁绿。
忆昔霓旌下南苑，苑中万物生颜色。
昭阳殿里第一人，同辇随君侍君侧。
辇前才人带弓箭，白马嚼啮黄金勒。
翻身向天仰射云，一箭正坠双飞翼。
明眸皓齿今何在，血污游魂归不得。
清渭东流劒阁深，去住彼此无消息。
人生有情泪霑臆，江水江花岂终极。
黄昏胡骑尘满城，欲往城南忘南北。','',''),('quantangshi-10625','哀王孙','杜甫','quantangshi','','卷11','长安城头头白乌，夜飞延秋门上呼。
又向人家啄大屋，屋底达官走避胡。
金鞭断折九马死，骨肉不待同驰驱。
腰下实玦青珊瑚，可怜王孙泣路隅。
问之不肯道姓名，但道困苦乞为奴。
已经百日窜荆棘，身上无有完肌肤。
高帝子孙尽隆准，龙种自与常人殊。
豺狼在邑龙在野，王孙善保千金躯。
不敢长语临交衢，且为王孙立斯须。
昨夜东风吹血腥，东来橐驼满旧都。
朔方健儿好身手，昔何勇锐今何愚。
窃闻天子已传位，贤德北服南单于。
花门剺面请雪耻，慎勿出口他人狙。
哀哉王孙慎勿疎，五陵佳气无时无。','',''),('quantangshi-10626','大云寺赞公房四首 一','杜甫','quantangshi','','卷11','心在水精域，衣霑春雨时。
洞门尽徐步，深院果幽期。
到扉开复闭，撞钟斋及兹。
醍醐长发性，饮食过扶衰。
把臂有多日，开怀无愧辞。
黄鹂度结构，紫鸽下罘罳。
愚意会所适，花边行自迟。
汤休起我病，微笑索题诗。','',''),('quantangshi-10627','大云寺赞公房四首 二','杜甫','quantangshi','','卷11','细软青丝履，光明白氎巾。
深藏供老宿，取用及吾身。
自顾转无趣，交情何尚新。
道林才不世，惠远德过人。
雨泻暮檐竹，风吹青井芹。
天阴对图画，最觉润龙鳞。','',''),('quantangshi-10628','大云寺赞公房四首 三','杜甫','quantangshi','','卷11','灯影照无睡，心清闻妙香。
夜深殿突兀，风动金锒铛。
天黑闭春院，地清栖暗芳。
玉绳回断绝，铁凤森翱翔。
梵放时出寺，钟残仍殷牀。
明朝在沃野，苦见尘沙黄。','',''),('quantangshi-10629','大云寺赞公房四首 四','杜甫','quantangshi','','卷11','童儿汲井华，惯捷瓶上手。
沾洒不濡地，埽除似无帚。
明霞烂复阁，霁雾搴高牖。
侧塞被径花，飘颻委墀柳。
艰难世事迫，隐遯佳期后。
晤语契深心，那能总箝口。
奉辞还杖策，暂别终回首。
泱泱泥污人，听听国多狗。
既未免羁绊，时来憩奔走。
近公如白雪，执热烦何有。','',''),('quantangshi-10630','苏端薛复筵简薛华醉歌','杜甫','quantangshi','','卷11','文章有神交有道，端复得之名誉早。
爱客满堂尽豪翰，开筵上日思芳草。
安得健步移远梅，乱插繁花向晴昊。
千里犹残旧冰雪，百壶且试开怀抱。
垂老恶闻战鼓悲，急觞为缓忧心捣。
少年努力纵谈笑，看我形容已枯槁。
坐中薛华善醉歌，歌辞自作风格老。
近来海内为长句，汝与山东李白好。
何刘沈谢力未工，才兼鲍昭愁绝倒。
诸生颇尽新知乐，万事终伤不自保。
气酣日落西风来，愿吹野水添金杯。','',''),('quantangshi-10631','晦日寻崔戢李封','杜甫','quantangshi','','卷11','朝光入瓮牖，尸寝惊敝裘。
起行视天宇，春气渐和柔。
兴来不暇嬾，今晨梳我头。
出门无所待，徒步觉自由。
杖藜复恣意，免值公与侯。
晚定崔李交，会心真罕俦。
每过得酒倾，二宅可淹留。
喜结仁里欢，况因令节求。
李生园欲荒，旧竹颇修修。
引客看埽除，随时成献酬。
崔侯初筵色，已畏空尊愁。
未知天下士，至性有此不。
草牙既青出，蜂声亦暖游。
思见农器陈，何当甲兵休。
上古葛天民，不贻黄屋忧。
至今阮籍等，熟醉为身谋。
威凤高其翔，长鲸吞九洲。
地轴为之翻，百川昔乱流。
当歌欲一放，泪下恐莫收。
浊醪有妙理，庶用慰沈浮。','',''),('quantangshi-10632','雨过苏端','杜甫','quantangshi','','卷11','鸡鸣风雨交，久旱云亦好。
杖藜入春泥，无食起我早。
诸家忆所历，一饭迹便埽。
苏侯得数过，欢喜每倾倒。
也复可怜人，呼儿具梨枣。
浊醪必在眼，尽醉摅怀抱。
红稠屋角花，碧委墙隅草。
亲宾纵谈谑，喧闹畏衰老。
况蒙霈泽垂，粮粒或自保。
妻孥隔军垒，拨弃不拟道。','',''),('quantangshi-10633','喜晴','杜甫','quantangshi','','卷11','皇天久不雨，既雨晴亦佳。
出郭眺西郊，肃肃春增华。
青荧陵陂麦，窈窕桃李花。
春夏各有实，我饥岂无涯。
干戈虽横放，惨澹鬬龙蛇。
甘泽不犹愈，且耕今未赊。
丈夫则带甲，妇女终在家。
力难及黍稷，得种菜与麻。
千载商山芝，往者东门瓜。
其人骨已朽，此道谁疵瑕。
英贤遇轗轲，远引蟠泥沙。
顾慙昧所适，回首白日斜。
汉阴有鹿门，沧海有灵查。
焉能学众口，咄咄空咨嗟。','',''),('quantangshi-10634','送率府程录事还乡','杜甫','quantangshi','','卷11','鄙夫行衰谢，抱病昏妄集。
当时往还人，记一不识十。
程侯晚相遇，与语才杰立。
熏然耳目开，颇觉聪明人。
千载得鲍叔，末契有所及。
意钟老柏青，义动修蛇蛰。
若人可数见，慰我垂白泣。
告别无淹晷，百忧复相袭。
内愧突不黔，庶羞以赒给。
素丝挈长鱼，碧酒随玉粒。
途穷见交态，世梗悲路涩。
东风吹春冰，泱莽后土湿。
念君惜羽翮，既饱更思戢。
莫作翻云鹘，闻呼向禽急。','',''),('quantangshi-10635','述怀一首','杜甫','quantangshi','','卷11','去年潼关破，妻子隔绝久。
今夏草木长，脱身得西走。
麻鞋见天子，衣袖露两肘。
朝廷慜生还，亲故伤老丑。
涕泪授拾遗，流离主恩厚。
柴门虽得去，未忍即开口。
寄书问三川，不知家在否。
比闻同罹祸，杀戮到鸡狗。
山中漏茅屋，谁复依户牖。
摧颓苍松根，地冷骨未朽。
几人全性命，尽室岂相偶。
嵚岑猛虎场，郁结回我首。
自寄一封书，今已十月后。
反畏消息来，寸心亦何有。
汉运初中兴，生平老耽酒。
沈思欢会处，恐作穷独叟。','',''),('quantangshi-10636','送长孙九侍御赴武威判官','杜甫','quantangshi','','卷11','骢马新凿蹄，银鞍被来好。
绣衣黄白郎，骑向交河道。
问君适万里，取别何草草。
天子忧凉州，严程到须早。
去秋羣胡反，不得无电埽。
此行收遗甿，风俗方再造。
族父领元戎，名声国中老。
夺我同官良，飘颻按城堡。
使我不能餐，令我恶怀抱。
若人才思阔，溟涨浸绝岛。
尊前失诗流，塞上得国宝。
皇天悲送远，云雨白浩浩。
东郊尚烽火，朝野色枯槁。
西极柱亦倾，如何正穹昊。','',''),('quantangshi-10637','送樊二十三侍御赴汉中判官','杜甫','quantangshi','','卷11','威弧不能弦，自尔无宁岁。
川谷血横流，豺狼沸相噬。
天子从北来，长驱振凋敝。
顿兵岐梁下，却跨沙漠裔。
二京陷未收，四极我得制。
萧索汉水清，缅通淮湖税。
使者纷星散，王纲尚旒缀。
南伯从事贤，君行立谈际。
生知七曜历，手画三军势。
冰雪净聪明，雷霆走精锐。
幕府辍谏官，朝廷无此例。
至尊方旰食，仗尔布嘉惠。
补阙暮征入，柱史晨征憩。
正当艰难时，实藉长久计。
回风吹独树，白日照执袂。
恸哭苍烟根，山门万重闭。
居人莽牢落，游子方迢递。
裴回悲生离，局促老一世。
陶唐歌遗民，后汉更列帝。
恨无匡复姿，聊欲从此逝。','',''),('quantangshi-10638','送从弟亚赴安西判官','杜甫','quantangshi','','卷11','南风作秋声，杀气薄炎炽。
盛夏鹰隼击，时危异人至。
令弟草中来，苍然请论事。
诏书引上殿，奋舌动天意。
兵法五十家，尔腹为箧笥。
应对如转丸，疏通略文字。
经纶皆新语，足以正神器。
宗庙尚为灰，君臣俱下泪。
崆峒地无轴，青海天轩轾。
西极最疮痍，连山暗烽燧。
帝曰大布衣，藉卿佐元帅。
坐看清流沙，所以子奉使。
归当再前席，适远非历试。
须存武威郡，为画长久利。
孤峰石戴驿，快马金缠辔。
黄羊饫不膻，芦酒多还醉。
踊跃常人情，惨澹苦士志。
安边敌何有，反正计始遂。
吾闻驾鼓车，不合用骐骥。
龙吟回其头，夹辅待所致。','',''),('quantangshi-10639','送韦十六评事充同谷郡防御判官','杜甫','quantangshi','','卷11','昔没贼中时，潜与子同游。
今归行在所，王事有去留。
逼侧兵马间，主忧急良筹。
子虽躯干小，老气横九州。
挺身艰难际，张目视寇雠。
朝廷壮其节，奉诏令参谋。
銮舆驻凤翔，同谷为咽喉。
西扼弱水道，南镇枹罕陬。
此邦承平日，剽劫吏所羞。
况乃胡未灭，控带莽悠悠。
府中韦使君，道足示怀柔。
令侄才俊茂，二美又何求。
受词太白脚，走马仇池头。
古色沙土裂，积阴雪云稠。
羌父豪猪靴，羌儿青兕裘。
吹角向月窟，苍山旌旆愁。
鸟惊出死树，龙怒拔老湫。
古来无人境，今代横戈矛。
伤哉文儒士，愤激驰林丘。
中原正格鬬，后会何缘由。
百年赋命定，岂料沈与浮。
且复恋良友，握手步道周。
论兵远壑净，亦可纵冥搜。
题诗得秀句，札翰时相投。','',''),('quantangshi-10640','塞芦子','杜甫','quantangshi','','卷11','五城何迢迢，迢迢隔河水。
边兵尽东征，城内空荆杞。
思明割怀卫，秀岩西未已。
回略大荒来，崤函盖虚尔。
延州秦北户，关防犹可倚。
焉得一万人，疾驱塞芦子。
岐有薛大夫，旁制山贼起。
近闻昆戎徒，为退三百里。
芦关扼两寇，深意实在此。
谁能叫帝阍，胡行速如鬼。','',''),('quantangshi-10641','彭衙行','杜甫','quantangshi','','卷11','忆昔避贼初，北走经险艰。
夜深彭衙道，月照白水山。
尽室久徒步，逢人多厚颜。
参差谷鸟吟，不见游子还。
痴女饥齩我，啼畏虎狼闻。
怀中掩其口，反侧声愈嗔。
小儿强解事，故索苦李餐。
一旬半雷雨，泥泞相牵攀。
既无御雨备，径滑衣又寒。
有时经契阔，竟日数里间。
野果充糇粮，卑枝成屋椽。
早行石上水，暮宿天边烟。
少留周家洼，欲出芦子关。
故人有孙宰，高义薄曾云。
延客已曛黑，张灯启重门。
暖汤濯我足，剪纸招我魂。
从此出妻孥，相视涕阑干。
众雏烂熳睡，唤起霑盘餐。
誓将与夫子，永结为弟昆。
遂空所坐堂，安居奉我欢。
谁肯艰难际，豁达露心肝。
别来岁月周，胡羯仍构患。
何当有翅翎，飞去堕尔前。','',''),('quantangshi-10642','北征','杜甫','quantangshi','','卷11','皇帝二载秋，闰八月初吉。
杜子将北征，苍茫问家室。
维时遭艰虞，朝野少暇日。
顾慙恩私被，诏许归蓬荜。
拜辞诣阙下，怵惕久未出。
虽乏谏诤姿，恐君有遗失。
君诚中兴主，经纬固密勿。
东胡反未已，臣甫愤所切。
挥涕恋行在，道途犹恍惚。
干坤含疮痍，忧虞何时毕。
靡靡逾阡陌，人烟眇萧瑟。
所遇多被伤，呻吟更流血。
回首凤翔县，旌旗晚明灭。
前登寒山重，屡得饮马窟。
邠郊入地底，泾水中荡潏。
猛虎立我前，苍崖吼时裂。
菊垂今秋花，石戴古车辙。
青云动高兴，幽事亦可悦。
山果多琐细，罗生杂橡栗。
或红如丹砂，或黑如点漆。
雨露之所濡，甘苦齐结实。
缅思桃源内，益叹身世拙。
坡陀望鄜畤，岩谷互出没。
我行已水滨，我仆犹木末。
鸱鸟鸣黄桑，野鼠拱乱穴。
夜深经战场，寒月照白骨。
潼关百万师，往者散何卒。
遂令半秦民，残害为异物。
况我堕胡尘，及归尽华发。
经年至茅屋，妻子衣百结。
恸哭松声回，悲泉共幽咽。
平生所娇儿，颜色白胜雪。
见耶背面啼，垢腻脚不韤。
牀前两小女，补绽才过膝。
海图坼波涛，旧绣移曲折。
天吴及紫凤，颠倒在裋褐。
老夫情怀恶，呕泄卧数日。
那无囊中帛，救汝寒凛栗。
粉黛亦解苞，衾裯稍罗列。
瘦妻面复光，痴女头自栉。
学母无不为，晓妆随手抹。
移时施朱铅，狼藉画眉阔。
生还对童穉，似欲忘饥渴。
问事竞挽须，谁能即嗔喝。
飜思在贼愁，甘受杂乱聒。
新归且慰意，生理焉能说。
至尊尚蒙尘，几日休练卒。
仰观天色改，坐觉祆气豁。
阴风西北来，惨澹随回鹘。
其王愿助顺，其俗善驰突。
送兵五千人，驱马一万匹。
此辈少为贵，四方服勇决。
所用皆鹰腾，破敌过箭疾。
圣心颇虚伫，时议气欲夺。
伊洛指掌收，西京不足拔。
官军请深入，蓄锐何俱发。
此举开青徐，旋瞻略恒碣。
昊天积霜露，正气有肃杀。
祸转亡胡岁，势成擒胡月。
胡命其能久，皇纲未宜绝。
忆昨狼狈初，事与古先别。
奸臣竟葅醢，同恶随荡析。
不闻夏殷衰，中自诛褒妲。
周汉获再兴，宣光果明哲。
桓桓陈将军，仗钺奋忠烈。
微尔人尽非，于今国犹活。
凄凉大同殿，寂寞白兽闼。
都人望翠华，佳气向金阙。
园陵固有神，埽洒数不缺。
煌煌太宗业，树立甚宏达。','',''),('quantangshi-10643','得舍弟消息','杜甫','quantangshi','','卷11','风吹紫荆树，色与春庭暮。
花落辞故枝，风回返无处。
骨肉恩书重，漂泊难相遇。
犹有泪成河，经天复东注。','',''),('quantangshi-10644','徒步归行','杜甫','quantangshi','','卷11','明公壮年值时危，经济实藉英雄姿。
国之社稷今若是，武定祸乱非公谁。
凤翔千官且饱饭，衣马不复能轻肥。
青袍朝士最困者，白头拾遗徒步归。
人生交契无老少，论交何必先同调。
妻子山中哭向天，须公枥上追风骠。','',''),('quantangshi-10645','玉华宫','杜甫','quantangshi','','卷11','溪回松风长，苍鼠窜古瓦。
不知何王殿，遗构绝壁下。
阴房鬼火青，坏道哀湍泻。
万籁真笙竽，秋色正萧洒。
美人为黄土，况乃粉黛假。
当时侍金舆，故物独石马。
忧来藉草坐，浩歌泪盈把。
冉冉征途间，谁是长年者。','',''),('quantangshi-10646','九成宫','杜甫','quantangshi','','卷11','苍山入百里，崖断如杵臼。
曾宫凭风回，岌嶪土囊口。
立神扶栋梁，凿翠开户牖。
其阳产灵芝，其阴宿牛斗。
纷披长松倒，揭𡿗怪石走。
哀猨啼一声，客泪迸林薮。
荒哉隋家帝，制此今颓朽。
向使国不亡，焉为巨唐有。
虽无新增修，尚置官居守。
巡非瑶水远，迹是雕墙后。
我行属时危，仰望嗟叹久。
天王守太白，驻马更搔首。','',''),('quantangshi-10647','羌村 一','杜甫','quantangshi','','卷11','峥嵘赤云西，日脚下平地。
柴门鸟雀噪，归客千里至。
妻孥怪我在，惊定还拭泪。
世乱遭飘荡，生还偶然遂。
邻人满墙头，感叹亦歔欷。
夜阑更秉烛，相对如梦寐。','',''),('quantangshi-10648','羌村 二','杜甫','quantangshi','','卷11','晚岁迫偷生，还家少欢趣。
娇儿不离膝，畏我复却去。
忆昔好追凉，故绕池边树。
萧萧北风劲，抚事煎百虑。
赖知禾黍收，已觉糟牀注。
如今足斟酌，且用慰迟暮。','',''),('quantangshi-10649','羌村 三','杜甫','quantangshi','','卷11','羣鸡正乱叫，客至鸡鬬争。
驱鸡上树木，始闻叩柴荆。
父老四五人，问我久远行。
手中各有携，倾榼浊复清。
苦辞酒味薄，黍地无人耕。
兵革既未息，儿童尽东征。
请为父老歌，艰难块深情。
歌罢仰天叹，四座泪纵横。','',''),('quantangshi-10650','逼仄行赠毕曜','杜甫','quantangshi','','卷11','逼仄何逼仄，我居巷南子巷北。
可恨邻里间，十日不一见颜色。
自从官马送还宫，行路难行涩如棘。
我贫无乘非无足，昔者相过今不得。
实不是爱微躯，又非关足无力。
徒步翻愁官长怒，此心炯炯君应识。
晓来急雨春风颠，睡美不闻钟鼓传。
东家蹇驴许借我，泥滑不敢骑朝天。
已令请急会通籍，男儿信命绝可怜。
焉能终日心拳拳，忆君诵诗神凛然。
辛夷始花亦已落，况我与子非壮年。
街头酒价常苦贵，方外酒徒稀醉眠。
速宜相就饮一斗，恰有三百青铜钱。','',''),('quantangshi-10651','送李校书二十六韵','杜甫','quantangshi','','卷11','代北有豪鹰，生子毛尽赤。
渥洼骐骥儿，尤异是龙脊。
李舟名父子，清峻流辈伯。
人间好少年，不必须白皙。
十五富文史，十八足宾客。
十九授校书，二十声辉赫。
众中每一见，使我潜动魄。
自恐二男儿，辛勤养无益。
干元元年春，万姓始安宅。
舟也衣彩衣，告我欲远适。
倚门固有望，敛衽就行役。
南登吟白华，已见楚山碧。
蔼蔼咸阳都，冠盖日云积。
何时太夫人，堂上会亲戚。
汝翁草明光，天子正前席。
归期岂烂漫，别意终感激。
顾我蓬屋姿，谬通金闺籍。
小来习性嬾，晚节慵转剧。
每愁悔吝作，如觉天地窄。
羡君齿发新，行己能夕惕。
临岐意颇切，对酒不能吃。
回身视绿野，惨澹如荒泽。
老雁春忍饥，哀号待枯麦。
时哉高飞燕，绚练新羽翮。
长云湿褒斜，汉水饶巨石。
无令轩车迟，衰疾悲夙昔。','',''),('quantangshi-10652','洗兵马','杜甫','quantangshi','','卷11','中兴诸将收山东，捷书日报清昼同。
河广传闻一苇过，胡危命在破竹中。
祗残邺城不日得，独任朔方无限功。
京师皆骑汗血马，回纥喂肉葡萄宫。
已喜皇威清海岱，常思仙仗过崆峒。
三年笛里关山月，万国兵前草木风。
成王功大心转小，郭相谋深古来少。
司徒清鉴悬明镜，尚书气与秋天杳。
二三豪俊为时出，整顿干坤济时了。
东走无复忆鲈鱼，南飞觉有安巢鸟。
青春复随冠冕入，紫禁正耐烟花绕。
鹤禁通霄凤辇备，鸡鸣问寝龙楼晓。
攀龙附凤势莫当，天下尽化为侯王。
汝等岂知蒙帝力，时来不得夸身强。
关中既留萧丞相，幕下复用张子房。
张公一生江海客，身长九尺须眉苍。
征起适遇风云会，扶颠始知筹策良。
青袍白马更何有，后汉今周喜再昌。
寸地尺天皆入贡，奇祥异瑞争来送。
不知何国致白环，复道诸山得银瓮。
隐士休歌紫芝曲，词人解撰河清颂。
田家望望惜雨干，布谷处处催春种。
淇上健儿归莫嬾，城南思妇愁多梦。
安得壮士挽天河，净洗甲兵长不用。','',''),('quantangshi-10653','留花门','杜甫','quantangshi','','卷11','北门天骄子，饱肉气勇决。
高秋马肥健，挟矢射汉月。
自古以为患，诗人厌薄伐。
修德使其来，羁縻固不绝。
胡为倾国至，出入暗金阙。
中原有驱除，隐忍用此物。
公主歌黄鹄，君王指白日。
连云屯左辅，百里见积雪。
长戟鸟休飞，哀笳曙幽咽。
田家最恐惧，麦倒桑枝折。
沙苑临清渭，泉香草丰洁。
渡河不用船，千骑常撇烈。
胡尘逾太行，杂种抵京室。
花门既须留，原野转萧瑟。','',''),('quantangshi-10654','病后遇王倚饮赠歌','杜甫','quantangshi','','卷11','麟角凤觜世莫识，煎胶续弦奇自见。
尚看王生抱此怀，在于甫也何由羡。
且遇王生慰畴昔，素知贱子甘贫贱。
酷见冻馁不足耻，多病沈年苦无健。
王生怪我颜色恶，答云伏枕艰难徧。
疟疠三秋孰可忍，寒热百日相交战。
头白眼暗坐有胝，肉黄皮皱命如线。
惟生哀我未平复，为我力致美肴膳。
遣人向市赊香稉，唤妇出房亲自馔。
长安冬葅酸且绿，金城土酥静如练。
兼求富豪且割鲜，密沽斗酒谐终宴。
故人情义晚谁似，令我手脚轻欲漩。
老马为驹信不虚，当时得意况深眷。
但使残年饱吃饭，只愿无事常相见。','',''),('quantangshi-10655','湖城东遇孟云卿复归刘颢宅宿宴饮散因为醉歌','杜甫','quantangshi','','卷11','疾风吹尘暗河县，行子隔手不相见。
湖城城南一开眼，驻马偶识云卿面。
向非刘颢为地主，嬾回鞭辔成高宴。
刘侯叹我携客来，置酒张灯促华馔。
且将款曲终今夕，休语艰难尚酣战。
照室红炉促曙光，萦窗素月垂文练。
天开地裂长安陌，寒尽春生洛阳殿。
岂知驱车复同轨，可惜刻漏随更箭。
人生会合不可常，庭树鸡鸣泪如线。','',''),('quantangshi-10656','阌乡姜七少府设脍戏赠长歌','杜甫','quantangshi','','卷11','姜侯设脍当严冬，昨日今日皆天风。
河冻未渔不易得，凿冰恐侵河伯宫。
饔人受鱼鲛人手，洗鱼磨刀鱼眼红。
无声细下飞碎雪，有骨已剁觜春葱。
偏劝腹腴愧年少，软炊香饭缘老翁。
落砧何曾白纸湿，放箸未觉金盘空。
新欢便饱姜侯德，清觞异味情屡极。
东归贪路自觉难，欲别上马身无力。
可怜为人好心事，于我见子真颜色。
不恨我衰子贵时，怅望且为今相忆。','',''),('quantangshi-10657','戏赠阌乡秦少公短歌','杜甫','quantangshi','','卷11','去年行宫当太白，朝回君是同舍客。
同心不减骨肉亲，每语见许文章伯。
今日时清两京道，相逢苦觉人情好。
昨夜邀欢乐更无，多才依旧能潦倒。','',''),('quantangshi-10658','李鄠县丈人胡马行','杜甫','quantangshi','','卷11','丈人骏马名胡骝，前年避胡过金牛。
回鞭却走见天子，朝饮汉水暮灵州。
自矜胡骝奇绝代，乘出千人万人爱。
一闻说尽急难材，转益愁向驽骀辈。
头上锐耳批秋竹，脚下高蹄削寒玉。
始知神龙别有种，不比俗马空多肉。
洛阳大道时再清，累日喜得俱东行。
凤臆龙鬐未易识，侧身注目长风生。','',''),('quantangshi-10659','义鹘','杜甫','quantangshi','','卷11','阴崖有苍鹰，养子黑柏颠。
白蛇登其巢，吞噬恣朝餐。
雄飞远求食，雌者鸣辛酸。
力强不可制，黄口无半存。
其父从西归，飜身入长烟。
斯须领健鹘，痛愤寄所宣。
斗上捩孤影，噭哮来九天。
修鳞脱远枝，巨颡坼老拳。
高空得蹭蹬，短草辞蜿蜒。
折尾能一掉，饱肠皆已穿。
生虽灭众雏，死亦垂千年。
物情有报复，快意贵目前。
兹实鸷鸟最，急难心炯然。
功成失所往，用舍何其贤。
近经潏水湄，此事樵夫传。
飘萧觉素发，凛欲冲儒冠。
人生许与分，只在顾盼间。
聊为义鹘行，用激壮士肝。','',''),('quantangshi-10660','画鹘行','杜甫','quantangshi','','卷11','高堂见生鹘，飒爽动秋骨。
初惊无拘挛，何得立突兀。
乃知画师妙，功刮造化窟。
写作神骏姿，充君眼中物。
鸟鹊满樛枝，轩然恐其出。
侧脑看青霄，宁为众禽没。
长翮如刀劒，人寰可超越。
干坤空峥嵘，粉墨且萧瑟。
缅思云沙际，自有烟雾质。
吾今意何伤，顾步独纡郁。','',''),('quantangshi-10661','瘦马行','杜甫','quantangshi','','卷11','东郊瘦马使我伤，骨骼硉兀如堵墙。
绊之欲动转敧侧，此岂有意仍腾骧。
细看六印带官字，众道三军遗路旁。
皮干剥落杂泥滓，毛暗萧条连雪霜。
去岁奔波逐余寇，骅骝不惯不得将。
士卒多骑内厩马，惆怅恐是病乘黄。
当时历块误一蹶，委弃非汝能周防。
见人惨澹若哀诉，失主错莫无晶光。
天寒远放雁为伴，日暮不收乌啄疮。
谁家且养愿终惠，更试明年春草长。','',''),('quantangshi-10662','新安吏','杜甫','quantangshi','','卷11','客行新安道，喧呼闻点兵。
借问新安吏，县小更无丁。
府帖昨夜下，次选中男行。
中男绝短小，何以守王城。
肥男有母送，瘦男独伶俜。
白水暮东流，青山犹哭声。
莫自使眼枯，收汝泪纵横。
眼枯即见骨，天地终无情。
我军取相州，日夕望其平。
岂意贼难料，归军星散营。
就粮近故垒，练卒依旧京。
掘壕不到水，牧马役亦轻。
况乃王师顺，抚养甚分明。
送行勿泣血，仆射如父兄。','',''),('quantangshi-10663','潼关吏','杜甫','quantangshi','','卷11','士卒何草草，筑城潼关道。
大城铁不如，小城万丈余。
借问潼关吏，修关还备胡。
要我下马行，为我指山隅。
连云列战格，飞鸟不能逾。
胡来但自守，岂复忧西都。
丈人视要处，窄狭容单车。
艰难奋长戟，万古用一夫。
哀哉桃林战，百万化为鱼。
请嘱防关将，慎勿学哥舒。','',''),('quantangshi-10664','石壕吏','杜甫','quantangshi','','卷11','暮投石壕邨，有吏夜捉人。
老翁逾墙走，老妇出门看。
吏呼一何怒，妇啼一何苦。
听妇前致词，三男邺城戍。
一男附书致，二男新战死。
存者且偷生，死者长已矣。
室中更无人，惟有乳下孙。
有孙母未去，出入无完帬。
老妪力虽衰，请从吏夜归。
急应河阳役，犹得备晨炊。
夜久语声绝，如闻泣幽咽。
天明登前途，独与老翁别。','',''),('quantangshi-10665','新婚别','杜甫','quantangshi','','卷11','兔丝附蓬麻，引蔓故不长。
嫁女与征夫，不如弃路旁。
结发为妻子，席不暖君牀。
暮婚晨告别，无乃太怱忙。
君行虽不远，守边赴河阳。
妾身未分明，何以拜姑嫜。
父母养我时，日夜令我藏。
生女有所归，鸡狗亦得将。
君今往死地，沈痛迫中肠。
誓欲随君去，形势反苍黄。
勿为新婚念，努力事戎行。
妇人在军中，兵气恐不扬。
自嗟贫家女，久致罗襦裳。
罗襦不复施，对君洗红妆。
仰视百鸟飞，大小必双翔。
人事多错迕，与君永相望。','',''),('quantangshi-10666','垂老别','杜甫','quantangshi','','卷11','四郊未宁静，垂老不得安。
子孙阵亡尽，焉用身独完。
投杖出门去，同行为辛酸。
幸有牙齿存，所悲骨髓干。
男儿既介胄，长揖别上官。
老妻卧路啼，岁暮衣裳单。
孰知是死别，且复伤其寒。
此去必不归，还闻劝加餐。
土门壁甚坚，杏园度亦难。
势异邺城下，纵死时犹宽。
人生有离合，岂择衰老端。
忆昔少壮日，迟回竟长叹。
万国尽征戍，烽火被冈峦。
积尸草木腥，流血川原丹。
何乡为乐土，安敢尚盘桓。
弃绝蓬室居，塌然摧肺肝。','',''),('quantangshi-10667','无家别','杜甫','quantangshi','','卷11','寂寞天宝后，园庐但蒿藜。
我里百余家，世乱各东西。
存者无消息，死者为尘泥。
贱子因阵败，归来寻旧蹊。
人行见空巷，日瘦气惨凄。
但对狐与狸，竖毛怒我啼。
四邻何所有，一二老寡妻。
宿鸟恋本枝，安辞且穷栖。
方春独荷锄，日暮还灌畦。
县吏知我至，召令习鼓鞞。
虽从本州役，内顾无所携。
近行止一身，远去终转迷。
家乡既荡尽，远近理亦齐。
永痛长病母，五年委沟溪。
生我不得力，终身两酸嘶。
人生无家别，何以为烝黎。','',''),('quantangshi-10668','夏日叹','杜甫','quantangshi','','卷11','夏日出东北，陵天经中街。
朱光彻厚地，郁蒸何由开。
上苍久无雷，无乃号令乖。
雨降不濡物，良田起黄埃。
飞鸟苦热死，池鱼涸其泥。
万人尚流冗，举目唯蒿莱。
至今大河北，化作虎与豺。
浩荡想幽蓟，王师安在哉？
对食不能餐，我心殊未谐。
眇然贞观初，难与数子偕。','',''),('quantangshi-10669','夏夜叹','杜甫','quantangshi','','卷11','永日不可暮，炎蒸毒我肠。
安得万里风，飘颻吹我裳。
昊天出华月，茂林延疎光。
仲夏苦夜短，开轩纳微凉。
虚明见纤毫，羽虫亦飞扬。
物情无巨细，自适固其常。
念彼荷戈士，穷年守边疆。
何由一洗濯，执热互相望。
竟夕击刁斗，喧声连万方。
青紫虽被体，不如早还乡。
北城悲笳发，鹳鹤号且翔。
况复烦促倦，激烈思时康。','',''),('quantangshi-10670','立秋后题','杜甫','quantangshi','','卷11','日月不相饶，节序昨夜隔。
玄蝉无停号，秋燕已如客。
平生独往愿，惆怅年半百。
罢官亦由人，何事拘形役。','',''),('quantangshi-10671','贻阮隐居','杜甫','quantangshi','','卷11','陈留风俗衰，人物世不数。
塞上得阮生，迥继先父祖。
贫知静者性，自益毛发古。
车马入邻家，蓬蒿翳环堵。
清诗近道要，识子用心苦。
寻我草径微，褰裳蹋寒雨。
更议居远邨，避喧甘猛虎。
足明箕颍客，荣贵如粪土。','',''),('quantangshi-10672','遣兴三首 一','杜甫','quantangshi','','卷11','下马古战场，四顾但茫然。
风悲浮云去，黄叶坠我前。
朽骨穴蝼蚁，又为蔓草缠。
故老行叹息，今人尚开边。
汉虏互胜负，封疆不常全。
安得廉耻将，三军同晏眠。','',''),('quantangshi-10673','遣兴三首 二','杜甫','quantangshi','','卷11','高秋登塞山，南望马邑州。
降虏东击胡，壮健尽不留。
穹庐莽牢落，上有行云愁。
老弱哭道路，愿闻甲兵休。
邺中事反覆，死人积如丘。
诸将已茅土，载驱谁与谋。','',''),('quantangshi-10674','遣兴三首 三','杜甫','quantangshi','','卷11','丰年孰云迟，甘泽不在早。
耕田秋雨足，禾黍已映道。
春苗九月交，颜色同日老。
劝汝衡门士，忽悲尚枯槁。
时来展材力，先后无丑好。
但讶鹿皮翁，忘机对芳草。','',''),('quantangshi-10675','昔游','杜甫','quantangshi','','卷11','昔谒华盖君，深求洞宫脚。
玉棺已上天，白日亦寂莫。
暮升艮岑顶，巾几犹未却。
弟子四五人，入来泪俱落。
余时游名山，发轫在远壑。
良觌违夙愿，含凄向寥廓。
林昏罢幽磬，竟夜伏石阁。
王乔下天坛，微月映皓鹤。
晨溪向虚駃，归径行已昨。
岂辞青鞋胝，怅望金匕药。
东蒙赴旧隐，尚忆同志乐。
休事董先生，于今独萧索。
胡为客关塞，道意久衰薄。
妻子亦何人，丹砂负前诺。
虽悲鬒发变，未忧筋力弱。
扶藜望清秋，有兴入庐霍。','',''),('quantangshi-10676','幽人','杜甫','quantangshi','','卷11','孤云亦羣游，神物有所归。
麟凤在赤霄，何当一来仪。
往与惠荀辈，中年沧洲期。
天高无消息，弃我忽若遗。
内惧非道流，幽人见瑕疵。
洪涛隐语笑，鼓枻蓬莱池。
崔嵬扶桑日，照耀珊瑚枝。
风帆倚翠盖，暮把东皇衣。
咽漱元和津，所思烟霞微。
知名未足称，局促商山芝。
五湖复浩荡，岁暮有余悲。','',''),('quantangshi-10677','佳人','杜甫','quantangshi','','卷11','绝代有佳人，幽居在空谷。
自云良家子，零落依草木。
关中昔丧败，兄弟遭杀戮。
官高何足论，不得收骨肉。
世情恶衰歇，万事随转烛。
夫壻轻薄儿，新人已如玉。
合昏尚知时，鸳鸯不独宿。
但见新人笑，那闻旧人哭。
在山泉水清，出山泉水浊。
侍婢卖珠回，牵萝补茅屋。
摘花不插发，采柏动盈匊。
天寒翠袖薄，日暮倚修竹。','',''),('quantangshi-10678','赤谷西崦人家','杜甫','quantangshi','','卷11','跻险不自喧，出郊已清目。
溪回日气暖，径转山田熟。
鸟雀依茅茨，藩篱带松菊。
如行武陵暮，欲问桃花宿。','',''),('quantangshi-10679','西枝邨寻置草堂地夜宿赞公土室二首 一','杜甫','quantangshi','','卷11','出郭眄细岑，披榛得微路。
溪行一流水，曲折方屡渡。
赞公汤休徒，好静心迹素。
昨枉霞上作，盛论岩中趣。
怡然共携手，恣意同远步。
扪萝涩先登，陟巘眩反顾。
要求阳冈暖，苦陟阴岭冱。
惆怅老大藤，沈吟屈蟠树。
卜居意未展，杖策回且暮。
层巅余落日，早蔓已多露。','',''),('quantangshi-10680','西枝邨寻置草堂地夜宿赞公土室二首 二','杜甫','quantangshi','','卷11','天寒鸟已归，月出人更静。
土室延白光，松门耿疎影。
跻攀倦日短，语乐寄夜永。
明燃林中薪，暗汲石底井。
大师京国旧，德业天机秉。
从来支许游，兴趣江湖迥。
数奇谪关塞，道广存箕颍。
何知戎马间，复接尘事屏。
幽寻岂一路，远色有诸岭。
晨光稍曚昽，更越西南顶。','',''),('quantangshi-10681','寄赞上人','杜甫','quantangshi','','卷11','一昨陪锡杖，卜邻南山幽。
年侵腰脚衰，未便阴崖秋。
重冈北面起，竟日阳光留。
茅屋买兼土，斯焉心所求。
近闻西枝西，有谷杉黍稠。
亭午颇和暖，石田又足收。
当期塞雨干，宿昔齿疾瘳。
裴回虎穴上，面势龙泓头。
柴荆具茶茗，迳路通林丘。
与子成二老，来往亦风流。','',''),('quantangshi-10682','太平寺泉眼','杜甫','quantangshi','','卷11','招提凭高冈，疎散连草莽。
出泉枯柳根，汲引岁月古。
石间见海眼，天畔萦水府。
广深丈尺间，宴息敢轻侮。
青白二小蛇，幽姿可时覩。
如丝气或上，烂熳为云雨。
山头到山下，凿井不尽土。
取供十方僧，香美胜牛乳。
北风起寒文，弱藻舒翠缕。
明涵客衣净，细荡林影趣。
何当宅下流，余润通药圃。
三春湿黄精，一食生毛羽。','',''),('quantangshi-10683','梦李白二首 一','杜甫','quantangshi','','卷11','死别已吞声，生别常恻恻。
江南瘴疠地，逐客无消息。
故人入我梦，明我长相忆。
恐非平生魂，路远不可测。
魂来枫叶青，魂返关塞黑。
君今在罗网，何以有羽翼。
落月满屋梁，犹疑照颜色。
水深波浪阔，无使蛟龙得。','',''),('quantangshi-10684','梦李白二首 二','杜甫','quantangshi','','卷11','浮云终日行，游子久不至。
三夜频梦君，情亲见君意。
告归常局促，苦道来不易。
江湖多风波，舟楫恐失坠。
出门搔白首，若负平生志。
冠盖满京华，斯人独顦顇。
孰云网恢恢，将老身反累。
千秋万岁名，寂莫身后事。','',''),('quantangshi-10685','有怀台州郑十八司户','杜甫','quantangshi','','卷11','天台隔三江，风浪无晨暮。
郑公纵得归，老病不识路。
昔如水上鸥，今如罝中兔。
性命由他人，悲辛但狂顾。
山鬼独一脚，蝮蛇长如树。
呼号傍孤城，岁月谁与度。
从来御魑魅，多为才名误。
夫子嵇阮流，更被时俗恶。
海隅微小吏，眼暗发垂素。
黄帽映青袍，非供折腰具。
平生一杯酒，见我故人遇。
相望无所成，干坤莽回互。','',''),('quantangshi-10686','遣兴五首 一','杜甫','quantangshi','','卷11','蛰龙三冬卧，老鹤万里心。
昔时贤俊人，未遇犹视今。
嵇康不得死，孔明有知音。
又如壠底松，用舍在所寻。
大哉霜雪干，岁久为枯林。','',''),('quantangshi-10687','遣兴五首 二','杜甫','quantangshi','','卷11','昔者庞德公，未曾入州府。
襄阳耆旧间，处士节独苦。
岂无济时策，终竟畏罗罟。
林茂鸟有归，水深鱼知聚。
举家依鹿门，刘表焉得取。','',''),('quantangshi-10688','遣兴五首 三','杜甫','quantangshi','','卷11','我今日夜忧，诸弟各异方。
不知死与生，何况道路长。
避寇一分散，饥寒永相望。
岂无柴门归，欲出畏虎狼。
仰看云中雁，禽鸟亦有行。','',''),('quantangshi-10689','遣兴五首 四','杜甫','quantangshi','','卷11','蓬生非无根，漂荡随高风。
天寒落万里，不复归本丛。
客子念故宅，三年门巷空。
怅望但烽火，戎车满关东。
生涯能几何，常在羁旅中。','',''),('quantangshi-10690','遣兴五首 五','杜甫','quantangshi','','卷11','昔在洛阳时，亲友相追攀。
送客东郊道，遨游宿南山。
烟尘阻长河，树羽成臯间。
回首载酒地，岂无一日还。
丈夫贵壮健，惨戚非朱颜。','',''),('quantangshi-10691','遣兴五首 一','杜甫','quantangshi','','卷11','朔风飘胡雁，惨澹带砂砾。
长林何萧萧，秋草萋更碧。
北里富熏天，高楼夜吹笛。
焉知南邻客，九月犹絺綌。','',''),('quantangshi-10692','遣兴五首 二','杜甫','quantangshi','','卷11','长陵锐头儿，出猎待明发。
騂弓金爪镝，白马蹴微雪。
未知所驰逐，但见暮光灭。
归来悬两狼，门户有旌节。','',''),('quantangshi-10693','遣兴五首 三','杜甫','quantangshi','','卷11','漆有用而割，膏以明自煎。
兰摧白露下，桂折秋风前。
府中罗旧尹，沙道尚依然。
赫赫萧京兆，今为时所怜。','',''),('quantangshi-10694','遣兴五首 四','杜甫','quantangshi','','卷11','猛虎凭其威，往往遭急缚。
雷吼徒咆哮，枝撑已在脚。
忽看皮寝处，无复睛闪烁。
人有甚于斯，足以劝元恶。','',''),('quantangshi-10695','遣兴五首 五','杜甫','quantangshi','','卷11','朝逢富家葬，前后皆辉光。
共指亲戚大，缌麻百夫行。
送者各有死，不须羡其强。
君看束练去，亦得归山冈。','',''),('quantangshi-10696','遣兴五首 一','杜甫','quantangshi','','卷11','天用莫如龙，有时系扶桑。
顿辔海徒涌，神人身更长。
性命苟不存，英雄徒自强。
吞声勿复道，真宰意茫茫。','',''),('quantangshi-10697','遣兴五首 二','杜甫','quantangshi','','卷11','地用莫如马，无良复谁记。
此日千里鸣，追风可君意。
君看渥洼种，态与驽骀异。
不杂蹄啮间，逍遥有能事。','',''),('quantangshi-10698','遣兴五首 三','杜甫','quantangshi','','卷11','陶潜避俗翁，未必能达道。
观其着诗集，颇亦恨枯槁。
达生岂是足，默识盖不早。
有子贤与愚，何其挂怀抱。','',''),('quantangshi-10699','遣兴五首 四','杜甫','quantangshi','','卷11','贺公雅吴语，在位常清狂。
上疏乞骸骨，黄冠归故乡。
爽气不可致，斯人今则亡。
山阴一茅宇，江海日凄凉。','',''),('quantangshi-10700','遣兴五首 五','杜甫','quantangshi','','卷11','吾怜孟浩然，裋褐即长夜。
赋诗何必多，往往凌鲍谢。
清江空旧鱼，春雨余甘蔗。
每望东南云，令人几悲吒。','',''),('quantangshi-10701','前出塞九首 一','杜甫','quantangshi','','卷11','戚戚去故里，悠悠赴交河。
公家有程期，亡命婴祸罗。
君已富士境，开边一何多。
弃绝父母恩，吞声行负戈。','',''),('quantangshi-10702','前出塞九首 二','杜甫','quantangshi','','卷11','出门日已远，不受徒旅欺。
骨肉恩岂断，男儿死无时。
走马脱辔头，手中挑青丝。
捷下万仞冈，俯身试搴旗。','',''),('quantangshi-10703','前出塞九首 三','杜甫','quantangshi','','卷11','磨刀呜咽水，水赤刃伤手。
欲轻肠断声，心绪乱已久。
丈夫誓许国，愤惋复何有。
功名图骐驎，战骨当速朽。','',''),('quantangshi-10704','前出塞九首 四','杜甫','quantangshi','','卷11','送徒既有长，远戍亦有身。
生死向前去，不劳吏怒嗔。
路逢相识人，附书与六亲。
哀哉两决绝，不复同苦辛。','',''),('quantangshi-10705','前出塞九首 五','杜甫','quantangshi','','卷11','迢迢万余里，领我赴三军。
军中异苦乐，主将宁尽闻。
隔河见胡骑，倏忽数百羣。
我始为奴仆，几时树功勋。','',''),('quantangshi-10706','前出塞九首 六','杜甫','quantangshi','','卷11','挽弓当挽强，用箭当用长。
射人先射马，擒贼先擒王。
杀人亦有限，列国自有疆。
苟能制侵陵，岂在多杀伤。','',''),('quantangshi-10707','前出塞九首 七','杜甫','quantangshi','','卷11','驱马天雨雪，军行入高山。
迳危抱寒石，指落曾冰间。
已去汉月远，何时筑城还。
浮云暮南征，可望不可攀。','',''),('quantangshi-10708','前出塞九首 八','杜甫','quantangshi','','卷11','单于寇我垒，百里风尘昏。
雄劒四五动，彼军为我奔。
虏其名王归，系颈授辕门。
潜身备行列，一胜何足论。','',''),('quantangshi-10709','前出塞九首 九','杜甫','quantangshi','','卷11','从军十年余，能无分寸功。
众人贵苟得，欲语羞雷同。
中原有鬬争，况在狄与戎。
丈夫四方志，安可辞固穷。','',''),('quantangshi-10710','后出塞五首 一','杜甫','quantangshi','','卷11','男儿生世间，及壮当封侯。
战伐有功业，焉能守旧丘。
召募赴蓟门，军动不可留。
千金买马鞭，百金装刀头。
闾里送我行，亲戚拥道周。
斑白居上列，酒酣进庶羞。
少年别有赠，含笑看吴钩。','',''),('quantangshi-10711','后出塞五首 二','杜甫','quantangshi','','卷11','朝进东门营，暮上河阳桥。
落日照大旗，马鸣风萧萧。
平沙列万幕，部伍各见招。
中天悬明月，令严夜寂寥。
悲笳数声动，壮士惨不骄。
借问大将谁，恐是霍嫖姚。','',''),('quantangshi-10712','后出塞五首 三','杜甫','quantangshi','','卷11','古人重守边，今人重高勋。
岂知英雄主，出师亘长云。
六合已一家，四夷且孤军。
遂使貔虎士，奋身勇所闻。
拔劒击大荒，日收胡马羣。
誓开玄冥北，持以奉吾君。','',''),('quantangshi-10713','后出塞五首 四','杜甫','quantangshi','','卷11','献凯日继踵，两蕃静无虞。
渔阳豪侠地，击鼓吹笙竽。
云帆转辽海，稉稻来东吴。
越罗与楚练，照耀舆台躯。
主将位益崇，气骄凌上都。
边人不敢议，议者死路衢。','',''),('quantangshi-10714','后出塞五首 五','杜甫','quantangshi','','卷11','我本良家子，出师亦多门。
将骄益愁思，身贵不足论。
跃马二十年，恐辜明主恩。
坐见幽州骑，长驱河洛昏。
中夜间道归，故里但空邨。
恶名幸脱免，穷老无儿孙。','',''),('quantangshi-10715','别赞上人','杜甫','quantangshi','','卷11','百川日东流，客去亦不息。
我生苦漂荡，何时有终极。
赞公释门老，放逐来上国。
还为世尘婴，颇带顦顇色。
杨枝晨在手，豆子雨已熟。
是身如浮云，安可限南北。
异县逢旧友，初忻写胸臆。
天长关塞寒，岁暮饥冻逼。
野风吹征衣，欲别向曛黑。
马嘶思故枥，归鸟尽敛翼。
古来聚散地，宿昔长荆棘。
相看俱衰年，出处各努力。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-10716','万丈潭','杜甫','quantangshi','','卷11','青溪合冥莫，神物有显晦。
龙依积水蟠，窟压万丈内。
局步凌垠堮，侧身下烟霭。
前临洪涛宽，却立苍石大。
山色一径尽，崖绝两壁对。
削成根虚无，倒影垂澹瀩。
黑如湾澴底，清见光炯碎。
孤云倒来深，飞鸟不在外。
高萝成帷幄，寒木累旌旆。
远川曲通流，嵌窦潜泄濑。
造幽无人境，发兴自我辈。
告归遗恨多，将老斯游最。
闭藏修鳞蛰，出入巨石碍。
何事暑天过，快意风雨㑹。','',''),('quantangshi-10717','两当县吴十侍御江上宅','杜甫','quantangshi','','卷11','寒城朝烟澹，山谷落叶赤。
阴风千里来，吹汝江上宅。
鵾鸡号枉渚，日色傍阡陌。
借问持斧翁，几年长沙客。
哀哀失木狖，矫矫避弓翮。
亦知故乡乐，未敢思夙昔。
昔在凤翔都，共通金闺籍。
天子犹蒙尘，东郊暗长戟。
兵家忌间谍，此辈常接迹。
台中领举劾，君必慎剖析。
不忍杀无辜，所以分白黑。
上官权许与，失意见迁斥。
仲尼甘旅人，向子识损益。
朝廷非不知，闭口休叹息。
余时忝诤臣，丹陛实咫尺。
相看受狼狈，至死难塞责。
行迈心多违，出门无与适。
于公负明义，惆怅头更白。','',''),('quantangshi-10718','发秦州','杜甫','quantangshi','','卷11','我衰更嬾拙，生事不自谋。
无食问乐土，无衣思南州。
汉源十月交，天气凉如秋。
草木未黄落，况闻山水幽。
栗亭名更佳，下有良田畴。
充肠多薯蓣，崖蜜亦易求。
密竹复冬笋，清池可方舟。
虽伤旅寓远，庶遂平生游。
此邦俯要冲，实恐人事稠。
应接非本性，登临未销忧。
溪谷无异石，塞田始微收。
岂复慰老夫，惘然难久留。
日色隐孤戍，乌啼满城头。
中宵驱车去，饮马寒塘流。
磊落星月高，苍茫云雾浮。
大哉干坤内，吾道长悠悠。','',''),('quantangshi-10719','赤谷','杜甫','quantangshi','','卷11','天寒霜雪繁，游子有所之。
岂但岁月暮，重来未有期。
晨发赤谷亭，险艰方自兹。
乱石无改辙，我车已载脂。
山深苦多风，落日童穉饥。
悄然邨墟迥，烟火何由追。
贫病转零落，故乡不可思。
常恐死道路，永为高人嗤。','',''),('quantangshi-10720','铁堂峡','杜甫','quantangshi','','卷11','山风吹游子，缥缈乘险绝。
峡形藏堂隍，壁色立积铁。
径摩穹苍蟠，石与厚地裂。
修纤无垠竹，嵌空太始雪。
威迟哀壑底，徒旅惨不悦。
水寒长冰横，我马骨正折。
生涯抵弧矢，盗贼殊未灭。
飘蓬逾三年，回首肝肺热。','',''),('quantangshi-10721','盐井','杜甫','quantangshi','','卷11','卤中草木白，青者官盐烟。
官作既有程，煮盐烟在川。
汲井岁榾榾，出车日连连。
自公斗三百，转致斛六千。
君子慎止足，小人苦喧阗。
我何良叹嗟，物理固自然。','',''),('quantangshi-10722','寒硖','杜甫','quantangshi','','卷11','行迈日悄悄，山谷势多端。
云门转绝岸，积阻霾天寒。
寒硖不可度，我实衣裳单。
况当仲冬交，溯沿增波澜。
野人寻烟语，行子傍水餐。
此生免荷殳，未敢辞路难。','',''),('quantangshi-10723','法镜寺','杜甫','quantangshi','','卷11','身危适他州，勉强终劳苦。
神伤山行深，愁破崖寺古。
婵娟碧鲜净，萧摵寒箨聚。
回回山根水，冉冉松上雨。
泄云蒙清晨，初日翳复吐。
朱甍半光炯，户牖粲可数。
拄策忘前期，出萝已亭午。
冥冥子规叫，微径不复取。','',''),('quantangshi-10724','青阳峡','杜甫','quantangshi','','卷11','塞外苦厌山，南行道弥恶。
冈峦相经亘，云水气参错。
林迥硖角来，天窄壁面削。
磎西五里石，奋怒向我落。
仰看日车侧，俯恐坤轴弱。
魑魅啸有风，霜霰浩漠漠。
昨忆逾陇坂，高秋视吴岳。
东笑莲华卑，北知崆峒薄。
超然侔壮观，已谓殷寥廓。
突兀犹趁人，及兹叹冥莫。','',''),('quantangshi-10725','龙门镇','杜甫','quantangshi','','卷11','细泉兼轻冰，沮洳栈道湿。
不辞辛苦行，迫此短景急。
石门雪云隘，古镇峰峦集。
旌竿暮惨澹，风水白刃涩。
胡马屯成臯，防虞此何及。
嗟尔远戍人，山寒夜中泣。','',''),('quantangshi-10726','石龛','杜甫','quantangshi','','卷11','熊罴哮我东，虎豹号我西。
我后鬼长啸，我前狨又啼。
天寒昏无日，山远道路迷。
驱车石龛下，仲冬见虹霓。
伐竹者谁子，悲歌上云梯。
为官采美箭，五岁供梁齐。
苦云直簳尽，无以充提携。
奈何渔阳骑，飒飒惊烝黎。','',''),('quantangshi-10727','积草岭','杜甫','quantangshi','','卷11','连峰积长阴，白日递隐见。
飕飕林响交，惨惨石壮变。
山分积草岭，路异明水县。
旅泊吾道穷，衰年岁时倦。
卜居尚百里，休驾投诸彦。
邑有佳主人，情如已会面。
来书语绝妙，远客惊深眷。
食蕨不愿余，茅茨眼中见。','',''),('quantangshi-10728','泥功山','杜甫','quantangshi','','卷11','朝行青泥上，暮在青泥中。
泥泞非一时，版筑劳人功。
不畏道途永，乃将汩没同。
白马为铁骊，小儿成老翁。
哀猿透却坠，死鹿力所穷。
寄语北来人，后来莫悤悤。','',''),('quantangshi-10729','凤凰台','杜甫','quantangshi','','卷11','亭亭凤凰台，北对西康州。
西伯今寂寞，凰声亦悠悠。
山峻路绝踪，石林气高浮。
安得万丈梯，为君上上头。
恐有无母雏，饥寒日啾啾。
我能剖心出，饮啄慰孤愁。
心以当竹实，炯然无外求。
血以当醴泉，岂徒比清流。
所贵王者瑞，敢辞微命休。
坐看彩翮长，举意八极周。
自天衔瑞图，飞下十二楼。
图以奉至尊，凤以垂鸿猷。
再光中兴业，一洗苍生忧。
深衷正为此，羣盗何淹留。','',''),('quantangshi-10730','干元中寓居同谷县作歌七首 一','杜甫','quantangshi','','卷11','有客有客字子美，白头乱发垂过耳。
岁拾橡栗随狙公，天寒日暮山谷里。
中原无书归不得，手脚冻皴皮肉死。
鸣呼一歌兮歌已哀，悲风为我从天来。','',''),('quantangshi-10731','干元中寓居同谷县作歌七首 二','杜甫','quantangshi','','卷11','长鑱长鑱白木柄，我生托子以为命。
黄精无苗山雪盛，短衣数挽不掩胫。
此时与子空归来，男呻女吟四壁静。
鸣呼二歌兮歌始放，邻里为我色惆怅。','',''),('quantangshi-10732','干元中寓居同谷县作歌七首 三','杜甫','quantangshi','','卷11','有弟有弟在远方，三人各瘦何人强。
生别展转不相见，胡尘暗天道路长。
东飞驾鹅后鹙鸧，安得送我置汝旁。
鸣呼三歌兮歌三发，汝归何处收兄骨。','',''),('quantangshi-10733','干元中寓居同谷县作歌七首 四','杜甫','quantangshi','','卷11','有妹有妹在钟离，良人早殁诸孤痴。
长淮浪高蛟龙怒，十年不见来何时。
扁舟欲往箭满眼，杳杳南国多旌旗。
鸣呼四歌兮歌四奏，林猨为我啼清昼。','',''),('quantangshi-10734','干元中寓居同谷县作歌七首 五','杜甫','quantangshi','','卷11','四山多风溪水急，寒雨飒飒枯树湿。
黄蒿古城云不开，白狐跳梁黄狐立。
我生何为在穷谷，中夜起坐万感集。
鸣呼五歌兮歌正长，魂招不来归故乡。','',''),('quantangshi-10735','干元中寓居同谷县作歌七首 六','杜甫','quantangshi','','卷11','南有龙兮在山湫，古木巃嵷枝相樛。
木叶黄落龙正蛰，蝮蛇东来水上游。
我行怪此安敢出，拔劒欲斩且复休。
鸣呼六歌兮歌思迟，溪壑为我回春姿。','',''),('quantangshi-10736','干元中寓居同谷县作歌七首 七','杜甫','quantangshi','','卷11','男儿生不成名身已老，三年饥走荒山道。
长安卿相多少年，富贵应须致身早。
山中儒生旧相识，但话宿昔伤怀抱。
鸣呼七歌兮悄终曲，仰视皇天白日速。','',''),('quantangshi-10737','发同谷县','杜甫','quantangshi','','卷11','贤有不黔突，圣有不暖席。
况我饥愚人，焉能尚安宅。
始来兹山中，休驾喜地僻。
奈何迫物累，一岁四行役。
忡忡去绝境，杳杳更远适。
停骖龙潭云，回首白崖石。
临岐别数子，握手泪再滴。
交情无旧深，穷老多惨戚。
平生嬾拙意，偶值栖遁迹。
去住与愿违，仰慙林间翮。','',''),('quantangshi-10738','木皮岭','杜甫','quantangshi','','卷11','首路栗亭西，尚想凤皇邨。
季冬携童穉，辛苦赴蜀门。
南登木皮岭，艰险不易论。
汗流被我体，祁寒为之暄。
远岫争辅佐，千岩自崩奔。
始知五岳外，别有他山尊。
仰干塞大明，俯入裂厚坤。
再闻虎豹鬬，屡局风水昏。
高有废阁道，摧折如短辕。
下有冬青林，石上走长根。
西崖特秀发，焕若灵芝繁。
润聚金碧气，清无沙土痕。
忆观昆仑图，目击悬圃存。
对此欲何适，默伤垂老魂。','',''),('quantangshi-10739','白沙渡','杜甫','quantangshi','','卷11','畏途随长江，渡口下绝岸。
差池上舟楫，杳窕入云汉。
天寒荒野外，日暮中流半。
我马向北嘶，山猨饮相唤。
水清石礧礧，沙白滩漫漫。
迥然洗愁辛，多病一疎散。
高壁抵嵚崟，洪涛越凌乱。
临风独回首，揽辔复三叹。','',''),('quantangshi-10740','水会渡','杜甫','quantangshi','','卷11','山行有常程，中夜尚未安。
微月没已久，崖倾路何难。
大江动我前，汹若溟渤宽。
篙师暗理楫，歌笑轻波澜。
霜浓木石滑，风急手足寒。
入舟已千忧，陟巘仍万盘。
迥眺积水外，始知众星干。
远游令人瘦，衰疾慙加餐。','',''),('quantangshi-10741','飞仙阁','杜甫','quantangshi','','卷11','土门山行窄，微径缘秋毫。
栈云兰干峻，梯石结构牢。
万壑攲疎林，积阴带奔涛。
寒日外澹泊，长风中怒号。
歇鞍在地底，始觉所历高。
往来杂坐卧，人马同疲劳。
浮生有定分，饥饱岂可逃。
叹息谓妻子，我何随汝曹。','',''),('quantangshi-10742','五盘','杜甫','quantangshi','','卷11','五盘虽云险，山色佳有余。
仰凌栈道细，俯映江木疎。
地僻无网罟，水清反多鱼。
好鸟不妄飞，野人半巢居。
喜见淳朴俗，坦然心神舒。
东郊尚格鬬，巨猾何时除。
故乡有弟妹，流落随丘墟。
成都万事好，岂若归吾庐。','',''),('quantangshi-10743','龙门阁','杜甫','quantangshi','','卷11','清江下龙门，绝壁无尺土。
长风驾高浪，浩浩自太古。
危途中萦盘，仰望垂线缕。
滑石攲谁凿，浮梁袅相拄。
目眩陨杂花，头风吹过雨。
百年不敢料，一坠那得取。
饱闻经瞿塘，足见度大庾。
终身历艰险，恐惧从此数。','',''),('quantangshi-10744','石柜阁','杜甫','quantangshi','','卷11','季冬日已长，山晚半天赤。
蜀道多早花，江间饶奇石。
石柜曾波上，临虚荡高壁。
清晖回羣鸥，暝色带远客。
羁栖负幽意，感叹向绝迹。
信甘孱懦婴，不独冻馁迫。
优游谢康乐，放浪陶彭泽。
吾衰未自安，谢尔性所适。','',''),('quantangshi-10745','桔柏渡','杜甫','quantangshi','','卷11','青冥寒江渡，驾竹为长桥。
竿湿烟漠漠，江永风萧萧。
连笮动袅娜，征衣飒飘颻。
急流鸨鷁散，绝岸鼋鼍骄。
西辕自兹异，东逝不可要。
高通荆门路，阔会沧海潮。
孤光隐顾眄，游子怅寂寥。
无以洗心胸，前登但山椒。','',''),('quantangshi-10746','劒门','杜甫','quantangshi','','卷11','惟天有设险，劒门天下壮。
连山抱西南，石角皆北向。
两崖崇墉倚，刻画城郭状。
一夫怒临关，百万未可傍。
珠玉走中原，岷峨气凄怆。
三皇五帝前，鸡犬各相放。
后王尚柔远，职贡道已丧。
至今英雄人，高视见霸王。
并吞与割据，极力不相让。
吾将罪真宰，意欲铲叠嶂。
恐此复偶然，临风默惆怅。','',''),('quantangshi-10747','鹿头山','杜甫','quantangshi','','卷11','鹿头何亭亭，是日慰饥渴。
连山西南断，俯见千里豁。
游子出京华，劒门不可越。
及兹险阻尽，始喜原野阔。
殊方昔三分，霸气曾间发。
天下今一家，云端失双阙。
悠然想扬马，继起名硉兀。
有文令人伤，何处埋尔骨。
纡余脂膏地，惨澹豪侠窟。
仗钺非老臣，宣风岂专达。
冀公柱石姿，论道邦国活。
斯人亦何幸，公镇逾岁月。','',''),('quantangshi-10748','成都府','杜甫','quantangshi','','卷11','翳翳桑榆日，照我征衣裳。
我行山川异，忽在天一方。
但逢新人民，未卜见故乡。
大江东流去，游子去日长。
曾城填华屋，季冬树木苍。
喧然名都会，吹箫间笙簧。
信美无与适，侧身望川梁。
鸟[雀]夜各归，中原杳茫茫。
初月出不高，众星尚争光。
自古有羁旅，我何苦哀伤。','',''),('quantangshi-10749','石笋行','杜甫','quantangshi','','卷11','君不见益州城西门，陌上石笋双高蹲。
古来相传是海眼，苔藓蚀尽波涛痕。
雨多往往得瑟瑟此事恍惚难明论。
恐是昔时卿相墓，立石为表今仍存。
惜哉俗态好蒙蔽，亦如小臣媚至尊。
政化错迕失大体，坐看倾危受厚恩。
嗟尔石笋擅虚名，后来未识犹骏奔。
安得壮士掷天外，使人不疑见本根。','',''),('quantangshi-10750','石犀行','杜甫','quantangshi','','卷11','君不见秦时蜀太守，刻石立作三犀牛。
自古虽有厌胜法，天生江水向东流。
蜀人矜夸一千载，泛溢不近张仪楼。
今年灌口损户口，此事或恐为神羞。
终藉堤防出众力，高拥木石当清秋。
先王作法皆正道，鬼怪何得参人谋。
嗟尔三犀不经济，缺讹只与长川逝。
但见元气常调和，自免洪涛恣凋瘵。
安得壮士提天纲，再平水土犀奔茫。','',''),('quantangshi-10751','杜鹃行','杜甫','quantangshi','','卷11','君不见昔日蜀天子，化作杜鹃似老乌。
寄巢生子不自啄，羣鸟至今与哺雏。
虽同君臣有旧礼，骨肉满眼身羁孤。
业工窜伏深树里，四月五月偏号呼。
其声哀痛口流血，所诉何事常区区。
尔岂摧残始发愤，羞带羽翮伤形愚。
苍天变化谁料得，万事反覆何所无。
万事反覆何所无，岂忆当殿羣臣趋。','',''),('quantangshi-10752','赠蜀僧闾丘师兄','杜甫','quantangshi','','卷11','大师铜梁秀，籍籍名家孙。
呜呼先博士，炳灵精气奔。
惟昔武皇后，临轩御干坤。
多士尽儒冠，墨客蔼云屯。
当时上紫殿，不独卿相尊。
世传闾丘笔峻极逾昆仑。
凤藏丹宵暮，龙去白水浑。
青荧雪岭东，碑碣旧制存。
斯文散都邑，高价越璵璠。
晚看作者意，妙绝与谁论。
吾祖诗冠古，同年蒙主恩。
豫章夹日月，岁久空深根。
小子思疎阔，岂能达词门。
穷愁一挥泪，相遇即诸昆。
我住锦官城，兄居只树图。
地近慰旅愁，往来当丘樊。
天涯歇滞雨，稉稻卧不翻。
漂然薄游倦，始与道侣敦。
景晏步修廊，而无车马喧。
夜阑接软语，落月如金盆。
漠漠世界黑，驱车争夺繁。
惟有摩尼珠，可照浊水源。','',''),('quantangshi-10753','泛溪','杜甫','quantangshi','','卷11','落景下高堂，进州泛回溪。
谁谓筑居小，未尽乔木西。
远郊信荒僻，秋色有余凄。
练练峰上雪，纤纤云表霓。
童戏左右岸，罟弋毕提携。
翻倒荷芰乱，指挥径路迷。
得鱼已割鳞，采藕不洗泥。
人情逐鲜美，物贱事已睽。
吾邨蔼暝姿，异舍鸡亦栖。
萧条欲何适，出处无可齐。
衣上见新月，霜中登故畦。
浊醪自初熟，东城多鼓鼙。','',''),('quantangshi-10754','题壁画马歌','杜甫','quantangshi','','卷11','韦侯别我有所适，知我怜君画无敌。
戏拈秃笔埽骅骝，歘见骐驎出东壁。
一匹齕草一匹嘶，坐看千里当霜蹄。
时危安得真致此，与人同生亦同死。','',''),('quantangshi-10755','戏题画山水图歌','杜甫','quantangshi','','卷11','十日画一水，五日画一石。
能事不受相促迫，王宰始肯留真迹。
壮哉昆仑方壶图，挂君高堂之素壁。
巴陵洞庭日本东，赤岸水与银河通，中有云气随飞龙。
舟人渔子入浦溆，山木尽亚洪涛风。
尤工远势古莫比，咫尺应须论万里。
焉得并州快剪刀，剪取吴松半江水。','',''),('quantangshi-10756','题李尊师松树障子歌','杜甫','quantangshi','','卷11','老夫清晨梳白头，玄都道士来相访。
握发呼儿延入户，手提新画青松障。
障子松林静杳冥，凭轩忽若无丹青。
阴崖却承霜雪干，偃盖反走虬龙形。
老夫平生好奇古，对此兴与精灵聚。
已知仙客意相亲，更觉良工心独苦。
松下丈人巾屦同，偶坐似是商山翁。
怅望聊歌紫芝曲，时危惨澹来悲风。','',''),('quantangshi-10757','戏为双松图歌','杜甫','quantangshi','','卷11','天下几人画古松，毕宏已老韦偃少。
绝笔长风起纤末，满堂动色嗟神妙。
两株惨裂苔藓皮，屈铁交错回高枝，白摧朽骨龙虎死。
黑入太阴雷雨垂，松根胡僧憩寂寞。
庞眉皓首无住着，偏袒右肩露双脚。
叶里松子僧前落，韦侯韦侯数相见。
我有一匹好东绢，重之不减锦绣段。
已命拂拭光凌乱，请公放笔为直干。','',''),('quantangshi-10758','投简成华两县诸子','杜甫','quantangshi','','卷11','赤县官曹拥材杰，软裘快马当冰雪。
长安苦寒谁独悲，杜陵野老骨欲折。
南山豆苗早荒秽，青门瓜地新冻裂。
乡里儿童项领成，朝廷故旧礼数绝。
自然弃掷与时异，况乃疎顽临事拙。
饥卧动即向一旬，敝裘何啻联百结。
君不见空墙日色晚，此老无声泪垂血。','',''),('quantangshi-10759','徐卿二子歌','杜甫','quantangshi','','卷11','君不见徐卿二子生绝奇，感应吉梦相追随。
孔子释氏亲抱送，竝是天上麒麟儿。
大儿九龄色清澈，秋水为神玉为骨。
小儿五岁气食牛，满堂宾客皆回头。
吾知徐公百不忧，积善衮衮生公侯。
丈夫生儿有如此二雏者，名位岂肯悲微休。','',''),('quantangshi-10760','病柏','杜甫','quantangshi','','卷11','有柏生崇冈，童童状车盖。
偃蹙龙虎姿，主当风云会。
神明依正直，故老多再拜。
岂知千年根，中路颜色坏。
出非不得地，蟠据亦高大。
岁寒忽无凭，日夜柯叶改。
丹凤领九雏，哀鸣翔其外。
鸱鸮志意满，养子穿穴内。
客从何乡来，伫立久吁怪。
静求元精理，浩荡难倚赖。','',''),('quantangshi-10761','病橘','杜甫','quantangshi','','卷11','羣橘少生意，虽多亦奚为。
惜哉结实小，酸涩如棠棃。
剖之尽蠹虫，采掇爽其宜。
纷然不适口，岂只存其皮。
萧萧半死叶，未忍别故枝。
玄冬霜雪积，况乃回风吹。
尝闻蓬莱殿，罗列潇湘姿。
此物岁不稔，玉食失光辉。
寇盗尚凭陵，当君减膳时。
汝病是天意，吾谂罪有司。
忆昔南海使，奔腾献荔支。
百马死山谷，到今耆旧悲。','',''),('quantangshi-10762','枯椶','杜甫','quantangshi','','卷11','蜀门多椶榈，高者十八九。
其皮割剥甚，虽众亦易朽。
徒布如云叶，青黄岁寒后。
交横集斧斤，凋丧先蒲柳。
伤时苦军乏，一物官尽取。
嗟尔江汉人，生成复何有。
有同枯椶木，使我沈叹久。
死者即已休，生者何自守。
啾啾黄雀啅，侧见寒蓬走。
念尔形影干，摧残没藜莠。','',''),('quantangshi-10763','枯柟','杜甫','quantangshi','','卷11','楩柟枯峥嵘，乡党皆莫记。
不知几百岁，惨惨无生意。
上枝摩皇天，下根蟠厚地。
巨围雷霆坼，万孔虫蚁萃。
冻雨落流胶，冲风夺佳气。
白鹄遂不来，天鸡为愁思。
犹含栋梁具，无复霄汉志。
良工古昔少，识者出涕泪。
种榆水中央，成长何容易。
截承金露盘，褭褭不自畏。','',''),('quantangshi-10764','丽春','杜甫','quantangshi','','卷11','百草竞春华，丽春应最胜。
少须好颜色，多漫枝条剩。
纷纷桃李枝，处处总能移。
如何贵此重，却怕有人知。','',''),('quantangshi-10765','丈人山','杜甫','quantangshi','','卷11','自为青城客，不唾青城地。
为爱丈人山，丹梯近幽意。
丈人祠西佳气浓，缘云拟住最高峰。
埽除白发黄精在，君看他时冰雪容。','',''),('quantangshi-10766','百忧集行','杜甫','quantangshi','','卷11','忆年十五心尚孩，健如黄犊走复来。
庭前八月棃枣熟，一日上树能千回。
即今倏忽已五十，坐卧只多少行立。
强将笑语供主人，悲见生涯百忧集。
入门依旧四壁空，老妻覩我颜色同。
痴儿未知父子礼，叫怒索饭啼门东。','',''),('quantangshi-10767','戏作花卿歌','杜甫','quantangshi','','卷11','成都猛将有花卿，学语小儿知姓名。
用如快鹘风火生，见贼唯多身始轻。
緜州副使着柘黄，我卿埽除即日平。
子章髑髅血糢糊，手提掷还崔大夫。
李侯重有此节度，人道我卿绝世无。','',''),('quantangshi-10768','入奏行赠西山检察使窦侍御','杜甫','quantangshi','','卷11','窦侍御，骥之子，凤之雏。
年未三十忠义俱，骨鲠绝代无。
炯如一段清冰出万壑，置在迎风寒露之玉壶。
蔗浆归厨金盌冻，洗涤烦热足以宁君躯。
政用疎通合典则，戚联豪贵耽文儒。
兵革未息人未苏，天子亦念西南隅。
吐蕃凭陵气颇麤，窦氏检察应时须。
运粮绳桥壮士喜，斩木火井穷猿呼。
八州刺史思一战，三城守边却可图。
此行入奏计未小，密奉贤旨恩宜殊。
绣衣春当霄汉立，彩服日向庭闱趋。
省郎京尹必俯拾，江花未落还成都。
江花未落还成都，肯访浣花老翁无。
为君酤酒满眼酤，与奴白饭马青刍。','',''),('quantangshi-10769','柟树为风雨所拔叹','杜甫','quantangshi','','卷11','倚江柟树草堂前，故老相传二百年。
诛茅卜居总为此，五月仿髴闻寒蝉。
东南飘风动地至，江翻石走流云气。
干排雷雨犹力争，根断泉源岂天意。
沧波老树性所爱，浦上童童一青盖。
野客频留惧雪霜，行人不过听竽籁。
虎倒龙颠委榛棘，泪痕血点垂胷臆。
我有新诗何处吟，草堂自此无颜色。','',''),('quantangshi-10770','茅屋为秋风所破歌','杜甫','quantangshi','','卷11','八月秋高风怒号，卷我屋上三重茅。
茅飞度江洒江郊，高者挂罥长林梢。
下者飘转沈塘坳，南邨羣童欺我老无力。
忍能对面为盗贼，公然抱茅入竹去。
唇焦口燥呼不得，归来倚仗自叹息。
俄顷风定云墨色，秋天漠漠向昏黑。
布衾多年冷似铁，骄儿恶卧踏里裂。
牀牀屋漏无干处，雨脚如麻未断绝。
自经丧乱少睡眠，长夜霑湿何由彻。
安得广厦千万间，大庇天下寒士俱欢颜。
风雨不动安如山，呜呼！何时眼前突兀见此屋？
吾庐独破受冻死亦足。','',''),('quantangshi-10771','大雨','杜甫','quantangshi','','卷11','西蜀冬不雪，春农尚嗷嗷。
上天回哀眷，朱夏云郁陶。
执热乃沸鼎，纤絺成緼袍。
风雷飒万里，霈泽施蓬蒿。
敢辞茅苇漏，已喜黍豆高。
三日无行人，二江声怒号。
流恶邑里清，矧兹远江臯。
荒庭步鹳鹤，隐几望波涛。
沈疴聚药饵，顿忘所进劳。
则知润物功，可以贷不毛。
阴色静陇亩，劝耕自官曹。
四邻耒耜出，何必吾家操。','',''),('quantangshi-10772','溪涨','杜甫','quantangshi','','卷11','当时浣花桥，溪水才尺余。
白石明可把，水中有行车。
秋夏忽泛溢，岂惟入吾庐。
蛟龙亦狼狈，况是鼈与鱼。
兹晨已半落，归路跬步疎。
马嘶未敢动，前有深填淤。
青青屋东麻，散乱牀上书。
不意远山雨，夜来复何如。
我游都市间，晚憩必邨墟。
乃知久行客，终日思其居。','',''),('quantangshi-10773','戏赠友二首 一','杜甫','quantangshi','','卷11','元年建巳月，郎有焦校书。
自夸足膂力，能骑生马驹。
一朝被马踏，唇裂版齿无。
壮心不肯已，欲得东擒胡。','',''),('quantangshi-10774','戏赠友二首 二','杜甫','quantangshi','','卷11','元年建巳月，官有王司直。
马惊折左臂，骨折面如墨。
驽骀漫深泥，何不避雨色。
劝君休叹恨，未必不为福。','',''),('quantangshi-10775','遭田父泥饮美严中丞','杜甫','quantangshi','','卷11','步屧随春风，邨邨自花柳。
田翁逼社日，邀我尝春酒。
酒酣夸新尹，畜眼未见有。
回头指大男，渠是弓弩手。
名在飞骑籍，长番岁时久。
前日放营农，辛苦救衰朽。
差料死则已，誓不举家走。
今年大作社，拾遗能住否。
叫妇开大瓶，盆中为吾取。
感此气扬扬，须知风化首。
语多虽杂乱，说尹终在口。
朝来偶然出，自卯将及酉。
久客惜人情，如何拒邻叟。
高声索果栗，欲起时被肘。
指挥过无礼，未觉邨野丑。
月出遮我留，仍嗔问升斗。','',''),('quantangshi-10776','喜雨','杜甫','quantangshi','','卷11','春旱天地昏，日色赤如血。
农事都已休，兵戈况骚屑。
巴人困军须，恸哭厚土热。
沧江夜来雨，真宰罪一雪。
谷根小苏息，沴气终不灭。
何由见宁岁，解我忧思结。
峥嵘羣山云，交会未断绝。
安得鞭雷公，滂沱洗吴越。','',''),('quantangshi-10777','渔阳','杜甫','quantangshi','','卷11','渔阳突骑犹精锐，赫赫雍王都节制。
猛将飘然恐后时，本朝不入非高计。
禄山北筑雄武城，旧防败走归其营。
系书请问燕耆旧，今日何须十万兵。','',''),('quantangshi-10778','天边行','杜甫','quantangshi','','卷11','天边老人归未得，日暮东临大江哭。
陇右河源不种田，胡骑羌兵入巴蜀。
洪涛滔天风拔木，前飞秃鹙后鸿鹄。
九度附书向洛阳，十年骨肉无消息。','',''),('quantangshi-10779','大麦行','杜甫','quantangshi','','卷11','大麦干枯小麦黄，妇女行泣夫走藏。
东至集壁西梁洋，问谁腰镰胡与羌。
岂无蜀兵三千人，部领辛苦江山长。
安得如鸟有羽翅，托身白云还故乡。','',''),('quantangshi-10780','苦战行','杜甫','quantangshi','','卷11','苦战身死马将军，自云伏波之子孙。
干戈未定失壮士，使我叹恨伤精魂。
去年江南讨狂贼，临江把臂再难得。
别时孤云今不飞，时独看云泪横臆。','',''),('quantangshi-10781','去秋行','杜甫','quantangshi','','卷11','去秋涪江木落时，臂枪走马谁家儿。
到今不知白骨处，部曲有去皆无归。
遂州城中汉节在，遂州城外巴人稀。
战场冤魂每夜哭，空令野营猛士悲。','',''),('quantangshi-10782','述古三首 一','杜甫','quantangshi','','卷11','赤骥顿长缨，非无万里姿。
悲鸣泪至地，为问驭者谁。
凤凰从东来，何意复高飞。
竹花不结实，念子忍朝饥。
古时君臣合，可以物理推。
贤人识定分，进退固其宜。','',''),('quantangshi-10783','述古三首 二','杜甫','quantangshi','','卷11','市人日中集，于利竞锥刀。
置膏烈火上，哀哀自煎熬。
农人望岁稔，相率除蓬蒿。
所务谷为本，邪赢无乃劳。
舜举十六相，身尊道何高。
秦时任商鞅，法令如牛毛。','',''),('quantangshi-10784','述古三首 三','杜甫','quantangshi','','卷11','汉光得天下，祚永固有开。
岂惟高祖圣，功自萧曹来。
经纶中兴业，何代无长才。
吾慕寇邓勋，济时信良哉。
耿贾亦宗臣，羽翼共裴回。
休运终四百，图画在云台。','',''),('quantangshi-10785','观打鱼歌','杜甫','quantangshi','','卷11','緜州江水之东津，鲂鱼鱍鱍色胜银。
渔人漾舟沈大网，截江一拥数百鳞。
众鱼常才尽却弃，赤鲤腾出如有神。
潜龙无声老蛟怒，回风飒飒吹沙尘。
饔子左右挥双刀，脍飞金盘白雪高。
徐州秃尾不足忆，汉阴槎头远遁逃。
鲂鱼肥美知第一，既饱欢娱亦萧瑟。
君不朝来割素鬐，咫尺波涛永相失。','',''),('quantangshi-10786','又观打鱼','杜甫','quantangshi','','卷11','苍江鱼子清晨集，设网提纲万鱼急。
能者操舟疾若风，撑突波涛挺叉入。
小鱼脱漏不可记，半死半生犹戢戢。
大鱼伤损皆垂头，屈强泥沙有时立。
东津观鱼已再来，主人罢鲙还倾杯。
日暮蛟龙改窟穴，山根鳣鲔随云雷。
干戈兵革鬬未止，凤凰麒麟安在哉？
吾徒胡为纵此乐，暴殄天物圣所哀。','',''),('quantangshi-10787','越王楼歌','杜甫','quantangshi','','卷11','緜州州府何磊落，显庆年中越王作。
孤城西北起高楼，碧瓦朱甍照城郭。
楼下长江百丈清，山头落日半轮明。
君王旧迹今人赏，转见千秋万古情。','',''),('quantangshi-10788','海棕行','杜甫','quantangshi','','卷11','左緜公馆清江濆，海棕一株高入云。
龙鳞犀甲相错落，苍棱白皮十抱文。
自是众木乱纷纷，海棕焉知身出羣。
移栽北辰不可得，时有西域胡僧识。','',''),('quantangshi-10789','姜楚公画角鹰歌','杜甫','quantangshi','','卷11','楚公画鹰鹰戴角，杀气森森到幽朔。
观者贪愁掣臂飞，画师不是无心学。
此鹰写真在左緜，却嗟真骨遂虚传。
梁间燕雀休惊怕，亦未抟空上九天。','',''),('quantangshi-10790','相逢歌赠严二别驾','杜甫','quantangshi','','卷11','我行入东川，十步一回首。
城都乱罢气萧飒，浣花草堂亦何有。
梓中豪俊大者谁，本州从事知名久。
把臂开尊饮我酒，酒酣击劒蛟龙吼。
乌帽拂尘青螺粟，紫衣将炙绯衣走。
铜盘烧蜡光吐日，夜如何其初促膝。
黄昏始扣主人门，谁谓俄顷胶在漆。
万事尽付形骸外，百年未见欢娱毕。
神倾意豁真佳士，久客多忧今愈疾。
高视干坤又可愁，一躯交态同悠悠。
垂老遇君未恨晚，似君须向古人求。','',''),('quantangshi-10791','光禄坂行','杜甫','quantangshi','','卷11','山行落日下绝壁，西望千山万山赤。
树枝有鸟乱鸣时，暝色无人独归客。
马惊不忧深谷坠，草动只怕长弓射。
安得更似开元中，道路即今多拥隔。','',''),('quantangshi-10792','冬到金华山观因得故拾遗陈公学堂遗迹','杜甫','quantangshi','','卷11','涪右众山内，金华紫崔嵬。
上有蔚蓝天，垂光抱琼台。
系舟接绝壁，杖策穷萦回。
四顾俯层巅，澹然川谷开。
雪岭日色死，霜鸿有余哀。
焚香玉女跪，雾里仙人来。
陈公读书堂，石柱仄青苔。
悲风为我起，激烈伤雄才。','',''),('quantangshi-10793','陈拾遗故宅','杜甫','quantangshi','','卷11','拾遗平昔居，大屋尚修椽。
悠扬荒山日，惨澹故园烟。
位下曷足伤，所贵者圣贤。
有才继骚雅，哲匠不比肩。
公生扬马后，名与日月悬。
同游英俊人，多秉辅佐权。
彦昭超玉价，郭振起通泉。
到今素壁滑，洒翰银钩连。
盛事会一时，此堂岂千年。
终古立忠义，感遇有遗编。','',''),('quantangshi-10794','谒文公上方','杜甫','quantangshi','','卷11','野寺隐乔木，山僧高下居。
石门日色异，绛气横扶疎。
窈窕入风磴，长芦纷卷舒。
庭前猛虎卧，遂得文公庐。
俯视万家邑，烟尘对阶除。
吾师雨花外，不下十年余。
长者自布金，禅龛只晏如。
大珠脱玷翳，白月当空虚。
甫也南北人，芜蔓少耘锄。
久遭诗酒污，何事忝簪裾。
王侯与蝼蚁，同尽随丘墟。
愿闻第一义，回向心地初。
金篦刮眼膜，价重百车渠。
无生有汲引，兹理傥吹嘘。','',''),('quantangshi-10795','奉赠射洪李四丈','杜甫','quantangshi','','卷11','丈人屋上乌，人好乌亦好。
人生意气豁，不在相逢早。
南京乱初定，所向邑枯槁。
游子无根株，茅斋付秋草。
东征下月峡，挂席穷海岛。
万里须十金，妻孥未相保。
苍茫风尘际，蹭蹬骐驎老。
志士怀感伤，心胸已倾倒。','',''),('quantangshi-10796','早发射洪县南途中作','杜甫','quantangshi','','卷11','将老忧贫窭，筋力岂能及。
征途乃侵星，得使诸病入。
鄙人寡道气，在困无独立。
俶装逐徒旅，达曙凌险涩。
寒日出雾迟，清江转山急。
仆夫行不进，驽马若维絷。
汀洲稍疏散，风景开怏悒。
空慰所尚怀，终非曩游集。
衰颜偶一破，胜事难屡挹。
茫然阮籍途，更洒杨朱泣。','',''),('quantangshi-10797','通泉驿南去通泉县十五里山水作','杜甫','quantangshi','','卷11','溪行衣自湿，亭午气始散。
冬温蚊蚋在，人远凫鸭乱。
登顿生曾阴，攲倾出高岸。
驿楼衰柳侧，县郭轻烟畔。
一川何绮丽，尽目穷壮观。
山色远寂寞，江光夕滋漫。
伤时愧孔父，去国同王粲。
我生苦飘零，所历有嗟叹。','',''),('quantangshi-10798','过郭代公故宅','杜甫','quantangshi','','卷11','豪俊初未遇，其迹或脱略。
代公尉通泉，放意何自若。
及夫登衮冕，直气森喷薄。
磊落见异人，岂伊常情度。
定策神龙后，宫中翕清廓。
俄顷辨尊亲，指挥存顾托。
羣公有慙色，王室无削弱。
迥出名臣上，丹青照台阁。
我行得遗迹，池馆皆疏凿。
壮公临事断，顾步涕横落。
高咏宝劒篇，神交付冥漠。','',''),('quantangshi-10799','观薛稷少保书画壁','杜甫','quantangshi','','卷11','少保有古风，得之陕郊篇。
惜哉功名忤，但见书画传。
我游梓州东，遗迹涪江边。
画藏青莲界，书入金牓悬。
仰看垂露姿，不崩亦不骞。
郁郁三大字，蛟龙岌相缠。
又挥西方变，发地扶屋椽。
惨澹壁飞动，到今色未填。
此行叠壮观，郭薛俱才贤。
不知百载后，谁复来通泉。','',''),('quantangshi-10800','通泉县署屋壁后薛少保画鹤','杜甫','quantangshi','','卷11','薛公十一鹤，皆写青田真。
画色久欲尽，苍然犹出尘。
低昂各有意，磊落如长人。
佳此志气远，岂惟粉墨新。
万里不以力，羣游森会神。
威迟白凤态，非是仓庚邻。
高堂未倾覆，常得慰嘉宾。
曝露墙壁外，终嗟风雨频。
赤霄有真骨，耻饮洿池津。
冥冥任所往，脱略谁能驯。','',''),('quantangshi-10801','陪王侍御同登东山最高顶宴姚通泉晚携酒泛江','杜甫','quantangshi','','卷11','姚公美政谁与俦，不减昔时陈太丘。
邑中上客有柱史，多暇日陪骢马游。
东山高顶罗珍羞，下顾城郭销我忧。
清江白日落欲尽，复携美人登彩舟。
笛声愤怨哀中流，妙舞逶迤夜未休。
灯前往往大鱼出，听曲低昂如有求。
三更风起寒浪涌，取乐喧呼觉船重。
满空星河光破碎，四座宾客色不动。
请公临深莫相违，回船罢酒上马归。
人生欢会岂有极，无使霜过霑人衣。','',''),('quantangshi-10802','春日戏题恼郝使君兄','杜甫','quantangshi','','卷11','使君意气凌青霄，忆昨欢娱常见招。
细马时鸣金騕褭，佳人屡出董骄饶。
东流江水西飞燕，可惜春光不相见。
愿携王赵两红颜，再骋肌肤如素练。
通泉百里近梓州，请公一来开我愁。
舞处重看花满面，尊前还有锦缠头。','',''),('quantangshi-10803','短歌行赠王郎司直','杜甫','quantangshi','','卷11','王郎酒酣拔劒斫地歌莫哀，我能拔尔抑塞磊落之奇才。
豫章翻风白日动，鲸鱼跋浪沧溟开。
且脱佩劒休裴回，西得诸侯棹锦水。
欲向何门趿珠履，仲宣楼头春色深。
青眼高歌望吾子，眼中之人吾老矣。','',''),('quantangshi-10804','短歌行送祁录事归合州因寄苏使君','杜甫','quantangshi','','卷11','前者途中一相见，人事经年记君面。
后生相动何寂寥，君有长才不贫贱。
君今起柁春江流，余亦沙边具小舟。
幸为达书贤府主，江花未尽会江楼。','',''),('quantangshi-10805','陪章留后惠义寺饯嘉州崔都督赴州','杜甫','quantangshi','','卷11','中军待上客，令肃事有恒。
前驱入宝地，祖帐飘金绳。
南陌既留欢，兹山亦深登。
清闻树杪磬，远谒云端僧。
回策匪新岸，所攀仍旧藤。
耳激洞门飙，目存寒谷冰。
出尘閟轨躅，毕景遗炎蒸。
永愿坐长夏，将衰栖大乘。
羁旅惜宴会，艰难怀友朋。
劳生共几何，离恨兼相仍。','',''),('quantangshi-10806','将适吴楚留别章使君留后兼幕府诸公得柳字','杜甫','quantangshi','','卷11','我来入蜀门，岁月亦已久。
岂惟长儿童，自觉成老丑。
常恐性坦率，失身为杯酒。
近辞痛饮徒，折节万夫后。
昔如纵壑鱼，今如丧家狗。
既无游方恋，行止复何有。
相逢半新故，取别随薄厚。
不意青草湖，扁舟落吾手。
眷眷章梓州，开筵俯高柳。
楼前出骑马，帐下罗宾友。
健儿簸红旗，此乐或难朽。
日车隐昆仑，鸟雀噪户牖。
波涛未足畏，三峡徒雷吼。
所忧盗贼多，重见衣冠走。
中原消息断，黄屋今安否。
终作适荆蛮，安排用庄叟。
随云拜东皇，挂席上南斗。
有使即寄书，无使长回首。','',''),('quantangshi-10807','山寺','杜甫','quantangshi','','卷11','野寺根石壁，诸龛徧崔嵬。
前佛不复辨，百身一莓苔。
虽有古殿存，世尊亦尘埃。
如闻龙象泣，足令信者哀。
使君骑紫马，捧拥从西来。
树羽静千里，临江久裴回。
山僧衣蓝缕，告诉栋梁摧。
公为顾宾徒，咄嗟檀施开。
吾知多罗树，却倚莲华台。
诸天必欢喜，鬼物无嫌猜。
以兹抚士卒，孰曰非周才。
穷子失净处，高人忧祸胎。
岁晏风破肉，荒林寒可回。
思量入道苦，自哂同婴孩。','',''),('quantangshi-10808','椶拂子','杜甫','quantangshi','','卷11','椶拂且薄陋，岂知身效能。
不堪代白羽，有足除苍蝇。
荧荧金错刀，擢擢朱丝蝇。
非独颜色好，亦用顾盼称。
吾老抱疾病，家贫卧炎蒸。
咂肤倦扑灭，赖尔甘服膺。
物微世竞弃，义在谁肯征。
三岁清秋至，未敢阙缄藤。','',''),('quantangshi-10809','桃竹杖引赠章留后','杜甫','quantangshi','','卷11','江心蟠石生桃竹，苍波喷浸尺度足。
斩根削皮如紫玉，江妃水仙惜不得。
梓潼使君开一束，满堂宾客皆叹息。
怜我老病赠两茎，出入爪甲铿有声。
老夫复欲东南征，乘涛鼓枻白帝城。
路幽必为鬼神夺，拔劒或与蛟龙争。
重为告曰，杖兮！杖兮！尔之生也甚正直，慎勿见水踊跃学变化为龙。
使我不得尔之扶持，灭迹于君山湖上之青峰。
噫！风尘澒洞兮豺虎齩人，忽失双杖兮吾将曷从。','',''),('quantangshi-10810','寄题江外草堂','杜甫','quantangshi','','卷11','我生性放诞，雅欲逃自然。
嗜酒爱风竹，卜居必林泉。
遭乱到蜀江，卧疴遣所便。
诛茅初一亩，广地方连延。
经营上元始，断手宝应年。
敢谋土木丽，自觉面势坚。
台亭随高下，敞豁当清川。
虽有会心侣，数能同钓船。
干戈未偃息，安得酣歌眠。
蛟龙无定窟，黄鹄摩苍天。
古来达士志，宁受外物牵。
顾惟鲁钝姿，岂识悔吝先。
偶携老妻去，惨澹凌风烟。
事迹无固必，幽贞愧双全。
尚念四小松，蔓草易拘缠。
霜骨不甚长，永为邻里怜。','',''),('quantangshi-10811','韦讽录事宅观曹将军画马图','杜甫','quantangshi','','卷11','国初已来画鞍马，神妙独数江都王。
将军得名三十载，人间又见真乘黄。
曾貌先帝照夜白，龙池十日飞霹雳。
内府殷红马脑盌，倢伃传诏才人索。
盌赐将军拜舞归，轻纨细绮相追飞。
贵戚权门得笔迹，始觉屏障生光辉。
昔日太宗拳毛騧，近时郭家师子花。
今之新图有二马，复令识者久叹嗟。
此皆骑战一敌万，缟素漠漠开风沙。
其余七匹亦殊绝，迥若寒空动烟雪。
霜蹄蹴踏长楸间，马官厮养森成列。
可怜九马争神骏，顾视清高气深稳。
借问苦心爱者谁，后有韦讽前支遁。
忆昔巡幸新丰宫，翠华拂天来向东。
腾骧磊落三万匹，皆与此图筋骨同。
自从献宝朝河宗，无复射蛟江水中。
君不见金粟堆前松柏里，龙媒去尽鸟呼风。','',''),('quantangshi-10812','送韦讽上阆州录事参军','杜甫','quantangshi','','卷11','国步犹艰难，兵革未衰息。
万方哀嗷嗷，十载供军食。
庶官务割剥，不暇忧反侧。
诛求何多门，贤者贵为德。
韦生富春秋，洞彻有清识。
操持纪纲地，喜见朱丝直。
当令豪夺吏，自此无颜色。
必若救疮痍，先应去蟊贼。
挥泪临大江，高天意凄恻。
行行树佳政，慰我深相忆。','',''),('quantangshi-10813','丹青引赠曹将军霸','杜甫','quantangshi','','卷11','将军魏武之子孙，于今为庶为清门。
英雄割据虽已矣，文彩风流犹尚存。
学书初学卫夫人，但恨无过王右军。
丹青不知老将至，富贵于我如浮云。
开元之中常引见，承恩数上南熏殿。
凌烟功臣少颜色，将军下笔开生面。
良相头上进贤冠，猛将腰间大羽箭。
褒公鄂公毛发动英姿飒爽来酣战。
先帝天马玉花骢，画工如山貌不同。
是日牵来赤墀下，迥立阊阖生长风。
诏谓将军拂绢素，意匠惨澹经营中。
斯须九重真龙出，一洗万古凡马空。
玉花却在御榻上，榻上庭前屹相向。
至尊含笑催赐金，圉人太仆皆惆怅。
弟子韩干早入室，亦能画马穷殊相。
干惟画肉不画骨，忍使骅骝气凋丧。
将军画善盖有神，必逢佳士亦写真。
即今飘泊干戈际，屡貌寻常行路人。
途穷反遭俗眼白，世上未有如公贫。
但看古来盛名下，终日坎壈缠其身。','',''),('quantangshi-10814','阆州东楼筵奉送十一舅往青城县得昏字','杜甫','quantangshi','','卷11','曾城有高楼，制古丹雘存。
迢迢百余尺，豁达开四门。
虽有车马客，而无人世喧。
游目俯大江，列筵慰别魂。
是时秋冬交，节往颜色昏。
天寒鸟兽休，霜露在草根。
今我送舅氏，万感集清尊。
岂伊山川间，回首盗贼繁。
高贤意不暇，王命久崩奔。
临风欲恸哭，声出已复吞。','',''),('quantangshi-10815','严氏溪放歌行','杜甫','quantangshi','','卷11','天下甲马未尽销，岂免沟壑常漂漂。
劒南岁月不可度，边头公卿仍独骄。
费心姑息是一役，肥肉大酒徒相要。
呜呼古人已粪土，独觉志士甘渔樵。
况我飘转无定所，终日慽慽忍羁旅。
秋宿霜溪素月高，喜得与子长夜语。
东游西还力实倦，从此将身更何许。
知子松根长茯苓，迟暮有有意来同煮。','',''),('quantangshi-10816','南池','杜甫','quantangshi','','卷11','峥嵘巴阆间，所向尽山谷。
安知有苍池，万顷浸坤轴。
呀然阆城南，枕带巴江腹。
芰荷入异县，稉稻共比屋。
皇天不无意，美利戒止足。
高田失西成，此物颇丰熟。
清源多众鱼，远岸富乔木。
独叹枫香林，春时好颜色。
南有汉王祠，终朝走巫祝。
歌舞散灵衣，荒哉旧风俗。
高堂亦明王，魂魄犹正直。
不应空陂上，缥缈亲酒食。
淫祀自古昔，非唯一川渎。
干戈浩茫茫，地僻伤极目。
平生江海兴，遭乱身局促。
驻马问渔舟，踌躇慰羁束。','',''),('quantangshi-10817','发阆中','杜甫','quantangshi','','卷11','前有毒蛇后猛虎，溪行尽日无邨坞。
江风萧萧云拂地，山木惨惨天欲雨。
女病妻忧归意速，秋花锦石谁复数。
别家三月一得书，避地何时免愁苦。','',''),('quantangshi-10818','寄韩谏议','杜甫','quantangshi','','卷11','今我不乐思岳阳，身欲奋飞病在牀。
美人娟娟隔秋水，濯足洞庭望八荒。
鸿飞冥冥日月白，青枫叶赤天雨霜。
玉京羣帝集北斗，或骑骐驎翳凤皇。
芙蓉旌旗烟雾乐，影动倒景摇潇湘。
星宫之君醉琼浆，羽人稀少不在旁。
似闻昨者赤松子，恐是汉代韩张良。
昔随刘氏定长安，帷幄未改神惨伤。
国家成败吾岂敢，色难腥腐餐风香。
周南留滞古所惜，南极老人应寿昌。
美人胡为隔秋水，焉得置之贡玉堂。','',''),('quantangshi-10819','忆昔二首 一','杜甫','quantangshi','','卷11','忆昔先皇巡朔方，千乘万骑入咸阳。
阴山骄子汗血马，长驱东胡胡走藏。
邺城反覆不足怪，关中小儿坏纪纲，张后不乐上为忙。
至今今上犹拨乱，劳身焦思补四方。
我昔近侍叨奉引，出兵整肃不可当。
为留猛士守未央，致使岐雍防西羌。
犬戎直来坐御牀，百官跣足随天王愿见北地傅介子，老儒不用尚书郎。','',''),('quantangshi-10820','忆昔二首 二','杜甫','quantangshi','','卷11','忆昔开元全盛日，小邑犹藏万家室。
稻米流脂粟米白，公私苍廪俱丰实。
九州道路无豺虎，远行不劳吉日出。
齐纨鲁缟车班班，男耕女桑不相失。
宫中圣人奏云门，天下朋友皆胶漆。
百余年间未灾变，叔孙礼乐萧何律。
岂闻一绢直万钱，有田种谷今流血。
洛阳宫殿烧焚尽，宗庙新除狐兔穴。
伤心不忍问耆旧，复恐初从乱离说。
小臣鲁钝无所能，朝廷记识蒙禄秩。
周宣中兴望我皇，洒血江汉身衰疾。','',''),('quantangshi-10821','冬狩行','杜甫','quantangshi','','卷11','君不见东川节度兵马雄，校猎亦似观成功。
夜发猛士三千人，清晨合围步骤同。
禽兽已毙十七八，杀声落日回苍穹。
幕前生致九青兕，骆驼𡾋峞垂玄熊。
东西南北百里间，仿髴蹴踏寒山空。
有鸟名鸜鹆，力不能高飞逐走蓬。
肉味不足登鼎俎，何为见羁虞罗中。
春搜冬狩侯得同，使君五马一马骢。
况今摄行大将权，号令颇有前贤风。
飘然时危一老翁，十年厌见旌旗红。
喜君士卒甚整肃，为我回辔擒西戎。
草中狐兔尽何益，天子不在咸阳宫。
朝廷虽无幽王祸，得不哀痛尘再蒙。
呜呼，得不哀痛尘再蒙。','',''),('quantangshi-10822','自平','杜甫','quantangshi','','卷11','自平宫中吕太一，收珠南海千余日。
近供生犀翡翠稀，复恐征戎干戈密。
蛮溪豪族小动摇，世封刺史非时朝。
蓬莱殿前诸主将，才如伏波不得骄。','',''),('quantangshi-10823','释闷','杜甫','quantangshi','','卷11','四海十年不解兵，犬戎也复临咸京。
失道非关出襄野，扬鞭忽是过胡城。
豺狼塞路人断绝，烽火照夜尸纵横。
天子亦应厌奔走，羣公固合思升平。
但恐诛求不改辙，闻道嬖孽能全生。
江边老翁错料事，眼暗不见风尘清。','',''),('quantangshi-10824','赠别贺兰銛','杜甫','quantangshi','','卷11','黄雀饱野粟，羣飞动荆榛。
今君抱何恨，寂寞向时人。
老骥倦骧首，苍鹰愁易驯。
高贤世未识，固合婴饥贫。
国步初返正，干坤尚风尘。
悲歌鬓发白，远赴湘吴春。
我恋岷下芋，君思千里莼。
生离与死别，自古鼻酸辛。','',''),('quantangshi-10825','别唐十五诫因寄礼部贾侍郎','杜甫','quantangshi','','卷11','九载一相逢，百年能几何。
复为万里别，送子山之阿。
白鹤久同林，潜鱼本同河。
未知栖集期，衰老强高歌。
歌罢两凄恻，六龙忽蹉跎。
相视发皓白，况难驻羲和。
胡星坠燕地，汉将仍横戈。
萧条四海内，人少豺虎多。
少人慎莫投，多虎信所过。
饥有易子食，兽犹畏虞罗。
子负经济才，天门郁嵯峨。
飘颻适东周，来往若崩波。
南宫吾故人，白马金盘陀。
雄笔映千古，见贤心靡他。
念子善师事，岁寒守旧柯。
为吾谢贾公，病肺卧江沱。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-10826','阆山歌','杜甫','quantangshi','','卷11','阆州城中灵山白，阆州城北玉台碧。
松浮欲尽不尽云，江动将崩未崩石。
那知根无鬼神会，已觉气与嵩华敌。
中原格鬬且未归，应结茅斋看青壁。','',''),('quantangshi-10827','阆水歌','杜甫','quantangshi','','卷11','嘉陵江色何所似，石黛碧玉相因依。
正怜日破浪花出，更复春从沙际归。
巴童荡桨攲侧过，水鸡衔鱼来去飞。
阆中胜事可肠断，阆州城南天下稀。','',''),('quantangshi-10828','草堂','杜甫','quantangshi','','卷11','昔我去草堂，蛮夷塞成都。
今我归草堂，成都适无虞。
请陈初乱时，反复乃须臾。
大将赴朝廷，羣小起异图。
中宵斩白马，盟歃气已麤。
西取邛南兵，北断劒阁隅。
布衣数十人，亦拥专城居。
其势不两大，始闻蕃汉殊。
西卒却倒戈，贼臣互相诛。
焉知肘腋祸，自及枭獍徒。
义士皆痛愤，纪纲乱相逾。
一国实三公，万人欲为鱼。
唱和作威福，孰肯辨无辜。
眼前列杻械，背后吹笙竽。
谈笑行杀戮，溅血满长衢。
到今用钺地，风雨闻号呼。
鬼妾与鬼马，色悲充尔娱。
国家法令在，此又足惊吁。
贱子且奔走，三年望东吴。
弧矢暗江海，难为游五湖。
不忍竟舍此，复来剃榛芜。
入门四松在，步屧万竹疎。
旧犬喜我归，低徊入衣裾。
邻舍喜我归，酤酒携胡芦。
大官喜我来，遣骑问所须。
城郭喜我来，宾客隘邨墟。
天下尚未宁，健儿胜腐儒。
飘颻风尘际，何地置老夫。
于时见疣赘，骨髓幸未枯。
饮啄愧残生，食薇不敢余。','',''),('quantangshi-10829','四松','杜甫','quantangshi','','卷11','四松初移时，大抵三尺强。
别来忽三载，离立如人长。
会看根不拔，莫计枝凋伤。
幽色幸秀发，疎柯亦昂藏。
所插小藩篱，本亦有堤防。
终然掁拨损，得恡千叶黄。
敢为故林主，黎庶犹未康。
避贼今始归，春草满空堂。
览物叹衰谢，及兹慰凄凉。
清风为我起，洒面若微霜。
足以送老姿，聊侍偃盖张。
我生无根带，配尔亦茫茫。
有情且赋诗，事迹可两望。
勿矜千载后，惨澹蟠穹苍。','',''),('quantangshi-10830','水槛','杜甫','quantangshi','','卷11','苍江多风飙，云雨昼夜飞。
茅轩驾巨浪，焉得不低垂。
游子久在外，门户无人持。
高岸尚如谷，何伤浮柱攲。
扶颠有劝诫，恐贻识者嗤。
既殊大厦倾，可以一木支。
临川视万里，何必阑槛为。
人生感故物，慷慨有余悲。','',''),('quantangshi-10831','破船','杜甫','quantangshi','','卷11','平生江海心，宿昔具扁舟。
岂惟青溪上，日傍柴门游。
苍皇避乱兵，缅邈怀旧丘。
邻人亦已非，野竹独修修。
船舷不重扣，埋没已经秋。
仰看西飞翼，下愧东逝流。
故者或可掘，新者亦易求。
所悲数奔窜，白屋难久留。','',''),('quantangshi-10832','营屋','杜甫','quantangshi','','卷11','我有阴江竹，能令朱夏寒。
阴通积水内，高入浮云端。
甚疑鬼物凭，不顾翦伐残。
东偏若面势，户牖永可安。
爱惜已六载，兹晨去千竿。
萧萧见白日，汹汹开奔湍。
度堂匪华丽，养拙异考盘。
草茅虽剃葺，衰疾方少宽。
洗然顺所适，此足代加餐。
寂无斤斧响，庶遂憩息欢。','',''),('quantangshi-10833','除草','杜甫','quantangshi','','卷11','草有害于人，曾何生阻修。
其毒甚蜂虿，其多弥道周。
清晨步前林，江色未散忧。
芒刺在我眼，焉能待高秋。
霜露一霑凝，蕙叶亦难留。
荷锄先童穉，日入仍讨求。
转致水中央，岂无双钓舟。
顽根易滋蔓，敢使依旧丘。
自兹藩篱旷，更觉松竹幽。
芟夷不可阙，疾恶信如雠。','',''),('quantangshi-10834','扬旗','杜甫','quantangshi','','卷11','江雨飒长夏，府中有余清。
我公会宾客，肃肃有异声。
初筵阅军装，罗列照广庭。
庭空六马入，駊騀扬旗旌。
回回偃飞盖，熠熠迸流星。
来缠风飙急，去擘山岳倾。
材归俯身尽，妙取略地平。
虹霓就掌握，舒卷随人轻。
三州陷犬戎，但见西岭青。
公来练猛士，欲夺天边城。
此堂不易升，庸蜀日已宁。
吾徒且加餐，休适蛮与荆。','',''),('quantangshi-10835','太子张舍人遗织成褥段','杜甫','quantangshi','','卷11','客从西北来，遗我翠织成。
开缄风涛涌，中有掉尾鲸。
逶迤罗水族，琐细不足名。
客云充君褥，承君终宴荣。
空堂魑魅走，高枕形神清。
领客珍重意，顾我非公卿。
留之惧不祥，施之混柴荆。
服饰定尊卑，大哉万古程。
今我一贱老，裋褐更无营。
煌煌珠宫物，寝处祸所婴。
叹息当路子，干戈尚纵横。
掌握有权柄，衣马自肥轻。
李鼎死岐阳，实以骄贵盈。
来瑱赐自尽，气豪直阻兵。
皆闻黄金多，坐见悔吝生。
奈何田舍翁，受此厚贶情。
锦鲸卷还客，始觉心和平。
振我麤席尘，愧客茹藜羹。','',''),('quantangshi-10836','莫相疑行','杜甫','quantangshi','','卷11','男儿生无所成头皓白，牙齿欲落真可惜。
忆献三赋蓬莱宫，自怪一日声辉赫。
集贤学士如堵墙，观我落笔中书堂。
往时文彩动人主，此日饥寒趋路旁。
晚将末契托年少，当面输心背面笑。
寄谢悠悠世上儿，不争好恶莫相疑。','',''),('quantangshi-10837','别蔡十四着作','杜甫','quantangshi','','卷11','贾生恸哭后，寥落无其人。
安知蔡夫子，高义迈等伦。
献书谒皇帝，志以清风尘。
流涕洒丹极，万乘为酸辛。
天地则创痍，朝廷当正臣。
异才复间出，周道日惟新。
使蜀见知己，别颜始一伸。
主人薨城府，扶榇归咸秦。
巴道此相逢，会我病江滨。
忆念凤翔都，聚散俄十春。
我衰不足道，但愿子意陈。
稍令社稷安，自契鱼水亲。
我虽消渴甚，敢望帝力勤。
尚思未朽骨，复覩耕桑民。
积水架三峡，浮龙倚长津。
扬舲洪涛间，仗子济物身。
鞍马下秦塞，王城通北辰。
玄甲聚不散，兵久食恐贫。
穷谷无粟帛，使者来相因。
若凭南辕吏，书札到天垠。','',''),('quantangshi-10838','杜鹃','杜甫','quantangshi','','卷11','西川有杜鹃，东川无杜鹃。
涪万无杜鹃，云安有杜鹃。
我昔游锦城，结庐锦水边。
有竹一顷余，乔木上参天。
杜鹃暮春至，哀哀叫其间。
我见常再拜，重是古帝魂。
生子百鸟巢，百鸟不敢嗔。
仍为餧其子，礼若奉至尊。
鸿雁及羔羊，有礼太古前。
行飞与跪乳，识序如知恩。
圣贤古法则，付与后世传。
君看禽鸟情，犹解事杜鹃。
今忽暮春间，值我病经年。
身病不能拜，泪下如迸泉。','',''),('quantangshi-10839','客居','杜甫','quantangshi','','卷11','客居所居堂，前江后山根。
下堑万寻岸，苍涛郁飞飜。
葱青众木梢，邪竖杂石痕。
子规昼夜啼，壮士敛精魂。
峡开四千里，水合数百源。
人虎相半居，相伤终两存。
蜀麻久不来，吴盐拥荆门。
西南失大将，商旅自星奔。
今又降元戎，已闻动行轩。
舟子候利涉，亦凭节制尊。
我在路中央，生理不得论。
卧愁病脚废，徐步视小园。
短畦带碧草，怅望思王孙。
凤随其皇去，篱雀暮喧繁。
览物想故国，十年别荒邨。
日暮归几翼，北林空自昏。
安得覆八溟，为君洗干坤。
稷契易为力，犬戎何足吞。
儒生老无成，臣子忧四番。
箧中有旧笔，情至时复援。','',''),('quantangshi-10840','客堂','杜甫','quantangshi','','卷11','忆昨离少城，而今异楚蜀。
舍舟复深山，窅窕一林麓。
栖泊云安县，消中内相毒。
旧疾甘载来，衰年得无足。
死为殊方鬼，头白免短促。
老马终望云，南雁意在北。
别家长儿女，欲起慙筋力。
客堂序节改，具物对羁束。
石暄蕨芽紫，渚秀芦笋绿。
巴莺纷未稀，徼麦早向熟。
悠悠日动江，漠漠春辞木。
台郎选才俊，自顾亦已极。
前辈声名人，埋没何所得。
居然绾章绂，受性本幽独。
平生憩息地，必种数竿竹。
事业只浊醪，营葺但草屋。
上公有记者，累奏资薄禄。
主忧岂济时，身远弥旷职。
循文庙算正，献可天衢直。
尚想趋朝廷，毫发裨社稷。
形骸今若是，进退委行色。','',''),('quantangshi-10841','石研诗','杜甫','quantangshi','','卷11','平公今诗伯，秀发吾所羡。
奉使三峡中，长啸得石研。
巨璞禹凿余，异壮君独见。
其滑乃波涛，其光或雷电。
聊坳各尽墨，多水递隐现。
挥洒容数人，十手可对面。
比公头上冠，贞质未为贱。
当公赋佳句，况得终清宴。
公含起草姿，不远明光殿。
致于丹青地，知汝随顾眄。','',''),('quantangshi-10842','水阁朝霁奉简严云安','杜甫','quantangshi','','卷11','东城抱春岑，江阁邻石面。
崔嵬晨云白，朝旭射芳甸。
雨槛卧花丛，风牀展书卷。
钩帘宿鹭起，丸药流莺啭。
呼婢取酒壶，绩儿诵文选。
晚交严明府，矧此数相见。','',''),('quantangshi-10843','赠郑十八贲','杜甫','quantangshi','','卷11','温温士君子，令我怀抱尽。
灵芝冠众芳，安得阙亲近。
遭乱意不归，窜身迹非隐。
细人尚姑息，吾子色愈谨。
高怀见物理，识者安肯哂。
卑飞欲何待，捷径应未忍。
示我百篇文，诗家一标准。
羇离交屈宋，牢落值颜闵。
水路迷畏途，药饵驻修轸。
古人日以远，青史字不泯。
步趾咏唐虞，追随饭葵堇。
数杯资好事，异味烦县尹。
心虽在朝谒，力与愿矛盾。
抱病排金门，衰容岂为敏。','',''),('quantangshi-10844','三韵三篇 一','杜甫','quantangshi','','卷11','高马勿唾面，长鱼无损鳞。
辱马马毛焦，困鱼鱼有神。
君看磊落士，不肯易其身。','',''),('quantangshi-10845','三韵三篇 二','杜甫','quantangshi','','卷11','荡荡万斛船，影若扬白虹。
起樯必椎牛，挂席集众功。
自非风动天，莫置大水中。','',''),('quantangshi-10846','三韵三篇 三','杜甫','quantangshi','','卷11','烈士恶多门，小人自同调。
名利苟可取，杀身傍权要。
何当官曹清，尔辈堪一笑。','',''),('quantangshi-10847','青丝','杜甫','quantangshi','','卷11','青丝白马谁家子，麤豪且逐风尘起。
不闻汉主放妃嫔，近静潼关埽蠭蚁。
殿前兵马破汝时，十月即为齑粉期。
未如面缚归金阙，万一皇恩下玉墀。','',''),('quantangshi-10848','近闻','杜甫','quantangshi','','卷11','近闻犬戎远遁逃，牧马不敢侵临洮。
渭水逶迤白日净，陇山萧瑟秋云高。
崆峒五原亦无事，北庭数有关中使。
似闻赞普更求亲，舅甥和好应难弃。','',''),('quantangshi-10849','蚕谷行','杜甫','quantangshi','','卷11','天下郡国向万城，无有一城无甲兵。
焉得铸甲作农器，一寸荒田牛得耕。
牛尽耕，蚕亦成。
不劳烈士泪滂沱，男谷女丝行复歌。','',''),('quantangshi-10850','折槛行','杜甫','quantangshi','','卷11','呜呼房魏不复见，秦王学士时难羡。
青衿胄子困泥涂，白马将军若雷电。
千载少似朱云人，至今折槛空嶙峋。
娄公不语宋公语，尚忆先皇容直臣。','',''),('quantangshi-10851','引水','杜甫','quantangshi','','卷11','月峡瞿塘云作顶，乱石峥嵘俗无井。
云安酤水奴仆悲，鱼复移居心力省。
白帝城西万竹蟠，接筒引水喉不干。
人生留滞生理难，斗水何直百忧宽。','',''),('quantangshi-10852','古柏行','杜甫','quantangshi','','卷11','孔明庙前有老柏，柯如青铜根如石。
霜皮溜雨四十围，黛色参天二千尺。
君臣已与时际会，树木犹为人爱惜。
云来气接巫峡长，月出寒通雪山白。
忆昨路绕锦亭东，先主武侯同閟宫。
崔嵬枝干郊原古，窈窕丹青户牖空。
落落盘踞虽得地，冥冥孤高多烈风。
扶持自是神明力，正直原因造化功。
大厦如倾要梁栋，万牛回首丘山重。
不露文章世已惊，未辞剪伐谁能送。
苦心岂免容蝼蚁，香叶终经宿鸾凤。
志士幽人莫怨嗟，古来材大难为用。','',''),('quantangshi-10853','缚鸡行','杜甫','quantangshi','','卷11','小奴缚鸡向市卖，鸡被缚急相喧争。
家中厌鸡食虫蚁，不知鸡卖还遭烹。
虫鸡与人何厚薄，吾叱奴人解其缚。
鸡虫得失无了时，注目寒江倚山阁。','',''),('quantangshi-10854','负薪行','杜甫','quantangshi','','卷11','夔州处女发半华，四十五十无夫家。
更遭丧乱嫁不售，一生抱恨堪咨嗟。
土风坐男使女立，应当门户女出入。
十犹八九负薪归，卖薪得钱应供给。
至老双鬟只垂颈，野花山叶银钗竝。
筋力登危集市门，死生射利兼盐井。
面妆首饰杂啼痕，地褊衣寒困石根。
若道巫山女麤丑，何得此有昭君邨。','',''),('quantangshi-10855','最能行','杜甫','quantangshi','','卷11','峡中丈夫绝轻死，少在公门多在水。
富豪有钱驾大舸，贫穷取给行艓子。
小儿学问止论语，大儿结束随商旅。
攲帆侧柁入波涛，撇漩捎濆无险阻。
朝发白帝暮江陵，顷来目击幸有征。
瞿堂漫天虎须怒，归州长年行最能。
此乡之人气量窄，误竞南风疎北客。
若道土无英俊才，何得山有屈原宅。','',''),('quantangshi-10856','寄裴施州','杜甫','quantangshi','','卷11','廊庙之具裴施州，宿昔一逢无此流。
金钟大镛在东序，冰壶玉衡悬清秋。
自从相遇感多病，三岁为客宽边愁。
尧有四岳明至理，汉二千石真分忧。
几度寄书白盐北，苦寒赠我青羔裘。
霜雪回光避锦袖，龙蛇动箧蟠银钩。
紫衣使者辞复命，再拜故人谢佳政。
将老已失子孙忧，后来况接才华盛。','',''),('quantangshi-10857','郑典设自施州归','杜甫','quantangshi','','卷11','吾怜荥阳秀，冒暑初有适。
名贤慎所出，不肯妄行役。
旅兹殊俗远，竟以屡空迫。
南谒裴施州，气合无险僻。
攀援悬根木，登顿入天石。
青山自一川，城郭洗忧戚。
听子话此邦，令我心悦怿。
其俗则纯朴，不知有主客。
温温诸侯门，礼亦如古昔。
敕厨倍常羞，杯盘颇狼藉。
时虽属丧乱，事贵赏匹敌。
中宵惬良会，裴郑非远戚。
羣书一万卷，博涉供务隙。
他日辱银钩，森疎见矛戟。
倒屣喜旋归，画地求所历。
乃闻风土质，又重田畴辟。
刺史似寇恂，列郡宜竞惜。
北风吹瘴疠，羸老思散策。
渚拂蒹葭塞，峤穿萝茑幂。
此身仗儿仆，高兴潜有激。
孟冬方首路，强饭取崖壁。
叹尔疲驽骀，汗沟血不赤。
终然备外饰，驾驭何所益。
我有平肩舆，前途犹准的。
翩翩入鸟道，庶脱蹉跌厄。','',''),('quantangshi-10858','柴门','杜甫','quantangshi','','卷11','孤舟登瀼西，回首望两崖。
东城干旱天，其气如焚柴。
长影没窈窕，余光散唅呀。
大江蟠嵌根，归海成一家。
下冲割坤轴，竦壁攒镆铘。
萧飒洒秋色，氛昏霾日车。
峡门自此始，最窄容浮查。
禹功翊造化，疎凿就攲斜。
巨渠决太古，众水为长蛇。
风烟渺吴蜀，舟楫通盐麻。
我今远游子，飘转混泥沙。
万物附本性，约身不愿奢。
茅栋盖一牀，清池有余花。
浊醪与脱粟，在眼无咨嗟。
山荒人民少，地僻日夕佳。
贫病固其常，富贵任生涯。
老于干戈际，宅幸蓬荜遮。
石乱上云气，杉清延月华。
赏妍又分外，理惬夫何夸。
足了垂白年，敢居高士差。
书此豁平昔，回首犹暮霞。','',''),('quantangshi-10859','贻华阳柳少府','杜甫','quantangshi','','卷11','系马乔木间，问人野寺门。
柳侯披衣笑，见我颜色温。
竝坐石下堂，俛视大江奔。
火云洗月露，绝壁上朝暾。
自非晓相访，触热生病根。
南方六七月，出入异中原。
老少多暍死，汗逾水浆飜。
俊才得之子，筋力不辞烦。
指挥当世事，语及戎马存。
涕泪溅我裳，悲气排帝阍。
郁陶抱长策，义仗知者论。
吾衰卧江汉，但愧识璵璠。
文章一小技，于道未为尊。
起予幸斑白，因是托子孙。
俱客古信州，结庐依毁垣。
相去四五里，径微山叶繁。
时危挹佳士，况免军旅喧。
醉从赵女舞，歌鼓秦人盆。
子壮顾我伤，我驩兼泪痕。
余生如过鸟，故里今空邨。','',''),('quantangshi-10860','雷','杜甫','quantangshi','','卷11','大旱山岳燋，密云复无雨。
南方瘴疠地，罹此农事苦。
封内必舞雩，峡中喧击鼓。
真龙竟寂莫，土梗空俯偻。
吁嗟公私病，税敛缺不补。
故老仰面啼，疮痍向谁数。
暴尫或前闻，鞭巫非稽古。
请先偃甲兵，处分听人主。
万邦但各业，一物休尽取。
水旱其数然，尧汤免亲覩。
上天铄金石，羣盗乱豺虎。
二者存一端，愆阳不犹愈。
昨宵殷其雷，风过齐万弩。
复吹霾翳散，虚觉神灵聚。
气暍肠胃融，汗滋衣裳污。
吾衰尤拙计，失望筑场圃。','',''),('quantangshi-10861','火','杜甫','quantangshi','','卷11','楚山经月火，大旱则斯举。
旧俗烧蛟龙，惊惶致雷雨。
爆嵌魑魅泣，崩冻岚阴昈。
罗落沸百泓，根源皆万古。
青林一灰烬，云气无处所。
入夜殊赫然，新秋照牛女。
风吹巨焰作，河棹腾烟柱。
势欲焚昆仑，光弥焮洲渚。
腥至焦长蛇，声吼缠猛虎。
神物已高飞，不见石与土。
尔宁要谤讟，凭此近荧侮。
薄关长吏忧，甚昧至精主。
远迁谁扑灭，将恐及环堵。
流汗卧江亭，更深气如缕。','',''),('quantangshi-10862','七月三日亭午已后较热退晚加小凉稳睡有诗因论壮年乐事戏呈元二十一曹长','杜甫','quantangshi','','卷11','今兹商用事，余热亦已末。
衰年旅炎方，生意从此活。
亭午减汗流，北邻耐人聒。
晚风爽乌匼，筋力苏摧折。
闭目逾十旬，大江不止渴。
退藏恨雨师，健步闻旱魃。
园蔬抱金玉，无以供采掇。
密云虽聚散，徂暑终衰歇。
前圣眘焚巫，武王亲救暍。
阴阳相主客，时序递回斡。
洒落唯清秋，昏霾一空阔。
萧萧紫塞雁，南向欲行列。
歘思红颜日，霜露冻阶闼。
胡马挟雕弓，鸣弦不虚发。
长鈚逐狡兔，突羽当满月。
惆怅白头吟，萧条游侠窟。
临轩望山阁，缥缈安可越。
高人炼丹砂，未念将朽骨。
少壮迹颇疎，欢乐曾倏忽。
杖藜风尘际，老丑难翦拂。
吾子得神仙，本是池中物。
贱夫美一睡，烦促婴词笔。','',''),('quantangshi-10863','牵牛织女','杜甫','quantangshi','','卷11','牵牛出河西，织女处其东。
万古永相望，七夕谁见同。
神光意难候，此事终蒙胧。
飒然精灵合，何必秋遂通。
亭亭新妆立，龙驾具曾空。
世人亦为尔，祈请走儿童。
称家随丰俭，白屋达公宫。
膳夫翊堂殿，鸣玉凄房栊。
曝衣徧天下，曳月扬微风。
蛛丝小人态，曲缀瓜果中。
初筵裛重露，日出甘所终。
嗟汝未嫁女，秉心郁忡忡。
防身动如律，竭力机杼中。
虽无姑舅事，敢昧织作功。
明明君臣契，咫尺或未容。
义无弃礼法，恩始夫妇恭。
小大有佳期，戒之在至公。
方圆苟龃龉，丈夫多英雄。','',''),('quantangshi-10864','毒热寄简崔评事十六弟','杜甫','quantangshi','','卷11','大暑运金气，荆扬不知秋。
林下有塌翼，水中无行舟。
千室但埽地，闭关人事休。
老夫转不乐，旅次兼百忧。
蝮蛇暮偃蹇，空牀难暗投。
炎宵恶明烛，况乃怀旧丘。
开襟仰内弟，执热露白头。
束带负芒刺，接居成阻修。
何当清霜飞，会子临江楼。
载闻大易义，讽兴诗家流。
蕴藉异时辈，检身非苟求。
皇皇使臣体，信是德业优。
楚材择杞梓，汉苑归骅骝。
短章达我心，理为识者筹。','',''),('quantangshi-10865','殿中杨监见示张旭草书图','杜甫','quantangshi','','卷11','斯人已云亡，草圣祕难得。
及兹烦见示，满目一凄恻。
悲风生微绡，万里起古色。
锵锵鸣玉动，落落羣松直。
连山蟠其间，溟涨与笔力。
有练实先书，临池真尽墨。
俊拔为之主，暮年思转极。
未知张王后，谁竝百代则。
呜呼东吴精，逸气感清识。
杨公拂箧笥，舒卷忘寝食。
念昔挥毫端，不独观酒德。','',''),('quantangshi-10866','杨监又出画鹰十二扇','杜甫','quantangshi','','卷11','近时冯绍正，能画鸷鸟样。
明公出此图，无乃传其状。
殊姿各独立，清绝心有向。
疾禁千里马，气敌万人将。
忆昔骊山宫，冬移含元仗。
天寒大羽猎，此物神俱王。
当时无凡材，百中皆用壮。
粉墨形似间，识者一惆怅。
干戈少暇日，真骨老崖嶂。
为君除狡兔，会是飜韝上。','',''),('quantangshi-10867','送殿中杨监赴蜀见相公','杜甫','quantangshi','','卷11','去水绝还波，泄云无定姿。
人生在世间，聚散亦暂时。
离别重相逢，偶然岂定期。
送子清秋暮，风物长年悲。
豪俊贵勋业，邦家频出师。
相公镇梁益，军事无孑遗。
解榻再见今，用才复择谁。
况子已高位，为郡得固辞。
难拒供给费，慎哀渔夺私。
干戈未甚息，纪纲正所持。
泛舟巨石横，登陆草露滋。
山门日易久，当念居者思。','',''),('quantangshi-10868','赠李十五丈别','杜甫','quantangshi','','卷11','峡人鸟兽居，其室附层颠。
下临不测江，中有万里船。
多病纷倚薄，少留改岁年。
绝域谁慰怀，开颜喜名贤。
孤陋忝末亲，等级敢比肩。
人生意颇合，相与襟袂连。
一日两遣仆，三日一共筵。
扬论展寸心，壮笔过飞泉。
玄成美价存，子山旧业传。
不闻八尺躯，常受众目怜。
且为辛苦行，盖被生事牵。
北回白帝棹，南入黔阳天。
汧公制方隅，迥出诸侯先。
封内如太古，时危独萧然。
清高金茎露，正直朱丝弦。
昔在尧四岳，今之黄颍川。
于迈恨不同，所思无由宣。
山深水增波，解榻秋露悬。
客游虽云久，主要月再圆。
晨集风渚亭，醉操云峤篇。
丈夫贵知己，欢罢念归旋。','',''),('quantangshi-10869','西阁曝日','杜甫','quantangshi','','卷11','凛冽倦玄冬，负暄嗜飞阁。
羲和流德泽，颛顼愧倚薄。
毛发具自和，肌肤潜沃若。
太阳信深仁，衰气歘有托。
攲倾烦注眼，容易收病脚。
流离木杪猨，翩跹山颠鹤。
用知苦聚散，哀乐日已作。
即事会赋诗，人生忽如昨。
古来遭丧乱，贤圣尽萧索。
胡为将暮年，忧世心力弱。','',''),('quantangshi-10870','课伐木','杜甫','quantangshi','','卷11','长夏无所为，客居课奴仆。
清晨饭其腹，持斧入白谷。
青冥曾巅后，十里斩阴木。
人肩四根已，亭午下山麓。
尚闻丁丁声，功课日各足。
苍皮成委积，素节相照烛。
藉汝跨小篱，当仗苦虚竹。
空荒咆熊罴，乳兽待人肉。
不示知禁情，岂惟干戈哭。
城中贤府主，处贵如白屋。
萧萧理体净，蠭虿不敢毒。
虎穴连里闾，堤防旧风俗。
泊舟沧江岸，久客慎所触。
舍西崖峤壮，雷雨蔚含蓄。
墙宇资屡修，衰年怯幽独。
尔曹轻执热，为我忍烦促。
秋光近青岑，季月当泛菊。
报之以微寒，共给酒一斛。','',''),('quantangshi-10871','园人送瓜','杜甫','quantangshi','','卷11','江间虽炎瘴，瓜熟亦不早。
柏公镇夔国，滞务兹一埽。
食新先战士，共少及溪老。
倾筐蒲鸽青，满眼颜色好。
竹竿接嵌窦，引注来鸟道。
沈浮乱水玉，爱惜如芝草。
落刃嚼冰霜，开怀慰枯槁。
许以秋蔕除，仍看小童抱。
东陵迹芜绝，楚汉休征讨。
园人非故侯，种此何草草。','',''),('quantangshi-10872','信行远修水筒','杜甫','quantangshi','','卷11','汝性不茹荤，清静仆夫内。
秉心识本源，于事少滞碍。
云端水筒坼，林表山石碎。
触热藉子修，通流与厨会。
往来四十里，荒险崖谷大。
日熏惊未餐，貌赤愧相对。
浮瓜供老病，裂饼尝所爱。
于斯答恭谨，足以殊殿最。
讵要方士符，何假将军盖。
行诸直如笔，用意崎岖外。','',''),('quantangshi-10873','槐叶冷淘','杜甫','quantangshi','','卷11','青青高槐叶，采掇付中厨。
新麪来近市，汁滓宛相俱。
入鼎资过熟，加餐愁欲无。
碧鲜俱照箸，香饭兼苞芦。
经齿冷于雪，劝人投此珠。
愿随金騕褭，走置锦屠苏。
路远思恐泥，兴深终不渝。
献芹则小小，荐藻明区区。
万里露寒殿，开冰清玉壶。
君王纳凉晚，此味亦时须。','',''),('quantangshi-10874','行官张望补稻畦水归','杜甫','quantangshi','','卷11','东屯大江北，百顷平若案。
六月青稻多，千畦碧泉乱。
插秧适云已，引溜加溉灌。
更仆往方塘，决渠当断岸。
公私各地着，浸润无天旱。
主守问家臣，分明见溪伴。
芊芊炯翠羽，剡剡生银汉。
欧鸟镜里来，关山云边看。
秋菰成黑米，精凿传白粲。
玉粒足晨炊，红鲜任霞散。
终然添旅食，作苦期壮观。
遗穗及众多，我仓戒滋蔓。','',''),('quantangshi-10875','催宗文树鸡栅','杜甫','quantangshi','','卷11','吾衰怯行迈，旅次展崩迫。
愈风传乌鸡，秋卵方漫吃。
自春生成者，随母向百翮。
驱趁制不禁，喧呼山腰宅。
课奴杀青竹，终日憎赤帻。
蹋藉盘案飜，塞蹊使之隔。
墙东有隙地，可以树高栅。
避热时来归，问儿所为迹。
织笼曹其内，令入不得掷。
稀间可突过，觜爪还污席。
我宽蝼蚁遭，彼免狐貉厄。
应宜各长幼，自此均勍敌。
笼栅念有修，近身见损益。
明明领处分，一一当剖析。
不昧风雨晨，乱离减忧慽。
其流则凡鸟，其气心匪石。
倚赖穷岁晏，拨烦去冰释。
未似尸乡翁，拘留盖阡陌。','',''),('quantangshi-10876','园官送茶','杜甫','quantangshi','','卷11','清晨蒙菜把，常荷地主恩。
守者愆实数，略有其名存。
苦苣刺如针，马齿叶亦繁。
青青嘉蔬色，埋没在中园。
园吏未足怪，世事固堪论。
呜呼战伐久，荆棘暗长原。
乃知苦苣辈，倾夺蕙草根。
小人塞道路，为态何喧喧。
又如马齿盛，气拥葵荏昏。
点染不易虞，丝麻杂罗纨。
一经器物内，永挂麤刺痕。
志士采紫芝，放歌避戎轩。
畦丁负笼至，感动百虑端。','',''),('quantangshi-10877','上后园山脚','杜甫','quantangshi','','卷11','朱夏热所婴，清旭步北林。
小园背高冈，挽葛上崎崟。
旷望延驻目，飘颻散疎襟。
潜鳞恨水壮，去翼依云深。
勿谓地无疆，劣于山有阴。
石榞徧天下，水陆兼浮沈。
自我登陇首，十年经碧岑。
劒门来巫峡，薄倚浩至今。
故园暗戎马，骨肉失追寻。
时危无消息，老去多归心。
志士惜白日，久客藉黄金。
敢为苏门啸，庶作梁父吟。','',''),('quantangshi-10878','驱竖子摘苍耳','杜甫','quantangshi','','卷11','江上秋已分，林中瘴犹剧。
畦丁告劳苦，无以供日夕。
蓬莠独不焦，野蔬暗泉石。
卷耳况疗风，童儿且时摘。
侵星驱之去，烂熳任远适。
放筐亭午际，洗剥相蒙幂。
登牀半生熟，下箸还小益。
加点瓜薤间，依稀橘奴迹。
乱世诛求急，黎民糠籺窄。
饱食复何心，荒哉膏粱客。
富家厨肉臭，战地骸骨白。
寄语恶少年，黄金且休掷。','',''),('quantangshi-10879','秋行官张请督促东渚耗稻向毕清晨遣女奴阿稽竖子阿段往问','杜甫','quantangshi','','卷11','东渚雨今足，伫闻稉稻香。
上天无偏颇，蒲稗各自长。
人情见非类，田家戒其荒。
功夫竞搰搰，除草置岸旁。
谷者命之本，客居安可忘。
青春具所务，勤垦免乱常。
吴牛力容易，竝驱动莫当。
丰苗亦已穊，云水照方塘。
有生固蔓延，静一资堤防。
督领不无人，提携颇在纲。
荆扬风土暖，肃肃候微霜。
尚恐主守疎，用心未甚臧。
清朝遣婢仆，寄语逾崇冈。
西成聚必散，不独陵我仓。
岂要仁里誉，感此乱世忙。
北风吹蒹葭，蟋蟀近中堂。
荏苒百工休，郁纡迟暮伤。','',''),('quantangshi-10880','阻雨不得归瀼西甘林','杜甫','quantangshi','','卷11','三伏适已过，骄阳化为霖。
欲归瀼西宅，阻此江浦深。
坏舟百版坼，峻岸复万寻。
篙工初一弃，恐泥劳寸心。
伫立东城隅，怅望高飞禽。
草堂乱悬圃，不隔昆仑岑。
昏浑衣裳外，旷绝同层阴。
园甘长成时，三寸如黄金。
诸侯旧上计，厥贡倾千林。
邦人不足重，所迫豪吏侵。
客居暂封殖，日夜偶瑶琴。
虚徐五株态，侧塞烦胸襟。
焉得辍两足，杖藜出岖嵚。
条流数翠实，偃息归碧浔。
拂拭乌皮几，喜闻樵牧音。
令儿快搔背，脱我头上簪。','',''),('quantangshi-10881','雨','杜甫','quantangshi','','卷11','峡云行清晓，烟雾相裴回。
风吹苍江树，雨洒石壁来。
凄凄生余寒，殷殷兼出雷。
白谷变气候，朱炎安在哉？
高鸟湿不下，居人门未开。
楚宫久已灭，幽佩为谁哀。
侍臣书王梦，赋有冠古才。
冥冥翠龙驾，多自巫山台。','',''),('quantangshi-10882','雨二首 一','杜甫','quantangshi','','卷11','青山澹无姿，白露谁能数。
片片水上云，萧萧沙中雨。
殊俗状巢居，曾台俯风渚。
佳客适万里，沈思情延伫。
挂帆远色外，惊浪满吴楚。
久阴蛟螭出，寇盗复几许。','',''),('quantangshi-10883','雨二首 二','杜甫','quantangshi','','卷11','空山中宵阴，微冷先枕席。
回风起清曙，万象萋已碧。
落落出岫云，浑浑倚天石。
日假何道行，雨含长江白。
连樯荆州船，有士荷矛戟。
南防草镇惨，霑湿赴远役。
羣盗下辟山，总戎备强敌。
水深云光廓，鸣橹各有适。
渔艇息悠悠，夷歌负樵客。
留滞一老翁，书时记朝夕。','',''),('quantangshi-10884','晚登瀼上堂','杜甫','quantangshi','','卷11','故跻瀼岸高，颇免崖石拥。
开襟野堂豁，系马林花动。
雉堞粉如云，山田麦无壠。
春气晚更生，江流静犹涌。
四序婴我怀，羣盗久相踵。
黎民困逆节，天子渴垂拱。
所思注东北，深峡转修耸。
衰老自成病，郎官未为冗。
凄其望吕葛，不复梦周孔。
济世数向时，斯人各枯冢。
楚星南天黑，蜀月西雾重。
安得随鸟翎，迫此惧将恐。','',''),('quantangshi-10885','又上后园山脚','杜甫','quantangshi','','卷11','昔我游山东，忆戏东岳阳。
穷秋立日观，矫首望八荒。
朱崖着毫发，碧海吹衣裳。
蓐收困用事，玄冥蔚强梁。
逝水自朝宗，镇名各其方。
平原独顦顇，农力废耕桑。
非关风露凋，曾是戍役伤。
于时国用富，足以守边疆。
朝廷任猛将，远夺戎虏场。
到今事反覆，故老泪万行。
龟蒙不复见，况乃怀旧乡。
肺萎属久战，骨出热中肠。
忧来杖匣劒，更上林北冈。
瘴毒猨鸟落，峡干南日黄。
秋风亦已起，江汉始如汤。
登高欲有往，荡析川无梁。
哀彼远征人，去家死路旁。
不及祖父茔，累累冢相当。','',''),('quantangshi-10886','雨','杜甫','quantangshi','','卷11','山雨不作埿，江云薄为雾。
晴飞半岭鹤，风乱平沙树。
明灭洲景微，隐见岩姿露。
拘闷出门游，旷绝经目趣。
消中日伏枕，卧久尘及屦。
岂无平肩舆，莫辨望乡路。
兵戈浩未息，蛇虺反相顾。
悠悠边月破，郁郁流年度。
针灸阻朋曹，糠籺对童孺。
一命须屈色，新知渐成故。
穷荒益自卑，飘泊欲谁诉。
虺羸愁应接，俄顷恐违迕。
浮俗何万端，幽人有独步。
庞公竟独往，尚子终罕遇。
宿留洞庭秋，天寒潇湘素。
杖策可入舟，送此齿发暮。','',''),('quantangshi-10887','甘林','杜甫','quantangshi','','卷11','舍舟越西冈，入林解我衣。
青刍适马性，好鸟知人归。
晨光映远岫，夕露见日曦。
迟暮少寝食，清旷喜荆扉。
经过倦俗态，在野无所违。
试问甘藜藿，未肯羡轻肥。
喧静不同科，出处各天机。
勿矜朱门是，陋此白屋非。
明朝步邻里，长老可以依。
时危赋敛数，脱粟为尔挥。
相携行豆田，秋花霭菲菲。
子实不得吃，货市送王畿。
尽添军旅用，迫此公家威。
主人长跪问，戎马何时稀。
我衰易悲伤，屈指数贼围。
劝其死王命，慎莫远奋飞。','',''),('quantangshi-10888','雨','杜甫','quantangshi','','卷11','行云递崇高，飞雨霭而至。
潺潺石间溜，汩汩松上驶。
亢阳乘秋热，百谷皆已弃。
皇天德泽降，焦卷有生意。
前雨伤卒暴，今雨喜容易。
不可无雷霆，间作鼓增气。
佳声达中宵，所望时一致。
清霜九月天，仿髴见滞穗。
郊扉及我私，我圃日苍翠。
恨无抱瓮力，庶减临江费。','',''),('quantangshi-10889','种莴苣','杜甫','quantangshi','','卷11','阴阳一错乱，骄蹇不复理。
枯旱于其中，炎方惨如毁。
植物半蹉跎，嘉生将已矣。
云雷歘奔命，师伯集所使。
指麾赤白日，澒洞青光起。
雨声先已风，散足尽西靡。
山泉落沧江，霹雳犹在耳。
终朝纡飒沓，信宿罢潇洒。
堂下可以畦，呼童对经始。
苣兮蔬之常，随事蓺其子。
破块数席间，荷锄功易止。
两旬不甲坼，空惜埋泥滓。
野苋迷汝来，宗生实于此。
此辈岂无秋，亦蒙寒露委。
飜然出地速，滋蔓户庭毁。
因知邪干正，掩抑至没齿。
贤良虽得禄，守道不封己。
拥寒败芝兰，众多盛荆杞。
中园陷萧艾，老圃永为耻。
登于白玉盘，藉以如霞绮。
苋也无所施，胡颜入筐篚。','',''),('quantangshi-10890','暇日小园散病将种秋菜督勒耕牛兼书触目','杜甫','quantangshi','','卷11','不爱入州府，畏人嫌我真。
及乎归茅宇，旁舍未曾嗔。
老病忌拘束，应接丧精神。
江邨意自放，林木心所欣。
秋耕属地湿，山雨近甚匀。
冬菁饭之半，牛力晚来新。
深耕种数亩，未甚后四邻。
嘉蔬既不一，名数颇具陈。
荆巫非苦寒，采撷接青春。
飞来两白鹤，暮啄泥中芹。
雄者左翮垂，损伤已露筋。
一步再流血，尚经矰缴勤。
三步六号叫，志屈悲哀频。
鸾皇不相待，侧颈诉高旻。
杖藜俯沙渚，为汝鼻酸辛。','',''),('quantangshi-10891','八哀诗 赠司空王公思礼','杜甫','quantangshi','','卷11','司空出东夷，童稚刷劲翮。
追随燕蓟儿，颖锐物不隔。
服事哥舒翰，意无流沙碛。
未甚拔行间，犬戎大充斥。
短小精悍姿，屹然强寇敌。
贯穿百万众，出入由咫尺。
马鞍悬将首，甲外控鸣镝。
洗劒青海水，刻铭天山石。
九曲非外蕃，其王转深壁。
飞兔不近驾，鸷鸟资远击。
晓达兵家流，饱闻春秋癖。
胷襟日沈静，肃肃自有适。
潼关初溃散，万乘犹辟易。
偏裨无所施，元帅见手格。
太子入朔方，至尊狩梁益。
胡马缠伊洛，中原气甚逆。
肃宗登宝位，塞望势敦迫。
公时徒步至，请罪将厚责。
际会清河公，间道传玉册天王拜跪毕，谠议果冰释。
翠华卷飞雪，熊虎亘阡陌。
屯兵凤皇山，帐殿泾渭辟。
金成贼咽喉诏镇雄所搤。
禁暴清无双，爽气春淅沥。
巷有从公歌，野多青青麦。
及夫哭庙后，复领太原役恐惧禄位高，怅望王土窄。
不得见清时，呜呼就窀穸。
永系五湖舟，悲甚田横客。
千秋汾晋间，事与云水白。
昔观文苑传，岂述廉蔺绩。
嗟嗟邓大夫，士卒终倒戟。','',''),('quantangshi-10892','八哀诗 故司徒李公光弼','杜甫','quantangshi','','卷11','司徒天宝末，北收晋阳甲。
胡骑攻吾城，愁寂意不惬。
人安若泰山，蓟北断右胁。
朔方气乃苏，黎首见帝业。
二宫泣西郊，九庙起颓压。
未散河阳卒，思明伪臣妾。
复自碣石来，火焚干坤猎。
高视笑禄山，公又大献捷。
异王册崇勋，小敌信所怯。
拥兵镇河汴，千里初妥帖。
青蝇纷营营，风雨秋一叶。
内省未入朝死泪终映睫。
大屋去高栋，长城埽遗堞。
平生白羽扇，零落蛟龙匣。
雅望与英姿，恻怆槐里接。
三军晦光彩，烈士痛稠叠。
直笔在史臣，将来洗箱箧。
吾思哭孤冢，南纪阻归楫。
扶颠永萧条，未济失利涉。
疲{艹/尔}竟何人，洒涕巴东峡。','',''),('quantangshi-10893','八哀诗 赠左仆射郑国公严公武','杜甫','quantangshi','','卷11','郑公瑚琏器，华岳金天晶。
昔在童子日，已闻老成名。
嶷然大贤后，复见秀骨清。
开口取将相，小心事友生。
阅书百纸尽，落笔四座惊。
历识匪父任，嫉邪常力争。
汉议尚整肃，胡骑忽纵横。
飞传自河陇，逢人问公卿。
不知万乘出，雪涕风悲鸣。
受词劒阁道，谒帝萧关城。
寂寞云台仗，飘颻沙塞旌。
江山少使者，笳鼓凝皇情。
壮士血相视，忠臣气不平。
密论贞观体，挥发岐阳征。
感激动四极，联翩收二京。
西郊牛酒再，原庙丹青明。
匡汲俄宠辱，卫霍竟哀荣。
四登会府地，三掌华阳兵。
京兆空柳色，尚书无履声。
羣乌自朝夕，白马休横行。
诸葛蜀人爱，文翁儒化成。
公来雪山重，公去雪山轻。
记室得何逊，韬钤延子荆。
四郊失壁垒，虚馆开逢迎。
堂上指图画，军中吹玉笙。
岂无成都酒，忧国只细倾。
时观锦水钓，问俗终相并。
意待犬戎灭，人藏红粟盈。
以兹报主愿，庶或裨世程。
炯炯一心在，沈沈二竖婴。
颜回竟短折，贾谊徒忠贞。
飞旐出江汉，孤舟轻荆衡。
虚无马融笛，怅望龙骧茔。
空余老宾客，身上愧簪缨。','',''),('quantangshi-10894','八哀诗 赠太子师汝阳郡王琎','杜甫','quantangshi','','卷11','汝阳让帝子，眉宇真天人。
虬须似太宗，色映塞外春。
往者开元中，主恩视遇频。
出入独非时，礼异见羣臣。
爱其谨洁极，倍此骨肉亲。
从容听朝后，或在风雪晨。
忽思格猛兽，苑囿腾清尘。
羽旗动若一，万马肃駪駪。
诏王来射雁，拜命已挺身。
箭出飞鞚内，上又回翠麟。
飜然紫塞翮，下拂明月轮。
胡人虽获多，天笑不为新。
王每中一物，手自与金银。
袖中谏猎书，扣马久上陈。
竟无衔橛虞，圣聪矧多仁。
官免供给费，水有在藻鳞。
匪唯帝老大，皆是王忠勤。
晚年务置醴，门引申白宾。
道大容无能，永怀侍芳茵。
好学尚贞烈，义形必霑巾。
挥翰绮绣扬，篇什若有神。
川广不可溯，墓久狐兔邻。
宛彼汉中郡，文雅见天伦。
何以开我悲，泛舟俱远津。
温温昔风味，少壮已书绅。
旧游易磨灭，衰谢增酸辛。','',''),('quantangshi-10895','八哀诗 赠祕书监江夏李公邕','杜甫','quantangshi','','卷11','长啸宇宙间，高才日陵替。
古人不可见，前辈复谁继。
忆昔李公存，词林有根柢。
声华当健笔，洒落富清制。
风流散金石，追琢山岳锐。
情穷造化理，学贯天人际。
干谒走其门，碑版照四裔。
各满深望还，森然起凡例。
萧萧白杨路，洞彻宝珠惠。
龙宫墖庙涌，浩劫浮云卫。
宗儒俎豆事，故吏去思计。
眄睐已皆虚，跋涉曾不泥。
向来映当时，岂独劝后世。
丰屋珊瑚钩，骐驎织成罽。
紫骝随劒几，义取无虚岁。
分宅脱骖间，感激怀未济。
众归赒给美，摆落多藏秽。
独步四十年，风听九臯唳。
呜呼江夏姿，竟掩宣尼袂。
往者武后朝，引用多宠嬖。
否臧太常议，面折二张势。
衰俗凛生风，排荡秋旻霁。
忠贞负冤恨，宫阙深旒缀。
放逐早联翩，低垂困炎厉。
日斜鵩鸟入，魂断苍梧帝。
荣枯走不暇，星驾无安税。
几分汉廷竹，夙拥文侯[彗]。
终悲洛阳狱，事近小臣敝。
祸阶初负谤，易力何深哜。
伊昔临淄亭，酒酣托末契。
重敍东都别，朝阴改轩砌。
论文到崔苏，指尽流水逝。
近伏盈川雄，未甘特进丽。
是非张相国，相扼一危脆。
争名古岂然，键捷歘不闭。
例及吾家诗，旷怀埽氛翳。
慷慨嗣真作，咨嗟玉山桂。
钟律俨高悬，鲲鲸喷迢遰。
坡陀青州血，芜没汶阳瘗。
哀赠竟萧条，恩波延揭厉。
子孙存如线，旧客舟凝滞。
君臣尚论兵，将帅接燕蓟。
郎吟六公篇，忧来豁蒙蔽。','',''),('quantangshi-10896','八哀诗 故祕书少监武功苏公源明','杜甫','quantangshi','','卷11','武功少也孤，徒步客徐衮。
读书东岳中，十载考坟典。
时下莱芜郭，忍饥浮云巘。
负米晚为身，每食脸必泫。
夜字照爇薪，垢衣生碧藓。
庶以勤苦志，报兹劬劳显。
学蔚醇儒姿，文包旧史善。
洒落辞幽人，归来潜京辇。
射君东堂策，宗匠集精选。
制可题未干，乙科已大阐。
文章日自负，吏禄亦累践。
晨趋阊阖内，足蹋宿昔趼。
一麾出守还，黄屋朔风卷。
不暇陪八骏，虏庭悲所遣。
平生满尊酒，断此朋知展。
忧愤病二秋，有恨石可转。
肃宗复社稷，得无逆顺辨。
范晔顾其儿，李斯忆黄犬。
祕书茂松意，溟涨本末浅。
青荧芙蓉劒，犀兕岂独剸。
反为后辈亵，予实苦怀缅。
煌煌斋房芝，事绝万手搴。
垂之俟来者，正始征劝勉。
不要悬黄金，胡为投乳贙。
结交三十载，吾与谁游衍。
荥阳复冥莫，罪罟已横罥。
呜呼子逝日，始泰则终蹇。
长安米万钱，凋丧尽余喘。
战伐何当解，归帆阻清沔。
尚缠漳水疾，永负蒿里饯。','',''),('quantangshi-10897','八哀诗 故着作郎贬台州司户荥阳郑公虔','杜甫','quantangshi','','卷11','鶢鶋至鲁门，不识钟鼓飨。
孔翠望赤霄，愁思雕笼养。
荥阳冠众儒，早闻名公赏。
地崇士大夫，况乃气精爽。
天然生知姿，学立游夏上。
神农极阙漏，黄石愧师长。
药纂西极名，兵流指诸掌。
贯穿无遗恨，荟蕞何技痒。
圭臬星经奥，虫篆丹青广。
子云窥未徧，方朔谐太枉。
神翰顾不一，体变钟兼两。
文传天下口，大字犹在牓。
昔献书画图，新诗亦俱往。
沧洲动玉陛，宣鹤误一响。
三绝自御题，四方尤所仰。
嗜酒益疎放，弹琴视天壤。
形骸实土木，亲近唯几杖。
未曾寄官曹，突兀倚书幌。
晚就芸香阁，胡尘昏坱莽。
反覆归圣朝，点染无涤荡。
老蒙台州掾，泛泛淛江桨。
覆穿四明雪，饥拾楢溪橡。
空闻紫芝歌，不见杏坛丈。
天长眺东南，秋色余魍魉。
别离惨至今，斑白徒怀曩。
春深秦山秀，叶坠清渭朗。
剧谈王侯门，野税林下鞅。
操纸终夕酣，时物集遐想。
词场竟疎阔，平昔滥吹奖。
百年见存殁，牢落吾安放。
萧条阮咸在，出处同世网。
他日访江楼，含凄述飘荡。','',''),('quantangshi-10898','八哀诗 故右仆射相国张公九齢','杜甫','quantangshi','','卷11','相国生南纪，金璞无留矿。
仙鹤下人间，独立霜毛整。
矫然江海思，复与云路永。
寂寞想土阶，未遑等箕颍。
上君白玉堂，倚君金华省。
碣石岁峥嵘，天地日蛙黾。
退食吟大庭，何心记榛梗。
骨惊畏曩哲，鬒变负人境。
虽蒙换蝉冠，右地恧多幸。
敢忘二疏归，痛迫苏耽井。
紫绶映暮年，荆州谢所领。
庾公兴不浅，黄霸镇每静。
宾客引调同，讽咏在务屏。
诗罢地有余，篇终语清省。
一阳发阴管，淑气含公鼎。
乃知君子心，用才文章境。
散帙起翠螭，倚薄巫庐竝。
绮丽玄晖拥，牋诔任昉骋。
自我一家则，未缺只字警。
千秋沧海南，名系朱鸟影。
归老守故林，恋阙悄延颈。
波涛良史笔，芜绝大庾岭。
向时礼数隔，制作难上请。
再读徐孺碑，犹思理烟艇。','',''),('quantangshi-10899','写怀二首 一','杜甫','quantangshi','','卷11','劳生共干坤，何处异风俗。
冉冉自趋竞，行行见羁束。
无贵贱不悲，无富贫亦足。
万古一骸骨，邻家递歌哭。
鄙夫到巫峡，三岁如转烛。
全命甘留滞，忘情任荣辱。
朝班及暮齿，日给还脱粟。
编蓬石城东，采药山北谷。
用心霜雪间，不必条蔓绿。
非关故安排，曾是顺幽独。
达士如弦直，小人似钩曲。
曲直我不知，负暄候樵牧。','',''),('quantangshi-10900','写怀二首 二','杜甫','quantangshi','','卷11','夜深坐南轩，明月照我膝。
惊风飜河汉，梁栋已出日。
羣生各一宿，飞动自俦匹。
吾亦驱其儿，营营为私实。
天寒行旅稀，岁暮日月疾。
荣名忽中人，世乱如虮虱。
古者三皇前，满腹志愿毕。
胡为有结绳，陷此胶与漆。
祸首燧人氏，厉阶董孤笔。
君看灯烛张，转使飞蛾密。
放神八极外，俯仰俱萧瑟。
终契如往还，得匪合仙术。','',''),('quantangshi-10901','可叹','杜甫','quantangshi','','卷11','天上浮云如白衣，斯须改变如苍狗。
古往今来共一时，人生万事无不有。
近者抉眼去其夫，河东女儿身姓柳。
丈夫正色动引经，酆城客子王季友。
羣书万卷常暗诵，孝经一通看在手。
贫穷老瘦家卖屐，好事就之为携酒。
豫章太守高帝孙，引为宾客敬颇久。
闻道三年未曾语，小心恐惧闭其口。
太守得之更不疑，人生反覆看亦丑。
明月无瑕岂容易，紫气郁郁犹冲斗。
时危可仗真豪俊，二人得置君侧否。
太守顷者领山南，邦人思之比父母。
王生早曾拜颜色，高山之外皆培塿。
用为羲和天为成，用平水土地为厚。
王也论道阻江湖，李也丞疑旷前后。
死为星辰终不灭，致君尧舜焉肯朽。
吾辈碌碌饱饭行，风后力牧长回首。','',''),('quantangshi-10902','观公孙大娘弟子舞劒器行','杜甫','quantangshi','','卷11','昔有佳人公孙氏，一舞劒气动四方。
观者如山色沮丧，天地为之久低昂。
㸌如羿射九日落，矫如羣帝骖龙翔。
来如雷霆收震怒，罢如江海凝清光。
绛唇珠袖两寂莫，况有弟子传芬芳。
临颍美人在白帝，妙舞此曲神扬扬。
与余问答既有以，感时抚事增惋伤。
先帝侍女八千人，公孙劒器初第一。
五十年间似反掌，风尘倾动昏王室。
棃园子弟散如烟，女乐余姿映寒日。
金粟堆南木已拱，瞿唐石城草萧瑟。
玳筵急管曲复终，乐极哀来月东出。
老夫不知其所往，足茧荒山转愁疾。','',''),('quantangshi-10903','往在','杜甫','quantangshi','','卷11','往在西京日，胡来满彤宫。
中宵焚九庙，云汉为之红。
解瓦飞十里，繐帷纷曾空。
疚心惜木主，一一灰悲风。
合昏排铁骑，清旭散锦𩦺贼臣表逆节，相贺以成功。
是时妃嫔戮，连为粪土丛。
当宁陷玉座，白间剥画虫。
不知二圣处，私泣百岁翁。
车驾既云还，楹桷歘穹崇。
故老复涕泗，祠官树椅桐。
宏壮不如初，已见帝力雄。
前春礼郊庙，祀事亲圣躬。
微躯忝近臣，景从陪羣公。
登阶捧玉册，峨冕耿金钟。
侍祠恧先露，掖垣迩濯龙。
天子惟孝孙，五云起九重。
镜匳换粉黛，翠羽犹葱胧。
前者厌羯胡，后来遭犬戎。
俎豆腐膻肉，罘罳行角弓。
安得自西极，申命空山东。
尽躯诣阙下，士庶塞关中。
主将晓逆顺，元元归始终。
一朝自罪己，万里车书通。
锋镝供锄犂，征戍听所从。
冗官各复业，土着还力农。
君臣节俭足，朝野欢呼同。
中兴似国初，继体如太宗。
端拱纳谏诤，和风日冲融。
赤墀樱桃枝，隐映银丝笼。
千春荐陵寝，永永垂无穷。
京都不再火，泾渭开愁容。
归号故松柏，老去苦飘蓬。','',''),('quantangshi-10904','昔游','杜甫','quantangshi','','卷11','昔者与高李，晚登单父台。
寒芜际碣石，万里风云来。
桑柘叶如雨，飞藿去裴回。
清霜大泽冻，禽兽有余哀。
是时仓廪实，洞达寰区开。
猛士思灭胡，将帅望三台。
君王无所惜，驾驭英雄材。
幽燕盛用武，供给亦劳哉。
吴门转粟帛，泛海陵蓬莱。
肉食三十万，猎射起黄埃。
隔河忆长眺，青岁已摧颓。
不及少年日，无复故人杯。
赋诗独流涕，乱世想贤才。
有能市骏骨，莫恨少龙媒。
商山议得失，蜀主脱嫌猜。
吕尚封国邑，傅说已盐梅。
景晏楚山深，水鹤去低回。
庞公任本性，携子卧苍苔。','',''),('quantangshi-10905','壮游','杜甫','quantangshi','','卷11','往昔十四五，出游翰墨场。
斯文崔魏徒，以我似班扬。
七龄思即壮，开口咏凤皇。
九龄书大字，有作成一囊。
性豪业嗜酒，嫉恶怀刚肠。
脱略小时辈，结交皆老苍。
饮酣视八极，俗物都茫茫。
东下姑苏台，已具浮海航。
到今有遗恨，不得穷扶桑。
王谢风流远，阖庐丘墓荒。
劒池石壁仄，长洲荷芰香。
嵯峨阊门北，清庙映回塘。
每趋吴太伯，抚事泪浪浪。
枕戈忆句践，渡浙想秦皇。
蒸鱼闻匕首，除道哂要章。
越女天下白，鉴湖五月凉。
剡溪蕴秀异，欲罢不能忘。
归帆拂天姥，中岁贡旧乡。
气劘屈贾垒，目短曹刘墙。
忤下考功第，独辞京尹堂。
放荡齐赵间，裘马颇清狂。
春歌丛台上，冬猎青丘旁。
呼鹰皂枥林，逐兽云雪冈。
射飞曾纵鞚，引臂落鹙鸧。
苏侯据鞍喜，忽如携葛强。
快意八九年，西归到咸阳。
许与必词伯，赏游实贤王。
曳裾置醴地，奏赋入明光。
天子废食召，羣公会轩裳。
脱身无所爱，痛饮信行藏。
黑貂不免敝，斑鬓兀称觞。
杜曲晚耆旧，四郊多白杨。
坐深乡党敬，日觉死生忙。
朱门任倾夺，赤族迭罹殃。
国马竭粟豆，官鸡输稻粱。
举隅见烦费，引古惜兴亡。
河朔风尘起，岷山行幸长。
两宫各警跸，万里遥相望。
崆峒杀气黑，少海旌旗黄。
禹功亦命子，涿鹿亲戎行。
翠华拥英岳，螭虎噉豺狼。
爪牙一不中，胡兵更陆梁。
大军载草草，凋瘵满膏肓。
备员窃补衮，忧愤心飞扬。
上感九庙焚，下悯万民疮。
斯时伏青蒲，延争守御牀。
君辱敢爱死，赫怒幸无伤。
圣哲体仁恕，宇县复小康。
哭庙灰烬中，鼻酸朝未央。
小臣议论绝，老病客殊方。
郁郁苦不展，羽翮困低昂。
秋风动哀壑，碧蕙捐微芳。
之推避赏从，渔父濯沧浪。
荣华敌勋业，岁暮有严霜。
吾观鸱夷子，才格出寻常。
羣凶逆未定，侧伫英俊翔。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-10906','遣怀','杜甫','quantangshi','','卷11','昔我游宋中，惟梁孝王都。
名今陈留亚，剧则贝魏俱。
邑中九万家，高栋照通衢。
舟车半天下，主客多欢娱。
白刃讐不义，黄金倾有无。
杀人红尘里，报答在斯须。
忆与高李辈，论交入酒垆。
两公壮藻思，得我色敷腴。
气酣登吹台，怀古视平芜。
芒砀云一去，雁鹜空相呼。
先帝正好武，寰海未凋枯。
猛将收西域，长戟破林胡。
百万攻一城，献捷不云输。
组练弃如泥，尺土负百夫。
拓境功未已，元和辞大炉。
乱离朋友尽，合沓岁月徂。
吾衰将焉托，存殁再呜呼。
萧条益堪愧，独在天一隅。
乘黄已去矣，凡马徒区区。
不复见颜鲍，系舟卧荆巫。
临餐吐更食，常恐违抚孤。','',''),('quantangshi-10907','同元使君舂陵行','杜甫','quantangshi','','卷11','遭乱发尽白，转衰病相婴。
沈緜盗贼际，狼狈江汉行。
叹时药力薄，为客羸瘵成。
吾人诗家秀，博采世上名。
粲粲元道州，前圣畏后生。
观呼舂陵作，歘见俊哲情。
复览贼退篇，结也实国桢。
贾谊昔流恸，匡衡常引经。
道州忧黎庶，词气浩纵横。
两章对秋月，一字偕华星。
至君唐虞际，纯朴忆大庭。
何时降玺书，用尔为丹青。
狱讼永衰息，岂唯偃甲兵。
凄恻念诛求，薄敛近休明。
乃知正人意，不苟飞长缨。
凉飙振南岳，之子宠若惊。
色阻金印大，兴含沧浪清。
我多长卿病，日夕思朝廷。
肺枯渴太甚，漂泊公孙城。
呼儿具纸笔，隐几临轩楹。
作诗呻吟内，黑澹字攲倾。
感彼危苦词，庶几知者听。','',''),('quantangshi-10908','李潮八分小篆歌','杜甫','quantangshi','','卷11','苍颉鸟迹既茫昧，字体变化如浮云。
陈仓石鼓又已讹，大小二篆生八分。
秦有李斯汉蔡邕，中间作者寂不闻。
峄山之碑野火焚，枣木传客肥失真。
苦县光和尚骨立，书贵瘦硬方通神。
惜哉李蔡不复得，吾甥李潮下笔亲。
尚书韩择木，骑曹蔡有邻。
开元已来数八分，潮也奄有二子成三人。
况潮小篆逼秦相，快劒长戟森相向。
八分一字直百金，蛟龙盘拏肉屈强。
吴郡张颠夸草书，草书非古空雄壮。
岂如吾甥不流宕，丞相中郎丈人行。
巴东逢李潮，逾月求我歌。
我今衰老才力薄，潮乎潮乎奈汝何。','',''),('quantangshi-10909','览柏中允兼子侄数人除官制词因述父子兄弟四美载歌丝纶','杜甫','quantangshi','','卷11','纷然丧乱际，见此忠孝门。
蜀中寇亦甚，柏氏功弥存。
深诚补王室，戮力自元昆。
三止锦江沸，独清玉垒昏。
高名入竹帛，新渥照干坤。
子弟先卒伍，芝兰叠璵璠。
同心注师律，洒血在戎轩。
丝纶实具载，绂冕已殊恩。
奉公举骨肉，诛叛经寒温。
金甲雪犹冻，朱旗尘不飜。
每闻战场说，歘激懦气奔。
圣主国多盗，贤臣官则尊。
方当节钺用，必绝祲沴根。
吾病日回首，云台谁再论。
作歌挹盛事，推毂期孤骞。','',''),('quantangshi-10910','听杨氏歌','杜甫','quantangshi','','卷11','佳人绝代歌，独立发皓齿。
满堂惨不乐，响下清虚里。
江城带素月，况乃清夜起。
老夫悲暮年，壮士泪如水。
玉杯久寂寞，金管迷宫征。
勿云听者疲，愚智心尽死。
古来杰出士，岂待一知己。
吾闻昔秦青，倾侧天下耳。','',''),('quantangshi-10911','荆南兵马使太常卿赵公大食刀歌','杜甫','quantangshi','','卷11','太常楼船声嗷嘈，问兵刮寇趋下牢。
牧出令奔飞百艘，猛蛟突兽纷腾逃。
白帝寒城驻锦袍，玄冬示我胡国刀。
壮士短衣头虎毛，凭轩拔鞘天为高。
翻风转日木怒号，冰翼雪澹伤哀猱。
镌错碧甖䴙鹈膏，铓锷已莹虚秋涛。
鬼物撇捩辞坑壕，苍水使者扪赤条。
龙伯国人罢钓鳌，芮公回首颜色劳。
分阃救世用贤豪，赵公玉立高歌起。
揽环结佩相终始，万岁持之护天子。
得君乱丝与君理，蜀江如线如针水。
荆岑弹丸心未已，贼臣恶子休干纪。
魑魅魍魉徒为耳，妖腰乱领敢欣喜。
用之不高亦不庳，不似长劒须天倚。
吁嗟光禄英雄弭，大食宝刀聊可比。
丹青宛转麒麟里，光芒六合无泥滓。','',''),('quantangshi-10912','王兵马使二角鹰','杜甫','quantangshi','','卷11','悲台萧飒石巃嵸，哀壑杈枒浩呼汹。
中有万里之长江，回风滔日孤光动。
角鹰飜倒壮士臂，将军玉帐轩翠气。
二鹰猛脑徐侯穟，目如愁胡视天地。
杉鸡竹兔不自惜，溪虎野羊俱辟易。
韝上锋棱十二翮，将军勇锐与之敌。
将军树勋起安西，昆仑虞泉入马蹄。
白羽曾肉三狻猊，敢决岂不与之齐。
荆南芮公得将军，亦如角鹰下翔云。
恶鸟飞飞啄金屋，安得尔辈开其羣，驱出六合枭鸾分。','',''),('quantangshi-10913','狄明府','杜甫','quantangshi','','卷11','梁公曾孙我姨弟，不见十年官济济。
大贤之后竟陵迟，浩荡古今同一体。
比看叔伯四十人，有才无命百寮底。
今者兄弟一百人，几人卓绝秉周礼。
在汝更用文章为，长兄白眉复天启。
汝门请从曾翁说，太后当朝多巧诋。
狄公执政在末年，浊河终不污清济。
国嗣初将付诸武，公独廷诤守丹陛。
禁中决册请房陵，前朝长老皆流涕。
太宗社稷一朝正，汉宫威仪重昭洗。
时危始识不世才，谁谓荼苦甘如荠。
汝曹又宜列土食，身使门户多旌棨。
胡为漂泊岷汉间，干谒王侯颇历抵。
况乃山高水有波，秋风萧萧露泥泥。
虎之饥，下巉岩。
蛟之横，出清泚。
早归来，黄土泥衣眼易眯。','',''),('quantangshi-10914','秋风二首 一','杜甫','quantangshi','','卷11','秋风淅淅吹巫山，上牢下牢修水关。
吴樯楚柁牵百丈，暖向神都寒未还。
要路何日罢长戟，战自青羌连百蛮。
中巴不曾消息好，暝传戍鼓长云间。','',''),('quantangshi-10915','秋风二首 二','杜甫','quantangshi','','卷11','秋风淅淅吹我衣，东流之外西日微。
天清小城捣练急，石古细路行人稀。
不知明月为谁好，早晚孤帆他夜归。
会将白发倚庭树，故园池台今是非。','',''),('quantangshi-10916','久雨期王将军不至','杜甫','quantangshi','','卷11','天雨萧萧滞茅屋，空山无以慰幽独。
锐头将军来何迟，令我心中苦不足。
数看黄雾乱玄云，时听严风折乔木。
泉源泠泠杂猿狖，泥泞漠漠饥鸿鹄。
岁暮穷阴耿未已，人生会面难再得。
忆尔腰下铁丝箭，射杀林中雪色鹿。
前者坐皮因问毛，知子历险人马劳。
异兽如飞星宿落，应弦不碍苍山高。
安得突骑只五千，崒然眉骨皆尔曹。
走平乱世相催促，一豁明主正郁陶。
忆昔范增碎玉斗，未使吴兵着白袍。
昏昏阊阖闭氛祲，十月荆南雷怒号。','',''),('quantangshi-10917','别李祕书始兴寺所居','杜甫','quantangshi','','卷11','不见祕书心若失，及见祕书失心疾。
安为动主理信然，我独觉子神充实。
重闻西方止观经，老身古寺风泠泠。
妻儿待我且归去，他日杖藜来细听。','',''),('quantangshi-10918','虎牙行','杜甫','quantangshi','','卷11','秋风歘吸吹南国，天地惨惨无颜色。
洞庭扬波江汉回，虎牙铜柱皆倾侧。
巫峡阴岑朔漠气，峰峦窈窕溪谷黑。
杜鹃不来猿狖寒，山鬼幽忧雪霜逼。
楚老长嗟忆炎瘴，三尺角弓两斛力。
壁立石城横塞起，金错旌竿满云直。
渔阳突骑猎青丘，犬戎锁甲闻丹极。
八荒十年防盗贼，征戍诛求寡妻哭，远客中宵泪霑臆。','',''),('quantangshi-10919','锦树行','杜甫','quantangshi','','卷11','今日苦短昨日休，岁云暮矣增离忧。
霜凋碧树待锦树，万壑东逝无停留。
荒戍之城石色古，东郭老人住青丘。
飞书白帝营斗粟，琴瑟几杖柴门幽。
青草萋萋尽枯死，天马跂足随氂牛。
自古圣贤多薄命，奸雄恶少皆封侯。
故国三年一消息，终南渭水寒悠悠。
五陵豪贵反颠倒，乡里小儿狐白裘。
生男堕地要膂力，一生富贵倾邦国。
莫愁父母少黄金，天下风尘儿亦得。','',''),('quantangshi-10920','赤霄行','杜甫','quantangshi','','卷11','孔雀未知牛有角，渴饮寒泉逢抵触。
赤霄悬圃须往来，翠尾金花不辞辱。
江中淘河吓飞燕，衔泥却落羞华屋。
皇孙犹曾莲勺困，卫庄见贬伤其足。
老翁慎莫怪少年，葛亮贵和书有篇。
丈夫垂名动万年，记忆细故非高贤。','',''),('quantangshi-10921','前苦寒行二首 一','杜甫','quantangshi','','卷11','汉时长安雪一丈，牛马毛寒缩如猬。
楚江巫峡冰入怀，虎豹哀号又堪记。
秦城老翁荆扬客，惯习炎蒸岁絺綌。
玄冥祝融气或交，手持白羽未敢释。','',''),('quantangshi-10922','前苦寒行二首 二','杜甫','quantangshi','','卷11','去年白帝雪在山，今年白帝雪在地。
冻埋蛟龙南浦缩，寒刮肌肤北风利。
楚人四时皆麻衣，楚天万里无晶辉。
三足之乌足恐断，羲和送将何所归。','',''),('quantangshi-10923','后苦寒行二首 一','杜甫','quantangshi','','卷11','南纪巫庐瘴不绝，太古以来无尺雪。
蛮夷长老怨苦寒，昆仑天关冻应折。','',''),('quantangshi-10924','后苦寒行二首 二','杜甫','quantangshi','','卷11','晚来江门失大木，猛风中夜吹白屋。
天兵斩断青海戎，杀气南行动地轴，不尔苦寒何太酷。
巴东之峡生凌澌，彼苍回轩人得知。','',''),('quantangshi-10925','晚晴','杜甫','quantangshi','','卷11','高唐暮冬雪壮哉，旧瘴无复似尘埃。
崖沈谷没白皑皑，江石缺裂青枫摧。
南天三旬苦雾开，赤日照耀从西来。
六龙寒急光裴回，照我衰颜忽落地，口虽吟咏心中哀。
未怪及时少年子，扬眉结义黄金台。
洎乎吾生何飘零，支离委绝同死灰。','',''),('quantangshi-10926','复阴','杜甫','quantangshi','','卷11','方冬合沓玄阴塞，昨日晚晴今日黑。
万里飞蓬映天过，孤城树羽扬风直。
江涛簸岸黄沙走，云雪埋山苍兕吼。
君不见夔子之国杜陵翁，牙齿半落左耳聋。','',''),('quantangshi-10927','夜归','杜甫','quantangshi','','卷11','夜来归来冲虎过，山黑家中已眠卧。
傍见北斗向江低，仰看明星当空大。
庭前把烛嗔两炬，峡口惊猿闻一个。
白头老罢舞复歌，杖藜不睡谁能那。','',''),('quantangshi-10928','寄柏学士林居','杜甫','quantangshi','','卷11','自胡之反持干戈，天下学士亦奔波。
叹彼幽栖载典籍，萧然暴露依山阿。
青山万里静散地，白雨一洗空垂萝。
乱代飘零余到此，古人成败子如何。
荆扬春冬异风土，巫峡日夜多云雨。
赤叶枫林百舌鸣，黄泥野岸天鸡舞。
盗贼纵横甚密迩，形神寂莫甘辛苦。
几时高议排金门，各使苍生有环堵。','',''),('quantangshi-10929','寄从孙崇简','杜甫','quantangshi','','卷11','嵯峨白帝城东西，南有龙湫北虎溪。
吾孙骑曹不骑马，业学尸乡多养鸡。
庞公隐时尽室去，武陵春树他人迷。
与汝林居未相失，近身药裹酒长携。
牧竖樵童亦无赖，莫令斩断青云梯。','',''),('quantangshi-10930','奉酬薛十二丈判官见赠','杜甫','quantangshi','','卷11','忽忽峡中睡，悲风方一醒。
西来有好鸟，为我下青冥。
羽毛净白雪，惨澹飞云汀。
既蒙主人顾，举翮唳孤亭。
持以比佳士，及此慰扬舲。
清文动哀玉，见道发新硎。
欲学鸱夷子，待勒燕山铭。
谁重断蛇劒，致君君未听。
志在麒麟阁，无心云母屏。
卓氏近新寡，豪家朱门扃。
相如才调逸，银汉会双星。
客来洗粉黛，日暮拾流萤。
不是无膏火，劝郎勤六经。
老夫自汲涧，野水日泠泠。
我叹黑头白，君看银印青。
卧病识山鬼，为农知地形。
谁矜坐锦帐，苦厌食鱼腥。
东西两岸坼，横水注沧溟。
碧色忽惆怅，风雷搜百灵。
空中右白虎，赤节引娉婷。
自云帝里女，噀雨凤凰翎。
襄王薄行迹，莫学冷如丁。
千秋一拭泪，梦觉有微馨。
人生相感动，金石两青荧。
丈人但安坐，休辨渭与泾。
龙蛇尚格鬬，洒血暗郊坰。
吾闻聪明主，治国用轻刑。
销兵铸农器，今古岁方宁。
文王日俭德，俊乂始盈庭。
荣华贵少壮，岂食楚江萍。','',''),('quantangshi-10931','醉为马坠诸公携酒相看','杜甫','quantangshi','','卷11','甫也诸侯老宾客，罢酒酣歌拓金戟。
骑马忽忆少年时，散蹄迸落瞿塘石。
白帝城门水云外，低身直下八千尺。
粉堞电转紫游缰，东得平冈出天壁。
江村野堂争入眼，垂鞭嚲鞚凌紫陌。
向来皓首惊万人，自倚红颜能骑射。
安知决臆追风足，朱汗骖驔犹喷玉。
不虞一蹶终损伤，人生快意多所辱。
职当忧戚伏衾枕，况乃迟暮加烦促。
明知来问腆我颜，杖藜强起依僮仆。
语尽还成开口笑，提携别埽清溪曲。
酒肉如山又一时，初筵哀丝动豪竹。
共指西日不相贷，喧呼且覆杯中渌。
何必走马来为问，君不见嵇康养生遭杀戮。','',''),('quantangshi-10932','别李义','杜甫','quantangshi','','卷11','神尧十八子，十七王其门。
道国洎舒国，督唯亲弟昆。
中外贵贱殊，余亦忝诸孙。
丈人嗣三叶，之子白玉温。
道国继德业，请从丈人论。
丈人领宗卿，肃穆古制敦。
先朝纳谏诤，直气横干坤。
子建文笔壮，河间经术存。
尔克富诗礼，骨清虑不喧。
洗然遇知几，谈论淮湖奔。
忆昔初见时，小襦绣芳荪。
长成忽会面，慰我久疾魂。
三峡春冬交，江山云雾昏。
正宜且聚集，恨此当离尊。
莫怪执杯迟，我衰涕唾烦。
重问子何之，西上岷江源。
愿子少干谒，蜀都足戎轩。
误失将帅意，不如亲故恩。
少年早归来，梅花已飞飜。
努力慎风水，岂惟数盘[飧]。
猛虎卧在岸，蛟螭出无痕。
王子自爱惜，老夫困石根。
生别古所嗟，发声为尔吞。','',''),('quantangshi-10933','送高司直寻封阆州','杜甫','quantangshi','','卷11','丹雀衔书来，暮栖何乡树。
骅骝事天子，辛苦在道路。
司直非冗官，荒山甚无趣。
借问泛舟人，胡为入云雾。
与子姻娅间，即亲亦有故。
万里长江边，邂逅一相遇。
长卿消渴再，公干沈緜屡。
清谈慰老夫，开卷得佳句。
时见文章士，欣然澹情素。
伏枕闻别离，畴能忍漂寓。
良会苦短促，溪行水奔注。
熊罴咆空林，游子慎驰骛。
西谒巴中侯，艰险如跬步。
主人不世才，先帝常特顾。
拔为天军佐，崇大王法度。
淮海生清风，南翁尚思慕。
公宫造广厦，木石乃无数。
初闻伐松柏，犹卧天一柱。
我瘦书不成，成字读亦误。
为我问故人，劳心练征戍。','',''),('quantangshi-10934','君不见简苏徯','杜甫','quantangshi','','卷11','君不见道边废弃池，君不见前者摧折桐。
百年死树中琴瑟，一斛旧水藏蛟龙。
丈夫盖棺事始定，君今幸未成老翁。
何恨顦顇在山中，深山穷谷不可处，霹雳魍魉兼狂风。','',''),('quantangshi-10935','赠苏四徯','杜甫','quantangshi','','卷11','异县昔同游，各云厌转蓬。
别离已五年，尚在行李中。
戎马日衰息，乘舆安九重。
有才何栖栖，将老委所穷。
为郎未为贱，其奈疾病攻。
子何面黧黑，不得豁心胷。
巴蜀倦剽掠，下愚成土风。
幽蓟已削平，荒徼尚弯弓。
斯人脱身来，岂非吾道东。
干坤虽宽大，所适装囊空。
肉食哂菜色，少壮欺老翁。
况乃主客间，古来逼侧同。
君今下荆扬，独帆如飞鸿。
二州豪侠场，人马皆自雄。
一请甘饥寒，再请甘养蒙。','',''),('quantangshi-10936','寄薛三郎中','杜甫','quantangshi','','卷11','人生无贤愚，飘颻若埃尘。
自非得神仙，谁免危其身。
与子俱白头，役役常苦辛。
虽为尚书郎，不及村野人。
忆昔村野人，其乐难具陈。
蔼蔼桑麻交，公侯为等伦。
天未厌戎马，我辈本常贫。
子尚客荆州，我亦滞江滨。
峡中一卧病，疟疠终冬春。
春复加肺气，此病盖有因。
早岁与苏郑，痛饮情相亲。
二公化为土，嗜酒不失真。
余今委修短，岂得恨命屯。
闻子心甚壮，所遇信席珍。
上马不用扶，每扶必怒嗔。
赋诗宾客间，挥洒动八垠。
乃知盖代手，才力老益神。
青草洞庭湖，东浮沧海漘。
君山可避暑，况足采白苹。
子岂无扁舟，往复江汉津。
我未下瞿塘，空念禹功勤。
听说松门峡，吐药揽衣巾。
高秋却束带，鼓枻视青旻。
凤池日澄碧，济济多士新。
余病不能起，健者勿逡巡。
上有明哲君，下有行化臣。','',''),('quantangshi-10937','大觉高僧兰若','杜甫','quantangshi','','卷11','巫山不见庐山远，松林兰若秋风晚。
一老犹鸣日暮钟，诸僧尚乞斋时饭。
香炉峰色隐晴湖，种杏仙家近白榆。
飞锡去年啼邑子，献花何日许门徒。','',''),('quantangshi-10938','宿青溪驿奉怀张员外十五兄之绪','杜甫','quantangshi','','卷11','漾舟千山内，日入泊枉渚。
我生本飘飘，今复在何许。
石根青枫林，猿鸟聚俦侣。
月明游子静，畏虎不得语。
中夜怀友朋，干坤此深阻。
浩荡前后间，佳期付荆楚。','',''),('quantangshi-10939','敬寄族弟唐十八使君','杜甫','quantangshi','','卷11','与君陶唐后，盛族多其人。
圣贤冠史籍，枝派罗源津。
在今气磊落，巧伪莫敢亲。
介立实吾弟，济时肯杀身。
物白讳受玷，行高无污真。
得罪永泰末，放之五溪滨。
鸾凤有铩翮，先儒曾抱麟。
雷霆霹长松，骨大却生筋。
一失不足伤，念子孰自珍。
泊舟楚宫岸，恋阙浩酸辛。
除名配清江，厥土巫峡邻。
登陆将首途，笔札枉所申。
归朝局病肺，叙旧思重陈。
春风洪涛壮，谷转颇弥旬。
我能泛中流，搪突鼍獭瞋。
长年已省柁，慰此贞良臣。','',''),('quantangshi-10940','忆昔行','杜甫','quantangshi','','卷11','忆昔北寻小有洞，洪河怒涛过轻舸。
辛勤不见华盖君，艮岑青辉惨么么。
千崖无人万壑静，三步回头五步坐。
秋山眼冷魂未归，仙赏心违泪交堕。
弟子谁依白茅室，卢老独启青铜锁。
巾拂香余捣药尘，阶除灰死烧丹火。
悬圃沧洲莽空阔，金节羽衣飘婀娜。
落日初霞闪余映，倏忽东西无不可。
松风涧水声合时，青兕黄熊啼向我。
徒然咨嗟抚遗迹，至今梦想犹佐。
祕诀隐文须内教，晚岁何功使愿果。
更讨衡阳董炼师，南浮早鼓潇湘柁。','',''),('quantangshi-10941','魏将军歌','杜甫','quantangshi','','卷11','将军昔着从事衫，铁马驰突重两衔。
披坚执锐略西极，昆仑月窟东崭岩。
君门羽林万猛士，恶若哮虎子所监。
五年起家列霜戟，一日过海收风帆。
平生流辈徒蠢蠢，长安少年气欲尽。
魏侯骨耸精爽紧，华岳峰尖见秋隼。
星躔宝校金盘陀，夜骑天驷超天河。
欃枪荧惑不敢动，翠蕤云旓相荡摩。
吾为子起歌都护，酒阑插劒肝胆露。','',''),('quantangshi-10942','北风','杜甫','quantangshi','','卷11','北风破南极，朱凤日威垂。
洞庭秋欲雪，鸿雁将安归。
十年杀气盛，六合人烟稀。
吾慕汉初老，时清犹茹芝。','',''),('quantangshi-10943','客从','杜甫','quantangshi','','卷11','客从南溟来，遗我泉客珠。
珠中有隐字，欲辨不成书。
缄之箧笥久，以俟公家须。
开视化为血，哀今征敛无。','',''),('quantangshi-10944','白马','杜甫','quantangshi','','卷11','白马东北来，空鞍贯双箭。
可怜马上郎，意气今谁见。
近时主将戳，中夜商于战。
丧乱死多门，呜呼泪如霰。','',''),('quantangshi-10945','白凫行','杜甫','quantangshi','','卷11','君不见黄鹄高于五尺童，化为白凫似老翁。
故畦遗穗已荡尽，天寒岁暮波涛中。
鳞介腥膻素不食，终日忍饥西复东。
鲁门鶢鶋亦蹭蹬，闻道如今犹避风。','',''),('quantangshi-10946','朱凤行','杜甫','quantangshi','','卷11','君不见潇湘之山衡山高，山巅朱凤声嗷嗷。
侧身长顾求其羣，翅垂口噤心甚劳。
下愍百鸟在罗网，黄雀最小犹难逃。
愿分竹实及蝼蚁，尽使鸱枭相怒号。','',''),('quantangshi-10947','惜别行送向卿进奉端午御衣之上都','杜甫','quantangshi','','卷11','肃宗昔在灵武城，指挥猛将收咸京。
向公泣血洒行殿，佐佑卿相干坤平。
逆胡冥寞随烟烬，卿家兄弟功名震。
麒麟图画鸿雁行，紫极出入黄金印。
尚书勋业超千古，雄镇荆州继吾祖。
裁缝云雾成御衣，拜跪题封向端午。
向卿将命寸心赤，青山落日江潮白。
卿到朝廷说老翁，漂零已是沧浪客。','',''),('quantangshi-10948','醉歌行赠公安颜少府请顾八题壁','杜甫','quantangshi','','卷11','神仙中人不易得，颜氏之子才孤标。
天马长鸣待驾驭，秋鹰整翮当云霄。
君不见东吴顾文学，君不见西汉杜陵老。
诗家笔势君不嫌，词翰升堂为君埽。
是日霜风冻七泽，乌蛮落照衔赤壁。
酒酣耳热忘头白，感君意气无所惜，一为歌行歌主客。','',''),('quantangshi-10949','夜闻觱篥','杜甫','quantangshi','','卷11','夜闻觱篥沧江上，衰年侧耳情所向。
邻舟一听多感伤，塞曲三更歘悲壮。
积雪飞霜此夜寒，孤灯急管复风湍。
君知天地干戈满，不见江湖行路难。','',''),('quantangshi-10950','发刘郎浦','杜甫','quantangshi','','卷11','挂帆早发刘郎浦，疾风飒飒昏亭午。
舟中无日不沙尘，岸上空村尽豺虎。
十日北风风未回，客行岁晚晚相催。
白头厌伴渔人宿，黄帽青鞋归去来。','',''),('quantangshi-10951','别董颋','杜甫','quantangshi','','卷11','穷冬急风水，逆浪开帆难。
士子甘旨阙，不知道里寒。
有求彼乐土，南适小长安。
到我舟檝去，觉君衣裳单。
素闻赵公节，兼尽宾主欢。
已结门庐望，无令霜雪残。
老夫缆亦解，脱粟朝未餐。
飘荡兵甲际，几时怀抱宽。
汉阳颇宁静，岘首试考盘。
当念着白帽，采薇青云端。','',''),('quantangshi-10952','送重表侄王砅评事使南海','杜甫','quantangshi','','卷11','我之曾祖姑，尔之高祖母。
尔祖未显时，归为尚书妇。
隋朝大业末，房杜俱交友长者来在门，荒年自糊口。
家贫无供给，客位但箕帚。
俄顷羞颇珍，寂寥人散后。
入怪鬓发空，吁嗟为之久。
自陈剪髻鬟，鬻市充杯酒。
上云天下乱，宜与英俊厚。
向窃窥数公，经纶亦俱有。
次问最少年，虬髯十八九。
子等成大名，皆因此人手。
下云风云合，龙虎一吟吼。
愿展丈夫雄，得辞儿女丑。
秦王时在坐，真气惊户牖。
及乎贞观初，尚书践台斗。
夫人常肩舆，上殿称万寿。
六宫师柔顺，法则化妃后。
至尊均嫂叔，盛事垂不朽。
凤雏无凡毛，五色非尔曹。
往者胡作逆，干坤沸嗷嗷。
吾客左冯翊，尔家同遁逃。
争夺至徒步，块独委蓬蒿。
逗留热尔肠，十里却呼号。
自下所骑马，右持腰间刀。
左牵紫游缰，飞走使我高。
苟活到今日，寸心铭佩牢。
乱离又聚散，宿昔恨滔滔。
水花笑白首，春草随青袍。
廷评近要津，节制收英髦。
北驱汉阳传，南泛上泷舠。
家声肯坠地，利器当秋毫。
番禺亲贤领，筹运神功操。
大夫出卢宋，宝贝休脂膏。
洞主降接武，海胡舶千艘。
我欲就丹砂，跋涉觉身劳。
安能陷粪土，有志乘鲸鳌。
或骖鸾腾天，聊作鹤鸣臯。','',''),('quantangshi-10953','咏怀二首 一','杜甫','quantangshi','','卷11','人生贵是男，丈夫重天机。
未达善一身，得志行所为。
嗟余竟轗轲，将老逢艰危。
胡雏逼神器，逆节同所归。
河雒化为血，公侯草间啼。
西京复陷没，翠盖蒙尘飞。
万姓悲赤子，两宫弃紫微。
倏忽向二纪，奸雄多是非。
本朝再树立，未及贞观时。
日给在军储，上官督有司。
高贤迫形势，岂暇相扶持。
疲{艹尔}苟怀策，栖屑无所施。
先王实罪己，愁痛正为兹。
岁月不我与，蹉跎病于斯。
夜看丰城气，回首蛟龙池。
齿发已自料，意深陈苦词。','',''),('quantangshi-10954','咏怀二首 二','杜甫','quantangshi','','卷11','邦危坏法则，圣远益愁慕。
飘颻桂水游，怅望苍梧暮。
潜鱼不衔钩，走鹿无反顾。
皦皦幽旷心，拳拳异平素。
衣食相拘阂，朋知限流寓。
风涛上春沙，千里侵江树。
逆行少吉日，时节空复度。
井竈任尘埃，舟航烦数具。
牵缠加老病，琐细隘俗务。
万古一死生，胡为足名数。
多忧污桃源，拙计泥铜柱。
未辞炎瘴毒，摆落跋涉惧。
虎狼窥中原，焉得所历住。
葛洪及许靖，避世常此路。
贤愚诚等差，自爱各驰骛。
羸瘠且如何，魄夺针灸屡。
拥滞僮仆慵，稽留篙师怒。
终当挂帆席，天意难告诉。
南为祝融客，勉强亲杖屦。
结托老人星，罗浮展衰步。','',''),('quantangshi-10955','送顾八分文学适洪吉州','杜甫','quantangshi','','卷11','中郎石经后，八分盖顦顇。
愿侯运炉锤，笔力破余地。
昔在开元中，韩蔡同贔屭。
玄宗妙其书，是以数子至。
御札早流传，揄扬非造次。
三人竝入直，恩泽各不二。
愿于韩蔡内，辨眼工小字。
分日示诸王，钩深法更祕。
文学与我游，萧疎外声利。
追随二十载，浩荡长安醉。
高歌卿相宅，文翰飞省寺。
视我扬马间，白首不相弃。
骅骝入穷巷，必脱黄金辔。
一论朋友难，迟暮敢失坠。
古来事反覆，相见横涕泗。
向者玉珂人，谁是青云器。
才尽伤形体，病渴污官位。
故旧独依然，时危话颠踬。
我甘多病老，子负忧世志。
胡为困衣食，颜色少称遂。
远作辛苦行，顺从众多意。
舟檝无根蔕，蛟鼍好为祟。
况兼水贼繁，特戒风飙驶。
崩腾戎马际，往往杀长吏。
子干东诸侯，劝勉防纵恣。
邦以民为本，鱼饥费香饵。
请哀疮痍深，告诉皇华使。
使臣精所择，进德知历试。
恻隐诛求情，固应贤愚异。
列士恶苟得，俊杰思自致。
赠子猛虎行，出效载酸鼻。','',''),('quantangshi-10956','上水遣怀','杜甫','quantangshi','','卷11','我衰太平时，身病戎马后。
蹭蹬多拙为，安得不皓首。
驱驰四海内，童稚日糊口。
但遇新少年，少逢旧亲友。
低颜下色地，故人知善诱。
后生血气豪，举动见老丑。
穷迫挫曩怀，常如中风走。
一纪出西蜀，于今向南斗。
孤舟乱春华，暮齿依蒲柳。
冥冥九疑葬，圣者骨亦朽。
蹉跎陶唐人，鞭挞日月久。
中间屈贾辈，谗毁竟自取。
郁没二悲魂，萧条犹在否。
崷崒清湘石，逆行杂林薮。
篙工密逞巧，气若酣杯酒。
歌讴互激远，回斡明受授。
善知应触类，各藉颖脱手。
古来经济才，何事独罕有。
苍苍众色晚，熊挂玄蛇吼。
黄罴在树颠，正为羣虎守。
羸骸将何适，履险颜益厚。
庶与达者论，吞声混瑕垢。','',''),('quantangshi-10957','遣遇','杜甫','quantangshi','','卷11','磬折辞主人，开帆驾洪涛。
春水满南国，朱崖云日高。
舟子废寝食，飘风争所操。
我行匪利涉，谢尔从者劳。
石间采蕨女，鬻菜输官曹。
丈夫死百役，暮返空邨号。
闻见事略同，刻剥及锥刀。
贵人岂不仁，视汝如莠蒿。
索钱多门户，丧乱纷嗷嗷。
奈何黠吏徒，渔夺成逋逃。
自喜遂生理，花时甘緼袍。','',''),('quantangshi-10958','解忧','杜甫','quantangshi','','卷11','减米散同舟，路难恩共济。
向来云涛盘，众力亦不细。
呀坑瞥眼过，飞橹本无蔕。
得失瞬息间，致远宜恐泥。
百虑视安危，分明曩贤计。
兹理庶可广，拳拳期勿替。','',''),('quantangshi-10959','宿鉴石浦','杜甫','quantangshi','','卷11','早宿宾从劳，仲春江山丽。
飘风过无时，舟檝敢不系。
回塘澹暮色，日没众星嘒。
缺月残未生，青灯死分翳。
穷途多俊异，乱世少恩惠。
鄙夫亦放荡，草草频卒岁。
斯文忧患余，圣哲垂彖系。','',''),('quantangshi-10960','早行','杜甫','quantangshi','','卷11','歌哭俱在晓，行迈有期程。
孤舟似昨日，闻见同一声。
飞鸟数求食，潜鱼亦独惊。
前王作网罟，设法害生成。
碧藻非不茂，高帆终日征。
干戈未揖让，崩迫开其情。','',''),('quantangshi-10961','过津口','杜甫','quantangshi','','卷11','南岳自兹近，湘流东逝深。
和风引桂楫，春日涨云岑。
回首过津口，而多枫树林。
白鱼困密网，黄鸟喧嘉音。
物微限通塞，恻隐仁者心。
瓮余不尽酒，膝有无声琴。
圣贤两寂寞，眇眇独开襟。','',''),('quantangshi-10962','次空灵岸','杜甫','quantangshi','','卷11','沄沄逆素浪，落落展清眺。
幸有舟檝迟，得尽所历妙。
空灵霞石峻，枫栝隐奔峭。
青春犹无私，白日亦偏照。
可使营吾居，终焉托长啸。
毒瘴未足忧，兵戈满边徼。
向者留遗恨，耻为达人诮。
回帆凯赏延，佳处领其要。','',''),('quantangshi-10963','宿花石戍','杜甫','quantangshi','','卷11','午辞空灵岑，夕得花石戍。
岸疏开辟水，木杂今古树。
地蒸南风盛，春热西日暮。
四序本平分，气候何回互。
茫茫天造间，理乱岂恒数。
系舟盘藤轮，策杖古樵路。
罢人不在村，野圃泉自注。
柴扉虽芜没，农器尚牢固。
山东残逆气，吴楚守王度。
谁能扣君门，下令减征赋。','',''),('quantangshi-10964','早发','杜甫','quantangshi','','卷11','有求常百虑，斯文亦吾病。
以兹朋故多，穷老驱驰并。
早行篙师怠，席挂风不正。
昔人戒垂堂，今则奚奔命。
涛飜黑蛟跃，日山黄雾映。
烦促瘴岂侵，颓倚睡未醒。
仆夫问盥栉，暮颜腼青镜。
随意簪葛巾，仰慙林花盛。
侧闻夜来寇，幸喜囊中净。
艰危作远客，干请伤直性。
薇蕨饿首阳，粟马资历聘。
贱子欲适从，疑误此二柄。','',''),('quantangshi-10965','次晚洲','杜甫','quantangshi','','卷11','参错云石稠，坡陀风涛壮。
晚洲适知名，秀色固异状。
棹经垂猨把，身在度鸟上。
摆浪散帙妨，危沙折花当。
羁离暂愉悦，羸老反惆怅。
中原未解兵，吾得终疎放。','',''),('quantangshi-10966','望岳','杜甫','quantangshi','','卷11','南岳配朱鸟，秩礼自百王。
歘吸领地灵，鸿洞半炎方。
邦家用祀典，在德非馨香。
巡守何寂寥，有虞今则亡。
洎吾隘世网，行迈越潇湘。
渴日绝壁出，漾舟清光旁。
祝融五峰尊，峰峰次低昴。
紫盖独不朝，争长嶫相望。
恭闻魏夫人，羣仙夹翱翔。
有时五峰气，散风如飞霜。
牵迫限修途，未暇杖崇冈。
归来觊命驾，沐浴休玉堂。
三叹问府主，曷以赞我皇。
牲璧忍衰俗，神其思降祥。','',''),('quantangshi-10967','湘江宴饯裴二端公赴道州','杜甫','quantangshi','','卷11','白日照舟师，朱旗散广川。
羣公饯南伯，肃肃秩初筵。
鄙人奉末眷，佩服自早年。
义均骨肉地，怀抱罄所宣。
盛名富事业，无取愧高贤。
不以丧乱婴，保爱金石坚。
计拙百僚下，气苏君子前。
会合苦不久，哀乐本相缠。
交游飒向尽，宿昔浩茫然。
促觞激百虑，掩抑泪潺湲。
热云集曛黑，缺月未生天。
白团为我破，华烛蟠长烟。
鸹鹖催明星，解袂从此旋。
上请减兵甲，下请安井田。
永念病渴老，附书远山巅。','',''),('quantangshi-10968','清明','杜甫','quantangshi','','卷11','着处繁花务是日，长沙千人万人出。
渡头翠柳艳明眉，争道朱蹄骄啮膝。
此都好游湘西寺，诸将亦自军中至。
马援征行在眼前，葛强亲近同心事。
金镫下山红粉晚，牙樯捩柁青楼远。
古时丧乱皆可知，人世悲欢暂相遣。
弟侄虽存不得书，干戈未息苦离居。
逢迎少壮非吾道，况乃今朝更祓除。','',''),('quantangshi-10969','风雨看舟前落花戏为新句','杜甫','quantangshi','','卷11','江上人家桃树枝，春寒细雨出疎篱。
影遭碧水潜勾引，风妒红花却倒吹。
吹花困癫傍舟檝，水光风力俱相怯。
赤憎轻薄遮入怀，珍重分明不来接。
湿久飞迟半日高，萦沙惹草细于毛。
蜜蜂蝴蝶生情性，偷眼蜻蜓避百劳。','',''),('quantangshi-10970','岳麓山道林二寺行','杜甫','quantangshi','','卷11','玉泉之南麓山殊，道林林壑争盘纡。
寺门高开洞庭野，殿脚插入赤沙湖。
五月寒风冷佛骨，六时天乐朝香炉。
地灵步步雪山草，僧宝人人沧海珠。
墖劫宫墙壮丽敌，香厨松道清凉俱。
连花交响共命鸟，金牓双回三足乌。
方丈涉海费时节，悬圃寻河知有无。
暮年且喜经行近，春日兼蒙暄暖扶。
飘然斑白身奚适，傍此烟霞茅可诛。
桃源人家易制度，橘洲田土仍膏腴。
潭府邑中甚淳古，太守庭内不喧呼。
昔遭衰世皆晦迹，今幸乐国养微躯。
依止老宿亦未晚，富贵功名焉足图。
久为野客寻幽惯，细学何颙免兴孤。
一重一掩吾肺腑，山鸟山花吾友于。
宋公放逐曾题壁，物色分留与老夫。','',''),('quantangshi-10971','奉送魏六丈佑少府之交广','杜甫','quantangshi','','卷11','贤豪赞经纶，功成空名垂。
子孙不振耀，历代皆有之。
郑公四叶孙，长大常苦饥。
众中见毛骨，犹是麒麟儿。
磊落贞观事，致君朴直词。
家声盖六合，行色何其微。
遇我苍吾阴，忽惊会面稀。
议论有余地，公侯来未迟。
虚思黄金贵，自笑青云期。
长卿久病渴，武帝元同时。
季子黑貂敝，得无妻嫂欺。
尚为诸侯客，独屈州县卑。
南游炎海甸，浩荡从此辞。
穷途仗神道，世乱轻土宜。
解帆岁云暮，可与春风归。
出入朱门家，华屋刻蛟螭。
玉食亚王者，乐张游子悲。
侍婢艳倾城，绡绮轻雾霏。
掌中琥珀钟，行酒双逶迤。
新欢继明烛，梁栋星辰飞。
两情顾盼合，珠碧赠于斯。
上贵见肝胆，下贵不相疑。
心事披写间，气酣达所为。
错挥铁如意，莫避珊瑚枝。
始兼逸迈兴，终慎宾主仪。
戎马暗天宇，呜呼生别离。','',''),('quantangshi-10972','别张十三建封','杜甫','quantangshi','','卷11','尝读唐实录，国家草昧初。
刘裴建首义，龙见尚踌躇。
秦王拨乱姿，一劒总兵符。
汾晋为丰沛，暴隋竟涤除。
宗臣则庙食，后祀何疎芜。
彭城英雄种，宜膺将相图。
尔惟外曾孙，倜傥汗血驹。
眼中万少年，用意尽崎岖。
相逢长沙亭，乍问绪业余。
乃吾故人子，童丱聊居诸。
挥手洒衰泪，仰看八尺躯。
内外名家流，风神荡江湖。
范云堪晚友，嵇绍自不孤。
择材征南幕，湖落回鲸鱼。
载感贾生恸，复闻乐毅书。
主忧急盗贼，师老荒京都。
旧丘岂税驾，大厦倾宜扶。
君臣各有分，管葛本时须。
虽当霰雪严，未觉栝柏枯。
高义在云台，嘶鸣望天衢。
羽人埽碧海，功业竟何如。','',''),('quantangshi-10973','暮秋枉裴道州手札率尔遣兴寄近呈苏涣侍御','杜甫','quantangshi','','卷11','久客多枉友朋书，素书一月凡一束。
虚名但蒙寒温问，泛爱不救沟壑辱。
齿落未是无心人，舌存耻作穷途哭。
道州手札适复至，纸长要自三过读。
盈把那须沧海珠，入怀本倚昆山玉。
拨弃潭州百斛酒，芜没潇岸千株菊。
使我昼立烦儿孙，令我夜坐费灯烛。
忆子初尉永嘉去，红颜白面花映肉。
军符侯印取岂迟，紫燕騄耳行甚速。
圣朝尚飞战鬬尘，济世宜引英俊人。
黎元愁痛会苏息，夷狄跋扈徒逡巡。
授钺筑坛闻意旨，颓纲漏网期弥纶。
郭钦上书见大计，刘毅答诏惊羣臣。
他日更仆语不浅，明公论兵气益振。
倾壶箫管黑白发，儛劒霜雪吹青春。
宴筵曾语苏季子，后来杰出云孙比。
茅斋定王城郭门，药物楚老渔商市。
市北肩舆每联袂，郭南抱瓮亦隐几。
无数将军西第成，早作丞相东山起。
鸟雀苦肥秋粟菽，蛟龙欲蛰寒沙水。
天下鼓角何时休，阵前部曲终日死。
附书与裴因示苏，此生已愧须人扶。
致君尧舜付公等，早据要路思捐躯。','',''),('quantangshi-10974','奉赠李八丈判官','杜甫','quantangshi','','卷11','我丈时英特，宗枝神尧后。
珊瑚市则无，騄骥人得有。
早年见标格，秀气冲星斗。
事业富清机，官曹正独守。
顷来树嘉政，皆已传众口。
艰难体贵安，冗长吾敢取。
区区犹历试，炯炯更持久。
讨论实解颐，操割纷应手。
箧书积讽谏，宫阙限奔走。
入幕未展材，秉钧孰为偶。
所亲问淹泊，泛爱惜衰朽。
垂白乱南翁，委身希北叟。
真成穷辙鲋，或似丧家狗。
秋枯洞庭石，风飒长沙柳。
高兴激荆衡，知音为回首。','',''),('quantangshi-10975','岁晏行','杜甫','quantangshi','','卷11','岁云暮矣多北风，潇湘洞庭白雪中。
渔父天寒网罟冻，莫徭射雁鸣桑弓。
去年米贵阙军食，今年米贱大伤农。
高马达官厌酒肉，此辈杼轴茅茨空。
楚人重鱼不重鸟，汝休枉杀南飞鸿。
况闻处处鬻男女，割慈忍爱还租庸。
往日用钱捉私铸，今许铅锡和青铜。
刻泥为之最易得，好恶不合长相蒙。
万国城头吹画角，此曲哀怨何时终。','',''),('quantangshi-10976','追酬故高蜀州人日见寄','杜甫','quantangshi','','卷11','自蒙蜀州人日作，不意清诗久零落。
今晨散帙眼忽开，迸泪幽吟事如昨。
呜呼壮士多慷慨，合沓高名动寥廊。
叹我凄凄求友篇，感时郁郁匡君略。
锦里春光空烂熳，瑶墀侍臣已冥莫。
潇湘水国傍鼋鼍，鄠杜秋天失雕鹗。
东西南北更谁论，白首扁舟病独存。
遥拱北辰缠寇盗，欲倾东海洗干坤。
边塞西蕃最充斥，衣冠南渡多崩奔。
鼓瑟至今悲帝子，曳裾何处觅王门。
文章曹植波澜阔，服食刘安德业尊。
长笛谁能乱愁思，昭州词翰与招魂。','',''),('quantangshi-10977','苏大侍御访江浦赋八韵记异','杜甫','quantangshi','','卷11','庞公不浪出，苏氏今有之。
再闻诵新作，突过黄初诗。
干坤几反覆，扬马宣同时。
今晨清镜中，胜食斋房芝。
余发喜却变，白间生黑丝。
昨夜舟火灭，湘娥帘外悲。
百灵未敢散，风破寒江迟。','',''),('quantangshi-10978','题衡山县文宣王庙新学堂呈陆宰','杜甫','quantangshi','','卷11','旄头彗紫微，无复俎豆事。
金甲相排荡，青衿一顦顇。
呜呼已十年，儒服弊于地。
征夫不遑息，学者沦素志。
我行洞庭野，歘得文翁肆。
侁侁胄子行，若舞风雩至。
周室宜中兴，孔门未应弃。
是以资雅才，涣然立新意。
衡山虽小邑，首唱恢大义。
因见县尹心，根源旧宫閟。
讲堂非曩构，大屋加涂墍。
下可容百人，墙隅亦深邃。
何必三千徒，始压戎马气。
林木在庭户，密干叠苍翠。
有井朱夏时，辘轳冻阶戺。
耳闻读书声，杀伐灾仿髴。
故国延归望，衰颜减愁思。
南纪改波澜，西河共风味。
采诗倦跋涉，载笔尚可记。
高歌激宇宙，凡百慎失坠。','',''),('quantangshi-10979','入衡州','杜甫','quantangshi','','卷11','兵革自久远，兴衰看帝王。
汉仪甚照耀，胡马何猖狂。
老将一失律，清边生战场。
君臣忍瑕垢，河岳空金汤。
重镇如割据，轻权绝纪纲。
军州体不一，宽猛性所将。
嗟彼苦节士，素于圆凿方。
寡妻从为郡，兀者安堵墙。
凋弊惜邦本，哀矜存事常。
旌麾非其任，府库实过防。
恕己独在此，多忧增内伤。
偏裨限酒肉，卒伍单衣裳。
元恶迷是似，聚谋泄康庄。
竟流帐下血，大降湖南殃。
烈火发中夜，高烟焦上苍。
至今分粟帛，杀气吹沅湘。
福善理颠倒，明征天莽茫。
销魂避飞镝，累足穿豺狼。
隐忍枳棘刺，迁延胝趼疮。
远归儿侍侧，犹乳女在旁。
久客幸脱免，暮年慙激昴。
萧条向水陆，汩没随鱼商。
报主身已老，入朝病见妨。
悠悠委薄俗，郁郁回刚肠。
参错走洲渚，舂容转林篁。
片帆左郴岸，通郭前衡阳。
华表云鸟埤，名园花草香。
旗亭壮邑屋，烽橹蟠城隍。
中有古刺史，盛才冠岩廓。
扶颠待柱石，独坐飞风霜。
昨者间琼树，高谈随羽觞。
无论再缱绻，己是安苍黄。
剧孟七国畏，马卿四赋良。
门阑苏生在，勇锐白起强。
问罪富形势，凯歌悬否臧。
氛埃期必埽，蚊蚋焉能当。
橘井旧地宅，仙山引舟航。
此行厌暑雨，厥土闻清凉。
诸舅剖符近，开缄书札光。
频繁命屡及，磊落字百行。
江总外家养，谢安乘兴长。
下流匪珠玉，择木羞鸾皇。
我师嵇叔夜，世贤张子房。
柴荆寄乐土，鹏路观翱翔。','',''),('quantangshi-10980','舟中苦热遣怀奉呈[阳]中丞通简台省诸公','杜甫','quantangshi','','卷11','愧为湖外客，看此戎马乱。
中夜混黎甿，脱身亦奔窜。
平生方寸心，反掌帐下难。
呜呼杀贤良，不叱白刃散。
吾非丈夫特，没齿埋冰炭。
耻以风病辞，胡然泊湘岸。
入舟虽苦热，垢腻可溉灌。
痛彼道边人，形骸改昏旦。
中丞连帅职，封内权得按。
身当问罪先，县实诸侯半。
士卒既辑睦，启行促精悍。
似闻上游兵，稍逼长沙馆。
邻好彼克修，天机自明断。
南图卷云水，北拱戴霄汉。
美名光史臣，长策何壮观。
驱驰数公子，咸愿同伐叛。
声节衰有余，夫何激衰懦。
偏裨表三上，卤莽同一贯。
始谋谁其间，回首增愤惋。
宗英李端公，守职甚昭焕。
变通迫胁地，谋画焉得算。
王室不肯微，凶徒略无惮。
此流须卒斩，神器资强干。
扣寂豁烦襟，皇天照嗟叹。','',''),('quantangshi-10981','聂耒阳以仆阻水书致酒肉疗饥荒江诗得代怀兴尽本韵至县呈聂令陆路去方田驿四十里舟行一日时属江涨泊于方田','杜甫','quantangshi','','卷11','耒阳驰尺素，见访荒江眇。
义士烈女家，风流吾贤绍。
昨见狄相孙，许公人伦表。
前期翰林后，屈迹县邑小。
知我碍湍涛，半旬获浩溔。
麾下杀元戎，湖边有飞旐。
孤舟增郁郁，僻路殊悄悄。
侧惊猿猱捷，仰羡鹳鹤矫。
礼过宰肥羊，愁当置清醥。
人非西喻蜀，兴在北坑赵。
方行郴岸静，未话长沙扰。
崔师乞已至，澧卒用矜少。
问罪消息真，开颜憩亭沼。','',''),('quantangshi-10982','冬日洛城北谒玄元皇帝庙','杜甫','quantangshi','','卷11','配极玄都閟，凭虚禁御长。
守祧严具礼，掌节镇非常。
碧瓦初寒外，金茎一气旁。
山河扶绣户，日月近雕梁。
仙李盘根大，猗兰奕叶光。
世家遗旧史，道德付今王。
画手看前辈，吴生远擅场。
森罗移地轴，妙绝动宫墙。
五圣联龙衮，千官列雁行。
冕旒俱秀发，旌斾尽飞扬。
翠柏深留景，红棃迥得霜。
风筝吹玉柱，露井冻银牀。
身退卑周室，经传拱汉皇。
谷神如不死，养拙更何乡。','',''),('quantangshi-10983','赠韦左丞丈','杜甫','quantangshi','','卷11','左辖频虚位，今年得旧儒。
相门韦氏在，经术汉臣须。
时议归前烈，天伦恨莫俱。
鸰原荒宿草，凤沼接亨衢。
有客虽安命，衰容岂壮夫。
家人忧几杖，甲子混泥途。
不谓矜余力，还来谒大巫。
岁寒仍顾遇，日暮且踟蹰。
老骥思千里，饥鹰待一呼。
君能微感激，亦足慰榛芜。','',''),('quantangshi-10984','投赠哥舒开府二十韵','杜甫','quantangshi','','卷11','今代麒麟阁，何人第一功。
君王自神武，驾驭必英雄。
开府当朝杰，论兵迈古风。
先锋百胜在，略地两隅空。
青海无传箭，天山早挂弓。
廉颇仍走敌，魏绛已和戎。
每惜河湟弃，新兼节制通。
智谋垂睿想，出入冠诸公。
日月低秦树，干坤绕汉宫。
胡人愁逐北，宛马又从东。
受命边沙远，归来御席同。
轩墀曾宠鹤，畋猎旧非熊。
茅土加名数，山河誓始终。
策行遗战伐，契合动昭融。
勋业青冥上，交亲气概中。
未为珠履客，已见白头翁。
壮节初题柱，生涯独转蓬。
几年春草歇，今日暮途穷。
军事留孙楚，行间识吕蒙。
防身一长劒，将欲倚崆峒。','',''),('quantangshi-10985','上韦左相二十韵','杜甫','quantangshi','','卷11','凤历轩辕纪，龙飞四十春。
八荒开寿域，一气转洪钧。
霖雨思贤佐，丹青忆老臣。
应图求骏马，惊代得麒麟。
沙汰江河浊，调和鼎鼐新。
韦贤初相汉，范叔已归秦。
盛业今如此，传经固绝伦。
豫樟深出地，沧海阔无津。
北斗司喉舌，东方领搢绅。
持衡留藻鉴，听履上星辰。
独步才超古，余波德照邻。
聪明过管辂，尺牍倒陈遵。
岂是池中物，由来席上珍。
庙堂知至理，风俗尽还淳。
才杰俱登用，愚蒙但隐沦。
长卿多病久，子夏索居频。
回首驱流俗，生涯似众人。
巫咸不可问，邹鲁莫容身。
感激时将晚，苍茫兴有神。
为公歌此曲，涕泪在衣巾。','',''),('quantangshi-10986','奉赠太常张卿二十韵','杜甫','quantangshi','','卷11','方丈三韩外，昆仑万国西。
建标天地阔，诣绝古今迷。
气得神仙迥，恩承雨露低。
相门清议众，儒术大名齐。
轩冕罗天阙，琳琅识介圭。
伶官诗必诵，夔乐典犹稽。
健笔凌鹦鹉，銛锋莹䴙鹈。
友于皆挺拔，公望各端倪。
通籍逾青琐，亨衢照紫泥。
灵虬传夕箭，归马散霜蹄。
能事闻重译，嘉谟及远黎。
弼谐方一展，班序更何跻。
适越空颠踬，游梁竟惨凄。
谬知终画虎，微分是醯鸡。
萍泛无休日，桃阴想旧蹊。
吹嘘人所羡，腾跃事仍暌。
碧海真难涉，青云不可梯。
顾深慙锻炼，才小辱提携。
槛束哀猨叫，枝惊夜鹊栖。
几时陪羽猎，应指钓璜溪。','',''),('quantangshi-10987','敬赠郑谏议十韵','杜甫','quantangshi','','卷11','谏官非不达，诗义早知名。
破的由来事，先锋孰敢争。
思飘云物外，律中鬼神惊。
毫发无遗恨，波澜独老成。
野人宁得所，天意薄浮生。
多病休儒服，冥搜信客旌。
筑居仙缥缈，旅食岁峥嵘。
使者求颜阖，诸公厌禰衡。
将期一诺重，歘使寸心倾。
君见途穷哭，宜忧阮步兵。','',''),('quantangshi-10988','奉赠鲜于京兆二十韵','杜甫','quantangshi','','卷11','王国称多土，贤良复几人。
异才应间出，爽气必殊伦。
始见张京兆，宜居汉近臣。
骅骝开道路，雕鹗离风尘。
侯伯知何等，文章实致身。
奋飞超等级，容易失沈沦。
脱略磻溪钓，操持郢匠斤。
云霄今已逼，台衮更谁亲。
凤穴雏皆好，龙门客又新。
义声纷感激，败绩自逡巡。
途远欲何向，天高难重陈。
学诗犹孺子，乡赋念嘉宾。
不得同鼌错，吁嗟后郄诜。
计疎疑翰墨，时过忆松筠。
献纳纡皇眷，中间谒紫宸。
且随诸彦集，方凯薄才伸。
破胆遭前政，阴谋独秉钧。
微生霑忌刻，万事益酸辛。
交合丹青地，恩倾雨露辰。
有儒愁饿死，早晚报平津。','',''),('quantangshi-10989','赠特进汝阳王二十韵','杜甫','quantangshi','','卷11','特进羣公表，天人夙德升。
霜蹄千里骏，风翮九霄鹏。
服礼求毫发，惟忠忘寝兴。
圣情常有眷，朝退若无凭。
仙醴来浮蚁，奇毛或赐鹰。
清关尘不杂，中使日相乘。
晚节嬉游简，平居孝义称。
自多亲棣萼，谁敢问山陵。
学业醇儒富，辞华哲匠能。
笔飞鸾耸立，章罢凤骞腾。
精理通谈笑，忘形向友朋。
寸长堪缱绻，一诺岂骄矜。
已忝归曹植，何知对李膺。
招要恩屡至，崇重力难胜。
披雾初欢夕，高秋爽气澄。
尊罍临极浦，凫雁宿张灯。
花月穷游宴，炎天避郁蒸。
研寒金井水，檐动玉壶冰。
瓢饮唯三径，岩栖在百层。
且持蠡测海，况挹酒如渑。
鸿宝宁全祕，丹梯庶可凌。
淮王门有客，终不愧孙登。','',''),('quantangshi-10990','郑驸马宅宴洞中','杜甫','quantangshi','','卷11','主家阴洞细烟雾，留客夏簟清琅玕。
春酒杯浓琥珀薄，冰浆椀碧玛瑙寒。
误疑茅堂过江麓，已入风磴霾云端。
自是秦楼压郑谷，时闻杂佩声珊珊。','',''),('quantangshi-10991','李监宅','杜甫','quantangshi','','卷11','尚觉王孙贵，豪家意颇浓。
屏开金孔雀，褥隐绣芙蓉。
且食双鱼美，谁看异味重。
门阑多喜色，女壻近乘龙。','',''),('quantangshi-10992','重题郑氏东亭','杜甫','quantangshi','','卷11','华亭入翠微，秋日乱清晖。
崩石欹山树，清涟曳水衣。
紫鳞冲岸跃，苍隼护巢归。
向晚寻征路，残云傍马飞。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-10993','题张氏隐居二首 一','杜甫','quantangshi','','卷11','春山无伴独相求，伐木丁丁山更幽。
涧道余寒历冰雪，石门斜日到林丘。
不贪夜识金银气，远害朝看糜鹿游。
乘兴杳然迷出处，对君疑是泛虚舟。','',''),('quantangshi-10994','题张氏隐居二首 二','杜甫','quantangshi','','卷11','之子时相见，邀人晚兴留。
霁潭鳣发发，春草鹿呦呦。
杜酒偏劳劝，张棃不外求。
前村山路险，归醉每无愁。','',''),('quantangshi-10995','天宝初南曹小司寇舅于我太夫人堂下累土为山一匮盈尺以代彼朽木承诸焚香瓷瓯瓯甚安矣旁植慈竹盖兹数峰嵚岑婵娟宛有尘外数致乃不知兴之所至而作是诗','杜甫','quantangshi','','卷11','一匮功盈尺，三峰意出羣。
望中疑在野，幽处欲生云。
慈竹春阴覆，香炉晓势分。
惟南将献寿，佳气日氛氲。','',''),('quantangshi-10996','龙门','杜甫','quantangshi','','卷11','龙门横野断，驿树出城来。
气色皇居近，金银佛寺开。
往还时屡改，川水日悠哉。
相阅征途上，生涯尽几回。','',''),('quantangshi-10997','奉寄河南韦尹丈人','杜甫','quantangshi','','卷11','有客传河尹，逢人问孔融。
青囊仍隐逸，章甫尚西东。
鼎石分门户，词场继国风。
尊荣瞻地绝，疎放忆途穷。
浊酒寻陶令，丹砂访葛洪。
江湖漂短褐，霜雪满飞蓬。
牢落干坤大，周流道术空。
谬慙知蓟子，真怯笑扬雄。
盘错神明惧，讴歌德义丰。
尸乡余土室，难说祝鸡翁。','',''),('quantangshi-10998','赠李白','杜甫','quantangshi','','卷11','秋来相顾尚飘蓬，未就丹砂愧葛洪。
痛饮狂歌空度日，飞扬跋扈为谁雄。','',''),('quantangshi-10999','与任城许主簿游南池','杜甫','quantangshi','','卷11','秋水通沟洫，城隅进小船。
晚凉看洗马，森木乱鸣蝉。
菱熟经时雨，蒲荒八月天。
晨朝降白露，遥忆旧青氊。','',''),('quantangshi-11000','登兖州城楼','杜甫','quantangshi','','卷11','东郡趋庭日，南楼纵目初。
浮云连海岳，平野入青徐。
孤嶂秦碑在，荒城鲁殿余。
从来多古意，临眺独踌躇。','',''),('quantangshi-11001','刘九法曹郑瑕丘石门宴集','杜甫','quantangshi','','卷11','秋水清无底，萧然静客心。
掾曹乘逸兴，鞍马去相寻。
能吏逢聊璧，华筵直一金。
晚来横吹好，泓下亦龙吟。','',''),('quantangshi-11002','暂如临邑至㟙山湖亭奉怀李员外率尔成兴','杜甫','quantangshi','','卷11','野亭逼湖水，歇马高林间。
鼍吼风奔浪，鱼跳日映山。
暂游阻词伯，却望怀青关。
霭霭生云雾，唯应促驾还。','',''),('quantangshi-11003','对雨书怀走邀许十一簿公','杜甫','quantangshi','','卷11','东岳云峰起，溶溶满太虚。
震雷飜幕燕，骤雨落河鱼。
座对贤人酒，门听长者车。
相邀愧泥泞，骑马到阶除。','',''),('quantangshi-11004','巳上人茅斋','杜甫','quantangshi','','卷11','巳公茅屋下，可以赋新诗。
枕簟入林僻，茶瓜留客迟。
江莲摇白羽，天棘梦青丝空忝许询辈，难酬支遁词。','',''),('quantangshi-11005','房兵曹胡马诗','杜甫','quantangshi','','卷11','胡马大宛名，锋棱瘦骨成。
竹批双耳峻，风入四蹄轻。
所向无空阔，真堪托死生。
骁腾有如此，万里可横行。','',''),('quantangshi-11006','画鹰','杜甫','quantangshi','','卷11','素练风霜起，苍鹰画作殊。
身思狡兔，俱目似愁胡。
绦旋光堪擿，轩楹势可呼。
何当击凡鸟，毛血洒平芜。','',''),('quantangshi-11007','与李十二白同寻范十隐居','杜甫','quantangshi','','卷11','李侯有佳句，往往似阴铿。
余亦东蒙客，怜君如弟兄。
醉眠秋共被，携手日同行。
更想幽期处，还寻北郭生。
入门高兴发，侍立小童清。
落景闻寒杵，屯云对古城。
向来吟橘颂，谁欲讨莼羹。
不愿论簪笏，悠悠沧海情。','',''),('quantangshi-11008','临邑舍弟书至苦雨黄河泛溢堤防之患簿领所忧因寄此诗用宽其意','杜甫','quantangshi','','卷11','二仪积风雨，百谷漏波涛。
闻道洪何坼，遥连沧海高。
职思忧悄悄，郡国诉嗷嗷。
舍弟卑栖邑，防川领簿曹。
尺书前日至，版筑不时操。
难假鼋鼍力，空瞻乌鹊毛。
燕南吹畎亩，济上没蓬蒿。
螺蚌满近郭，蛟螭乘九臯。
徐关深水府，碣石小秋毫。
白屋留孤树，清天矢万艘。
吾衰同泛梗，利涉想蟠桃。
倚赖天涯钓，犹能掣巨鳌。','',''),('quantangshi-11009','过宋员外之问旧庄','杜甫','quantangshi','','卷12','宋公旧池馆，零落守阳阿。
枉道祗从入，吟诗许更过。
淹留问耆老，寂莫向山河。
更识将军树，悲风日暮多。','',''),('quantangshi-11010','夜宴左氏庄','杜甫','quantangshi','','卷12','风林纤月落，衣露净琴张。
暗水流花径，春星带草堂。
检书烧烛短，看劒引杯长。
诗罢闻吴咏，扁舟意不忘。','',''),('quantangshi-11011','送蔡希曾都尉还陇右因寄高三十五书记','杜甫','quantangshi','','卷12','蔡子勇成癖，弯弓西射胡。
健儿宁鬬死，壮士耻为儒。
官是先锋得，材缘挑战须。
身轻一鸟过，枪急万人呼。
云幕随开府，春城赴上都。
马头金狎帢，驼背锦糢糊。
咫尺云山路，归飞青海隅。
上公犹宠锡，突将且前驱。
汉使黄河远，凉州白麦枯。
因君问消息，好在阮元瑜。','',''),('quantangshi-11012','春日忆李白','杜甫','quantangshi','','卷12','白也诗无敌，飘然思不羣。
清新庾开府，俊逸鲍参军。
渭北春天树，江东日暮云。
何时一尊酒，重与细论文。','',''),('quantangshi-11013','赠陈二补阙','杜甫','quantangshi','','卷12','世儒多汩没，夫子独声名。
献纳开东观，君王问长卿。
皂雕寒始急，天马老能行。
自到青冥里，休看白发生。','',''),('quantangshi-11014','寄高三十五书记','杜甫','quantangshi','','卷12','叹惜高生老，新诗日又多。
美名人不及，佳句法如何。
主将收才子，崆峒足凯歌。
闻君已朱绂，且得慰蹉跎。','',''),('quantangshi-11015','送裴二虬作尉永嘉','杜甫','quantangshi','','卷12','孤屿亭何处，天涯水气中。
故人官就此，绝境兴谁同。
隐吏逢梅福，游山忆谢公。
扁舟吾已就，把钓待秋风。','',''),('quantangshi-11016','城西陂泛舟','杜甫','quantangshi','','卷12','青蛾皓齿在楼船，横笛短箫悲远天。
春风自信牙樯动，迟日徐看锦缆牵。
鱼吹细浪摇歌扇，燕蹴飞花落舞筵。
不有小舟能蘯桨，百壶那送酒如泉。','',''),('quantangshi-11017','赠田九判官','杜甫','quantangshi','','卷12','崆峒使节上青霄，河陇降王款圣朝。
宛马总肥春苜蓿，将军只数汉嫖姚。
陈留阮瑀谁争长，京兆田郎早见招。
麾下赖君才竝入，独能无意向渔樵。','',''),('quantangshi-11018','赠献纳使起居田舍人','杜甫','quantangshi','','卷12','献纳司存雨露边，地分清切任才贤。
舍人退食收封事，宫女开函近御筵。
晓漏追飞青琐闼，晴窗点检白云篇。
扬雄更有河东赋，唯待吹嘘送上天。','',''),('quantangshi-11019','送韦书记赴安西','杜甫','quantangshi','','卷12','夫子歘通贵，云泥相望悬。
白头无藉在，朱绂有哀怜。
书记赴三捷，公车留二年。
欲浮江海去，此别意苍然。','',''),('quantangshi-11020','陪郑广文游何将军山林十首 一','杜甫','quantangshi','','卷12','不识南塘路，今知第五桥。
名园依绿水，野竹上青霄。
谷口旧相得，濠梁同见招。
平生为幽兴，未惜马蹄遥。','',''),('quantangshi-11021','陪郑广文游何将军山林十首 二','杜甫','quantangshi','','卷12','百顷风潭上，千重夏木清。
卑枝低结子，接叶暗巢莺。
鲜鲫银丝脍，香芹碧涧羹。
飜疑柁楼底，晚饭越中行。','',''),('quantangshi-11022','陪郑广文游何将军山林十首 三','杜甫','quantangshi','','卷12','万里戎王子，何年别月支。
异花开绝域，滋蔓匝清池。
汉使徒空到，神农竟不知。
露飜兼雨打，开坼日离披。','',''),('quantangshi-11023','陪郑广文游何将军山林十首 四','杜甫','quantangshi','','卷12','旁舍连高竹，疎篱带晚花。
碾涡深没马，藤蔓曲藏蛇。
词赋工无益，山林迹未赊。
尽捻书籍卖，来问尔东家。','',''),('quantangshi-11024','陪郑广文游何将军山林十首 五','杜甫','quantangshi','','卷12','剩水沧江破，残山碣石开。
绿垂风折笋，红绽雨肥梅。
银甲弹筝用，金鱼换酒来。
兴移无洒埽，随意坐莓苔。','',''),('quantangshi-11025','陪郑广文游何将军山林十首 六','杜甫','quantangshi','','卷12','风磴吹阴雪，云门吼瀑泉。
酒醒思卧簟，衣冷欲装绵。
野老来看客，河鱼不取钱。
只疑淳朴处，自有一山川。','',''),('quantangshi-11026','陪郑广文游何将军山林十首 七','杜甫','quantangshi','','卷12','棘树寒云色，茵蔯春藕香。
脆添生菜美，阴益食单凉。
野鹤清晨出，山精白日藏。
石林蟠水府，百里独苍苍。','',''),('quantangshi-11027','陪郑广文游何将军山林十首 八','杜甫','quantangshi','','卷12','忆过杨柳渚，走马定昆池。
醉把青荷叶，狂遗白接䍦。
刺船思郢客，解水乞吴儿。
坐对秦山晚，江湖兴颇随。','',''),('quantangshi-11028','陪郑广文游何将军山林十首 九','杜甫','quantangshi','','卷12','牀上书连屋，阶前树拂云。
将军不好武，稚子总能文。
醒酒微风入，听诗静夜分。
絺衣挂萝薜，凉月白纷纷。','',''),('quantangshi-11029','陪郑广文游何将军山林十首 十','杜甫','quantangshi','','卷12','幽意忽不惬，归期无奈何。
出门流水注，回首白云多。
自笑灯前舞，谁怜醉后歌。
祗应与朋好，风雨亦来过。','',''),('quantangshi-11030','重过何氏五首 一','杜甫','quantangshi','','卷12','问讯东桥竹，将军有报书。
倒衣还命驾，高枕乃吾庐。
花妥莺捎蝶，溪喧獭趁鱼。
重来休沐地，真作野人居。','',''),('quantangshi-11031','重过何氏五首 二','杜甫','quantangshi','','卷12','山雨尊仍在，沙沈榻未移。
犬迎曾宿客，鸦护落巢儿。
云薄翠微寺，天清黄子陂。
向来幽兴极，步屣过东篱。','',''),('quantangshi-11032','重过何氏五首 三','杜甫','quantangshi','','卷12','落日平台上，春风啜茗时。
石阑斜点笔，桐叶坐题诗。
翡翠鸣衣桁，蜻蜓立钓丝。
自今幽兴熟，来往亦无期。','',''),('quantangshi-11033','重过何氏五首 四','杜甫','quantangshi','','卷12','颇怪朝参嬾，应耽野趣长。
雨抛金锁甲，苔卧绿沈枪。
手自移蒲柳，家才足稻粱。
看君用幽意，白日到羲皇。','',''),('quantangshi-11034','重过何氏五首 五','杜甫','quantangshi','','卷12','到此应常宿，相留可判年。
蹉跎暮容色，怅望好林泉。
何路霑微禄，归山买薄田。
斯游恐不遂，把酒意茫然。','',''),('quantangshi-11035','冬日有怀李白','杜甫','quantangshi','','卷12','寂寞书斋里，终朝独尔思。
更寻嘉树传，不忘角弓诗。
短褐风霜入，还丹日月迟。
未因乘兴去，空有鹿门期。','',''),('quantangshi-11036','杜位宅守岁','杜甫','quantangshi','','卷12','守岁阿戎家，椒盘已颂花。
盍簪喧枥马，列炬散林鸦。
四十明朝过，飞腾暮景斜。
谁能更拘束，烂醉是生涯。','',''),('quantangshi-11037','与鄠县源大少府宴渼陂','杜甫','quantangshi','','卷12','应为四陂好，金钱罄一餐。
饭抄云子白，瓜嚼水精寒。
无计回船下，空愁避酒难。
主人情烂熳，持答翠琅玕。','',''),('quantangshi-11038','崔驸马山亭宴集','杜甫','quantangshi','','卷12','萧史幽栖地，林间蹋凤毛。
洑流何处入，乱石闭门高。
客醉挥金椀，诗成得绣袍。
清秋多宴会，终日困香醪。','',''),('quantangshi-11039','九日杨奉化会白水崔明府','杜甫','quantangshi','','卷12','今日潘怀县，同时陆浚仪。
坐开桑落酒，来把菊花枝。
天宇清霜净，公堂宿雾披。
晚酣留客舞，凫舄共差池。','',''),('quantangshi-11040','赠翰林张四学士','杜甫','quantangshi','','卷12','翰林逼华盖，鲸力破沧溟。
天上张公子，宫中汉客星赋诗拾翠殿，佐酒望云亭。
紫诰仍兼绾，黄麻似六经。
内分金带赤，恩与荔枝青。
无复随高凤，空余泣聚萤。
此生任春草，垂老独漂萍。
傥忆山阳会，悲歌在一听。','',''),('quantangshi-11041','送张二十参军赴蜀州因呈杨五侍御','杜甫','quantangshi','','卷12','好去张公子，通家别恨添。
两行秦树直，万点蜀山尖。
御史新骢马，参军旧紫髯。
皇华吾善处，于汝定无嫌。','',''),('quantangshi-11042','陪诸贵公子丈八沟携妓纳凉晚际遇雨二首 一','杜甫','quantangshi','','卷12','落日放船好，轻风生浪迟。
竹深留客处，荷净纳凉时。
公子调冰水，佳人雪藕丝。
片云头上黑，应是雨催诗。','',''),('quantangshi-11043','陪诸贵公子丈八沟携妓纳凉晚际遇雨二首 二','杜甫','quantangshi','','卷12','雨来霑席上，风急打船头。
越女红帬湿，燕姬翠黛愁。
缆侵堤柳系，幔宛浪花浮。
归路飜萧飒，陂塘五月秋。','',''),('quantangshi-11044','白水明府舅宅喜雨','杜甫','quantangshi','','卷12','吾舅政如此，古人谁复过。
碧山晴又湿，白水雨偏多。
精祷既不昧，欢娱将谓何。
汤年旱颇甚，今日醉弦歌。','',''),('quantangshi-11045','陪李金吾花下饮','杜甫','quantangshi','','卷12','胜地初相引，余行得自娱。
见轻吹鸟毳，随意数花须。
细草称偏坐，香醪嬾再酤。
醉归应犯夜，可怕李金吾。','',''),('quantangshi-11046','赠高式颜','杜甫','quantangshi','','卷12','昔别是何处，相逢皆老夫。
故人还寂寞，削迹共艰虞。
自失论文友，空知卖酒垆。
平生飞动意，见尔不能无。','',''),('quantangshi-11047','赠比部萧郎中十兄','杜甫','quantangshi','','卷12','有美生人杰，由来积德门。
汉朝丞相系，梁日帝王孙。
蕴藉为郎久，魁梧秉哲尊。
词华倾后辈，风雅蔼孤骞。
宅相荣姻戚，儿童惠讨论。
见知真自幼，谋拙丑诸昆。
漂荡云天阔，沈埋日月奔。
致君时已晚，怀古意空存。
中散山阳锻，愚公野谷村。
宁纡长者辙，归老任干坤。','',''),('quantangshi-11048','九日曲江','杜甫','quantangshi','','卷12','缀席茱萸好，浮舟菡萏衰。
季秋时欲半，九日意兼悲。
江水清源曲，荆门此路疑。
晚来高兴尽，摇荡菊花期。','',''),('quantangshi-11049','承沈八丈东美除膳部员外阻雨未遂驰贺奉寄此诗','杜甫','quantangshi','','卷12','今日西京掾，多除内省郎。
通家惟沈氏，谒帝似冯唐。
诗律羣公问，儒门旧史长。
清秋便寓直，列宿顿辉光。
未暇申宴慰，含情空激扬。
司存何所比，膳部默凄伤。
贫贱人事略，经过霖潦妨。
礼同诸父长，恩岂布衣忘。
天路牵骐骥，云台引栋梁。
徒怀贡公喜，飒飒鬓毛苍。','',''),('quantangshi-11050','奉留赠集贤院崔于二学士','杜甫','quantangshi','','卷12','昭代将垂白，途穷乃叫阍。
气冲星象表，词感帝王尊。
天老书题目，春宫验讨论。
倚风遗鶂路，随水到龙门。
竟与蛟螭杂，空闻燕雀喧。
青冥犹契阔，陵厉不飞飜。
儒术诚难起，家声庶已存。
故山多药物，胜概忆桃源。
欲整还乡斾，长怀禁掖垣。
谬称三赋在，难述二公恩。','',''),('quantangshi-11051','故武卫将军挽歌三首 一','杜甫','quantangshi','','卷12','严警当寒夜，前军落大星。
壮夫思感决，哀诏惜精灵。
王者今无战，书生已勒铭。
封侯意疎阔，编简为谁青。','',''),('quantangshi-11052','故武卫将军挽歌三首 二','杜甫','quantangshi','','卷12','舞劒过人绝，鸣弓射兽能。
銛锋行惬顺，猛噬失蹻腾。
赤羽千夫膳，黄河十月冰。
横行沙漠外，神速至今称。','',''),('quantangshi-11053','故武卫将军挽歌三首 三','杜甫','quantangshi','','卷12','哀挽青门去，新阡绛水遥。
路人纷雨泣，天意飒风飘。
部曲精仍锐，匈奴气不骄。
无由覩雄略，大树日萧萧。','',''),('quantangshi-11054','官定后戏赠','杜甫','quantangshi','','卷12','不作河西尉，凄凉为折腰。
老夫怕趋走，率府且逍遥。
耽酒须微禄，狂歌托圣朝。
故山归兴尽，回首向风飙。','',''),('quantangshi-11055','九日蓝田崔氏庄','杜甫','quantangshi','','卷12','老去悲秋强自宽，兴来今日尽君欢。
羞将短发还吹帽，笑倩旁人为正冠。
蓝水远从千涧落，玉山高并两峰寒。
明年此会知谁健，醉把茱萸子细看。','',''),('quantangshi-11056','崔氏东山草堂','杜甫','quantangshi','','卷12','爱汝玉山草堂静，高秋爽气相鲜新。
有时自发钟磬响，落日更见渔樵人。
盘剥白鸦谷口栗，饭煮青泥坊底芹。
何为西庄王给事，柴门空闭鏁松筠。','',''),('quantangshi-11057','对雪','杜甫','quantangshi','','卷12','战哭多新鬼，愁吟独老翁。
乱云低薄暮，急雪舞回风。
瓢弃尊无绿，炉存火似红。
数州消息断，愁坐正书空。','',''),('quantangshi-11058','月夜','杜甫','quantangshi','','卷12','今夜鄜州月，闺中只独看。
遥怜小儿女，未解忆长安。
香雾云鬟湿，清辉玉臂寒。
何时倚虚幌，双照泪痕干。','',''),('quantangshi-11059','遣兴','杜甫','quantangshi','','卷12','骥子好男儿，前年学语时。
问知人客姓，诵得老夫诗。
世乱怜渠小，家贫仰母慈。
鹿门携不遂，雁足系难期。
天地军麾满，山河战角悲。
傥归免相失，见日敢辞迟。','',''),('quantangshi-11060','元日寄韦氏妹','杜甫','quantangshi','','卷12','近闻韦氏妹，迎在汉钟离。
郎伯殊方镇，京华旧国移。
春城回北斗，郢树发南枝。
不见朝正使，啼痕满面垂。','',''),('quantangshi-11061','春望','杜甫','quantangshi','','卷12','国破山河在，城春草木深。
感时花溅泪，恨别鸟惊心。
烽火连三月，家书抵万金。
白头搔更短，浑欲不胜簪。','',''),('quantangshi-11062','忆幼子','杜甫','quantangshi','','卷12','骥子春犹隔，莺歌暖正繁。
别离惊节换，聪慧与谁论。
涧水空山道，柴门老树村。
忆渠愁只睡，炙背俯晴轩。','',''),('quantangshi-11063','一百五日夜对月','杜甫','quantangshi','','卷12','无家对寒食，有泪如金波。
斫却月中桂，清光应更多。
仳离放红蘂，想像嚬青蛾。
牛女漫愁思，秋期犹渡河。','',''),('quantangshi-11064','喜达行在所三首 一','杜甫','quantangshi','','卷12','西忆岐阳信，无人遂却回。
眼穿当落日，心死着寒灰。
雾树行相引，莲峰望忽开。
所亲惊老瘦，辛苦贼中来。','',''),('quantangshi-11065','喜达行在所三首 二','杜甫','quantangshi','','卷12','愁思胡笳夕，凄凉汉苑春。
生还今日事，间道暂时人。
司隶章初覩，南阳气已新。
喜心飜倒极，呜咽泪霑巾。','',''),('quantangshi-11066','喜达行在所三首 三','杜甫','quantangshi','','卷12','死去凭谁报，归来始自怜。
犹瞻太白雪，喜遇武功天。
影静千官里，心苏七校前。
今朝汉社稷，新数中兴年。','',''),('quantangshi-11067','得家书','杜甫','quantangshi','','卷12','去凭游客寄，来为附家书。
今日知消息，他乡且旧居。
熊儿幸无恙，骥子最怜渠。
临老羁孤极，伤时会合疎。
二毛趋帐殿，一命侍鸾舆。
北阙妖氛满，西郊白露初。
凉风新过雁，秋雨欲生鱼。
农事空山里，眷言终荷锄。','',''),('quantangshi-11068','奉赠严八阁老','杜甫','quantangshi','','卷12','扈圣登黄阁，明公独妙年。
蛟龙得云雨，雕鹗在秋天。
客礼容疎放，官曹可接联。
新诗句句好，应任老夫传。','',''),('quantangshi-11069','奉送郭中丞兼太仆卿充陇右节度使三十韵','杜甫','quantangshi','','卷12','诏发西山将，秋屯陇右兵。
凄凉余部曲，燀赫旧家声。
雕鹗乘时去，骅骝顾主鸣。
艰难须上策，容易即前程。
斜日当轩盖，高风卷斾旌。
松悲天水冷，沙乱雪山清。
和虏犹怀惠，防边不敢惊。
古来于异域，镇静示专征。
燕蓟奔封豕，周秦触骇鲸。
中原何惨黩，余孽尚纵横。
箭入昭阳殿，笳吟细柳营。
内人红袖泣，王子白衣行。
宸极祆星动，园陵杀气平。
空余金椀出，无复繐帷轻。
毁庙天飞雨，焚宫火彻明。
罘罳朝共落，棆桷夜同倾。
三月师逾整，羣胡势就烹。
疮痍亲接战，勇决冠垂成。
妙誉期元宰，殊恩且列卿。
几时回节钺，戮力埽欃枪。
圭窦三千士，云梯七十城。
耻非齐说客，祗似鲁诸生。
通籍微班忝，周行独坐荣。
随肩趋漏刻，短发寄簪缨。
径欲依刘表，还疑厌禰衡。
渐衰那此别，忍泪独含情。
废邑狐狸语，空邨虎豹争。
人频坠涂炭，公岂忘精诚。
元帅调新律，前军压旧京。
安边仍扈从，莫作后功名。','',''),('quantangshi-11070','送杨六判官使西蕃','杜甫','quantangshi','','卷12','送远秋风落，西征海气寒。
帝京氛祲满，人世别离难。
绝域遥怀怒，和亲愿结欢。
敕书怜赞普，兵甲望长安。
宣命前程急，惟良待士宽。
子云清自守，今日起为官。
垂泪方投笔，伤时即据鞍。
儒衣山鸟怪，汉节野童看。
边酒排金盏，夷歌捧玉盘。
草轻蕃马健，雪重拂庐干。
慎尔参筹画，从兹正羽翰。
归来权可取，九万一朝抟。','',''),('quantangshi-11071','月','杜甫','quantangshi','','卷12','天上秋期近，人间月影清。
入河蟾不没，捣药兔长生。
只益丹心苦，能添白发明。
干戈知满地，休照国西营。','',''),('quantangshi-11072','留别贾严二阁老两院补阙','杜甫','quantangshi','','卷12','田园须蹔往，戎马惜离羣。
去远留诗别，愁多任酒醺。
一秋常苦雨，今日始无云。
山路时吹角，那堪处处闻。','',''),('quantangshi-11073','晚行口号','杜甫','quantangshi','','卷12','三川不可到，归路晚山稠。
落雁浮寒水，饥乌集戍楼。
市朝今日异，丧乱几时休。
远愧梁江总，还家尚黑头。','',''),('quantangshi-11074','独酌成诗','杜甫','quantangshi','','卷12','灯花何太喜，酒绿正相亲。
醉里从为客，诗成觉有神。
兵戈犹在眼，儒术岂谋身。
共被微官缚，低头愧野人。','',''),('quantangshi-11075','行次昭陵','杜甫','quantangshi','','卷12','旧俗疲庸主，羣雄问独夫。
谶归龙凤质，威定虎狼都。
天属尊尧典，神功协禹谟。
风云随绝足，日月继高衢。
文物多师古，朝廷半老儒。
直词宁戮辱，贤路不崎岖。
往者灾犹降，苍生喘未苏。
指麾安率土，荡涤抚洪炉。
壮士悲陵邑，幽人拜鼎湖。
玉衣晨自举，铁马汗常趋。
松柏瞻虚殿，尘沙立暝途。
寂寥开国日，流恨满山隅。','',''),('quantangshi-11076','重经昭陵','杜甫','quantangshi','','卷12','草昧英雄起，讴歌历数归。
风尘三尺劒，社稷一戎衣。
翼亮贞文德，丕承戢武威。
圣图天广大，宗祀日光辉。
陵寝盘空曲，熊罴守翠微。
再窥松柏路，还见五云飞。','',''),('quantangshi-11077','喜闻官军已临贼境二十韵','杜甫','quantangshi','','卷12','胡虏潜京县，官军拥贼壕。
鼎鱼犹假息，穴蚁欲何逃。
帐殿罗玄冕，辕门照白袍。
秦山当警跸，汉苑入旌旄。
路失羊肠险，云横雉尾高。
五原空壁垒，八水散风涛。
今日看天意，游魂贷尔曹。
乞降那更得，尚诈莫徒劳。
元帅归龙种，司空握豹韬。
前军苏武节，左将吕虔刀。
兵气回飞鸟，威声没巨鳌。
戈鋋开雪色，弓矢尚秋毫。
天步艰方尽，时和运更遭。
谁云遗毒螫，已是沃腥臊。
睿想丹墀近，神行羽卫牢。
花门腾绝漠，拓羯渡临洮。
此辈感恩至，羸俘何足操。
锋先衣染血，骑突劒吹毛。
喜觉都城动，悲怜子女号。
家家卖钗钏，只待献春醪。','',''),('quantangshi-11078','收京三首 一','杜甫','quantangshi','','卷12','仙仗离丹极，妖星照玉除。
须为下殿走，不可好楼居。
暂屈汾阳驾，聊飞燕将书。
依然七庙略，更与万方初。','',''),('quantangshi-11079','收京三首 二','杜甫','quantangshi','','卷12','生意甘衰白，天涯正寂寥。
忽闻哀痛诏，又下圣明朝。
羽翼怀商老，文思忆帝尧。
叨逢罪己日，霑洒望青霄。','',''),('quantangshi-11080','收京三首 三','杜甫','quantangshi','','卷12','汗马收宫阙，春城铲贼壕。
赏应歌杕杜，归及荐樱桃。
杂虏横戈数，功臣甲第高。
万方频送喜，无乃圣躬劳。','',''),('quantangshi-11081','腊日','杜甫','quantangshi','','卷12','腊日常年暖尚遥，今年腊日冻全消。
侵陵雪色还萱草，漏泄春光有柳条。
纵酒欲谋良夜醉，还家初散紫宸朝。
口脂面药随恩泽，翠管银罂下九霄。','',''),('quantangshi-11082','紫宸殿退朝口号','杜甫','quantangshi','','卷12','户外昭容紫袖垂，双瞻御座引朝仪。
香飘合殿春风转，花覆千官淑景移。
昼漏希闻高阁报，天颜有喜近臣知。
宫中每出归东省，会送夔龙集凤池。','',''),('quantangshi-11083','曲江二首 一','杜甫','quantangshi','','卷12','一片花飞减却春，风飘万点正愁人。
且看欲尽花经眼，莫厌伤多酒入唇。
江上小堂巢翡翠，花边高冢卧麒麟。
细推物理须行乐，何用浮名绊此身。','',''),('quantangshi-11084','曲江二首 二','杜甫','quantangshi','','卷12','朝回日日典春衣，每日江头尽醉归。
酒债寻常行处有，人生七十古来稀。
穿花蛱蝶深深见，点水蜻蜓款款飞。
传语风光共流转，暂时相赏莫相违。','',''),('quantangshi-11085','曲江对酒','杜甫','quantangshi','','卷12','苑外江头坐不归，水精春殿转霏微。
桃花细逐杨花落，黄鸟时兼白鸟飞。
纵饮久判人共弃，嬾朝真与世相违。
吏情更觉沧洲远，老大悲伤未拂衣。','',''),('quantangshi-11086','曲江对雨','杜甫','quantangshi','','卷12','城上春云覆苑墙，江亭晚色静年芳。
林花着雨燕脂落，水荇牵风翠带长。
龙武新军深驻辇，芙蓉别殿谩焚香。
何时诏此金钱会，暂醉佳人锦瑟旁。','',''),('quantangshi-11087','奉和贾至舍人早朝大明宫','杜甫','quantangshi','','卷12','五夜漏声催晓箭，九重春色醉仙桃。
旌旗日暖龙蛇动，宫殿风微燕雀高。
朝罢香烟携满袖，诗成珠玉在挥毫。
欲知世掌丝纶美，池上于今有凤毛。','',''),('quantangshi-11088','宣政殿退朝晚出左掖','杜甫','quantangshi','','卷12','天门日射黄金牓，春殿晴曛赤羽旗。
宫草微微承委佩，炉烟细细驻游丝。
云近蓬莱常好色，雪残鳷鹊亦多时。
侍臣缓步归青琐，退食从容出每迟。','',''),('quantangshi-11089','题省中院壁','杜甫','quantangshi','','卷12','掖垣竹埤梧十寻，洞门对溜常阴阴。
落花游丝白日静，鸣鸠乳燕青春深。
腐儒衰晚谬通籍，退食迟回违寸心。
衮职曾无一字补，许身愧比双南金。','',''),('quantangshi-11090','春宿左省','杜甫','quantangshi','','卷12','花隐掖垣暮，啾啾栖鸟过。
星临万户动，月傍九霄多。
不寝听金钥，因风想玉珂。
明朝有封事，数问夜如何。','',''),('quantangshi-11091','送翰林张司马南海勒碑','杜甫','quantangshi','','卷12','冠冕通南极，文章落上台。
诏从三殿去，碑到百蛮开。
野馆浓花发，春帆细雨来。
不知沧海上，天遣几时回。','',''),('quantangshi-11092','晚出左掖','杜甫','quantangshi','','卷12','昼刻传呼浅，春旗簇仗齐。
退朝花底散，归院柳边迷。
楼雪融城湿，宫云去殿低。
避人焚谏草，骑马欲鸡栖。','',''),('quantangshi-11093','曲江陪郑八丈南史饮','杜甫','quantangshi','','卷12','雀啄江头黄柳花，䴔䴖鸂鶒满晴沙。
自知白发非春事，且尽芳尊恋物华。
近侍即今难浪迹，此身那得更无家。
丈人文力犹强健，岂傍青门学种瓜。','',''),('quantangshi-11094','送贾阁老出汝州','杜甫','quantangshi','','卷12','西掖梧桐树，空留一院阴。
艰难归故里，去住损春心。
宫殿青门隔，云山紫逻深。
人生五马贵，莫受二毛侵。','',''),('quantangshi-11095','郑驸马池台喜遇郑广文同饮','杜甫','quantangshi','','卷12','不谓生戎马，何知共酒杯。
然脐郿坞败，握节汉臣回。
白发千茎雪，丹心一寸灰。
别离经死地，披写忽登台。
重对秦箫发，俱过阮宅来。
留连春夜舞，泪落强裴回。','',''),('quantangshi-11096','送郑十八虔贬台州司户伤其临老陷贼之故阙为面别情见于诗','杜甫','quantangshi','','卷12','郑公樗散鬓成丝，酒后常称老画师。
万里伤心严谴日，百年垂死中兴时。
苍惶已就长途往，邂逅无端出饯迟。
便与先生应永诀，九重泉路尽交期。','',''),('quantangshi-11097','题郑十八着作虔','杜甫','quantangshi','','卷12','台州地阔海冥冥，云水长和岛屿青。
乱后故人双别泪，春深逐客一浮萍。
酒酣嬾舞谁相拽，诗罢能吟不复听。
第五桥东流恨水，皇陂岸北结愁亭。
贾生对鵩伤王傅，苏武看羊陷贼庭。
可念此翁怀直道，也霑新国用轻刑。
禰衡实恐遭江夏，方朔虚传是岁星。
穷巷悄然车马绝，案头干死读书萤。','',''),('quantangshi-11098','端午日赐衣','杜甫','quantangshi','','卷12','宫衣亦有名，端午被恩荣。
细葛含风輭，香罗叠雪轻。
自天题处湿，当暑着来清。
意内称长短，终身荷圣情。','',''),('quantangshi-11099','赠毕四','杜甫','quantangshi','','卷12','才大今诗伯，家贫苦宦卑。
饥寒奴仆贱，颜状老翁为。
同调嗟谁惜，论文笑自知。
流传江鲍体，相顾免无儿。','',''),('quantangshi-11100','酬孟云卿','杜甫','quantangshi','','卷12','乐极伤头白，更长爱烛红。
相逢难衮衮，告别莫怱怱。
但恐天河落，宁辞酒盏空。
明朝牵世务，挥泪各西东。','',''),('quantangshi-11101','奉赠王中允','杜甫','quantangshi','','卷12','中允声名久，如今契阔深。
共传收庾信，不比得陈琳一病缘明主，三年独此心。
穷愁应有作，试诵白头吟。','',''),('quantangshi-11102','奉陪郑驸马韦曲二首 一','杜甫','quantangshi','','卷12','韦曲花无赖，家家恼杀人。
绿尊虽尽日，白发好禁春。
石角钩衣破，藤枝刺眼新。
何时占业竹，头戴小乌巾。','',''),('quantangshi-11103','奉陪郑驸马韦曲二首 二','杜甫','quantangshi','','卷12','野寺垂杨里，春畦乱水间。
美花多映竹，好鸟不归山。
城郭终何事，风尘岂驻颜。
谁能共公子，薄暮欲俱还。','',''),('quantangshi-11104','奉答岑参补阙见赠','杜甫','quantangshi','','卷12','窈窕清禁闼，罢朝归不同。
君随丞相后，我往日华东。
冉冉柳枝碧，娟娟花蘂红。
故人得佳句，独赠白头翁。','',''),('quantangshi-11105','送许八拾遗归江宁觐省甫昔时尝客游此县于许生处乞瓦棺寺维摩图样志诸篇末','杜甫','quantangshi','','卷12','诏许辞中禁，慈颜赴北堂。
圣朝新孝理，祖席倍辉光。
内帛擎偏重，宫衣着更香。
淮阴清夜驿，京口渡江航。
春隔鸡人昼，秋期燕子凉。
赐书夸父老，寿酒乐城隍。
看画曾饥渴，追踪恨淼茫。
虎头金粟影，神妙独难忘。','',''),('quantangshi-11106','因许八奉寄江宁旻上人','杜甫','quantangshi','','卷12','不见旻公三十年，对书寄与泪潺湲。
旧来好事今能否，老去新诗谁与传。
棊局动随寻涧竹，袈裟忆上泛湖船。
闻君话我为官在，头白昏昏只醉眠。','',''),('quantangshi-11107','至德二载甫自京金光门出问道归凤翔干元初从左拾遗移华州掾与亲故别因出此门有悲往事','杜甫','quantangshi','','卷12','此道昔归顺，西郊胡正繁。
至今残破胆，应有未招魂。
近得归京邑，移官岂至尊。
无才日衰老，驻马望千门。','',''),('quantangshi-11108','寄高三十五詹事','杜甫','quantangshi','','卷12','安稳高詹事，兵戈久索居。
时来如宦达，岁晚莫情疎。
天上多鸿雁，池中足鲤鱼。
相看过半百，不寄一行书。','',''),('quantangshi-11109','路逢襄阳杨少府入城戏呈杨员外绾','杜甫','quantangshi','','卷12','寄语杨员外，山寒少茯苓。
归来稍喧暖，当为斸青冥。
飜动神仙窟，封题鸟兽形。
兼将老藤杖，扶汝醉初醒。','',''),('quantangshi-11110','题郑县亭子','杜甫','quantangshi','','卷12','郑县亭子涧之滨，户牖凭高发兴新。
云断岳莲临大路，天晴宫柳暗长春。
巢边野雀羣欺燕，花底山蜂远趁人。
更欲题诗满青竹，晚来幽独恐伤神。','',''),('quantangshi-11111','早秋苦热堆案相仍','杜甫','quantangshi','','卷12','七月六日苦炎热，对食暂餐还不能。
每愁夜中自足蝎，况乃秋后转多蝇。
束带发狂欲大叫，簿书何急来相仍。
南望青松架短壑，安得赤脚蹋层冰。','',''),('quantangshi-11112','望岳','杜甫','quantangshi','','卷12','西岳崚嶒竦处尊，诸峰罗立如儿孙。
安得仙人九节杖，拄到玉女洗头盆。
车箱入谷无归路，箭栝通天有一门。
稍待西风凉冷后，高寻白帝问真源。','',''),('quantangshi-11113','至日遣兴奉寄北省旧阁老两院故人二首 一','杜甫','quantangshi','','卷12','去岁兹辰捧御牀，五更三点入鵷行。
欲知趋走伤心地，正想氛氲满眼香。
无路从容陪语笑，有时颠倒着衣裳。
何人错忆穷愁日，愁日愁随一线长。','',''),('quantangshi-11114','至日遣兴奉寄北省旧阁老两院故人二首 二','杜甫','quantangshi','','卷12','忆昨逍遥供奉班，去年今日侍龙颜。
麒麟不动炉烟上，孔雀徐开扇影还。
玉几由来天北极，朱衣只在殿中间。
孤城此日堪肠断，愁对寒云雪满山。','',''),('quantangshi-11115','得弟消息二首 一','杜甫','quantangshi','','卷12','近有平阴信，遥怜舍弟存。
侧身千里道，寄食一家村。
烽举新酣战，啼垂旧血痕。
不知临老日，招得几人魂。','',''),('quantangshi-11116','得弟消息二首 二','杜甫','quantangshi','','卷12','汝懦归无计，吾衰往未期。
浪传乌鹊喜，深负鹡鸽诗。
生理何颜面，忧端且岁时。
两京三十口，虽在命如丝。','',''),('quantangshi-11117','忆弟二首 一','杜甫','quantangshi','','卷12','丧乱闻吾弟，饥寒傍济州。
人稀吾不到，兵在见何由。
忆昨狂催走，无时病去忧。
即今千种恨，惟共水东流。','',''),('quantangshi-11118','忆弟二首 二','杜甫','quantangshi','','卷12','且喜河南定，不问邺城围。
百战今谁在，三年望汝归。
故园花自发，春日鸟还飞。
断绝人烟久，东西消息稀。','',''),('quantangshi-11119','得舍弟消息','杜甫','quantangshi','','卷12','乱后谁归得，他乡胜故乡。
直为心厄苦，久念与存亡。
汝书犹在壁，汝妾已辞房。
旧犬知愁恨，垂头傍我牀。','',''),('quantangshi-11120','秦州杂诗二十首 一','杜甫','quantangshi','','卷12','满目悲生事，因人作远游。
迟回度陇怯，浩荡及关愁。
水落鱼龙夜，山空鸟鼠秋。
西征问烽火，心折此淹留。','',''),('quantangshi-11121','秦州杂诗二十首 二','杜甫','quantangshi','','卷12','秦州山北寺，胜迹隗嚣宫。
苔藓山门古，丹青野殿空。
月明垂叶露，云逐渡溪风。
清渭无情极，愁时独向东。','',''),('quantangshi-11122','秦州杂诗二十首 三','杜甫','quantangshi','','卷12','州图领同谷，驿道出流沙。
降虏兼千帐，居人有万家。
马骄珠汗落，胡舞白蹄斜。
年少临洮子，西来亦自夸。','',''),('quantangshi-11123','秦州杂诗二十首 四','杜甫','quantangshi','','卷12','鼓角缘边郡，川原欲夜时。
秋听殷地发，风散入云悲。
抱叶寒蝉静，归来独鸟迟。
万方声一概，吾道竟何之。','',''),('quantangshi-11124','秦州杂诗二十首 五','杜甫','quantangshi','','卷12','南使宜天马，由来万匹强。
浮云连阵没，秋草徧山长。
闻说真龙种，仍残老驌驦。
哀鸣思战鬬，逈立向苍苍。','',''),('quantangshi-11125','秦州杂诗二十首 六','杜甫','quantangshi','','卷12','城上胡笳奏，山边汉节归。
防河赴沧海，奉诏发金微。
士苦形骸黑，旌疎鸟兽稀。
那闻往来戍，恨解邺城围。','',''),('quantangshi-11126','秦州杂诗二十首 七','杜甫','quantangshi','','卷12','莽莽万重山，孤城山谷间。
无风云出塞，不夜月临关。
属国归何晚，楼兰斩未还。
烟尘独长望，衰飒正摧颜。','',''),('quantangshi-11127','秦州杂诗二十首 八','杜甫','quantangshi','','卷12','闻道寻源使，从天此路回。
牵牛去几许，宛马至今来。
一望幽燕隔，何时郡国开。
东征健儿尽，羌笛暮吹哀。','',''),('quantangshi-11128','秦州杂诗二十首 九','杜甫','quantangshi','','卷12','今日明人眼，临池好驿亭。
丛篁低地碧，高柳半天青。
稠叠多幽事，喧呼阅使星。
老夫如有此，不异在郊坰。','',''),('quantangshi-11129','秦州杂诗二十首 十','杜甫','quantangshi','','卷12','云气接昆仑，涔涔塞雨繁。
羌童看渭水，使客向河源。
烟火军中幕，牛羊岭上村。
所居秋草净，正闭小蓬门。','',''),('quantangshi-11130','秦州杂诗二十首 十一','杜甫','quantangshi','','卷12','萧萧古塞冷，漠漠秋云低。
黄鹄翅垂雨，苍鹰饥啄泥。
蓟门谁自北，汉将独征西。
不意书生耳，临衰厌鼓鞞。','',''),('quantangshi-11131','秦州杂诗二十首 十二','杜甫','quantangshi','','卷12','山头南郭寺，水号北流泉。
老树空庭得，清渠一邑传。
秋花危石底，晚景卧钟边。
俯仰悲身世，溪风为飒然。','',''),('quantangshi-11132','秦州杂诗二十首 十三','杜甫','quantangshi','','卷12','传道东柯谷，深藏数十家。
对门藤盖瓦，映竹水穿沙。
瘦地飜宜粟，阳坡可种瓜。
船人近相报，但恐失桃花。','',''),('quantangshi-11133','秦州杂诗二十首 十四','杜甫','quantangshi','','卷12','万古仇池穴，潜通小有天。
神鱼人不见，福地语真传。
近接西南境，长怀十九泉。
何时一茅屋，送老白云边。','',''),('quantangshi-11134','秦州杂诗二十首 十五','杜甫','quantangshi','','卷12','未暇泛苍海，悠悠兵马间。
塞门风落木，客舍雨连山。
阮籍行多兴，庞公隐不还。
东柯遂疎嬾，休镊鬓毛斑。','',''),('quantangshi-11135','秦州杂诗二十首 十六','杜甫','quantangshi','','卷12','东柯好崖谷，不与众峰羣。
落日邀双鸟，晴天养片云。
野人矜险绝，水竹会平分。
采药吾将老，儿童未遣闻。','',''),('quantangshi-11136','秦州杂诗二十首 十七','杜甫','quantangshi','','卷12','边秋阴易久，不复辨晨光。
檐雨乱淋幔，山云低度墙。
鸬鹚窥浅井，蚯蚓上深堂。
车马何萧索，门前百草长。','',''),('quantangshi-11137','秦州杂诗二十首 十八','杜甫','quantangshi','','卷12','地僻秋将尽，山高客未归。
塞云多断绩，边日少光辉。
警急烽常报，传闻檄屡飞。
西戎外甥国，何得迕天威。','',''),('quantangshi-11138','秦州杂诗二十首 十九','杜甫','quantangshi','','卷12','凤林戈未息，鱼海路常难。
候火云烽峻，悬军幕井干。
风连西极动，月过北庭寒。
故老思飞将，何时议筑坛。','',''),('quantangshi-11139','秦州杂诗二十首 二十','杜甫','quantangshi','','卷12','唐尧真自圣，野老复何知。
晒药能无妇，应门幸有儿。
藏书闻禹穴，读记忆仇池。
为报鸳行旧，鹪鹩在一枝。','',''),('quantangshi-11140','月夜忆舍弟','杜甫','quantangshi','','卷12','戍鼓断人行，秋边一雁声。
露从今夜白，月是故乡明。
有弟皆分散，无家问死生。
寄书长不避，况乃未休兵。','',''),('quantangshi-11141','宿赞公房','杜甫','quantangshi','','卷12','杖锡何来此，秋风已飒然。
雨荒深院菊，霜倒半池莲。
放逐宁违性，虚空不离禅。
相逢成夜宿，陇月向人圆。','',''),('quantangshi-11142','东楼','杜甫','quantangshi','','卷12','万里流沙道，西征过北门。
但添新战骨，不返旧征魂。
楼角临风迥，城阴带水昏。
传声看驿使，送节向河源。','',''),('quantangshi-11143','雨晴','杜甫','quantangshi','','卷12','天水秋云薄，从西万里风。
今朝好晴景，久雨不妨农。
塞柳行疎翠，山棃结小红。
胡笳楼上发，一雁入高空。','',''),('quantangshi-11144','寓目','杜甫','quantangshi','','卷12','一县蒲萄熟，秋山苜蓿多。
关云常带雨，塞水不成河。
羌女轻烽燧，胡儿制骆驼。
自伤迟暮眼，丧乱饱经过。','',''),('quantangshi-11145','山寺','杜甫','quantangshi','','卷12','野寺残僧少，山园细路高。
麝香眠石竹，鹦鹉啄金桃。
乱石通人过，悬崖置屋牢。
上方重阁晚，百里见秋毫。','',''),('quantangshi-11146','即事','杜甫','quantangshi','','卷12','闻道花门破，和亲事却非。
人怜汉公主，生得渡河归。
秋思抛云髻，腰支胜宝衣。
羣凶犹索战，回首意多违。','',''),('quantangshi-11147','遣怀','杜甫','quantangshi','','卷12','愁眼看霜露，寒城菊自花。
天风随断柳，客泪堕清笳。
水净楼阴直，山昏塞日斜。
夜来归鸟尽，啼杀后栖鸦。','',''),('quantangshi-11148','天河','杜甫','quantangshi','','卷12','常时任显晦，秋至辄分明。
纵被微云掩，终能永夜清。
含星动双阙，伴月照边城。
牛女年年渡，何曾风浪生。','',''),('quantangshi-11149','初月','杜甫','quantangshi','','卷12','光细弦岂上，影斜轮未安。
微升古塞外，已隐暮云端。
河汉不改色，关山空自寒。
庭前有白露，暗满菊花团。','',''),('quantangshi-11150','归燕','杜甫','quantangshi','','卷12','不独避霜雪，其如俦侣稀。
四时无失序，八月自知归。
春色岂相访，众雏还识机。
故巢傥未毁，会傍主人飞。','',''),('quantangshi-11151','捣衣','杜甫','quantangshi','','卷12','亦知戍不返，秋至拭清砧。
已近苦寒月，况经长别心。
宁辞捣熨倦，一寄塞垣深。
用尽闺中力，君听空外音。','',''),('quantangshi-11152','促织','杜甫','quantangshi','','卷12','促织甚微细，哀音何动人。
草根吟不稳，牀下夜相亲。
久客得无泪，放妻难及晨。
悲丝与急管，感激异天真。','',''),('quantangshi-11153','萤火','杜甫','quantangshi','','卷12','幸因腐草出，敢近太阳飞。
未足临书卷，时能点客衣。
随风隔幔小，带雨傍林微。
十月清霜重，飘零何处归。','',''),('quantangshi-11154','蒹葭','杜甫','quantangshi','','卷12','摧折不自守，秋风吹若何。
暂时花戴雪，几处叶沈波。
体弱春风早，丛长夜露多。
江湖后摇落，亦恐岁蹉跎。','',''),('quantangshi-11155','苦竹','杜甫','quantangshi','','卷12','青冥亦自守，輭弱强扶持。
味苦夏虫避，丛卑春鸟疑。
轩墀曾不重，剪伐欲无辞。
幸近幽人屋，霜根结在兹。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-11156','除架','杜甫','quantangshi','','卷12','束薪已零落，瓠叶转萧疎。
幸结白花了，宁辞青蔓除。
秋虫声不去，暮雀意何如。
寒事今牢落，人生亦有初。','',''),('quantangshi-11157','废畦','杜甫','quantangshi','','卷12','秋蔬拥霜露，岂敢惜凋残。
暮景数枝叶，天风吹汝寒。
绿霑泥滓尽，香与岁时阑。
生意春如昨，悲君白玉盘。','',''),('quantangshi-11158','夕烽','杜甫','quantangshi','','卷12','夕峰来不近，每日报平安。
塞上传光小，云边落点残。
照秦通警急，过陇自艰难。
闻道蓬莱殿，千门立马看。','',''),('quantangshi-11159','秋笛','杜甫','quantangshi','','卷12','清商欲尽奏，奏苦血霑衣。
他日伤心极，征人白骨归。
相逢恐恨过，故作发声微。
不见秋云动，悲风稍稍飞。','',''),('quantangshi-11160','送远','杜甫','quantangshi','','卷12','带甲满天地，胡为君远行。
亲朋尽一哭，鞍马去孤城。
草木岁月晚，关河霜雪清。
别离已昨日，因见古人情。','',''),('quantangshi-11161','观兵','杜甫','quantangshi','','卷12','北庭送壮士，貔虎数尤多。
精锐旧无敌，边隅今若何。
妖氛拥白马，元帅待雕戈。
莫守邺城下，斩鲸辽海波。','',''),('quantangshi-11162','不归','杜甫','quantangshi','','卷12','河间尚征伐，汝骨在空城。
从弟人皆有，终身恨不平。
数金怜俊迈，总角爱聪明。
而上三年土，春风草又生。','',''),('quantangshi-11163','天末忆李白','杜甫','quantangshi','','卷12','凉风起天末，君子意如何。
鸿雁几时到，江湖秋水多。
文章憎命达，魑魅喜人过。
应共冤魂语，投诗赠汩罗。','',''),('quantangshi-11164','独立','杜甫','quantangshi','','卷12','空外一鸷鸟，河间双白鸥。
飘颻搏击便，容易往来游。
草露亦多湿，蛛丝仍未收。
天机近人事，独立万端忧。','',''),('quantangshi-11165','日暮','杜甫','quantangshi','','卷12','日落风亦起，城头鸟尾讹。
黄云高未动，白水已扬波。
羌妇语还哭，胡儿行且歌。
将军别换马，夜出拥雕戈。','',''),('quantangshi-11166','空囊','杜甫','quantangshi','','卷12','翠柏苦犹食，晨霞高可餐。
世人共卤莽，吾道属艰难。
不爨井晨冻，无衣牀夜寒。
囊空恐羞涩，留得一钱看。','',''),('quantangshi-11167','病马','杜甫','quantangshi','','卷12','乘尔亦已久，天寒关塞深。
尘中老尽力，岁晚病伤心。
毛骨岂殊众，驯良犹至今。
物微意不浅，感动一沈吟。','',''),('quantangshi-11168','蕃劒','杜甫','quantangshi','','卷12','致此自僻远，又非珠玉装。
如何有奇怪，每夜吐光芒。
虎气必腾趠，龙身宁久藏。
风尘苦未息，持汝奉明王。','',''),('quantangshi-11169','铜瓶','杜甫','quantangshi','','卷12','Ｂ乱后碧井废，时清瑶殿深。
铜瓶未失水，百丈有哀音。
侧想美人意，应非寒甃沈。
蛟龙半缺落，犹得折黄金。','',''),('quantangshi-11170','观安西兵过赴关中待命二首 一','杜甫','quantangshi','','卷12','四镇富精锐，摧锋皆绝伦。
还闻献士卒，足以静风尘。
老马夜知道，苍鹰饥着人。
临危经久战，用急始如神。','',''),('quantangshi-11171','观安西兵过赴关中待命二首 二','杜甫','quantangshi','','卷12','奇兵不在众，万马救中原。
谈笑无河北，心肝奉至尊。
孤云随杀气，飞鸟避辕门。
竟日留欢乐，城池未觉喧。','',''),('quantangshi-11172','送人从军','杜甫','quantangshi','','卷12','弱水应无地，阳关已近天。
今君渡沙碛，累月断人烟。
好武宁论命，封侯不计年。
马寒防失道，雪没锦鞍鞯。','',''),('quantangshi-11173','野望','杜甫','quantangshi','','卷12','清秋望不极，迢遰起曾阴。
远水兼天净，孤城隐雾深。
叶稀风更落，山迥日初沈。
独鹤归何晚，昏鸦已满林。','',''),('quantangshi-11174','示侄佐','杜甫','quantangshi','','卷12','多病秋风落，君来慰眼前。
自闻茅屋趣，只想竹林眠。
满谷山云起，侵篱涧水悬。
嗣宗诸子侄，早觉仲容贤。','',''),('quantangshi-11175','佐还山后寄三首 一','杜甫','quantangshi','','卷12','山晚浮云合，归时恐路迷。
涧寒人欲到，村黑鸟应栖。
野客茅茨小，田家树木低。
旧谙疎嬾叔，须汝故相携。','',''),('quantangshi-11176','佐还山后寄三首 二','杜甫','quantangshi','','卷12','白露黄粱熟，分张素有期。
已应舂得细，颇觉寄来迟。
味岂同金菊，香宜配绿葵。
老人佗日爱，正想滑流匙。','',''),('quantangshi-11177','佐还山后寄三首 三','杜甫','quantangshi','','卷12','几道泉浇圃，交横落慢坡。
葳蕤秋叶少，隐映野云多。
隔沼连香芰，通林带女萝。
甚闻霜薤白，重惠意如何。','',''),('quantangshi-11178','从人觅小胡孙许寄','杜甫','quantangshi','','卷12','人说南州路，山猨树树悬。
举家闻若骇，为寄小如拳。
预哂愁胡面，初调见马鞭。
许求聪慧者，童稚捧应癫。','',''),('quantangshi-11179','秋日阮隐居致薤三十束','杜甫','quantangshi','','卷12','隐者柴门内，畦蔬绕舍秋。
盈筐承露薤，不待致书求。
束比青刍色，圆齐玉箸头。
衰年关鬲冷，味暖并无忧。','',''),('quantangshi-11180','秦州见敕目薛三璩授司议郎毕四曜除监察与二子有故远喜迁官兼述索居凡三十韵','杜甫','quantangshi','','卷12','大雅何寥阔，斯人尚典刑。
交期余潦倒，材力尔精灵。
二子声同日，诸生困一经。
文章开穾奥，迁擢润朝廷。
旧好何由展，新诗更忆听。
别来头并白，相见眼终青。
伊昔贫皆甚，同忧心不宁。
栖遑分半菽，浩荡逐流萍。
俗态犹猜忌，妖氛忽杳冥。
独慙投汉阁，俱议哭秦庭。
远蜀祗无补，囚梁亦固扃。
华夷相混合，宇宙一膻腥。
帝力收三统，天威总四溟。
旧都俄望幸，清庙肃惟馨。
杂种虽高垒，长驱甚建瓴。
焚香淑景殿，涨水望云亭。
法驾初还日，羣公若会星。
宫臣仍点染，柱史正零丁。
官忝趋栖凤，朝回叹聚萤。
唤人看腰褭，不嫁惜娉婷。
掘劒知埋狱，提刀见发硎。
侏儒应共饱，渔父忌偏醒。
旅泊穷清渭，长吟望浊泾。
羽书还似急，烽火未全停。
师老资残寇，戎生及近坰。
忠臣辞愤激，烈士涕飘零。
上将盈边鄙，元勋溢鼎铭。
仰思调玉烛，谁定握青萍。
陇俗轻鹦鹉，原情类鹡鸰。
秋风动关塞，高卧想仪行。','',''),('quantangshi-11181','寄彭州高三十五使君适虢州岑二十七长史参三十韵','杜甫','quantangshi','','卷12','故人何寂寞，今我独凄凉。
老去才难尽，秋来兴甚长。
物情尤可见，辞客未能忘。
海内知名士，云端各异方。
高岑殊缓步，沈鲍得同行。
意惬关飞动，篇终接混茫。
举天悲富骆，近代惜卢王。
似尔官仍贵，前贤命可伤。
诸侯非弃掷，半刺已翱翔。
诗好几时见，书成无信将。
男儿行处是，客子鬬身强。
羁旅推贤圣，沈绵抵咎殃。
三年犹疟疾，一鬼不销亡。
隔日搜脂髓，增寒抱雪霜。
徒然潜隙地，有腼屡鲜妆。
何太龙钟极，于今出处妨。
无钱居帝里，尽室在边疆。
刘表虽遗恨，庞公至死藏。
心微傍鱼鸟，肉瘦怯豺狼。
陇草萧萧白，洮云片片黄。
彭门劒阁外，虢略鼎湖旁。
荆玉簪头冷，巴笺染翰光。
乌麻蒸续晒，丹橘露应尝。
岂异神仙宅，俱兼山水乡。
竹斋烧药竈，花屿读书牀。
更得清新否，遥知对属忙。
旧宫宁改汉，淳俗本归唐。
济世宜公等，安贫亦士常。
蚩尤终戮辱，胡羯漫猖狂。
会待祆氛静，论文暂裹粮。','',''),('quantangshi-11182','寄岳州贾司马六丈巴州严八使君两阁老五十韵','杜甫','quantangshi','','卷12','衡岳啼猨里，巴州鸟道边。
故人俱不利，谪宦两悠然。
开辟干坤正，荣枯雨露偏。
长沙才子远，钓濑客星悬。
忆昨趋行殿，殷忧捧御筵。
讨胡愁李广，奉使待张骞。
无复云台仗，虚修水战船。
苍茫城七十，流落劒三千。
画角吹秦晋，旄头俯涧瀍。
小儒轻董卓，有识笑苻坚。
浪作禽填海，那将血射天。
万方思助顺，一鼓气无前。
阴散陈仓北，晴熏太白巅。
乱麻尸积卫，破竹势临燕。
法驾还双阙，王师下八川。
此时霑奉引，佳气拂周旋。
貔虎开金甲，麒麟受玉鞭。
侍臣谙入仗，厩马解登仙。
花动朱楼雪，城凝碧树烟。
衣冠心惨怆，故老泪潺湲。
哭庙悲风急，朝正霁景鲜。
月分梁汉米，春得水衡钱。
内蘂繁于缬，宫莎輭胜緜。
恩荣同拜手，出入最随肩。
晚着华堂醉，寒重绣被眠。
辔齐兼秉烛，书枉满怀牋。
每觉升元辅，深期列大贤。
秉钧方咫尺，铩翮再聊翩。
禁掖朋从改，微班性命全。
青蒲甘受戮，白发竟谁怜。
弟子贫原宪，诸生老伏虔。
师资谦未达，乡党敬何先。
旧好肠堪断，新愁眼欲穿。
翠干危栈竹，红腻小湖莲。
贾笔论孤愤，严诗赋几篇。
定知深意苦，莫使众人传。
贝锦无停织，朱丝有断弦。
浦鸥防碎首，霜鹘不空拳。
地僻昏炎瘴，山稠隘石泉。
且将棊度日，应用酒为年。
典郡终微眇，治中实弃捐。
安排求傲吏，比兴展归田。
去去才难得，苍苍理又玄。
古人称逝矣，吾道卜终焉。
陇外飜投迹，渔阳复控弦。
笑为妻子累，甘与岁时迁。
亲故行稀少，兵戈动接联。
他乡饶梦寐，失侣自屯邅。
多病加淹泊，长吟阻静便。
如公尽雄俊，志在必腾骞。','',''),('quantangshi-11183','寄张十二山人彪三十韵','杜甫','quantangshi','','卷12','独卧蒿阳客，三违颍水春。
艰难随老母，惨澹向时人。
谢氏寻山屐，陶公漉酒巾。
羣凶弥宇宙，此物在风尘。
历下辞姜被，关西得孟邻。
早通交契密，晚接道流新。
静者心多妙，先生艺绝伦。
草书何太苦，诗兴不无神。
曹植休前辈，张芝更后身。
数篇吟可老，一字买堪贫。
将恐曾防寇，深潜托所亲。
宁闻倚门夕，尽力洁飧晨。
疎嬾为名误，驱驰丧我真。
索居犹寂寞，相遇益悲辛。
流转依边徼，逢迎念席珍。
时来故旧少，乱后别离频。
世祖修高庙，文公赏从臣。
商山犹入楚，源水不离秦。
存想青龙祕，骑行白鹿驯。
耕岩非谷口，结草即河滨。
肘后符应验，囊中药未陈。
旅怀殊不惬，良觌渺无因。
自古皆悲恨，浮生有屈伸。
此邦今尚武，何处且依仁。
鼓角凌天籁，关山信月轮。
官场罗镇碛，贼火近洮岷。
萧索论兵地，苍茫鬬将辰。
大军多处所，余孽尚纷纶。
高兴知笼鸟，斯文起获麟。
穷秋正摇落，回首望松筠。','',''),('quantangshi-11184','寄李十二白二十韵','杜甫','quantangshi','','卷12','昔年有狂客，号尔谪仙人。
笔落惊风雨，诗成泣鬼神。
声名从此大，汩没一朝伸。
文彩承殊渥，流传必绝伦。
龙舟移棹晚，兽锦夺袍新。
白日来深殿，青云满后尘。
乞归优诏许，遇我宿心亲。
未负幽栖志，兼全宠辱身。
剧谈怜野逸，嗜酒见天真。
醉舞梁园夜，行歌泗水春。
才高心不展，道屈善无邻。
处士禰衡俊，诸生原宪贫。
稻粱求未足，薏苡谤何频。
五岭炎蒸地，三危放逐臣。
几年遭鵩鸟，独泣向麒麟。
苏武先还汉，黄公岂事秦。
楚筵辞醴日，梁狱上书辰。
已用当时法，谁将此义陈。
老吟秋月下，病起暮江滨。
莫怪恩波隔，乘槎与问津。','',''),('quantangshi-11185','蜀相','杜甫','quantangshi','','卷12','丞相祠堂何处寻，锦官城外柏森森。
映堦碧草自春色，隔叶黄鹂空好音。
三顾频烦天下计，两朝开济老臣心。
出师未捷身先死，长使英雄泪满襟。','',''),('quantangshi-11186','卜居','杜甫','quantangshi','','卷12','浣花流水水西头，主人为卜林塘幽。
已知出郭少尘事，更有澄江销客愁。
无数蜻蜓齐上下，一双鸂鶒对沈浮。
东行万里堪乘兴，须向山阴上小舟。','',''),('quantangshi-11187','一室','杜甫','quantangshi','','卷12','一室他乡远，空林暮景悬。
正愁闻塞笛，独立见江船。
巴蜀来多病，荆蛮去几年。
应同王粲宅，留井岘山前。','',''),('quantangshi-11188','梅雨','杜甫','quantangshi','','卷12','南京西浦道，四月熟黄梅。
湛湛长江去，冥冥细雨来。
茅茨疎易湿，云雾密难开。
竟日蛟龙喜，盘涡与岸回。','',''),('quantangshi-11189','为农','杜甫','quantangshi','','卷12','锦里烟尘外，江村八九家。
圆荷浮小叶，细麦落轻花。
卜宅从兹老，为农去国赊。
远惭句漏令，不得问丹砂。','',''),('quantangshi-11190','有客','杜甫','quantangshi','','卷12','幽栖地僻经过少，老病人扶再拜难。
岂有文章惊海内，漫劳车马驻江干。
竟日淹留佳客坐，百年麤粝腐儒餐。
不嫌野外无供给，乘兴还来看药栏。','',''),('quantangshi-11191','狂夫','杜甫','quantangshi','','卷12','万里桥西一，草堂，百花潭水即沧浪。
风含翠筱娟娟静，雨裛红蕖冉冉香。
厚禄故人书断绝，恒饥稚子色凄凉。
欲填沟壑唯疎放，自笑狂夫老更狂。','',''),('quantangshi-11192','宾至','杜甫','quantangshi','','卷12','患气经时久，临江卜宅新。
喧卑方避俗，疎快颇宜人。
有客过茅宇，呼儿正葛巾。
自锄稀菜甲，小摘为情亲。','',''),('quantangshi-11193','王十五司马弟出郭相访兼遗营茅屋赀','杜甫','quantangshi','','卷12','客里何迁次，江边正寂寥。
肯来寻一老，愁破是今朝。
忧我营茅栋，携钱过野桥。
他乡唯表弟，还往莫辞遥。','',''),('quantangshi-11194','堂成','杜甫','quantangshi','','卷12','背郭堂成荫白茅，缘江路熟俯青郊。
桤林碍日吟风叶，笼竹和烟滴露梢。
暂止飞乌将数子，频来语燕定新巢。
旁人错比扬雄宅，嬾惰无心作解嘲。','',''),('quantangshi-11195','田舍','杜甫','quantangshi','','卷12','田舍清江曲，柴门古道旁。
草深迷市井，地僻嬾衣裳。
榉柳枝枝弱，枇杷树树香。
鸬鹚西日照，晒翅满鱼梁。','',''),('quantangshi-11196','进艇','杜甫','quantangshi','','卷12','南京久客耕南亩，北望伤神坐北窗。
昼引老妻乘小艇，晴看稚子浴清江。
俱飞蛱蝶元相逐，并蔕芙蓉本自双。
茗饮蔗浆携所有，瓷甖无谢玉为缸。','',''),('quantangshi-11197','西郊','杜甫','quantangshi','','卷12','时出碧鸡坊，西郊向草堂。
市桥官柳细，江路野梅香。
傍架齐书帙，看题减药囊。
无人觉来往，疎嬾意何长。','',''),('quantangshi-11198','所思','杜甫','quantangshi','','卷12','苦忆荆州醉司马，谪官樽俎定常开。
九江日落醒何处，一柱观头眠几回。
可怜怀抱向人尽，欲问平安无使来。
故凭锦水将双泪，好过瞿塘灧滪堆。','',''),('quantangshi-11199','江村','杜甫','quantangshi','','卷12','清江一曲抱村流，长夏江村事事幽。
自去自来堂上燕，相亲相近水中鸥。
老妻画纸为碁局，稚子敲针作钓钩。
多病所须唯药物，微躯此外更何求。','',''),('quantangshi-11200','江涨','杜甫','quantangshi','','卷12','江涨柴门外，儿童报急流。
下牀高数尺，倚杖没中洲。
细动迎风燕，轻摇逐浪鸥。
渔人萦小楫，容易拔船头。','',''),('quantangshi-11201','野老','杜甫','quantangshi','','卷12','野老篱前江岸回，柴门不正逐江开。
渔人网集澄潭下，贾客船随返照来。
长路关心悲劒阁，片云何意傍琴台。
王师未报收东郡，城阙秋生画角哀。','',''),('quantangshi-11202','云山','杜甫','quantangshi','','卷12','京洛云山外，音书静不来。
神交作赋客，力尽望乡台。
衰疾江边卧，亲朋日暮回。
白鸥元水宿，何事有余哀。','',''),('quantangshi-11203','遣兴','杜甫','quantangshi','','卷12','干戈犹未定，弟妹各何之。
拭泪霑襟血，梳头满面丝。
地卑荒野大，天远暮江迟。
衰疾那能久，应无见汝时。','',''),('quantangshi-11204','北邻','杜甫','quantangshi','','卷12','明府岂辞满，藏身方告劳。
青钱买野竹，白帻岸江臯。
爱酒晋山简，能诗何水曹。
时来访老疾，步屧到蓬蒿。','',''),('quantangshi-11205','南邻','杜甫','quantangshi','','卷12','锦里先生乌角巾，园收芋粟不全贫。
惯看宾客儿童喜，得食阶除鸟雀驯。
秋水才深四五尺，野航恰受两三人。
白沙翠竹江村暮，相对柴门月色新。','',''),('quantangshi-11206','出郭','杜甫','quantangshi','','卷12','霜露晚凄凄，高天逐望低。
远烟盐井上，斜景雪峰西。
故国犹兵马，他乡亦鼓鼙。
江城今夜客，还与旧乌啼。','',''),('quantangshi-11207','过南邻朱山人水亭','杜甫','quantangshi','','卷12','相近竹参差，相过人不知。
幽花欹满树，小水细通池。
归客村非远，残樽席更移。
看君多道气，从此数追随。','',''),('quantangshi-11208','恨别','杜甫','quantangshi','','卷12','洛城一别四千里，胡骑长驱五六年。
草木变衰行劒外，兵戈阻绝老江边。
思家步月清宵立，忆弟看云白日眠。
闻道河阳近乘胜，司徒急为破幽燕。','',''),('quantangshi-11209','寄贺兰銛','杜甫','quantangshi','','卷12','朝野欢娱后，干坤震荡中。
相随万里日，总作白头翁。
岁晚仍分袂，江边更转蓬。
勿云俱异域，饮啄几回同。','',''),('quantangshi-11210','寄杨五桂州谭','杜甫','quantangshi','','卷12','五岭皆炎热，宜人独桂林。
梅花万里外，雪片一冬深。
闻此宽相忆，为邦复好音。
江边送孙楚，远附白头吟。','',''),('quantangshi-11211','逢唐兴刘主簿弟','杜甫','quantangshi','','卷12','分手开元末，连年绝尺书。
江山且相见，戎马未安居。
劒外官人冷，关中驿骑疎。
轻舟下吴会，主簿意何如。','',''),('quantangshi-11212','和裴迪登新津寺寄王侍郎','杜甫','quantangshi','','卷12','何限倚山木，吟诗秋叶黄。
蝉声集古寺，鸟影度寒塘。
风物悲游子，登临忆侍郎。
老夫贪佛日，随意宿僧房。','',''),('quantangshi-11213','敬简王明府','杜甫','quantangshi','','卷12','叶县郎官宰，周南太史公。
神仙才有数，流落意无穷。
骥病思偏秣，鹰愁怕苦笼。
看君用高义，耻与万人同。','',''),('quantangshi-11214','重简王明府','杜甫','quantangshi','','卷12','甲子西南异，冬来只薄寒。
江云何夜尽，蜀雨几时干。
行李须相问，穷愁岂有宽。
君听鸿雁响，恐致稻粱难。','',''),('quantangshi-11215','建都十二韵','杜甫','quantangshi','','卷12','苍生未苏息，胡马半干坤。
议在云台上，谁扶黄屋尊。
建都分魏阙，下韶辟荆门。
恐失东人望，其如西极存。
时危当雪耻，计大岂轻论。
虽倚三阶正，终愁万国飜。
牵裾恨不死，漏网荷殊恩。
永负汉庭哭，遥怜湘水魂。
穷冬客江劒，随事有田园。
风断青蒲节，霜埋翠竹根。
衣冠空穰穰，关辅久昏昏。
愿枉长安日，光辉照北原。','',''),('quantangshi-11216','岁暮','杜甫','quantangshi','','卷12','岁暮远为客，边隅还用兵。
烟尘犯雪岭，鼓角动江城。
天地日流血，朝廷谁请缨。
济时敢爱死，寂寞壮心惊。','',''),('quantangshi-11217','和裴迪登蜀州东亭送客逢早梅相忆见寄','杜甫','quantangshi','','卷12','东阁官梅动诗兴，还如何逊在扬州。
此时对雪遥相忆，送客逢春可自由。
幸不折来伤岁暮，若为看去乱乡愁。
江边一树垂垂发，朝夕催人自白头。','',''),('quantangshi-11218','寄赠王十将军承俊','杜甫','quantangshi','','卷12','将军胆气雄，臂悬两角弓。
缠结青骢马，出入锦城中。
时危未授钺，势屈难为功。
宾客满堂上，何人高义同。','',''),('quantangshi-11219','暮登四安寺钟楼寄裴十','杜甫','quantangshi','','卷12','暮倚高楼对雪峰，僧来不语自鸣钟。
孤城返照红将歛，近市浮烟翠且重。
多病独愁常閴寂，故人相见未从容。
知君苦思缘诗瘦，大向交游万事慵。','',''),('quantangshi-11220','散愁二首 一','杜甫','quantangshi','','卷12','久客宜旋斾，兴王未息戈。
蜀星阴见少，江雨夜闻多。
百万传深入，寰区望匪它。
司徒下燕赵，收取旧山河。','',''),('quantangshi-11221','散愁二首 二','杜甫','quantangshi','','卷12','闻道并州镇，尚书训士齐。
几时通蓟北，当日报关西。
恋阙丹心破，霑衣皓首啼。
老魂招不得，归路恐长迷。','',''),('quantangshi-11222','奉酬李都督表丈早春作','杜甫','quantangshi','','卷12','力疾坐清晓，来时悲早春。
转添愁伴客，更觉老随人。
红入桃花嫩，青归柳叶新。
望乡应未已，四海尚风尘。','',''),('quantangshi-11223','客至','杜甫','quantangshi','','卷12','舍南舍北皆春水，但见羣鸥日日来。
花径不曾缘客扫，蓬门今始为君开。
盘餐市远无兼味，樽酒家贫只旧醅。
肯与邻翁相对饮，隔篱呼取尽余杯。','',''),('quantangshi-11224','遣意二首 一','杜甫','quantangshi','','卷12','啭枝黄鸟近，泛渚白鸥轻。
一径野花落，孤村春水生。
衰年催酿黍，细雨更移橙。
渐喜交游绝，幽居不用名。','',''),('quantangshi-11225','遣意二首 二','杜甫','quantangshi','','卷12','檐影微微落，津流脉脉斜。
野船明细火，宿雁聚圆沙。
云掩初弦月，香传小树花。
邻人有美酒，稚子夜能赊。','',''),('quantangshi-11226','漫成二首 一','杜甫','quantangshi','','卷12','野日荒荒白，春流泯泯清。
渚蒲随地有，村径逐门成。
只作披衣惯，常从漉酒生。
眼前无俗物，多病也身轻。','',''),('quantangshi-11227','漫成二首 二','杜甫','quantangshi','','卷12','江臯已仲春，花下复清晨。
仰面贪看鸟，回头错应人。
读书难字过，对酒满壶频。
近识峨眉老，知予嬾是真。','',''),('quantangshi-11228','春夜喜雨','杜甫','quantangshi','','卷12','好雨知时节，当春乃发生。
随风潜入夜，润物细无声。
野径云俱黑，江船火独明。
晓看红湿处，花重锦官城。','',''),('quantangshi-11229','春水','杜甫','quantangshi','','卷12','三月桃花浪，江流复旧痕。
朝来没沙尾，碧色动柴门。
接缕垂芳饵，连筒灌小园。
已添无数鸟，争浴故相喧。','',''),('quantangshi-11230','春水生二绝 一','杜甫','quantangshi','','卷12','二月六夜春水生。
门前小滩浑欲平，鸬鹚鸂鶒莫漫喜。
吾与汝曹俱眼明。','',''),('quantangshi-11231','春水生二绝 二','杜甫','quantangshi','','卷12','一夜水高二尺强，数日不可更禁当。
南市津头有船卖，无钱即买系篱旁。','',''),('quantangshi-11232','江亭','杜甫','quantangshi','','卷12','坦腹江亭暖，长吟野望时。
水流心不竞，云在意俱迟。
寂寂春将晚，欣欣物自私。
故林归未得，排闷强裁诗。','',''),('quantangshi-11233','村夜','杜甫','quantangshi','','卷12','萧萧风色暮，江头人不行。
村舂雨外急，邻火夜深明。
胡羯何多难，渔樵寄此生。
中原有兄弟，万里正含情。','',''),('quantangshi-11234','早起','杜甫','quantangshi','','卷12','春来常早起，幽事颇相关。
帖石防颓岸，开林出远山。
一丘藏曲折，缓步有跻攀。
童仆来城市，瓶中得酒还。','',''),('quantangshi-11235','可惜','杜甫','quantangshi','','卷12','花飞有底急，老去愿春迟。
可惜欢娱地，都非少壮时。
宽心应是酒，遣兴莫过诗。
此意陶潜解，吾生后汝期。','',''),('quantangshi-11236','落日','杜甫','quantangshi','','卷12','落日在帘钩，溪边春事幽。
芳菲缘岸圃，樵爨倚滩舟。
啅雀争枝坠，飞虫满院游。
浊醪谁造汝，一酌散千忧。','',''),('quantangshi-11237','独酌','杜甫','quantangshi','','卷12','步屦深林晚，开樽独酌迟。
仰蜂黏落絮，行蚁上枯梨。
薄劣惭真隐，幽偏得自怡。
本无轩冕意，不是傲当时。','',''),('quantangshi-11238','徐步','杜甫','quantangshi','','卷12','整履步青芜，荒庭日欲晡。
芹泥随燕觜，花蘂上蜂须。
把酒从衣湿，吟诗信杖扶。
敢论才见忌，实有醉如愚。','',''),('quantangshi-11239','寒食','杜甫','quantangshi','','卷12','寒食江村路，风花高下飞。
汀烟轻冉冉，竹日静晖晖。
田父要皆去，邻家闹不违。
地偏相识尽，鸡犬亦忘归。','',''),('quantangshi-11240','高柟','杜甫','quantangshi','','卷12','柟树色冥冥，江边一盖青。
近根开药圃，接叶制茅亭。
落景阴犹合，微风韵可听。
寻常绝醉困，卧此片时醒。','',''),('quantangshi-11241','恶树','杜甫','quantangshi','','卷12','独遶虚斋径，常持小斧柯。
幽阴成颇杂，恶木剪还多。
枸杞因吾有，鸡栖奈汝何。
方知不材者，生长漫婆娑。','',''),('quantangshi-11242','石镜','杜甫','quantangshi','','卷12','蜀王将此镜，送死置空山。
冥寞怜香骨，提携近玉颜。
众妃无复叹，千骑亦虚还。
独有伤心石，埋轮月宇间。','',''),('quantangshi-11243','琴台','杜甫','quantangshi','','卷12','茂陵多病后，尚爱卓文君。
酒肆人间世，琴台日暮云。
野花留宝靥，蔓草见罗帬。
归凤求皇意，寥寥不复闻。','',''),('quantangshi-11244','闻斛斯六官未归','杜甫','quantangshi','','卷12','故人南郡去，去索作碑钱。
本卖文为活，飜令室倒悬。
荆扉深蔓草，土锉冷疎烟。
老罢休无赖，归来省醉眠。','',''),('quantangshi-11245','游修觉寺','杜甫','quantangshi','','卷12','野寺江天豁，山扉花竹幽。
诗应有神助，吾得及春游。
径石相萦带，川云自去留。
禅枝宿众鸟，漂转暮归愁。','',''),('quantangshi-11246','后游','杜甫','quantangshi','','卷12','寺忆新游处，桥怜再渡时。
江山如有待，花柳更无私。
野润烟光薄，沙暄日色迟。
客愁全为减，舍此复何之。','',''),('quantangshi-11247','题新津北桥楼','杜甫','quantangshi','','卷12','望极春城上，开筵近鸟巢。
白花檐外朵，青柳槛前梢。
池水观为政，厨烟觉远庖。
西川供客眼，唯有此江郊。','',''),('quantangshi-11248','江涨','杜甫','quantangshi','','卷12','江发蛮夷涨，山添雨雪流。
大声吹地转，高浪蹴天浮。
鱼鳖为人得，蛟龙不自谋。
轻帆好去便，吾道付沧洲。','',''),('quantangshi-11249','晚晴','杜甫','quantangshi','','卷12','村晚惊风度，庭幽过雨霑。
夕阳薰细草，江色映疎帘。
书乱谁能帙，杯干可自添。
时闻有余论，未怪老夫潜。','',''),('quantangshi-11250','朝雨','杜甫','quantangshi','','卷12','凉气晚萧萧，江云乱眼飘。
风鸳藏近渚，雨燕集深条。
黄绮终辞汉，巢由不见尧。
草堂樽酒在，幸得过清朝。','',''),('quantangshi-11251','江上值水如海势聊短述','杜甫','quantangshi','','卷12','为人性僻耽佳句，语不惊人死不休。
老去诗篇浑漫兴，春来花鸟莫深愁。
新添水槛供垂钓，故着浮槎替入舟。
焉得思如陶谢手，令渠述作与同游。','',''),('quantangshi-11252','送裴五赴东川','杜甫','quantangshi','','卷12','故人亦流落，高义动干坤。
何日通燕塞，相看老蜀门。
东行应暂别，北望苦销魂。
凛凛悲秋意，非君谁与论。','',''),('quantangshi-11253','赴青城县出成都寄陶王二少尹','杜甫','quantangshi','','卷12','老耻妻孥笑，贫嗟出入劳。
客情投异县，诗态忆吾曹。
东郭沧江合，西山白雪高。
文章差底病，回首兴滔滔。','',''),('quantangshi-11254','因崔五侍御寄高彭州','杜甫','quantangshi','','卷12','百年已过半，秋至转饥寒。
为问彭州牧，何时救急难。','',''),('quantangshi-11255','野望因过常少仙','杜甫','quantangshi','','卷12','野桥齐度马，秋望转悠哉。
竹覆青城合，江从灌口来。
入村樵径引，尝果栗皱开。
落尽高天日，幽人未遣回。','',''),('quantangshi-11256','寄杜位','杜甫','quantangshi','','卷12','近闻宽法离新州，想见怀归尚百忧。
逐客虽皆万里去，悲君已是十年流。
干戈况复尘随眼，鬓发还应雪满头。','',''),('quantangshi-11257','奉简高三十五使君','杜甫','quantangshi','','卷12','当代论才子，如公复几人。
骅骝开道路，鹰隼出风尘。
行色秋将晚，交情老更亲。
天涯喜相见，披豁对吾真。','',''),('quantangshi-11258','送韩十四江东觐省','杜甫','quantangshi','','卷12','兵戈不见老莱衣，叹息人间万事非。
我已无家寻弟妹，君今何处访庭闱。
黄牛峡静滩声转，白马江寒树影稀。
此别应须各努力，故乡犹恐未同归。','',''),('quantangshi-11259','酬高使君相赠','杜甫','quantangshi','','卷12','古寺僧牢落，空房客寓居。
故人供禄米，邻舍与园蔬。
双树容听法，三车肯载书。
草玄吾岂敢，赋或似相如。','',''),('quantangshi-11260','草堂即事','杜甫','quantangshi','','卷12','荒村建子月，独树老夫家。
雾里江船渡，风前径竹斜。
寒鱼依密藻，宿鹭起圆沙。
蜀酒禁愁得，无钱何处赊。','',''),('quantangshi-11261','魏十四侍御就弊庐相别','杜甫','quantangshi','','卷12','有客骑骢马，江边问草堂。
远寻留药价，惜别到文场。
入幕旌旗动，归轩锦绣香。
时应念衰疾，书疏及沧浪。','',''),('quantangshi-11262','徐九少尹见过','杜甫','quantangshi','','卷12','晚景孤村僻，行军数骑来。
交新徒有喜，礼厚愧无才。
赏静怜云竹，忘归步月台。
何当看花蘂，欲发照江梅。','',''),('quantangshi-11263','范二员外邈吴十侍御郁特枉驾阙展待聊寄此','杜甫','quantangshi','','卷12','暂往比邻去，空闻二妙归。
幽栖诚简略，衰白已光辉。
野外贫家远，村中好客稀。
论文或不愧，肯重欵柴扉。','',''),('quantangshi-11264','王十七侍御抡许携酒至草堂奉寄此诗便请邀高三十五使君同到','杜甫','quantangshi','','卷12','老夫卧稳朝慵起，白屋寒多暖始开。
江鹳巧当幽径浴，邻鸡还过短墙来。
绣衣屡许携家酝，皂盖能忘折野梅。
戏假霜威促山简，须成一醉习池回。','',''),('quantangshi-11265','王竟携酒高亦同过共用寒字','杜甫','quantangshi','','卷12','卧病荒郊远，通行小径难。
故人能领客，携酒重相看。
自愧无鲑菜，空烦卸马鞍。
移樽劝山简，头白恐风寒。','',''),('quantangshi-11266','陪李七司马皂江上观造竹桥即日成往来之人免冬寒入水聊题短作简李公二首 一','杜甫','quantangshi','','卷12','伐竹为桥结构同，褰裳不涉往来通。
天寒白鹤归华表，日落青龙见水中。
顾我老非题柱客，知君才是济川功。
合欢却笑千年事，驱石何时到海东。','',''),('quantangshi-11267','陪李七司马皂江上观造竹桥即日成往来之人免冬寒入水聊题短作简李公二首 二','杜甫','quantangshi','','卷12','把烛成桥夜，回舟坐客时。
天高云去尽，江迥月来迟。
衰谢多扶病，招邀屡有期。
异方乘此兴，乐罢不无悲。','',''),('quantangshi-11268','李司马桥了承高使君自成都回','杜甫','quantangshi','','卷12','向来江上手纷纷，三日成功事出羣。
已传童子骑青竹，总拟桥东待使君。','',''),('quantangshi-11269','少年行二首 一','杜甫','quantangshi','','卷12','莫笑田家老瓦盆，自从盛酒长儿孙。
倾银注瓦惊人眼，共醉终同卧竹根。','',''),('quantangshi-11270','少年行二首 二','杜甫','quantangshi','','卷12','巢燕养雏浑去尽，江花结子已无多。
黄衫年少来宜数，不见堂前东逝波。','',''),('quantangshi-11271','野人送朱樱','杜甫','quantangshi','','卷12','西蜀樱桃也自红，野人相赠满筠笼。
数回细写愁仍破，万颗匀圆讶许同。
忆昨赐霑门下省，退朝擎出大明宫。
金盘玉筯无消息，此日尝新任转蓬。','',''),('quantangshi-11272','即事','杜甫','quantangshi','','卷12','百宝装腰带，真珠络臂韝。
笑时花近眼，舞罢锦缠头。','',''),('quantangshi-11273','赠花卿','杜甫','quantangshi','','卷12','锦城丝管日纷纷，半入江风半入云。
此曲秪应天上有，人间能得几回闻。','',''),('quantangshi-11274','少年行','杜甫','quantangshi','','卷12','马上谁家薄媚郎，临堦下马坐人牀。
不通姓字麤豪甚，指点银瓶索酒尝。','',''),('quantangshi-11275','观李固请司马弟山水图三首 一','杜甫','quantangshi','','卷12','简易高人意，匡牀竹火炉。
寒天留远客，碧海挂新图。
虽对连山好，贪看绝岛孤。
羣仙不愁思，冉冉下蓬壶。','',''),('quantangshi-11276','观李固请司马弟山水图三首 二','杜甫','quantangshi','','卷12','方丈浑连水，天台总映云。
人间长见画，老去恨空闻。
范蠡舟偏小，王乔鹤不羣。
此生随万物，何路出尘氛。','',''),('quantangshi-11277','观李固请司马弟山水图三首 三','杜甫','quantangshi','','卷12','高浪垂翻屋，崩崖欲压牀。
野桥分子细，沙岸绕微茫。
红浸珊瑚短，青悬薜荔长。
浮查并坐得，仙老暂相将。','',''),('quantangshi-11278','题桃树','杜甫','quantangshi','','卷12','小径升堂旧不斜，五株桃树亦从遮。
高秋总餧贫人实，来岁还舒满眼花。
帘户每宜通乳燕，儿童莫信打慈鵶。
寡妻羣盗非今日，天下车书正一家。','',''),('quantangshi-11279','萧八明府堤处觅桃栽','杜甫','quantangshi','','卷12','奉乞桃栽一百根，春前为送浣花村。
河阳县里虽无数，濯锦江边未满园。','',''),('quantangshi-11280','从韦二明府续处觅绵竹','杜甫','quantangshi','','卷12','华轩蔼蔼他年到，绵竹亭亭出县高。
江上舍前无此物，幸分苍翠拂波涛。','',''),('quantangshi-11281','凭何十一少府邕觅桤木栽','杜甫','quantangshi','','卷12','草堂堑西无树林，非子谁复见幽心。
饱闻桤木三年大，与致溪边十亩阴。','',''),('quantangshi-11282','凭韦少府班觅松树子','杜甫','quantangshi','','卷12','落落出羣非榉柳，青青不朽岂杨梅。
欲存老盖千年意，为觅霜根数寸栽。','',''),('quantangshi-11283','又于韦处乞大邑瓷盌','杜甫','quantangshi','','卷12','大邑烧瓷轻且坚，扣如哀玉锦城传。
君家白盌胜霜雪，急送茅斋也可怜。','',''),('quantangshi-11284','诣徐卿觅果栽','杜甫','quantangshi','','卷12','草堂少花今欲栽，不问绿李与黄梅。
石笋街中却归去，果园坊里为求来。','',''),('quantangshi-11285','赠别何邕','杜甫','quantangshi','','卷12','生死论交地，何由见一人。
悲君随燕雀，薄宦走风尘。
绵谷元通汉，沱江不向秦。
五陵花满眼，传语故乡春。','',''),('quantangshi-11286','赠别郑炼赴襄阳','杜甫','quantangshi','','卷12','戎马交驰际，柴门老病身。
把君诗过日，念此别惊神。
地阔峨眉晚，天高岘首春。
为于耆旧内，试觅姓庞人。','',''),('quantangshi-11287','重赠郑炼','杜甫','quantangshi','','卷12','郑子将行罢使臣，囊无一物献尊亲。
江山路远羇离日，裘马谁为感激人。','',''),('quantangshi-11288','奉和严中丞西城晚眺十韵','杜甫','quantangshi','','卷12','汲黯匡君切，廉颇出将频。
直词才不世，雄略动如神。
政简移风速，诗清立意新。
层城临暇景，绝域望余春。
旗尾蛟龙会，楼头燕雀驯。
地平江动蜀，天阔树浮秦。
帝念深分阃，军须远算缗。
花罗封蛱蝶，瑞锦送麒麟。
辞第输高义，观图忆古人。
征南多兴绪，事业暗相亲。','',''),('quantangshi-11289','严中丞枉驾见过','杜甫','quantangshi','','卷12','元戎小队出郊坰，问柳寻花到野亭。
川合东西瞻使节，地分南北任流萍。
扁舟不独如张翰，白帽还应似管宁。
寂寞江天云雾里，何人道有少微星。','',''),('quantangshi-11290','广州段功曹到得杨五长史谭书功曹却归聊寄此诗','杜甫','quantangshi','','卷12','卫青开幕府，杨仆将楼船。
汉节梅花外，春城海水边。
铜梁书远及，珠浦使将旋。
贫病他乡老，烦君万里传。','',''),('quantangshi-11291','得广州张判官叔卿书使还以诗代意','杜甫','quantangshi','','卷12','乡关胡骑远，宇宙蜀城偏。
忽得炎州信，遥从月峡传。
云深骠骑幕，夜隔孝廉船。
却寄双愁眼，相思泪点悬。','',''),('quantangshi-11292','送段功曹归广州','杜甫','quantangshi','','卷12','南海春天外，功曹几月程。
峡云笼树小，湖日落船明。
交趾丹砂重，韶州白葛轻。
幸君因旅客，时寄锦官城。','',''),('quantangshi-11293','绝句漫兴九首 一','杜甫','quantangshi','','卷12','眼见客愁愁不醒，无赖春色到江亭。
即遣花开深造次，便觉莺语太丁宁。','',''),('quantangshi-11294','绝句漫兴九首 二','杜甫','quantangshi','','卷12','手种桃李非无主，野老墙低还似家。
恰似春风相欺得，夜来吹折数枝花。','',''),('quantangshi-11295','绝句漫兴九首 三','杜甫','quantangshi','','卷12','熟知茅斋绝低小，江上燕子故来频。
衔泥点污琴书内，更接飞虫打着人。','',''),('quantangshi-11296','绝句漫兴九首 四','杜甫','quantangshi','','卷12','二月已破三月来，渐老逢春能几回。
莫思身外无穷事，且尽生前有限杯。','',''),('quantangshi-11297','绝句漫兴九首 五','杜甫','quantangshi','','卷12','肠断春江欲尽头，杖藜徐步立芳洲。
颠狂柳絮随风去，轻薄桃花逐水流。','',''),('quantangshi-11298','绝句漫兴九首 六','杜甫','quantangshi','','卷12','嬾慢无堪不出村，呼儿日在掩柴门。
苍苔浊酒林中静，碧水春风野外昏。','',''),('quantangshi-11299','绝句漫兴九首 七','杜甫','quantangshi','','卷12','糁径杨花铺白毡，点溪荷叶叠青钱。
笋根稚子无人见，沙上凫雏傍母眠。','',''),('quantangshi-11300','绝句漫兴九首 八','杜甫','quantangshi','','卷12','舍西柔桑叶可拈，江畔细麦复纤纤。
人生几何春已夏，不放香醪如蜜甜。','',''),('quantangshi-11301','绝句漫兴九首 九','杜甫','quantangshi','','卷12','隔户杨柳弱袅袅，恰似十五女儿腰。
谁谓朝来不作意，狂风挽断最长条。','',''),('quantangshi-11302','江畔独步寻花七绝句 一','杜甫','quantangshi','','卷12','江上被花恼不彻，无处告诉只颠狂。
走觅南邻爱酒伴，经旬出饮独空牀。','',''),('quantangshi-11303','江畔独步寻花七绝句 二','杜甫','quantangshi','','卷12','稠花乱蘂畏江滨，行步欹危实怕春。
诗酒尚堪驱使在，未须料理白头人。','',''),('quantangshi-11304','江畔独步寻花七绝句 三','杜甫','quantangshi','','卷12','江深竹静两三家，多事红花映白花。
报答春光知有处，应须美酒送生涯。','',''),('quantangshi-11305','江畔独步寻花七绝句 四','杜甫','quantangshi','','卷12','东望少城花满烟，百花高楼更可怜。
谁能载酒开金盏，唤取佳人舞绣筵。','',''),('quantangshi-11306','江畔独步寻花七绝句 五','杜甫','quantangshi','','卷12','黄师塔前江水东，春光嬾困倚微风。
桃花一簇开无主，可爱深红爱浅红。','',''),('quantangshi-11307','江畔独步寻花七绝句 六','杜甫','quantangshi','','卷12','黄四娘家花满蹊，千朵万朵压枝低。
留连戏蝶时时舞，自在娇莺恰恰啼。','',''),('quantangshi-11308','江畔独步寻花七绝句 七','杜甫','quantangshi','','卷12','不是爱花即肯死，只恐花尽老相催。
繁枝容易纷纷落，嫩叶商量细细开。','',''),('quantangshi-11309','三绝句 一','杜甫','quantangshi','','卷12','楸树馨香倚钓矶，斩新花蘂未应飞。
不如醉里风吹尽，可忍醒时雨打稀。','',''),('quantangshi-11310','三绝句 二','杜甫','quantangshi','','卷12','门外鸬鷀去不来，沙头忽见眼相猜。
自今已后知人意，一日须来一百回。','',''),('quantangshi-11311','三绝句 三','杜甫','quantangshi','','卷12','无数春笋满林生，柴门密掩断人行。
会须上番看成竹，客至从嗔不出迎。','',''),('quantangshi-11312','戏为六绝句 一','杜甫','quantangshi','','卷12','庾信文章老更成，凌云健笔意纵横。
今人嗤点流传赋，不觉前贤畏后生。','',''),('quantangshi-11313','戏为六绝句 二','杜甫','quantangshi','','卷12','杨王卢骆当时体，轻薄为文哂未休。
尔曹身与名俱灭，不废江河万古流。','',''),('quantangshi-11314','戏为六绝句 三','杜甫','quantangshi','','卷12','从使卢王操翰墨，劣于汉魏近风骚。
龙文虎脊皆君驭，历块过都见尔曹。','',''),('quantangshi-11315','戏为六绝句 四','杜甫','quantangshi','','卷12','才力应难夸数公，凡今谁是出羣雄。
或看翡翠兰苕上，未掣鲸鱼碧海中。','',''),('quantangshi-11316','戏为六绝句 五','杜甫','quantangshi','','卷12','不薄今人爱古人，清词丽句必为邻。
窃攀屈宋宜方驾，恐与齐梁作后尘。','',''),('quantangshi-11317','戏为六绝句 六','杜甫','quantangshi','','卷12','未及前贤更勿疑，递相祖述复先谁。
别裁伪体亲风雅，转益多师是汝师。','',''),('quantangshi-11318','江头四咏 丁香','杜甫','quantangshi','','卷12','丁香体柔弱，乱结枝犹垫。
细叶带浮毛，疎花披素艳。
深栽小斋后，庶近幽人占。
晚堕兰麝中，休怀粉身念。','',''),('quantangshi-11319','江头四咏 栀子','杜甫','quantangshi','','卷12','栀子比众木，人间诚未多。
于身色有用，与道气伤和。
红取风霜实，青看雨露柯。
无情移得汝，贵在映江波。','',''),('quantangshi-11320','江头四咏 鸂鶒','杜甫','quantangshi','','卷12','故使笼宽织，须知动损毛。
看云莫怅望，失水任呼号。
六翮曾经剪，孤飞卒未高。
且无鹰隼虑，留滞莫辞劳。','',''),('quantangshi-11321','江头四咏 花鸭','杜甫','quantangshi','','卷12','花鸭无泥滓，堦前每缓行。
羽毛知独立，黑白太分明。
不觉羣心妒，休牵众眼惊。
稻粱霑汝在，作意莫先鸣。','',''),('quantangshi-11322','畏人','杜甫','quantangshi','','卷12','早花随处发，春鸟异方啼。
万里清江上，三年落日低。
畏人成小筑，褊性合幽栖。
门径从榛草，无心走马蹄。','',''),('quantangshi-11323','远游','杜甫','quantangshi','','卷12','贱子何人记，迷芳着处家。
竹风连野色，江沫拥春沙。
种药扶衰病，吟诗解叹嗟。
似闻胡骑走，失喜问京华。','',''),('quantangshi-11324','野望','杜甫','quantangshi','','卷12','西山白雪三奇戍，南浦清江万里桥。
海内风尘诸弟隔，天涯涕泪一身遥。
唯将迟暮供多病，未有涓埃答圣朝。
跨马出郊时极目，不堪人事日萧条。','',''),('quantangshi-11325','官池春雁二首 一','杜甫','quantangshi','','卷12','自古稻粱多不足，至今鸂鶒乱为羣。
且休怅望看春水，更恐归飞隔暮云。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-11326','官池春雁二首 二','杜甫','quantangshi','','卷12','青春欲尽急还乡，紫塞宁论尚有霜。
翅在云天终不远，力微[矰]缴绝须防。','',''),('quantangshi-11327','水槛遣心二首 一','杜甫','quantangshi','','卷12','去郭轩楹敞，无村眺望赊。
澄江平少岸，幽树晚多花。
细雨鱼儿出，微风燕子斜。
城中十万户，此地两三家。','',''),('quantangshi-11328','水槛遣心二首 二','杜甫','quantangshi','','卷12','蜀天常夜雨，江槛已朝晴。
叶润林塘密，衣干枕席清。
不堪秪老病，何得尚浮名。
浅把涓涓酒，深凭送此生。','',''),('quantangshi-11329','屏迹三首 一','杜甫','quantangshi','','卷12','用拙存吾道，幽居近物情。
桑麻深雨露，燕雀半生成。
村鼓时时急，渔舟个个轻。
杖藜从白首，心迹喜双清。','',''),('quantangshi-11330','屏迹三首 二','杜甫','quantangshi','','卷12','晚起家何事，无营地转幽。
竹光团野色，舍影漾江流。
失学从儿嬾，长贫任妇愁。
百年浑得醉，一月不梳头。','',''),('quantangshi-11331','屏迹三首 三','杜甫','quantangshi','','卷12','衰颜甘屏迹，幽事供高卧。
鸟下竹根行，龟开萍叶过。
年荒酒价乏，日并园蔬课。
犹酌甘泉歌，歌长击樽破。','',''),('quantangshi-11332','奉酬严公寄题野亭之作','杜甫','quantangshi','','卷12','拾遗曾奏数行书，嬾性从来水竹居。
奉引滥骑沙苑马，幽栖真钓锦江鱼。
谢安不倦登临费，阮籍焉知礼法疎。
枉沐旌麾出城府，草茅无径欲教锄。','',''),('quantangshi-11333','中丞严公雨中垂寄见忆一绝奉答二绝 一','杜甫','quantangshi','','卷12','雨映行宫辱赠诗，元戎肯赴野人期。
江边老病虽无力，强拟晴天理钓丝。','',''),('quantangshi-11334','中丞严公雨中垂寄见忆一绝奉答二绝 二','杜甫','quantangshi','','卷12','何日雨晴云出溪，白沙青石先无泥。
只须伐竹开荒径，倚杖穿花听马嘶。','',''),('quantangshi-11335','谢严中丞送青城山道士乳酒一瓶','杜甫','quantangshi','','卷12','山瓶乳酒下青云，气味浓香幸见分。
鸣鞭走送怜渔父，洗盏开尝对马军。','',''),('quantangshi-11336','严公仲夏枉驾草堂兼携酒馔','杜甫','quantangshi','','卷12','竹里行厨洗玉盘，花边立马簇金鞍。
非关使者征求急，自识将军礼数宽。
百年地辟柴门逈，五月江深草阁寒。
看弄渔舟移白日，老农何有罄交欢。','',''),('quantangshi-11337','严公厅宴同咏蜀道画图','杜甫','quantangshi','','卷12','日临公馆静，画满地图雄。
劒阁星桥北，松州雪岭东。
华夷山不断，吴蜀水相通。
兴与烟霞会，清樽幸不空。','',''),('quantangshi-11338','奉送严公入朝十韵','杜甫','quantangshi','','卷12','鼎湖瞻望远，象阙宪章新。
四海犹多难，中原忆旧臣。
与时安反侧，自昔有经纶。
感激张天步，从容静塞尘。
南图回羽翮，北极捧星辰，漏鼓还思昼，宫莺罢啭春。
空留玉帐术，愁杀锦城人。
阁道通丹地，江潭隐白苹。
此生那老蜀，不死会归秦。
公若登台辅，临危莫爱身。','',''),('quantangshi-11339','送严侍郎到绵州同登杜使君江楼','杜甫','quantangshi','','卷12','野兴每难尽，江楼延赏心。
归朝送使节，落景惜登临。
稍稍烟集渚，微微风动襟。
重船依浅濑，轻鸟度层阴。
槛峻背幽谷，窗虚交茂林。
灯光散远近，月彩静高深。
城拥朝来客，天横醉后参。
穷途衰谢意，苦调短长吟。
此会共能几，诸孙贤至今。
不劳朱户闭，自待白河沈。','',''),('quantangshi-11340','奉济驿重送严公四韵','杜甫','quantangshi','','卷12','远送从此别，青山空复情。
几时杯重把，昨夜月同行。
列郡讴歌惜，三朝出入荣。
江村独归处，寂寞养残生。','',''),('quantangshi-11341','送梓州李使君之任','杜甫','quantangshi','','卷12','籍甚黄丞相，能名自颍川。
近看除刺史，还喜得吾贤。
五马何时到，双鱼会早传。
老思筇竹杖，冬要锦衾眠。
不作临岐恨，惟听举最先。
火云挥汗日，山驿醒心泉。
遇害陈公殒，于今蜀道怜。
君行射洪县，为我一潸然。','',''),('quantangshi-11342','巴西驿亭观江涨呈窦使君','杜甫','quantangshi','','卷12','宿雨南江涨，波涛乱远峰。
孤亭凌喷薄，万井逼舂容。
霄汉愁高鸟，泥沙困老龙。
天边同客舍，携我豁心胸。','',''),('quantangshi-11343','九日登梓州城','杜甫','quantangshi','','卷12','伊昔黄花酒，如今白发翁。
追欢筋力异，望远岁时同。
弟妹悲歌里，朝廷醉眼中。
兵戈与关塞，此日意无穷。','',''),('quantangshi-11344','九日奉寄严大夫','杜甫','quantangshi','','卷12','九日应愁思，经时冒险艰。
不眠持汉节，何路出巴山。
小驿香醪嫩，重岩细菊斑。
遥知簇鞍马，回首白云间。','',''),('quantangshi-11345','黄草','杜甫','quantangshi','','卷12','黄草峡西船不归，赤甲山下行人稀。
秦中驿使无消息，蜀道兵戈有是非。
万里秋风吹锦水，谁家别泪湿罗衣。
莫愁劒阁终堪据，闻道松州已被围。','',''),('quantangshi-11346','怀旧','杜甫','quantangshi','','卷12','地下苏司业，情亲独有君。
那因丧乱后，便有死生分。
老罢知明镜，悲来望白云。
自从失词伯，不复更论文。','',''),('quantangshi-11347','所思','杜甫','quantangshi','','卷12','郑老身仍窜，台州信所传。
为农山涧曲，卧病海云边。
世已疎儒素，人犹乞酒钱。
徒劳望牛斗，无计劚龙泉。','',''),('quantangshi-11348','不见','杜甫','quantangshi','','卷12','不见李生久，佯狂真可哀。
世人皆欲杀，吾意独怜才。
敏捷诗千首，飘零酒一杯。
匡山读书处，头白好归来。','',''),('quantangshi-11349','题玄武禅师屋壁','杜甫','quantangshi','','卷12','何年顾虎头，满壁画瀛州。
赤日石林气，青天江海流。
锡飞常近鹤，杯度不惊鸥。
似得庐山路，真随惠远游。','',''),('quantangshi-11350','客夜','杜甫','quantangshi','','卷12','客睡何曾着，秋天不肯明。
卷帘残月影，高枕远江声。
计拙无衣食，途穷仗友生。
老妻书数纸，应悉未归情。','',''),('quantangshi-11351','客亭','杜甫','quantangshi','','卷12','秋窗犹曙色，落木更天风。
日出寒山外，江流宿雾中。
圣朝无弃物，老病已成翁。
多少残生事，飘零似转蓬。','',''),('quantangshi-11352','秋尽','杜甫','quantangshi','','卷12','秋尽东行且未回，茅斋寄在少城隈。
篱边老却陶潜菊，江上徒逢袁绍杯。
雪岭独看西日落，劒门犹阻北人来。
不辞万里长为客，怀抱何时得好开。','',''),('quantangshi-11353','陪王侍御宴通泉东山野亭','杜甫','quantangshi','','卷12','江水东流去，清樽日复斜。
异方同宴赏，何处是京华。
亭景临山水，村烟对浦沙。
狂歌过于胜，得醉即为家。','',''),('quantangshi-11354','野望','杜甫','quantangshi','','卷12','金华山北涪水西，仲冬风日始凄凄。
山连越巂蟠三蜀，水散巴渝下五溪。
独鹤不知何事舞，饥乌似欲向人啼。
射洪春酒寒仍绿，目极伤神谁为携。','',''),('quantangshi-11355','闻官军收河南河北','杜甫','quantangshi','','卷12','劒外忽传收蓟北，初闻涕泪满衣裳。
却看妻子愁何在，漫卷诗书喜欲狂。
白日放歌须纵酒，青春作伴好还乡。
即从巴峡穿巫峡，便下襄阳向洛阳。','',''),('quantangshi-11356','涪江泛舟送韦班归京','杜甫','quantangshi','','卷12','追饯同舟日，伤春一水间。
飘零为客久，衰老羡君还。
花远重重树，云轻处处山。
天涯故人少，更益鬓毛斑。','',''),('quantangshi-11357','春日梓州登楼二首 一','杜甫','quantangshi','','卷12','行路难如此，登楼望欲迷。
身无却少壮，迹有但羇栖。
江水流城郭，春风入鼓鞞。
双双新燕子，依旧已衔泥。','',''),('quantangshi-11358','春日梓州登楼二首 二','杜甫','quantangshi','','卷12','天畔登楼眼，随春入故园。
战场今始定，移柳更能存。
厌蜀交游冷，思吴胜事繁。
应须理舟楫，长啸下荆门。','',''),('quantangshi-11359','郪城西原送李判官兄武判官弟赴成都府','杜甫','quantangshi','','卷12','凭高送所亲，久坐惜芳辰。
远水非无浪，他山自有春。
野花随处发，官柳着行新。
天际伤愁别，离筵何太频。','',''),('quantangshi-11360','泛江送魏十八仓曹还京因寄岑中允参范郎中季明','杜甫','quantangshi','','卷12','迟日深春水，轻舟送别筵。
帝乡愁绪外，春色泪痕边。
见酒须相忆，将诗莫浪传。
若逢岑与范，为报各衰年。','',''),('quantangshi-11361','送路六侍御入朝','杜甫','quantangshi','','卷12','童稚情亲四十年，中间消息两茫然。
更为后会知何地，忽漫相逢是别筵。
不分桃花红胜锦，生憎柳絮白于绵。
劒南春色还无赖，触忤愁人到酒边。','',''),('quantangshi-11362','泛江送客','杜甫','quantangshi','','卷12','二月频送客，东津江欲平。
烟花山际重，舟楫浪前轻。
泪逐劝杯下，愁连吹笛生。
离筵不隔日，那得易为情。','',''),('quantangshi-11363','上牛头寺','杜甫','quantangshi','','卷12','青山意不尽，衮衮上牛头。
无复能拘碍，真成浪出游。
花浓春寺静，竹细野池幽。
何处莺啼切，移时独未休。','',''),('quantangshi-11364','望牛头寺','杜甫','quantangshi','','卷12','牛头见鹤林，梯径绕幽深。
春色浮山外，天河宿殿阴。
传灯无白日，布地有黄金。
休作狂歌老，回看不住心。','',''),('quantangshi-11365','上兜率寺','杜甫','quantangshi','','卷12','兜率知名寺，真如会法堂。
江山有巴蜀，栋宇自齐梁。
庾信哀虽久，何颙好不忘。
白牛车远近，且欲上慈航。','',''),('quantangshi-11366','望兜率寺','杜甫','quantangshi','','卷12','树密当山径，江深隔寺门。
霏霏云气重，闪闪浪花飜。
不复知天大，空余见佛尊。
时应清盥罢，随喜给孤园。','',''),('quantangshi-11367','甘园','杜甫','quantangshi','','卷12','春日清江岸，千甘二顷园。
青云羞叶密，白雪避花繁。
结子随边使，开筒近至尊。
后于桃李熟，终得献金门。','',''),('quantangshi-11368','数陪李梓州泛江有女乐在诸舫戏为艳曲二首赠李 一','杜甫','quantangshi','','卷12','上客回空骑，佳人满近船。
江清歌扇底，野旷舞衣前。
玉袖凌风并，金壶隐浪偏。
竞将明媚色，偷眼艳阳天。','',''),('quantangshi-11369','数陪李梓州泛江有女乐在诸舫戏为艳曲二首赠李 二','杜甫','quantangshi','','卷12','白日移歌袖，清霄近笛牀。
翠眉萦度曲，云鬓俨分行。
立马千山暮，回舟一水香。
使君自有妇，莫学野鸳鸯。','',''),('quantangshi-11370','登牛头山亭子','杜甫','quantangshi','','卷12','路出双林外，亭窥万井中。
江城孤照日，山谷远含风。
兵革身将老，关河信不通。
犹残数行泪，忍对百花丛。','',''),('quantangshi-11371','陪李梓州王阆州苏遂州李果州四使君登惠义寺','杜甫','quantangshi','','卷12','春日无人境，虚空不住天。
莺花随世界，楼阁寄山巅。
迟暮身何得，登临意惘然。
谁能解金印，潇洒共安禅。','',''),('quantangshi-11372','送何侍御归朝','杜甫','quantangshi','','卷12','舟楫诸侯饯，车舆使者归。
山花相映发，水鸟自孤飞。
春日垂霜鬓，天隅把绣衣。
故人从此去，寥落寸心违。','',''),('quantangshi-11373','江亭送眉州辛别驾升之','杜甫','quantangshi','','卷12','柳影含云幕，江波近酒壶。
异方惊会面，终宴惜征途。
沙晚低风蝶，天晴喜浴凫。
别离伤老大，意绪日荒芜。','',''),('quantangshi-11374','涪城县香积寺官阁','杜甫','quantangshi','','卷12','寺下春江深不流，山腰官阁迥添愁。
含风翠壁孤云细，背日丹枫万木稠。
小院回廊春寂寂，浴凫飞鹭晚悠悠。
诸天合在藤萝外，昏黑应须到上头。','',''),('quantangshi-11375','戏题寄上汉中王三首 一','杜甫','quantangshi','','卷12','西汉亲王子，成都老客星。
百年双白鬓，一别五秋萤。
忍断杯中物，秪看座右铭。
不能随皂盖，自醉逐浮萍。','',''),('quantangshi-11376','戏题寄上汉中王三首 二','杜甫','quantangshi','','卷12','策杖时能出，王门异昔游。
已知嗟不起，未许醉相留。
蜀酒浓无敌，江鱼美可求。
终思一酩酊，净扫雁池头。','',''),('quantangshi-11377','戏题寄上汉中王三首 三','杜甫','quantangshi','','卷12','羣盗无归路，衰颜会远方。
尚怜诗警策，犹记酒颠狂。
鲁卫弥尊重，徐陈略丧亡。
空余枚叟在，应念早升堂。','',''),('quantangshi-11378','陪章留后侍御宴南楼','杜甫','quantangshi','','卷12','绝域长夏晚，兹楼清宴同。
朝廷烧栈北，鼓角满天东。
屡食将军第，仍骑御史骢。
本无丹竈术，那免白头翁。
寇盗狂歌外，形骸痛饮中。
野云低渡水，檐雨细随风。
出号江城黑，题诗蜡炬红。
此身醒[复]醉，不拟哭途穷。','',''),('quantangshi-11379','台上','杜甫','quantangshi','','卷12','改席台能迥，留门月复光。
云行遗暑湿，山谷进风凉。
老去一杯足，谁怜屡舞长。
何须把官烛，似恼鬓毛苍。','',''),('quantangshi-11380','送王十五判官扶侍还黔中','杜甫','quantangshi','','卷12','大家东征逐子回，风生洲渚锦帆开。
青青竹笋迎船出，日日江鱼入馔来。
离别不堪无限意，艰危深仗济时才。
黔阳信使应稀少，莫怪频频劝酒杯。','',''),('quantangshi-11381','倦夜','杜甫','quantangshi','','卷12','竹凉浸卧内，野月满庭隅。
重露成涓滴，稀星乍有无。
暗飞萤自照，水宿鸟相呼。
万事干戈里，空悲清夜徂。','',''),('quantangshi-11382','悲秋','杜甫','quantangshi','','卷12','凉风动万里，羣盗尚纵横。
家远传书日，秋来为客情。
秋窥高鸟过，老逐众人行。
始欲投三峡，何由见两京。','',''),('quantangshi-11383','对雨','杜甫','quantangshi','','卷12','莽莽天涯雨，江边独立时。
不愁巴道路，恐湿汉旌旗。
雪岭防秋急，绳桥战胜迟。
西戎甥舅礼，未敢背恩私。','',''),('quantangshi-11384','警急','杜甫','quantangshi','','卷12','才名旧楚将，妙略拥兵机。
玉垒虽传檄，松州会解围。
和亲知拙计，公主漫无归。
青海今谁得，西戎实饱飞。','',''),('quantangshi-11385','王命','杜甫','quantangshi','','卷12','汉北豺狼满，巴西道路难。
血埋诸将甲，骨断使臣鞍。
牢落新烧栈，苍茫旧筑坛。
深怀喻蜀意，恸哭望王官。','',''),('quantangshi-11386','征夫','杜甫','quantangshi','','卷12','十室几人在，千山空自多。
路衢唯见哭，城市不闻歌。
漂梗无安地，衔枚有荷戈。
官军未通蜀，吾道竟如何。','',''),('quantangshi-11387','有感五首 一','杜甫','quantangshi','','卷12','将帅蒙恩泽，兵戈有岁年。
至今劳圣主，何以报皇天。
白骨新交战，云台旧拓边乘槎断消息，无处觅张骞。','',''),('quantangshi-11388','有感五首 二','杜甫','quantangshi','','卷12','幽蓟余虵豕，干坤尚虎狼。
诸侯春不贡，使者日相望。
慎勿吞青海，无劳问越裳。
大君先息战，归马华山阳。','',''),('quantangshi-11389','有感五首 三','杜甫','quantangshi','','卷12','洛下舟车入，天中贡赋均。
日闻红粟腐，寒待翠华春。
莫取金汤固，长令宇宙新。
不过行俭德，盗贼本王臣。','',''),('quantangshi-11390','有感五首 四','杜甫','quantangshi','','卷12','丹桂风霜急，青梧日夜凋。
由来强干地，未有不臣朝。
受钺亲贤往，卑宫制诏遥。
终依古封建，岂独听箫韶。','',''),('quantangshi-11391','有感五首 五','杜甫','quantangshi','','卷12','盗灭人还乱，兵残将自疑。
登坛名绝假，报主尔何迟。
领郡輙无色，之官皆有词。
愿闻哀痛诏，端拱问疮痍。','',''),('quantangshi-11392','送元二适江左','杜甫','quantangshi','','卷12','乱后今相见，秋深复远行。
风尘为客日，江海送君情。
晋室丹阳尹，公孙白帝城。
经过自爱惜，取次莫论兵。','',''),('quantangshi-11393','章梓州水亭','杜甫','quantangshi','','卷12','城晚通云雾，亭深到芰荷。
吏人桥外少，秋水席边多。
近属淮王至，高门蓟子过。
荆州爱山简，吾醉亦长歌。','',''),('quantangshi-11394','翫月呈汉中王','杜甫','quantangshi','','卷12','夜深露气清，江月满江城。
浮客转危坐，归舟应独行。
关山同一照，乌鹊自多惊。
欲得淮王术，风吹晕已生。','',''),('quantangshi-11395','戏作寄上汉中王二首 一','杜甫','quantangshi','','卷12','云里不闻双雁过，掌中贪见一珠新。
秋风袅袅吹江汉，只在他乡何处人。','',''),('quantangshi-11396','戏作寄上汉中王二首 二','杜甫','quantangshi','','卷12','谢安舟楫风还起，梁苑池台雪欲飞。
杳杳东山携汉妓，泠泠修竹待王归。','',''),('quantangshi-11397','投简梓州幕府兼简韦十郎官','杜甫','quantangshi','','卷12','幕下郎官安稳无，从来不奉一行书。
固知贫病人须弃，能使韦郎迹也疎。','',''),('quantangshi-11398','登高','杜甫','quantangshi','','卷12','风急天高猨啸哀，渚清沙白鸟飞回。
无边落木萧萧下，不尽长江衮衮来。
万里悲秋常作客，百年多病独登台。
艰难苦恨繁霜鬓，潦倒新停浊酒杯。','',''),('quantangshi-11399','九日','杜甫','quantangshi','','卷12','去年登高郪县北，今日重在涪江滨。
苦遭白发不相放，羞见黄花无数新。
世乱郁郁久为客，路难悠悠常傍人。
酒阑却忆十年事，肠断骊山清路尘。','',''),('quantangshi-11400','遣愤','杜甫','quantangshi','','卷12','闻道花门将，论功未尽归。
自从收帝里，谁复总戎机。
蜂虿终怀毒，雷霆可震威。
莫令鞭血地，再湿汉臣衣。','',''),('quantangshi-11401','章梓州橘亭饯成都窦少尹','杜甫','quantangshi','','卷12','秋日野亭千橘香，玉盘锦席高云凉。
主人送客何所作，行酒赋诗殊未央。
衰老应为难离别，贤声此去有辉光。
预传籍籍新京尹，青史无劳数赵张。','',''),('quantangshi-11402','送陵州路使君赴任','杜甫','quantangshi','','卷12','王室比多难，高官皆武臣。
幽燕通使者，岳牧用词人。
国待贤良急，君当拔擢新。
佩刀成气象，行盖出风尘。
战伐干坤破，疮痍府库贫。
众僚宜洁白，万役但平均。
霄汉瞻佳士，泥途任此身。
秋天正摇落，回首大江滨。','',''),('quantangshi-11403','薄暮','杜甫','quantangshi','','卷12','江水长流地，山云薄暮时。
寒花隐乱草，宿鸟择深枝。
旧国见何日，高秋心苦悲。
人生不再好，鬓发白成丝。','',''),('quantangshi-11404','西山三首 一','杜甫','quantangshi','','卷12','彝界荒山顶，蕃州积雪边。
筑城依白帝，转粟上青天。
蜀将分旗鼓，羌兵助井泉。
西戎背和好，杀气日相缠。','',''),('quantangshi-11405','西山三首 二','杜甫','quantangshi','','卷12','辛苦三城戍，长防万里秋。
烟尘浸火井，雨雪闭松州。
风动将军幕，天寒使者裘。
漫山贼营垒，回首得无忧。','',''),('quantangshi-11406','西山三首 三','杜甫','quantangshi','','卷12','子弟犹深入，关城未解围。
蚕崖铁马瘦，灌口米船稀。
辩士安边策，元戎决胜威。
今朝乌鹊喜，欲报凯歌归。','',''),('quantangshi-11407','薄游','杜甫','quantangshi','','卷12','淅淅风生砌，团团日隐墙。
遥空秋雁灭，半岭暮云长。
病叶多先坠，寒花只暂香。
巴城添泪眼，今夜复清光。','',''),('quantangshi-11408','赠韦赞善别','杜甫','quantangshi','','卷12','扶病送君发，自怜犹不归。
秪应尽客泪，复作掩荆扉。
江汉故人少，音书从此稀。
往还二十载，岁晚寸心违。','',''),('quantangshi-11409','送李卿哗','杜甫','quantangshi','','卷12','王子思归日，长安已乱兵。
霑衣问行在，走马向承明。
暮景巴蜀僻，春风江汉清。
晋山虽自弃，魏阙尚含情。','',''),('quantangshi-11410','绝句','杜甫','quantangshi','','卷12','江边踏青罢，回首见旌旗。
风起春城暮，高楼鼓角悲。','',''),('quantangshi-11411','城上','杜甫','quantangshi','','卷12','草满巴西绿，空城白日长。
风吹花片片，春动水茫茫。
八骏随天子，羣臣从武皇。
遥闻出巡守，早晚徧遐荒。','',''),('quantangshi-11412','舍弟占归草堂检校聊示此诗','杜甫','quantangshi','','卷12','久客应吾道，相随独尔来。
孰知江路近，频为草堂回。
鹅鸭宜长数，柴荆莫浪开。
东林竹影薄，腊月更须栽。','',''),('quantangshi-11413','伤春五首 一','杜甫','quantangshi','','卷12','天下兵虽满，春光日自浓。
西京疲百战，北阙任羣凶。
关塞三千里，烟花一万重。
蒙尘清路急，御宿且谁供。
殷复前王道，周迁旧国容。
蓬莱足云气，应合总从龙。','',''),('quantangshi-11414','伤春五首 二','杜甫','quantangshi','','卷12','鸎入新年语，花开满故枝。
天青风卷幔，草碧水通池。
牢落官军速，萧条万事危。
鬓毛元自白，泪点向来垂。
不是无兄弟，其如有别离。
巴山春色静，北望转逶迤。','',''),('quantangshi-11415','伤春五首 三','杜甫','quantangshi','','卷12','日月还相鬬，星辰屡合围。
不成诛执法，焉得变危机。
大角缠兵气，钩陈出帝畿。
烟尘昏御道，耆旧把天衣。
行在诸军阙，来朝大将稀。
贤多隐屠钓，王肯载同归。','',''),('quantangshi-11416','伤春五首 四','杜甫','quantangshi','','卷12','再有朝廷乱，难知消息真。
近传王在洛，复道使归秦。
夺马悲公主，登车泣贵嫔。
萧关迷北上，沧海欲东巡。
敢料安危体，犹多老大臣。
岂无嵇绍血，霑洒属车尘。','',''),('quantangshi-11417','伤春五首 五','杜甫','quantangshi','','卷12','闻说初东幸，孤儿却走多。
难分太仓粟，竞弃鲁阳戈。
胡虏登前殿，王公出御河。
得无中夜舞，谁忆大风歌。
春色生烽燧，幽人泣薜萝。
君臣重修德，犹足见时和。','',''),('quantangshi-11418','王阆州筵奉酬十一舅惜别之作','杜甫','quantangshi','','卷12','万壑树声满，千崖秋气高。
浮舟出郡郭，别酒寄江涛。
良会不复久，此生何太劳。
穷愁但有骨，羣盗尚如毛。
吾舅惜分手，使君寒赠袍。
沙头暮黄鸪，失侣自哀号。','',''),('quantangshi-11419','放船','杜甫','quantangshi','','卷12','送客苍溪县，山寒雨不开。
直愁骑马滑，故作泛舟回。
青惜峰峦过，黄知橘柚来。
江流大自在，坐稳兴悠哉。','',''),('quantangshi-11420','奉待严大夫','杜甫','quantangshi','','卷12','殊方又喜故人来，重镇还须济世才。
常怪偏裨终日待，不知旌节隔年回。
欲辞巴徼啼莺合，远下旌门去鷁催。
身老时危思会面，一生襟抱向谁开。','',''),('quantangshi-11421','奉寄高常侍','杜甫','quantangshi','','卷12','汶上相逢年颇多，飞腾无那故人何。
总戎楚蜀应全未，方驾曹刘不啻过。
今日朝廷须汲黯，中原将帅忆廉颇。
天涯春色催迟暮，别泪遥添锦水波。','',''),('quantangshi-11422','奉寄章十侍御','杜甫','quantangshi','','卷12','淮海维扬一俊人，金章紫绶照青春。
指麾能事回天地，训练强兵动鬼神。
湘西不得归关羽，河内犹宜借寇恂。
朝觐从容问幽仄，勿云江汉有垂纶。','',''),('quantangshi-11423','将赴荆南寄别李劒州','杜甫','quantangshi','','卷12','使君高义驱今古，寥落三年坐劒州。
但见文翁能化俗，焉知李广未封侯。
路经灧滪双蓬鬓，天入沧浪一钓舟。
戎马相逢更何日，春风回首仲宣楼。','',''),('quantangshi-11424','奉寄别马巴州','杜甫','quantangshi','','卷12','勋业终归马伏波，功曹非复汉萧何。
扁舟系缆沙边久，南国浮云水上多。
独把鱼竿终远去，难随鸟翼一相过。
知君未爱春湖色，兴在骊驹白玉珂。','',''),('quantangshi-11425','泛江','杜甫','quantangshi','','卷12','方舟不用楫，极目总无波。
长日容杯酒，深江净绮罗。
乱离还奏乐，飘泊且听歌。
故国流清渭，如今花正多。','',''),('quantangshi-11426','陪王使君晦日泛江就黄家亭子二首 一','杜甫','quantangshi','','卷12','山豁何时断，江平不肯流。
稍知花改岸，始验鸟随舟。
结束多红粉，欢娱恨白头。
非君爱人客，晦日更添愁。','',''),('quantangshi-11427','陪王使君晦日泛江就黄家亭子二首 二','杜甫','quantangshi','','卷12','有径金沙软，无人碧草芳。
野畦连蛱蝶，江槛俯鸳鸯。
日晚烟花乱，风生锦绣香。
不须吹急管，衰老易悲伤。','',''),('quantangshi-11428','南征','杜甫','quantangshi','','卷12','春岸桃花水，云帆枫树林。
偷生长避地，适远更霑襟。
老病南征日，君恩北望心。
百年歌自苦，未见有知音。','',''),('quantangshi-11429','久客','杜甫','quantangshi','','卷12','羁旅知交态，淹留见俗情。
衰颜聊自哂，小吏最相轻。
去国哀王粲，伤时哭贾生。
狐狸何足道，豺虎正纵横。','',''),('quantangshi-11430','春远','杜甫','quantangshi','','卷12','肃肃花絮晚，菲菲红素轻。
日长唯鸟雀，春远独柴荆。
数有关中乱，何曾劒外清。
故乡归不得，地入亚夫营。','',''),('quantangshi-11431','暮寒','杜甫','quantangshi','','卷12','雾隐平郊树，风含广岸波。
沈沈春色静，惨惨暮寒多。
戍鼓犹长击，林鸎遂不歌。
忽思高宴会，朱袖拂云和。','',''),('quantangshi-11432','双燕','杜甫','quantangshi','','卷12','旅食惊双燕，衔泥入此堂。
应同避燥湿，且复过炎凉。
养子风尘际，来时道路长。
今秋天地在，吾亦离殊方。','',''),('quantangshi-11433','百舌','杜甫','quantangshi','','卷12','百舌来何处，重重祗报春。
知音兼众语，整翮岂多身。
花密藏难见，枝高听转新。
过时如发口，君侧有谗人。','',''),('quantangshi-11434','地隅','杜甫','quantangshi','','卷12','江汉山重阻，风云地一隅。
年年非故物，处处是穷途。
丧乱秦公子，悲凉楚大夫。
平生心已折，行路日荒芜。','',''),('quantangshi-11435','游子','杜甫','quantangshi','','卷12','巴蜀愁谁语，吴门兴杳然。
九江春草外，三峡暮帆前。
厌就成都卜，休为吏部眠。
蓬莱如可到，衰白问羣仙。','',''),('quantangshi-11436','归梦','杜甫','quantangshi','','卷12','道路时通塞，江山日寂寥。
偷生唯一老，伐叛已三朝。
雨急青枫暮，云深黑水遥。
梦归归未得，不用楚辞招。','',''),('quantangshi-11437','江亭王阆州筵饯萧遂州','杜甫','quantangshi','','卷12','离亭非旧国，春色是他乡。
老畏歌声断，愁随舞曲长。
二天开宠饯，五马烂生光。
川路风烟接，俱宜下凤皇。','',''),('quantangshi-11438','绝句二首 一','杜甫','quantangshi','','卷12','迟日江山丽，春风花草香。
泥融飞燕子，沙暖睡鸳鸯。','',''),('quantangshi-11439','绝句二首 二','杜甫','quantangshi','','卷12','江碧鸟逾白，山青花欲燃。','',''),('quantangshi-11440','滕王亭子','杜甫','quantangshi','','卷12','君王台榭枕巴山，万丈丹梯尚可攀。
春日鸎啼修竹里，仙家犬吠白云间。
清江锦石伤心丽，嫩蘂浓花满目班。
人到于今歌出牧，来游此地不知还。','',''),('quantangshi-11441','玉台观','杜甫','quantangshi','','卷12','中天积翠玉台遥，上帝高居绛节朝。
遂有冯夷来击鼓，始知嬴女善吹箫。
江光隐见鼋鼍窟，石势参差乌鹊桥。
更肯红颜生羽翼，便应黄发老渔樵。','',''),('quantangshi-11442','滕王亭子','杜甫','quantangshi','','卷12','寂寞春山路，君王不复行。
古墙犹竹色，虚阁自松声。
鸟雀荒村暮，云霞过客情。
尚思歌吹入，千骑把霓旌。','',''),('quantangshi-11443','玉台观','杜甫','quantangshi','','卷12','浩劫因王造，平台访古游。
彩云萧史驻，文字鲁恭留。
宫阙通羣帝，干坤到十洲。
人传有笙鹤，时过此山头。','',''),('quantangshi-11444','渡江','杜甫','quantangshi','','卷12','春江不可渡，二月已风涛。
舟楫欹斜疾，鱼龙偃卧高。
渚花兼素锦，汀草乱青袍。
戏问垂纶客，悠悠见汝曹。','',''),('quantangshi-11445','喜雨','杜甫','quantangshi','','卷12','南国旱无雨，今朝江出云。
入空才漠漠，洒迥已纷纷。
巢燕高飞尽，林花润色分。
晚来声不绝，应得夜深闻。','',''),('quantangshi-11446','送韦郎司直归成都','杜甫','quantangshi','','卷12','窜身来蜀地，同病得韦郎。
天下干戈满，江边岁月长。
别筵花欲暮，春日鬓俱苍。
为问南溪竹，抽梢合过墙。','',''),('quantangshi-11447','将赴成都草堂途中有作先寄严郑公五首 一','杜甫','quantangshi','','卷12','得归茅屋赴成都，直为文翁再剖符。
但使闾阎还揖让，敢论松竹久荒芜。
鱼知丙穴由来美酒忆郫筒不用酤。
五马旧曾谙小径，几回书札待潜夫。','',''),('quantangshi-11448','将赴成都草堂途中有作先寄严郑公五首 二','杜甫','quantangshi','','卷12','处处青江带白苹，故园犹得见残春。
雪山斥候无兵马，锦里逢迎有主人。
休怪儿童延俗客，不教鹅鸭恼比邻。
习池未觉风流尽，况复旌州赏更新。','',''),('quantangshi-11449','将赴成都草堂途中有作先寄严郑公五首 三','杜甫','quantangshi','','卷12','竹寒沙碧浣花溪，菱刺藤梢咫尺迷。
过客径须愁出入，居人不自解东西。
书签药里封蛛网，野店山桥送马蹄。
岂藉荒庭春草色，先判一饮醉如泥。','',''),('quantangshi-11450','将赴成都草堂途中有作先寄严郑公五首 四','杜甫','quantangshi','','卷12','常苦沙崩损药栏，也从江槛落风湍。
新松恨不高千尺，恶竹应须斩万竿。
生理祗凭黄阁老，衰颜欲付紫金丹。
三年奔走空皮骨，信有人间行路难。','',''),('quantangshi-11451','将赴成都草堂途中有作先寄严郑公五首 五','杜甫','quantangshi','','卷12','锦官城西生事微，乌皮几在还思归。
昔去为忧乱兵入，今来已恐邻人非。
侧身天地更怀古，回首风尘甘息机。
共说总戎云鸟阵，不妨游子芰荷衣。','',''),('quantangshi-11452','别房太尉墓','杜甫','quantangshi','','卷12','他乡复行役，驻马别孤坟。
近泪无干土，低空有断云。
对碁陪谢傅，把劒觅徐君。
唯见林花落，鸎啼送客闻。','',''),('quantangshi-11453','自阆州领妻子却赴蜀州山行三首 一','杜甫','quantangshi','','卷12','汨汨避羣盗，悠悠经十年。
不成向南国，复作游西川。
物役水虚照，魂伤山寂然。
我生无倚着，尽室畏途边。','',''),('quantangshi-11454','自阆州领妻子却赴蜀州山行三首 二','杜甫','quantangshi','','卷12','长林偃风色，回复意犹迷。
衫裛翠微润，马衔青草嘶。
栈县斜避石，桥断却寻溪。
何日干戈尽，飘飘愧老妻。','',''),('quantangshi-11455','自阆州领妻子却赴蜀州山行三首 三','杜甫','quantangshi','','卷12','行色递隐见，人烟时有无。
仆夫穿竹语，稚子入云呼。
转石惊魑魅，抨弓落狖鼯。
真供一笑乐，似欲慰穷途。','',''),('quantangshi-11456','山馆','杜甫','quantangshi','','卷12','南国昼多雾，北风天正寒。
路危行木杪，身远宿云端。
山鬼吹灯灭，厨人语夜阑。
鸡鸣问前馆，世乱敢求安。','',''),('quantangshi-11457','行次盐亭县卿题四韵奉简严遂州蓬州两使君谘议诸昆季','杜甫','quantangshi','','卷12','马首见盐亭，高山拥县青。
云溪花淡淡，春郭水泠泠。
全蜀多名士，严家聚德星。
长歌意无极，好为老夫听。','',''),('quantangshi-11458','倚杖','杜甫','quantangshi','','卷12','看花虽郭内，倚杖即溪边。
山县早休市，江桥春聚船。
狎鸥轻白浪，归雁喜青天。
物色兼生意，凄凉忆去年。','',''),('quantangshi-11459','陪王汉州留杜绵州泛房公西湖','杜甫','quantangshi','','卷12','旧相恩追后，春池赏不稀。
阙庭分未到，舟楫有光辉。
豉化莼丝熟，刀鸣[鲙]缕飞。
使君双皂盖，滩浅正相依。','',''),('quantangshi-11460','舟前小鹅儿','杜甫','quantangshi','','卷12','鹅儿黄似酒，对酒爱新鹅。
引颈嗔船逼，无行乱眼多。
翅开遭宿雨，力小困沧波。
客散层城暮，狐狸奈若何。','',''),('quantangshi-11461','得房公池鹅','杜甫','quantangshi','','卷12','房相西亭鹅一羣，眠沙泛浦白于云。
凤皇池上应回首，为报笼随王右军。','',''),('quantangshi-11462','答杨梓州','杜甫','quantangshi','','卷12','闷到房公池水头，坐逢杨子镇东州。
却向青溪不相见，回船应载阿戎游。','',''),('quantangshi-11463','登楼','杜甫','quantangshi','','卷12','花近高楼伤客心，万方多难此登临。
锦江春色来天地，玉垒浮云变古今。
北极朝廷终不改，西山寇盗莫相侵。
可怜后主还祠庙，日暮聊为梁甫吟。','',''),('quantangshi-11464','春归','杜甫','quantangshi','','卷12','苔径临江竹，茅檐覆地花。
别来频甲子，倏忽又春华。
倚杖看孤石，倾壶就浅沙。
远鸥浮水静，轻燕受风斜。
世路虽多梗，吾生亦有涯。
此身醒复醉，乘兴即为家。','',''),('quantangshi-11465','归雁','杜甫','quantangshi','','卷12','东来万里客，乱定几年归。
肠断江城雁，高高正北飞。','',''),('quantangshi-11466','赠王二十四侍御契四十韵','杜甫','quantangshi','','卷12','往往虽相见，飘飘愧此身。
不关轻绂冕，俱是避风尘。
一别星桥夜，三移斗柄春。
败亡非赤壁，奔走为黄巾。
子去何潇洒，余藏异隐沦。
书成无过雁，衣故有县鹑。
恐惧行装数，伶俜卧疾频。
晓鸎工迸泪，秋月解伤神。
会面嗟黧黑，含凄话苦辛。
接舆还入楚，王粲不归秦。
锦里残丹竈，花溪得钓纶。
消中祗自惜，晚起索谁亲。
伏柱闻周史，乘槎有汉臣。
鸳鸿不易狎，龙虎未宜驯。
客则挂冠至，交非倾盖新。
由来意气合，直取性情真。
浪迹同生死，无心耻贱贫。
偶然存蔗芋，幸各对松筠。
麤饭依他日，穷愁怪此辰。
女长裁褐稳，男大卷书匀。
漰口江如练，蚕崖雪似银。
名园当翠巘，野棹没青苹。
屡喜王侯宅，时邀江海人。
追随不觉晚，欵曲动弥旬。
但使芝兰秀，何烦栋宇邻。
山阳无俗物，郑驿正留宾。
出入并鞍马，光辉参席珍。
重游先主庙，更历少城闉。
石镜通幽魄，琴台隐绛唇。
送终惟粪土，结爱独荆榛。
置酒高林下，观碁积水滨。
区区甘累趼，稍稍息劳筋。
网聚粘圆鲫，丝繁煮细莼。
长歌敲柳瘿，小睡凭藤轮。
农月须知课，田家敢忘勤。
浮生难去食，良会惜清晨。
列国兵戈暗，今王德教淳。
要闻除䝟貐，休作画麒麟。
洗眼看轻薄，虚怀任屈伸。
莫令胶漆地，万古重雷陈。','',''),('quantangshi-11467','寄董卿嘉荣十韵','杜甫','quantangshi','','卷12','闻道君牙帐，防秋近赤霄。
下临千雪岭，却背五绳桥。
海内久戎服，京师今晏朝。
犬羊曾烂熳，宫阙尚萧条。
猛将宜尝胆，龙泉必在腰。
黄图遭污辱，月窟可焚烧。
会取干戈利，无令斥候骄。
居然双捕虏，自是一嫖姚。
落日思轻骑，高天忆射雕。
云台画形像，皆为扫氛妖。','',''),('quantangshi-11468','寄司马山人十二韵','杜甫','quantangshi','','卷12','关内昔分袂，天边今转蓬。
驱驰不可说，谈笑偶然同。
道术曾留意，先生早击蒙。
家家迎蓟子，处处识壶公。
长啸峨嵋北，潜行玉垒东。
有时骑猛虎，虚室使仙童。
发少何劳白，颜衰肯更红。
望云悲轗轲，毕景羡冲融。
丧乱形仍役，凄凉信不通。
悬旌要路口，倚劒短亭中。
永作殊方客，残生一老翁。
相哀骨可换，亦遣驭清风。','',''),('quantangshi-11469','黄河二首 一','杜甫','quantangshi','','卷12','黄河北岸海西军，椎鼓鸣钟天下闻。
铁马长鸣不知数，胡人高鼻动成羣。','',''),('quantangshi-11470','黄河二首 二','杜甫','quantangshi','','卷12','黄河西岸是吾蜀，欲须供给家无粟。
愿驱众蔗戴君王，混一车书弃金玉。','',''),('quantangshi-11471','寄李十四员外布十二韵','杜甫','quantangshi','','卷12','名参汉望苑，职述景题舆。
巫峡将之郡，荆门好附书。
远行无自苦，内热比何如。
正是炎天阔，那堪野馆疎。
黄牛平驾浪，画鷁上凌虚。
试待盘涡歇，方期解缆初。
闷能过小径，自为摘嘉蔬。
渚柳元幽僻，村花不扫除。
宿阴繁素柰，过雨乱红蕖。
寂寂夏先晚，泠泠风有余。
江清心可莹，竹冷发堪梳。
直作移巾几，秋帆发弊庐。','',''),('quantangshi-11472','归来','杜甫','quantangshi','','卷12','客里有所过，归来知路难。
开门野鼠走，散帙壁鱼干。
洗杓开新酝，低头拭小盘。
凭谁给麴蘖，细酌老江干。','',''),('quantangshi-11473','王录事许修草堂赀不到聊小诘','杜甫','quantangshi','','卷12','为嗔王录事，不寄草堂赀。
昨属愁春雨，能忘欲漏时。','',''),('quantangshi-11474','寄邛州崔录事','杜甫','quantangshi','','卷12','邛州崔录事，闻在果园坊。
久待无消息，终朝有底忙。
应愁江树远，怯见野亭荒。
浩荡风尘外，谁知酒熟香。','',''),('quantangshi-11475','过故斛斯校书庄二首 一','杜甫','quantangshi','','卷12','此老已云殁，邻人嗟亦休。
竟无宣室召，徒有茂陵求。
妻子寄他食，园林非昔游。
空余繐帷在，淅淅野风秋。','',''),('quantangshi-11476','过故斛斯校书庄二首 二','杜甫','quantangshi','','卷12','燕入非旁舍，鸥归祗故池。
断桥无复板，卧柳自生枝。
遂有山阳作，多惭鲍叔知。
素交零落尽，白首泪双垂。','',''),('quantangshi-11477','立秋雨院中有作','杜甫','quantangshi','','卷12','山云行绝塞，大火复西流。
飞雨动华屋，萧萧梁栋秋。
穷途愧知己，暮齿借前筹。
已费清晨谒，那成长者谋。
解衣开北户，高枕对南楼。
树湿风凉进，江喧水气浮。
礼宽心有适，节爽病微瘳。
主将归调鼎，吾还访旧丘。','',''),('quantangshi-11478','奉和严大夫军城早秋','杜甫','quantangshi','','卷12','秋风褭褭动高旌，玉帐分弓射虏营。
已收滴博云间戍，更夺蓬婆雪外城。','',''),('quantangshi-11479','院中晚晴怀西郭茅舍','杜甫','quantangshi','','卷12','幕府秋风日夜清，澹云疎雨过高城。
叶心朱实看时落，阶面青苔先自生。
复有楼台衔暮景，不劳钟鼓报新晴。
浣花溪里花饶笑，肯信吾兼吏隐名。','',''),('quantangshi-11480','到村','杜甫','quantangshi','','卷12','碧涧虽多雨，秋沙先少泥。
蛟龙引子过，荷芰逐花低。
老去参戎幕，归来散马蹄。
稻粱须就列，榛草即相迷。
蓄积思江汉，疎顽惑町畦。
稍酬知己分，还入故林栖。','',''),('quantangshi-11481','宿府','杜甫','quantangshi','','卷12','清秋幕府井梧寒，独宿江城蜡炬残。
永夜角声悲自语，中天月色好谁看。
风尘荏苒音书绝，关塞萧条行路难。
已忍伶俜十年事，强移栖息一枝安。','',''),('quantangshi-11482','遣闷奉呈严公二十韵','杜甫','quantangshi','','卷12','白水鱼竿客，清秋鹤发翁。
胡为来幕下，秪合在舟中。
黄卷真如律，青袍也自公。
老妻忧坐[痹]，幼女问头风。
平地专欹倒，分曹失异同。
礼甘衰力就，义忝上官通。
畴昔论诗蚤，光辉仗钺雄。
宽容存性拙，剪拂念途穷。
露裛思藤架，烟霏想桂丛。
信然龟触网，直作鸟窥笼。
西岭纡村北，南江遶舍东。
竹皮寒旧翠，椒实雨新红。
浪簸船应坼，杯干瓮即空。
藩篱生野径，斤斧任樵童。
束缚酬知己，蹉跎効小忠。
周防期稍稍，太简遂悤悤。
晓入朱扉启，昏归画角终。
不成寻别业，未敢息微躬。
乌鹊愁银汉，驽骀怕锦幪。
会希全物色，时放倚梧桐。','',''),('quantangshi-11483','送舍弟频赴齐州三首 一','杜甫','quantangshi','','卷12','岷岭南蛮北，徐关东海西。
此行何日到，送汝万行啼。
绝域惟高枕，清风独杖藜。
危时暂相见，衰白意都迷。','',''),('quantangshi-11484','送舍弟频赴齐州三首 二','杜甫','quantangshi','','卷12','风尘暗不开，汝去几时来。
兄弟分离苦，形容老病催。
江通一柱观，日落望乡台。','',''),('quantangshi-11485','送舍弟频赴齐州三首 三','杜甫','quantangshi','','卷12','诸姑今海畔，两弟亦山东。
去傍干戈觅，来看道路通。
短衣防战地，匹马逐秋风。
莫作俱流落，长瞻碣石鸿。','',''),('quantangshi-11486','严郑公阶下新松','杜甫','quantangshi','','卷12','弱质岂自负，移根方尔瞻。
细声闻玉帐，疎翠近珠帘。
未见紫烟集，虚蒙清露霑。
何当一百丈，欹盖拥高檐。','',''),('quantangshi-11487','严郑公宅同咏竹','杜甫','quantangshi','','卷12','绿竹半含箨，新梢才出墙。
色侵书帙晚，阴过酒樽凉。
雨洗娟娟净，风吹细细香。
但令无剪伐，会见拂云长。','',''),('quantangshi-11488','奉观严郑公厅事岷山沱江画图十韵','杜甫','quantangshi','','卷12','沱水流中座，岷山到此堂。
白波吹粉壁，青嶂插雕梁。
直讶杉松冷，兼疑菱荇香。
雪云虚点缀，沙草得微茫。
岭雁随毫末，川霓饮练光。
霏红洲蘂乱，拂黛石萝长。
暗谷非关雨，丹枫不为霜。
秋成玄圃外，景物洞庭旁。
绘事功殊绝，幽襟兴激昂。
从来谢太傅，丘壑道难忘。','',''),('quantangshi-11489','晚秋陪严郑公摩诃池泛舟','杜甫','quantangshi','','卷12','湍驶风醒酒，船回雾起堤。
高城秋自落，杂树晚相迷。
坐触鸳鸯起，巢倾翡翠低。
莫须惊白鹭，为伴宿清溪。','',''),('quantangshi-11490','初冬','杜甫','quantangshi','','卷12','垂老戎衣窄，归休寒色深。
渔舟上急水，猎火着高林。
日有习池醉，愁来梁甫吟。
干戈未偃息，出处遂何心。','',''),('quantangshi-11491','至后','杜甫','quantangshi','','卷12','冬至至后日初长，远在劒南思洛阳。
青袍白马有何意，金谷铜驼非故乡。
梅花欲开不自觉，棣蕚一别永相望。
愁极本凭诗遣兴，诗成吟咏转凄凉。','',''),('quantangshi-11492','正月三日归溪上有作简院内诸公','杜甫','quantangshi','','卷12','野外堂依竹，篱边水向城。
蚁浮仍腊味，鸥泛已春声。
药许隣人劚，书从稚子擎。
白头趋幕府，深觉负平生。','',''),('quantangshi-11493','弊庐遣兴奉寄严公','杜甫','quantangshi','','卷12','野水平桥路，春沙映竹村。
风轻粉蝶喜，花暖蜜蜂喧。
把酒宜深酌，题诗好细论。
府中瞻暇日，江上忆词源。
迹忝朝廷旧，情依节制尊。
还思长者辙，恐避席为门。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-11494','春日江村五首 一','杜甫','quantangshi','','卷12','农务村村急，春流岸岸深。
干坤万里眼，时序百年心。
茅屋还堪赋，桃源自可寻。
艰难贱生理，飘泊到如今。','',''),('quantangshi-11495','春日江村五首 二','杜甫','quantangshi','','卷12','迢递来三蜀，蹉跎有六年。
客身逢故旧，发兴自林泉。
过懒从衣结，频游任履穿。
藩篱无限景，恣意买江天。','',''),('quantangshi-11496','春日江村五首 三','杜甫','quantangshi','','卷12','种竹交加翠，栽桃烂熳红。
经心石镜月，到面雪山风。
赤管随王命，银章付老翁。
岂知牙齿落，名玷荐贤中。','',''),('quantangshi-11497','春日江村五首 四','杜甫','quantangshi','','卷12','扶病垂朱绂，归休步紫苔。
郊扉存晚计，幕府愧羣材。
燕外晴丝卷，鸥边水叶开。
隣家送鱼鼈，问我数能来。','',''),('quantangshi-11498','春日江村五首 五','杜甫','quantangshi','','卷12','羣盗哀王粲，中年召贾生。
登楼初有作，前席竟为荣。
宅入先贤传，才高处士名。
异时怀二子，春日复含情。','',''),('quantangshi-11499','绝句六首 一','杜甫','quantangshi','','卷12','日出篱东水，云生舍北泥。
竹高鸣翡翠，沙僻舞鵾鸡。','',''),('quantangshi-11500','绝句六首 二','杜甫','quantangshi','','卷12','蔼蔼花蘂乱，飞飞蜂蝶多。
幽栖身懒动，客至欲如何。','',''),('quantangshi-11501','绝句六首 三','杜甫','quantangshi','','卷12','凿井交椶叶，开渠断竹根。
扁舟轻褭缆，小径曲通村。','',''),('quantangshi-11502','绝句六首 四','杜甫','quantangshi','','卷12','急雨捎溪足，斜晖转树腰。
隔巢黄鸟竝，翻藻白鱼跳。','',''),('quantangshi-11503','绝句六首 五','杜甫','quantangshi','','卷12','舍下笋穿壁，庭中藤刺檐。
地晴丝冉冉，江白草纤纤。','',''),('quantangshi-11504','绝句六首 六','杜甫','quantangshi','','卷12','江动月移石，溪虚云傍花。
鸟栖知故道，帆过宿谁家。','',''),('quantangshi-11505','绝句四首 一','杜甫','quantangshi','','卷12','堂西长笋别开门，堑北行椒却背村。
梅熟许同朱老吃，松高拟对阮生论。','',''),('quantangshi-11506','绝句四首 二','杜甫','quantangshi','','卷12','欲作鱼梁云复湍，因惊四月雨声寒。
青溪先有蛟龙窟，竹石如山不敢安。','',''),('quantangshi-11507','绝句四首 三','杜甫','quantangshi','','卷12','两个黄鹂鸣翠柳，一行白鹭上青天。
窗含西岭千秋雪，门泊东吴万里船。','',''),('quantangshi-11508','绝句四首 四','杜甫','quantangshi','','卷12','药条药甲润青青，色过棕亭入草亭。
苗满空山慙取誉，根居隙地怯成形。','',''),('quantangshi-11509','哭严仆射归榇','杜甫','quantangshi','','卷12','素幔随流水，归舟返旧京。
老亲如宿昔，部曲异平生。
风送蛟龙雨，天长骠骑营。
一哀三峡暮，遗后见君情。','',''),('quantangshi-11510','宴戎州杨使君东楼','杜甫','quantangshi','','卷12','胜绝惊身老，情忘发兴奇。
座从歌妓密，乐任主人为。
重碧拈春酒，轻红擘荔枝。
楼高欲愁思，横笛未休吹。','',''),('quantangshi-11511','渝州候严六侍御不到先下峡','杜甫','quantangshi','','卷12','闻道乘骢发，沙边待至今。
不知云雨散，虚费短长吟。
山带乌蛮阔，江连白帝深。
船经一柱观，留眼共登临。','',''),('quantangshi-11512','拨闷','杜甫','quantangshi','','卷12','闻道云安麴米春，才倾一盏即醺人。
乘舟取醉非难事，下峡消愁定几巡。
长年三老遥怜汝，棙柁开头捷有神。
已办青钱防雇直，当令美味入吾唇。','',''),('quantangshi-11513','闻高常侍亡','杜甫','quantangshi','','卷12','归朝不相见，蜀使忽传亡。
虚历金华省，何殊地下郎。
致君丹槛折，哭友白云长。
独步诗名在，秪令故旧伤。','',''),('quantangshi-11514','宴忠州使君侄宅','杜甫','quantangshi','','卷12','出守吾家侄，殊方此日欢。
自须游阮巷，不是怕湖滩。
乐助长歌逸，杯饶旅思宽。
昔曾如意舞，牵率强为看。','',''),('quantangshi-11515','禹庙','杜甫','quantangshi','','卷12','禹庙空山里，秋风落日斜。
荒庭垂橘柚，古屋画龙蛇。
云气生虚壁，江声走白沙。
早知乘四载，疏凿控三巴。','',''),('quantangshi-11516','题忠州龙兴寺所居院壁','杜甫','quantangshi','','卷12','忠州三峡内，井邑聚云根。
小市常争米，孤城早闭门。
空看过客泪，莫觅主人恩。
淹泊仍愁虎，深居赖独园。','',''),('quantangshi-11517','旅夜书怀','杜甫','quantangshi','','卷12','细草微风岸，危樯独夜舟。
星垂平野阔，月涌大江流。
名岂文章着，官因老病休。
飘飘何所似，天地一沙鸥。','',''),('quantangshi-11518','别常征君','杜甫','quantangshi','','卷12','儿扶犹杖策，卧病一秋强。
白发少新洗，寒衣宽总长。
故人忧见及，此别泪相忘。
各逐萍流转，来书细作行。','',''),('quantangshi-11519','三绝句 一','杜甫','quantangshi','','卷12','前年渝州杀刺史，今年开州杀刺史。
羣盗相随剧虎狼，食人更肯留妻子。','',''),('quantangshi-11520','三绝句 二','杜甫','quantangshi','','卷12','二十一家同入蜀，惟残一人出骆谷。
自说二女啮臂时，回头却向秦云哭。','',''),('quantangshi-11521','三绝句 三','杜甫','quantangshi','','卷12','殿前兵马虽骁雄，纵暴略与羌浑同。
闻道杀人汉水上，妇女多在官军中。','',''),('quantangshi-11522','十二月一日三首 一','杜甫','quantangshi','','卷12','今朝腊月春意动，云安县前江可怜。
一声何处送书雁，百丈谁家上水船。
未将梅蘂惊愁眼，要取楸花媚远天。
明光起草人所羡，肺病几时朝日边。','',''),('quantangshi-11523','十二月一日三首 二','杜甫','quantangshi','','卷12','寒轻市上山烟碧，日满楼前江雾黄。
负盐出井此溪女，打鼓发船何郡郎。
新亭举目风景切，茂陵着书消渴长。
春花不愁不烂漫，楚客唯听棹相将。','',''),('quantangshi-11524','十二月一日三首 三','杜甫','quantangshi','','卷12','即看燕子入山扉，岂有黄鹂历翠微。
短短桃花临水岸，轻轻柳絮点人衣。
春来准拟开怀久，老去亲知见面稀。
他日一杯难强进，重嗟筋力故山违。','',''),('quantangshi-11525','又雪','杜甫','quantangshi','','卷12','南雪不到地，青崖霑未消。
微微向日薄，脉脉去人遥。
冬热鸳鸯病，峡深豺虎骄。
愁边有江水，焉得北之朝。','',''),('quantangshi-11526','奉汉中王手札','杜甫','quantangshi','','卷12','国有干坤大，王今叔父尊。
剖符来蜀道，归盖取荆门。
峡险通舟过，江长注海奔。
主人留上客，避暑得名园。
前后缄书报，分明馔玉恩。
天云浮绝壁，风竹在华轩。
已觉良宵永，何看骇浪翻。
入期朱邸雪，朝傍紫微垣。
枚乘文章老，河间礼乐存。
悲秋宋玉宅，失路武陵源。
淹薄俱崖口，东西异石根。
夷音迷咫尺，鬼物傍黄昏。
犬马诚为恋，狐狸不足论。
从容草奏罢，宿昔奉清罇。','',''),('quantangshi-11527','赠崔十三评事公辅','杜甫','quantangshi','','卷12','飘飘西极马，来自渥洼池。
飒飁定山桂，低徊风雨枝。
我闻龙正直，道屈尔何为。
且有元戎命，悲歌识者谁。
官联辞宂长，行路洗欹危。
脱劒主人赠，去帆春色随。
阴沈铁凤阙，教练羽林儿。
天子朝侵早，云台仗数移。
分军应供给，百姓日支离。
黠吏因封己，公才或守雌。
燕王买骏骨，渭老得熊罴。
活国名公在，拜坛羣寇疑。
冰壶动瑶碧，野水失蛟螭。
入幕诸彦集，渴贤高选宜。
骞腾坐可致，九万起于斯。
复进出矛戟，昭然开鼎彝。
会看之子贵，叹及老夫衰。
岂但江曾决，还思雾一披。
暗尘生古镜，拂匣照西施。
舅氏多人物，无慙困翮垂。','',''),('quantangshi-11528','长江二首 一','杜甫','quantangshi','','卷12','众水会涪万，瞿塘争一门。
朝宗人共挹，盗贼尔谁尊。
孤石隐如马，高萝垂饮猨。
归心异波浪，何事即飞飜。','',''),('quantangshi-11529','长江二首 二','杜甫','quantangshi','','卷12','浩浩终不息，乃知东极临。
众流归海意，万国奉君心。
色借潇湘阔，声驱灧滪深。
未辞添雾雨，接上遇衣襟。','',''),('quantangshi-11530','承闻故房相公灵榇自阆州启殡归葬东都有作二首 一','杜甫','quantangshi','','卷12','远闻房太守，归葬陆浑山。
一德兴王后，孤魂久客间。
孔明多故事，安石竟崇班。
他日嘉陵涕，仍沾楚水还。','',''),('quantangshi-11531','承闻故房相公灵榇自阆州启殡归葬东都有作二首 二','杜甫','quantangshi','','卷12','丹旐飞飞日，初传发阆州。
风尘终不解，江汉忽同流。
劒动新身匣，书归故国楼。
尽哀知有处，为客恐长休。','',''),('quantangshi-11532','云安九日郑十八携酒陪诸公宴','杜甫','quantangshi','','卷12','寒花开已尽，菊蘂独盈枝。
旧摘人频异，轻香酒蹔随。
地偏初衣裌，山拥更登危。
万国皆戎马，酣歌泪欲垂。','',''),('quantangshi-11533','答郑十七郎一绝','杜甫','quantangshi','','卷12','雨后过畦润，花残步屐迟。
把文惊小陆，好客见当时。','',''),('quantangshi-11534','将晓二首 一','杜甫','quantangshi','','卷12','石城除击柝，铁锁欲开关。
鼓角悲荒塞，星河落曙山。
巴人常小梗，蜀使动无还。
垂老孤帆色，飘飘犯百蛮。','',''),('quantangshi-11535','将晓二首 二','杜甫','quantangshi','','卷12','军吏回官烛，舟人自楚歌。
寒沙蒙薄雾，落月去清波。
壮惜身名晚，衰慙应接多。
归朝日簪笏，筋力定如何。','',''),('quantangshi-11536','怀锦水居止二首 一','杜甫','quantangshi','','卷12','军旅西征僻，风尘战伐多。
犹闻蜀父老，不忘舜讴歌。
天险终难立，柴门岂重过。
朝朝巫峡水，远逗锦江波。','',''),('quantangshi-11537','怀锦水居止二首 二','杜甫','quantangshi','','卷12','万里桥南宅，百花潭北庄。
层轩皆面水，老树饱经霜。
雪岭界天白，锦城曛日黄。
惜哉形胜地，回首一茫茫。','',''),('quantangshi-11538','子规','杜甫','quantangshi','','卷12','峡里云安县，江楼翼瓦齐。
两边山木合，终日子规啼。
眇眇春风见，萧萧夜色凄。
客愁那听此，故作傍人低。','',''),('quantangshi-11539','立春','杜甫','quantangshi','','卷12','春日春盘细生菜，忽忆两京梅发时。
盘出高门行白玉，菜传纤手送青丝。
巫峡寒江那对眼，杜陵远客不胜悲。
此身未知归定处，呼儿觅纸一题诗。','',''),('quantangshi-11540','漫成一绝','杜甫','quantangshi','','卷12','江月去人只数尺，风灯照夜欲三更。
沙头宿鹭联拳静，船尾跳鱼拨刺鸣。','',''),('quantangshi-11541','老病','杜甫','quantangshi','','卷12','老病巫山里，稽留楚客中。
药残他日裹，花发去年丛。
夜足霑沙雨，春多逆水风。
合分双赐笔，犹作一飘蓬。','',''),('quantangshi-11542','南楚','杜甫','quantangshi','','卷12','南楚青春异，暄寒早早分。
无名江上草，随意岭头云。
正月蜂相见，非时鸟共闻。
杖藜妨跃马，不是故离羣。','',''),('quantangshi-11543','寄常征君','杜甫','quantangshi','','卷12','白水青山空复春，征君晚节傍风尘。
楚妃堂上色殊众，海鹤阶前鸣向人。
万事纠纷犹绝粒，一官羇绊实藏身。
开州入夏知凉冷，不似云安毒热新。','',''),('quantangshi-11544','寄岑嘉州','杜甫','quantangshi','','卷12','不见故人十年余，不道故人无素书。
愿逢颜色关塞远，岂意出守江城居。
外江三峡且相接，斗酒新诗终日疎。
谢朓每篇堪讽诵，冯唐已老听吹嘘。
泊船秋夜经春草，伏枕青枫限玉除。
眼前所寄选何物，赠子云安双鲤鱼。','',''),('quantangshi-11545','移居夔州郭','杜甫','quantangshi','','卷12','伏枕云安县，迁居白帝城。
春知催柳别，江与放船清。
农事闻人说，山光见鸟情。
禹功饶断石，且就土微平。','',''),('quantangshi-11546','船下夔州郭宿雨湿不得上岸别王十二判官','杜甫','quantangshi','','卷12','依沙宿舸船，石濑月娟娟。
风起春灯乱，江鸣夜雨悬。
晨钟云外湿，胜地石堂烟。
柔橹轻鸥外，含凄觉汝贤。','',''),('quantangshi-11547','雨不绝','杜甫','quantangshi','','卷12','鸣雨既过渐细微，映空摇扬如丝飞。
阶前短草泥不乱，院里长条风乍稀。
舞石旋应将乳子，行云莫自湿仙衣。
眼边江舸何怱促，未待安流逆浪归。','',''),('quantangshi-11548','崔评事弟许相迎不到应虑老夫见泥雨怯出必愆佳期走笔戏简','杜甫','quantangshi','','卷12','江阁要宾许马迎，午时起坐自天明。
浮云不负青春色，细雨何孤白帝城。
身过花间霑湿好，醉于马上往来轻。
虚疑皓首冲泥怯，实少银鞍傍险行。','',''),('quantangshi-11549','宿江边阁','杜甫','quantangshi','','卷12','暝色延山径，高斋次水门。
薄云岩际宿，孤月浪中飜。
鹳鹤追飞静，豺狼得食喧。
不眠忧战伐，无力正干坤。','',''),('quantangshi-11550','夜宿西阁晓呈元二十一曹长','杜甫','quantangshi','','卷12','城暗更筹急，楼高雨雪微。
稍通绡幕霁，远带玉绳稀。
门鹊晨光起，墙乌宿处飞。
寒江流甚细，有意待人归。','',''),('quantangshi-11551','西阁口号','杜甫','quantangshi','','卷12','山木抱云稠，寒江绕上头。
雪崖才变石，风幔不依楼。
社稷堪流涕，安危在运筹。
看君话王室，感动几销忧。','',''),('quantangshi-11552','西阁雨望','杜甫','quantangshi','','卷12','楼雨霑云幔，山寒着水城。
径添沙面出，湍减石棱生。
菊蘂凄疎放，松林驻远情。
滂沱朱槛湿，万虑傍檐楹。','',''),('quantangshi-11553','不离西阁二首 一','杜甫','quantangshi','','卷12','江柳非时发，江花冷色频。
地偏应有瘴，腊近已含春。
失学从愚子，无家住老身。
不知西阁意，肯别定留人。','',''),('quantangshi-11554','不离西阁二首 二','杜甫','quantangshi','','卷12','西阁从人别，人今亦故亭。
江云飘素练，石壁断空青。
沧海先迎日，银河倒列星。
平生耽胜事，吁骇始初经。','',''),('quantangshi-11555','西阁三度期大昌严明府同宿不到','杜甫','quantangshi','','卷12','问子能来宿，今疑索故要。
匣琴虚夜夜，手板自朝朝。
金吼霜钟彻，花催腊炬销。
早凫江槛底，双影漫飘颻。','',''),('quantangshi-11556','西阁二首 一','杜甫','quantangshi','','卷12','巫山小摇落，碧色见松林。
百鸟各相命，孤云无自心。
层轩俯江壁，要路亦高深。
朱绂犹纱帽，新诗近玉琴。
功名不早立，衰病谢知音。
哀世非王粲，终然学越吟。','',''),('quantangshi-11557','西阁二首 二','杜甫','quantangshi','','卷12','嬾心似江水，日夜向沧洲。
不道含香贱，其如镊白休。
经过调碧柳，萧索倚朱楼。
毕娶何时竟，消中得自由。
豪华看古往，服食寄冥搜。
诗尽人间兴，兼须入海求。','',''),('quantangshi-11558','阁夜','杜甫','quantangshi','','卷12','岁暮阴阳催短景，天涯霜雪霁寒宵。
五更鼓角声悲壮，三峡星河影动摇。
野哭几家闻战伐，夷歌数处起渔樵。
卧龙跃马终黄土，人事依依漫寂寥。','',''),('quantangshi-11559','西阁夜','杜甫','quantangshi','','卷12','恍惚寒山暮，逶迤白雾昏。
山虚风落石，楼静月侵门。
击柝可怜子，无衣何处村。
时危关百虑，盗贼尔犹存。','',''),('quantangshi-11560','瀼西寒望','杜甫','quantangshi','','卷12','水色含羣动，朝光切太虚。
年侵频怅望，兴远一萧疎。
猨挂时相学，鸥行炯自如。
瞿唐春欲至，定卜瀼西居。','',''),('quantangshi-11561','入宅三首 一','杜甫','quantangshi','','卷12','奔峭背赤甲，断崖当白盐。
客居愧迁次，春酒渐多添。
花亚欲移竹，鸟窥新卷帘。
衰年不敢恨，胜概欲相兼。','',''),('quantangshi-11562','入宅三首 二','杜甫','quantangshi','','卷12','乱后居难定，春归客未还。
水生鱼复浦，云暖麝香山。
半顶梳头白，过眉拄杖斑。
相看多使者，一一问函关。','',''),('quantangshi-11563','入宅三首 三','杜甫','quantangshi','','卷12','宋玉归州宅，云通白帝城。
吾人淹老病，旅食岂才名。
峡口风常急，江流气不平。
只应与儿子，飘转任浮生。','',''),('quantangshi-11564','赤甲','杜甫','quantangshi','','卷12','卜居赤甲迁居新，两见巫山楚水春。
炙背可以献天子，美芹由来知野人。
荆州郑薛寄书近，蜀客郗岑非我邻。
笑接郎中评事饮，病从深酌道吾真。','',''),('quantangshi-11565','卜居','杜甫','quantangshi','','卷12','归羡辽东鹤，吟同楚执圭。
未成游碧海，着处觅丹梯。
云障宽江左，春耕破瀼西。
桃红客若至，定似昔人迷。','',''),('quantangshi-11566','暮春题瀼西新赁草屋五首 一','杜甫','quantangshi','','卷12','久嗟三峡客，再与暮春期。
百舌欲无语，繁花能几时。
谷虚云气薄，波乱日华迟。
战伐何由定，哀伤不在兹。','',''),('quantangshi-11567','暮春题瀼西新赁草屋五首 二','杜甫','quantangshi','','卷12','此邦千树橘，不见比封君。
养拙干戈际，全生麋鹿羣。
畏人江北草，旅食瀼西云。
万里巴渝曲，三年实饱闻。','',''),('quantangshi-11568','暮春题瀼西新赁草屋五首 三','杜甫','quantangshi','','卷12','彩云阴复白，锦树晓来青。
身世双蓬鬓，干坤一草亭。
哀歌时自短，醉舞为谁醒。
细雨荷锄立，江猨吟翠屏。','',''),('quantangshi-11569','暮春题瀼西新赁草屋五首 四','杜甫','quantangshi','','卷12','壮年学书劒，他日委泥沙。
事主非无禄，浮生即有涯。
高斋依药饵，绝域改春华。
丧乱丹心破，王臣未一家。','',''),('quantangshi-11570','暮春题瀼西新赁草屋五首 五','杜甫','quantangshi','','卷12','欲陈济世策，已老尚书郎。
未息豺虎鬬，空慙鸳鹭行。
时危人事急，风逆羽毛伤。
落日悲江汉，中宵泪满床。','',''),('quantangshi-11571','园','杜甫','quantangshi','','卷12','仲夏流多水，清晨向小园。
碧溪摇艇阔，朱果烂枝繁。
始为江山静，终防市井喧。
畦蔬绕茅屋，自足媚盘餐。','',''),('quantangshi-11572','竖子至','杜甫','quantangshi','','卷12','樝梨且缀碧，梅杏半传黄。
小子幽园至，轻笼熟柰香。
山风犹满把，野露及新尝。
欲寄江湖客，提携日月长。','',''),('quantangshi-11573','示獠奴阿段','杜甫','quantangshi','','卷12','山木苍苍落日曛，竹竿褭褭细泉分。
郡人入夜争余沥，竖子寻源独不闻。
病渴三更回白首，传声一注湿青云。
曾惊陶侃胡奴异，怪尔常穿虎豹羣。','',''),('quantangshi-11574','秋野五首 一','杜甫','quantangshi','','卷12','秋野日疏芜，寒江动碧虚。
系舟蛮井络，卜宅楚村墟。
枣熟从人打，葵荒欲自锄。
盘餐老夫食，分减及溪鱼。','',''),('quantangshi-11575','秋野五首 二','杜甫','quantangshi','','卷12','易识浮生理，难教一物违。
水深鱼极乐，林茂鸟知归。
吾老甘贫病，荣华有是非。
秋风吹几杖，不厌此山薇。','',''),('quantangshi-11576','秋野五首 三','杜甫','quantangshi','','卷12','礼乐攻吾短，山林引兴长。
掉头纱帽仄，曝背竹书光。
风落收松子，天寒割蜜房。
稀疎小红翠，驻屐近微香。','',''),('quantangshi-11577','秋野五首 四','杜甫','quantangshi','','卷12','远岸秋沙白，连山晚照红。
潜鳞输骇浪，归翼会高风。
砧响家家发，樵声个个同。
飞霜任青女，赐被隔南宫。','',''),('quantangshi-11578','秋野五首 五','杜甫','quantangshi','','卷12','身许麒膦画，年衰鸳鹭羣。
大江秋易盛，空峡夜多闻。
径隐千重石，帆留一片云。
儿童解蛮语，不必作参军。','',''),('quantangshi-11579','溪上','杜甫','quantangshi','','卷12','峡内淹留客，溪边四五家。
古苔生迮地，秋竹隐疎花。
塞俗人无井，山田饭有沙。
西江使船至，时复问京华。','',''),('quantangshi-11580','树间','杜甫','quantangshi','','卷12','岑寂双甘树，婆娑一院香。
交柯低几杖，垂实碍衣裳。
满岁如松碧，同时待菊黄。
几回霑叶露，乘月坐胡牀。','',''),('quantangshi-11581','课小竖鉏斫舍北果林枝蔓荒秽净讫移牀三首 一','杜甫','quantangshi','','卷12','病枕依茅栋，荒鉏净果林。
背堂资僻远，在野兴清深。
山雉防求敌，江猨应独吟。
泄云高不去，隐几亦无心。','',''),('quantangshi-11582','课小竖鉏斫舍北果林枝蔓荒秽净讫移牀三首 二','杜甫','quantangshi','','卷12','众壑生寒早，长林卷雾齐。
青虫悬就日，朱果落封泥。
薄俗防人面，全身学马蹄。
吟诗坐回首，随意葛巾低。','',''),('quantangshi-11583','课小竖鉏斫舍北果林枝蔓荒秽净讫移牀三首 三','杜甫','quantangshi','','卷12','篱弱门何向，沙虚岸只摧。
日斜鱼更食，客散鸟还来。
寒水光难定，秋山响易哀。
天涯稍曛黑，倚杖更裴回。','',''),('quantangshi-11584','寒雨朝行视园树','杜甫','quantangshi','','卷12','柴门杂树向千株，丹橘黄甘此地无。
江上今朝寒雨歇，篱中秀色画屏纡。
桃蹊李径年虽故，栀子红椒艳复殊。
鏁石藤稍元自落，倚天松骨见来枯。
林香出实垂将尽，叶蔕辞枝不重苏。
爱日恩光蒙借贷，清霜杀气得忧虞。
衰颜更觅藜床坐，缓步仍须竹杖扶。
散骑未知云阁处，啼猨僻在楚山隅。','',''),('quantangshi-11585','季秋江村','杜甫','quantangshi','','卷12','乔木村墟古，疎篱野蔓悬。
清琴将暇日，白首望霜天。
登俎黄甘重，支床锦石圆。
远游虽寂寞，难见此山川。','',''),('quantangshi-11586','小园','杜甫','quantangshi','','卷12','由来巫峡水，本自楚人家。
客病留因药，春深买为花。
秋庭风落果，瀼岸雨颓沙。
问俗营寒事，将诗待物华。','',''),('quantangshi-11587','自瀼西荆扉且移居东屯茅屋四首 一','杜甫','quantangshi','','卷12','白盐危峤北，赤甲古城东。
平地一川稳，高山四面同。
烟霜凄野日，秔稻熟天风。
人事伤蓬转，吾将守桂丛。','',''),('quantangshi-11588','自瀼西荆扉且移居东屯茅屋四首 二','杜甫','quantangshi','','卷12','东屯复瀼西，一种住青溪。
来往皆茅屋，淹留为稻畦。
市喧宜近利，林僻此无蹊。
若访衰翁语，须令剩客迷。','',''),('quantangshi-11589','自瀼西荆扉且移居东屯茅屋四首 三','杜甫','quantangshi','','卷12','道北冯都使，高斋见一川。
子能渠细石，吾亦沼清泉。
枕带还相似，柴荆即有焉。
斫畲应费日，解缆不知年。','',''),('quantangshi-11590','自瀼西荆扉且移居东屯茅屋四首 四','杜甫','quantangshi','','卷12','牢落西江外，参差北户间。
久游巴子国，卧病楚人山。
幽独移佳境，清深隔远关。
寒空见鸳鹭，回首忆朝班。','',''),('quantangshi-11591','茅堂检校收稻二首 一','杜甫','quantangshi','','卷12','香稻三秋末，平田百顷间。
喜无多屋宇，幸不碍云山。
御裌侵寒气，尝新破旅颜。
红鲜终日有，玉粒未吾悭。','',''),('quantangshi-11592','茅堂检校收稻二首 二','杜甫','quantangshi','','卷12','稻米炊能白，秋葵煮复新。
谁云滑易饱，老藉软俱匀。
种幸房州熟，苗同伊阙春。
无劳映渠盌，自有色如银。','',''),('quantangshi-11593','东屯月夜','杜甫','quantangshi','','卷12','抱疾漂萍老，防边旧谷屯。
春农亲异俗，岁月在衡门。
青女霜枫重，黄牛峡水喧。
泥留虎鬬迹，月挂客愁村。
乔木澄稀影，轻云倚细根。
数惊闻雀噪，暂睡想猨蹲。
日转东方白，风来北斗昏。
天寒不成寝，无梦寄归魂。','',''),('quantangshi-11594','东屯北崦','杜甫','quantangshi','','卷12','盗贼浮生困，诛求异俗贫。
空村惟见鸟，落日未逢人。
步壑风吹面，看松露滴身。
远山回白首，战地有黄尘。','',''),('quantangshi-11595','从驿次草堂复至东屯二首 一','杜甫','quantangshi','','卷12','峡内归田客，江边借马骑。
非寻戴安道，似向习家池。
峡险风烟僻，天寒橘柚垂。
筑场看敛积，一学楚人为。','',''),('quantangshi-11596','从驿次草堂复至东屯二首 二','杜甫','quantangshi','','卷12','短景难高卧，衰年强此身。
山家蒸栗暖，野饭射麋新。
世路知交薄，门庭畏客频。
牧童斯在眼，田父实为邻。','',''),('quantangshi-11597','暂往白帝复还东屯','杜甫','quantangshi','','卷12','复作归田去，犹残获稻功。
筑场怜穴蚁，拾穗许村童。
落杵光辉白，除芒子粒红。
加餐可扶老，仓庾慰飘蓬。','',''),('quantangshi-11598','刈稻了咏怀','杜甫','quantangshi','','卷12','稻获空云水，川平对石门。
寒风疎落木，旭日散鸡豚。
野哭初闻战，樵歌稍出村。
无家问消息，作客信干坤。','',''),('quantangshi-11599','上白帝城','杜甫','quantangshi','','卷12','城峻随天壁，楼高更女墙。
江流思夏后，风至忆襄王。
老去闻悲角，人扶报夕阳。
公孙初恃险，跃马意何长。','',''),('quantangshi-11600','上白帝城二首 一','杜甫','quantangshi','','卷12','江城含变态，一上一回新。
天欲今朝雨，山归万古春。
英雄余事业，衰迈久风尘。
取醉他乡客，相逢故国人。
兵戈犹拥蜀，赋敛强输秦。
不是烦形胜，深慙畏损神。','',''),('quantangshi-11601','上白帝城二首 二','杜甫','quantangshi','','卷12','白帝空祠庙，孤云自往来。
江山城宛转，栋宇客裴回。
勇略今何在，当年亦壮哉。
后人将酒肉，虚殿日尘埃。
谷鸟鸣还过，林花落又开。
多慙病无力，骑马入青苔。','',''),('quantangshi-11602','武侯庙','杜甫','quantangshi','','卷12','遗庙丹青落，空山草木长。
犹闻辞后主，不复卧南阳。','',''),('quantangshi-11603','八阵图','杜甫','quantangshi','','卷12','功盖三分国，名高八阵图。
江流石不转，遗恨失吞吴。','',''),('quantangshi-11604','谒先主庙','杜甫','quantangshi','','卷12','惨淡风云会，乘时各有人。
力侔分社稷，志屈偃经纶。
复汉留长策，中原仗老臣。
杂耕心未已，欧血事酸辛。
霸气西南歇，雄图历数屯。
锦江元过楚，劒阁复通秦。
旧俗存祠庙，空山立鬼神。
虚檐交鸟道，枯木半龙鳞。
竹送清溪月，苔移玉座春。
闾阎儿女换，歌舞岁时新。
绝域归舟远，荒城系马频。
如何对摇落，况乃久风尘。
孰与关张并，功临耿邓亲。
应天才不小，得士契无邻。
迟暮堪帷幄，飘零且钓缗。
向来忧国泪，寂寞洒衣巾。','',''),('quantangshi-11605','白盐山','杜甫','quantangshi','','卷12','卓立羣峰外，蟠根积水边。
他皆任厚地，尔独近高天。
白牓千家邑，清秋万估船。
词人取佳句，刻画竟谁传。','',''),('quantangshi-11606','滟滪堆','杜甫','quantangshi','','卷12','巨积水中央，江寒出水长。
沈牛答云雨，如马戒舟航。
天意存倾覆，神功接混茫。
干戈连解缆，行止忆垂堂。','',''),('quantangshi-11607','滟滪','杜甫','quantangshi','','卷12','灧滪既没孤根深，西来水多愁太阴。
江天漠漠鸟双去，风雨时时龙一吟。
舟人渔子歌回首，估客胡商泪满襟。
寄语舟航恶年少，休翻盐井横黄金。','',''),('quantangshi-11608','白帝','杜甫','quantangshi','','卷12','白帝城中云出门，白帝城下雨翻盆。
高江急峡雷霆鬬，翠木苍藤日月昏。
戎马不如归马逸，千家今有百家存。
哀哀寡妇诛求尽，恸哭秋原何处村。','',''),('quantangshi-11609','白帝城楼','杜甫','quantangshi','','卷12','江度寒山阁，城高绝塞楼。
翠屏宜晚对，白谷会深游。
急急能鸣雁，轻轻不下鸥。
彝陵春色起，渐拟放扁舟。','',''),('quantangshi-11610','晓望白帝城盐山','杜甫','quantangshi','','卷12','徐步移班杖，看山仰白头。
翠深开断壁，红远结飞楼。
日出清江望，暄和散旅愁。
春城见松雪，始拟进归舟。','',''),('quantangshi-11611','白帝城最高楼','杜甫','quantangshi','','卷12','城尖径昃旌斾愁，独立缥缈之飞楼。
峡坼云霾龙虎卧，江清日抱鼋鼍游。
扶桑西枝对断石，弱水东影随长流。
杖藜叹世者谁子，泣血迸空回白头。','',''),('quantangshi-11612','白帝楼','杜甫','quantangshi','','卷12','漠漠虚无里，连连睥睨侵。
楼光去日远，峡影入江深。
腊破思端绮，春归待一金。
去年梅柳意，还欲搅边心。','',''),('quantangshi-11613','陪诸公上白帝城宴越公堂之作','杜甫','quantangshi','','卷12','此堂存古制，城上俯江郊。
落构垂云雨，荒阶蔓草茅。
柱穿蜂溜蜜，栈缺燕添巢。
坐接春杯气，心伤艳蘂梢。
英灵如过隙，宴衎愿投胶。
莫问东流水，生涯未即抛。','',''),('quantangshi-11614','峡隘','杜甫','quantangshi','','卷12','闻说江陵府，云沙静眇然。
白鱼如切玉，朱橘不论钱。
水有远湖树，人今何处船。
青山各在眼，却望峡中天。','',''),('quantangshi-11615','诸葛庙','杜甫','quantangshi','','卷12','久游巴子国，屡入武侯祠。
竹日斜虚寝，溪风满薄帷。
君臣当共济，贤圣亦同时。
翊戴归先主，并吞更出师。
虫虵穿画壁，巫觋醉蛛丝。
歘忆吟梁父，躬耕也未迟。','',''),('quantangshi-11616','峡口二首 一','杜甫','quantangshi','','卷12','峡口大江间，西南控百蛮。
城欹连粉堞，岸断更青山。
开辟多天险，防隅一水关。
乱离闻鼓角，秋气动衰颜。','',''),('quantangshi-11617','峡口二首 二','杜甫','quantangshi','','卷12','时清关失险，世乱戟如林。
去矣英雄事，荒哉割据心。
芦花留客晚，枫树坐猨深。
疲薾烦亲故，诸侯数赐金。','',''),('quantangshi-11618','天池','杜甫','quantangshi','','卷12','天池马不到，岚壁鸟才通。
百顷青云杪，层波白石中。
郁纡腾秀气，萧瑟浸寒空。
直对巫山出，兼疑夏禹功。
鱼龙开辟有，菱芡古今同。
闻道奔雷黑，初看浴日红。
飘零神女雨，断续楚王风。
欲问支机石，如临献宝宫。
九秋惊雁序，万里狎渔翁。
更是无人处，诛茅任薄躬。','',''),('quantangshi-11619','瞿塘两崖','杜甫','quantangshi','','卷12','三峡传何处，双崖壮此门。
入天犹石色，穿水忽云根。
猱攫须髯古，蛟龙窟宅尊。
羲和冬驭近，愁畏日车翻。','',''),('quantangshi-11620','夔州歌十绝句 一','杜甫','quantangshi','','卷12','中巴之东巴东山，江水开辟流其间。
白帝高为三峡镇，夔州险过百牢关。','',''),('quantangshi-11621','夔州歌十绝句 二','杜甫','quantangshi','','卷12','白帝夔州各异城，蜀江楚峡混殊名。
英雄割据非天意，霸主并吞在物情。','',''),('quantangshi-11622','夔州歌十绝句 三','杜甫','quantangshi','','卷12','羣雄竞起问前朝，王者无外见今朝。
比讶渔阳结怨恨，元听舜日旧箫韶。','',''),('quantangshi-11623','夔州歌十绝句 四','杜甫','quantangshi','','卷12','赤甲白盐俱刺天，闾阎缭绕接山巅。
枫林橘树丹青合，复道重楼锦绣悬。','',''),('quantangshi-11624','夔州歌十绝句 五','杜甫','quantangshi','','卷12','瀼东瀼西一万家，江北江南春冬花。
背飞鹤子遗琼蘂，相趁凫雏入蒋牙。','',''),('quantangshi-11625','夔州歌十绝句 六','杜甫','quantangshi','','卷12','东屯稻畦一百顷，北有涧水通青苗。
晴浴狎鸥分处处，雨随神女下朝朝。','',''),('quantangshi-11626','夔州歌十绝句 七','杜甫','quantangshi','','卷12','蜀麻吴盐自古通，万斛之舟行若风。
长年三老长歌里，白昼摊钱高浪中。','',''),('quantangshi-11627','夔州歌十绝句 八','杜甫','quantangshi','','卷12','忆昔咸阳都市合，山水之图张卖时。
巫峡曾经宝屏见，楚宫犹对碧峰疑。','',''),('quantangshi-11628','夔州歌十绝句 九','杜甫','quantangshi','','卷12','武侯祠堂不可忘，中有松柏参天长。
干戈满地客愁破，云日如火炎天凉。','',''),('quantangshi-11629','夔州歌十绝句 十','杜甫','quantangshi','','卷12','阆风玄圃与蓬壶，中有高堂天下无。
借问夔州压何处，峡门江腹拥城隅。','',''),('quantangshi-11630','上卿翁请修武侯庙遗像缺落时崔卿权夔州','杜甫','quantangshi','','卷12','大贤为政即多闻，刺史真符不必分。
尚有西郊诸葛庙，卧龙无首对江濆。','',''),('quantangshi-11631','偶题','杜甫','quantangshi','','卷12','文章千古事，得失寸心知。
作者皆殊列，名声岂浪垂。
骚人嗟不见，汉道盛于斯。
前辈飞腾入，余波绮丽为。
后贤兼旧列，历代各清规。
法自儒家有，心从弱岁疲。
永怀江左逸，多病邺中奇。
騄骥皆良马，骐驎带好儿。
车轮徒已斵，堂构惜仍亏。
漫作潜夫论，虚传幼妇碑。
缘情慰漂荡，抱疾屡迁移。
经济慙长策，飞栖假一枝。
尘沙傍蜂虿，江峡绕蛟螭。
萧瑟唐虞远，联翩楚汉危。
圣朝兼盗贼，异俗更喧卑。
郁郁星辰劒，苍苍云雨池。
两都开幕府，万宇插军麾。
南海残铜柱，东风避月支。
音书恨乌鹊，号怒怪熊罴。
稼穑分诗兴，柴荆学土宜。
故山迷白阁，秋水隐黄陂。
不敢要佳句，愁来赋别离。','',''),('quantangshi-11632','秋兴八首 一','杜甫','quantangshi','','卷12','玉露凋伤枫树林，巫山巫峡气萧森。
江间波浪兼天涌，塞上风云接地阴。
丛菊两开他日泪，孤舟一系故园心。
寒衣处处催刀尺，白帝城高急暮砧。','',''),('quantangshi-11633','秋兴八首 二','杜甫','quantangshi','','卷12','夔府孤城落日斜，每依南斗望京华。
听猨实下三声泪，奉使虚随八月查。
画省香炉违伏枕，山楼粉堞隐悲笳。
请看石上藤萝月，已暎洲前芦荻花。','',''),('quantangshi-11634','秋兴八首 三','杜甫','quantangshi','','卷12','千家山郭静朝晖，一日江楼坐翠微。
信宿渔人还泛泛，清秋燕子故飞飞。
匡衡抗疏功名薄，刘向传经心事违。
同学少年多不贱，五陵衣马自轻肥。','',''),('quantangshi-11635','秋兴八首 四','杜甫','quantangshi','','卷12','闻道长安似弈棊，百年世事不胜悲。
王侯第宅皆新主，文武衣冠异昔时。
直北关山金鼓振，征西车马羽书迟。
鱼龙寂寞秋江冷，故国平居有所思。','',''),('quantangshi-11636','秋兴八首 五','杜甫','quantangshi','','卷12','蓬莱宫阙对南山，承露金茎霄汉间。
西望瑶池降王母，东来紫气满函关。
云移雉尾开宫扇，日绕龙鳞识圣颜。
一卧沧江惊岁晚，几回青琐照朝班。','',''),('quantangshi-11637','秋兴八首 六','杜甫','quantangshi','','卷12','瞿唐峡口曲江头，万里风烟接素秋。
花萼夹城通御气，芙蓉小苑入边愁。
朱帘绣柱围黄鹤，锦缆牙樯起白鸥。
回首可怜歌舞地，秦中自古帝王州。','',''),('quantangshi-11638','秋兴八首 七','杜甫','quantangshi','','卷12','昆明池水汉时功，武帝旌旗在眼中。
织女机丝虚月夜，石鲸鳞甲动秋风。
波漂菰米沈云黑，露冷莲房坠粉红。
关塞极天唯鸟道，江湖满地一渔翁。','',''),('quantangshi-11639','秋兴八首 八','杜甫','quantangshi','','卷12','昆吾御宿自逶迤，紫阁峰阴入渼陂。
香稻啄余鹦鹉粒，碧梧栖老凤皇枝。
佳人拾翠春相问，仙侣同舟晚更移。
彩笔昔游干气象，白头吟望苦低垂。','',''),('quantangshi-11640','咏怀古迹五首 一','杜甫','quantangshi','','卷12','支离东北风尘际，漂泊西南天地间。
三峡楼台淹日月，五溪衣服共云山。
羯胡事主终无赖，词客衰时且未还。
庾信平生最萧瑟，暮年诗赋动江关。','',''),('quantangshi-11641','咏怀古迹五首 二','杜甫','quantangshi','','卷12','摇落深知宋玉悲，风流儒雅亦吾师。
怅望千秋一洒泪，萧条异代不同时。
江山故宅空文藻，云雨荒台岂梦思。
最是楚宫俱泯灭，舟人指点到今疑。','',''),('quantangshi-11642','咏怀古迹五首 三','杜甫','quantangshi','','卷12','羣山万壑赴荆门，生长明妃尚有村。
一去紫台连朔漠，独留青冢向黄昏。
画图省识春风面，环佩空归月夜魂。
千载琵琶作胡语，分明怨恨曲中论。','',''),('quantangshi-11643','咏怀古迹五首 四','杜甫','quantangshi','','卷12','蜀主窥吴幸三峡，崩年亦在永安宫。
翠华想像空山里，玉殿虚无野寺中。
古庙杉松巢水鹤，岁时伏腊走村翁。
武侯祠屋常邻近，一体君臣祭祀同。','',''),('quantangshi-11644','咏怀古迹五首 五','杜甫','quantangshi','','卷12','诸葛大名垂宇宙，宗臣遗像肃清高。
三分割据纡筹策，万古云霄一羽毛。
伯仲之间见伊吕，指挥若定失萧曹。
福移汉祚难恢复，志决身歼军务劳。','',''),('quantangshi-11645','诸将五首 一','杜甫','quantangshi','','卷12','汉朝陵暮对南山，胡虏千秋尚入关。
昨日玉鱼蒙葬地，早时今盌出人间。
见愁汗马西戎逼，曾闪朱旗北斗殷。
多少材官守泾渭，将军且莫破愁颜。','',''),('quantangshi-11646','诸将五首 二','杜甫','quantangshi','','卷12','韩公本意筑三城，拟绝天骄拔汉旌。
岂谓尽烦回纥马，翻然远救朔方兵胡来不觉潼关隘，龙起犹闻晋水清。
独使至尊忧社稷，诸君何以答升平。','',''),('quantangshi-11647','诸将五首 三','杜甫','quantangshi','','卷12','洛阳宫殿化为烽，休道秦关百二重。
沧海未全归禹贡，蓟门何处尽尧封。
朝廷衮职虽多预，天下军储不自供。
稍喜临边王相国，肯销金甲事春农。','',''),('quantangshi-11648','诸将五首 四','杜甫','quantangshi','','卷12','回首扶桑铜柱标，冥冥氛祲未全销。
越裳翡翠无消息，南海明珠久寂寥。
殊锡曾为大司马，总戎皆插侍中貂。
炎风朔雪天王地，只在忠臣翊圣朝。','',''),('quantangshi-11649','诸将五首 五','杜甫','quantangshi','','卷12','锦江春色逐人来，巫峡清秋万壑哀。
正忆往时严仆射，共迎中使望乡台。
主恩前后三持节，军令分明数举杯。
西蜀地形天下险，安危须仗出羣材。','',''),('quantangshi-11650','秋日夔府咏怀奉寄郑监李宾客一百韵','杜甫','quantangshi','','卷12','绝塞乌蛮北，孤城白帝边。
飘零仍百里，消渴已三年。
雄劒鸣开匣，羣书满系船。
乱离心不展，衰谢日萧然。
筋力妻孥问，菁华岁月迁。
登临多物色，陶冶赖诗篇。
峡束沧江起，岩排石树圆。
拂云霾楚气，朝海蹴吴天。
煮井为盐速，烧畲度地偏。
有时惊叠嶂，何处觅平川。
鸂鶒双双舞，猕猿垒垒悬。
碧萝长似带，锦石小如钱。
春草何曾歇，寒花亦可怜。
猎人吹戍火，野店引山泉。
唤起搔头急，扶行几屐穿。
两京犹薄产，四海绝随肩。
幕府初交辟，郎官幸备员。
瓜时犹旅寓，萍泛苦夤缘。
药饵虚狼藉，秋风洒静便。
开襟驱瘴疠，明目扫云烟。
高宴诸侯礼，佳人上客前。
哀筝伤老大，华屋艳神仙。
南内开元曲，常时弟子传。
法歌声变转，满座涕潺湲。
吊影夔州僻，回肠杜曲煎。
即今龙厩水，莫带犬戎膻。
耿贾扶王室，萧曹拱御筵。
乘威灭蜂虿，戮力効鹰鹯。
旧物森犹在，凶徒恶未悛。
国须行战伐，人忆止戈鋋。
奴仆何知礼，恩荣错与权。
胡星一彗孛，黔首逐拘挛。
哀痛丝纶切，烦苛法令蠲。
业成陈始王，兆喜出于畋。
宫禁经纶密，台阶翊戴全。
熊罴载吕望，鸿雁美周宣。
侧听中兴主，长吟不世贤。
音徽一柱数，道里下牢千。
郑李光时论，文章并我先。
阴何尚清省，沈宋歘联翩。
律比昆仑竹，音知燥湿弦。
风流俱善价，惬当久忘筌。
置驿常如此，登龙盖有焉。
虽云隔礼数，不敢坠周旋。
高视收人表，虚心味道玄。
马来皆汗血，鹤唳必青田。
羽翼商山起，蓬莱汉阁连。
管宁纱帽净，江令锦袍鲜。
东郡时题壁，南湖日扣舷。
远游凌绝境，佳句染华牋。
每欲孤飞去，徒为百虑牵。
生涯已寥落，国步乃迍邅。
衾枕成芜没，池塘作弃捐。
别离忧怛怛，伏腊涕涟涟。
露菊班丰镐，秋蔬影涧瀍。
共谁论昔事，几处有新阡。
富贵空回首，喧争嬾着鞭。
兵戈尘漠漠，江汉月娟娟。
局促看秋燕，萧疎听晚蝉。
雕虫蒙记忆，烹鲤问沈绵。
卜羡君平杖，偷存子敬毡。
囊虚把钗钏，米尽坼花钿。
甘子阴凉叶，茅斋八九椽。
阵图沙北岸，市暨瀼西巅。
羁绊心常折，栖迟病即痊。
紫收岷岭芋，白种陆池莲。
色好梨胜颊，穰多栗过拳。
勅厨唯一味，求饱或三鳣。
儿去看鱼笱，人来坐马鞯。
缚柴门窄窄，通竹溜涓涓。
堑抵公畦棱，村依野庙壖。
缺篱将棘拒，倒石赖藤缠。
借问频朝谒，何如稳醉眠。
谁云行不逮，自觉坐能坚。
雾雨银章涩，馨香粉署妍。
紫鸾无近远，黄雀任翩翾。
困学违从众，明公各勉旃。
声华夹宸极，早晚到星躔。
恳谏留匡鼎，诸儒引服虔。
不逢输鲠直，会是正陶甄。
宵旰忧虞轸，黎元疾苦骈。
云台终日画，青简为谁编。
行路难何有，招寻兴已专。
由来具飞檝，蹔拟控鸣弦。
身许双峰寺，门求七祖禅。
落帆追宿昔，衣褐向真诠。
安石名高晋，昭王客赴燕。
途中非阮籍，查上似张骞。
披拂云宁在，淹留景不延。
风期终破浪，水怪莫飞涎。
他日辞神女，伤春怯杜鹃。
淡交随聚散，泽国绕回旋。
本自依迦叶，何曾藉偓佺。
炉峯生转盻，橘井尚高褰。
东走穷归鹤，南征尽跕鸢。
晚闻多妙教，卒践塞前愆。
顾凯丹青列，头陀琬琰镌。
众香深黯黯，几地肃芊芊。
勇猛为心极，清羸任体孱。
金蓖空刮眼，镜象未离铨。','',''),('quantangshi-11651','赠李八祕书别三十韵','杜甫','quantangshi','','卷12','往时中补右，扈跸上元初。
反气凌行在，妖星下直庐。
六龙瞻汉阙，万骑略姚墟。
玄朔回天步，神都忆帝车。
一戎才汗马，百姓免为鱼。
通籍蟠螭印，差肩列凤舆。
事殊迎代邸，喜异赏朱虚。
寇盗方归顺，干坤欲晏如。
不才同补衮，奉诏许牵裾。
鸳鹭叨云阁，麒麟滞玉除。
文园多病后，中散旧交疎。
飘泊哀相见，平生意有余。
风烟巫峡远，台榭楚宫虚。
触目非论故，新文尚起予。
清秋凋碧柳，别浦落红蕖。
消息多旗帜，经过叹里闾。
战连唇齿国，军急羽毛书。
幕府筹频问，山家药正锄。
台星入朝谒，使节有吹嘘。
西蜀灾长弭，南翁愤始摅。
对敭抏士卒，干没费仓储。
势藉兵须用，功无礼忽诸。
御鞍金騕褭，宫砚玉蟾蜍。
拜舞银钩落，恩波锦帕舒。
此行非不济，良友昔相于。
去斾依颜色，沿流想疾徐。
沈绵疲井臼，倚薄似樵渔。
乞米烦佳客，钞诗听小胥。
杜陵斜晚照，潏水带寒淤。
莫话清溪发，萧萧白暎梳。','',''),('quantangshi-11652','寄刘峡州伯华使君四十韵','杜甫','quantangshi','','卷12','峡内多云雨，秋来尚郁蒸。
远山朝白帝，深水谒彝陵。
迟暮嗟为客，西南喜得朋。
哀猨更起坐，落雁失飞腾。
伏枕思琼树，临轩对玉绳。
青松寒不落，碧海阔逾澄。
昔岁文为理，羣公价尽增。
家声同令闻，时论以儒称。
太后当朝肃，多才接迹升。
翠虚捎魍魉，丹极上鵾鹏。
宴引春壶满，恩分夏簟冰。
雕章五色笔，紫殿九华灯。
学并卢王敏，书偕褚薛能。
老兄真不坠，小子独无承。
近有风流作，聊从月继征。
放蹄知赤骥，捩翅服苍鹰。
卷轴来何晚，襟怀庶可凭。
会期吟讽数，益破旅愁凝。
雕刻初谁料，纤毫欲自矜。
神融蹑飞动，战胜洗侵凌。
妙取筌蹄弃，高宜百万层。
白头遗恨在，青竹几人登。
回首追谈笑，劳歌局寝兴。
年华纷已矣，世故莽相仍。
刺史诸侯贵，郎官列宿应。
潘生骖阁远，黄霸玺书增。
乳贙号攀石，饥鼯诉落藤。
药囊亲道士，灰劫问胡僧。
凭久乌皮折，簪稀白帽棱。
林居看蚁穴，野食行鱼罾。
筋力交雕丧，飘零免战兢。
皆为百里宰，正似六安丞。
姹女萦新裹，丹砂冷旧秤。
但求椿寿永，莫虑杞天崩。
炼骨调情性，张兵挠棘矜。
养生终自惜，伐数必全惩。
政术甘疎诞，词场愧服膺。
展怀诗诵鲁，割爱酒如渑。
咄咄宁书字，冥冥欲避矰。
江湖多白鸟，天地有青蝇。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-11653','夔府书怀四十韵','杜甫','quantangshi','','卷12','昔罢河西尉，初兴蓟北师。
不才名位晚，敢恨省郎迟。
扈圣崆峒日，端居灧滪时。
萍流仍汲引，樗散尚恩慈。
遂阻云台宿，常怀湛露诗。
翠华森远矣，白首飒凄其。
拙被林泉滞，生逢酒赋欺。
文园终寂寞，汉阁自磷缁。
病隔君臣议，惭纡德泽私。
扬镳惊主辱，拔劒拨年衰。
社稷经纶地，风云际会期。
血流纷在眼，涕洒乱交颐。
四渎楼船泛，中原鼓角悲。
贼壕连白翟，战瓦落丹墀。
先帝严灵寝，宗臣切受遗。
恒山犹突骑，辽海竞张旗。
田父嗟胶漆，行人避蒺藜。
总戎存大体，降将餙卑词。
楚贡何年绝，尧封旧俗疑。
长吁翻北寇，一望卷西夷。
不必陪玄圃，超然待具茨。
凶兵铸农器，讲殿辟书帷。
庙算高难测，天忧实在兹。
形容真潦倒，答效莫支持。
使者分王命，羣公各典司。
恐乖均赋歛，不似问疮痍。
万里烦供给，孤城最怨思。
绿林宁小患，云梦欲难追。
即事须尝胆，苍生可察眉。
议堂犹集凤，正观是元龟。
处处喧飞檄，家家急竞锥。
萧车安不定，蜀使下何之。
钓濑疎坟籍，耕岩进弈棊。
地蒸余破扇，冬暖更纤絺。
豺遘哀登楚麟伤泣象尼。
衣冠迷适越，藻绘忆游睢。
赏月延秋桂，倾阳逐露葵。
大庭终反朴，京观且僵尸。
高枕虚眠昼，哀歌欲和谁。
南宫载勋业，凡百慎交绥。','',''),('quantangshi-11654','解闷十二首 一','杜甫','quantangshi','','卷12','草阁柴扉星散居，浪翻江黑雨飞初。
山禽引子哺红果，溪友得钱留白鱼。','',''),('quantangshi-11655','解闷十二首 二','杜甫','quantangshi','','卷12','商胡离别下扬州，忆上西陵故驿楼。
为问淮南米贵贱，老夫乘兴欲东流。','',''),('quantangshi-11656','解闷十二首 三','杜甫','quantangshi','','卷12','一辞故国十经秋，每见秋瓜忆故丘。
今日南湖采薇蕨，何人为觅郑瓜州。','',''),('quantangshi-11657','解闷十二首 四','杜甫','quantangshi','','卷12','沈范早知何水部，曹刘不待薛郎中。
独当省署开文苑，兼泛沧浪学钓翁。','',''),('quantangshi-11658','解闷十二首 五','杜甫','quantangshi','','卷12','李陵苏武是吾师，孟子论文更不疑。
一饭未曾留俗客，数篇今见古人诗。','',''),('quantangshi-11659','解闷十二首 六','杜甫','quantangshi','','卷12','复忆襄阳孟浩然，清诗句句尽堪传。
即今耆旧无新语，漫钓槎头缩颈鳊。','',''),('quantangshi-11660','解闷十二首 七','杜甫','quantangshi','','卷12','陶冶性灵在底物，新诗改罢自长吟。
孰知二谢将能事，颇学阴何苦用心。','',''),('quantangshi-11661','解闷十二首 八','杜甫','quantangshi','','卷12','不见高人王右丞，蓝田丘壑漫寒藤。
最传秀句寰区满，未绝风流相国能。','',''),('quantangshi-11662','解闷十二首 九','杜甫','quantangshi','','卷12','先帝贵妃今寂寞，荔枝还复入长安。
炎方每续朱[樱]献，玉座应悲白露[团]。','',''),('quantangshi-11663','解闷十二首 十','杜甫','quantangshi','','卷12','忆过泸戎摘荔枝，青峰隐暎石逶迤。
京中旧见无颜色，红颗酸甜只自知。','',''),('quantangshi-11664','解闷十二首 十一','杜甫','quantangshi','','卷12','翠瓜碧李沈玉甃，赤梨葡萄寒露成。
可怜先不异枝蔓，此物娟娟长远生。','',''),('quantangshi-11665','解闷十二首 十二','杜甫','quantangshi','','卷12','侧生野岸及江蒲，不熟丹宫满玉壶。
云壑布衣骀背死，劳生重马翠眉须。','',''),('quantangshi-11666','复愁十二首 一','杜甫','quantangshi','','卷12','人烟生处僻，虎迹过新蹄。
野鹘翻窥草，村船逆上溪。','',''),('quantangshi-11667','复愁十二首 二','杜甫','quantangshi','','卷12','钓艇收缗尽，昏鸦接翅归。
月生初学扇，云细不成衣。','',''),('quantangshi-11668','复愁十二首 三','杜甫','quantangshi','','卷12','万国尚防寇，故园今若何。
昔归相识少，早已战场多。','',''),('quantangshi-11669','复愁十二首 四','杜甫','quantangshi','','卷12','身觉省郎在，家须农事归。
年深荒草径，老恐失柴扉。','',''),('quantangshi-11670','复愁十二首 五','杜甫','quantangshi','','卷12','金丝镂箭镞，皂尾制旗竿。
一自风尘起，犹嗟行路难。','',''),('quantangshi-11671','复愁十二首 六','杜甫','quantangshi','','卷12','胡虏何曾盛，干戈不肯休。
闾阎听小子，谈话觅封侯。','',''),('quantangshi-11672','复愁十二首 七','杜甫','quantangshi','','卷12','贞观铜牙弩，开元锦兽张。
花门小前好，此物弃沙场。','',''),('quantangshi-11673','复愁十二首 八','杜甫','quantangshi','','卷12','今日翔麟马，先宜驾鼓车。
无劳问河北，诸将觉荣华。','',''),('quantangshi-11674','复愁十二首 九','杜甫','quantangshi','','卷12','任转江淮粟，休添苑囿兵。
由来貔虎士，不满凤皇城。','',''),('quantangshi-11675','复愁十二首 十','杜甫','quantangshi','','卷12','江上亦秋色，火云终不移。
巫山犹锦树，南国且黄鹂。','',''),('quantangshi-11676','复愁十二首 十一','杜甫','quantangshi','','卷12','每恨陶彭泽，无钱对菊花。
如今九日至，自觉酒须赊。','',''),('quantangshi-11677','复愁十二首 十二','杜甫','quantangshi','','卷12','病减诗仍拙，吟多意有余。
莫看江总老，犹被赏时鱼。','',''),('quantangshi-11678','承闻河北诸道节度入朝欢喜口号绝句十二首 一','杜甫','quantangshi','','卷12','禄山作逆降天诛，更有思明亦已无。
汹汹人寰犹不定，时时鬬战欲何须。','',''),('quantangshi-11679','承闻河北诸道节度入朝欢喜口号绝句十二首 二','杜甫','quantangshi','','卷12','社稷苍生计必安，蛮夷杂种错相干。
周宣汉武今王是，孝子忠臣后代看。','',''),('quantangshi-11680','承闻河北诸道节度入朝欢喜口号绝句十二首 三','杜甫','quantangshi','','卷12','喧喧道路多歌谣，河北将军尽入朝。
始是干坤王室正，却交江汉客魂销。','',''),('quantangshi-11681','承闻河北诸道节度入朝欢喜口号绝句十二首 四','杜甫','quantangshi','','卷12','不道诸公无表来，茫然庶事遣人猜。
拥兵相学干戈锐，使者徒劳百万回。','',''),('quantangshi-11682','承闻河北诸道节度入朝欢喜口号绝句十二首 五','杜甫','quantangshi','','卷12','鸣玉锵金尽正臣，修文偃武不无人。
兴王会静妖氛气，圣寿宜过一万春。','',''),('quantangshi-11683','承闻河北诸道节度入朝欢喜口号绝句十二首 六','杜甫','quantangshi','','卷12','英雄见事若通神，圣哲为心小一身。
燕赵休矜出佳丽，宫闱不拟选才人。','',''),('quantangshi-11684','承闻河北诸道节度入朝欢喜口号绝句十二首 七','杜甫','quantangshi','','卷12','抱病江天白首郎，空山楼阁暮春光。
衣冠是日朝天子，草奏何时入帝乡。','',''),('quantangshi-11685','承闻河北诸道节度入朝欢喜口号绝句十二首 八','杜甫','quantangshi','','卷12','澶漫山东一百州，削成如桉抱青丘。
苞茅重入归关内，王祭还供尽海头。','',''),('quantangshi-11686','承闻河北诸道节度入朝欢喜口号绝句十二首 九','杜甫','quantangshi','','卷12','东逾辽水北滹沱，星象风云喜共和。
紫气关临天地阔，黄金台贮俊贤多。','',''),('quantangshi-11687','承闻河北诸道节度入朝欢喜口号绝句十二首 十','杜甫','quantangshi','','卷12','渔阳突骑邯郸儿，酒酣并辔金鞭垂。
意气即归双阙舞，雄豪复遣五陵知。','',''),('quantangshi-11688','承闻河北诸道节度入朝欢喜口号绝句十二首 十一','杜甫','quantangshi','','卷12','李相将军拥蓟门，白头虽老赤心存。
竟能尽说诸侯入，知有从来天子尊。','',''),('quantangshi-11689','承闻河北诸道节度入朝欢喜口号绝句十二首 十二','杜甫','quantangshi','','卷12','十二年来多战场，天威已息阵堂堂。
神灵汉代中兴主，功业汾阳异姓王。','',''),('quantangshi-11690','喜闻盗贼蕃寇总退口号五首 一','杜甫','quantangshi','','卷12','萧关陇水入官军，青海黄河卷塞云。
北极转愁龙虎气，西戎休纵犬羊羣。','',''),('quantangshi-11691','喜闻盗贼蕃寇总退口号五首 二','杜甫','quantangshi','','卷12','赞普多教使入秦，数通和好止烟尘。
朝廷忽用哥舒将，杀伐虚悲公主亲。','',''),('quantangshi-11692','喜闻盗贼蕃寇总退口号五首 三','杜甫','quantangshi','','卷12','崆峒西极过昆仑，驼马由来拥国门。
逆气数年吹路断，蕃人闻道渐星奔。','',''),('quantangshi-11693','喜闻盗贼蕃寇总退口号五首 四','杜甫','quantangshi','','卷12','勃律天西采玉河，坚昆碧盌最来多。
旧随汉使千堆宝，少答胡王万匹罗。','',''),('quantangshi-11694','喜闻盗贼蕃寇总退口号五首 五','杜甫','quantangshi','','卷12','今春喜气满干坤，南北东西拱至尊。
大历二年调玉烛，玄元皇帝圣云孙。','',''),('quantangshi-11695','洞房','杜甫','quantangshi','','卷12','洞房环佩冷，玉殿起秋风。
秦地应新月，龙池满旧宫。
系舟今夜远，清漏往时同。
万里黄山北，园陵白露中。','',''),('quantangshi-11696','宿昔','杜甫','quantangshi','','卷12','宿昔青门里，蓬莱仗数移。
花娇迎杂树，龙喜出平池。
落日留王母，微风倚少儿。
宫中行乐祕，少有外人知。','',''),('quantangshi-11697','能画','杜甫','quantangshi','','卷12','能画毛延寿，投壶郭舍人。
每蒙天一笑，复似物皆春。
政化平如水，皇恩断若神。
时时用抵戏，亦未杂风尘。','',''),('quantangshi-11698','鬬鸡','杜甫','quantangshi','','卷12','鬬鸡初赐锦，舞马既登牀。
帘下宫人出，楼前御柳长。
仙游终一閟，女乐久无香。
寂寞骊山道，清秋草木黄。','',''),('quantangshi-11699','鹦鹉','杜甫','quantangshi','','卷12','鹦鹉含愁思，聪明忆别离。
翠衿浑短尽，红觜漫多知。
未有开笼日，空残旧宿枝。
世人怜复损，何用羽毛奇。','',''),('quantangshi-11700','历历','杜甫','quantangshi','','卷12','历历开元事，分明在眼前。
无端盗贼起，忽已岁时迁。
巫峡西江外，秦城北斗边。
为郎从白首，卧病数秋天。','',''),('quantangshi-11701','洛阳','杜甫','quantangshi','','卷12','洛阳昔陷没，胡马犯潼关。
天子初愁思，都人惨别颜。
清笳去宫阙，翠盖出关山。
故老仍流涕，龙髯幸再攀。','',''),('quantangshi-11702','骊山','杜甫','quantangshi','','卷12','骊山绝望幸，花萼罢登临。
地下无朝烛，人间有赐金。
鼎湖龙去远，银海雁飞深。
万岁蓬莱日，长悬旧羽林。','',''),('quantangshi-11703','提封','杜甫','quantangshi','','卷12','提封汉天下，万国尚同心。
借问悬车守，何如俭德临。
时征俊乂入，草窃犬羊侵。
愿戒兵犹火，恩加四海深。','',''),('quantangshi-11704','覆舟二首 一','杜甫','quantangshi','','卷12','巫峡盘涡晓，黔阳贡物秋。
丹砂同陨石，翠羽共沈舟。
羁使空斜影，龙居閟积流。
篙工幸不溺，俄顷逐轻鸥。','',''),('quantangshi-11705','覆舟二首 二','杜甫','quantangshi','','卷12','竹宫时望拜，桂馆或求仙。
姹女临波日，神光照夜年。
徒闻斩蛟劒，无复爨犀船。
使者随秋色，迢迢独上天。','',''),('quantangshi-11706','垂白','杜甫','quantangshi','','卷12','垂白冯唐老，清秋宋玉悲。
江喧长少睡，楼迥独移时。
多难身何补，无家病不辞。
甘从千日醉，未许七哀诗。','',''),('quantangshi-11707','草阁','杜甫','quantangshi','','卷12','草阁临无地，柴扉永不关。
鱼龙回夜水，星月动秋山。
久露清初湿，高云薄未还。
泛舟惭小妇，飘泊损红颜。','',''),('quantangshi-11708','江月','杜甫','quantangshi','','卷12','江月光于水，高楼思杀人。
天边长作客，老去一霑巾。
玉露团清影，银河没半轮。
谁家挑锦字，灭烛翠眉嚬。','',''),('quantangshi-11709','江上','杜甫','quantangshi','','卷12','江上日多雨，萧萧荆楚秋。
高风下木叶，永夜揽貂裘。
勋业频看镜，行藏独倚楼。
时危思报主，衰谢不能休。','',''),('quantangshi-11710','中夜','杜甫','quantangshi','','卷12','中夜江山静，危楼望北辰。
长为万里客，有愧百年身。
故国风云气，高堂战伐尘。
胡雏负恩泽，嗟尔太平人。','',''),('quantangshi-11711','江汉','杜甫','quantangshi','','卷12','江汉思归客，干坤一腐儒。
片云天共远，永夜月同孤。
落日心犹壮，秋风病欲疎。
古来存老马，不必取长途。','',''),('quantangshi-11712','白露','杜甫','quantangshi','','卷12','白露团甘子，清晨散马蹄。
圃开连石树，船渡入江溪。
凭几看鱼乐，回鞭急鸟栖。
渐知秋实美，幽径恐多蹊。','',''),('quantangshi-11713','孟氏','杜甫','quantangshi','','卷12','孟氏好兄弟，养亲唯小园。
承颜胝手足，坐客强盘[飧]。
负米力葵外，读书秋树根。
卜邻惭近舍，训子学谁门。','',''),('quantangshi-11714','吾宗','杜甫','quantangshi','','卷12','吾宗老孙子，质朴古人风。
耕凿安时论，衣冠与世同。
在家常早起，忧国愿年丰。
语及君臣际，经书满腹中。','',''),('quantangshi-11715','有叹','杜甫','quantangshi','','卷12','壮心久零落，白首寄人间。
天下兵常鬬，江东客未还。
穷猨号雨雪，老马怯关山。
武德开元际，苍生岂重攀。','',''),('quantangshi-11716','冬深','杜甫','quantangshi','','卷12','花叶随天意，江溪共石根。
早霞随类影，寒水各依痕。
易下杨朱泪，难招楚客魂。
风涛暮不稳，舍棹宿谁门。','',''),('quantangshi-11717','不寐','杜甫','quantangshi','','卷12','瞿塘夜水黑，城内改更筹。
翳翳月沈雾，辉辉星近楼。
气衰甘少寐，心弱恨和愁。
多垒满山谷，桃源无处求。','',''),('quantangshi-11718','月圆','杜甫','quantangshi','','卷12','孤月当楼满，寒江动夜扉。
委波金不定，照席绮逾依。
未缺空山静，高悬列宿稀。
故园松桂发，万里共清辉。','',''),('quantangshi-11719','中宵','杜甫','quantangshi','','卷12','西阁百寻余，中宵步绮疏。
飞星过水白，落月动沙虚。
择木知幽鸟，潜波想巨鱼。
亲朋满天地，兵甲少来书。','',''),('quantangshi-11720','遣愁','杜甫','quantangshi','','卷12','养拙蓬为户，茫茫何所开。
江通神女馆，地隔望乡台。
渐惜容颜老，无由弟妹来。
兵戈与人事，回首一悲哀。','',''),('quantangshi-11721','秋清','杜甫','quantangshi','','卷12','高秋苏病气，白发自能梳。
药饵憎加减，门庭闷扫除。
杖藜还客拜，爱竹遣儿书。
十月江平稳，轻舟进所如。','',''),('quantangshi-11722','伤秋','杜甫','quantangshi','','卷12','林僻来人少，山长去鸟微。
高秋收画扇，久客掩荆扉。
嬾慢头时栉，艰难带减围。
将军犹汗马，天子尚戎衣。
白蒋风飙脆，殷柽晓夜稀。
何年减豺虎，似有故园归。','',''),('quantangshi-11723','秋峡','杜甫','quantangshi','','卷12','江涛万古峡，肺气久衰翁。
不寐防巴虎，全生狎楚童。
衣裳垂素发，门巷落丹枫。
常怪商山老，兼存翊赞功。','',''),('quantangshi-11724','南极','杜甫','quantangshi','','卷12','南极青山众，西江白谷分。
古城疏落木，荒戍密寒云。
岁月虵常见，风飙虎或闻。
近身皆鸟道，殊俗自人羣。
睥睨登哀柝，矛弧照夕曛。
乱离多醉尉，愁杀李将军。','',''),('quantangshi-11725','摇落','杜甫','quantangshi','','卷12','摇落巫山暮，寒江东北流。
烟尘多战鼓，风浪少行舟。
鹅费义之墨，貂余季子裘。
长怀报明主，卧病复高秋。','',''),('quantangshi-11726','耳聋','杜甫','quantangshi','','卷12','生年鹖冠子，叹世鹿皮翁。
眼复几时暗，耳从前月聋。
猨鸣秋泪缺，雀噪晚愁空。
黄落惊山树，呼儿问朔风。','',''),('quantangshi-11727','独坐二首 一','杜甫','quantangshi','','卷12','竟日雨冥冥，双崖洗更青。
水花寒落岸，山鸟暮过庭。
暖老须燕玉，充饥忆楚萍。
胡笳在楼上，哀怨不堪听。','',''),('quantangshi-11728','独坐二首 二','杜甫','quantangshi','','卷12','白狗斜临北，黄牛更在东。
峡云常照夜，江月会兼风。
晒药安垂老，应门试小童。
亦知行不逮，苦恨耳多聋。','',''),('quantangshi-11729','远游','杜甫','quantangshi','','卷12','江阔浮高栋，云长出断山。
尘沙连越巂，风雨暗荆蛮。
雁矫衔芦内，猨啼失木间。
弊裘苏季子，历国未知还。','',''),('quantangshi-11730','夜','杜甫','quantangshi','','卷12','露下天高秋水清，空山独夜旅魂惊。
疎灯自照孤帆宿，新月犹悬双杵鸣。
南菊再逢人卧病，北书不至雁无情。
步蟾倚杖看牛斗，银汉遥应接凤城。','',''),('quantangshi-11731','暮春','杜甫','quantangshi','','卷12','卧病拥塞在峡中，潇湘洞庭虚暎空。
楚天不断四时雨，巫峡常吹千里风。
沙上草阁柳新暗，城边野池莲欲红。
暮春鸳鹭立洲渚，挟子翻飞还一丛。','',''),('quantangshi-11732','晴二首 一','杜甫','quantangshi','','卷12','久雨巫山暗，新晴锦绣文。
碧知湖外草，红见海东云。
竟日莺相和，摩霄鹤数羣。
野花干更落，风处急纷纷。','',''),('quantangshi-11733','晴二首 二','杜甫','quantangshi','','卷12','啼乌争引子，鸣鹤不归林。
下食遭泥去，高飞恨久阴。
雨声冲塞尽，日气射江深。
回首周南客，驱驰魏阙心。','',''),('quantangshi-11734','雨','杜甫','quantangshi','','卷12','始贺天休雨，还嗟地出雷。
骤看浮峡过，密作渡江来。
牛马行无色，蛟龙鬬不开。
干戈盛阴气，未必自阳台。','',''),('quantangshi-11735','月三首 一','杜甫','quantangshi','','卷12','断续巫山雨，天河此夜新。
若无青嶂月，愁杀白头人。
魍魉移深树，虾蟆动半轮。
故园当北斗，直指照西秦。','',''),('quantangshi-11736','月三首 二','杜甫','quantangshi','','卷12','并照巫山出，新窥楚水清。
羁栖愁里见，二十四回明。
必验升沈体，如知进退情。
不违银汉落，亦伴玉绳横。','',''),('quantangshi-11737','月三首 三','杜甫','quantangshi','','卷12','万里瞿塘峡，春来六上弦。
时时开暗室，故故满青天。
爽合风襟静，高当泪脸悬。
南飞有乌鹊，夜久落江边。','',''),('quantangshi-11738','雨','杜甫','quantangshi','','卷12','万木云深隐，连山雨未开。
风扉掩不定，水鸟过仍回。
鲛馆如鸣杼，樵舟岂伐枚。
清凉破炎毒，衰意欲登台。','',''),('quantangshi-11739','晚晴','杜甫','quantangshi','','卷12','返照斜初彻，浮云薄未归。
江虹明远饮，峡雨落余飞。
凫雁终高去，熊罴觉自肥。
秋分客尚在，竹露夕微微。','',''),('quantangshi-11740','夜雨','杜甫','quantangshi','','卷12','小雨夜复密，回风吹早秋。
野凉侵闭户，江满带维舟。
通籍恨多病，为郎忝薄游。
天寒出巫峡，醉别仲宣楼。','',''),('quantangshi-11741','更题','杜甫','quantangshi','','卷12','只应踏初雪，骑马发荆州。
直怕巫山雨，真伤白帝秋。
羣公苍玉佩，天子翠云裘。
同舍晨趋侍，胡为淹此留。','',''),('quantangshi-11742','归','杜甫','quantangshi','','卷12','束带还骑马，东西却渡船。
林中才有地，峡外绝无天。
虚白高人静，喧卑俗累牵。
他乡悦迟暮，不敢废诗篇。','',''),('quantangshi-11743','返照','杜甫','quantangshi','','卷12','楚王宫北正黄昏，白帝城西过雨痕。
返照入江翻石壁，归云拥树失山村。
衰年肺病唯高枕，绝塞愁时早闭门。
不可久留豺虎乱，南方实有未招魂。','',''),('quantangshi-11744','热三首 一','杜甫','quantangshi','','卷12','雷霆空霹雳，云雨竟虚无。
炎赫衣流汗，低垂气不苏。
乞为寒水玉，愿作冷秋菰。
何似儿童岁，风凉出舞雩。','',''),('quantangshi-11745','热三首 二','杜甫','quantangshi','','卷12','瘴云终不灭，泸水复西来。
闭户人高卧，归林鸟却回。
峡中都似火，江上只空雷。
想见阴宫雪，风门飒踏开。','',''),('quantangshi-11746','热三首 三','杜甫','quantangshi','','卷12','朱李沈不冷，雕胡炊屡新。
将衰骨尽痛，被褐味空频。
歘翕炎蒸景，飘颻征戍人。
十年可解甲，为尔一霑巾。','',''),('quantangshi-11747','日暮','杜甫','quantangshi','','卷12','牛羊下来久，各已闭柴门。
风月自清夜，江山非故园。
石泉流暗壁，草露滴秋根。
头白灯明里，何须花烬繁。','',''),('quantangshi-11748','八月十五夜月二首 一','杜甫','quantangshi','','卷12','满目飞明镜，归心折大刀。
转蓬行地远，攀桂仰天高。
水路疑霜雪，林栖见羽毛。
此时瞻白兔，直欲数秋毫。','',''),('quantangshi-11749','八月十五夜月二首 二','杜甫','quantangshi','','卷12','稍下巫山峡，犹衔白帝城。
气沈全浦暗，轮仄半楼明。
刁斗皆催晓，蟾蜍且自倾。
张弓倚残魄，不独汉家营。','',''),('quantangshi-11750','十六夜翫月','杜甫','quantangshi','','卷12','旧挹金波爽，皆传玉露秋。
关山随地阔，河汉近人流。
谷口樵归唱，孤城笛起愁。
巴童浑不寝，半夜有行舟。','',''),('quantangshi-11751','十七夜对月','杜甫','quantangshi','','卷12','秋月仍圆夜，江村独老身。
卷帘还照客，倚杖更随人。
光射潜虬动，明翻宿鸟频。
茅斋依橘柚，清切露华新。','',''),('quantangshi-11752','村雨','杜甫','quantangshi','','卷12','雨声传两夜，寒事飒高秋。
挈带看朱绂，开箱覩黑裘。
世情只益睡，盗贼敢忘忧。
松菊新霑洗，茅齐慰远游。','',''),('quantangshi-11753','雨晴','杜甫','quantangshi','','卷12','雨时山不改，晴罢峡如新。
天路看殊俗，秋江思杀人。
有猨挥泪尽，无犬附书频。
故国愁眉外，长歌欲损神。','',''),('quantangshi-11754','晚晴吴郎见过北舍','杜甫','quantangshi','','卷12','圃畦新雨润，愧子废鉏来。
竹杖交头拄，柴扉隔径开。
欲栖羣鸟乱，未去小童催。
明日重阳酒，相迎自发醅。','',''),('quantangshi-11755','暝','杜甫','quantangshi','','卷12','日下四山阴，山庭岚气侵。
牛羊归径险，鸟雀聚枝深。
正枕当星劒，收书动玉琴。
半扉开烛影，欲掩见清砧。','',''),('quantangshi-11756','云','杜甫','quantangshi','','卷12','龙似瞿唐会，江依白帝深。
终年常起峡，每夜必通林。
收获辞霜渚，分明在夕岑。
高斋非一处，秀气豁烦襟。','',''),('quantangshi-11757','月','杜甫','quantangshi','','卷12','四更山吐月，残夜水明楼。
尘匣元开镜，风帘自上钩。
兔应疑鹤发，蟾亦恋貂裘。
斟酌姮娥寡，天寒耐九秋。','',''),('quantangshi-11758','雨四首 一','杜甫','quantangshi','','卷12','微雨不滑道，断云疎复行。
紫崖奔处黑，白鸟去边明。
秋日新霑影，寒江旧落声。
柴扉临野碓，半得捣香秔。','',''),('quantangshi-11759','雨四首 二','杜甫','quantangshi','','卷12','江雨旧无时，天晴忽散丝。
暮秋霑物冷，今日过云迟。
上马迥休出，看鸥坐不辞。
高轩当灧滪，润色静书帷。','',''),('quantangshi-11760','雨四首 三','杜甫','quantangshi','','卷12','物色岁将晏，天隅人未归。
朔风鸣淅淅，寒雨下霏霏。
多病久加饭，衰容新授衣。
时危觉凋丧，故旧短书稀。','',''),('quantangshi-11761','雨四首 四','杜甫','quantangshi','','卷12','楚雨石苔滋，京华消息迟。
山寒青兕呌，江晚白鸥饥。
神女花钿落，鲛人织杼悲。
繁忧不自整，终日洒如丝。','',''),('quantangshi-11762','夜','杜甫','quantangshi','','卷12','绝岸风威动，寒房烛影微。
岭猨霜外宿，江鸟夜深飞。
独坐亲雄劒，哀歌叹短衣。
烟尘绕阊阖，白首壮心违。','',''),('quantangshi-11763','晨雨','杜甫','quantangshi','','卷12','小雨晨光内，初来叶上闻。
雾交才洒地，风逆旋随云。
暂起柴荆色，轻霑鸟兽羣。
麝香山一半，亭午未全分。','',''),('quantangshi-11764','返照','杜甫','quantangshi','','卷12','返照开巫峡，寒空半有无。
已低鱼复暗，不尽白盐孤。
荻岸如秋水，松门似画图。
牛羊识童仆，既夕应传呼。','',''),('quantangshi-11765','向夕','杜甫','quantangshi','','卷12','畎亩孤城外，江村乱水中。
深山催短景，乔木易高风。
鹤下云汀近，鸡栖草屋同。
琴书散明烛，长夜始堪终。','',''),('quantangshi-11766','晓望','杜甫','quantangshi','','卷12','白帝更声尽，阳台曙色分。
高峯寒上日，叠岭宿霾云。
地坼江帆隐，天清木叶闻。
荆扉对麋鹿，应共尔为羣。','',''),('quantangshi-11767','雷','杜甫','quantangshi','','卷12','巫峡中宵动，沧江十月雷。
龙虵不成蛰，天地划争回。
却碾空山过，深蟠绝壁来。
何须妒云雨，霹雳楚王台。','',''),('quantangshi-11768','雨','杜甫','quantangshi','','卷12','冥冥甲子雨，已度立春时。
轻箑烦相向，纤絺恐自疑。
烟添才有色，风引更如丝。
直觉巫山暮，兼催宋玉悲。','',''),('quantangshi-11769','朝二首 一','杜甫','quantangshi','','卷12','清旭楚宫南，霜空万岭含。
野人时独往，云木晓相参。
俊鹘无声过，饥乌下食贪。
病身终不动，摇落任江潭。','',''),('quantangshi-11770','朝二首 二','杜甫','quantangshi','','卷12','浦帆晨初发，郊扉冷未开。
村疎黄叶坠，野静白鸥来。
础润休全湿，云晴欲半回。
巫山冬可怪，昨夜有奔雷。','',''),('quantangshi-11771','晚','杜甫','quantangshi','','卷12','杖藜寻晚巷，炙背近墙暄。
人见幽居僻，吾知拙养尊。
朝廷问府主，耕稼学山村。
归翼飞栖定，寒灯亦闭门。','',''),('quantangshi-11772','夜二首 一','杜甫','quantangshi','','卷12','白夜月休弦，灯花半委眠。
号山无定鹿，落树有惊蝉。
暂忆江东鲙，兼怀雪下船。
蛮歌犯星起，空觉在天边。','',''),('quantangshi-11773','夜二首 二','杜甫','quantangshi','','卷12','城郭悲笳暮，村墟过翼稀。
甲兵年数久，赋歛夜深归。
暗树依岩落，明河绕塞微。
斗斜人更望，月细鹊休飞。','',''),('quantangshi-11774','宗武生日','杜甫','quantangshi','','卷12','小子何时见，高秋此日生。
自从都邑语，已伴老夫名。
诗是吾家事，人传世上情。
熟精文选理，休觅彩衣轻。
凋瘵筵初秩，欹斜坐不成。
流霞分片片，涓滴就徐倾。','',''),('quantangshi-11775','又示宗武','杜甫','quantangshi','','卷12','觅句新知律，摊书解满牀。
试吟青玉案，莫羡紫罗囊。
假日从时饮，明年共我长。
应须饱经术，已似爱文章。
十五男儿志，三千弟子行。
曾参与游夏，达者得升堂。','',''),('quantangshi-11776','熟食日示宗文宗武','杜甫','quantangshi','','卷12','消渴游江汉，羇栖尚甲兵。
几年逢熟食，万里逼清明。
松柏邛山路，风花白帝城。
汝曹催我老，回首泪纵横。','',''),('quantangshi-11777','又示两儿','杜甫','quantangshi','','卷12','令节成吾老，他时见汝心。
浮生看物变，为恨与年深。
长葛书难得，江州涕不禁。
团圆思弟妹，行坐白头吟。','',''),('quantangshi-11778','社日两篇 一','杜甫','quantangshi','','卷12','九农成德业，百祀发光辉。
报効神如在，馨香旧不违。
南翁巴曲醉，北雁塞声微。
尚想东方朔，诙谐割肉归。','',''),('quantangshi-11779','社日两篇 二','杜甫','quantangshi','','卷12','陈平亦分肉，太史竟论功。
今日江南老，他时渭北童。
欢娱看绝塞，涕泪落秋风。
鸳鹭回金阙，谁怜病峡中。','',''),('quantangshi-11780','九日五首 一','杜甫','quantangshi','','卷12','重阳独酌杯中酒，抱病起登江上台。
竹叶于人既无分，菊花从此不须开。
殊方日落玄猨哭，旧国霜前白雁来。
弟妹萧条各何往，干戈衰谢两相催。','',''),('quantangshi-11781','九日五首 二','杜甫','quantangshi','','卷12','旧日重阳日，传杯不放杯。
即今蓬鬓改，但愧菊花开。
北阙心长恋，西江首独回。
茱萸赐朝士，难得一枝来。','',''),('quantangshi-11782','九日五首 三','杜甫','quantangshi','','卷12','旧与苏司业，兼随郑广文。
采花香泛泛，坐客醉纷纷。
野树歌还倚，秋砧醒却闻。
欢娱两冥漠，西北有孤云。','',''),('quantangshi-11783','九日五首 四','杜甫','quantangshi','','卷12','故里樊川菊，登高素浐源。
他时一笑后，今日几人存。
巫峡蟠江路，终南对国门。
系舟身万里，伏枕泪双痕。
为客裁乌帽，从儿具绿尊。
佳辰对羣盗，愁绝更谁论。','',''),('quantangshi-11784','九日诸人集于林','杜甫','quantangshi','','卷12','九日明朝是，相要旧俗非。
老翁难早出，贤客幸知归。
旧采黄花剩，新梳白发微。
漫看年少乐，忍泪已霑衣。','',''),('quantangshi-11785','大历二年九月三十日','杜甫','quantangshi','','卷12','为客无时了，悲秋向夕终。
瘴余夔子国，霜薄楚王宫。
草敌虚岚翠，花禁冷叶红。
年年小摇落，不与故园同。','',''),('quantangshi-11786','十月一日','杜甫','quantangshi','','卷12','有瘴非全歇，为冬亦不难。
夜郎溪日暖，白帝峡风寒。
蒸裹如千室，焦糟幸一柈。
兹辰南国重，旧俗自相欢。','',''),('quantangshi-11787','孟冬','杜甫','quantangshi','','卷12','殊俗还多事，方冬变所为。
破甘霜落爪，尝稻雪飜匙。
巫峡寒都薄，乌蛮瘴远随。
终然减滩濑，暂喜息蛟螭。','',''),('quantangshi-11788','冬至','杜甫','quantangshi','','卷12','年年至日长为客，忽忽穷愁泥杀人。
江上形容吾独老，天边风俗自相亲。
杖蓼雪后临丹壑，鸣玉朝来散紫宸。
心折此时无一寸，路迷何处见三秦。','',''),('quantangshi-11789','小至','杜甫','quantangshi','','卷12','天时人事日相催，冬至阳生春又来。
刺绣五纹添弱线，吹葭六琯动浮灰。
岸容待腊将舒柳，山意冲寒欲放梅。
云物不殊乡国异，教儿且覆掌中杯。','',''),('quantangshi-11790','览物','杜甫','quantangshi','','卷12','曾为掾吏趋三辅，忆在潼关诗兴多。
巫峡忽如瞻华岳，蜀江犹似见黄河。
舟中得病移衾枕，洞口经春长薜萝。
形胜有余风土恶，几时回首一高歌。','',''),('quantangshi-11791','忆郑南玭','杜甫','quantangshi','','卷12','郑南伏毒寺，潇洒到江心。
石影衔珠阁，泉声带玉琴。
风杉曾曙倚，云峤忆春临。
万里沧浪外，龙蛇只自深。','',''),('quantangshi-11792','怀灞上游','杜甫','quantangshi','','卷12','怅望东陵道，平生灞上游。
春浓停野骑，夜宿敞云楼。
离别人谁在，经过老自休。
眼前今古意，江汉一归舟。','',''),('quantangshi-11793','愁','杜甫','quantangshi','','卷12','江草日日唤愁生，巫峡泠泠非世情。
盘涡鹭浴底心性，独树花发自分明。
十年戎马暗万国，异域宾客老孤城。
渭水秦山得见否，人经罢病虎纵横。','',''),('quantangshi-11794','昼梦','杜甫','quantangshi','','卷12','二月饶睡昏昏然，不独夜短昼分眠。
桃花气暖眼自醉，春渚日落梦相牵。
故乡门巷荆棘底，中原君臣豺虎边。
安得务农息战鬬，普天无吏横索钱。','',''),('quantangshi-11795','览镜呈柏中丞','杜甫','quantangshi','','卷12','渭水流关内，终南在日边。
胆销豺虎窟，泪入犬羊天。
起晚堪从事，行迟更学仙。
镜中衰谢色，万一故人怜。','',''),('quantangshi-11796','即事','杜甫','quantangshi','','卷12','暮春三月巫峡长，皛皛行云浮日光。
雷声忽送千峰雨，花气浑如百和香。
黄莺过水飜回去，燕子衔泥湿不妨。
飞阁卷帘图画里，虚无只少对潇湘。','',''),('quantangshi-11797','即事','杜甫','quantangshi','','卷12','天畔羣山孤草亭，江中风浪雨冥冥。
一双白鱼不受钓，三寸黄甘犹自青。
多病马卿无日起，穷途阮籍几时醒。
未闻细柳散金甲，肠断秦川流浊泾。','',''),('quantangshi-11798','闷','杜甫','quantangshi','','卷12','瘴疠浮三蜀，风云暗百蛮。
卷帘唯白水，隐几亦青山。
猨捷长难见，鸥轻故不还。
无钱从滞客，有镜巧催颜。','',''),('quantangshi-11799','戏作俳谐体遣闷二首 一','杜甫','quantangshi','','卷12','异俗吁可怪，斯人难竝居。
家家养乌鬼，顿顿食黄鱼。
旧识能为态，新知已暗疎。
治生且耕凿，只有不关渠。','',''),('quantangshi-11800','戏作俳谐体遣闷二首 二','杜甫','quantangshi','','卷12','西历青羌板，南留白帝城。
于菟侵客恨，粔籹作人情。
瓦卜传神语，畲田费火声。
是非何处定，高枕笑浮生。','',''),('quantangshi-11801','得舍弟观书自中都已达江陵今兹暮春月末行李合到夔州悲喜相兼团圆可待赋诗即事情见乎词','杜甫','quantangshi','','卷12','尔到江陵府，何时到峡州？
乱难生有别，聚集病应瘳。
飒飒开啼眼，朝朝上水楼。
老身须付托，白骨更何忧。','',''),('quantangshi-11802','喜观即到复题短篇二首 一','杜甫','quantangshi','','卷12','巫峡千山暗，终南万里春。
病中吾见弟，书到汝为人。
意答儿童问，来经战伐新。
泊船悲喜后，款款话归秦。','',''),('quantangshi-11803','喜观即到复题短篇二首 二','杜甫','quantangshi','','卷12','待尔嗔乌鹊，抛书示鹡鸰。
枝间喜不去，原上急曾经。
江阁嫌津柳，风帆数驿亭。
应论十年事，愁绝始星星。','',''),('quantangshi-11804','舍弟观归蓝田迎新妇送示两篇 一','杜甫','quantangshi','','卷12','汝去迎妻子，高秋念却回。
即今萤已乱，好与雁同来。
东望西江水，南游北户开。
卜居期静处，会有故人杯。','',''),('quantangshi-11805','舍弟观归蓝田迎新妇送示两篇 二','杜甫','quantangshi','','卷12','楚塞难为路，蓝田莫滞留。
衣裳判白露，鞍马信清秋。
满峡重江水，开帆八月舟。
此时同一醉，应在仲宣楼。','',''),('quantangshi-11806','第五弟丰独在江左近三四载寂无消息觅使寄此二首 一','杜甫','quantangshi','','卷12','乱后嗟吾在，羇栖见汝难。
草黄骐骥病，沙晚鹡鸰寒。
楚设关城险，吴吞水府宽。
十年朝夕泪，衣袖不曾干。','',''),('quantangshi-11807','第五弟丰独在江左近三四载寂无消息觅使寄此二首 二','杜甫','quantangshi','','卷12','闻汝依山寺，杭州定越州。
风尘淹别日，江汉失清秋。
影盖啼猨树，魂飘结蜃楼。
明年下春水，东尽白云求。','',''),('quantangshi-11808','舍弟观赴蓝田取妻子到江陵喜寄三首 一','杜甫','quantangshi','','卷12','汝迎妻子达荆州，消息真传解我忧。
鸿雁影来连峡内，鹡鸰飞急到沙头。
峣关险路今虚远，禹凿寒江正稳流。
朱绂即当随彩鷁，青春不假报黄牛。','',''),('quantangshi-11809','舍弟观赴蓝田取妻子到江陵喜寄三首 二','杜甫','quantangshi','','卷12','马度秦关雪正深，北来肌骨苦寒侵。
他乡就我生春色，故国移居见客心。
剩欲提携如意舞，喜多行坐白头吟。
巡檐索共梅花笑，冷蘂疎枝半不禁。','',''),('quantangshi-11810','舍弟观赴蓝田取妻子到江陵喜寄三首 三','杜甫','quantangshi','','卷12','庾信罗含俱有宅，春来秋去作谁家。
短墙若在从残草，乔木如存可假花。
卜筑应同蒋诩径，为园须似邵平瓜。
比年病酒开涓滴，弟劝兄酬何怨嗟。','',''),('quantangshi-11811','江雨有怀郑典设','杜甫','quantangshi','','卷12','春雨暗暗塞峡中，早晚来自楚王宫。
乱波分披已打岸，弱云狼籍不禁风。
宠光蕙叶与多碧，点注桃花舒小红。
谷口子真正忆汝，岸高瀼滑限西东。','',''),('quantangshi-11812','王十五前阁会','杜甫','quantangshi','','卷12','楚岸收新雨，春台引细风。
情人来石上，鲜脍出江中。
邻舍烦书札，肩舆强老翁。
病身虚俊味，何幸饫儿童。','',''),('quantangshi-11813','寄韦有夏郎中','杜甫','quantangshi','','卷12','省郎忧病士，书信有柴胡。
饮子频通汗，怀君想报珠。
亲知天畔少，药味峡中无。
归楫生衣卧，春鸥洗翅呼。
犹闻上急水，早作取平途。
万里皇华使，为僚记腐儒。','',''),('quantangshi-11814','陪柏中丞观宴将士二首 一','杜甫','quantangshi','','卷12','极乐三军士，谁知百战场。
无私齐绮馔，久坐密金章。
醉客霑鹦鹉，佳人指凤皇。
几时来翠节，特地引红妆。','',''),('quantangshi-11815','陪柏中丞观宴将士二首 二','杜甫','quantangshi','','卷12','绣段装檐额，金花帖鼓腰。
一夫先舞劒，百战后歌樵。
江树城孤远，云台使寂寥。
汉朝频选将，应拜霍嫖姚。','',''),('quantangshi-11816','七月一日题终明府水楼二首 一','杜甫','quantangshi','','卷12','高栋曾轩已自凉，秋风此日洒衣裳。
翛然欲下阴山雪，不去非无汉署香。
绝辟过云开锦绣，疎松夹水奏笙簧。
看君宜着王乔履，真赐还疑出尚方。','',''),('quantangshi-11817','七月一日题终明府水楼二首 二','杜甫','quantangshi','','卷12','宓子弹琴邑宰日，终军弃繻英妙时。
承家节操尚不泯，为政风流今在兹。
可怜宾客尽倾盖，何处老翁来赋诗。
楚江巫峡半云雨，清簟疎帘看弈棊。','',''),('quantangshi-11818','季秋苏五弟缨江楼夜宴崔十三评事韦少府侄三首 一','杜甫','quantangshi','','卷12','峡险江惊急，楼高月迥明。
一时今夕会，万里故乡情。
星落黄姑渚，秋辞白帝城。
老人因酒病，坚坐看君倾。','',''),('quantangshi-11819','季秋苏五弟缨江楼夜宴崔十三评事韦少府侄三首 二','杜甫','quantangshi','','卷12','明月生长好，浮云薄渐遮。
悠悠照边塞，悄悄忆京华。
清动杯中物，高随海上查。
不眠瞻白兔，百过落乌纱。','',''),('quantangshi-11820','季秋苏五弟缨江楼夜宴崔十三评事韦少府侄三首 三','杜甫','quantangshi','','卷12','对月那无酒，登楼况有江。
听歌惊白鬓，笑舞拓秋窗。
尊蚁添相续，沙鸥竝一双。
尽怜君醉倒，更觉片心降。','',''),('quantangshi-11821','九月一日过孟十二仓曹十四主簿兄弟','杜甫','quantangshi','','卷12','藜杖侵寒露，蓬门启曙烟。
力稀经树歇，老困拨书眠。
秋觉追随尽，来因孝友偏。
清谈见滋味，尔辈可忘年。','',''),('quantangshi-11822','过客相寻','杜甫','quantangshi','','卷12','穷老真无事，江山已定居。
地幽忘盥栉，客至罢琴书。
挂壁移筐果，呼儿问煮鱼。
时闻系舟楫，及此问吾庐。','',''),('quantangshi-11823','孟仓曹步趾领新酒酱二物满器见遗老夫','杜甫','quantangshi','','卷12','楚岸通秋屐，胡牀面夕畦。
藉糟分汁滓，瓮酱落提携。
饭粝添香味，朋来有醉泥。
理生那免俗，方法报山妻。','',''),('quantangshi-11824','柳司马至','杜甫','quantangshi','','卷12','有使归三峡，相过问两京。
函关犹出将，渭水更屯兵。
设备邯郸道，和亲逻些城。
幽燕唯鸟去，商洛少人行。
衰谢身何补，萧条病转婴。
霜天到宫阙，恋主寸心明。','',''),('quantangshi-11825','简吴郎司法','杜甫','quantangshi','','卷12','有客乘舸自忠州，遣骑安置瀼西头。
古堂本买藉疎豁，借汝迁居停宴游。
云石荧荧高叶曙，风江飒飒乱帆秋。
却为姻娅过逢地，许坐曾轩数散愁。','',''),('quantangshi-11826','又呈吴郎','杜甫','quantangshi','','卷12','堂前扑枣任西邻，无食无儿一妇人。
不为困穷宁有此，祗缘恐惧转须亲。
即防远客虽多事，使插疎篱却甚真。
已诉征求贫到骨，正思戎马泪盈巾。','',''),('quantangshi-11827','覃山人隐居','杜甫','quantangshi','','卷12','南极老人自有星，北山移文谁勒铭。
征君已去独松菊，哀壑无光留户庭。
予见乱离不得已，子知出处必须经。
高车驷马带倾覆，怅望秋天虚翠屏。','',''),('quantangshi-11828','柏学士茅屋','杜甫','quantangshi','','卷12','碧山学士焚银鱼，白马却走身岩居。
古人已用三冬足，年少今开万卷余。
晴云满户团倾盖，秋水浮阶溜决渠。
富贵必从勤苦得，男儿须读五车书。','',''),('quantangshi-11829','题柏大兄弟山居屋壁二首 一','杜甫','quantangshi','','卷12','叔父朱门贵，郎君玉树高。
山居精典籍，文雅涉风骚。
江汉终吾老，云林得尔曹。
哀弦绕白雪，未与俗人操。','',''),('quantangshi-11830','题柏大兄弟山居屋壁二首 二','杜甫','quantangshi','','卷12','野屋流寒水，山篱带薄云。
静应连虎穴，喧已去人羣。
笔架霑窗雨，书签映隙曛。
萧萧千里足，个个五花文。','',''),('quantangshi-11831','戏寄崔评事表侄苏五表弟韦大少府诸侄','杜甫','quantangshi','','卷12','隐豹深愁雨，潜龙故起云。
泥多仍径曲，心醉阻贤羣。
忍待江山丽，还披鲍谢文。
高楼忆疎豁，秋兴坐氛氲。','',''),('quantangshi-11832','秋日寄题郑监湖上亭三首 一','杜甫','quantangshi','','卷12','碧草逢春意，沅湘万里秋。
池要山简马，月净庾公楼。
磨灭余篇翰，平生一钓舟。
高唐寒浪减，仿髴识昭丘。','',''),('quantangshi-11833','秋日寄题郑监湖上亭三首 二','杜甫','quantangshi','','卷12','新作湖边宅，还闻宾客过。
自须开竹迳，谁道避云萝。
官序潘生拙，才名贾傅多。
舍舟应转地，邻接意如何。','',''),('quantangshi-11834','秋日寄题郑监湖上亭三首 三','杜甫','quantangshi','','卷12','暂阻蓬莱阁，终为江海人。
挥金应物理，拖玉岂吾身。
羹煮秋莼滑，杯迎露菊新。
赋诗分气象，佳句莫频频。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-11835','谒真谛寺禅师','杜甫','quantangshi','','卷12','兰若山高处，烟霞嶂几重。
冻泉依细石，晴雪落长松。
问法看诗忘，观身向酒慵。
未能割妻子，卜宅近前峰。','',''),('quantangshi-11836','别崔潩因寄薛据孟云卿','杜甫','quantangshi','','卷12','志士惜妄动，知深难固辞。
如何久磨砺，但取不磷缁。
夙夜听忧主，飞腾急济时。
荆州过薛孟，为报欲论诗。','',''),('quantangshi-11837','送李八祕书赴杜相公幕','杜甫','quantangshi','','卷12','青帘白舫益州来，巫峡秋涛天地回。
石出倒听枫叶下，橹摇背指菊花开。
贪趋相府今晨发，恐失佳期后命催。
南极一星朝北斗，五云多处是三台。','',''),('quantangshi-11838','巫峡敝庐奉赠侍御四舅别之澧朗','杜甫','quantangshi','','卷12','江城秋日落，山鬼闭门中。
行李淹吾舅，诛茅问老翁。
赤眉犹世乱，青眼只途穷。
传语桃源客，人今出处同。','',''),('quantangshi-11839','奉送十七舅下邵桂','杜甫','quantangshi','','卷12','绝域三冬暮，浮生一病身。
感深辞舅氏，别后见何人。
飘缈苍梧帝，推迁孟母邻。
昏昏阻云水，侧望苦伤神。','',''),('quantangshi-11840','送覃二判官','杜甫','quantangshi','','卷12','先帝弓劒远，小臣余此生。
蹉跎病江汉，不复谒承明。
饯尔白头日，永怀丹凤城。
迟迟恋屈宋，渺渺卧荆衡。
魂断航舸失，天寒沙水清。
肺肝若稍愈，亦上赤霄行。','',''),('quantangshi-11841','季夏送乡弟韶陪黄门从叔朝谒','杜甫','quantangshi','','卷12','令弟尚为苍水使，名家莫出杜陵人。
比来相国兼安蜀，归赴朝廷已入秦。
舍舟策马论兵地，拖玉腰金报主身。
莫度清秋吟蟋蟀，早闻黄阁画麒麟。','',''),('quantangshi-11842','送十五弟侍御使蜀','杜甫','quantangshi','','卷12','喜弟文章进，添余别兴牵。
数杯巫峡酒，百丈内江船。
未息豺狼鬬，空催犬马年。
归朝多便道，搏击望秋天。','',''),('quantangshi-11843','送田四弟将军将夔州柏中丞命起居江陵节度阳城郡王卫公幕','杜甫','quantangshi','','卷12','离筵罢多酒，起地发寒塘。
回首中丞座，驰牋异姓王。
燕辞枫树日，雁度麦城霜。
空醉山翁酒，遥怜似葛强。','',''),('quantangshi-11844','送王十六判官','杜甫','quantangshi','','卷12','客下荆南尽，君今复入舟。
买薪犹白帝，鸣橹少沙头。
衡霍生春早，潇湘共海浮。
荒林庾信宅，为仗主人留。','',''),('quantangshi-11845','奉送卿二翁统节度镇军还江陵','杜甫','quantangshi','','卷12','火旗还锦缆，白马出江城。
嘹唳吟笳发，箫条别浦清。
寒空巫峡曙，落日渭阳明。
留滞嗟衰疾，何时见息兵。','',''),('quantangshi-11846','送鲜于万州迁巴州','杜甫','quantangshi','','卷12','京兆先时杰，琳琅照一门。
朝廷偏注意，接近与名藩。
祖帐排舟数，寒江触石喧。
看君妙为政，他日有殊恩。','',''),('quantangshi-11847','寄杜位','杜甫','quantangshi','','卷12','寒日经檐短，穷猨失木悲。
峡中为客恨，江上忆君时。
天地身何在，风尘病敢辞。
封书两行泪，霑洒裛新诗。','',''),('quantangshi-11848','奉寄李十五祕书二首 一','杜甫','quantangshi','','卷12','避暑云安县，秋风早下来。
暂留鱼复浦，同过楚王台。
猨鸟千崖窄，江湖万里开。
竹枝歌未好，画舸莫迟回。','',''),('quantangshi-11849','奉寄李十五祕书二首 二','杜甫','quantangshi','','卷12','行李千金赠，衣冠八尺身。
飞腾知有策，意度不无神。
班秩兼通贵，公侯出异人。
玄成负文彩，世业岂沈沦。','',''),('quantangshi-11850','奉送韦中丞之晋赴湖南','杜甫','quantangshi','','卷12','宠渥征黄渐，权宜借寇频。
湖南安背水，峡内忆行春。
王室仍多故，苍生倚大臣。
还将徐孺子，处处待高人。','',''),('quantangshi-11851','送李功曹之荆州充郑侍御判官重赠','杜甫','quantangshi','','卷12','曾闻宋玉宅，每欲到荆州。
此地生涯晚，遥悲水国秋。
孤城一柱观，落日九江流。
使者虽光彩，青枫远自愁。','',''),('quantangshi-11852','送孟十二仓曹赴东京选','杜甫','quantangshi','','卷12','君行别老亲，此去苦家贫。
藻镜留连客，江山顦顇人。
秋风楚竹冷，夜雪巩梅春。
朝夕高堂念，应宜彩服新。','',''),('quantangshi-11853','凭孟仓曹将书觅土娄旧庄','杜甫','quantangshi','','卷12','平居丧乱后，不到洛阳岑。
为历云山问，无辞荆棘深。
北风黄叶下，南浦白头吟。
十载江湖客，茫茫迟暮心。','',''),('quantangshi-11854','别苏徯（赴湖南幕）','杜甫','quantangshi','','卷12','故人有游子，弃掷傍天隅。
他日怜才命，居然屈壮图。
十年犹塌翼，绝倒为惊吁。
消渴今如在，提携愧老夫。
岂知台阁旧，先拂凤皇雏。
得实飜苍竹，栖枝把翠梧。
北辰当宇宙，南岳据江湖。
国带风尘色，兵张虎豹符。
数论封内事，挥发府中趋。
赠尔秦人策，莫鞭辕下驹。','',''),('quantangshi-11855','存殁口号二首 一','杜甫','quantangshi','','卷12','席谦不见近弹棊，毕曜仍传旧小诗。
玉局他年无限笑，白杨今日几人悲。','',''),('quantangshi-11856','存殁口号二首 二','杜甫','quantangshi','','卷12','郑公粉绘随长夜，曹霸丹青已白头。
天下何曾有山水，人间不解重骅骝。','',''),('quantangshi-11857','奉汉中王手札报韦侍御萧尊师亡','杜甫','quantangshi','','卷12','秋日萧韦逝，淮王报峡中。
少年疑柱史，多术怪仙公。
不但时人惜，祗应吾道穷。
一哀侵疾病，相识自儿童。
处处邻家笛，飘飘客子蓬。
强吟怀旧赋，已作白头翁。','',''),('quantangshi-11858','哭王彭州抡','杜甫','quantangshi','','卷12','执友惊沦没，斯人已寂寥。
新文生沈谢，异骨降松乔。
北部初高选，东堂早见招。
蛟龙缠倚劒，鸾凤夹吹箫。
历职汉庭久，中年胡马骄。
兵戈暗两观，宠辱事三朝。
蜀路江干窄，彭门地里遥。
解龟生碧草，谏猎阻清霄。
顷壮戎麾出，叨陪幕府要。
将军临气候，猛士寒风飙。
井漏泉谁汲，烽疎火不烧。
前筹自多暇，隐几接终朝。
翠石俄双表，寒松竟后凋。
赠诗焉敢坠，染翰欲无聊。
再哭经过罢，离魂去住销。
之官方玉折，寄葬与萍漂。
旷望渥洼道，霏微河汉桥。
夫人先即世，令子各清标。
巫峡长云雨，秦城近斗杓。
冯唐毛发白，归兴日萧萧。','',''),('quantangshi-11859','见萤火','杜甫','quantangshi','','卷12','巫山秋夜萤火飞，帘疎巧入坐人衣。
忽惊屋里琴书冷，复乱檐边星宿稀。
却绕井阑添个个，偶经花蘂弄辉辉。
苍江白发愁看汝，来岁如今归未归。','',''),('quantangshi-11860','吹笛','杜甫','quantangshi','','卷12','吹笛秋山风月清，谁家巧作断肠声。
风飘律吕相和切，月傍关山几处明。
胡骑中宵堪北走，武陵一曲想南征。
故园杨柳今摇落，何得愁中曲尽生。','',''),('quantangshi-11861','孤雁','杜甫','quantangshi','','卷12','孤雁不饮啄，飞鸣声念羣。
谁怜一片影，相失万重云。
望尽似犹见，哀多如更闻。
野鵶无意绪，鸣噪自纷纷。','',''),('quantangshi-11862','鸥','杜甫','quantangshi','','卷12','江浦寒鸥戏，无他亦自饶。
却思飜玉羽，随意点春苗。
雪暗还须浴，风生一任飘。
几羣沧海上，清影日萧萧。','',''),('quantangshi-11863','猨','杜甫','quantangshi','','卷12','褭褭啼虚壁，萧萧挂冷枝。
艰难人不见，隐见尔如知。
惯习元从众，全生或用奇。
前林腾每及，父子莫相离。','',''),('quantangshi-11864','黄鱼','杜甫','quantangshi','','卷12','日见巴东峡，黄鱼出浪新。
脂膏兼饲犬，长大不容身。
筒桶相沿久，风雷肯为神。
泥沙卷涎沫，回首怪龙鳞。','',''),('quantangshi-11865','白小','杜甫','quantangshi','','卷12','白小羣分命，天然二寸鱼。
细微霑水族，风俗当园蔬。
入肆银花乱，倾箱雪片虚。
生成犹拾卵，尽取义何如。','',''),('quantangshi-11866','麂','杜甫','quantangshi','','卷12','永与清溪别，蒙将玉馔俱。
无才逐仙隐，不敢恨庖厨。
乱世轻全物，微声及祸枢。
衣冠兼盗贼，饕餮用斯须。','',''),('quantangshi-11867','鸡','杜甫','quantangshi','','卷12','纪德名标五，初鸣度必三。
殊方听有异，失次晓无慙。
问俗人情似，充庖尔辈堪。
气交亭育际，巫峡漏司南。','',''),('quantangshi-11868','玉腕骝','杜甫','quantangshi','','卷12','闻说荆南马，尚书玉腕骝。
顿骖飘赤汗，踞蹐顾长楸。
胡虏三年入，干坤一战收。
举鞭如有问，欲伴习池游。','',''),('quantangshi-11869','见王监兵马使说近山有白黑二鹰罗者久取竟未能得王以为毛骨有异他鹰恐腊后春生骞飞避暖劲翮思秋之甚眇不可见请余赋诗 一','杜甫','quantangshi','','卷12','雪飞玉立尽清秋，不惜奇毛恣远游。
在野只教心力破，千人何事网罗求。
一生自猎知无敌，百中争能耻下韝。
鹏碍九天须却避，兔藏三穴莫深忧。','',''),('quantangshi-11870','见王监兵马使说近山有白黑二鹰罗者久取竟未能得王以为毛骨有异他鹰恐腊后春生骞飞避暖劲翮思秋之甚眇不可见请余赋诗 二','杜甫','quantangshi','','卷12','黑鹰不省人间有，度海疑从北极来。
正翮抟风超紫塞，立冬几夜宿阳台。
虞罗自各虚施巧，春雁同归必见猜。
万里寒空祗一日，金眸玉爪不凡才。','',''),('quantangshi-11871','太岁日','杜甫','quantangshi','','卷12','楚岸行将老，巫山坐复春。
病多犹是客，谋拙竟何人。
阊阖开黄道，衣冠拜紫宸。
荣光悬日月，赐与出金银。
愁寂鸳行断，参差虎穴邻。
西江元下蜀，北斗故临秦。
散地逾高枕，生涯脱要津。
天边梅柳树，相见几回新。','',''),('quantangshi-11872','元日示宗武','杜甫','quantangshi','','卷12','汝啼吾手战，吾笑汝身长。
处处逢正月，迢迢滞远方。
飘零还柏酒，衰病只藜牀。
训喻青衿子，名慙白首郎。
赋诗犹落笔，献寿更称觞。
不见江东弟，高歌泪数行。','',''),('quantangshi-11873','远怀舍弟颖观等','杜甫','quantangshi','','卷12','阳翟空知处，荆南近得书。
积年仍远别，多难不安居。
江汉春风起，冰霜昨夜除。
云天犹错莫，花萼尚萧疎。
对酒都疑梦，吟诗正忆渠。
旧时元日会，乡党羡吾庐。','',''),('quantangshi-11874','续得观书迎就当阳居止正月中旬定出三峡','杜甫','quantangshi','','卷12','自汝到荆府，书来数唤吾。
颂椒添讽咏，禁火卜欢娱。
舟楫因人动，形骸用杖扶。
天旋夔子国，春近岳阳湖。
发日排南喜，伤神散北吁。
飞鸣还接翅，行序密衔芦。
俗薄江山好，时危草木苏。
冯唐虽晚达，终觊在皇都。','',''),('quantangshi-11875','将别巫峡赠南卿兄瀼西果园四十亩','杜甫','quantangshi','','卷12','苔竹素所好，萍蓬无定居。
远游长儿子，几地别林庐。
杂蘂红相对，他时锦不如。
具舟将出峡，巡圃念携锄。
正月喧莺末，兹辰放鷁初。
雪篱梅可折，风榭柳微舒。
托赠卿家有，因歌野兴疎。
残生逗江汉，何处狎樵渔。','',''),('quantangshi-11876','送大理封主簿五郎亲事不合却赴通州主簿前阆州贤子余与主簿平章郑氏女子垂欲纳郑氏伯父京书至女子已前许他族亲事遂停','杜甫','quantangshi','','卷12','禁脔去东牀，趋庭赴北堂。
风波空远涉，琴瑟几虚张。
渥水出骐骥，昆山生凤皇。
两家诚款款，中道许苍苍。
颇谓秦晋匹，从来王谢郎。
青春动才调，白首缺辉光。
玉润终孤立，珠明得暗藏。
余寒折花卉，恨别满江乡。','',''),('quantangshi-11877','人日两篇 一','杜甫','quantangshi','','卷12','元日到人日，未有不阴时。
冰雪莺难至，春寒花较迟。
云随白水落，风振紫山悲。
蓬鬓稀疎久，无劳比素丝。','',''),('quantangshi-11878','人日两篇 二','杜甫','quantangshi','','卷12','此日此时人共得，一谈一笑俗相看。
尊前柏叶休随酒，胜里金花巧耐寒。
佩劒冲星聊暂拔，匣琴流水自须弹。
早春重引江湖兴，直道无忧行路难。','',''),('quantangshi-11879','江梅','杜甫','quantangshi','','卷12','梅蘂腊前破，梅花年后多。
绝知春意好，最奈客愁何。
雪树元同色，江风亦自波。
故园不可见，巫岫郁嵯峨。','',''),('quantangshi-11880','庭草','杜甫','quantangshi','','卷12','楚草经寒碧，逢春入眼浓。
旧低收叶举，新掩卷牙重。
步履宜轻过，开筵得屡供。
看花随节序，不敢强为容。','',''),('quantangshi-11881','大历三年春白帝城放船出瞿塘峡久居夔府将适江陵漂泊有诗凡四十韵','杜甫','quantangshi','','卷12','老向巴人里，今辞楚塞隅。
入舟飜不乐，解缆独长吁。
窄转深啼狖，虚随乱浴凫。
石苔凌几杖，空翠扑肌肤。
叠壁排霜劒，奔泉溅水珠。
杳冥藤上下，浓澹树荣枯。
神女峰娟妙，昭君宅有无。
曲留明怨惜，梦尽失欢娱。
摆阖盘涡沸，欹斜激浪输。
风雷缠地脉，冰雪耀天衢。
鹿角真走险，狼头如跋胡。
恶滩宁变色，高卧负微躯。
书史全倾挠，装囊半压濡。
生涯临臬兀，死地脱斯须。
不有平川决，焉知众壑趋。
干坤霾涨海，雨露洗春芜。
欧鸟牵丝扬，骊龙濯锦纡。
落霞沈绿绮，残月坏金枢。
泥笋苞初荻，沙茸出小蒲。
雁儿争水马，燕子逐樯乌。
绝岛容烟雾，环洲纳晓晡。
前闻辨陶牧，转眄拂宜都。
县郭南畿好，津亭北望孤。
劳心依憩息，朗咏划昭苏。
意遣乐还笑，衰迷贤与愚。
飘萧将素发，汩没听洪炉。
丘壑曾忘返，文章敢自诬。
此生遭圣代，谁分哭穷途。
卧疾淹为客，蒙恩早厠儒。
廷争酬造化，朴直乞江湖。
灧滪险相迫，沧浪深可逾。
浮名寻已已，嬾计却区区。
喜近天皇寺，先披古画图。
应经帝子渚，同泣舜苍梧。
朝士兼戎服，君王按湛卢。
旄头初俶扰，鹑首丽泥涂。
甲卒身虽贵，书生道固殊。
出尘皆野鹤，历块匪辕驹。
伊吕终难降，韩彭不易呼。
五云高太甲，六月旷抟扶。
回首黎元病，争权将帅诛。
山林托疲苶，未必免崎岖。','',''),('quantangshi-11882','巫山县汾州唐使君十八弟宴别兼诸公携酒乐相送率题小诗留于屋壁，','杜甫','quantangshi','','卷12','卧病巴东久，今年强作归。
故人犹远谪，兹日倍多违。
接宴身兼杖，听歌泪满衣。
诸公不相弃，拥别惜光辉。','',''),('quantangshi-11883','春夜峡州田侍御长史津亭留宴','杜甫','quantangshi','','卷12','北斗三更席，西江万里船。
杖藜登水榭，挥翰宿春天。
白发烦多酒，明星惜此筵。
始知云雨峡，忽尽下牢边。','',''),('quantangshi-11884','泊松滋江亭','杜甫','quantangshi','','卷12','沙帽随鸥鸟，扁舟系此亭。
江湖深更白，松竹远微青。
一柱全应近，高唐莫再经。
今宵南极外，甘作老人星。','',''),('quantangshi-11885','行次古城店泛江作不揆鄙拙奉呈江陵幕府诸公','杜甫','quantangshi','','卷12','老年常道路，迟日复山川。
白屋花开里，孤城麦秀边。
济江元自阔，下水不劳牵。
风蝶勤依浆，春鸥嬾避船。
王门高德业，幕府盛才贤。
行色兼多病，苍茫泛爱前。','',''),('quantangshi-11886','乘雨入行军六弟宅','杜甫','quantangshi','','卷12','曙角凌云罢，春城带雨长。
水花分堑弱，巢燕得泥忙。
令弟雄军佐，凡才污省郎。
萍漂忍流涕，衰飒近中堂。','',''),('quantangshi-11887','宴胡侍御书堂','杜甫','quantangshi','','卷12','江湖春欲暮，墙宇日犹微。
暗暗春籍满，轻轻花絮飞。
翰林名有素，墨客兴无违。
今夜文星动，吾侪醉不归。','',''),('quantangshi-11888','书堂饮既夜复邀李尚书下马月下赋绝句','杜甫','quantangshi','','卷12','湖水林风相与清，残尊下马复同倾。
久判野鹤如霜鬓，遮莫邻鸡下五更。','',''),('quantangshi-11889','上巳日徐司录林园宴集','杜甫','quantangshi','','卷12','鬓毛垂领白，花蘂亚枝红。
欹倒衰年废，招寻令节同。
薄衣临积水，吹面受和风。
有喜留攀桂，无劳问转蓬。','',''),('quantangshi-11890','奉送苏州李二十五长史丈之任','杜甫','quantangshi','','卷12','星坼台衡地，曾为人所怜。
公侯终必复，经术昔相传。
食德见从事，克家何妙年。
一毛生凤穴，三尺献龙泉。
赤壁浮春暮，姑苏落海边。
客间头最白，惆怅此离筵。','',''),('quantangshi-11891','暮春江陵送马大卿公恩命追赴阙下','杜甫','quantangshi','','卷12','自古求忠孝，名家信有之。
吾贤富才术，此道未磷缁。
玉府标孤映，霜蹄去不疑。
激扬音韵彻，籍甚众多推。
潘陆应同调，孙吴亦异时。
北辰征事业，南纪赴恩私。
卿月升金掌，王春度玉墀。
熏风行应律，湛露即歌诗。
天意高难问，人情老易悲。
尊前江汉阔，后会且深期。','',''),('quantangshi-11892','暮春陪李尚书李中丞过郑监湖亭泛舟','杜甫','quantangshi','','卷12','海内文章伯，湖边意绪多。
玉尊移晚兴，桂楫带酣歌。
春日繁鱼鸟，江天足芰荷。
郑庄宾客地，衰白远来过。','',''),('quantangshi-11893','奉送蜀州柏二别驾将中丞命赴江陵起居卫尚书太夫人因示从弟行军司马佐','杜甫','quantangshi','','卷12','中丞问俗画熊频，爱弟传书彩鷁新。
迁转五州防御使，起居八座太夫人。
楚宫腊送荆门水，白帝云偷碧海春。
报与惠连诗不惜，知吾斑鬓总如银。','',''),('quantangshi-11894','夏日杨长宁宅送崔侍御常正字入京','杜甫','quantangshi','','卷12','醉酒扬雄宅，升堂子贱琴。
不堪垂老鬓，还对欲分襟。
天地西江远，星辰北斗深。
乌台俯麟阁，长夏白头吟。','',''),('quantangshi-11895','和江陵宋大少府暮春雨后同诸公及舍弟宴书斋','杜甫','quantangshi','','卷12','渥洼汗血种，天上麒麟儿。
才士得神秀，书斋闻尔为。
棣华晴雨好，彩服暮春宜。
朋酒日欢会，老夫今始知。','',''),('quantangshi-11896','宇文晁尚书之甥崔彧司业之孙尚书之子重泛郑监前湖','杜甫','quantangshi','','卷12','郊扉俗远长幽寂，野水春来更接连。
锦席淹留还出浦，葛巾欹侧未回船。
尊当霞绮轻初散，棹拂荷珠碎却圆。
不但习池归酩酊，君看郑谷去夤缘。','',''),('quantangshi-11897','多病执热奉怀李尚书','杜甫','quantangshi','','卷12','衰年正苦病侵凌，首夏何须气郁蒸。
大水淼茫炎海接，奇峰硉兀火云升。
思霑道暍黄梅雨，敢望宫恩玉井冰。
不是尚书期不顾山阴野雪兴难乘。','',''),('quantangshi-11898','水宿遣兴奉呈羣公','杜甫','quantangshi','','卷12','鲁钝仍多病，逢迎远复迷。
耳聋须画字，发短不胜蓖。
泽国虽勤雨，炎天竟浅泥。
小江还积浪，弱缆且长堤。
归路非关北，行舟却向西。
暮年漂泊恨，今夕乱离啼。
童稚频书札，盘餐讵糁藜。
我行何到此，物理直难齐。
高枕飜星月，严城叠鼓鞞。
风号闻虎豹，水宿伴凫鹥。
异县惊虚往，同人惜解携。
蹉跎长泛鷁，展转屡鸣鸡。
嶷嶷瑚琏器，阴阴桃李蹊。
余波期救涸，费日苦轻赍。
支策门阑邃，肩舆羽翮低。
自伤甘贱役，谁愍强幽栖。
巨海能无钓，浮云亦有梯。
勋庸思树立，语默可端倪。
赠粟囷应指，登桥柱必题。
丹心老未折，时访武陵溪。','',''),('quantangshi-11899','奉贺阳城郡王太夫人恩命加邓国太夫人','杜甫','quantangshi','','卷12','卫幕衔恩重，潘舆送喜频。
济时瞻上将，锡号戴慈亲。
富贵当如此，尊荣迈等伦。
郡依封土旧，国与大名新。
紫诰鸾回纸，清朝燕贺人。
远传冬笋味，更觉彩衣春。
奕叶班姑史，芬芳孟母邻。
义方兼有训，词翰两如神。
委曲承颜体，骞飞报主身。
可怜忠与孝，双美画骐麟。','',''),('quantangshi-11900','江陵望幸','杜甫','quantangshi','','卷12','雄都元壮丽，望幸歘威神。
地利西通蜀，天文北照秦。
风烟含越鸟，舟楫控吴人。
未枉周王驾，终期汉武巡。
甲兵分圣旨，居守付宗臣。
早发云台杖，恩波起涸鳞。','',''),('quantangshi-11901','江边星月二首 一','杜甫','quantangshi','','卷12','骤雨清秋夜，金波耿玉绳。
天河元自白，江浦向来澄。
映物连珠断，缘空一镜升。
余光隐更漏，况乃露华凝。','',''),('quantangshi-11902','江边星月二首 二','杜甫','quantangshi','','卷12','江月辞风缆，江星别雾船。
鸡鸣还曙色，鹭浴自清川。
历历竟谁种，悠悠何处圆。
客愁殊未已，他夕始相鲜。','',''),('quantangshi-11903','舟月对驿近寺','杜甫','quantangshi','','卷12','更深不假烛，月朗自明船。
金刹清枫外，朱楼白水边。
城乌啼眇眇，野鹭宿娟娟。
皓首江湖客，钩帘独未眠。','',''),('quantangshi-11904','舟中','杜甫','quantangshi','','卷12','风餐江柳下，雨卧驿楼边。
结缆排鱼网，连樯竝米船。
今朝云细薄，昨夜月清圆。
飘泊南庭老，祗应学水仙。','',''),('quantangshi-11905','遣闷','杜甫','quantangshi','','卷12','地阔平沙岸，舟虚小洞房。
使尘来驿道，城日避乌樯。
暑雨留蒸湿，江风借夕凉。
行云星隐见，叠浪月光芒。
萤鉴缘帷彻，蛛丝罥鬓长。
哀筝犹凭几，鸣笛竟霑裳。
倚着如秦赘，过逢类楚狂。
气冲看劒匣，颖脱抚锥囊。
妖孽关东臭，兵戈陇右创。
时清疑武略，世乱局文场。
余力浮于海，端忧问彼苍。
百年从万事，故国耿难忘。','',''),('quantangshi-11906','江陵节度阳城郡王新楼成王请严侍御判官赋七字句同作','杜甫','quantangshi','','卷12','楼上炎天冰雪生，高飞燕雀贺新成。
碧窗宿雾蒙蒙湿，朱栱浮云细细轻。
杖钺褰帷瞻具美，投壶散帙有余清。
自公多暇延参佐，江汉风流万古情。','',''),('quantangshi-11907','又作此奉卫公','杜甫','quantangshi','','卷12','西北楼成雄楚都，远开山岳散江湖。
二仪清浊还高下，三伏炎蒸定有无。
推毂几年唯镇静，曳裾终日盛文儒。
白头授简焉能赋，愧似相如为大夫。','',''),('quantangshi-11908','舟出江陵南浦奉寄郑少尹','杜甫','quantangshi','','卷12','更欲投何处，飘然去此都。
形骸元土木，舟檝复江湖。
社稷缠妖气，干戈送老儒。
百年同弃物，万国尽穷途。
雨洗平沙静，天衔阔岸纡。
鸣螿随泛梗，别燕赴秋菰。
栖托难高卧，饥寒迫向隅。
寂寥相喣沫，浩荡报恩珠。
溟涨鲸波动，衡阳雁影徂。
南征问悬榻，东逝想乘桴。
滥窃商歌听，时忧卞泣诛。
经过忆郑驿，斟酌旅情孤。','',''),('quantangshi-11909','江南逢李龟年','杜甫','quantangshi','','卷12','歧王宅里寻常见，崔九堂前几度闻。
正是江南好风景，落花时节又逢君。','',''),('quantangshi-11910','官亭夕坐戏简颜十少府','杜甫','quantangshi','','卷12','南国调寒杵，西江浸日车。
客愁连蟋蟀，亭古带蒹葭。
不返青丝鞚，虚烧夜烛花。
老翁须地主，细细酌流霞。','',''),('quantangshi-11911','秋日荆南述怀三十韵','杜甫','quantangshi','','卷12','昔承推奖分，愧匪挺生材。
迟暮宫臣忝，艰危衮职陪。
扬镳随日驭，折槛出云台。
罪戾宽犹活，干戈塞未开。
星霜玄鸟变，身世白驹催。
伏枕因超忽，扁舟任往来。
九钻巴噀火，三蛰楚祠雷。
望帝传应实，昭王问不回。
蛟螭深作横，豺虎乱雄猜。
素业行已矣，浮名安在哉？
琴乌曲怨愤，庭鹤舞摧颓。
秋雨漫湘水，阴风过岭梅。
苦摇求食尾，常曝报恩顋。
结舌防谗柄，探肠有祸胎。
苍茫步兵哭，展转仲宣哀。
饥籍家家米，愁征处处杯。
休为贫士叹，任受众人咍。
得丧初难识，荣枯划易该。
差池分组冕，合沓起蒿莱。
不必伊周地，皆知屈宋才。
汉庭和异域，晋史坼中台。
霸业寻常体，忠臣忌讳灾。
羣公纷戮力，圣虑窅裴回。
数见铭钟鼎，真宜法斗魁。
愿闻锋镝铸，莫使栋梁摧。
盘石圭多翦，凶门毂少推。
垂旒资穆穆，祝网但恢恢。
赤雀飜然至，黄龙讵假媒。
贤非梦傅野，隐类凿颜坯。
自古江湖客，冥心苦死灰。','',''),('quantangshi-11912','秋日荆南送石首薛明府辞满告别奉寄薛尚书颂德敍怀斐然之作三十韵','杜甫','quantangshi','','卷12','南征为客久，西候别君初。
岁满归凫舄，秋来把雁书。
荆门留美化，姜被就离居。
闻道和亲人，垂名报国余。
连枝不日竝，八座几时除。
往者胡星孛，恭惟汉网疎。
风尘相澒洞，天地一丘墟。
殿瓦鸳鸯坼，宫帘翡翠虚。
钩陈摧徼道，枪累失储胥。
文物陪巡守，亲贤病拮据。
公时呵䝟貐，首唱却鲸鱼。
势惬宗萧相，材非一范雎。
尸填太行道，血走浚仪渠。
滏口师仍会，函关愤已摅。
紫微临大角，皇极正乘舆。
赏从频峨冕，殊私再直庐。
岂惟高卫霍，曾是接应徐。
降集飜翔凤，追攀绝众狙。
侍臣双宋玉，战策两穰苴。
鉴澈劳悬镜，荒芜已荷锄。
向来披述作，重此忆吹嘘。
白发甘凋丧，青云亦卷舒。
经纶功不朽，跋涉体何如。
应讶耽湖橘，常餐占野蔬。
十年婴药饵，万里狎樵渔。
扬子淹投阁，邹生惜曳裾。
但惊飞熠耀，不记改蟾蜍。
烟雨封巫峡，江淮略孟诸。
汤池虽险固，辽海尚填淤。
努力输肝胆，休烦独起予。','',''),('quantangshi-11913','哭李尚书','杜甫','quantangshi','','卷12','漳滨与蒿里，逝水竟同年。
欲挂留徐劒，犹回忆戴船。
相知成白首，此别间黄泉。
风雨嗟何及，江湖涕泫然。
修文将管辂，奉使失张骞。
史阁行人在，诗家秀句传。
客亭鞍马绝，旅榇网虫悬。
复魄昭丘远，归魂素浐偏。
樵苏封葬地，喉舌罢朝天。
秋色凋春草，王孙若个边。','',''),('quantangshi-11914','重题','杜甫','quantangshi','','卷12','涕泗不能收，哭君余白头。
儿童相识尽，宇宙此生浮。
江雨铭旌湿，湖风井径秋。
还瞻魏太子，宾客减应刘。','',''),('quantangshi-11915','独坐','杜甫','quantangshi','','卷12','悲愁回白首，倚杖背孤城。
江敛洲渚出，天虚风物清。
沧溟服衰谢，朱绂负平生。
仰羡黄昏鸟，投林羽翮轻。','',''),('quantangshi-11916','暮归','杜甫','quantangshi','','卷12','霜黄碧梧白鹤楼，城上击拆复乌啼。
客子入门月皎皎，谁家捣练风凄凄。
南渡桂水关舟檝，北归秦川多鼓鞞。
年过半百不称意，明日看云还杖藜。','',''),('quantangshi-11917','移居公安敬赠卫大郎','杜甫','quantangshi','','卷12','卫侯不易得，余病汝知之。
雅量涵高远，清襟照等夷。
平生感意气，少小爱文辞。
河海由来合，风云若有期。
形容劳宇宙，质朴谢轩墀。
自古幽人泣，留年壮士悲。
水烟通径草，秋露接园葵。
入邑豺狼鬬，伤弓鸟雀饥。
白头供宴语，乌几伴栖迟。
交态遭轻薄，今朝豁所思。','',''),('quantangshi-11918','公安送韦二少府匡赞','杜甫','quantangshi','','卷12','逍遥公后世多贤，送尔维舟惜此筵。
念我能书数字至，将诗不必万人传。
时危兵甲黄尘里，日短江湖白发前。
古往今来皆涕泪，断肠分手各风烟。','',''),('quantangshi-11919','赠虞十五司马','杜甫','quantangshi','','卷12','远师虞祕监，今喜识玄孙。
形像丹青逼，家声器宇存。
凄凉怜笔势，浩荡问词源。
爽气金天豁，清谈玉露繁。
伫鸣南岳凤，欲化北溟鲲。
交态知浮俗，儒流不异门。
过逢联客位，日夜倒芳尊。
沙岸风吹叶，云江月上轩。
百年嗟已半，四座敢辞喧。
书籍终相与，青山隔故园。','',''),('quantangshi-11920','公安县怀古','杜甫','quantangshi','','卷12','野旷吕蒙营，江深刘备城。
寒天催日短，风浪与云平。
洒落君臣契，飞腾战伐名。
维舟倚前浦，长啸一含情。','',''),('quantangshi-11921','公安送李二十九弟晋肃入蜀余下沔鄂','杜甫','quantangshi','','卷12','正解柴桑缆，仍看蜀道行。
樯乌相背发，塞雁一行鸣。
南纪连铜柱，西江接锦城。
凭将百钱卜，飘泊问君平。','',''),('quantangshi-11922','宴王使君宅题二首 一','杜甫','quantangshi','','卷12','汉主追韩信，苍生起谢安。
吾徒自漂泊，世事各艰难。
逆旅招邀近，他乡思绪宽。
不材甘朽质，高卧岂泥蟠。','',''),('quantangshi-11923','宴王使君宅题二首 二','杜甫','quantangshi','','卷12','泛爱容霜发，留欢卜夜闲。
自吟诗送老，相劝酒开颜。
戎马今何地，乡园独旧山。
江湖堕清月，酩酊任扶还。','',''),('quantangshi-11924','留别公安太易沙门','杜甫','quantangshi','','卷12','隐居欲就庐山远，丽藻初逢休上人。
数问舟航留制作，长开箧笥拟心神。
沙村白雪仍含冻，江县红梅已放春。
先蹋炉峰置兰若，徐飞锡杖出风尘。','',''),('quantangshi-11925','晓发公安','杜甫','quantangshi','','卷12','北城击柝复欲罢，东方明星亦不迟。
邻鸡野哭如昨日，物色生态能几时。
舟檝眇然自此去，江湖远适无前期。
出门转眄已陈迹，药饵扶吾随所之。','',''),('quantangshi-11926','泊岳阳城下','杜甫','quantangshi','','卷12','江国逾千里，山城仅百层。
岸风飜夕浪，舟雪洒寒灯。
留滞才难尽，艰危气益增。
图南未可料，变化有鲲鹏。','',''),('quantangshi-11927','缆船苦风戏题四韵奉简郑十三判官','杜甫','quantangshi','','卷12','楚岸朔风疾，天寒鸧鸹呼。
涨沙霾草树，舞雪渡江湖。
吹帽时时落，维舟日日孤。
因声置驿外，为觅酒家垆。','',''),('quantangshi-11928','登岳阳楼','杜甫','quantangshi','','卷12','昔闻洞庭水，今上岳阳楼。
吴楚东南坼，干坤日夜浮。
亲朋无一字，老病有孤舟。
戎马关山北，凭轩涕泗流。','',''),('quantangshi-11929','陪裴使君登岳阳楼','杜甫','quantangshi','','卷12','湖阔兼云雾，楼孤属晚晴。
礼加徐孺子，诗接谢宣城。
雪岸丛梅发，春泥百草生。
敢违渔父问，从此更南征。','',''),('quantangshi-11930','过南岳入洞庭湖','杜甫','quantangshi','','卷12','洪波忽争道，岸转异江湖。
鄂渚分云树，衡山引舳舻。
翠牙穿裛桨，碧节上寒蒲。
病渴身何去，春生力更无。
壤童犂雨雪，渔屋架泥涂。
欹侧风帆满，微冥水驿孤。
悠悠回赤壁，浩浩略苍梧。
帝子留遗恨，曹公屈壮图。
圣朝光御极，残孽驻艰虞。
才淑随厮养，名贤隐锻炉。
邵平元入汉，张翰后归吴。
莫怪啼痕数，危樯逐夜乌。','',''),('quantangshi-11931','宿青草湖','杜甫','quantangshi','','卷12','洞庭犹在目，青草续为名。
宿桨依农事，邮签报水程。
寒冰争倚薄，云月递微明。
湖雁双双起，人来故北征。','',''),('quantangshi-11932','宿白沙驿','杜甫','quantangshi','','卷12','水宿仍余照，人烟复此亭。
驿边沙旧白，湖外草新青。
万象皆春气，孤槎自客星。
随波无限月，的的近南溟。','',''),('quantangshi-11933','湘夫人祠','杜甫','quantangshi','','卷12','肃肃湘妃庙，空墙碧水春。
虫书玉佩藓，燕舞翠帷尘。
晚泊登汀树，微馨借渚苹。
苍梧恨不尽，染泪在丛筠。','',''),('quantangshi-11934','祠南夕望','杜甫','quantangshi','','卷12','百丈牵江色，孤舟泛日斜。
兴来犹杖屦，目断更云沙。
山鬼迷春竹，湘娥倚暮花。
湖南清绝地，万古一长嗟。','',''),('quantangshi-11935','登白马潭','杜甫','quantangshi','','卷12','水生春缆没，日出野船开。
宿鸟行犹去，丛花笑不来。
人人伤白首，处处接金杯。
莫道新知要，南征且未回。','',''),('quantangshi-11936','归雁','杜甫','quantangshi','','卷12','闻道今春雁，南归自广州。
见花辞涨海，避雪到罗浮。
是物关兵气，何时免客愁。
年年霜露隔，不过五湖秋。','',''),('quantangshi-11937','野望','杜甫','quantangshi','','卷12','纳纳干坤大，行行郡国遥。
云山兼五岭，风壤带三苗。
野树侵江阔，春蒲长雪消。
扁舟空老去，无补圣明朝。','',''),('quantangshi-11938','入乔口','杜甫','quantangshi','','卷12','漠漠旧京远，迟迟归路赊。
残年傍水国，落日对春华。
树蜜早蠭乱，江泥轻燕斜。
贾生骨已朽，凄恻近长沙。','',''),('quantangshi-11939','铜官渚守风','杜甫','quantangshi','','卷12','不夜楚帆落，避风湘渚间。
水耕先浸草，春火更烧山。
早泊云物晦，逆行波浪悭。
飞来双白鹤，过去杳难攀。','',''),('quantangshi-11940','北风','杜甫','quantangshi','','卷12','春生南国瘴，气待北风苏。
向晚霾残日，初宵鼓大炉。
爽携卑湿地，声拔洞庭湖。
万里鱼龙伏，三更鸟兽呼。
涤除贪破浪，愁绝付摧枯。
执热沈沈在，凌寒往往须。
且知宽疾胏，不敢恨危途。
再宿烦舟子，衰容问仆夫。
今晨非盛怒，便道即长驱。
隐几看帆席，云州涌坐隅。','',''),('quantangshi-11941','双枫浦','杜甫','quantangshi','','卷12','辍棹青枫浦，双枫旧已摧。
自惊衰谢力，不道栋梁材。
浪足浮纱帽，皮须截锦苔。
江边地有主，暂借上天回。','',''),('quantangshi-11942','奉送王信州崟北归','杜甫','quantangshi','','卷12','朝廷防盗贼，供给愍诛求。
下诏选郎署，传声能典州。
苍生今日困，天子向时忧。
井屋有烟起，疮痍无血流。
壤歌唯海甸，画角自山楼。
白发寐常早，荒榛农复秋。
解龟逾卧辙，遣骑觅扁舟。
徐榻不知倦，颍川何以酬。
尘生彤管笔，寒腻黑貂裘。
高义终焉在，斯文去矣休。
别离同雨散，行止各云浮。
林热鸟开口，江浑鱼掉头。
尉佗虽北拜，太史尚南留。
军旅应都息，寰区要尽收。
九重思谏诤，八极念怀柔。
徙倚瞻王室，从容仰庙谋。
故人持雅论，绝塞豁穷愁。
复见陶唐理，甘为汗漫游。','',''),('quantangshi-11943','江阁卧病走笔寄呈崔卢两侍御','杜甫','quantangshi','','卷12','客子庖厨薄，江楼枕席清。
衰年病祗瘦，长夏想为情。
滑忆雕胡饭，香闻锦带羹。
溜匙兼暖腹，谁欲致杯甖。','',''),('quantangshi-11944','潭州送韦员外牧韶州','杜甫','quantangshi','','卷12','炎海韶州牧，风流汉署郎。
分符先令望，同舍有辉光。
白首多年疾，秋天昨夜凉。
洞庭无过雁，书疏莫相忘。','',''),('quantangshi-11945','江阁对雨有怀行营裴二端公','杜甫','quantangshi','','卷12','南纪风涛壮，阴晴屡不分。
野流行地日，江入度山云。
层阁凭雷殷，长空水面文。
雨来铜柱北，应洗伏波军。','',''),('quantangshi-11946','酬韦韶州见寄','杜甫','quantangshi','','卷12','养拙江湖外，朝廷记忆疎。
深慙长者辙，重得故人书。
白发丝难理，新诗锦不如。
虽无南去雁，看取北来鱼。','',''),('quantangshi-11947','千秋节有感二首 一','杜甫','quantangshi','','卷12','自罢千秋节，频伤八月来。
先朝常宴会，壮观已尘埃。
凤纪编生日，龙池堑劫灰。
湘川新涕泪，秦树远楼台。
宝镜羣臣得，金吾万国回。
衢尊不重饮，白首独余哀。','',''),('quantangshi-11948','千秋节有感二首 二','杜甫','quantangshi','','卷12','御气云楼敞，含风彩仗高。
仙人张内乐，王母献宫桃。
罗袜红蕖艳，金羁白雪毛。
舞阶衔寿酒，走索背秋毫。
圣主他年贵，边心此日劳。
桂江流向北，满眼送波涛。','',''),('quantangshi-11949','晚秋长沙蔡五侍御饮筵送殷六参军归澧州觐省','杜甫','quantangshi','','卷12','佳士欣相识，慈颜望远游。
甘从投辖饮，肯作置书邮。
高鸟黄云暮，寒蝉碧树秋。
湖南冬不雪，吾病得淹留。','',''),('quantangshi-11950','湖中送敬十使君适广陵','杜甫','quantangshi','','卷12','相见各头白，其如离别何。
几年一会面，今日复悲歌。
少壮乐难得，岁寒心匪他。
气缠霜匣满，冰置玉壶多。
遭乱实漂泊，济时曾琢磨。
形容吾校老，胆力尔谁过。
秋晚岳增翠，风高湖涌波。
骞腾访知己，淮海莫磋跎。','',''),('quantangshi-11951','长沙送李十一','杜甫','quantangshi','','卷12','与子避地西康州，洞庭相逢十二秋。
远愧尚方曾赐履，竟非吾土倦登楼。
久存胶漆应难竝，一辱泥涂遂晚收。
李杜齐名真忝窃，朔云寒菊倍离忧。','',''),('quantangshi-11952','重送刘十弟判官','杜甫','quantangshi','','卷12','分源豕韦派，别浦雁宾秋。
年事推兄忝，人才觉弟优。
经过辨丰劒，意气逐吴钩。
垂翅徒衰老，先鞭不滞留。
本枝凌岁晚，高义豁穷愁。
他日临江待，长沙旧驿楼。','',''),('quantangshi-11953','奉赠卢五丈参谋','杜甫','quantangshi','','卷12','恭惟同自出，妙选异高标。
入幕知孙楚，披襟得郑侨。
丈人藉才地，门阀冠云霄。
老矣逢迎拙，相于契托饶。
赐钱倾府待，争米驻船遥。
邻好艰难薄，氓心杼轴焦。
客星空伴使，寒水不成潮。
素发干垂领，银章破在腰。
说诗能累夜，醉酒或连朝。
藻翰惟牵率，湖山合动摇。
时清非造次，兴尽却萧条。
天子多恩泽，苍生转寂寥。
休传鹿是马，莫信鵩如鸮。
未解依依袂，还斟泛泛瓢。
流年疲蟋蟀，体物幸鹪鹩。
辜负沧州愿，谁云晚见招。','',''),('quantangshi-11954','登舟将适汉阳','杜甫','quantangshi','','卷12','春宅弃汝去，秋帆催客归。
庭蔬尚在眼，浦浪已吹衣。
生理飘荡拙，有心迟暮归。
中原戎马盛，远道素书稀。
塞雁与时集，樯乌终岁飞。
鹿门自此往，永息汉阴机。','',''),('quantangshi-11955','暮秋将归秦留别湖南幕府亲友','杜甫','quantangshi','','卷12','水阔苍梧野，天高白帝秋。
途穷那免哭，身老不禁愁。
大府才能会，诸公德业优。
北归冲雨雪，谁悯敝貂裘。','',''),('quantangshi-11956','送卢十四弟侍御护韦尚书灵榇归上都二十韵','杜甫','quantangshi','','卷12','素幕渡江远，朱幡登陆微。
悲鸣驷马顾，失涕万人挥。
参佐哭辞毕，门阑谁送归。
从公伏事久，之子俊才稀。
长路更执绋，此心犹倒衣。
感恩义不小，怀旧礼无违。
墓待龙骧诏，台迎獬豸威。
深衷见士则，雅论在兵机。
戎狄乘妖气，尘沙落禁闱。
往年朝谒断，他日埽除非。
但促铜壶箭，休添玉帐旗。
动询黄阁老，肯虑白登围。
万姓疮痍合，羣凶嗜欲肥。
刺规多谏诤，端拱自光辉。
俭约前王体，风流后代希。
对敭期特达，衰朽再芳菲。
空里愁书字，山中疾采薇。
拨杯要忽罢，抱被宿何依。
眼冷看征盖，儿扶立钓矶。
清霜洞庭叶，故就别时飞。','',''),('quantangshi-11957','哭李常侍峄二首 一','杜甫','quantangshi','','卷12','一代风流尽，修文地下深。
斯人不重见，将老失知音。
短日行梅岭，寒山落桂林。
长安若个畔，犹想映貂金。','',''),('quantangshi-11958','哭李常侍峄二首 二','杜甫','quantangshi','','卷12','青琐陪双入，铜梁阻一辞。
风尘逢我地，江汉哭君时。
次第寻书札，呼儿检赠诗。
发挥王子表，不愧史臣词。','',''),('quantangshi-11959','哭韦大夫之晋','杜甫','quantangshi','','卷12','凄怆郇瑕色，差池弱冠年。
丈人叨礼数，文律早周旋。
台阁黄图里，簪裾紫盖边。
尊荣真不忝，端雅独翛然。
贡喜音容间，冯招病疾缠。
南过骇仓卒，北思悄联緜。
鵩鸟长沙讳，犀牛蜀郡怜。
素车犹恸哭，宝劒欲高悬。
汉道中兴盛，韦经亚相传。
冲融标世业，磊落映时贤。
城府深朱夏，江湖眇霁天。
绮楼关树顶，飞旐泛堂前。
帟幕疑风燕，笳箫急暮蝉。
兴残虚白室，迹断孝廉船。
童孺交游尽，喧卑俗事牵。
老来多涕泪，情在强诗篇。
谁寄方隅理，朝难将帅权。
春秋褒贬例，名器重双全。','',''),('quantangshi-11960','舟中夜雪有怀卢十四侍御弟','杜甫','quantangshi','','卷12','朔风吹桂水，朔雪夜纷纷。
暗度南楼月，寒深北渚云。
烛斜初近见，舟重竟无闻。
不识山阴道，听鸡更忆君。','',''),('quantangshi-11961','对雪','杜甫','quantangshi','','卷12','北雪犯长沙，胡云冷万家。
随风且间叶，带雨不成花。
金错囊从罄，银壶酒易赊。
无人竭浮蚁，有待至昏鸦。','',''),('quantangshi-11962','楼上','杜甫','quantangshi','','卷12','天地空搔首，频抽白玉簪。
皇舆三极北，身事五湖南。
恋阙劳肝肺，论材愧杞柟。
乱离难自救，终是老湘潭。','',''),('quantangshi-11963','冬晚送长孙渐舍人归州','杜甫','quantangshi','','卷12','参卿休坐幄，荡子不还乡。
南客潇湘外，西戎鄠杜旁。
衰年倾盖晚，费日系舟长。
会面思来札，销魂逐去樯。
云晴鸥更舞，风逆雁无行。
匣里雌雄劒，吹毛任选将。','',''),('quantangshi-11964','暮冬送苏四郎徯兵曹适桂州','杜甫','quantangshi','','卷12','飘飘苏季子，六印佩何迟。
早作诸侯客，兼工古体诗。
尔贤埋照久，余病长年悲。
卢绾须征日，楼兰要斩时。
岁阳初盛动，王化久磷缁。
为人苍梧庙，看云哭九疑。','',''),('quantangshi-11965','风疾舟中伏枕书怀三十六韵奉呈湖南亲友','杜甫','quantangshi','','卷12','轩辕休制律，虞舜罢弹琴。
尚错雄鸣管，犹伤半死心。
圣贤名古邈，羇旅病年侵。
舟泊常依震，湖平早见参。
如闻马融笛，若倚仲宣襟。
故国悲寒望，羣云惨岁阴。
水乡霾白屋，枫岸叠青岑。
郁郁冬炎瘴，蒙蒙雨滞淫。
鼓迎非祭鬼，弹落似鸮禽。
兴尽才无闷，愁来遽不禁。
生涯相汩没，时物自萧森。
疑惑尊中弩，淹留冠上簪。
牵裾惊魏帝，投阁为刘歆。
狂走终奚适，微才谢所钦。
吾安藜不糁，汝贵玉为琛。
乌几重重缚，鹑衣寸寸针。
哀伤同庾信，述作异陈琳。
十暑岷山葛，三霜楚户砧。
叨陪锦帐座，久放白头吟。
反朴时难遇，忘机陆易沈。
应过数粒食，得近四知金。
春草封归恨，源花费独寻。
转蓬忧悄悄，行药病涔涔。
瘗夭追潘岳，持危觅邓林。
蹉跎飜学步，感激在知音。
却假苏张舌，高夸周宋镡。
纳流迷浩汗，峻址得嵚崟。
城府开清旭，松筠起碧浔。
披颜争倩倩，逸足竞骎骎。
朗鉴存愚直，皇天实照临。
公孙仍恃险，侯景未生擒。
书信中原阔，干戈北斗深。
畏人千里井，问俗九州箴。
战血流依旧，军声动至今。
葛洪尸定解，许靖力还任。
家事丹砂诀，无成涕作霖。','',''),('quantangshi-11966','奉赠萧二十使君','杜甫','quantangshi','','卷12','惜在严公幕，俱为蜀使臣。
艰危参大府，前后间清尘。
起草鸣先路，乘槎动要津。
王凫聊暂出，萧雉只相驯。
终始任安义，荒芜孟母邻。
联翩匍匐礼，意气死生亲。
张老存家事，嵇康有故人。
食恩慙卤莽，镂骨抱酸辛。
巢许山林志，夔龙廊庙珍。
鹏图乃矫翼，熊轼且移轮。
磊落衣冠地，苍茫土木身。
埙篪鸣自合，金石莹逾新。
重忆罗江外，同游锦水滨。
结欢随过隙，怀旧益霑巾。
旷绝含香舍，稽留伏枕辰。
停骖双阙早，回雁五湖春。
不达长卿病，从来原宪贫。
监河受贷粟，一起辙中鳞。','',''),('quantangshi-11967','奉送二十三舅录事之摄郴州','杜甫','quantangshi','','卷12','贤良归盛族，吾舅尽知名。
徐庶高交友，刘牢出外甥。
泥涂岂珠玉，环堵但柴荆。
衰老悲人世，驱驰厌甲兵。
气春江上别，泪血渭阳情。
舟鷁排风影，林乌反哺声。
永嘉多北至，句漏且南征。
必见公侯复，终闻盗贼平。
郴州颇凉冷，橘井尚凄清。
从役何蛮貊，居官志在行。','',''),('quantangshi-11968','送魏二十四司直充岭南掌选崔郎中判官兼寄韦韶州','杜甫','quantangshi','','卷12','选曹分五岭，使者历三湘。
才美膺推荐，君行佐纪纲。
佳声斯共远，雅节在周防。
明白山涛鉴，嫌疑陆贾装。
故人湖外少，春日岭南长。
凭报韶州牧，新诗昨寄将。','',''),('quantangshi-11969','送赵十七明府之县','杜甫','quantangshi','','卷12','连城为宝重，茂宰得才新。
山雉迎舟楫，江花报邑人。
论交飜恨晚，卧病却愁春。
惠爱南翁悦，余波及老身。','',''),('quantangshi-11970','燕子来舟中作','杜甫','quantangshi','','卷12','湖南为客动经春，燕子衔泥两度新。
旧入故园常识主，如今社日远看人。
可怜处处巢君室，何异飘飘托此身。
暂语船樯还起去，穿花落水益霑巾。','',''),('quantangshi-11971','同豆卢峰知字韵','杜甫','quantangshi','','卷12','炼金欧冶子，喷玉大宛儿。
符彩高无敌，聪明达所为。
梦兰他日应，折桂早年知。
烂漫通经术，光芒刷羽仪。
谢庭瞻不远，潘省会于斯。
倡和将雏曲，田翁号鹿皮。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-11972','归雁二首 一','杜甫','quantangshi','','卷12','万里衡阳雁，今年又北归。
双双瞻客上，一一背人飞。
云里相呼疾，沙边自宿稀。
系书元浪语，愁寂故山薇。','',''),('quantangshi-11973','归雁二首 二','杜甫','quantangshi','','卷12','欲雪违胡地，先花别楚云。
却过清渭影，高起洞庭羣。
塞北春阴暮，江南日色曛。
伤弓流落羽，行断不堪闻。','',''),('quantangshi-11974','小寒食舟中作','杜甫','quantangshi','','卷12','佳辰强饭食犹寒，隐几萧条带鹖冠。
春水船如天上坐，老年花似雾中看。
娟娟戏蝶过闲幔，片片轻鸥下急湍。
云白山清万余里，愁看直北是长安。','',''),('quantangshi-11975','清明二首 一','杜甫','quantangshi','','卷12','朝来新火起新烟，湖色春光净客船。
绣羽衔花他自得，红颜骑竹我无缘。
胡童结束还难有，楚女腰肢亦可怜。
不见定王城旧处，长怀贾傅井依然。
虚霑焦举为寒食，实藉严君卖卜钱。
钟鼎山林各天性，浊醪粗饭任吾年。','',''),('quantangshi-11976','清明二首 二','杜甫','quantangshi','','卷12','此身飘泊苦西东，右臂偏枯半耳聋。
寂寂系舟双下泪，悠悠伏枕左书空。
十年蹴鞠将雏远，万里秋千习俗同。
旅雁上云归紫塞，家人钻火用青枫。
秦城楼阁烟花里，汉主山河锦绣中。
风水春来洞庭阔，白苹愁杀白头翁。','',''),('quantangshi-11977','发潭州','杜甫','quantangshi','','卷12','夜醉长沙酒，晓行湘水春。
岸花飞送客，樯燕语留人。
贾傅才未有，褚公书绝伦。
高名前后事，回首一伤神。','',''),('quantangshi-11978','回棹','杜甫','quantangshi','','卷12','宿昔试安命，自私犹畏天。
劳生系一物，为客费多年。
衡岳江湖大，蒸池疫疠偏。
散才婴薄俗，有迹负前贤。
巾拂那关眼，瓶罍易满船。
火云滋垢腻，冻雨裛沈緜。
强饭莼添滑，端居茗续煎。
清思汉水上，凉忆岘山巅。
顺浪飜堪倚，回帆又省牵。
吾家碑不昧，王氏井依然。
几杖将衰齿，茅茨寄短椽。
灌园曾取适，游寺可终焉。
遂性同渔父，成名异鲁连。
篙师烦尔送，朱夏及寒泉。','',''),('quantangshi-11979','赠韦七赞善','杜甫','quantangshi','','卷12','乡里衣冠不乏贤，杜陵韦曲未央前。
尔家最近魁三象，时论同归尺五天。
北走关山开雨雪，南游花柳塞云烟。
洞庭春色悲公子，鰕菜忘归范蠡船。','',''),('quantangshi-11980','奉酬寇十侍御锡见寄四韵复寄寇','杜甫','quantangshi','','卷12','往别郇瑕地，于今四十年。
来簪御府笔，故泊洞庭船。
诗忆伤心处，春深把臂前。
南瞻按百越，黄帽待君偏。','',''),('quantangshi-11981','酬郭十五受判官','杜甫','quantangshi','','卷12','才微岁老尚虚名，卧病江湖春复生。
药裹关心诗总废，花枝照眼句还成。
只同燕石能星陨，自得隋珠觉夜明。
乔口橘洲风浪促，系帆何惜片时程。','',''),('quantangshi-11982','衡州送李大夫七丈勉赴广州','杜甫','quantangshi','','卷12','斧钺下青冥，楼船过洞庭。
北风随爽气，南斗避文星。
日月笼中鸟，干坤水上萍。
王孙丈人行，垂老见飘零。','',''),('quantangshi-11983','哭长孙侍御','杜甫','quantangshi','','卷12','道为谋书重，名因赋颂雄。
礼闱曾擢桂，宪府旧乘骢。
流水生涯尽，浮云世事空。
唯余旧台柏，萧瑟九原中。','',''),('quantangshi-11984','虢国夫人','杜甫','quantangshi','','卷12','虢国夫人承主恩，平明上马入宫门。
却嫌脂粉涴颜色，澹埽蛾眉朝至尊。','',''),('quantangshi-11985','军中醉饮寄沈八刘叟','杜甫','quantangshi','','卷12','酒渴爱江清，余甘漱晚汀。
輭沙欹坐稳，冷石醉眠醒。
野膳随行帐，华音发从伶。
数杯君不见，醉已遣沈冥。','',''),('quantangshi-11986','杜鹃行','杜甫','quantangshi','','卷12','古时杜宇称望帝，魂作杜鹃何微细。
跳枝窜叶树木中，抢佯瞥捩雌随雄。
毛衣惨黑貌顦顇，众鸟安肯相尊崇。
隳形不敢栖华屋，短翮唯愿巢深丛。
穿皮啄朽觜欲秃，苦饥始得食一虫。
谁言养雏不自哺，此语亦足为愚蒙。
声音咽咽如有谓，号啼略与婴儿同。
口干垂血转迫促，似欲上诉于苍穹。
蜀人闻之皆起立，至今斅学传遗风。
乃知变化不可穷，岂知昔日居深宫，嫔嫱左右如花红。','',''),('quantangshi-11987','闻惠二过东溪特一送','杜甫','quantangshi','','卷12','惠子白驹瘦，归溪唯病身。
皇天无老眼，空谷滞斯人。
崖蜜松花熟，山杯竹叶新。
柴门了无事，黄绮未称臣。','',''),('quantangshi-11988','舟泛洞庭','杜甫','quantangshi','','卷12','蛟室围青草，龙堆拥白沙。
护江盘古木，迎棹舞神鵶。
破浪南风正，收颿畏日斜。
云山千万叠，底处上仙槎。','',''),('quantangshi-11989','李盐铁二首','杜甫','quantangshi','','卷12','落叶春风起，高城烟雾开。
杂花分户映，娇燕入檐回。
一见能倾产，虚怀只爱才。
盐官虽绊骥，名是汉庭来。','',''),('quantangshi-11990','长吟','杜甫','quantangshi','','卷12','江渚飜鸥戏，官桥带柳阴。
江飞兢渡日，草见蹋春心。
已拨形骸累，真为烂漫深。
赋诗歌句稳，不免自长吟。','',''),('quantangshi-11991','绝句九首 七','杜甫','quantangshi','','卷12','闻道巴山里，春船正好行。
都将百年兴，一望九江城。','',''),('quantangshi-11992','绝句九首 八','杜甫','quantangshi','','卷12','水槛温江口，茅堂石笋西。
移船先主庙，洗药淙沙溪。','',''),('quantangshi-11993','绝句九首 九','杜甫','quantangshi','','卷12','设道春来好，狂风大放颠。
吹花随水去，飜却钓鱼船。','',''),('quantangshi-11994','瞿唐怀古','杜甫','quantangshi','','卷12','西南万壑注，勍敌两崖[开]。
地与山根裂，江从月窟来。
削成当白帝，空曲隐阳台。
疏凿功虽美，陶钧力大哉。','',''),('quantangshi-11995','送司马入京','杜甫','quantangshi','','卷12','羣盗至今日，先朝忝从臣。
叹君能恋主，久客羡归秦。
黄阁长司谏，丹墀有故人。
向来论社稷，为话涕霑巾。','',''),('quantangshi-11996','惜别行送刘仆射判官','杜甫','quantangshi','','卷12','闻道南行市骏马，不限匹数军中须。
襄阳幕府天下异，主将俭省忧艰虞。
祗收壮健胜铁甲，岂因格鬬求龙驹。
而今西北自反胡，骐驎荡尽一匹无。
龙媒真种在帝都，子孙永落西南隅。
向非戎事备征伐，君肯辛苦越江湖。
江湖凡马多顦顇，衣冠往往乘蹇驴。
梁公富贵于身疎，号令明白人安居。
俸钱时散士子尽，府库不为骄豪虚。
以兹报主寸心赤，气却西戎回北狄。
罗网羣马籍马多，气在驱驰出金帛。
刘侯奉使光推择，滔滔才略沧溟窄。
杜陵老翁秋系船，扶病相识长沙驿。
强梳白发提胡卢，手把菊花路旁摘。
九州兵革浩茫茫，三叹聚散临重阳。
当杯对客忍流涕，君不觉老夫神内伤。','',''),('quantangshi-11997','呀鹘行','杜甫','quantangshi','','卷12','病鹘孤飞俗眼丑，每夜江边宿衰柳。
清秋落日已侧身，过雁归鵶错回首。
紧脑雄姿迷所向，疎翮稀毛不可状。
强神迷复皂雕前，俊才早在苍鹰上。
风涛飒飒寒山阴，熊罴欲蛰龙蛇深。
念尔此时有一掷，失声溅血非其心。','',''),('quantangshi-11998','狂歌行赠四兄','杜甫','quantangshi','','卷12','与兄行年校一岁，贤者是兄愚者弟。
兄将富贵等浮云，弟切功名好权势。
长安秋雨十日泥，我曹鞴马听晨鸡。
公卿朱门未开锁，我曹已到肩相齐。
吾兄睡稳方舒膝，不袜不巾蹋晓日。
男啼女哭莫我知，身上须缯腹中实。
今年思我来嘉州，嘉州酒重花绕楼。
楼头吃酒楼下卧，长歌短咏还相酬。
四时八节还拘礼，女拜弟妻男拜弟。
幅巾鞶带不挂身，头脂足垢何曾洗。
吾兄吾兄巢许伦，一生喜怒长任真。','',''),('quantangshi-11999','逃难','杜甫','quantangshi','','卷12','五十头白翁，南北逃世难。
疎布缠枯骨，奔走苦不暖。
已衰病方入，四海一涂炭。
干坤万里内，莫见容身畔。
妻孥复随我，回首共悲欢。
故国莽丘墟，邻里各分散。
归路从此迷，涕尽湘江岸。','',''),('quantangshi-12000','寄高适','杜甫','quantangshi','','卷12','楚隔干坤远，难招病客魂。
诗名惟我共，世事与谁论。
北阙更新主，南星落故园。
定知相见日，烂漫倒芳尊。','',''),('quantangshi-12001','送灵州李判官','杜甫','quantangshi','','卷12','犬戎腥四海，回首一茫茫。
血战干坤赤，氛迷日月黄。
将军专策略，幕府盛材良。
近贺中兴主，神兵动朔方。','',''),('quantangshi-12002','与严二郎奉礼别','杜甫','quantangshi','','卷12','别君谁暖眼，将老病缠身。
出涕同斜日，临风看去尘。
商歌还入夜，巴俗自为邻。
尚愧微躯在，遥闻盛礼新。
山东羣盗散，阙下受降频。
诸将归应尽，题书报旅人。','',''),('quantangshi-12003','巴西驿亭观江涨呈窦使君二首 一','杜甫','quantangshi','','卷12','转惊波作怒，即恐岸随流。
赖有杯中物，还同海上鸥。
关心小剡县，傍眼见扬州。
为接情人饮，朝来减半愁。','',''),('quantangshi-12004','巴西驿亭观江涨呈窦使君二首 二','杜甫','quantangshi','','卷12','向晚波微绿，连空岸脚青。
日兼春有暮，愁与醉无醒。
漂泊犹杯酒，踌躇此驿亭。
相看万里外，同是一浮萍。','',''),('quantangshi-12005','遣忧','杜甫','quantangshi','','卷12','乱离知又甚，消息苦难真。
受谏无今日，临危忆古人。
纷纷乘白马，攘攘着黄巾。
隋氏留宫室，焚烧何太频。','',''),('quantangshi-12006','早花','杜甫','quantangshi','','卷12','西京安稳未，不见一人来。
腊日巴江曲，山花已自开。
盈盈当雪杏，艳艳待春梅。
直苦风尘暗，谁忧容鬓催。','',''),('quantangshi-12007','巴山','杜甫','quantangshi','','卷12','巴山遇中使，云自峡城来。
盗贼还奔突，乘舆恐未回。
天寒邵伯树，地阔望仙台。','',''),('quantangshi-12008','收京','杜甫','quantangshi','','卷12','复道收京邑，兼闻杀犬戎。
衣冠却扈从，车架已还宫。
克复成如此，安危在数公。
莫令回首地，恸哭起悲风。','',''),('quantangshi-12009','巴西闻收宫阙送班司马入京','杜甫','quantangshi','','卷13','闻道收宗庙，鸣銮自陕归。
倾都看黄屋，正殿引朱衣。
劒外春天远，巴西敕使稀。
念君轻世乱，匹马向王畿。','',''),('quantangshi-12010','花底','杜甫','quantangshi','','卷13','紫蕚扶千蘂，黄须照万花。
忽疑行暮雨，何事入朝霞。
恐是潘安县，堪留卫玠车。
深知好颜色，莫作委泥沙。','',''),('quantangshi-12011','柳边','杜甫','quantangshi','','卷13','只道梅花发，那知柳亦新。
枝枝总到地，叶叶自开春。
紫燕时飜翼，黄鹂不露身。
汉南应老尽，霸上远愁人。','',''),('quantangshi-12012','送窦九归成都','杜甫','quantangshi','','卷13','文章亦不尽，窦子才纵横。
非尔更苦节，何人符大名。
读书云阁观，问绢锦官城。
我有浣花竹，题诗须一行。','',''),('quantangshi-12013','赠裴南部闻袁判官自来欲有按问','杜甫','quantangshi','','卷13','尘满莱芜甑，堂横单父琴。
人皆知饮水，公辈不偷金。
梁狱书因上，秦台镜欲临。
独醒时所嫉，羣小谤能深。
即出黄沙在，何须白发侵。
使君传旧德，已见直绳心。','',''),('quantangshi-12014','奉使崔都水翁下峡','杜甫','quantangshi','','卷13','无数涪江筏，鸣桡总发时。
别离终不久，宗族忍相遗。
白狗黄牛峡，朝云暮雨祠。
所过频问讯，到日自题诗。','',''),('quantangshi-12015','题郪县郭三十二明府茅屋壁','杜甫','quantangshi','','卷13','江头且系船，为尔独相怜。
云散灌坛雨，春青彭泽田。
频惊适小国，一拟问高天。
别后巴东路，逢人问几贤。','',''),('quantangshi-12016','遣闷戏呈路十九曹长','杜甫','quantangshi','','卷13','江浦雷声喧昨夜，春城雨色动微寒。
黄鹂竝坐交愁湿，白鹭羣飞大剧干。
晚节渐于诗律细，谁家数去酒杯宽。
惟吾最爱清狂客，百徧向看意未阑。','',''),('quantangshi-12017','随章留后新亭会送诸君','杜甫','quantangshi','','卷13','新亭有高会，行子得良时。
日动映江幕，风鸣排槛旗。
绝荤终不改，劝酒欲无词。
已堕岘山泪，因题零雨诗。','',''),('quantangshi-12018','东津送韦讽摄阆州录事','杜甫','quantangshi','','卷13','闻说江山好，怜君吏隐兼。
宠行舟远泛，怯别酒频添。
推荐非承乏，操持必去嫌。
他时如按县，不得慢陶潜。','',''),('quantangshi-12019','客旧馆','杜甫','quantangshi','','卷13','陈迹随人事，初秋别此亭。
重来棃叶赤，依旧竹林青。
风幔何时卷，寒砧昨夜声。
无由出江汉，愁绪月冥冥。','',''),('quantangshi-12020','阆州奉送二十四舅使自京赴任青城','杜甫','quantangshi','','卷13','闻道王乔舄，名因太史传。
如何碧鸡使，把诏紫微天。
秦岭愁回马，涪江醉泛船。
青城漫污杂，吾舅意凄然。','',''),('quantangshi-12021','愁坐','杜甫','quantangshi','','卷13','高斋常见野，愁坐更临门。
十月山寒重，孤城月水昏。
葭萌氐种迥，左担犬戎存。
终日忧奔走，归期未敢论。','',''),('quantangshi-12022','陪郑公秋晚北池临眺','杜甫','quantangshi','','卷13','北池云水阔，华馆辟秋风。
独鹤元依渚，衰荷且映空。
采菱寒刺上，蹋藕野泥中。
素檝分曹往，金盘小径通。
萋萋露草碧，片片晚旗红。
杯酒霑津吏，衣裳与钓翁。
异方初艳菊，故里亦高桐。
摇落关山思，淹留战伐功。
严城殊未掩，清宴已知终。
何补参卿事，欢娱到薄躬。','',''),('quantangshi-12023','去蜀','杜甫','quantangshi','','卷13','五载客蜀郡，一年居梓州。
如何关塞阻，转作潇湘游。
世事已黄发，残生随白鸥。
安危大臣在，不必泪长流。','',''),('quantangshi-12024','放船','杜甫','quantangshi','','卷13','收帆下急水，卷幔逐回滩。
江市戎戎暗，山云淰淰寒。
村荒无径入，独鸟怪人看。
已泊城楼底，何曾夜色阑。','',''),('quantangshi-12025','哭台州郑司户苏少监','杜甫','quantangshi','','卷13','故旧谁怜我，平生郑与苏。
存亡不重见，丧乱独前途。
豪俊何人在，文章埽地无。
羇游万里阔，凶问一年俱。
白首中原上，清秋大海隅。
夜台当北斗，泉路着东吴。
得罪台州去，时危弃硕儒。
移官蓬阁后，谷贵没潜夫。
流恸嗟何及，衔冤有是夫。
道消诗兴废，心息酒为徒。
许与才虽薄，追谁迹未拘。
班扬名甚盛，嵇阮逸相须。
会取君臣合，宁铨品命殊。
贤良不必展，廊庙偶然趋。
胜决风尘际，功安造化炉。
从容拘旧学，惨澹閟阴符。
摆落嫌疑久，哀伤志力输。
俗依緜谷异，客对雪山孤。
童稚思诸子，交朋列友于。
情乖清酒送，望绝抚坟呼。
疟病餐巴水，疮痍老蜀都。
飘零迷哭处，天地日榛芜。','',''),('quantangshi-12026','送王侍御往东川放生池祖席','杜甫','quantangshi','','卷13','东川诗友合，此赠怯轻为。
况复传宗近，空然惜别离。
梅花交近野，草色向平池。
傥忆江边卧，归期愿早知。','',''),('quantangshi-12027','惠义寺送王少尹赴成都','杜甫','quantangshi','','卷13','苒苒谷中寺，娟娟林表峰。
阑干上处远，结构坐来重。
骑马行春径，衣冠起晚钟。
云门青寂寂，此别惜相从。','',''),('quantangshi-12028','避地','杜甫','quantangshi','','卷13','避地岁时晚，窜身筋骨劳。
诗书遂墙壁，奴仆且旌旄。
行在仅闻信，此生随所遭。
神尧旧天下，会见出腥臊。','',''),('quantangshi-12029','惠义寺园送辛员外','杜甫','quantangshi','','卷13','朱樱此日垂朱实，郭外谁家负郭田。
万里相逢贪握手，高才却望足离筵。','',''),('quantangshi-12030','又送','杜甫','quantangshi','','卷13','双峰寂寂对春台，万竹青青照客杯。
细草留连侵坐輭，残花怅望近人开。
同舟昨日何由得，竝马今朝未拟回。
直到緜州始分首，江边树里共谁来。','',''),('quantangshi-12031','九日登梓州城','杜甫','quantangshi','','卷13','客心惊暮序，宾雁下襄州。
共赏重阳节，言寻戏马游。
湖风秋戍柳，江雨暗山楼。
且酌东篱菊，聊祛南国愁。','',''),('quantangshi-12032','阙题','杜甫','quantangshi','','卷13','三月雪连夜，未应伤物华。
只缘春欲尽，留着伴棃花。','',''),('quantangshi-12033','句','杜甫','quantangshi','','卷13','寒食少天气，东风多柳花。
小桃知客意，春尽始开花。','',''),('quantangshi-12034','自蜀奉册命往朔方途中呈韦左相文部房尚书门下崔侍郎','賈至','quantangshi','','卷13','胡羯乱中夏，銮舆忽南巡。
衣冠陷戎寇，狼狈随风尘。
豳公秉大节，临难不顾身。
激昂白刃前，溅血下沾巾。
尚书抱忠义，历险披荆榛。
扈从出剑门，登翼岷江滨。
时望挹侍郎，公才标缙绅。
亭亭昆山玉，皎皎无缁磷。
顾惟乏经济，捍牧陪从臣。
永愿雪会稽，仗剑清咸秦。
太皇时内禅，神器付嗣君。
新命集旧邦，至德被远人。
捧册自南服，奉诏趋北军。
觐谒心载驰，违离难重陈。
策马出蜀山，畏途上缘云。
饮啄丛箐间，栖息虎豹羣。
崎岖凌危栈，惴栗惊心神。
峭壁上嵚岑，大江下沄沄。
皇风扇八极，异类怀深仁。
元凶诱黠虏，肘腋生妖氛。
明主信英武，威声赫四邻。
誓师自朔方，旗帜何缤纷。
铁骑照白日，旄头拂秋旻。
将来荡沧溟，宁止蹴昆仑。
古来有屯难，否泰长相因。
夏康缵禹绩，代祖复汉勋。
于役各勤王，驱驰拱紫宸。
岂惟太公望，往昔逢周文。
谁谓三杰才，功业独殊伦。
感此慰行迈，无为歌苦辛。','',''),('quantangshi-12035','赠裴九侍御昌江草堂弹琴','賈至','quantangshi','','卷13','朔风吹疎林，积雪在崖巘。
鸣琴草堂响，小涧清且浅。
沈吟东山意，欲去芳岁晚。
怅望黄绮心，白云若在眼。','',''),('quantangshi-12036','巴陵早秋寄荆州崔司马吏部阎功曹舍人','賈至','quantangshi','','卷13','谪居潇湘渚，再见洞庭秋。
极目连江汉，西南浸斗牛。
滔滔荡云梦，澹澹摇巴丘。
旷如临渤澥，窅疑造瀛洲。
君山丽中波，苍翠长夜浮。
帝子去永久，楚词尚悲秋。
我同长沙行，时事加百忧。
登高望旧国，胡马满东周。
宛叶徧蓬蒿，樊邓无良畴。
独攀青枫树，泪洒沧江流。
故人西掖寮，同扈岐阳搜。
差池尽三黜，蹭蹬各南州。
相去虽地接，不得从之游。
耿耿云阳台，迢迢王粲楼。
跂予暮霞里，谁谓无轻舟。','',''),('quantangshi-12037','闲居秋怀寄阳翟陆赞府封丘高少府','賈至','quantangshi','','卷13','今日霖雨霁，飒然高馆凉。
秋风吹二毛，烈士加慨慷。
忆昔皇运初，众宾俱龙骧。
解巾佐幕府，脱剑升明堂。
郁郁被庆云，昭昭翼太阳。
鲸鱼纵大壑，鸑鷟鸣高冈。
信矣草创时，泰阶速贤良。
一言顿遭逢，片善蒙恩光。
我生属圣明，感激窃自彊。
崎岖郡邑权，连骞翰墨场。
天朝富英髦，多士如圭璋。
盛才溢下位，蹇步徒猖狂。
闭门对羣书，几案在我旁。
枕席相远游，聊欲浮沧浪。
八月白露降，玄蝉号枯桑。
舣舟临清川，迢递愁思长。
我有同怀友，各在天一方。
离披不相见，浩荡隔两乡。
平生霞外期，宿昔共行藏。
岂无蓬莱树，岁晏空苍苍。','',''),('quantangshi-12038','送友人使河源','賈至','quantangshi','','卷13','送君鲁郊外，下车上高丘。
萧条千里暮，日落黄云秋。
举酒有余恨，论边无远谋。
河源望不见，旌斾去悠悠。','',''),('quantangshi-12039','送李侍御','賈至','quantangshi','','卷13','我年四十余，已叹前路短。
羁离洞庭上，安得不引满。
李侯忘情者，与我同疎懒。
孤帆泣潇湘，望远心欲断。','',''),('quantangshi-12040','送耿副使归长沙','賈至','quantangshi','','卷13','画舸欲南归，江亭且留宴。
日暮湖上云，萧萧若流霰。
昨夜相知者，明发不可见。
惆怅西北风，高帆为谁扇。','',''),('quantangshi-12041','送夏侯子之江夏','賈至','quantangshi','','卷13','扣楫洞庭上，清风千里来。
留欢一杯酒，欲别复裴回。
相见楚山下，渔舟忆钓台。
羡君还旧里，归念独悠哉。','',''),('quantangshi-12042','寓言二首 一','賈至','quantangshi','','卷13','春草纷碧色，佳人旷无期。
悠哉千里心，欲采商山芝。
叹息良会晚，如何桃李时。
怀君晴川上，伫立夏云滋。','',''),('quantangshi-12043','寓言二首 二','賈至','quantangshi','','卷13','凛凛秋闺夕，绮罗早知寒。
玉砧调鸣杵，始捣机中纨。
忆昨别离日，桐花覆井栏。
今来思君时，白露盈堦漙。
闻有关河信，欲寄双玉盘。
玉以委贞心，盘以荐嘉餐。
嗟君在万里，使妾衣带宽。','',''),('quantangshi-12044','燕歌行','賈至','quantangshi','','卷13','国之重镇惟幽都，东威九夷北制胡。
五军精卒三十万，百战百胜擒单于。
前临滹沱后易水，崇山沃野亘千里。
昔时燕山重贤士，黄金筑台从隗始。
倏忽兴王定蓟丘，汉家又以封王侯。
萧条魏晋为横流，鲜卑窃据朝五州。
我唐区夏余十纪，军容武备赫万祀。
彤弓黄钺授元帅，垦耕大漠为内地。
季秋胶折边草腓，治兵羽猎因出师。
千营万队连旌旗，望之如火忽电驰。
匈奴慑窜穷发北，大荒万里无尘飞。
君不见隋家昔为天下宰，穷兵黩武征辽海。
南风不竞多死声，鼓卧旗折黄云横。
六军将士皆死尽，战马空鞍归故营。
时移道革天下平，白环入贡沧海清。
自有农夫已高枕，无劳校尉重横行。','',''),('quantangshi-12045','巴陵寄李二户部张十四礼部','賈至','quantangshi','','卷13','江南春草初幂幂，愁杀江南独愁客。
秦中杨柳也应新，转忆秦中相忆人。
万里莺花不相见，登高一望泪沾巾。','',''),('quantangshi-12046','长门怨','賈至','quantangshi','','卷13','独坐思千里，春庭晓景长。
莺喧翡翠幕，柳覆郁金堂。
舞蝶萦愁绪，繁花对靓妆。
深情托瑶瑟，弦断不成章。','',''),('quantangshi-12047','铜雀台','賈至','quantangshi','','卷13','日暮铜台静，西陵鸟雀归。
抚弦心断绝，听管泪霏微。
灵几临朝奠，空牀卷夜衣。
苍苍川上月，应照妾魂飞。','',''),('quantangshi-12048','侍宴曲','賈至','quantangshi','','卷13','云陛褰珠扆，天墀覆绿杨。
隔帘妆隐映，向席舞低昂。
鸣佩长廊静，开冰广殿凉。
欢余剑履散，同辇入昭阳。','',''),('quantangshi-12049','对酒曲二首 一','賈至','quantangshi','','卷13','梅发柳依依，黄鹂历乱飞。
当歌怜景色，对酒惜芳菲。
曲水浮花气，流风散舞衣。
通宵留暮雨，上客莫言归。','',''),('quantangshi-12050','对酒曲二首 二','賈至','quantangshi','','卷13','春来酒味浓，举酒对春丛。
一酌千忧散，三杯万事空。
放歌乘美景，醉舞向东风。
寄语尊前客，生涯任转蓬。','',''),('quantangshi-12051','送陆协律赴端州','賈至','quantangshi','','卷13','越井人南去，湘川水北流。
江边数杯酒，海内一孤舟。
岭峤同仙客，京华即旧游。
春心将别恨，万里共悠悠。','',''),('quantangshi-12052','送王员外赴长沙','賈至','quantangshi','','卷13','携手登临处，巴陵天一隅。
春生云梦泽，水溢洞庭湖。
共叹虞飜枉，同悲阮籍途。
长沙旧卑湿，今古不应殊。','',''),('quantangshi-12053','送夏侯参军赴广州','賈至','quantangshi','','卷13','闻道衡阳外，由来雁不飞。
送君从此去，书信定应稀。
云海南溟远，烟波北渚微。
勉哉孙楚吏，彩服正光辉。','',''),('quantangshi-12054','长沙别李六侍御','賈至','quantangshi','','卷13','月明湘水白，霜落洞庭干。
放逐长沙外，相逢路正难。
云归帝乡远，雁报朔方寒。
此别盈襟泪，雍门不假弹。','',''),('quantangshi-12055','岳阳楼宴王员外贬长沙','賈至','quantangshi','','卷13','极浦三春草，高楼万里心。
楚山晴霭碧，湘水暮流深。
忽与朝中旧，同为泽畔吟。
停杯试北望，还欲泪沾[襟]。','',''),('quantangshi-12056','咏冯昭仪当熊','賈至','quantangshi','','卷13','白羽插雕弓，霓旌动朔风。
平明出金屋，扈辇上林中。
逐兽长廊静，呼鹰御苑空。
王孙莫谏猎，贱妾解当熊。','',''),('quantangshi-12057','早朝大明宫呈两省僚友','賈至','quantangshi','','卷13','银烛熏天紫陌长，禁城春色晓苍苍。
千条弱柳垂青琐，百啭流莺绕建章。
剑佩声随玉墀步，衣冠身惹御炉香。
共沐恩波凤池上，朝朝染翰侍君王。','',''),('quantangshi-12058','白马','賈至','quantangshi','','卷13','白马紫连钱，嘶鸣丹阙前。
闻珂自蝶躞，不要下金鞭。','',''),('quantangshi-12059','赠薛瑶英','賈至','quantangshi','','卷13','舞怯铢衣重，笑疑桃脸开。
方知汉成帝，虚筑避风台。','',''),('quantangshi-12060','出塞曲','賈至','quantangshi','','卷13','万里平沙一聚尘，南飞羽檄北来人。
传道五原烽火急，单于昨夜寇新秦。','',''),('quantangshi-12061','春思二首 一','賈至','quantangshi','','卷13','草色青青柳色黄，桃花历乱李花香。
东风不为吹愁去，春日偏能惹恨长。','',''),('quantangshi-12062','春思二首 二','賈至','quantangshi','','卷13','红粉当垆弱柳垂，金花腊酒解酴醿。
笙歌日暮能留客，醉杀长安轻薄儿。','',''),('quantangshi-12063','勤政楼观乐','賈至','quantangshi','','卷13','银河帝女下三清，紫禁笙歌出九城。
为报延州来听乐，须知天下欲升平。','',''),('quantangshi-12064','赠陕掾梁宏','賈至','quantangshi','','卷13','梁子工文四十年，诗颠名过草书颠。
白头仍作功曹掾，禄薄难供沽酒钱。','',''),('quantangshi-12065','答严大夫','賈至','quantangshi','','卷13','今夕秦天一雁来，梧桐坠叶捣衣催。
思君独步华亭月，旧馆秋阴生绿苔。','',''),('quantangshi-12066','送李侍郎赴常州','賈至','quantangshi','','卷13','雪晴云散北风寒，楚水吴山道路难。
今日送君须尽醉，明朝相忆路漫漫。','',''),('quantangshi-12067','初至巴陵与李十二白裴九同泛洞庭湖三首 一','賈至','quantangshi','','卷13','江上相逢皆旧游，湘山永望不堪愁。
明月秋风洞庭水，孤鸿落叶一扁舟。','',''),('quantangshi-12068','初至巴陵与李十二白裴九同泛洞庭湖三首 二','賈至','quantangshi','','卷13','枫岸纷纷落叶多，洞庭秋水晚来波。
乘兴轻舟无近远，白云明月吊湘娥。','',''),('quantangshi-12069','初至巴陵与李十二白裴九同泛洞庭湖三首 三','賈至','quantangshi','','卷13','江畔枫叶初带霜，渚边菊花亦已黄。
轻舟落日兴不尽，三湘五湖意何长。','',''),('quantangshi-12070','西亭春望','賈至','quantangshi','','卷13','日长风暖柳青青，北雁归飞入窅冥。
岳阳城上闻吹笛，能使春心满洞庭。','',''),('quantangshi-12071','君山','賈至','quantangshi','','卷13','湘中老人读黄老，手援紫藟坐碧草。
春至不知湖水深，日暮忘却巴陵道。','',''),('quantangshi-12072','洞庭送李十二赴零陵','賈至','quantangshi','','卷13','今日相逢落叶前，洞庭秋水远连天。
共说金华旧游处，回看北斗欲潸然。','',''),('quantangshi-12073','江南送李卿','賈至','quantangshi','','卷13','双鹤南飞度楚山，楚南相见忆秦关。
愿值回风吹羽翼，早随阳雁及春还。','',''),('quantangshi-12074','送王道士还京','賈至','quantangshi','','卷13','一片仙云入帝乡，数声秋雁至衡阳。
借问清都旧花月，岂知迁客泣潇湘。','',''),('quantangshi-12075','巴陵夜别王八员外','賈至','quantangshi','','卷13','柳絮飞时别洛阳，梅花发后到三湘。
世情已逐浮云散，离恨空随江水长。','',''),('quantangshi-12076','别裴九弟','賈至','quantangshi','','卷13','西江万里向东流，今夜江边驻客舟。
月色更添春色好，芦风似胜竹风幽。','',''),('quantangshi-12077','送南给事贬崖州','賈至','quantangshi','','卷13','畴昔丹墀与凤池，即今相见两相悲。
朱崖云梦三千里，欲别俱为恸哭时。','',''),('quantangshi-12078','重别南给事','賈至','quantangshi','','卷13','谪宦三年尚未回，故人今日又重来。
闻道崖州一千里，今朝须尽数千杯。','',''),('quantangshi-12079','岳阳楼重宴别王八员外贬长沙','賈至','quantangshi','','卷13','江路东连千里潮，青云北望紫微遥。
莫道巴陵湖水阔，长沙南畔更萧条。','',''),('quantangshi-12080','紫参歌','錢起','quantangshi','','卷13','远公林下满青苔，春药偏宜间石开。
往往幽人寻水见，时时仙蝶隔云来。
阴阳雕刻花如鸟，对凤连鸡一何小。
春风宛转虎溪傍，紫翼红翘翻霁光。
贝叶经前无住色，莲花会里暂留香。
蓬山才子怜幽性，白云阳春动新咏。
应知仙卉老云霞，莫赏夭桃满蹊迳。','',''),('quantangshi-12081','玛瑙杯歌','錢起','quantangshi','','卷13','瑶溪碧岸生奇宝，剖质披心出文藻。
良工雕饰明且鲜，得成珍器入芳筵。
含华炳丽金尊侧，翠斝琼觞忽无色。
繁弦急管催献酬，倏若飞空生羽翼。
𤩌𤩌兰英照豹斑，满堂词客尽朱颜。
花光来去传香袖，霞影高低傍玉山。
王孙彩笔题新咏，碎锦连珠复辉映。
世情贵耳不贵奇，谩说海底珊瑚枝。
宁及琢磨当妙用，燕歌楚舞长相随。','',''),('quantangshi-12082','锄药咏','錢起','quantangshi','','卷13','莳药穿林复在巘，浓香秀色深能浅。
云气垂来裛露偏，松阴占处知春晚。
拂曙残莺百啭催，萦泉带石几花开。
不随飞鸟缘枝去，如笑幽人出谷来。
对之不觉忘疎嬾，废卷荷锄嫌日短。
岂无萱草树堦墀，惜尔幽芳世所遗。
但使芝兰出萧艾，不辞手足皆胼胝。
宁学陶潜空嗜酒，颓龄舍此事东菑。','',''),('quantangshi-12083','病鹤篇','錢起','quantangshi','','卷13','独鹤声哀羽摧折，沙头一点留残雪。
三山侣伴能远翔，五里裴回忍为别。
惊羣各畏野人机，谁肯相将霞水飞。
不及川凫长比翼，随波双泛复双归。
碧海沧江深且广，目尽天倪安得往。
云山隔路不隔心，宛颈和鸣长在想。
何时白雾卷青天，接影追飞太液前。','',''),('quantangshi-12084','片玉篇','錢起','quantangshi','','卷13','至宝未为代所奇，韫灵示[璞]荆山陲。
独使虹光天子识，不将清韵世人知。
世人所贵惟燕石，美玉对之成瓦砾。
空山埋照凡几年，古色苍痕宛自然。
重溪幂幂暗云树，一片荧荧光石泉。
美人之鉴明且彻，玉指提携叹奇绝。
试劳香袖拂莓苔，不觉清心皎冰雪。
连城美价幸逢时，命代良工岂见遗。
试作圭璋礼天地，何如瓀𤨟在堦墀。','',''),('quantangshi-12085','画鹤篇','錢起','quantangshi','','卷13','点素凝姿任画工，霜毛玉羽照帘栊。
借问飞鸣华表上，何如粉缋彩屏中。
文昌宫近芙蓉阙，兰室絪緼香且结。
炉气朝成缑岭云，银灯夜作华亭月。
日暖花明梁燕归，应惊片雪在仙闱。
主人顾盼千金重，谁肯裴回五里飞。','',''),('quantangshi-12086','秋霖曲','錢起','quantangshi','','卷13','君不见圣主旰食忧元元，秋风苦雨暗九门。
凤凰池里沸泉腾，苍龙阙下生云根。
阴精离毕太淹度，倦鸟将归不知树。
愁阴惨淡时殷雷，生灵垫溺若寒灰。
公卿红粒爨丹桂，黔首白骨封青苔。
貂裘玉食张公子，炮炙熏天戟门里。
且如歌笑日挥金，应笑禹汤能罪己。
鹤鸣蛙跃正及时，豹隐兰凋亦可悲。
焉得太阿决屏翳，还令率土见朝曦。','',''),('quantangshi-12087','白石枕','錢起','quantangshi','','卷13','琢珉胜水碧，所贵素且贞。
曾无白圭玷，不作浮磬鸣。
捧来太阳前，一片新冰清。
沈沈风宪地，待尔秋已至。
璞坚难为功，谁怨晚成器。
比德无磷缁，论交亦如此。','',''),('quantangshi-12088','赋得青城山歌送杨杜二郎中赴蜀军','錢起','quantangshi','','卷13','蜀山西南千万重，仙经最说青城峰。
青城嵚岑倚空碧，远压峨嵋吞剑壁。
锦屏云起易成霞，玉洞花明不知夕。
星台二妙逐王师，阮瑀军书王粲诗。
日落猨声连玉笛，晴来山翠傍旌旗。
绿萝春月营门近，知君对酒遥相思。','',''),('quantangshi-12089','送李大夫赴广州','錢起','quantangshi','','卷13','一贤间气生，麟趾凤凰羽。
何意人之望，未为王者辅。
出镇忽推才，盛哉文且武。
南越寄维城，雄雄拥甲兵。
鼓门通幕府，天井入军营。
厥俗多豪侈，古来难致礼。
唯君饮冰心，可酌贪泉水。
忠臣感圣君，徇义不邀勋。
龙镜逃山魅，霜风破嶂雪。
征途凡几转，魏阙如在眼。
向郡海潮迎，指乡关树远。
按节化瓯闽，下车佳政新。
应令尉陀俗，还作上皇人。
支离交俊哲，弱冠至华发。
昔许霄汉期，今嗟鹏鷃别。
图南不可御，惆怅守薄暮。','',''),('quantangshi-12090','送崔校书从军','錢起','quantangshi','','卷13','雁门太守能爱贤，麟阁书生亦投笔。
宁唯玉劒报知己，更有龙韬佐师律。
别马连嘶出御沟，家人几夜望刀头。
燕南春草伤心色，蓟北黄云满眼愁。
闻道轻生能击虏，何嗟少壮不封侯。','',''),('quantangshi-12091','送张将军征西','錢起','quantangshi','','卷13','长安少年唯好武，金殿承恩争破虏。
沙场烽火隔天山，铁骑征西几岁还。
战处黑云霾翰海，愁中明月度阳关。
玉笛声悲离酌晚，金方路极行人远。
计日霜戈尽敌归，回首戎城空落晖。
始笑子卿心计失，徒看海上节旄稀。','',''),('quantangshi-12092','送修武元少府','錢起','quantangshi','','卷13','寸禄荣色养，此行宁叹惜。
自今黄绶采兰时，不厌丹墀芳草色。
百战荒城复井田，几家春树带人烟。
黎甿久厌蓬飘苦，迟尔西南惠月传。','',''),('quantangshi-12093','送崔十三东游','錢起','quantangshi','','卷13','千里有同心，十年一会面。
当杯缓筝柱，倏忽催离宴。
丹凤城头噪晚鸦，行人马首夕阳斜。
灞上春风留别袂，关东新月宿谁家。
官柳依依两乡色，谁能此别不相忆。','',''),('quantangshi-12094','送邬三落第还乡','錢起','quantangshi','','卷13','郢客文章绝世稀，常嗟时命与心违。
十年失路谁知己，千里思亲独远归。
云帆春水将何适，日爱东南暮山碧。
关中新月对离尊，江上残花待归客。
名宦无媒自古迟，穷途此别不堪悲。
荷衣垂钓且安命，金马招贤会有时。','',''),('quantangshi-12095','送马明府赴江陵','錢起','quantangshi','','卷13','陶令南行心自永，江天极目澄秋景。
万室遥方犬不鸣，双凫下处人皆静。
清风高兴得湖山，门柳萧条双翟闲。
黄花满把应相忆，落日登楼北望还。','',''),('quantangshi-12096','送毕侍御谪居','錢起','quantangshi','','卷13','崇兰香死玉簪折，志士吞声甘徇节。
忠荩不为明主知，悲来莫向时人说。
沧浪之水见心清，楚客辞天泪满缨。
百鸟喧喧噪一鹗，上林高枝亦难托。
宁嗟人世弃虞飜，且喜江山得康乐。
自怜黄绶老婴身，妻子朝来劝隐沦。
桃花洞里举家去，此别相思复几春。','',''),('quantangshi-12097','送褚大落第东归','錢起','quantangshi','','卷13','离琴弹苦调，美人惨向隅。
顷来荷策干明主，还复扁舟归五湖。
汉家侧席明扬久，岂意遗贤在林薮。
玉堂金马隔青云，墨客儒生皆白首。
昨梦芳洲采白苹，归期且喜故园春。
稚子只思陶令至，文君不厌马卿贫。
剡中风月久相忆，池上旧游应再得。
酒熟宁孤芳杜春，诗成不枉青山色。
念此那能不羡归，长杨谏猎事皆违。
他日东流一乘兴，知君为我扫荆扉。','',''),('quantangshi-12098','送傅管记赴蜀军','錢起','quantangshi','','卷13','终童之死谁继出，燕颔儒生今俊逸。
主将早知鹦鹉赋，飞书许载蛟龙笔。
峨嵋玉垒指霞标，鸟没天低幕府遥。
巴山雨色藏征斾，汉水猨声咽短箫。
赐璧腰金应可料，才畧纵横年且妙。
无人不重乐毅贤，何敌能当鲁连啸。
日暮黄云千里昏，壮心轻别不销魂。
勤君用却龙泉劒，莫负平生国士恩。','',''),('quantangshi-12099','送张少府','錢起','quantangshi','','卷13','愁云破斜照，别酌劝行子。
蓬惊马首风，雁拂天边水。
寸晷如三岁，离心在万里。','',''),('quantangshi-12100','行路难','錢起','quantangshi','','卷13','君不见明星映空月，太阳朝升光尽歇。
君不见凋零委路蓬，长风飘举入云中。
由来人事何尝定，且莫骄奢笑践穷。','',''),('quantangshi-12101','卢龙塞行送韦掌记','錢起','quantangshi','','卷13','雨雪纷纷黑山外，行人共指卢龙塞。
万里飞沙咽鼓鼙，三军杀气凝旌斾。
陈琳书记本翩翩，料敌张兵夺酒泉。
圣主好文兼好武，封侯莫比汉皇年。','',''),('quantangshi-12102','效古秋夜长','錢起','quantangshi','','卷13','秋汉飞玉霜，北风扫荷香。
含情纺织孤灯尽，拭泪相思寒漏长。
檐前碧云静如水，月吊栖乌啼鸟起。
谁家少妇事鸳机，锦幕云屏深掩扉。
白玉窗中闻落叶，应怜寒女独无衣。','',''),('quantangshi-12103','卧病李员外题扉而去','錢起','quantangshi','','卷13','僻陋病者居，蒿莱行迳失。
谁知簪绂贵，能问幽忧疾。
珂声未驻门，兰气先入室。
沉疴不冠带，安得候蓬荜。
清扬去莫寻，离念顷来侵。
雀栖高窗静，日出修桐阴。
枕上忆君子，悄悄唯苦心。','',''),('quantangshi-12104','酬王维春夜竹亭赠别','錢起','quantangshi','','卷13','山月随客来，主人兴不浅。
今宵竹林下，谁觉花源远。
惆怅曙莺啼，孤云还绝巘。','',''),('quantangshi-12105','山中寄时校书','錢起','quantangshi','','卷13','蓬莱紫气温如玉，唯予知尔阳春曲。
别来几日芳荪绿，百花酒满不见君，青山一望心断续。','',''),('quantangshi-12106','送李四擢第归觐省','錢起','quantangshi','','卷13','当年贵得意，文字各争名。
齐唱阳春曲，唯君金玉声。
悬黎宝中出，高价世难掩。
鸿羽不低飞，龙津徒自险。
直矜鹦鹉赋，不贵芳桂枝。
少俊蔡邕许，长鸣唐举知。
梁城下熊轼，朱戟何暐耀。
才子欲归宁，棠花已含笑。
高门知庆大，子孝觉亲荣。
独揽还珠美，宁唯问绢情。
离筵不尽醉，掺袂一何早。
马蹄西别轻，树色东看好。
行尘忽不见，惆怅青门道。','',''),('quantangshi-12107','过曹钧隐居','錢起','quantangshi','','卷13','荃蕙有奇性，馨香道为人。
不居众芳下，宁老空林春。
之子秉高节，攻文还守真。
素书寸阴尽，流水怨情新。
济济振缨客，烟霄各致身。
谁当举玄晏，不使作良臣。','',''),('quantangshi-12108','哭曹钧','錢起','quantangshi','','卷13','苦节推白首，怜君负此生。
忠荩名空在，家贫道不行。
朝来相忆访蓬荜，只谓渊明犹卧疾。
忽见江南吊鹤来，始知天上文星失。
尝恨知音千古稀，那堪夫子九泉归。
一声邻笛残阳里，酹酒空堂泪满衣。','',''),('quantangshi-12109','东阳郡斋中诣南山招韦十','錢起','quantangshi','','卷13','霁来海半山，隐映城上起。
中峰落照时，残雪翠微里。
同心久为别，孤兴那对此。
良会何迟迟，清扬瞻则迩。','',''),('quantangshi-12110','清泥驿迎献王侍御','錢起','quantangshi','','卷13','候馆扫清昼，使车出明光。
森森入郭树，一道引飞霜。
仰视骢花白，多惭绶色黄。
鹪鹩无羽翼，愿假宪乌翔。','',''),('quantangshi-12111','沭阳古渡作','錢起','quantangshi','','卷13','日落问津处，云霞残碧空。
牧牛避田烧，退鷁随潮风。
回首故乡远，临流此路穷。
翩翩青冥去，羡彼高飞鸿。','',''),('quantangshi-12112','卧疾答刘道士','錢起','quantangshi','','卷13','白露蚕已丝，空林日凄清。
寥寥昼扉掩，独卧秋窗明。
宝字比仙药，羽人寄柴荆。
长吟想风驭，怳若升蓬瀛。','',''),('quantangshi-12113','梦寻西山准上人','錢起','quantangshi','','卷13','别处秋泉声，至今犹在耳。
何尝梦魂去，不见雪山子。
新月隔林时，千峰翠微里。
言忘心更寂，迹灭云自起。
觉来缨上尘，如洗功德水。','',''),('quantangshi-12114','长安旅宿','錢起','quantangshi','','卷13','九秋旅夜长，万感何时歇。
蕙花渐寒暮，心事犹楚越。
直躬邅世道，咫步隔天阙。
每闻长乐钟，载泣灵台月。
明旦北门外，归途堪白发。','',''),('quantangshi-12115','过桐柏山','錢起','quantangshi','','卷13','秋风过楚山，山静秋声晚。
赏心无定极，仙步亦清远。
返照云窦空，寒流石苔浅。
羽人昔已去，灵迹欣方践。
投策谢归途，世缘从此遣。','',''),('quantangshi-12116','李士曹厅对雨','錢起','quantangshi','','卷13','春雨暗重城，讼庭深更寂。
终朝人吏少，满院烟云集。
湿鸟压花枝，新苔宜砌石。
掾曹富文史，清兴对词客。
爱尔蕙兰丛，芳香饱时泽。','',''),('quantangshi-12117','登胜果寺南楼雨中望严协律','錢起','quantangshi','','卷13','微雨侵晚阳，连山半藏碧。
林端陟香榭，云外迟来客。
孤村凝片烟，去水生远白。
但隹川原趣，不觉城池夕。
更喜眼中人，清光渐咫尺。','',''),('quantangshi-12118','冬夜题旅馆','錢起','quantangshi','','卷13','退飞忆林薮，乐业羡黎庶。
四海尽穷途，一枝无宿处。
严冬北风急，中夜哀鸿去。
孤烛思何深，寒窗坐难曙。
劳歌待明发，惆怅盈百虑。','',''),('quantangshi-12119','自终南山晚归','錢起','quantangshi','','卷13','采苓日往还。
得性非樵隐，白水到初阔。
青山辞尚近，绝境胜无倪。
归途兴不尽，沮溺时返顾。
牛羊自相引，逍遥不外求。
尘虑从兹泯。','',''),('quantangshi-12120','早渡伊川见旧邻作','錢起','quantangshi','','卷13','鵾鸡鸣早霜，秋水寒旅涉。
渔人昔邻舍，相见具舟楫。
出浦兴未尽，向山心更惬。
村落通白云，茅茨隐红叶。
东臯满时稼，归客欣复业。','',''),('quantangshi-12121','夕发箭场岩下作','錢起','quantangshi','','卷13','行役不遑安，在幽机转发。
山谷无明晦，溪霞自兴没。
朝栉杉下风，夕饮石上月。
懿尔青云士，垂缨朝凤阙。
宁知采竹人，每食慙薇蕨。','',''),('quantangshi-12122','同李五夕次香山精舍访宪上人','錢起','quantangshi','','卷13','彼岸闻山钟，仙舟过苕水。
松门入幽映，石径趋迤逦。
初月开草堂，远公方觏止。
忘言在闲夜，凝念得微理。
泠泠功德池，相与涤心耳。','',''),('quantangshi-12123','雨中望海上怀郁林观中道侣','錢起','quantangshi','','卷13','山观海头雨，悬沫动烟树。
只疑苍茫里，郁岛欲飞去。
大块怒天吴，惊潮荡云路。
羣真俨盈想，一苇不可渡。
惆怅赤城期，愿假轻鸿驭。','',''),('quantangshi-12124','广德初銮驾出关后登高愁望二首 一','錢起','quantangshi','','卷13','长安不可望，远处边愁起。
辇毂混戎夷，山河空表里。
黄云压城阙，斜照移烽垒。
汉帜远成霞，胡马来如蚁。
不知涿鹿战，早晚蚩尤死。
渴日候河清，沈忧催暮齿。','',''),('quantangshi-12125','广德初銮驾出关后登高愁望二首 二','錢起','quantangshi','','卷13','愁看秦川色，惨惨云景晦。
干坤暂运行，品物遗覆载。
黄尘涨戎马，紫气随龙斾。
掩泣指关东，日月妖氛外。
臣心寄远水，朝海去如带。
周德更休明，天衢伫开泰。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-12126','独往覆釜山寄郎士元','錢起','quantangshi','','卷13','赏心无远近，芳月好登望。
胜事引幽人，山下复山上。
将寻洞中药，复爱湖外嶂。
古壁苔入云，阴溪树穿浪。
谁言世缘绝，更惜知音旷。
莺啼绿萝春，回首还惆怅。','',''),('quantangshi-12127','送王季友赴洪州幕下','錢起','quantangshi','','卷13','列郡皆用武，南征所从谁。
诸侯重才畧，见子如琼枝。
抚剑感知己，出门方远辞。
烟波带幕府，海日生红旗。
问我何功德，负恩留玉墀。
销魂把别袂，愧尔酬明时。','',''),('quantangshi-12128','客舍赠郑贲','錢起','quantangshi','','卷13','结交意不薄，匪席言莫违。
世义随波久，人生知己稀。
先鸣誓相达，未遇还相依。
一望金门诏，三看黄鸟飞。
暝投同旅食，朝出易儒衣。
嵇向林庐接，携手行将归。','',''),('quantangshi-12129','山中春仲寄上王恒颍川沈冲','錢起','quantangshi','','卷13','隐者守恬泊，春山日深净。
谁知蟠木材，得性无人境。
座隅泉出洞，竹上云起岭。
饥貁入山厨，饮虹过药井。
前溪堪放逸，仲月好风景。
游目来远思，摘芳寄汝颍。','',''),('quantangshi-12130','南中春意','錢起','quantangshi','','卷13','入仕无知言，游方随世道。
平生愿开济，遇物干怀抱。
已阻青云期，甘同散樗老。
客游南海曲，坐见韶阳蚤。
旧国别佳人，他乡思芳草。
惜无鸿鹄翅，安得凌苍昊。','',''),('quantangshi-12131','东陵药堂寄张道士','錢起','quantangshi','','卷13','木落苍山空，当轩秋水色。
清旦振衣坐，永吟意何极。
愿言金丹寿，一假鸾凤翼。
日夕开真经，言忘心更默。
玄都有仙子，采药早相识。
烟霞难再期，焚香空叹息。','',''),('quantangshi-12132','苦雨忆皇甫冉','錢起','quantangshi','','卷13','凉雨门巷深，穷居成习静。
独吟愁霖雨，更使秋思永。
疲疴苦昏垫，日夕开轩屏。
草木森已悲，衾帱清且冷。
如何游宦客，江海随泛梗。
延首长相思，忧襟孰能整。','',''),('quantangshi-12133','寄任山人','錢起','quantangshi','','卷13','天阶崇黼黻，世路有趋竞。
独抱中孚爻，谁知苦寒咏。
行潦难朝海，散材空遇圣。
岂无鸣凤时，其如问津命。
所思青山郭，再梦绿萝径。
林泉春可游，羡尔得其性。','',''),('quantangshi-12134','登秦岭半岩遇雨','錢起','quantangshi','','卷13','屏翳忽腾气，浮阳惨无晖。
千峰挂飞雨，百尺摇翠微。
震电闪云迳，奔流翻石矶。
倚岩假松盖，临水羡荷衣。
不得采苓去，空思乘月归。
且怜东臯上，水色侵荆扉。','',''),('quantangshi-12135','杪秋南山西峰题准上人兰若','錢起','quantangshi','','卷13','向山看霁色，步步豁幽性。
返照乱流明，寒空千嶂净。
石门有余好，霞残月欲映。
上诣远公庐，孤峰悬一迳。
云里隔窗火，松下闻山磬。
客到两忘言，猨心与禅定。','',''),('quantangshi-12136','田园雨后赠邻人','錢起','quantangshi','','卷13','安排常任性，偃卧晚开户。
樵客荷蓑归，向来春山雨。
残云虹未落，返景霞初吐。
时鸟鸣村墟，新泉遶林圃。
尧年尚恬泊，邻里成太古。
室迩人遂遥，相思怨芳杜。','',''),('quantangshi-12137','天门谷题孙逸人石壁','錢起','quantangshi','','卷13','崖石乱流处，竹深斜照归。
主人卧磻石，心耳涤清晖。
春雷近作解，空谷半芳菲。
云栋彩虹宿，药圃蝴蝶飞。
恶嚣慕嘉遯，几夜瞻少微。
相见竟何说，忘情同息机。','',''),('quantangshi-12138','蓝溪休沐寄赵八给事','錢起','quantangshi','','卷13','虫鸣归旧里，田野秋农闲。
即事敦夙尚，衡门方再关。
夕阳入东篱，爽气高前山。
霜蕙后时老，巢禽知暝还。
侍臣黄枢宠，鸣玉青云间。
肯想观鱼处，寒泉照发斑。','',''),('quantangshi-12139','游辋川至南山寄谷口王十六','錢起','quantangshi','','卷13','山色不厌远，我行随处深。
迹幽青萝迳，思绝孤霞岑。
独鹤引过浦，鸣猨呼入林。
褰裳百泉里，一步一清心。
王子在何处，隔云鸡犬音。
折麻定延伫，乘月期招寻。','',''),('quantangshi-12140','蓝田溪与渔者宿','錢起','quantangshi','','卷13','独游屡忘归，况此隐沦处。
濯发清泠泉，月明不能去。
更怜垂纶叟，静若沙上鹭。
一论白云心，千里沧洲趣。
芦中夜火尽，浦口秋山曙。
叹息分枝禽，何时更相遇。','',''),('quantangshi-12141','淮上别范大','錢起','quantangshi','','卷13','悲风陨凉叶，送归怨南楚。
穷年将别离，寸晷申宴语。
长淮流不尽，征棹忽复举。
碧落半愁云，黄鹤时顾侣。
游宦且未达，前途各修阻。
分袂一相嗟，良辰更何许。','',''),('quantangshi-12142','离居夜雨奉寄李京兆','錢起','quantangshi','','卷13','永夜不可度，蛩吟秋雨滴。
寂寞想章台，始叹云泥隔。
雷声匪君车，犹时过我庐。
电影非君烛，犹能明我目。
如何琼树枝，梦里看不足。
望望佳期阻，愁生寒草绿。','',''),('quantangshi-12143','叹毕少府以持法无隐见系','錢起','quantangshi','','卷13','用法本禁邪，尽心翻自极。
毕公在囹圄，世事何糺纆。
翠凤呈其瑞，虞罗寄铩翼。
囚中千念时，窗外百花色。
落景闭圜扉，春虫网丛棘。
古人不念文，纷泪莫霑臆。','',''),('quantangshi-12144','小园招隐','錢起','quantangshi','','卷13','支离鲜兄弟，形影如手足。
但遂饮冰节，甘辞代耕禄。
斑衣在林巷，始觉无羁束。
交柯低户阴，闲鸟将雏宿。
穷通世情阻，日夜苔径绿。
谁言北郭贫，能分晏婴粟。','',''),('quantangshi-12145','过温逸人旧居','錢起','quantangshi','','卷13','返真难合道，怀旧仍无吊。
浮俗渐浇淳，斯人谁继妙。
声容在心耳，宁觉阻言笑。
玄堂闭几春，拱木齐云峤。
鹤传居士舞，猨得苏门啸。
酹酒片阳微，空山想埋照。','',''),('quantangshi-12146','县内水亭晨兴听讼','錢起','quantangshi','','卷13','晨光起宿露，池上判黎甿。
借问秋泉色，何如拙宦情。
磨铅辱利用，策蹇愁前程。
昨夜明月满，中心如鹊惊。
负恩时易失，多病绩难成。
坐惜寒塘晚，霜风吹杜蘅。','',''),('quantangshi-12147','海畔秋思','錢起','quantangshi','','卷13','匡济难道合，去留随兴牵。
偶为谢客事，不顾平子田。
魏阙贲翘楚，此身长弃捐。
箕裘空在念，咄咄谁推贤。
无用即明代，养疴仍壮年。
日夕望佳期，帝乡路几千。
秋风晨夜起，零落愁芳荃。','',''),('quantangshi-12148','太子李舍人城东别业','錢起','quantangshi','','卷13','南山转羣木，昏晓拥山翠。
小泽近龙居，清苍常雨气。
君家北原上，千金买胜事。
丹阙退朝廻，白云迎赏至。
新晴村落外，处处烟景异。
片水明断岸，余霞入古寺。
东臯指归翼，目尽有余意。','',''),('quantangshi-12149','谷口新居寄同省朋故','錢起','quantangshi','','卷13','种黍傍烟溪，榛芜兼沮洳。
亦知生计薄，所贵隐身处。
橡栗石上村，莓苔水中路。
萧然授衣日，得此还山趣。
汲井爱秋泉，结茅因古树。
闲云与幽鸟，对我不能去。
寄谢鸳鹭羣，狎鸥拙所慕。','',''),('quantangshi-12150','京兆尹厅前甘棠树降甘露','錢起','quantangshi','','卷13','内史用尧意，理京宣惠慈。
气和祥则降，孰谓天难知。
济旱露为兆，有如埙应篪。
岂无夭桃树，洒此甘棠枝。
玉色与人净，珠光临笔垂。
协风与之俱，物性皆熙熙。
何必凤池上，方看作霖时。','',''),('quantangshi-12151','秋夜作','錢起','quantangshi','','卷13','万计各无成，寸心日悠漫。
浮生竟何穷，巧历不能算。
流落四海间，辛勤百年半。
商歌向秋月，哀韵兼浩叹。
寤寐怨佳期，美人隔霄汉。
寒云度穷水，别业遶垂幔。
窗中问谈鸡，长夜何时旦。','',''),('quantangshi-12152','观村人牧山田','錢起','quantangshi','','卷13','六府且未盈，三农争务作。
贫民乏井税，塉土皆垦凿。
禾黍入寒云，茫茫半山郭。
秋来积霖雨，霜降方銍获。
中田聚黎甿，反景空村落。
顾惭不耕者，微禄同卫鹤。
庶追周任言，敢负谢生诺。','',''),('quantangshi-12153','裴侍郎湘川回以青竹筒相遗因而赠之','錢起','quantangshi','','卷13','楚竹青玉润，从来湘水阴。
缄书取直节，君子知虚心。
入用随宪简，积文不受金。
体将丹凤直，色映秋霜深。
宁肯假伶伦，谬为龙凤吟。
唯将翰院客，昔祕瑶华音。
长跪捧嘉贶，岁寒惭所钦。','',''),('quantangshi-12154','东城初陷与薛员外王补阙暝投南山佛寺','錢起','quantangshi','','卷13','日昃石门里，松声山寺寒。
香云空静影，定水无惊湍。
洗足解尘缨，忽觉天形宽。
清钟扬虚谷，微月深重峦。
噫我朝露世，翻浮与波澜。
行运遘忧患，何缘亲盘桓。
庶将镜中象，尽作无生观。','',''),('quantangshi-12155','奉和张荆州巡农晚望','錢起','quantangshi','','卷13','太清霁云雷，阳春陶物象。
明牧行春令，仁风助升长。
时和俗勤业，播殖农厥壤。
阴阴桑陌连，漠漠水田广。
郡中忽无事，方外还独往。
日暮驻归轩，湖山有佳赏。
宣城传逸韵，千载谁此响。','',''),('quantangshi-12156','送包何东游','錢起','quantangshi','','卷13','水国尝独往，送君还念兹。
湖山远近色，昏旦烟霞时。
子好谢公迹，常吟孤屿诗。
果乘扁舟去，若与白鸥期。
野趣及春好，客游欣此辞。
入云投馆僻，采碧过帆迟。
江上日回首，琴中劳别思。
春鸿刷归翼，一寄杜蘅枝。','',''),('quantangshi-12157','酬陶六辞秩归旧居见柬','錢起','quantangshi','','卷13','靖节昔高尚，令孙嗣清徽。
旧庐云峰下，献岁车骑归。
去俗因解绶，忆山得采薇。
田畴春事起，里巷相寻稀。
渊明醉乘兴，闲门秪掩扉。
花禽惊曙月，邻女上鸣机。
毕娶愿已果，养恬志宁违。
吾当挂朝服，同尔缉荷衣。','',''),('quantangshi-12158','奉使采箭簳竹谷中晨兴赴岭','錢起','quantangshi','','卷13','孤客倦夜坐，闻猨乘早发。
背溪已斜汉，登栈尚残月。
重峰转森爽，幽步更超越。
云木耸鹤巢，风萝扫虎穴。
人羣从自远，世役终难歇。
入山非买山，采竹异采蕨。
谁见子牟意，悁劳书魏阙。','',''),('quantangshi-12159','同严逸人东溪泛舟','錢起','quantangshi','','卷13','子陵江海心，高迹此闲放。
渔舟在溪水，曾是敦夙尚。
朝霁收云物，垂纶独清旷。
寒花古岸傍，唳鹤晴沙上。
纷吾好贞逸，不远来相访。
已接方外游，仍陪郢中唱。
欢言尽佳酌，高兴延秋望。
日暮浩歌还，红霞乱青嶂。','',''),('quantangshi-12160','过沈氏山居','錢起','quantangshi','','卷13','鸡鸣孤烟起，静者能卜筑。
乔木出云心，闲门掩山腹。
贫交喜相见，把臂欢不足。
空林留宴言，永日清耳目。
泉声冷尊俎，荷气香童仆。
往往仙犬鸣，樵人度深竹。
酒酣出谷口，世网何羁束。
始愿今不从，区区折腰禄。','',''),('quantangshi-12161','赠柏岩老人','錢起','quantangshi','','卷13','日与麋鹿羣，贤哉买山叟。
庞眉忽相见，避世一何久。
林栖古崖曲，野事佳春后。
瓠叶覆荆扉，栗苞垂瓮牖。
独歌还独酌，不耕亦不耦。
硗田隔云溪，多雨长稂莠。
烟霞得情性，身世同刍狗。
寄谢营道人，天真此翁有。','',''),('quantangshi-12162','送薛判官赴蜀','錢起','quantangshi','','卷13','横笛声转悲，羽觞酣欲别。
举目叩关远，离心不可说。
边陲劳帝念，日下降才杰。
路极巴水长，天衔剑峰缺。
单车动夙夜，越境正炎节。
星桥过客稀，火井蒸云热。
阴符能制胜，千里在坐决。
始见儒者雄，长缨系余孽。','',''),('quantangshi-12163','诏许昌崔明府拜补阙','錢起','quantangshi','','卷13','儒者久营道，诏书方问贤。
至精一耀世，高步谁同年。
何树可栖凤，高梧枝拂天。
脱身凫舄里，载笔虎闱前。
日月传轩后，衣冠真列仙。
则知骊龙珠，不祕清泠泉。
才子贵难见，郢歌空复传。
惜哉效颦客，心想劳婵娟。','',''),('quantangshi-12164','仲春晚寻覆釜山','錢起','quantangshi','','卷13','蝴蝶弄和风，飞花不知晚。
王孙寻芳草，步步忘路远。
况我爱青山，涉趣皆游践。
萦回必中路，阴晦阳复显。
古岸生新泉，霞峰映雪巘。
交枝花色异，奇石云根浅。
碧洞志忘归，紫芝行可搴。
应嗤嵇叔夜，林卧方沈湎。','',''),('quantangshi-12165','赠东邻郑少府','錢起','quantangshi','','卷13','一闻白雪唱，愿见清扬久。
谁谓结绶来，得陪趋府后。
小邑蓝溪上，卑栖惬所偶。
忘言复连墙，片月亦携手。
草色同春迳，莺声共高柳。
美景百花时，平生一杯酒。
圣朝法天地，以我为刍狗。
秩满归白云，期君访谷口。','',''),('quantangshi-12166','谢张法曹万顷小山暇景见忆','錢起','quantangshi','','卷13','乐道随去处，养和解朝簪。
茅堂近丹阙，佳致亦何深。
退食不趋府，忘机还在林。
清风乱流上，永日小山阴。
解箨雨中竹，将雏花际禽。
物华对幽寂，弦酌兼咏吟。
自昔仰高步，及兹劳所钦。
郢歌叨继组，知己复知音。','',''),('quantangshi-12167','罢章陵令山居过中峰道者二首 一','錢起','quantangshi','','卷13','宁辞园令秩，不改渊明调。
解印无与言，见山始一笑。
幽人还绝境，谁道苦奔峭。
随云剩渡溪，出门更垂钓。
吾庐青霞里，窗树玄猨啸。
微月清风来，方知散发妙。','',''),('quantangshi-12168','罢章陵令山居过中峰道者二首 二','錢起','quantangshi','','卷13','丘壑趣如此，暮年始栖偃。
赖遇无心云，不笑归来晚。
鸣鸠拂红枝，初服傍清畎。
昨日山僧来，犹嫌嘉遯浅。
托君紫阳家，路灭心更远。
梯云创其居，抱犊上绝巘。
杏田溪一曲，霞境峰几转。
路石挂飞泉，谢公应在眼。
愿言携手去，采药长不返。','',''),('quantangshi-12169','登覆釜山遇道人二首 一','錢起','quantangshi','','卷13','晨策趣无涯，名山深转秀。
三休变覆景，万转迷宇宙。
攀崖到天窗，入洞穷玉溜。
侧迳蹲怪石，飞萝掷惊狖。
花间炼药人，鸡犬和乳窦。
散发便迎客，采芝仍满袖。
郭璞赋游仙，始愿今可就。','',''),('quantangshi-12170','登覆釜山遇道人二首 二','錢起','quantangshi','','卷13','真气重嶂里，知君嘉遯幽。
山堦压丹穴，药井通洑流。
道者带经出，洞中携我游。
欲骖白霓去，且为紫芝留。
忽忆武陵事，别家疑数秋。','',''),('quantangshi-12171','寻华山云台观道士','錢起','quantangshi','','卷13','秋日西山明，胜趣引孤策。
桃源数曲尽，洞口两岸坼。
还从罔象来，忽得仙灵宅。
霓裳谁之子，霞酌能止客。
残阳在翠微，携手更登历。
林行拂烟雨，溪望乱金碧。
飞鸟下天窗，褭松际云壁。
稍寻玄踪远，宛入寥天寂。
愿言葛仙翁，终年炼玉液。','',''),('quantangshi-12172','海上卧病寄王临','錢起','quantangshi','','卷13','离客穷海阴，萧辰归思结。
一随浮云滞，几怨黄鹄别。
妙年即沈疴，生事多所阙。
劒中负明义，枕上惜玄发。
之子良史才，华簪偶时哲。
相思千里道，愁望飞鸟绝。
岁暮冰雪寒，淮湖不可越。
百年去心虑，孤影守薄劣。
独余慕侣情，金石无休歇。','',''),('quantangshi-12173','登玉山诸峰偶至悟真寺','錢起','quantangshi','','卷13','郭南云水佳，讼简野情发。
紫芝每相引，黄绶不能緤。
稍入石门幽，始知灵境绝。
冥搜未寸晷，仙迳俄九折。
蟠木盖石梁，崩岸露云穴。
数峰拔昆仑，秀色与空澈。
玉气交晴虹，桂花留曙月。
半岩采珉者，一点如片雪。
真赏无前程，奇观宁暂辍。
更闻东林磬，可听不可说。
兴中寻觉化，寂尔诸象灭。','',''),('quantangshi-12174','长安客舍赠李行父明府','錢起','quantangshi','','卷13','藏器待时少，知人自古难。
遂令丹穴凤，晚食金琅玕。
谁谓兵戈际，鸣琴方一弹。
理烦善用简，济猛能兼宽。
夙夜念黎庶，寝兴非宴安。
洪波未静壑，何树不惊鸾。
凫舄傍京辇，甿心悬灌坛。
高槐暗苦雨，长剑生秋寒。
旅食还为客，饥年亦尽欢。
亲劳携斗水，往往救泥蟠。
但恐酬明义，蹉跎芳岁阑。','',''),('quantangshi-12175','美杨侍御清文见示','錢起','quantangshi','','卷13','伯牙道丧来，弦绝无人续。
谁知绝唱后，更有难和曲。
层峰与清流，逸势竞奔蹙。
清文不出户，仿像皆在目。
雾雪看满怀，兰荃坐盈掬。
孤光碧潭月，一片昆仑玉。
初见歌阳春，韶光变枯木。
再见吟白雪，便觉云肃肃。
则知造化源，方寸能展缩。
斯文不易遇，清爽心岂足。
愿言书诸绅，可以为佩服。','',''),('quantangshi-12176','山居新种花药与道土同游赋诗','錢起','quantangshi','','卷13','自乐鱼鸟性，宁求农牧资。
浅深爱岩壑，疏凿尽幽奇。
雨花相助好，莺鸣春草时。
种兰入山翠，引葛上花枝。
风露拆红紫，缘溪复映池。
新泉香杜若，片石引江蓠。
宛谓武陵洞，潜鹰造化移。
杖策携烟客，满袖掇芳蕤。
蝴蝶舞留我，仙鸡闲傍篱。
但令黄精熟，不虑韶光迟。
笑指云萝迳，樵人那得知。','',''),('quantangshi-12177','初黄绶赴蓝田县作','錢起','quantangshi','','卷13','蟠木无匠伯，终年弃山樊。
苦心非良知，安得入君门。
忽忝英达顾，宁窥造化恩。
萤光起腐草，云翼腾沈鲲。
片石世何用，良工心所存。
一叨尉京甸，三省惭黎元。
贤尹正趋府，仆夫俨归轩。
眼中县胥色，耳里苍生言。
居人散山水，即景真桃源。
鹿聚入田迳，鸡鸣隔岭村。
飡和俗久清，到邑政空论。
且嘉讼庭寂，前阶满芳荪。','',''),('quantangshi-12178','归义寺题震上人壁','錢起','quantangshi','','卷13','入谷逢雨花，香绿引幽步。
招提饶泉石，万转同一趣。
向背森碧峰，浅深罗古树。
尧皇未登极，此地曾隐雾。
祕谶得神谋，因高思虎踞。
太阳忽临照，物象俄光煦。
梵王宫始开，长者金先布。
白水入禅境，砀山通觉路。
往往无心云，犹起潜龙处。
仍闻七祖后，佛子继调御。
溪鸟投慧灯，山蝉饱甘露。
不作解缨客，宁知舍筏喻。
身世已悟空，归途复何去。','',''),('quantangshi-12179','奉和圣制登会昌山应制','錢起','quantangshi','','卷13','睿想入希夷，真游到具茨。
玉銮登嶂远，云辂出花迟。
泉壑凝神处，阳和布泽时。
六龙多顺动，四海正雍熙。','',''),('quantangshi-12180','省中对雪寄元判官拾遗昆季','錢起','quantangshi','','卷13','万点瑶台雪，飞来锦帐前。
琼枝应比净，鹤发敢争先。
散影成花月，流光透竹烟。
今朝谢家兴，几处郢歌传。','',''),('quantangshi-12181','山斋独坐喜玄上人夕至','錢起','quantangshi','','卷13','舍下虎溪径，烟霞入暝开。
柴门兼竹静，山月与僧来。
心莹红莲水，言忘绿茗杯。
前峰曙更好，斜汉欲西回。','',''),('quantangshi-12182','秋夜寄张韦二主簿','錢起','quantangshi','','卷13','凉夜褰帘好，轻云过月初。
碧空河色浅，红叶露声虚。
道阻天难问，机忘世易疎。
不知双翠凤，栖棘复何如。','',''),('quantangshi-12183','归故山路逢邻居隐者','錢起','quantangshi','','卷13','握手云栖路，澘然恨几重。
谁知绿林盗，长占彩霞峰。
心死池塘草，声悲石径松。
无因芳杜月，琴酒更相逢。','',''),('quantangshi-12184','落第刘拾遗相送东归','錢起','quantangshi','','卷13','不醉百花酒，伤心千里归。
独收和氏玉，还采旧山薇。
出处离心尽，荣枯会面稀。
预愁芳草色，一径入衡闱。','',''),('quantangshi-12185','和刘七读书','錢起','quantangshi','','卷13','夜雨深馆静，苦心黄卷前。
云阴留墨沼，萤影傍华编。
梦鸟富清藻，通经仍妙年。
何愁丹穴凤，不饮玉池泉。','',''),('quantangshi-12186','早下江宁','錢起','quantangshi','','卷13','暮天微雨散，凉吹片帆轻。
云物高秋节，山川孤客情。
霜苹留楚水，寒雁别吴城。
宿浦有归梦，愁猨莫夜鸣。','',''),('quantangshi-12187','登复州南楼','錢起','quantangshi','','卷13','孤树延春日，他山卷曙霞。
客心湖上雁，归思日边花。
行李迷方久，归期涉岁赊。','',''),('quantangshi-12188','江陵晦日陪诸官泛舟','錢起','quantangshi','','卷13','节物堪为乐，江湖有主人。
舟行深更好，山趣久弥新。
尊酒平生意，烟花异国春。
城南无夜月，长袖莫留宾。','',''),('quantangshi-12189','县城秋夕','錢起','quantangshi','','卷13','山城日易夕，愁生先掩扉。
俸薄不沽酒，家贫忘授衣。
露重蕙花落，月冷莎难飞。
効拙惭无补，云林叹再归。','',''),('quantangshi-12190','秋夜梁七兵曹同宿二首 一','錢起','quantangshi','','卷13','一笑不可得，同心相见稀。
摘菱频贳酒，待月未扃扉。
星影低惊鹊，虫声傍旅衣。
卑栖岁已晚，共羡雁南飞。','',''),('quantangshi-12191','秋夜梁七兵曹同宿二首 二','錢起','quantangshi','','卷13','好欲弃吾道，今宵又遇君。
老夫相劝酒，稚子待题文。
月下谁家笛，城头几片云。
如何此幽兴，明日重离羣。','',''),('quantangshi-12192','和万年成少府寓直','錢起','quantangshi','','卷13','赤县新秋夜，文人藻思催。
钟声自仙掖，月色近霜台。
一叶兼萤度，孤云带雁来。
明朝紫书下，应问长卿才。','',''),('quantangshi-12193','春夜过长孙绎别业','錢起','quantangshi','','卷13','佳期难再得，清夜此云林。
带竹新泉冷，穿花片月深。
含毫凝逸思，酌水话幽心。
不觉星河转，山枝惊曙禽。','',''),('quantangshi-12194','题温处士山居','錢起','quantangshi','','卷13','谁知白云外，别有绿萝春。
苔绕溪边径，花深洞里人。
逸妻看种药，稚子伴垂纶。
颍上逃尧者，何如此养真。','',''),('quantangshi-12195','题陈季壁','錢起','quantangshi','','卷13','郢人何苦调，饮水仍布衾。
烟火昼不起，蓬蒿春欲深。
前庭少乔木，邻舍闻新禽。
虽有征贤诏，终伤不遇心。','',''),('quantangshi-12196','赠邻居齐六司仓','錢起','quantangshi','','卷13','沈冥众所遗，咫尺绝佳期。
始觉衡门下，翛然太古时。
鸡声共邻巷，烛影隔茅茨。
坐惜牛羊迳，芳荪白露滋。','',''),('quantangshi-12197','送征雁','錢起','quantangshi','','卷13','秋空万里净，嘹唳独南征。
风急翻霜冷，云开见月惊。
塞长怯去翼，影灭有余声。
怅望遥天外，乡愁满目生。','',''),('quantangshi-12198','宴郁林观张道士房','錢起','quantangshi','','卷13','灭迹人间世，忘归象外情。
竹坛秋月冷，山殿夜钟清。
仙侣披云集，霞杯达曙斜。
同欢不可再，朝暮赤龙迎。','',''),('quantangshi-12199','秋夕与梁鍠文宴','錢起','quantangshi','','卷13','客到衡门下，林香蕙草时。
好风能自至，明月不须期。
秋日翻荷影，晴光脆柳枝。
留欢美清夜，宁觉晓钟迟。','',''),('quantangshi-12200','哭空寂寺玄上人','錢起','quantangshi','','卷13','凄然双树下，垂泪远公房。
灯续生前火，炉添没后香。
阴堦明片雪，寒竹响空廊。
寂灭应为乐，尘心徒自伤。','',''),('quantangshi-12201','题精舍寺','錢起','quantangshi','','卷13','胜景不易遇，入门神顿清。
房房占山色，处处分泉声。
诗思竹间得，道心松下生。
何时来此地，摆落世间情。','',''),('quantangshi-12202','开元观遇张侍御','錢起','quantangshi','','卷13','碧落忘归处，佳期不厌逢。
晚凉生玉井，新暑避烟松。
欲醉流霞酌，还醒度竹钟。
更怜琪树下，历历见遥峰。','',''),('quantangshi-12203','和人秋归终南山别业','錢起','quantangshi','','卷13','旧居三顾后，晚节重幽寻。
野迳到门尽，山窗连竹阴。
昔年莺山谷，今日凤归林。
物外凌云操，谁能继此心。','',''),('quantangshi-12204','故相国苗公挽歌','錢起','quantangshi','','卷13','灞陵谁宠葬，汉主念萧何。
盛业留青史，浮荣逐逝波。
陇云仍作雨，薤露已成歌。
凄怆平津阁，秋风吊客过。','',''),('quantangshi-12205','酬刘员外雨中见寄','錢起','quantangshi','','卷13','苦雨滴兰砌，秋风生葛衣。
潢污三迳绝，砧杵四邻稀。
分与玄豹隐，不为湘燕飞。
惭君角巾折，犹肯问衡闱。','',''),('quantangshi-12206','赋得归云送李山人归华山','錢起','quantangshi','','卷13','秀色横千里，归云积几重。
欲依毛女岫，初卷少姨峰。
盖影随征马，衣香拂卧龙。
秪应函谷上，真气日溶溶。','',''),('quantangshi-12207','过裴长官新亭','錢起','quantangshi','','卷13','茅屋多新意，芳林昨试移。
野人知石路，戏鸟认花枝。
慢水萦蓬户，闲云挂竹篱。
到家成一醉，归马不能骑。','',''),('quantangshi-12208','寄郢州郎士元使君','錢起','quantangshi','','卷13','龙节知无事，江城不掩扉。
诗传过客远，书到故人稀。
坐啸看潮起，行春送雁归。
望舒三五夜，思尽谢玄晖。','',''),('quantangshi-12209','过长孙宅与朗上人茶会','錢起','quantangshi','','卷13','偶与息心侣，忘归才子家。
玄谈兼藻思，绿茗代榴花。
岸帻看云卷，含毫任景斜。
松乔若逢此，不复醉流霞。','',''),('quantangshi-12210','下第题长安客舍','錢起','quantangshi','','卷13','不遂青云望，愁看黄鸟飞。
棃花度寒食，客子未春衣。
世事随时变，交情与我违。
空余主人柳，相见却依依。','',''),('quantangshi-12211','陪考功王员外城东池亭宴','錢起','quantangshi','','卷13','无双锦帐郎，绝境有林塘。
鹤静疎羣羽，蓬开失众芳。
晴山看不厌，流水趣何长。
日晚催归骑，钟声下夕阳。','',''),('quantangshi-12212','过孙员外蓝田山居','錢起','quantangshi','','卷13','不知香署客，谢病翠微间。
去幄兰将老，辞车雉亦闲。
近窗云出洞，当户竹连山。
对酒溪霞晚，家人采蕨还。','',''),('quantangshi-12213','秋园晚沐','錢起','quantangshi','','卷13','黄卷在穷巷，归来生道心。
五株衰柳下，三径小园深。
倒薤翻成字，寒花不假林。
庞眉谢羣彦，独酌且闲吟。','',''),('quantangshi-12214','穷秋对雨','錢起','quantangshi','','卷13','晦日连苦雨，动息更邅回。
生事萍无定，愁心云不开。
翟门悲暝雀，墨竈上寒苔。
始信宜城守，乘流畏曝腮。','',''),('quantangshi-12215','裴迪南门秋夜对月','錢起','quantangshi','','卷13','夜来诗酒兴，月满谢公楼。
影闭重门静，寒生独树秋。
鹊惊随叶散，萤远入烟流。
今夕遥天末，清光几处愁。','',''),('quantangshi-12216','和蜀县段明府秋城望归期','錢起','quantangshi','','卷13','制锦蜀江静，飞凫汉阙遥。
一兹风靡草，再视露盈条。
旅望多愁思，秋天更泬寥。
河阳传丽藻，清韵入歌谣。','',''),('quantangshi-12217','晚归蓝田酬王维给事赠别','錢起','quantangshi','','卷13','卑栖却得性，每与白云归。
徇禄仍怀橘，看山免采薇。
暮禽先去马，新月待开扉。
霄汉时回首，知音青琐闱。','',''),('quantangshi-12218','再得毕侍御书闻巴中卧病','錢起','quantangshi','','卷13','芳信来相续，同心远更亲。
数重云外树，不隔眼中人。
梦寐花骢色，相思黄鸟春。
更闻公干病，一夜二毛新。','',''),('quantangshi-12219','宿新里馆','錢起','quantangshi','','卷13','愁人待晓鸡，秋雨暗凄凄。
度烛萤时灭，传书雁渐低。
客来知计误，梦里泣津迷。
无以逃悲思，寒螿处处啼。','',''),('quantangshi-12220','谷口书斋寄杨补阙','錢起','quantangshi','','卷13','泉壑带茅茨，云霞生薜帷。
竹怜新雨后，山爱夕阳时。
闲鹭栖常早，秋花落更迟。
家童扫萝迳，昨与故人期。','',''),('quantangshi-12221','衡门春夜','錢起','quantangshi','','卷13','不厌晴林下，微风度葛巾。
宁唯北牕月，自谓上皇人。
丛筱轻新暑，孤花占晚春。
寄言庄叟蝶，与尔得天真。','',''),('quantangshi-12222','题吴通微主人','錢起','quantangshi','','卷13','食贫无尽日，有愿几时谐。
长啸秋光晚，谁知志士怀。
朝烟不起竈，寒叶欲连堦。
饮水仍留我，孤灯点夜斋。','',''),('quantangshi-12223','晚次宿预馆','錢起','quantangshi','','卷13','乡心不可问，秋气又相逢。
飘泊方千里，离悲复几重。
回云随去雁，寒露滴鸣蛩。
延颈遥天末，如闻故国钟。','',''),('quantangshi-12224','蓝上茅茨期王维补阙','錢起','quantangshi','','卷13','山中人不见，云去夕阳过。
浅濑寒鱼少，丛兰秋蝶多。
老年疎世事，幽性乐天和。
酒熟思才子，溪头望玉珂。','',''),('quantangshi-12225','春宵寓直','錢起','quantangshi','','卷13','养拙惯云卧，为郎如鸟栖。
不知仙阁峻，惟觉玉绳低。
帐喜香烟暖，诗惭赐笔题。
未央春漏促，残梦谢晨鸡。','',''),('quantangshi-12226','新昌里言怀','錢起','quantangshi','','卷13','性拙偶从宦，心闲多掩扉。
虽看北堂草，不忘旧山薇。
花月霁来好，云泉堪梦归。
如何建章漏，催着早朝衣。','',''),('quantangshi-12227','秋夜寄袁中丞王员外','錢起','quantangshi','','卷13','一夕盈千念，方知别者劳。
衰荣难会面，魂梦暂同袍。
片月临堦早，晴河度雁高。
应怜蒋生迳，秋露满蓬蒿。','',''),('quantangshi-12228','九日闲居寄登高数子','錢起','quantangshi','','卷13','初服栖穷巷，重阳忆旧游。
门闲谢病日，心醉授衣秋。
酒尽寒花笑，庭空暝雀愁。
今朝落帽客，几处管弦留。','',''),('quantangshi-12229','晚入宣城界','錢起','quantangshi','','卷13','斜日片帆阴，春风孤客心。
山来指樵路，岸去惜花林。
海气蒸云黑，潮声隔雨深。
乡愁不可道，浦宿听猨吟。','',''),('quantangshi-12230','静夜酬通上人问疾','錢起','quantangshi','','卷13','东林生早凉，高枕远公房。
大士看心后，中宵清漏长。
惊蝉出暗柳，微月隐回廊。
何事沈疴久，含毫问药王。','',''),('quantangshi-12231','奉陪使君十四叔晚憩大云门寺','錢起','quantangshi','','卷13','野寺千家外，闲行晚暂过。
炎氛临水尽，夕照傍林多。
境对知心妄，人安觉政和。
绳牀摇麈尾，佳趣满沧波。','',''),('quantangshi-12232','省中春暮酬嵩阳焦道士见招','錢起','quantangshi','','卷13','朝花飞暝林，对酒伤春心。
流年催素发，不觉映华簪。
垂老遇知己，酬恩看寸阴。
如何紫芝客，相忆白云深。','',''),('quantangshi-12233','酬苗发员外宿龙池寺见寄','錢起','quantangshi','','卷13','宁知待漏客，清夜此从容。
暂别迎车雉，还随护法龙。
香烟轻上月，林岭静闻钟。
郢曲传甘露，尘心洗几重。','',''),('quantangshi-12234','贞懿皇后挽词','錢起','quantangshi','','卷13','淑丽诗传美，徽章礼饰哀。
有恩加象服，无日祀高禖。
晓月孤秋殿，寒山出夜台。
通灵深眷想，青鸟独飞来。','',''),('quantangshi-12235','岁初归旧山','錢起','quantangshi','','卷13','欲知愚谷好，久别与春还。
莺暖初归树，云晴却恋山。
石田耕种少，野客性情闲。
求仲应难见，残阳且掩关。','',''),('quantangshi-12236','銮驾避狄岁寄别韩云卿','錢起','quantangshi','','卷13','白发壮心死，愁看国步移。
关山惨无色，亲爱忽惊离。
影绝龙分剑，声衰鸟恋枝。
茫茫云海外，相忆不相知。','',''),('quantangshi-12237','咏白油帽送客','錢起','quantangshi','','卷13','薄质惭加首，愁阴幸庇身。
卷舒无定日，行止必依人。
已沐脂膏惠，宁辞雨露频。
虽同客衣色，不染洛阳尘。','',''),('quantangshi-12238','蓝上采石芥寄前李明府','錢起','quantangshi','','卷13','渊明遗爱处，山芥绿芳初。
翫此春阴色，犹滋夜雨余。
隔溪烟叶小，覆石雪花舒。
采采还相赠，瑶华信不如。','',''),('quantangshi-12239','送贇法师往上都','錢起','quantangshi','','卷13','远近化人天，王城指日边。
宰君迎说法，童子伴随缘。
到处花为雨，行时杖出泉。
今霄松月下，门闭想安禅。','',''),('quantangshi-12240','送沈少府还江宁','錢起','quantangshi','','卷13','远宦碧云外，此行佳兴牵。
湖山入闾井，鸥鸟傍神仙。
斜日背乡树，春潮迎客船。
江楼新咏发，应与政声传。','',''),('quantangshi-12241','送虞说擢第东游','錢起','quantangshi','','卷13','湖山不可厌，东望有余情。
片玉登科后，孤舟任兴行。
月中严子濑，花际楚王城。
岁暮云臯鹤，闻天更一鸣。','',''),('quantangshi-12242','送少微师西行','錢起','quantangshi','','卷13','随缘忽西去，何日返东林。
世路宁磋别，空门久息心。
人烟一饭少，山雪独行深。
天外猨啼处，谁闻清梵音。','',''),('quantangshi-12243','送昆山孙少府','錢起','quantangshi','','卷13','徇禄近沧海，乘流看碧霄。
谁知仙吏去，宛与世尘遥。
远帆背归鸟，孤舟抵上潮。
悬知讼庭静，窗竹日萧萧。','',''),('quantangshi-12244','送屈突司马充安西书记','錢起','quantangshi','','卷13','制胜三军劲，澄清万里余。
星飞庞统骥，箭发鲁连书。
海月低云斾，江霞入锦车。
遥知太阿剑，计日斩鲸鱼。','',''),('quantangshi-12245','送时暹避难适荆南','錢起','quantangshi','','卷13','三叹把离袂，七哀深我情。
云天愁远别，豺虎拥前程。
驻马恋携手，隔河闻哭声。
相思昏若梦，泪眼几时明。','',''),('quantangshi-12246','送边补阙东归省觐','錢起','quantangshi','','卷13','东去有余意，春风生赐衣。
凤凰衔诏下，才子采兰归。
斗酒百花里，情人一笑稀。
别离须计日，相望在彤闱。','',''),('quantangshi-12247','送弹琴李长史往洪州','錢起','quantangshi','','卷13','抱琴为傲吏，孤棹复南行。
几度秋江水，皆添白雪声。
佳期来客梦，幽思缓王程。
佐牧无劳问，心和政自平。','',''),('quantangshi-12248','送宋征君让官还山','錢起','quantangshi','','卷13','至人无滞迹，谒帝复思玄。
魏阙辞花绶，春山有杏田。
紫霞开别酒，黄鹤舞离弦。
今夜思君梦，遥遥入洞天。','',''),('quantangshi-12249','送陈供奉恩勅放归觐省','錢起','quantangshi','','卷13','得意今如此，清光不可攀。
臣心尧日下，乡思楚云间。
杨柳依归棹，芙蓉栖旧山。
采兰兼衣锦，何似买臣还。','',''),('quantangshi-12250','送外甥范勉赴任常州长史兼觐省','錢起','quantangshi','','卷13','怜君展骥去，能解倚门愁。
就养仍荣禄，还乡即昼游。
橘花低客舍，莼菜绕归舟。
与报垂纶叟，知吾世网留。','',''),('quantangshi-12251','陇右送韦三还京','錢起','quantangshi','','卷13','春风起东道，握手望京关。
柳色从乡至，莺声送客还。
嘶骖顾近驿，归路出他山。
举目情难尽，羁离失志间。','',''),('quantangshi-12252','送元评事归山居','錢起','quantangshi','','卷13','忆家望云路，东去独依依。
水宿随渔火，山行到竹扉。
寒花催酒熟，山犬喜人归。
遥羡书窗下，千峰出翠微。','',''),('quantangshi-12253','送武进韦明府','錢起','quantangshi','','卷13','理邑想无事，鸣琴不下堂。
井田通楚越，津市半渔商。
卢橘垂残雨，红莲拆早霜。
送君催白首，临水独思乡。','',''),('quantangshi-12254','送上官侍御','錢起','quantangshi','','卷13','执简朝方下，乘轺去不赊。
感恩轻远道，入幕比还家。
碣石春云色，邯郸古树花。
飞书报明主，烽火静天涯。','',''),('quantangshi-12255','送郭秀才制举下第南游','錢起','quantangshi','','卷13','失志思浪迹，知君晦近名。
出关尘渐远，过郢兴弥清。
山尽溪初广，人闲舟自行。
探幽无旅思，莫畏楚猨鸣。','',''),('quantangshi-12256','送夏侯审校书东归','錢起','quantangshi','','卷13','楚乡飞鸟没，独与碧云还。
破镜催归客，残阳见旧山。
诗成流水上，梦尽落花间。
傥寄相思字，愁人定解颜。','',''),('quantangshi-12257','送卫功曹赴荆南','錢起','quantangshi','','卷13','汉家仍用武，才子晚成名。
惆怅江陵去，谁知魏阙情。
碧云愁楚水，春酒醉宜城。
定想褰帷政，还闻坐啸声。','',''),('quantangshi-12258','送马使君赴郑州','錢起','quantangshi','','卷13','东土忽无事，专城复任贤。
喜观班瑞礼，还在偃兵年。
膏雨带荥水，归人耕圃田。
遥知下车日，万井起新烟。','',''),('quantangshi-12259','送郎四补阙东归','錢起','quantangshi','','卷13','无事共干世，多时废隐沦。
相看恋簪组，不觉老风尘。
劝酒怜今别，伤心倍去春。','',''),('quantangshi-12260','送陆三出尉','錢起','quantangshi','','卷13','春草晚来色，东门愁送君。
盛才仍下位，明代负奇文。
且乐神仙道，终随鸳鹭羣。
梅生寄黄绶，不日在青云。','',''),('quantangshi-12261','送安都秀才北还','錢起','quantangshi','','卷13','年少工文客，言离却解颜。
不嗟荆宝退，能喜彩衣还。
新月来前馆，高阳出故关。
相思东北望，燕赵隔青山。','',''),('quantangshi-12262','送褚十一澡擢第归吴觐省','錢起','quantangshi','','卷13','林表吴山色，诗人思不忘。
向家流水便，怀橘彩衣香。
满酌留归骑，前程未夕阳。
怆兹江海去，谁惜杜蘅芳。','',''),('quantangshi-12263','送费秀才归衡州','錢起','quantangshi','','卷13','南望潇湘渚，词人远忆家。
客心随楚水，归棹宿江花。
不畏心期阻，惟愁面会赊。
云天有飞翼，方寸伫瑶华。','',''),('quantangshi-12264','送陆郎中','錢起','quantangshi','','卷13','事边仍恋主，举酒复悲歌。
粉署含香别，辕门载笔过。
莺声出汉苑，柳色过漳河。
相忆情难尽，离居春草多。','',''),('quantangshi-12265','送僧归日本','錢起','quantangshi','','卷13','上国随缘住，来途若梦行。
浮天沧海远，去世法舟轻。
水月通禅观，鱼龙听梵声。
惟怜一灯影，万里眼中明。','',''),('quantangshi-12266','送杨皞擢第游江南','錢起','quantangshi','','卷13','行人临水去，新咏复新悲。
万里高秋月，孤山远别时。
挂帆严子濑，酹酒敬亭祠。','',''),('quantangshi-12267','送田仓曹归觐','錢起','quantangshi','','卷13','青丝络骢马，去府望梁城。
节下趋庭处，秋来怀橘情。
别筵寒日晚，归路碧云生。
千里相思夜，愁看新月明。','',''),('quantangshi-12268','送张管书记','錢起','quantangshi','','卷13','边事多劳役，儒衣逐鼓鼙。
日寒关树外，峰尽塞云西。
河广篷难度，天遥雁渐低。
班超封定远，之子去思齐。','',''),('quantangshi-12269','送萧常侍北使','錢起','quantangshi','','卷13','绛节引雕戈，鸣驺动玉珂。
戎城去日远，汉使隔年多。
雁宿常连雪，沙飞半渡河。
明光朝即迩，[杕]杜早成歌。','',''),('quantangshi-12270','送李栖桐道举擢第还乡省侍','錢起','quantangshi','','卷13','几年深道要，一举过贤关。
名与玄珠出，乡宜昼锦还。
莲舟同宿浦，柳岸向家山。
欲见宁亲孝，儒衣稚子斑。','',''),('quantangshi-12271','送柳道士','錢起','quantangshi','','卷13','去世能成道，游仙不定家。
归期千岁鹤，行迈五云车。
海上春应尽，壶中日未斜。
不知相忆处，琪树几枝花。','',''),('quantangshi-12272','送陆珽侍御使新罗','錢起','quantangshi','','卷13','衣冠周柱史，才学我乡人。
受命辞云陛，倾城送使臣。
去程沧海月，归思上林春。
始觉儒风远，殊方礼乐新。','',''),('quantangshi-12273','重送陆侍御使日本','錢起','quantangshi','','卷13','万里三韩国，行人满目愁。
辞天使星远，临水涧霜秋。
云佩迎仙岛，虹旌过蜃楼。
定知怀魏阙，回首海西头。','',''),('quantangshi-12274','送陆贽擢第还苏州','錢起','quantangshi','','卷13','乡路归何早，云间喜擅名。
思亲卢橘熟，带雨客帆轻。
夜火临津驿，晨钟隔浦城。
华亭养仙羽，计日再飞鸣。','',''),('quantangshi-12275','送虞说擢第南归觐省','錢起','quantangshi','','卷13','南风起别袂，心到衡湘间。
归客楚山远，孤舟云水闲。
爱君采莲处，花岛连家山。
得意且宁省，人生难此还。','',''),('quantangshi-12276','送原公南游','錢起','quantangshi','','卷13','有意兼程去，飘然二翼轻。
故乡多久别，春草不伤情。
洗钵泉初暖，焚香晓更清。','',''),('quantangshi-12277','送万兵曹赴广陵','錢起','quantangshi','','卷13','秋日思还客，临流语别难。
楚城将坐啸，郢曲有余悲。
山晚桂花老，江寒苹叶衰。
应须杨得意，更诵长卿辞。','',''),('quantangshi-12278','送李判官赴桂州幕','錢起','quantangshi','','卷13','欲知儒道贵，缝掖见诸侯。
且感千金诺，宁辞万里游。
雁峰侵瘴远，桂水出云流。
坐惜离居晚，相思绿蕙秋。','',''),('quantangshi-12279','题苏公林亭','錢起','quantangshi','','卷13','平津东阁在，别是竹林期。
万叶秋声里，千家落照时。
门随深巷静，窗过远钟迟。
客位苔生处，依然又赋诗。','',''),('quantangshi-12280','赋得寒云轻重色送子恂入京','錢起','quantangshi','','卷13','无限寒云色，苍茫浅更深。
从龙如有瑞，捧日不成阴。
积翠全低岭，虚明半出林。
帝乡遥在目，铁马又骎骎。','',''),('quantangshi-12281','赋得丛兰曙后色送梁侍御人京','錢起','quantangshi','','卷13','曙色传芳意，分明锦绣丛。
兰生齐后日，花发夜来风。
不向三峰里，全胜一县中。
遥知大苑内，应待五花骢。','',''),('quantangshi-12282','赋得余冰','錢起','quantangshi','','卷13','晓日余冰上，春池一镜明。
多从履处薄，偏向饮时清。
比雪光仍在，因风片不成。
更随舟楫去，犹可助坚贞。','',''),('quantangshi-12283','赋得浦口望斜月送皇甫判官','錢起','quantangshi','','卷13','起见西楼月，依依向浦斜。
动摇生浅浪，明灭照寒沙。
水渚犹疑雪，梅林不辨花。
送君无可赠，持此代瑶华。','',''),('quantangshi-12284','赋得绵绵思远道送岑判官入岭','錢起','quantangshi','','卷13','极目烟霞外，孤舟一使星。
兴中寻白雪，梦里过沧溟。
夜月松江戍，秋风竹坞亭。
不知行远近，芳草日青青。','',''),('quantangshi-12285','江宁春夜裴使君席送萧员外','錢起','quantangshi','','卷13','花院日扶疎，江云自卷舒。
主人熊轼任，归客稚门车。
曙月稀星里，春烟紫禁余。
行看石头戍，记得是南徐。','',''),('quantangshi-12286','送薛八谪居','錢起','quantangshi','','卷13','东水将孤客，南行路几千。
虹翻潮上雨，鸟落瘴中天。
谪去宁留恨，思归岂待年。
衔杯且一醉，别泪莫潸然。','',''),('quantangshi-12287','送衡阳归客','錢起','quantangshi','','卷13','归客爱鸣榔，南征忆旧乡。
江山追宋玉，云雨忆荆王。
醉里宜城近，歌中郢路长。
怜君从此去，日夕望三湘。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-12288','送员外侍御入朝','錢起','quantangshi','','卷13','别思乱无绪，妖氛犹未清。
含香五夜客，持赋十年兄。
霜拂金波树，星回玉斗城。
自怜江上鹤，垂翅羡飞鸣。','',''),('quantangshi-12289','送李谏议归荆州','錢起','quantangshi','','卷13','归舟同不系，纤草剩忘忧。
禁掖曾通籍，江城旧列侯。
暮帆依夏口，春雨梦荆州。
何日朝云陛，随君拜冕旒。','',''),('quantangshi-12290','送元中丞江淮转运','錢起','quantangshi','','卷13','薄税归天府，轻徭赖使臣。
欢霑赐帛老，恩及卷绡人。
去问殊官俗，来经几劫春。
东南御亭上，莫问有风尘。','',''),('quantangshi-12291','送唐别驾赴郢州','錢起','quantangshi','','卷13','少年从事好，此去别愁轻。
满座诗人兴，随君郢路行。
蒹葭侵驿树，云水抱山城。
遥爱下车日，江臯春草生。','',''),('quantangshi-12292','送郑巨及第后归觐','錢起','quantangshi','','卷13','多才白华子，初擅桂枝名。
嘉庆送归客，新秋带雨行。
离人背水去，喜鹊近家迎。
别赠难为此，衰年畏后生。','',''),('quantangshi-12293','宿远上人兰若','錢起','quantangshi','','卷13','香花闭一林，真士此看心。
行道白云近，然灯翠壁深。
梵筵清水月，禅坐冷山阴。
更说东溪好，明朝乘兴寻。','',''),('quantangshi-12294','酬元祕书晚出蓝溪见寄','錢起','quantangshi','','卷13','野兴引才子，独行幽径迟。
云留下山处，鸟静出溪时。
拙宦不忘隐，归休常在兹。
知音倘相访，炊黍扫茅茨。','',''),('quantangshi-12295','别张起居','錢起','quantangshi','','卷13','有别时留恨，销魂况在今。
风涛初振海，鵷鹭各辞林。
旧国关河绝，新秋草露深。
陆机婴世网，应负故山心。','',''),('quantangshi-12296','郭司徒厅夜宴','錢起','quantangshi','','卷13','秋堂复夜阑，举目尽悲端。
霜堞鸟声苦，更楼月色寒。
美人深别意，斗酒少留欢。
明发将何赠，平生双玉盘。','',''),('quantangshi-12297','初至京口示诸弟','錢起','quantangshi','','卷13','还家百战后，访故几人存。
兄弟得相见，荣枯何处论。
新诗添卷轴，旧业见儿孙。
点检平生事，焉能出荜门。','',''),('quantangshi-12298','月下洗药','錢起','quantangshi','','卷13','汲井向新月，分流入众芳。
湿花低桂影，翻叶静泉光。
露下添余润，蜂惊引暗香。
寄言养生客，来此共提筐。','',''),('quantangshi-12299','晚春永宁墅小园独坐寄上王相公','錢起','quantangshi','','卷13','东阁一何静，莺声落日愁。
夔龙暂为别，昏旦思兼秋。
蕙草出篱外，花枝寄竹幽。
上方传雅颂，七夕让风流。','',''),('quantangshi-12300','岁暇题茅茨','錢起','quantangshi','','卷13','谷口逃名客，归来遂野心。
薄田供岁酒，乔木待新禽。
溪路春云重，山厨夜火深。
桃源应渐好，仙客许相寻。','',''),('quantangshi-12301','九日登玉山','錢起','quantangshi','','卷13','霞景青山上，谁知此胜游。
龙沙传往事，菊酒对今秋。
步石随云起，题诗向水流。
忘归更有处，松下片云幽。','',''),('quantangshi-12302','宴崔驸马玉山别业','錢起','quantangshi','','卷13','金榜开青琐，骄奢半隐沦。
玉箫惟送酒，罗袖爱留宾。
竹馆烟催瞑，梅园雪误春。
满朝辞赋客，尽是入林人。','',''),('quantangshi-12303','春谷幽居','錢起','quantangshi','','卷13','黄鸟鸣园柳，新阳改旧阴。
春来此幽兴，宛是谢公心。
扫迳兰芽出，添池山影深。
虚名随振鹭，安得久栖林。','',''),('quantangshi-12304','赋得池上双丁香树','錢起','quantangshi','','卷13','得地移根远，交柯遶指柔。
露香浓结桂，池影鬬蟠虬。
黛叶轻筠绿，金花笑菊秋。
何如南海外，雨露隔炎洲。','',''),('quantangshi-12305','题樊川杜相公别业','錢起','quantangshi','','卷13','数亩园林好，人知贤相家。
结茅书阁俭，带水槿篱斜。
古树生春藓，新荷卷落花。
圣恩加玉铉，安得卧青霞。','',''),('quantangshi-12306','酬卢十一过宿','錢起','quantangshi','','卷13','乞还方未遂，日夕望云林。
况复逢青草，何妨问此心。
闭门公务散，枉策故情深。
遥夜他乡宿，同君梁甫吟。','',''),('quantangshi-12307','崔十四宅问候','錢起','quantangshi','','卷13','晓日早莺啼，江城旅思迷。
微官同寄傲，移疾阻招携。
远水闾阎内，青山稚堞西。
王孙莫久卧，春草欲萋萋。','',''),('quantangshi-12308','山路见梅感而有作','錢起','quantangshi','','卷13','莫言山路僻，还被好风催。
行客凄凉过，村篱冷落开。
晚溪寒水照，晴日数蜂来。
重忆江南酒，何因把一杯。','',''),('quantangshi-12309','咏门上画松上元王杜三相公','錢起','quantangshi','','卷13','昔闻生涧底，今见起毫端。
众草此时没，何人知岁寒。
岂能裨栋宇，且欲出门阑。
只在丹青笔，凌云也不难。','',''),('quantangshi-12310','早发东阳','錢起','quantangshi','','卷13','信风催过客，早发梅花桥。
数雁起前渚，千艘争便潮。
将随浮云去，日惜故山遥。
惆怅烟波末，佳期在碧霄。','',''),('quantangshi-12311','舟中寄李起居','錢起','quantangshi','','卷13','南行风景好，昏旦水臯闲。
春色郢中树，晴霞湖上山。
去家旅帆远，回首暮潮还。
蕙草知何赠，故人云汉间。','',''),('quantangshi-12312','夜雨寄寇校书','錢起','quantangshi','','卷13','秋馆烟雨合，重城钟漏深。
佳期阻清夜，孤兴发离心。
烛影出绡幕，虫声连素琴。
此时蓬阁友，应念昔同衾。','',''),('quantangshi-12313','喜李侍御拜郎官入省','錢起','quantangshi','','卷13','粉署花骢入，丹霄紫诰垂。
直庐惊漏近，赐被觉霜移。
汉主前瑶席，穰侯许凤池。
应怜后行雁，空羡上林枝。','',''),('quantangshi-12314','苏端林亭对酒喜雨','錢起','quantangshi','','卷13','小雨飞林顶，浮凉入晚多。
能知留客处，偏与好风过。
濯锦飜红蕊，跳珠乱碧荷。
芳尊深几许，此兴可酣歌。','',''),('quantangshi-12315','见上林春雁翔青云寄杨起居李员外','錢起','quantangshi','','卷13','上林春更好，宾雁不知归。
顾影怜青籞，传声入紫微。
夜陪池鹭宿，朝出苑花飞。
宁忆寒乡侣，鸾凰一见稀。','',''),('quantangshi-12316','偶成','錢起','quantangshi','','卷13','含毫意不浅，微月上帘栊。
门静吏人息，心闲囹圄空。
繁星入疎树，惊鹊倦秋风。
始觉牵卑剧，宵眠亦在公。','',''),('quantangshi-12317','渔潭值雨','錢起','quantangshi','','卷13','日入林岛异，鹤鸣风草间。
孤帆泊枉渚，飞雨来前山。
客意念留滞，川途忽阻艰。
赤亭仍数里，夜待安流还。','',''),('quantangshi-12318','题萧丞小池','錢起','quantangshi','','卷13','莺鸣蕙草绿，朝兴情人期。
林沼忘言处，鸳鸿养翮时。
春泉滋药暖，晴日度花迟。
此会无辞醉，良辰难再追。','',''),('quantangshi-12319','送集贤崔八叔承恩括图书','錢起','quantangshi','','卷13','雨露满儒服，天心知子虚。
还劳五经笥，更访百家书。
赠别倾文苑，光华比使车。
晚云随客散，寒树出关疎。
相见应朝夕，归期在玉除。','',''),('quantangshi-12320','送张五员外东归楚州','錢起','quantangshi','','卷13','缨佩不为美，人羣宁免辞。
杳然黄鹄去，未负白云期。
此别清兴尽，高秋临水时。
好山枉帆僻，浪迹到家迟。
他日诏书下，梁鸿安可追。','',''),('quantangshi-12321','闲居寄包何','錢起','quantangshi','','卷13','去名即栖遁，何必归沧浪。
种药幽不浅，杜门喧自忘。
林眠多晓梦，鸦散惊初阳。
片雪幽云至，回风邻果香。
佳期碧天末，惆怅紫兰芳。','',''),('quantangshi-12322','津梁寺寻李侍御','錢起','quantangshi','','卷13','禅林绝过客，柱史正焚香。
驯鸽不猜隼，慈云能护霜。
骢声隔暗竹，吏事散空廊。
霄汉期鸳鹭，狐狸避宪章。
遶堦春色至，屈草待君芳。','',''),('quantangshi-12323','山园秋晚寄杜黄裳少府','錢起','quantangshi','','卷13','惆怅佳期阻，园林秋景闲。
终朝碧云外，唯见暮禽还。
泉石思携手，烟霞不闭关。
杖藜仍把菊，对卷也看山。
望望离心起，非君谁解颜。','',''),('quantangshi-12324','东溪杜野人致酒','錢起','quantangshi','','卷13','万重云树下，数亩子平居。
野院罗泉石，荆扉背里闾。
早冬耕凿暇，弋雁复烹鱼。
静扫寒花径，唯邀傲吏车。
晚来留客好，小雪下山初。','',''),('quantangshi-12325','忆山中寄旧友','錢起','quantangshi','','卷13','数岁白云里，与君同采薇。
树深烟不散，溪静鹭忘飞。
更忆东岩趣，残阳破翠微。
脱巾花下醉，洗药月前归。
风景今还好，如何与世违。','',''),('quantangshi-12326','东臯早春寄郎四校书','錢起','quantangshi','','卷13','禄微赖学稼，岁起归衡茅。
穷达恋明主，耕桑亦近郊。
夜来霁山雪，阳气动林梢。
兰蕙暖初吐，春鸠鸣欲巢。
蓬莱时入梦，知子忆贫交。','',''),('quantangshi-12327','玉山东溪题李叟屋壁','錢起','quantangshi','','卷13','霞景已斜照，烟溪方暝投。
山家归路僻，辙迹乱泉流。
野老采薇暇，蜗庐招客幽。
麏麚突荒院，鸬鹊步闲畴。
偶此惬真性，令人轻宦游。','',''),('quantangshi-12328','温泉宫礼见','錢起','quantangshi','','卷13','新丰佳气满，圣主在温泉。
云暧龙行处，山明日驭前。
顺风求至道，侧席问遗贤。
灵雪瑶墀降，晨霞彩仗悬。
沧溟不让水，疵贱也朝天。','',''),('quantangshi-12329','游襄阳泉石晚归','錢起','quantangshi','','卷13','游目随山胜，回桡爱浦长。
往来幽不浅，昏旦兴难忘。
木末看归翼，莲西失夕阳。
人声指闾井，野趣惜林塘。
稍近垂杨路，菱舟拥岸香。','',''),('quantangshi-12330','夏日陪史郎中宴杜郎中果园','錢起','quantangshi','','卷13','何事重逢迎，春醪晚更清。
林端花自老，池上月初明。
路入仙郎次，乌连柱史名。
竹阴疎柰院，山翠傍芜城。
引满不辞醉，风来待曙更。','',''),('quantangshi-12331','南溪春耕','錢起','quantangshi','','卷13','荷蓑趣南迳，戴胜鸣条枚。
溪雨有余润，土膏宁厌开。
沟塍落花尽，耒耜度云回。
谁道耦耕倦，仍兼胜赏催。
日长农有暇，悔不带经来。','',''),('quantangshi-12332','省试湘灵鼓瑟','錢起','quantangshi','','卷13','善鼓云和瑟，常闻帝子灵。
冯夷空自舞，楚客不堪听。
苦调凄金石，清音入杳冥。
苍梧来怨慕，白芷动芳馨。
流水传潇浦，悲风过洞庭。
曲终人不见，江上数峰青。','',''),('quantangshi-12333','观法驾自凤翔回','錢起','quantangshi','','卷13','欃枪一扫灭，阊阖九重开。
海晏鲸鲵尽，天旋日月来。
圣情苏品物，龙御辟云雷。
晓漏移仙仗，朝阳出帝台。
周惭散马出，禹让浚川回。
欲识封人愿，南山举酒杯。','',''),('quantangshi-12334','题玉山村叟屋壁','錢起','quantangshi','','卷13','谷口好泉石，居人能陆沈。
牛羊下山小，烟火隔云深。
一迳入溪色，数家连竹阴。
藏虹辞晚雨，惊隼落残禽。
涉趣皆流目，将归羡在林。
却思黄绶事，辜负紫芝心。','',''),('quantangshi-12335','县中池竹言怀','錢起','quantangshi','','卷13','官小志已足，时清免负薪。
卑栖且得地，荣耀不关身。
自爱赏心处，丛篁流水滨。
荷香度高枕，山色满南邻。
道在即为乐，机忘宁厌贫。
却愁丹凤诏，来访漆园人。','',''),('quantangshi-12336','山园栖隐','錢起','quantangshi','','卷13','守静信推分，灌园乐在兹。
且忘尧舜力，宁顾尚书期。
晚景采兰暇，空林散帙时。
卷荷藏露滴，黄口触虫丝。
三径与嚣远，一瓢常自怡。
情人半云外，风月讵相思。','',''),('quantangshi-12337','送王谏议任东都居守','錢起','quantangshi','','卷13','车徒凤掖东，去去洛阳宫。
暂以青蒲隔，还看紫禁同。
经过乘雨露，潇洒出鸳鸿。
官署名台下，云山旧苑中。
暮天双阙静，秋月九重空。
且喜成周地，诗人播国风。','',''),('quantangshi-12338','送郑书记','錢起','quantangshi','','卷13','决胜无遗策，辞天便起缨。
出身唯殉死，报国且能兵。
受命麒膦殿，参谋骠骑营。
短箫催别酒，斜日驻前旌。
义勇千夫敌，风沙万里行。
几年丹阙下，侯印锡书生。','',''),('quantangshi-12339','送族侄赴任','錢起','quantangshi','','卷13','林下不成兴，仲容微禄牵。
客程千里远，别念一帆悬。
欲欢卑栖去，其如胜趣偏。
云山深郡郭，花木净潮田。
坐啸帷应下，离居月复圆。
此时知小阮，相忆绿尊前。','',''),('quantangshi-12340','长安落第作','錢起','quantangshi','','卷13','始愿今如此，前途复若何。
无媒献词赋，生事日蹉跎。
不遇张华识，空悲甯戚歌。
故山归梦远，新岁客愁多。
刷羽思乔木，登龙恨失波。
散才非世用，回音谢云萝。','',''),('quantangshi-12341','酬长孙绎蓝溪寄杏','錢起','quantangshi','','卷13','爱君蓝水上，种杏近成田。
拂迳清阴合，临流彩实悬。
清香和宿雨，佳色出晴烟。
懿此倾筐赠，想知怀橘年。
芳馨来满袖，琼玖愿酬篇。
把玩情何极，云林若眼前。','',''),('quantangshi-12342','药堂秋暮','錢起','quantangshi','','卷13','隐来未得道，岁去愧云松。
茅屋空山暮，荷衣白露浓。
唯怜石苔色，不染世人踪。
潭静宜孤鹤，山深绝远钟。
有时丹竈上，数点彩霞重。
勉事壶公术，仙期待赤龙。','',''),('quantangshi-12343','哭常徴君','錢起','quantangshi','','卷13','万化一朝尽，穷泉悲此君。
如何丹竈术，能误紫芝焚。
不遂苍生望，空留封禅文。
远年随逝水，真气尽浮云。
山闭龙蛇蛰，林寒麋鹿羣。
伤心载酒地，仙菊为谁薰。','',''),('quantangshi-12344','送鲍中丞赴太原军营','錢起','quantangshi','','卷13','年壮才仍美，时来道易行。
宠兼三独任，威肃贰师营。
将略过南仲，天心寄北京。
云旗临塞色，龙笛出关声。
汉月随霜去，边尘计日清。
渐知王事好，文武用书生。','',''),('quantangshi-12345','奉送刘相公江淮催转运','錢起','quantangshi','','卷13','国用资戎事，臣劳为主忧。
将徴任土贡，更发济川舟。
拥传星还去，过池凤不留。
唯高饮水节，稍浅别家愁。
落叶淮边雨，孤山海上秋。
遥知谢公兴，微月上江楼。','',''),('quantangshi-12346','送李秀才落第游荆楚','錢起','quantangshi','','卷13','翠羽虽成梦，迁莺尚后羣。
名逃郄诜策，兴发谢玄文。
昏旦扁舟去，江山几路分。
上潮吞海日，归雁出湖云。
诗思应须苦，猨声莫厌闻。
离居见新月，那得不思君。','',''),('quantangshi-12347','奉陪郭常侍宴浐川山池','錢起','quantangshi','','卷13','掖垣携爱客，胜地赏年光。
向竹过宾馆，寻山到妓堂。
歌声掩金谷，舞态出平阳。
地满簪裾影，花添兰麝香。
莺啼春未老，酒冷日犹长。
安石风流事，须归问省郎。','',''),('quantangshi-12348','寇中送张司马归洛','錢起','quantangshi','','卷13','戎狄寇周日，衣冠适洛年。
客亭新驿骑，归路旧人烟。
吾道将东矣，秋风更飒然。
云愁百战地，树隔两乡天。
旅思蓬飘陌，惊魂雁怯弦。
今朝一尊酒，莫惜醉离筵。','',''),('quantangshi-12349','奉和宣城张太守南亭秋夕怀友','錢起','quantangshi','','卷13','池馆蟪蛄声，梧桐秋露晴。
月临朱戟静，河近画楼明。
卷幔浮凉入，闻钟永夜清。
片云悬曙斗，数雁过秋城。
羽扇扬风暇，瑶琴怅别情。
江山飞丽藻，谢朓让前名。','',''),('quantangshi-12350','过山人所居因寄诸遗补','錢起','quantangshi','','卷13','空谷春云满，愚公晦迹深。
一随玄豹隐，几换绿萝阴。
绝径人稀道，芳荪我独寻。
厨烟住峭壁，酒气出重林。
蝴蝶晴还舞，黄鹂晚暂吟。
所思青琐客，瑶草寄幽心。','',''),('quantangshi-12351','过鸣臯隐者','錢起','quantangshi','','卷13','磻石老红鲜，徴君卧几年。
飞泉出林下，一径过崖巅。
鸡犬逐人静，云霞宜地偏。
终朝数峰胜，不远一壶前。
仲月霁春雨，香风生药田。
丹溪不可别，琼草色芊芊。','',''),('quantangshi-12352','送杨錥归隐','錢起','quantangshi','','卷13','悔作扫门事，还吟招隐诗。
今年芳草色，不失故山期。
遥想白云里，采苓春日迟。
溪花藏石径，岩翠带茅茨。
九转莫飞去，三回良在兹。
还嗤茂陵客，贫病老明时。','',''),('quantangshi-12353','酬刘起居卧病见寄','錢起','quantangshi','','卷13','承颜看彩服，不觉别丹墀。
味道能忘病，过庭更学诗。
缭垣多画戟，远岫入书帷。
竹静携琴处，林香让果时。
声同叨眷早，交澹在年衰。
更枉兼金赠，难为继组词。','',''),('quantangshi-12354','陪南省诸公宴殿中李监宅','錢起','quantangshi','','卷13','将门高胜霍，相子宠过韦。
宦贵攀龙后，心倾待士时。
壶觞开雅宴，鸳鹭眷相随。
舞退燕姬曲，歌徴谢朓诗。
晚钟过竹静，醉客出花迟。
莫惜留余兴，良辰不可追。','',''),('quantangshi-12355','山斋读书寄时校书杜叟','錢起','quantangshi','','卷13','日爱蘅茅下，闲观山海图。
幽人自守朴，穷谷也名愚。
倒岭和溪雨，新泉到户枢。
丛兰齐稚子，蟠木老潜夫。
忆戴差过剡，游仙惯入壶。
濠梁时一访，庄叟亦吾徒。','',''),('quantangshi-12356','晚归蓝田旧居','錢起','quantangshi','','卷13','云卷东臯下，归来省故蹊。
泉移怜石在，林长觉原低。
旧里情难尽，前山赏未迷。
引藤看古木，尝酒咒春鸡。
兴与时髦背，年将野老齐。
才微甘引退，应得遂霞栖。','',''),('quantangshi-12357','寄袁州李嘉佑员外','錢起','quantangshi','','卷13','谁谓江山阻，心亲梦想偏。
容辉常在目，离别任经年。
郡国通流水，云霞共远天。
行春莺几啭，迟客月频圆。
雁有归乡羽，人无访戴船。
愿徴黄霸入，相见玉堦前。','',''),('quantangshi-12358','禁闱玩雪寄薛左丞','錢起','quantangshi','','卷13','玄云低禁苑，飞雪满神州。
虚白生台榭，寒光入冕旒。
粉凝宫壁静，乳结洞门幽。
细绕回风转，轻随落羽浮。
怒涛堆砌石，新月孕帘钩。
为报诗人道，丰年颂圣猷。','',''),('quantangshi-12359','春暮过石龟谷题温处士林园','錢起','quantangshi','','卷13','隐几无名老，何年此陆沈。
丘园自得性，婚嫁不婴心。
岁计因山薄，霞栖在谷深。
设罝连草色，晒药背松阴。
触兴云生岫，随耕鸟下林。
搘颐笑来客，头上有朝簪。','',''),('quantangshi-12360','宿毕侍御宅','錢起','quantangshi','','卷13','交情频更好，子有古人风。
晤语清霜里，平生苦节同。
心惟二仲合，室乃一瓢空。
落叶寄秋菊，愁云低夜鸿。
薄寒灯影外，残漏雨声中。
明发南昌去，回看御史骢。','',''),('quantangshi-12361','中书遇雨','錢起','quantangshi','','卷13','济旱惟宸虑，为霖即上台。
云衔七曜起，雨拂九门来。
纶阁飞丝度，龙渠激溜回。
色翻池上藻，香裛鼎前杯。
湘燕皆舒翼，沙鳞岂曝腮。
尺波应万假，虞海载沿洄。','',''),('quantangshi-12362','适楚次徐城','錢起','quantangshi','','卷13','去家随旅雁，几日到南荆。
行迈改乡邑，苦辛淹晦明。
畏途在淫雨，未暮息趋程。
穷木对秋馆，寒鵶愁古城。
迷津坐为客，对酒默含情。
感激念知己，匣中孤劒鸣。','',''),('quantangshi-12363','经李蒙颍阳旧居','錢起','quantangshi','','卷13','同心而早世，天道亦何论。
独有山阳宅，平生永不谖。
青溪引白鸟，流涕吊芳荪。
蔓草入空室，丛篁深毁垣。
旧游还在眼，神理更忘言。
唯见东山月，人亡不去门。','',''),('quantangshi-12364','赠汉阳隐者','錢起','quantangshi','','卷13','当年不出世，知子餐霞人。
乐道复安土，遗荣长隐身。
蘅茅古林曲，秔稻清江滨。
桂棹为渔暇，荷衣御暑新。
欵颜行在役，幽兴惜今晨。
分手天涯去，再来芳杜春。','',''),('quantangshi-12365','巨鱼纵大壑','錢起','quantangshi','','卷13','巨鱼纵大壑，遂性似乘时。
奋跃风生鬣，腾凌浪鼓鳍。
龙摅回地轴，鲲化想天池。
方快吞舟意，尤殊在藻嬉。
倾危嗟幕燕，隐晦诮泥龟。
喻士逢明主，才猷得所施。','',''),('quantangshi-12366','送李九归河北','錢起','quantangshi','','卷13','文武资人望，谋猷简圣情。
南州初卧鼓，东土复维城。
寄重分符去，威仍出阃行。
斗牛移八座，日月送双旌。
别恋瞻天起，仁风应物生。
伫闻收组练，锵玉会承明。','',''),('quantangshi-12367','送丁着作佐台郡','錢起','quantangshi','','卷13','多年金马客，名遂动归轮。
佐郡紫书下，过门朱绶新。
扬舲望海岳，入境背风尘。
水驿偏乘月，梅园别受春。
带经临府吏，鲙鲤待乡人。
始见美高士，逍遥在搢绅。','',''),('quantangshi-12368','送王使君赴太原行营','錢起','quantangshi','','卷13','太白明无象，皇威未戢戈。
诸侯持节钺，千里控山河。
汉驿双旌度，胡沙七骑过。
惊蓬连雁起，牧马入云多。
不卖卢龙塞，能消瀚海波。
须传出师颂，莫奏式微歌。','',''),('quantangshi-12369','送王使君移镇淮南','錢起','quantangshi','','卷13','共许徐方牧，能临河内人。
郡移棠转茂，车至鹿还驯。
吏事嘉师旅，鸳行惜搢绅。
别心倾祖席，愁望尽征轮。
紫诰徴黄晚，苍生借寇频。
愿言青琐拜，早及上林春。','',''),('quantangshi-12370','李四劝为尉氏尉李七勉为开封尉','錢起','quantangshi','','卷13','美政惟兄弟，时人数俊贤。
皇枝双玉树，吏道二梅仙。
自理尧唐俗，唯将礼让传。
采兰花萼聚，就日雁行联。
黄绶俄三载，青云未九迁。
庙堂为宰制，几日试龙泉。','',''),('quantangshi-12371','春夜宴任六昆季宅','錢起','quantangshi','','卷13','际晚绿烟起，入门芳树深。
不才叨下客，喜宴齿诸簪。
夜月仍携妓，清风更在林。
彩毫挥露色，银烛动花阴。
自接通家好，应知待士心。
向隅逢故识，兹夕愿披襟。','',''),('quantangshi-12372','闲居酬张起居见赠','錢起','quantangshi','','卷13','在林非避世，守拙自离羣。
弱羽谢风水，穷愁依典坟。
良知不遐弃，新咏独相闻。
能使幽兴苦，坐忘清景曛。
前山带乔木，暮鸟联归云。
向夕野人思，难忘骑省文。','',''),('quantangshi-12373','奉和王相公秋日戏赠元校书','錢起','quantangshi','','卷13','才妙心仍远，名疎迹可追。
清秋闻礼暇，新雨到山时。
胜事唯愁尽，幽寻不厌迟。
弄云怜鹤去，隔水许僧期。
贤相敦高躅，雕龙忆所思。
芙蓉洗清露，愿比谢公诗。','',''),('quantangshi-12374','过杨驸马亭子','錢起','quantangshi','','卷13','衣冠在汉庭，台榭接天成。
彩凤翻箫曲，祥鳣入馆名。
歌钟芳月曙，林嶂碧云生。
乱水归潭净，高花映竹明。
退朝追宴乐，开合醉簪缨。
长袖留嘉客，栖乌下禁城。','',''),('quantangshi-12375','山下别杜少府','錢起','quantangshi','','卷13','把手意难尽，前山日渐低。
情人那忍别，宿鸟尚同栖。
寸晷恋言笑，佳期欲阻暌。
离云愁出岫，去水咽分溪。
庄叟几虚说，杨朱空自迷。
伤心独归路，秋草更萋萋。','',''),('quantangshi-12376','晚出青门望终南别业','錢起','quantangshi','','卷13','能清谢朓思，暂下承明庐。
远山新水下，寒臯微雨余。
更怜归鸟去，宛到卧龙居。
笑指丛林上，闲云自卷舒。
宁心鸣凤日，却意钓璜初。
处贵有余兴，伊周位不如。','',''),('quantangshi-12377','送严士良侍奉詹事南游','錢起','quantangshi','','卷13','疏傅独知止，曾参善爱亲。
江山侍行迈，长幼出嚣尘。
握手想千古，此心能几人。
风光满长陌，草色傍征轮。
日夕望荆楚，莺鸣芳杜新。
渔烟月下浅，花屿水中春。
点翰遥相忆，含情向白苹。','',''),('quantangshi-12378','题祕书王迪城北池亭','錢起','quantangshi','','卷13','子乔来魏阙，明主赐衣簪。
从宦辞人事，同尘即道心。
还追大隐迹，寄此凤城阴。
昨夜新烟雨，池台清且深。
伏泉通粉壁，迸笋出花林。
晚沐常多暇，春醪时独斟。
西南汉宫月，复对绿窗琴。','',''),('quantangshi-12379','过王舍人宅','錢起','quantangshi','','卷13','入门花柳暗，知是近臣居。
大隐心何远，高风物自疎。
翛然静者事，宛得上皇余。
鸡犬偷仙药，儿童授道书。
清吟送客后，微月上城初。
彩笔有新咏，文星垂太虚。
承恩金殿宿，应荐马相如。','',''),('quantangshi-12380','过瑞龙观道士','錢起','quantangshi','','卷13','不知谁氏子，炼魄家洞天。
鹤待成丹日，人寻种杏田。
灵山含道气，物性皆自然。
白鹿顾瑞草，骊龙蟠玉泉。
得兹象外趣，便割区中缘。
石窦采云母，霞堂陪列仙。
主人善止客，柯烂忘归年。','',''),('quantangshi-12381','送沈仲','錢起','quantangshi','','卷13','天朴非外假，至人常晏如。
心期邈霄汉，词律响琼琚。
举酒常叹息，无人达子虚。
夜光失隋掌，骥騄伏盐车。
考室晋山下，归田秦岁初。
寒云随路合，落照下城余。
千里还同术，无劳怨索居。','',''),('quantangshi-12382','和韦侍御寓直对雨','錢起','quantangshi','','卷13','名贯四科首，班宜二妙齐。
如何厌白简，未得步金闺。
寓直晦秋雨，吟余闻远鸡。
漏声过旦冷，云色向窗低。
谁谓霄汉近，翻嗟心事暌。
兰滋人未握，霜晓鹗还栖。
伫见田郎字，亲劳御笔题。','',''),('quantangshi-12383','奉和圣制登朝元阁','錢起','quantangshi','','卷13','六合纡玄览，重轩启上清。
石林飞栋出，霞顶泰堦平。
拂曙銮舆上，曦阳瑞雪晴。
翠微回日驭，丹巘驻天行。
御气升银汉，垂衣俯锦城。
山通玉苑迥，河抱紫关明。
感物干文动，凝神道化成。
周王陟乔岳，列辟让英声。','',''),('quantangshi-12384','奉和杜相公移长兴宅奉呈元相公','錢起','quantangshi','','卷13','守贵常思俭，平津此意深。
能卑丞相宅，何谢故人心。
种蕙初抽带，移篁不改阴。
院梅朝助鼎，池凤夕归林。
觉路经中得，沧州梦里寻。
道高仍济代，恩重岂投簪。
报国谁知己，推贤共作霖。
兴来文雅振，清韵掷双金。','',''),('quantangshi-12385','送任先生任唐山丞','錢起','quantangshi','','卷13','再命果良愿，几年勤说诗。
上公频握发，才子共垂帷。
琢玉成良器，出门偏怆离。
腰章佐墨绶，耀锦到茅茨。
树老见家日，潮平归县时。
衣催莲女织，颂听海人词。
鸿鹄志应在，荃兰香未衰。
金门定回音，云路有佳期。','',''),('quantangshi-12386','送外甥怀素上人归乡侍奉','錢起','quantangshi','','卷13','释子吾家宝，神清慧有余。
能翻梵王字，妙尽伯英书。
远鹤无前侣，孤云寄太虚。
狂来轻世界，醉里得真如。
飞锡离乡久，宁亲喜腊初。
故池残雪满，寒柳霁烟疎。
寿酒还尝药，晨餐不荐鱼。
遥知禅诵外，健笔赋闲居。','',''),('quantangshi-12387','送张中丞赴桂州','錢起','quantangshi','','卷13','出守求人瘼，推贤动圣情。
紫台初下诏，皂盖始专城。
宠借飞霜简，威加却月营。
云衢降五马，林木引双旌。
夙仰敦诗礼，尝闻偃甲兵。
戍楼云外静，讼阁竹间清。
化伫还珠美，心将片玉贞。
寇恂朝望重，计日谒承明。','',''),('quantangshi-12388','送王相公赴范阳','錢起','quantangshi','','卷13','翊圣衔恩重，频年按节行。
安危皆报国，文武不缘名。
受脤乃调鼎，为霖更洗兵。
幕开丞相阁，旗总贰师营。
料敌知无战，安边示有征。
代云横马首，燕雁拂笳声。
去镇关河静，归看日月明。
欲知瞻恋切，迟暮一书生。','',''),('quantangshi-12389','送蒋尚书居守东都','錢起','quantangshi','','卷13','凤辇幸秦久，周人徯帝情。
若非君敏德，谁镇洛阳城。
前席命才彦，举朝推令名。
纶言动北斗，职事守东京。
郑履下天去，蘧轮满路声。
出关秋树直，对阙远山明。
肃肃保厘处，水流宫苑清。
长安日西笑，朝夕衮衣迎。','',''),('quantangshi-12390','送李兵曹赴河中','錢起','quantangshi','','卷13','能荷钟鼎业，不矜纨绮荣。
侯门三事后，儒服一书生。
昔志学文史，立身为士英。
骊珠难隐耀，臯鹤会长鸣。
休命且随牒，候时常振缨。
寒蝉思关柳，匹马向蒲城。
秋日黯将暮，黄河如欲清。
黎人思坐啸，知子树佳声。','',''),('quantangshi-12391','罢官后酬元校书见赠','錢起','quantangshi','','卷13','心期怅已阻，交道复何如。
自我辞丹阙，惟君到故庐。
忘机贫负米，忆戴出无车。
邻犬吠初服，家人愁斗储。
秋堂入闲夜，云月思离居。
穷巷闻砧冷，荒枝应鹊疎。
宦名随落叶，生事感枯鱼。
临水仍挥手，知音未弃余。','',''),('quantangshi-12392','同邬戴关中旅寓','錢起','quantangshi','','卷13','文士皆求遇，今人谁至公。
灵台一寄宿，杨柳再春风。
更惜忘形友，频年失志同。
羽毛齐燕雀，心事阻鸳鸿。
留滞惭归养，飞鸣恨触笼。
橘怀乡梦里，书去客愁中。
残雪迷归雁，韶光弃断蓬。
吞悲问唐举，何路出屯蒙。','',''),('quantangshi-12393','新丰主人','錢起','quantangshi','','卷13','明代少知己，夜光频暗投。
迍邅终薄命，动息尽穷愁。
自欲归飞鷁，当为不系舟。
双垂素丝泪，几弊皂貂裘。
暮鸟栖幽树，孤云出旧丘。
蛩悲衣褐夕，雨暗转蓬秋。
客里冯谖劒，歌中甯戚牛。
主人能纵酒，一醉且忘忧。','',''),('quantangshi-12394','夕游覆釜山道士观因登玄元庙','錢起','quantangshi','','卷13','冥搜过物表，洞府次溪傍。
已入瀛洲远，谁言仙路长。
孤烟出深竹，道侣正焚香。
鸣磬爱山静，步虚宜夜凉。
仍同象帝庙，更上紫霞冈。
霁月悬琪树，明星映碧堂。
倾思丹竈术，愿采玉芝芳。
傥把浮丘袂，乘云别旧乡。','',''),('quantangshi-12395','陪郭常侍令公东亭宴集','錢起','quantangshi','','卷13','盛业山河列，重名劒履荣。
珥貂为相子，开合引时英。
美景池台色，佳期宴赏情。
词人载笔至，仙妓出花迎。
暗竹朱轮转，回塘玉佩鸣。
舞衫招戏蝶，歌扇隔啼莺。
饮德心皆醉，披云兴转清。
不愁懽乐尽，积庆在和羹。','',''),('quantangshi-12396','太子李舍人城东别业与二三文友逃暑','錢起','quantangshi','','卷13','下马失炎暑，重门深绿篁。
宫臣礼嘉客，林表开兰堂。
兹夕兴难尽，澄罍照墨塲。
鲜风吹印绶，密坐皆馨香。
美景惜文会，清吟迟羽觞。
东林晚来好，目极趣何长。
鸟道挂疎雨，人家残夕阳。
城隅拥归骑，留醉恋琼芳。','',''),('quantangshi-12397','柏崖老人号无名先生男削发女黄冠自以云泉独乐命予赋诗','錢起','quantangshi','','卷13','古也忧婚嫁，君能乐性肠。
长男栖月宇，少女炫霓裳。
问尔餐霞处，春山芝桂旁。
鹤前飞九转，壶里驻三光。
与我开龙峤，披云静药堂。
胡麻兼藻绿，石髓隔花香。
帝力言何有，椿年喜渐长。
窅然高象外，宁不傲羲皇。','',''),('quantangshi-12398','赠李十六','錢起','quantangshi','','卷13','半面喜投分，数年钦盛名。
常思梦颜色，谁忆访柴荆。
忽听欵扉响，欣然倒屣迎。
蓬蒿驻驺驭，鸡犬傍簪缨。
酌水即嘉宴，新知甚故情。
仆夫视日色，栖鸟催车声。
自尔宴言后，至今门馆清。
何当更乘兴，林下已苔生。','',''),('quantangshi-12399','裴仆射东亭','錢起','quantangshi','','卷13','凤扆任匡济，云溪难退还。
致君超列辟，得道在荣班。
朱戟缭垣下，高斋芳树间。
隔花开远水，废卷爱晴山。
晚沐值清兴，知音同解颜。
藉兰开赐酒，留客下重关。
仙犬逐人静，朝车映竹闲。
则知真隐逸，未必谢区寰。','',''),('quantangshi-12400','中书王舍人辋川旧居','錢起','quantangshi','','卷13','几年家绝壑，满径种芳兰。
带石买松贵，通溪涨水宽。
诵经连谷响，吹律减云寒。
谁谓桃源里，天书问考盘。
一从解蕙带，三入偶蝉冠。
今夕复何夕，归休寻旧欢。
片云隔苍翠，春雨半林湍。
藤长穿松盖，花繁压药栏。
景深青眼下，兴绝彩毫端。
笑向同来客，登龙此地难。','',''),('quantangshi-12401','送襄阳卢判官奏开河事','錢起','quantangshi','','卷13','千里趋魏阙，一言简圣聪。
河流引关外，国用赡秦中。
有诏许其策，随山兴此功。
连云积石阻，计日安波通。
飞棹转年谷，利人胜岁丰。
言归汉阳路，拜手蓬莱宫。
紫殿赐衣出，青门酣酌同。
晚阳过微雨，秋水见新鸿。
坐惜去车远，愁看离馆空。
因思郢川守，南楚满清风。','',''),('quantangshi-12402','奉送户部李郎中充晋国副节度出塞','錢起','quantangshi','','卷13','德佐调梅用，忠输击虏年。
子房推庙略，汉主托兵权。
受命荣中禁，分麾镇左贤。
风生黑山道，星下紫微天。
始愿文经国，俄看武定边。
鬼方尧日远，幕府代云连。
汗马将行矣，卢龙已肃然。
关防驱使节，花月眷离筵。
自忝知音遇，而今感义偏。
泪闻横吹落，心逐去旌悬。
帝念夔能政，时须说济川。
劳还应即尔，朝暮玉墀前。','',''),('quantangshi-12403','奉和中书常舍人晚秋集贤院即事寄徐薛二侍御','錢起','quantangshi','','卷13','文星垂太虚，辞伯综羣书。
彩笔下鸳掖，褒衣来石渠。
典坟探奥旨，造化覩权舆。
述圣鲁宣父，通经汉仲舒。
窗明宜缥带，地肃近丹除。
清昼删诗暇，高秋作赋初。
露盘侵汉耸，宫柳度鵶疎。
静对连云阁，晴闻过阙车。
旧僚云出矣，晚岁复何如。
海峤瞻归路，江城梦直庐。
含毫思两凤，望远寄双鱼。
定笑巴歌拙，还参丽曲余。','',''),('quantangshi-12404','和范郎中宿直中书晓翫清池赠南省同僚两垣遗补','錢起','quantangshi','','卷13','青琐留才子，春池静禁林。
自矜仙岛胜，宛在掖垣深。
引派彤庭里，含虚玉砌阴。
涨来知圣泽，清处见天心。
兰气飘红岸，文星动碧浔。
凤栖长近日，虬卧欲为霖。
席宠虽高位，流谦乃素襟。
焚香春漏尽，假寐晓莺吟。
丹地宜清泚，朝阳复照临。
司言兼逸趣，鼓兴接知音。
六义惊摛藻，三台响掷金。
为怜风水外，落羽此漂沈。','',''),('quantangshi-12405','同程九早入中书','錢起','quantangshi','','卷13','汉家贤相重英奇，蟠木何材也见知。
不意云霄能自致，空惊鵷鹭忽相随。
腊雪初明柏子殿，春光欲上万年枝。
独慙皇鉴明如日，未厌春光向玉墀。','',''),('quantangshi-12406','仲春宴王补阙城东小池','錢起','quantangshi','','卷13','王孙兴至幽寻好，芳草春深景气和。
药院爱随流水入，山斋喜与白云过。
犹嫌巢鹤窥人远，不厌丛花对客多。
醉来倚玉无余事，目送归鸿笑复歌。','',''),('quantangshi-12407','夜宿灵台寺寄郎士元','錢起','quantangshi','','卷13','西日横山含碧空，东方吐月满禅宫。
朝瞻双顶青冥上，夜宿诸天色界中。
石潭倒献莲花水，塔院空闻松柏风。
万里故人能尚尔，知君视听我心同。','',''),('quantangshi-12408','题郎士元半日吴村别业兼呈李长官','錢起','quantangshi','','卷13','半日吴村带晚霞，闲门高柳乱飞鵶。
横云岭外千重树，流水声中一两家。
愁人昨夜相思苦，闰月今年春意赊。
自叹梅生头似雪，却怜潘令县如花。','',''),('quantangshi-12409','猷川雪后送僧粲临还京时避世卧疾','錢起','quantangshi','','卷13','连步青溪几万重，有时共立在孤峯。
斋到盂空餐雪麦，经传金字坐云松。
呻吟独卧猷川水，振锡先闻长乐钟。
回望羣山携手处，离心一一涕无从。','',''),('quantangshi-12410','和李员外扈驾幸温泉宫','錢起','quantangshi','','卷13','未央月晓度疎钟，凤辇时巡出九重。
雪霁山门迎瑞日，云开水殿候飞龙。
经寒不入宫中树，佳气常薰仗外峯。
遥羡枚臯扈仙跸，偏承霄汉渥恩浓。','',''),('quantangshi-12411','长信怨','錢起','quantangshi','','卷13','长信萤来一叶秋，蛾眉泪尽九重幽。
鳷鹊观前明月度，芙蓉阙下绛河流。
鸳衾久别难为梦，凤管遥闻更起愁。
谁分昭阳夜歌舞，君王玉辇正淹留。','',''),('quantangshi-12412','送河南陆少府','錢起','quantangshi','','卷13','云间陆生美且奇，银章朱绶暎金羁。
自料抱材将致远，宁嗟趋府暂牵卑。
东城社日催巢燕，上苑秋声散御梨。
朝夕诏书还柏署，行看飞隼集高枝。','',''),('quantangshi-12413','送李评事赴潭州使幕','錢起','quantangshi','','卷13','湖南远去有余情，苹叶初齐白芷生。
谩说简书催物役，遥知心赏缓王程。
兴过山寺先云到，啸引江帆带月行。
幕下由来贵无事，伫闻谈笑静黎甿。','',''),('quantangshi-12414','送李九贬南阳','錢起','quantangshi','','卷13','玉柱金罍醉不欢，云山驿道向东看。
鸿声断续暮天远，柳影萧疎秋日寒。
霜降幽林霑蕙若，弦惊翰苑失鸳鸾。
秋来回首君门阻，马上应歌行路难。','',''),('quantangshi-12415','送裴頔侍御使蜀','錢起','quantangshi','','卷13','柱史才年四十强，须髯玄发美清扬。
朝天绣服乘恩贵，出使星轺满路光。
锦水繁花添丽藻，峨嵋明月引飞觞。
多才自有云霄望，计日应追鸳鹭行。','',''),('quantangshi-12416','送韦信爱子归觐','錢起','quantangshi','','卷13','离舟解缆到斜晖，春水东流燕北飞。
才子学诗趋露冕，棠花含笑待斑衣。
稍闻江树啼猨近，转觉山林过客稀。
借问还珠盈合浦，何如鲤也入庭闱。','',''),('quantangshi-12417','送兴平王少府游梁','錢起','quantangshi','','卷13','旧识相逢情更亲，攀欢甚少怆离频。
黄绶罢来多远客，青山何处不愁人。
日斜官树闻蝉满，雨过关城见月新。
梁国遗风重词赋，诸侯应念马卿贫。','',''),('quantangshi-12418','送张员外出牧岳州','錢起','quantangshi','','卷13','凤凰衔诏与何人，善政多才宠寇恂。
台上鸳鸾争送远，岳阳云树待行春。
自怜黄阁知音在，不厌彤幨出守频。
应笑冯唐衰且拙，世情相见白头新。','',''),('quantangshi-12419','送孙十尉温县','錢起','quantangshi','','卷13','飞花落絮满河桥，千里伤心送客遥。
不惜芸香染黄绶，惟怜鸿羽下青霄。
云衢有志终骧首，吏道无媒且折腰。
急管繁弦催一醉，颓阳不驻引征镳。','',''),('quantangshi-12420','送钟评事应宏词下第东归','錢起','quantangshi','','卷13','芳岁归人嗟转蓬，含情回首灞陵东。
蛾眉不入秦台镜，鷁羽还惊宋国风。
世事悠扬春梦里，年光寂寞旅愁中。
劝君稍尽离筵酒，千里佳期难再同。','',''),('quantangshi-12421','送严维尉河南','錢起','quantangshi','','卷13','蕙叶青青花乱开，少年趋府下蓬莱。
甘泉未献扬雄赋，吏道何劳贾谊才。
征陌独愁飞盖远，离筵只惜暝钟催。
欲知别后相思处，愿植琼枝向柏台。','',''),('quantangshi-12422','送马员外拜官觐省','錢起','quantangshi','','卷13','二十为郎事汉文，鸳雏骥子自为羣。
笔精已许台中妙，劒术还令世上闻。
归觐屡经槐里月，出师常笑棘门军。
莫言来往朝天远，看取鸣鞘入断云。','',''),('quantangshi-12423','送冷朝阳擢第后归金陵觐省','錢起','quantangshi','','卷13','莱子昼归今始好，潘园景色夏偏浓。
夕阳流水吟诗去，明月青山出竹逢。
兄弟相欢初让果，乡人争贺旧登龙。
佳期少别俄千里，云树愁看过几重。','',''),('quantangshi-12424','九日宴浙江西亭','錢起','quantangshi','','卷13','诗人九日怜芳菊，筵客高斋宴浙江。
渔浦浪花摇素壁，西陵树色入秋窗。
木奴向熟悬金实，桑落新开泻玉缸。
四子醉时争讲习，笑论黄霸旧为邦。','',''),('quantangshi-12425','和王员外雪晴早朝','錢起','quantangshi','','卷13','紫微晴雪带恩光，绕仗偏随鸳鹭行。
长信月留宁避晓，宜春花满不飞香。
独看积素凝清禁，已觉轻寒让太阳。
题柱盛名兼绝唱，风流谁继汉田郎。','',''),('quantangshi-12426','避暑纳凉','錢起','quantangshi','','卷13','木槿花开畏日长，时摇轻扇倚绳牀。
初晴草蔓缘新笋，频雨苔衣染旧墙。
十旬河朔应虚醉，八柱天台好纳凉。
无事始然知静胜，深垂纱帐咏沧浪。','',''),('quantangshi-12427','早夏','錢起','quantangshi','','卷13','楚狂身世恨情多，似病如忧正是魔。
花萼败春多寂寞，叶阴迎夏已清和。
鹂黄好鸟摇深树，细白佳人着紫罗。
军旅阅诗裁不得，可怜风景遣如何。','',''),('quantangshi-12428','题嵩阳焦道士石壁','錢起','quantangshi','','卷13','三峯花畔碧堂悬，锦里真人此得仙。
玉体才飞西蜀雨，霓裳欲向大罗天。
彩云不散烧丹竈，白鹿时藏种玉田。
幸入桃源因去世，方期丹诀一延年。','',''),('quantangshi-12429','题延州圣僧穴','錢起','quantangshi','','卷13','定力无涯不可称，未知何代坐禅僧。
默默山门宵闭月，荧荧石壁昼然灯。
四时树长书经叶，万岁岩悬拄杖藤。
昔日舍身缘救鸽，今时出见有飞鹰。','',''),('quantangshi-12430','乐游原晴望上中书李侍郎','錢起','quantangshi','','卷13','爽气朝来万里清，凭高一望九秋轻。
不知凤沼霖初霁，但觉尧天日转明。
四野山河通远色，千家砧杵共秋声。
遥想青云丞相府，何时开合引书生。','',''),('quantangshi-12431','幽居春暮书怀','錢起','quantangshi','','卷13','自哂鄙夫多野性，贫居数亩半临湍。
溪云杂雨来茅屋，山雀将雏到药栏。
仙箓满牀闲不厌，阴符在箧老羞看。
更怜童子宜春服，花里寻师指杏坛。','',''),('quantangshi-12432','谒许由庙','錢起','quantangshi','','卷13','故向箕山访许由，林泉物外自清幽。
松上挂瓢枝几变，石间洗耳水空流。
绿苔唯见遮三径，青史空传谢九州。
缅想古人增叹惜，飒然云树满岩秋。','',''),('quantangshi-12433','过张成侍御宅','錢起','quantangshi','','卷13','丞相幕中题凤人，文章心事每相亲。
从军谁谓仲宣乐，入室方知颜子贫。
杯里紫茶香代酒，琴中绿水静留宾。
欲知别后相思意，唯愿琼枝入梦频。','',''),('quantangshi-12434','酬考功杨员外见赠佳句','錢起','quantangshi','','卷13','上林谏猎知才薄，尺组承恩愧命牵。
潢潦难滋沧海润，萤光空尽太阳前。
虚名滥接登龙士，野性宁忘种黍田。
相国无私人守朴，何辞老去上皇年。','',''),('quantangshi-12435','寄永嘉王十二','錢起','quantangshi','','卷13','永嘉风景入新年，才子诗成定可怜。
梦里还乡不相见，天涯忆戴复谁传。
花倾晓露垂如泪，莺拂游丝断若弦。
愿得回风吹海雁，飞书一宿到君边。','',''),('quantangshi-12436','七盘岭阻寇闻李端公先到南楚','錢起','quantangshi','','卷13','日暮穷途泪满襟，云天南望羡飞禽。
阮肠暗与孤鸿断，江水遥连别恨深。
明月既能通忆梦，青山何用隔同心。
秦楚眼看成绝国，相思一寄白头吟。','',''),('quantangshi-12437','酬赵给事相寻不遇留赠','錢起','quantangshi','','卷13','谁忆颜生穷巷里，能劳马迹破春苔。
忽看童子扫花处，始愧夕郎题凤来。
斜景适随诗兴尽，好风才送佩声回。
岂无鸡黍期他日，惜此残春阻绿杯。','',''),('quantangshi-12438','山中酬杨补阙见过','錢起','quantangshi','','卷13','日暖风恬种药时，红泉翠壁薜萝垂。
幽溪鹿过苔还静，深树云来鸟不知。
青琐同心多逸兴，春山载酒远相随。
却慙身外牵缨冕，未胜杯前倒接䍦。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-12439','同王錥起居程浩郎中韩翃舍人题安国寺用上人院','錢起','quantangshi','','卷13','慧眼沙门真远公，经行宴坐有儒风。
香缘不绝簪裾会，禅想宁妨藻思通。
曙后炉烟生不灭，晴来堦色并归空。
狂夫入室无余事，唯与天花一笑同。','',''),('quantangshi-12440','寻司勋李郎中不遇','錢起','quantangshi','','卷13','知己知音同舍郎，如何咫尺阻清扬。
每恨蒹葭傍芳树，多惭新燕入华堂。
重花不隔陈蕃榻，修竹能深夫子墙。
唯有早朝趋凤合，朝时怜羽接鸳行。','',''),('quantangshi-12441','赠张南史','錢起','quantangshi','','卷13','紫泥何日到沧州，笑向东阳沈隐侯。
黛色晴峯云外出，縠文江水县前流。
使臣自欲论公道，才子非关厌薄游。
溪畔秋兰虽可佩，知君不得少停舟。','',''),('quantangshi-12442','暇日览旧诗因以题咏','錢起','quantangshi','','卷13','逍遥心地得关关，偶被功名涴我闲。
有寿亦将归象外，无诗兼不恋人间。
何穷默识轻洪范，未丧斯文胜大还。
