加之清一，莫不顺则。
意彼刑法，设以化人。
致使无之，而化益纯。
所谓代刑，以道去杀。
呜呼呜呼，人不斯察。','',''),('quantangshi-12621','二风诗','結','quantangshi','','卷13','国有世谟，仁信勤欤。
王实惛荒，终亡此乎。
焉有力恣谄惑，而不亡其国。
呜呼亡王，忍为此心。
敢正亡王，永为世箴。','',''),('quantangshi-12622','二风诗 一','結','quantangshi','','卷13','嘻乎王家，曾有凶王。
中世失国，岂非骄荒。
复复之难，令则可忘。','',''),('quantangshi-12623','二风诗 二','結','quantangshi','','卷13','嘻乎乱王，王心何思。
暴淫虐惑，无思不为。
生人冤怨，言何极之。','',''),('quantangshi-12624','二风诗 一','結','quantangshi','','卷13','夫为君上兮，慈顺明恕。
可以化人，忍行昏恣。
独乐其身，一徇所欲。','',''),('quantangshi-12625','二风诗 二','結','quantangshi','','卷13','夫为君上兮，兢慎俭约。
可以保身，忍行荒惑。
虐暴于人，前世失国。','',''),('quantangshi-12626','二风诗 一','結','quantangshi','','卷13','贤圣为上兮，必俭约戒身。
鉴察化人，所以保福也。
如何不思，荒恣是为。
上下隔塞，人神怨奰。
敖恶无厌，不畏颠坠。','',''),('quantangshi-12627','二风诗 二','結','quantangshi','','卷13','圣贤为上兮，必用贤正。
黜奸佞之臣，所以长久也。
如何反是，以为乱矣。
宠邪信惑，近佞好谀。
废嫡立庶，忍为祸谟。','',''),('quantangshi-12628','二风诗','結','quantangshi','','卷13','夫何伤兮，伤王乎。
欲何为乎，将蠹枯矣。
无人救乎，蠹枯及矣。
不可救乎，嗟伤王。
自为人君，变为人奴。
为人君者，忘戒乎。','',''),('quantangshi-12629','补乐歌十首 一','結','quantangshi','','卷13','吾人苦兮，水深深。
网罟设兮，水不深。','',''),('quantangshi-12630','补乐歌十首 二','結','quantangshi','','卷13','吾人苦兮，山幽幽。
网罟设兮，山不幽。','',''),('quantangshi-12631','补乐歌十首 一','結','quantangshi','','卷13','猗太帝兮，其智如神。
分草实兮，济我生人。','',''),('quantangshi-12632','补乐歌十首 二','結','quantangshi','','卷13','猗太帝兮，其功如天。
均四时兮，成我丰年。','',''),('quantangshi-12633','补乐歌十首 一','結','quantangshi','','卷13','玄云溶溶兮，垂雨蒙蒙。
类我圣泽兮，涵濡不穷。','',''),('quantangshi-12634','补乐歌十首 二','結','quantangshi','','卷13','玄云漠漠兮，含暎逾光。
类我圣德兮，溥被无方。','',''),('quantangshi-12635','补乐歌十首','結','quantangshi','','卷13','圣德至深兮，奫奫如渊。
生类娭娭兮，孰知其然。','',''),('quantangshi-12636','补乐歌十首','結','quantangshi','','卷13','植植万物兮，滔滔根茎。
五德涵柔兮，沨沨而生。
其生如何兮秞秞，天下皆自我君兮化成。','',''),('quantangshi-12637','补乐歌十首 一','結','quantangshi','','卷13','我有金石兮，击考崇崇。
与汝歌舞兮，上帝之风。
由六合兮，英华沨沨。','',''),('quantangshi-12638','补乐歌十首 二','結','quantangshi','','卷13','我有丝竹兮，韵和泠泠。
与汝歌舞兮，上帝之声。
由六合兮，根底嬴嬴。','',''),('quantangshi-12639','补乐歌十首 一','結','quantangshi','','卷13','元化油油兮，孰知其然。
至德汨汨兮，顺之以先。','',''),('quantangshi-12640','补乐歌十首 二','結','quantangshi','','卷13','元化浘浘兮，孰知其然。
至道泱泱兮，由之以全。','',''),('quantangshi-12641','补乐歌十首 一','結','quantangshi','','卷13','森森羣象兮，日见生成。
欲闻朕初兮，玄封冥冥。','',''),('quantangshi-12642','补乐歌十首 二','結','quantangshi','','卷13','洋洋至化兮，日见深柔。
欲闻大濩兮，大渊油油。','',''),('quantangshi-12643','补乐歌十首 一','結','quantangshi','','卷13','茫茫下土兮，乃生九州。
山有长岑兮，川有深流。','',''),('quantangshi-12644','补乐歌十首 二','結','quantangshi','','卷13','茫茫下土兮，乃均四方。
国有安乂兮，野有封疆。','',''),('quantangshi-12645','补乐歌十首 三','結','quantangshi','','卷13','茫茫下土兮，乃歌万年。
上有茂功兮，下戴仁天。','',''),('quantangshi-12646','补乐歌十首 一','結','quantangshi','','卷13','万姓苦兮，怨且哭。
不有圣人兮，谁护育。','',''),('quantangshi-12647','补乐歌十首 二','結','quantangshi','','卷13','圣人生兮，天下和。
万姓熙熙兮，舞且歌。','',''),('quantangshi-12648','系乐府十二首 思太古','結','quantangshi','','卷13','东南三千里，沅湘为太湖。
湖上山谷深，有人多似愚。
婴孩寄树颠，就水捕鷠鲈。
所欢同鸟兽，身意复何拘。
吾行遍九州，此风皆已无。
吁嗟圣贤敎，不觉久踌蹰。','',''),('quantangshi-12649','系乐府十二首 陇上叹','結','quantangshi','','卷13','援车登陇坂，穷高遂停驾。
延望戎狄乡，巡回复悲咤。
滋移有情敎，草木犹可化。
圣贤礼让风，何不遍西夏。
父子忍猜害，君臣敢欺诈。
所适今若斯，悠悠欲安舍。','',''),('quantangshi-12650','系乐府十二首 颂东夷','結','quantangshi','','卷13','尝闻古天子，朝会张新乐。
金石无全声，宫商乱清浊。
东惊且悲叹，节变何烦数。
始知中国人，耽此亡纯朴。
尔为外方客，何为独能觉。
其音若或在，蹈海吾将学。','',''),('quantangshi-12651','系乐府十二首 贱士吟','結','quantangshi','','卷13','南风发天和，和气天下流。
能使万物荣，不能变羁愁。
为愁亦何尔，自请说此由。
谄竞实多路，苟邪皆共求。
尝闻古君子，指以为深羞。
正方终莫可，江海有沧洲。','',''),('quantangshi-12652','系乐府十二首 唉乃曲','結','quantangshi','','卷13','谁能听唉乃，唉乃感人情。
不恨湘波深，不怨湘水清。
所嗟岂敢道，空羡江月明。
昔闻扣断舟，引钓歌此声。
始歌悲风起，歌竟愁云生。
遗曲今何在，逸为渔父行。','',''),('quantangshi-12653','系乐府十二首 贫妇词','結','quantangshi','','卷13','谁知苦贫夫，家有愁怨妻。
请君听其词，能不为酸凄。
所怜抱中儿，不如山下麑。
空念庭前地，化为人吏蹊。
出门望山泽，回头心复迷。
何时见府主，长跪向之啼。','',''),('quantangshi-12654','系乐府十二首 去乡悲','結','quantangshi','','卷13','踌蹰古塞关，悲歌为谁长。
日行见孤老，羸弱相提将。
闻其呼怨声，闻声问其方。
方言无患苦，岂弃父母乡。
非不见其心，仁惠诚所望。
念之何可说，独立为凄伤。','',''),('quantangshi-12655','系乐府十二首 寿翁兴','結','quantangshi','','卷13','借问多寿翁，何方自修育。
惟云顺所然，忘情学草木。
始知世上术，劳苦化金玉。
不见充所求，空闻肆耽欲。
清和存王母，潜濩无乱黩。
谁正好长生，此言堪佩服。','',''),('quantangshi-12656','系乐府十二首 农臣怨','結','quantangshi','','卷13','农臣何所怨，乃欲干人主。
不识天地心，徒然怨风雨。
将论草木患，欲说昆虫苦。
巡回宫阙傍，其意无由吐。
一朝哭都市，泪尽归田亩。
谣颂若采之，此言当可取。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-12657','系乐府十二首 谢大龟','結','quantangshi','','卷13','客来自江汉，云得双大龟。
且言龟甚灵，问我君何疑。
自昔保方正，顾尝无妄私。
顺和固鄙分，全守真常规。
行之恐不及，此外将何为。
惠恩如可谢，占问敢终辞。','',''),('quantangshi-12658','系乐府十二首 古遗叹','結','quantangshi','','卷13','古昔有遗叹，所叹何所为。
有国遗贤臣，万事为冤悲。
所遗非遗望，所遗非可遗。
所遗非遗用，所遗在遗之。
嗟嗟山海客，全独竟何辞。
心非膏濡类，安得无不遗。','',''),('quantangshi-12659','系乐府十二首 下客谣','結','quantangshi','','卷13','下客无黄金，岂思主人怜。
客言胜黄金，主人然不然。
珠玉成彩翠，绮罗如婵娟。
终恐见斯好，有时去君前。
岂知保忠信，长使令德全。
风声与时茂，歌颂万千年。','',''),('quantangshi-12660','漫歌八曲 故城东','結','quantangshi','','卷13','漫惜故城东，良田野草生。
说向县大夫，大夫劝我耕。
耕者我为先，耕者相次焉。
谁爱故城东，今为近郭田。','',''),('quantangshi-12661','漫歌八曲 西阳城','結','quantangshi','','卷13','江北有大洲，洲上堪力耕。
此中宜五谷，不及西阳城。
城畔多野桑，城中多古荒。
衣食可力求，此外何所望。','',''),('quantangshi-12662','漫歌八曲 大回中','結','quantangshi','','卷13','樊水欲东流，大江又北来。
樊山当其南，此中为大回。
回中鱼好游，回中多钓舟。
漫欲作渔人，终焉无所求。','',''),('quantangshi-12663','漫歌八曲 小回中','結','quantangshi','','卷13','丛石横大江，人言是钓台。
水石相冲激，此中为小回。
回中浪不恶，复在武昌郭。
来客去客船，皆向此中泊。','',''),('quantangshi-12664','漫歌八曲 将牛何处去二首 一','結','quantangshi','','卷13','将牛何处去，耕彼故城东。
相伴有田父，相欢惟牧童。','',''),('quantangshi-12665','漫歌八曲 将牛何处去二首 二','結','quantangshi','','卷13','将牛何处去，耕彼西阳城。
叔闲修农具，直者伴我耕。','',''),('quantangshi-12666','漫歌八曲 将船何处去二首 一','結','quantangshi','','卷13','将船何处去，钓彼大回中。
叔静能鼓桡，正者随弱翁。','',''),('quantangshi-12667','漫歌八曲 将船何处去二首 二','結','quantangshi','','卷13','将船何处去，送客小回南。
有时逢恶客，还家亦少酣。','',''),('quantangshi-12668','引极三首 思元极','結','quantangshi','','卷13','天旷莽兮杳泱茫，气浩浩兮色苍苍。
上何有兮人不测，积清寥兮成元极。
彼元极兮灵且异，思一见兮藐难至。
思不从兮空自伤，心慅𢜱兮意惶懹。
思假翼兮鸾凤，乘长风兮上羾。
揖元气兮本深实，餐至和兮永终日。','',''),('quantangshi-12669','引极三首 望仙府','結','quantangshi','','卷13','山凿落兮眇嵚岑，云溶溶兮木棽棽。
中何有兮人不覩，远欹差兮閟仙府。
彼仙府兮深且幽，望一至兮藐无由。
望不从兮知如何，心混混兮意浑和。
思假足兮虎豹，超阻绝兮凌趠。
诣仙府兮从羽人，饵五灵兮保清真。','',''),('quantangshi-12670','引极三首 怀潜君','結','quantangshi','','卷13','海浩淼兮汩洪溶，流蕴蕴兮涛汹汹。
下何有兮人不闻，深溢漭兮居潜君。
彼潜君兮圣且神，思一见兮藐无因。
思不从兮空踟蹰，心回迷兮意萦纡。
思假鳞兮鲲龙，激沆浪兮奔从。
拜潜君兮索玄宝，佩元符兮轨皇道。','',''),('quantangshi-12671','演兴四首 招太灵','結','quantangshi','','卷13','招太灵兮山之巅，山屹𡵉兮水沦涟。
祠之櫴兮眇何年，木修修兮草鲜鲜。
嗟魑魅兮淫厉，自古昔兮崇祭。
禧太灵兮端清，予愿致夫精诚。
久愵兮㤝㤝，招捃𢹝兮呼风。
风之声兮起飔飔，吹玄云兮散而浮。
望太灵兮俨而安，澹油溶兮都清闲。','',''),('quantangshi-12672','演兴四首 初祀','結','quantangshi','','卷13','山之乳兮葺太祠，木孙为桷兮木母榱。
云缨为𣓍兮愚木栭，洞渊禅兮揭巍巍。
涂木兰兮莳糅蔫，被弱草兮禘礿联。
仡浑洪兮馥阗阗，管化石兮洞刳天。
翘修钐兮掉芜殳，灵巫𧮢兮舞颙干。
荐天𩷨兮酒阳泉，献水芸兮饭霜籼，与太灵兮千万年。','',''),('quantangshi-12673','演兴四首 讼木魅','結','quantangshi','','卷13','登高峰兮俯幽谷，心悴悴兮念羣木。
见樗栲兮相阴覆，怜梫榕兮不丰茂。
见榛梗之森梢，闵枞橎兮合蠹。
槢桡桡兮未坚，椲桹桹兮可屈。
櫁林樽兮不香，拔丰茸兮已实。
岂元化之不均兮，非雨露之偏殊。
谅理性之不等于顺时兮，不如瘗吾心以冥想。
终念此兮不怡，佁予莫识天地之意兮。
愿截恶木之根，倾枭獍之古巢。
取囗童以为薪，割大木使飞焰。
徯枯腐之烧焚，实非吾心之不仁惠也。
岂耻夫善恶之相纷，且欲畚三河之膏壤。
裨济水之清涟，将封灌乎善木。
令橚橚以梴梴，尚畏乎众善之未茂兮。
为众恶之所挑凌，思聚义以为曹。
令敷扶以相胜，取方所以柯如兮。
吾将出于南荒，求寿藤与蟠木。
吾将出于东方，祈有德而来归。
辅神柽与坚香，且忧颙之翩翩。
又愁㺠奔驰，及阴阳兮不和。
恶此土之失时，今神柽兮不茂。
使坚香兮不滋，重嗟惋兮何补。
每齐心以精意，切援祝于神明。
冀感通于天地，犹恐众妖兮木魅。
魍魉兮山精，山误惑于灵心。
经绐于言兮不听，敢引佩以指水，誓吾心兮自明。','',''),('quantangshi-12674','演兴四首 闵岭中','結','quantangshi','','卷13','囗羣山以延想，吾独闵乎岭中。
彼岭中兮何有，有天含之玉峰。
殊閟绝之极颠，上闻产乎翠茸。
欲采之以将寿，眇不知夫所从。
大渊蕴蕴兮绝嶘岌岌，非梯梁以通险。
当无路兮可入，彼猛毒兮曹聚。
必凭托乎阻修，常儗儗兮伺人。
又如何兮不愁，彼妖精兮变怪。
必假见于风雨，常闪闪而伺人。
又如何兮不苦，欲仗仁兮托信。
将径往兮不难，久懹懹以㥄惋。
却迟回而永叹，惧大灵兮不知。
以予心为永惟，若不可乎遂已。
吾终保夫直方，则必蒙皮篥以为矢。
弦毋筱以为弧，化毒铜以为戟。
刺棘竹以为殳，得猛烈之材。
获与之而并驱，且舂刺乎恶毒。
又引射夫妖怪，尽羣类兮使无。
令善仁兮不害，然后采梫榕以驾深。
收枞橞兮梯险，跻予身之飘飘。
承予步之𨁹𨁹，入岭中而登玉峰。
极閟绝而求翠茸，将吾寿兮随所从。
思未得兮马如龙，独翳蔽于山颠。
久低回而愠瘀，空仰讼于上玄。
彼至精兮必应，宁古有而今无。
将与身而皆亡，岂言之而已乎。','',''),('quantangshi-12675','闵荒诗一首','結','quantangshi','','卷13','炀皇嗣君位，隋德滋昏幽。
日作及身祸，以为长世谋。
居常耻前王，不思天子游。
意欲出明堂，便登浮海舟。
令行山川改，功与玄造侔。
河淮可支合，峰𡻮生回沟。
封陨下泽中，作山防逸流。
船𦫃状龙鷁，若负宫阙浮。
荒娱未央极，始到沧海头。
忽见海门山，思作望海楼。
不知新都城，已为征战丘。
当时有遗歌，歌曲太冤愁。
四海非天狱，何为非天囚。
天囚正凶忍，为我万姓讐。
人将引天钐，人将持天锼。
所欲充其心，相与绝悲忧。
自得隋人歌，每为隋君羞。
欲歌当阳春，似觉天下秋。
更歌曲未终，如有怨气浮。
奈何昏王心，不觉此怨尤。
遂令一夫唱，四海欣提矛。
吾闻古贤君，其道常静柔。
慈惠恐不足，端和忘所求。
嗟嗟有隋氏，惛惛谁与俦。','',''),('quantangshi-12676','忝官引','結','quantangshi','','卷13','天下昔无事，僻居养愚钝。
山野性所安，熙然自全顺。
忽逢暴兵起，闾巷见军阵。
将家瀛海滨，自弃同刍粪。
往在干元初，圣人启休运。
公车诣魏阙，天子垂清问。
敢诵王者箴，亦献当时论。
朝廷爱方直，明主嘉忠信。
屡授不次官，曾与专征印。
兵家未曾学，荣利非所徇。
偶得凶丑降，功劳愧方寸。
尔来将四岁，慙耻言可尽。
请取冤者辞，为吾忝官引。
冤辞何者苦，万邑余灰烬。
冤辞何者悲，生人尽锋刃。
冤辞何者甚，力役遇劳困。
冤辞何者深，孤弱亦哀恨。
无谋救冤者，禄位安可近。
而可爱轩裳，其心又干进。
此言非所戒，此言敢贻训。
实欲辞无能，归耕守吾分。','',''),('quantangshi-12677','舂陵行','結','quantangshi','','卷13','军国多所需，切责在有司。
有司临郡县，刑法竞欲施。
供给岂不忧，徴敛又可悲。
州小经乱亡，遗人实困疲。
大乡无十家，大族命单羸。
朝餐是草根，暮食仍木皮。
出言气欲绝，意速行步迟。
追呼尚不忍，况乃鞭扑之。
邮亭传急符，来往迹相追。
更无宽大恩，但有迫促期。
欲令鬻儿女，言发恐乱随。
悉使索其家，而又无生资。
听彼道路言，怨伤谁复知。
去冬山贼来，杀夺几无遗。
所愿见王官，抚养以惠慈。
奈何重驱逐，不使存活为。
安人天子命，符节我所持。
州县忽乱亡，得罪复是谁。
逋缓违诏令，蒙责固其宜。
前贤重守分，恶以祸福移。
亦云贵守官，不爱能适时。
顾惟孱弱者，正直当不亏。
何人采国风，吾欲献此辞。','',''),('quantangshi-12678','贼退示官吏','結','quantangshi','','卷13','昔岁逢太平，山林二十年。
泉源在庭户，洞壑当门前。
井税有常期，日[晏]犹得眠。
忽然遭世变，数岁亲戎旃。
今来典斯郡，山夷又纷然。
城小贼不屠，人贫伤可怜。
是以陷隣境，此州独见全。
使臣将王命，岂不如贼焉。
今彼徴敛者，迫之如火煎。
谁能绝人命，以作时世贤。
思欲委符节，引竿自刺船。
将家就鱼麦，归老江湖边。','',''),('quantangshi-12679','寄源休','結','quantangshi','','卷13','天下未偃兵，儒生预戎事。
功劳安可问，且有忝官累。
昔常以荒浪，不敢学为吏。
况当在兵家，言之岂容易。
忽然向三岭，境外为偏帅。
时多尚矫诈，进退多欺贰。
纵有一直方，则上似奸智。
谁为明信者，能辨此劳畏。','',''),('quantangshi-12680','雪中怀孟武昌','結','quantangshi','','卷13','冬来三度雪，农者欢岁稔。
我麦根已濡，各得在仓廪。
天寒未能起，孺子惊人寝。
云有山客来，篮中见冬簟。
烧柴为温酒，煮鳜为作沈。
客亦爱杯尊，思君共杯饮。
所嗟山路闲，时节寒又甚。
不能苦相邀，兴尽还就枕。','',''),('quantangshi-12681','与党评事','結','quantangshi','','卷13','自顾无功劳，一岁官再迁。
局身班次中，常窃愧耻焉。
加以久荒浪，惛愚性颇全。
未知在冠冕，不合无拘牵。
勤强所不及，于人或未然。
岂忘惠君子，恕之识见偏。
且欲因我心，顺为理化先。
彼云万物情，有愿随所便。
爱君得自遂，令我空渊禅。','',''),('quantangshi-12682','与党侍御','結','quantangshi','','卷13','众坐吾独欢，或问欢为谁。
高人党茂宗，复来官宪司。
昔吾顺元和，与世行自遗。
茂宗正作吏，日有趋走疲。
及吾污冠冕，茂宗方矫时。
诮吾顺让者，乃是干进资。
今将问茂宗，茂宗欲何辞。
若云吾无心，此来复何为。
若云吾有羞，于此还见嗤。
谁言万类心，闲之不可窥。
吾欲喻茂宗，茂宗宜听之。
长辕有修辙，驭者令尔驰。
山谷安可怨，筋力当自悲。
嗟嗟党茂宗，可为识者规。','',''),('quantangshi-12683','与瀼溪邻里','結','quantangshi','','卷13','昔年苦逆乱，举族来南奔。
日行几十里，爱君此山村。
峰谷呀回映，谁家无泉源。
修竹多夹路，扁舟皆到门。
瀼溪中曲滨，其阳有闲园。
邻里昔赠我，许之及子孙。
我尝有匮乏，邻里能相分。
我尝有不安，邻里能相存。
斯人转贫弱，力役非无冤。
终以瀼滨讼，无令天下论。','',''),('quantangshi-12684','招孟武昌','結','quantangshi','','卷13','风霜枯万物，退谷如春时。
穷冬涸江海，杯湖澄清漪。
湖尽到谷口，单船近堦墀。
湖中更何好，坐见大江水。
欹石为水涯，半山在湖里。
谷口更何好，绝壑流寒泉。
松桂荫茅舍，白云生坐边。
武昌不干进，武昌人不厌。
退谷正可游，杯湖任来泛。
湖上有水鸟，见人不飞鸣。
谷口有山兽，往往随人行。
莫将车马来，令我鸟兽惊。','',''),('quantangshi-12685','招陶别驾家阳华作','結','quantangshi','','卷13','海内厌兵革，骚骚十二年。
阳华洞中人，似不知乱焉。
谁能家此地，终老可自全。
草堂背岩洞，几峰轩户前。
清渠匝庭堂，出门仍灌田。
半崖盘石径，高亭临极巅。
引望见何处，迤逶陇北川。
杉松几万株，苍苍满前山。
岩高瞹华阳，飞溜何潺潺。
洞深迷远近，但觉多洄渊。
昼游兴未尽，日暮不欲眠。
探烛饮洞中，醉昏漱寒泉。
始知天下心，耽爱各有偏。
陶家世高逸，公忍不独然。
无或毕婚嫁，竟为俗务牵。','',''),('quantangshi-12686','游石溪示学者','結','quantangshi','','卷13','小溪在城下，形胜堪赏爱。
尤宜春水满，水石更殊怪。
长山势回合，井邑相萦带。
石林绕舜祠，西南正相对。
阶庭无争讼，郊境罢守卫。
时时溪上来，劝引辞学辈。
今谁不务武，儒雅道将废。
岂忘二三子，旦夕相勉励。','',''),('quantangshi-12687','游潓泉示泉上学者','結','quantangshi','','卷13','顾吾漫浪久，不欲有所拘。
每到潓泉上，情性可安舒。
草堂在山曲，澄澜涵阶除。
松竹阴幽径，清源涌坐隅。
筑塘列圃畦，引流灌时蔬。
复在郊郭外，正堪静者居。
惬心则自适，喜尚人或殊。
此中若可安，不服铜虎符。','',''),('quantangshi-12688','喻瀼溪乡旧游','結','quantangshi','','卷13','往年在瀼滨，瀼人皆忘情。
今来游瀼乡，瀼人见我惊。
我心与瀼人，岂有辱与荣。
瀼人异其心，应为我冠缨。
昔贤恶如此，所以辞公卿。
贫穷老乡里，自休还力耕。
况曾经逆乱，日厌闻战争。
尤爱一溪水，而能存让名。
终当来其滨，饮啄全此生。','',''),('quantangshi-12689','喻旧部曲','結','quantangshi','','卷13','漫游樊水阴，忽见旧部曲。
尚言军中好，犹望有所属。
故令争者心，至死终不足。
与之一杯酒，喻使烧戎服。
兵兴向十年，所见堪叹哭。
相逢是遗人，当合识荣辱。
劝汝学全生，随我畲退谷。','',''),('quantangshi-12690','喻常吾直','結','quantangshi','','卷13','山泽多饥人，闾里多坏屋。
战争且未息，徴敛何时足。
不能救人患，不合食天粟。
何况假一官，而苟求其禄。
近年更长吏，数月未为速。
来者罢而官，岂得不为辱。
劝为辞府主，从我游退谷。
谷中有寒泉，为尔洗尘服。','',''),('quantangshi-12691','漫问相里黄州','結','quantangshi','','卷13','东邻有渔父，西邻有山僧。
各问其性情，变之俱不能。
公为二千石，我为山海客。
志业岂不同，今已殊名迹。
相里不相类，相友且相异。
何况天下人，而欲同其意。
人意苟不同，分寸不相容。
漫问轩裳客，何如耕钓翁。','',''),('quantangshi-12692','酬裴云客','結','quantangshi','','卷13','自厌久荒浪，于时无所任。
耕钓以为事，来家樊水阴。
甚醉或漫歌，甚闲亦漫吟。
不知愚僻意，称得云客心。
云客方持斧，与人正相临。
符印随坐起，守位常森森。
纵能有相招，岂暇来山林。','',''),('quantangshi-12693','酬孟武昌苦雪','結','quantangshi','','卷13','积[雪]闲山路，有人到庭前。
云是孟武昌，令献苦雪篇。
长吟未及终，不觉为凄然。
古之贤达者，与世竟何异。
不能救时患，讽谕以全意。
知公惜春物，岂非爱时和。
知公苦阴雪，伤彼灾患多。
奸凶正驱驰，不合问君子。
林莺与野兽，无乃怨于此。
兵兴向九岁，稼穑谁能忧。
何时不发卒，何日不杀牛。
耕者日已少，耕牛日已希。
皇天复何忍，更又恐毙之。
自经危乱来，触物堪伤叹。
见君问我意，只益胸中乱。
山禽饥不飞，山木冻皆折。
悬泉化为冰，寒水近不热。
出门望天地，天地皆昏昏。
时见双峰下，雪中生白云。','',''),('quantangshi-12694','漫酬贾沔州','結','quantangshi','','卷13','往年壮心在，尝欲济时难。
奉诏举州兵，令得诛暴叛。
上将屡颠覆，偏师尝救乱。
未曾弛戈甲，终日领簿案。
出入四五年，忧劳忘昏旦。
无谋静凶丑，自觉愚且愞。
岂欲皂枥中，争食麧与藖。
去年辞职事，所惧贻忧患。
天子许安亲，官又得闲散。
自家樊水上，性情尤荒慢。
云山与水木，似不憎吾漫。
以兹忘时世，日益无畏惮。
漫醉人不嗔，漫眠人不唤。
漫游无远近，漫乐无早晏。
漫中漫亦忘，名利谁能算。
闻君劝我意，为君一长叹。
人谁年八十，我已过其半。
家中孤弱子，长子未及冠。
且为儿童主，种药老溪涧。','',''),('quantangshi-12695','送孟校书往南海','結','quantangshi','','卷13','吾闻近南海，乃是魑魅乡。
忽见孟夫子，欢然游此方。
忽喜海风来，海帆又欲张。
漂漂随所去，不念归路长。
君有失母儿，爱之似阿阳。
始解随人行，不欲离君傍。
相劝早旋归，此言慎勿忘。','',''),('quantangshi-12696','别何员外','結','quantangshi','','卷13','谁能守清躅，谁能嗣世儒。
吾见何君饶，为人有是夫。
黜官二十年，未曾暂崎岖。
终不病贫贱，寥寥无所拘。
忽然逢知己，数月领官符。
犹是尚书郎，收赋来江湖。
人皆悉苍生，随意极所须。
比盗无兵甲，似偷又不如。
公能独宽大，使之力自输。
吾欲探时谣，为公伏奏书。
但恐抵忌讳，未知肯听无。
不然且相送，醉欢于坐隅。','',''),('quantangshi-12697','宴湖上亭作','結','quantangshi','','卷13','广亭盖小湖，湖亭实清旷。
轩窗幽水石，怪异尤难状。
石尊能寒酒，寒水宜初涨。
岸曲坐客稀，杯浮上摇漾。
远水入帘幕，淅[沥]吹酒舫。
欲去未回时，飘飘正堪望。
酣兴思共醉，促酒更相向。
舫去若惊凫，溶瀛满湖浪。
朝来暮忘返，暮归独惆怅。
谁肯爱林泉，从吾老湖上。','',''),('quantangshi-12698','夜宴石鱼湖作','結','quantangshi','','卷13','风霜虽惨然，出游熙天正。
登临日暮归，置酒湖上亭。
高烛照泉深，光华溢轩楹。
如见海底日，曈曈始欲生。
夜寒闭窗户，石溜何清泠。
若在深洞中，半崖闻水声。
醉人疑舫影，呼指递相惊。
何故有双鱼，随吾酒舫行。
醉昏能诞语，劝醉能忘情。
坐无拘忌人，勿限醉与醒。','',''),('quantangshi-12699','刘侍御月夜宴会','結','quantangshi','','卷13','我从苍梧来，将耕旧山田。
踟蹰为故人，且复停归船。
日夕得相从，转觉和乐全。
愚爱凉风来，明月正满天。
河汉望不见，几星犹粲然。
中夜兴欲酣，改坐临清川。
未醉恐天旦，更歌促繁弦。
欢娱不可逢，请君莫言旋。','',''),('quantangshi-12700','樊上漫作','結','quantangshi','','卷13','漫家郎亭下，复在樊水边。
去郭五六里，扁舟到门前。
山竹绕茅舍，庭中有寒泉。
西边双石峰，引望堪忘年。
四邻皆渔父，近渚多闲田。
且欲学耕钓，于斯求老焉。','',''),('quantangshi-12701','登殊亭作','結','quantangshi','','卷13','时节方大暑，试来登殊亭。
凭轩未及息，忽若秋气生。
主人既多闲，有酒共我倾。
坐中不相异，岂恨醉与醒。
漫歌无人听，浪语无人惊。
时复一回望，心目出四溟。
谁能守缨佩，日与灾患并。
请君诵此意，令彼惑者听。','',''),('quantangshi-12702','石鱼湖上作','結','quantangshi','','卷13','吾爱石鱼湖，石鱼在湖里。
鱼背有酒樽，绕鱼是湖水。
儿童坐小舫，载酒胜一杯。
座中令酒舫，空去复满来。
湖岸多欹石，石下流寒泉。
醉中一盥漱，快意无比焉。
金玉吾不须，轩冕吾不爱。
且欲坐湖畔，石鱼长相对。','',''),('quantangshi-12703','引东泉作','結','quantangshi','','卷13','东泉人未知，在我左山东。
引之傍山来，垂流落庭中。
宿雾含朝光，掩映如残虹。
有时散成雨，飘洒随清风。
众源发渊窦，殊怪皆不同。
此流又高悬，{汸番}{汸番}在长空。
山林何处无，兹地不可逢。
吾欲解缨佩，便为泉上翁。','',''),('quantangshi-12704','登白云亭','結','quantangshi','','卷13','出门见南山，喜逐松径行。
穷高欲极远，始到白云亭。
长山绕井邑，登望宜新晴。
州渚曲湘水，萦回随郡城。
九疑千万峰，嵺嵺天外青。
烟云无远近，皆傍林岭生。
俯视松竹间，石水何幽清。
涵映满轩户，娟娟如镜明。
何人病惛浓，积醉且未醒。
与我一登临，为君安性情。','',''),('quantangshi-12705','潓阳亭作','結','quantangshi','','卷13','问吾常宴息，泉上何处好。
独有潓阳亭，令人可终老。
前轩临潓泉，凭几漱清流。
外物自相扰，渊渊还复休。
有时出东户，更欲檐下坐。
非我意不行，石渠能留我。
峰石若鳞次，欹垂复旋回。
为我引潓泉，泠泠檐下来。
天寒宜泉温，泉寒宜天暑。
谁到潓阳亭，其心肯思去。','',''),('quantangshi-12706','登九疑第二峰','結','quantangshi','','卷13','九疑第二峰，其上有仙坛。
杉松映飞泉，苍苍在云端。
何人居此处，云是鲁女冠。
不知几百岁，燕坐饵金丹。
相传羽化时，云鹤满峰峦。
妇中有高人，相望空长叹。','',''),('quantangshi-12707','题孟中丞茅阁','結','quantangshi','','卷13','小山为郡城，随水能萦纡。
亭亭最高处，今是西南隅。
杉大老犹在，苍苍数十株。
垂阴满城上，枝叶何扶疎。
乃知四海中，遗事谁谓无。
及观茅阁成，始觉形胜殊。
凭轩望熊湘，云榭连苍梧。
天下正炎热，此然冰雪俱。
客有在中坐，颂歌复何如。
公欲举遗材，如此佳木欤。
公方庇苍生，又如斯阁乎。
请达谣颂声，愿公且踟蹰。','',''),('quantangshi-12708','窊尊诗','結','quantangshi','','卷13','巉巉小山石，数峰对窊亭。
窊石堪为樽，状类不可名。
巡回数尺间，如见小蓬瀛。
尊中酒初涨，始有岛屿生。
岂无日观峰，直下临沧溟。
爱之不觉醉，醉卧还自醒。
醒醉在尊畔，始为吾性情。
若以形胜论，坐隅临郡城。
平湖近阶砌，近山复青青。
异木几十株，林条冒檐楹。
盘根满石上，皆作龙蛇形。
酒堂贮酿器，户牖皆罂瓶。
此尊可常满，谁是陶渊明。','',''),('quantangshi-12709','朝阳岩下歌','結','quantangshi','','卷13','朝阳岩下湘水深，朝阳洞口寒泉清。
零陵城郭夹湘岸，岩洞幽奇带郡城。
荒芜自古人不见，零陵徒有先贤传。
水石为娱安可羡，长歌一曲留相劝。','',''),('quantangshi-12710','无为洞口作','結','quantangshi','','卷13','无为洞口春水满，无为洞傍春云白。
爱此踟蹰不能去，令人悔作衣冠客。
洞傍山僧皆学禅，无求无欲亦忘年。
欲问其心不能问，我到山中得无闷。','',''),('quantangshi-12711','宿无为观','結','quantangshi','','卷13','九疑山深几千里，峰谷崎岖人不到。
山中旧有仙姥家，十里飞泉遶丹竈。
如今道士三四人，茹芝炼玉学轻身。
霓裳羽盖傍临壑，飘颻似欲来云鹤。','',''),('quantangshi-12712','宿洄溪翁宅','結','quantangshi','','卷13','长松万株遶茅舍，怪石寒泉近岩下。
老翁八十犹能行，将领儿孙行拾稼。
吾羡老翁居处幽，吾爱老翁无所求。
时俗是非何足道，得似老翁吾即休。','',''),('quantangshi-12713','说洄溪招退者','結','quantangshi','','卷13','长松亭亭满四山，山间乳窦流清泉。
洄溪正在此山里，乳水松膏常灌田。
松膏乳水田肥良，稻苗如蒲米粒长。
糜色如珈玉液酒，酒熟犹闻松节香。
溪边老翁年几许，长男头白孙嫁女。
问言只食松田米，无药无方向人语。
浯溪石下多泉源，盛暑大寒冬大温。
屠苏宜在水中石，洄溪一曲自当门。
吾今欲作洄溪翁，谁能住我舍西东。
勿惮山深与地僻，罗浮尚有葛仙翁。','',''),('quantangshi-12714','宿丹崖翁宅','結','quantangshi','','卷13','扁舟欲到泷口湍，春水湍泷上水难。
投竿来泊丹崖下，得与崖翁尽一欢。
丹崖之亭当石颠，破竹半山引寒泉。
泉流掩映在木杪，有若白鸟飞林间。
往往随风作雾雨，湿人巾履满庭前。
丹崖翁，爱丹崖，弃官几年崖下家。
儿孙棹船抱酒瓮，醉里长歌挥钓车。
吾将求退与翁游，学翁歌醉在鱼舟。
官吏随人往未得，却望丹崖慙复羞。','',''),('quantangshi-12715','石鱼湖上醉歌','結','quantangshi','','卷13','石鱼湖，似洞庭，夏水欲满君山青。
山为樽，水为沼，酒徒历历坐洲岛。
长风连日作大浪，不能废人运酒舫。
我持长瓢坐巴丘，酌饮四坐以散愁。','',''),('quantangshi-12716','橘井','結','quantangshi','','卷13','灵橘无根井有泉，世间如梦又千年。
乡园不见重归鹤，姓字今为第几仙。
风[泠]露坛人悄悄，地闲荒径草绵绵。
如何蹑得苏君迹，白日霓旌拥上天。','',''),('quantangshi-12717','石宫四咏 一','結','quantangshi','','卷13','石宫春云白，白云宜苍苔。
拂云践石径，俗士谁能来。','',''),('quantangshi-12718','石宫四咏 二','結','quantangshi','','卷13','石宫夏水寒，寒水宜高林。
远风吹萝蔓，野客熙清阴。','',''),('quantangshi-12719','石宫四咏 三','結','quantangshi','','卷13','石宫秋气清，清气宜山谷。
落叶逐霜风，幽人爱松竹。','',''),('quantangshi-12720','石宫四咏 四','結','quantangshi','','卷13','石宫冬日暖，暖日宜温泉。
晨光静水雾，逸者犹安眠。','',''),('quantangshi-12721','唉乃曲五首 一','結','quantangshi','','卷13','偶存名迹在人间，顺俗与时未安闲。
来谒大官兼问政，扁舟却入九疑山。','',''),('quantangshi-12722','唉乃曲五首 二','結','quantangshi','','卷13','湘江二月春水平，满月和风宜夜行。
唱桡欲过平阳戍，守吏相呼问姓名。','',''),('quantangshi-12723','唉乃曲五首 三','結','quantangshi','','卷13','千里枫林烟雨深，无朝无暮有猨吟。
停桡静听曲中意，好是云山韶濩音。','',''),('quantangshi-12724','唉乃曲五首 四','結','quantangshi','','卷13','零陵郡北湘水东，浯溪形胜满湘中。
溪口石颠堪自逸，谁能相伴作渔翁。','',''),('quantangshi-12725','唉乃曲五首 五','結','quantangshi','','卷13','下泷船似入深渊，上泷船似欲升天。
泷南始到九疑郡，应绝高人乘兴船。','',''),('quantangshi-12726','郢城西楼吟','張繼','quantangshi','','卷13','连山尽塞水萦回，山上戍门临水开。
珠帘直下一百丈，日暖游鳞自相向。
昔人爱险闭层城，今人复爱闲江清。
沙洲枫岸无来客，草绿花开山鸟鸣。','',''),('quantangshi-12727','登丹阳楼','張繼','quantangshi','','卷13','寒臯那可望，旅客又初还。
迢遰高楼上，萧疎凉野间。
暮晴依远水，秋兴属连山。
浮客时相见，霜雕朱翠颜。','',''),('quantangshi-12728','春夜皇甫冉宅欢宴','張繼','quantangshi','','卷13','流落时相见，悲欢共此情。
兴因尊酒洽，愁为故人轻。
暗滴花茎露，斜晖月过城。
那知横吹笛，江外作边声。','',''),('quantangshi-12729','会稽秋晚奉呈于太守','張繼','quantangshi','','卷13','寂寂讼庭幽，森森戟户秋。
山光隐危堞，湖色上高楼。
禹穴探书罢，天台作赋游。
云浮将越客，岁晚共淹留。','',''),('quantangshi-12730','题严陵钓台','張繼','quantangshi','','卷13','旧隐人如在，清风亦似秋。
客星沈夜壑，钓石俯春流。
鸟向乔枝聚，鱼依浅濑游。
古来芳饵下，谁是不吞钩。','',''),('quantangshi-12731','清明日自西午桥至瓜岩村有怀','張繼','quantangshi','','卷13','晚霁龙门雨，春生汝穴风。
鸟啼官路静，花发毁垣空。
鸣玉慙时辈，垂丝学老翁。
旧游人不见，惆怅洛城东。','',''),('quantangshi-12732','洛阳作','張繼','quantangshi','','卷13','洛阳天子县，金谷石崇乡。
草色侵官道，花枝出苑墙。
书成休逐客，赋罢遂为郎。
贫贱非吾事，西游思自强。','',''),('quantangshi-12733','晚次淮阳','張繼','quantangshi','','卷13','微凉风叶下，楚俗转清闲。
候馆临秋水，郊扉掩暮山。
月明潮渐近，露湿雁初还。
浮客了无定，萍流淮海间。','',''),('quantangshi-12734','送窦十九判官使江南','張繼','quantangshi','','卷13','游客淹星纪，裁诗炼土风。
今看乘传去，那与问津同。
南郡迎徐子，临川谒谢公。
思归一惆怅，于越古亭中。','',''),('quantangshi-12735','江上送客游庐山','張繼','quantangshi','','卷13','楚客自相送，霑裳春水边。
晚来风信好，并发上江船。
花映新林岸，云开瀑布泉。
惬心应在此，佳句向谁传。','',''),('quantangshi-12736','酬张二十员外前国子博士窦叔向','張繼','quantangshi','','卷13','故交日零落，心赏寄何人。
幸与冯唐遇，心同迹复亲。
语言未终夕，离别又伤春。
结念湓城下，闻猨诗兴新。','',''),('quantangshi-12737','会稽郡楼雪霁','張繼','quantangshi','','卷13','江城昨夜雪如花，郢客登楼齐望华。
夏禹坛前仍聚玉，西施浦上更飞沙。
帘栊向晚寒风度，睥睨初晴落景斜。
数处微明销不尽，湖山清映越人家。','',''),('quantangshi-12738','冯翊西楼','張繼','quantangshi','','卷13','城上西楼倚暮天，楼中归望正凄然。
近郭乱山横古渡，野庄乔木带新烟。
北风吹雁声能苦，远客辞家月再圆。
陶令好文常对酒，相招那惜醉为眠。','',''),('quantangshi-12739','送邹判官往陈留','張繼','quantangshi','','卷13','齐宋伤心地，频年此用兵。
女停襄邑杼，农废汶阳耕。
国使乘轺去，诸侯拥节迎。
深仁荷君子，薄赋恤黎甿。
火燎原犹热，波摇海未平。
应将否泰理，一问鲁诸生。','',''),('quantangshi-12740','酬李书记校书越城秋夜见赠','張繼','quantangshi','','卷13','东越秋城夜，西人白发年。
寒城警刁斗，孤愤抱龙泉。
凤辇栖岐下，鲸波鬬洛川。
量空海陵粟，赐乏水衡钱。
投阁嗤扬子，飞书代鲁连。
苍苍不可问，余亦赋思玄。','',''),('quantangshi-12741','感怀','張繼','quantangshi','','卷13','调与时人背，心将静者论。
终年帝城里，不识五侯门。','',''),('quantangshi-12742','长相思','張繼','quantangshi','','卷13','辽阳望河县，白首无由见。
海上珊瑚枝，年年寄春燕。','',''),('quantangshi-12743','奉寄皇甫补阙','張繼','quantangshi','','卷13','京口情人别久，扬州估客来疎。
潮至浔阳回去，相思无处通书。','',''),('quantangshi-12744','枫桥夜泊','張繼','quantangshi','','卷13','月落乌啼霜满天，江枫渔父对愁眠。
姑苏城外寒山寺，夜半钟声到客船。','',''),('quantangshi-12745','阊门即事','張繼','quantangshi','','卷13','耕夫召募逐楼船，春草青青万顷田。
试上吴门窥郡郭，清明几处有新烟。','',''),('quantangshi-12746','安公房问法','張繼','quantangshi','','卷13','流年一日复一日，世事何时是了时。
试向东林问禅伯，遣将心地学琉璃。','',''),('quantangshi-12747','上清词','張繼','quantangshi','','卷13','紫阳宫女捧丹砂，王母令过汉帝家。
春风不肯停仙驭，却向蓬莱看杏花。','',''),('quantangshi-12748','送顾况泗上觐叔父','張繼','quantangshi','','卷13','吴乡岁贡足嘉宾，后进之中见此人。
别业更临洙泗上，拟将书卷对残春。','',''),('quantangshi-12749','留别','張繼','quantangshi','','卷13','何事千年遇圣君，坐令双鬓老江云。
南行更入山深浅，岐路悠悠水自分。','',''),('quantangshi-12750','送张中丞归使幕','張繼','quantangshi','','卷13','独受主恩归，当朝似者稀。
玉壶分御酒，金殿赐春衣。
拂席流莺醉，鸣鞭骏马肥。
满台簪白笔，捧手恋清辉。','',''),('quantangshi-12751','华州夜宴庾侍御宅','張繼','quantangshi','','卷13','世故他年别，心期此夜同。
千峰孤烛外，片雨一更中。
酒客逢山简，诗人得谢公。
自怜驱匹马，拂曙向关东。','',''),('quantangshi-12752','赠章八元','張繼','quantangshi','','卷13','相见谈经史，江楼坐夜阑。
风声吹户响，灯影照人寒。
俗薄交游尽，时危出处难。
衰年逢二妙，亦得闷怀宽。','',''),('quantangshi-12753','城西虎跑寺','張繼','quantangshi','','卷13','石势虎蹲伏，山形龙屈盘。
寺开梁殿阁，坟掩晋衣冠。
出涧泉声细，斜阳塔影寒。
近城多囗囗，栖息此中安。','',''),('quantangshi-12754','禇主簿宅会毕庶子钱员外郎使君','張繼','quantangshi','','卷13','开瓮腊酒熟，主人心赏同。
斜阳疎竹上，残雪乱山中。
更喜宣城印，朝廷与谢公。','',''),('quantangshi-12755','奉送王相公赴幽州','張繼','quantangshi','','卷13','黄阁开帏幄，丹墀拜冕旒。
位高汤左相，权总汉诸侯。
不改周南化，仍分赵北忧。
双旌过易水，千骑入幽州。
塞草连天幕，边风动地愁。
无因随远道，结束佩吴钩。','',''),('quantangshi-12756','重经巴丘','張繼','quantangshi','','卷13','昔年高接李膺欢，日泛仙舟醉碧澜。
诗句乱随青草落，酒肠俱逐洞庭宽。
浮生聚散云相似，往事冥微梦一般。
今日片帆城下去，秋风回首泪阑干。','',''),('quantangshi-12757','九日巴丘杨公台上宴集','張繼','quantangshi','','卷13','凄凄霜日上高台，水国秋凉客思哀。
万叠银山寒浪起，一行斜字早鸿来。
谁家捣练孤城暮，何处题衣远信回。
江汉路长身不定，菊花三笑旅怀开。','',''),('quantangshi-12758','游灵岩','張繼','quantangshi','','卷13','灵岩有路入烟霞，台殿高低释子家。
风满回廊飘坠叶，水流绝涧泛秋花。
青松阅世风霜古，翠竹题诗岁月赊。
谁谓无生真可学，山中亦自有年华。','',''),('quantangshi-12759','河间献王墓','張繼','quantangshi','','卷13','汉家宗室独称贤，遗事闲中见旧编。
偶过河间寻往迹，却怜荒冢带寒烟。
频求千古书连帙，独对三雍策几篇。
雅乐未兴人已逝，雄歌依旧大风传。','',''),('quantangshi-12760','秋日道中','張繼','quantangshi','','卷13','齐鲁西风草树秋，川原高下过东州。
道边白鹤来华表，陌上苍麟卧古丘。
九曲半应非禹迹，三山何处是仙洲。
径行俯仰成今古，却忆当年赋远游。','',''),('quantangshi-12761','华清宫','張繼','quantangshi','','卷13','天宝承平奈乐何，华清宫殿郁嵯峩。
朝元阁峻临秦岭，羯鼓楼高俯渭河。
玉树长飘云外曲，霓裳闲舞月中歌。
只今惟有温泉水，呜咽声中感慨多。','',''),('quantangshi-12762','春申君祠','張繼','quantangshi','','卷13','春申祠宇空山里，古柏阴阴石泉水。
日暮江南无主人，弥令过客思公子。
萧条寒景傍山村，寂寞谁知楚相尊。
当时珠履三千客，赵使怀惭不敢言。','',''),('quantangshi-12763','人日代客子是日立春','張繼','quantangshi','','卷13','人日兼春日，长怀复短怀。
遥知双彩胜，并在一金钗。','',''),('quantangshi-12764','寄郑员外','張繼','quantangshi','','卷13','经月愁闻雨，新年苦忆君。
何时共登眺，整屐待晴云。','',''),('quantangshi-12765','饮李十二宅','張繼','quantangshi','','卷13','重门敞春夕，灯烛霭余辉。
醉我百尊酒，留连夜未归。','',''),('quantangshi-12766','山家','張繼','quantangshi','','卷13','板桥人渡泉声，茅檐日午鸡鸣。
莫嗔焙茶烟暗，却喜晒谷天晴。','',''),('quantangshi-12767','归山','張繼','quantangshi','','卷13','心事数茎白发，生涯一片青山。
空林有雪相待，古道无人独还。','',''),('quantangshi-12768','金谷园','張繼','quantangshi','','卷13','彩楼歌馆正融融，一骑星飞锦帐空。
老尽名花春不管，年年啼鸟怨东风。','',''),('quantangshi-12769','邮亭','張繼','quantangshi','','卷13','云淡山横日欲斜，邮亭下马对残花。
自从身逐征西府，每到开时不在家。','',''),('quantangshi-12770','宿白马寺','張繼','quantangshi','','卷13','白马驮经事已空，断碑残刹见遗踪。
萧萧茅屋秋风起，一夜雨声羁思浓。','',''),('quantangshi-12771','明德宫','張繼','quantangshi','','卷13','碧瓦朱楹白昼闲，金衣宝扇晓风寒。
摩云观阁高如许，长对河流出断山。','',''),('quantangshi-12772','读峄山碑','張繼','quantangshi','','卷13','六国平来四海家，相君当代擅才华。
谁知颂德山头石，却与他人戒后车。','',''),('quantangshi-12773','句','張繼','quantangshi','','卷13','汉月经时掩，胡尘与岁深。','',''),('quantangshi-12774','令狐员外宅宴寄中丞','韓翃','quantangshi','','卷13','寒色凝罗幕，同人清夜期。
玉杯留醉处，银烛送归时。
独坐隔千里，空吟对雪诗。','',''),('quantangshi-12775','禇主簿宅会毕庶子钱员外郎使君','韓翃','quantangshi','','卷13','开瓮腊酒熟，主人心赏同。
斜阳疎竹上，残雪乱天中。
更喜宣城印，朝廷与谢公。','',''),('quantangshi-12776','送李明府赴滑州','韓翃','quantangshi','','卷13','渭城寒食罢，送客归远道。
乌帽背斜晖，青骊踏春草。
酒醒孤烛夜，衣冷千山早。
去事沈尚书，应怜词赋好。','',''),('quantangshi-12777','送李司直赴江西使幕','韓翃','quantangshi','','卷13','敛版辞汉廷，进帆归楚幕。
三江城上转，九里人家泊。
好酒近宜城，能诗谢康乐。
雨晴西山树，日出南昌郭。
竹露点衣巾，湖烟湿扃钥。
主人苍玉佩，后骑黄金络。
高视领八州，相期同一鹗。
行当报知己，从此飞寥廓。','',''),('quantangshi-12778','祭岳回重赠孟都督','韓翃','quantangshi','','卷13','封作天齐王，清祠太山下。
鲁公秋赛毕，晓日回高驾。
从骑尽幽并，同人皆沈谢。
自矜文武足，一醉寒溪夜。','',''),('quantangshi-12779','送南少府归寿春','韓翃','quantangshi','','卷13','人言寿春远，此去先秋到。
孤客小翼舟，诸生高翅帽。
淮风生竹簟，楚雨移茶竈。
若在八公山，题诗一相报。','',''),('quantangshi-12780','赠别崔司直赴江东兼简常州独孤使君','韓翃','quantangshi','','卷13','爱君青袍色，芳草能相似。
官重法家流，名高墨曹吏。
春衣淮上宿，美酒江边醉。
楚酪沃雕胡，湘羹糁香饵。
前朝山水国，旧日风流地。
苏山逐青骢，江家驱白鼻。
右军尚少年，三领东方骑。
亦过小丹阳，应知百城贵。','',''),('quantangshi-12781','经月岩山','韓翃','quantangshi','','卷13','驱车过闽越，路出饶阳西。
仙山翠如画，簇簇生虹霓。
羣峯若侍从，众阜如婴提。
岩峦互吞吐，岭岫相追携。
中有月轮满，皎洁如圆圭。
玉皇恣游览，到此神应迷。
嫦娥曳霞帔，引我同攀跻。
腾腾上天半，玉镜悬飞梯。
瑶池何悄悄，鸾鹤烟中栖。
回头望尘事，露下寒凄凄。','',''),('quantangshi-12782','送客之江宁','韓翃','quantangshi','','卷13','春流送客不应赊，南入徐州见柳花。
朱雀桥边看淮水，乌衣巷里问王家。
千闾万井无多事，辟户开门向山翠。
楚云朝下石头城，江燕双飞瓦棺寺。
吴士风流甚可亲，相逢嘉赏日应新。
从来此地夸羊酪，自有莼羹定却人。','',''),('quantangshi-12783','送山阴姚丞携妓之任兼寄山阴苏少府','韓翃','quantangshi','','卷13','东风香草路，南客心容与。
白皙吴王孙，青蛾柳家女。
都门数骑出，河口片帆举。
夜簟眠橘洲，春衫傍枫屿。
山阴政简甚从容，到罢唯求物外踪。
落日花边剡溪水，晴烟竹里会稽峯。
才子风流苏伯玉，同官晓暮应相逐。
加餐共爱鲈鱼肥，醒酒仍怜甘蔗熟。
知君炼思本清新，季子如今德有邻。
他日如寻始宁墅，题诗早晚寄西人。','',''),('quantangshi-12784','和高平朱参军思归作','韓翃','quantangshi','','卷13','髯参军，髯参军。
身为北州吏，心寄东山云。
坐见凄凄芳草绿，遥思往日晴江曲。
刺船频向剡中回，捧被曾过越人宿。
花里莺啼白日高，春楼把酒送车螯。
狂歌好爱陶彭泽，佳句唯称谢法曹。
平生乐事多如此，忍为浮名隔千里。
一雁南飞动客心，思归何待秋风起。','',''),('quantangshi-12785','赠别成明府赴劒南','韓翃','quantangshi','','卷13','朝为三室印，晚为三蜀人。
遥知下车日，正及巴山春。
县道橘花里，驿流江水滨。
公门輙无事，赏地能相亲。
解衣初醉绿芳夕，应采蹲鸱荐佳客。
霁水远暎西川时，闲望碧鸡飞古祠。
爱君乐事佳兴发，天外铜梁多梦思。','',''),('quantangshi-12786','送孙泼赴云中','韓翃','quantangshi','','卷13','黄骢少年舞双戟，目视旁人皆辟易。
百战能夸陇上儿，一身复作云中客。
寒风动地气苍茫，横吹先悲出塞长。
敲石军中传夜火，斧冰河畔汲朝浆。
前锋直指阴山外，虏骑纷纷胆应碎。
匈奴破尽人看归，金印酬功如斗大。','',''),('quantangshi-12787','送客还江东','韓翃','quantangshi','','卷13','还家不落春风后，数日应沽越人酒。
池畔花深鬬鸭栏，桥边雨洗藏鸦柳。
遥怜内舍着新衣，复向邻家醉落晖。
把手闲歌香橘下，空山一望鹧鸪飞。','',''),('quantangshi-12788','送夏侯侍郎','韓翃','quantangshi','','卷13','元戎车右早飞声，御史府中新正名。
翰墨已齐钟大理，风流好继谢宣城。
从军晓别龙骧幕，六骑先驱嘶近郭。
前路应留白玉台，行人輙美黄金络。
使君下马爱瀛洲，简贵将求物外游。
听讼不闻乌布帐，迎宾暂着紫绨裘。
公庭日夕罗山翠，功遂心闲无一事。
移书或问岛边人，立仗时呼铃下吏。
事业初传小夏侯，中年劒笏在西州。
浮云飞鸟两相忘，他日依依城上楼。','',''),('quantangshi-12789','送李湜下第归卫州便游河北','韓翃','quantangshi','','卷13','莫嗟太常屈，便入苏门啸。
里在应未迟，勿作我身料。
轻云日下不成阴，出对流芳搅别心。
万雉城东春水阔，千人乡北晚花深。
旧竹青青常绕宅，到时疎旷应自适。
佳期纵得上宫游，旅食还为北邙客。
路出司州胜景长，西山翠色带清漳。
仙人矶近茱萸涧，铜雀台临野马冈。
屡道主人多爱士，何辞策马千余里。
高谭魏国访先生，修刺平原过内史。
一举青云在早秋，恐君从此便淹留。
有钱莫向河间用，载笔须来阙下游。','',''),('quantangshi-12790','张山人草堂会王方士','韓翃','quantangshi','','卷13','屿花晚，山日长，蕙带麻襦食草堂。
一片水光飞入户，千竿竹影乱登墙。
园梅熟，家酝香。
新湿头巾不复篸，相看醉倒卧藜牀。','',''),('quantangshi-12791','送蓨县刘主簿楚','韓翃','quantangshi','','卷13','起家得事平原侯，晚出都门辞旧游。
草色连绵几千里，青骊躞蹀路旁子。
花深近县宿河阳，竹暎春舟渡淇水。
邺下淹留佳赏新，羣公旧日心相亲。
金盘晓鲙朱衣鲋，玉簟霄迎翠羽人。
王程书使前期促，他日应知举鞭速。
寒水浮瓜五月时，把君衣袖长河曲。','',''),('quantangshi-12792','题玉山观禅师兰若','韓翃','quantangshi','','卷13','玉山宴坐移年月，锡杖承恩诣丹阙。
先朝亲与会龙华，紫禁鸣钟白日斜。
宫女焚香把经卷，天人就席礼袈裟。
禅牀久卧虎溪水，兰若初开凤城里。
不出嚣尘见远公，道成何必青莲宫。
朝持药钵千家近，暮倚绳牀一室空。
掖垣挥翰君称美，远客陪游问真理。
薄宦深知误此心，回心愿学雷居士。','',''),('quantangshi-12793','赠别上元主簿张着','韓翃','quantangshi','','卷13','上书一见平津侯，劒笏斜齐秣陵尉。
朝垂绶带迎远客，暮锁印囊飞上吏。
长乐花深万井时，同官无事有归期。
回船对酒三生渚，系马焚香五愿祠。
日日澄江带山翠，绿芳都在经过地。
行人看射领军堂，游女题诗光宅寺。
风流才调爱君偏，此别相逢定几年。
惆怅浮云迷远道，张侯楼上月娟娟。','',''),('quantangshi-12794','别泛水县尉','韓翃','quantangshi','','卷13','未央宫殿金开钥，诏引贤良卷珠箔。
花间赐食近丹墀，烟里挥毫对青阁。
万年枝影转斜光，三道先成君激昂。
谷水直言身不顾，郄诜高第转名香。
绿槐阴阴出关道，上有蝉声下秋草。
奴子平头骏马肥，少年白皙登王畿。
五侯客舍偏留宿，一县人家争看归。
南向千峯北临水，佳期赏地应穷此。
赋诗或送郑行人，举酒常陪魏公子。
自怜寂寞会君稀，犹着前时博士衣。
我欲低眉问知己，若将无用废东归。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-12795','别李明府','韓翃','quantangshi','','卷13','宠光五世要青组，出入珠宫引箫鼓。
醉舞雄王玳瑁牀，娇嘶骏马珊瑚柱。
胡儿夹鼓越婢随，行捧玉盘尝荔枝。
罗山道士请人送，林邑使臣调象骑。
爱君一身游上国，阙下名公如旧识。
万里初怀印绶归，湘江过尽岭花飞。
五侯焦石烹江笋，千户沈香染客衣。
别后想君难可见，苍梧云里空山县。
汗苑芳菲入夏阑，待君障日蒲葵扇。','',''),('quantangshi-12796','送中兄典邵州','韓翃','quantangshi','','卷13','官骑连西向楚云，朱轩出饯昼纷纷。
百城兼领安南国，双笔遥挥王左君。
一路诸侯争馆谷，洪池高会荆台曲。
玉颜送酒铜[鞮]歌，金管留人石头宿。
北雁初回江燕飞，南湖春暖着春衣。
湘君祠对空山掩，渔父焚香日暮归。
百事无留到官后，重门寂寂垂高柳。
零陵过赠石香溪，洞口人来饮醇酒。
登楼暮结邵阳情，万里苍波烟霭生。
他日新诗应见报，还如宣远在安城。','',''),('quantangshi-12797','送万巨','韓翃','quantangshi','','卷13','汉相见王陵，扬州事张禹。
风帆木兰檝，水国莲花府。
百丈清江十月天，寒城鼓角晓钟前。
金炉促膝诸曹吏，玉管繁华美少年。
有时过向长干地，远对湖光近山翠。
好逢南苑看人归，也向西池留客醉。
高柳垂烟橘带霜，朝游石渚暮横塘。
红牋色夺风流座，白苎词倾翰墨场。
夫子前年入朝后，高名籍籍时贤口。
共怜诗兴转清新，继远家声在此身。
屈指待为青琐客，回头莫羡白亭人。','',''),('quantangshi-12798','送巴州杨使君','韓翃','quantangshi','','卷13','白云县北千山口，青岁欲开残雪后。
前驱锦带鱼皮鞮，侧佩金璋虎头绶。
南郑侯家醉落晖，东关陌上着鞭归。
愁看野马随官骑，笑取秦人带客旗。
使者下车忧疾苦，豪吏销声出公府。
万里歌钟相庆时，巴童声节渝儿舞。','',''),('quantangshi-12799','送王侍御赴江西兼寄李袁州','韓翃','quantangshi','','卷13','中朝理章服，南国随旌旆。
腊酒湘城隅，春衣楚江外。
垂帘白角簟，下筯鲈鱼鲙。
雄笔佐名公，虚舟应时辈。
按俗承流几路清，平明山霭春江云。
湓城诗赠鱼司马，汝水人逢王右军。
绿苹白芷遥相引，孤兴幽寻知不近。
井上铜人行见无，湖中石燕飞应尽。
礼门前直事仙郎，腰垂青绶领咸阳。
花间五马迎君日，雨霁烟开玉女冈。','',''),('quantangshi-12800','寄雍丘窦明府','韓翃','quantangshi','','卷13','少年结绶骋金羁，许下如看琼树枝。
入里亲过朗陵伯，出门高视颍川儿。
西游太府东乘传，泗上诸侯谁不羡。
时辈宁将白笔期，高流竚向丹霄见。
何事飜飞不及羣，虎班突骑来纷纷。
吴江垂钓楚山醉，身寄沧波心白云。
中岁胡尘静如扫，一官又罢行将老。
薛公荐士得君初，囗领黄金千室余。
机尽独亲沙上鸟，家贫唯向釜中鱼。
囗囗囗囗囗囗囗，囗出重门烟树里。
感物吟诗对暮天，怀人倚杖临秋水。
别离几日问前期，鸣雁亭边人去时。
独坐不堪朝与夕，高风萧索乱蝉悲。','',''),('quantangshi-12801','赠衮州孟都督','韓翃','quantangshi','','卷13','少年亲事冠军侯，中岁仍迁北衮州。
露冕宁夸汉车服，下帷常讨鲁春秋。
后斋草色连高阁，车简人稀独行乐。
闲心近掩陶使君，诗兴遥齐谢康乐。
远山重叠水逶迤，落日东城闲望时。
不见双亲办丰膳，能留五马尽佳期。
北场争转黄金勒，爱客华亭赏秋色。
卷帘满地铺氍毹，吹角鸣弦开玉壶。
愿学平原十日饮，此时不忍歌骊驹。','',''),('quantangshi-12802','别孟都督','韓翃','quantangshi','','卷13','平芜霁色寒城下，美酒百壶争劝把。
连呼宝劒锐头儿，少驻金羁大头马。
一饮留欢分有余，寸心怀思复何如。
他时相忆若相问，青琐门前开素书。','',''),('quantangshi-12803','送别郑明府','韓翃','quantangshi','','卷13','长头大鼻鬓如雪，早岁连兵劒锋折。
千金尽去无斗储，双袖破来空百结。
独恋郊扉已十春，高阳酒徒连此身。
路傍谁识郑公子，谷口应知汉逸人。
儿女相悲探井臼，前功岂在他人后。
劝君不得学渊明，且策驴车辞五柳。','',''),('quantangshi-12804','赠别王侍御赴上都','韓翃','quantangshi','','卷13','翩翩马上郎，执简佩银章。
西向洛阳归鄠杜，回头结念莲花府。
朝辞芳草万岁街，暮宿春山一泉坞。
青青树色傍行衣，乳燕流莺相间飞。
远过三峯临八水，幽寻佳赏偏如此。
残花片片细柳风，落日疎钟小槐雨。
相思掩泣复何如，公子门前人渐疎。
幸有心期当小暑，葛衣纱帽望回车。','',''),('quantangshi-12805','赠别太常李博士兼寄两省旧游','韓翃','quantangshi','','卷13','两年戴武弁，趋侍明光殿。
一朝簪惠文，客事信陵君。
简异当朝执，香非寓直熏。
差肩何记室，携手李将军。
玉镫初回酸枣馆，金钿正舞石榴裙。
忽惊万事随流水，不见双旌逐塞云。
感旧抚心多寂寂，与君相遇头初白。
暂夸五首军中诗，还忆万年枝下客。
昨日留欢今送归，空披秋水暎斜晖。
闲吟佳句对孤鹤，惆怅寒霜落叶稀。','',''),('quantangshi-12806','寄哥舒仆射','韓翃','quantangshi','','卷13','万里长城家，一生唯报国。
腰垂紫文绶，手控黄金勒。
高视黑头翁，遥吞白骑贼。
先麾牙门将，转鬬黄河北。
帐下亲兵皆少年，锦衣承日绣行缠。
辘轳宝劒初出鞘，宛转角弓初上弦。
步人抽箭大如笛，前把两矛后双戟。
左盘右射红尘中，鹘入鸦羣有谁敌。
杀将破军白日余，回旃舞旆北风初。
郡公楯鼻好磨墨，走马为君飞羽书。','',''),('quantangshi-12807','赠别华阴道士','韓翃','quantangshi','','卷13','紫府先生旧同学，腰垂彤管贮灵药。
耻论方士小还丹，好饮仙人太玄酪。
芙蓉山顶玉池西，一室平临万仞溪。
昼洒瑶台五云湿，夜行金烛七星齐。
回身暂下青冥里，方外相寻有知己。
卖鲊市中何许人，钓鱼坐上谁家子。
青青百草云台春，烟驾霓衣白角巾。
露叶独归仙掌去，回风片雨谢时人。','',''),('quantangshi-12808','送崔秀才赴上元兼省叔父','韓翃','quantangshi','','卷13','寒塘敛暮雪，腊鼓迎春早。
匹马五城人，重裘千里道。
淮山轻露湿，江树狂风扫。
楚县久酝醲，扬州百花好。
练湖东望接云阳，女市西游入建康。
行乐远夸红布旆，风流近赌紫香囊。
诗家行辈如君少，极目苦心怀谢朓。
烟开日上板桥南，吴岫青青出林表。','',''),('quantangshi-12809','赠别韦兵曹归池州','韓翃','quantangshi','','卷13','南陵八月天，暮色远峰前。
楚竹青阳路，吴江赤马船。
籝金诸客贵，佩玉主人贤。
终日应相逐，归期定几年。','',''),('quantangshi-12810','寄武陵李少府','韓翃','quantangshi','','卷13','小县春山口，公孙吏隐时。
楚歌催晚醉，蛮语入新诗。
桂水遥相忆，花源暗有期。
郢门千里外，莫怪尺书迟。','',''),('quantangshi-12811','赠张建','韓翃','quantangshi','','卷13','结客平陵下，当年倚侠游。
传看辘轳剑，醉脱驦驌裘。
翠羽双鬟妾，珠帘百尺楼。
春风坐相待，晚日莫淹留。','',''),('quantangshi-12812','送监军李判官','韓翃','quantangshi','','卷13','上客佩双剑，东城喜再游。
旧从张博望，新事郑长秋。
踏水回金勒，看风试锦裘。
知君不久住，汉将扫旄头。','',''),('quantangshi-12813','送客归广平','韓翃','quantangshi','','卷13','家在赵邯郸，归心輙自欢。
晚杯狐腋暖，春雪马毛寒。
孟月途中破，轻冰水上残。
到时杨柳色，奈向故园看。','',''),('quantangshi-12814','送张儋水路归北海','韓翃','quantangshi','','卷13','千里东归客，孤心忆旧游。
片帆依白水，高枕卧青州。
柏寝寒芜变，梧台宿雨收。
知君心兴远，每上海边楼。','',''),('quantangshi-12815','送故人归鲁','韓翃','quantangshi','','卷13','鲁客多归兴，居人怅别情。
雨余衫袖冷，风急马蹄轻。
秋草灵光殿，寒云曲阜城。
知君拜亲后，少妇下机迎。','',''),('quantangshi-12816','送故人归蜀','韓翃','quantangshi','','卷13','一骑西南远，翩翩入剑门。
客衣筒布润，山舍荔枝繁。
古庙祠金马，春江带白鼋。
自应成旅逸，爱客有王孙。','',''),('quantangshi-12817','酬程延秋夜即事见赠','韓翃','quantangshi','','卷13','长簟迎风早，空城澹月华。
星河秋一雁，砧杵夜千家。
节候看应晚，心期卧亦赊。
向来吟秀句，不觉已鸣鸦。','',''),('quantangshi-12818','送郭赞府归淮南','韓翃','quantangshi','','卷13','骏马淮南客，归时引望新。
江声六合暮，楚色万家春。
白苎歌西曲，黄苞寄北人。
不知心赏后，早晚见行尘。','',''),('quantangshi-12819','题龙兴寺澹师房','韓翃','quantangshi','','卷13','双林彼上人，诗兴转相亲。
竹里经声晚，门前山色春。
卷帘苔点净，下筯药苗新。
记取无生理，归来问此身。','',''),('quantangshi-12820','送客游江南','韓翃','quantangshi','','卷13','南使孤帆远，东风任意吹。
楚云殊不断，江鸟暂相随。
月净鸳鸯水，春生豆蔻枝。
赏称佳丽地，君去莫应知。','',''),('quantangshi-12821','送高员外赴淄青使幕','韓翃','quantangshi','','卷13','远水流春色，回风送落晖。
人趋双节近，马递百花归。
山驿尝官酒，关城度客衣。
从来赤管笔，提向幕中稀。','',''),('quantangshi-12822','寻胡处士不遇','韓翃','quantangshi','','卷13','到来心自足，不见亦相亲。
说法思居士，忘机忆丈人。
微风吹药案，晴日照茶巾。
幽兴殊未尽，东城飞暮尘。','',''),('quantangshi-12823','赠张道者','韓翃','quantangshi','','卷13','采药三山罢，乘风五日归。
翦荷成旧屋，锉蘖染新衣。
玉粒指应久，丹砂验不微。
坐看青节引，要与白云飞。','',''),('quantangshi-12824','题苏许公林亭','韓翃','quantangshi','','卷13','平津东阁在，别是竹林期。
万叶秋声里，千家落照时。
门随深巷静，窗过远钟迟。
客舍苔生处，依依又赋诗。','',''),('quantangshi-12825','送元诜还江东','韓翃','quantangshi','','卷13','过江秋色在，诗兴与归心。
客路随枫岸，人家扫橘林。
潮声当昼起，山翠近南深。
几日华阳洞，寒花引独寻。','',''),('quantangshi-12826','送客游江南','韓翃','quantangshi','','卷13','桂水随去远，赏心知有余。
衣香楚山橘，手鲙湘波鱼。
芳芷不共把，浮云怅离居。
遥想汩罗上，吊屈秋风初。','',''),('quantangshi-12827','送海州姚别驾','韓翃','quantangshi','','卷13','少年为长史，东去事诸侯。
坐觉千闾静，闲随五马游。
行人楚国道，暮雪郁林州。
他日知相忆，春风海上楼。','',''),('quantangshi-12828','送夏侯审','韓翃','quantangshi','','卷13','谢公邻里在，日夕问佳期。
春水人归后，东田花尽时。
下楼闲待月，行乐笑题诗。
他日吴中路，千山入梦思。','',''),('quantangshi-12829','送赵评事赴洪州使幕','韓翃','quantangshi','','卷13','孤舟行远近，一路过湘东。
官属张廷尉，身随杜幼公。
山河映湘竹，水驿带青枫。
万里思君处，秋江夜雨中。','',''),('quantangshi-12830','送李侍御赴徐州行营','韓翃','quantangshi','','卷13','少年兼柱史，东至旧徐州。
远属平津阁，前驱博望侯。
向营淮水满，吹角楚天秋。
客梦依依处，寒山对白楼。','',''),('quantangshi-12831','送李秀才归江南','韓翃','quantangshi','','卷13','过淮芳草歇，千里又东归。
野水吴山出，家林越鸟飞。
荷香随去棹，梅雨点行衣。
无数沧江客，如君达者稀。','',''),('quantangshi-12832','题僧房','韓翃','quantangshi','','卷13','披衣闻客至，关锁此时开。
鸣罄夕阳尽，卷帘秋色来。
名香连竹径，清梵出花台。
身在心无住，他方到几回。','',''),('quantangshi-12833','送寿州陈录事','韓翃','quantangshi','','卷13','寿阳南渡口，敛笏见诸侯。
五两楚云暮，千家淮水秋。
开帘对芳草，送客上春洲。
请问山中桂，王孙几度游。','',''),('quantangshi-12834','送赵陆司兵归使幕','韓翃','quantangshi','','卷13','客路青芜遍，关城白日低。
身趋双节近，名共五云齐。
远水公田上，春山郡舍西。
无因得携手，东望转凄凄。','',''),('quantangshi-12835','送蒋员外端公归淮南','韓翃','quantangshi','','卷13','淮南芳草色，日夕引归船。
御史王元贶，郎官顾彦先。
光风千日暖，寒食百花燃。
惆怅佳期近，澄江与暮天。','',''),('quantangshi-12836','题慈仁寺竹院','韓翃','quantangshi','','卷13','千峰对古寺，何异到西林。
幽罄蝉声下，闲窗竹翠阴。
诗人谢客兴，法侣远公心。
寂寂炉烟里，香花欲暮深。','',''),('quantangshi-12837','赠郓州马使君','韓翃','quantangshi','','卷13','东方千马骑，出望使君时。
暮雪行看尽，春城到莫迟。
路人趋墨帻，官柳度青丝。
他日铃斋内，知君亦赋诗。','',''),('quantangshi-12838','送张丞归使幕','韓翃','quantangshi','','卷13','独受主恩归，当朝似者稀。
玉壶分御酒，金殿赐春衣。
拂席流莺醉，鸣鞭骏马肥。
满台簪白笔，捧手恋清晖。','',''),('quantangshi-12839','赠长洲何主簿','韓翃','quantangshi','','卷13','挂席逐归流，依依望虎丘。
残春过楚县，夜雨宿吴洲。
野寺吟诗入，溪桥折笋游。
到官无一事，清静有诸侯。','',''),('quantangshi-12840','送崔过归淄青幕府','韓翃','quantangshi','','卷13','平陵车马客，海上见旌旗。
旧驿千山下，残花一路时。
春衣过水冷，暮雨出关迟。
莫道青州客，迢迢在梦思。','',''),('quantangshi-12841','田仓曹东亭夏夜饮得春字','韓翃','quantangshi','','卷13','薛公门下人，公子又相亲。
玉佩迎初夜，金壶醉老春。
葛衣香有露，罗幕静无尘。
更羡风流外，文章是一秦。','',''),('quantangshi-12842','赠王逖','韓翃','quantangshi','','卷13','端笏事龙楼，思闲輙告休。
新调赭白马，暂试黑貂裘。
珠履迎佳客，金钱与莫愁。
座中豪贵满，谁道不风流。','',''),('quantangshi-12843','送深州吴司马归使幕','韓翃','quantangshi','','卷13','东门送远客，车马正纷纷。
旧识张京兆，新随刘领军。
行骢看暮雨，归雁踏青云。
一去藂台北，佳声几日闻。','',''),('quantangshi-12844','华亭夜宴庾侍御宅','韓翃','quantangshi','','卷13','世故他年别，心期此夜同。
千峰孤烛外，片雨一更中。
酒客逢山简，诗人得谢公。
自怜驱匹马，拂曙向关东。','',''),('quantangshi-12845','送客之上谷','韓翃','quantangshi','','卷13','北客悲秋色，田园忆去来。
披衣朝易水，匹马夕燕台。
风翦荷花碎，霜迎栗罅开。
赏心知不浅，累月故人杯。','',''),('quantangshi-12846','同中书刘舍人题青龙上房','韓翃','quantangshi','','卷13','西掖归来后，东林静者期。
远峰春雪里，寒竹暮天时。
笑说金人偈，闲听宝月诗。
更怜茶兴在，好出下方迟。','',''),('quantangshi-12847','宴吴王宅','韓翃','quantangshi','','卷13','玉管箫声合，金杯酒色殷。
听歌吴季札，纵饮汉中山。
称寿争离席，留欢輙上关。
莫言辞客醉，犹得曳裾还。','',''),('quantangshi-12848','题荐福寺衡岳暕师房','韓翃','quantangshi','','卷13','春城乞食还，高论此中闲。
僧腊堦前树，禅心江上山。
疎帘看雪卷，深户映花关。
晚送门人出，钟声杳霭间。','',''),('quantangshi-12849','送戴廸赴凤翔幕府','韓翃','quantangshi','','卷13','青春带文绶，去事魏征西。
上路金羇出，中人玉筯齐。
当歌酒万斛，看猎马千蹄。
自有从军乐，何须怨解携。','',''),('quantangshi-12850','送郢州郎使君','韓翃','quantangshi','','卷13','千人插羽迎，知是范宣城。
暮雪楚山冷，春江汉水清。
红鲜供客饭，翠竹引舟行。
一别何时见，相思芳草生。','',''),('quantangshi-12851','送李中丞赴辰州','韓翃','quantangshi','','卷13','白羽逐青丝，翩翩南下时。
巴人迎道路，蛮帅引旌旗。
暮雨山开少，秋江叶落迟。
功成益地日，应见竹郎祠。','',''),('quantangshi-12852','送刘侍御赴陕州','韓翃','quantangshi','','卷13','金羁映驌驦，后骑佩干将。
把酒春城晚，鸣鞭晓路长。
带冰新溜涩，间雪早梅香。
明日怀贤处，依依御史牀。','',''),('quantangshi-12853','李中丞宅夜宴送丘侍御赴江东便往辰州','韓翃','quantangshi','','卷13','积雪临阶夜，重裘对酒时。
中丞违沈约，才子送丘迟。
一路三江上，孤舟万里期。
辰州佳兴在，他日寄新诗。','',''),('quantangshi-12854','送李侍御归宣州使幕','韓翃','quantangshi','','卷13','春草东江外，翩翩北路归。
官齐魏公子，身逐谢玄晖。
山色随行骑，莺声傍客衣。
主人池上酌，携手暮花飞。','',''),('quantangshi-12855','东城水亭宴李侍御副使','韓翃','quantangshi','','卷13','东门留客处，沽酒用钱刀。
秋水牀下急，斜晖林外高。
金羇络騕褭，玉匣闭豪曹。
去日随戎幕，东风见伯劳。','',''),('quantangshi-12856','送祕书谢监赴江西使幕','韓翃','quantangshi','','卷13','谢监忆山程，辞家万里行。
寒衣傍楚色，孤枕宿潮声。
小寇不足问，新诗应渐清。
府公相待日，引斾出江城。','',''),('quantangshi-12857','送江陵元司录','韓翃','quantangshi','','卷13','新领州从事，曾为朝大夫。
江城竹使待，山路橘官扶。
片雨三江道，残秋五叶湖。
能令诗思好，楚色与寒芜。','',''),('quantangshi-12858','送李舍人携家归江东觐省','韓翃','quantangshi','','卷13','二十青宫吏，成名似者稀。
承颜陆郎去，携手谢娘归。
夜月回孤烛，秋风试夹衣。
扁舟楚水上，来往速如飞。','',''),('quantangshi-12859','送刘侍御赴令公行营','韓翃','quantangshi','','卷13','东城跃紫骝，西路大刀头。
上客刘公干，元戎郭细侯。
一军偏许国，百战又防秋。
请问萧关道，胡尘早晚收。','',''),('quantangshi-12860','送苏州姚长史','韓翃','quantangshi','','卷13','江城驿路长，烟树过云阳。
舟领青丝缆，人歌白玉郎。
葛衣行柳翠，花簟宿荷香。
别有心期处，湖光满讼堂。','',''),('quantangshi-12861','送金华王明府','韓翃','quantangshi','','卷13','县舍江云里，心闲境又偏。
家贫陶令酒，月俸沈郎钱。
黄蘖香山路，青枫暮雨天。
时闻引车骑，竹外到铜泉。','',''),('quantangshi-12862','送田仓曹汴州觐省','韓翃','quantangshi','','卷13','拜庆承天宠，朝来辞汉宫。
玉杯分湛露，金勒借追风。
古驿秋山下，平芜暮雨中。
翩翩魏公子，人看渡关东。','',''),('quantangshi-12863','送张渚赴越州','韓翃','quantangshi','','卷13','白面谁家郎，青骊照地光。
桃花开绶色，苏合借衣香。
暮雪连峰近，春江海市长。
风流似张绪，别后见垂杨。','',''),('quantangshi-12864','奉和元相公家园即事寄王相公','韓翃','quantangshi','','卷13','共列中台贵，能齐物外心。
回车青阁晚，解带碧茸深。
寒水分畦入，晴花度竹寻。
题诗更相忆，一字重千金。','',''),('quantangshi-12865','送道士侄归池阳','韓翃','quantangshi','','卷13','银角桃枝杖，东门赠别初。
幽州寻马客，灞岸送驴车。
野饭秋山静，行衣落照余。
燕南羣从少，此去意何如。','',''),('quantangshi-12866','送刘长上归城南别业','韓翃','quantangshi','','卷13','数刻是归程，花间落照明。
春衣香不散，骏马汗犹轻。
南渡春流浅，西风片雨晴。
朝还会相就，饭尔五侯鲭。','',''),('quantangshi-12867','赠张五諲归濠州别业','韓翃','quantangshi','','卷13','常知罢官意，果与世人疎。
复此凉风起，仍闻濠上居。
故山期采菊，秋水忆观鱼。
一去蓬蒿迳，羡君闲有余。','',''),('quantangshi-12868','送营城李少府','韓翃','quantangshi','','卷13','怀录兼就养，更怀趋府心。
晴山东里近，春水北门深。
新绶映芳草，旧家依远林。
还乘郑小驷，躞蹀县城阴。','',''),('quantangshi-12869','鲁中送鲁使君归郑州','韓翃','quantangshi','','卷13','城中金络骑，出饯沈东阳。
九月寒露白，六关秋草黄。
齐讴听处妙，鲁酒把来香。
醉后着鞭去，梅山道路长。','',''),('quantangshi-12870','送夏侯校书归上都','韓翃','quantangshi','','卷13','后辈传佳句，高流爱美名。
青春事贺监，黄卷问张生。
暮雪重裘醉，寒山匹马行。
此回将诣阙，几日谏书成。','',''),('quantangshi-12871','送李明府赴连州','韓翃','quantangshi','','卷13','万里向南湘，孤舟入桂阳。
诸侯迎上客，小吏拜官郎。
春服幢花细，初筵木槿芳。
看承雨露速，不待荔枝香。','',''),('quantangshi-12872','送卢大理赵侍御祭东岳兼寄孟衮州','韓翃','quantangshi','','卷13','东岳昔有事，两臣朝望归。
驿亭开岁酒，斋舍着新衣。
上客钟大理，主人陶武威。
仍随御史马，山路满光辉。','',''),('quantangshi-12873','送皇甫大夫赴浙东','韓翃','quantangshi','','卷13','舟师分水国，汉将领秦官。
麾下同心吏，军中囗囗端。
吴门秋露湿，楚驿暮天寒。
豪贵东山去，风流胜谢安。','',''),('quantangshi-12874','送韦秀才','韓翃','quantangshi','','卷13','东人相见罢，秋草独归时。
几日孙弘阁，当年谢朓诗。
寒山叶落早，多雨路行迟。
好忆金门步，功名自有期。','',''),('quantangshi-12875','送客一归襄阳二归浔阳','韓翃','quantangshi','','卷13','南驱匹马会心期，东望扁舟惬梦思。
熨斗山前春色早，香炉峰顶暮烟时。
空林欲访庞居士，古寺应怀远法师。
两地由来堪取兴，三贤他日幸留诗。','',''),('quantangshi-12876','送故人赴江陵寻庾牧','韓翃','quantangshi','','卷13','主人持节拜荆州，走马应从一路游。
斑竹冈连山雨暗，枇杷门向楚天秋。
佳期笑把斋中酒，远意闲登城上楼。
文体此时看又别，吾知小庾甚风流。','',''),('quantangshi-12877','送客水路归陕','韓翃','quantangshi','','卷13','相风竿影晓来斜，渭水东流去不赊。
枕上未醒秦地酒，舟前已见陕人家。
春桥杨柳应齐叶，古县棠棃也作花。
好是吾贤佳赏地，行逢三月会连沙。','',''),('quantangshi-12878','送丹阳刘太真','韓翃','quantangshi','','卷13','长干道上落花朝，羡尔当年赏事饶。
下筯已怜鹅炙美，开笼不奈鸭媒娇。
春衣晚入青杨巷，细马初过皂荚桥。
相访不辞千里远，西风好借木兰桡。','',''),('quantangshi-12879','送客归江州','韓翃','quantangshi','','卷13','东归复得采真游，江水迎君日夜流。
客舍不离青雀舫，人家旧在白鸥洲。
风吹山带遥知雨，露湿荷裳已报秋。
闻道泉明居止近，篮舆相访为淹留。','',''),('quantangshi-12880','题张逸人园林','韓翃','quantangshi','','卷13','花源一曲映茅堂，清论闲阶坐夕阳。
麈尾手中毛已脱，蟹螯尊上味初香。
春深黄口传窥树，雨后青苔散点墙。
更道小山宜助赏，呼儿舒簟醉岩芳。','',''),('quantangshi-12881','又题张逸人园林','韓翃','quantangshi','','卷13','藏头不复见时人，爱此云山奉养真。
露色点衣孤屿晓，花枝妨帽小园春。
时携幼稚诸峰上，闲濯眉须一水滨。
兴罢归来还对酌，茅檐挂着紫荷巾。','',''),('quantangshi-12882','送刘将军','韓翃','quantangshi','','卷13','明光细甲照錏锻，昨日承恩拜虎牙。
胆大欲期姜伯约，功多不让李轻车。
青巾校尉遥相许，墨矟将军莫大夸。
阙下来时亲伏奏，胡尘未尽不为家。','',''),('quantangshi-12883','送郑员外','韓翃','quantangshi','','卷13','风流不减杜陵时，五十为郎未是迟。
孺子亦知名下士，乐人争唱卷中诗。
身齐吏部还多醉，心顾尚书自有期。
要路眼青知己在，不应穷巷久低眉。','',''),('quantangshi-12884','寄徐州郑使君','韓翃','quantangshi','','卷13','江城五马楚云边，不羡雍容画省年。
才子旧称何水部，使君还继谢临川。
射堂草遍收残雨，官路人稀对夕天。
虽卧郡斋千里隔，与君同见月初圆。','',''),('quantangshi-12885','送襄垣王君归南阳别墅','韓翃','quantangshi','','卷13','都门霁后不飞尘，草色萋萋满路春。
双兔坡东千室吏，三鸦水上一归人。
愁眠客舍衣香满，走渡河桥马汗新。
少妇比来多远望，应知蟢子上罗巾。','',''),('quantangshi-12886','送王诞渤海使赴李太守行营','韓翃','quantangshi','','卷13','少年结客散黄金，中岁连兵扫绿林。
渤海名王曾折首，汉家诸将尽倾心。
行人去指徐州近，饮马回看泗水深。
喜见明时钟太尉，功名一似旧淮阴。','',''),('quantangshi-12887','送王少府归杭州','韓翃','quantangshi','','卷13','归舟一路转青苹，更欲随潮向富春。
吴郡陆机称地主，钱塘苏小是乡亲。
葛花满把能消酒，栀子同心好赠人。
早晚重过鱼浦宿，遥怜佳句箧中新。','',''),('quantangshi-12888','赠王随','韓翃','quantangshi','','卷13','青云自致晚应遥，朱邸新婚乐事饶。
饮罢更怜双袖舞，试来偏爱五花骄。
帐里炉香春梦晓，堂前烛影早更朝。
更说球场新雨歇，王孙今日定相邀。','',''),('quantangshi-12889','同题仙游观','韓翃','quantangshi','','卷13','仙台下见五城楼，风物凄凄宿雨收。
山色遥连秦树晚，砧声近报汉宫秋。
疎松影落空坛静，细草香闲小洞幽。
何用别寻方外去，人间亦自有丹丘。','',''),('quantangshi-12890','访王起居不遇留赠','韓翃','quantangshi','','卷13','双龙阙下拜恩初，天子令君注起居。
载笔已齐周右史，论诗更事谢中书。
行闻漏滴随金仗，入对炉烟侍玉除。
贺客自知来独晚，青骊不见意何如。','',''),('quantangshi-12891','送刘评事赴广州使幕','韓翃','quantangshi','','卷13','征南官属似君稀，才子当今刘孝威。
蛮府参军趋传舍，交州刺史拜行衣。
前临瘴海无人过，却望衡阳少雁飞。
为报苍梧云影道，明年早送客帆归。','',''),('quantangshi-12892','送冷朝阳还上元','韓翃','quantangshi','','卷13','青丝䋏引木兰船，名遂身归拜庆年。
落日澄江乌榜外，秋风疎柳白门前。
桥通小市家林近，山带平湖野寺连。
别后依依寒食里，共君携手在东田。','',''),('quantangshi-12893','送高别驾归汴州','韓翃','quantangshi','','卷13','信陵门下识君偏，骏马轻裘正少年。
寒雨送归千里外，东风沈醉百花前。
身随玉帐心应惬，官佐龙符势又全。
久客未知何计是，参差去借汶阳田。','',''),('quantangshi-12894','送康洗马归滑州','韓翃','quantangshi','','卷13','腰佩雕弓汉射声，东归衔命见双旌。
青丝玉勒康侯马，孟水金堤滑伯城。
腊雪夜看宜纵饮，寒芜昼猎不妨行。
怀君又隔千山远，别后春风百草生。','',''),('quantangshi-12895','寄上田仆射','韓翃','quantangshi','','卷13','家封薛县异诸田，报主荣亲义两全。
仆射临戎谢安石，大夫持宪杜延年。
金装昼出罗千骑，玉案晨飡直万钱。
应念一身留阙下，阖门遥寄鲁西偏。','',''),('quantangshi-12896','送王光辅归青州兼寄储侍郎','韓翃','quantangshi','','卷13','几回奏事建章宫，圣主偏知汉将功。
身着紫衣趋阙下，口衔丹诏出关东。
蝉声驿路秋山里，草色河桥落照中。
远忆故人沧海别，当年好跃五花骢。','',''),('quantangshi-12897','宴杨驸马山池','韓翃','quantangshi','','卷13','垂杨拂岸草茸茸，绣户帘前花影重。
鲙下玉盘红缕细，酒开金瓮绿醅浓。
中朝驸马何平叔，南国词人陆士龙。
落日泛舟同醉处，回潭百丈映千峰。','',''),('quantangshi-12898','送长史李少府入蜀','韓翃','quantangshi','','卷13','行行独出故关迟，南望千山无尽期。
见舞巴童应暂笑，闻歌蜀道又堪悲。
孤城晚闭清江上，匹马寒嘶白露时。
别后此心君自见，山中何事不相思。','',''),('quantangshi-12899','送客还江东','韓翃','quantangshi','','卷13','不妨高卧顺流归，五两行看扫翠微。
鼯鼠夜喧孤枕近，䴔䴖晓避客船飞。
一壶先醉桃枝簟，百和初熏苎布衣。
君到新林江口泊，吟诗应赏谢玄晖。','',''),('quantangshi-12900','寄令狐尚书','韓翃','quantangshi','','卷13','立身荣贵复何如，龙节红旗从板舆。
妙略多推霍骠骑，能文独见沈尚书。
临风高会千门帐，映水连营百乘车。
他日感恩慙未报，举家犹似涸池鱼。','',''),('quantangshi-12901','扈从郊庙因呈两省诸公','韓翃','quantangshi','','卷13','丹墀列士主恩同，厩马翩翩出汉宫。
奉引乘舆金仗里，亲尝赐食玉盘中。
昼趋行殿旌门北，夜宿斋房刻漏东。
明日驾回承雨露，齐将万岁及春风。','',''),('quantangshi-12902','送端州冯使君','韓翃','quantangshi','','卷13','白皙风流似有须，一门豪贵领苍梧。
三峰亭暗橘边宿，八桂林香节下趋。
玉树羣儿争翠羽，金盘少妾拣明珠。
怀君乐事不可见，鬃马翩翩新虎符。','',''),('quantangshi-12903','送王府张参军附学及第东归','韓翃','quantangshi','','卷13','邻家不识鬬鸡翁，闭户能齐隐者风。
顾步曾为小山客，成名因事大江公。
一身千里寒芜上，单马重裘腊月中。
寂寂故园行见在，暮天残雪洛城东。','',''),('quantangshi-12904','送齐明府赴东阳','韓翃','quantangshi','','卷13','绿丝帆繂桂为樯，过尽淮山楚水长。
万里移家背春谷，一官行府向东阳。
风流好爱杯中物，豪荡仍欺陌上郎。
别后心期如在眼，猨声烟色树苍苍。','',''),('quantangshi-12905','鲁中送从事归荥阳','韓翃','quantangshi','','卷13','故园衰草带荥波，岁晚知如君思何。
轻橐归时鲁缟薄，寒衣缝处郑绵多。
万人都督鸣骝送，百里邦君枉骑过。
累路尽逢知己在，曾无对酒不高歌。','',''),('quantangshi-12906','衮州送李明府使苏州便赴告期','韓翃','quantangshi','','卷13','莫言水国去迢迢，白马吴门见不遥。
枫树林中经楚雨，木兰舟上蹋江潮。
空山古寺千年石，草色寒堤百尺桥。
早晚卢家兰室在，珊瑚玉佩彻青霄。','',''),('quantangshi-12907','送田明府归终南别业','韓翃','quantangshi','','卷13','故园此日多心赏，窗下泉流竹外云。
近馆应逢沈道士，比邻自识卞田君。
离宫树影登山见，上苑钟声过雪闻。
相劝早移丹凤阙，不须常恋白鸥羣。','',''),('quantangshi-12908','家兄自山南罢归献诗叙事','韓翃','quantangshi','','卷13','时辈已争先，吾兄未着鞭。
空嗟镊须日，犹是屈腰年。
不以殊方远，仍论水地偏。
襄橙随客路，汉竹引归船。
云木巴东峡，林泉岘北川。
池余骑马处，宅似卧龙边。
夜簟千峰月，朝窗万井烟。
朱荷江女院，青稻楚人田。
县舍多潇洒，城楼入醉眠。
黄苞柑正熟，红缕鲙仍鲜。
坐厌牵丝倦，因从解绶旋。
初辞五斗米，唯奉一囊钱。
室好生虚白，书耽守太玄。
枥中嘶欵段，阶下引潺湲。
落照渊明柳，春风叔夜弦。
绛纱儒客帐，丹诀羽人篇。
雅论承安石，新诗与惠连。
兴清湖见底，襟豁雾开天。
魏阙心犹系，周才道岂捐。
一丘无自逸，三府会招贤。','',''),('quantangshi-12909','奉送王相公缙赴幽州巡边','韓翃','quantangshi','','卷13','黄阁开帷幄，丹墀侍冕旒。
位高汤左相，权总汉诸侯。
不改周南化，仍分赵北忧。
双旌过易水，千骑入幽州。
塞草连天暮，边风动地秋。
无因随远道，结束佩吴钩。','',''),('quantangshi-12910','寄赠虢州张参军','韓翃','quantangshi','','卷13','三十事诸侯，贤豪冠北州。
桃花迎骏马，苏合染轻裘。
观妓将军第，题诗关尹楼。
青林朝送客，绿屿晚回舟。
好栗分通子，名香赠莫愁。
洗杯新酒熟，把烛故人留。
百雉归云过，千峰宿雨收。
蒹葭露下晚，菡萏水中秋。
忆昨陪行乐，常时接献酬。
佳期虽雾散，惠问亦川流。
开卷酲堪解，含毫思苦抽。
无因达情意，西望日悠悠。','',''),('quantangshi-12911','送李中丞赴商州','韓翃','quantangshi','','卷13','五马渭桥东，连嘶逐晓风。
当年紫髯将，他日黑头公。
不异金吾宠，兼齐玉帐雄。
闭营春雪下，吹角暮山空。
香麝松阴里，寒猨黛色中。
郡斋多赏事，好与故人同。','',''),('quantangshi-12912','汉宫曲二首 一','韓翃','quantangshi','','卷13','骏马绣障泥，红尘扑四蹄。
归时何太晚，日照杏花西。','',''),('quantangshi-12913','汉宫曲二首 二','韓翃','quantangshi','','卷13','绣幕珊瑚钩，春开翡翠楼。
深情不肯道，娇倚钿箜篌。','',''),('quantangshi-12914','陪孟都督祭岳途中有赠','韓翃','quantangshi','','卷13','封疆七百里，禄秩二千石。
拥节祠太山，寒天霜草白。','',''),('quantangshi-12915','宿甑山','韓翃','quantangshi','','卷13','山中今夜何人，阙下当年近臣。
青琐应须早去，白云何用相亲。','',''),('quantangshi-12916','别甑山','韓翃','quantangshi','','卷13','一身趋侍丹墀，西路翩翩去时。
惆怅青山绿水，何年更是来期。','',''),('quantangshi-12917','送陈明府赴淮南','韓翃','quantangshi','','卷13','年华近逼清明，落日微风送行。
黄鸟绵蛮芳树，紫骝躞蹀东城。
花间一杯促膝，烟外千里含情。
应渡淮南信宿，诸侯拥斾相迎。','',''),('quantangshi-12918','送客知鄂州','韓翃','quantangshi','','卷13','江口千家带楚云，江花乱点雪纷纷。
春风落日谁相见，青翰舟中有鄂君。','',''),('quantangshi-12919','寒食','韓翃','quantangshi','','卷13','春城无处不飞花，寒食东风御柳斜。
日暮汉宫传蜡烛，轻烟散入五侯家。','',''),('quantangshi-12920','羽林骑','韓翃','quantangshi','','卷13','骏马牵来御柳中，鸣鞭欲向渭桥东。
红蹄乱蹋春城雪，花颔骄嘶上苑风。','',''),('quantangshi-12921','看调马','韓翃','quantangshi','','卷13','鸳鸯赭白齿新齐，晚日花中散碧蹄。
玉勒斗回初喷沫，金鞭欲下不成嘶。','',''),('quantangshi-12922','寄赠衡州杨使君','韓翃','quantangshi','','卷13','湘竹斑斑湘水春，衡阳太守虎符新。
朝来笑向归鸿道，早晚南飞见主人。','',''),('quantangshi-12923','宿石邑山中','韓翃','quantangshi','','卷13','浮云不共此山齐，山霭苍苍望转迷。
晓月暂飞高树里，秋河隔在数峰西。','',''),('quantangshi-12924','江南曲','韓翃','quantangshi','','卷13','长乐花枝雨点销，江城日暮好相邀。
春楼不闭葳蕤锁，绿水回通宛转桥。','',''),('quantangshi-12925','赠张千牛','韓翃','quantangshi','','卷13','蓬莱阙下是天家，上路新回白鼻騧。
急管昼催平乐酒，春衣夜宿杜陵花。','',''),('quantangshi-12926','汉宫曲二首 一','韓翃','quantangshi','','卷13','五柞宫中过腊看，万年枝上雪花残。
绮窗夜闭玉堂静，素绠朝穿金井寒。','',''),('quantangshi-12927','汉宫曲二首 二','韓翃','quantangshi','','卷13','家在长陵小市中，珠帘绣户对春风。
君王昨日移仙仗，玉辇迎将入汉宫。','',''),('quantangshi-12928','赠李翼','韓翃','quantangshi','','卷13','王孙别舍拥朱轮，不羡空名乐此身。
门外碧潭春洗马，楼前红烛夜迎人。','',''),('quantangshi-12929','少年行','韓翃','quantangshi','','卷13','千点斓斒玉勒骢，青丝结尾绣缠鬃。
鸣鞭晓出章台路，叶叶春衣杨柳风。','',''),('quantangshi-12930','题玉真观李祕书院','韓翃','quantangshi','','卷13','白云斜日影深松，玉宇瑶坛知几重。
把酒题诗人散后，华阳洞里有疎钟。','',''),('quantangshi-12931','送客之潞府','韓翃','quantangshi','','卷13','官柳青青匹马嘶，回风暮雨入铜鞮。
佳期别在春山里，应是人蓡五叶齐。','',''),('quantangshi-12932','送客贬五溪','韓翃','quantangshi','','卷13','南过猨声一逐臣，回看秋草泪霑巾。
寒天暮雪空山里，几处蛮家是主人。','',''),('quantangshi-12933','送齐山人归长白山','韓翃','quantangshi','','卷13','旧事仙人白兔公，掉头归去又乘风。
柴门流水依然在，一路寒山万木中。','',''),('quantangshi-12934','寄裴郓州','韓翃','quantangshi','','卷13','乌纱灵寿对秋风，怅望浮云济水东。
官树阴阴铃阁暮，州人转忆白头翁。','',''),('quantangshi-12935','梁城赠一二同幕','韓翃','quantangshi','','卷13','五营河畔列旌旗，吹角鸣鼙日暮时。
曾是信陵门下客，两回相吊不胜悲。','',''),('quantangshi-12936','河上寄故人','韓翃','quantangshi','','卷13','河流晓天，濮水清烟。
日暖昆吾台上，春深颛顼城边。
莺声乱啁鹄囗，花片细点龙泉。
西望情人早至，犹应得醉芳年。','',''),('quantangshi-12937','留题宁川香盖寺壁','韓翃','quantangshi','','卷13','爱远登高尘眼开。
为怜萧寺上经台，山川谁识龙蛇蛰。
天地自迎风雨来，柳放寒条秋已老。
雁摇孤翼暮空回，何人会得其中事。
又被残花落日催。','',''),('quantangshi-12938','寄柳氏','韓翃','quantangshi','','卷13','章台柳，章台柳，颜色青青今在否？纵使长条似旧垂，也应攀折他人手。','',''),('quantangshi-12939','海上寄萧立','獨孤及','quantangshi','','卷13','朔风剪塞草，寒露日夜结。
行行到瀛壖，归思生暮节。
驿楼见万里，延首望辽碣。
远海入大荒，平芜际穷发。
旧国在梦想，故人胡且越。
契阔阻风期，荏苒成雨别。
海西望京口，两地各天末。
索居动经秋，再笑知曷月。
日南望中尽，唯见飞鸟灭。
音尘未易得，何由慰饥渴。','',''),('quantangshi-12940','三月三日自京到华阴于水亭独酌寄裴六薛八','獨孤及','quantangshi','','卷13','祗役匪遑息，经时客三秦。
还家问节候，知到上巳辰。
山县何所有，高城闭青春。
和风不吾欺，桃杏满四邻。
旧友适远别，谁当接欢欣。
呼儿命长瓢，独酌湘吴醇。
一酌一朗咏，既酣意亦申。
言筌暂两忘，霞月祗相新。
裴子尘表物，薛侯席上珍。
寄书二傲吏，何日同车茵。
讵肯使空名，终然羁此身。
他年解桎梏，长作海上人。','',''),('quantangshi-12941','代书寄上裴六冀刘二颍','獨孤及','quantangshi','','卷13','昔余马首东，君在海北汭。
尽屏簿领书，相与议岩穴。
载来诣佳境，每山有车辙。
长啸林木动，高歌唾壶缺。
此辞月未周，虏马嘶绛阙。
猛虎踞大道，九州当中裂。
闻君弃孤城，犹自握汉节。
耻栖恶木影，忍与故山别。
脱舄挂岭云，冏然若鸟逝。
唯留潺湲水，分付练溪月。
尔来大谷梨，白花再成雪。
关梁限天险，欢乐竟两绝。
大盗近削平，三川今底宁。
句芒布春令，屏翳收雷霆。
伊洛日夜涨，鸣臯兰杜青。
骞骞两黄鹄，何处游青冥。
畴昔切玉刃，应如新发硎。
及时当树勋，高悬景钟铭。
莫抱白云意，径往丹丘庭。
功成傥长揖，然后谋沧溟。','',''),('quantangshi-12942','客舍月下对酒醉后寄毕四耀','獨孤及','quantangshi','','卷13','乡路风雪深，生事忧患迫。
天长波澜广，高举无六翮。
独立寒夜移，幽境思弥积。
霜月照胆净，银河入檐白。
沽酒聊自劳，开樽坐檐隙。
主人奏丝桐，能使高兴剧。
清机暂无累，献酢更络绎。
慷慨葛天歌，愔愔广陵陌。
既醉万事遗，耳热心亦适。
视身兀如泥，瞪目傲今昔。
故人间城阙，音信两脉脉。
别时前盟在，寸景莫自掷。
心与白日鬬，十无一满百。
寓形薪火内，甘作天地客。
与物无亲疎，斗酒胜竹帛。
何必用自苦，将贻古贤责。','',''),('quantangshi-12943','下弋阳江舟中代书寄裴侍御','獨孤及','quantangshi','','卷13','故乡隔西日，水去连长天。
前路知几许，但指天南边。
怆恨极浦外，隐映青山连。
东风满帆来，五两如弓弦。
遥羡绣衣客，冏然马首先。
得餐武昌鱼，不顾浔阳田。
屈指数别日，忽乎成两年。
百花已满眼，春草渐碧鲜。
岂是离居时，奈何于役牵。
洞庭有深涉，曷日期归旋。
且作异乡料，讵知携手缘。
离忧未易销，莫道樽酒贤。','',''),('quantangshi-12944','癸卯岁赴南丰道中闻京师失守寄权士繇韩幼深','獨孤及','quantangshi','','卷13','种田不遇岁，策名不遭时。
胡尘晦落日，西望泣路岐。
猛虎啸北风，麕麚皆载驰。
深泥驾疲牛，踸踔余何之。
诘屈白道转，缭绕清溪随。
荒谷啸山鬼，深林啼子规。
长叹指故山，三奏归来词。
不逢眼中人，调苦车逶迟。
士繇松筠操，幼深琼树姿。
别来平安否，何阶一申眉。
白云失帝乡，远水恨天涯。
昂藏双威凤，曷月还西枝。
努力爱华发，盛年振羽仪。
但令迍难康，不负沧洲期。
莫作新亭泣，徒使夷吾嗤。','',''),('quantangshi-12945','贾员外处见中书贾舍人巴陵诗集覧之怀旧代书寄赠','獨孤及','quantangshi','','卷13','海岸望青琐，云长天漫漫。
十年不一展，知有关山难。
适逢阮始平，立马问长安。
取公咏怀诗，示我江海澜。
暂若窥武库，森然矛戟寒。
眼明遗头风，心悦忘朝餐。
大驾今返正，熊罴扈鸣銮。
公游凤凰沼，献可在笔端。
系越有长缨，封关祗一丸。
冏然翔寥廓，仰望惭羽翰。
嘉会不我与，相思岁云殚。
唯当袖佳句，持比青琅玕。','',''),('quantangshi-12946','代书寄上李广州','獨孤及','quantangshi','','卷13','皖水望番禺，迢迢青天末。
鸿雁飞不到，音尘何由达。
独有舆人歌，隔云声喧聒。
皆称府君仁，百越赖全活。
推诚鱼鳖信，持正魑魅怛。
疲民保中和，性足无夭阏。
天子咨四岳，伫公济方割。
几时复旋归，入践青琐闼。
贱子托明德，缭若松上葛。
别离鄙恡生，结念思所豁。
门栏关山阻，岐路天地阔。
唯凭万里书，持用慰饥渴。','',''),('quantangshi-12947','夏中酬于逖毕耀问病见赠','獨孤及','quantangshi','','卷13','救物智所昧，学仙愿未从。
行藏两乖角，蹭蹬风波中。
薄宦耻降志，卧疴非养蒙。
闭关涉两旬，羇思浩无穷。
鸑鷟何处来，双舞下碧空。
离别隔云雨，惠然此相逢。
把手贺疾间，举杯欣酒浓。
新诗见久要，清论激深衷。
高馆舒夜簟，开门延微风。
火云赫嵯峨，日暮千万峯。
遥指故山笑，相看抚号钟。
声和由心清，事感知气同。
出处未易料，且歌缓愁容。
愿君崇明德，岁暮如青松。','',''),('quantangshi-12948','酬梁二十宋中所赠兼留别梁少府','獨孤及','quantangshi','','卷13','少读黄帝书，肯不笑机事。
意犹负深衷，未免名迹累。
厌贫学干禄，欲徇宾王利。
甘为风波人，岂复江海意。
担簦平台下，是日饮羇思。
逢君道寸心，暂喜一交臂。
绪言未及竟，离念已复至。
甯[陵]望南丘，云雨成两地。
途殊迹方间，河广流且驶。
暮帆望不及，览赠心欲醉。
爱君如金锡，昆弟皆茂异。
奕赫连丝衣，荣养能锡类。
君子道未长，深藏青云器。
巨鳞有纵时，今日不足议。
唯当加餐饭，好我袖中字。
别离动经年，莫道分首易。','',''),('quantangshi-12949','庚子岁避地至玉山酬韩司马所赠','獨孤及','quantangshi','','卷13','沧海疾风起，洪波骇恬鳞。
已无济川分，甘作乘桴人。
挥手谢秣陵，举帆指瓯闽。
安和风尘表，偶与琼瑶亲。
共悲行路难，况逢江南春。
故园忽如梦，返复知何辰。
旷野豺虎满，深山兰蕙新。
枉君灞陵什，廻首徒酸辛。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-12950','奉和李大夫同吕评事太行苦热行兼寄院中诸公','獨孤及','quantangshi','','卷13','驷马上太行，修途亘辽碣。
王程无留驾，日昃未遑歇。
请问此何时，恢台朱明月。
长蛇稽天讨，上将方北伐。
明主命使臣，皇华得时杰。
已忘羊肠险，岂惮湿风热。
摇策汗滂沧，登岸思纡结。
炎云如烟火，溪谷将恐竭。
昼景赩可畏，凉飙何由发。
山长飞鸟堕，目极行车绝。
赵魏方俶扰，安危俟明哲。
归路岂不怀，饮冰有苦节。
会同传檄至，疑议立谈决。
况有阮元瑜，翩翩秉书札。
起予歌赤坂，永好逾白雪。
谁念剖竹人，无因执羁绁。','',''),('quantangshi-12951','酬皇甫侍御望天灊山见示之作','獨孤及','quantangshi','','卷13','早岁慕五岳，尝为尘机碍。
孰知天柱峯，今与郡斋对。
隐嶙抱元气，氤氲含青霭。
云崖媚远空，石壁寒古塞。
汉皇南游日，望秩此昭配。
法驾到谷口，礼容振荒外。
焚柴百神趋，执玉万方会。
天旋物顺动，德布泽霶霈。
讲武威已耀，学仙功未艾。
黄金竟何成，洪业遽沦昧。
度世若一瞬，昨朝已千载。
如今封禅坛，唯见云雨晦。
长望哀往古，劳生惭大块。
清晖幸相娱，幽独知所赖。
寒城春方正，初日明可爱。
万殊喜阳和，余亦荷时泰。
山色日夜绿，下有清浅濑。
愧作拳偻人，沈迷簿书内。
登临叹拘限，出处悲老大。
况听郢中曲，复识湘南态。
思免物累牵，敢令道机退。
瞒然诵佳句，持此秋兰佩。','',''),('quantangshi-12952','送陈兼应辟兼寄高适贾至','獨孤及','quantangshi','','卷13','结绿处燕石，卞和不必知。
所以王佐才，未能忘茅茨。
罢官梁山外，获稻楚水湄。
适会傅岩人，虚舟济川时。
天网忽摇顿，公才难弃遗。
凤凰翔千仞，今始一鸣岐。
上马指国门，举鞭射书帷。
预知大人赋，掩却归来词。
天子方在宥，朝廷张四维。
料君能献可，努力副畴咨。
旧友满皇州，高冠飞翠蕤。
相逢绛阙下，应道轩车迟。
高侯秉戎翰，策马观西夷。
方从幕中事，参谋王者师。
贾生去洛阳，焜耀琳琅姿。
芳名动北步，逸韵陵南皮。
肃肃举鸿毛，冷然顺风吹。
波流有同异，由是限别离。
汉塞隔陇底，秦川连镐池。
白云日夜满，道里安可思。
梦想浩盈积，物华愁变衰。
因君附错刀，送远益凄其。
四海各横绝，九霄应易期。
不知故巢燕，决起栖何枝。','',''),('quantangshi-12953','送相里郎中赴江西','獨孤及','quantangshi','','卷13','君把一尺诏，南游济沧浪。
受恩忘险艰，不道歧路长。
戎狄方构患，休牛殊未遑。
三秦千仓空，战卒如饿狼。
委输资外府，诹谋寄贤良。
有才当陈力，安得遂翱翔。
岂不慎井赋，赋均人亦康。
遥知轩车到，万室安耕桑。
火伏金气腾，昊天欲苍茫。
寒蝉惨巴邓，秋色愁沅湘。
昨日携手西，于今芸再黄。
欢娱讵几许，复向天一方。
蹢躅话世故，惆怅举离觞。
共求数刻欢，戏谑君此堂。
今日把手笑，少时各他乡。
身名同风波，聚散未易量。
曷月还朝天，及时开智囊。
前期傥犹阔，加饭勉自强。','',''),('quantangshi-12954','观海','獨孤及','quantangshi','','卷13','北登渤澥岛，廻首秦东门。
谁尸造物功，凿此天池源。
澒洞吞百谷，周流无四垠。
廓然混茫际，望见天地根。
白日自中吐，扶桑如可扪。
超遥蓬莱峰，想像金台存。
秦帝昔经此，登临冀飞翻。
扬旌百神会，望日羣山奔。
徐福竟何成，羡门徒空言。
唯见石桥足，千年潮水痕。','',''),('quantangshi-12955','初晴抱琴登马退山对酒望远醉后作','獨孤及','quantangshi','','卷13','年长心易感，况为忧患缠。
壮图迫世故，行止两茫然。
王旅方伐叛，虎臣皆被坚。
鲁人着儒服，甘就南山田。
挈榼上高磴，超遥望平川。
沧江大如綖，隐映入远天。
荒服何所有，山花雪中然。
寒泉得日景，吐溜鸣湔湔。
举酒劝白云，唱歌慰颓年。
微风度竹来，韵我号钟弦。
一弹一引满，耳热知心宣。
曲终余亦酣，起舞山水前。
人生几何时，太半百忧煎。
今日羇愁破，始知浊酒贤。','',''),('quantangshi-12956','同徐侍郎五云溪新庭重阳宴集作','獨孤及','quantangshi','','卷13','万峰苍翠色，双溪清浅流。
已符东山趣，况值江南秋。
白露天地肃，黄花门馆幽。
山公惜美景，肯为芳樽留。
五马照池塘，繁弦催献酬。
临风孟嘉帽，乘兴李膺舟。
骋望傲千古，当歌遗四愁。
岂令永和人，独擅山阴游。','',''),('quantangshi-12957','雨晴后陪王员外泛后湖得溪字','獨孤及','quantangshi','','卷13','远山媚平楚，宿雨涨清溪。
沿溯任舟檝，欢言无町畦。
酒酣相视笑，心与白鸥齐。','',''),('quantangshi-12958','题思禅寺上方','獨孤及','quantangshi','','卷13','溪口闻法鼓，停桡登翠屏。
攀云到金界，合掌开禅扃。
郁律众山抱，空蒙花雨零。
老僧指香楼，云是不死庭。
眇眇于越路，茫茫春草青。
远山喷百谷，缭绕驰东溟。
目极道何在，境照心亦冥。
騞然诸根空，破结如破瓶。
下视三界狭，但闻五浊腥。
山中有良药，吾欲隳天形。','',''),('quantangshi-12959','季冬自嵩山赴洛道中作','獨孤及','quantangshi','','卷13','皇运偶中变，长蛇食中土。
天盖西北倾，众星陨如雨。
胡尘动地起，千里闻战鼓。
死人成为阜，流血涂草莽。
策马何纷纷，捐躯抗豺虎。
甘心赴国难，谁谓荼叶苦。
天子初受命，省方造区宇。
斩鲸安溟波，截鳌作天柱。
三微复正统，五玉归文祖。
不图汉官仪，今日忽再覩。
升高望京邑，佳气连海浦。
宝鼎歊景云，明堂舞干羽。
虎臣囗激昂，囗囗囗御侮。
腐儒着缝掖，何处议邹鲁。
西上轘辕山，丘陵横今古。
和气蒸万物，腊月春霭吐。
得为太平人，穷达不足数。
他日遇封禅，着书继三五。','',''),('quantangshi-12960','早发若岘驿望庐山','獨孤及','quantangshi','','卷13','雨罢山翠鲜，泠泠东风好。
断崖云生处，是向峯顶道。
谁谓峯顶远，跂予可瞻讨。
忘缘祛天机，脱屐恨不早。
祗恐岁云暮，遂与空名老。
心往迹未并，惭愧山上草。','',''),('quantangshi-12961','寒夜溪行舟中作','獨孤及','quantangshi','','卷13','日沈诸山昏，寂历羣动宿。
孤舟独不系，风水夜相逐。
云归恒星白，霜下天地肃。
月轮大如盘，金波入空谷。
魏阙万里道，羇念千虑束。
倦飞思故巢，敢望桐与竹。
沈吟登楼赋，中夜起三复。
忧来无良方，归候春酒熟。','',''),('quantangshi-12962','壬辰岁过旧居','獨孤及','quantangshi','','卷13','少年事远游，出入燕与秦。
离居岁周天，犹作劳歌人。
负劒渡颍水，归马自知津。
缘源到旧庐，揽涕寻荒榛。
邻里喜相劳，壶觞展殷勤。
酒兰击筑语，及此离会因。
丈夫随世波，岂料百年身。
今日负鄙愿，多慙故山春。','',''),('quantangshi-12963','丙戌岁正月出洛阳书怀','獨孤及','quantangshi','','卷13','往岁衣褐见，受服金马门。
拟将忠与贞，来酬主人恩。
天地暂雷雨，洪波生平原。
穷鳞遂蹭蹬，夙昔事罕存。
幸逢帝出震，授钺清东藩。
白日忽再中，万方咸骏奔。
王风从西来，春光满干坤。
蛰虫竞飞动，余亦辞笼樊。
遭遇思自强，宠辱安足言。
唯将四方志，廻首谢故园。','',''),('quantangshi-12964','伤春怀归','獨孤及','quantangshi','','卷13','谁谓乡可望，望在天地涯。
但有时命同，万里共岁华。
昨夜南山雨，殷雷坼萌芽。
源桃不余欺，先发秦人家。
寂寂户外掩，迟迟春日斜。
源桃默无言，秦人独长嗟。
不惜中肠苦，但言会合赊。
思归吾谁诉，笑向南枝花。','',''),('quantangshi-12965','杂诗','獨孤及','quantangshi','','卷13','百花结成子，春物舍我去。
流年惜不得，独坐空闺暮。
心自有所待，甘为物华悞。
未必千黄金，买得一人顾。','',''),('quantangshi-12966','山中春思','獨孤及','quantangshi','','卷13','獭祭川水大，人家春日长。
独谣昼不暮，搔首慙年芳。
靡草知节换，含葩向新阳。
不嫌三径深，为我生池塘。
亭午井竈闲，雀声响空仓。
花落没屐齿，风动羣木香。
归路云水外，天涯杳茫茫。
独卷万里心，深入山鸟行。
芳景勿相迫，春愁未遽忘。','',''),('quantangshi-12967','雨后公超谷北原眺望寄高拾遗','獨孤及','quantangshi','','卷13','崖口雨足收，清光洗高天。
虹霓敛残霭，山水含碧鲜。
远空霞破露月轮，薄云片片成鱼鳞。
五陵如荠渭如带，目极千里关山春。
朝来爽气未易说，画取花峯赠远人。','',''),('quantangshi-12968','自东都还濠州奉酬王八谏议见赠','獨孤及','quantangshi','','卷13','关西仕时俱稚容，彪彪之鬓始相逢。
天地变化县城改，独有故人交态在。
不言会合迹未并，犹以岁寒心相待。
洛阳居守寄酇侯，君着貂冠参运筹。
高阁连云骑省夜，新文会友凉风秋。
青袍白面昔携手，冉冉府趋君记否。
云分雨散十五年，始得一笑樽酒前。
未遑少留骤远别，况值旅雁鸣秋天。
二华旧游如梦想，他时再会何由缘。
赖君赠我郢中曲，别后相思被管弦。','',''),('quantangshi-12969','官渡柳歌送李员外承恩往扬州觐省','獨孤及','quantangshi','','卷13','君不见官渡河两岸，三月杨柳枝。
千条万条色，一一胜绿丝。
花作铅粉絮，叶成翠羽帐。
此时送远人，怅望春水上。
远客折杨柳，依依两含情。
夹郎木兰舟，送郎千里行。
郎把紫泥书，东征觐庭闱。
脱却貂襜褕，新着五彩衣。
双凤并两翅，将雏东南飞。
五两得便风，几日到扬州。
莫贪扬州好，客行剩淹留。
郎到官渡头，春阑已应久。
殷勤道远别，为谢大堤柳。
攀条傥相忆，五里一回首。
明年柳枝黄，问郎还家否。','',''),('quantangshi-12970','东平蓬莱驿夜宴平卢杨判官醉后赠别姚太守置酒留宴','獨孤及','quantangshi','','卷13','驿楼涨海壖，秋月寒城边。
相见自不足，况逢主人贤。
夜清酒浓人如玉，一斗何啻直十千。
木兰为樽金为杯，江南急管卢女弦。
齐童如花解郢曲，起舞激楚歌采莲。
固知别多相逢少，乐极哀至心婵娟。
少留莫辞醉，前路方悠然。
明日分飞傥相忆，祗应遥望西南天。','',''),('quantangshi-12971','同岑郎中屯田韦员外花树歌','獨孤及','quantangshi','','卷13','东风动地吹花发，渭城桃李千树雪。
芳菲可爱不可留，武陵归客心欲绝。
金华省郎惜佳辰，秪持棣蕚照青春。
君家自是成蹊处，况有庭花作主人。','',''),('quantangshi-12972','和李尚书画射虎图歌','獨孤及','quantangshi','','卷13','饥虎呀呀立当路，万夫震恐百兽怒。
彤弓金镞当者谁，鸣鞭飞控流星驰。
居然画中见真态，若务除恶不顾私。
时和年丰五兵已，白额未诛壮士耻。
分铢远迩悬彀中，不中不发思全功。
舍矢如破石可裂，应弦尽敌山为空。
杀气满堂观者骇，飒若崖谷生长风。
精微入神在毫末，作缋造物可同功。
方叔秉钺受命新，丹青起予气益振。
底绥静难巧可拟，嗟叹不足声成文。
他时代天育万物，亦以此道安斯民。','',''),('quantangshi-12973','和赠远','獨孤及','quantangshi','','卷13','忆得去年春风至，中庭桃李映琐窗。
美人挟瑟对芳树，玉颜亭亭与花双。
今年新花如旧时，去年美人不在兹。
借问离居恨深浅，祗应独有庭花知。','',''),('quantangshi-12974','和题藤架','獨孤及','quantangshi','','卷13','䔿䔿叶成幄，璀璀花落架。
花前离心苦，愁至无日夜。
人去藤花千里强，藤花无主为谁芳。
相思历乱何由尽，春日迢迢如线长。','',''),('quantangshi-12975','江上代书寄裴使君','獨孤及','quantangshi','','卷13','何地离念剧，江臯风雪时。
艰难伤远道，老大怯前期。
畴昔行藏计，祗将力命推。
能令书信数，犹足缓相思。','',''),('quantangshi-12976','诣开悟禅师问心法次第寄韩郎中','獨孤及','quantangshi','','卷13','障深闻道晚，根钝出尘难。
浊劫相从惯，迷途自谓安。
得知身垢妄，始喜额珠完。
欲识真如理，君尝法味看。','',''),('quantangshi-12977','登后湖伤春怀京师故旧','獨孤及','quantangshi','','卷13','昨日看摇落，惊秋方怨咨。
几经开口笑，复及看花时。
世事空名束，生涯素发知。
山山春草满，何处不相思。','',''),('quantangshi-12978','暮春于山谷寺上方遇恩命加官赐服酬皇甫侍御见贺之作','獨孤及','quantangshi','','卷13','天书到法堂，朽质被荣光。
自笑无功德，殊恩谬激扬。
还登建礼署，犹忝会稽章。
佳句慙相及，称仁岂易当。','',''),('quantangshi-12979','答李滁州题庭前石竹花见寄','獨孤及','quantangshi','','卷13','殷疑曙霞染，巧类匣刀裁。
不怕南风热，能迎小暑开。
游蜂怜色好，思妇感年催。
览赠添离恨，愁肠日几廻。','',''),('quantangshi-12980','得李滁州书以玉潭庄见托因书春思以诗代答','獨孤及','quantangshi','','卷13','春物行将老，怀君意讵堪。
朱颜因酒强，白发对花慙。
日日思琼树，书书话玉潭。
知同百口累，曷日办抽簪。','',''),('quantangshi-12981','答李滁州忆玉潭新居见寄','獨孤及','quantangshi','','卷13','从来招隐地，未有剖符人。
山水能成癖，巢夷拟独亲。
猪肝无足累，马首敢辞勤。
扫洒潭中月，他时望德邻。','',''),('quantangshi-12982','将赴京答李纾赠别','獨孤及','quantangshi','','卷13','胶漆常投分，荆蛮各倦游。
帝乡今独往，沟水便分流。
甘作远行客，深慙不系舟。
思君带将缓，岂直日三秋。','',''),('quantangshi-12983','和张大夫秋日有怀呈院中诸公','獨孤及','quantangshi','','卷13','至公无暇日，高阁闭秋天。
肘印拘王事，篱花思长年。
绩成心不有，虑澹物犹牵。
窃效泉鱼跃，因闻郢曲妍。','',''),('quantangshi-12984','和大夫秋夜书情即事','獨孤及','quantangshi','','卷13','上略当分阃，高情善闭关。
忘机羣动息，无战五兵闲。
铃阁风传漏，书窗月满山。
方知秋兴作，非惜二毛斑。','',''),('quantangshi-12985','送虢州王录事之任','獨孤及','quantangshi','','卷13','谓子文章达，当年羽翼高。
一经俄白首，三命尚青袍。
未遇须藏器，安卑莫告劳。
盘根傥相值，试用发硎刀。','',''),('quantangshi-12986','送长孙将军拜歙州之任','獨孤及','quantangshi','','卷13','临难敢横行，遭时取盛名。
五兵常典校，四十又专城。
浪逐楼船破，风从虎竹生。
岛夷今可料，系颈有长缨。','',''),('quantangshi-12987','送何员外使湖南','獨孤及','quantangshi','','卷13','夙昔皆黄绶，差池复琐闱。
上田无晚熟，逸翮果先飞。
前路舟休系，故山云不归。
王程傥未复，莫遣鲤书稀。','',''),('quantangshi-12988','送江陵全少卿赴府任','獨孤及','quantangshi','','卷13','冢司方眘选，剧县得英髦。
固是攀云渐，何嗟趋府劳。
楚山迎驿路，汉水涨秋涛。
骞翥方兹始，看君六翮高。','',''),('quantangshi-12989','送虞秀才擢第归长沙','獨孤及','quantangshi','','卷13','充赋名今遂，安亲事不违。
甲科文比玉，归路锦为衣。
海运同鵾化，风帆若鸟飞。
知君到三迳，松菊有光辉。','',''),('quantangshi-12990','送阳翟张主簿之任','獨孤及','quantangshi','','卷13','旧闻阳翟县，西接凤高山。
作吏同山隐，知君处剧闲。
少年当効用，远道岂辞艰。
迟子扬名后，方期彩服还。','',''),('quantangshi-12991','送游员外赴淮西','獨孤及','quantangshi','','卷13','多君有奇略，投笔佐元戎。
已佩郎官印，兼乘御史骢。
使星随驿骑，归路有秋风。
莫道无书札，他年怀袖空。','',''),('quantangshi-12992','送马郑州','獨孤及','quantangshi','','卷13','使君朱两轓，春日整东辕。
芳草成臯路，青山凉水源。
勉修循吏迹，以谢主人恩。
当使仁风动，遥听舆颂喧。','',''),('quantangshi-12993','送义乌韦明府','獨孤及','quantangshi','','卷13','妙年能致身，陈力复安亲。
不惮关山远，宁辞簿领勤。
过江云满路，到县海为邻。
每叹违心赏，吴门正早春。','',''),('quantangshi-12994','送陈王府张长史还京','獨孤及','quantangshi','','卷13','论齿弟兄列，为邦前后差。
十年方一见，此别复何嗟。
极目故关道，伤心南浦花。
少时相忆处，招手望行车。','',''),('quantangshi-12995','水西馆泛舟送王员外','獨孤及','quantangshi','','卷13','单醪敢献酢，曲沼荷经过。
泛览亲鱼鸟，夤缘涉芰荷。
剧谈增惠爱，美景借清和。
明日汀洲草，依依奈别何。','',''),('quantangshi-12996','李卿东池夜宴得池字','獨孤及','quantangshi','','卷13','政成机不扰，心惬宴忘疲。
去烛延高月，倾罍就小池。
舞盘廻雪动，弦奏跃鱼随。
自是山公兴，谁令下士知。','',''),('quantangshi-12997','九月九日李苏州东楼宴','獨孤及','quantangshi','','卷13','是菊花开日，当君乘兴秋。
风前孟嘉帽，月下庾公楼。
酒解留征客，歌能破别愁。
醉归无以赠，祗奉万年酬。','',''),('quantangshi-12998','萧文学山池宴集','獨孤及','quantangshi','','卷13','檀栾千亩绿，知是辟疆园。
远岫当庭户，诸花覆水源。
主人邀尽醉，林鸟助狂言。
莫问愁多少，今皆付酒樽。','',''),('quantangshi-12999','与韩侍御同寻李七舍人不遇题壁留赠','獨孤及','quantangshi','','卷13','三径何寂寂，主人山上山。
亭空檐月在，水落钓矶闲。
药院鸡犬静，酒垆苔藓班。
知君少机事，当待暮云还。','',''),('quantangshi-13000','喜辱韩十四郎中书兼封近诗示代书题赠','獨孤及','quantangshi','','卷13','各牵于役间游遨，独坐相思正郁陶。
长跪读书心蹔缓，短章投我曲何高。
宦情缘木知非愿，王事敦人敢告劳。
所叹在官成远别，徒言岏水才容舠。','',''),('quantangshi-13001','早发龙沮馆舟中寄东海徐司仓郑司户','獨孤及','quantangshi','','卷13','沙禽相呼曙色分，渔浦鸣桹十里闻。
正当秋风渡楚水，况值远道伤离羣。
津头却望后湖岸，别处已隔东山云。
停舻目送北归翼，惜无瑶华持寄君。','',''),('quantangshi-13002','酬常郿县见赠','獨孤及','quantangshi','','卷13','爱君修政若修身，鳏寡来归乳雉驯。
堂上五弦销暇日，邑中千室有阳春。
谓乘凫舄朝天子，却愧猪肝累主人。
辞后读君怀县作，定知三岁字犹新。','',''),('quantangshi-13003','登山谷寺上方答皇甫侍御卧疾阙陪车骑之后','獨孤及','quantangshi','','卷13','梵宫香阁攀霞上，天柱孤峯指掌看。
汉主马踪成蔓草，法王身相示空棺。
云扶踊塔青霄庳，松荫禅庭白日寒。
不见戴逵心莫展，赖将新赠比琅玕。','',''),('quantangshi-13004','答皇甫十六侍御北归留别作','獨孤及','quantangshi','','卷13','正当楚客伤春地，岂是骚人道别时。
俱徇空名嗟欲老，况将行役料前期。
劳生多故应同病，羸马单车莫自悲。
明日相望隔云水，解颜唯有袖中诗。','',''),('quantangshi-13005','答李滁州见寄','獨孤及','quantangshi','','卷13','相逢遽叹别离牵，三见江臯惠草鲜。
白发俱生欢未再，沧州独往意何坚。
愁看郡内花将歇，忍过山中月屡圆。
终日望君休汝骑，愧无堪报起予篇。','',''),('quantangshi-13006','得柳员外书封寄近诗书中兼报新主行营兵马因代书戏答','獨孤及','quantangshi','','卷13','郎官作掾心非好，儒服临戎政已闻。
说劒尝宗漆园吏，戒严应笑棘门军。
遥知抵掌论皇道，时复吟诗向白云。
百越待君言即叙，相思不敢怆离羣。','',''),('quantangshi-13007','同皇甫侍御斋中春望见示之作','獨孤及','quantangshi','','卷13','望远思归心易伤，况将衰鬓偶年光。
时攀芳树愁花尽，昼掩高斋厌日长。
甘比流波辞旧浦，忍看新草遍横塘。
因君赠我江枫咏，春思如今未易量。','',''),('quantangshi-13008','伤春赠远','獨孤及','quantangshi','','卷13','去水流年日并驰，年光客思两相随。
咨嗟斑鬓今承弁，慙愧新荷又发池。
杨柳逶迤愁远道，鹧鸪啁哳怨南枝。
忆君何啻同琼树，但向春风送别离。','',''),('quantangshi-13009','奉和中书常舍人晚秋集贤院即事寄赠徐薛二侍御','獨孤及','quantangshi','','卷14','汉家金马署，帝座紫微郎。
图籍淩羣玉，歌诗冠柏梁。
阴阴万年树，肃肃五经堂。
挥翰忘朝食，研精待夕阳。
晴空露盘迥，秋月琐窗凉。
远兴生斑鬓，高情寄缥囊。
葳蕤双鸑鷟，夙昔并翱翔。
汲冢同刊谬，蓬山共补亡。
差池摧羽翮，流落限江湘。
禁省一分袂，昊天三雨霜。
石渠遗迹满，水国暮云长。
早晚朝宣室，归时道路光。','',''),('quantangshi-13010','江宁酬郑县刘少府兄赠别作','獨孤及','quantangshi','','卷14','往年脱缝掖，接武仕关西。
结绶腰章并，趋堦手板齐。
仙山不用买，朋酒日相携。
抵掌夸潭壑，忘情向组圭。
事迁时既往，年长迹逾暌。
何为青云器，犹嗟浊水泥。
役牵方远别，道在或先迷。
莫见良田晚，遭时亦杖藜。','',''),('quantangshi-13011','送李宾客荆南迎亲','獨孤及','quantangshi','','卷14','宗室刘中垒，文场谢客儿。
当为天北斗，曾使海西陲。
毛节精诚着，铜楼羽翼施。
还申供帐别，言赴倚门期。
恩渥霑行李，晨昏在路岐。
君亲两报遂，不敢议伤离。','',''),('quantangshi-13012','题玉潭','獨孤及','quantangshi','','卷14','碧玉徒强名，冰壶难比德。
唯当寂照心，可并奫沦色。','',''),('quantangshi-13013','海上怀华中旧游寄郑县刘少府造渭南王少府崟','獨孤及','quantangshi','','卷14','凉风台上三峯月，不夜城边万里沙。
离别莫言关塞远，梦魂长在子真家。','',''),('quantangshi-13014','和虞部韦郎中寻杨驸马不遇','獨孤及','quantangshi','','卷14','金屋琼台萧史家，暮春三月渭州花。
到君仙洞不相见，谓已吹箫乘早霞。','',''),('quantangshi-13015','李张皇甫阎权等数公并有送别之作见寄因答','獨孤及','quantangshi','','卷14','洞庭正波苹叶衰，岂是秦吴远别时。
谢君箧中绮端赠，何以报之长相思。','',''),('quantangshi-13016','将还越留别豫章诸公','獨孤及','quantangshi','','卷14','客鸟倦飞思旧林，裴徊犹恋众花阴。
他时相忆双航苇，莫问吴江深不深。','',''),('quantangshi-13017','送别荆南张判官','獨孤及','quantangshi','','卷14','輶车骆马往从谁，梦浦兰台日更迟。
欲识桃花最多处，前程问取武陵儿。','',''),('quantangshi-13018','陪王员外北楼宴待月','獨孤及','quantangshi','','卷14','劝酒论心夜不疲，含情有待问谁思。
伫看晴月澄澄影，来照江楼酩酊时。','',''),('quantangshi-13019','垂花坞醉后戏题','獨孤及','quantangshi','','卷14','紫蔓青条拂酒壶，落花时与竹风俱。
归时自负花前醉，笑向鯈鱼问乐无。','',''),('quantangshi-13020','题刘相公三湘图','郎士元','quantangshi','','卷14','昔别醉衡霍，迩来忆南州。
今朝平津邸，兼得潇湘游。
稍辨郢门树，依然芳杜洲。
微明三巴峡，咫尺万里流。
飞鸟不知倦，远帆生暮愁。
涔阳指天末，北渚空悠悠。
枕上见渔父，坐中常狎鸥。
谁言魏阙下，自有东山幽。','',''),('quantangshi-13021','长安逢故人','郎士元','quantangshi','','卷14','数年音信断，不意在长安。
马上相逢久，人中欲认难。
一官今嬾道，双鬓竟羞看。
莫问生涯事，只应持钓竿。','',''),('quantangshi-13022','送韦湛判官','郎士元','quantangshi','','卷14','高阁晴江上，重阳古戍闲。
聊因送归客，更此望乡山。
惜别心能醉，经秋鬓自斑。
临流兴不尽，惆怅水云间。','',''),('quantangshi-13023','送长沙韦明府','郎士元','quantangshi','','卷14','秋入长沙县，萧条旅宦心。
烟波连桂水，官舍映枫林。
云日楚天暮，沙汀白露深。
遥知讼堂里，佳政在鸣琴。','',''),('quantangshi-13024','送孙愿','郎士元','quantangshi','','卷14','悠然富春客，忆与暮潮归。
擢第人多羡，如君独步稀。
乱流江渡浅，远色海山微。
若访新安路，严陵有钓矶。','',''),('quantangshi-13025','送林宗配雷州','郎士元','quantangshi','','卷14','昨日三峰尉，今朝万里人。
平生任孤直，岂是不防身。
海雾多为瘴，山雷乍作隣。
遥怜北户月，与子独相亲。','',''),('quantangshi-13026','送洪州李别驾之任','郎士元','quantangshi','','卷14','南去秋江远，孤舟兴自多。
能将流水引，更入洞庭波。
夏口帆初上，浔阳雁正过。
知音在霄汉，佐郡岂蹉跎。','',''),('quantangshi-13027','送杨中丞和蕃','郎士元','quantangshi','','卷14','锦车登陇日，边草正萋萋。
旧好寻君长，新愁听鼓鼙。
河源飞鸟外，雪岭大荒西。
汉垒今犹在，遥知路不迷。','',''),('quantangshi-13028','送李将军赴定州','郎士元','quantangshi','','卷14','双旌汉飞将，万里授横戈。
春色临边尽，黄云出塞多。
鼓鼙悲绝漠，烽戍隔长河。
莫断阴山路，天骄已请和。','',''),('quantangshi-13029','关羽祠送高员外还荆州','郎士元','quantangshi','','卷14','将军禀天姿，义勇冠今昔。
走马百战场，一剑万人敌。
虽为感恩者，竟是思归客。
流落荆巫间，裴回故乡隔。
离筵对祠宇，洒酒暮天碧。
去去勿复言，衔悲向陈迹。','',''),('quantangshi-13030','送张南史','郎士元','quantangshi','','卷14','雨余深巷静，独酌送残春。
车马虽嫌僻，莺花不弃贫。
虫丝黏户网，鼠迹印牀尘。
借问山阳会，如今有几人。','',''),('quantangshi-13031','送奚贾归吴','郎士元','quantangshi','','卷14','东南富春渚，曾是谢公游。
今日奚生去，新安江正秋。
水清迎过客，霜叶落行舟。
遥想赤亭下，闻猨应夜愁。','',''),('quantangshi-13032','送陆员外赴潮州','郎士元','quantangshi','','卷14','含香台上客，剖竹海边州。
楚地多归信，闽溪足乱流。
今朝永嘉兴，重见谢公游。','',''),('quantangshi-13033','送裴补阙入河南幕','郎士元','quantangshi','','卷14','皎然青琐客，何事动行轩。
苦节酬知己，清吟去掖垣。
秋城临海树，寒月上营门。
邹鲁诗书国，应无鼙鼓喧。','',''),('quantangshi-13034','送韩司直路出延陵','郎士元','quantangshi','','卷14','游吴还适越，来往任风波。
复送王孙去，其如春草何。
岸明残雪在，潮满夕阳多。
季子留遗庙，停舟试一过。','',''),('quantangshi-13035','盩厔县郑礒宅送钱大','郎士元','quantangshi','','卷14','暮蝉不可听，落叶岂堪闻。
共是悲秋客，那知此路分。
荒城背流水，远雁入寒云。
陶令门前菊，余花可赠君。','',''),('quantangshi-13036','送元诜还丹阳别业','郎士元','quantangshi','','卷14','已知成傲吏，复见解朝衣。
应向丹阳郭，秋山独掩扉。
草堂连古寺，江日动晴晖。
一别沧州远，兰桡几岁归。','',''),('quantangshi-13037','送崔侍御往容州宣慰','郎士元','quantangshi','','卷14','秦原独立望湘川，击隼南飞向楚天。
奉诏不言空问俗，清时因得访遗贤。
荆门晓色兼梅雨，桂水春风过客船。
畴昔常闻陆贾说，故人今日岂徒然。','',''),('quantangshi-13038','朱方南郭留别皇甫冉','郎士元','quantangshi','','卷14','萦回枫叶岸，留滞木兰桡。
吴岫新经雨，江天正落潮。
故人劳见爱，行客自无憀。
若问前程事，孤云入剡遥。','',''),('quantangshi-13039','赠张五諲归濠州别业','郎士元','quantangshi','','卷14','常知罢官意，果与世人疎。
复此凉风起，仍闻濠上居。
故山期采菊，秋水忆观鱼。
一去蓬蒿径，羡君闲有余。','',''),('quantangshi-13040','送王司马赴润州','郎士元','quantangshi','','卷14','暂屈文为吏，聊将禄代耕。
金陵且不远，山水复多名。
楚塞因高出，寒潮入夜生。
离心逐春草，直到建康城。','',''),('quantangshi-13041','留卢秦卿','郎士元','quantangshi','','卷14','知有前期在，欢如此夜中。
无将故人酒，不及古淳风。','',''),('quantangshi-13042','赠强山人','郎士元','quantangshi','','卷14','或掉轻舟或杖藜。
寻常适意钓前溪，草堂竹迳在何处。
落日孤烟寒渚西。','',''),('quantangshi-13043','赠韦司直','郎士元','quantangshi','','卷14','闻君感叹二毛初，旧友相依万里余。
烽火有时惊暂定，甲兵无处可安居。
客来吴地星霜久，家在平陵音信疎。
昨日风光还入户，登山临水意何如。','',''),('quantangshi-13044','石城馆酬王将军','郎士元','quantangshi','','卷14','谁能绣衣客，肯驻木兰舟。
连雁沙边至，孤城江上秋。
归帆背南浦，楚塞入西楼。
何处看离思，沧波日夜流。','',''),('quantangshi-13045','酬王季友题半日村别业兼呈李明府','郎士元','quantangshi','','卷14','村映寒原日已斜，烟生密竹早归鸦。
长溪南路当羣岫，半景东隣照数家。
门通小径连芳草，马饮春泉踏浅沙。
欲待主人林上月，还思潘岳县中花。','',''),('quantangshi-13046','酬二十八秀才见寄','郎士元','quantangshi','','卷14','昨夜山月好，故人果相思。
清光到枕上，袅袅凉风时。
永意能在我，惜无携手期。','',''),('quantangshi-13047','冬夕寄青龙寺源公','郎士元','quantangshi','','卷14','歛屦入寒竹，安禅过漏声。
高松残子落，深井冻痕生。
罢磬风枝动，悬灯雪屋明。
何当招我宿，乘月上方行。','',''),('quantangshi-13048','塞下曲','郎士元','quantangshi','','卷14','宝刀塞下儿，身经百战曾百胜。
壮心竟未嫖姚知，白草山头日初没。
黄沙戍下悲歌发，萧条夜静边风吹，独倚营门望秋月。','',''),('quantangshi-13049','柏林寺南望','郎士元','quantangshi','','卷14','溪上遥闻精舍钟，泊舟微径度深松。
青山霁后云犹在，画出东南四五峰。','',''),('quantangshi-13050','宿杜判官江楼','郎士元','quantangshi','','卷14','适楚岂吾愿，思归秋向深。
故人江楼月，永夜千里心。
叶落觉乡梦，鸟啼惊越吟。
寥寥更何有，断续空城砧。','',''),('quantangshi-13051','春宴王补阙城东别业','郎士元','quantangshi','','卷14','柳陌乍随州势转，花源忽傍竹阴开。
能将瀑水清人境，直取流莺送酒杯。
山下古松当绮席，檐前片雨滴春苔。
地主同声复同舍，留欢不畏夕阳催。','',''),('quantangshi-13052','郢城西楼吟','郎士元','quantangshi','','卷14','连山尽处水萦回，山上戍门临水开。
朱栏直下一百丈，日暖游鳞自相向。
昔人爱险闭层城，今日爱闲江复清。
沙洲枫岸无来客，草绿花红山鸟鸣。','',''),('quantangshi-13053','听邻家吹笙','郎士元','quantangshi','','卷14','凤吹声如隔彩霞，不知墙外是谁家。
重门深锁无寻处，疑有碧桃千树花。','',''),('quantangshi-13054','登丹阳北楼','郎士元','quantangshi','','卷14','寒臯那可望，旅望又初还。
迢遰高楼上，萧条旷野闲。
暮晴依远水，秋兴属连山。
浮客时相见，霜凋动翠颜。','',''),('quantangshi-13055','题精舍寺','郎士元','quantangshi','','卷14','石林精舍武溪东，夜扣禅关谒远公。
月在上方诸品静，僧持半偈万缘空。
秋山竟日闻猨啸，落木寒泉听不穷。
惟有双峰最高顶，此心期与故人同。','',''),('quantangshi-13056','双林寺谒傅大士','郎士元','quantangshi','','卷14','草露经前代，津梁及后人。
此方今示灭，何国更分身。
月色空知夜，松阴不记春。
犹怜下生日，应在一微尘。','',''),('quantangshi-13057','题尹真人祠','郎士元','quantangshi','','卷14','窅窅云旗去不还，阴阴祠宇闭空山。
我来始悟丹青妙，稽首如逢冰雪颜。','',''),('quantangshi-13058','山中即事','郎士元','quantangshi','','卷14','入谷多春兴，乘舟棹碧浔。
山云昨夜雨，溪水晓来深。','',''),('quantangshi-13059','湘夫人二首 一','郎士元','quantangshi','','卷14','蛾眉对湘水，遥哭苍梧山。
万乘既已殁，孤舟谁忍还。
至今楚竹上，犹有泪痕斑。','',''),('quantangshi-13060','湘夫人二首 二','郎士元','quantangshi','','卷14','南有涔阳路，渺渺多新愁。
桂酒神降时，回风江上秋。
彩云忽无处，碧水空安流。','',''),('quantangshi-13061','盖少府新除江南尉问风俗','郎士元','quantangshi','','卷14','闻君作尉向江潭，吴越风烟到自谙。
客路寻常随竹影，人家大底傍山岚。
缘溪花木偏宜远，避地衣冠尽向南。
惟有夜猨啼海树，思乡望国意难堪。','',''),('quantangshi-13062','春宴张舍人宅','郎士元','quantangshi','','卷14','嬾寻芳草径，来接侍臣筵。
山色知残雨，墙阴觉暮天。
莺啼汉宫柳，花隔杜陵烟。
地与东城接，春光醉目前。','',''),('quantangshi-13063','寄李袁州桑落酒','郎士元','quantangshi','','卷14','色比琼浆犹嫩，香同甘露仍春。
十千提携一斗，远送潇湘故人。','',''),('quantangshi-13064','赠万生下第还吴','郎士元','quantangshi','','卷14','直道多不偶，美才应息机。
灞陵春欲暮，云海独言归。
为客成白首，入门嗟布衣。
莼羹若可忆，慙出掩柴扉。','',''),('quantangshi-13065','送大德讲时河东徐明府招','郎士元','quantangshi','','卷14','远近作人天，王城指日边。
宰君迎说法，童子伴随缘。
到处花为雨，行时杖出泉。
今宵松月下，开阁想安禅。','',''),('quantangshi-13066','赴无锡别灵一上人','郎士元','quantangshi','','卷14','高僧本姓竺，开士旧名林。
一入春山里，千峰不可寻。
新年芳草徧，度日白云深。
欲问微官去，悬知讶此心。','',''),('quantangshi-13067','送粲上人兼寄梁镇员外','郎士元','quantangshi','','卷14','季月还乡独未能，林行溪宿厌层冰。
尺素欲传三署客，雪山愁送五天僧。
连空朔气横秦苑，满目寒云隔灞陵。
借问从来香积寺，何时携手更同登。','',''),('quantangshi-13068','送韦逸人归钟山','郎士元','quantangshi','','卷14','逸人归路远，弟子出山迎。
服药颜犹驻，耽书癖已成。
柴扉多岁月，藜杖见公卿。
更作儒林传，应须载姓名。','',''),('quantangshi-13069','登无锡北楼','郎士元','quantangshi','','卷14','秋兴因危堞，归心过远山。
风霜征雁早，江海旅人还。
驿树寒仍密，渔舟晚更闲。
仲宣何所赋，秪欲滞柴关。','',''),('quantangshi-13070','和王相公题中书丛竹寄上元相公','郎士元','quantangshi','','卷14','多时仙掖里，色并翠琅玕。
幽意含烟月，清阴庇蕙兰。
枝繁宜露重，叶老爱天寒。
竟日双鸾止，孤吟为一看。','',''),('quantangshi-13071','酬萧二十七侍御初秋言怀','郎士元','quantangshi','','卷14','楚客秋多兴，江林月渐生。
细枝凉叶动，极浦早鸿声。
胜赏睽前夕，新诗报远情。
曲高慙和者，惆怅闭寒城。','',''),('quantangshi-13072','奉和杜相公益昌路作','郎士元','quantangshi','','卷14','春半梁山正落花，台衡受律向天涯。
南去猨声傍双节，西来江色遶千家。
风吹画角孤城晓，林映蛾眉片月斜。
已见庙谟能喻蜀，新文更喜报金华。','',''),('quantangshi-13073','赋得长洲苑送李惠','郎士元','quantangshi','','卷14','草深那可访，地久阻相传。
散漫三秋雨，疎芜万里烟。
都迷采兰处，强记馆娃年。
客有游吴者，临风思眇然。','',''),('quantangshi-13074','别房士清','郎士元','quantangshi','','卷14','世路还相见，偏堪泪满衣。
那能郢门别，独向邺城归。
平楚看蓬转，连山望鸟飞。
苍苍岁阴暮，况复惜驰晖。','',''),('quantangshi-13075','送彭偃房由赴朝因寄钱大郎中李十七舍人','郎士元','quantangshi','','卷14','衰病已经年，西峰望楚天。
风光欺鬓发，秋色换山川。
寂寞浮云外，支离汉水边。
平生故人远，君去话潸然。','',''),('quantangshi-13076','送李遂之越','郎士元','quantangshi','','卷14','未习风波事，初为东越游。
露霑湖草晚，月照海山秋。
梅市门何处，兰亭水向流。
西兴待潮信，落日满孤舟。','',''),('quantangshi-13077','送郑正则徐州行营','郎士元','quantangshi','','卷14','从军非陇头，师在古徐州。
气劲三河卒，功全万户侯。
元戎阃外略，才子握中筹。
莫听关山曲，还生塞上愁。','',''),('quantangshi-13078','送钱拾遗归兼寄刘校书','郎士元','quantangshi','','卷14','墟落岁阴暮，桑榆烟景昏。
蝉声静空馆，雨色隔秋原。
归客不可望，悠然林外村。
终当报芸阁，携手醉柴门。','',''),('quantangshi-13079','送郴县裴明府之任兼充宣慰','郎士元','quantangshi','','卷14','白苹楚水三湘远，芳草秦城二月初。
连雁北飞看欲尽，孤舟南去意何如。
渡江野老思求瘼，候馆郴人忆下车。
别后天涯何所寄，故交惟有袖中书。','',''),('quantangshi-13080','送李敖湖南书记','郎士元','quantangshi','','卷14','怜君才与阮家同，掌记能资亚相雄。
入楚岂忘看泪竹，泊舟应自爱江枫。
诚知客梦烟波里，肯厌猨鸣夜雨中。
莫信衡湘书不到，年年秋雁过巴东。','',''),('quantangshi-13081','送麴司直','郎士元','quantangshi','','卷14','曙雪苍苍兼曙云，朔风烟雁不堪闻。
贫交此别无他赠，唯有青山远送君。','',''),('quantangshi-13082','送别','郎士元','quantangshi','','卷14','穆陵关上秋云起，安陆城边远行子。
薄暮寒蝉三两声，回头故乡千万里。','',''),('quantangshi-13083','咸阳西楼别窦审','郎士元','quantangshi','','卷14','西楼回起寒原上，霁日遥分万井间。
小苑城隅连渭水，离宫曙色近京关。
亭臯寂寞伤孤客，云雪萧条满众山。
时命如今犹未偶，辞君拟欲拂衣还。','',''),('quantangshi-13084','闻蝉寄友人','郎士元','quantangshi','','卷14','昨日始闻莺，今朝蝉又鸣。
朱颜向华发，定是几年程。
故国白云远，闲居青草生。
因垂数行泪，书寄十年兄。','',''),('quantangshi-13085','送李骑曹之灵武宁侍','郎士元','quantangshi','','卷14','一岁一归宁，凉天数骑行。
河来当塞曲，山远与沙平。
纵猎旗风卷，听笳帐月生。
新鸿引寒色，回日满京城。','',''),('quantangshi-13086','冯翊西楼','郎士元','quantangshi','','卷14','城上西楼倚暮天，楼中归望正凄然。
近郭乱山横古渡，野庄乔木带新烟。
北风吹雁声能苦，远客辞家月再圆。
陶令好文常对酒，相招一和白云篇。','',''),('quantangshi-13087','郢城秋望','郎士元','quantangshi','','卷14','白首思归归不得，空山闻雁雁声哀。
高城落日望西北，又见秋风逐水来。','',''),('quantangshi-13088','夜泊湘江','郎士元','quantangshi','','卷14','湘山木落洞庭波，湘水连云秋雁多。
寂寞舟中谁借问，月明只自听渔歌。','',''),('quantangshi-13089','留别常着','郎士元','quantangshi','','卷14','岁晏苍郊蓬转时，游人相见说归期。
宓君堂上能留客，明日还家应未迟。','',''),('quantangshi-13090','送张光归吴','郎士元','quantangshi','','卷14','看取庭芜白露新，劝君不用久风尘。
秋来多见长安客，解爱鲈鱼能几人。','',''),('quantangshi-13091','闻吹杨叶者二首 一','郎士元','quantangshi','','卷14','妙吹杨叶动悲笳，胡马迎风起恨赊。
若是雁门寒月夜，此时应卷尽惊沙。','',''),('quantangshi-13092','闻吹杨叶者二首 二','郎士元','quantangshi','','卷14','天生一艺更无伦，寥亮幽音妙入神。
吹向别离攀折处，当应合有断肠人。','',''),('quantangshi-13093','润州南郭留别','皇甫冉','quantangshi','','卷14','萦回枫叶岸，留滞木兰桡。
吴岫新经雨，江天正落潮。
故人劳见爱，行客自无聊。
君问前程事，孤云入剡遥。','',''),('quantangshi-13094','祭张公洞二首 一','皇甫冉','quantangshi','','卷14','尧心知稼穑，精意遶山川。
风雨神只应，笙镛诏命传。
沐兰秪扫地，酌桂伫灵仙。
拂雾陈金策，焚香拜玉筵。','',''),('quantangshi-13095','祭张公洞二首 二','皇甫冉','quantangshi','','卷14','云开小有洞，日出大罗天。
三鸟随王母，双童翊子先。
何时种核桃，几度看桑田。
倏忽烟霞散，空岩骑吏旋。','',''),('quantangshi-13096','临平道赠同舟人','皇甫冉','quantangshi','','卷14','远山谁辨江南北，长路空随树浅深。
流荡飘颻此何极，唯应行客共知心。','',''),('quantangshi-13097','巫山峡','皇甫冉','quantangshi','','卷14','巫峡见巴东，迢迢出半空。
云藏神女馆，雨到楚王宫。
朝暮泉声落，寒暄树色同。
清猿不可听，偏在九秋中。','',''),('quantangshi-13098','长安路','皇甫冉','quantangshi','','卷14','长安九城路，戚里五侯家。
结束趋平乐，联翩抵狭斜。
高楼临远水，复道出繁花。
唯见相如宅，蓬门度岁华。','',''),('quantangshi-13099','送朱逸人','皇甫冉','quantangshi','','卷14','时人多不见，出入五湖间。
寄酒全吾道，移家爱远山。
更看秋草暮，欲共白云还。
虽在风尘裹，陶潜身自闲。','',''),('quantangshi-13100','西陵寄灵一上人','皇甫冉','quantangshi','','卷14','西陵遇风处，自古是通津。
终日空江上，云山若待人。
汀洲寒事早，鱼鸟兴情新。
回望山阴路，心中有所亲。','',''),('quantangshi-13101','赴无锡寄别灵一净虚二上人云门所居','皇甫冉','quantangshi','','卷14','高僧本姓竺，开士旧名林。
一入春山里，千峰不可寻。
新年芳草徧，终日白云深。
欲徇微官去，悬知讶此心。','',''),('quantangshi-13102','舟中送李八','皇甫冉','quantangshi','','卷14','词客金门未有媒，游吴适越任舟回。
远水迢迢分手去，天边山色待人来。','',''),('quantangshi-13103','与张补阙王炼师自徐方清路同舟南下于台头寺留别赵员外裴补阙同赋杂题一首','皇甫冉','quantangshi','','卷14','朝朝春事晚，泛泛行舟远。
淮海思无穷，悠扬烟景中。
幸将仙子去，复与故人同。
高枕随流水，轻帆任远风。
钟声野寺逈，草色故城空。
送别高台上，裴回共惆怅。
悬知白日斜，定是犹相望。','',''),('quantangshi-13104','酬张二仲彝','皇甫冉','quantangshi','','卷14','吴洲见芳草，楚客动归心。
屈宋乡山古，荆衡烟雨深。
艰难十载别，羁旅四愁侵。
澧月通沅水，湘云入桂林。
已看生白发，当为乏黄金。
江海时相见，唯闻梁甫吟。','',''),('quantangshi-13105','三月三日义兴李明府后亭泛舟','皇甫冉','quantangshi','','卷14','江南烟景复如何，闻道新亭更可过。
处处蓻兰春浦绿，萋萋藉草远山多。
壶觞须就陶彭泽，时俗犹传晋永和。
更使轻桡徐转去，微风落日水增波。','',''),('quantangshi-13106','少室山韦炼师升仙歌','皇甫冉','quantangshi','','卷14','红霞紫气昼氲氲，绛节青幢迎少君。
忽从林下升天去，空使时人礼白云。','',''),('quantangshi-13107','独孤中丞筵陪饯韦君赴升州','皇甫冉','quantangshi','','卷14','中司龙节贵，上客虎符新。
地控吴襟带，才高汉缙绅。
泛舟应度腊，入境便行春。
处处歌来暮，长江建业人。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-13108','送王绪剡中','皇甫冉','quantangshi','','卷14','不见关山去，何时到郯中。
已闻成竹木，更道长儿童。
篱落云常聚，村墟水自通。
朝朝忆玄度，非是对清风。','',''),('quantangshi-13109','酬李郎中侍御秋夜登福州城楼见寄','皇甫冉','quantangshi','','卷14','辛勤万里道，箫索九秋残。
月照闽中夜，天凝海上寒。
王程无地远，主意在人安。
遥寄登楼作，空知行路难。','',''),('quantangshi-13110','同李司直诸公暑夜南余馆','皇甫冉','quantangshi','','卷14','何处多明月，津亭暑夜深。
烟霞不可望，云树更沈沈。
好是吴中隐，仍为洛下吟。
微官朝复夕，牵强亦何心。','',''),('quantangshi-13111','赠普门上人','皇甫冉','quantangshi','','卷14','支公身欲老，长在沃州多。
慧力堪传敎，禅功久伏魔。
山云随坐夏，江草伴头陀。
借问回心后，贤愚去几何。','',''),('quantangshi-13112','与诸公同登无锡北楼','皇甫冉','quantangshi','','卷14','秋兴因危堞，归心过远山。
风霜征雁早，江海旅人闲。
驿树寒仍密，渔舟晚自还。
仲宣何所赋，秪叹在荆蛮。','',''),('quantangshi-13113','同李苏州伤美人','皇甫冉','quantangshi','','卷14','玉佩石榴裙，当年嫁使君。
专房犹见宠，倾国众皆闻。
歌舞常无对，幽明忽此分。
阳台千万里，何处作朝云。','',''),('quantangshi-13114','送李录事赴饶州','皇甫冉','quantangshi','','卷14','北人南去雪纷纷，雁叫汀沙不可闻。
积水长天随远客，荒城极浦足寒云。
山从建业千峰出，江至浔阳九派分。
借问督邮才弱冠，府中年少不如君。','',''),('quantangshi-13115','同诸公有怀绝句','皇甫冉','quantangshi','','卷14','旧国迷江树，他乡近海门。
移家南渡久，童稚解方言。','',''),('quantangshi-13116','题魏仲光淮山所居','皇甫冉','quantangshi','','卷14','人群不相见，乃在白云间。
问我将何适，羡君今独闲。
朝朝汲淮水，暮暮上龟山。
幸已安贫定，当从鬓发斑。','',''),('quantangshi-13117','送郑判官赴徐州','皇甫冉','quantangshi','','卷14','从军非陇头，师在古徐州。
气劲三河卒，功多万里侯。
元戎阃外令，才子幄中筹。
莫听关山曲，还生出塞愁。','',''),('quantangshi-13118','送顾苌往新安','皇甫冉','quantangshi','','卷14','由来山水客，复道向新安。
半是乘潮便，全非行路难。
晨装林月在，野饭浦沙寒。
严子千年后，何人钓旧滩。','',''),('quantangshi-13119','秋夜有怀高三十五兼呈空和尚','皇甫冉','quantangshi','','卷14','晚节闻君趋道深，结茅栽树近东林。
大师几度曾摩顶，高士何年遂发心。
北渚三更闻过雁，西城万里动寒砧。
不见支公与玄度，相思拥膝坐长吟。','',''),('quantangshi-13120','途中送权三兄弟','皇甫冉','quantangshi','','卷14','淮海风涛起，江关忧思长。
同悲鹊遶树，独作雁随阳。
山晚云初雪，汀寒月照霜。
由来濯缨处，渔父爱沧浪。','',''),('quantangshi-13121','送裴阐','皇甫冉','quantangshi','','卷14','道向毗陵岂是归，客中谁与换春衣。
今夜孤舟行近远，子荆零雨正霏霏。','',''),('quantangshi-13122','杂言湖山歌送许鸣谦','皇甫冉','quantangshi','','卷14','湖中之山兮波上青，桂飒飒兮雨冥冥。
君归兮春早，满山兮碧草。
晨舂暮汲兮心何求，涧户岩扉兮身自老。
东岭西峰兮同白云，鸡鸣犬吠兮时相闻。
幽芳媚景兮当嘉月，践石扪萝兮恣超忽。
空山寂寂兮颍阳人，旦夕孤云随一身。','',''),('quantangshi-13123','杂言迎神词二首 迎神','皇甫冉','quantangshi','','卷14','启庭户，列芳鲜，目眇眇，心绵绵，因风托雨降琼筵。
纷下拜，屡加笾，人心望岁祈丰年。','',''),('quantangshi-13124','杂言迎神词二首 送神','皇甫冉','quantangshi','','卷14','露霑衣，月隐壁，气凄凄，人寂寂，风回雨度虚瑶席。
来无声，去无迹，神心降和福远客。','',''),('quantangshi-13125','屏风上各赋一物得携琴客','皇甫冉','quantangshi','','卷14','不是向空林，应当就磐石。
白云知隐处，芳草迷行迹。
如何秪役心，见尔携琴客。','',''),('quantangshi-13126','江草歌送卢判官','皇甫冉','quantangshi','','卷14','江臯兮春早，江上兮芳草。
杂蘼芜兮杜蘅，作丛秀兮欲罗生。
被遥隰兮经长衍，雨中深兮烟中浅。
目眇眇兮增愁，步迟迟兮堪搴。
澧之浦兮湘之滨，思夫君兮送美人。
吴洲曲兮楚乡路，远孤城兮依独戎。
新月能分裛露时，夕阳照见连天处。
问君行迈将何之，淹泊沿洄风日迟。
处处汀洲有芳草，王孙讵肯念归期。','',''),('quantangshi-13127','题画帐二首 山水','皇甫冉','quantangshi','','卷14','桂水饶枫杉，荆南足烟雨。
犹疑黛色中，复是雒阳岨。','',''),('quantangshi-13128','题画帐二首 远帆','皇甫冉','quantangshi','','卷14','朝见巴江客，暮见巴江客。
云帆傥暂停，中路阳台夕。','',''),('quantangshi-13129','落第后东游留别','皇甫冉','quantangshi','','卷14','功成方自得，何事学干求。
果以浮名误，深贻达士羞。
九江连涨海，万里任虚舟。
岁晚同怀客，相思波上鸥。','',''),('quantangshi-13130','杂言月洲歌送赵冽还襄阳','皇甫冉','quantangshi','','卷14','汉之广矣中有洲，洲如月兮水环流。
流聒聒兮湍与濑，草青青兮春更秋。
苦竹林，香枫树，樵子罛师几家住。
万山飞雨一川来，巴客归船傍洲去。
归人不可迟，芳杜满洲时。
无限风烟皆自悲，莫辞贫贱阻心期。
家住洲头定近远，朝泛轻桡暮当返。
不能随尔卧芳洲，自念天机一何浅。','',''),('quantangshi-13131','寄刘八山中','皇甫冉','quantangshi','','卷14','东臯若近远，苦雨隔还期。
闺岁风霜晚，山田收获迟。
茅檐燕去后，樵路菊黄时。
平子游都久，知君坐见嗤。','',''),('quantangshi-13132','答张諲刘方平兼呈贺兰广','皇甫冉','quantangshi','','卷14','野性难驯狎，荒郊自闭门。
心闲同海鸟，日夕恋山村。
屡枉琼瑶赠，如今道术存。
远峯时振策，春雨耐香源。
复有故人在，宁闻庐鹊喧。
青青草色绿，终是待王孙。','',''),('quantangshi-13133','沣水送郑鄠县读书','皇甫冉','quantangshi','','卷14','麦秋中夏凉风起，送君西郊及沣水。
孤烟远树动离心，隔岸江流若千里。
早年江海谢浮名，此路云山惬尔情。
上古全经皆在口，秦人如见济南生。','',''),('quantangshi-13134','九日寄郑丰','皇甫冉','quantangshi','','卷14','重阳秋已晚，千里信仍稀。
何处登高望，知君正忆归。
还当采时菊，定未授寒衣。
欲识离居恨，郊园正掩扉。','',''),('quantangshi-13135','酬包评事壁画山水见寄','皇甫冉','quantangshi','','卷14','一官知所傲，本意在云泉。
濡翰生新兴，群峰忽眼前。
黛中分远近，笔下起风烟。
岩翠深樵路，湖光出钓船。
寒侵赤城顶，日照武陵川。
若览名山志，仍闻招隐篇。
遂令江海客，惆怅忆闲田。','',''),('quantangshi-13136','渡汝水向太和山','皇甫冉','quantangshi','','卷14','落日事搴陟，西南投一峯。
诚知秋水浅，但怯无人踪。','',''),('quantangshi-13137','秋怨','皇甫冉','quantangshi','','卷14','长信多秋气，昭阳借月华。
那堪闭永巷，闻道选良家。','',''),('quantangshi-13138','赠郑山人','皇甫冉','quantangshi','','卷14','白首沧洲客，陶然得此生。
庞公采药去，莱氏与妻行。
乍见还州里，全非隐姓名。
枉帆临海峤，贳酒秣陵城。
伐木吴山晓，持竿越水清。
家人恣贫贱，物外任衰荣。
忽尔辞林壑，高歌至上京。
避喧心已惯，念远梦频成。
石路寒花发，江田腊雪明。
玄纁倘有命，何以遂躬耕。','',''),('quantangshi-13139','刘方平西斋对雪','皇甫冉','quantangshi','','卷14','对酒闲斋晚，开轩腊雪时。
花飘疑节候，色净润帘帷。
委树寒枝弱，萦空去雁迟。
自然堪访戴，无复四愁诗。','',''),('quantangshi-13140','福先寺寻湛然寺主不见','皇甫冉','quantangshi','','卷14','寂然空伫立，往往报疎钟。
高馆谁留客，东南二室峰。
川原通霁色，田野变春容。
惆怅层城暮，犹言归路逢。','',''),('quantangshi-13141','河南郑少尹城南亭送郑判官还河东','皇甫冉','quantangshi','','卷14','使臣怀饯席，亚尹有前溪。
客是仙舟里，途从御苑西。
泉声喧暗竹，草色引长堤。
故绛青山在，新田绿树齐。
天秋闻别鹄，关晓待鸣鸡。
应叹沈冥者，年年津路迷。','',''),('quantangshi-13142','登玄元庙','皇甫冉','quantangshi','','卷14','古庙川原迥，重门禁籞连。
海童纷翠盖，羽客事琼筵。
御路分疎柳，离宫出苑田。
兴新无向背，望久辨山川。
物外将遗老，区中誓绝缘。
函关若远近，紫气独依然。','',''),('quantangshi-13143','冬夜集赋得寒漏','皇甫冉','quantangshi','','卷14','清冬洛阳客，寒漏建章台。
出禁因风彻，萦窗共月来。
偏将残濑杂，乍与远鸿哀。
遥夜重城警，流年滴水催。
闲斋堪坐听，况有故人杯。','',''),('quantangshi-13144','玄元观送李源李风还奉先华阴','皇甫冉','quantangshi','','卷14','此去那知道路遥，寒原紫府上迢迢。
莫辞别酒和琼液，乍唱离歌和凤箫。
远水东流浮落景，缭垣西转失行镳。
华山秦塞长相忆，无使音尘顿寂寥。','',''),('quantangshi-13145','刘方平壁画山','皇甫冉','quantangshi','','卷14','墨妙无前，性生笔先。
回溪已失，远嶂犹连。
侧径樵客，长林野烟。
青峰之外，何处云天。','',''),('quantangshi-13146','登山歌','皇甫冉','quantangshi','','卷14','青山前，青山后，登高望两处。
两处今何有？
烟景满川原，离人堪白首。','',''),('quantangshi-13147','和郑少尹祭中岳寺北访萧居士越上方','皇甫冉','quantangshi','','卷14','肃寺祠灵境，寻真到隐居。
夤缘幽谷远，萧散白云余。
晚节持僧律，他年着道书。
海边曾狎鸟，濠上正观鱼。
寂静求无相，淳和覩太初。
一峰绵岁月，万性任盈虚。
篱隔溪钟度，窗临涧木疎。
谢公怀旧壑，回驾复何如。','',''),('quantangshi-13148','秋夜寄所思','皇甫冉','quantangshi','','卷14','寂寞坐遥夜，清风何处来？
天高散骑省，月冷建章台。
邻笛哀声急，城砧朔气催。
芙蓉已委绝，谁复可为媒。','',''),('quantangshi-13149','赋得郢路悲猨','皇甫冉','quantangshi','','卷14','悲猨何处发？郢路第三声。
远客知秋暮，空山益夜清。
啾啾深众木，嗷嗷入孤城。
坐觉盈心耳，翛然适楚情。','',''),('quantangshi-13150','杂言无锡惠山寺流泉歌','皇甫冉','quantangshi','','卷14','寺有泉兮泉在山，锵金鸣玉兮长潺潺。
作潭镜兮澄寺内，泛岩花兮到人间。
土膏脉动知春早，隈隩阴深长苔草。
处处萦回石磴喧，朝朝盥漱山僧老。
僧自老，松自新，流活活，无冬春。
任疏凿兮与汲引，若有意兮山中人。
偏依佛界通仙境，明灭玲珑媚林岭。
宛如太室临九潭，讵减天台望三井。
我来结绶未经秋，已厌微官忆旧游。
且复迟回犹未去，此心秪为灵泉留。','',''),('quantangshi-13151','清明日青龙寺上方赋得多字','皇甫冉','quantangshi','','卷14','上方偏可适。
季月况堪过，远近水声至。
东西山色多，夕阳留径草。
新叶变庭柯，已度清明节。
春秋如客何。','',''),('quantangshi-13152','与张諲宿刘八城东庄','皇甫冉','quantangshi','','卷14','人闲当岁暮，田野尚逢迎。
莱子多嘉庆，陶公得此生。
寒芜连古渡，云树近严城。
鸡黍无辞薄，贫交但贵情。','',''),('quantangshi-13153','寄刘方平','皇甫冉','quantangshi','','卷14','坐忆山中人，穷栖事南亩。
烟霞相亲外，墟落今何有。
潘郎作赋年，陶令辞官后。
达生遗自适，良愿固无负。
田取颍水流，树入阳城口。
岁暮忧思盈，离居不堪久。','',''),('quantangshi-13154','曾东游以诗寄之','皇甫冉','quantangshi','','卷14','出郭离言多，回车始知远。
寂然层城暮，更念前山转。
总辔越成臯，浮舟背梁苑。
朝朝劳延首，往住若在眼。
落日孤云还，边愁迷楚关。
如何溆花发，复对游子颜。
古寺杉栝里，连樯洲渚间。
烟生海西岸，云见吴南山。
惊风扫芦荻，翻浪连天白。
正是扬帆时，偏逢江上客。
由来许佳句，况乃惬所适。
嵯峨天姥峰，翠色春更碧。
气凄湖上雨，月净剡中夕。
钓艇或相逢，江蓠又堪摘。
迢迢始宁墅，芜没谢公宅。
朱槿列摧墉，苍苔徧幽石。
顾予任疎懒，期尔振羽翮。
沧洲未可行，须售金门策。','',''),('quantangshi-13155','适荆州途次南阳赠何明府','皇甫冉','quantangshi','','卷14','千里独游日，有怀谁与同。
言过细阳令，一遇郎陵公。
清节迈多士，斯文传古风。
闾阎知俗变，原野识年丰。
吾道方在此，前程殊未穷。
江天经岘北，客思满巴东。
梦渚夕愁远，山丘晴望通。
应嗟出处异，流荡楚云中。','',''),('quantangshi-13156','秋夜戏题刘方平壁','皇甫冉','quantangshi','','卷14','鸿悲月白时将谢，正可招寻惜遥夜。
翠帐兰房曲且深，宁知户外清霜下。','',''),('quantangshi-13157','问正上人疾','皇甫冉','quantangshi','','卷14','医王犹有疾，妙理竞难穷。
饵药应随病，观身转悟空。
地闲花欲雨，窗冷竹生风。
几日东林去，门人待远公。','',''),('quantangshi-13158','山中五咏 门柳','皇甫冉','quantangshi','','卷14','接影武昌城，分行汉南道。
何事闲门外，空对青山老。','',''),('quantangshi-13159','山中五咏 远山','皇甫冉','quantangshi','','卷14','少室尽西峯，鸣臯隐南面。
柴门纵复关，终日窗中见。','',''),('quantangshi-13160','山中五咏 南涧','皇甫冉','quantangshi','','卷14','上路各乘轩，高明尽鸣玉。
宁知涧下人，自爱轻波渌。','',''),('quantangshi-13161','山中五咏 春早','皇甫冉','quantangshi','','卷14','草徧颍阳山，花开武陵水。
春色既已同，人心亦相似。','',''),('quantangshi-13162','山中五咏 山馆','皇甫冉','quantangshi','','卷14','山馆长寂寂，闲云朝夕来。
空庭复何有，落日照青苔。','',''),('quantangshi-13163','送窦十九叔向赴京','皇甫冉','quantangshi','','卷14','冰结杨柳津，从吴去入秦。
徒云还上国，谁为作中人。
驿树同霜霰，渔舟伴苦辛。
相如求一谒，词赋远随身。','',''),('quantangshi-13164','登石城戍望海寄诸暨严少府','皇甫冉','quantangshi','','卷14','平明登古戍，徙倚待寒潮。
江海方回合，云林自寂寥。
讵能知远近，徒见荡烟霄。
即此沧洲路，嗟君久折腰。','',''),('quantangshi-13165','和樊润州秋日登城楼','皇甫冉','quantangshi','','卷14','露冕临平楚，寒城带早霜。
时同借河内，人是卧淮阳。
积水澄天堑，连山入帝乡。
因高欲见下，非是爱秋光。','',''),('quantangshi-13166','寄江东李判官','皇甫冉','quantangshi','','卷14','远怀不可道，历稔倦离忧。
洛下闻新雁，江南想暮秋。
澄清佐八使，纲纪案诸侯。
地识吴平久，才当晋用求。
时贤几殂谢，摛藻继风流。
更有西陵作，还成北固游。
归途限尺牍，王事在扁舟。
山色临湖尽，猿声入梦愁。','',''),('quantangshi-13167','送蒋评事往福州','皇甫冉','quantangshi','','卷14','江上春常早，闽中客去稀。
登山怨迢递，临水惜芳菲。
烟树何时尽，风帆几日归。
还看复命处，盛府有光辉。','',''),('quantangshi-13168','送从弟豫贬远州','皇甫冉','quantangshi','','卷14','何事成迁客，思归不见乡。
游吴经万里，吊屈过三湘。
水与荆巫接，山通鄢郢长。
名嗟黄绶系，才是白眉良。
独结南枝恨，应思北雁行。
忧来沽楚酒，玄鬓莫凝霜。','',''),('quantangshi-13169','送钱唐路少府赴制举','皇甫冉','quantangshi','','卷14','公车待诏赴长安，客里新正阻旧欢。
迟日未能销野雪，晴花偏自犯江寒。
东溟道路通秦塞，北阙威仪识汉官。
共许郄诜工射策，恩荣请向一枝看。','',''),('quantangshi-13170','赋得荆溪夜湍送蒋逸人归义兴山','皇甫冉','quantangshi','','卷14','惊湍流不极，夜度识云岑。
长带溪沙浅，时因山雨深。
方同七里路，更遂五湖心。
揭厉朝将夕，潺湲古至今。
花源君若许，虽远亦相寻。','',''),('quantangshi-13171','送孔党赴举','皇甫冉','quantangshi','','卷14','入贡列诸生，诗书业早成。
家承孔圣后，身有鲁儒名。
楚水通荥浦，春山拥汉京。
爱君方弱冠，为赋少年行。','',''),('quantangshi-13172','齐郎中筵赋得的的帆向浦留别','皇甫冉','quantangshi','','卷14','一帆何处去，正在望中微。
浦迥摇空色，汀回见落晖。
每争高鸟度，能送远人归。
偏似南浮客，悠扬无所依。','',''),('quantangshi-13173','送陆鸿渐栖霞寺采茶','皇甫冉','quantangshi','','卷14','采茶非采菉，远远上层崖。
布叶春风暖，盈筐白日斜。
旧知山寺路，时宿野人家。
借问王孙草，何时泛椀花。','',''),('quantangshi-13174','泊丹阳与诸人同舟至马林溪遇雨','皇甫冉','quantangshi','','卷14','云林不可望，溪水更悠悠。
共载人皆客，离家春是秋。
远山方对枕，细雨莫回舟。
来往南徐路，多为芳草留。','',''),('quantangshi-13175','太常魏博士远出贼庭江外相逢因叙其事','皇甫冉','quantangshi','','卷14','烽火惊戎塞，豺狼犯帝畿。
川原无稼穑，日月翳光辉。
里社枌榆毁，宫城骑吏非。
羣生被惨毒，杂虏耀轻肥。
多士从芳饵，唯君识祸机。
心同合浦叶，命寄首阳薇。
耻作纤鳞喣，方随高鸟飞。
山经商岭出，水泛汉池归。
离别霜凝鬓，逢迎泪迸衣。
京华长路绝，江海故人稀。
秉节身常苦，求仁志不违。
秪应穷野外，耕种且相依。','',''),('quantangshi-13176','送包佶赋得天津桥','皇甫冉','quantangshi','','卷14','洛阳岁暮作征客，囗囗囗囗囗囗囗。
相望依然一水间，相思已如千年隔。
晴烟霁景满天津，凤阁龙楼暎水滨。
岂无朝夕轩车度，其奈相逢非所亲。
巩树甘陵愁远道，他乡一望人堪老。
君报还期在早春，桥边日日看芳草。','',''),('quantangshi-13177','上礼部杨侍郎','皇甫冉','quantangshi','','卷14','郢匠抡材日，辕轮必尽呈。
敢言当一干，徒欲隶诸生。
末学慙邹鲁，深仁录弟兄。
余波知可挹，弱植更求荣。
绩愧他年败，功期此日成。
方因旧桃李，犹冀载飞鸣。
道浅犹怀分，时移但自惊。
关门惊暮节，林壑废春畊。
十里嵩峯近，千秋颍水清。
烟花迷戍谷，墟落接阳城。
渺默思乡梦，迟回知己情。
劳歌终此曲，还是苦辛行。','',''),('quantangshi-13178','宿严维宅送包七','皇甫冉','quantangshi','','卷14','江湖同避地，分手自依依。
尽室今为客，经秋空念归。
岁储无别墅，寒服羡邻机。
草色村桥晚，蝉声江树稀。
夜凉宜共醉，时难惜相违。
何事随阳侣，汀洲忽背飞。','',''),('quantangshi-13179','同张侍御咏兴宁寺经藏院海石榴花','皇甫冉','quantangshi','','卷14','嫩叶生初茂，残花少更鲜。
结根龙藏侧，故欲并青莲。','',''),('quantangshi-13180','崔十四宅各赋一物得檐柳','皇甫冉','quantangshi','','卷14','官渡老风烟，浔阳媚云日。
汉将营前见，胡笳曲中出。
复在此檐端，垂阴仲长室。','',''),('quantangshi-13181','送段明府','皇甫冉','quantangshi','','卷14','遥夜此何其，霜空残杳霭。
方嗟异乡别，蹔是同公会。
海林秋更疎，野水寒犹大。
离人转吴岫，旅雁从燕塞。
日夕望前期，劳心白云外。','',''),('quantangshi-13182','送王司直','皇甫冉','quantangshi','','卷14','西塞云山远，东风道路长。
人心胜潮水，相送过浔阳。','',''),('quantangshi-13183','婕妤春怨','皇甫冉','quantangshi','','卷14','花枝出建章，凤管发昭阳。
借问承恩者，双蛾几许长。','',''),('quantangshi-13184','送魏十六还苏州','皇甫冉','quantangshi','','卷14','秋夜深深北送君，阴虫切切不堪闻。
归舟明日毗陵道，回首姑苏是白云。','',''),('quantangshi-13185','婕妤怨','皇甫冉','quantangshi','','卷14','由来咏团扇，今已值秋风。
事逐时皆徃，恩无日再中。
早鸿闻上苑，寒露下深宫。
颜色年年谢，相如赋岂工。','',''),('quantangshi-13186','送客','皇甫冉','quantangshi','','卷14','旗鼓军威重，关山客路赊。
待封甘度陇，回首不思家。
城下春山路，营中瀚海沙。
河源虽万里，音信寄来查。','',''),('quantangshi-13187','秋日东郊作','皇甫冉','quantangshi','','卷14','闲看秋水心无事，卧对寒松手自栽。
庐岳高僧留偈别，茅山道士寄书来。
燕知社日辞巢去，菊为重阳冒雨开。
浅薄将何称献纳，临岐终日自迟回。','',''),('quantangshi-13188','秋夜宿严维宅','皇甫冉','quantangshi','','卷14','昔闻玄度宅，门向会稽峯。
君住东湖下，清风继旧踪。
秋深临水月，夜半隔山钟。
世故多离别，良宵讵可逢。','',''),('quantangshi-13189','见诸姬学玉台体','皇甫冉','quantangshi','','卷14','艳唱召燕姬，清弦待卢女。
由来道姓秦，谁不知家楚。
传杯见目成，结带明心许。
宁辞玉辇迎，自堪金屋贮。
朝朝作行云，襄王迷处所。','',''),('quantangshi-13190','酬张二仓曹扬子所居见寄兼呈韩郎中','皇甫冉','quantangshi','','卷14','孤云独鹤自悠悠，别后经年尚泊舟。
渔父置词相借问，郎官能赋许依投。
折芳远寄三春草，乘兴闲看万里流。
莫怪杜门频乞假，不堪扶病拜龙楼。','',''),('quantangshi-13191','送安律师','皇甫冉','quantangshi','','卷14','出家童子岁，爱此雪山人。
长路经千里，孤云伴一身。
水中应见月，草上岂伤春。
永日空林下，心将何物亲。','',''),('quantangshi-13192','题卢十一所居','皇甫冉','quantangshi','','卷14','春风来几日，先入辟疆园。
身外无余事，闲吟昼闭门。','',''),('quantangshi-13193','送陆[澧]郭郧','皇甫冉','quantangshi','','卷14','才见吴洲百草春，已闻燕雁一声新。
秋风何处催年急，偏逐山行水宿人。','',''),('quantangshi-13194','山中横云','皇甫冉','quantangshi','','卷14','湘水风日满，楚山朝夕空。
连峰虽已见，犹念长云中。','',''),('quantangshi-13195','题裴二十一新园','皇甫冉','quantangshi','','卷14','东郭访先生，西郊寻隐路。
久为江南客，自有云阳树。
已得闲园心，不知公府步。
开门白日晚，倚杖青山暮。
果熟任霜封，篱疎从水度。
穷年无牵缀，往事惜沦悞。
唯见耦耕人，朝朝自来去。','',''),('quantangshi-13196','寄高云','皇甫冉','quantangshi','','卷14','南徐风日好，怅望毗陵道。
毗陵有故人，一见恨无因。
独恋青山久，唯令白发新。
每嫌持手板，时见着头巾。
烟景临寒食，农桑接仲春。
家贫仍嗜酒，生事今何有。
芳草遍江南，劳心忆携手。','',''),('quantangshi-13197','温泉即事','皇甫冉','quantangshi','','卷14','天仗星辰转，霜冬景气和。
树含温液润，山入缭垣多。
丞相金钱赐，平阳玉辇过。
鲁儒求一谒，无路独如何。','',''),('quantangshi-13198','送张南史','皇甫冉','quantangshi','','卷14','马卿工词赋，位下年将暮。
谢客爱云山，家贫身不闲。
风波杳未极，几处逢相识。
富贵人皆变，谁能念贫贱。
岸有经霜草，林有故年枝。
俱应待春色，独使客心悲。','',''),('quantangshi-13199','庐山歌送至弘法师兼呈薛江州','皇甫冉','quantangshi','','卷14','释子去兮访名山，禅舟容与兮住仍前。
猿啾啾兮怨月，江渺渺兮多烟。
东林西林兮入何处，上方下方兮通石路。
连湘接楚饶桂花，事久年深无杏树。
使君爱人兼爱山，时引双旌万木间。
政成人野皆不扰，遂令法侣性安闲。','',''),('quantangshi-13200','送薛秀才','皇甫冉','quantangshi','','卷14','虽是寻山客，还同慢世人。
读书惟务静，无褐不忧贫。
野色春冬树，鸡声远近邻。
郄公即吾友，合与尔相亲。','',''),('quantangshi-13201','使往寿州淮路寄刘长卿','皇甫冉','quantangshi','','卷14','榛草荒凉村落空，驱驰卒岁亦何功。
蒹葭曙色苍苍远，蟋蟀秋声处处同。
乡路遥知淮浦外，故人多在楚云东。
日夕烟霜那可道，寿阳西去水无穷。','',''),('quantangshi-13202','酬李司兵直夜见寄','皇甫冉','quantangshi','','卷14','江城闻鼓角，旅宿复何如。
寒月此宵半，春风旧岁余。
徒云资薄禄，未必胜闲居。
见欲扁舟去，谁能畏简书。','',''),('quantangshi-13203','送薛判官之越','皇甫冉','quantangshi','','卷14','时难自多务，职小亦求贤。
道路无辞远，云山并在前。
樟亭待潮处，已是越人烟。','',''),('quantangshi-13204','同温丹徒登万岁楼','皇甫冉','quantangshi','','卷14','高楼独立思依依，极浦遥山合翠微。
江客不堪频北顾，塞鸿何事复南飞。
丹阳古渡寒烟积，瓜步空洲远树稀。
闻道王师犹转战，谁能谈笑解重围。','',''),('quantangshi-13205','赋得檐燕','皇甫冉','quantangshi','','卷14','拂水竞何忙，傍檐如有意。
翻风去每远，带雨归偏驶。
令君裁杏梁，更欲年年去。','',''),('quantangshi-13206','送李万州赴饶州觐省','皇甫冉','quantangshi','','卷14','前程观拜庆，旧馆惜招携。
荀氏风流远，胡家清白齐。
川回吴岫失，塞阔楚云低。
举目亲鱼鸟，惊心怯鼓鼙。
人稀渔浦外，滩浅定山西。
无限青青草，王孙去不迷。','',''),('quantangshi-13207','送邹判官赴河南','皇甫冉','quantangshi','','卷14','看君发原隰，四牡去皇皇。
始罢沧江吏，还随粉署郎。
海沂军未息，河畔岁仍荒。
征税人全少，榛芜虏近亡。
所行知宋远，相隔叹淮长。
早晚裁书寄，银钩伫八行。','',''),('quantangshi-13208','宿淮阴南楼酬常伯能','皇甫冉','quantangshi','','卷14','淮阴日落上南楼，乔木荒城古渡头。
浦外野风初入户，窗中海月早知秋。
沧波一望通千里，画角三声起百忧。
伫立分宵绝来客，烦君步屐忽相求。','',''),('quantangshi-13209','送归中丞使新罗','皇甫冉','quantangshi','','卷14','诏使殊方远，朝仪旧典行。
浮天无尽处，望日计前程。
暂喜孤山出，长愁积水平。
野风飘叠鼓，海雨湿危旌。
异俗知文敎，通儒有令名。
还将大戴礼，方外授诸生。','',''),('quantangshi-13210','小江怀灵一上人','皇甫冉','quantangshi','','卷14','江上年年春早，津头日日人行。
借问山阴远近，犹闻薄暮钟声。','',''),('quantangshi-13211','送唐别驾赴郢州','皇甫冉','quantangshi','','卷14','莫叹辞家远，方看佐郡荣。
长林通楚塞，高岭见秦城。
雪向峣关下，人从郢路迎。
翩翩骏马去，自是少年行。','',''),('quantangshi-13212','送魏中丞还河北','皇甫冉','quantangshi','','卷14','宁知贵公子，本是鲁诸生。
上国风尘旧，中司印绶荣。
辛勤戎旅事，雪下护羗营。','',''),('quantangshi-13213','送李使君赴邵州','皇甫冉','quantangshi','','卷14','出送东方骑，行安南楚人。
城池春足雨，风俗夜迎神。
郢路逢归客，湘川问去津。
争看使君度，皂盖雪中新。','',''),('quantangshi-13214','寄振上人无碍寺所居','皇甫冉','quantangshi','','卷14','恋亲时见在人羣，多在东山就白云。
独坐焚香诵经处，深山古寺雪纷纷。','',''),('quantangshi-13215','酬李补阙','皇甫冉','quantangshi','','卷14','十年归客但心伤，三径无人已自荒。
夕宿灵台伴烟月，晨趋建礼逐衣裳。
偶因麋鹿随丰草，谬荷鸳鸾借末行。
纵有谏书犹未献，春风拂地日空长。','',''),('quantangshi-13216','故齐王赠承天皇帝挽歌','皇甫冉','quantangshi','','卷14','礼盛追崇日，人知友悌恩。
旧居从代邸，新陇入文园。
鸿宝仙书祕，龙旗帝服尊。
苍苍松里月，万古此高原。','',''),('quantangshi-13217','赠恭顺皇后挽歌','皇甫冉','quantangshi','','卷14','徂谢年方久，哀荣事独稀。
虽殊百两迓，同是九泉归。
诏使归金策，神人送玉衣。
空山竟不从，宁肯学湘妃。','',''),('quantangshi-13218','病中对石竹花','皇甫冉','quantangshi','','卷14','散点空堦下，闲凝细雨中。
那能久相伴，嗟尔殢秋风。','',''),('quantangshi-13219','寄郑二侍御归新郑无碍寺所居','皇甫冉','quantangshi','','卷14','何事休官早，归来作郑人。
云山随伴侣，伏腊见乡亲。
南亩无三径，东林寄一身。
谁当便静者，莫使甑生尘。','',''),('quantangshi-13220','送庐山人归林虑山','皇甫冉','quantangshi','','卷14','无论行远近，归向旧烟林。
寥落人家少，青冥鸟道深。
白云长满目，芳草自知心。','',''),('quantangshi-13221','送荣别驾赴华州','皇甫冉','quantangshi','','卷14','直到羣峯下，应无累日程。
高车入郡舍，流水出关城。
草色田家迥，槐阴府吏迎。
还将海沂咏，籍甚汉公卿。','',''),('quantangshi-13222','送常大夫加散骑常侍赴朔方','皇甫冉','quantangshi','','卷14','故垒烟尘后，新军河塞间。
金貂宠汉将，玉节度萧关。
澶漫沙中雪，依稀汉口山。
人知窦车骑，计日勒铭还。','',''),('quantangshi-13223','送王翁信还剡中旧居','皇甫冉','quantangshi','','卷14','海岸耕残雪，溪沙钓夕阳。
客中何所有，春草渐看长。','',''),('quantangshi-13224','酬张继','皇甫冉','quantangshi','','卷14','怅望南徐登北固，迢遥西塞恨东关。
落日临川问音信，寒潮唯带夕阳还。','',''),('quantangshi-13225','送柳八员外赴江西','皇甫冉','quantangshi','','卷14','岐路穷无极，长江九派分。
行人随旅雁，楚树入湘云。
久在征南役，何殊蓟北勋。
离心不可问，岁暮雪纷纷。','',''),('quantangshi-13226','赋长道一绝送陆邃潜夫','皇甫冉','quantangshi','','卷14','高山迥欲登，远水深难渡。
杳杳复漫漫，行人别家去。','',''),('quantangshi-13227','又得云字','皇甫冉','quantangshi','','卷14','何事千年遇圣君，坐令双鬓老如云。
南行更入深山浅，岐路悠悠水自分。','',''),('quantangshi-13228','送陆潜夫往茅山赋得华阳洞','皇甫冉','quantangshi','','卷14','游仙洞兮访真官，奠瑶席兮礼石坛。
忽仿髴兮云扰，杳阴深兮夏寒。
欲回头兮挥手，便辞家兮可否。
有婚嫁兮婴缠，绵归来兮已久。','',''),('quantangshi-13229','又送陆潜夫茅山寻友','皇甫冉','quantangshi','','卷14','登山自补屐，访友不赍粮。
坐啸青枫晚，行吟白日长。
人烟隔水见，草气入林香。
谁作招寻侣，清斋宿紫阳。','',''),('quantangshi-13230','赋得越山三韵','皇甫冉','quantangshi','','卷14','西陵犹隔水，北岸已春山。
独鸟连天去，孤云伴客还。
秪应结茅宇，出入石林间。','',''),('quantangshi-13231','送卢郎中使君赴京','皇甫冉','quantangshi','','卷14','三年期上国，万里自东溟。
曲盖遵长道，油幢憩短亭。
楚云山隐隐，淮雨草青青。
康乐多新兴，题诗纪所经。','',''),('quantangshi-13232','杨氏林亭探得古槎','皇甫冉','quantangshi','','卷14','千年古貌多，八月秋涛晚。
偶被主人留，那知来近远。','',''),('quantangshi-13233','送郑二之茅山','皇甫冉','quantangshi','','卷14','水流绝涧终日，草长深山暮春。
犬吠鸡鸣几处，条桑种杏何人。','',''),('quantangshi-13234','和王给事禁省梨花咏','皇甫冉','quantangshi','','卷14','巧解逢人笑，还能乱蝶飞。
春时风入户，几片落朝衣。','',''),('quantangshi-13235','送郑员外入茅山居','皇甫冉','quantangshi','','卷14','但见全家去，宁知几日还。
白云迎谷口，流水出人间。
冠冕情遗世，神仙事满山。
其中应有物，岂贵一身闲。','',''),('quantangshi-13236','送志弥师往淮南','皇甫冉','quantangshi','','卷14','已能持律藏，复去礼禅亭。
长老偏摩顶，时流尚诵经。
独行寒野旷，旅宿远山青。
眷属空相望，鸿飞已杳冥。','',''),('quantangshi-13237','谢韦大夫柳栽','皇甫冉','quantangshi','','卷14','本在胡笳曲，今从汉将营。
浓阴方待庇，弱植岂无情。
比雪花应吐，藏乌叶未成。
五株蒙远赐，应使号先生。','',''),('quantangshi-13238','问李二司直所居云山','皇甫冉','quantangshi','','卷14','门外水流何处，天边树遶谁家。
山色东西多少，朝朝几度云遮。','',''),('quantangshi-13239','刘侍御朝命许停官归侍','皇甫冉','quantangshi','','卷14','孟孙唯问孝，莱子复辞官。
幸遂温凊愿，其甘稼穑难。
采芝供上药，拾槿奉晨餐。
栋里云藏雨，山中暑带寒。
非时应有笋，闲地尽生兰。
赐告承优诏，长筵永日欢。','',''),('quantangshi-13240','送陆鸿渐赴越','皇甫冉','quantangshi','','卷14','行随新树深，梦隔重江远。
迢递风日间，苍茫洲渚晚。','',''),('quantangshi-13241','送窦叔向','皇甫冉','quantangshi','','卷14','楚客怨逢秋，闲吟兴非一。
弃官守贫病，作赋推文律。
樵径未经霜，茅檐初负日。
今看泛月去，偶见乘潮出。
卜地会为隣，还依仲长室。','',''),('quantangshi-13242','题蒋道士房','皇甫冉','quantangshi','','卷14','轩窗缥缈起烟霞，诵诀存思白日斜。
闻道昆仑有仙籍，何时青鸟送丹砂。','',''),('quantangshi-13243','夜集张諲所居','皇甫冉','quantangshi','','卷14','江南成久客，门馆日萧条。
惟有图书在，多伤鬓发凋。
诸生陪讲诵，稚子给渔樵。
虚室寒灯静，空堦落叶飘。
沧洲自有趣，谁道隐须招。','',''),('quantangshi-13244','酬权器','皇甫冉','quantangshi','','卷14','南望江南满山雪，此情惆怅将谁说。
徒随羣吏不曾闲，顾与诸生为久别。
闻君静坐转耽书，种树葺茅还旧居。
终日白云应自足，明年芳草又何如。
人生有怀若不展，出入公门犹未免。
回舟朝夕待春风，先报华阳洞深浅。','',''),('quantangshi-13245','寄刘方平大谷田家','皇甫冉','quantangshi','','卷14','故山闻独往，樵路忆相从。
冰结泉声绝，霜清野翠浓。
篱边颍阳道，竹外少姨峯。
日夕田家务，寒烟隔几重。','',''),('quantangshi-13246','送云阳少府','皇甫冉','quantangshi','','卷14','渭曲春光无远近，池阳谷口倍芳菲。
官舍村桥来几日，残花寥落待君归。','',''),('quantangshi-13247','鲁山送别','皇甫冉','quantangshi','','卷14','凄凄游子若飘蓬，明月清罇秪暂同。
南望千山如黛色，愁君客路在其中。','',''),('quantangshi-13248','题高云客舍','皇甫冉','quantangshi','','卷14','孤兴日自深，浮云非所仰。
窗中西城峻，树外东川广。
晏起簪葛巾，闲吟倚藜杖。
阮公道在醉，庄子生常养。
五柳转扶疎，千峰恣来往。
清秋香秔获，白露寒菜长。
吴国滞风烟，平陵延梦想。
时人趋缨弁，高鸟违罗网。
世事徒乱纷，吾心方浩荡。
唯将山与水，处处谐真赏。','',''),('quantangshi-13249','台头寺愿上人院古松下有小松裁毫末新生与纤草不辨重其有凌云干霄之志与赵八员外裴十补阙同赋之','皇甫冉','quantangshi','','卷14','细草亦全高，秋毫乍堪比。
及至干霄日，何人复居此。','',''),('quantangshi-13250','渔子沟寄赵员外裴补阙','皇甫冉','quantangshi','','卷14','欲逐淮潮上，暂停渔子沟。
相望知不见，终是屡回头。','',''),('quantangshi-13251','送崔使君赴寿州','皇甫冉','quantangshi','','卷14','列郡专城分国忧，彤幨皂盖古诸侯。
仲华遇主年犹少，公瑾论兵位已酬。
草色青青宜建隼，蝉声处处杂鸣驺。
千里相思如可见，淮南木落早惊秋。','',''),('quantangshi-13252','送谢十二判官','皇甫冉','quantangshi','','卷14','四牡驱驰千里余，越山稠叠海林疎。
不辞终日离家远，应为刘公一纸书。','',''),('quantangshi-13253','送处州裴使君赴京','皇甫冉','quantangshi','','卷14','使君朝北阙，车骑发东方。
别喜天书召，宁忧地脉长。
山行朝复夕，水宿露为霜。
秋草连秦塞，孤帆落汉阳。
新衔趋建礼，旧位识文昌。
唯有东归客，应随南雁翔。','',''),('quantangshi-13254','送田济之扬州赴选','皇甫冉','quantangshi','','卷14','家贫不自给，求禄为荒年。
调补无高位，卑栖屈此贤。
江山欲霜雪，吴楚接风烟。
相去诚非远，离心亦渺然。','',''),('quantangshi-13255','送袁郎中破贼北归','皇甫冉','quantangshi','','卷14','优诏亲贤时独稀，中途紫绂（一作“绶”）换征衣。
黄香省闼登朝去，杨仆楼船振旅归。
万里长闻随战角，十年不得掩（一作“偃”）郊扉。
囗囗囗囗囗囗囗，但将词赋奉恩辉。','',''),('quantangshi-13256','同李万晚望南岳寺怀普门上人','皇甫冉','quantangshi','','卷14','释子身心无垢纷，独将衣钵去人羣。
相思晚望松林寺，唯有钟声出白云。','',''),('quantangshi-13257','奉和独孤中丞游法华寺','皇甫冉','quantangshi','','卷14','谢君临郡府，越国旧山川。
访道三千界，当仁五百年。
岩空驺驭响，树密斾旌连。
阁影凌空壁，松声助乱泉。
开门得初地，伏槛接诸天。
向背春光满，楼台古制全。
羣峰争彩翠，百谷会风烟。
香象随僧久，祥乌报客先。
清心乘暇日，稽首慕良缘。
法证无生偈，诗成大雅篇。
苍生望已久，回驾独依然。','',''),('quantangshi-13258','之京留别刘方平','皇甫冉','quantangshi','','卷14','客子慕俦侣，含凄整晨装。
邀欢日不足，况乃前期长。
离袂惜嘉月，远还劳折芳。
迟回越二陵，回首但苍茫。
乔木清宿雨，故关愁夕阳。
人言长安乐，其奈缅相望。','',''),('quantangshi-13259','出塞','皇甫冉','quantangshi','','卷14','吹角出塞门，前瞻即胡地。
三军尽回首，皆洒望乡泪。
转念关山长，行看风景异。
由来征戍客，负得轻生义。','',''),('quantangshi-13260','赴李少府庄失路','皇甫冉','quantangshi','','卷14','君家南郭白云连，正待情人弄石泉。
月照烟花迷客路，苍苍何处是伊川。','',''),('quantangshi-13261','雨雪','皇甫冉','quantangshi','','卷14','风沙悲久戍，雨雪更劳师。
绝漠无人境，将军苦战时。
山川迷向背，氛雾失旌旗。
徒念天涯隔，中人芳草期。','',''),('quantangshi-13262','馆陶李丞旧居','皇甫冉','quantangshi','','卷14','盛名天下挹余芳，弃置终身不拜郎。
词藻世传平子赋，园林人比郑公乡。
门前坠叶浮秋水，篱外寒臯带夕阳。
日日青松成古木，秪应来者为心伤。','',''),('quantangshi-13263','送刘兵曹还陇山居','皇甫冉','quantangshi','','卷14','离堂徒宴语，行子但悲辛。
虽是还家路，终为陇上人。
先秋雪已满，近夏草初新。
唯有闻羌笛，梅花曲里春。','',''),('quantangshi-13264','同李三月夜作','皇甫冉','quantangshi','','卷14','霜风惊度雁，月露皓疎林。
处处砧声发，星河秋夜深。','',''),('quantangshi-13265','同裴少府安居寺对雨','皇甫冉','quantangshi','','卷14','共结寻真会，还当退食初。
炉烟云气合，林叶雨声余。
溽暑销珍簟，浮凉入绮疏。
归心从念远，怀此复何如。','',''),('quantangshi-13266','送元晟归潜山所居','皇甫冉','quantangshi','','卷14','深山秋事早，君去复何如。
裛露收新稼，迎寒葺旧庐。
题诗即招隐，作赋是闲居。
别后空相忆，嵇康懒寄书。','',''),('quantangshi-13267','送康判官徃新安赋得江路西南永','皇甫冉','quantangshi','','卷14','不向新安去，那知江路长。
猿声比庐霍，水色胜潇湘。
驿树收残雨，渔家带夕阳。
何须愁旅泊，使者有辉光。','',''),('quantangshi-13268','宿洞灵观','皇甫冉','quantangshi','','卷14','孤烟灵洞远，积雪满山寒。
松柏凌高殿，莓苔封古坛。
客来清夜久，仙去白云残。
明日开金箓，焚香更沐兰。','',''),('quantangshi-13269','酬卢十一过宿','皇甫冉','quantangshi','','卷14','乞还方未遂，日夕望云林。
况复逢春草，何劳问此心。
闭门公务散，枉策故情深。
遥夜他乡酒，同君梁甫吟。','',''),('quantangshi-13270','酬裴十四','皇甫冉','quantangshi','','卷14','淮海各联翩，三年方一见。
素心终不易，玄发何须变。
旧国想平陵，春山满阳羡。
隣鸡莫遽唱，共惜良夜晏。','',''),('quantangshi-13271','彭祖井','皇甫冉','quantangshi','','卷14','上公旌节在徐方，旧井莓苔近寝堂。
访古因知彭祖宅，得仙何必葛洪乡。
清虚不共春池竟，盥漱偏宜夏日长。
闻道延年如玉液，欲将调鼎献明光。','',''),('quantangshi-13272','奉和对雪','皇甫冉','quantangshi','','卷14','春雪偏当夜，暄风却变寒。
庭深不复扫，城晓更宜看。
命酒闲令酌，披蓑晚未冠。
连营鼓角动，忽似战桑干。','',''),('quantangshi-13273','送萧献士','皇甫冉','quantangshi','','卷14','惆怅烟郊晚，依然此送君。
长河隔旅梦，浮客伴孤云。
淇上春山直，黎阳大道分。
西陵倘一吊，应有士衡文。','',''),('quantangshi-13274','卖药人处得南阳朱山人书','皇甫冉','quantangshi','','卷14','卖药何为者，逃名市井居。
唯通远山信，因致逸人书。
已报还丹効，全将世事疎。
秋风景溪里，萧散寄樵渔。','',''),('quantangshi-13275','初出沅江夜入湖','皇甫冉','quantangshi','','卷14','放溜出江口，回瞻松栝深。
不知舟中月，更引湖间心。','',''),('quantangshi-13276','送裴员外往江南','皇甫冉','quantangshi','','卷14','分务江南远，留欢幕下荣。
枫林萦楚塞，水驿到湓城。
岸草知春晚，沙禽好夜惊。
风帆几泊处，处处暮潮清。','',''),('quantangshi-13277','奉和王相公早春登徐州城','皇甫冉','quantangshi','','卷14','落日凭危堞，春风似故乡。
川流通楚塞，山色遶徐方。
壁垒依寒草，旌旗动夕阳。
元戎资上策，南亩起耕桑。','',''),('quantangshi-13278','奉和对山僧','皇甫冉','quantangshi','','卷14','吏散重门掩，僧来闭阁闲。
远心驰北阙，春兴寄东山。
草长风光里，莺喧静默间。
芳辰不可住，惆怅暮禽还。','',''),('quantangshi-13279','奉和待勤照上人不至','皇甫冉','quantangshi','','卷14','东洛居贤相，南方待本师。
旌麾俨欲动，杯锡杳仍迟。
积雪迷何处，惊风泊几时。
大臣能护法，况有故山期。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-13280','奉和汉祖庙下之作','皇甫冉','quantangshi','','卷14','古庙风烟积，春城车骑过。
方修汉祖祀，更使沛童歌。
寝帐巢禽出，香烟水雾和。
神心降福处，应在故乡多。','',''),('quantangshi-13281','和朝郎中扬子翫雪寄山阴严维','皇甫冉','quantangshi','','卷14','凝阴晦长箔，积雪满通川。
征客寒犹去，愁人昼更眠。
谢家兴咏日，汉将出师年。
闻有招寻兴，随君访戴船。','',''),('quantangshi-13282','闲居作','皇甫冉','quantangshi','','卷14','多病辞官罢，闲居作赋成。
图书唯药箓，饮食止藜羹。
学谢淹中术，诗无邺下名。
不堪趋建礼，讵是厌承明。
已辍金门步，方从石路行。
远山期道士，高柳觅先生。
性懒尤因疾，家贫自省营。
种苗虽尚短，谷价幸全轻。
篇咏投康乐，壶觞就步兵。
何人肯相访，开户一逢迎。','',''),('quantangshi-13283','归渡洛水','皇甫冉','quantangshi','','卷14','暝色赴春愁，归人南渡头。
渚烟空翠合，滩月碎光流。
澧浦饶芳草，沧浪有钓舟。
谁知放歌客，此意正悠悠。','',''),('quantangshi-13284','送郑二员外','皇甫冉','quantangshi','','卷14','置酒竟长宵，送君登远道。
羇心看旅雁，晚泊依秋草。
秋草尚芊芊，离忧亦渺然。
元戎辟才彦，行子犯风烟。
风烟积惆怅，淮海殊飘荡。
明日是重阳，登高远相望。','',''),('quantangshi-13285','酬崔侍御期籍道士不至兼寄','皇甫冉','quantangshi','','卷14','一心求妙道，几岁候真师。
丹竈今何在，白云无定期。
昆仑烟景绝，汗漫徃还迟。
君但焚香待，人间到有时。','',''),('quantangshi-13286','送裴陟归常州','皇甫冉','quantangshi','','卷14','夜雨须停棹，秋风暗入衣。
见君尝北望，何事却南归。','',''),('quantangshi-13287','赠别','皇甫冉','quantangshi','','卷14','南桥春日暮，杨柳带青渠。
不得同携手，空成意有余。','',''),('quantangshi-13288','和袁郎中破贼后经剡中山水','皇甫冉','quantangshi','','卷14','武库分帷幄，儒衣事鼓鼙。
兵连越徼外，寇尽海门西。
节比全疎勒，功当雪会稽。
旌旗回剡岭，士马濯耶溪。
受律梅初发，班师草未齐。
行看佩金印，岂得访丹梯。','',''),('quantangshi-13289','徐州送丘侍御之越','皇甫冉','quantangshi','','卷14','时鸟催春色，离人惜岁华。
远山随拥传，芳草引还家。
北固潮当阔，西陵路稍斜。
纵令寒食过，犹有镜中花。','',''),('quantangshi-13290','闲居','皇甫冉','quantangshi','','卷14','桃红复含宿雨，柳绿更带春烟。
花落家童未扫，莺啼山客犹眠。','',''),('quantangshi-13291','送延陵陈法师赴上元','皇甫冉','quantangshi','','卷14','延陵初罢讲，建业去随缘。
翻译推多学，坛场最少年。
浣衣逢野水，乞食向人烟。
遍礼南朝寺，焚香古像前。','',''),('quantangshi-13292','赋得海边树','皇甫冉','quantangshi','','卷14','历历缘荒岸，溟溟入远天。
每同沙草发，长共水云连。
摇落潮风早，离披海雨偏。
故伤游子意，多在客舟前。','',''),('quantangshi-13293','题昭上人房','皇甫冉','quantangshi','','卷14','沃州传敎后，百衲老空林。
虑尽朝昏磬，禅随坐卧心。
鹤飞湖草迥，门闭野云深。
地与天台接，中峯早晚寻。','',''),('quantangshi-13294','送李使君赴抚州','皇甫冉','quantangshi','','卷14','远送临川守，还同康乐侯。
岁时徒改易，今古接风流。
五马嘶长道，双旌向本州。
乡心寄西北，应上郡城楼。','',''),('quantangshi-13295','同樊润州游郡东山','皇甫冉','quantangshi','','卷14','北固多陈迹，东山复盛游。
铙声发大道，草色引行驺。
此地何时有，长江自古流。
频随公府步，南客寄徐州。','',''),('quantangshi-13296','酬杨侍御寺中见招','皇甫冉','quantangshi','','卷14','贫居依柳市，闲步在莲宫。
高阁宜春雨，长廊好啸风。
诚如双树下，岂比一丘中。','',''),('quantangshi-13297','重阳日酬李观','皇甫冉','quantangshi','','卷14','不见白衣来送酒，但令黄菊自开花。
愁看日晚良辰过，步步行寻陶令家。','',''),('quantangshi-13298','寄权器','皇甫冉','quantangshi','','卷14','露湿青芜时欲晚，水流黄叶意无穷。
节近重阳念归否，眼前篱菊带秋风。','',''),('quantangshi-13299','酬李判官度梨岭见寄','皇甫冉','quantangshi','','卷14','陇首怨西征，岭南雁北顾。
行人与流水，共向闽中去。','',''),('quantangshi-13300','送魏六侍御葬','皇甫冉','quantangshi','','卷14','哭葬寒郊外，行将何所从。
盛曹徒列柏，新墓已栽松。
海月同千古，江云覆几重。
旧书曾谏猎，遗草议登封。
畴昔轻三事，尝期老一峯。
门临商岭道，窗引洛城钟。
应积泉中恨，无因世上逢。
招寻偏见厚，疎慢亦相容。
张范唯通梦，求羊永绝踪。
谁知长卿疾，歌赋不还邛。','',''),('quantangshi-13301','送张道士归茅山谒李尊师','皇甫冉','quantangshi','','卷14','向山独有一人行，近洞应逢双鹤迎。
尝以素书传弟子，还因白石号先生。
无穷杏树行时种，几许芝田向月耕。
师事少君年岁久，欲随旄节徃层城。','',''),('quantangshi-13302','酬裴补阙吴寺见寻','皇甫冉','quantangshi','','卷14','东林初结构，已有晚钟声。
窻户背流水，房廊半架城。
远山重叠见，芳草浅深生。
每与君携手，多烦长老迎。','',''),('quantangshi-13303','送王相公之幽州','皇甫冉','quantangshi','','卷14','自昔萧曹任，难兼卫霍功。
勤劳无远近，旌节屡西东。
不选三河卒，还令万里通。
雁行缘古塞，马鬣起长风。
遮虏关山静，防秋鼓角雄。
徒思一攀送，羸老荜门中。','',''),('quantangshi-13304','题竹扇赠别','皇甫冉','quantangshi','','卷14','湘竹殊堪制，齐纨且未工。
幸亲芳袖日，尤带旧林风。
掩笑歌筵里，传书卧阁中。
竟将为别赠，宁与合欢同。','',''),('quantangshi-13305','归阳羡兼送刘八长卿','皇甫冉','quantangshi','','卷14','湖上孤帆别，江南谪宦归。
前程愁更远，临水泪沾衣。
云梦春山徧，潇湘过客稀。
武陵招我隐，岁晚闭柴扉。','',''),('quantangshi-13306','东郊迎春','皇甫冉','quantangshi','','卷14','晓见苍龙驾，东郊春已迎。
彩云天仗合，玄象太阶平。
佳气山川秀，和风政令行。
句陈霜骑肃，御道雨师清。
律向韶阳变，人随草木荣。
遥观上林树，今日遇迁莺。','',''),('quantangshi-13307','招隐寺送阎判官还江州','皇甫冉','quantangshi','','卷14','离别那逢秋气悲，东林更作上方期。
共知客路浮云外，暂爱僧房坠叶时。
长江九派人归少，寒岭千重雁度迟。
借问浔阳在何处，每看潮落一相思。','',''),('quantangshi-13308','送李山人还','皇甫冉','quantangshi','','卷14','从来无检束，只欲老烟霞。
鸡犬声相应，深山有几家。','',''),('quantangshi-13309','韦中丞西厅海榴','皇甫冉','quantangshi','','卷14','海花争让候榴花，犯雪先开内史家。
末客朝朝铃阁下，从公步履玩年华。','',''),('quantangshi-13310','洪泽馆壁见故礼部尚书题诗','皇甫冉','quantangshi','','卷14','底事洪泽壁，空留黄绢词。
年年淮水上，行客不胜悲。','',''),('quantangshi-13311','望南山雪怀山寺普上人','皇甫冉','quantangshi','','卷14','夜夜梦莲宫，无由见远公。
朝来出门望，知在雪山中。','',''),('quantangshi-13312','送夔州班使君','皇甫冉','quantangshi','','卷14','晚日照楼边，三军拜峡前。
白云随浪散，青壁与山连。
万岭岷峨雪，千家橘柚川。
还如赴河内，天上去经年。','',''),('quantangshi-13313','寻戴处士','皇甫冉','quantangshi','','卷14','车马长安道，谁知大隐心。
蛮僧留古镜，蜀客寄新琴。
晒药竹斋暖，捣茶松院深。
思君一相访，残雪似山阴。','',''),('quantangshi-13314','早发中严寺别契上人','皇甫冉','quantangshi','','卷14','苍苍松桂阴，残月半西岑。
素壁寒灯暗，红炉夜火深。
厨开山鼠散，钟尽岭猿吟。
行役方如此，逢师懒话心。','',''),('quantangshi-13315','华清宫','皇甫冉','quantangshi','','卷14','骊岫接新丰，岧峣驾翠空。
凿山开祕殿，隐雾闭仙宫。
绛阙犹栖凤，雕梁尚带虹。
温泉曾浴日，华馆旧迎风。
肃穆瞻云辇，沈深闭绮栊。
东郊倚望处，瑞气霭蒙蒙。','',''),('quantangshi-13316','送孔巢父赴河南军','皇甫冉','quantangshi','','卷14','江城相送阻烟波，况复新秋一雁过。
闻道全师征北虏，更言诸将会南河。
边心杳杳乡人绝，塞草青青战马多。
共许陈琳工奏记，知君名宦未蹉跎。','',''),('quantangshi-13317','李二侍御丹阳东去新亭','皇甫冉','quantangshi','','卷14','姑苏东望海陵间，几度裁书信未还。
长在府中持白简，岂知天畔有青山。
人归极浦寒流广，雁下平芜秋野闲。
旧日新亭更携手，他乡风景亦相关。','',''),('quantangshi-13318','夜发沅江寄李颍川刘侍郎','皇甫冉','quantangshi','','卷14','半夜回舟入楚乡，月明山水共苍苍。
孤猨更发秋风里，不是愁人亦断肠。','',''),('quantangshi-13319','浪淘沙二首 一','皇甫冉','quantangshi','','卷14','蛮歌豆蔻北人愁，松雨蒲风野艇秋。
浪起䴔䴖眠不得，寒沙细细入江流。','',''),('quantangshi-13320','浪淘沙二首 二','皇甫冉','quantangshi','','卷14','濑头细草接疎林，恶浪罾船半欲沈。
宿鹭眠洲非旧浦，去年沙觜是江心。','',''),('quantangshi-13321','春思','皇甫冉','quantangshi','','卷14','莺啼燕语报新年，马邑龙堆路几千。
家住秦城邻汉苑，心随明月到胡天。
机中锦字论长恨，楼上花枝笑独眠。
为问元戎窦车骑，何时反斾勒燕然。','',''),('quantangshi-13322','逢庄纳因赠','皇甫冉','quantangshi','','卷14','世故还相见，天涯共向东。
春归江海上，人老别离中。
郡吏名何晚，沙鸥道自同。
甘泉须早献，且莫叹飘蓬。','',''),('quantangshi-13323','送韦山人归钟山所居','皇甫冉','quantangshi','','卷14','逸人归路远，弟子出山迎。
服药颜虽驻，耽书癖已成。
柴扉度岁月，藜杖见公聊。
更作儒林传，还应有姓名。','',''),('quantangshi-13324','送普门上人','皇甫冉','quantangshi','','卷14','花宫难久别，道者忆千灯。
残雪入林路，深山归寺僧。
日光依嫩草，泉响滴春冰。
何用求方便，看心是一乘。','',''),('quantangshi-13325','怨回纥歌二首 一','皇甫冉','quantangshi','','卷14','白首南朝女，愁听异域歌。
收兵颉利国，饮马胡芦河。
毳布腥膻久，穹庐岁月多。
雕巢城上宿，吹笛泪滂沱。','',''),('quantangshi-13326','怨回纥歌二首 二','皇甫冉','quantangshi','','卷14','祖席驻征棹，开帆信候潮。
隔烟桃叶泣，吹管杏花飘。
船去鸥飞阁，人归尘上桥。
别离惆怅泪，江路湿红蕉。','',''),('quantangshi-13327','句','皇甫冉','quantangshi','','卷14','微官同侍苍龙阙，直谏偏推白马生。','',''),('quantangshi-13328','代宛转歌二首 一','劉方平','quantangshi','','卷14','星参差，明月二八灯五枝。
黄鹤瑶琴将别去，芙蓉羽帐惜空垂。
歌宛转，宛转恨无穷。
愿为潮与浪，俱起碧流中。','',''),('quantangshi-13329','代宛转歌二首 二','劉方平','quantangshi','','卷14','晓将近，黄姑织女银河尽。
九华锦衾无复情，千金宝镜谁能引。
歌宛转，宛转伤别离。
愿作杨与柳，同向玉窗垂。','',''),('quantangshi-13330','乌栖曲二首 一','劉方平','quantangshi','','卷14','蛾眉曼脸倾城国，鸣环动佩新相识。
银汉斜临白玉堂，芙蓉行障掩灯光。','',''),('quantangshi-13331','乌栖曲二首 二','劉方平','quantangshi','','卷14','画舸双艚锦为缆，芙蓉花发莲叶暗。
门前月色映横塘，感郎中夜度潇湘。','',''),('quantangshi-13332','巫山高','劉方平','quantangshi','','卷14','楚国巫山秀，清猨日夜啼。
万重春树合，十二碧峰齐。
峡出朝云下，江来暮雨西。
阳台归路直，不畏向家迷。','',''),('quantangshi-13333','巫山神女','劉方平','quantangshi','','卷14','神女藏难识，巫山秀莫羣。
今宵为大雨，昨日作孤云。
散漫愁巴峡，徘徊恋楚君。
先王为立庙，春树几氛氲。','',''),('quantangshi-13334','梅花落','劉方平','quantangshi','','卷14','新岁芳梅树，繁花四面同。
春风吹渐落，一夜几枝空。
少妇今如此，长城恨不穷。
莫将辽海雪，来比后庭中。','',''),('quantangshi-13335','铜雀妓','劉方平','quantangshi','','卷14','遗令奉君王，嚬蛾强一妆。
岁移陵树色，恩在舞衣香。
玉座生秋气，铜台下夕阳。
泪痕霑井干，舞袖为谁长。','',''),('quantangshi-13336','秋夜思','劉方平','quantangshi','','卷14','旅梦何时尽，征途望每赊。
晚秋淮上水，新月楚人家。
猨啸空山近，鸿飞极浦斜。
明朝南岸去，言折桂枝花。','',''),('quantangshi-13337','秋夜泛舟','劉方平','quantangshi','','卷14','林塘夜发舟，虫响荻飕飕。
万影皆因月，千声各为秋。
岁华空复晚，乡思不堪愁。
西北浮云外，伊川何处流。','',''),('quantangshi-13338','折杨枝','劉方平','quantangshi','','卷14','官渡初杨柳，风来亦动摇。
武昌行路好，应为最长条。
叶映黄鹂夕，花繁白雪朝。
年年攀折意，流恨入纤腰。','',''),('quantangshi-13339','班婕妤','劉方平','quantangshi','','卷14','夕殿别君王，宫深月似霜。
人幽在长信，萤出向昭阳。
露浥红兰湿，秋凋碧树伤。
惟当合欢扇，从此箧中藏。','',''),('quantangshi-13340','新春','劉方平','quantangshi','','卷14','南陌春风早，东隣曙色斜。
一花开楚国，双燕入卢家。
眠罢梳雪髻，妆成上锦车。
谁知如昔日，更浣越溪纱。','',''),('quantangshi-13341','寄严八判官','劉方平','quantangshi','','卷14','洛阳新月动秋砧，瀚海沙场天半阴。
出塞能全仲叔策，安亲更切老莱心。
汉家宫里风云晓，羌笛声中雨雪深。
怀袖未传三岁字，相思空作陇头吟。','',''),('quantangshi-13342','秋夜寄皇甫冉郑丰','劉方平','quantangshi','','卷14','洛阳清夜白云归，城里长河列宿稀。
秋后见飞千里雁，月中闻捣万家衣。
长怜西雍青门道，久别东吴黄鹄矶。
借问客书何所寄，用心不啻两乡违。','',''),('quantangshi-13343','寄陇右严判官','劉方平','quantangshi','','卷14','副相西征重，苍生属望晨。
还同周薄伐，不取汉和亲。
虏阵摧枯易，王师决胜频。
高旗临鼓角，太白静风尘。
赤狄争归化，青羌已请臣。
遥传阃外美，盛选幕中宾。
玉劒光初发，冰壶色自真。
忠贞期报主，章服岂荣身。
边草含风绿，征鸿过月新。
胡笳长出塞，陇水半归秦。
绝漠多来往，连年厌苦辛。
路经西汉雪，家掷后园春。
谁念烟云里，深居汝颍滨。
一丛黄菊地，九日白衣人。
松叶疎开岭，桃花密映津。
缣书若有寄，为访许由邻。','',''),('quantangshi-13344','拟娼楼节怨','劉方平','quantangshi','','卷14','上苑离离莺度，昆明幂幂蒲生。
时光春华可惜，何须对镜含情。','',''),('quantangshi-13345','采莲曲','劉方平','quantangshi','','卷14','落日晴江里，荆歌艳楚腰。
采莲从小惯，十五即乘潮。','',''),('quantangshi-13346','长信宫','劉方平','quantangshi','','卷14','梦里君王近，宫中河汉高。
秋风能再热，团扇不辞劳。','',''),('quantangshi-13347','京兆眉','劉方平','quantangshi','','卷14','新作蛾眉样，谁将月里同。
有来凡几日，相效满城中。','',''),('quantangshi-13348','春雪','劉方平','quantangshi','','卷14','飞雪带春风，裴回乱绕空。
君看似花处，偏在洛阳东。','',''),('quantangshi-13349','望夫石','劉方平','quantangshi','','卷14','佳人成古石，藓驳覆花黄。
犹有春山杏，枝枝似薄妆。','',''),('quantangshi-13350','送别','劉方平','quantangshi','','卷14','华亭霁色满今朝，云里樯竿去转遥。
莫怪山前深复浅，清淮一日两回潮。','',''),('quantangshi-13351','夜月','劉方平','quantangshi','','卷14','更深月色半人家，北斗阑干南斗斜。
今夜偏知春气暖，虫声新透绿窗纱。','',''),('quantangshi-13352','春怨','劉方平','quantangshi','','卷14','纱窗日落渐黄昏，金屋无人见泪痕。
寂寞空庭春欲晚，梨花满地不开门。','',''),('quantangshi-13353','代春怨','劉方平','quantangshi','','卷14','朝日残莺伴妾啼，开帘只见草萋萋。
庭前时有东风入，杨柳千条尽向西。','',''),('quantangshi-13354','宣州东峰亭各赋一物得古壁苔','劉太真','quantangshi','','卷14','苒苒温寒泉，绵绵古危壁。
光含孤翠动，色与暮云寂。
深浅松月间，幽人自登历。','',''),('quantangshi-13355','顾十二况左迁过韦苏州房杭州韦睦州三使君皆有郡中燕集诗辞章高丽鄙夫之所仰慕顾生既至留连笑语因亦成篇以继三君子之风焉','劉太真','quantangshi','','卷14','宠至乃不惊，罪及非无由。
奔迸历畏途，缅貌赴偏陬。
牧此雕弊甿，属当赋敛秋。
凤兴谅无补，旬暇焉敢休。
前日怀友生，独登城上楼。
迢迢西北望，远思不可收。
今曰车骑来，旷然销人忧。
晨迎东斋饭，晚度南溪游。
以我碧流水，泊君青翰舟。
莫将迁客程，不为胜境留。
飞札谢三守，斯篇希见酬。','',''),('quantangshi-13356','贡院寄前主司萧尚书听','劉太真','quantangshi','','卷14','独坐贡闱里，愁心芳草生。
山公昨夜事，应见此时情。','',''),('quantangshi-13357','东峰亭同刘太真各赋一物得垂涧藤','袁傪','quantangshi','','卷14','寒涧留不息，古藤终日垂。
迎风仍未定，拂水更相宜。
新花与旧叶，惟有幽人知。','',''),('quantangshi-13358','喜陆侍御破石埭草寇东峰亭赋诗','袁傪','quantangshi','','卷14','古诗东峰上，登临兴有余。
同观白简使，新报赤囊书。
几处闲烽堠，千方庆里闾。
欣欣夏木长，寂寂晚烟徐。
战罢言归马，远师赋出车。
因知越范蠡，湖海意[何如]。','',''),('quantangshi-13359','东峰亭各赋一物得岭上云','崔何','quantangshi','','卷14','伫立增远意，中峰见孤云。
溶溶傍危石，片片宜夕曛。
渐向羣木尽，残飞更氤氲。','',''),('quantangshi-13360','喜陆侍御破石埭草寇东峰亭赋诗','崔何','quantangshi','','卷14','绝景西溪寺，连延近郭山。
高深清扃外，行止翠微间。
江澈烟尘静，川源草树闲。
中丞健步到，柱史捷书还。
一战清戎越，三吴变险艰。
功名麟阁上，得咏入秦关。','',''),('quantangshi-13361','东峰亭各赋一物得幽径石','王緯','quantangshi','','卷14','片石东溪上，阴崖剩阻修。
雨余青石霭，岁晚绿苔幽。
从来不可转，今日为人留。','',''),('quantangshi-13362','喜陆侍御破石埭草寇东峰亭赋诗','王緯','quantangshi','','卷14','蜂虿聚吴州，推贤奉圣忧。
忠诚资上策，仁勇佐前筹。
草木成鹅鹳，戈鋋复斗牛。
戎车一战后，残垒五兵收。
野静山戎险，江平水面流。
更怜羁旅客，从此罢葵丘。','',''),('quantangshi-13363','东峰亭各赋一物得临轩桂','郭澹','quantangshi','','卷14','青青芳桂树，幽阴在庭轩。
向日阴还合，从风叶乍翻。
共看霜雪后，终不变凉暄。','',''),('quantangshi-13364','喜陆侍御破石埭草寇东峰亭赋诗','郭澹','quantangshi','','卷14','介胄鹰扬出，山林蚁聚空。
忽闻飞简报，曾是坐筹功。
逈夜昏氛灭，危亭眺望雄。
茂勋推世上，余兴寄杯中。
喜色烟霞改，欢忻里巷同。
幸兹尊俎末，饮至又从公。','',''),('quantangshi-13365','东峰亭各赋一物得林中翠','高傪','quantangshi','','卷14','杳霭无定状，霏微常满林。
清风光不散，过雨色偏深。
幽意赏难尽，终朝再招寻。','',''),('quantangshi-13366','东峰亭各赋一物得栖烟鸟','李岑','quantangshi','','卷14','从来养毛羽，昔日曾飞迁。
变转对朝阳，差池栖夕烟。
遇此枝叶覆，夙举冀冲天。','',''),('quantangshi-13367','东峰亭各赋一物得寒溪草','蘇寓','quantangshi','','卷14','幂䍥溪边草，游人不厌看。
余芳幽处老，深色望中寒。
幸得陪情兴，青青赏未阑。','',''),('quantangshi-13368','东峰亭各赋一物得阴崖竹','袁邕','quantangshi','','卷14','终岁寒苔色，寂寥幽思深。
朝歌犹夕岚，日永流清阴。
龙钟负烟雪，自有凌云心。','',''),('quantangshi-13369','唐德明兴圣庙乐章 迎神','李紓','quantangshi','','卷14','元尊九德，佐尧光宅。
烈祖太宗，方周作伯。
响怀霜露，乐变金石。
白云青风，仿髴来格。','',''),('quantangshi-13370','唐德明兴圣庙乐章 登歌奠币','李紓','quantangshi','','卷14','四时有典，百事来祭。
尊祖奉宗，严禋大帝。
礼先苍璧，奠备黝制。
于万斯年，熙成帝系。','',''),('quantangshi-13371','唐德明兴圣庙乐章 迎俎','李紓','quantangshi','','卷14','盛牲实俎，涓选休成。
鼎煁阳燧，玉盥阴精。
有飶嘉豆，既和大羹。
侑以清乐，细齐人情。','',''),('quantangshi-13372','唐德明兴圣庙乐章 德明酌献','李紓','quantangshi','','卷14','清庙弈弈，和乐雍雍。
器尊牺象，礼属宗公。
白水方[裸]，黄流在中。
谟明之德，万古清风。','',''),('quantangshi-13373','唐德明兴圣庙乐章 兴圣酌献','李紓','quantangshi','','卷14','閟宫静谧，合乐周张。
泰尊始献，百末重觞。
震澹存诚，庶几迪尝。
遥源之祚，天汉灵长。','',''),('quantangshi-13374','唐德明兴圣庙乐章 亚献终献','李紓','quantangshi','','卷14','惟清惟肃，靡闻靡见。
举备九成，俛终三献。
庆彰曼寿，胙撤嘉荐。
瘗玉埋牲，礼神斯徧。','',''),('quantangshi-13375','唐德明兴圣庙乐章 送神','李紓','quantangshi','','卷14','元精回复，灵贶繁滋。
风洒兰路，云摇桂旗。
高丘缅邈，凉部逶迟。
瞻望靡及，缠绵永思。','',''),('quantangshi-13376','让皇帝庙乐章 迎神','李紓','quantangshi','','卷14','皇矣天宗，德先王季。
因心则友，克让以位。
爰命有司，式尊前志。
神其降灵，昭飨祀事。','',''),('quantangshi-13377','让皇帝庙乐章 奠币','李紓','quantangshi','','卷14','惟帝时若，去而上仙。
祀用商武，乐备宫悬。
白壁加荐，玄纁告虔。
子孙拜后，承兹吉蠲。','',''),('quantangshi-13378','让皇帝庙乐章 迎俎','李紓','quantangshi','','卷14','祀盛体荐，礼协粢盛。
方周假庙，用鲁纯牲。
捧撤祗敬，击拊和鸣。
受厘归胙，既戒而平。','',''),('quantangshi-13379','让皇帝庙乐章 酌献','李紓','quantangshi','','卷14','八音具举，三寿既盥。
洁兹宗彝，瑟彼圭瓒。
兰肴重错，椒醑飘散。
降祚维城，永为藩翰。','',''),('quantangshi-13380','让皇帝庙乐章 亚献终献','李紓','quantangshi','','卷14','秩礼有序，和音既同。
九仪不忒，三揖将终。
孝感藩后，相维辟公。
四时之典，永永无穷。','',''),('quantangshi-13381','让皇帝庙乐章 送神','李紓','quantangshi','','卷14','奠献已事，昏昕载分。
风摇雨散，灵卫絪緼。
龙驾帝服，已腾五云。
泮宫复閟，寂寞无闻。','',''),('quantangshi-13382','释奠武成王乐章 迎神','于邵','quantangshi','','卷14','卜畋不从，兆发非熊。
乃倾荒政，爰佐一戎。
盛烈载垂，命祀维崇。
日练上戊，宿严閟宫。
迎奏嘉至，感而遂通。','',''),('quantangshi-13383','释奠武成王乐章 奠币登歌','于邵','quantangshi','','卷14','管罄升，坛芗集。
上公进，嘉币执。
信以通，僾如及。
恢帝功，锡后邑。
四维张，百度立。
绵亿载，邈难挹。','',''),('quantangshi-13384','释奠武成王乐章 迎俎酌献','于邵','quantangshi','','卷14','五齐絜，九牢硕。
梡橛循，罍斝涤。
进具物，扬鸿绩。
和奏发，高灵寂。
虔告终，繁祉锡。
昭秩祀，永无易。','',''),('quantangshi-13385','释奠武成王乐章 亚献终献','于邵','quantangshi','','卷14','贰觞以献，三变其终。
顾此非馨，尚达斯衷。
茅缩可致，神歆载融。
始神翊周，拯溺除凶。
时维降佑，永绝兴戎。','',''),('quantangshi-13386','释奠武成王乐章 送神','于邵','quantangshi','','卷14','明祀方终，备乐斯阕。
黝纁就瘗，豆笾告撤。
肸蠁尚余，光景云灭。
返归虚极，神心则悦。','',''),('quantangshi-13387','登鹳雀楼','王之渙','quantangshi','','卷14','白日依山尽，黄河入海流。
欲穷千里目，更上一层楼。','',''),('quantangshi-13388','送别','王之渙','quantangshi','','卷14','杨柳东风树，青青夹御河。
近来攀折苦，应为别离多。','',''),('quantangshi-13389','凉州词二首” 一','王之渙','quantangshi','','卷14','黄河远上白云间，一片孤城万仞山。
羌笛何须怨杨柳，春光不度玉门关。','',''),('quantangshi-13390','凉州词二首” 二','王之渙','quantangshi','','卷14','单于北望拂云堆，杀马登坛祭几回。
汉家天子今神武，不肯和亲归去来。','',''),('quantangshi-13391','宴词','王之渙','quantangshi','','卷14','长堤春水绿悠悠，畎入漳河一道流。
莫听声声催去棹，桃溪浅处不胜舟。','',''),('quantangshi-13392','九日送别','王之渙','quantangshi','','卷14','蓟庭萧瑟故人稀，何处登高且送归。
今日暂同芳菊酒，明朝应作断蓬飞。','',''),('quantangshi-13393','晚秋石门礼拜','閻防','quantangshi','','卷14','轻策临绝壁，招提谒金仙。
舟车无由径，岩峤乃属天。
踯躅淹昃景，夷犹望新弦。
石门变暝色，谷口生人烟。
阳雁叫平楚，秋风急寒川。
驰晖苦代谢，浮脆慙贞坚。
永欲卧丘壑，息心依梵筵。
誓将历劫愿，无以外物牵。','',''),('quantangshi-13394','百丈溪新理茅茨读书','閻防','quantangshi','','卷14','浪迹弃人世，远山自幽独。
始傍巢由踪，吾其获心曲。
荒庭何所有，老树半空腹。
秋蜩鸣北林，暮鸟穿我屋。
栖迟乐遵渚，恬旷寡所欲。
开卦推盈虚，散帙攻节目。
养闲度人事，达命知止足。
不学东周儒，俟时劳伐辐。','',''),('quantangshi-13395','宿岸道人精舍','閻防','quantangshi','','卷14','早岁参道风，放情入寥廓。
重因息心侣，遂果岩下诺。
敛迹辞人间，杜门守寂寞。
秋风翦兰蕙，霜气冷淙壑。
山牖见然灯，竹房闻捣药。
愿言舍尘事，所趣非龙蠖。','',''),('quantangshi-13396','夕次鹿门山作','閻防','quantangshi','','卷14','庞公嘉遯所，浪迹难追攀。
浮舟暝始至，抱杖聊自闲。
双岩开鹿门，百谷集珠湾。
喷薄湍上水，舂容漂里山。
焦原不足险，梁壑未成艰。
我行自春仲，夏鸟忽緜蛮。
蕙草色已晚，客心殊倦还。
远游非避地，访道爱童颜。
安能徇机巧争夺锥刀间。','',''),('quantangshi-13397','与永乐诸公夜泛黄河作','閻防','quantangshi','','卷14','烟深载酒入，但觉暮川虚。
映水见山火，鸣榔闻夜渔。
爱兹山水趣，忽与人世疎。
无暇然官烛，中流有望舒。','',''),('quantangshi-13398','句','閻防','quantangshi','','卷14','熊踞庭中树，龙蒸栋里云。','',''),('quantangshi-13399','怀哉行','薛據','quantangshi','','卷14','明时无废人，广厦无弃材。
良工不我顾，有用宁自媒。
怀策望君门，岁晏空迟回。
秦城多车马，日夕飞尘埃。
伐鼓千门启，鸣珂双阙来。
我闻雷雨施，天泽罔不该。
何意斯人徒，弃之如死灰。
主好臣必効，时禁权不开。
俗流实骄矜，得志轻草莱。
文王赖多士，汉帝资羣才。
一言竝拜相，片善咸居台。
夫君何不遇，为泣黄金台。','',''),('quantangshi-13400','古兴','薛據','quantangshi','','卷14','日中望双阙，轩盖扬飞尘。
鸣佩初罢朝，自言皆近臣。
光华满道路，意气安可亲。
归来宴高堂，广筵罗八珍。
仆妾尽绮纨，歌舞夜达晨。
四时固相代，谁能久要津。
已看覆前车，未见易后轮。
丈夫须兼济，岂能乐一身。
君今皆得志，肯顾憔悴人。','',''),('quantangshi-13401','冬夜寓居寄储太祝','薛據','quantangshi','','卷14','自为洛阳客，夫子吾知音。
爱义能下士，时人无此心。
奈何离居夜，巢鸟飞空林。
愁坐至月上，复闻南邻砧。','',''),('quantangshi-13402','登秦望山','薛據','quantangshi','','卷14','南登秦望山，目极大海空。
朝阳半荡漾，晃朗天水红。
溪壑争喷薄，江湖遰交通。
而多渔商客，不悟岁月穷。
振缗迎早潮，弭棹候长风。
予本萍泛者，乘流任西东。
茫茫天际帆，栖泊何时同。
将寻会稽迹，从此访任公。','',''),('quantangshi-13403','西陵口观海','薛據','quantangshi','','卷14','长江漫汤汤，近海势弥广。
在昔胚浑凝，融为百川泱。
地形失端倪，天色灒滉漾。
东南际万里，极目远无象。
山影乍浮沈，潮波忽来往。
孤帆或不见，棹歌犹想像。
日暮长风起，客心空振荡。
浦口霞未收，潭心月初上。
林屿几邅回，亭臯时偃仰。
岁晏访蓬瀛，真游非外奖。','',''),('quantangshi-13404','题鹤林寺','薛據','quantangshi','','卷14','道门隐形胜，向背临法桥。
松覆山殿冷，花藏溪路遥。
珊珊宝幡挂，焰焰明灯烧。
迟日半空谷，春风连上潮。
少凭水木兴，暂忝身心调。
愿谢携手客，兹山禅侣饶。','',''),('quantangshi-13405','初去郡斋书怀','薛據','quantangshi','','卷14','肃徒辞汝頴，怀古独凄然。
尚想文王化，犹思巢父贤。
时移多谗巧，大道竟谁传。
况是疾风起，悠悠旌斾悬。
征鸟无返翼，归流不停川。
已经霜雪下，乃验松柏坚。
回首望城邑，迢迢间云烟。
志士不伤物，小人皆自妍。
感时惟责己，在道非怨天。
从此适乐土，东归知几年。','',''),('quantangshi-13406','出青门往南山下别业','薛據','quantangshi','','卷14','旧居在南山，夙驾自城阙。
榛莽相蔽亏，去尔渐超忽。
散漫余雪晴，苍茫季冬月。
寒风吹长林，白日原上没。
怀抱旷莫伸，相知阻胡越。
弱年好栖隐，炼药在岩窟。
及此离垢氛，兴来亦因物。
末路期赤松，斯言庶不伐。','',''),('quantangshi-13407','泊震泽口','薛據','quantangshi','','卷14','日落草木阴，舟徒泊江汜。
苍茫万象开，合沓闻风水。
洄沿值渔翁，䆗窱逢樵子。
云开天宇静，月明照万里。
早雁湖上飞，晨钟海边起。
独坐嗟远游，登岸望孤洲。
零落星欲尽，朣胧气渐收。
行藏空自秉，智识仍未周。
伍胥既仗劒，范蠡亦乘流。
歌竟鼓楫去，三江多客愁。','',''),('quantangshi-13408','题丹阳陶司马厅壁','薛據','quantangshi','','卷14','高鉴清洞彻，儒风入进难。
诏书增宠命，才子益能官。
门带山光晚，城临江水寒。
唯余好文客，时得咏幽兰。','',''),('quantangshi-13409','古兴','薛據','quantangshi','','卷14','投珠恐见疑，抱玉但垂泣。
道在君不举，功成叹何及。','',''),('quantangshi-13410','早发上东门','薛據','quantangshi','','卷14','十五能文西入秦，三十无家作路人。
时命不将明主合，布衣空惹洛阳尘。','',''),('quantangshi-13411','句','薛據','quantangshi','','卷14','省署开文苑，沧浪学钓翁。
穷冬时短晷，日尽西南天。','',''),('quantangshi-13412','秋夕会友','姚係','quantangshi','','卷14','倦客易相失，懽游无良辰。
忽然一夕间，稍慰阖家贫。
白露下庭梧，孤琴始悲辛。
回风入幽草，虫响满四邻。
会遇更何时，持杯重殷勤。','',''),('quantangshi-13413','荆山独往','姚係','quantangshi','','卷14','宿昔山水上，抱琴独踯躅。
山远去难穷，琴悲多断续。
岩重丹阳树，泉咽闻阴谷。
时下白云中，淹留秋水曲。
秋水石栏深，潺湲如喷玉。
杂芳被阴岸，坠露方消绿。
恣此平生怀，独游还自足。','',''),('quantangshi-13414','五老峰大明观赠隐者','姚係','quantangshi','','卷14','云观此山北，与君携手稀。
林端涉横水，洞口入斜晖。
颇觉鸾鹤迩，忽为烟雾飞。
故人清和客，默会琴心微。
丹术幸可授，青龙当未归。
悠悠平生意，此日复相违。','',''),('quantangshi-13415','送周愿判官归岭南','姚係','quantangshi','','卷14','早蝉望秋鸣，夜琴怨离声。
眇然多异感，值子江山行。
由来重义人，感激事纵横。
往复念遐阻，淹留慕平生。
晨奔九衢饯，暮始万里程。
山驿风月榭，海门烟霞城。
易绡泉源近，拾翠沙溆明。
兰蕙一为赠，贫交空复情。','',''),('quantangshi-13416','送陆浑主簿赵宗儒之任','姚係','quantangshi','','卷14','山中眇然意，此意乃平生。
常日望鸣臯，遥对洛阳城。
故人吏为隐，怀此若蓬瀛。
夕气冒岩上，晨流泻岸明。
存亡区中事，影响羽人情。
溪寂值猨下，云归闻鹤声。
及兹春始暮，花葛正明荣。
会有携手日，悠悠去无程。','',''),('quantangshi-13417','杨参军庄送宇文邈','姚係','quantangshi','','卷14','秋云冒原隰，野鸟满林声。
爱此田舍事，稽君车马程。
离堂惨不喧，脉脉复盈盈。
兰叶一经霜，香销为赠轻。
灯光耿方寂，虫思隐余清。
相望忽无际，如含江海情。','',''),('quantangshi-13418','京西遇旧识兼送往陇西','姚係','quantangshi','','卷14','蝉鸣一何急，日暮秋风树。
即此不胜愁，陇阴人更去。
相逢与相失，共是亡羊路。','',''),('quantangshi-13419','古别离','姚係','quantangshi','','卷14','凉风已袅袅，露重木兰枝。
独上高楼望，行人远不知。
轻寒入洞户，明月满秋池。
燕去鸿方至，年年是别离。','',''),('quantangshi-13420','野居池上看月','姚係','quantangshi','','卷14','悠然云间月，复此照池塘。
泫露苍茫湿，沈波澹滟光。
应门当未曙，歌吹满昭阳。
远近徒伤目，清辉霭自长。','',''),('quantangshi-13421','庭柳','姚係','quantangshi','','卷14','褭褭柳杨枝，当轩杂佩垂。
交阴总共密，分条各自宜。
因依似永久，揽结更伤离。
爱此阳春色，秋风莫遽吹。','',''),('quantangshi-13422','硖州旅舍奉怀苏州韦郎中','令狐峘','quantangshi','','卷14','儒服学从政，遂为尘事婴。
衔命东复西，孰堪异乡情。
怀禄且怀恩，策名敢逃名。
羡彼农亩人，白首亲友并。
江山入秋气，草木雕晚荣。
方塘寒露凝，旅管凉飙生。
懿交守东吴，梦想闻颂声。
云水方浩浩，离忧何平时。','',''),('quantangshi-13423','释奠日国学观礼闻雅颂','令狐峘','quantangshi','','卷14','肃肃先师庙，依依胄子羣。
满庭陈旧礼，开户拜清芬。
万舞当华烛，箫韶入翠云。
颂歌清晓听，雅吹度风闻。
澹泊调元气，中和美圣君。
唯余东鲁客，蹈舞向南熏。','',''),('quantangshi-13424','释奠日国学观礼闻雅颂','滕珦','quantangshi','','卷14','太学时观礼，东方晓色分。
威仪何棣棣，环佩又纷纷。
古乐从空尽，清歌几处闻。
六和成远吹，九奏动行云。
圣上尊儒学，春秋奠茂勋。
幸因陪齿列，聊以颂斯文。','',''),('quantangshi-13425','奉和圣制麟德殿燕百僚应制','常衮','quantangshi','','卷14','云辟御筵张，山呼圣寿长。
玉阑丰瑞草，金陛立神羊。
台鼎资庖膳，天星奉酒浆。
蛮夷陪作位，犀象舞成行。
网已祛三面，歌因守四方。
千秋不可极，花发满宫香。','',''),('quantangshi-13426','晚秋集贤院即事寄徐薛二侍郎','常衮','quantangshi','','卷14','穆穆上清居，沈沈中祕书。
金铺深内殿，石甃净寒渠。
花树台斜倚，空烟阁半虚。
缥囊披锦绣，翠轴卷琼琚。
墨润冰文茧，香销蠹字鱼。
翻黄桐叶老，吐白桂花初。
旧德双游处，聊芳十载余。
北朝荣庾薛，西汉盛严徐。
侍讲亲华扆，徴吟步绮疏。
缀帘金翡翠，赐砚玉蟾蜍。
序秩东南远，离忧岁月除。
承明期重入，江海意何如。','',''),('quantangshi-13427','早秋望华清宫树因以成咏','常衮','quantangshi','','卷14','可怜云木丛，满禁碧蒙蒙。
色润灵泉近，险清辇路通。
玉坛标八桂，金井识双桐。
交映凝寒露，相和起夜风。
数枝盘石上，几叶落云中。
燕拂宜秋霁，蝉鸣觉昼空。
翠屏更隐见，珠缀共玲珑。
雷雨生成早，樵苏禁令雄。
野藤高助绿，仙果迥呈红。
惆怅缭垣暮，兹山闻暗虫。','',''),('quantangshi-13428','和考功员外杪秋忆终南旧宅之作','常衮','quantangshi','','卷14','静忆溪边宅，知君许谢公。
晓霜凝耒耜，初日照梧桐。
涧鼠喧藤蔓，山禽窜石丛。
白云当岭雨，黄叶绕阶风。
野菓垂桥上，高泉落水中。
欢荣来自间，羸贱赏曾通。
月满珠藏海，天晴鹤在笼。
余阴如可寄，愿得隐墙东。','',''),('quantangshi-13429','题金吾郭将军石洑茅堂','常衮','quantangshi','','卷14','云戟曙沈沈，轩墀清且深。
家传成栋美，尧宠结茅心。
玉佩多依石，油幢亦在林。
炉香诸洞暖，殿影众山阴。
草奏风生笔，筵开雪满琴。
客从龙阙至，僧自虎溪寻。
潇洒延清赏，周流会素襟。
终朝惜尘步，一醉见华簪。','',''),('quantangshi-13430','登栖霞寺','常衮','quantangshi','','卷14','林香雨气新，山寺绿无尘。
遂结云外侣，共游天上春。
鹤鸣金阁丽，僧语竹房邻。
待月水流急，惜花风起频。
何方非坏境，此地有归人。
回首空门外，皤然一幻身。','',''),('quantangshi-13431','逢南中使寄岭外故人','常衮','quantangshi','','卷14','见说南来处，苍梧指桂林。
过秋天更暖，边海日长阴。
巴路缘云出，蛮乡入洞深。
信回人自老，梦到月应沈。
碧水通春色，青山寄远心。
炎方难久客，为尔一霑襟。','',''),('quantangshi-13432','代员将军罢战后归故里','常衮','quantangshi','','卷14','结发事疆场，全生到海乡。
连云防铁岭，同日破渔阳。
牧马胡天晚，移军碛路长。
枕戈眠古戍，吹角立繁霜。
归老勋仍在，酬恩虏未忘。
独行过邑里，多病对农桑。
雄劒依尘橐，兵符寄药囊。
空余麾下将，犹逐羽林郎。','',''),('quantangshi-13433','咏冬瑰花','常衮','quantangshi','','卷14','独鹤寄烟霜，双鸾思晚芳。
旧阴依谢宅，新艳出萧墙。
蝶散摇轻露，莺衔入夕阳。
雨朝胜濯锦，风夜剧焚香。
丽日千层艳，孤霞一片光。
密来惊叶少，动处觉枝长。
布影期高赏，留春为远方。
尝闻赠琼玖，叨和愧升堂。','',''),('quantangshi-13434','句','常衮','quantangshi','','卷14','风候已应同岭北，云山仍喜似终南。','',''),('quantangshi-13435','登圣善寺阁','褚朝陽','quantangshi','','卷14','飞阁青霞里，先秋独早凉。
天花映窗近，月桂拂檐香。
华岳三峰小，黄河一带长。
空间指归路，烟际有垂杨。','',''),('quantangshi-13436','五丝','褚朝陽','quantangshi','','卷14','越人传楚俗，截竹竞萦丝。
水底深休也，日中远贺之。
章施文胜质，列匹美于姬。
锦绣侔新段，羔羊寝旧诗。
但夸端午节，谁荐屈原祠。
把酒时伸奠，汨罗空远而。','',''),('quantangshi-13437','奉上徐中书','褚朝陽','quantangshi','','卷14','中禁仙池越凤凰，池边词客紫薇郎。
既能作颂雄风起，何不时吹兰蕙香。','',''),('quantangshi-13438','小洞庭洄源亭宴四郡太守诗','蘇源明','quantangshi','','卷14','小洞庭兮牵方舟，风袅袅兮离平流。
牵方舟兮小洞庭，云微微兮连绝𡷨。
层澜壮兮缅以没，重岩转兮超以忽。
冯夷逝兮护轻桡，蛟龙行兮落增潮。
泊中湖兮澹而闲，并曲溆兮怅而还。
适予手兮非予期，将解袂兮藂予思。
尚君子兮寿厥身，承明主兮忧斯人。','',''),('quantangshi-13439','秋夜小洞庭离宴诗','蘇源明','quantangshi','','卷14','浮涨湖兮莽迢遥，川后礼兮扈予桡。
横增沃兮蓬仙延，川后福兮易予舷。
月澄凝兮明空波，星磊落兮耿秋河。
夜既良兮酒且多，乐方作兮奈别何。','',''),('quantangshi-13440','闺情','鄭虔','quantangshi','','卷14','银钥开香阁，金台照夜灯。
长征君自惯，独卧妾何曾。','',''),('quantangshi-13441','古意','畢耀','quantangshi','','卷14','璇闺绣户斜光入，千金女儿倚门立。
横波美目虽往来，罗袂遥遥不相及。
闻道今年初避人，珊珊挂镜长随身。
愿得侍儿为道意，后堂罗帐一相亲。','',''),('quantangshi-13442','情人玉清歌','畢耀','quantangshi','','卷14','洛阳有人名玉清，可怜玉清如其名。
善踏斜柯能独立，婵娟花艳无人及。
珠为帬，玉为缨，临春风，吹玉笙。
悠悠满天星，黄金阁上晚妆成。
云和曲中为曼声，玉梯不得蹈。
摇袂两盈盈，城头之日复何情。','',''),('quantangshi-13443','赠独孤常州','畢耀','quantangshi','','卷14','洪炉无久停，日月速若飞。
忽然冲人身，饮酒不须疑。','',''),('quantangshi-13444','奉和圣制次琼岳应制','韋濟','quantangshi','','卷14','陆海披晴雪，千旗猎早阳。
岳临秦路险，河遶汉垣长。
行漏通鳷鹊，离宫接建章。
都门信宿近，歌舞从周王。','',''),('quantangshi-13445','成都为客作','田澄','quantangshi','','卷14','蜀郡将之远，城南万里桥。
衣缘乡泪湿，貌以客愁销。
地富鱼为米，山芳桂是樵。
旅游唯得酒，今日过明朝。','',''),('quantangshi-13446','奉和苑舍人宿直晓翫新池寄南省友','沈東美','quantangshi','','卷14','传闻阊阖里，寓直有神仙。
史为三坟博，郎因五字迁。
晨临翔凤沼，春注跃龙泉。
去似登天上，来如看镜前。
影摇宸翰发，波净列星悬。
既济仍怀友，流谦欲进贤。
弹冠声实贵，覆被渥恩偏。
温室言虽阻，文场契独全。
玉珂光赫奕，朱绂气蝉联。
兴逸潘仁赋，名高谢朓篇。
青云仰不逮，白云和难牵。
苒苒胡为此，甘心老岁年。','',''),('quantangshi-13447','变律 一','蘇渙','quantangshi','','卷14','日月东西行，寒暑冬夏易。
阴阳无停机，造化渺莫测。
开目为晨光，闭目为夜色。
一开复一闭，明晦无休息。
居然六合外，旷哉天地德。
天地且不言，世人浪喧喧。','',''),('quantangshi-13448','变律 二','蘇渙','quantangshi','','卷14','毒蜂成一窠，高挂恶木枝。
行人百步外，目断魂亦飞。
长安大道边，挟弹谁家儿。
右手持金丸，引满无所疑。
一中纷下来，势若风雨随。
身如万箭攒，宛转迷所之。
徒有疾恶心，奈何不知几。','',''),('quantangshi-13449','变律 三','蘇渙','quantangshi','','卷14','养蚕为素丝，叶尽蚕不老。
倾筐对空林，此意向谁道。
一女不得织，万夫受其寒。
一夫不得意，四海行路难。
祸亦不在大，福亦不在先。
世路险孟门，吾徒当勉旃。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-13450','赠零陵僧','蘇渙','quantangshi','','卷14','张颠没在二十年，谓言草圣无人传。
零陵沙门继其后，新书大字大如斗。
兴来走笔如旋风，醉后耳热心更凶。
忽如裴旻舞双劒，七星错落缠蛟龙。
又如吴生画[鬼神]，魑魅魍魉惊本身。
钩锁相连势不绝，倔强毒蛇争屈铁。
西河舞劒气凌云，孤蓬自振唯有君。
今日华堂看洒落，四座喧呼叹佳作。
回首邀余赋一章，欲令羡价齐钟张。
琅诵囗句三百字，何似醉僧颠复狂。
忽然告我游南溟，言祈亚相求大名。
亚相书翰凌献之，见君绝意必深知。
南中纸价当日贵，只恐贪泉成墨池。','',''),('quantangshi-13451','江南曲','劉眘虛','quantangshi','','卷14','美人何荡漾，湖上风日长。
玉手欲有赠，裴回双明璫。
歌声随绿水，怨色起青阳。
日暮还家望，云波横洞房。','',''),('quantangshi-13452','九日送人','劉眘虛','quantangshi','','卷14','海上正摇落，客中还别离。
同舟去未已，远送新相知。
流水意何极，满尊徒尔为。
从来菊花节，早已醉东篱。','',''),('quantangshi-13453','暮秋扬子江寄孟浩然','劉眘虛','quantangshi','','卷14','木叶纷纷下，东南日烟霜。
林山相晚暮，天海空青苍。
暝色况复久，秋声亦何长。
孤舟兼微月，独夜仍越乡。
寒笛对京口，故人在襄阳。
咏思劳今夕，江汉遥相望。','',''),('quantangshi-13454','浔阳陶氏别业','劉眘虛','quantangshi','','卷14','陶家习先隐，种柳长江边。
朝夕浔阳郭，白衣来几年。
霁云明孤岭，秋水澄寒天。
物象自清旷，野情何绵联。
萧萧丘中赏，明宰非徒然。
愿守黍稷税，归耕东山田。','',''),('quantangshi-13455','登庐山峰顶寺','劉眘虛','quantangshi','','卷14','孤峰临万象，秋气何高清。
天际南郡出，林端西江明。
山门二缁叟，振锡闻幽声。
心照有无界，业悬前后生。
虽知真机静，尚与爱网并。
方首金门路，未遑参道情。','',''),('quantangshi-13456','寻东溪还湖中作','劉眘虛','quantangshi','','卷14','出山更回首，日暮清溪深。
东岭新别处，数猨叫空林。
昔游有初迹，此路还独寻。
幽兴方在往，归怀复为今。
云峰劳前意，湖水成远心。
望望已超越，坐鸣舟中琴。','',''),('quantangshi-13457','送韩平兼寄郭微','劉眘虛','quantangshi','','卷14','上客夜相过，小童能酤酒。
即为临水处，正值归雁后。
前路望乡山，近家见门柳。
到时春未暮，风景自应有。
余忆东州人，经年别来久。
殷勤为传语，日夕念携手。
兼问前寄书，书中复达否。','',''),('quantangshi-13458','寄阎防','劉眘虛','quantangshi','','卷14','青冥南山口，君与缁锡邻。
深路入古寺，乱花随暮春。
纷纷对寂莫，往往落衣巾。
松色空照水，经声时有人。
晚心复南望，山远情独亲。
应以修往业，亦惟立此身。
深林度空夜，烟月资清真。
莫叹文明日，弥年徒隐沦。','',''),('quantangshi-13459','海上诗送薛文学归海东','劉眘虛','quantangshi','','卷14','何处归且远，送君东悠悠。
沧溟千万里，日夜一孤舟。
旷望绝国所，微茫天际愁。
有时近仙境，不定若梦游。
或见青色古，孤山百里秋。
前心方杳眇，后路劳夷犹。
离别惜吾道，风波敬皇休。
春浮花气远，思逐海水流。
日暮骊歌后，永怀空沧洲。','',''),('quantangshi-13460','越中问海客','劉眘虛','quantangshi','','卷14','风雨沧洲暮，一帆今始归。
自云发南海，万里速如飞。
初谓落何处，永将无所依。
冥茫渐西见，山色越中微。
谁念去时远，人经此路稀。
泊舟悲且泣，使我亦霑衣。
浮海焉用说，忆乡难久违。
纵为鲁连子，山路有柴扉。','',''),('quantangshi-13461','阙题','劉眘虛','quantangshi','','卷14','道由白云尽，春与青溪长。
时有落花至，远随流水香。
闲门向山路，深柳读书堂。
幽映每白日，清辉照衣裳。','',''),('quantangshi-13462','寄江滔求孟六遗文','劉眘虛','quantangshi','','卷14','南望襄阳路，思君情转亲。
偏知汉水广，应与孟家邻。
在日贪为善，昨来闻更贫。
相如有遗草，一为问家人。','',''),('quantangshi-13463','积雪为小山','劉眘虛','quantangshi','','卷14','飞雪伴春还，春庭晓自闲。
虚心应任道，遇赏遂成山。
峰小形全秀，岩虚势莫攀。
以幽能皎洁，谓近可循环。
孤影临冰境，寒光对玉颜。
不随迟日尽，留顾岁华间。','',''),('quantangshi-13464','赠乔琳','劉眘虛','quantangshi','','卷14','去年上策不见收，今年寄食仍淹留。
羡君有酒能共醉，羡君无钱能不忧。
如今五侯不待客，羡君不问五侯宅。
如今七贵方自尊，羡君不过七贵门。
丈夫会应有知己，世上悠悠何足论。','',''),('quantangshi-13465','茙葵花歌','劉眘虛','quantangshi','','卷14','昨日一花开，今日一花开。
今日花正好，昨日花已老。
人生不得长少年，莫惜牀头酤酒钱。
请君有钱向酒家，君不见茙葵花。','',''),('quantangshi-13466','句','劉眘虛','quantangshi','','卷14','归梦如春水，悠悠遶故乡。
驻马渡江处，望乡待归舟。','',''),('quantangshi-13467','冬夜宴萧十丈因饯殷郭二子西上','息夫牧','quantangshi','','卷14','有琴斯鸣，于宰之庭。
君子莅止，其心孔平。
政既告成，德以永贞。
鸣琴有衎，于颍之畔。
彼之才髦，其年未冠。
闻诗闻礼，斐兮璨璨。
鸣琴其怡，于颍之湄。
二子翰飞，言戾京师。
有郁者桂，爰攀其枝。
琴既鸣矣，宵既清矣。
烘煁有炜，酒醴惟旨。
喟我寤叹，吁其别矣。','',''),('quantangshi-13468','蝉鸣一篇五章 一','華','quantangshi','','卷14','蝉其鸣矣，于彼疎桐。
庇影容迹，何所不容。
嘒嘒其长，永托于风。
未见君子，我心仲仲。
既见君子，乐且有融。','',''),('quantangshi-13469','蝉鸣一篇五章 二','華','quantangshi','','卷14','彼蝉鸣矣，于林之表。
含风饮露，以乐吾道。
有怀载迁，伊谁云保。
未见君子，我心悄悄。
既见君子，披豁予抱。','',''),('quantangshi-13470','蝉鸣一篇五章 三','華','quantangshi','','卷14','蝉鸣蝉鸣，幽畅乎而。
肃肃尔庭，远近凉飔。
言赴高柳，丛篁间之。
思而不见，如渴如饥。
亦既觏止，我心则夷。','',''),('quantangshi-13471','蝉鸣一篇五章 四','華','quantangshi','','卷14','蝉鸣伊何，时运未与。
匪叹秋徂，怨斯路阻。
愿言莫从，郁悒谁语。
君子至止，慰我延伫。
何斯违斯，倏尔遐举。','',''),('quantangshi-13472','蝉鸣一篇五章 五','華','quantangshi','','卷14','岁之秋深，蝉其夕吟。
披衣轩除，萧萧风林。
我友来斯，言告离衿。
何以叙怀，临水鸣琴。
何以赠言，委顺浮沈。','',''),('quantangshi-13473','寄萧頴士补正字','鄒象先','quantangshi','','卷14','六月度开云，三峯翫山翠。
尔时黄绶屈，别后青云致。','',''),('quantangshi-13474','河中晚霁','韋建','quantangshi','','卷14','湖广舟自轻，江天欲澄霁。
是时清楚望，气色犹霾曀。
踯蹰金霞白，波上日初丽。
烟红落镜中，树木生天际。
杳杳涯欲斑，蒙蒙云复闭。
言垂星汉明，又覩寰瀛势。
微兴从此惬，悠然不知岁。
试歌沧浪清，遂觉干坤细。
肯念客衣薄，将期永投袂。
迟回渔父间，一雁声嘹唳。','',''),('quantangshi-13475','泊舟盱眙','韋建','quantangshi','','卷14','泊舟淮水次，霜降夕流清。
夜久潮浸岸，天寒月近城。
平沙依雁宿，候馆听鸡鸣。
乡国云霄外，谁堪羁旅情。','',''),('quantangshi-13476','铨试后徴山别业寄源侍御','殷寅','quantangshi','','卷14','别业在徴山，登高望畿甸。
严令天地肃，城阙如何见。
蔼蔼王侯门，华轩日游炫。
幸逢休明代，山虏尚交战。
投策去园林，率名皆拜选。
圣君性则哲，济济多英彦。
裴楷能清通，山涛急推荐。
謏才甘自屏，薄伎忝余眷。
虽承国士恩，尚乏中人援。
畴昔相知者，今兹秉天宪。
朱绂何赫赫，绣衣复葱蒨。','',''),('quantangshi-13477','玄元皇帝应角贺圣祚无疆','殷寅','quantangshi','','卷14','应历生周日，修祠表汉年。
复兹秦岭上，更似霍山前。
昔赞神功启，今符圣祚延。
已题金简字，仍访玉堂仙。
睿祖光元始，曾孙体又玄。
言因六梦接，庆叶九龄传。
北阙心超矣，南山寿固然。
无由同拜庆，窃拚贺陶甄。','',''),('quantangshi-13478','秋怨','柳中庸','quantangshi','','卷14','玉树起凉烟，凝情一叶前。
别离伤晓镜，摇落思秋弦。
汉垒关山月，胡笳塞北天。
不知肠断梦，空遶几山川。','',''),('quantangshi-13479','春思赠人','柳中庸','quantangshi','','卷14','红粉当三五，青娥艳一双。
绮罗回锦陌，弦管入花江。
落雁惊金弹，抛杯泻玉缸。
谁知褐衣客，顦顇在书窗。','',''),('quantangshi-13480','幽院早春','柳中庸','quantangshi','','卷14','草短花初拆，苔青柳半黄。
隔帘春雨细，高枕晓莺长。
无事含闲梦，多情识异香。','',''),('quantangshi-13481','寒食戏赠','柳中庸','quantangshi','','卷14','春暮越江边，春阴寒食天。
杏花香麦粥，柳絮伴秋千。
酒是芳菲节，人当桃李年。
不知何处恨，已解入筝弦。','',''),('quantangshi-13482','听筝','柳中庸','quantangshi','','卷14','抽弦促柱听秦筝，无限秦人悲怨声。
似逐春风知柳态，如随啼鸟识花情。
谁家独夜愁灯影，何处空楼思月明。
更入几重离别恨，江南歧路洛阳城。','',''),('quantangshi-13483','河阳桥送别','柳中庸','quantangshi','','卷14','黄河流出有浮桥，晋国归人此路遥。
若傍阑干千里望，北风驱马雨萧萧。','',''),('quantangshi-13484','征怨','柳中庸','quantangshi','','卷14','岁岁金河复玉关，朝朝马策与刀环。
三春白雪归青冢，万里黄河遶黑山。','',''),('quantangshi-13485','凉州曲二首 一','柳中庸','quantangshi','','卷14','关山万里远征人，一望关山泪满巾。
青海戍头空有月，黄沙碛里本无春。','',''),('quantangshi-13486','凉州曲二首 二','柳中庸','quantangshi','','卷14','高槛连天望武威，穷阴拂地戍金微。
九城弦管声遥发，一夜关山雪满飞。','',''),('quantangshi-13487','江行','柳中庸','quantangshi','','卷14','繁阴乍隐洲，落叶初飞浦。
萧萧楚客帆，暮入寒江雨。','',''),('quantangshi-13488','丁评事宅秋夜宴集','柳中庸','quantangshi','','卷14','翠幕卷回廊，银灯开后堂。
风惊拥砌叶，月冷满庭霜。
绮席人将醉，繁弦夜未央。
共怜今促席，谁道客愁长。','',''),('quantangshi-13489','夜渡江','柳中庸','quantangshi','','卷14','夜渚带浮烟，苍茫晦远天。
舟轻不觉动，缆急始知牵。
听笛遥寻岸，闻香暗识莲。
唯看去帆影，常恐客心悬。','',''),('quantangshi-13490','扬子途中','柳中庸','quantangshi','','卷14','楚塞望苍然，寒林古戍边。
秋风人渡水，落日雁飞天。','',''),('quantangshi-13491','宴城东庄','崔惠童','quantangshi','','卷14','一月主人笑几回，相逢相识且衔杯。
眼看春色如流水，今日残花昨日开。','',''),('quantangshi-13492','宴城东庄','崔敏童','quantangshi','','卷14','一年始有一年春，百岁曾无百岁人。
能向花前几回醉，十千沽酒莫辞贫。','',''),('quantangshi-13493','奉和圣制早登太行山中言志','苗晉卿','quantangshi','','卷14','金吾戒道清，羽骑动天声。
砥路方南绝，重岩始北征。
关楼前望远，河邑下观平。
喜气回舆合，祥风入斾轻。
祝尧三老至，会禹百神迎。
月令农先急，春搜礼复行。
仍亲后土祭，更理晋阳兵。
不似劳车辙，空留八骏名。','',''),('quantangshi-13494','赋虞书歌','賈躭','quantangshi','','卷14','众书之中虞书巧，体法自然归大道。
不同怀素只攻颠，岂类张芝惟创草。
形势素，筋骨老，父子君臣相揖抱。
孤青似竹更飕飔，阔白如波长浩渺。
能方正，不隳倒，功夫未至难寻奥。
须知孔子庙堂碑，便是青箱中至宝。','',''),('quantangshi-13495','云门山投龙诗','趙居貞','quantangshi','','卷14','晓登云门山，直上一千尺。
绝顶弥孤耸，盘途几倾窄。
前对竖裂峯，下临削成壁。
阳巘灵芝秀，阴崖半天赤。
大壑静不波，渺溟无际极。
是时雪初霁，冱寒水更积。
披展送龙仪，宁安服狐白。
沛恩惟圣主，祈福在方伯。
三元章醮升，五域囗囗觌。
帟幕翠微亘，机茵丹洞辟。
祝起鸣天鼓，拜传端素册。
霞间朱绂萦，岚际黄裳襞。
玉策奉诚信，仙佩俟奔驿。
香气入岫门，瑞云出岩石。
至诚必招感，大福旋来格。
空中忽神言，帝寿万千百。','',''),('quantangshi-13496','扈从回銮应制','蕭華','quantangshi','','卷14','粤在秦京日，议乎封禅难。
岂知陶唐主，道济苍生安。
惟彼烈祖事，增修实荣观。
声名朝万国，玉帛礼三坛。
纂圣德重光，建元功载刊。
仍开旧驰道，不记昔回銮。
羽卫摇晴日，弓戈生早寒。
犹思检玉处，却望白云端。','',''),('quantangshi-13497','西河郡太原守张夫人挽歌','李岑','quantangshi','','卷14','鹊印庆仍传，鱼轩宠莫先。
从夫元凯贵，训子孟轲贤。
龙是双归日，鸾非独舞年。
哀荣今共尽，凄怆杜陵田。','',''),('quantangshi-13498','玄元皇帝应见贺圣祚无疆','李岑','quantangshi','','卷14','皇纲归有道，帝系祖玄元。
运表南山祚，神通北极尊。
大同齐日月，兴废应干坤。
圣后趋庭礼，宗臣稽首言。
千官欣肆观，万国贺深恩。
锡宴云天接，飞声雷地喧。
祥光浮紫阁，喜气绕皇轩。
未预承天命，空勤望帝门。','',''),('quantangshi-13499','复游浯溪','友讓','quantangshi','','卷14','昔到才三岁，今来鬓已苍。
剥苔看篆字，剃草觅书堂。
引客登台上，呼童扫树旁。
石渠疏拥水，门径斸藂篁。
田地潜更主，林园尽废荒。
悲凉问耆耋，疆界指垂杨。','',''),('quantangshi-13500','南溪别业','蔣冽','quantangshi','','卷14','结宇依青嶂，开轩对绿畴。
树交花两色，溪合水同流。
竹径春来扫，兰尊夜不收。
逍遥自得意，鼓腹醉中游。','',''),('quantangshi-13501','古意','蔣冽','quantangshi','','卷14','冉冉红罗帐，开君玉楼上。
画作同心鸟，衔花两相向。
春风正可怜，吹暎绿窗前。
妾意空相感，君心何处边。','',''),('quantangshi-13502','台中书怀','蔣冽','quantangshi','','卷14','持宪当休明，饬躬免颠沛。
直绳备豪右，正色清冠盖。
寄切才恨薄，职雄班匪大。
坐居三独中，立在百僚外。
简牍时休暇，依然秋兴多。
披书唯骨鲠，循迹少闲和。
庭树凌霜柏，池倾萎露荷。
岁寒应可见，感此遂成歌。','',''),('quantangshi-13503','经埋轮地','蔣冽','quantangshi','','卷14','汉家张御史，晋国绿珠楼。
时代邈已远，共谢洛阳秋。
洛阳大道边，旧地尚依然。
下马独太息，扰扰城市喧。
时人欣绿珠，诗满金谷圆。
千载埋轮地，无人兴一言。
正直死犹忌，况乃未死前。
汨罗有飜浪，恐是嫌屈原。
我闻太古水，上与天相连。
如何一落地，又作九曲泉。
万古惟高步，可以旌我贤。','',''),('quantangshi-13504','山行见鹊巢','蔣冽','quantangshi','','卷14','鹊巢性本高，更在西山木。
朝下清泉戏，夜近明月宿。
非直避网罗，兼能免倾覆。
岂忧五陵子，挟弹来相逐。','',''),('quantangshi-13505','巫山之阳香溪之阴明妃神女旧迹存焉','蔣冽','quantangshi','','卷14','神女归巫峡，明妃入汉宫。
捣衣余石在，荐枕旧室空。
行雨有时度，溪流何日穷。
至今词赋里，凄怆写遗风。','',''),('quantangshi-13506','夜飞鹊','蔣冽','quantangshi','','卷14','北林夜方久，南月影频移。
何啻飞三匝，犹言未得枝。','',''),('quantangshi-13507','途次维扬望京口寄白下诸公','蔣渙','quantangshi','','卷14','北望情何限，南行路转深。
晚帆低荻叶，寒日下枫林。
云白兰陵渚，烟青建业岑。
江天秋向尽，无处不伤心。','',''),('quantangshi-13508','登栖霞寺塔','蔣渙','quantangshi','','卷14','三休寻磴道，九折步云霓。
瀍涧临江北，郊原极海西。
沙平瓜步出，树远绿杨低。
南指晴天外，青峯是会稽。','',''),('quantangshi-13509','和徐侍郎书丛筱韵','蔣渙','quantangshi','','卷14','中禁夕沈沈，幽篁别作林。
色连鸡树近，影落凤池深。
为重凌霜节，能虚应物心。
年年承雨露，长对紫庭阴。','',''),('quantangshi-13510','故太常卿赠礼部尚书李公及夫人挽歌二首 一','蔣渙','quantangshi','','卷14','白简尝持宪，黄图复尹京。
能标百郡则，威肃一朝清。
典秩崇三礼，临戍振五兵。
更闻传世业，才子有高名。','',''),('quantangshi-13511','故太常卿赠礼部尚书李公及夫人挽歌二首 二','蔣渙','quantangshi','','卷14','封树遵同穴，生平此共归。
镜埋鸾已去，泉掩凤何飞。
薤挽疑笳曲，松风思翟衣。
扬名将宠赠，泉路满光辉。','',''),('quantangshi-13512','挽涌泉寺僧怀玉','段懷然','quantangshi','','卷14','我师一念登初地，佛国笙歌两度来。
唯有门前古槐树，枝低只为挂银台。','',''),('quantangshi-13513','辞房相公','張偁','quantangshi','','卷14','秋风飒飒雨霏霏，愁杀恓遑一布衣。
辞君且作随阳鸟，海内无家何处归。','',''),('quantangshi-13514','移耶溪旧居呈陈元初校书','陳孫','quantangshi','','卷14','鸡犬渔舟里，长谣任兴行。
即令邀客醉，已被远山迎。
书笈将非重，荷衣着甚轻。
谢安无个事，忽起为苍生。','',''),('quantangshi-13515','西河郡太原守张夫人挽歌','李峯','quantangshi','','卷14','鹊印庆仍传，鱼轩宠莫先。
从夫元凯贵，训子孟轲贤。
龙是双归日，鸾非独舞年。
哀荣今共尽，凄怆杜陵田。','',''),('quantangshi-13516','感怀弟妹','沈千運','quantangshi','','卷14','今日春气暖，东风杏花拆。
筋力久不如，却羡涧中石。
神仙杳难准，中寿稀满百。
近世多夭伤，喜见鬓发白。
杖藜竹树间，宛宛旧行迹。
岂知林园主，却是林园客。
兄弟可存半，空为亡者惜。
冥冥无再期，哀哀望松柏。
骨肉能几人，年大自疎隔。
性情谁免此，与我不相易。
唯念得尔辈，时看慰朝夕。
平生兹已矣，此外尽非适。','',''),('quantangshi-13517','赠史修文','沈千運','quantangshi','','卷14','故人阻千里，会面非别期。
握手于此地，当欢反成悲。
念离宛犹昨，俄已经数期。
畴昔皆少年，别来鬓如丝。
不道旧姓名，相逢知是谁。
曩游尽骞翥，与君仍布衣。
岂曰无其才，命理应有时。
别路渐欲少，不觉生涕涕。','',''),('quantangshi-13518','濮中言怀','沈千運','quantangshi','','卷14','圣朝优贤良，草泽无遗匿。
人生各有命，在余胡不淑。
一生但区区，五十无寸禄。
衰退当弃捐，贫贱招毁讟。
栖栖去人世，屯踬日穷迫。
不如守田园，岁晏望丰熟。
壮年失宜尽，老大无筋力。
始觉前计非，将贻后生福。
童儿新学稼，少女未能织。
顾此烦知己，终日求衣食。','',''),('quantangshi-13519','山中作','沈千運','quantangshi','','卷14','栖隐非别事，所愿离风尘。
不辞城邑游，礼乐拘束人。
迩来归山林，庶事皆吾身。
何者为形骸，谁是智与仁。
寂寞了闲事，而后知天真。
咳唾矜崇华，迂俯相屈伸。
如何巢与由，天子不知臣。','',''),('quantangshi-13520','古歌','沈千運','quantangshi','','卷14','北邙不种田，但种松与柏。
松柏未生处，留待市朝客。','',''),('quantangshi-13521','别李季友','王季友','quantangshi','','卷14','栖鸟不恋枝，喈喈在同声。
行子驰出户，依依主人情。
昔时霜台镜，丑妇羞尔形。
闭匣二十年，皎洁常独明。
今日照离别，前途白发生。','',''),('quantangshi-13522','寄韦子春','王季友','quantangshi','','卷14','出山秋云曙，山木已再春。
食我山中药，不忆山中人。
山中谁余密，白发日相亲。
雀鼠画夜无，知我厨廪贫。
依依北舍松，不厌吾南隣。
有情尽弃捐，土石为同身。
夫子质千寻，天泽枝叶新。
余以不材寿，非智免斧斤。','',''),('quantangshi-13523','杂诗','王季友','quantangshi','','卷14','采山仍采隐，在山不在深。
持斧事远游，固非匠者心。
翳翳青桐枝，樵爨日所侵。
斧声出岩壑，四听无知音。
岂为鼎下薪，当复堂上琴。
凤鸟久不栖，且与枳棘林。','',''),('quantangshi-13524','滑中赠崔高士瑾','王季友','quantangshi','','卷14','夫子保药命，外身得无咎。
日月不能老，化肠为筯否。
十年前见君，甲子过我寿。
于何今相逢，华发在我后。
近而知其远，少见今白首。
遥信蓬莱宫，不死世世有。
玄石采盈担，神方秘其肘。
问家惟指云，爱气常言酒。
摄生固如此，履道当不朽。
未能太玄同，愿亦天地久。
实腹以芝术，贱形乃刍狗。
自勉将勉余，良药在苦口。','',''),('quantangshi-13525','还山留别长安知己','王季友','quantangshi','','卷14','出山不见家，还山见家在。
山门是门前，此去长樵采。
青溪谁招隐，白发自相待。
惟余涧底松，依依色不改。','',''),('quantangshi-13526','代贺若令誉赠沈千运','王季友','quantangshi','','卷14','相逢问姓名亦存，别时无子今有孙。
山上双松长不改，百家唯有三家村。
村南村西车马道，一宿通舟水浩浩。
涧中磊磊十里石，河上淤泥种桑麦。
平坡冢墓皆我亲，满田主人是旧客。
举声酸鼻问同年，十人六七归下泉。
分手如何更此地，回头不语泪潸然。','',''),('quantangshi-13527','酬李十六岐','王季友','quantangshi','','卷14','炼丹文武火未成，卖药贩履俱逃名。
出谷迷行洛阳道，乘流醉卧滑台城。
城下故人久离怨，一欢适我两家愿。
朝饮杖悬沽酒钱，暮餐囊有松花饭。
于何车马日憧憧，李膺门馆争登龙。
千宾揖对若流水，五经发难如叩钟。
下笔新诗行满壁，立谈古人坐在席。
问我草堂有卧云，知我山储无儋石。
自耕自刈食为天，如鹿如麋饮野泉。
亦知世上公卿贵，且养丘中草木年。','',''),('quantangshi-13528','宿东溪李十五山亭','王季友','quantangshi','','卷14','上山下山入山谷，溪中落日留我宿。
松石依依当主人，主人不在意亦足。
名花出地两重阶，绝顶平天一小斋。
本意由来是山水，何用相逢语旧怀。','',''),('quantangshi-13529','观于舍人壁画山水','王季友','quantangshi','','卷14','野人宿在人家少，朝见此山谓山晓。
半壁仍栖岭上云，开帘欲放湖中鸟。
独坐长松是阿谁，再三招手起来迟。
于公大笑向予说，小弟丹青能尔为。','',''),('quantangshi-13530','玉壶冰','王季友','quantangshi','','卷14','玉壶知素结，止水复中澄。
坚白能虚受，清寒得自凝。
分形同晓镜，照物掩宵灯。
壁映圆光入，人惊爽气凌。
金罍何足贵，瑶席几回升。
正值求圭瓒，提携共饮冰。','',''),('quantangshi-13531','古塞曲','王季友','quantangshi','','卷14','进军飞狐北，穷寇势将变。
日落沙尘昏，背河更一战。
騂马黄金勒，雕弓白羽箭。
射杀左贤王，归奏未央殿。
欲言塞下事，天子不召见。
东出咸阳门，哀哀泪如霰。','',''),('quantangshi-13532','野外行','于逖','quantangshi','','卷14','老病无乐事，岁秋悲更长。
穷郊日萧索，生意已苍黄。
小弟发亦白，两男俱不强。
有才且未达，况我非贤良。
幸以朽钝姿，野外老风霜。
寒鸦噪晚景，乔木思故乡。
魏人宅蓬池，结网伫鳣鲂。
水清鱼不来，岁暮空旁徨。','',''),('quantangshi-13533','忆舍弟','于逖','quantangshi','','卷14','衰门少兄弟，兄弟唯两人。
饥寒各流浪，感念伤我神。
夏期秋未来，安知无他因。
不怨别天长，但愿见尔身。
茫茫天地间，万类各有亲。
安知汝与我，乖隔同胡秦。
何时对形影，愤懑当共陈。','',''),('quantangshi-13534','杂诗','張彪','quantangshi','','卷14','富贵多胜事，贪贱无良图。
上德兼济心，中才不如愚。
商者多巧智，农者争膏腴。
儒生未遇时，衣食不自如。
久与故交别，他荣我穷居。
到门懒入门，何况千里余。
君子有褊性，矧乃寻常徒。
行行任天地，无为强亲疎。','',''),('quantangshi-13535','神仙','張彪','quantangshi','','卷14','神仙可学无，百岁名大约。
天地何苍茫，人间半哀乐。
浮生亮多惑，善事翻为恶。
争先等驰驱，中路苦瘦弱。
长老思养寿，后生笑寂寞。
五谷非长年，四气乃灵药。
列子何必待，吾心满寥廓。','',''),('quantangshi-13536','北游还酬孟云卿','張彪','quantangshi','','卷14','忽忽忘前事，志愿能相乖。
衣马久羸弊，谁信文与才。
善道居贫贱，洁服蒙尘埃。
行行无定心，壈坎难归来。
慈母忧疾疹，至家念栖哀。
与君宿姻亲，深见中外怀。
俟余惜时节，伥望临高台。','',''),('quantangshi-13537','古别离','張彪','quantangshi','','卷14','别离无远近，事欢情亦悲。
不闻车轮声，后会将何时。
去日忘寄书，来日乖前期。
纵知明当返，一息千万思。','',''),('quantangshi-13538','回军跛者','趙徵明','quantangshi','','卷14','既老又不全，始得离边城。
一枝假枯木，步步向南行。
去时日一百，来时月一程。
常恐道路旁，掩弃狐兔茔。
所愿死乡里，到日不愿生。
闻此哀怨词，念念不忍听。
惜无异人术，倏忽具尔形。','',''),('quantangshi-13539','挽歌词','趙徵明','quantangshi','','卷14','寒日蒿上明，凄凄郭东路。
素车谁家子，丹旐引将去。
原下荆棘丛，丛边有新墓。
人间痛伤别，此是长别处。
旷野多萧条，青松白杨树。','',''),('quantangshi-13540','思归','趙徵明','quantangshi','','卷14','为别未几日，去日如三秋。
犹疑望可见，日日上高楼。
惟见分手处，白苹满芳洲。
寸心宁死别，不忍生离忧。','',''),('quantangshi-13541','泉上雨后作','季川','quantangshi','','卷14','风雨荡繁暑，雷息佳霁初。
众峰带云雨，清气入我庐。
飒飒凉飙来，临窥惬所图。
绿萝长新蔓，褭褭垂坐隅。
流水复檐下，丹砂发清渠。
养葛为我衣，种芋为我蔬。
谁是畹与畦，弥漫连野芜。','',''),('quantangshi-13542','登云中','季川','quantangshi','','卷14','灌田东山下，取乐在尔休。
清兴相引行，日日三四周。
白鸥与我心，不厌此中游。
穷览颇有适，不极趣无幽。
憀然歌采薇，曲尽心悠悠。','',''),('quantangshi-13543','山中晓兴','季川','quantangshi','','卷14','河汉降玄霜，昨来节物殊。
愧无神仙姿，岂有阴阳俱。
灵鸟望不见，慨然悲高梧。
华叶随风扬，珍条杂榛芜。
为君寒谷吟，叹息知何如。','',''),('quantangshi-13544','古远行','季川','quantangshi','','卷14','悠悠远行者，羁独当时思。
道与日月长，人无茅舍期。
出门万里心，谁不伤别离。
纵远当白发，岁月悲今时。
何况异形容，安须与尔悲。','',''),('quantangshi-13545','晚秋拾遗朱放访山居','秦系','quantangshi','','卷14','不逐时人后，终年独闭关。
家中贫自乐，石上卧常闲。
坠栗添新味，寒花带老颜。
侍臣当献纳，那得到空山。','',''),('quantangshi-13546','题女道士居','秦系','quantangshi','','卷14','不饵住云溪，休丹罢药畦。
杏花虚结子，石髓任成泥。
扫地青牛卧，栽松白鹤栖。
共知仙女丽，莫是阮郎妻。','',''),('quantangshi-13547','山中枉张宙员外书期访衡门','秦系','quantangshi','','卷14','常恨相知晚，朝来枉数行。
卧云惊圣代，拂石候仙郎。
时果连枝熟，春醪满瓮香。
贫家仍有趣，山色满湖光。','',''),('quantangshi-13548','山中赠张正则评事','秦系','quantangshi','','卷14','终年常避喧，师事五千言。
流水闲过院，春风与闭门。
山茶邀上客，桂实落前轩。
莫强敎余起，微官不足论。','',''),('quantangshi-13549','题镜湖野老所居','秦系','quantangshi','','卷14','湖里寻君去，樵风往返吹。
树喧巢鸟出，路细葑田移。
沤苎成鱼网，枯根是酒巵。
老年唯自适，生事任羣儿。','',''),('quantangshi-13550','早秋宿崔业居处','秦系','quantangshi','','卷14','从来席不暖，为尔便淹流。
鸡黍今相会，云山昔共游。
上帘宜晚景，卧簟觉新秋。
身事何须问，余心正四愁。','',''),('quantangshi-13551','赠乌程杨苹明府','秦系','quantangshi','','卷14','策杖政成时，清溪弄钓丝。
当年潘子貌，避病沈侯诗。
漉酒迎宾急，看花署字迟。
杨梅今熟未，与我两三枝。','',''),('quantangshi-13552','徐侍郎素未相识时携酒命馔兼命诸诗客同访会稽山居','秦系','quantangshi','','卷14','忽道仙翁至，幽人学拜迎。
华簪窥瓮牖，珍味代藜羹。
洗砚鱼仍戏，移樽鸟不惊。
兰亭攀叙却，会此越中营。','',''),('quantangshi-13553','春日闲居三首 一','秦系','quantangshi','','卷14','一似桃源隐，将令过客迷。
碍冠门柳长，惊梦院莺啼。
浇药泉流细，围碁日影低。
举家无外事，共爱草萋萋。','',''),('quantangshi-13554','春日闲居三首 二','秦系','quantangshi','','卷14','长谣朝复暝，幽独几人知。
老鹤兼雏弄，丛篁带笋移。
白云将袖拂，青镜出檐窥。
邀取渔家叟，花间把酒巵。','',''),('quantangshi-13555','春日闲居三首 三','秦系','quantangshi','','卷14','寂寂池亭里，轩窗间绿苔。
游鱼牵荇没，戏鸟踏花摧。
小径僧寻去，高峯鹿下来。
中年曾屡辟，多病复迟回。','',''),('quantangshi-13556','题石室山王宁所居','秦系','quantangshi','','卷14','白云知所好，柏叶幸加餐。
石镜妻将照，仙书我借看。
鸟来翻药椀，猿饮怕鱼竿。
借问檐前树，何枝曾挂冠。','',''),('quantangshi-13557','送王道士','秦系','quantangshi','','卷14','真人俄整舃，双鹤屡飞翔。
恐入壶中住，须传肘后方。
霓裳云气润，石径术苗香。
一去何时见，仙家日月长。','',''),('quantangshi-13558','将移耶溪旧居留赠严维秘书','秦系','quantangshi','','卷14','鸡犬渔舟里，长谣任兴行。
那邀落日醉，已被远山迎。
书箧将非重，荷衣着甚轻。
谢安无个事，忽起为苍生。','',''),('quantangshi-13559','秋日过僧惟则故院','秦系','quantangshi','','卷14','衰草经行处，微灯旧道场。
门人失谭柄，野鸟上禅牀。
科斗书空古，栴檀钵自香。
今朝数行泪，却洒约公房。','',''),('quantangshi-13560','山中奉寄钱起员外兼简苗发员外','秦系','quantangshi','','卷14','空山岁计是胡麻，穷海无梁泛一槎。
稚子唯能觅梨栗，逸妻相共老烟霞。
高吟丽句惊巢鹤，闲闭春风看落花。
借问省中何水部，今人几个属诗家。','',''),('quantangshi-13561','献薛仆射','秦系','quantangshi','','卷14','由来那敢议轻肥，散发行歌自采薇。
逋客未能忘野兴，辟书翻遣脱荷衣。
家中匹妇空相笑，池上羣鸥尽欲飞。
更乞大贤容小隐，益看愚谷有光辉。','',''),('quantangshi-13562','鲍防员外见寻因书情呈赠','秦系','quantangshi','','卷14','少小为儒不自强，如今嬾复见侯王。
览镜已知身渐老，买山将作计偏长。
荒凉鸟兽同三迳，撩乱琴书共一牀。
犹有郎官来问疾，时人莫道我佯狂。','',''),('quantangshi-13563','寄浙东皇甫中丞','秦系','quantangshi','','卷14','闲闲麋鹿或相随，一两年来鬓欲衰。
琴砚共依春酒瓮，云霞覆着破柴篱。
注书不向时流说，种药空令道者知。
久带纱巾仍藉草，山中那得见朝仪。','',''),('quantangshi-13564','题章野人山居','秦系','quantangshi','','卷14','带郭茅亭诗兴饶，回看一曲倚危桥。
门前山色能深浅，壁上湖光自动摇。
闲花散落填书帙，戏鸟低飞碍柳条。
向此隐来经几载，如今已是汉家朝。','',''),('quantangshi-13565','山中枉皇甫温大夫见招书','秦系','quantangshi','','卷14','十年木屐步苔痕，石上松间水自喧。
三辟草堂仍被褐，数行书札忽临门。
卧多共息嵇康病，才劣虚同郭隗尊。
亚相已能怜潦倒，山花笑处莫啼猿。','',''),('quantangshi-13566','题茅山李尊师山居','秦系','quantangshi','','卷14','天师百岁少如童，不到山中竟不逢。
洗药每临新瀑水，步虚时上最高峰。
篱间五月留残雪，座右千年廕老松。
此去人寰今远近，回看云壑一重重。','',''),('quantangshi-13567','耶溪书怀寄刘长卿员外','秦系','quantangshi','','卷14','时人多笑乐幽栖，晚起闲行独杖藜。
云色卷舒前后岭，药苗新旧两三畦。
偶逢野果将呼子，屡折荆钗亦为妻。
拟共钓竿长往复，岩陵滩上胜耶溪。','',''),('quantangshi-13568','山中崔大夫有书相问','秦系','quantangshi','','卷14','客在烟霞里，闲闲逐狎鸥。
终年常裸足，连日半蓬头。
带月乘渔艇，迎寒绽鹿裘。
已于人事少，多被挂冠留。
素业堆千卷，清风至一丘。
苍黄倒藜杖，伛偻覩银钩。
迹愧巢由隐，才非管乐俦。
从来自多病，不是傲王侯。','',''),('quantangshi-13569','张建封大夫奏系为校书郎因寄此作','秦系','quantangshi','','卷14','久是烟霞客，潭深钓得鱼。
不知芸阁上，遗校几多书。','',''),('quantangshi-13570','会稽山居寄薛播侍郎袁高给事高参舍人','秦系','quantangshi','','卷14','稷卨今为相，明君复是尧。
宁知买臣困，犹负会稽樵。','',''),('quantangshi-13571','闲居览史','秦系','quantangshi','','卷14','长策胸中不复论，荷衣蓝缕闭柴门。
当时汉祖无三杰，争得咸阳与子孙。','',''),('quantangshi-13572','山中赠耿拾遗湋兼两省故人','秦系','quantangshi','','卷14','数片荷衣不蔽身，青山白鸟岂知贫。
如今非是秦时世，更隐桃花亦笑人。','',''),('quantangshi-13573','秋日送僧志幽归山寺','秦系','quantangshi','','卷14','禅室绳牀在翠微，松间荷笠一僧归。
磬声寂历宜秋夜，手冷灯前自衲衣。','',''),('quantangshi-13574','题僧明惠房','秦系','quantangshi','','卷14','檐前朝暮雨添花，八十真僧饭一麻。
入定几时将出定，不知巢燕污袈裟。','',''),('quantangshi-13575','答泉州薛播使君重阳日赠酒','秦系','quantangshi','','卷14','欲强登高无力也，篱边黄菊为谁开。
共知不是浔阳郡，那得王弘送酒来。','',''),('quantangshi-13576','题洪道士山院','秦系','quantangshi','','卷14','霞外主人门不扃，数株桃树药囊青。
闲行池畔随孤鹤，若问多应道姓丁。','',''),('quantangshi-13577','期王炼师不至','秦系','quantangshi','','卷14','黄精蒸罢洗琼杯，林下从留石上苔。
昨日围棋未终局，多乘白鹤下山来。','',''),('quantangshi-13578','题赠张道士山居','秦系','quantangshi','','卷14','盘石垂萝即是家，回头犹看五枝花。
松间寂寂无烟火，应服朝来一片霞。','',''),('quantangshi-13579','山中书怀寄张建封大夫','秦系','quantangshi','','卷14','昨日年催白发新，身如麋鹿不知贫。
时时亦被羣儿笑，赖有南山四老人。','',''),('quantangshi-13580','山中赠诸暨丹丘明府','秦系','quantangshi','','卷14','荷衣半破带莓苔，笑向陶潜酒瓮开。
纵醉远须上山去，白云那肯下山来。','',''),('quantangshi-13581','奉寄昼公','秦系','quantangshi','','卷14','蓑笠双童傍酒船，湖山相引到房前。
团蕉何事敎人见，暂借空牀守坐禅。','',''),('quantangshi-13582','宿云门上方','秦系','quantangshi','','卷14','禅室遥看峰顶头，白云东去水长流。
松间傥许幽人住，不更将钱买沃州。','',''),('quantangshi-13583','即事奉呈郎中韦使君','秦系','quantangshi','','卷14','久卧云间已息机，青袍忽着狎鸥飞。
诗兴到来无一事，郡中今有谢玄晖。','',''),('quantangshi-13584','晓鸡','秦系','quantangshi','','卷14','黯黯严城罢鼓鼙，数声相续出寒栖。
不嫌惊破纱窗梦，却恐为妖半夜啼。','',''),('quantangshi-13585','寄李白','任華','quantangshi','','卷14','古来文章有能奔逸气，耸高格。
清人心神，惊人魂魄。
我闻当今有李白，大猎赋，鸿猷文，嗤长卿，笑子云。
班张所作琐细不入耳，未知卿云得在嗤笑限。
登庐山，观瀑布，海风吹不断，江月照还空。
余爱此两句：登天台，望渤海云垂大鹏飞，山压巨鳌背，斯言亦好在。
至于他作多不拘常律，振摆超腾，既俊且逸。
或醉中操纸，或兴来走笔。
手下忽然片云飞，眼前划见孤峰出。
而我有时白日忽欲睡，睡觉歘然起攘臂。
任生知有君，君也知有任生未。
中间闻道在长安，及余戾止。
君已江东访元丹，邂逅不得见君面。
每常把酒，向东望良久。
见说往年在翰林，胸中矛戟何森森。
新诗传在宫人口，佳句不离明主心。
身骑天马多意气，目送飞鸿对豪贵。
承恩召入凡几回，待诏归来仍半醉。
权臣妬盛名，羣犬多吠声。
有勅放君却归隐沦处，高歌大笑出关去。
且向东山为外臣，诸侯交迓驰朱轮。
白璧一双买交者，黄金百镒相知人。
平生傲岸其志不可测，数十年为客，未尝一日低颜色。
八咏楼中坦腹眠，五侯门下无心忆。
繁花越台上，细柳吴宫侧。
绿水青山知有君，白云明月偏相识。
养高兼养闲，可望不可攀。
庄周万物外，范蠡五湖间。
人传访道沧海上，丁令王乔每往还。
蓬莱径是曾到来，方丈岂唯方一丈。
伊余每欲乘兴往相寻，江湖拥隔劳寸心。
今朝忽遇东飞翼，寄此一章表胸臆。
傥能报我一片言，但访任华有人识。','',''),('quantangshi-13586','寄杜拾遗','任華','quantangshi','','卷14','杜拾遗，名甫第二才甚奇。
任生与君别，别来已多时，何尝一日不相思。
杜拾遗，知不知，昨日有人诵得数篇黄绢词。
吾怪异奇特借问，果然称是杜二之所为。
势攫虎豹，气腾蛟螭。
沧海无风似鼓荡，华岳平地欲奔驰。
曹刘俯仰惭大敌，沈谢逡巡称小儿。
昔在帝城中，盛名君一个。
诸人见所作，无不心胆破。
郎官丛里作狂歌，丞相阁中常醉卧。
前年皇帝归长安，承恩阔步青云端。
积翠扈游花匼匝，披香寓直月团栾。
英才特达承天睠，公卿无不相钦慕。
只缘汲黯好直言，遂使安仁却为掾。
如今避地锦城隅，幕下英僚每日相随提玉壶。
半醉起舞捋髭须，乍低乍昂傍若无。
古人制礼但为防俗士，岂得为君设之乎。
而我不飞不鸣亦可以，只待朝廷有知己。
已曾读却无限书，拙诗一句两句在人耳。
如今看之总无益，又不能崎岖傍朝市。
且当事耕稼，岂得便徒尔。
南阳葛亮为友朋，东山谢安作邻里。
闲常把琴弄，闷即携樽起。
莺啼二月三月时，花发千山万山里。
此时幽旷无人知，火急将书凭驿使，为报杜拾遗。','',''),('quantangshi-13587','怀素上人草书歌','任華','quantangshi','','卷14','吾尝好奇，古来草圣无不知，岂不知右军与献之。
虽有壮丽之骨，恨无狂逸之姿。
中间张长史，独放荡而不羁，以颠为名倾荡于当时。
张老颠，殊不颠于怀素。
怀素颠，乃是颠。
人谓尔从江南来，我谓尔从天上来。
负颠狂之墨妙，有墨狂之逸才。
狂僧前日动京华，朝骑王公大人马，暮宿王公大人家。
谁不造素屏，谁不涂粉壁。
粉壁摇晴光，素屏凝晓霜，待君挥洒兮不可弥忘。
骏马迎来坐堂中，金盆盛酒竹叶香。
十杯五杯不解意，百杯已后始颠狂。
一颠一狂多意气，大呌一声起攘臂。
挥毫倏忽千万字，有时一字两字长丈二。
翕若长鲸泼剌动海岛，歘若长蛇戌律透深草。
回环缭绕相拘连，千变万化在眼前。
飘风骤雨相击射，速禄飒拉动檐隙。
掷华山巨石以为点，掣衡山阵云以为画。
兴不尽，势转雄。
恐天低而地窄，更有何处最可怜，褭褭枯藤万丈悬。
万丈悬，拂秋水，映秋天。
或如丝，或如发，风吹欲绝又不绝，锋芒利如欧冶劒。
劲直浑是并州铁，时复枯燥何䙰褷。
忽觉阴山突兀横翠微，中有枯松错落一万丈。
倒挂绝壁蹙枯枝，千魑魅兮万魍魉，欲出不可何闪尸。
又如翰海日暮愁阴浓，忽然跃出千黑龙。
夭矫偃蹇，入乎苍穹。
飞沙走石满穷塞，万里飕飕西北风。
狂僧有绝艺，非数仞高墙不足以逞其笔势。
或逢花笺与绢素，凝神执笔守恒度。
别来筋骨多情趣，霏霏微微点长露。
三秋月照丹凤楼，二月花开上林树。
终恐绊骐骥之足，不得展千里之步。
狂僧狂僧，尔虽有绝艺。
犹当假良媒，不因礼部张公将尔来，如何得声名一旦喧九垓。','',''),('quantangshi-13588','金陵酧李翰林谪仙子','魏萬','quantangshi','','卷14','君抱碧海珠，我怀蓝田玉。
各称希代宝，万里遥相烛。
长卿慕蔺久，子猷意已深。
平生风云人，暗合江海心。
去秋忽乘兴，命驾来东土。
谪仙游梁园，爱子在邹鲁。
二处一不见，拂衣向江东。
五两挂海月，扁舟随长风。
南游吴越徧，高揖二千石。
雪上天台山，春逢翰林伯。
宣父敬项橐，林宗重黄生。
一长复一少，相看如弟兄。
惕然意不尽，更逐西南去。
同舟入秦淮，建业龙盘处。
楚歌对吴酒，借问承恩初。
宫买长门赋，天迎驷马车。
才高世难容，道废可推命。
安石重携妓，子房空谢病。
金陵百万户，六代帝王都。
虎石据西江，钟山临北湖。
二山信为美，王屋人相待。
应为岐路多，不知岁寒在。
君游早晚还，勿久风尘间。
此别未远别，秋期到仙山。','',''),('quantangshi-13589','赠李十二白','崔宗之','quantangshi','','卷14','凉风八九月，白露满空庭。
耿耿意不畅，捎捎风叶声。
思见雄俊士，共话今古情。
李侯忽来仪，把袂苦不早。
清论既抵掌，玄谈又绝倒。
分明楚汉事，历历王霸道。
担囊无俗物，访古千里余。
袖有匕首劒，怀中茂陵书。
双眸光照人，词赋凌子虚。
酌酒弦素秦，霜气正凝洁。
平生心中事，今日为君说。
我家有别业，寄在嵩之阳。
明月出高岑，清溪澄素光。
云散窗户静，风吹松桂香。
子若同斯游千载不相忘。','',''),('quantangshi-13590','赠李十二白','崔成甫','quantangshi','','卷14','我是潇湘放逐臣，君辞明主汉江滨。
天外常求太白老，金陵捉得酒仙人。','',''),('quantangshi-13591','寄题杜拾遗锦江野亭','嚴武','quantangshi','','卷14','漫向江头把钓竿，懒眠沙草爱风湍。
莫倚善题鹦鹉赋，何须不着鵕鸃冠。
腹中书籍幽时晒，肘后医方静处看。
兴发会能驰骏马，应须直到使君滩。','',''),('quantangshi-13592','酬别杜二','嚴武','quantangshi','','卷14','独逢尧典日，再覩汉官时。
未効风霜劲，空惭雨露私。
夜钟清万户，曙漏拂千旗。
并向殊庭谒，俱承别馆追。
斗城怜旧路，涡水惜归期。
峰树还相伴，江云更对垂。
试回沧海棹，莫妬敬亭诗。
秪是书应寄，无忘酒共持。
但令心事在，未肯鬓毛衰。
最怅巴山里，清猨醒梦思。','',''),('quantangshi-13593','题巴州光福寺楠木','嚴武','quantangshi','','卷14','楚江长流对楚寺，楠木幽生赤崖背。
临溪插石盘老根，苔色青苍山雨痕。
高枝闹叶鸟不度，半掩白云朝与暮。
香殿萧条转密阴，花龛滴沥垂清露。
闻道偏多越水头，烟生霁歛使人愁。
月明忽忆湘川夜，猨呌还思鄂渚秋。
看君幽霭几千丈，寂寞穷山今遇赏。
亦知钟梵报黄昏，犹卧禅牀恋奇响。','',''),('quantangshi-13594','班婕妤','嚴武','quantangshi','','卷14','贱妾如桃李，君王若岁时。
秋风一已劲，摇落不胜悲。
寂寂苍苔满，沈沈绿草滋。
繁华非此日，指辇竞何辞。','',''),('quantangshi-13595','巴岭答杜二见忆','嚴武','quantangshi','','卷14','卧向巴山落月时，两乡千里梦相思。
可但步兵偏爱酒，也知光禄最能诗。
江头赤叶枫愁客，篱外黄花菊对谁。
跂马望君非一度，冷猨秋雁不胜悲。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-13596','军城早秋','嚴武','quantangshi','','卷14','昨夜秋风入汉关，朔云边月满西山。
更催飞将追骄虏，莫遣沙场匹马远。','',''),('quantangshi-13597','潭州留别杜员外院长','韋迢','quantangshi','','卷14','江畔长沙驿，相逢缆客船。
大名诗独步，小郡海西偏。
地湿愁飞鵩，天炎畏跕鸢。
去留俱失意，把臂共潸然。','',''),('quantangshi-13598','早发湘潭寄杜员外院长','韋迢','quantangshi','','卷14','北风昨夜雨，江上早来凉。
楚岫千峰翠，湘潭一叶黄。
故人湖外客，白首尚为郎。
相忆无南雁，何时有报章。','',''),('quantangshi-13599','寄杜员外','郭受','quantangshi','','卷14','新诗海内流传久，旧德朝中属望劳。
郡邑地卑饶雾雨，江湖天阔足风涛。
松花酒熟傍看醉，莲叶舟轻自学操。
春兴不知凡几首，衡阳纸价顿能高。','',''),('quantangshi-13600','晦日呈诸判官','韓滉','quantangshi','','卷14','晦日新晴春色娇，万家攀折渡长桥。
年年老向江城寺，不觉春风换柳条。','',''),('quantangshi-13601','听乐怅然自述','韓滉','quantangshi','','卷14','万事伤心对管弦，一身含泪向春烟。
黄金用尽敎歌舞，留与他人乐少年。','',''),('quantangshi-13602','题弟臮述书赋后','竇蒙','quantangshi','','卷14','受命别家乡，思归每断肠。
季江留被在，子敬与琴亡。
吾弟当平昔，才名荷宠光。
作诗通小雅，献赋掩长杨。
流转三千里，悲啼百万行。
庭前紫荆树，何日再芬芳。','',''),('quantangshi-13603','迎春东郊','張濯','quantangshi','','卷14','颛顼时初谢，句芒令复陈。
飞灰将应节，宾日已知春。
考历明三统，迎祥受万人。
衣冠宵执玉，坛墠晓清尘。
肃穆来东道，回环拱北辰。
仗前花待发，旗处柳疑新。
云敛黄山际，冰开素浐滨。
圣朝多庆赏，希为荐沈沦。','',''),('quantangshi-13604','题舜庙','張濯','quantangshi','','卷14','古都遗庙出河濆，万代千秋仰圣君。
蒲坂城边长逝水，苍梧野外不归云。
寥寥象设魂应在，寂寂虞篇德已闻。
向晚风吹庭下栢，犹疑琴曲韵南薰。','',''),('quantangshi-13605','迎春东郊','王綽','quantangshi','','卷14','玉管潜移律，东郊始报春。
銮舆应宝运，天仗出佳辰。
睿泽光时辈，恩辉及物新。
虬螭动旌斾，烟景入城闉。
御柳初含色，龙池渐启津。
谁怜在阴者，得与蛰虫伸。','',''),('quantangshi-13606','邯郸少年行','鄭錫','quantangshi','','卷14','霞鞍金口骝，豹袖紫貂裘。
家住丛台近，门前漳水流。
唤人呈楚舞，借客试吴钩。
见说秦兵至，甘心赴国讐。','',''),('quantangshi-13607','陇头别','鄭錫','quantangshi','','卷14','秋尽初移幕，霑裳一送君。
据鞍窥古堠，开竈爇寒云。
登陇人回首，临关马顾羣。
从来断肠处，皆向此中分。','',''),('quantangshi-13608','度关山','鄭錫','quantangshi','','卷14','象弭插文犀，鱼肠莹䴙鹈。
水声分陇咽，马色度关迷。
晓幕胡沙惨，危烽汉月低。
仍闻数骑将，更欲出辽西。','',''),('quantangshi-13609','出塞','鄭錫','quantangshi','','卷14','关山落叶秋，掩泪望营州。
辽海云沙暮，幽燕旌斾愁。
战余能送阵，身老未封侯。
去国三千里，归心红粉楼。','',''),('quantangshi-13610','玉阶怨','鄭錫','quantangshi','','卷14','长门寒水流，高殿晓风秋。
昨夜鸳鸯梦，还陪豹尾游。
前鱼不解泣，共辇岂关羞。
那及轻身燕，双飞上玉楼。','',''),('quantangshi-13611','千里思','鄭錫','quantangshi','','卷14','渭水通胡苑，轮台望汉关。
帛书秋海断，锦字夜机闲。
旅梦虫催晓，边心雁带还。
惟余两乡思，一夕度关山。','',''),('quantangshi-13612','襄阳乐','鄭錫','quantangshi','','卷14','春生岘首东，先暖习池风。
拂水初含绿，惊林未吐红。
渚边游汉女，桑下问庞公。
磨灭怀中刺，曾将示孔融。','',''),('quantangshi-13613','送客之江西','鄭錫','quantangshi','','卷14','乘轺奉紫泥，泽国渺天涯。
九派春潮满，孤帆暮雨低。
草深莺断续，花落水东西。
更有高唐处，知君路不迷。','',''),('quantangshi-13614','望月','鄭錫','quantangshi','','卷14','高堂新月明，虚殿夕风清。
素影纱窗霁，浮凉羽扇轻。
稍随微露滴，渐逐晓参横。
遥忆云中咏，萧条空复情。','',''),('quantangshi-13615','出塞曲','鄭錫','quantangshi','','卷14','校尉征兵出塞西，别营分骑过龙溪。
沙平虏迹风吹尽，雾失烽烟道易迷。
玉靶半开鸿已落，金河欲渡马连嘶。
会当系取天骄入，不使军书夜刺闺。','',''),('quantangshi-13616','秦人谣','古之奇','quantangshi','','卷14','微生祖龙代，却思尧舜道。
何人仕帝庭，拔杀指佞草。
奸臣弄民柄，天子恣衷抱。
上下一相蒙，马鹿遂颠倒。
中国既板荡，骨肉安可保。
人生贵年寿，吾恨死不早。','',''),('quantangshi-13617','阮客旧居','李陽冰','quantangshi','','卷14','阮客身何在，仙云洞口横。
人间不到处，今日此中行。','',''),('quantangshi-13618','酬耿拾遗题赠','嚴維','quantangshi','','卷14','掩扉常自静，驿吏忽传呼。
水巷惊驯鸟，藜牀起病躯。
顾身悲欲老，戒子力为儒。
明日公西去，烟霞复作徒。','',''),('quantangshi-13619','酬王侍御西陵渡见寄','嚴維','quantangshi','','卷14','前年万里别，昨日一封书。
郢曲西陵渡，秦官使者车。
柳塘薰昼日，花水溢春渠。
若不嫌鸡黍，先令扫弊庐。','',''),('quantangshi-13620','酬刘员外见寄','嚴維','quantangshi','','卷14','苏耽佐郡时，近出白云司。
药补清羸疾，窗吟绝妙词。
柳塘春水慢，花坞夕阳迟。
欲识怀君意，明朝访檝师。','',''),('quantangshi-13621','同韩员外宿云门寺','嚴維','quantangshi','','卷14','小岭路难近，仙郎此夕过。
潭空观月定，涧静见云多。
竹翠烟深锁，松声雨点和。
万缘俱不有，对境自垂萝。','',''),('quantangshi-13622','酬诸公宿镜水宅','嚴維','quantangshi','','卷14','幸免低头向府中，贵将藜藿与君同。
阳雁呌霜来枕上，寒山映月在湖中。
诗书何德名夫子，草木推年长数公。
闻道汉家偏尚少，此身那此访芝翁。','',''),('quantangshi-13623','送薛尚书入蜀','嚴維','quantangshi','','卷14','卑情不敢论，拜首入辕门。
列郡诸侯长，登朝八座尊。
凝笳临水发，行斾向风飜。
几许遗黎泣，同怀父母恩。','',''),('quantangshi-13624','送李祕书往儋州','嚴維','quantangshi','','卷14','魑魅曾为伍，蓬莱近拜郎。
臣心瞻北阙，家事在南荒。
莎草山城小，毛洲海驿长。
玄成知必大，宁是泛沧浪。','',''),('quantangshi-13625','送人入金华','嚴維','quantangshi','','卷14','明月双溪水，清风八咏楼。
昔年为客处，今日送君游。','',''),('quantangshi-13626','送崔峒使往睦州兼寄薛司户','嚴維','quantangshi','','卷14','如今相府用英髦，独往南州肯告劳。
冰水近开渔浦出，雪云初卷定山高。
木奴花映桐庐县，青雀舟随白露涛。
使者应须访廉吏，府中惟有范功曹。','',''),('quantangshi-13627','送房元直赴北京','嚴維','quantangshi','','卷14','犹道楼兰十万师，书生匹马去何之。
临歧未断归家目，望月空吟出塞诗。
常欲激昂论上策，不应憔悴老明时。
遥知到日逢寒食，彩笔长裾会晋祠。','',''),('quantangshi-13628','荆溪馆呈丘义兴','嚴維','quantangshi','','卷14','失路荆溪上，依人忽暝投。
长桥今夜月，阳羡古时州。
野烧明山郭，寒更出县楼。
先生能馆我，无事五湖游。','',''),('quantangshi-13629','一公新泉','嚴維','quantangshi','','卷14','山下新泉出，泠泠北去源。
落池才有响，喷石未成痕。
独映孤松色，殊分众鸟喧。
唯当清夜月，观此启禅门。','',''),('quantangshi-13630','奉试水精环','嚴維','quantangshi','','卷14','王室符长庆，环中得水精。
任圆循不极，见素质仍贞。
信是天然瑞，非因朴斲成。
无瑕胜玉美，至洁过冰清。
未肯齐珉价，宁同杂佩声。
能衔任黄雀，亦欲应时明。','',''),('quantangshi-13631','自云阳归晚泊陆澧宅','嚴維','quantangshi','','卷14','天阴行易晚，前路故人居。
孤棹所思久，寒林相见初。
闲灯忘夜水，清漏任更疎。
明发还须去，离家几岁除。','',''),('quantangshi-13632','九日陪崔郎中北山宴','嚴維','quantangshi','','卷14','上客南台至，重阳此会文。
菊芳寒露洗，杯翠夕阳曛。
务简人同醉，溪闲鸟自羣。
府中官最小，唯有孟参军。','',''),('quantangshi-13633','留别邹绍刘长卿','嚴維','quantangshi','','卷14','中年从一尉，自笑此身非。
道在甘微禄，时难耻息机。
晨趋本郡府，书掩故山扉。
待见干戈毕，何妨更采薇。','',''),('quantangshi-13634','书情献相公','嚴維','quantangshi','','卷14','年来白发欲星星，误却生涯是一经。
魏阙望中何日见，商歌奏罢复谁听。
孤根独弃慙山木，弱质无成状水萍。
今日更须询哲匠，不应休去老岩扃。','',''),('quantangshi-13635','赠送朱放','嚴維','quantangshi','','卷14','昔年居汉水，日醉习家池。
道胜迹常在，名高身不知。
欲依天目住，新自始宁移。
生事曾无长，惟将白接䍦。','',''),('quantangshi-13636','剡中赠张卿侍御','嚴維','quantangshi','','卷14','辟疆年正少，公子贵初还。
早列月卿位，新参柱史班。
千夫驰驿道，驷马入家山。
深巷乌衣盛，高门画戟闲。
逶迤天乐下，照耀剡溪间。
自贱游章句，空为衰草颜。','',''),('quantangshi-13637','赠万经','嚴維','quantangshi','','卷14','万公长慢世，昨日又隳官。
纵酒真彭泽，论诗得建安。
家山伯禹穴，别墅小长干。
輙有时人至，窗前白眼看。','',''),('quantangshi-13638','书情上李苏州','嚴維','quantangshi','','卷14','东土苗人尚有残，皇皇亚相出朝端。
手持国宪羣僚畏，口喻天慈百姓安。
礼数自怜今日绝，风流空计往年欢。
误着青袍将十载，忍令渔浦却垂竿。','',''),('quantangshi-13639','余姚祗役奉简鲍参军','嚴維','quantangshi','','卷14','童年献赋在皇州，方寸思量君与侯。
万事无成新白首，两春虚掷对沧流。
歌诗盛赋文星动，箫管新亭晦日游。
知己欲依何水部，乡人今正贱东丘。','',''),('quantangshi-13640','奉和独孤中丞游云门寺','嚴維','quantangshi','','卷14','绝壑开花界，耶溪极上源。
光辉三独坐，登陟五云门。
深木鸣驺驭，晴山曜武贲。
乱泉观坐卧，疎磬发朝昏。
苍翠新秋色，莓苔积雨痕。
上方看度鸟，后夜听吟猿。
异迹焚香对，新诗酌茗论。
归来还抚俗，诸老莫攀辕。','',''),('quantangshi-13641','奉和皇甫大夫夏日游花严寺','嚴維','quantangshi','','卷14','初第华严会，王家少长行。
到宫龙节驻，礼塔雁行成。
莲界千峰静，梅天一雨清。
禅庭未可恋，圣主寄苍生。','',''),('quantangshi-13642','宿法华寺','嚴維','quantangshi','','卷14','一夕雨沈沈，哀猨万木阴。
天龙来护法，长老密看心。
鱼梵空山静，纱灯古殿深。
无生久已学，白发浪相侵。','',''),('quantangshi-13643','题茅山李尊师所居','嚴維','quantangshi','','卷14','天师百岁少如童，不到山中更不逢。
洗药每临新瀑水，步虚时遶最高峰。
篱根五月留残雪，座右千年荫古松。
此去人寰知近远，回看路隔一重重。','',''),('quantangshi-13644','送薛居士和州读书','嚴維','quantangshi','','卷14','孤云独鹤共悠悠，万卷经书一叶舟。
楚地巢城民舍少，烟村社树鹭湖秋。
蒿莱织妾晨炊黍，隅落耕童夕放牛。
年少不应辞苦节，诸生若遇亦封侯。','',''),('quantangshi-13645','送李端','嚴維','quantangshi','','卷14','故关衰草遍，离别正堪悲。
路出寒云外，人归暮雪时。
少孤为客早，多难识君迟。
揜泣空相向，风尘何所期。','',''),('quantangshi-13646','宿天竺寺','嚴維','quantangshi','','卷14','方外主人名道林，怕将水月净身心。
居然对我说无我，寂历山深将夜深。','',''),('quantangshi-13647','丹阳送韦参军','嚴維','quantangshi','','卷14','丹阳郭里送行舟，一别心知两地秋。
日晚江南望江北，寒鸦飞尽水悠悠。','',''),('quantangshi-13648','入唐溪','嚴維','quantangshi','','卷14','啸终万籁起，吹去当溪云。
环屿或明昧，远峯尚氛氲。
雨新翠叶发，夜早玄象分。
金涧流不尽，入山深更闻。','',''),('quantangshi-13649','送桃岩成上人归本寺','嚴維','quantangshi','','卷14','长老归缘起，桃花忆旧岩。
清晨云抱石，深夜月笼杉。
道具门人捧，斋粮谷鸟衔。
余生愿依止，文字欲三缄。','',''),('quantangshi-13650','酬普选二上人期相会见寄','嚴維','quantangshi','','卷14','本意宿东林，因听子贱琴。
遥知大小朗，已断去来心。
夜静溪声近，庭寒月色深。
宁知尘外意，定后便成吟。','',''),('quantangshi-13651','相里使君宅听澄上人吹小管','嚴維','quantangshi','','卷14','秦僧吹竹闭秋城，早在梨园称主情。
今夕襄阳山太守，座中流泪听商声。','',''),('quantangshi-13652','赠别至弘上人','嚴維','quantangshi','','卷14','最称弘偃少，早岁草茆居。
年老从僧律，生知解佛书。
衲衣求坏帛，野饭拾春蔬。
章句无求断，时中学有余。','',''),('quantangshi-13653','奉和刘祭酒伤白马','嚴維','quantangshi','','卷14','沛艾如龙马，来从上苑中。
棣华恩见赐，伯舅礼仍崇。
镜点黄金眼，花开白雪鬃。
性柔君子德，足逸大王风。
色照鸣珂静，声连喷玉雄。
食场恩未尽，过隟命旋终。
练影依云没，银鞍向月空。
仍闻乐府唱，犹念代劳功。','',''),('quantangshi-13654','哭灵一上人','嚴維','quantangshi','','卷14','一公何不住，空有远公名。
共说岑山路，今时不可行。
旧房松更老，新塔草初生。
经论传缁侣，文章遍墨卿。
禅林枝干折，法宇栋梁倾。
谁复修僧史，应知传已成。','',''),('quantangshi-13655','题鲍行军小阁','嚴維','quantangshi','','卷14','宇下无留事，经营意独新。
文房已得地，相阁是推轮。
席上招贤急，山阴对雪频。
虚明先旦暮，启闭异冬春。
谈笑兵家法，逢迎幕府宾。
还将负暄处，时借在阴人。','',''),('quantangshi-13656','陪皇甫大夫谒禹庙','嚴維','quantangshi','','卷14','竹使羞殷荐，松龛拜夏祠。
为鱼歌德后，舞羽降神时。
文卫瞻如在，精灵信有期。
夕阳陪醉止，塘上鸟咸迟。','',''),('quantangshi-13657','同王徴君湘中有怀','嚴維','quantangshi','','卷14','八月洞庭秋，潇湘水北流。
还家万里梦，为客五更愁。
不用看书帙，偏宜上酒楼。
故人京洛满，何日复同游。','',''),('quantangshi-13658','奉和皇甫大夫祈雨应时雨降','嚴維','quantangshi','','卷14','致和知必感，岁旱未书灾。
伯禹明灵降，元戎祷请来。
九成陈夏乐，三献奉殷罍。
掣曳旗交电，铿锵鼓应雷。
行云依盖转，飞雨逐车回。
欲识皇天意，为霖贶在哉。','',''),('quantangshi-13659','赠别刘长卿时赴河南严中丞幕府','嚴維','quantangshi','','卷14','早见登郎署，同时迹下僚。
几年江路永，今去国门遥。
文变骚人体，官移汉帝朝。
望山吟度日，接枕话通宵。
万里趋公府，孤帆恨信潮。
匡时知已老，圣代耻逃尧。','',''),('quantangshi-13660','晦日宴游','嚴維','quantangshi','','卷14','晦日湔裾俗，春楼致酒时。
出山还已醉，谢客旧能诗。
溪柳薰晴浅，岩花待闰迟。
为邦久无事，比屋自熙熙。','',''),('quantangshi-13661','夏日纳凉','嚴維','quantangshi','','卷14','山阴过野客，镜里接仙郎。
盥漱临寒水，褰闱入夏堂。
杉松交日影，枕簟上湖光。
衮衮承嘉话，清风纳晚凉。','',''),('quantangshi-13662','僧房避暑','嚴維','quantangshi','','卷14','支公好闲寂，庭宇爱林篁。
幽旷无烦暑，恬和不可量。
蕙风清水殿，荷气杂天香。
明月谈空坐，怡然道术忘。','',''),('quantangshi-13663','九日登高','嚴維','quantangshi','','卷14','诗家九日怜芳菊，迟客高斋瞰浙江。
汉浦浪花摇素壁，西陵树色入秋窗。
木奴向熟悬金实，桑落新开泻玉缸。
四子醉时争讲德，笑论黄霸屈为邦。','',''),('quantangshi-13664','九月十日即事','嚴維','quantangshi','','卷14','家贫惟种竹，时幸故人看。
菊度重阳少，林经闰月寒。
宿酲犹落帽，华发强扶冠。
美景良难得，今朝更尽欢。','',''),('quantangshi-13665','送丘为下第归苏州','嚴維','quantangshi','','卷14','沧江一身客，献赋空十年。
明主岂能好，今人谁举贤。
国门税征驾，旅食谋归旋。
皦日媚春水，绿苹香客船。
无媒既不达，余亦思归田。','',''),('quantangshi-13666','送少微上人东南游','嚴維','quantangshi','','卷14','旧游多不见，师在翟公门。
瘴海空山热，雷州白日昏。
片心应为法，万里独无言。
人尽酬恩去，平生未感恩。','',''),('quantangshi-13667','赠送崔子向','嚴維','quantangshi','','卷14','旅食来江上，求名赴洛阳。
新诗踪谢守，内学似支郎。
行怯秦为客，心依越是乡。
何人作知己，送尔泪浪浪。','',''),('quantangshi-13668','答刘长卿七里濑重送','嚴維','quantangshi','','卷14','新安非欲枉帆过，海内如君有几何。
醉里别时秋水色，老人南望一狂歌。','',''),('quantangshi-13669','岁初喜皇甫侍御至','嚴維','quantangshi','','卷14','湖上新正逢故人，情深应不笑家贫。
明朝别后门还掩，修竹千竿一老身。','',''),('quantangshi-13670','送舍弟','嚴維','quantangshi','','卷14','疎懒吾成性，才华尔自彊。
早称眉最白，何事绶仍黄。
时暑嗟于迈，家贫念聚粮。
秪应宵梦里，诗兴属池塘。','',''),('quantangshi-13671','示外生','嚴維','quantangshi','','卷14','牵役非吾好，宽情尔在傍。
经过悲井邑，起坐倦舟航。
相宅生应贵，逢时学可强。
无轻吾未用，世事有行藏。','',''),('quantangshi-13672','咏孩子','嚴維','quantangshi','','卷14','嘉客会初筵，宜时魄再圆。
众皆含笑戏，谁不点颐怜。
绣被花堪摘，罗绷色欲妍。
将雏有旧曲，还入武城弦。','',''),('quantangshi-13673','酬谢侍御喜王宇及第见贺不遇之作','嚴維','quantangshi','','卷14','寂寞柴门掩，经过柱史荣。
老夫宁有力，半子自成名。
柳映三桥发，花连上道明。
缄书到别墅，郢曲果先成。','',''),('quantangshi-13674','秋日与诸公文会天寺','嚴維','quantangshi','','卷14','相访从吾道，因缘会尔时。
龙盘余帝宅，花界古人祠。
明月虚空色，青林大小枝。
还将经济学，来问道安师。','',''),('quantangshi-13675','答刘长卿蛇浦桥月下重送','嚴維','quantangshi','','卷14','月色今宵最明，庭闲夜久天清。
寂寞多年老宦，殷勤远别深情。
溪临修竹烟色，风落高梧雨声。
耿耿相看不寐，遥闻晓柝山城。','',''),('quantangshi-13676','发桐庐寄刘员外','嚴維','quantangshi','','卷14','处处云山无尽时，桐庐南望转参差。
舟人莫道新安近，欲上潺湲行自迟。','',''),('quantangshi-13677','秋夜船行','嚴維','quantangshi','','卷14','扁舟时属暝，月上有余辉。
海燕秋还去，渔人夜不归。
中流何寂寂，孤棹也依依。
一点前村火，谁家未掩扉。','',''),('quantangshi-13678','游灞陵山','嚴維','quantangshi','','卷14','入山未尽意，胜迹聊独寻。
方士去在昔，药堂留至今。
四隅白云闲，一路清溪深。
芳秀惬春目，高闲宜远心。
潭分化丹水，路遶升仙林。
此道人不悟，坐鸣松下琴。','',''),('quantangshi-13679','重送新安刘员外','嚴維','quantangshi','','卷14','秋江渺渺水空波，越客孤舟欲榜歌。
手折衰杨悲老大，故人零落已无多。','',''),('quantangshi-13680','忆长安 五月','嚴維','quantangshi','','卷14','忆长安，五月时，君王避暑华池。
进膳甘瓜朱李，续命芳兰彩丝。
竞处高明台榭，槐阴柳色通逵。','',''),('quantangshi-13681','状江南 季春','嚴維','quantangshi','','卷14','江南季春天，莼叶细如弦。
池边草作迳，湖上叶如船。','',''),('quantangshi-13682','句','嚴維','quantangshi','','卷14','五色惊彩凤，千里象骢威。
三伏轩车动，尧心急谏官。
名通内籍贵，立近御牀寒。
波从少海息，云自大风开。','',''),('quantangshi-13683','琴歌','顧況','quantangshi','','卷14','琴调秋些，胡风遶雪。
峡泉声咽，佳人愁些。','',''),('quantangshi-13684','上古之什补亡训传十三章','顧況','quantangshi','','卷14','遐哉上古，生弃与柱。
句龙是生，乃有甫田。
惟彼甫田，有万斯年。
开利之源，无乃塞源。
一廛亦官，百廛亦官。
啬夫孔艰，浸兮暵兮，申有螽兮。
惟馨祀是患，岂止馁与寒。
啬夫咨咨，䅎盛苗衰。
耕之耰之，襏襫锄犂。
手胼足胝，水之蛭螾。
吮喋我肌，我姑自思。
胡不奋飞，东人利百。
西人利百，有匪我心。
胡为不易，河水活活。
万人逐末，俾尔之愉悦兮。','',''),('quantangshi-13685','上古之什补亡训传十三章 一','顧況','quantangshi','','卷14','左车有庆，万人犹病。
曷可去之，于党孔盛。
敏尔之生，胡为波迸。','',''),('quantangshi-13686','上古之什补亡训传十三章 二','顧況','quantangshi','','卷14','左车有赫，万人毒螫。
曷可去之，于党孔硕。
敏尔之生，胡为草戚。','',''),('quantangshi-13687','上古之什补亡训传十三章 一','顧況','quantangshi','','卷14','筑城登登，于以作固。
咨尔寺兮，发郊外冢墓。
死而无知，犹或不可。
若其有知，惟上帝是愬。','',''),('quantangshi-13688','上古之什补亡训传十三章 二','顧況','quantangshi','','卷14','筑城奕奕，于以固敌。
咨尔寺兮，发郊外冢甓。
死而无知，犹或不可。
若其有知，惟上帝是谪。','',''),('quantangshi-13689','上古之什补亡训传十三章','顧況','quantangshi','','卷14','持斧持斧，无翦我松柏兮。','',''),('quantangshi-13690','上古之什补亡训传十三章','顧況','quantangshi','','卷14','十月之郊，羣木肇生。
阳潜地中，舒达句萌。
曀其蔚兮，不可以游息。
乃熂蒺藜，乃夷荆棘。
乃繇彼曲直，匠氏度思。
登斧以时，泽梁蓁蓁。
无或夭枝，有巨根蔕。
生混茫际，呼吸羣籁。
万人挥斤，坎坎有厉。
陆迁水济，百力殚弊。
审方面势，姑博其制。
作为公室，公室既成。
御燥湿风日，栋之斯厚。
榱之斯密，如翼于飞。
如鳞栉比，缭以周墉。
墄以崇阶，俯而望之。
矗与云齐，啸砆碔砆。
藻井旋题，丹素之燝兮。
椒挂之馥兮，高阁高阁。
珠缀结络，金铺烂若。
不集于鸟雀，绘事告毕。
宾筵秩秩，乃命旨酒琴瑟。
琴瑟在堂，莫不静谧。
周环掩辟，仰不漏日。
冬日严凝，言纳其阳。
和风载升，夏日郁蒸。
言用于阴，凉封飒兴。
有匪君子，自贤不已。
乃梦乘舟，乃梦乘车。
梦人占之，更爽其居。
炎炎则移，皎皎则亏。
木实之繁兮，明年息枝。
爰处若思，胡宁不尔思。','',''),('quantangshi-13691','上古之什补亡训传十三章','顧況','quantangshi','','卷14','燕燕于巢，缀葺维戊。
甲兮乙兮，不宜有谬。
飞龙在天，云掩于斗。
曷日于雨，乃曰庚午。
彼日之差，亦孔斯丑。
昔在羲和，湎淫不修。
我筮我龟，莫我告繇。
胤廼征之，彝伦九畴。
君子授律，是禡是禷。
三五不备，罔克攸遂。
惠此蒸人，毋废尔事。
尔莫我从，维来者是冀。','',''),('quantangshi-13692','上古之什补亡训传十三章','顧況','quantangshi','','卷14','苏方之赤，在胡之舶。
其利乃博，我土旷兮。
我居阗兮，我衣不白兮。
朱紫烂兮，传瑞晔兮，相唐虞之维百兮。','',''),('quantangshi-13693','上古之什补亡训传十三章','顧況','quantangshi','','卷14','陵霜之华，我心忧嗟。
阴之胜矣，而阳不加。
坱轧陶钧，乃帝乃神。
乃舒乃屯，烈烈严秋。
熙熙阳春，职生有伦。
今华发非其辰，辰属东方之仁。
遐想三五，黄帝登云。
尧年百余，二仪分位。
六气不渝，二景如璧，五星如珠。','',''),('quantangshi-13694','上古之什补亡训传十三章','顧況','quantangshi','','卷14','囝生闽方，闽吏得之。
乃绝其阳，为臧为获。
致金满屋，为髠为钳。
如视草木，天道无知。
我罹其毒，神道无知。
彼受其福，郎罢别囝。
吾悔生汝，及汝既生。
人劝不举，不从人言。
果获是苦，囝别郎罢。
心催血下，隔地绝天。
及至黄泉，不得在郎罢前。','',''),('quantangshi-13695','上古之什补亡训传十三章','顧況','quantangshi','','卷14','我行自东，山海其空。
旅棘有丛，我行自西。
垒与云齐，雨雪凄凄。
我行自南，烈火满林。
日中无禽，雾雨淫淫。
我行自北，烛龙寡色。','',''),('quantangshi-13696','上古之什补亡训传十三章','顧況','quantangshi','','卷14','采采者蜡，于泉谷兮。
煌煌中堂，烈华烛兮。
新歌善舞，弦柱促兮。
荒岩之人，自取其毒兮。','',''),('quantangshi-13697','弃妇词','顧況','quantangshi','','卷14','古人虽弃妇，弃妇有归处。
今日妾辞君，辞君欲何去。
本家零落尽，恸哭来时路。
忆昔未嫁君，闻君甚周旋。
及与同结发，值君适幽燕。
孤魂托飞鸟，两眼如流泉。
流泉咽不燥，万里关山道。
及至见君归，君归妾已老。
物情弃衰歇，新宠方妍好。
拭泪出故房，伤心剧秋草。
妾以憔悴捐，羞将旧物远。
余生欲有寄，谁肯相留连。
空牀对虚牖，不觉尘埃厚。
寒水芙蓉花，秋风堕杨柳。
记得初嫁君，小姑始扶牀。
今日君弃妾，小姑如妾长。
回头语小姑，莫嫁如兄夫。','',''),('quantangshi-13698','游子吟','顧況','quantangshi','','卷14','故枥思疲马，故窠思迷禽。
浮云蔽我乡，踯躅游子吟。
游子悲久滞，浮云郁东岑。
客堂无丝桐，落叶如秋霖。
艰哉远游子，所以悲滞淫。
一为浮云词，愤塞谁能禁。
驰归百年内，唯愿展所钦。
胡为不归欤，坐使年病侵。
未老霜遶鬓，非狂火烧心。
太行何难哉，北斗不可斟。
夜静星河出，耿耿辰与参。
佳人敻青天，尺素重于金。
泬寥羣动异，眇默诸境森。
苔衣上闲阶，蟋蟋催寒砧。
立身计几悞，道险无容针。
三年不还家，万里遗锦衾。
梦魂无重阻，离忧罔古今。
胡为不归欤，辜负匣中琴。
腰下是何物，牵缠旷登寻。
朝与名山期，夕宿楚水阴。
楚水殊演漾，名山窅岖嵚。
客从洞庭来，婉娈潇湘深。
橘柚在南国，鸿雁遗秋音。
下有碧草洲，上有青橘林。
引烛窥洞穴，凌波睥天琛。
蒲荷影参差，凫鹤雏淋涔。
浩歌惜芳杜，散发轻华簪。
胡为不归欤，泪下沾衣襟。
鸢飞戾宵汉，蝼蚁制鳣鱏。
赫赫大圣朝，日月光照临。
圣主虽启迪，奇人分湮沈。
层城登云韶，王府锵球琳。
鹿鸣志丰草，况复虞人箴。','',''),('quantangshi-13699','拟古三首 一','顧況','quantangshi','','卷14','龙剑昔藏影，送雄留其雌。
人生阻欢会，神物亦别离。
碧树感秋落，佳人无还期。
夜琴为君咽，浮云为君滋。
爱而伤不见，星汉徒参差。','',''),('quantangshi-13700','拟古三首 二','顧況','quantangshi','','卷14','幽居盼天造，胡息运行机。
春葩妍既荣，秋叶瘁以飞。
滔滔川之逝，日没月光辉。
所贵法干健，于道悟入微。
任彼声势徒，得志方夸毗。','',''),('quantangshi-13701','拟古三首 三','顧況','quantangshi','','卷14','浮生果何慕，老去羡介推。
陶令何足录，彭泽归已迟。
空负漉酒巾，乞食形诸诗。
吾惟抱贞素，悠悠白云期。','',''),('quantangshi-13702','伤子','顧況','quantangshi','','卷14','老夫哭爱子，日暮千行血。
声逐断猿悲，迹随飞鸟灭。
老夫已七十，不作多时别。','',''),('quantangshi-13703','春游曲 一','顧況','quantangshi','','卷14','游童苏合带，倡女蒲葵扇。
初日映城时，相思忽相见。
褰裳踏露草，理鬓回花面。
薄暮不同归，留情此芳甸。','',''),('quantangshi-13704','春游曲 二','顧況','quantangshi','','卷14','柘弹连钱马，银钩妥堕鬟。
采桑春陌上，踏草夕阳间。
意合词先露，心诚貌却闲。
明朝若相忆，云雨出巫山。','',''),('quantangshi-13705','从军行二首 一','顧況','quantangshi','','卷14','弭节结徒侣，速征赴龙城。
单于近突围，烽燧屡夜惊。
长弓挽满月，剑华霜雪明。
远道百草殒，峭觉寒风生。
风寒欲砭肌，争奈裘袄轻。
回首家不见，候雁空中鸣。
笳奏遝以哀，肃肃趣严程。
寄语塞外胡，拥骑休横行。','',''),('quantangshi-13706','从军行二首 二','顧況','quantangshi','','卷14','少年胆气麁，好勇万人敌。
仗剑出门去，三边正艰厄。
怒目时一呼，万骑皆辟易。
杀人蓬麻轻，走马汗血滴。
丑虏何足清，天山坐宁谧。
不有封侯相，徒负幽并客。','',''),('quantangshi-13707','塞上曲','顧況','quantangshi','','卷14','黠虏初南下，尘飞塞北境。
汉将怀不平，讐扰当远屏。
金革卧不暖，起舞霜月冷。
点军三十千，部伍严以整。
酣战祈成功，于焉罢边衅。','',''),('quantangshi-13708','弋阳溪中望仙人城','顧況','quantangshi','','卷14','何草乏灵姿，无山不孤绝。
我行虽云蹇，偶胜聊换节。
上界浮中流，光响洞明灭。
晚禽曝霜羽，寒鱼依石发。
自有无还心，隔波望松雪。','',''),('quantangshi-13709','严公钓台作','顧況','quantangshi','','卷14','灵芝产遐方，威凤家重宵。
严生何耿洁，托志肩夷巢。
汉后虽则贵，子陵不知高。
糠粃当世道，长揖夔龙朝。
扫门彼何人，升降不同朝。
舍舟遂长往，山谷多清飙。','',''),('quantangshi-13710','萧寺偃松','顧況','quantangshi','','卷14','凄凄百卉病，亭亭双松逈。
直上古寺深，横拂秋殿冷。
轻响入龟目，片阴栖鹤顶。
山中多好树，可怜无比并。','',''),('quantangshi-13711','独游青龙寺','顧況','quantangshi','','卷14','春风入香刹，暇日独游衍。
旷然莲花台，作礼月光面。
乘兹第八识，出彼超二见。
摆落区中缘，无边广弘愿。
长廊朝雨毕，古木时禽啭。
积翠暧遥原，杂英纷似霰。
凤城腾日窟，龙首横天堰。
蚁步避危阶，蝇飞响深殿。
大通智胜佛，几刦道场现。','',''),('quantangshi-13712','初秋莲塘归','顧況','quantangshi','','卷14','秋光净无迹，莲消锦云红。
只有溪上山，还识扬舲翁。
如何白苹花，幽渚笑凉风。','',''),('quantangshi-13713','从江西至彭蠡入浙西淮南界道中寄齐相公','顧況','quantangshi','','卷14','大贤旧丞相，作镇江山雄。
自镇江山来，何人得如公。
处士待徐孺，仙人期葛洪。
一身控上游，八郡趋下风。
比屋除畏溺，林塘曳烟虹。
生人罢虔刘，井税均且充。
大府肃无事，欢然接悲翁。
心清百丈泉，目送孤飞鸿。
数年鄱阳掾，抱责栖微躬。
首阳及汨罗，无乃褊其衷。
杨朱并阮籍，未免哀途穷。
四贤虽得仁，此怨何怱怱。
老氏齐宠辱，于陵一穷通。
本师留度门，平等冤亲同。
能依二谛法，了达三轮空。
真境靡方所，出离内外中。
无边尽未来，定惠双修功。
蹇步慙寸进，餙装随转蓬。
朝行楚水阴，夕宿吴洲东。
吴洲复白云，楚水飘丹枫。
晚霞烧廻潮，千里光曈曈。
蓂开海上影，桂吐淮南丛。
何当翼明庭，草木生春融。','',''),('quantangshi-13714','寄上兵部韩侍郎奉呈李户部卢刑部杜三侍郎','顧況','quantangshi','','卷14','道路五千里，门阑三十年。
当时携手人，今日无半全。
咏题官舍内，赋韵僧房前。
公登略彴桥，况榜龙{舟昂}船。
远寺吐朱阁，春潮浮绿烟。
鵷鸿翔邓林，沙鸨飞吴田。
诸子纷出祖，中宵久留连。
坐客三千人，皆称主人贤。
国士分如此，家臣亦依然。
身在薜萝中，头刺文案边。
故吏已重叠，门生从联翩。
得罪为何名，无阶问皇天。
出门多岐路，命驾无由缘。
伏承诸侍郎，顾念犹迍邅。
圣代逢三宥，营魂空九迁。','',''),('quantangshi-13715','长安窦明府后亭','顧況','quantangshi','','卷14','君为长安令，我美长安政。
五日一朝天，南山对明镜。
鸟飞青苔院，水木相辉映。
客至南云乡，丝桐展歌咏。
吏人何萧萧，终岁无喧竞。
欲识明府贤，邑中多百姓。','',''),('quantangshi-13716','谢王郎中见赠琴鹤','顧況','quantangshi','','卷14','此琴等焦尾，此鹤方胎生。
赴节何徘徊，理感物自并。
独立江海上，一弹天地清。
朱弦动瑶华，白羽飘玉京。
因想羡门辈，眇然四体轻。
子乔翔邓林，王母游层城。
忽如启灵署，鸾凤相和鸣。
何由玉女牀，去食琅玕英。','',''),('quantangshi-13717','和翰林吴舍人兄弟西斋','顧況','quantangshi','','卷14','君家诚易知，易知复难同。
新裁尺一诏，早入明光宫。
西斋何其高，上与星汉通。
永怀洞庭石，春色相玲珑。
久怀巴峡泉，夜落君丝桐。
信是怡神所，迢迢蔑华嵩。
鸟飞晴云灭，叠嶂盘虚空。
君家诚易知，易知意难穷。','',''),('quantangshi-13718','望初月简于吏部','顧況','quantangshi','','卷14','泬寥中秋夜，坐见如钩月。
始从西南升，又欲西南没。
全移河上影，暂透林间缺。
纵待三五时，终为千里别。','',''),('quantangshi-13719','上湖至破山赠文周萧元植','顧況','quantangshi','','卷14','一别二十年，依依过故辙。
湖上非往态，梦想频虚结。
二子伴我行，我行感徂节。
后人应不识，前事寒泉咽。
一别二十年，人堪几回别。','',''),('quantangshi-13720','酬信州刘侍郎兄','顧況','quantangshi','','卷14','刘兄本知命，屈伸不介怀。
南州管灵山，可惜旷土栖。
樵隐同一径，竹树薄西斋。
鸟陵嶂合杳，月配波徘徊。
薄宦修礼数，长景谢谭谐。
愿为南州民，输税事鉏犁。
胡为走不止，风雨惊邅回。','',''),('quantangshi-13721','奉酬刘侍郎','顧況','quantangshi','','卷14','几回新秋影，壁满蟾又缺。
镜破似倾台，轮斜同覆辙。
虽分上林桂，还照沧洲雪。
暂伴顦顇人，归华耿不灭。','',''),('quantangshi-13722','酬本部韦左司','顧況','quantangshi','','卷14','好鸟依佳树，飞雨洒高城。
况与二三子，列坐分两楹。
文雅一何盛，林塘含余清。
府君未归朝，游子不待晴。
白云帝城远，沧江枫叶鸣。
却略欲一言，零泪和酒倾。
寸心久摧折，别离重骨惊。
安得凌风翰，肃肃宾天京。','',''),('quantangshi-13723','酬房杭州','顧況','quantangshi','','卷14','郡楼何其旷，亭亭广而深。
故人牧余杭，留我披胸衿。
满箧阅新作，璧玉诞清音。
流水入洞天，窅豁欲淩临。
辟险延北阜，剃道陟南岑。
朝从山寺还，醒醉动笑吟。
荷花十余里，月色攒湖林。
父老惜使君，却欲速华簪。','',''),('quantangshi-13724','酬漳州张九使君','顧況','quantangshi','','卷14','故人穷越徼，狂生起悲愁。
山海万里别，草木十年秋。
鞭马广陵桥，出祖张漳州。
促膝堕簪珥，辟幌戛琳球。
短题自兹简，华篇讵能酬。
无阶承明庭，高步相追游。
南方荣桂枝，淩冬舍温裘。
猿唫郡斋中，龙静檀栾流。
薜鹿莫徭洞，网鱼卢亭洲。
心安处处安，处处思遐陬。','',''),('quantangshi-13725','在滁苦雨归桃花崦伤亲友略尽','顧況','quantangshi','','卷14','废弃忝残生，后来亦先夭。
诗人感风雨，长夜何时晓。
去国宦情无，近乡归梦少。
庇身绝中授，甘静忘外扰。
丽景变重阴，洞山空木表。
灵潮若可通，寄谢西飞鸟。','',''),('quantangshi-13726','苦雨','顧況','quantangshi','','卷14','朝与佳人期，碧树生红蕚。
暮与佳人期，飞雨洒清阁。
佳人窅何许，中夜心寂寞。
试忆花正开，复惊叶初落。
行骑飞泉鹿，卧听双海鹤。
嘉愿有所从，安得处其薄。','',''),('quantangshi-13727','赠别崔十三长官','顧況','quantangshi','','卷14','真玉烧不热，宝剑拗不折。
欲别崔侠心，崔侠心如铁。
复如金刚锁，无有功不彻。
仍于直道中，行事不诋讦。
崔侠两兄弟，垂范继芳烈。
相识三十年，致书字不灭。
我来宣城郡，饮水仰清洁。
蔼蔼北阜松，峩峩南山雪。
顾生归山去，知作几年别。','',''),('quantangshi-13728','哭从兄苌','顧況','quantangshi','','卷14','洞庭违鄂渚，袅袅秋风时。
何人不客游，独与帝子期。
黄鹄铩飞翅，青云叹沈姿。
身终一骑曹，高盖者为谁。
从驾至梁汉，金根复京师。
皇恩溢九垠，不记屠沽儿。
立身有高节，满卷多好诗。
赫赫承明庭，羣公默无词。
草木正摇落，哭兄鄱水湄。
共居云阳里，轗轲多别离。
人生倏忽间，旅衬飘若遗。
稚子新学拜，枯杨生一枝。
人生倏忽间，精爽无不之。
旧国数千里，家人由未知。
人生倏忽间，安用才士为。','',''),('quantangshi-13729','华山西冈游赠隐玄叟','顧況','quantangshi','','卷14','羣峰郁初霁，泼黛若鬟沐。
失风鼓唅呀，摇撼千灌木。
木叶微堕黄，石泉净停绿。
危磴萝薜牵，逈步入幽谷。
我心寄青霞，世事惭苍鹿。
遂令巢许辈，于焉谢尘俗。
想是悠悠云，可契去留躅。','',''),('quantangshi-13730','归阳萧寺有丁行者能修无生忍担水施僧况归命稽首作诗','顧況','quantangshi','','卷14','化佛示持帚，仲尼称执鞭。
列生御风归，饲豕如人焉。
曹溪第六祖，踏碓逾三年。
伊人自何方，长绶趋遥泉。
开士行何苦，双瓶胝两肩。
萧寺百余僧，东厨正扬烟。
露足沙石裂，外形巾褐穿。
若其有此身，岂得安稳眠。
独出违顺境，不为寒暑还。
大圣于其中，领我心之虔。
万法常空灭，无生因忍全。
一国一释迦，一灯分百千。
永愿遗世知，现身弥勒前。
潜容偏虚空，灵响不可传。
智慧舍利佛，神通自干连。
阿若楚系简帛陈如，迦叶迦旜延。
左右二菩萨，文殊并普贤。
身披六铢衣，亿刦为大仙。
宝塔宝楼阁，重檐交梵天。
譬如一明珠，共赞光白圆。
天魔波[旬]等，降伏金刚坚。
野叉罗刹鬼，亦赦尘垢缠。
乃致金翅鸟，吞龙护洪渊。
一十一众中，身意皆快然。
八河注大海，中有楞伽船。
佛法付国王，平等无颇偏。
天子事端拱，大臣行其权。
玉堂无蝇飞，五月冰凛筵。
尽力答明主，犹自招罪愆。
九族无白身，百花动婵娟。
神圣恶如此，物华不能妍。
禄山一微胡，驱马来自燕。
宛彼宫阙丽，如何犬羊膻。
苦哉千万人，流血成丹川。
此辈之死后，镬汤所熬煎。
业风吹其魂，猛火烧其烟。
独有丁行者，无忧树枝边。
市头盲老人，长者乞一钱。
韬照多密用，为君吟此篇。','',''),('quantangshi-13731','大茅岭东新居忆亡子从真','顧況','quantangshi','','卷14','谷鸟犹呼儿，山人夕霑襟。
怀哉隔生死，怅矣徒登临。
东门忧不入，西河遇亦深。
古来失中道，偶向经中寻。
大象无停轮，倏忽成古今。
其夭非不幸，炼形由太阴。
凡欲攀云阶，譬如火铸金。
虚室留旧札，洞房掩闲琴。
泉源登方诸，上有空青林。
彷佛通寤寐，萧寥邈微音。
软草被汀洲，鲜云略浮沈。
赬景宣叠丽，绀波响飘淋。
石窟含云巢，迢迢耿南岑。
悲恨自兹断，情尘讵能侵。
真静一时变，作起唯从心。','',''),('quantangshi-13732','乌啼曲二首 一','顧況','quantangshi','','卷14','玉房掣锁声翻叶，银箭添泉遶霜堞。
毕逋拨刺月衔城，八九雏飞其母惊。
此是天上老鵶鸣，人间老鵶无此声。
摇风杂佩耿华烛，夜听羽人弹此曲。
东方曈曈赤日旭。','',''),('quantangshi-13733','乌啼曲二首 二','顧況','quantangshi','','卷14','月出江林西，江林寂寂城鵶啼。
昔人何处为此曲，今人何处听不足。
城寒月晓驰思深，江上青草为谁绿。','',''),('quantangshi-13734','幽居弄','顧況','quantangshi','','卷14','苔衣生，花露滴，月入西林荡东壁。
扣商占角两三声，洞户溪窗一冥寂。
独去沧洲无四邻，身婴世网此何身。
关情命曲寄惆怅，久别山南山里人。','',''),('quantangshi-13735','公子行','顧況','quantangshi','','卷14','轻薄儿，面如玉，紫陌春风缠马足。
双𩍐悬金缕鹘飞，长衫刺雪生犀束。
绿槐夹道阴初成，珊瑚几节敌流星。
红肌拂拂酒光狞，当街背拉金吾行。
朝游冬冬鼓声发，暮游冬冬鼓声绝。
入门不肯自升堂，美人扶踏金阶月。','',''),('quantangshi-13736','古离别','顧況','quantangshi','','卷14','西江上，风动麻姑嫁时浪。
西山为水水为尘，不是人间离别人。','',''),('quantangshi-13737','长安道','顧況','quantangshi','','卷14','长安道，人无衣，马无草，何不归来山中老。','',''),('quantangshi-13738','龙宫操','顧況','quantangshi','','卷14','龙宫月明光参差，精卫衔石东飞时。
鲛人织绡采藕丝，翻江倒海倾吴蜀。
汉女江妃杳相续，龙王宫中水不足。','',''),('quantangshi-13739','梁广画花歌','顧況','quantangshi','','卷14','王母欲过刘彻家，飞琼夜入云軿车。
紫书分付与青鸟，却向人间求好花。
上元夫人最小女，头面端正能言语。
手把梁生画花看，凝嚬掩笑心相许。
心相许，为白阿娘从嫁与。','',''),('quantangshi-13740','送别日晚歌','顧況','quantangshi','','卷14','日窅窅兮下山，望佳人兮不还。
花落兮屋上，草生兮堦间。
日日兮春风，芳菲兮欲歇。
老不可兮更少，君何为兮轻别。','',''),('quantangshi-13741','行路难三首 一','顧況','quantangshi','','卷14','君不见担雪塞井空用力，炊砂作饭岂堪食。
一生肝胆向人尽，相识不如不相识。
冬青树上挂凌霄，岁晏花凋树不凋。
凡物各自有根本，种禾终不生豆苗。
行路难，行路难，何处是平道。
中心无事当富贵，今日看君颜色好。','',''),('quantangshi-13742','行路难三首 二','顧況','quantangshi','','卷14','君不见少年头上如云发，少壮如云老如雪。
岂知灌顶有醍醐，能使清凉头不热。
吕梁之水挂飞流，鼋鼍蛟蜃不敢游。
少年恃险若平地，独倚长剑凌清秋。
行路难，行路难，昔少年，今已老。
前朝竹帛事皆空，日暮牛羊占城草。','',''),('quantangshi-13743','行路难三首 三','顧況','quantangshi','','卷14','君不见古人烧水银，变作北邙山上尘。
藕丝挂在虚空中，欲落不落愁杀人。
睢水英雄多血刃，建章宫阙成煨烬。
淮王身死桂树折，徐福一去音书绝。
行路难，行路难，生死皆由天。
秦皇汉武遭不脱，汝独何人学神仙。','',''),('quantangshi-13744','悲歌 一','顧況','quantangshi','','卷14','边城路，今人犂田昔人墓。
岸上沙，昔日江水今人家。
今人昔人共长叹，四气相催节廻换。
明月皎皎入华池，白云离离渡霄汉。','',''),('quantangshi-13745','悲歌 二','顧況','quantangshi','','卷14','我欲升天天隔霄，我欲渡水水无桥。
我欲上山山路险，我欲汲井井泉遥。
越人翠被今何夕，独立沙边江草碧。
紫燕西飞欲寄书，白云何处逢来客。','',''),('quantangshi-13746','悲歌 三','顧況','quantangshi','','卷14','新系青丝百尺绳，心在君家辘轳上。
我心皎洁君不知，辘轳一转一惆怅。','',''),('quantangshi-13747','悲歌 四','顧況','quantangshi','','卷14','何处春风吹晓幕，江南渌水通朱阁。
美人二八面如花，泣向春风畏花落。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-13748','悲歌 五','顧況','quantangshi','','卷14','临春风，听春鸟，别时多，见时少。
愁人夜永不得眠，瑶井玉绳相对晓。','',''),('quantangshi-13749','悲歌 六','顧況','quantangshi','','卷14','轩辕黄帝初得仙，鼎湖一去三千年。
周流三十六洞天，洞中日月星辰联。
骑龙驾景游八极，轩辕弓剑无人识，东海青童寄消息。','',''),('quantangshi-13750','春草谣','顧況','quantangshi','','卷14','春草不解行，随人上东城。
正月二月色绵绵，千里万里伤人情。','',''),('quantangshi-13751','苔藓山歌','顧況','quantangshi','','卷14','野人夜梦江南山，江南山深松桂闲。
野人觉后长叹息，帖藓黏苔作山色。
闭门无事任盈虚，终日欹眠观四如。
一如白云飞出壁，二如飞雨岩前滴。
三如腾虎欲咆哮，四如嬾龙遭霹雳。
嶮峭嵌空潭洞寒，小儿两手扶栏干。','',''),('quantangshi-13752','同裴观察东湖望山歌','顧況','quantangshi','','卷14','浴鲜积翠栖灵异，石洞花宫横半空。
夜光潭上明星启，风雨坛边树如洗。
水淹徐孺宅恒干，绳坠洪崖井无底。
主人载酒东湖阴，遥望西山三四岑。','',''),('quantangshi-13753','八月五日歌','顧況','quantangshi','','卷14','四月八日明星出，摩耶夫人降前佛。
八月五日佳气新，昭成太后生圣人。
开元九年燕公说，奉诏听置千秋节。
丹青庙里贮姚宋，花蕚楼中宴岐薛。
清乐灵香几处闻，鸾歌凤吹动祥云。
已于武库见灵鸟，仍向晋山逢老君。
率土普天无不乐，河清海晏穷寥廓。
梨园第子传法曲，张果先生进仙药。
玉座凄凉游帝京，悲翁回首望承明。
云韶九奏杳然远，唯有五陵松柏声。','',''),('quantangshi-13754','露青竹杖歌','顧況','quantangshi','','卷14','鲜于仲通正当年，章仇兼琼在蜀川。
约束蜀儿采马鞭，蜀儿采鞭不敢眠。
横截斜飞飞鸟边，绳桥夜上层崖颠。
头插白云跨飞泉，采得马鞭长且坚。
浮沤丁子珠联联，灰煮蜡楷光烂然。
章仇兼琼持上天，上天雨露何其偏。
飞龙闲厩马数千，朝饮吴江夕秣燕。
红尘扑辔汗湿鞯，师子麒麟聊比肩。
江面昆明洗刷牵，四蹄踏浪头枿天。
蛟龙稽颡河伯虔，拓羯胡雏脚手鲜。
陈闳韩干丹青妍，欲貌未貌眼欲穿。
金鞍玉勒锦连干，骑入桃花杨柳烟。
十二楼中奏管弦，楼中美人夺神仙。
争爱大家把此鞭，禄山入关关破年。
忽见扬州北邙前，秪有人还千一钱。
亭亭笔直无皴节，磨捋形相一条铁。
市头格是无人别，江海贱臣不拘絏。
垂窗挂影西窗缺，稚子觅衣挑仰穴。
家童拾薪几拗折，玉润犹沾玉垒雪。
碧鲜似染苌弘血，蜀帝城边子规咽。
相如桥上文君绝，往年策马降至尊。
七盘九折横剑门，穆王八骏超昆仑。
安用冉冉孤生根，圣人不贵难得货，金玉珊珊谁买恩。','',''),('quantangshi-13755','金璫玉佩歌','顧況','quantangshi','','卷14','赠君金璫太霄之玉佩，金锁禹步之流珠。
五岳真君之秘箓，九天丈人之宝书。
东井沐浴辰已毕，先进洞房上奔日。
借问君欲何处来，黄姑织女机边出。','',''),('quantangshi-13756','瑶草春','顧況','quantangshi','','卷14','瑶草春，杳容与，江南艳歌京西舞。
执心轻子都，信节冠秋胡。
议以腰支嫁，时论自有夫。
蝉鬓蛾眉明井底，燕裙赵袂萦辘轳。
李生闻之泪如绠，不忍回头看此井。
月中桂树落一枝，池上䴔䴖唳孤影。
露桃穠李自成溪，流水终天不向西。
翠帐绿窗寒寂寂，锦茵罗荐夜凄凄。
瑶草春，丹井远，别后相思意深浅。','',''),('quantangshi-13757','萧郸草书歌','顧況','quantangshi','','卷14','萧子草书人不及，洞庭叶落秋风急。
上林花开春露湿，花枝蒙蒙向水垂。
见君数行之洒落，石上之松松下鹤。
若把君书比仲将，不知谁在凌云阁。','',''),('quantangshi-13758','范山人画山水歌','顧況','quantangshi','','卷14','山峥嵘，水泓澄。
漫漫汗汗一笔耕，一草一木栖神明。
忽如空中有物，物中有声。
复如远道望乡客，梦遶山川身不行。','',''),('quantangshi-13759','嵇山道芬上人画山水歌','顧況','quantangshi','','卷14','镜中真僧白道芬，不服朱审李将军。
渌汗平铺洞庭水，笔头点出苍梧云。
且看八月十五夜，月下看山尽如画。','',''),('quantangshi-13760','杜秀才画立走水牛歌','顧況','quantangshi','','卷14','昆仑儿，骑白象，时时锁着师子项。
奚奴跨马不搭鞍，立走水牛惊汉官。
江村小儿好夸骋，脚踏牛头上牛领。
浅草平田攃过时，大虫着钝几落井。
杜生知我恋沧州，画作一障张牀头。
八十老婆拍手笑，妬他织女嫁牵牛。','',''),('quantangshi-13761','梁司马画马歌','顧況','quantangshi','','卷14','画精神，画筋骨，一团旋风瞥灭没。
仰秣如上贺兰山，低头欲饮长城窟。
此马昂然独此羣，阿爷是龙飞入云。
黄沙枯碛无寸草，一日行过千里道。
展处把笔欲描时，司马一騧赛倾倒。','',''),('quantangshi-13762','丘小府小鼓歌','顧況','quantangshi','','卷14','地盘山鷄犹可像，坎坎砰砰随手长。
夜半高楼沈醉时，万里踏桥乱山响。','',''),('quantangshi-13763','宜城放琴客歌','顧況','quantangshi','','卷14','佳人玉立生此方，家住邯郸不是倡。
头髻䰀鬌手爪长，善抚琴瑟有文章。
新妍笼裙云母光，朱弦绿水喧洞房。
忽闻斗酒初决绝，日暮浮云古离别。
巴猿啾啾峡泉咽，泪落罗衣颜色暍。
不知谁家更张设，丝履墙偏钗股折。
南山阑干千丈雪，七十非人不暖热。
人情厌薄古共然，相公心在持事坚。
上善若水任方圆，忆昨好之今弃捐。
服药不如独自眠，从他更嫁一少年。','',''),('quantangshi-13764','李供奉弹箜篌歌','顧況','quantangshi','','卷14','国府乐手弹箜篌，赤黄条索金鎝头。
早晨有敕鸳鸯殿，夜静遂歌明月楼。
起坐可怜能抱撮，大指调弦中指拨。
腕头花落舞制裂，手下鸟惊飞拨剌。
珊瑚席，一声一声鸣锡锡。
罗绮屏，一弦一弦如撼铃。
急弹好，迟亦好，宜远听，宜近听。
左手低，右手举，易调移音天赐与。
大弦似秋雁，联联度陇关。
小弦似春燕，喃喃向人语。
手头疾，腕头软，来来去去如风卷。
声清泠泠鸣索索，垂珠碎玉空中落。
美女争窥玳瑁帘，圣人卷上真珠箔。
大弦长，小弦短，小弦紧快大弦缓。
初调锵锵似鸳鸯水上弄新声，入深似太清仙鹤游秘馆。
李供奉，仪容质，身才稍稍六尺一。
在外不曾輙敎人，内里声声不遣出。
指剥葱，腕削玉，饶盐饶酱五味足。
弄调人间不识名，弹尽天下崛奇曲。
胡曲汉曲声皆好，弹着曲髓曲肝脑。
往往从空入户来，瞥瞥随风落春草。
草头只觉风吹入，风来草即随风立。
草亦不知风到来，风亦不知声缓急。
爇玉烛，点银灯，光照手，实可憎。
只照箜篌弦上手，不照箜篌声里能。
驰凤阙，拜鸾殿，天子一日一回见。
王侯将相立马迎，巧声一日一回变。
实可重，不惜千金买一弄。
银器胡瓶马上驮，瑞锦轻罗满车送。
此州好手非一国，一国东西尽南北。
除却天上化下来，若向人间实难得。','',''),('quantangshi-13765','刘禅奴弹琵琶歌','顧況','quantangshi','','卷14','乐府只传横吹好，琵琶写出关山道。
羁雁出塞绕黄云，边马仰天嘶白草。
明妃愁中汉使回，蔡琰愁处胡笳哀。
鬼神知妙欲收响，阴风切切四面来。
李陵寄书别苏武，自有生人无此苦。
当时若值霍骠姚，灭尽乌孙夺公主。','',''),('quantangshi-13766','李湖州孺人弹筝歌','顧況','quantangshi','','卷14','武帝升天留法曲，凄清掩仰弦柱促。
上阳宫人怨青苔，此夜想夫怜碧玉。
思妇高楼刺壁窥，愁猿呌月鹦呼儿。
寸心十指有长短，妙入神处无人知。
独把梁州凡几拍，风沙对面胡秦隔。
听中忘却前溪碧，醉后犹疑边草白。','',''),('quantangshi-13767','郑女弹筝歌','顧況','quantangshi','','卷14','郑女八岁能弹筝，春风吹落天上声。
一声雍门泪承睫，两声赤鲤露鬐鬣。
二声白猿臂拓颊，郑女出参丈人时。
落花惹断游空丝，高楼不掩许声出，羞杀百舌黄莺儿。','',''),('quantangshi-13768','谅公洞庭孤橘歌','顧況','quantangshi','','卷14','不种自生一株橘，谁敎渠向堦前出。
不羡江陵千木奴，下生白蚁子，上生青雀雏。
飞花檐卜旃檀香，结实如缀摩尼珠。
洞庭橘树笼烟碧，洞庭波月连沙白。
待取天公放恩赦，侬家定作湖中客。','',''),('quantangshi-13769','送行歌','顧況','quantangshi','','卷14','送行人，歌一曲，何者为泥何者玉？年华已向秋草里，春梦犹传故山绿。','',''),('quantangshi-13770','险竿歌','顧況','quantangshi','','卷14','宛陵女儿擘飞手，长竿横空上下走。
已能轻险若平地，岂肯身为一家妇。
宛陵将士天下雄，一下定却长稍弓。
翻身挂影恣腾蹋，反绾头髻盘旋风。
盘旋风，撇飞鸟，惊猿遶，树枝褭。
头上打鼓不闻时，手蹉脚跌蜘蛛丝。
忽雷掣断流星尾，矐睒划破蚩尤旗。
若不随仙作仙女，即应嫁贼生贼儿。
中丞方略通变化，外户不扃从女嫁。','',''),('quantangshi-13771','洛阳行送洛阳韦七明府','顧況','quantangshi','','卷14','始上龙门望洛川，洛阳桃李艳阳天。
最好当年二三月，上阳宫树千花发。
疏家父子错挂冠，梁鸿夫妻虚适越。','',''),('quantangshi-13772','黄鹄楼歌送独孤助','顧況','quantangshi','','卷14','故人西去黄鹄楼，西江之水上天流，黄鹄杳杳江悠悠。
黄鹄徘徊故人别，离壶酒尽清丝绝。
绿屿没余烟，白沙连晓月。','',''),('quantangshi-13773','庐山瀑布歌送李顾','顧況','quantangshi','','卷14','飘白霓，挂丹梯。
应从织女机边落，不遣浔阳湖向西。
火雷劈山珠喷日，五老峰前九江溢。
九江悠悠万古情，古人行尽今人行。
老人也欲上山去，上个深山无姓名。','',''),('quantangshi-13774','朝上清歌','顧況','quantangshi','','卷14','洁眼朝上清，绿景开紫霞。
皇皇紫微君，左右皆灵娥。
曼声流睇，和清歌些。
至阳无谖，其乐多些。
旌盖飒沓，箫鼓和些。
金凤玉麟，郁骈罗些。
反风名香，香气遐些。
琼田瑶草，寿无涯些。
君着玉衣，升玉车些。
欲降琼宫，玉女家些。
其桃千年，始着花些。
萧寥天清而灭云，目琼琼兮情感。
佩随香兮夜闻，肃肃兮愔愔。
启天和兮洞灵心，和为丹兮云为马。
君乘之觞于瑶池之上兮，三光罗列而在下。','',''),('quantangshi-13775','剡纸歌','顧況','quantangshi','','卷14','云门路上山阴雪，中有玉人持玉节。
宛委山里禹余粮，石中黄子黄金屑。
剡溪剡纸生剡藤，喷水捣后为蕉叶。
欲写金人金口经，寄与山阴山里僧。
手把山中紫罗笔，思量点画龙蛇出。
政是垂头蹋翼时，不免向君求此物。','',''),('quantangshi-13776','洛阳早春','顧況','quantangshi','','卷14','何地避春愁，终年忆旧游。
一家千里外，百舌五更头。
客路偏逢雨，乡山不入楼。
故园桃李月，伊水向东流。','',''),('quantangshi-13777','步虚词','顧況','quantangshi','','卷14','逈步游三洞，清心礼七真。
飞符超羽翼，焚火醮星辰。
残药沾鸡犬，灵香出凤麟。
壶中无窄处，愿得一容身。','',''),('quantangshi-13778','鄱阳大云寺一公房','顧況','quantangshi','','卷14','尽日陪游处，斜阳竹院清。
定中观有漏，言外证无生。
色界聊传法，空门不用情。
欲知相去近，钟鼓两闻声。','',''),('quantangshi-13779','送友失意南归','顧況','quantangshi','','卷14','衣挥京洛尘，完璞伴归人。
故国青山徧，沧江白发新。
邻荒收酒幔，屋古布苔茵。
不用通名姓，渔樵共主宾。','',''),('quantangshi-13780','南归','顧況','quantangshi','','卷14','老病力难任，犹多镜雪侵。
鲈鱼消宦况，鸥鸟识归心。
急雨江帆重，残更驿树深。
乡关殊可望，渐渐入吴音。','',''),('quantangshi-13781','闲居自述','顧況','quantangshi','','卷14','荣辱不关身，谁为疎与亲。
有山堪结屋，无地可容尘。
白发偏添寿，黄花不笑贫。
一樽朝暮醉，陶令果何人。','',''),('quantangshi-13782','题歙山栖霞寺','顧況','quantangshi','','卷14','明征君旧宅，陈后主题诗。
迹在人亡处，山空月满时。
宝瓶无破响，道树有低枝。
已是伤离客，仍逢靳尚祠。','',''),('quantangshi-13783','经废寺','顧況','quantangshi','','卷14','不知何世界，有处似南朝。
石路无人扫，松门被火烧。
断幡犹挂刹，故板尚搘桥。
数卷残经在，多年字欲销。','',''),('quantangshi-13784','送李道士','顧況','quantangshi','','卷14','人境年虚掷，仙源日未斜。
羡君乘竹杖，辞我隐桃花。
鸟去宁知路，云飞似忆家。
莫愁客鬓改，自有紫河车。','',''),('quantangshi-13785','酬唐起居前后见寄二首 一','顧況','quantangshi','','卷14','愁人空望国，惊鸟不归林。
莫话弹冠事，谁知结袜心。
霜凋树吹断，土蚀剑痕深。
欲作怀沙赋，明时耻自沈。','',''),('quantangshi-13786','酬唐起居前后见寄二首 二','顧況','quantangshi','','卷14','何处吊灵均，江边一老人。
汉仪君已接，楚奏我空频。
直道其如命，平生不负神。
自伤庚子日，[鵩]鸟上承尘。','',''),('quantangshi-13787','奉酬茅山赠赐并简綦毋正字','顧況','quantangshi','','卷14','玉帝居金阙，灵山几处朝。
简书犹有畏，神理讵能超。
鹤庙新家近，龙门旧国遥。
离怀结不断，玉洞一吹箫。','',''),('quantangshi-13788','白苹洲送客','顧況','quantangshi','','卷14','莫信梅花发，由来谩报春。
不才充野客，扶病送朝臣。
阙下摇青佩，洲边采白苹。
临流不痛饮，鸥鸟也欺人。','',''),('quantangshi-13789','春鸟词送元秀才入京','顧況','quantangshi','','卷14','春来绣羽齐，暮向竹林栖。
禁苑衔花出，河桥隔树啼。
寻声知去远，顾影念飞低。
别有无巢燕，犹窥幕上泥。','',''),('quantangshi-13790','别江南','顧況','quantangshi','','卷14','江城吹晓角，愁杀远行人。
汉将犹防虏，吴官欲向秦。
布帆轻白浪，锦带入红尘。
将底求名宦，平生但任真。','',''),('quantangshi-13791','空梁落燕泥','顧況','quantangshi','','卷14','卷幕参差燕，常衔浊水泥。
为黏珠履迹，未等画梁齐。
旧点痕犹浅，新巢缉尚低。
不缘频上落，那得此飞栖。','',''),('quantangshi-13792','上元夜忆长安','顧況','quantangshi','','卷14','沧州老一年，老去忆秦川。
处处逢珠翠，家家听管弦。
云车龙阙下，火树凤楼前。
今夜沧州夜，沧州夜月圆。','',''),('quantangshi-13793','酬扬州白塔寺永上人','顧況','quantangshi','','卷14','塔上是何缘，香灯续细烟。
松枝当麈尾，柳絮替蚕绵。
浮草经行徧，空花义趣圆。
我来虽为法，暂借一牀眠。','',''),('quantangshi-13794','送韦秀才赴举','顧況','quantangshi','','卷14','鄱阳中酒地，楚老独醒年。
芳桂君应折，沈灰我不然。
洛桥浮逆水，关树接非烟。
唯有残生梦，犹能到日边。','',''),('quantangshi-13795','送使君','顧況','quantangshi','','卷14','天中洛阳道，海上使君归。
拂雾趋金殿，焚香入璅闱。
山亭倾别酒，野服间朝衣。
他日思朱鹭，知从小苑飞。','',''),('quantangshi-13796','历阳苦雨','顧況','quantangshi','','卷14','襄城秋雨晦，楚客不归心。
亥市风烟接，隋宫草路深。
离忧翻独笑，用事感浮阴。
夜夜空堦响，唯余蚯蚓吟。','',''),('quantangshi-13797','伤大理谢少卿','顧況','quantangshi','','卷14','旧馆绝逢迎，新诗何处呈。
空留封禅草，已作岱宗行。
柳蠹风吹析，堦崩雪遶平。
无因重来此，剩哭两三声。','',''),('quantangshi-13798','经徐侍郎墓作','顧況','quantangshi','','卷14','不知山吏部，墓作石桥东。
宅兆乡关异，平生翰墨空。
夜泉无晓日，枯树足悲风。
更想幽冥事，唯应有梦同。','',''),('quantangshi-13799','酅公合祔挽歌','顧況','quantangshi','','卷14','草露前朝事，荆茅圣主封。
空传余竹帛，永绝旧歌钟。
清镜无双影，穷泉有几重。
笳箫最悲处，风入九原松。','',''),('quantangshi-13800','相国晋公挽歌二首 一','顧況','quantangshi','','卷14','玉节朝天罢，洪炉造化新。
中和方作圣，太素忽收神。
盛德横千古，高标出四邻。
欲知言不尽，处处有遗尘。','',''),('quantangshi-13801','相国晋公挽歌二首 二','顧況','quantangshi','','卷14','凝笳催晓奠，丹旐向青山。
夕照新茔近，秋风故吏还。
本朝光汉代，从此扫胡关。
今日天难问，浮云满世间。','',''),('quantangshi-13802','晋公魏国夫人柳氏挽歌','顧況','quantangshi','','卷14','鱼轩海上遥，鸾影月中销。
双剑来时合，孤桐去日凋。
夕阳迷陇隧，秋雨咽笳箫。
画翣无留影，铭旌已度桥。','',''),('quantangshi-13803','义川公主挽词','顧況','quantangshi','','卷14','弄玉吹箫后，湘灵鼓瑟时。
月边丹桂落，风底白杨悲。
杂佩分泉户，余香出繐帷。
夜台飞镜匣，偏共掩蛾眉。','',''),('quantangshi-13804','忆山中','顧況','quantangshi','','卷14','春还不得还，家在最深山。
蕙圃泉浇湿，松窗月映闲。
薄田临谷口，小职向人间。
去处但无事，重门深闭关。','',''),('quantangshi-13805','送大理张卿','顧況','quantangshi','','卷14','春色依依惜解携，月卿今夜泊隋堤。
白沙洲上江篱长，绿树村边谢豹啼。
迁客比来无倚仗，故人相去隔云泥。
越禽唯有南枝分，目送孤鸿飞向西。','',''),('quantangshi-13806','宿湖边山寺','顧況','quantangshi','','卷14','羣峰过雨涧淙淙，松下扉扃白鹤双。
香透经窗笼桧栢，云生梵宇湿幡幢。
蒲团僧定风过席，苇岸渔歌月堕江。
谁悟此生同寂灭，老禅慧力得心降。','',''),('quantangshi-13807','湖南客中春望','顧況','quantangshi','','卷14','鸣雁嘹嘹北向频，渌波何处是通津。
风尘海内怜双鬓，涕泪天涯惨一身。
故里音书应望绝，异乡景物又更新。
便抛印绶从归隐，吴渚香莼漫吐春。','',''),('quantangshi-13808','闲居怀旧','顧況','quantangshi','','卷14','日长鼓腹爱吾庐，洗竹浇花兴有余。
骚客空传成相赋，晋人已负绝交书。
贫居谪所谁推毂，仕向侯门耻曳裾。
今日思来总皆罔，汗青功业又何如。','',''),('quantangshi-13809','寄江南鹤林寺石冰上人','顧況','quantangshi','','卷14','山川重复出，心地暗相逢。
忽忆秋江月，如闻古寺钟。
湖平南北岸，云抱两三峰。
定力超香象，真言摄毒龙。
风中何处鹤，石上几年松。
为报烟霞道，人间共不容。','',''),('quantangshi-13810','乐府','顧況','quantangshi','','卷14','暖谷春光至，宸游近甸荣。
云随天仗转，风入御帘轻。
翠盖浮佳气，朱楼倚太清。
朝臣冠剑退，宫女管弦迎。
细草承雕辇，繁花入幔城。
文房开圣藻，武卫宿天营。
玉醴随觞至，铜壶逐漏行。
五星含土德，万姓彻中声。
亲祀先崇典，躬推示劝耕。
国风新正乐，农器近消兵。
道德关河固，刑章日月明。
野人同鸟兽，率舞感升平。','',''),('quantangshi-13811','送从兄使新罗','顧況','quantangshi','','卷14','六气铜浑转，三光玉律调。
河宫清奉賮，海岳晏来朝。
地绝提封入，天平赐贡饶。
扬威轻破虏，柔服耻征辽。
曙色黄金阙，寒声白鹭潮。
楼船非习战，骢马是嘉招。
帝女飞衔石，鲛人卖泪绡。
管宁虽不偶，徐市傥相邀。
独岛缘空翠，孤霞上泬寥。
蟾蜍同汉月，螮蝀异秦桥。
水豹横吹浪，花鹰逈拂霄。
晨装凌莽渺，夜泊记招摇。
几路通员峤，何山是沃焦。
飓风晴汨起，阴火暝潜烧。
鬓发成新髻，人参长旧苗。
扶桑衔日近，析木带津遥。
梦向愁中积，魂当别处销。
临川思结网，见弹欲求鸮。
共散羲和历，谁差甲子朝。
沧波伏忠信，译语辨讴谣。
叠鼓鲸鳞隐，阴帆鷁首飘。
南溟垂大翼，西海饮文鳐。
指景寻灵草，排云听洞箫。
封侯万里外，未肯后班超。','',''),('quantangshi-13812','山居即事','顧況','quantangshi','','卷14','下泊降茅仙，萧闲隐洞天。
杨君闲上法，司命驻流年。
崦合桃花水，窗分柳谷烟。
抱孙堪种树，倚杖问耘田。
世事休相扰，浮名任一边。
由来谢安石，不解饮灵泉。','',''),('quantangshi-13813','题卢道土房','顧況','quantangshi','','卷14','秋砧响落木，共坐茅君家。
唯见两童子，门外汲井花。
空坛静白日，神鼎飞丹砂。
麈尾拂霜草，金铃摇霁霞。
上章尘世隔，看弈桐阴斜。
稽首问仙要，黄精堪饵花。','',''),('quantangshi-13814','梦后吟','顧況','quantangshi','','卷14','醉中还有梦，身外已无心。
明镜唯知老，青山何处深。','',''),('quantangshi-13815','题灵山寺','顧況','quantangshi','','卷14','觉地本随身，灵山重结因。
如何战鸟佛，不化捕鱼人。','',''),('quantangshi-13816','题元阳观旧读书房赠李范','顧況','quantangshi','','卷14','此观十年游，此房千里宿。
还来旧窗下，更取君书读。','',''),('quantangshi-13817','永嘉','顧況','quantangshi','','卷14','东瓯传旧俗，风日江边好。
何处乐神声，夷歌出烟岛。','',''),('quantangshi-13818','青弋江','顧況','quantangshi','','卷14','凄清回泊夜，沦波激石响。
