内官先向蓬莱殿，金合开香泻御炉。','',''),('quantangshi-13875','宫词五首 二','顧況','quantangshi','','卷14','玉楼天半起笙歌，风送宫嫔笑语和。
月殿影开闻夜漏，水精帘卷近银河。','',''),('quantangshi-13876','宫词五首 三','顧況','quantangshi','','卷14','玉阶容卫宿千官，风猎青旗晓仗寒。
侍女先来荐琼蘂，露浆新下九霄盘。','',''),('quantangshi-13877','宫词五首 四','顧況','quantangshi','','卷14','九重天乐降神仙，步舞分行踏锦筵。
嘈囋一声钟鼓歇，万人楼下拾金钱。','',''),('quantangshi-13878','宫词五首 五','顧況','quantangshi','','卷14','金吾持戟护新檐，天乐声传万姓瞻。
楼上美人相倚看，红妆透出水精帘。','',''),('quantangshi-13879','寻桃花岭潘三姑台','顧況','quantangshi','','卷14','桃花岭上觉天低，人上青山马隔溪。
行到三姑学仙处，还有刘阮二郎迷。','',''),('quantangshi-13880','夜中望仙观','顧況','quantangshi','','卷14','日暮衔花飞鸟还，月明溪上见青山。
遥知玉女窗前树，不是仙人不得攀。','',''),('quantangshi-13881','送李侍御往吴兴','顧況','quantangshi','','卷14','世间只有情难说，今夜应无不醉人。
若向洞庭山下过，暗知浇沥圣姑神。','',''),('quantangshi-13882','奉和韩晋公晦日呈诸判官','顧況','quantangshi','','卷14','江南无处不闻歌，晦日中军乐更多。
不是风光催柳色，却缘威令动阳和。','',''),('quantangshi-13883','子规','顧況','quantangshi','','卷14','杜宇冤亡积有时，年年啼血动人悲。
若敎恨魄皆能化，何树何山着子规。','',''),('quantangshi-13884','海鸥咏','顧況','quantangshi','','卷14','万里飞来为客鸟，曾蒙丹凤借枝柯。
一朝凤去梧桐死，满目鸱鸢奈尔何。','',''),('quantangshi-13885','赠韦清将军','顧況','quantangshi','','卷14','身执金吾主禁兵，腰间宝剑重横行。
接舆亦是狂歌者，更就将军乞一声。','',''),('quantangshi-13886','赠僧二首 一','顧況','quantangshi','','卷14','家住义兴东舍溪，溪边莎草雨无泥。
上人一向心入定，春鸟年年空自啼。','',''),('quantangshi-13887','赠僧二首 二','顧況','quantangshi','','卷14','出头皆是新年少，何处能容老病翁。
更把浮荣喻生灭，世间无事不虚空。','',''),('quantangshi-13888','登楼望水','顧況','quantangshi','','卷14','鸟啼花发柳含烟，掷却风光忆少年。
更上高楼望江水，故乡何处一归船。','',''),('quantangshi-13889','湖中','顧況','quantangshi','','卷14','青草湖边日色低，黄茅嶂里鹧鸪啼。
丈夫飘荡今如此，一曲长歌楚水西。','',''),('quantangshi-13890','岁日作','顧況','quantangshi','','卷14','不觉老将春共至，更悲携手几人全。
还丹寂寞羞明镜，手把屠苏让少年。','',''),('quantangshi-13891','山中赠客','顧況','quantangshi','','卷14','山中好处无人别，涧梅伪作山中雪。
野客相逢夜不眠，山中童子烧松节。','',''),('quantangshi-13892','王郎中妓席五咏 箜篌','顧況','quantangshi','','卷14','玉作搔头金步摇，高张苦调响连宵。
欲知写尽相思梦，度水寻云不用桥。','',''),('quantangshi-13893','王郎中妓席五咏 舞','顧況','quantangshi','','卷14','汗浥新装画不成，丝催急节舞衣轻。
落花遶树疑无影，回雪从风暗有情。','',''),('quantangshi-13894','王郎中妓席五咏 歌','顧況','quantangshi','','卷14','柳拂青楼花满衣，能歌宛转世应稀。
空中几处闻清响，欲遶行云不遣飞。','',''),('quantangshi-13895','王郎中妓席五咏 筝','顧況','quantangshi','','卷14','秦声楚调怨无穷，陇水胡笳咽复通。
莫遣黄莺花里啭，参差撩乱妬春风。','',''),('quantangshi-13896','王郎中妓席五咏 笙','顧況','quantangshi','','卷14','欲写人间离别心，须听鸣凤似龙吟。
江南曲尽归何处，洞水山云知浅深。','',''),('quantangshi-13897','送李山人还玉溪','顧況','quantangshi','','卷14','好鸟共鸣临水树，幽人独欠买山钱。
若为种得千竿竹，引取君家一眼泉。','',''),('quantangshi-13898','送少微上人还鹿门','顧況','quantangshi','','卷14','少微不向吴中隐，为个生缘在鹿门。
行入汉江秋月色，襄阳耆旧几人存。','',''),('quantangshi-13899','宿昭应','顧況','quantangshi','','卷14','武帝祈灵太乙坛，新丰树色绕千官。
那知今夜长生殿，独闭山门月影寒。','',''),('quantangshi-13900','题琅邪上方','顧況','quantangshi','','卷14','东晋王家在此溪，南朝树色隔窗低。
碑沈字灭昔人远，谷鸟犹向寒花啼。','',''),('quantangshi-13901','安仁港口望仙人城','顧況','quantangshi','','卷14','楼台采翠远分明，闻说仙家在此城。
欲上仙城无路上，水边花里有人声。','',''),('quantangshi-13902','寄祕书包监','顧況','quantangshi','','卷14','一别长安路几千，遥知旧日主人怜。
贾生只是三年谪，独自无才已四年。','',''),('quantangshi-13903','小孤山','顧況','quantangshi','','卷14','古庙枫林江水边，寒鸦接饭雁横天。
大孤山远小孤出，月照洞庭归客船。','',''),('quantangshi-13904','送李秀才游嵩山','顧況','quantangshi','','卷14','嵩山石壁挂飞流，无限神仙在上头。
采得新诗题石壁，老人惆怅不同游。','',''),('quantangshi-13905','从剡溪至赤城','顧況','quantangshi','','卷14','灵溪宿处接灵山，窈映高楼向月闲。
夜半鹤声残梦里，犹疑琴曲洞房闲。','',''),('quantangshi-13906','叶上题诗从苑中流出','顧況','quantangshi','','卷14','花落深宫莺亦悲，上阳宫女断肠时。
君恩不闭东流水，叶上题诗寄与谁。','',''),('quantangshi-13907','崦里桃花','顧況','quantangshi','','卷14','崦里桃花逢女冠，林间杏叶落仙坛。
老人方授上清箓，夜听步虚山月寒。','',''),('quantangshi-13908','听子规','顧況','quantangshi','','卷14','栖霞山中子规鸟，口边血出啼不了。
山僧后夜初出定，闻似不闻山月晓。','',''),('quantangshi-13909','竹枝曲','顧況','quantangshi','','卷14','帝子苍梧不复归，洞庭叶下荆云飞。
巴人夜唱竹枝后，肠断晓猿声渐稀。','',''),('quantangshi-13910','寻僧二首 一','顧況','quantangshi','','卷14','方丈玲珑花竹闲，已将心印出人闲。
家家门外长安道，何处相逢是宝山。','',''),('quantangshi-13911','寻僧二首 二','顧況','quantangshi','','卷14','弥天释子本高情，往往山中独自行。
莫怪狂人游楚国，莲花只在淤泥生。','',''),('quantangshi-13912','桃花曲','顧況','quantangshi','','卷14','魏帝宫人舞凤楼，隋家天子泛龙舟。
君王夜醉春眠晏，不觉桃花逐水流。','',''),('quantangshi-13913','赠远','顧況','quantangshi','','卷14','暂出河边思远道，却来窗下听新莺。
故人一别几时见，春草还从旧处生。','',''),('quantangshi-13914','早春思归有唱竹枝歌者坐中下泪','顧況','quantangshi','','卷14','渺渺春生楚水波，楚人齐唱竹枝歌。
与君皆是思归客，拭泪看花奈老何。','',''),('quantangshi-13915','送郭秀才','顧況','quantangshi','','卷14','故人曾任丹徒令，买得青山拟独耕。
不作草堂招远客，却将垂柳借啼莺。','',''),('quantangshi-13916','宫词','顧況','quantangshi','','卷14','长乐宫连上苑春，玉楼金殿艳歌新。
君门一入无由出，唯有宫莺得见人。','',''),('quantangshi-13917','悼稚','顧況','quantangshi','','卷14','稚子比来骑竹马，犹疑只在屋东西。
莫言道者无悲事，曾听巴猿向月啼。','',''),('quantangshi-13918','山僧兰若','顧況','quantangshi','','卷14','绝顶茅庵老此生，寒云孤木伴经行。
世人那得知幽径，遥向青峰礼磬声。','',''),('quantangshi-13919','句','顧況','quantangshi','','卷14','崦合桃花水，窗鸣柳谷泉。
颓垣化为陂，陆地堪乘舟。
汀洲渺渺江篱短，疑是疑非两断肠。
巫峡朝云暮不归，洞庭春水晴空满。
龙吟四泽欲兴雨，凤引九雏警宿乌。
新妇矶边月明，女儿浦口潮平。','',''),('quantangshi-13920','发南康夜泊灨石中','耿湋','quantangshi','','卷14','倦客乘归舟，春溪杳将暮。
羣林结暝色，孤泊有佳趣。
夜山转长江，赤月吐深树。
飒飒松上吹，泛泛花间露。
险石俯潭涡，跳湍碍沿溯。
岂唯垂堂戒，兼以临深惧。
稍出回雁峰，明登斩蛟柱。
连云向重山，杳未见钟路。','',''),('quantangshi-13921','过王山人旧居','耿湋','quantangshi','','卷14','故宅春山中，来逢夕阳入。
汲少井味变，开稀户枢涩。
树朽鸟不栖，阶闲云自湿。
先生何处去，惆怅空独立。','',''),('quantangshi-13922','晚次昭应','耿湋','quantangshi','','卷14','落日向林路，东风吹麦陇。
藤草蔓古渠，牛羊下荒冢。
骊宫户久闭，温谷泉长涌。
为问全盛时，何人最荣宠。','',''),('quantangshi-13923','听早蝉歌','耿湋','quantangshi','','卷14','蝉鸣兮夕曛，声和兮夏云。
白日兮将短，秋意兮已满。
乍悲鸣兮欲长，犹嘶涩兮多断。
风萧萧兮转清，韵嘒嘒兮初成。
依婆娑之古树，思辽落之荒城。
闲院支颐，深林倚策。
犹惆怅而无语，鬓星星而已白。','',''),('quantangshi-13924','芦花动','耿湋','quantangshi','','卷14','连素穗，翻秋气，细节疎茎任长吹。
共作月中声，孤舟发乡思。','',''),('quantangshi-13925','赋得寒蛩','耿湋','quantangshi','','卷14','尔谁造，鸣何早，趯趯连声徧阶草。
复与夜雨和，游人听堪老。','',''),('quantangshi-13926','宣城逢张二南史','耿湋','quantangshi','','卷14','全家宛陵客，文雅世难逢。
寄食年将老，干时计未从。
秋来句曲水，雨后敬亭峯。
西北长安远，登临恨几重。','',''),('quantangshi-13927','题童子寺','耿湋','quantangshi','','卷14','半偈留何处，全身弃此中。
雨余沙塔坏，月满雪山空。
耸刹临回磴，朱楼间碧丛。
朝朝日将暮，长对晋阳宫。','',''),('quantangshi-13928','夏日寄东溪隐者','耿湋','quantangshi','','卷14','日华浮野水，草色合遥空。
处处山依旧，年年事不同。
闲田孤垒外，暑雨片云中。
惆怅多尘累，无由访钓翁。','',''),('quantangshi-13929','之江淮留别京亲故','耿湋','quantangshi','','卷14','长云迷一雁，渐远向南声。
已带千霜鬓，初为万里行。
繁虫满夜草，连雨暗秋城。
前路诸侯贵，何人重客卿。','',''),('quantangshi-13930','太原送许侍御出幕归东都','耿湋','quantangshi','','卷14','昔随刘越石，今日独归时。
汾水风烟冷，并州花木迟。
荒庭增别梦，野雨失行期。
莫向山阳过，隣人夜笛悲。','',''),('quantangshi-13931','华州客舍奉和崔端公春城晓望','耿湋','quantangshi','','卷14','不语看芳径，悲春嬾独行。
向人微月在，报雨早霞生。
贫病催年齿，风尘掩姓名。
赖逢骢马客，郢曲缓羇情。','',''),('quantangshi-13932','题清萝翁双泉','耿湋','quantangshi','','卷14','侧弁向清漪，门中夕照移。
异源生暗石，叠响落秋池。
叶拥沙痕没，流回草蔓随。
泠泠无限意，不独远公知。','',''),('quantangshi-13933','酬李文','耿湋','quantangshi','','卷14','落照长杨苑，秋天渭水滨。
初飞万木叶，又长一年人。
贫病仍为客，艰虞更问津。
多慙惠然意，今日肯相亲。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-13934','赠严维','耿湋','quantangshi','','卷14','许询清论重，寂寞住山阴。
野路接寒寺，闲门当古林。
海田秋熟早，湖水夜渔深。
世上穷通理，谁人奈此心。','',''),('quantangshi-13935','春日题苗发竹亭','耿湋','quantangshi','','卷14','春亭及策上，郎吏谢玄晖。
闲咏疎篁近，高眠远岫微。
偏宜留野客，暂得解朝衣。
犹忆东溪里，雷云掩故扉。','',''),('quantangshi-13936','题孝子陵','耿湋','quantangshi','','卷14','荒坟秋陌上，霜露正霏霏。
松柏自成拱，苫庐长不归。
浮埃积蓬鬓，流血在麻衣。
何必曾参传，千年至行稀。','',''),('quantangshi-13937','题庄上人房','耿湋','quantangshi','','卷14','不语焚香坐，心知道已成。
流年衰此世，定力见他生。
暮雪余春冷，寒灯续昼明。
寻常五侯至，敢望下阶迎。','',''),('quantangshi-13938','宋中','耿湋','quantangshi','','卷14','日暮黄云合，年深白骨稀。
旧村乔木在，秋草远人归。
废井莓苔厚，荒田路径微。
唯余近山色，相对似依依。','',''),('quantangshi-13939','秋夜思归','耿湋','quantangshi','','卷14','来时犹暑服，今已露漫漫。
多雨逢初霁，深秋生夜寒。
投人心似切，为客事皆难。
何处无留滞，谁能暂问看。','',''),('quantangshi-13940','送李端','耿湋','quantangshi','','卷14','世上许刘桢，洋洋风雅声。
客来空改岁，归去未成名。
远近天初暮，关河雪半晴。
空怀谏书在，回首恋承明。','',''),('quantangshi-13941','送崔明府赴青城','耿湋','quantangshi','','卷14','清冬宾御出，蜀道翠微间。
远雾开羣壑，初阳照近关。
霜潭浮紫菜，雪栈绕青山。
当似遗民去，柴桑政自闲。','',''),('quantangshi-13942','送王将军出塞','耿湋','quantangshi','','卷14','汉家边事重，窦宪出临戎。
绝漠秋山在，阳关旧路通。
列营依茂草，吹角向高风。
更就燕然石，行看奏虏功。','',''),('quantangshi-13943','雨中留别','耿湋','quantangshi','','卷14','东西无定客，风雨未休时。
悯默此中别，飘零何处期。
青山违旧隐，白发入新诗。
岁岁迷津路，生涯渐可悲。','',''),('quantangshi-13944','送杨将军','耿湋','quantangshi','','卷14','一身良将后，万里讨乌孙。
落日边陲静，秋风鼓角喧。
远山当碛路，茂草向营门。
生死酬恩宠，功名岂敢论。','',''),('quantangshi-13945','送夏侯审游蜀','耿湋','quantangshi','','卷14','暮峰和玉垒，回望不通秦。
更问蜀城路，但逢巴语人。
石林莺啭晓，板屋月明春。
若访严夫子，无嫌卜肆贫。','',''),('quantangshi-13946','送张侍御赴郴州别驾','耿湋','quantangshi','','卷14','佐郡人难料，分襟日复斜。
一帆随远水，百口过长沙。
明月江边夜，平陵梦里家。
王孙对芳草，愁思杳无涯。','',''),('quantangshi-13947','送苗贇赴阳翟丞','耿湋','quantangshi','','卷14','夕阳秋草上，去马弟兄看。
年少初辞阙，时危远效官。
山行独夜雨，旅宿二陵寒。
诗兴生何处，嵩阳羽客坛。','',''),('quantangshi-13948','送绛州郭参军','耿湋','quantangshi','','卷14','远事诸侯出，青山古晋城。
连行麴水阁，独入议中兵。
夜雨新田湿，春风曙角鸣。
人传府公政，记室有参卿。','',''),('quantangshi-13949','常州留别','耿湋','quantangshi','','卷14','万里南天外，求书禹穴间。
往来成白首，旦暮见青山。
夜浦凉云过，秋塘好月闲。
殷勤阳羡桂，别此几时攀。','',''),('quantangshi-13950','关山月','耿湋','quantangshi','','卷14','月明边徼静，戍客望乡时。
塞古柳衰尽，关寒榆发迟。
苍苍万里道，戚戚十年北。
今夜青楼上，还应照所思。','',''),('quantangshi-13951','代宋州将淮上乞师','耿湋','quantangshi','','卷14','唇齿幸相依，危亡故远归。
身轻百战出，家在数重围。
上将坚深垒，残兵鬬落晖。
常闻铁劒利，早晚借余威。','',''),('quantangshi-13952','秋晚卧疾寄司空拾遗曙卢少府纶','耿湋','quantangshi','','卷14','寒几坐空堂，疎髯似积霜。
老医迷旧疾，朽药误新方。
晚果红低树，秋苔绿徧墙。
慙非蒋生径，不敢望求羊。','',''),('quantangshi-13953','赠海明上人','耿湋','quantangshi','','卷14','来自西天竺，持经奉紫微。
年深梵语变，行苦俗流归。
月上安禅久，苔生出院稀。
梁间有驯鸽，不去复何依。','',''),('quantangshi-13954','津亭有怀','耿湋','quantangshi','','卷14','津亭一望乡，淮海晚茫茫。
草没栖洲鹭，天连暎浦樯。
徃来通楚越，旦暮易渔商。
惆怅缄书毕，何人向洛阳。','',''),('quantangshi-13955','晚投江泽浦即事呈柳兵曹泥','耿湋','quantangshi','','卷14','落日过重霞，轻烟上远沙。
移舟冲荇蔓，转浦入芦花。
断岸迂来客，连波漾去槎。
故乡何处在，更道向天涯。','',''),('quantangshi-13956','东郊别业','耿湋','quantangshi','','卷14','东臯占薄田，耕种过余年。
护药栽山刺，浇蔬引竹泉。
晚雷期稔岁，重雾报晴天。
若问幽人意，思齐沮溺贤。','',''),('quantangshi-13957','早朝','耿湋','quantangshi','','卷14','钟鼓余声里，千官向紫微。
冒寒人语少，乘月烛来稀。
清漏闻驰道，轻霞暎琐闱。
犹看嘶马处，未启掖垣扉。','',''),('quantangshi-13958','屏居盩厔','耿湋','quantangshi','','卷14','百年心不料，一卷日相知。
乘兴偏难改，忧家是强为。
县城寒寂寞，峰树远参差。
自笑无谋者，秪应道在斯。','',''),('quantangshi-13959','进秋隼','耿湋','quantangshi','','卷14','岂悟因罗者，迎霜献紫微。
夕阳分素臆，秋色上花衣。
举翅云天近，回眸燕雀稀。
应随明主意，百中有光辉。','',''),('quantangshi-13960','咏宣州笔','耿湋','quantangshi','','卷14','寒竹慙虚受，纤毫任几重。
影端缘守直，心劲懒藏锋。
落纸惊风起，摇空见露浓。
丹青与文事，舍此复何从。','',''),('quantangshi-13961','春日洪州即事','耿湋','quantangshi','','卷14','钟陵春日好，春水满南塘。
竹宇分朱阁，桐花间绿杨。
蹉跎看鬓色，留滞惜年芳。
欲问羇愁发，秦关道路长。','',''),('quantangshi-13962','雪后宿王纯池州草堂','耿湋','quantangshi','','卷14','宿君湖上宅，琴韵静参差。
夜雪入秋浦，孤城连贵池。
流年看共老，衔酒发中悲。
良会应难再，晨鸡自有期。','',''),('quantangshi-13963','旅次汉故畤','耿湋','quantangshi','','卷14','我行过汉畤，寥落见孤城。
邑里经多难，儿童识五兵。
广川桑遍绿，丛薄雉连鸣。
惆怅萧关道，终军愿请缨。','',''),('quantangshi-13964','过三郊驿却寄杨评事时此子郭令公欲有表荐','耿湋','quantangshi','','卷14','冉冉青衫客，悠悠白发人。
乱山孤驿暮，长路百花新。
终岁行他县，全家望此身。
更思君去就，早晚问平津。','',''),('quantangshi-13965','陇西行','耿湋','quantangshi','','卷14','雪下阳关路，人稀陇戍头。
封狐犹未翦，边将岂无羞。
白草三冬色，黄云万里愁。
因思李都尉，毕竟不封侯。','',''),('quantangshi-13966','巴陵逢洛阳邻舍','耿湋','quantangshi','','卷14','因君知北事，流浪已忘机。
客久多人识，年高众病归。
连云湖色远，度雪雁声稀。
又说家林尽，凄伤泪满衣。','',''),('quantangshi-13967','哭张融','耿湋','quantangshi','','卷14','早岁能文客，中年与世违。
有家孀妇少，无子吊人稀。
繐帐尘空暗，铭旌雨不飞。
依然旧乡路，寂寞几回归。','',''),('quantangshi-13968','送友贬岭南','耿湋','quantangshi','','卷14','暮年从远谪，落日别交亲。
湖上北飞雁，天涯南去人。
梦成湘浦夜，泪尽桂阳春。
岁月茫茫意，何时雨露新。','',''),('quantangshi-13969','春日即事二首 一','耿湋','quantangshi','','卷14','诗书成志业，嬾慢致蹉跎。
圣代丹霄远，明时白发多。
浅谋堪自笑，穷巷忆谁过。
寂寞前山暮，归人樵采歌。','',''),('quantangshi-13970','春日即事二首 二','耿湋','quantangshi','','卷14','数亩东臯宅，青春独屏居。
家贫僮仆慢，官罢友朋疎。
强饮沽来酒，羞看读了书。
闲花开满地，惆怅复何如。','',''),('quantangshi-13971','赠田家翁','耿湋','quantangshi','','卷14','老人迎客处，篱落稻畦间。
蚕屋朝寒闭，田家昼雨闲。
门闾新剃草，蹊径旧谙山。
自道谁相及，邀予试徃还。','',''),('quantangshi-13972','赠韦山人','耿湋','quantangshi','','卷14','失意成逋客，终年独掩扉。
无机狎鸥惯，多病见人稀。
流水知行药，孤云伴采薇。
空斋莫闲笑，心事与时违。','',''),('quantangshi-13973','浚公院怀旧','耿湋','quantangshi','','卷14','远公传敎毕，身没向他方。
吊客来何见，门人闭影堂。
纱灯临古砌，尘札在空牀。
寂寞疎钟后，秋天有夕阳。','',''),('quantangshi-13974','雨中宿义兴寺','耿湋','quantangshi','','卷14','遥夜宿东林，虫声阶草深。
高风初落叶，多雨未归心。
家国身犹负，星霜鬓已侵。
沧洲纵不去，何处有知音。','',''),('quantangshi-13975','送王祕书归江东','耿湋','quantangshi','','卷14','回首望知音，逶迤桑柘林。
人归海郡远，路入雨天深。
万木经秋叶，孤舟向暮心。
唯余江畔草，应见白头吟。','',''),('quantangshi-13976','渭上送李蔵器移家东都','耿湋','quantangshi','','卷14','求名虽有据，学稼又无田。
故国三千里，新春五十年。
移家还作客，避地莫知贤。
洛浦今何处，风帆去渺然。','',''),('quantangshi-13977','春寻柳先生','耿湋','quantangshi','','卷14','言是商山老，尘心莫问年。
白髯垂策短，乌帽据梧偏。
酒熟飞巴雨，丹成见海田。
疎云披远水，景动石牀前。','',''),('quantangshi-13978','题藏公院','耿湋','quantangshi','','卷14','古院林公住，疎篁近井桃。
俗年人见少，禅地自知高。
药草诚多喻，沧溟在一毫。
仍悲次宗辈，尘事日为劳。','',''),('quantangshi-13979','夏夜西亭即事寄钱员外','耿湋','quantangshi','','卷14','高亭宾客散，暑夜醉相和。
细汗迎衣集，微凉待扇过。
风还池色定，月晚树阴多。
遥想随行者，珊珊动晓珂。','',''),('quantangshi-13980','与清江上人及诸公宿李八昆季宅','耿湋','quantangshi','','卷14','汤公多外友，洛社自相依。
远客还登会，秋怀欲忘归。
惊风林果少，骤雨砌虫稀。
更过三张价，东游愧陆机。','',''),('quantangshi-13981','春日即事','耿湋','quantangshi','','卷14','邻里朝光徧，披衣夜醉醒。
庖厨非旧火，林木发新青。
接果移天性，疎泉逐地形。
清明来几日，戴胜已堪听。','',''),('quantangshi-13982','秋夜会宿李永宅忆江南旧游','耿湋','quantangshi','','卷14','偶宿俱南客，相看喜尽归。
湖山话不极，岁月念空违。
子夜高梧冷，秋阴远漏微。
那无此良会，惜在谢家稀。','',''),('quantangshi-13983','冬夜寻李永因书事赠之','耿湋','quantangshi','','卷14','栖遑偏降志，疵贱倍修身。
近觉多衰鬓，深知独故人。
天垂五夜月，霜覆九衢尘。
不待逢沮溺，而今恶问津。','',''),('quantangshi-13984','立春日宴高陵任明府宅','耿湋','quantangshi','','卷14','春灰今变候，密雪又霏霏。
坐客同心满，流年此会稀。
风成空处乱，素积夜来飞。
且共衔杯酒，陶潜不得归。','',''),('quantangshi-13985','春日游慈恩寺寄畅当','耿湋','quantangshi','','卷14','浮世今何事，空门此谛真。
死生俱是梦，哀乐讵关身。
远草光连水，春篁色离尘。
当从庚中庶，诗客更何人。','',''),('quantangshi-13986','晚秋过苏少府','耿湋','quantangshi','','卷14','九江迷去住，羣吏且因依。
高木秋垂露，寒城暮掩扉。
随云心自远，看草伴应稀。
肯信同年友，相望青琐闱。','',''),('quantangshi-13987','登鹳雀楼','耿湋','quantangshi','','卷14','久客心常醉，高楼日渐低。
黄河经海内，华岳镇关西。
去远千帆小，来迟独鸟迷。
终年不得意，空觉负东溪。','',''),('quantangshi-13988','赋得沙上雁','耿湋','quantangshi','','卷14','衡阳多道里，弱羽复哀音。
还塞知何日，惊弦乱此心。
夜阴前侣远，秋冷后湖深。
独立汀洲意，宁知霜霰侵。','',''),('quantangshi-13989','夜寻卢处士','耿湋','quantangshi','','卷14','月高鸡犬静，门掩向寒塘。
夜竹深茅宇，秋庭冷石牀。
住山年已远，服药寿偏长。
虚弃如吾者，逢君益自伤。','',''),('quantangshi-13990','邠州留别','耿湋','quantangshi','','卷14','终岁山川路，生涯总几何。
艰难为客惯，贫贱受恩多。
暮角寒山色，秋风远水波。
无人见惆怅，垂鞚入烟萝。','',''),('quantangshi-13991','赠张将军','耿湋','quantangshi','','卷14','寥落军城暮，重门返照间。
鼓鼙经雨暗，士马过秋闲。
惯守临边郡，曾营近海山。
关西旧业在，夜夜梦中还。','',''),('quantangshi-13992','赠隐公','耿湋','quantangshi','','卷14','世间无近远，定里徧曾过。
东海经长在，南朝寺最多。
暮年聊化俗，初地即摧魔。
今日忘尘虑，看心义若何。','',''),('quantangshi-13993','赠别安邑韩少府','耿湋','quantangshi','','卷14','子真能自在，江海意何如。
门掩疎尘吏，心闲阅道书。
古城寒欲雪，远客暮无车。
杳杳思前路，谁堪千里余。','',''),('quantangshi-13994','送胡校书秩满归河中','耿湋','quantangshi','','卷14','古树汾阴道，悠悠东去长。
位卑仍解印，身老又还乡。
河水平秋岸，关门向夕阳。
音书须数附，莫学晋嵇康。','',''),('quantangshi-13995','送河中张胄曹往太原计会回','耿湋','quantangshi','','卷14','北风长至远，四牡向幽并。
衰木新田路，寒芜故绛城。
遥听边上信，远计朔南程。
料变当临事，遥知外国情。','',''),('quantangshi-13996','送郭正字归郢上','耿湋','quantangshi','','卷14','济江篇已出，书府俸犹贫。
积雪商山道，全家楚塞人。
大堤逢落日，广汉望通津。
却别渔潭下，惊鸥那可亲。','',''),('quantangshi-13997','题李孝廉书房','耿湋','quantangshi','','卷14','野情专易外，一室向青山。
业就三编绝，心通万事闲。
莺稀春木上，草徧暮堦间。
莫道归繻在，来时弃故关。','',''),('quantangshi-13998','酬畅当','耿湋','quantangshi','','卷14','同游漆沮后，已是十年余。
几度曾相梦，何时定得书。
月高城影尽，霜重柳条疎。
且对尊中酒，千般想未如。','',''),('quantangshi-13999','留别解县韩明府','耿湋','quantangshi','','卷14','闲人州县厌，贱士友朋讥。
朔雪逢初下，秦关独暮归。
寒茅下原浅，残雪过风微。
一路何相慰，唯君能政稀。','',''),('quantangshi-14000','游钟山紫芝观','耿湋','quantangshi','','卷14','系舟仙宅下，清磬落春风。
雨数芝田长，云开石路重。
古房清磴接，深殿紫烟浓。
鹤驾何时去，游人自不逢。','',''),('quantangshi-14001','晚秋宿裴员外寺院','耿湋','quantangshi','','卷14','仲言多丽藻，晚水独芙蓉。
梁苑仍秋过，仁祠又夜逢。
回林通暗竹，去雨带寒钟。
愿向空门里，修持比昼龙。','',''),('quantangshi-14002','秋夜喜卢司直严少府访宿','耿湋','quantangshi','','卷14','寂寂闭层城，悠悠此夜情。
早凉过鬓发，秋思入柴荆。
严子多高趣，卢公有盛名。
还如杜陵下，暂拂蒋元卿。','',''),('quantangshi-14003','下邽客舍喜叔孙主簿郑少府见过','耿湋','quantangshi','','卷14','良宵复杪秋，把酒说羇游。
落木东西别，寒萍远近流。
萧条旅馆月，寂历曙更筹。
不是仇梅至，何人问百忧。','',''),('quantangshi-14004','盩厔客舍','耿湋','quantangshi','','卷14','寥寂荒垒下，客舍雨微微。
门见苔生满，心慙吏到稀。
篱花看未发，海燕欲先归。
无限堪惆怅，谁家复捣衣。','',''),('quantangshi-14005','宿韦员外宅','耿湋','quantangshi','','卷14','传经韦相后，赐笔汉家郎。
幽阁诸生会，寒宵几刻长。
座中灯泛酒，檐外月如霜。
人事多飘忽，邀欢讵可忘。','',''),('quantangshi-14006','登沃州山','耿湋','quantangshi','','卷14','沃州初望海，携手尽时髦。
小暑开鹏翼，新蓂长鹭涛。
月如芳草远，身比夕阳高。
羊祜伤风景，谁云异我曹。','',''),('quantangshi-14007','宿岐山姜明府厅','耿湋','quantangshi','','卷14','暝色休羣动，秋斋远客情。
细风和雨气，寒竹度帘声。
日觉蹉跎近，天敎嬾慢成。
谁能谒卿相，朝夕筭浮荣。','',''),('quantangshi-14008','上巳日','耿湋','quantangshi','','卷14','共来修禊事，内顾一悲翁。
玉鬓风尘下，花林丝管中。
故山离水石，旧侣失鵷鸿。
不及游鱼乐，裴回莲叶东。','',''),('quantangshi-14009','登乐游原','耿湋','quantangshi','','卷15','园庙何年废，登临有故丘。
孤村连日静，多雨及霖休。
常与秦山对，曾经汉主游。
岂知千载后，万事水东流。','',''),('quantangshi-14010','题惟干上人房','耿湋','quantangshi','','卷15','绳牀茅屋下，独坐味闲安。
苦行无童子，忘机避宰官。
是非齐已久，夏腊比应难。
更悟真如性，尘心稍自宽。','',''),('quantangshi-14011','会凤翔张少尹南亭','耿湋','quantangshi','','卷15','远过张正见，诗兴自依依。
西府军城暮，南庭吏事稀。
草檐宜日过，花圃任烟归。
更料重关外，羣僚候启扉。','',''),('quantangshi-14012','早春宴高陵滑少府','耿湋','quantangshi','','卷15','且宽沈簿领，应赖酒如渑。
春夜霜犹下，东城月未升。
清言饶醉客，乱舞避寒灯。
名字书仙籍，诸生病未能。','',''),('quantangshi-14013','寒蜂采菊蕊','耿湋','quantangshi','','卷15','游扬下晴空，寻芳到菊丛。
带声来蕊上，连影在香中。
去住霑余雾，高低顺过风。
终慙异蝴蝶，不与梦魂通。','',''),('quantangshi-14014','题杨着别业','耿湋','quantangshi','','卷15','柳巷向陂斜，回阳噪乱鵶。
农桑子云业，书籍蔡邕家。
暮叶初飜砌，寒池转露沙。
如何守儒行，寂寞过年华。','',''),('quantangshi-14015','送太仆寺李丞赴都到桃林塞','耿湋','quantangshi','','卷15','远过桃林塞，休年自昔闻。
曲河随暮草，重阜接闲云。
造父为周御，詹嘉守晋军。
应多怀古思，落叶又纷纷。','',''),('quantangshi-14016','宋中','耿湋','quantangshi','','卷15','百战无军食，孤城陷虏尘。
为伤多易子，翻吊浅为臣。
漫漫东流水，悠悠南陌人。
空思前事往，向晓泪霑巾。','',''),('quantangshi-14017','陪宴湖州公堂','耿湋','quantangshi','','卷15','谢公为楚郡，坐客是瑶林。
文府重门奥，儒源积浪深。
壶觞邀薄醉，笙磬发高音。
末至才仍短，难随白雪吟。','',''),('quantangshi-14018','寻觉公因寄李二端司空十四曙','耿湋','quantangshi','','卷15','少年尝昧道，无事日悠悠。
及至悟生死，寻僧已白头。
云回庐瀑雨，树落给园秋。
为我谢宗许，尘中难久留。','',''),('quantangshi-14019','送郭秀才赴举','耿湋','quantangshi','','卷15','乡赋鹿鸣篇，君为贡士先。
新经梦笔夜，才比弃繻年。
海雨沾隋柳，江潮赴楚船。
相看南去雁，离恨倍潸然。','',''),('quantangshi-14020','送王闰','耿湋','quantangshi','','卷15','相送临汉水，怆然望故关。
江芜连梦泽，楚雪入商山。
语我他年旧，看君此日还。
因将自悲泪，一洒别离间。','',''),('quantangshi-14021','送蜀客还','耿湋','quantangshi','','卷15','万峯深积翠，路向此中难。
欲暮多羇思，因高莫远看。
卓家人寂寞，扬子业荒残。
唯见岷山水，悠悠带月寒。','',''),('quantangshi-14022','送海州卢录事','耿湋','quantangshi','','卷15','之官逢计吏，风土问如何。
海口朝阳近，青州春气多。
郊原鹏影到，楼阁蜃云和。
损益关从事，期听劳者歌。','',''),('quantangshi-14023','登钟山馆','耿湋','quantangshi','','卷15','匹马宜春路，萧条背馆心。
涧花寒夕雨，潭水黑朝林。
野市鱼盐隘，江村竹苇深。
子规何处发，青树满高岑。','',''),('quantangshi-14024','秋日','耿湋','quantangshi','','卷15','照耀天山外，飞鵶几共过。
微红拂秋汉，片白透长波。
影促寒汀薄，光残古木多。
金霞与云气，散漫复相和。','',''),('quantangshi-14025','赠苗员外','耿湋','quantangshi','','卷15','为郎日赋诗，小谢少年时。
业继儒门后，心多道者期。
晚回长乐殿，新出夜明祠。
行乐西园暮，春风动柳丝。','',''),('quantangshi-14026','诣顺公问道','耿湋','quantangshi','','卷15','此身知是妄，远远诣支公。
何法住持后，能逃生死中。
秋苔经古径，萚叶满疎丛。
方便如开诱，南宗与北宗。','',''),('quantangshi-14027','废庆宝寺','耿湋','quantangshi','','卷15','黄叶前朝寺，无僧寒殿开。
池晴龟出暴，松暝鹤飞回。
古井碑横草，阴廊画杂苔。
禅宫亦销歇，尘世转堪哀。','',''),('quantangshi-14028','赴许州留别洛中亲故','耿湋','quantangshi','','卷15','淳风今变俗，末学误为文。
幸免投湘浦，那辞近汝坟。
山遮魏阙路，日隐洛阳云。
谁念联翩翼，烟中独失羣。','',''),('quantangshi-14029','送叶尊师归处州','耿湋','quantangshi','','卷15','风驭南行远，长山与夜江。
羣祆离分野，五岳拜旌幢。
石髓调金鼎，云浆实玉缸。
㹞㹞吠声晓，洞府有仙厖。','',''),('quantangshi-14030','酬张少尹秋日凤翔西郊见寄','耿湋','quantangshi','','卷15','鼎气孕河汾，英英济旧勋。
刘生曾任侠，张率自能文。
官佐征西府，名齐将上军。
秋山遥出浦，野鹤暮离羣。
远恨边笳起，劳歌骑吏闻。
废关人不到，荒戍日空曛。
草木凉初变，阴晴景半分。
叠蝉临积水，乱燕入过云。
丽藻终思我，衰髯亦为君。
闲吟寡和曲，庭叶渐纷纷。','',''),('quantangshi-14031','春日书情寄元校书伯和相国元子','耿湋','quantangshi','','卷15','数岁平津邸，诸生出门时。
羇孤力行早，疎贱托身迟。
芳草看无厌，青山到未期。
贫居悲老大，春日上茅茨。
卫玠琼瑶色，玄成鼎鼐姿。
友朋汉相府，兄弟谢家诗。
律合声虽应，劳歌调自悲。
流年不可住，惆怅镜中丝。','',''),('quantangshi-14032','奉送崔侍御和蕃','耿湋','quantangshi','','卷15','万里华戎隔，风沙道路秋。
新恩明主启，旧好使臣修。
旌节随边草，关山见戍楼。
俗殊人左袵，地远水西流。
日暮冰先合，春深雪未休。
无论善长对，博望自封侯。','',''),('quantangshi-14033','春日即事','耿湋','quantangshi','','卷15','芳菲那变易，年鬓自蹉跎。
室与千峯对，门唯二仲过。
宦情知己少，生事托人多。
草色微风长，莺声细雨和。
几时犹滞拙，终日望恩波。
纵欲论相报，无如漂母何。','',''),('quantangshi-14034','仙山行','耿湋','quantangshi','','卷15','深溪人不到，杖策独缘源。
花落寻无径，鸡鸣觉近村。
数翁皆藉草，对[弈]复倾尊。
看毕初为局，归逢几世孙。
云迷入洞处，水引出山门。
惆怅归城郭，樵柯迹尚存。','',''),('quantangshi-14035','得替后书怀上第五相公','耿湋','quantangshi','','卷15','谁语恓惶客，偏承顾盼私。
应逾骨肉分，敢忘死生期。
山县唯荒垒，云屯尽老师。
庖人宁自代，食蘖谬相推。
黄绶名空罢，青春鬓又衰。
还来扫门处，犹未报恩时。
独立花飞满，无言月下迟。
不知丞相意，更欲遣何之。','',''),('quantangshi-14036','入塞曲','耿湋','quantangshi','','卷15','将军带十围，重锦制戎衣。
猿臂销弓力，虬须长劒威。
首登平乐宴，新破大宛归。
楼上诛姬笑，门前问客稀。
暮烽玄兔急，秋草紫骝肥。
未奉君王诏，高槐昼掩扉。','',''),('quantangshi-14037','送姚校书因归河中','耿湋','quantangshi','','卷15','十年相见少，一岁又还乡。
去住人惆怅，东西路渺茫。
古陂无茂草，高树有残阳。
委弃秋来稻，雕疎采后桑。
月轮生舜庙，河水出关墙。
明日过闾里，光辉芸阁郎。','',''),('quantangshi-14038','题清源寺','耿湋','quantangshi','','卷15','儒墨兼宗道，云泉隐旧庐。
盂城今寂寞，辋水自纡余。
内学销多累，西林易故居。
深房春竹老，细雨夜钟疎。
陈迹留金地，遗文在石渠。
不知登座客，谁得蔡邕书。','',''),('quantangshi-14039','奉送蒋尚书兼御史大夫东都留守','耿湋','quantangshi','','卷15','副相威名重，春卿礼乐崇。
锡圭仍拜下，分命遂居东。
高斾翻秋日，清铙引细风。
蝉稀金谷树，草徧德阳宫。
敎用儒门俭，兵依武库雄。
谁云千载后，周召独为公。','',''),('quantangshi-14040','喜侯十七校书见访','耿湋','quantangshi','','卷15','东城独屏居，有客到吾庐。
发廪因舂黍，开畦复翦蔬。
许酣令乞酒，辞窭任无鱼。
徧出新成句，更通未悟书。
藤丝秋不长，竹粉雨仍余。
谁为须张烛，凉空有望舒。','',''),('quantangshi-14041','晚春青门林亭燕集','耿湋','quantangshi','','卷15','都门连骑出，东野柳如丝。
秦苑看山处，王孙逐草时。
欢游难再得，衰老是前期。
林静莺啼远，春深日过迟。
落花今夕思，秉烛古人诗。
对酒当为乐，双杯未可辞。','',''),('quantangshi-14042','晚秋东游寄猗氏第五明府解县韩明府','耿湋','quantangshi','','卷15','步出青门去，疎钟隔上林。
四郊多难日，千里独归心。
暮鸟声偏苦，秋云色易阴。
乱坟松柏少，野径草茅深。
灞涘袁安履，汾南宓贱琴。
何由听白雪，秪益泪霑襟。','',''),('quantangshi-14043','奉和元承杪秋忆终南旧居','耿湋','quantangshi','','卷15','白玉郎仍少，羊车上路平。
秋风摇远草，旧业起高情。
乱树通秦苑，重原接杜城。
溪云随暮淡，野水带寒清。
广树留峯翠，闲门响叶声。
近樵应已烧，多稼又新成。
解佩从休沐，承家岂退耕。
恭侯有遗躅，何事学泉明。','',''),('quantangshi-14044','晚夏即事临南居','耿湋','quantangshi','','卷15','何须学从宦，其奈本无机。
蕙草芳菲歇，青山早晚归。
广庭余落照，高枕对闲扉。
树色迎秋老，蝉声过雨稀。
艰难逢事异，去就与时违。
遥忆衡门外，苍苍三径微。','',''),('quantangshi-14045','省试骊珠诗','耿湋','quantangshi','','卷15','是日重泉下，言探径寸珠。
龙鳞今不逆，鱼目也应殊。
掌上星初满，盘中月正孤。
酬恩光莫及，照乘色难逾。
欲问投人否，先论按劒无。
傥怜希代价，敢对此冰壶。','',''),('quantangshi-14046','元日早朝','耿湋','quantangshi','','卷15','九陌朝臣满，三朝候鼓赊。
远珂时接韵，攒炬偶成花。
紫贝为高阙，黄龙建大牙。
参差万戟合，左右八貂斜。
羽扇纷朱槛，金炉隔翠华。
微风传曙漏，晓日上春霞。
环佩声重叠，蛮夷服等差。
乐和天易感，山固寿无涯。
渥泽千年圣，车书四海家。
盛明多在位，谁得守蓬麻。','',''),('quantangshi-14047','送归中丞使新罗','耿湋','quantangshi','','卷15','远国通王化，儒林得使臣。
六君成典册，万里奉丝纶。
云水连孤棹，恩私在一身。
悠悠龙节去，渺渺蜃楼新。
望里行还暮，波中岁又春。
昏明看日御，灵怪问舟人。
城邑分华夏，衣裳拟缙绅。
他时礼命毕，归路勿迷津。','',''),('quantangshi-14048','赠兴平郑明府','耿湋','quantangshi','','卷15','海内兵犹在，关西赋未均。
仍劳持斧使，尚宰茂陵人。
遥夜重城掩，清宵片月新。
绿琴听古调，白屋被深仁。
迹与儒生合，心惟静者亲。
深情先结契，薄宦早趋尘。
贫病休何日，艰难过此身。
悠悠行远道，冉冉过良辰。
明主知封事，长沮笑问津。
栖遑忽相见，欲语泪霑巾。','',''),('quantangshi-14049','和王怀州观西营秋射','耿湋','quantangshi','','卷15','谢公亲校武，草碧露漫漫。
落叶停高驾，空林满从官。
迎筹皆叠鼓，挥箭或移竿。
名借三军勇，功推百中难。
主皮山郡晚，饮筭柳营寒。
明日开铃阁，新诗双玉盘。','',''),('quantangshi-14050','晚登虔州即事寄李侍御','耿湋','quantangshi','','卷15','章溪与贡水，何事会波澜。
万里归人少，孤舟行路难。
春光浮曲浪，暮色隔连滩。
花发从南早，江流向北宽。
故交参盛府，新角耸危冠。
楚劒期终割，隋珠惜未弹。
酒醒愁转极，别远泪初干。
愿保乔松质，青青过大寒。','',''),('quantangshi-14051','奉和第五相公登鄱阳郡城西楼','耿湋','quantangshi','','卷15','茂德为邦久，丰貂旧相尊。
发生传雨露，均养助干坤。
晓肆登楼目，春销恋阙魂。
女墙分吏事，远道启津门。
湓浦潮声尽，钟陵暮色繁。
夕阳移梦土，芳草接湘源。
封内羣甿复，兵间百赋存。
童牛耕废亩，壕木遶新村。
野步渔声溢，荒祠鼓舞喧。
高斋成五字，远岫发孤猨。
一顾承英达，多荣及子孙。
家贫仍受赐，身老未酬恩。
属和瑶华曲，堪将系组纶。','',''),('quantangshi-14052','甘泉诗','耿湋','quantangshi','','卷15','异井甘如醴，深仁远未涯。
气寒堪破暑，源净自蠲邪。
修绠悬冰甃，新桐荫玉沙。
带星凝晓露，拂雾涌秋华。
绿溢涵千仞，清泠饮万家。
何能葛洪宅，终日闭烟霞。','',''),('quantangshi-14053','发绵津驿','耿湋','quantangshi','','卷15','孤舟北去暮心伤，细雨东风春草长。
杳杳短亭分水陆，隆隆远鼓集渔商。
千丛野竹连湘浦，一派寒江下吉阳。
欲问长安今远近，初年塞雁有归行。','',''),('quantangshi-14054','塞上曲','耿湋','quantangshi','','卷15','惯习干戈事鞍马，初从少小在边城。
身微久属千夫长，家远多亲五郡兵。
嬾说疆场曾大获，且悲年鬓老长征。
寒鸿过尽残阳里，楼上凄凄暮角声。','',''),('quantangshi-14055','路旁老人','耿湋','quantangshi','','卷15','老人独坐倚官树，欲语潸然泪便垂。
陌上归心无产业，城边战骨有亲知。
余生尚在艰难日，长路多逢轻薄儿。
绿水青山虽似旧，如今贫后复何为。','',''),('quantangshi-14056','赠别刘员外长卿','耿湋','quantangshi','','卷15','清如寒玉直如丝，世故多虞事莫期。
建德津亭人别夜，新安江水月明时。
为文易老皆知苦，谪宦无名倍足悲。
不学朱云能折槛，空羞献纳在丹墀。','',''),('quantangshi-14057','宿万固寺因寄严补阙','耿湋','quantangshi','','卷15','晓随樵客到青冥，因礼山僧宿化城。
钟梵已休初入定，有无皆离本难名。
云开半夜千林静，月上中峰万壑明。
为报故人雷处士，尘心终日自劳生。','',''),('quantangshi-14058','岐阳客舍呈张明府','耿湋','quantangshi','','卷15','逸妻稚子应沟壑，归路茫茫东去遥。
凉叶下时心悄悄，空斋梦里雨萧萧。
星霜渐见侵华发，生长虚闻在圣朝。
知己只今何处在，故山无事别渔樵。','',''),('quantangshi-14059','奉和李观察登河中白楼','耿湋','quantangshi','','卷15','城上高楼飞鸟齐，从公一遂蹑丹梯。
黄河曲尽流天外，白日轮轻落海西。
玉树九重长在梦，云衢一望杳如迷。
何心更和阳春奏，况复秋风闻战鼙。','',''),('quantangshi-14060','朝下寄韩舍人','耿湋','quantangshi','','卷15','侍臣鸣佩出西曹，鸾殿分阶翊彩旄。
瑞气回浮青玉案，日华遥上赤霜袍。
花间焰焰云旗合，鸟外亭亭露掌高。
肯念万年芳树里，随风一叶在蓬蒿。','',''),('quantangshi-14061','贺李观察祷河神降雨','耿湋','quantangshi','','卷15','质明斋祭北风微，驺驭千羣拥庙扉。
玉帛才敷云淡淡，笙镛未撤雨霏霏。
路边五稼添膏长，河上双旌带湿归。
若出敬亭山下作，何人敢和谢玄晖。','',''),('quantangshi-14062','上将行','耿湋','quantangshi','','卷15','萧关扫定犬羊羣，闭阁层城白日曛。
枥上骅骝嘶鼓角，门前老将识风云。
旌旗四面寒山暎，丝管千家静夜闻。
谁道古来多简册，功臣唯有卫将军。','',''),('quantangshi-14063','许下书情寄张韩二舍人','耿湋','quantangshi','','卷15','谪宦军城老更悲，近来频夜梦丹墀。
银杯乍灭心中火，金镊唯多鬓上丝。
绕院绿苔闻雁处，满庭黄叶闭门时。
故人高步云衢上，肯念前程杳未期。','',''),('quantangshi-14064','九日','耿湋','quantangshi','','卷15','重阳寒寺满秋梧，客在南楼顾老夫。
步蹇强登游藻井，发稀那更插茱萸。
横空过雨千峰出，大野新霜万叶枯。
更望尊中菊花酒，殷勤能得几回沽。','',''),('quantangshi-14065','送大谷高少府','耿湋','quantangshi','','卷15','县属并州北近胡，悠悠此别宦仍孤。
应知史笔思循吏，莫料辕门笑鲁儒。
古塞草青宜牧马，春城月暗好啼乌。
雕残贵有亲仁术，梅福何须去隐吴。','',''),('quantangshi-14066','同李端春望','耿湋','quantangshi','','卷15','二毛羇旅尚迷津，万井莺花雨后春。
宫阙参差当晚日，山河迤逦静纤尘。
和风醉里承恩客，芳草归时失意人。
南北东西各自去，年年依旧物华新。','',''),('quantangshi-14067','岳祠送薛近贬官','耿湋','quantangshi','','卷15','枯松老柏仙山下，白帝祠堂枕古逵。
迁客无辜祝史告，神明有喜女巫知。
遥思桂浦人空去，远过衡阳雁不随。
度岭梅花翻向北，回看不见树南枝。','',''),('quantangshi-14068','送友人游江南','耿湋','quantangshi','','卷15','远别悠悠白发新，江潭何处是通津。
潮声偏惧初来客，海味唯甘久住人。
漠漠烟光前浦晚，青青草色定山春。
汀洲更有南回雁，乱起联翩北向秦。','',''),('quantangshi-14069','长门怨','耿湋','quantangshi','','卷15','闻道昭阳宴，嚬蛾落叶中。
清歌逐寒月，遥夜入深宫。','',''),('quantangshi-14070','秋日','耿湋','quantangshi','','卷15','反照入闾巷，忧来与谁语。
古道无人行，秋风动禾黍。','',''),('quantangshi-14071','秋夜','耿湋','quantangshi','','卷15','高秋夜分后，远客雁来时。
寂寞重门掩，无人问所思。','',''),('quantangshi-14072','慈恩寺残春','耿湋','quantangshi','','卷15','双林花已尽，叶色占残芳。
若问同游客，高年最断肠。','',''),('quantangshi-14073','早次眉县界','耿湋','quantangshi','','卷15','匹马晓路归，悠悠渭川道。
晴山向孤城，秋日满白草。','',''),('quantangshi-14074','路傍墓','耿湋','quantangshi','','卷15','石马双双当古树，不知何代公侯墓。
墓前靡靡春草深，唯有行人看碑路。','',''),('quantangshi-14075','代园中老人','耿湋','quantangshi','','卷15','佣赁难堪一身老，皤皤力役在青春。
林园手种唯吾事，桃李成阴归别人。','',''),('quantangshi-14076','古意','耿湋','quantangshi','','卷15','虽言千骑上头居，一世生离恨有余。
叶下绮窗银烛冷，含啼自草锦中书。','',''),('quantangshi-14077','凉州词','耿湋','quantangshi','','卷15','国使翻翻随斾旌，陇西岐路足荒城。
毡裘牧马胡雏小，日暮蕃歌三两声。','',''),('quantangshi-14078','安邑王校书居','耿湋','quantangshi','','卷15','秋来池馆清，夜闻宫漏声。
迢遰玉山迥，泛灧银河倾。
琴上松风至，窗里竹烟生。
多君不家食，孰云事岩耕。','',''),('quantangshi-14079','登总持寺阁','耿湋','quantangshi','','卷15','今日登高阁，三休忽自悲。
因知筋力减，不及徃年时。
草树还如旧，山河亦在兹。
龙钟兼老病，更有重来期。','',''),('quantangshi-14080','寄钱起','耿湋','quantangshi','','卷15','草长花落树，羸病强寻春。
无复少年意，空余华发新。
青原高见水，白社静逢人。
寄谢南宫客，轩车不见亲。','',''),('quantangshi-14081','宿青龙寺故昙上人院','耿湋','quantangshi','','卷15','年深宫院在，闲客自相逢。
闭户临寒竹，无人有夜钟。
降龙今已去，巢鹤竟何从。
坐见繁星晓，凄凉识旧峯。','',''),('quantangshi-14082','新蝉','耿湋','quantangshi','','卷15','今朝蝉忽鸣，迁客若为情。
便觉一年谢，能令万感生。
微风方满树，落日稍沈城。
为问同怀者，凄凉听几声。','',''),('quantangshi-14083','秋中雨田园即事','耿湋','quantangshi','','卷15','漠漠重云暗，萧萧密雨垂。
为霖淹古道，积日满荒陂。
五稼何时获，孤村几户炊。
乱流发通圃，腐叶着秋枝。
暮爨新樵湿，晨渔旧浦移。
空余去年菊，花发在东篱。','',''),('quantangshi-14084','拜新月','耿湋','quantangshi','','卷15','开帘见新月，便即下堦拜。
细语人不闻，北风吹裙带。','',''),('quantangshi-14085','客行赠人','耿湋','quantangshi','','卷15','旅行虽别路，日暮各思归。
欲下今朝泪，知君亦湿衣。','',''),('quantangshi-14086','赠山老人','耿湋','quantangshi','','卷15','白首独一身，青山为四隣。
虽行故乡陌，不见故乡人。','',''),('quantangshi-14087','赠胡居士','耿湋','quantangshi','','卷15','孔融过五十，海内故人稀。
相府恩犹在，知君未拂衣。','',''),('quantangshi-14088','荐福寺送元伟','耿湋','quantangshi','','卷15','送客攀花后，寻僧坐竹时。
明朝莫回望，青草马行迟。','',''),('quantangshi-14089','观邻老栽松','耿湋','quantangshi','','卷15','虽过老人宅，不解老人心。
何事斜阳里，栽松欲待阴。','',''),('quantangshi-14090','哭麴象','耿湋','quantangshi','','卷15','忆昨秋风起，君曾叹逐臣。
何言芳草日，自作九泉人。','',''),('quantangshi-14091','哭苗垂','耿湋','quantangshi','','卷15','旧友无由见，孤坟草欲长。
月斜邻笛尽，车马出山阳。','',''),('quantangshi-14092','题云际寺故僧院','耿湋','quantangshi','','卷15','白发悤悤色，青山草草心。
远公仍下世，从此别东林。','',''),('quantangshi-14093','句','耿湋','quantangshi','','卷15','高树多凉吹，疎蝉足断声。','',''),('quantangshi-14094','塞下曲 一','戎昱','quantangshi','','卷15','惨惨寒日没，北风卷蓬根。
将军领疲兵，却入古塞门。
回头指阴山，杀气成黄云。','',''),('quantangshi-14095','塞下曲 二','戎昱','quantangshi','','卷15','上山望胡兵，胡马驰骤速。
黄河冰已合，意又向南牧。
嫖姚夜出军，霜雪割人肉。','',''),('quantangshi-14096','塞下曲 三','戎昱','quantangshi','','卷15','塞北无草木，乌鸢巢僵尸。
泱渀沙漠空，终日胡风吹。
战卒多苦辛，苦辛无四时。','',''),('quantangshi-14097','塞下曲 四','戎昱','quantangshi','','卷15','晚渡西海西，向东看日没。
傍岸砂砾堆，半和战兵骨。
单于竟未灭，阴气常勃勃。','',''),('quantangshi-14098','塞下曲 五','戎昱','quantangshi','','卷15','城上画角哀，即知兵心苦。
试问左右人，无言泪如雨。
何意休明时，终年事鼙鼓。','',''),('quantangshi-14099','塞下曲 六','戎昱','quantangshi','','卷15','北风凋白草，胡马日骎骎。
夜后戍楼月，秋来边将心。
铁衣霜露重，战马岁年深。
自有卢龙塞，烟尘飞至今。','',''),('quantangshi-14100','苦哉行五首 一','戎昱','quantangshi','','卷15','彼鼠侵我厨，纵狸授粱肉。
鼠虽为君却，狸食自须足。
冀雪大国耻，翻是大国辱。
膻腥逼绮罗，砖瓦杂珠玉。
登楼非骋望，目笑是心哭。
何意天乐中，至今奏胡曲。','',''),('quantangshi-14101','苦哉行五首 二','戎昱','quantangshi','','卷15','官军收洛阳，家住洛阳里。
夫壻与兄弟，目前见伤死。
吞声不许哭，还遣衣罗绮。
上马随匈奴，数秋黄尘里。
生为名家女，死作塞垣鬼。
乡国无还期，天津哭流水。','',''),('quantangshi-14102','苦哉行五首 三','戎昱','quantangshi','','卷15','登楼望天衢，目极泪盈睫。
彊笑无笑容，须妆旧花靥。
昔年买奴仆，奴仆来碎叶。
岂意未死间，自为匈奴妾。
一生忽至此，万事痛苦业。
得出塞垣飞，不如彼蜂蝶。','',''),('quantangshi-14103','苦哉行五首 四','戎昱','quantangshi','','卷15','妾家清河边，七叶承貂蝉。
身为最小女，偏得浑家怜。
亲戚不相识，幽闺十五年。
有时最远出，秪到中门前。
前年狂胡来，惧死翻生全。
今秋官军至，岂意遭戈鋋。
匈奴为先锋，长鼻黄发拳。
弯弓猎生人，百步牛羊膻。
脱身落虎口，不及归黄泉。
苦哉难重陈，暗哭苍苍天。','',''),('quantangshi-14104','苦哉行五首 五','戎昱','quantangshi','','卷15','可汗奉亲诏，今月归燕山。
忽如乱刀劒，搅妾心肠间。
出户望北荒，迢迢玉门关。
生人为死别，有去无时还。
汉月割妾心，胡风凋妾颜。
去去断绝魂，呌天天不闻。','',''),('quantangshi-14105','苦辛行','戎昱','quantangshi','','卷15','且莫奏短歌，听余苦辛词。
如今刀笔士，不及屠沽儿。
少年无事学诗赋，岂意文章复相悞。
东西南北少知音，终年竟岁悲行路。
仰面诉天天不闻，低头告地地不言。
天地生我尚如此，陌上他人何足论。
谁谓西江深，涉之固无忧。
谁谓南山高，可以登之游。
险巇唯有世间路，一晌令人堪白头。
贵人立意不可测，等闲桃李成荆棘。
风尘之士深可亲，心如鸡犬能依人。
悲来却忆汉天子，不弃相如家旧贫。
劝君且饮酒，酒能散羇愁。
谁家有酒判一醉，万事从他江水流。','',''),('quantangshi-14106','长安秋夕','戎昱','quantangshi','','卷15','八月更漏长，愁人起常早。
闭门寂无事，满院生秋草。
昨宵西窗梦，梦入荆南道。
远客归去来，在家贫亦好。','',''),('quantangshi-14107','罗江客舍','戎昱','quantangshi','','卷15','山县秋云暗，茅亭暮雨寒。
自伤庭叶下，谁问客衣单。
有兴时添酒，无聊嬾整冠。
近来乡国梦，夜夜到长安。','',''),('quantangshi-14108','赠岑郎中','戎昱','quantangshi','','卷15','童年未解读书时，诵得郎中数首诗。
四海烟尘犹隔阔，十年魂梦每相随。
虽披云雾逢迎疾，已恨趋风拜德迟。
天下无人鉴诗句，不寻诗伯重寻谁。','',''),('quantangshi-14109','闻笛','戎昱','quantangshi','','卷15','入夜思归切，笛声清更哀。
愁人不愿听，自到枕前来。
风起寒云断，夜深关月开。
平明独惆怅，飞尽一庭梅。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-14110','汉上题韦氏庄','戎昱','quantangshi','','卷15','结茅同楚客，卜筑汉江边。
日落数归鸟，夜深闻扣舷。
水痕侵岸柳，山翠借厨烟。
调笑提筐妇，春来蚕几眠。','',''),('quantangshi-14111','闺情','戎昱','quantangshi','','卷15','侧听宫官说，知君宠尚存。
未能开笑颊，先欲换愁魂。
宝镜窥妆影，红衫裛泪痕。
昭阳今再入，宁敢恨长门。','',''),('quantangshi-14112','衡阳春日游僧院','戎昱','quantangshi','','卷15','曾共刘谘议，同时事道林。
与君相掩泪，来客岂知心。
堦雪凌春积，炉烟向暝深。
依然旧童子，相送出花林。','',''),('quantangshi-14113','玉台体题湖上亭','戎昱','quantangshi','','卷15','湖入县西边，湖头胜事偏。
绿竿初长笋，红颗未开莲。
蔽日高高树，迎人小小船。
清风长入坐，夏月似秋天。','',''),('quantangshi-14114','早梅','戎昱','quantangshi','','卷15','一树寒梅白玉条，迥临村路傍溪桥。
应缘近水花先发，疑是经春雪未销。','',''),('quantangshi-14115','移家别湖上亭','戎昱','quantangshi','','卷15','好是春风湖上亭，柳条藤蔓系离情。
黄莺久住浑相识，欲别频啼四五声。','',''),('quantangshi-14116','客堂秋夕','戎昱','quantangshi','','卷15','隔窗萤影灭复流，北风微雨虚堂秋。
虫声竟夜引乡泪，蟋蟀何自知人愁。
四时不得一日乐，以此方悲客游恶。
寂寂江城无所闻，梧桐叶上偏萧索。','',''),('quantangshi-14117','湖南雪中留别','戎昱','quantangshi','','卷15','草草还草草，湖东别离早。
何处愁杀人，归鞍雪中道。
出门迷辙迹，云水白浩浩。
明日武陵西，相思鬓堪老。','',''),('quantangshi-14118','赠别张驸马','戎昱','quantangshi','','卷15','上元年中长安陌，见君朝下欲归宅。
飞龙骑马三十匹，玉勒雕鞍照初日。
数里衣香遥扑人，长衢雨歇无纤尘。
从奴斜抱勑赐锦，双双蹙出金麒麟。
天子爱壻皇后弟，独步明时负权势。
一身扈跸承殊泽，甲第朱门耸高戟。
凤凰楼上伴吹箫，鹦鹉杯中醉留客。
泰去否来何足论，宫中晏驾人事翻。
一朝负谴辞丹阙，五年待罪湘江源。
冠冕凄凉几迁改，眼看桑田变成海。
华堂金屋别赐人，细眼黄头总何在。
渚宫相见寸心悲，嬾欲今时问昔时。
看君风骨殊未歇，不用愁来双泪垂。','',''),('quantangshi-14119','泾州观元戎出师','戎昱','quantangshi','','卷15','寒日征西将，萧萧万马丛。
吹笳覆楼雪，祝纛满旗风。
遮虏黄云断，烧羌白草空。
金铙肃天外，玉帐静霜中。
朔野长城闭，河源旧路通。
卫青师自老，魏绛赏何功。
枪垒依沙迥，辕门压塞雄。
燕然如可勒，万里愿从公。','',''),('quantangshi-14120','从军行','戎昱','quantangshi','','卷15','昔从李都尉，双鞬照马蹄。
擒生黑山北，杀敌黄云西。
太白沈虏地，边草复萋萋。
归来邯郸市，百尺青楼梯。
感激然诺重，平生胆力齐。
芳筵暮歌发，艳粉轻鬟低。
半酣秋风起，铁骑门前嘶。
远戍报烽火，孤城严鼓鼙。
挥鞭望尘去，少妇莫含啼。','',''),('quantangshi-14121','古意','戎昱','quantangshi','','卷15','女伴朝来说，知君欲弃捐。
嬾梳明镜下，羞到画堂前。
有泪霑脂粉，无情理管弦。
不知将巧笑，更遣向谁怜。','',''),('quantangshi-14122','听杜山人弹胡笳','戎昱','quantangshi','','卷15','绿琴胡笳谁妙弹，山人杜陵名庭兰。
杜君少与山人友，山人没来今已久。
当时海内求知音，嘱付胡笳入君手。
杜陵攻琴四十年，琴声在音不在弦。
座中为我奏此曲，满堂萧飋如穷边。
第一第二拍，泪尽蛾眉没蕃客。
更闻出塞入塞声，穹庐毡帐难为情。
胡天雨雪四时下，五月不曾芳草生。
须臾促轸变宫征，一声悲兮一声喜。
南看汉月双眼明，却顾胡儿寸心死。
回鹘数年收洛阳，洛阳士女皆驱将。
岂无父母与兄弟，闻此哀情皆断肠。
杜陵先生证此道，沈家祝家皆绝倒。
如今世上雅风衰，若个深知此声好。
世上爱筝不爱琴，则明此调难知音。
今朝促轸为君奏，不向俗流传此心。','',''),('quantangshi-14123','咏史','戎昱','quantangshi','','卷15','汉家青史上，计拙是和亲。
社稷依明主，安危托妇人。
岂能将玉貌，便拟静胡尘。
地下千年骨，谁为辅佐臣。','',''),('quantangshi-14124','桂州腊夜','戎昱','quantangshi','','卷15','坐到三更尽，归仍万里赊。
雪声偏傍竹，寒梦不离家。
晓角分残漏，孤灯落碎花。
二年随骠骑，辛苦向天涯。','',''),('quantangshi-14125','再赴桂州先寄李大夫','戎昱','quantangshi','','卷15','玷玉甘长弃，朱门喜再游。
过因才后重，恩合死前酬。
养骥须怜瘦，栽松莫厌秋。
今朝两行泪，一半血和流。','',''),('quantangshi-14126','题招提寺','戎昱','quantangshi','','卷15','招提精舍好，石壁向江开。
山影水中尽，鸟声天上来。
一灯传岁月，深院长莓苔。
日暮双林磬，泠泠送客回。','',''),('quantangshi-14127','谪官辰州冬至日[有]怀','戎昱','quantangshi','','卷15','去年长至在长安，策杖曾簪獬豸冠。
此岁长安逢至日，下堦遥想雪霜寒。
梦随行伍朝天去，身寄穷荒报国难。
北望南郊消息断，江头唯有泪阑干。','',''),('quantangshi-14128','赠韦况徴君','戎昱','quantangshi','','卷15','身欲逃名名自随，凤衔丹诏降茅茨。
苦节难违天子命，贞心唯有老松知。
回看药竈封题密，强入蒲轮引步迟。
今日巢由旧冠带，圣朝风化胜尧时。','',''),('quantangshi-14129','送吉州阎使君入道二首 一','戎昱','quantangshi','','卷15','闻道桃源去，尘心忽自悲。
余当从宦日，君是弃官时。
金汞封仙骨，灵津咽玉池。
受传三箓备，起坐五云随。
洞里花常发，人间鬓易衰。
他年会相访，莫作烂柯棊。','',''),('quantangshi-14130','送吉州阎使君入道二首 二','戎昱','quantangshi','','卷15','庐陵太守近隳官，霞帔初朝五帝坛。
风过鬼神延受箓，夜深龙虎卫烧丹。
冰容入镜纤埃静，玉液添瓶漱齿寒。
莫遣桃花迷客路，千山万水访君难。','',''),('quantangshi-14131','入劒门','戎昱','quantangshi','','卷15','劒门兵革后，万事尽堪悲。
鸟鼠无巢穴，儿童话别离。
山川同昔日，荆棘是今时。
征战何年定，家家有画旗。','',''),('quantangshi-14132','过商山','戎昱','quantangshi','','卷15','雨暗商山过客稀，路傍孤店闭柴扉。
卸鞍良久茅檐下，待得巴人樵采归。','',''),('quantangshi-14133','闰春宴花溪严侍御庄','戎昱','quantangshi','','卷15','一团青翠色，云是子陵家。
山带新晴雨，溪留闰月花。
瓶开巾漉酒，地坼笋抽芽。
彩缛承颜面，朝朝赋白华。','',''),('quantangshi-14134','岁暮客怀','戎昱','quantangshi','','卷15','异乡三十口，亲老复家贫。
无事干坤内，虚为翰墨人。
岁华南去后，愁梦北来频。
惆怅江边柳，依依又欲春。','',''),('quantangshi-14135','秋望兴庆宫','戎昱','quantangshi','','卷15','先皇歌舞地，今日未游巡。
幽咽龙池水，凄凉御榻尘。
随风秋树弃，对月老宫人。
万事如桑海，悲来欲恸神。','',''),('quantangshi-14136','送郑炼师贬辰州','戎昱','quantangshi','','卷15','辰州万里外，想得逐臣心。
谪去刑名枉，人间痛惜深。
误将瑕指玉，遂使谩消金。
计日西归在，休为泽畔吟。','',''),('quantangshi-14137','云梦故城秋望','戎昱','quantangshi','','卷15','故国遗墟在，登临想旧游。
一朝人事变，千载水空流。
梦渚鸿声晚，荆门树色秋。
片云凝不散，遥挂望乡愁。','',''),('quantangshi-14138','秋日感怀','戎昱','quantangshi','','卷15','洛阳岐路信悠悠，无事辞家两度秋。
日下未驰千里足，天涯徒泛五湖舟。
菏衣半浸缘乡泪，玉貌潜销是客愁。
说向长安亲与故，谁怜岁晚尚淹留。','',''),('quantangshi-14139','送王明府入道','戎昱','quantangshi','','卷15','何事陶彭泽，明时又挂冠。
为耽泉石趣，不惮薜萝寒。
轻雪笼纱帽，孤猨傍醮坛。
悬悬老松下，金竈夜烧丹。','',''),('quantangshi-14140','秋月','戎昱','quantangshi','','卷15','江干入夜杵声秋，百尺疎桐挂斗牛。
思苦自看明月苦，人愁不是月华愁。','',''),('quantangshi-14141','赋得铁马鞭','戎昱','quantangshi','','卷15','成器虽因匠，怀刚本自天。
为怜持寸节，长拟静三边。
未入英髦用，空存铁石坚。
希君剖腹取，还解抱龙泉。','',''),('quantangshi-14142','闻颜尚书陷贼中','戎昱','quantangshi','','卷15','闻说征南没，那堪故吏闻。
能持苏武节，不受马超勋。
国破无家信，天秋有雁羣。
同荣不同辱，今日负将军。','',''),('quantangshi-14143','送苏参军','戎昱','quantangshi','','卷15','忆昨青襟醉里分，酒醒回首怆离羣。
舟移极浦城初掩，山束长江日早曛。
客来有恨空思德，别后谁人更议文。
常叹苏生官太屈，应缘才似鲍参军。','',''),('quantangshi-14144','成都元十八侍御','戎昱','quantangshi','','卷15','不见元生已数朝，浣花溪路去菲遥。
客舍早知浑寂寞，交情岂谓更萧条。
空有寸心思会面，恨无单酌遣相邀。
骅骢幸自能驰骤，何惜挥鞭过柞桥。','',''),('quantangshi-14145','观卫尚书九日对中使射破的','戎昱','quantangshi','','卷15','盛宴倾黄菊，殊私降紫泥。
月营开射圃，霜斾拂晴霓。
出将三朝贵，弯弓五善齐。
腕回金镞满，的破绿弦低。
勇气干牛斗，欢声震鼓鼙。
忠臣思报国，更欲取关西。','',''),('quantangshi-14146','辰州闻大驾还宫','戎昱','quantangshi','','卷15','闻道銮舆归魏阙，望云西拜喜成悲。
宁知陇水烟销日，再有园林秋荐时。
渭水战添亡虏血，秦人生覩旧朝仪。
自惭出守辰州畔，不得亲随日月旗。','',''),('quantangshi-14147','辰州建中四年多怀','戎昱','quantangshi','','卷15','荒徼辰阳远，穷秋瘴雨深。
主恩堪洒血，边宦更何心。
海上红旗满，生前白发侵。
竹寒宁改节，隼静早因禽。
务退门多掩，愁来酒独斟。
天涯忧国泪，无日不霑襟。','',''),('quantangshi-14148','上桂州李大夫','戎昱','quantangshi','','卷15','今日辞门馆，情将众别殊。
感深翻有泪，仁过曲怜愚。
晚镜伤秋鬓，晴寒切病驱。
烟霞万里阔，宇宙一身孤。
倚马才宁有，登龙意岂无。
唯于方寸内，暗贮报恩珠。','',''),('quantangshi-14149','江城秋霁','戎昱','quantangshi','','卷15','霁后江城风景凉，岂堪登眺只堪伤。
远天螮蝀收残雨，映水鸬鷀近夕阳。
万事无成空过日，十年多难不还乡。
不知何处销兹恨，转觉愁随夜夜长。','',''),('quantangshi-14150','上李常侍','戎昱','quantangshi','','卷15','旌旗晓过大江西，七校前驱万队齐。
千里政声人共喜，三军令肃马前嘶。
恩霑境内风初变，春入城阴柳渐低。
桃李不须令更种，早知门下旧成蹊。','',''),('quantangshi-14151','上湖南崔中丞','戎昱','quantangshi','','卷15','山上青松陌上尘，云泥岂合得相亲。
举世尽嫌良马瘦，唯君不弃卧龙贫。
千金未必能移性，一诺从来许杀身。
莫道书生无感激，寸心还是报恩人。','',''),('quantangshi-14152','早春雪中','戎昱','quantangshi','','卷15','阴云万里昼漫漫，愁坐关心事几般。
为报春风休下雪，柳条初放不禁寒。','',''),('quantangshi-14153','云安阻雨','戎昱','quantangshi','','卷15','日长巴峡雨蒙蒙，又说归舟路未通。
游人不及西江水，先得东流到渚宫。','',''),('quantangshi-14154','湖南春日二首 一','戎昱','quantangshi','','卷15','自怜春日客长沙，江上无人转忆家。
光景却添乡思苦，檐前数片落梅花。','',''),('quantangshi-14155','湖南春日二首 二','戎昱','quantangshi','','卷15','三湘漂寓若流萍，万里湘乡隔洞庭。
羇客春来心欲碎，东风莫遣柳条青。','',''),('quantangshi-14156','送陆秀才归觐省','戎昱','quantangshi','','卷15','武陵何处在，南指楚云阴。
花蕚连枝近，桃源去路深。
啼莺徒寂寂，征马已骎骎。
堤上千年柳，条条挂我心。','',''),('quantangshi-14157','戏题秋月','戎昱','quantangshi','','卷15','秋宵月色胜春宵，万里天涯静寂寥。
近来数夜飞霜重，只畏娑婆树叶凋。','',''),('quantangshi-14158','宿湘江','戎昱','quantangshi','','卷15','九月湘江水漫流，沙边唯览月华秋。
金风浦上吹黄叶，一夜纷纷满客舟。','',''),('quantangshi-14159','戏赠张使君','戎昱','quantangshi','','卷15','数载蹉跎罢搢绅，五湖乘兴转迷津。
如今野客无家第，醉处寻常是主人。','',''),('quantangshi-14160','别公安贾明府','戎昱','quantangshi','','卷15','叶县门前江水深，浅于羇客报恩心。
把君诗卷西归去，一度相思一度吟。','',''),('quantangshi-14161','霁雪','戎昱','quantangshi','','卷15','风卷寒云暮雪晴，江烟洗尽柳条轻。
檐前数片无人埽，又得书窗一夜明。','',''),('quantangshi-14162','汉阴吊崔员外坟','戎昱','quantangshi','','卷15','远别望有归，叶落望春晖。
所痛泉路人，一去无还期。
荒坟遗汉阴，坟树啼子规。
存没抱冤滞，孤魂意何依。
岂无骨肉亲，岂无深相知。
曝露不复问，高名亦何为。
相携恸君罢，春日空迟迟。','',''),('quantangshi-14163','题槿花','戎昱','quantangshi','','卷15','自用金钱买槿栽，二年方始得花开。
鲜红未许佳人见，蝴蝶争知早到来。','',''),('quantangshi-14164','题宋玉亭','戎昱','quantangshi','','卷15','宋玉亭前悲暮秋，阳台路上雨初收。
应缘此处人多别，松竹萧萧也带愁。','',''),('quantangshi-14165','过东平军','戎昱','quantangshi','','卷15','画角初鸣残照微，营营鞍马往来稀。
相逢士卒皆垂泪，八座朝天何日归。','',''),('quantangshi-14166','送辰州郑使君','戎昱','quantangshi','','卷15','谁人不谴谪，君去独堪伤。
长子家无弟，慈亲老在堂。
惊魂随驿吏，冒暑向炎方。
未到猨啼处，参差已断肠。','',''),('quantangshi-14167','江上柳送人','戎昱','quantangshi','','卷15','江柳断肠色，黄丝垂未齐。
人看几重恨，鸟入一枝低。
乡泪正堪落，与君又解携。
相思万里道，春去夕阳西。','',''),('quantangshi-14168','湘南曲','戎昱','quantangshi','','卷15','虞帝南游不复还，翠蛾幽怨水云间。
昨夜月明湘浦宿，闺中珂佩度空山。','',''),('quantangshi-14169','桂州西山登高上陆大夫','戎昱','quantangshi','','卷15','登高上山上，高处更堪愁。
野菊他乡酒，芦花满眼秋。
风烟连楚郡，兄弟客荆州。
早晚朝天去，亲随定远侯。','',''),('quantangshi-14170','寄郑炼师','戎昱','quantangshi','','卷15','平生金石友，沦落向辰州。
已是二年客，那堪终日愁。
尺书浑不寄，两鬓计应秋。
今夜相思月，情人南海头。','',''),('quantangshi-14171','八月十五日','戎昱','quantangshi','','卷15','忆昔千秋节，懽娱万国同。
今来六亲远，此日一悲风。
年少逢胡乱，时平似梦中。
棃园几人在，应是涕无穷。','',''),('quantangshi-14172','征人归乡','戎昱','quantangshi','','卷15','三月江城柳絮飞，五年游客送人归。
故将别泪和乡泪，今日阑干湿汝衣。','',''),('quantangshi-14173','骆家亭子纳凉','戎昱','quantangshi','','卷15','江湖思渺然，不离国门前。
折苇鱼沈藻，攀藤鸟出烟。
生衣宜水竹，小酒入诗篇。
莫怪侵星坐，神清不欲眠。','',''),('quantangshi-14174','逢陇西故人忆关中舍弟','戎昱','quantangshi','','卷15','莫话边庭事，心摧不欲闻。
数年家陇地，舍弟殁胡军。
每念支离苦，常嗟骨肉分。
急难何日见，遥哭陇西云。','',''),('quantangshi-14175','秋夜梁十三厅事','戎昱','quantangshi','','卷15','今来秋已暮，还恐未成归。
梦里家仍远，愁中叶又飞。
竹声风度急，灯影月来微。
得见梁夫子，心源有所依。','',''),('quantangshi-14176','成都暮雨秋','戎昱','quantangshi','','卷15','九月龟城暮，愁人闭草堂。
地卑多雨润，天暖少秋霜。
纵欲倾新酒，其如忆故乡。
不知更漏意，惟向客边长。','',''),('quantangshi-14177','酬梁二十','戎昱','quantangshi','','卷15','渚宫无限客，相见独相亲。
长路皆同病，无言似一身。
岁寒唯爱竹，憔悴不堪春。
细与知音说，攻文恐悞人。','',''),('quantangshi-14178','花下宴送郑炼师','戎昱','quantangshi','','卷15','愁里惜春深，闻幽即共寻。
贵看花柳色，图放别离心。
客醉花能笑，诗成花伴吟。
为君调绿绮，先奏凤归林。','',''),('quantangshi-14179','秋馆雨后得弟兄书即事呈李明府','戎昱','quantangshi','','卷15','弟兄书忽到，一夜喜兼愁。
空馆复闻雨，贫家怯到秋。
坐中孤烛暗，窗外数萤流。
试以他乡事，明朝问子游。','',''),('quantangshi-14180','寄梁淑','戎昱','quantangshi','','卷15','长忆江头执别时，论文未有不相思。
雁过经秋无尺素，人来终日见新诗。
心思食檗何由展，家似流萍任所之。
悔学秦人南避地，武陵原上又征师。','',''),('quantangshi-14181','送张秀才之长沙','戎昱','quantangshi','','卷15','君向长沙去，长沙仆旧谙。
虽之桂岭北，终是阙庭南。
山霭生朝雨，江烟作夕岚。
松醪能醉客，慎勿滞湘潭。','',''),('quantangshi-14182','塞下曲','戎昱','quantangshi','','卷15','汉将归来虏塞空，旌旗初下玉关东。
高蹄战马三千匹，落日平原秋草中。','',''),('quantangshi-14183','送僧法和','戎昱','quantangshi','','卷15','达士心无滞，他乡总是家。
问经翻贝叶，论法指莲花。
欲契真空义，先开智慧芽。','',''),('quantangshi-14184','送严十五郎之长安','戎昱','quantangshi','','卷15','送客身为客，思家怆别家。
暂收双眼泪，遥想五陵花。
路远征车迥，山回剑阁斜。
长安君到日，春色未应赊。','',''),('quantangshi-14185','冬夜宴梁十三厅','戎昱','quantangshi','','卷15','故人能爱客，秉烛会吾曹。
家为朋徒罄，心缘翰墨劳。
夜寒销腊酒，霜冷重绨袍。
醉卧西窗下，时闻雁响高。','',''),('quantangshi-14186','收襄阳城二首 一','戎昱','quantangshi','','卷15','悲风惨惨雨修修，岘北山低草木愁。
暗发前军连夜战，平明旌斾入襄州。','',''),('quantangshi-14187','收襄阳城二首 二','戎昱','quantangshi','','卷15','五营飞将拥霜戈，百里僵尸满浕河。
日暮归来看剑血，将军却恨杀人多。','',''),('quantangshi-14188','出军','戎昱','quantangshi','','卷15','龙绕旌竿兽满旗，飜营乍似雪中移。
中军一队三千骑，尽是并州游侠儿。','',''),('quantangshi-14189','和李尹种葛','戎昱','quantangshi','','卷15','弱质人皆弃，唯君手自栽。
藟含霜后竹，香惹腊前梅。
拟托凌云势，须凭接引材。
清阴如可惜，黄鸟定飞来。','',''),('quantangshi-14190','送零陵妓','戎昱','quantangshi','','卷15','宝钿香蛾翡翠裙，装成掩泣欲行云。
殷勤好取襄王意，莫向阳台梦使君。','',''),('quantangshi-14191','采莲曲二首 一','戎昱','quantangshi','','卷15','虽听采莲曲，讵识采莲心。
漾檝爱花远，回船愁浪深。
烟生极浦色，日落半江阴。
同侣怜波静，看妆堕玉簪。','',''),('quantangshi-14192','采莲曲二首 二','戎昱','quantangshi','','卷15','涔阳女儿花满头，毵毵同泛木兰舟。
秋风日暮南湖里，争唱菱歌不肯休。','',''),('quantangshi-14193','塞上曲','戎昱','quantangshi','','卷15','胡风略地烧连山，碎叶孤城未下关。
山头烽子声声呌，知是将军夜猎还。','',''),('quantangshi-14194','寂上人禅房','戎昱','quantangshi','','卷15','俗尘浮垢闭禅关，百岁身心几日闲。
安得此生同草木，无营长在四时间。','',''),('quantangshi-14195','桂州口号','戎昱','quantangshi','','卷15','画角三声动客愁，晓霜如雪覆江楼。
谁道桂林风景暖，到来重着皂貂裘。','',''),('quantangshi-14196','红槿花','戎昱','quantangshi','','卷15','花是深红叶麴尘，不将桃李共争春。
今日惊秋自怜客，折来持赠少年人。','',''),('quantangshi-14197','哭黔中薛大夫','戎昱','quantangshi','','卷15','亚相何年镇百蛮，生涯万事瘴云间。
夜郎城外谁人哭，昨日空余旌节还。','',''),('quantangshi-14198','感春','戎昱','quantangshi','','卷15','看花泪尽知春尽，魂断看花秪恨春。
名位未霑身欲老，诗书宁救眼前贫。','',''),('quantangshi-14199','途中寄李二','戎昱','quantangshi','','卷15','杨柳烟含灞岸春，年年攀折为行人。
好风若借低枝便，莫遣青丝埽路尘。','',''),('quantangshi-14200','寄许炼师','戎昱','quantangshi','','卷15','埽石焚香礼碧空，露华偏湿蘂珠宫。
如何说得天坛上，万里无云月正中。','',''),('quantangshi-14201','下第留辞顾侍郎','戎昱','quantangshi','','卷15','绮陌彤彤花照尘，王门侯邸尽朱轮。
城南旧有山村路，欲向云霞觅主人。','',''),('quantangshi-14202','题云公山房','戎昱','quantangshi','','卷15','云公兰若深山里，月明松殿微风起。
试问空门清净心，莲花不着秋潭水。','',''),('quantangshi-14203','别离作','戎昱','quantangshi','','卷15','手把杏花枝，未曾经离别。
黄昏掩门后，寂寞自心知。','',''),('quantangshi-14204','九日贾明府见访','戎昱','quantangshi','','卷15','独掩衡门秋景闲，洛阳才子访柴关。
莫嫌浊酒君须醉，虽是贫家菊也斑。
同人愿得长携手，久客深思一破颜。
却笑孟嘉吹帽落，登高何必上龙山。','',''),('quantangshi-14205','开元观陪杜大夫中元日观乐','戎昱','quantangshi','','卷15','今朝欢称玉京天，况值关东俗理年。
舞态疑回紫阳女，歌声似遏彩云仙。
盘空双鹤惊几剑，洒砌三花度管弦。
落日香尘拥归骑，囗风油幕动高烟。','',''),('quantangshi-14206','中秋夜登楼望月寄人','戎昱','quantangshi','','卷15','西楼见月似江城，脉脉悠悠倚槛情。
万里此情同皎洁，一年今日最分明。
初惊桂子从天落，稍误芦花带雪平。
知称玉人临水见，可怜光彩有余清。','',''),('quantangshi-14207','赠宜阳张使君','戎昱','quantangshi','','卷15','暂作宜阳客，深知太守贤。
政移千里俗，人戴两重天。
旧郭多新室，闲坡尽辟田。
倘令黄霸在，今日耻同年。','',''),('quantangshi-14208','移家别树','戎昱','quantangshi','','卷15','千种庭前树，人移树不移。
看花愁作别，不及未栽时。','',''),('quantangshi-14209','成都送严十五之江东','戎昱','quantangshi','','卷15','江东万里外，别后几凄凄。
峡路花应发，津亭柳正齐。
酒倾迟日暮，川阔远天低。
心系征帆上，随君到剡溪。','',''),('quantangshi-14210','送李参军','戎昱','quantangshi','','卷15','好住好住王司户，珍重珍重李参军。
一东一西如别鹤，一南一北似浮云。
月照疎林千片影，风吹寒水万里纹。
别易会难今古事，非是余今独与君。','',''),('quantangshi-14211','题严氏竹亭','戎昱','quantangshi','','卷15','子陵栖遁处，堪系野人心。
溪水浸山影，岚烟向竹阴。
忘机看白日，留客醉瑶琴。
爱此多诗兴，归来步步吟。','',''),('quantangshi-14212','送王端公之太原归觐相公','戎昱','quantangshi','','卷15','柱史今何适，西行咏陟冈。
也知人惜别，终美雁成行。
春雨桃花静，离尊竹叶香。
到时丞相阁，应喜棣华芳。','',''),('quantangshi-14213','旅次寄湖南张郎中','戎昱','quantangshi','','卷15','寒江近户漫流声，竹影临窗乱月明。
归梦不知湖水阔，夜来还到洛阳城。','',''),('quantangshi-14214','晚次荆江','戎昱','quantangshi','','卷15','孤舟大江水，水涉无昏曙。
雨暗迷津时，云生望乡处。
渔翁闲自乐，樵客纷多虑。
秋色湖上山，归心日边树。
徒称竹箭美，未得枫林趣。
向夕垂钓还，吾从落潮去。','',''),('quantangshi-14215','同辛衮州巢父虚副端岳相思献酬之作因纾归怀兼呈辛魏二院长杨长宁','戎昱','quantangshi','','卷15','暮角发高城，情人坐中起。
临觞不及醉，分散秋风里。
虽有明月期，离心若千里。
前欢反惆怅，后会还如此。
焉得夜淹留，一回终宴喜。
羇游复牵役，馆至重湖水。
早晚泛归舟，吾从数君子。','',''),('quantangshi-14216','抚州处士湖泛舟送北回两指此南昌县查溪兰若别','戎昱','quantangshi','','卷15','移樽铺山曲，祖帐查溪阴。
铺山即远道，查溪非故林。
凄然诵新诗，落泪霑素襟。
郡政我何有，别情君独深。
禅庭古树秋，宿雨清沈沈。
挥袂故里远，悲伤去住心。','',''),('quantangshi-14217','耒阳溪夜行','戎昱','quantangshi','','卷15','乘夕棹归舟，缘源二转幽。
月明看岭树，风静听溪流。
岚气船间入，霜华衣上浮。
猨声虽此夜，不是别家愁。','',''),('quantangshi-14218','桂城早秋','戎昱','quantangshi','','卷15','远客惊秋早，江天夜露新。
满庭惟有月，空馆更何人。
卜命知身贱，伤寒舞劒频。
猨啼曾下泪，可是为忧贫。','',''),('quantangshi-14219','桂州岁暮','戎昱','quantangshi','','卷15','岁暮天涯客，寒窗欲晓时。
君恩空自感，乡思梦先知。
重谊人愁别，惊栖鹊恋枝。
不堪楼上角，南向海风吹。','',''),('quantangshi-14220','宿桂州江亭呈康端公','戎昱','quantangshi','','卷15','独向东亭坐，三更待月开。
萤光入竹去，水影过江来。
露滴千家静，年流一叶催。
龙钟万里客，正合故人哀。','',''),('quantangshi-14221','寒食日恩赐火','竇叔向','quantangshi','','卷15','恩光及小臣，华烛忽惊春。
电影随中使，星辉拂路人。
幸因榆柳暖，一照草茅贫。','',''),('quantangshi-14222','端午日恩赐百索','竇叔向','quantangshi','','卷15','仙宫长命缕，端午降殊私。
事盛蛟龙见，恩深犬马知。
余生傥可续，终冀答明时。','',''),('quantangshi-14223','贞懿皇后挽歌三首 一','竇叔向','quantangshi','','卷15','二陵恭妇道，六寝盛皇情。
礼逊生前贵，恩追殁后荣。
幼王亲捧土，爱女复连茔。
东望长如在，谁云向玉京。','',''),('quantangshi-14224','贞懿皇后挽歌三首 二','竇叔向','quantangshi','','卷15','后庭攀画柳，上陌咽清笳。
命妇羞苹叶，都人插柰花。
寿宫星月异，仙路往来赊。
纵有迎仙术，终悲隔绛纱。','',''),('quantangshi-14225','秋砧送邑大夫','竇叔向','quantangshi','','卷15','断续长门下，清泠逆旅秋。
征夫应待信，寒女不胜愁。
带月飞城上，因风散陌头。
离居偏入听，况复送归舟。','',''),('quantangshi-14226','过担石湖','竇叔向','quantangshi','','卷15','晓发渔门戍，晴看担石湖。
日衔高浪出，天入四空无。
尺寸分洲岛，纤毫指舳舻。
渺然从此去，谁念客帆孤。','',''),('quantangshi-14227','春日早朝应制','竇叔向','quantangshi','','卷15','紫殿俯千官，春松应合欢。
御炉香焰暖，驰道玉声寒。
乳燕翻珠缀，祥乌集露盘。
宫花一万树，不敢举头看。','',''),('quantangshi-14228','酬李袁州嘉佑','竇叔向','quantangshi','','卷15','少年轻会复轻离，老大开心总是悲。
强说前程聊自慰，未知携手定何时。
公才屈指登黄阁，匪服胡颜上赤墀。
想到长安诵佳句，满朝谁不念琼枝。','',''),('quantangshi-14229','夏夜宿表兄话旧','竇叔向','quantangshi','','卷15','夜合花开香满庭，夜深微雨醉初醒。
远书珍重何曾达，旧事凄凉不可听。
去日儿童皆长大，昔年亲友半凋零。
明朝又是孤舟别，愁见河桥酒幔青。','',''),('quantangshi-14230','句','竇叔向','quantangshi','','卷15','禁兵环素帟，宫女哭寒云。','',''),('quantangshi-14231','晚次方山精舍却寄张荐员外','竇常','quantangshi','','卷15','楚腊还无雪，江春又足风。
马羸三迳外，人病四愁中。
西塞波涛阔，南朝寺舍空。
犹衔步兵酒，宿醉在除东。','',''),('quantangshi-14232','和裴端公枢芜城秋夕简远近亲知','竇常','quantangshi','','卷15','岁积登朝恋，秋加陋巷贫。
宿酲因夜歇，佳句得愁新。
尽日凭幽几，何时上软轮。
汉廷风宪在，应念匪躬人。','',''),('quantangshi-14233','项亭怀古','竇常','quantangshi','','卷15','力取诚多难，天亡路亦穷。
有心裁帐下，无面到江东。
命厄留骓处，年销逐鹿中。
汉家神器在，须废拔山功。','',''),('quantangshi-14234','奉使西还早发小磵馆寄卢滁州迈','竇常','quantangshi','','卷15','野棠花覆地，山馆夜来阴。
马迹穿云去，鸡声出涧深。
清风时偃草，久旱或为霖。
试与惸嫠话，犹坚借寇心。','',''),('quantangshi-14235','早发金钩店寄奚十唐大二茂才','竇常','quantangshi','','卷15','出门山未曙，风叶暗萧萧。
月影临荒栅，泉声近废桥。
岁经秋后役，程在洛中遥。
寄谢金门侣，弓旌悞见招。','',''),('quantangshi-14236','途中立春寄杨郇伯','竇常','quantangshi','','卷15','浪迹终年客，惊心此地春。
风前独去马，泽畔耦耕人。
老大交情重，悲凉外物亲。
子云今在宅，应见柳条新。','',''),('quantangshi-14237','故秘监丹阳郡公延陵包公挽歌词','竇常','quantangshi','','卷15','卓绝明时第，孤贞贵后贫。
郄诜为胄子，季札是乡人。
笔下调金石，花开领搢绅。
那堪归葬日，哭渡柳杨津。','',''),('quantangshi-14238','凉国惠康公主挽歌','竇常','quantangshi','','卷15','玉立分尧绪，笄年下相门。
早加于氏对，偏占馆陶恩。
泪有潜成血，香无却返魂。
共知何驸马，垂白抱天孙。','',''),('quantangshi-14239','哭张仓曹南史','竇常','quantangshi','','卷15','万事竟蹉跎，重泉恨若何。
官临环卫小，身逐转蓬多。
丽藻尝专席，闲情欲烂柯。
春风宛陵路，丹旐在沧波。','',''),('quantangshi-14240','北固晚眺','竇常','quantangshi','','卷15','水国芒种后，梅天风雨凉。
露蚕开晚簇，江燕绕危樯。
山趾北来固，潮头西去长。
年年此登眺，人事几销亡。','',''),('quantangshi-14241','谒三闾庙','竇常','quantangshi','','卷15','君非三谏寤，礼许一身逃。
自树终天戚，何裨事主劳。
众鱼应饵骨，多士尽哺糟。
有客椒浆奠，文衰不继骚。','',''),('quantangshi-14242','茅山赠梁尊师','竇常','quantangshi','','卷15','云屋何年客，青山白日长。
种花春扫雪，看箓夜焚香。
上象壶中阔，平生醉里忙。
幸承仙籍后，乞取大还方。','',''),('quantangshi-14243','谒诸葛武侯庙','竇常','quantangshi','','卷15','永安宫外有祠堂，鱼水恩深祚不长。
角立一方初退舍，拟称三汉更图王。
人同过隟无留影，石在穷沙尚启行。
归蜀降吴竟何事，为陵为谷共苍苍。','',''),('quantangshi-14244','奉贺太保岐公承恩致政','竇常','quantangshi','','卷15','君为宫保及清时，冠盖初闲拜武迟。
五色诏中宣九德，百僚班外置三师。
山泉遂性休称疾，子弟能官各受词。
不学铸金思范蠡，乞言犹许上丹墀。','',''),('quantangshi-14245','之任武陵寒食日途次松滋渡先寄刘员外禹锡','竇常','quantangshi','','卷15','杏花榆荚晓风前，云际离离上峡船。
江转数程淹驿骑，楚曾三户少人烟。
看春又过清明节，算老重经癸巳年。
幸得柱山当郡舍，在朝长咏卜居篇。','',''),('quantangshi-14246','奉寄辰州房使君郎中','竇常','quantangshi','','卷15','汉代文明今盛明，犹将贾傅暂专城。
何妨密旨先符竹，莫是除书误姓名。
蜗舍喜时春梦去，隼旟行处瘴江清。
新年只可三十二，却笑潘郎白发生。','',''),('quantangshi-14247','立春后言怀招汴州李匡卫推','竇常','quantangshi','','卷15','闲斋夜击唾壶歌，试望夷门奈远何。
每听寒笳离梦断，时窥清鉴旅愁多。
初惊宵漏丁丁促，已觉春风习习和。
海内故人君最老，花开鞭马更相过。','',''),('quantangshi-14248','奉送职方崔员外摄中丞新罗册使','竇常','quantangshi','','卷15','帝命海东使，人行天一涯。
辨方知木德，开国有金家。
册拜申恩重，留欢作限赊。
顺风鲸浪热，初日锦帆斜。
夜色潜然火，秋期独往槎。
慰安皆喻旨，忠信自无瑕。
发美童年髻，簪香子月花。
便随琛賮入，正朔在中华。','',''),('quantangshi-14249','酬舍弟牟秋日洛阳官舍寄怀十韵','竇常','quantangshi','','卷15','幼为逃难者，才省用兵初。
去国三苗外，全生四纪余。
老头亲帝里，归处失吾庐。
逝水犹呜咽，祥云自卷舒。
正郎曾首拜，亚尹未平除。
几变陶家柳，空传魏阙书。
思凌天际鹤，言甚辙中鱼。
玉立知求己，金声乍起予。
在朝鱼水分，多病雪霜居。
忽报阳春曲，纵横恨不如。','',''),('quantangshi-14250','求自试','竇常','quantangshi','','卷15','仙禁祥云合，高梧彩凤游。
沈冥求自试，通鉴果蒙收。
文墨悲无位，诗书误白头。
陈王抗表日，毛遂请行秋。
双剑曾埋狱，司空问斗牛。
希垂拂拭惠，感激愿相投。','',''),('quantangshi-14251','花发上林','竇常','quantangshi','','卷15','上苑晓沈沈，花枝乱缀阴。
色浮双阙近，春入九门深。
向暖风初扇，余寒雪尚侵。
艳回秦女目，愁处越人心。
绕绕时萦蝶，关关乍引禽。
宁知幽谷羽，一举欲依林。','',''),('quantangshi-14252','过宋氏五女旧居','竇常','quantangshi','','卷15','谢庭风韵婕妤才，天纵斯文去不回。
一宅柳花今似雪，乡人拟筑望仙台。','',''),('quantangshi-14253','还京乐歌词','竇常','quantangshi','','卷15','百战初休十万师，国人西望翠华时。
家家尽唱升平曲，帝幸梨园亲制词。','',''),('quantangshi-14254','商山祠堂即事','竇常','quantangshi','','卷15','夺嫡心萌事可忧，四贤西笑暂安刘。
后王不敢论圭组，土偶人前枳树秋。','',''),('quantangshi-14255','七夕','竇常','quantangshi','','卷15','露盘花水望三星，仿髴虚无为降灵。
斜汉没时人不寐，几条蛛网下风庭。','',''),('quantangshi-14256','杏山馆听子规','竇常','quantangshi','','卷15','楚塞余春听渐稀，断猿今夕让霑衣。
云埋老树空山里，仿髴千声一度飞。','',''),('quantangshi-14257','史馆候别蒋拾遗不遇','竇牟','quantangshi','','卷15','千门万户迷，伫立月华西。
画戟晨光动，春松宿露低。
主文亲玉扆，通籍入金闺。
肯念从戎去，风沙事鼓鞞。','',''),('quantangshi-14258','早赴临台立马待漏口号寄弟羣','竇牟','quantangshi','','卷15','上陌行初尽，严城立未开。
人疑早朝去，客是远方来。
伏奏徒将命，周行自引才。
可怜霄汉曙，鸳鹭正徘徊。','',''),('quantangshi-14259','缑氏拜陵回道中呈李舍人少尹','竇牟','quantangshi','','卷15','忽忝诸卿位，仍陪长者车。
礼容皆若旧，名籍自凭虚。
上路花偏早，空山云甚余。
却愁新咏发，酬和不相如。','',''),('quantangshi-14260','陪韩院长韦河南同寻刘师不遇','竇牟','quantangshi','','卷15','仙客诚难访，吾人岂易同。
独游应驻景，相顾且吟风。
药畹琼枝秀，斋轩粉壁空。
不题三五字，何以达壶公。','',''),('quantangshi-14261','送东光吕少府之官连帅奏授','竇牟','quantangshi','','卷15','远爱东光县，平临若木津。
一城见先日，百里早惊春。
德礼邀才重，恩辉拜命新。
几时裁尺素，沧海有枯鳞。','',''),('quantangshi-14262','送刘公达判官赴天德军幕','竇牟','quantangshi','','卷15','特建青油幕，量分紫禁师。
自然知召子，不用问从谁。
文武轻车少，腥膻左袵衰。
北风如有寄，画取受降时。','',''),('quantangshi-14263','故秘监丹阳郡公延陵包公挽歌','竇牟','quantangshi','','卷15','台鼎尝虚位，夔龙莫致尧。
德音冥秘府，风韵散清朝。
天上文星落，林端玉树凋。
有吴君子墓，返葬故山遥。','',''),('quantangshi-14264','望终南','竇牟','quantangshi','','卷15','日爱南山好，时逢夏景残。
白云兼似雪，清昼乍生寒。
九陌峰如坠，千门翠可团。
欲知形胜尽，都在紫宸看。','',''),('quantangshi-14265','秋夕闲居对雨赠别卢七侍御坦','竇牟','quantangshi','','卷15','燕燕辞巢蝉蜕枝，穷居积雨坏藩篱。
夜长檐溜寒无寝，日晏厨烟湿未炊。
悟主一言那可学，从军五首竟徒为。
故人骢马朝天使，洛下秋声恐要知。','',''),('quantangshi-14266','晚过敷水驿却寄华州使院张郑二侍御','竇牟','quantangshi','','卷15','春雨如烟又若丝，晓来昏处晚晴时。
仙人掌上芙蓉沼，柱史关西松柏祠。
几许岁华销道路，无穷王事系戎师。
回瞻二妙非吾侣，日对三峰自有期。','',''),('quantangshi-14267','洛下闲居夜晴观雪寄四远诸兄弟','竇牟','quantangshi','','卷15','雪月相辉云四开，终风助冻不扬埃。
万重琼树宫中接，一直银河天上来。
荆楚岁时知染翰，湘吴醇酎忆衔杯。
强题缣素无颜色，鸿雁南飞早晚回。','',''),('quantangshi-14268','天津晓望因寄呈分司一二省郎','竇牟','quantangshi','','卷15','万乘西都去，千门正位虚。
凿龙横碧落，提象出华胥。
望幸宫嫔老，迎春海燕初。
保厘才半仗，容卫尽空庐。
要自词难拟，繇来画不如。
散郎无所属，聊事穆清居。','',''),('quantangshi-14269','早入朝书事','竇牟','quantangshi','','卷15','紫陌纷如画，彤庭郁未晨。
列星沈骑火，残月暗车尘。
隐轸排霄翰，差池跨海鳞。
玉声繁似乐，香泽散成春。
叹息驱羸马，分明识故人。
一生三不遇，今作老郎身。','',''),('quantangshi-14270','元日喜闻大礼寄上翰林四学士中书六舍人二十韵','竇牟','quantangshi','','卷15','有事郊坛毕，无私日月临。
岁华春更早，天瑞雪犹深。
玉辇回时令，金门降德音。
翰飞鸳别侣，藂植桂为林。
粉泽资鸿笔，薰和本素琴。
礼成戎器下，恩彻鬼方沈。
麟爵来称纪，官师退绝箴。
道风黄阁静，祥景紫垣阴。
寿酒朝时献，农书夜直寻。
国香煴翠幄，庭燎赩红衾。
汉魏文章盛，尧汤雨露霃。
密辞投水石，精义出沙金。
宸扆亲唯敬，钧衡近匪侵。
疾驱千里骏，清唳九霄禽。
庆赐迎新服，斋庄弃旧簪。
忽思班女怨，遥听越人吟。
末路甘贫病，流年苦滞淫。
梦中青琐闼，归处碧山岑。
窃拚闻韶濩，观光想韎任。
大哉环海晏，不笇子牟心。','',''),('quantangshi-14271','奉使至邢州赠李八使君','竇牟','quantangshi','','卷15','独占龙冈部，深持虎节居。
尽心敷吏术，含笑掩兵书。
礼饰华缨重，才牵雅制余。
茂阴延驿路，温液逗官渠。
南亩行春罢，西楼待客初。
瓮头开绿蚁，砧下落红鱼。
牧伯风流足，輶轩若涩虚。
今宵铃阁内，醉舞复何如。','',''),('quantangshi-14272','秋日洛阳官舍寄上水部家兄','竇牟','quantangshi','','卷15','洛阳归老日，此县忽为君。
白发兄仍见，丹诚帝岂闻。
九衢横逝水，二室散浮云。
屈指豪家尽，伤心要地分。
禁中周几鼎，源上汉诸坟。
貔虎今无半，狐狸宿有羣。
威声慙北部，仁化乐南薰。
野檗饥来食，天香静处焚。
壮年唯喜酒，幼学便诃文。
及尔空衰暮，离忧讵可闻。','',''),('quantangshi-14273','李舍人少尹惠家醖一小榼立书绝句','竇牟','quantangshi','','卷15','禁琐天浆嫩，虞行夜月寒。
一瓢那可醉，应遣试尝看。','',''),('quantangshi-14274','酬舍弟庠罢举从州辟书','竇牟','quantangshi','','卷15','之荆且愿依刘表，折桂终慙见郄诜。
舍弟未应丝作鬓，园公不用印随身。','',''),('quantangshi-14275','奉酬杨侍郎十兄见赠之作','竇牟','quantangshi','','卷15','翠羽雕虫日日新，翰林工部欲何神。
自悲由瑟无弹处，今作关西门下人。','',''),('quantangshi-14276','杏园渡','竇牟','quantangshi','','卷15','卫郊多垒少人家，南渡天寒日又斜。
君子素风悲已矣，杏园无复一枝花。','',''),('quantangshi-14277','奉诚园闻笛','竇牟','quantangshi','','卷15','曾绝朱缨吐锦茵，欲披荒草访遗尘。
秋风忽洒西园泪，满目山阳笛里人。','',''),('quantangshi-14278','雪中遇直','竇羣','quantangshi','','卷15','寒光凝雪彩，限直居粉闱。
怳疑白云上，乍觉金印非。
树色霭虚空，琴声谐素徽。
明晨阻通籍，独卧挂朝衣。','',''),('quantangshi-14279','东山月下怀友人','竇羣','quantangshi','','卷15','东山多乔木，月午始苍苍。
虽殊碧海状，爱此青苔光。
高下灭华烛，参差启洞房。
佳人梦余思，宝瑟愁应商。
皎洁殊未已，沈吟限一方。
宦情哂鸡口，世路倦羊肠。
彼美金石分，眷言兰桂芳。
清晖讵同夕，耿耿但相望。','',''),('quantangshi-14280','时兴','竇羣','quantangshi','','卷15','夙心旷何许，日暮依林薄。
流水不待人，孤云时映鹤。
蒙蒙千万花，曷为神仙药。
不遇烂柯叟，报非旧城郭。','',''),('quantangshi-14281','题剑','竇羣','quantangshi','','卷15','丈夫得宝剑，束发曾书绅。
嗟吁一朝遇，愿言千载邻。
心许留家树，辞直断佞臣。
焉能为绕指，拂拭试时人。','',''),('quantangshi-14282','黔中书事','竇羣','quantangshi','','卷15','万事非京国，千山拥丽谯。
佩刀看日晒，赐马傍江调。
言语多重译，壶觞每独谣。
沿流如着翅，不敢问归桡。','',''),('quantangshi-14283','冬日晓思寄杨二十七炼师','竇羣','quantangshi','','卷15','雨霜地如雪，松桂青参差。
鹤警晨光上，步出南轩时。
所遇各有适，我怀亦自怡。
愿言缄素封，昨夜梦琼枝。','',''),('quantangshi-14284','贞元末东院尝接事今西川武相公于兹三周谬领中宪徘徊厅宇多获文篇夏日即事因寄四韵','竇羣','quantangshi','','卷15','重轩深似谷，列柏镇含烟。
境绝苍蝇到，风生白雪前。
弹冠惊迹近，专席感恩偏。
霄汉朝来下，油幢路几千。','',''),('quantangshi-14285','北地','竇羣','quantangshi','','卷15','何事到容州，临池照白头。
兴随年已往，愁与水长流。
僶俯思逋客，辛勤悔饭牛。
诗人亦何意，树草欲忘忧。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-14286','雨后月下寄怀羊二十七资州','竇羣','quantangshi','','卷15','夕霁凉飙至，翛然心赏谐。
清光松上月，虚白郡中斋。
置酒平生在，开衿愿见乖。
殷勤寄双鲤，梦想入君怀。','',''),('quantangshi-14287','奉酬西川武相公晨兴赠友见示之作','竇羣','quantangshi','','卷15','碧树分晓色，宿雨弄清光。
犹闻子规啼，独念一声长。
眷眷轸芳思，依依寄远方。
情同如兰臭，惠比返魂香。
新什惊变雅，古瑟代沈湘。
殷勤见知己，掩抑绕中肠。
隙驷不我待，路人易相忘。
孤老空许国，幽报期苍苍。','',''),('quantangshi-14288','晨游昌师院','竇羣','quantangshi','','卷15','深庭芳草浓，晓井山泉溢。
林馥乱沈烟，石润侵经室。
幽岩鸟飞静，晴岭云归密。
壁藓凝苍华，竹阴满晴日。
生期半宵梦，忧绪仍非一。
若无高世心，安能此终毕。','',''),('quantangshi-14289','同王晦伯朱遐景宿慧山寺','竇羣','quantangshi','','卷15','共访青山寺，曾隐南朝人。
问古松桂老，开襟言笑新。
步移月亦出，水映石磷磷。
予洗肠中酒，君濯缨上尘。
皓彩入幽抱，清气逼苍旻。
信此澹忘归，淹留冰玉邻。','',''),('quantangshi-14290','草堂夜坐','竇羣','quantangshi','','卷15','匣中三尺剑，天上少微星。
勿谓相去远，壮心曾不停。','',''),('quantangshi-14291','经潼关赠宇文十','竇羣','quantangshi','','卷15','古有弓旌礼，今徴草泽臣。
方同白衣见，不是弃繻人。','',''),('quantangshi-14292','观画鹤','竇羣','quantangshi','','卷15','华亭不相识，卫国复谁知。
怅望冲天羽，甘心任画师。','',''),('quantangshi-14293','晚自台中归永宁里南望山色怅然有怀呈上右司十一兄','竇羣','quantangshi','','卷15','白发侵侵生有涯，青襟曾爱紫河车。
自怜悟主难归去，马上看山恐到家。','',''),('quantangshi-14294','中牟县经鲁公庙','竇羣','quantangshi','','卷15','青史编名在箧中，故林遗庙揖仁风。
还将文字如颜色，暂下蒲车为鲁公。','',''),('quantangshi-14295','初入谏司喜家室至','竇羣','quantangshi','','卷15','一旦悲欢见孟光，十年辛苦伴沧浪。
不知笔砚缘封事，犹问佣书日几行。','',''),('quantangshi-14296','春雨','竇羣','quantangshi','','卷15','昨日偷闲看花了，今朝多雨奈人何。
人间尽似逢花雨，莫爱芳菲湿绮罗。','',''),('quantangshi-14297','送内弟袁德师','竇羣','quantangshi','','卷15','南渡登州即水仙，西垣有客思悠然。
因君相问为官意，不卖毗陵负郭田。','',''),('quantangshi-14298','赠刘大兄院长','竇羣','quantangshi','','卷15','万年枝下昔同趋，三事行中半已无。
路自长沙忽相见，共惊双鬓别来殊。','',''),('quantangshi-14299','假日寻花','竇羣','quantangshi','','卷15','武陵缘源不可到，河阳带县讵堪夸。
枝枝如雪南关外，一日休闲尽属花。','',''),('quantangshi-14300','自京将赴黔南','竇羣','quantangshi','','卷15','风雨荆州二月天，问人初雇峡中船。
西南一望云和水，犹道黔南有四千。','',''),('quantangshi-14301','留守府酬皇甫曙侍御弹琴之什','竇庠','quantangshi','','卷15','青琐昼无尘，碧梧阴似水。
高张朱弦琴，静举白玉指。
洞箫又奏繁，寒磬一声起。
鹤警风露中，泉飞雪云里。
泠泠分雅郑，析析谐宫征。
座客无俗心，巢禽亦倾耳。
卫国知有人，齐竽偶相齿。
有时趋绛纱，尽日随朱履。
那令杂繁手，出假求焦尾。
几载遗正音，今朝自君始。','',''),('quantangshi-14302','金山行','竇庠','quantangshi','','卷15','西江中𤃩波四截，涌出一峰青堞㙞。
外如削成中缺裂，阳气发生阴气结。
是时炎天五六月，上有火云下冰雪。
夜色晨光相荡沃，积翠流霞满坑谷。
龙泓彻底沙布金，鸟道插云梯甃玉。
架险凌虚随指顾，榱桷玲珑皆固护。
斡流倒景不可窥，万仞千崖生跬步。
日华重重上金牓，丹楹碧砌真珠网。
此时天海风浪清，吴楚万家皆在掌。
琼楼菌阁纷明媚，曲槛回轩深且邃。
海鸟夜上珊瑚枝，江花晓落瑠璃地。
有时倒影沈江底，万状分明光似洗。
不知水上有楼台，却就波中看闭启。
舟人忘却江水深，水神误到人间世。
歘然风生波出没，瀖濩晶莹无定物。
居人相顾非人间，如到日宫经月窟。
信知灵景长有灵，住者不得无仙骨。
三神山上蓬莱宫，徒有丹青人未逢。
何如此处灵山宅，清凉不与嚣尘隔。
曾到金山处处行，梦魂长羡金山客。','',''),('quantangshi-14303','于阗钟歌送灵彻上人归越','竇庠','quantangshi','','卷15','海中有国倾神功，烹金化成九乳钟。
精气激射声冲瀜，护持海底诸鱼龙。
声有感，神无方，连天云水无津梁。
不知飞在灵嘉寺，一国之人皆若狂。
东南之美天下传，环文万象无雕镌。
有灵飞动不敢悬，锁在危楼五百年。
有时清秋日正中，繁霜满地天无风。
一声洞彻八音尽，万籁悄然星汉空。
徒言凡质千钧重，一夫之力能振动。
大鸣小鸣须在君，不撃不考终不闻。
高僧访古稽山曲，终日当之言不足。
手提文锋百炼成，恐刜此钟无一声。','',''),('quantangshi-14304','太原送穆质南游','竇庠','quantangshi','','卷15','今朝天景清，秋入晋阳城。
露叶离披处，风蝉三数声。
那言苦行役，值此远徂征。
莫话心中事，相看气不平。','',''),('quantangshi-14305','四皓驿听琴送王师简归湖南使幕','竇庠','quantangshi','','卷15','朱弦韵正调，清夜似闻韶。
山馆月犹在，松枝雪未消。
城笳三奏晓，别鹤一声遥。
明日思君处，春泉翻寂寥。','',''),('quantangshi-14306','夜行古战场','竇庠','quantangshi','','卷15','山断塞初平，人言古战庭。
泉冰声更咽，阴火焰偏青。
月落云沙黑，风回草木腥。
不知秦与汉，徒欲吊英灵。','',''),('quantangshi-14307','奉和王侍郎春日喜李侍郎崔给谏张舍人韦谏议见访因命觞观乐之什','竇庠','quantangshi','','卷15','华馆迟嘉宾，逢迎淑景新。
锦筵开绛帐，玉佩下朱轮。
曲里三仙会，风前百啭春。
欲知忘味处，共仰在齐人。','',''),('quantangshi-14308','酬谢韦卿二十五兄俯赠輙敢书情','竇庠','quantangshi','','卷15','大贤持赠一明璫，蓬荜初惊满室光。
埋没剑中生紫气，尘埃瑟上动清商。
荆山璞在终应识，楚国人知不是狂。
莫恨伏辕身未老，会将筋力是王良。','',''),('quantangshi-14309','奉酬侍御家兄东洛闲居夜晴观雪之什','竇庠','quantangshi','','卷15','洛阳宫观与天齐，雪净云消月未西。
清浅乍分银汉近，辉光渐觉玉绳低。
绿醽乍熟堪聊酌，黄竹篇成好命题。
应念武关山断处，空愁簿领候晨鸡。','',''),('quantangshi-14310','勅目至家兄蒙淮南仆射杜公奏授祕校兼节度参谋同书寄上','竇庠','quantangshi','','卷15','朝市三千里，园庐二十春。
步兵终日饮，原宪四时贫。
桂树留人久，蓬山入梦新。
鹤书承处重，鹊语喜时频。
草奏才偏委，嘉谋事最亲。
榻因徐孺解，醴为穆生陈。
卫国今多士，荆州好寄身。
烟霄定从此，非假问陶钧。','',''),('quantangshi-14311','酬韩愈侍郎登岳阳楼见赠','竇庠','quantangshi','','卷15','巨浸连空阔，危楼在杳冥。
稍分巴子国，欲近老人星。
昏旦呈新候，川原按旧经。
地图封七泽，天限锁重扃。
万象皆归掌，三光岂遁形。
月车才碾浪，日御已翻溟。
落照金成柱，余霞翠拥屏。
夜光疑汉曲，寒韵辨湘灵。
山晚云常碧，湖春草徧青。
轩黄曾举乐，范蠡几扬舲。
有客初留鷁，贪程尚数蓂。
自当徐孺榻，不是谢公亭。
雅论冰生水，雄材刃发硎。
座中琼玉润，名下茝兰馨。
假手诚知拙，斋心匪蹔宁。
每慙公府粟，却忆故山苓。
苦调当三叹，知音愿一听。
自悲由也瑟，敢坠孔悝铭。
野杏初成雪，松醪正满瓶。
莫辞今日醉，长恨古人醒。','',''),('quantangshi-14312','东都嘉量亭献留守韩仆射','竇庠','quantangshi','','卷15','卜筑三川上，仪刑万井中。
度材垂后俭，选胜揜前功。
云构中央起，烟波四面通。
乍疑游汗漫，稍似入崆垌。
廛閈高低尽，山河表里穷。
峰恋从地碧，宫观倚天红。
灵槛如朝蜃，飞桥状晚虹。
曙霞晴错落，夕霭湿葱茏。
庾亮楼何厄，陈蕃榻更崇。
有时闲讲德，永日静观风。
玉斝飞无算，金铙奏未终。
重筵开玳瑁，上客集鵷鸿。
接武空慙蹇，修文敢并雄。
岂须登岘首，然后奉羊公。','',''),('quantangshi-14313','段都尉别业','竇庠','quantangshi','','卷15','曾识将军段匹磾，几场花下醉如泥。
春来欲问林园主，桃李无言鸟自啼。','',''),('quantangshi-14314','灵台镇赠丘岑中丞','竇庠','quantangshi','','卷15','晓日天山雪半晴，红旗遥识汉家营。
近来胡骑休南牧，羊马城边春草生。','',''),('quantangshi-14315','赠道芬上人','竇庠','quantangshi','','卷15','云湿烟封不可闚，画时唯有鬼神知。
几回逢着天台客，认得岩西最老枝。','',''),('quantangshi-14316','金山寺','竇庠','quantangshi','','卷15','一点青螺白浪中，全依水府与天通。
晴江万里云飞尽，鳌背参差日气红。','',''),('quantangshi-14317','冬夜寓怀寄王翰林','竇庠','quantangshi','','卷15','满地霜芜叶下枝，几回吟断四愁诗。
汉家若欲论封禅，须及相如未病时。','',''),('quantangshi-14318','醉中赠符载','竇庠','quantangshi','','卷15','白社会中尝共醉，青云路上未相逢。
时人莫小池中水，浅处无妨有卧龙。','',''),('quantangshi-14319','龙门看花','竇庠','quantangshi','','卷15','无叶无枝不见空，连天扑地迳才通。
山莺惊起酒醒处，火焰烧人雪喷风。','',''),('quantangshi-14320','陪留守韩仆射巡内至上阳宫感兴二首 一','竇庠','quantangshi','','卷15','翠辇西归七十春，玉堂珠缀俨埃尘。
武皇弓剑埋何处，泣问上阳宫里人。','',''),('quantangshi-14321','陪留守韩仆射巡内至上阳宫感兴二首 二','竇庠','quantangshi','','卷15','愁云漠漠草离离，太乙句陈处处疑。
薄暮毁垣春雨里，残花犹发万年枝。','',''),('quantangshi-14322','老将行','竇鞏','quantangshi','','卷15','烽烟犹未尽，年鬓暗相催。
轻敌心空在，弯弓手不开。
马依秋草病，柳傍故营摧。
唯有酬恩客，时听说剑来。','',''),('quantangshi-14323','赠萧都官','竇鞏','quantangshi','','卷15','萧郎自小贤，爱客不言钱。
有酒轻寒夜，无愁倚少年。
闲寻织锦字，醉上看花船。
好是关身事，从人道性偏。','',''),('quantangshi-14324','忝职武昌初至夏口书事献府主相公','竇鞏','quantangshi','','卷15','白发放橐鞬，梁王爱旧全。
竹篱江畔宅，梅雨病中天。
时奉登楼宴，闲修上水船。
邑人兴谤易，莫遣鹤支钱。','',''),('quantangshi-14325','早秋江行','竇鞏','quantangshi','','卷15','回望湓城远，西风吹荻花。
暮潮江势阔，秋雨雁行斜。
多醉浑无梦，频愁欲到家。
渐惊云树转，数点是晨鵶。','',''),('quantangshi-14326','题任处士幽居','竇鞏','quantangshi','','卷15','红叶江邨夕，孤烟草舍贫。
水清鱼识钓，林静犬随人。
采掇山无主，扶持药有神。
客来唯劝酒，蝴蝶是前身。','',''),('quantangshi-14327','汉阴驿与宇文十相遇旋归西川因以赠别','竇鞏','quantangshi','','卷15','吴蜀何年别，相逢汉水头。
望乡心共醉，握手泪先流。
宿雾千山晓，春霖一夜愁。
离情方浩荡，莫说去刀州。','',''),('quantangshi-14328','早春松江野望','竇鞏','quantangshi','','卷15','江邨风雪霁，晓望忽惊春。
畊地人来早，营巢鹊语频。
带花移树小，插槿作篱新。
何事胜无事，穷通任此身。','',''),('quantangshi-14329','少妇词','竇鞏','quantangshi','','卷15','坐惜年光变，辽阳信未通。
燕迷新画屋，春识旧花丛。
梦绕天山外，愁翻锦字中。
昨来谁是伴，鹦鹉在帘栊。','',''),('quantangshi-14330','岁晚喜远兄弟至书情','竇鞏','quantangshi','','卷15','几年沧海别，相见竟多违。
鬓发缘愁白，音书为嬾稀。
新诗徒有赠，故国未同归。
人事那堪问，无言是与非。','',''),('quantangshi-14331','登玉鈎亭奉献淮南李相公','竇鞏','quantangshi','','卷15','西南城上高高处，望月分明似玉鈎。
朱槛人云看鸟灭，绿杨如荠遶江流。
定知有客嫌陈榻，从此无人上庾楼。
今日卷帘天气好，不劳骑马看扬州。','',''),('quantangshi-14332','南阳道中作','竇鞏','quantangshi','','卷15','东风雨洗顺阳川，蜀锦花开绿草田。
彩雉鬬时频驻马，酒旗翻处亦留钱。
新晴日照山头雪，薄暮人争渡口船。
早晚到家春欲尽，今年寒食月初圆。','',''),('quantangshi-14333','哭吕衡州八郎中','竇鞏','quantangshi','','卷15','今朝血泪问苍苍，不分先悲旅馆丧。
人送剑来归陇上，雁飞书去呌衡阳。
还家路远儿童小，埋玉泉深昼夜长。
望尽素车秋草外，欲将身赎返魂香。','',''),('quantangshi-14334','江陵遇元九李六二侍御纪事书情呈十二韵','竇鞏','quantangshi','','卷15','自见人相爱，如君爱我稀。
好闲容问道，攻短每言非。
梦想何曾间，追欢未省违。
看花怜后到，避酒许先归。
柳寺春堤远，津桥曙月微。
渔翁随去处，禅客共因依。
蓬阁初疑义，霜台晚畏威。
学深通古字，心直触危机。
肯滞荆州掾，犹香柏署衣。
山连巫峡秀，田傍渚宫肥。
美玉方齐价，迁鸎尚怯飞。
伫看霄汉上，连步侍彤闱。','',''),('quantangshi-14335','游仙词','竇鞏','quantangshi','','卷15','海上神山绿，溪边杏树红。
不知何处去，月照玉楼空。','',''),('quantangshi-14336','赠阿史那都尉','竇鞏','quantangshi','','卷15','较猎燕山经几春，雕弓白羽不离身。
年来马上浑无力，望见飞鸿指似人。','',''),('quantangshi-14337','陕府宾堂览房杜二公仁寿年中题纪手迹','竇鞏','quantangshi','','卷15','仁寿元和二百年，蒙笼水墨淡如烟。
当时憔悴题名日，汉祖龙潜未上天。','',''),('quantangshi-14338','早春送宇文十归吴','竇鞏','quantangshi','','卷15','春迟不省似今年，二月无花雪满天。
村店闭门何处宿，夜深遥唤渡江船。','',''),('quantangshi-14339','经窦车骑故城','竇鞏','quantangshi','','卷15','荒陂古堞欲千年，名振图书剑在泉。
今日诸孙拜坟树，愧无文字续燕然。','',''),('quantangshi-14340','赠王氏小儿','竇鞏','quantangshi','','卷15','竹林会里偏怜小，淮水清时最觉贤。
莫倚儿童轻岁月，丈人曾共尔同年。','',''),('quantangshi-14341','唐州东途作','竇鞏','quantangshi','','卷15','绿林兵起结愁云，白羽飞书未解纷。
天子欲开三面网，莫将弓箭射官军。','',''),('quantangshi-14342','新罗进白鹰','竇鞏','quantangshi','','卷15','御马新骑禁苑秋，白鹰来自东海头。
汉皇无事须游猎，雪乱争飞锦臂韝。','',''),('quantangshi-14343','秋夕','竇鞏','quantangshi','','卷15','护霜云映月朦胧，乌鹊争飞井上桐。
半夜酒醒人不觉，满池荷叶动秋风。','',''),('quantangshi-14344','襄阳寒食寄宇文籍','竇鞏','quantangshi','','卷15','烟水初销见万家，东风吹柳万条斜。
大堤欲上谁相伴，马踏春泥半是花。','',''),('quantangshi-14345','奉使蓟门','竇鞏','quantangshi','','卷15','自从身属富人侯，蝉噪槐花已四秋。
今日一茎新白发，懒骑官马到幽州。','',''),('quantangshi-14346','送刘禹锡','竇鞏','quantangshi','','卷15','十年憔悴武陵溪，鹤病深林玉在泥。
今日太行平似砥，九霄初倚入云梯。','',''),('quantangshi-14347','送元稹西归','竇鞏','quantangshi','','卷15','南州风土滞龙媒，黄纸初飞勅字来。
二月曲江连旧宅，阿婆情熟牡丹开。','',''),('quantangshi-14348','过骊山','竇鞏','quantangshi','','卷15','翠辇红旌去不回，苍苍宫树锁青苔。
有人说得当时事，曾见长生玉殿开。','',''),('quantangshi-14349','洛中即事','竇鞏','quantangshi','','卷15','高梧叶尽鸟巢空，洛水潺湲夕照中。
寂寂天桥车马绝，寒鸦飞入上阳宫。','',''),('quantangshi-14350','寻道者所隐不遇','竇鞏','quantangshi','','卷15','篱外涓涓涧水流，槿花半点夕阳收。
欲题名字知相访，又恐芭蕉不奈秋。','',''),('quantangshi-14351','寄南游兄弟','竇鞏','quantangshi','','卷15','书来未报几时还，知在三湘五岭间。
独立衡门秋水阔，寒鸦飞去日衔山。','',''),('quantangshi-14352','宫人斜','竇鞏','quantangshi','','卷15','离宫路远北原斜，生死恩深不到家。
云雨今归何处去，黄鹂飞上野棠花。','',''),('quantangshi-14353','代邻叟','竇鞏','quantangshi','','卷15','年来七十罢耕桑，就暖支羸强下牀。
满眼儿孙身外事，闲梳白发对残阳。','',''),('quantangshi-14354','新营别墅寄家兄','竇鞏','quantangshi','','卷15','懒性如今成野人，行藏由兴不由身。
莫惊此度归来晚，买得西山正值春。','',''),('quantangshi-14355','南游感兴','竇鞏','quantangshi','','卷15','伤心欲问前朝事，惟见江流去不回。
日暮东风春草绿，鹧鸪飞上越王台。','',''),('quantangshi-14356','题剑津','竇鞏','quantangshi','','卷15','风前推折千年剑，岩下澄空万古潭。
双剑变成龙化去，两溪相并水归南。','',''),('quantangshi-14357','放鱼','竇鞏','quantangshi','','卷15','金钱赎得免刀痕，闻道禽鱼亦感恩。
好去长江千万里，不须辛苦上龙门。','',''),('quantangshi-14358','永宁小园寄接近校书','竇鞏','quantangshi','','卷15','故里心期奈别何，手栽芳树忆庭柯。
东臯黍熟君应醉，梨叶初红白露多。','',''),('quantangshi-14359','从军别家','竇鞏','quantangshi','','卷15','自笑儒生着战袍，书斋壁上挂弓刀。
如今便是征人妇，好织回文寄窦滔。','',''),('quantangshi-14360','悼妓东东','竇鞏','quantangshi','','卷15','芳菲美艳不禁风，未到春残已坠红。
惟有侧轮车上铎，耳边长似呌东东。','',''),('quantangshi-14361','木兰歌','韋元甫','quantangshi','','卷15','木兰抱杼嗟，借问复为谁。
欲闻所戚戚，感激彊其颜。
老父隶兵籍，气力日衰耗。
岂足万里行，有子复尚少。
胡沙没马足，朔风裂人肤。
老父旧羸病，何以彊自扶。
木兰代父去，秣马备戎行。
易却纨绮裳，洗却铅粉妆。
驰马赴军幕，慷慨携干将。
朝屯雪山下，暮宿青海傍。
夜袭燕支虏，更携于阗羌。
将军得胜归，士卒还故乡。
父母见木兰，喜极成悲伤。
木兰能承父母颜，却卸巾韝理丝簧。
昔为烈士雄，今为娇子容。
亲戚持酒贺父母，始知生女与男同。
门前旧军都，十年共崎岖。
本结弟兄交，死战誓不渝。
今者见木兰，言声虽是颜貌殊。
惊愕不敢前，叹息徒嘻吁。
世有臣子心，能如木兰节。
忠孝两不渝，千古之名焉可灭。','',''),('quantangshi-14362','登越王楼见乔公诗偶题','王鋌','quantangshi','','卷15','云架重楼出郡城，虹梁雅韵仲宣情。
越王空置千年迹，丞相兼扬万古名。
过鸟时时冲客会，闲风往往弄江声。
谬将蹇步寻高躅，鱼目骊珠岂继明。','',''),('quantangshi-14363','清如玉壶冰','潘炎','quantangshi','','卷15','琰玉性惟坚，成壶体更圆。
虚心含景象，应物受寒泉。
温润资天质，清贞禀自然。
日融光乍散，雪照色逾鲜。
至鉴功宁宰，无私照岂偏。
明将冰镜对，白与粉花连。
拂拭终为美，提携伫见传。
勿令毫髪累，遗恨鲍公篇。','',''),('quantangshi-14364','长至日上公献寿','張叔良','quantangshi','','卷15','凤阙晴钟动，鸡人晓漏长。
九重初启钥，三事正称觞。
日至龙颜近，天旋圣历昌。
休光连雪净，瑞气杂炉香。
化被君臣洽，恩霑士庶康。
不因稽旧典，谁得纪朝章。','',''),('quantangshi-14365','泾渭扬清浊','呂牧','quantangshi','','卷15','泾渭横秦野，逶迤近帝城。
二渠通作润，万户映皆清。
明晦看殊色，潺湲听一声。
岸虚深草掩，波五晓烟轻。
御猎思投钓，渔歌好濯缨。
合流知禹力，同共到沧瀛。','',''),('quantangshi-14366','别张贾','韋夏卿','quantangshi','','卷15','束简下高阁，买符驱短辕。
故人惜分袂，结念醉芳罇。
切切别思缠，萧萧征骑烦。
临归无限意，相视却忘言。','',''),('quantangshi-14367','送顾况归茅山','韋夏卿','quantangshi','','卷15','圣代为迁客，虚皇作近臣。
法尊称大洞，学浅忝初真。
鸾凤文章丽，烟霞翰墨新。
羡君寻句曲，白鹄是三神。','',''),('quantangshi-14368','和丘员外题湛长史旧居','韋夏卿','quantangshi','','卷15','道胜物能齐，累轻身易退。
苟安一丘上，何必三山外。
云霞长若绮，松石常如黛。
徒有昔王过，竟遗青史载。
诗因野寺咏，酒向山椒酹。
异时逢尔知，兹辰驻余斾。','',''),('quantangshi-14369','同韦夏卿送顾况归茅山','綦毋誠','quantangshi','','卷15','谪宦闻尝赋，游仙便作诗。
白银双阙恋，青竹一龙骑。
先入茅君洞，旋过葛稚陂。
无然列御寇，五日有还期。','',''),('quantangshi-14370','感秋','姚倫','quantangshi','','卷15','试向疎林望，方知节候殊。
乱声千叶下，寒影一巢孤。
不蔽秋天雁，惊飞夜月乌。
霜风与春日，几度遣荣枯。','',''),('quantangshi-14371','过章秀才洛阳客舍','姚倫','quantangshi','','卷15','达人心自适，旅舍当闲居。
不出来时径，重看读了书。
晚山岚色近，斜日树阴疎。
尽是忘言客，听君诵子虚。','',''),('quantangshi-14372','赋得生刍一束','于結','quantangshi','','卷15','比玉人应重，为刍物自轻。
向风倾弱叶，裛露示纤茎。
蒨练宜春景，芊绵对雨情。
每慙苹藻用，多谢𦶜兰荣。
孺子才虽远，公孙策未行。
谘询如不弃，终冀及微生。','',''),('quantangshi-14373','赋得生刍一束','鄭孺華','quantangshi','','卷15','孙弘期射策，长倩赠生刍。
至洁心将比，忘忧道不孤。
芝兰方入室，萧艾莫同途。
馥馥香犹在，青青色更殊。
芳宁九春歇，薰岂十年无。
葑菲如堪采，山苗自可逾。','',''),('quantangshi-14374','空灵岸','張叔卿','quantangshi','','卷15','寒尽鸿先去，江回客未归。
早知名是幻，不敢绣为衣。
雾积川原暗，山多郡县稀。
今朝下湘岸，更逐鹧鸪飞。','',''),('quantangshi-14375','流桂州','張叔卿','quantangshi','','卷15','莫问苍梧远，而今世路难。
胡尘不到处，即是小长安。','',''),('quantangshi-14376','酬窦大闲居见寄','房孺復','quantangshi','','卷15','来自三湘到五溪，青枫无树不猨啼。
名慙竹使宦情少，路隔桃源归思迷。
鵩鸟赋成知性命，鲤鱼书至恨暌携。
烦君强着潘年比，骑省风流讵可齐。','',''),('quantangshi-14377','送妓人出家','楊郇伯','quantangshi','','卷15','尽出花钿与四隣，云鬟剪落厌残春。
暂惊风烛难留世，便是莲花不染身。
贝叶欲翻迷锦字，梵声初学悞梁尘。
从今艳色归空后，湘浦应无解佩人。','',''),('quantangshi-14378','宿北乐馆','陳潤','quantangshi','','卷15','欲眠不眠夜深浅，越鸟一声空山远。
庭木萧萧落叶时，溪声雨声听不辨。
溪流潺潺雨习习，灯影山光满窗入。
栋里不知浑是云，晓来但觉衣裳湿。','',''),('quantangshi-14379','东都所居寒食下作','陳潤','quantangshi','','卷15','江南寒食早，二月杜鹃鸣。
日暖山初绿，春寒雨欲晴。
浴蚕当社日，改火待清明。
更喜瓜田好，令人忆邵平。','',''),('quantangshi-14380','登西灵塔','陳潤','quantangshi','','卷15','塔庙出招提，登临碧海西。
不知人意远，渐觉鸟飞低。
稍与云霞近，如将日月齐。
迁乔未得意，徒欲蹑云梯。','',''),('quantangshi-14381','送骆征君','陳潤','quantangshi','','卷15','野人膺辟命，溪上掩柴扉。
黄卷犹将去，青山岂更归。
马留苔藓迹，人脱薜萝衣。
他日相思处，天边望少微。','',''),('quantangshi-14382','赋得浦外虹送人','陳潤','quantangshi','','卷15','日影化为虹，弯弯出浦东。
一条微雨后，五色片云中。
轮势随天度，桥形跨海通。
还将饮水处，持送使车雄。','',''),('quantangshi-14383','赋得秋河曙耿耿','陳潤','quantangshi','','卷15','晚望秋高夜，微明欲曙河。
桥成鹊已去，机罢女应过。
月上殊开练，云行类动波。
寻源不可到，耿耿复如何。','',''),('quantangshi-14384','赋得池塘生春草','陳潤','quantangshi','','卷15','谢公遗咏处，池水夹通津。
古往人何在，年来草自春。
色宜波际绿，香爱雨中新。
今日青青意，空悲行路人。','',''),('quantangshi-14385','阙题','陳潤','quantangshi','','卷15','丈夫不感恩，感恩宁有泪。
心头感恩血，一滴染天地。','',''),('quantangshi-14386','哭长孙侍郎','杜誦','quantangshi','','卷15','道为诗书重，名因赋颂雄。
礼闱曾擢桂，宪府既乘骢。
流水生涯尽，浮云世事空。
唯余旧台柏，萧瑟九原中。','',''),('quantangshi-14387','明皇帝挽歌','鄭丹','quantangshi','','卷15','律历千年会，车书万里同。
固期常戴日，岂意厌观风。
地惨新[疆]理，城摧旧战功。
山河万古壮，今夕尽归空。','',''),('quantangshi-14388','肃宗挽歌','鄭丹','quantangshi','','卷15','国以重明受，天从谅暗移。
诸侯方北面，白日忽西驰。
龙影当泉落，鸿名向庙垂。
永言青史上，还见戴无为。','',''),('quantangshi-14389','落花','鄭昈','quantangshi','','卷15','早春见花枝，朝朝恨发迟。
直看花落尽，却意未开时。
以此方人世，弥令感盛衰。
始知山简遶，频向习家池。','',''),('quantangshi-14390','宿新安江深渡馆寄郑州王使君','朱長文','quantangshi','','卷15','霜飞十月中，摇落众山空。
孤馆闭寒木，大江生夜风。
赋诗忙有意，沈约在关东。','',''),('quantangshi-14391','春眺扬州西上岗寄徐员外','朱長文','quantangshi','','卷15','芜城西眺极苍流，漠漠春烟间曙楼。
瓜步早潮吞建业，蒜山晴雪照扬州。
隋家故事不能问，鹤在仙池期我游。','',''),('quantangshi-14392','送李司直归浙东幕兼寄鲍将军','朱長文','quantangshi','','卷15','翩翩书记早曾闻，二十年来愿见君。
今日相逢悲白发，同时几许在青云。
人从北固山边去，水到西陵渡口分。
会作王门曳裾客，为余前谢鲍将军。','','');